INSERT INTO "public"."alembic_version" ("version_num") VALUES ('b62f32d45004');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1, 'دن لیون', '<p>دن لیون روزنامه نگار، رمان نویس و فیلمنامه نویس است. او سال‌ها ویراستار فناوری <em>Newsweek </em> بود و در حال حاضر کارمند مجموعه HBO <em>Silicon Valley</em> است. وبلاگ او، <em>خاطرات مخفی استیو جابز</em>، یک موفقیت فوق العاده بود.</p>', '2023-01-26 18:46:07.793167', '2023-01-26 18:46:07.793167', NULL, 'Dan Lyons');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (2, 'پل ویگنا و مایکل جی کیسی', '<p>پل ویگنا و مایکل جی کیسی هر دو روزنامه نگار در <em>وال استریت ژورنال</em> هستند. ویگنا همچنین گوینده <em>MoneyBeat</em> است و کیسی نویسنده <em>Che’s Afterlife</em> و <em>The Unfair Trade</em> است. کیسی همچنین مفسر عادی بی بی سی است.</p>', '2023-01-26 18:46:19.251724', '2023-01-26 18:46:19.251724', NULL, 'Paul Vigna and Michael J. Casey');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (3, 'جان واریلو', '<p>جان واریلو چهار شرکت را به تنهایی راه اندازی کرده و فروخته است. او همچنین امتیاز فروشندگی را ابداع کرد، ابزاری که میزان جذابیت شرکت ها را برای خریداران بالقوه ارزیابی می کند. مجلات <em>Fortune</em> و <em>Inc.</em> <em>Built to Sell</em> را یکی از بهترین عناوین تجاری سال 2011 قرار دادند.</p>', '2023-01-26 18:46:30.83024', '2023-01-26 18:46:30.83024', NULL, 'John Warrillow');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (4, 'Donella H. Meadows', '<p>دونلا میدوز دانشمند، نویسنده و معلم محیط زیست بود که به طور گسترده ای پیش از زمان خود در نظر گرفته می شد. او در طول زندگی خود یکی از مهمترین تحلیلگران سیستم روی زمین و دریافت کننده جایزه مک آرتور "نابغه" بود. Meadows در سال 2001 درگذشت.</p>', '2023-01-26 18:46:41.79612', '2023-01-26 18:46:41.79612', NULL, 'Donella H. Meadows');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (5, 'بن هوروویتز', '<p>بن هوروویتز شریک موسس شرکت سرمایه گذاری خطرپذیر Andreessen Horowitz است. او پیش از این یکی از بنیانگذاران و مدیرعامل شرکت فناوری اطلاعات Opsware بود که در نهایت در سال 2007 به قیمت 1.6 میلیارد دلار به هیولت پاکارد فروخت. وبلاگ او بیش از 10 میلیون خواننده دارد.</p>', '2023-01-26 18:46:54.233667', '2023-01-26 18:46:54.233667', NULL, 'Ben Horowitz ');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (6, 'کریس بروگان و جولین اسمیت', '<p>کریس بروگان یک وبلاگ نویس، روزنامه نگار و مشاور بازاریابی مشهور آمریکایی است. جولین اسمیت مشاور، سخنران و مدیر عامل شرکت نوپا Breather است که اتاق‌هایی را برای کار و استراحت اجاره می‌دهد.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (7, 'مارک ویلیامز و دنی پنمن', '<p>مارک ویلیامز قبل از بازنشستگی اخیر خود استاد روانشناسی بالینی در دانشگاه آکسفورد بود. او که بنیانگذار آکادمی شناخت درمانی است، در سال 2007 کتاب <em>روش ذهن آگاهانه از طریق افسردگی</em> را نیز تالیف کرد. دنی پنمن دارای مدرک دکترای بیوشیمی است و برای تعدادی از روزنامه ها از جمله <em>Daily Mail</em> بریتانیا مطلب نوشته است.</p>', '2023-01-26 18:47:05.487481', '2023-01-26 18:47:05.487481', NULL, 'Mark Williams and Danny Penman');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (8, 'راجر لوونشتاین', '<p>راجر لوونشتاین یک روزنامه‌نگار مالی آمریکایی و همکار <em>وال استریت ژورنال</em> است. او علاوه بر مقالات و نقدهای متعدد کتاب، پنج کتاب پرفروش نیز نوشته است، از جمله <em>پایان وال استریت</em>و <em>وقتی آمریکا پیر شد</em>.</p>', '2023-01-26 18:47:17.564621', '2023-01-26 18:47:17.564621', NULL, 'Roger Lowenstein');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (9, 'رایان هالیدی', '<p>رایان هالیدی نویسنده، استراتژیست رسانه ای و صاحب کتابفروشی آمریکایی است. او همچنین میزبان پادکست Daily Stoic است. کتاب‌های دیگر او عبارتند از <em>رواقی روزانه، سکون کلید است</em> و <em>شجاعت فرا می‌خواند</em>.</p>', '2023-01-26 18:47:29.885633', '2023-01-26 18:47:29.885633', NULL, 'Ryan Holiday');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (10, 'دانیل پریستلی', '<p>دانیل پریستلی یک کارآفرین برنده جوایز است که از 21 سالگی در حال ساخت و خرید مشاغل در سراسر جهان است. او همچنین یک سخنران پرطرفدار است که مشاوره های تخصصی کسب و کار ارائه می دهد، و همچنین نویسنده پرفروش کتاب های متعدد، از جمله <em>انقلاب کارآفرین</em>، که با گلن مک کریدی نوشته است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (11, 'نیل فیوره', '<p>نیل فیور، روانشناس آمریکایی و نویسنده پرفروش تعدادی کتاب، از جمله <em></em> <em>جاده</em> <em>بازگشت</em> <em>به</em > <em>سلامت</em>، با تمرکز اولیه بر بهره وری و هیپنوتیزم. او به عنوان یک مربی و مربی، به هزاران مشتری کمک کرده و با بسیاری از شرکت های مشهور مشورت کرده است.</p>', '2023-01-26 18:47:48.001172', '2023-01-26 18:47:48.001172', NULL, 'Neil Fiore');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (12, 'شین پریش و ریانون بوبین', '<p>شین پریش قبل از تأسیس Farnam Street، سازمانی که به مردم کمک می‌کند در دنیایی همیشه در حال تغییر هوشمندانه‌تر فکر کنند، به‌عنوان کارشناس امنیت سایبری برای آژانس اطلاعاتی برتر کانادا کار می‌کرد. آثار او در <em>نیویورک تایمز</em>، <em>وال استریت ژورنال</em>، <em>هافینگتون پست</em> و <em>فوربس</em> به نمایش درآمده است. . او همچنین میزبان پروژه دانش است، پادکستی که بیش از 10 میلیون بار دانلود شده است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (13, 'فرانک پارتنو', '<p>فرانک پارتنوی کارشناس مالی یکی از همکاران منظم روزنامه هایی مانند <em>Financial Times</em> و <em>The</em> <em>New York Times</em> است. او نویسنده کتاب های غیرداستانی مانند <em>طمع عفونی</em>، <em>پادشاه مسابقه</em> و <em>F.I.A.S.C.O.</em> است. </p>', '2023-01-26 18:48:05.890949', '2023-01-26 18:48:05.890949', NULL, 'Frank Partnoy');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (14, 'مت ریدلی', '<p>مت ریدلی دانشمند، روزنامه نگار و تاجر بریتانیایی است. او شش کتاب نوشته است و در سال 2011 جایزه هایک را برای <em>خوشبین منطقی</em> دریافت کرده است. او در حال حاضر برای <em>وال استریت ژورنال</em>و <em>تایمز</em> می نویسد. </p>', '2023-01-26 18:48:12.65768', '2023-01-26 18:48:12.65768', NULL, 'Matt Ridley');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (15, 'تیم رینگو', '<p>حرفه تیم رینگو در مشاوره HR و تجارت نرم افزار تقریباً 30 سال است. او نایب رئیس SAP Success Factors برای اروپا، خاورمیانه و آفریقا بود و اکنون در هیئت مدیره و مدیر غیر اجرایی Optunli است، یک راه حل منابع انسانی که برنامه ریزی استراتژیک نیروی کار را ارائه می دهد. او سخنران کنفرانس و نویسنده <em>محاسبه موفقیت</em> است.</p>', '2023-01-26 18:48:18.183215', '2023-01-26 18:48:18.183215', NULL, 'Tim Ringo');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (16, 'دبورا گرونفلد', '<p>دبورا گرونفلد استاد دانشکده تحصیلات تکمیلی بازرگانی استنفورد است که در آن برنامه اجرایی برای رهبران زن را هدایت می کند. برای بیش از 25 سال، تحقیقات، نویسندگی و تدریس او بر روانشناسی قدرت متمرکز بوده است و او در مجلات و نشریات دانشگاهی از جمله <em>وال استریت ژورنال</em> و <em>واشنگتن پست< /em>. او همچنین یکی از نویسندگان <em>استرس در محل کار آمریکا</em> است.</p>', '2023-01-26 18:48:23.265668', '2023-01-26 18:48:23.265668', NULL, 'Deborah Gruenfeld');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (17, 'شانل میلر', '<p>شانل میلر هنرمند و نویسنده ای است که در سانفرانسیسکو زندگی می کند. او در دانشگاه کالیفرنیا در سانتا باربارا تحصیل کرد و در رشته ادبیات فارغ التحصیل شد. «بیانیه قربانی» که او برای توضیح تأثیر تجاوز جنسی براک ترنر بر زندگی او نوشت، توسط <em>Buzzfeed</em> منتشر شد و بیش از 18 میلیون بار خوانده شده است. <em>نام من را بدانید</em> اولین کتاب میلر است. </p>', '2023-01-26 18:48:35.834902', '2023-01-26 18:48:35.834902', NULL, 'Chanel Miller');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (18, 'برانت پینویدیک', '<p>برانت پینویدیک یک تهیه کننده تلویزیونی کهنه کار، مشاور شرکتی سطح C و کارگردان فیلم مستند برنده جایزه است. او از روش خود برای توسعه زمین برای اجرای موفقیت آمیز بیش از 300 پروژه تلویزیونی و سینمایی استفاده کرده است. آنها شامل برنامه های تلویزیونی پرطرفدار <em>نجات بار</em> و <em>Extreme Makeover: Weight Loss Edition</em> هستند که او تهیه کننده اجرایی هر دو آنها بود. او همچنین ستون نویس مجله <em>Forbes</em> و مجری پادکست محبوب <em>Why I''m Not</em> است. <em>قانون 3 دقیقه</em> اولین کتاب اوست. </p>', '2023-01-26 18:48:47.568763', '2023-01-26 18:48:47.568763', NULL, 'Brant Pinvidic');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (19, 'رابرت پوینتون', '<p>رابرت پوینتون همکار دانشکده بازرگانی سعید در دانشگاه آکسفورد است که در آنجا برنامه‌های آموزشی اجرایی را طراحی و تسهیل می‌کند. پوینتون همچنین نویسنده <em>بداهه سازی کنید </em>(2013)، کتابچه راهنمای تکنیک های بداهه نوازی برای رهبران کسب و کار، و به طور منظم میزبان استراحت های آخر هفته برای حرفه ای های پرمشغله است.</p>', '2023-01-26 18:48:59.97246', '2023-01-26 18:48:59.97246', NULL, 'Robert Poynton');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (20, 'کیت هرلی', '<p>کتی هرلی وبلاگ نویس پشت پرده والدین عملی و نویسنده مقالات در PBS Parents و <em>The Huffington Post</em> است. او در لس آنجلس زندگی می‌کند، جایی که زمان خود را بین روان‌شناس و مشاور کودک و نوجوان، کارشناس والدین و مادر دو فرزند تقسیم می‌کند.</p>', '2023-01-26 18:49:05.431518', '2023-01-26 18:49:05.431518', NULL, 'Katie Hurley');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (21, 'جسی لوکاوالیر', '<p>Jesse LeCavalier دانشیار معماری در دانشگاه تورنتو است. یک نویسنده و محقق برنده جوایز، کار او شامل فعالیت در موسسه دانش عمومی در دانشگاه نیویورک، آزمایشگاه شهرهای آینده سنگاپور-ETH و Eidgenössische Technische Hochschule Zürich است.</p>', '2023-01-26 18:49:18.104295', '2023-01-26 18:49:18.104295', NULL, 'Jesse LeCavalier');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (22, 'استیون کوارتز و آنت آسپ', '<p> استیون کوارتز علوم شناختی و فلسفه را در موسسه فناوری کالیفرنیا تدریس می کند، جایی که او همچنین محقق اصلی آزمایشگاه علوم اعصاب شناختی مدرسه است. هدف اصلی پژوهشی او استفاده از روش ها و تکنیک های عصب شناسی برای درک بهتر علوم انسانی و اجتماعی است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (23, 'چارلز کان و رابرت مک لین', '<p>رابرت مک لین قبل از پیوستن به نیویورک رند به عنوان تحلیلگر، در رشته مالی تحصیل کرد. او بعداً روی مسائل استراتژیک و سازمانی برای مک کینزی در ایالات متحده، استرالیا و آسیا کار کرد. مک لین همچنین به عنوان رئیس و مدیر دانشکده مدیریت تحصیلات تکمیلی استرالیا خدمت کرد. تمرکز فعلی او بر سرمایه گذاری اجتماعی، بشردوستی و حفاظت است. </p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (24, 'مایکل جی. سیلورستاین', '<p>مایکل جی. سیلورستاین، دیلن بولدن، رون جاکوبسن و روهان ساجده شرکای ارشد و مدیران عامل گروه مشاوره بوستون هستند. سیلورستین نویسنده پرفروش <em>Trading Up</em>، <em>جایزه 10 تریلیون دلاری</em>، <em>زنان بیشتر می خواهند</em> و <em>شکار گنج</em> است. .</p>', '2023-01-26 18:49:41.727512', '2023-01-26 18:49:41.727512', NULL, 'Michael J. Silverstein');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (25, 'دنیل جیمز براون', '<p>دانیل جیمز براون یک نویسنده داستانی غیرداستانی برنده جایزه است. او همچنین نویسنده <em>زیر آسمان شعله ور: طوفان آتش بزرگ هینکلی در سال 1894</em> و <em> ستاره های بی تفاوت بالا: حماسه وحشتناک عروس دونر پارتی</em> است. em>.</p>', '2023-01-26 18:49:46.967345', '2023-01-26 18:49:46.967345', NULL, 'Daniel James Brown');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (26, 'ریچارد ساتن', '<p>ریچارد ساتون یک مشاور سلامت و عملکرد است که به ورزشکاران برتر، تیم های المپیک و فدراسیون های ورزشی بین المللی در مورد مدیریت درد و توسعه ورزشی مشاوره داده است. او همچنین با شرکت‌های پیشرو در زمینه توسعه انعطاف‌پذیری در برابر استرس، افزایش مشارکت کارکنان و افزایش بهره‌وری مشورت می‌کند. </p>', '2023-01-26 18:49:59.080129', '2023-01-26 18:49:59.080129', NULL, 'Richard Sutton');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (27, 'مایکل حیات', '<p>مایکل حیات نویسنده بسیاری از کتاب‌های پرفروش است و چندین دوره آموزشی را طراحی کرده است، از جمله پنج روز تا بهترین سال شما و Free to Focus. او مدیرعامل سابق و رئیس هیئت مدیره ناشران توماس نلسون بود.</p>', '2023-01-26 18:50:04.8781', '2023-01-26 18:50:04.8781', NULL, 'Michael Hyatt');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (28, 'برد فلد و جیسون مندلسون', '<p>براد فلد و جیسون مندلسون سرمایه گذاران اولیه و بنیانگذاران صندوق سرمایه گذاری خطرپذیر <em>Foundry Group</em> هستند. هر دو تجربه گسترده ای در زمینه سرمایه گذاری خطرپذیر دارند و این تجربه را از طریق داستان ها و مشاوره برای سرمایه گذاران و کارآفرینان دیگر در وبلاگ خود askthevc.com در دسترس قرار داده اند.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (29, 'دان تاپسکات و آنتونی دی ویلیامز', '<p>دان تاپسکات یک مدیر اجرایی و مشاور تجاری کانادایی است که بیش از 15 کتاب نوشته است، از جمله کتاب پرفروش <em>Shift پارادایم</em>.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (30, 'الکساندر اوستروالدر', '<p>الکساندر اوستروالدر، کارآفرین و سخنران اصلی محترم، یکی از بنیانگذاران شرکت Strategyzer است که بستر و خدماتی را برای ایجاد محصولات و مشاغل برتر ارائه می دهد.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (31, 'اریکا ولف موری', '<p>اریکا ولف موری نام بزرگی در تجارت کوچک است. سایر کارشناسان بهره‌وری و نوآوری بر روی برندهای بزرگ و شرکت‌های بزرگ تمرکز می‌کنند، اما علاقه و تخصص Wolfe-Murray در ترجمه مفاهیم کلیدی در تجارت و بازاریابی برای شرکت‌های کوچک و استارت‌آپ‌های کوچک نهفته است. Wolfe-Murray علاوه بر نویسنده، کارشناس بازاریابی و مشاور مدیریت، صاحب یک شرکت رسانه ای و مدیر یک برنامه مالیاتی برای مشاغل آزاد است.</p>', '2023-01-26 18:50:26.575595', '2023-01-26 18:50:26.575595', NULL, 'Erica Wolfe-Murray');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (32, 'فرانسیس سیریل', '<p>فرانچسکو سیریلو در دهه 1980 در حالی که در دانشگاه تحصیل می کرد، تکنیک بهره وری خود را که شهرت جهانی داشت، توسعه داد. در آن زمان، او با ساختار موثر روز کاری خود مبارزه کرد و در نهایت منجر به ایجاد تکنیک پومودورو شد. او اکنون وب سایت <em>pomodorotechnique.com</em> را اداره می کند و مربیگری و آموزش های مرتبط با تکنیک خود را ارائه می دهد.</p>', '2023-01-26 18:50:31.633362', '2023-01-26 18:50:31.633362', NULL, 'Francesco Cirillo');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (33, 'اسکات اشتاینبرگ', '<p> اسکات استاینبرگ یک مشاور استراتژیک، سخنران حرفه ای و مقاله نویس در موضوعاتی مانند رهبری و نوآوری است. او علاوه بر ارائه سمینارهای رهبری و کارگاه های آموزشی، نویسنده <em>بازی های بازی ثروتمند شوید</em> است.</p>', '2023-01-26 18:50:36.553781', '2023-01-26 18:50:36.553781', NULL, 'Scott Steinberg');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (34, 'اندرو نیوبرگ و مارک رابرت والدمن', '<p>اندرو نیوبرگ یک عصب شناس در زمینه نوروتئولوژی و مدیر تحقیقات موسسه سلامت یکپارچه مارکوس در فیلادلفیا است. او تعدادی کتاب نوشته است، از جمله کتاب پرفروش <em>چرا خدا نمی رود</em>.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (35, 'جان آکوف', '<p>جان آکوف با پیوستن به تیم دیو رمزی برای تبدیل شدن به یک نویسنده تمام وقت در سال 2010، زندگی خود را تغییر داد. >Gazelles</em>، <em>Baby Steps و 37 چیز دیگری که دیو رمزی در مورد بدهی به من آموخت</em> و <em>موارد مورد علاقه مسیحیان</em>.</p>', '2023-01-26 18:50:46.73431', '2023-01-26 18:50:46.73431', NULL, 'Jon Acuff');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (36, 'شری ترکل', '<p>شری ترکل یک روانشناس متخصص در تعامل انسان-فناوری و روانکاوی است و استاد ابی راکفلر ماوزه مطالعات اجتماعی علم و فناوری در MIT است. او چندین کتاب در مورد تأثیر رسانه های جدید بر جامعه منتشر کرده است، مانند <em>زندگی روی صفحه</em> و <em>تنها با هم</em>.</p>', '2023-01-26 18:50:52.111625', '2023-01-26 18:50:52.111625', NULL, 'Sherry Turkle');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (37, 'فیلیپ ای تتلاک و دن گاردنر', '<p>Philip E. Tetlock، استاد دانشگاه آننبرگ در دانشگاه پنسیلوانیا، متخصص در علوم سیاسی و روانشناسی است. رهبر مطالعه پیش‌بینی پروژه قضاوت خوب، بیش از 200 مقاله در مجلات معتبر منتشر کرده است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (38, 'هلاین اولن و هارولد پولاک', '<p>هلین اولن یک روزنامه‌نگار مالی برنده جوایز است که بر اساس <em>Business Insider</em> در میان 50 زن برتر جهان است که در حال تغییر جهان هستند.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (39, 'بایرون شارپ', '<p>بایرون شارپ استاد علم بازاریابی در دانشگاه استرالیای جنوبی است. او بیش از صد مقاله در مورد تحقیق در بازاریابی نوشته است و عمدتاً بر ایجاد قوانین تجربی که می توانند در عمل بازاریابی استفاده شوند تمرکز دارد.</p>', '2023-01-26 18:51:07.659901', '2023-01-26 18:51:07.659901', NULL, 'Byron Sharp');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (40, 'پاملا دراکرمن', '<p>پاملا دراکرمن گزارشگر سابق کارکنان وال استریت ژورنال است و مقالاتی برای <em>The</em> <em>Guardian</em>، <em>The</em> <em> نوشته است. نیویورک تایمز</em> و <em>The</em> <em>واشنگتن پست</em>. او همچنین نویسنده <em>Lust In Translation: Infidelity from Tokyo to Tennessee</em> است.</p>', '2023-01-26 18:51:12.339873', '2023-01-26 18:51:12.339873', NULL, 'Pamela Druckerman');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (41, 'کاترین کلینتون', '<p>کاترین کلینتون یک معلم و مورخ است که مطالعات آفریقایی-آمریکایی را در دانشگاه هاروارد خوانده و دکترای خود را دریافت کرده است. از دانشگاه پرینستون او بیش از 15 کتاب از جمله <em>داستان‌های جنگ داخلی</em>، <em> خواهران نیمه تاریخ</em> و <em>من هم، آمریکا را می‌خوانم، نوشته است.</em></p>', '2023-01-26 18:51:17.2755', '2023-01-26 18:51:17.2755', NULL, 'Catherine Clinton');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (42, 'میشل اوباما', '<p>میشل اوباما قبل از تحصیل در دانشکده حقوق هاروارد و سپس پیوستن به شرکت حقوقی معتبر شیکاگو Sidley & Austin از دانشگاه پرینستون فارغ التحصیل شد. او قبل از اینکه مدیر اجرایی برنامه مربیگری جوانان Public Allies شود، در دفتر شهردار شهرداری شیکاگو کار می کرد. پس از این، او به عنوان مدیر اجرایی امور اجتماعی در مرکز پزشکی دانشگاه شیکاگو مشغول به کار شد. از زمانی که بانوی اول ایالات متحده شد، او کتاب های متعددی نوشته و مدافع سلامت کودکان و مشکلات خانواده های نظامی بوده است.</p>', '2023-01-26 18:51:22.805963', '2023-01-26 18:51:22.805963', NULL, 'Michelle Obama');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (43, 'جاش ماهر', '<p>جاش ماهر یک سرمایه گذار و مشاور فناوری است. او همچنین رئیس <em>Seattle Angel</em> است، یک سازمان غیرانتفاعی متمرکز بر بازار سرمایه برای استارت‌آپ‌ها در شمال غربی اقیانوس آرام.</p>', '2023-01-26 18:51:27.651202', '2023-01-26 18:51:27.651202', NULL, 'Josh Maher');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (44, 'الکس گلدفین', '<p>الکس گلدفین یک مشاور بازاریابی، مربی کسب و کار و سخنران عمومی است. با استفاده از استراتژی های او، شرکت های Fortune 500 مانند آمازون، لاجیتک و ویرجین موبایل درآمد خود را به طور متوسط ​​15 درصد افزایش داده اند.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (45, 'M. K. گاندی', '<p>مهنداس کارامچاند گاندی (۲ اکتبر ۱۸۶۹ - ۳۰ ژانویه ۱۹۴۸) یک فعال هندی در اوایل قرن بیستم بود. گاندی پس از تلاش برای بهبود حقوق مهاجران هندی در آفریقای جنوبی، در سال 1915 به هند بازگشت تا با اعتقاد تزلزل‌ناپذیر خود به اعتراضات غیرخشونت‌آمیز، جنبش استقلال هند را علیه حکومت بریتانیا رهبری کند تا اینکه در سال 1948 در نماز عصر خود به قتل رسید.</p>', '2023-01-26 18:51:37.877137', '2023-01-26 18:51:37.877137', NULL, 'M. K. Gandhi');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (46, 'کریستوفر رایان و کاسیلدا جتا', '<p>کریستوفر رایان نویسنده و روزنامه نگار با مدرک دکترای روانشناسی است که در آلاسکا، مکزیک، هند و اسپانیا زندگی کرده است. نویسنده هندی-پرتغالی، Cacilda Jethá M.D. یک پزشک و روانپزشک است. رایان و جتا سال‌هاست که ازدواج کرده‌اند و تصمیم گرفته‌اند هیچ جزئیات شخصی درباره زندگی جنسی خود را فاش نکنند.</p>', '2023-01-26 18:51:43.528151', '2023-01-26 18:51:43.528151', NULL, 'Christopher Ryan and Cacilda Jethá');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (47, 'پیتر دراکر', '<p>پیتر دراکر (1909-2005) یکی از متفکران برتر مدیریت کسب و کار در نظر گرفته شد. او مشاور مدیریت، مربی و نویسنده بود. او بیش از 35 عنوان منتشر کرد - مجموعه ای قابل توجه از کار که به پایه و اساس تفکر تجاری مدرن کمک کرد. دراکر در سال 2002 توسط جورج دبلیو بوش مدال آزادی ریاست جمهوری را دریافت کرد.</p>', '2023-01-26 18:51:48.442256', '2023-01-26 18:51:48.442256', NULL, 'Peter Drucker');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (60, 'الریس', '<p>آل ریس یک نویسنده و متخصص بازاریابی است. او یک شرکت مشاوره موفق تاسیس کرد و تعدادی کتاب پرفروش مانند <em>22 قانون تغییر ناپذیر بازاریابی</em> و <em>سقوط تبلیغات و ظهور روابط عمومی</em> نوشته است.</em> p>', '2023-01-26 18:53:05.170449', '2023-01-26 18:53:05.170449', NULL, 'Al Ries');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (451, 'سارا نایت', '<p>سارا نایت نویسنده و ویراستار مستقل آمریکایی است. او دارای مدرک از دانشگاه هاروارد است.</p>', '2023-01-26 19:38:00.798232', '2023-01-26 19:38:00.798232', NULL, 'Sarah Knight');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (48, 'ریچارد دابز', '<p>ریچارد دابز در مک کینزی در مورد الگوهای اقتصادی جهانی تحقیق می کند. او در دانشگاه آکسفورد و چندین دانشگاه دیگر تدریس کرده است. <em>بدون اختلال معمولی</em> دومین کتاب پرفروش او است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (49, 'رابرت ویتاکر', '<p>رابرت ویتاکر نویسنده ای برنده جایزه است که پوشش گسترده ای در مورد مسائل مربوط به سلامت روان و صنعت داروسازی ارائه کرده است. او نویسنده چندین کتاب تحسین شده از جمله <em>دیوانه در آمریکا</em>، <em>همسر نقشه ساز</em> و <em>در دامان خدایان</em> است.</p> >', '2023-01-26 18:51:57.955879', '2023-01-26 18:51:57.955879', NULL, 'Robert Whitaker');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (50, 'جیمز گری', '<p>جیمز گری نویسنده آمریکایی است که کتاب پرفروش <em>New</em> <em>York</em> <em>Time</em> را نوشته است. جهان</em> <em>در</em> <em>a</em> <em>عبارت:</em> <em>A</em> <em>مختصر</em> <em>تاریخچه </em> <em>از</em> <em></em> <em>آفوریسم</em>. او سردبیر سابق مجله <em>TIME</em> در اروپا است.</p>', '2023-01-26 18:52:06.781913', '2023-01-26 18:52:06.781913', NULL, 'James Geary');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (51, 'و. ارزش اهمیت دارد', '<p>W. چان کیم و رنه موبورن، استادان استراتژی در INSEAD، یک مدرسه بازرگانی بین‌المللی با پردیس‌هایی در فرانسه، ابوظبی و ایالات متحده هستند. تجارت کلاسیک <em>استراتژی اقیانوس آبی</em>بیش از چهار میلیون نسخه در سراسر جهان فروخته شد. در سال 2017، ادامه آن <em>Blue Ocean Shift</em>به پرفروش‌ترین <em>نیویورک تایمز</em> تبدیل شد. در سال 2019، کیم و موبورن توسط Thinkers50 به عنوان متفکران شماره یک مدیریت در جهان معرفی شدند.</p>', '2023-01-26 18:52:12.067038', '2023-01-26 18:52:12.067038', NULL, 'W. Chan Kim');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (52, 'دیوید جی. هند', '<p>دیوید جی. هند استاد ممتاز در امپریال کالج لندن و همچنین رئیس سابق انجمن رویال آمار است. او متخصص ریاضیات مالی، اندازه‌گیری و آمار محاسباتی است و چندین کتاب از جمله <em>اطلاعات</em> <em>تولید:</em> <em>چگونه</em> <em>داده‌ها< /em> <em>قانون</em> <em>ما</em> <em>جهان</em> و <em>آمار:</em> <em>A</em> <em>خیلی< /em> <em>کوتاه</em> <em>مقدمه</em>.</p>', '2023-01-26 18:52:17.064013', '2023-01-26 18:52:17.064013', NULL, 'David J. Hand');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (53, 'شرلی دیویس', '<p>دکتر شرلی دیویس رئیس و مدیر عامل شرکت SDS Global Enterprises، یک شرکت راه حل های توسعه استراتژیک متخصص در HR است. او در چندین شرکت Fortune 100 و Fortune 50 در نقش‌های رهبری ارشد و اجرایی کار کرده است. او همچنین نویسنده پرفروش <em>صندلی</em> و <em>خودت را دوباره اختراع کن</em> است.</p>', '2023-01-26 18:52:23.095886', '2023-01-26 18:52:23.095886', NULL, 'Shirley Davis');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (54, 'جی. کریگ ونتر', '<p>ج. کریگ ونتر یک بیوشیمی و ژنتیک است و یکی از دانشمندان برجسته قرن بیست و یکم به شمار می رود. در سال 2001، ونتر توالی کامل ژنوم انسان را منتشر کرد. او بنیانگذار Celera Genomics، موسسه تحقیقات ژنومیک (TIGR) و موسسه J. Craig Venter (JCVI) است. ونتر همچنین نویسنده کتاب <em>زندگی با سرعت نور</em> است.</p>', '2023-01-26 18:52:34.838841', '2023-01-26 18:52:34.838841', NULL, 'J. Craig Venter');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (55, 'محمد را بزرگ کرد', '<p>رافی محمد بنیانگذار فرهنگ سود است، مشاوره ای که به کسب و کارها کمک می کند تا استراتژی های قیمت گذاری را توسعه و بهبود بخشند. محمد با حدود 20 سال تجربه در زمینه تخصصی خود، کتابهای تجاری دیگری از جمله <em>هنر قیمت گذاری</em> را نیز تالیف کرده است.</p>', '2023-01-26 18:52:39.559816', '2023-01-26 18:52:39.559816', NULL, 'Rafi Mohammed');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (56, 'دون میگل رویز و دون خوزه رویز', '<p>دون میگل رویز نویسنده <em>چهار توافقنامه</em> است که بیش از هفت سال پرفروش‌ترین کتاب <em>نیویورک تایمز</em> باقی ماند. از دیگر کتاب های او می توان به <em>تسلط عشق</em>و <em>صدای دانش</em> اشاره کرد. او از فلسفه های فرهنگ تولتک که بیش از هزار سال پیش در مکزیک شکوفا شد، استفاده می کند.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (57, 'بی ویلسون', '<p>بی ویلسون مورخ و نویسنده کتاب‌های بسیاری است، از جمله <em>کلاهبردار</em> و <em>چنگال را در نظر بگیرید</em>. ویلسون همچنین یک روزنامه‌نگار تحسین‌شده غذا، در سال 2002 توسط رادیو بی‌بی‌سی نویسنده غذای سال و روزنامه‌نگار غذای سال در سال‌های 2004، 2008 و 2009 توسط انجمن نویسندگان غذا برای ستون <em>ساندی تلگراف</em> خود انتخاب شد. متفکر آشپزخانه.</p>', '2023-01-26 18:52:50.75625', '2023-01-26 18:52:50.75625', NULL, 'Bee Wilson');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (58, 'مایکل ایستر', '<p>مایکل ایستر نویسنده و سردبیر مجله <em>Men’s Health</em> برنده جایزه است. او در دانشگاه نوادا، لاس وگاس، روزنامه نگاری تدریس می کند. <em>بحران آسایش</em> اولین کتاب او است.</p>', '2023-01-26 18:52:55.554159', '2023-01-26 18:52:55.554159', NULL, 'Michael Easter');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (59, 'ساکا سنقر', '<p>شاکا سنگور یک مربی، نویسنده و سخنران TED است که 19 سال را به جرم قتل در زندان گذراند. او در حال حاضر به عنوان مدیر استراتژی و نوآوری با #cut50 کار می کند، ابتکاری برای کاهش جمعیت زندانیان ایالات متحده تا سال 2025 به نصف.</p>', '2023-01-26 18:53:00.256584', '2023-01-26 18:53:00.256584', NULL, 'Shaka Senghor');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1346, 'سونکه آرنس', '<p>Sönke Ahrens یک نویسنده و محقق در آموزش و پرورش و علوم اجتماعی است. او همچنین نویسنده کتاب برنده جایزه <em>آزمایش و اکتشاف: اشکال جهانی افشای</em> است.</p>', '2023-01-27 02:43:57.272854', '2023-01-27 02:43:57.272854', NULL, 'Sönke Ahrens');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (61, 'مایکل بانگای استانیر', '<p>Michael Bungay Stanier در سال 2019 به عنوان رهبر فکری شماره 1 در مربیگری انتخاب شد. کتاب قبلی او، <em>عادت مربیگری،</em> 700000 نسخه فروخت و بیش از 1000 نقد پنج ستاره در آمازون به دست آورد. او بنیانگذار شرکت یادگیری و توسعه Box of Crayons است و به سراسر جهان سفر کرده و به شرکت‌ها در مورد چگونگی توسعه سبک‌های رهبری بهتر مشاوره داده است.</p>', '2023-01-26 18:53:09.630358', '2023-01-26 18:53:09.630358', NULL, 'Michael Bungay Stanier');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (62, 'اریکا شولتز و مایک شولتز', '<p>Erica و Mike Schulz رهبران گروه RAIN، یکی از شرکت‌های آموزش فروش پیشرو در جهان هستند. آنها با سازمان های برتر از جمله تویوتا و مدرسه بازرگانی هاروارد کار کرده اند. مایک همچنین چندین کتاب دیگر از جمله <em>گفتگوهای باران زایی</em> نوشته است. آنها همچنین پدر و مادر آری، پسرشان هستند که آنها را بزرگترین دستاورد خود می دانند.</p>', '2023-01-26 18:53:14.874477', '2023-01-26 18:53:14.874477', NULL, 'Erica Schultz and Mike Schultz');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (63, 'کیت هارتلی', '<p> کیت هارتلی بیش از 25 سال تجربه کار در روابط عمومی، مدیریت شهرت و ارتباطات بحران دارد. او یکی از بنیانگذاران Polpeo است، سازمانی که برندها را در مورد نحوه مدیریت بحران هایی که به صورت آنلاین انجام می شوند آموزش می دهد. </p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (64, 'جان مارک کومر', '<p>جان مارک کومر کشیش کلیسای بریج تاون در پورتلند، اورگان است. او دارای مدرک کارشناسی ارشد در مطالعات کتاب مقدس و الهیات از حوزه علمیه غرب است. کتاب‌های قبلی او <em>نام من امید است</em> و <em>عشق‌شناسی</em> کاوش‌های صمیمی در مورد اضطراب، افسردگی و ازدواج از منظر معنوی هستند. او همچنین میزبان پادکست <em>این لحظه فرهنگی</em> است که درباره پیچیدگی زندگی معنوی در دنیای مدرن است.</p>', '2023-01-26 18:53:27.713405', '2023-01-26 18:53:27.713405', NULL, 'John Mark Comer');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (65, 'میشل درزبولد', '<p>میشل درزبولد، کارشناس دست خط، تنها غیرنظامی است که برای برنامه آموزشی آزمون پیشرفته اسناد سرویس مخفی ایالات متحده دعوت شده است. تخصص او به سازمان های مجری قانون کمک کرده است تا مجرمان مرگبار را به طور دقیق معرفی کنند و پرونده های مربوط به آدم ربایی، آتش زدن، جعل و قتل را حل کنند.</p>', '2023-01-26 18:53:32.727294', '2023-01-26 18:53:32.727294', NULL, 'Michelle Dresbold');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (66, 'مایکل ماس', '<p>مایکل ماس یک روزنامه نگار برنده جایزه پولیتزر است که برای <em>New</em> <em>York</em> <em>Times</em> و <em>Wall</em> نوشته است. > <em>خیابان</em> <em>ژورنال.</em></p>', '2023-01-26 18:53:37.807497', '2023-01-26 18:53:37.807497', NULL, 'Michael Moss');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (67, 'مارکوس اورلیوس', '<p>مارکوس اورلیوس آنتونینوس (121-180 پس از میلاد) به عنوان امپراتور روم در سال 161 پس از میلاد به قدرت رسید. او را یکی از بزرگترین امپراتوران روم، مردی عادل و فرمانروایی می نامند که عمیقاً برای فلسفه ارزش قائل بود.</p>', '2023-01-26 18:53:43.022213', '2023-01-26 18:53:43.022213', NULL, 'Marcus Aurelius');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (68, 'وین بیکر', '<p>وین بیکر، استاد رابرت پی تام در مدیریت بازرگانی و استاد مدیریت و سازمان‌ها در دانشکده بازرگانی راس دانشگاه میشیگان است. او همچنین مدیر هیئت علمی مرکز تشکل های مثبت است. از وی شش کتاب و مقالات علمی متعددی منتشر شده است. </p>', '2023-01-26 18:53:54.751718', '2023-01-26 18:53:54.751718', NULL, 'Wayne Baker');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (69, 'مارک هورویتز و سامانتا هورویتز', '<p>Marc Hurwitz یکی از بنیانگذاران و مدیر ارشد بینش FlipSkills است. او دارای مدرک دکترا در علوم اعصاب شناختی است و در دانشگاه واترلو سخنرانی می کند.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (70, 'استیون آر گاندری', '<p>استیون آر. گاندری، استاد سابق جراحی قلب در دانشگاه لوما لیندا و مدیر مرکز طب ترمیمی در کالیفرنیا است. او همچنین نویسنده <em>Dr. تکامل رژیم غذایی Gundry</em>.</p>', '2023-01-26 18:54:04.741806', '2023-01-26 18:54:04.741806', NULL, 'Steven R. Gundry');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (71, 'نانسی بلیک', '<p>نانسی بلیک موسس و رئیس شرکت آموزش و مشاوره Sales Pro Insider است. او توسعه دهنده دوره های آموزشی واقعی است.</p>', '2023-01-26 18:54:10.514165', '2023-01-26 18:54:10.514165', NULL, 'Nancy Bleeke');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (72, 'برایان شاو', '<p>برایان سوی یک کارآفرین و مدیر Aespire است، یک شرکت طراحی و ارتباطات که به سازمان‌های غیرانتفاعی و بشردوستانه کمک می‌کند.</p>', '2023-01-26 18:54:15.511172', '2023-01-26 18:54:15.511172', NULL, 'Brian Sooy');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (73, 'استر وویچیکی', '<p> استر وویچیکی یک روزنامه‌نگار، مربی و مادر دو تن از موفق‌ترین کارآفرینان زن سیلیکون ولی، سوزان و آن وویچیکی است. خالق برنامه هنرهای رسانه ای دبیرستان پالو آلتو در کالیفرنیا، رویکردهای آموزشی Wojcicki توسط مدارس سراسر جهان اتخاذ شده است. در سال 2002، او به عنوان معلم سال کالیفرنیا انتخاب شد.</p>', '2023-01-26 18:54:20.950946', '2023-01-26 18:54:20.950946', NULL, 'Esther Wojcicki');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (74, 'موسسه آربینگر', '<p>موسسه Arbinger که توسط محققان در سال 1979 تأسیس شد، به انتشار پیام صلح از طریق کتاب، آموزش و ابزارهای دیگر اختصاص دارد. این موسسه بیش از 300 عضو دارد، از جمله مربیان و کارکنانی که در دفاتری واقع در هجده کشور مختلف کار می کنند.</p>', '2023-01-26 18:54:26.062653', '2023-01-26 18:54:26.062653', NULL, 'The Arbinger Institute');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (89, 'چارلی گیلکی', '<p>چارلی گیلکی یک فیلسوف، کهنه سرباز ارتش و کارآفرین است. شرکت او، Productive Flourishing، به کمک به خلاقان، کارآفرینان و رهبران برای پیشرفت در زندگی کاری و شخصی خود اختصاص دارد. گیلکی همچنین نویسنده <em>چرخه حیات کسب و کار کوچک</em> و میزبان پادکست <em>شکوفایی تولیدی</em> است.</p>', '2023-01-26 18:55:42.538211', '2023-01-26 18:55:42.538211', NULL, 'Charlie Gilkey');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (75, 'مایکل گرگر', '<p>مایکل گرگر، دکتر، پزشک، نویسنده و حامی سلامت عمومی آمریکایی است. گرگر نویسنده پرفروش <em>چگونه نمرد</em> و <em>کتاب آشپزی چگونه نمرد</em>، چندین مقاله آکادمیک نیز منتشر کرده است. گرگر قصد دارد منبع اطلاعاتی باشد که می‌توانید به آن اعتماد کنید، تمام سود حاصل از کتاب‌ها و سخنرانی‌هایش را به امور خیریه اهدا می‌کند، و یک وب‌سایت رایگان به نام NutritionFacts.org راه‌اندازی می‌کند. </p>', '2023-01-26 18:54:31.08696', '2023-01-26 18:54:31.08696', NULL, 'Michael Greger');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (76, 'و مردیث', '<p>دن مردیت نویسنده پرفروش <em>How to be F*cking Awesome</em> است. او کسب‌وکار کپی‌نویسی، خدمات ورزشی ممتاز، آژانس بازاریابی و یک گروه خودیاری بزرگ در فیس‌بوک به نام «قهوه با دن» را که بیش از 4000 دنبال‌کننده دارد، اداره می‌کند.</p>', '2023-01-26 18:54:36.012403', '2023-01-26 18:54:36.012403', NULL, 'Dan Meredith');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (77, 'صلح اولیه', '<p>آدیاشانتی یک معلم معنوی آمریکایی تبار است. کتاب‌های او عبارتند از <em>رقص پوچی، پایان دنیای تو، مراقبه واقعی، راه رهایی،</em> و <em> سقوط به فیض</em>.</p>', '2023-01-26 18:54:40.988402', '2023-01-26 18:54:40.988402', NULL, 'Adyashanti');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (78, 'هنر سوبچاک', '<p>Art Sobczak بیش از 30 سال تجربه در صنعت فروش دارد. او یک مربی حرفه ای تماس سرد B2B در شرکتش Business By Phone Inc. است و <em>تماس هوشمند</em> اولین کتاب پرفروش او است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (79, 'ما سنگ', '<p>Biz Stone قبل از تأسیس توییتر به ایجاد Xanga، Blogger و Odeo کمک کرد. پس از ترک توییتر، استون Jelly را تأسیس کرد که یک اپلیکیشن پرسش و پاسخ مبتنی بر تصویر بود و به یک سرمایه‌گذار فرشته برای تعدادی از شرکت‌ها از جمله Square و Beyond Meat تبدیل شد. کتاب های قبلی او <em>چه کسی</em> <em>اجازه</em> <em></em> <em>وبلاگ ها</em> <em>بیرون برود؟</em> و <em>وبلاگینگ است. :</em> <em>نابغه</em> <em>استراتژی‌ها</em> <em>برای</em> <em>Instant</em> <em>وب</em> <em>محتوا< /em>.</p>', '2023-01-26 18:54:51.357694', '2023-01-26 18:54:51.357694', NULL, 'Biz Stone');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (80, 'من دوگن هستم', '<p>سام دوگن، خالق <em>سامورایی مالی بسیار موفق،</em> بازنشسته شد. او پس از کار در یک بانک سرمایه گذاری برتر و رفتن به مدرسه بازرگانی پاره وقت در سن 34 سالگی بازنشستگی خود را به پایان رساند. انگیزه او برای نوشتن <em>این را بخر، نه آن را</em> ارائه نکات و توصیه هایی به هرکسی بود که به دنبال استقلال مالی بود. </p>', '2023-01-26 18:54:56.141219', '2023-01-26 18:54:56.141219', NULL, 'Sam Dogen');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (81, 'جولی ییپ ویلیامز', '<p> جولی ییپ ویلیامز دیپ لی تان در ویتنام به دنیا آمد و در کودکی با خانواده خود به ایالات متحده مهاجرت کرد. او به تحصیل در دانشکده حقوق هاروارد ادامه داد و در شهر نیویورک وکیل شد. پس از تشخیص سرطان روده بزرگ، جولی شروع به نوشتن در مورد مبارزه با بیماری و زندگی گسترده تر خود در یک وبلاگ آنلاین کرد و طرفداران زیادی را جمع کرد. او در سال 2018 درگذشت.</p>', '2023-01-26 18:55:01.086358', '2023-01-26 18:55:01.086358', NULL, 'Julie Yip-Williams');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (82, 'میشل بوربا', '<p>میکل بوربا یک روانشناس آموزشی و نویسنده پرفروش با بیش از 40 سال تجربه در کمک به والدین و فرزندانشان است. او همچنین <em>UnSelfie</em> را نوشته است، مطالعه‌ای درباره همدلی در عصر رسانه‌های اجتماعی خودمحور، و به طور منظم در برنامه‌های تلویزیونی از جمله <em>Today</em>، <em>Dateline</em> مشارکت می‌کند. ، <em>نما</em>، <em>دکتر. Phil</em>، <em>NBC Nightly News</em>، <em>Fox & Friends</em>، <em>Dr. Oz</em>، و <em>نمایش اولیه</em>.</p>', '2023-01-26 18:55:06.221122', '2023-01-26 18:55:06.221122', NULL, 'Michele Borba');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (83, 'سباستین مالابی', '<p>سباستین مالابی سردبیر <em>فایننشال تایمز</em> و پل ولکر عضو ارشد اقتصاد بین‌الملل در شورای روابط خارجی است.</p>', '2023-01-26 18:55:11.868364', '2023-01-26 18:55:11.868364', NULL, 'Sebastian Mallaby');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (84, 'تیاگو فورته', '<p>تیاگو فورته ForteLabs را تاسیس کرد و در زمینه بهره وری و مدیریت دانش شخصی متخصص است. او برای شرکت‌هایی مانند تویوتا، نستله، و بانک توسعه بین‌آمریکایی مشورت کرده و مهارت‌های بهره‌وری را به جامعه‌ای متشکل از ۲۵۰۰۰ زبان‌آموز آنلاین آموزش داده است.</p>', '2023-01-26 18:55:17.59632', '2023-01-26 18:55:17.59632', NULL, 'Tiago Forte');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (85, 'چیپ هیث و دن هیث', '<p> چیپ هیث استاد رفتار سازمانی در دانشگاه استنفورد است و برادرش دان هیث از اعضای ارشد دانشگاه دوک است. آن‌ها دو کتاب پرفروش دیگر را با همکاری یکدیگر نوشته‌اند: <em>ساخته شده است</em> و <em>قاطع</em>.</p>', '2023-01-26 18:55:22.803082', '2023-01-26 18:55:22.803082', NULL, 'Chip Heath & Dan Heath');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (86, 'لونگ اونگ', '<p>لونگ اونگ یک مدرس و فعال است. او به طور گسترده در مورد کامبوج و تجربیات خود و خانواده اش تحت حکومت خمرهای سرخ نوشته است. او سخنگوی ملی کمپین برای جهانی عاری از مین است.</p>', '2023-01-26 18:55:28.282862', '2023-01-26 18:55:28.282862', NULL, 'Loung Ung');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (87, 'جان بروکس', '<p>جان بروکس (1920-1993) روزنامه‌نگار و نویسنده بود که عمدتاً به‌خاطر کارش به‌عنوان همکار قدیمی در <em>The</em> <em>New</em> <em>Yorker</em> شناخته می‌شود. مجله em>، جایی که او مقالاتی مشابه آنچه در <em>کسب و کار</em> <em>ماجراهای</em> در مورد آنها صحبت شد نوشت.</p>', '2023-01-26 18:55:32.763957', '2023-01-26 18:55:32.763957', NULL, 'John Brooks');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (88, 'ریچارد شریدان', '<p>ریچارد شریدان بنیانگذار Menlo Innovations است، یک شرکت مشاوره و طراحی نرم افزار مستقر در Ann Arbor، میشیگان که جوایز متعددی را برای فرهنگ محل کار خود دریافت کرده است. شریدان و شرکتش میزبان تورها و بازدیدهای بی‌شماری از شرکت‌ها و رهبران دیگری هستند که مشتاق درک رازهای موفقیت منلو هستند. او نویسنده کتاب پرفروش <em>Joy, Inc</em> است.</p>', '2023-01-26 18:55:37.823641', '2023-01-26 18:55:37.823641', NULL, 'Richard Sheridan');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (90, 'استوارت فایرستاین', '<p>استوارت فایرستاین رئیس بخش زیست شناسی دانشگاه کلمبیا است، جایی که آزمایشگاه او در حال بررسی سیستم بویایی پستانداران است. علاوه بر این، Firestein در سال 2011 جایزه هیئت علمی برجسته Lenfest Distinguished Columbia را برای برتری در بورس تحصیلی و تدریس دریافت کرد.</p>', '2023-01-26 18:55:47.445273', '2023-01-26 18:55:47.445273', NULL, 'Stuart Firestein');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (91, 'جردن بی پیترسون', '<p>جردن پترسون استاد روانشناسی در دانشگاه تورنتو و همچنین روانشناس بالینی و منتقد فرهنگی است. او به دلیل ویدیوهای اغلب جنجالی خود در یوتیوب و حضورهای عمومی، که در آنها صحت سیاسی را نقد می کند، تبلیغات و پوشش رسانه ای گسترده ای به دست آورده است.</p>', '2023-01-26 18:55:52.486354', '2023-01-26 18:55:52.486354', NULL, 'Jordan B. Peterson');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (92, 'رندی پاوش', '<p>رندی پاوش استاد تعامل انسان و کامپیوتر در دانشگاه کارنگی ملون بود. سخنرانی خداحافظی او، با عنوان اصلی "آخرین سخنرانی: واقعاً رسیدن به رویاهای دوران کودکی شما"، اندکی قبل از مرگ او در سال 2008 ایراد شد. </p>', '2023-01-26 18:55:57.409793', '2023-01-26 18:55:57.409793', NULL, 'Randy Pausch');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (93, 'آلن پاتریکوف', '<p>آلن پاتریکوف یک سرمایه‌گذار آمریکایی است که شرکت‌های Greycroft و Apax Partners را تأسیس کرد. او در طول زندگی طولانی خود در رشد و توسعه شرکت های بزرگی مانند Venmo، Bumble، HuffPost، America Online، Office Depot و Apple Computer مشارکت داشته است. در حال حاضر، او در حال توسعه آخرین شرکت خود، Primetime Partners است که بر روی سرمایه گذاری در فناوری، محصولات و خدمات مرتبط با پیری متمرکز است. </p>', '2023-01-26 18:56:02.849659', '2023-01-26 18:56:02.849659', NULL, 'Alan Patricof');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (94, 'لورا شروف و الکس ترسنیوسکی', '<p>لورا شروف مدیر سابق تبلیغات برای نشریات متعدد، از جمله <em>USA Today</em>، مجله <em>People</em> و <em>InStyle</em> است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (95, 'بن کارلسون', '<p>بن کارلسون مدیر مدیریت دارایی نهادی در مدیریت ثروت Ritholtz است که متخصص در برنامه ریزی مالی و مدیریت دارایی است. او همچنین وبلاگ نویس پشت سایت تحسین شده <a href="http://www.awealthofcommonsense.com" rel="nofollow">www.awealthofcommonsense.com</a> است که اطلاعات حیاتی در مورد مدیریت ثروت، بازارهای مالی و سرمایه گذار ارائه می دهد. روانشناسی.</p>', '2023-01-26 18:56:13.547632', '2023-01-26 18:56:13.547632', NULL, 'Ben Carlson');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (96, 'چارلز پاسترناک', '<p>چارلز پاسترناک، بیوشیمی‌دان و نویسنده، قبلاً در دانشگاه آکسفورد تدریس می‌کرد، جایی که مرکز بین‌المللی بیوپزشکی آکسفورد را تأسیس کرد. پدربزرگ او لئونید پاسترناک، نقاش پست امپرسیونیست، و عمویش بوریس پاسترناک، رمان نویس برنده جایزه نوبل و نویسنده <em>دکتر ژیواگو</em> است.</p>', '2023-01-26 18:56:18.378762', '2023-01-26 18:56:18.378762', NULL, 'Charles Pasternak');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (97, 'دبلیو کریس وینتر', '<p>W. دکتر کریس وینتر، متخصص خواب و متخصص مغز و اعصاب است. او مشاور کسب‌وکارهای بزرگ، سازمان‌های ورزشی و ارتش ایالات متحده در مورد ارتباط بین خواب و عملکرد است. به عنوان نویسنده، او همچنین به <em>هافینگتون پست</em>، <em>جهان دونده</em> و <em>جزئیات</em> کمک کرده است.</p>', '2023-01-26 18:56:22.979226', '2023-01-26 18:56:22.979226', NULL, 'W. Chris Winter');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (98, 'جفری ا. مور', '<p>جفری آ. مور دارای دکترای ادبیات از دانشگاه واشنگتن است و به عنوان مشاور برای شرکت های فناوری مانند Salesforce و Microsoft کار می کند. اولین کتاب او، <em> عبور از شکاف</em>، بیش از یک میلیون نسخه فروخت.</p>', '2023-01-26 18:56:27.91753', '2023-01-26 18:56:27.91753', NULL, 'Geoffrey A. Moore');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (99, 'مارکوس باکینگهام و کرت کافمن', '<p>مارکوس باکینگهام و کرت کافمن هر دو سابقه مشاوره تجاری و تحقیقات تجاری دارند. در زمان انتشار کتاب، آنها برای سازمان گالوپ، یک شرکت مشاوره مدیریت عملکرد جهانی، کار می کردند. باکینگهام و کافمن هر دو شرکت‌های مشاوره و آموزش مدیریت را راه‌اندازی کرده‌اند و کتاب‌های پرفروش دیگری برای کسب‌وکار نوشته‌اند.</p>', '2023-01-26 18:56:32.707681', '2023-01-26 18:56:32.707681', NULL, 'Marcus Buckingham and Curt Coffman');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (100, 'برنه براون', '<p>برنه براون یک استاد محقق در دانشگاه هیوستون است و بیش از 15 سال را صرف مطالعه طیفی از احساسات، مانند آسیب پذیری، شجاعت، همدلی و شرم کرده است. سخنرانی او در TED، <em>قدرت آسیب پذیری</em>، بیش از 30 میلیون بازدید در سراسر جهان داشته است و او چهار کتاب پرفروش از جمله <em>Rising Strong</em> و <em>Daring Greatly</em>نوشته است. em>.</p>', '2023-01-26 18:56:38.178624', '2023-01-26 18:56:38.178624', NULL, 'Brené Brown');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (101, 'کریستین بوش', '<p>دکتر کریستین بوش استاد دانشگاه نیویورک است، جایی که او برنامه اقتصاد جهانی CGA را مدیریت می کند، و یک عضو مدعو در دانشکده اقتصاد لندن. کریستین یکی از بنیانگذاران شبکه Sandbox است که کارآفرینان و نوآوران از سراسر جهان و Leaders on Purpose را گرد هم می آورد، سازمانی که رهبران هدفمند را گرد هم می آورد. توییتر او: @ChrisSerendip. </p>', '2023-01-26 18:56:43.798604', '2023-01-26 18:56:43.798604', NULL, 'Christian Busch');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (102, 'لیزا وودراف', '<p>لیزا وودراف Organize365 را در میز آشپزخانه خود در سال 2012 شروع کرد. امروزه این برند محبوب سازماندهی کاغذ است. این برند با پادکست ها، محصولات، گواهینامه ها و کارگاه های آموزشی در مورد سازمان، افرادی را از سراسر ایالات متحده جذب می کند که به دنبال ابزارهایی برای رام کردن کاغذهای خارج از کنترل زندگی خود هستند. وودراف با خانواده اش در وست چستر، اوهایو زندگی می کند.</p>', '2023-01-26 18:56:49.174064', '2023-01-26 18:56:49.174064', NULL, 'Lisa Woodruff');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (103, 'کارین بی پورویس', '<p>مرحوم دکتر کارین پورویس مدیر بنیاد ریس جونز و یکی از بنیانگذاران موسسه رشد کودک کارین پورویس در دانشگاه مسیحی تگزاس در فورت ورث بود.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (104, 'بث میسی', '<p>بت میسی نویسنده و روزنامه نگار آمریکایی است که برنده بیش از دوازده جایزه برای برتری در روزنامه نگاری شده است. او به عنوان دختر یک کارگر کارخانه، کار خود را وقف زندگی مردم عادی کرده است.</p>', '2023-01-26 18:56:58.829009', '2023-01-26 18:56:58.829009', NULL, 'Beth Macy');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (105, 'مارک کورلانسکی', '<p>مارک کورلانسکی یک روزنامه نگار آمریکایی است که تعدادی کتاب داستانی و غیرداستانی نوشته است. کتاب پرفروش بین المللی <em>Cod</em> او به 15 زبان مختلف ترجمه شده است. از دیگر آثار او می توان به <em>نمک</em> و <em>جهان بدون ماهی</em> اشاره کرد.</p>', '2023-01-26 18:57:04.706696', '2023-01-26 18:57:04.706696', NULL, 'Mark Kurlansky');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (106, 'گابریل دولان', '<p>گابریل دولان نویسنده، مربی و سخنران اصلی متخصص در رهبری معتبر و داستان سرایی قانع کننده است. او دارای مدرک MBA در مدیریت و رهبری است و نویسنده پنج کتاب از جمله کتاب پرفروش <em>Ignite: Real Leadership, Real Talk, Real Results</em> (2015) است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (107, 'جان کوتس', '<p>جان کوتس یک عصب شناس است که در دانشگاه کمبریج کار می کند و یک تاجر سابق <em>وال استریت</em> (برای <em>گلدمن ساکس</em>، <em>مریل لینچ</em> و <em>Deutsche Bank</em>). در سال 2012، او در فهرست نهایی <em>فایننشال تایمز</em> و <em>جایزه بهترین کتاب کسب و کار سال گلدمن ساکس</em> قرار گرفت و در مجله <em>Foreign Policy</em> نام گرفت. فهرست 100 متفکر برتر جهانی.</p>', '2023-01-26 18:57:22.469998', '2023-01-26 18:57:22.469998', NULL, 'John Coates');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (108, 'والاس دی. واتلز', '<p>والاس دی. واتلز نویسنده و متفکری در جنبش اندیشه نو بود، رویکردی فلسفی به زندگی که فرض می‌کند خدا در همه چیز، از جمله همه انسان‌ها، وجود دارد. از دیگر کتاب‌های او می‌توان به <em>علم خوب بودن</em> و <em>علم بزرگ بودن</em> اشاره کرد.</p>', '2023-01-26 18:57:27.644833', '2023-01-26 18:57:27.644833', NULL, ' Wallace D. Wattles');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (109, 'مت واتکینسون', '<p>مت واتکینسون یک مشاور تجاری مشهور بین المللی است. اولین کتاب او، <em>ده اصل پشت تجارب عالی مشتری</em>، برنده جایزه کتاب مدیریت سال موسسه مدیریت خبره در سال 2014 شد. </p>', '2023-01-26 18:57:32.409401', '2023-01-26 18:57:32.409401', NULL, 'Matt Watkinson');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (110, 'از بانک خارج شد', '<p>ساشا ساگان نویسنده، تدوینگر، فیلمساز و تهیه کننده تلویزیونی است که در نیویورک، بوستون و لندن کار کرده است. مقالات او که به دلیل بررسی آیین های فرهنگی از طریق علم شناخته شده است، در نشریاتی از جمله <em>مجله نیویورک</em> و <em>O، مجله اپرا</em></p> منتشر شده است.', '2023-01-26 18:57:37.546687', '2023-01-26 18:57:37.546687', NULL, 'Sasha Sagan');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (111, 'اندرو چن', '<p>اندرو چن یک شریک عمومی در شرکت سرمایه گذاری خطرپذیر Andreessen Horowitz است. قبل از آن، او تیم‌های رشد در اوبر را در سال‌های اولیه خود رهبری می‌کرد. او همچنین عضو هیئت مدیره استارت‌آپ‌های با رشد سریعی مانند Substack، Clubhouse، Z League، All Day Kitchens، Sleeper، Maven و Reforge است. او یک وبلاگ پرطرفدار را اداره می‌کند و کارهایش در <em>Wired</em>، <em>وال استریت ژورنال</em> و <em>نیویورک تایمز</em> به نمایش درآمده است.</p >', '2023-01-26 18:57:43.123863', '2023-01-26 18:57:43.123863', NULL, 'Andrew Chen');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (112, 'جنیفر ارشد', '<p>جنیفر ارشد در مورد سلامت روان و علوم اجتماعی می نویسد و یکی از سردبیران <em> مجله نیویورک</em> است. علاوه بر نویسندگی و سخنرانی عمومی، ارشد در تعدادی از برنامه های تلویزیونی، از جمله <em>صبح بخیر آمریکا</em> و <em>امروز</em> ظاهر شده است.</p>', '2023-01-26 18:57:48.246276', '2023-01-26 18:57:48.246276', NULL, 'Jennifer Senior');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (113, 'پاتریک ام. لنسیونی', '<p>پاتریک ام. لنسیونی یک مرجع در ایجاد تیم های سالم است که روش کار سازمان ها را تغییر می دهد. او بنیانگذار شرکت مشاوره مدیریت The Table Group است و به مشتریان مختلفی مانند شرکت های Fortune 500، دانشگاه ها، تیم های ورزشی، ارتش و موسسات مذهبی مشاوره می دهد. لنسیونی همچنین یک سخنران برجسته و نویسنده پرفروش <em>نیویورک تایمز</em> <em>پنج اختلال عملکرد یک تیم</em>، <em>چهار وسواس یک مدیر فوق العاده</em است. >، و <em>مرگ بر اثر ملاقات</em>.</p>', '2023-01-26 18:57:53.113064', '2023-01-26 18:57:53.113064', NULL, 'Patrick M. Lencioni');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (114, 'رابرت گلیزر', '<p>رابرت گلیزر، بنیانگذار و مدیر عامل آژانس بازاریابی عملکرد Accelerate، برای صدها هزار خواننده که مشترک خبرنامه هفتگی الهام بخش "جمعه به جلو" او هستند، شناخته شده است. او نویسنده چندین کتاب انگیزشی پرفروش و همچنین یک سخنران الهام بخش است.</p>', '2023-01-26 18:57:58.427333', '2023-01-26 18:57:58.427333', NULL, 'Robert Glazer');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (128, 'توماس اریکسون', '<p>توماس اریکسون یک متخصص رفتار و نویسنده پرفروش است. اولین کتاب او، <em>در احاطه شده توسط احمق ها</em>، بیش از سه میلیون نسخه در سراسر جهان فروخته و به 42 زبان ترجمه شده است. اریکسون همچنین یک سخنران عمومی مورد توجه است و سخنرانی ها و سمینارهایی را در شرکت های بزرگی از جمله IKEA، کوکاکولا، مایکروسافت و ولوو ارائه کرده است.</p>', '2023-01-26 18:59:09.718837', '2023-01-26 18:59:09.718837', NULL, 'Thomas Erikson');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (115, 'کریس لوئیس', '<p>کریس لوئیس یک کارشناس برجسته ارتباطات و بنیانگذار هیئت مشاوران لوئیس، یک آژانس روابط عمومی و ارتباطات پیشرو است. تجربه او شامل ارائه آموزش رسانه ای برای رهبران تجاری، سیاستمداران و افراد مشهور و انتشار مقاله در <em>گاردین</em>، <em>فایننشال تایمز،</em> و <em>دیلی تلگراف</em است. > لوئیس همچنین نویسنده 20 کتاب پرفروش کتاب شومیز برتر رسمی بریتانیا <em>خیلی سریع برای فکر کردن</em> است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (116, 'دانیل لوبتسکی', '<p>دانیل لوبتزکی یک کارآفرین اجتماعی است. او بنیانگذار PeaceWorks و KIND Healthy Snacks است و کار او در تجارت توسط مجمع جهانی اقتصاد، <em>BusinessWeek</em> و <em>TIME </em>مجله</p> شناخته شده است.', '2023-01-26 18:58:08.555201', '2023-01-26 18:58:08.555201', NULL, 'Daniel Lubetzky');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (117, 'مارک ساترفیلد', '<p>مارک ساترفیلد مدیر عامل و بنیانگذار Gentle Rain Marketing, Inc است. او به مدت 20 سال یک نیروی فعال در صنعت بازاریابی بوده است و به مشتریان در بیش از 75 صنعت مختلف در مورد چگونگی رشد مؤثر تجارت خود مشاوره می دهد.</p>', '2023-01-26 18:58:13.261172', '2023-01-26 18:58:13.261172', NULL, 'Mark Satterfield');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (118, 'توسط اخلاق', '<p>دکتر کارن مورلی یک روانشناس، مربی اجرایی و نویسنده است. او در کمک به رهبران برای تأثیرگذاری بر سازمان‌هایشان تخصص دارد. او همچنین به طور منظم در <em>CEOWORLD</em> <em>مجله</em></p> است.', '2023-01-26 18:58:18.335221', '2023-01-26 18:58:18.335221', NULL, 'Karen Morley');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (119, 'هنری مینتزبرگ', '<p>هنری مینتزبرگ نویسنده و محقق تجارت و مدیریت است. علاوه بر این، او استاد دانشگاه مک گیل در مونترال است و چندین کتاب در زمینه مدیریت و استراتژی نوشته است. </p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (120, 'چارلز داروین', '<p>چارلز داروین (۱۸۰۹–۱۸۸۲) زمین‌شناس و طبیعت‌شناس انگلیسی بود که بیشتر به‌خاطر مشارکت‌هایش در زیست‌شناسی تکاملی شهرت دارد. در سال 1853، انجمن سلطنتی مدال سلطنتی را به دلیل مطالعاتش در مورد سازندهای زمین‌شناسی و فسیل‌ها به او اهدا کرد. او در کلیسای وست مینستر، نزدیک قبر اسحاق نیوتن به خاک سپرده شده است.</p>', '2023-01-26 18:58:28.240743', '2023-01-26 18:58:28.240743', NULL, 'Charles Darwin');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (121, 'مارگارت چنی', '<p>مارگارت چنی از زندگی‌نامه‌نویسان برجسته نیکولا تسلا است. آثار او همچنین شامل <em>تسلا: استاد رعد و برق</em>، نوشته مشترک رابرت یوث، و بیوگرافی خواننده جاز میبل مرسر با عنوان <em>نیمه شب در میبل</em> است.</p>', '2023-01-26 18:58:33.884297', '2023-01-26 18:58:33.884297', NULL, 'Margaret Cheney');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (122, 'شان آچار', '<p>شان آکور یکی از حامیان برجسته روانشناسی مثبت در جهان است. او پس از دوازده سال تدریس و تحقیق در هاروارد، مدیر عامل شرکت Good Think Inc.، یک شرکت مشاوره مستقر در کمبریج شد و در آنجا به تحقیقات خود ادامه می دهد. او نویسنده دو کتاب پرفروش <em>نیویورک تایمز</em>، <em>مزیت خوشبختی</em> و <em>پتانسیل بزرگ</em> است. </p>', '2023-01-26 18:58:39.03109', '2023-01-26 18:58:39.03109', NULL, 'Shawn Achor');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (123, 'راشل هافستتر', '<p>ریچل هافستتر نویسنده مشتاق مواد غذایی است و در مجلاتی مانند <em>O، مجله اپرا</em> و <em>Reader''s Digest</em> همکاری می کند. او همچنین بنیانگذار Guesterly است، سرویسی که برای رویدادهای شخصی و شرکتی جزوه های who’s who ایجاد می کند.</p>', '2023-01-26 18:58:43.958116', '2023-01-26 18:58:43.958116', NULL, 'Rachel Hofstetter');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (124, 'گرانت کاردون', '<p>Grant Cardone یک کارآفرین چند میلیونی خودساخته است. او همچنین نویسنده کتاب پرفروش <em>قانون 10x</em> است.</p>', '2023-01-26 18:58:48.885456', '2023-01-26 18:58:48.885456', NULL, 'Grant Cardone');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (125, 'جان هیگل سوم', '<p>جان هیگل سوم یک استراتژیست تجاری مستقر در سیلیکون ولی و بنیانگذار شرکت Beyond Our Edge است. او قبلاً شریک Deloitte بود و همچنین با McKinsey & Company و Boston Consulting Group کار می کرد. هیگل چندین کتاب در مورد تجارت نوشته است، از جمله <em>قدرت کشش</em>.</p>', '2023-01-26 18:58:54.096169', '2023-01-26 18:58:54.096169', NULL, 'John Hagel III');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (126, 'الیوت بیسنو', '<p>الیوت بیسنو، جف روزنتال، جرمی شوارتز، و برت لو بنیانگذاران و مالکان گروه سامیت هستند، سازمانی که به پرورش جامعه جهانی از رهبران تجاری و فکری اختصاص دارد. آن‌ها همچنین از طریق Summit Action Fund، یک ابزار سرمایه‌گذاری که از استارت‌آپ‌های نوپایی مانند اوبر و واربی ​​پارکر در لحظات حساس توسعه پشتیبانی می‌کند، سرمایه‌گذاران فعالی هستند.</p>', '2023-01-26 18:58:58.892877', '2023-01-26 18:58:58.892877', NULL, 'Elliott Bisnow');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (127, 'برایان پی موران و مایکل لنینگتون', '<p>برایان موران یک کارآفرین، مربی و سخنران عمومی است. او سابقه ای در تجارت دارد و سمت های مدیریتی و اجرایی در شرکت هایی مانند PepsiCo و UPS داشته است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (129, 'برایان سی گونیا', '<p>برایان سی. گونیا دانشیار دانشکده بازرگانی جانز هاپکینز کری است. تحقیقات او بر این تمرکز دارد که چگونه افراد می توانند از طریق رفتار اخلاقی، مذاکره موثر و خواب کافی به مشاغل خود کمک کنند. کارهای او در مجلاتی از جمله <em>Academy of Management Journal</em> و <em>Journal of Applied Psychology</em> منتشر شده است. </p>', '2023-01-26 18:59:14.404234', '2023-01-26 18:59:14.404234', NULL, 'Brian C. Gunia');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (130, 'دکتر سی کی بری', '<p>دکتر سی کی بری یک مربی حرفه‌ای است که در دنیای شرکت‌ها کار می‌کرد تا زمانی که متوجه شد در حال تعقیب رویاهای دیگران است. اکنون، او به افراد کمک می کند تا اهداف حرفه ای خود را تعریف کرده و به آنها دست یابند.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (131, 'روهیت بهارگاوا', '<p>روهیت بهارگاوا موسس گروه بازاریابی تاثیرگذار و متخصص در ایجاد نفوذ برند است. او پنج کتاب پرفروش در این زمینه نوشته است.</p>', '2023-01-26 18:59:24.108344', '2023-01-26 18:59:24.108344', NULL, 'Rohit Bhargava');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (132, 'سونه گودیکسن', '<p>سونه گودیکسن دانشیار طراحی و مدیریت نوآوری در دانشکده طراحی Kolding در دانمارک و بنیانگذار پلتفرم انجمن Biz Games است. جیک اینلاو دارای مدرک کارشناسی ارشد در علوم تربیتی از دانشگاه آرهوس و طراح بازی و مشاور نوآوری است. آنها با هم Gamebridges را تأسیس کردند، شرکتی که بازی های تجاری ایجاد می کند تا به سازمان ها کمک کند تا نوآوری را تحریک کنند. </p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (133, 'جک کنفیلد', '<p>جک کانفیلد یک سخنران برنده جایزه و نویسنده پرفروش است که متخصص در استراتژی های عملکرد و توسعه شخصی است. علاوه بر مجموعه کتاب‌های <em>سوپ مرغ برای روح</em> و کسب‌وکار رسانه‌ای خودیاری با همین نام، کنفیلد نویسنده یا نویسنده بیش از 150 کتاب است که بیش از 100 میلیون نسخه فروخته است. به 47 زبان ترجمه شده است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (134, 'هوارد مارکس', '<p>هوارد مارکس رئیس و یکی از بنیانگذاران شرکت سرمایه گذاری مستقر در لس آنجلس، <em>Oaktree Capital Management</em> است.</p>', '2023-01-26 18:59:39.856073', '2023-01-26 18:59:39.856073', NULL, 'Howard Marks');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (135, 'لئون هسر', '<p>لئون هسر یک اقتصاددان کشاورزی و کشاورز سابق است که برنامه ایالات متحده برای افزایش تولید غذا در سراسر جهان را هماهنگ کرده است.</p>', '2023-01-26 18:59:44.971908', '2023-01-26 18:59:44.971908', NULL, 'Leon Hesser');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (136, 'کوری استمپر', '<p>کوری استمپر به عنوان فرهنگ نویس برای Merriam-Webster کار می کند. او همچنین یک وبلاگ نویس محبوب است که نوشته هایش در <em>گاردین</em> و<em>نیویورک تایمز</em> ظاهر شده است.</p>', '2023-01-26 18:59:50.290013', '2023-01-26 18:59:50.290013', NULL, 'Kory Stamper');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (137, 'هنری کلود', '<p>هنری کلود به عنوان یک روانشناس بالینی آموزش دیده و یک مشاور رهبری موفق است. او همچنین مدیران کسب و کار را در زمینه عملکرد و رهبری مربی می کند. Cloud جدا از اینکه یک سخنران انگیزشی مکرر است، یک نویسنده پرفروش است و <em>Boundaries</em>، <em>The One-Life Solution</em>and<em> Integrity</em> را منتشر کرده است.</p> >', '2023-01-26 18:59:56.346152', '2023-01-26 18:59:56.346152', NULL, 'Henry Cloud');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (138, 'آل ریس و جک تروت', '<p>Al Ries و Jack Trout دو استاد بازاریابی مشهور هستند که تعدادی کتاب بازاریابی از جمله <em>Marketing Warfare، Bottom-Up</em>و<em> Horse Sense</em> منتشر کرده‌اند. آنها برای شرکت‌های برتر آمریکایی مانند اپل، AT&T و Procter & Gamble و همچنین برای شرکت‌های با عملکرد بالا در آمریکای لاتین و آسیا مشاوره و کار کرده‌اند.</p>', '2023-01-26 19:00:02.53963', '2023-01-26 19:00:02.53963', NULL, 'Al Ries and Jack Trout');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (139, 'کاستاس لاپاویتزاس و دیگران', '<p>کاستاس لاپاویتزاس استاد دانشکده مطالعات شرقی و آفریقایی دانشگاه لندن است. او همچنین عضو اتاق فکر <em>پژوهش در پول و امور مالی</em> (<em>RMF</em>) است.</p>', '2023-01-26 19:00:08.752167', '2023-01-26 19:00:08.752167', NULL, 'Costas Lapavitsas and others');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (140, 'بیل مک درموت', '<p>بیل مک درموت، مدیر عامل SAP، یک رهبر جهانی در نرم افزار با شعبه در بیش از 130 کشور است. او در هیئت‌های نظارت شرکت‌های متعددی مانند Under Armor و ANSYS، و همچنین در هیئت مشاوران برنامه Knowledge is Power است.</p>', '2023-01-26 19:00:14.648051', '2023-01-26 19:00:14.648051', NULL, 'Bill McDermott');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (141, 'ایان لزلی', '<p>یان لزلی به‌عنوان تبلیغ‌کننده و همچنین نویسنده فرهنگ و سیاست در <em>The Guardian</em> و <em>The New Statesman</em> کار می‌کند. علاوه بر این، او نویسنده کتاب تحسین شده <em>دروغگویان متولد شده: چرا نمی توانیم بدون فریب زندگی کنیم</em> است.</p>', '2023-01-26 19:00:20.328345', '2023-01-26 19:00:20.328345', NULL, 'Ian Leslie');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (142, 'AmyK Hutchens', '<p>AmyK Hutchens یک سخنران برنده جایزه، نویسنده پرفروش و مشاور تجاری مشهور است. او که قبلاً مدیر یک شرکت میلیارد دلاری بود، اکنون به سایر مدیران شرکت‌ها و تأثیرگذاران در سراسر جهان توصیه می‌کند تا به آنها کمک کنند تا به طور مؤثرتری رهبری، همکاری و نوآوری کنند. او با کتاب <em>رازهایی که رهبران نگه می‌دارند</em> به نویسنده پرفروش آمازون تبدیل شد.</p>', '2023-01-26 19:00:26.263041', '2023-01-26 19:00:26.263041', NULL, 'AmyK Hutchens');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (143, 'کلی مک گونیگال', '<p> کلی مک گونیگال یک روانشناس در دانشگاه استنفورد و یک رهبر در زمینه "کمک علمی" است که تحقیقات در روانشناسی، علوم اعصاب و پزشکی را در موقعیت های زندگی روزمره به کار می برد. او نویسنده کتاب پرفروش بین المللی <em>غریزه قدرت اراده</em> است.</p>', '2023-01-26 19:00:31.617318', '2023-01-26 19:00:31.617318', NULL, 'Kelly McGonigal');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (144, 'ساندیپ دیال', '<p> Sandeep Dayal مدیر عامل Cerenti، یک شرکت مشاوره بازاریابی و استراتژی تجاری است. دیال 25 سال تجربه در بازاریابی و استراتژی برندسازی دارد و قبلا برای مک کینزی و بوز آلن همیلتون کار کرده است.</p>', '2023-01-26 19:00:37.415861', '2023-01-26 19:00:37.415861', NULL, 'Sandeep Dayal');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (145, 'ارین مایر', '<p>ارین مایر استاد مدرسه تجارت جهانی INSEAD است و در ارتباطات بین فرهنگی تخصص دارد. کارهای او در <em>Harvard Business Review</em>، <em>Singapore Business Times</em> و در <em>Forbes.com</em></p> منتشر شده است.', '2023-01-26 19:00:43.267055', '2023-01-26 19:00:43.267055', NULL, 'Erin Meyer');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (146, 'جان بلیکی و ایان دی', '<p>جان بلیکی و ایان دی هر دو تجربه زیادی در مربیگری رهبران هیئت مدیره در سراسر جهان دارند.</p>', '2023-01-26 19:00:48.085755', '2023-01-26 19:00:48.085755', NULL, 'John Blakey and Ian Day');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (147, 'اریک اولین رایت', '<p>اریک اولین رایت، جامعه شناس آمریکایی، یکی از برجسته ترین و تأثیرگذارترین متفکران مکتبی به نام مارکسیسم تحلیلی بود. او همراه با دیگر مارکسیست‌های تحلیلی در زمینه‌های تاریخ، اقتصاد و فلسفه، در پی پر کردن شکاف بین مارکسیسم کلاسیک و علوم اجتماعی مدرن بود. او بیش از 30 سال در دانشگاه ویسکانسین-مدیسون جامعه‌شناسی تدریس کرد و نویسنده 10 کتاب از جمله <em>تصویر آرمان‌شهرهای واقعی</em> و <em>کلاس درک</em> بود. رایت در سال 2019 درگذشت.</p>', '2023-01-26 19:00:53.802638', '2023-01-26 19:00:53.802638', NULL, 'Erik Olin Wright ');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (148, 'جینو ویکمن', '<p> جینو ویکمن که از 21 سالگی کارآفرینی بود، از تجربیات خود استفاده کرد و آن را برای ایجاد سیستم عامل کارآفرینی استخراج کرد و یک شرکت توسعه رهبری به نام EOS Worldwide را تأسیس کرد. او همچنین کتاب پرفروش <em>Get a Grip</em> را نوشت.</p>', '2023-01-26 19:00:59.222031', '2023-01-26 19:00:59.222031', NULL, 'Gino Wickman');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (149, 'جفری وست', '<p>جفری وست یک فیزیکدان نظری است که علایقش از سؤالات اساسی فیزیک تا زیست شناسی و پایداری جهانی را شامل می شود. او استاد برجسته موسسه سانتافه و استاد مدعو در دانشگاه آکسفورد، کالج امپریال و دانشگاه فنی نانیانگ در سنگاپور است. او در سال 2006 مجله <em>Time</em> در فهرست "100 تاثیرگذارترین افراد جهان" قرار گرفت.</p>', '2023-01-26 19:01:04.669078', '2023-01-26 19:01:04.669078', NULL, 'Geoffrey West');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (150, 'مایکل آ. سینگر', '<p>Michael A. Singer یک معلم معنوی است. دو کتاب قبلی او - <em>روح بی اختیار</em> و <em>آزمایش تسلیم</em> - پرفروش‌ترین کتاب‌های <em>نیویورک تایمز</em> هستند. در سال 1975، او معبد کیهان - یک مرکز مدیتیشن و یوگا برای افراد با هر ادیان و عقاید - در نزدیکی Gainesville، فلوریدا تاسیس کرد. او همچنین مدیرعامل موسس یک شرکت میلیارد دلاری و خالق یک بسته نرم افزاری مدیریت عملکرد پزشکی است.</p>', '2023-01-26 19:01:11.146234', '2023-01-26 19:01:11.146234', NULL, 'Michael A. Singer');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (151, 'بایرون کیت', '<p> نویسنده و سخنران بایرون کیتی در دهه 1980 شخصاً از یک دوره افسردگی شدید رنج می برد که چندین سال به طول انجامید. او بر اساس تجربه خودش، اکنون روش خود را برای غلبه بر افسردگی و ناراحتی با مردم در سراسر جهان به اشتراک می گذارد تا بتوانند زندگی رضایت بخشی داشته باشند.</p>', '2023-01-26 19:01:16.771478', '2023-01-26 19:01:16.771478', NULL, 'Byron Katie');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (152, 'اسماعیل به', '<p>اسماعیل بیه، کودک سرباز سابق، در سیرالئون به دنیا آمد و اکنون نویسنده و فعال حقوق بشر ساکن نیویورک است.</p>', '2023-01-26 19:01:22.708261', '2023-01-26 19:01:22.708261', NULL, 'Ishmael Beah');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (153, 'دیوید اوگیلوی', '<p>دیوید اوگیلوی که «پدر تبلیغات» در نظر گرفته می‌شود، توسط مشتریانش به عنوان یک نابغه و توسط کارکنانش یک رئیس شگفت‌انگیز تحسین می‌شود. اسکاتلندی آکسفورد را رها کرد و به عنوان سرآشپز در پاریس، فروشنده خانه به خانه در اسکاتلند و محقق در موسسه تحقیقات مخاطبان دکتر گالوپ مشغول به کار شد. او در نهایت یکی از معروف ترین آژانس های تبلیغاتی جهان را که امروزه با نام <em>Ogilvy & Mather</em> شناخته می شود، تأسیس کرد و 450 دفتر در سراسر جهان دارد.</p>', '2023-01-26 19:01:27.587555', '2023-01-26 19:01:27.587555', NULL, 'David Ogilvy');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (154, 'خیابان جف اسمارت و رندی', '<p>Geoff Smart شرکت مشاوره ghSMART را اداره می کند که به رهبران کسب و کار کمک می کند تأثیر خود را افزایش دهند و به اهداف خود برسند. کتاب دیگر او، <em>Leadocracy</em> نیز پرفروش‌ترین کتاب <em>نیویورک تایمز</em> بود.</p>', '2023-01-26 19:01:32.232821', '2023-01-26 19:01:32.232821', NULL, 'Geoff Smart and Randy Street');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (155, 'آنی گریس', '<p>آنی گریس به عنوان یک زن جوان یک بازاریاب داغ بود. او که جوانترین معاونت در شرکت چندملیتی خود بود، تا سن 35 سالگی در 28 کشور بازاریابی را رهبری می کرد. گریس همچنین هر شب حداقل یک بطری شراب می نوشیدند. امروز او یک نویسنده و مدافع است که به مردم کمک می کند وابستگی به الکل را شکست دهند و کنترل زندگی خود را دوباره به دست آورند.</p>', '2023-01-26 19:01:37.025218', '2023-01-26 19:01:37.025218', NULL, 'Annie Grace');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (156, 'نیکولای چن نیلسن و نیکولای تیلیش', '<p>نیکولای چن نیلسن یک رهبر فکری در زمینه توسعه شخصی، شریک مشارکتی در مک‌کینزی و شرکت، و فارغ‌التحصیل انجمن جهانی شیپرز مجمع جهانی اقتصاد است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (157, 'بروس اچ. لیپتون', '<p>بیولوژیست سلول های بنیادی بروس اچ. او که به‌خاطر کار خود در ترکیب علم و معنویت شهرت دارد، زیست‌شناسی سلولی را در دانشگاه ویسکانسین تدریس کرده و تحقیقات پیشرو در دانشکده پزشکی دانشگاه استنفورد انجام داده است. در سال 2009، او جایزه صلح گوی را دریافت کرد.</p>', '2023-01-26 19:01:47.053784', '2023-01-26 19:01:47.053784', NULL, 'Bruce H. Lipton');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (158, 'ریچی نورتون', '<p>ریچی نورتون یک کارآفرین و مشاور توسعه تجارت بین‌المللی است. علاوه بر این، او وبلاگ تحسین‌شده <em>Start Stuff را اداره می‌کند و در سال 2012 کتاب پرفروش <em>رزومه‌ها مرده‌اند و چه باید کرد درباره آن</em> منتشر کرد.</p>', '2023-01-26 19:01:52.533677', '2023-01-26 19:01:52.533677', NULL, 'Richie Norton');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (159, 'سوفیا آموروسو', '<p>سوفیا آموروسو بنیانگذار<em> NastyGal</em>، یک سایت تجارت الکترونیکی موفق برای پوشاک، کفش و لوازم جانبی زنانه است.</p>', '2023-01-26 19:01:57.706461', '2023-01-26 19:01:57.706461', NULL, 'Sophia Amoruso');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (160, 'مارسیا رینولدز', '<p>مارسیا رینولدز مربی و نویسنده رهبری است و دارای مدرک دکترا در روانشناسی سازمانی است.</p>', '2023-01-26 19:02:02.92489', '2023-01-26 19:02:02.92489', NULL, 'Marcia Reynolds');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (161, 'آدریان گوستیک', '<p>آدریان گوستیک و چستر التون نویسندگان پرفروش‌ترین کتاب‌های <em>وال استریت ژورنال </em> <em>اصل هویج</em>، <em>بهترین تیم برنده‌ها</em> و <em هستند. > All In. </em>کتاب‌های آن‌ها که به بیش از 30 زبان ترجمه شده‌اند، به 1.5 میلیون خواننده در سراسر جهان فروخته شده‌اند. گوستیک و التون همچنین بنیانگذاران The Culture Works هستند که به شرکت‌ها کمک می‌کند تا کارمندان برجسته را جذب و حفظ کنند.</p>', '2023-01-26 19:02:08.457585', '2023-01-26 19:02:08.457585', NULL, 'Adrian Gostick');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (162, 'کوین کری', '<p>کوین کری برنامه سیاست آموزشی را در سازمان تحقیقات غیرانتفاعی New America هدایت می‌کند. او همچنین در دانشگاه جانز هاپکینز، بالتیمور، سیاست آموزشی تدریس کرده است. او یکی از همکاران دائمی <em>نیویورک تایمز</em> است و برای نشریاتی مانند <em>Wired</em> و<em> Slate</em> نوشته است.</p>', '2023-01-26 19:02:13.042844', '2023-01-26 19:02:13.042844', NULL, 'Kevin Carey');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (163, 'پیتر مایرز و شان نیکس', '<p>پیتر مایرز موسس گروه مشاوره Stand & Deliver است. مایرز که یک بازیگر برنده جایزه است، همچنین در دانشگاه استنفورد، مؤسسه Esalen و مؤسسه بین‌المللی توسعه مدیریت در لوزان، سوئیس، کلاس‌های اجرا و رهبری تدریس می‌کند.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (164, 'لی گلدمن', '<p>لی گلدمن متخصص قلب و عروق مشهور و متخصص بهداشت عمومی، استاد مرکز پزشکی دانشگاه کلمبیا است. او بیشتر به دلیل ایجاد معیارهای گلدمن، ابزاری برای تعیین اینکه کدام بیماران قلبی باید اولویت درمانی داشته باشند، شناخته شده است.</p>', '2023-01-26 19:02:22.538998', '2023-01-26 19:02:22.538998', NULL, 'Lee Goldman');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (165, 'هلن تاپر و سارا الیس', '<p>هلن تاپر یکی از بنیانگذاران و مدیر عامل شرکت توسعه شغلی برنده جایزه Amazing If است. او قبلا در مایکروسافت، ویرجین و بی پی کار می کرد. <em>حرفه اسکوئیگلی</em> اولین کتاب او است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (166, 'ویلیام مک اسکیل', '<p>ویلیام مک اسکیل دانشیار فلسفه در دانشگاه آکسفورد و همچنین بنیانگذار مؤسسات خیریه Giving What We Can و 80,000 است. سازمان های او در <em>نیویورک تایمز</em>، <em>وال استریت ژورنال</em>، در NPR، TED و بسیاری از رسانه های دیگر به نمایش درآمده اند.</p>', '2023-01-26 19:02:31.706467', '2023-01-26 19:02:31.706467', NULL, 'William MacAskill');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (167, 'ریک وارن', '<p>ریک وارن در هاروارد، کمبریج و آکسفورد سخنرانی کرده است. او بنیانگذار P.E.A.C.E جهانی است. طرحی که از فقرا حمایت می کند و آموزش و همچنین بسیاری از منابع دیگر را در 196 کشور فراهم می کند.</p>', '2023-01-26 19:02:36.725213', '2023-01-26 19:02:36.725213', NULL, 'Rick Warren');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (168, 'دیل کارنگی', '<p>دیل کارنگی نویسنده، مربی شرکتی و توسعه دهنده دوره های خودسازی بود. علیرغم اینکه در یک مزرعه در میسوری در فقر به دنیا آمد، او یکی از پرفروش ترین نویسندگان خودیاری در تمام دوران است و به خاطر آثار کلاسیک ماندگاری مانند <em>چگونه دوستانی پیدا کنیم و مردم را تحت تاثیر قرار دهیم</em> و <em>چگونه شناخته شده است. برای دست کشیدن از نگرانی و شروع زندگی</em>. این عناوین هنوز هم امروزه، ده‌ها سال پس از انتشار اولیه، بسیار محبوب هستند.</p>', '2023-01-26 19:02:42.197438', '2023-01-26 19:02:42.197438', NULL, 'Dale Carnegie');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (169, 'هوارد اس. فریدمن و لزلی آر. مارتین', '<p>هوارد اس. فریدمن، دکترا، یک استاد روانشناسی در دانشگاه کالیفرنیا است که کارش در زمینه سلامت و طول عمر جوایزی را از انجمن علوم روانشناسی و انجمن روانشناسی آمریکا برای او به ارمغان آورده است. از دیگر کتاب های او می توان به <em>روانشناسی سلامت</em> و <em>شخصیت خود درمانی</em> اشاره کرد.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (170, 'اندرو سوبل و جرولد هات', '<p>اندرو سوبل یکی از برجسته ترین متخصصان جهان در زمینه روابط تجاری و ایجاد وفاداری مشتری است. او همچنین یک سخنران اصلی مورد تقاضا با چندین دهه تجربه به عنوان مشاور مدیران ارشد و همچنین ارائه آموزش های اجرایی و مربیگری است. کتاب های قبلی او عبارتند از <em>سوالات قدرت</em>(2012)، <em>همه برای یک</em> (2009) و <em>ساخت باران</em>(2003).</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (171, 'و صفحه', '<p>KEN PAGE، LCSW، روان‌درمانگر مشهور و صدای پیشرو امید و خرد برای همه کسانی است که به دنبال یافتن و پرورش عشق سالم و پایدار هستند. او میزبان <em><a href="http://deeperdatingpodcast.com/" rel="nofollow">پادکست دوستیابی عمیق</a></em>، یکی از بنیانگذاران <a href= است. "http://deeperdating.com/" rel="nofollow">Deeperdating.com</a>; و نویسنده کتاب آشنایی عمیق تر: چگونه بازی های اغواگری را کنار بگذاریم و قدرت صمیمیت را کشف کنیم.</p>', '2023-01-26 19:02:56.737843', '2023-01-26 19:02:56.737843', NULL, 'Ken Page');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (172, 'ولفگانگ شفر و جی پی کوهلواین', '<p>ولفگانگ شفر مدیر استراتژی آژانس تبلیغاتی SelectNY است. او سال ها تجربه در توسعه استراتژی های برند جهانی برای بازارهای اروپا، آمریکا و آسیا دارد. او همچنین بنیانگذار Ueber-Brands Consulting است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (173, 'آری مایزل', '<p>آری مایزل رهبر و نویسنده شرکت آمریکایی است. او پس از تحصیل در رشته بازرگانی در دانشگاه پنسیلوانیا، شرکت Less Doing خود را تأسیس کرد که در کمک به سایر افراد و شرکت‌ها برای خودکارسازی و واگذاری کارشان تخصص دارد تا بتوانند کمتر کار کنند، اما هوشمندانه‌تر کار کنند.</p>', '2023-01-26 19:03:13.458282', '2023-01-26 19:03:13.458282', NULL, 'Ari Meisel');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (174, 'دیوید آهرن', '<p>دیوید آهرن، فرانک فورد و دیوید ویلک شرکت Four Day Weekend را بنیانگذاری کردند و کارآفرینان ساکن در دانشگاه مسیحی تگزاس هستند. به عنوان رهبران تحول فرهنگ و توانمندسازی تیم، آنها هزاران نمایش را برای مخاطبان در سراسر جهان اجرا کرده اند - از جمله کهنه سربازان ارتش، متخصصان شرکت، معلمان، دانش آموزان و دو رئیس جمهور ایالات متحده.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (175, 'اسکات گربر', '<p> اسکات گربر یک سخنران و مدیر عامل مورد تقاضا است. او همچنین یکی از بنیانگذاران شرکت جامعه است، سازمانی که انجمن های عضویت حرفه ای را برای برندهای جهانی پرورش می دهد. او همچنین یک بوت استرپر متخصص، خودساخته و نویسنده است. جدیدترین کتاب او در سال 2018 <em>Superconnector: Stop Networking and Start Building Business Relationships that Matter</em></p> است.
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (176, 'ایولین تریبول و الیزه رش', '<p>اولین تریبول یک متخصص تغذیه و نویسنده برنده جوایز مستقر در کالیفرنیا است، جایی که او یک مرکز مشاوره غذایی را اداره می کند. او قبلا نماینده انجمن رژیم غذایی آمریکا بود و کارشناس تغذیه خانگی در برنامه چت ABC <em>صبح بخیر آمریکا</em> بود. </p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (177, 'اریک توماس', '<p>اریک توماس یکی از موفق ترین سخنرانان انگیزشی تمام دوران است. او با افراد و تیم‌های شرکت‌های NBA، NFL، NCAA و Fortune 500، و همچنین با بچه‌های محروم تلاش می‌کند تا راه خود را در مدرسه پیدا کنند، کار می‌کند. او چندین کتاب از جمله <em>راز موفقیت</em>، <em>عظمت بر توست</em>، و <em>متوسط ​​مهارت فوق‌العاده اراده</em> نوشته است.</p>', '2023-01-26 19:03:36.634572', '2023-01-26 19:03:36.634572', NULL, 'Eric Thomas');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (178, 'ایرین کارمون و شانا کنیژنیک', '<p>ایرین کارمون یک روزنامه نگار و مفسر اسرائیلی-آمریکایی است. او یکی از همکاران سی‌ان‌ان، خبرنگار ارشد <em>مجله نیویورک، </em>و قبلاً گزارشگر ملی در MSNBC بود.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (179, 'ویکی رابین و جو دومینگز', '<p>ویکی رابین نویسنده و سخنران آمریکایی است. پس از حضور رابین در نمایش اپرا وینفری، کتاب او <em>پول یا زندگی شما</em> بلافاصله به پرفروش ترین کتاب تبدیل شد. بیش از یک میلیون نسخه فروخته است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (180, 'کن اولتا', '<p>از سال 1993، کن اولتا سالنامه ارتباطات را برای <em>نیویورکر</em> نوشته است. او همچنین نویسنده 12 کتاب است، از جمله کتاب پرفروش <em>نیویورک تایمز</em> <em>Googled: The End of the World as We Know</em>.</p>', '2023-01-26 19:03:51.19566', '2023-01-26 19:03:51.19566', NULL, 'Ken Auletta');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (181, 'مارک الهی', '<p>مارک دیواین کار حرفه ای خود را به عنوان یک حسابدار عمومی آغاز کرد، بعداً آموزش نیروی دریایی خود را به پایان رساند و با درجه فرماندهی در سال 2011 بازنشسته شد. </p>', '2023-01-26 19:03:55.596778', '2023-01-26 19:03:55.596778', NULL, 'Mark Divine');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (182, 'گرگ مک کیون', '<p>Greg McKeown یک سخنران، نویسنده، استراتژیست و میزبان پادکست <em>What''s Essential</em> است. او توسط شرکت هایی مانند <em>Fast Company</em>، <em>نیویورک تایمز</em> و <em>Fortune</em> معرفی شده است و برای <em>Harvard Business Review< /em>. کتاب 2014 مک کئون، <em>اساسیالیسم</em>، پرفروش‌ترین کتاب <em>نیویورک تایمز</em> است، و او همچنین یک رهبر جوان جهانی برای مجمع جهانی اقتصاد است.</p>', '2023-01-26 19:04:00.394189', '2023-01-26 19:04:00.394189', NULL, 'Greg McKeown');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (183, 'جاش ترنر', '<p>جاش ترنر یک متخصص برجسته لینکدین و بنیانگذار LinkedSelling، یک شرکت بازاریابی B2B است. شرکت او همچنین LinkedUniversity.com را اجرا می کند که آموزش آنلاین بازاریابی را از طریق LinkedIn ارائه می دهد.</p>', '2023-01-26 19:04:05.1942', '2023-01-26 19:04:05.1942', NULL, 'Josh Turner');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (184, 'باب بورگ و جان دیوید مان', '<p>Bob Burg نویسنده <em>Endless Referrals: Network Contacts Everyday Your To Sales است. </em>او همچنین در هیئت مدیره نجات حیوانات خانگی فلوریدا، Furry Friends است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (185, 'رابرت پیرسیگ', '<p>رابرت پیرسیگ نویسنده و فیلسوف آمریکایی است که توسط روزنامه بریتانیایی <em>گاردین</em> "احتمالاً پرخواننده ترین فیلسوف زنده" خوانده می شود. کار مهم او، <em>ذن و هنر تعمیر و نگهداری موتور سیکلت</em>، عمدتاً بر اساس رویدادهای واقعی در زندگی پیرسیگ است.</p>', '2023-01-26 19:04:15.362296', '2023-01-26 19:04:15.362296', NULL, 'Robert Pirsig');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (186, 'دیوید کوهن و برد فلد', '<p>دیوید کوهن موسس Techstars است و چندین شرکت دیگر را با موفقیت راه اندازی کرده است. اکنون او عمدتاً در استارت آپ های اینترنتی سرمایه گذاری می کند. برد فلد برای شرکت سرمایه گذاری خطرپذیر Foundry Group کار می کند و بیش از بیست و پنج سال است که به عنوان سرمایه گذار و کارآفرین فعال بوده است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (187, 'میلتون فریدمن', '<p>میلتون فریدمن در سال 1976 برنده جایزه نوبل اقتصاد شد. او دارای مدرک دکترا از دانشگاه کلمبیا است و در دهه 1980 مشاور اقتصادی رونالد ریگان بود. او بیش از 11 کتاب در مورد اقتصاد و آزادی فردی نوشته است.</p>', '2023-01-26 19:04:24.620984', '2023-01-26 19:04:24.620984', NULL, 'Milton Friedman');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (188, 'کاری نادو و اسلون بارنت', '<p>دکتر Kari Nadeau مدیر مرکز Sean N. Parker برای تحقیقات آلرژی و آسم در دانشگاه استنفورد است، جایی که او استاد بنیاد Naddisy در زمینه آلرژی غذایی، ایمونولوژی و آسم کودکان است. او همچنین عضو موسسه تحقیقات سلامت مادر و کودک استنفورد و موسسه ایمنی، پیوند و عفونت استنفورد است. او دارای مدرک دکترا و دکترا از دانشکده پزشکی هاروارد است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (189, 'چینگ ال آی', '<p>دکتر کینگ لی یک ایمونولوژیست و متخصص برجسته در پزشکی جنگل است. او یکی از اعضای موسس انجمن طب جنگلی ژاپن و معاون و دبیر کل انجمن بین المللی طبیعت و طب جنگلی است. دکتر لی در دانشکده پزشکی نیپون در توکیو، ژاپن تدریس می‌کند و عضو مدعو دانشگاه استنفورد بوده است.</p>', '2023-01-26 19:04:37.538456', '2023-01-26 19:04:37.538456', NULL, 'Qing Li');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (190, 'جو اونگهما', '<p>جو اونگهما روانشناس و متخصص در مورد چگونگی و چرایی تصمیم گیری افراد است. توصیه های او در ایالات متحده، استرالیا و اروپا مورد توجه قرار می گیرد، جایی که او به تعدادی از شرکت های بزرگ کمک کرده است تا کارکنان راضی بیشتری پیدا کنند.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (191, 'مایکل پولن', '<p>مایکل پولان نویسنده و استاد روزنامه نگاری در دانشگاه کالیفرنیا برکلی است. از دیگر کتاب‌های او می‌توان به <em>در دفاع از غذا، قوانین غذا</em>و<em> معضل همه‌چیزخوار، </em> که توسط <em>نیویورک تایمز به عنوان یکی از ده کتاب برتر سال 2006 معرفی شد، اشاره کرد. </em></p>', '2023-01-26 19:04:53.944279', '2023-01-26 19:04:53.944279', NULL, 'Michael Pollan');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (192, 'لوئیز هی', '<p>لویز هی نویسنده، سخنران و ناشر انگیزشی بود. هِی که به هر دو جنبش فکری جدید و علوم دینی مرتبط بود، با ماهاریشی ماهش یوگی نیز مطالعه کرد. پس از تشخیص سرطان دهانه رحم، او انگیزه یافت تا علم ذهن و پاکسازی معنوی را دنبال کند و تبدیل به یک نویسنده پرفروش و استاد انگیزشی شد.</p>', '2023-01-26 19:04:59.467253', '2023-01-26 19:04:59.467253', NULL, 'Louise Hay');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (193, 'کارن احمان', '<p>کارن ایمن نویسنده 13 کتاب الهام بخش است، از جمله کتاب پرفروش <em>نیویورک تایمز</em> <em>خفه نگه دار: چه باید گفت، چگونه آن را بگوییم و چه زمانی اصلاً چیزی نگوییم</em> em>. او سخنران Proverbs 31 Ministries و نویسنده برنامه محبوب مطالعه کتاب مقدس First 5 است.</p>', '2023-01-26 19:05:04.488123', '2023-01-26 19:05:04.488123', NULL, 'Karen Ehman');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (194, 'گرچن روبین', '<p>گرچن روبین نویسنده کتاب پرفروش <em>نیویورک تایمز</em> <em>پروژه شادی</em> است، کتابی که به بیش از 30 زبان ترجمه شده و جنبشی از مردم را برانگیخته است که می خواهند شادتر زندگی کنید.</p>', '2023-01-26 19:05:09.91286', '2023-01-26 19:05:09.91286', NULL, 'Gretchen Rubin');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (195, 'برایان کاپلان', '<p>برایان کاپلان استاد اقتصاد در دانشگاه جورج میسون و پدر سه فرزند است. <em>The</em> <em>New</em> <em>York</em> <em>Times</em> اولین کتاب خود را <em>The</em> <em>افسانه< /em> <em>از</em> <em></em> <em>رای دهندگان منطقی</em> <em>رای دهنده</em> "بهترین کتاب سیاسی سال".</p>', '2023-01-26 19:05:14.764488', '2023-01-26 19:05:14.764488', NULL, 'Bryan Caplan');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (196, 'استیون لینچ', '<p> استیون لینچ، علاوه بر توسعه‌دهنده استراتژی‌های تجاری موفق، افسر پلیس، بدنساز، دی‌جی و مدیر فروش داروسازی سابق است، فقط به چند مورد از حرفه‌های گذشته‌اش اشاره می‌کنیم. او همچنین یکی از بنیانگذاران RESULTS.com است، پلتفرمی که نرم افزار و خدمات مشاوره ای را برای کمک به رونق کسب و کار ارائه می دهد.</p>', '2023-01-26 19:05:22.512387', '2023-01-26 19:05:22.512387', NULL, 'Stephen Lynch');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (197, 'گری واینرچوک', '<p>گری واینرچوک یک نویسنده پرفروش و کارآفرین داستان نویس <em>نیویورک تایمز</em> است. او همچنین آژانس مشاوره دیجیتال خود به نام VaynerMedia را اداره می کند که به شرکت های Fortune 500 کمک می کند تا استراتژی های موثر رسانه های اجتماعی را توسعه دهند. او در <em>BusinessWeek</em> به عنوان یکی از 20 نفر برتر انتخاب شد که هر کارآفرینی باید دنبال کند.', '2023-01-26 19:05:27.210269', '2023-01-26 19:05:27.210269', NULL, 'Gary Vaynerchuk');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (198, 'بروس دیزلی', '<p>بروس دیزلی از سال 2012 تا 2020 معاون توییتر در اروپا، خاورمیانه و آفریقا بود. نوشته های او قبلاً در نشریاتی مانند <em>Harvard Business Review، </em><em>وال استریت ژورنال منتشر شده است. ، </em><em>واشنگتن پست، وایرد، </em>و <em> گاردین</em>. <em>Eat Sleep Work Repeat </em>اولین کتاب او است و همچنین پادکستی به همین نام اجرا می کند.</p>', '2023-01-26 19:05:35.542842', '2023-01-26 19:05:35.542842', NULL, 'Bruce Daisley');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (199, 'اکهارت توله', '<p> اکهارت توله یکی از مشهورترین و تأثیرگذارترین معلمان معنوی جهان است. کتاب پرفروش قبلی او، <em>قدرت اکنون </em> (همچنین در یک چشمک موجود است)، به بیش از 33 زبان ترجمه شد. </p>', '2023-01-26 19:05:41.145502', '2023-01-26 19:05:41.145502', NULL, 'Eckhart Tolle');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (200, 'سینتیا بارنت', '<p> سینتیا بارنت یک روزنامه نگار محیط زیست است که در مورد آب از رودخانه Suwannee تا سنگاپور گزارش داده است. او نویسنده <em>سراب</em> است که برنده مدال طلا بهترین عنوان غیرداستانی در جوایز کتاب فلوریدا شد و <em>انقلاب آبی</em> که به عنوان یکی از ده کتاب برتر علمی معرفی شد. در سال 2011 توسط <em>Boston Globe</em>.</p>', '2023-01-26 19:05:46.887548', '2023-01-26 19:05:46.887548', NULL, 'Cynthia Barnett');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (201, 'رابرت بولتون', '<p>رابرت بولتون، دکترا، بنیانگذار Ridge Training، شرکتی است که در بهبود روابط و عملکرد در کسب و کار، مراقبت های بهداشتی، و آموزش تخصص دارد.</p>', '2023-01-26 19:05:52.156162', '2023-01-26 19:05:52.156162', NULL, 'Robert Bolton');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (202, 'کریس اندرسون', '<p>کریس اندرسون یک کارآفرین و یک روزنامه نگار است. او از سال 2001 متصدی کنفرانس های TED بوده است. فرزند مبلغانی که در پاکستان کار می کردند، مدرک خود را از دانشگاه آکسفورد دریافت کرد، برای روزنامه های مختلف کار کرد و بیش از 100 مجله و وب سایت موفق راه اندازی کرد.</p>', '2023-01-26 19:05:57.429923', '2023-01-26 19:05:57.429923', NULL, 'Chris Anderson');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (203, 'دونالد میلر', '<p>دونالد میلر مدیر عامل آژانس بازاریابی StoryBrand و نویسنده پرفروش <em>نیویورک تایمز</em> است که کتاب‌هایش شامل <em>آبی مانند جاز</em>و <em>یک میلیون مایل در یک هزار سال.</em></p>', '2023-01-26 19:06:03.013568', '2023-01-26 19:06:03.013568', NULL, 'Donald Miller');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (204, 'مالکوم گلدول', '<p>مالکوم گلدول روزنامه‌نگار و نویسنده‌ای است که آثارش بینش‌های غیرمستقیم روان‌شناسی و جامعه‌شناسی را نشان می‌دهد. او با افراد مختلفی از افراد ناشناخته تا همه جا حاضر مصاحبه می‌کند و این حکایات شخصی را در روزنامه‌نگاری قابل دسترس، پرفروش‌ترین گفتگوهای غیرداستانی و انگیزشی برای کسب‌وکارها می‌پیوندد.</p>', '2023-01-26 19:06:07.956007', '2023-01-26 19:06:07.956007', NULL, 'Malcolm Gladwell');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (205, 'جف گوینز', '<p>Jeff Goins یک موسیقیدان، نویسنده و وبلاگ نویس است که برای بیش از 100 مجله، نشریه و وبلاگ نوشته است.</p>', '2023-01-26 19:06:13.097876', '2023-01-26 19:06:13.097876', NULL, 'Jeff Goins');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (293, 'دیوید آتنبرو', '<p>دیوید آتنبرو بیش از 60 سال است که برنامه های تاریخ طبیعی می سازد. او به سرتاسر جهان سفر کرده است و کمیاب‌ترین و شگفت‌انگیزترین گونه‌های جانوری و گیاهی را برای مخاطبان جهانی به ارمغان آورده است.</p>', '2023-01-26 19:14:17.061334', '2023-01-26 19:14:17.061334', NULL, 'David Attenborough');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (206, 'مایک سیلسکی', '<p>مایک سیلسکی از سال 2013 در <em>The</em> <em>Philadelphia Inquirer</em> ستون نویس ورزشی بوده است و توسط Associated Press Sports Editors به ​​عنوان برترین ستون نویس ورزشی در آمریکا معرفی شده است. او نویسنده <em>پژواک های محو شده: داستان واقعی رقابت و برادری از زمین فوتبال تا زمین های افتخار</em>و نویسنده همکار <em>چگونه مانند جکی رابینسون باشیم: درس های زندگی از بزرگترین بیسبال است. قهرمان</em>.</p>', '2023-01-26 19:06:17.444256', '2023-01-26 19:06:17.444256', NULL, 'Mike Sielski');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (207, 'کارسون تیت', '<p>کارسون تیت مربی، مشاور و بنیانگذار <em>Working Simply</em> است، یک مشاور مدیریتی که با مشتریان برجسته ای مانند کوکاکولا و جان دیر کار کرده است. ایده‌های تیت که متخصص بهره‌وری در محل کار است، در <em>نیویورک تایمز</em>، <em>Fast Company</em> و <em>Forbes</em> ارائه شده است.</p>', '2023-01-26 19:06:22.035451', '2023-01-26 19:06:22.035451', NULL, 'Carson Tate');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (208, 'مارتین لیندستروم', '<p>مارتین لیندستروم یک متخصص بازاریابی و برندسازی مشهور جهان است و مشاور شرکت‌هایی مانند والت دیزنی، پپسی و ردبول بوده است. مطالعه ای روی 30000 بازاریاب، او را به عنوان کارشناس شماره یک برندسازی در سال 2015 معرفی کرد، در حالی که <em>Thinkers 50</em> او را هجدهمین متفکر برتر تجاری جهان معرفی کرد.</p>', '2023-01-26 19:06:26.606953', '2023-01-26 19:06:26.606953', NULL, 'Martin Lindstrom');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (209, 'بی.جی مندلسون', '<p>بی.جی. مندلسون نویسنده، کمدین و مدافع آگاهی از سرطان سینه است. او همچنین در CNN، Forbes و Huffington Post همکاری داشته است.</p>', '2023-01-26 19:06:30.795669', '2023-01-26 19:06:30.795669', NULL, 'B.J. Mendelson');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (210, 'مایکل دی واتکینز', '<p>مایکل واتکینز استاد رهبری در مدرسه تجارت IMD است. او همچنین یک نویسنده بین المللی شناخته شده در موضوع توسعه رهبری است. از دیگر کتاب‌های او می‌توان به <em>حرکت بعدی شما</em> و <em>سورپرایزهای قابل پیش‌بینی</em> اشاره کرد.</p>', '2023-01-26 19:06:35.127423', '2023-01-26 19:06:35.127423', NULL, 'Michael D. Watkins');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (211, 'باستر بنسون', '<p>باستر بنسون بیش از 20 سال تجربه به‌عنوان رهبر محصولات در برخی از معتبرترین شرکت‌های سیلیکون ولی دارد. او از نزدیک دیده است که چگونه اختلافات غیرمولد می تواند پروژه ها را از مسیر خارج کند و چگونه اختلافات سازنده می تواند عملکرد را افزایش دهد. در حال حاضر باستر در آموزش برخی از شرکت های پیشرو جهان که چگونه به طور سازنده بحث کنند، تخصص دارد. او با آمازون، اسلک و توییتر و دیگران همکاری داشته است.</p>', '2023-01-26 19:06:39.855528', '2023-01-26 19:06:39.855528', NULL, 'Buster Benson');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (212, 'M. Tamra Chandler و Laura Dowling Grealish', '<p>طمرا چندلر، مدیر عامل و بنیانگذار PeopleFirm، یکی از بهترین مشاوران مدیریت آمریکا در سال 2018، طبق مجله <em>Forbes</em> است. PeopleFirm با مشتریانی از جمله T-Mobile، Nordstrom، Nike و بنیاد بیل و ملیندا گیتس برای بهبود و بازنگری فرهنگ داخلی، رهبری و مدیریت عملکرد کار می کند. لورا داولینگ گریلیش مشاور ارشد این شرکت است. </p>', '2023-01-26 19:06:44.232498', '2023-01-26 19:06:44.232498', NULL, 'M. Tamra Chandler and Laura Dowling Grealish');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (213, 'سوزوکی فصلی', '<p>شونریو سوزوکی یک راهب ژاپنی بود که در سال 1954 به ایالات متحده آمد. او علاوه بر تأسیس مرکز ذن سانفرانسیسکو، به دانش‌آموزان ذن بی‌شماری آموزش داد و چندین کتاب در این زمینه نوشت، از جمله <em>جریان‌های شاخه‌ای در تاریکی</em>.</p>', '2023-01-26 19:06:49.237525', '2023-01-26 19:06:49.237525', NULL, 'Shunryu Suzuki');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (214, 'کارل پیلمر', '<p>کارل پیلمر یک جامعه شناس و سالمند شناس و پروفسور هیزل ای رید در توسعه انسانی در دانشگاه کرنل است. او همچنین مدیر پروژه میراث کرنل است. انتشارات قبلی او شامل کتاب بسیار تحسین شده <em>30 درس برای زندگی</em> است.</p>', '2023-01-26 19:06:54.189217', '2023-01-26 19:06:54.189217', NULL, 'Karl Pillemer');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (215, 'کارل پوپر', '<p>کارل پوپر (94-1902) یکی از فیلسوفان اصلی قرن بیستم بود که به طور خاص بر روی فلسفه علم کار می کرد. او کار خود را در وین، زادگاهش آغاز کرد و در دهه 1930 ابتدا به نیوزلند و سپس به انگلستان مهاجرت کرد. و همچنین <em>منطق اکتشاف علمی</em>، که او در زمان اقامت در وین نوشت - اگرچه بعداً چندین بار در آن تجدید نظر کرد - یکی دیگر از آثار معروف او <em>جامعه باز و دشمنان آن است. </em>.</p>', '2023-01-26 19:06:59.10168', '2023-01-26 19:06:59.10168', NULL, 'Karl Popper');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (216, 'خانم هینچ', '<p>سوفیا هینچلیف – با نام مستعار خانم هینچ – زنی 29 ساله است که علاقه زیادی به نظافت دارد. او پس از ازدواج در سال 2018، یک حساب کاربری در اینستاگرام به زندگی خانگی و نظافت راه اندازی کرد که به موفقیتی فوری تبدیل شد و تنها در سه ماه بیش از یک میلیون دنبال کننده را جذب کرد. <em>Hinch Yourself Happy</em> اولین کتاب او است. </p>', '2023-01-26 19:07:04.235331', '2023-01-26 19:07:04.235331', NULL, 'Mrs. Hinch');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (217, 'مارتین بلیزر', '<p>دکتر مارتین بلسر استاد میکروبیولوژی و مدیر برنامه میکروبیوم انسانی دانشگاه نیویورک است. کار او عمدتاً بر روی باکتری‌هایی مانند <em>Helicobacter pylori</em>، <em>Campylobacter</em> و <em>Salmonella Bacillus anthracis</em> تمرکز دارد. اخیراً، تحقیقات او بر روی میکرو</p> انسان متمرکز شده است', '2023-01-26 19:07:09.190016', '2023-01-26 19:07:09.190016', NULL, 'Martin Blaser');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (218, 'اشلی ونس', '<p>اشلی ونس یکی از برجسته ترین نویسندگان فناوری امروز است. او که یک مقاله نویس تجاری آمریکایی است، برای <em>نیویورک تایمز</em> و <em>Bloomberg Businessweek</em> نوشته است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (219, 'گری جان بیشاپ', '<p>گری جان بیشاپ یک سخنران و نویسنده انگیزشی است. از دیگر کتاب‌های او می‌توان به <em>Unf*ck Yourself</em> و <em>Wise as F*ck</em> اشاره کرد. </p>', '2023-01-26 19:07:19.435289', '2023-01-26 19:07:19.435289', NULL, 'Gary John Bishop');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (220, 'الین ولتروت', '<p>Elaine Welteroth روزنامه نگار، نویسنده و ویراستار است. در سال 2016، در سن 29 سالگی، او به سمت سردبیری <em>Teen Vogue</em> رسید و او را به جوان‌ترین سردبیر در تاریخ ناشر Condé Nast و دومین زنی تبدیل کرد که چنین موقعیتی را در آن کسب کرد. موسسه، نهاد. قبل از ارتقای تاریخی خود در <em>Teen Vogue</em>، او سمت های سردبیری در <em>Ebony</em> و <em>Glamour</em> داشت. <em>بیش از کافی</em>اولین کتاب او است.</p>', '2023-01-26 19:07:24.856752', '2023-01-26 19:07:24.856752', NULL, 'Elaine Welteroth');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (221, 'نیکلاس اس. بارنت', '<p>نیکلاس اس. بارنت بیش از 30 سال تجربه به عنوان مشاور تجاری و مدیر شرکت دارد. او در حال حاضر مدیر اجرایی InSync Surveys، یکی از مشاوران مدیریت برتر استرالیا است.</p>', '2023-01-26 19:07:30.567202', '2023-01-26 19:07:30.567202', NULL, 'Nicholas S. Barnett');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (222, 'تانیا لونا و لی آن رنینگر', '<p>تانیا لونا و لی آن رنینگر محققان و بنیانگذاران LifeLabs Learning هستند، سازمانی که رهبران و تیم‌ها را آموزش می‌دهد. لونا برای انتشاراتی از جمله <em>روانشناسی امروز</em> و <em>Harvard Business Review</em> می نویسد. نویسندگان همچنین <em>سورپرایز</em></p> را نوشتند', '2023-01-26 19:07:35.712826', '2023-01-26 19:07:35.712826', NULL, 'Tania Luna and LeeAnn Renninger');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (223, 'دانیل گلمن', '<p>دانیل گولمن روانشناس و روزنامه‌نگار علمی سابق برای <em>نیویورک تایمز</em> و نویسنده 13 کتاب از جمله کتاب پرفروش <em>هوش عاطفی</em> است. او همچنین اغلب برای متخصصان و گروه های دانشجویی سخنرانی می کند.</p>', '2023-01-26 19:07:40.787848', '2023-01-26 19:07:40.787848', NULL, 'Daniel Goleman');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (224, 'مارشال گلداسمیت', '<p>مارشال گلداسمیت یک مربی رهبری و نویسنده پرفروش است. او عضو تالار مشاهیر 50 متفکران است و به مدت هشت سال متوالی در رتبه بندی ده متفکر برتر کسب و کار قرار گرفته است. 41 کتاب او که بیش از 2.5 میلیون نسخه فروخته و به 32 زبان ترجمه شده‌اند، شامل عناوین تأثیرگذاری مانند <em>محرک‌ها </em>و <em>چیزی که شما را به اینجا رساند، شما را به آنجا نخواهد برد</em> است. </p>', '2023-01-26 19:07:42.489961', '2023-01-26 19:07:42.489961', NULL, 'Marshall Goldsmith');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (225, 'دیوید ایگلمن', '<p> دیوید ایگلمن استاد علوم اعصاب در کالج پزشکی بیلور، در هیوستون، تگزاس است. تحقیقات او توسط مجلات معتبر معتبر از جمله <em>Science </em>و <em>Nature</em> منتشر شده است. او همچنین نویسنده کتاب علمی <em>Incognito: The Secret Lives of the Brain</em> و رمان <em>Sum: Forty Tales from the Afterlives</em> است. او <em>مغز</em>، مجموعه تلویزیونی بی بی سی را نوشت و ارائه کرد که به عنوان قطعه همراه این کتاب عمل می کند.</p>', '2023-01-26 19:07:47.458069', '2023-01-26 19:07:47.458069', NULL, 'David Eagleman');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (226, 'رایان هاوک', '<p>رایان هاوک یک سخنران کلیدی، میزبان پادکست <em>Leader Leader Show</em> و رئیس شرکت حسابداری Brixey & Meyer''s Leadership Advisor است. او همچنین با تیم‌ها و بازیکنان NFL، NBA و NCAA کار می‌کند و حلقه‌های رهبری را تسهیل می‌کند که به رهبران در مراحل مختلف حرفه‌شان راهنمایی می‌کنند. <em>به مدیریت خوش آمدید</em> اولین کتاب او است.</p>', '2023-01-26 19:07:52.245209', '2023-01-26 19:07:52.245209', NULL, 'Ryan Hawk');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (227, 'لین انرایت', '<p>لین انرایت یک روزنامه نگار ایرلندی الاصل و ساکن لندن است. آثار او در <em>Vogue، </em>the<em> Independent، BuzzFeed، </em>the<em> Guardian، </em>the<em> Irish Times، Elle، </em>the ظاهر شده است. <em> London Evening Standard، </em>و<em> Financial Times.</em></p>', '2023-01-26 19:07:57.297803', '2023-01-26 19:07:57.297803', NULL, 'Lynn Enright');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (228, 'اندرو یانگ', '<p>اندرو یانگ بنیانگذار و مدیر عامل Venture for America است، یک سازمان غیرانتفاعی ملی که به دانشجویان با استعداد کمک می‌کند پس از فارغ‌التحصیلی، تجربیات ارزشمندی را در کسب‌وکارهای نوپا جمع‌آوری کنند. او خود بیش از 12 سال در چندین استارت آپ کار کرده است و از سوی کاخ سفید به عنوان "قهرمان تغییر" معرفی شد و به عنوان یکی از "100 خلاق ترین افراد در کسب و کار" Fast Company لقب گرفت.</p>', '2023-01-26 19:08:02.38288', '2023-01-26 19:08:02.38288', NULL, 'Andrew Yang');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (229, 'بن گرینفیلد', '<p>بن گرینفیلد نویسنده پرفروش، نویسنده <em>نیویورک تایمز</em>، بدنساز سابق، ورزشکار سه گانه مرد آهنین و مربی است. او یک سخنران منظم در مورد موضوعات سلامتی و تناسب اندام است.</p>', '2023-01-26 19:08:07.362983', '2023-01-26 19:08:07.362983', NULL, 'Ben Greenfield');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (230, 'درک دریپر', '<p>درک دریپر یکی از بنیانگذاران و مدیر عامل مشاوران رهبری CDP است. او یک روانشناس تجاری با بیش از یک دهه تجربه در کمک به مشتریان در سراسر جهان است، او مدیران اجرایی و مدیران عالی رتبه در برخی از بزرگترین شرکت های جهان را هدایت می کند. او هنوز یک مطب روان درمانی کوچک را در لندن اداره می کند، جایی که با همسر و دو فرزندش زندگی می کند.</p>', '2023-01-26 19:08:11.86514', '2023-01-26 19:08:11.86514', NULL, 'Derek Draper');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (231, 'یعقوب بنبونان', '<p>نویسندگان، مدیر عامل، مدیر خلاق و مدیر ارشد رشد مشاوران برند زعفران هستند. Saffron یک شرکت مشاوره برند جهانی است که در سال 2001 تأسیس شد و برای مشتریانی از جمله زیمنس، یوتیوب و زینگ کار کرده است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (232, 'پیتر برگمن', '<p>پیتر برگمن مشاور و مشاور مدیران عامل از شرکت‌های بزرگ تا استارت‌آپ‌های کوچک است. تخصص او بر رهبری و بهبود زندگی کاری امروز متمرکز است. نوشته های او همچنین در <em>Forbes</em> و <em>Psychology Today</em> ظاهر شده است.</p>', '2023-01-26 19:08:22.704027', '2023-01-26 19:08:22.704027', NULL, 'Peter Bregman');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (256, 'بن دکر و کلی دکر', '<p>بن و کلی دکر از کارشناسان برجسته در ارتباطات تجاری هستند. آنها تجربه مربیگری گسترده ای با استارتاپ های بلندپروازانه و همچنین شرکت های Fortune 500 دارند. آنها با هم مغز پشت Decker Communications هستند، شرکتی که به افراد بی‌شماری کمک کرده تا مهارت‌های ارتباطی خود را بهبود بخشند.</p>', '2023-01-26 19:10:41.597476', '2023-01-26 19:10:41.597476', NULL, 'Ben Decker & Kelly Decker');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (233, 'دن کیندلون و مایکل تامپسون', '<p>مایکل تامپسون، دکترا، یک روانشناس خانواده مستقر در کمبریج، ماساچوست است. او یک نویسنده پرفروش <em>نیویورک تایمز</em> است که مهارت های مشاوره خود را به هزاران مدرسه در سراسر جهان ارائه کرده است. از دیگر کتاب های او می توان به <em>دلتنگی و شادی</em> و <em>کودک تحت فشار</em> اشاره کرد.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (234, 'ریچارد ان. بولز', '<p>ریچارد ان. بولز برای بیش از 40 سال یک رهبر محترم در زمینه توسعه شغلی بود، در این مدت او هرگز در انتشار به روز رسانی سالانه کتاب راهنمای شغلی پرفروش خود، <em>چتر نجات شما چه رنگی است، کوتاهی نکرد؟ </em> او همچنین یکی از اعضای منسا و یک سخنران اصلی محبوب بود.</p>', '2023-01-26 19:08:37.213422', '2023-01-26 19:08:37.213422', NULL, 'Richard N. Bolles');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (235, 'باربارا ناترسون-هورویتز و کاترین باورز', '<p>باربارا ناترسون-هورویتز استاد قلب و عروق در دانشگاه کالیفرنیا، لس آنجلس است. او همچنین عضو هیئت مشاوره پزشکی باغ وحش لس آنجلس است. کاترین باورز نویسنده و تهیه کننده در CNN International است و اغلب در UCLA در مورد موضوعات پزشکی سخنرانی می کند.</p>', '2023-01-26 19:08:41.862086', '2023-01-26 19:08:41.862086', NULL, 'Barbara Natterson-Horowitz and Kathryn Bowers');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (236, 'بردلی نلسون', '<p>دکتر بردلی نلسون یک پزشک و مدرس جامع نگر مشهور است که با هزاران مشتری کار کرده است. روش های او ترکیبی منحصر به فرد از انرژی درمانی، حرکت شناسی کاربردی و مغناطیس درمانی است. نلسون به طور گسترده‌ای به عنوان برجسته‌ترین متخصص در زمینه‌های نوظهور پزشکی بیوانرژتیک و روان‌شناسی انرژی در نظر گرفته می‌شود. </p>', '2023-01-26 19:08:46.711922', '2023-01-26 19:08:46.711922', NULL, 'Bradley Nelson');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (237, 'ست استفنز-دیویدویتز', '<p>Seth Stephens-Davidowitz نویسنده، سخنران اصلی و متخصص داده است. او که قبلاً یکی از برترین دانشمندان داده گوگل بود، اکنون روی استفاده از تجزیه و تحلیل مبتنی بر داده برای به دست آوردن بینش جدیدی در مورد رفتار و روانشناسی انسان تمرکز کرده است.</p>', '2023-01-26 19:08:51.55095', '2023-01-26 19:08:51.55095', NULL, 'Seth Stephens-Davidowitz');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (238, 'سارا گی فورد', '<p>سارا گی فوردن بیش از 15 سال مد را در میلان پوشش می داد و از برچسب هایی مانند گوچی، آرمانی و ورساچه پیروی می کرد، زیرا آنها از شرکت های کوچک خانوادگی به وزنه های سنگین جهانی تبدیل شدند. او اکنون در Bloomberg News در واشنگتن دی سی کار می کند، جایی که او در مورد چالش های پیش روی شرکت های بزرگ فناوری از جمله گوگل و آمازون گزارش می دهد.</p>', '2023-01-26 19:08:57.06754', '2023-01-26 19:08:57.06754', NULL, 'Sara Gay Forden');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (239, 'بیل برنت و دیو ایوانز', '<p>بیل برنت دارای مدرک کارشناسی ارشد در طراحی محصول از دانشگاه استنفورد است، جایی که او اکنون در آنجا تدریس می کند و مدیریت برنامه طراحی را بر عهده دارد. با بیش از سی سال تجربه، او متخصصی است که هنوز هم هر روز چیزهایی را طراحی، طراحی و می‌سازد.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (240, 'لورا واندرکام', '<p>لورا واندرکام نویسنده و متخصص بهره وری است که آثارش در <em>نیویورک تایمز</em>، <em> وال استریت ژورنال</em>، <em>شرکت سریع</em>، منتشر شده است، و <em>Fortune</em>. او یکی از مجریان پادکست <em>قبل از صبحانه</em> است که ایده‌هایی از کتاب‌های دیگر او در مورد مدیریت زمان از جمله <em>مردم موفق قبل از صبحانه چه می‌کنند، خارج از ساعت</em>، و<em است. > </em>و <em>من می دانم که او چگونه این کار را انجام می دهد. </em></p>', '2023-01-26 19:09:08.840331', '2023-01-26 19:09:08.840331', NULL, 'Laura Vanderkam');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (241, 'آبل جیمز', '<p>ابل جیمز خالق <em>مرد چربی سوز</em> است، یک پادکست موفق بین المللی در مورد تغذیه سالم و سبک زندگی. این پادکست به عنوان پادکست شماره یک غذا در هشت کشور رتبه بندی شده است.</p>', '2023-01-26 19:09:14.458738', '2023-01-26 19:09:14.458738', NULL, 'Abel James');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (242, 'دوره رابرت', '<p>رابرت کورسون یک نویسنده برنده جایزه است که آثارش در <em>مجله نیویورک تایمز</em>، <em>رولینگ استون</em> و <em>Esquire</em> منتشر شده است.< /p>', '2023-01-26 19:09:24.585775', '2023-01-26 19:09:24.585775', NULL, 'Robert Kurson');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (243, 'دیوید جی بلاند و الکساندر استروالدر', '<p>دیوید جی بلاند علاوه بر نویسنده بودن، بنیانگذار Precoil است، یک مشاور استراتژی که به کسب و کارها کمک می کند ایده های خود را آزمایش کنند. الکساندر اوستروالدر نظریه پرداز و کارآفرینی است که در مدل سازی کسب و کار تخصص دارد. </p>', '2023-01-26 19:09:29.894638', '2023-01-26 19:09:29.894638', NULL, 'David J. Bland and Alexander Osterwalder');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (244, 'دن سیروکر و پیت کومن', '<p>دن سیروکر مدیر تحلیل برای مبارزات انتخاباتی اوباما در سال 2008 بود. او یکی از بنیانگذاران Optimizely است، پلتفرمی که به کسب و کارها کمک می کند از داده ها برای بهبود حضور آنلاین خود استفاده کنند.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (245, 'آرون سینگ و مایک مستر', '<p>آرون سینگ یک وکیل پیشرو در حقوق شرکت های بین المللی و شریک سابق در قانون KPMG، یک قانون بین المللی است. او که یک مربی در زمینه رهبری شرکتی و مذاکرات با سه دهه تجربه است، به عنوان استاد مدعو در مدارس بازرگانی چین و بریتانیا خدمت کرده است، در سازمان‌های بین‌المللی تدریس کرده و به دولت بریتانیا در زمینه تجارت و سرمایه‌گذاری بین‌المللی مشاوره داده است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (246, 'راب جان دی جونگ', '<p>Rob-Jan de Jong یک مشاور، مربی و سخنران در توسعه رهبری است. مشتریان او عبارتند از TotalOil، ING، Phillips و سایر سازمان ها و مدارس تجاری در سراسر جهان. <em>پیش بینی</em> اولین حضور او را به عنوان نویسنده نشان می دهد.</p>', '2023-01-26 19:09:45.93745', '2023-01-26 19:09:45.93745', NULL, 'Rob-Jan de Jong');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (247, 'جف سندرز', '<p>جف سندرز یک سخنران عمومی و مربی شخصی است که با آرمان هایی که موعظه می کند زندگی می کند. ساندرز که زودتر، دونده ماراتن و گیاهخوار متعهد است، یکی از موثرترین خودبهینه سازهای امروزی است. <em>فرمول زمان آزاد </em>دومین کتاب او پس از اولین کتاب پرفروش او، <em>معجزه 5 صبح</em> است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (248, 'مورتیمر جی. آدلر و چارلز ون دورن', '<p>مورتیمر جی. آدلر یک فیلسوف، مربی و نویسنده علوم عمومی بود. ویراستار دایره المعارف بریتانیکا و مؤسس مؤسسه تحقیقات فلسفی، او همچنین مدافع آموزش بزرگسالان از طریق خواندن متون کلاسیک بود.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (249, 'دانیل جی سیگل', '<p>دانیل جی سیگل روانپزشکی است که در دانشکده پزشکی دیوید گفن در کالیفرنیا کار می کند. او در مطالعه ذهن آگاهی و مدیتیشن تخصص دارد و نویسنده چندین کتاب محبوب در این زمینه است، از جمله <em>والدین از درون</em> و <em>ذهن بینی</em>.</p>', '2023-01-26 19:10:02.475371', '2023-01-26 19:10:02.475371', NULL, 'Daniel J. Siegel');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (250, 'کن سگال', '<p>کن سگال نویسنده کتاب پرفروش <em>نیویورک تایمز</em> <em>به طرز دیوانه کننده ای ساده</em> است. او که دوازده سال با استیو جابز به‌عنوان مدیر خلاق اپل کار کرد، کمپین Think Different این برند را رهبری کرد و iMac نامید که منجر به برندسازی افسانه‌ای i برای محصولاتی مانند iPod و iPad شد.</p>', '2023-01-26 19:10:07.907646', '2023-01-26 19:10:07.907646', NULL, 'Ken Segall');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (251, 'کریس کرنز', '<p>کریس کرنز رهبری گروه تحلیلی و تحقیقاتی Spredfast را بر عهده دارد، یک مشاور بازاریابی اجتماعی که به سازمان‌ها اجازه می‌دهد تا از طریق رسانه‌های اجتماعی با مصرف‌کنندگان ارتباط برقرار کنند. او استراتژی دیجیتالی را برای برخی از بزرگترین برندهای جهان از جمله فورد، مایکروسافت و نایک تنظیم کرده است و تحقیقات او در نشریاتی مانند <em>نیویورک تایمز</em>، <em>فوربس</em> ظاهر شده است. ، <em>USA Today</em> و <em>AdWeek.</em></p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (252, 'Reggie Fils-Aime', '<p>Reggie Fils-Aimé رئیس سابق و مدیر ارشد اجرایی Nintendo of America است. قبل از صعود به قله غول بازی های ویدیویی، او یک حرفه ای چند دهه در فروش و بازاریابی داشت و با شرکت هایی مانند Proctor & Gamble، Pizza Hut، و VH1 کار می کرد.</p>', '2023-01-26 19:10:19.596702', '2023-01-26 19:10:19.596702', NULL, 'Reggie Fils-Aimé');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (253, 'رنه ایونسون', '<p> رنه ایونسون دارای مدرک روانشناسی سازمانی و علاقه مند به مدیریت ارتباطات و تعارض است. او بیش از سه دهه در مدیریت خدمات مشتری کار کرده است و کتاب های متعددی در زمینه ارتباطات در خدمات مشتری نوشته است، از جمله <em>آموزش خدمات مشتری 101</em> و <em>آموزش مدیریت خدمات مشتری 101</em>. </p>', '2023-01-26 19:10:25.92663', '2023-01-26 19:10:25.92663', NULL, 'Renée Evenson');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (254, 'تیم لبرشت', '<p>Tim Leberecht مدیر ارشد بازاریابی NBBJ است، یک شرکت طراحی و معماری که به بازیگران جهانی مانند آمازون، بوئینگ، مایکروسافت و استارباکس کمک می‌کند تا تجربیات برند معناداری ایجاد کنند. سخنرانی TED او "سه راه برای (مفید) از دست دادن کنترل برند شما" توسط میلیون ها نفر مشاهده شده است.</p>', '2023-01-26 19:10:31.440767', '2023-01-26 19:10:31.440767', NULL, 'Tim Leberecht');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (255, 'C.L.R. جیمز', '<p>C.L.R. جیمز (۱۹۰۱–۱۹۸۹) یک نویسنده و دانشگاهی اهل ترینیداد بود. او نویسنده کتاب های زیادی در مورد مارکسیسم، تاریخ و کریکت بود. او پیشگام در زمینه ادبیات پسااستعماری و یک فعال سیاسی تأثیرگذار بود.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (308, 'کریستوفر مک دوگال', '<p>کریستوفر مک دوگال نویسنده آمریکایی، سخنران TED و روزنامه نگار است که برای <em>Esquire، مجله نیویورک تایمز</em>، <em> مجله مردان</em>، <em> نیویورک</em نوشته است. > و<em>خارج</em>. او همچنین به عنوان ویراستار برای <em>Men’s Health عمل کرده است. </em></p>', '2023-01-26 19:19:19.030664', '2023-01-26 19:19:19.030664', NULL, 'Christopher McDougall');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (257, 'هانتر کلارک فیلدز', '<p> هانتر کلارک فیلدز "مرشد مادر آگاه" است که در مأموریتی برای پایان دادن به الگوهای نسل منفی است. کلارک فیلدز با ترکیب تجربه 20 ساله خود در مدیتیشن و یوگا با سفر شخصی خود به عنوان یک مادر، والدین را به سمت کنترل رفتار ارتجاعی خود راهنمایی می کند تا در نقش مراقبتی خود ماهرانه شوند.</p>', '2023-01-26 19:10:46.768799', '2023-01-26 19:10:46.768799', NULL, 'Hunter Clarke-Fields');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (258, 'کلسکی انجام دهید', '<p>کارن کلسکی یک استاد سابق و رئیس بخش است. او دانشگاه را ترک کرد تا The Professor Is In را راه اندازی کند.', '2023-01-26 19:10:51.79672', '2023-01-26 19:10:51.79672', NULL, 'Karen Kelsky');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (259, 'رندی تازه', '<p>رندی فریش یک کارآفرین و مدیر عامل پلت فرم تجربه محتوا Uberflip است که به کسب و کارها کمک می کند محتوای خود را به طور مؤثرتری مدیریت کنند. او همچنین یک سخنران عمومی مورد تقاضا و نویسنده پرفروش است. <em>F#ck Content Marketing</em> اولین کتاب اوست. </p>', '2023-01-26 19:11:03.831127', '2023-01-26 19:11:03.831127', NULL, 'Randy Frisch');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (260, 'الیزابت بلکبرن و الیسا اپل', '<p>دکتر الیزابت بلکبرن، دکترا، پس از کشف ماهیت مولکولی تلومرها، جایزه نوبل فیزیولوژی یا پزشکی را در سال 2009 با دو همکارش به اشتراک گذاشت. او اکنون رئیس مؤسسه سالک و استاد بازنشسته در دانشگاه کالیفرنیا، سانفرانسیسکو است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (261, 'سوزان دیوید', '<p>سوزان دیوید یک روانشناس پزشکی است. او مؤسسه مربیگری را در بیمارستان مک‌لین در ماساچوست اداره می‌کند و برای شرکت‌های بزرگ به عنوان مشاور کار کرده است. نوشته های او در <em>Harvard Business Review</em> و <em>Wall Street Journal</em></p> منتشر شده است.', '2023-01-26 19:11:14.957954', '2023-01-26 19:11:14.957954', NULL, 'Susan David');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (262, 'مایکل سی هایتر', '<p>Michael C. Hyter رئیس و مدیر عامل شورای رهبری اجرایی است، یک سازمان عضویت برای مدیران عامل، مدیران هیئت مدیره و مدیران ارشد سیاه پوست. او قبلاً مدیر ارشد تنوع در شرکت مشاوره جهانی Korn Ferry بود و همچنین ریاست دفتر آن در واشنگتن دی سی را بر عهده داشت. او نویسنده <em>قدرت گنجاندن</em> است.</p>', '2023-01-26 19:11:19.997433', '2023-01-26 19:11:19.997433', NULL, 'Michael C. Hyter');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (263, 'جردن النبرگ', '<p>جردن النبرگ استاد ریاضیات در دانشگاه ویسکانسین-مدیسون است. کار او طیف گسترده ای از موضوعات ریاضی، از جمله هندسه حسابی و نظریه اعداد را پوشش می دهد. النبرگ ستون محبوب "حساب را انجام دهید" را برای <em>Slate،</em> می نویسد و آثاری در <em>The</em> <em>نیویورک تایمز</em>، <em> ظاهر شده است. واشنگتن پست</em> و <em>The</em> <em>وال استریت ژورنال.</em> او همچنین نویسنده رمان <em>پادشاه ملخ</em></p> است.', '2023-01-26 19:11:25.315778', '2023-01-26 19:11:25.315778', NULL, 'Jordan Ellenberg');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (264, 'جان آر. دی جولیوس سوم', '<p>جان دی جولیوس موسس و مالک آبگرم جان رابرت، یکی از 20 سالن آبگرم برتر در آمریکا است. او همچنین رئیس گروه DiJulius است، یک گروه مشاوره خدمات مشتری که مشتریان آن شامل شرکت‌های موفقی مانند استارباکس، لکسوس و نستله هستند.</p>', '2023-01-26 19:11:30.305771', '2023-01-26 19:11:30.305771', NULL, 'John R. DiJulius III');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (265, 'آلف رن', '<p>Alf Rehn یک مدرس فنلاندی و نویسنده است که دارای کرسی مدیریت و سازمان در دانشگاه Åbo Akademi است. رن به عنوان ستون نویس کار می کند و در هیئت مدیره چندین شرکت، از جمله آژانس شرط بندی دولتی فنلاند، Veikkaus، حضور دارد. از دیگر آثار برجسته او می توان به <em>ایده های خطرناک</em> و <em>Trendspotting</em> اشاره کرد که وی با همکاری مگنوس لیندکویست نوشته است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (266, 'ویلیام اچ مک ریون', '<p>ویلیام اچ. مک ریون یک دریاسالار چهار ستاره بازنشسته نیروی دریایی ایالات متحده است. آخرین مأموریت او فرماندهی تمام نیروهای عملیات ویژه ایالات متحده بود. او نویسنده دو کتاب محبوب دیگر به نام‌های <em>تختخوابت را درست کن</em> و <em>داستان‌های دریا</em> است.</p>', '2023-01-26 19:11:40.93628', '2023-01-26 19:11:40.93628', NULL, 'William H. McRaven');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (267, 'کاترین وودوارد توماس', '<p>کاترین وودوارد توماس، یک درمانگر ازدواج و خانواده دارای مجوز، سالهاست که روش پنج مرحله‌ای پارادایم‌شکنی خود را برای جداسازی آگاهانه به مراجع و درمانگران آموزش داده است. او که یک نویسنده پرفروش و مربی معتبر است، دهه گذشته را وقف ایجاد یک مسیر جدید برای زوج هایی کرده است که به دنبال بسته شدن هستند.</p>', '2023-01-26 19:11:45.799302', '2023-01-26 19:11:45.799302', NULL, 'Katherine Woodward Thomas');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (268, 'وین دبلیو دایر', '<p><strong>درباره نویسنده</strong></p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (291, 'جیمز دبلیو تام و رونالد جی لویت', '<p>جیمز دبلیو تام متخصص حل تعارض با دهه‌ها تجربه در ایجاد محیط‌های کاری مشترک است. او همچنین یک استاد سابق حقوق و قاضی کالیفرنیا است که اکنون ریاست شرکت مشاوره Business Consultants Network Inc.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (269, 'جیمز آلتوچر', '<p>جیمز آلتوچر یک کارآفرین، پادکست و سرمایه‌گذار فرشته موفق است. او همچنین نویسنده چندین کتاب است که در فهرست پرفروش‌ترین‌های <em>وال استریت ژورنال</em> قرار گرفته‌اند، از جمله <em>خودت را انتخاب کن</em>. او 20 شرکت را تاسیس کرده است که 17 تای آنها شکست خورده اند. این تجربیات او را به ارزیابی مجدد رویکرد خود در زمینه تجارت و زندگی سوق داد، و او را به بینش هایی که در پادکست خود،<em>James Altucher Show</em> به اشتراک می گذارد، هدایت کرد، که تا به امروز بیش از 50 میلیون دانلود جمع آوری کرده است.< /p>', '2023-01-26 19:11:55.332874', '2023-01-26 19:11:55.332874', NULL, 'James Altucher');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (270, 'کیت فرازی با نوئل ویریچ', '<p>کیت فرازی نویسنده و کارآفرینی است که پرفروش‌ترین کتاب‌های تجاری او شامل <em>هیچ‌وقت تنها نخورید</em> و <em>چه کسی پشت شما را برمی‌دارد می‌باشد. </em>Ferrazzi<em> </em>همچنین موسس و مدیر عامل شرکت تحقیقاتی و مشاوره Ferrazzi Greenlight است. نوئل ویریچ نویسنده ای با بیش از بیست سال تجربه در روزنامه نگاری تحقیقی و گزارشگری است.</p>', '2023-01-26 19:12:00.661043', '2023-01-26 19:12:00.661043', NULL, 'Keith Ferrazzi with Noel Weyrich');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (271, 'مل رابینز', '<p>مل رابینز یک مجری تلویزیونی و مفسر مکرر در CNN است. او همچنین یک سخنران انگیزشی و سردبیر مجله <em>Success</em> است. کتاب قبلی او پرفروش‌ترین کتاب <em>بگویید خوب هستید</em> بود، که به روان‌شناسی پشت رسیدن به آنچه می‌خواهید می‌پردازد.</p>', '2023-01-26 19:12:05.197848', '2023-01-26 19:12:05.197848', NULL, 'Mel Robbins');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (272, 'کریس بروگان', '<p>کریس بروگان، مدیر عامل شرکت <em>Owner Media Group</em>، نویسنده پرفروش هشت کتاب و سخنران حرفه ای است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (273, 'لورن بی بلکر', '<p>جیم مک کورمیک مشاور سازمانی و مربی اجرایی و همچنین موسس و رئیس موسسه تحقیقاتی برای هوش ریسک است. او قبلاً مدیر اجرایی پنجمین شرکت بزرگ معماری در ایالات متحده است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (274, 'تام یانگ', '<p>تام یانگ یک روانشناس عملکرد با سابقه کار با افراد در بالاترین سطوح ورزش حرفه ای است. او مشاور تیم ملی فوتبال بلژیک و تیم جام اروپایی ۲۰۱۸ رایدر بوده است.</p>', '2023-01-26 19:12:26.092217', '2023-01-26 19:12:26.092217', NULL, 'Tom Young');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (275, 'جاناتان شاپیرو', '<p>جاناتان شاپیرو، فیلمنامه‌نویس هالیوود، روزنامه‌نگار و وکیل دادگستری، در بسیاری از مشاغل حرفه‌ای است. آثار نویسندگی او برای تلویزیون شامل بسیاری از برنامه های حقوقی معروف مانند <em>لیست سیاه، حقوقی بوستون</em>و <em>The Practice است.', '2023-01-26 19:12:31.75974', '2023-01-26 19:12:31.75974', NULL, 'Jonathan Shapiro');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (276, 'امیلی اوستر', '<p>امیلی اوستر، استاد اقتصاد در دانشگاه براون، دارای مدرک دکترای اقتصاد از دانشگاه هاروارد است. او نویسنده کتاب تحریک آمیز و بحث برانگیز <em>انتظار بهتر: چرا عقل مرسوم بارداری اشتباه است – و آنچه واقعاً باید بدانید</em> است. او مقالاتی برای <em>نیویورک تایمز، وال استریت ژورنال، فوربس </em>و<em> Esquire</em> نوشته است، و همچنین در کنفرانس TED در سال 2007 سخنران بود.</p>', '2023-01-26 19:12:37.086532', '2023-01-26 19:12:37.086532', NULL, 'Emily Oster');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (277, 'دیو لوگان', '<p> دیو لوگان استاد تجارت در دانشگاه کالیفرنیای جنوبی و نویسنده چندین کتاب موفق است. او با جان کینگ شرکت مشاوره مدیریت CultureSync را تأسیس کرد. جان کینگ همچنین یک نویسنده موفق و یک سخنران اصلی محبوب است. هیلی فیشر رایت یک متخصص اطفال سابق است که اکنون یک متخصص برجسته در زمینه مراقبت های بهداشتی و مدیریت کسب و کار است. او همچنین شریک <em>CultureSync،</em> است و به عنوان دستیار استاد بالینی در دانشگاه کلرادو خدمت می کند، جایی که دکترای خود را دریافت کرد</p>', '2023-01-26 19:12:42.828659', '2023-01-26 19:12:42.828659', NULL, 'Dave Logan');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (278, 'اوبری مارکوس', '<p>اوبری مارکوس موسس و مدیر عامل شرکت سبک زندگی Onnit است. مارکوس همچنین پادکست خود را دارد - <em>پادکست Aubrey Marcus</em>.</p>', '2023-01-26 19:12:48.809267', '2023-01-26 19:12:48.809267', NULL, 'Aubrey Marcus');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (279, 'کارمین گالو', '<p>کارمین گالو، معاون سابق یک شرکت بزرگ روابط عمومی جهانی است که برخی از معتبرترین برندهای جهان را در ارائه و ارتباطات مربی می‌کند. او در CNBC، NBC، CBS، و همچنین در <em>وال استریت ژورنال</em> و <em>نیویورک تایمز</em> ظاهر شده است.</p>', '2023-01-26 19:12:53.651414', '2023-01-26 19:12:53.651414', NULL, 'Carmine Gallo');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (280, 'کیت بولر', '<p>کیت بولر استاد تاریخ مسیحیت در دانشگاه دوک است. او آثار علمی در مورد بشارت و صنعت خودیاری منتشر کرده است در حالی که برای نوشتن زندگی خود با عنوان پرفروش <em>نیویورک تایمز</em> <em>همه چیز به دلیلی اتفاق می‌افتد (و دروغ‌های دیگر) طرفداران محبوبی پیدا کرده است. I''ve Loved</em>) و جدیدترین نسخه او <em>هیچ درمانی برای انسان بودن (و دیگر حقایقی که باید بشنوم)</em> وجود ندارد.</p>', '2023-01-26 19:12:58.571994', '2023-01-26 19:12:58.571994', NULL, 'Kate Bowler');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (281, 'ریچ شریدان', '<p>Rich Sheridan مدیر عامل Menlo Innovations در Ann Arbor، میشیگان است.</p>', '2023-01-26 19:13:03.903263', '2023-01-26 19:13:03.903263', NULL, 'Rich Sheridan');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (292, 'کریس گووارد', '<p>کریس گووارد بنیانگذار WiderFunnel، یک آژانس بهینه‌سازی بازاریابی است که با مشتریانی مانند Google، Electronic Arts و Babyage.com کار کرده است.</p>', '2023-01-26 19:14:12.175694', '2023-01-26 19:14:12.175694', NULL, 'Chris Goward');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (282, 'ریچارد دایسون و ریچارد ایوانز', '<p>ریچارد دایسون یک روزنامه‌نگار مالی برنده جایزه و مشارکت کننده منظم در عناوین تخصصی و غیرتخصصی از جمله <em>Express</em>، <em>Mail on Sunday</em>، <em> است. Investors Chronicle </em>و <em>Daily Telegraph</em>. دایسون همچنین رئیس امور مالی شخصی در گروه رسانه تلگراف بود. </p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (283, 'جان سی. نورکراس و همکاران.', '<p>John C. Norcross, PhD, ABPP, یک روانشناس بالینی دارای گواهی هیئت مدیره است که در دانشگاه اسکرانتون به عنوان استاد روانشناسی و در مرکز پزشکی SUNY Upstate به عنوان استاد کمکی روانپزشکی کار می کند.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (284, 'دیموند جان با دنیل پیزنر', '<p>Daymond John بنیانگذار و مدیر عامل FUBU است، یک نام تجاری سبک زندگی که بیش از 6 میلیارد دلار فروش جهانی به دست آورده است. او که مهمان دائمی <em>مخزن کوسه</em> شبکه ABC است، یکی از معتبرترین تاجران و مشاوران آمریکایی است. جان نویسنده کتاب های پرفروش متعددی از جمله <em>قدرت شکست </em>و <em>برخاستن و ساییدن</em> است. او همچنین سفیر ریاست جمهوری برای کارآفرینی جهانی بود، موقعیتی که باراک اوباما در سال 2014 برای حمایت از کارآفرینان جوان ایجاد کرد.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (285, 'اسکات گالووی', '<p> اسکات گالووی استاد بازاریابی در دانشکده بازرگانی NYU Stern و بنیانگذار نه شرکت از جمله پیامبر، رد پاکت، و L2 است. عناوین قبلی او عبارتند از <em>چهار</em> و<em>جبر خوشبختی</em>.</p>', '2023-01-26 19:13:30.306443', '2023-01-26 19:13:30.306443', NULL, 'Scott Galloway');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (286, 'آدام توز', '<p>آدام توز، مورخ بریتانیایی، استاد و مدیر مؤسسه اروپایی در دانشگاه کلمبیا، نیویورک است. کتاب های قبلی او عبارتند از برنده جایزه تاریخ ولفسون <em>دستمزد تخریب</em>(2006)، مطالعه سیاست های اقتصادی آلمان نازی، و <em>سیل بزرگ</em>(2014)، تحلیلی از جنگ بزرگ و ایجاد نظم بین المللی جدید.</p>', '2023-01-26 19:13:35.70357', '2023-01-26 19:13:35.70357', NULL, 'Adam Tooze');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (287, 'جان گوردون', '<p>جان گوردون نویسنده و متخصص در موضوعات کار تیمی، رهبری و فرهنگ است. او برای تعدادی از سازمان‌ها و شرکت‌های ورزشی کار کرده است، و کارهایش در <em>نیویورک پست، </em><em>وال استریت ژورنال</em> و <em>واشنگتن پست به نمایش درآمده است. /em></p>', '2023-01-26 19:13:42.309598', '2023-01-26 19:13:42.309598', NULL, 'Jon Gordon');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (288, 'آند ماسلن', '<p>اندی ماسلن سال‌هاست که معلم مورد نیاز تکنیک‌های کپی‌رایتینگ بوده و مدیر عامل آکادمی کپی‌نویسی اندی ماسلن است. او همچنین مدیر عامل آژانس ارتباطات شرکتی Sunfish است. مشتریان او عبارتند از <em>The Economist</em>، <em>نیویورک تایمز</em>، BBC Worldwide و بورس لندن.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (289, 'جفری فافر', '<p>جفری فافر استاد دانشکده تحصیلات تکمیلی بازرگانی استنفورد است و کلاس های زیادی را در مورد مدیریت موثر منابع انسانی تدریس کرده است. امروزه او با تحقیقات منتشر شده در مورد قدرت سازمانی که به 30 سال قبل بازمی گردد، یکی از کارشناسان برجسته مدیریت در جهان به شمار می رود. او همچنین نویسنده <em>Power</em> است که به جزئیات چگونگی استفاده خوانندگان از قدرت در زندگی روزمره خود می‌پردازد.</p>', '2023-01-26 19:13:55.918235', '2023-01-26 19:13:55.918235', NULL, 'Jeffrey Pfeffer');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (290, 'اریک وره', '<p>Eric Worre یک حرفه ای بسیار موفق در بازاریابی شبکه ای است که 25 سال فعالیت حرفه ای او میلیون ها درآمد برای او به همراه داشته است. در سال 2009 او NetworkMarketingPro.com را تأسیس کرد که پربیننده ترین سایت آموزش بازاریابی است و مخاطبان جهانی را به خود جذب کرد. <em>Go Pro</em> اولین کتاب پرفروش او است.</p>', '2023-01-26 19:14:00.675956', '2023-01-26 19:14:00.675956', NULL, 'Eric Worre');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (294, 'مایکل ای پورتر', '<p>مایکل ای. پورتر استاد مؤسسه استراتژی و رقابت در دانشکده بازرگانی هاروارد، و یک مرجع برجسته در استراتژی رقابتی و توسعه اقتصادی است. علاوه بر این، او 16 کتاب نوشته است، از جمله <em>مزیت رقابتی ملل</em> و <em>مزیت رقابتی: ایجاد و پایداری عملکرد برتر</em>.</p>', '2023-01-26 19:14:22.192268', '2023-01-26 19:14:22.192268', NULL, 'Michael E. Porter');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (295, 'ژنرال استنلی مک کریستال با تانتوم کالینز', '<p>ژنرال استنلی مک کریستال قبل از بازنشستگی به عنوان ژنرال چهار ستاره به مدت 34 سال در ارتش ایالات متحده خدمت کرد.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (296, 'ایرا چلف', '<p>Ira Chaleff نویسنده، مربی اجرایی و مشاور است که به عنوان یکی از 100 "بهترین ذهن در مورد رهبری" انتخاب شده است. از دیگر کارهای او می توان به <em>پیرو شجاع</em>و <em>هنر پیروی</em></p> اشاره کرد.', '2023-01-26 19:14:31.907179', '2023-01-26 19:14:31.907179', NULL, 'Ira Chaleff');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (297, 'Judith Hanson Lasater و Ike K. Lasater', '<p>جودیت هانسون لاستر از سال 1971 معلم یوگا بوده و همچنین رئیس انجمن معلمان یوگا کالیفرنیا است. او دارای دکترای روانشناسی شرق-غرب است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (298, 'راندال مونرو', '<p>رندال مونرو نویسنده وب کمیک محبوب <em>xkcd</em> و دو کتاب پرفروش <em>نیویورک تایمز</em> است - <em>چه می‌شد اگر؟</em> و <em >Thing Explainer.</em> او یک روباتیک سابق ناسا است که در سال 2006 آژانس را ترک کرد و به دنبال طراحی حرفه ای تمام وقت کمیک بود. </p>', '2023-01-26 19:14:42.180896', '2023-01-26 19:14:42.180896', NULL, 'Randall Munroe ');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (299, 'پیتر اتکینز', '<p>پیتر اتکینز یک فیزیکدان مشهور و نویسنده بیش از 60 کتاب است، از جمله <em>شیمی فیزیک</em>، یک کتاب درسی استاندارد که توسط دانش آموزان در سراسر جهان استفاده می شود. اتکینز عضو کالج لینکلن، دانشگاه آکسفورد، و یک چهره شناخته شده در مدار سخنرانی بین المللی است. او استاد مدعو در چین، فرانسه، اسرائیل و نیوزلند بوده است.</p>', '2023-01-26 19:18:25.29164', '2023-01-26 19:18:25.29164', NULL, 'Peter Atkins');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (300, 'رابرت جی شیلر', '<p>رابرت جي. او استاد اقتصاد در دانشگاه ییل و یکی از همکاران مکرر <em>نیویورک تایمز</em> است.</p>', '2023-01-26 19:18:30.273181', '2023-01-26 19:18:30.273181', NULL, 'Robert J. Shiller');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (301, 'مایک اسمیت', '<p>مایک اسمیت 25 سال تجربه تبلیغاتی دارد که برای شرکت هایی مانند HBO، مجله فوربس و هرست کار می کند.</p>', '2023-01-26 19:18:39.392237', '2023-01-26 19:18:39.392237', NULL, 'Mike Smith ');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (302, 'مایکل بیلی', '<p>مایکل بیلی یک انتخاب کننده سهام کهنه کار و مدیر پورتفولیو است که قبلاً در Bear Stearns و Raymond James کار می کرد. او در طول زندگی حرفه‌ای خود در استفاده از اصول اقتصاد رفتاری برای کمک به تصمیم‌گیری‌هایش متخصص شد. او در حال حاضر مدیر تحقیقات و رئیس کمیته سرمایه گذاری شرکت سرمایه گذاری FBB Capital Partners مستقر در واشنگتن دی سی است. </p>', '2023-01-26 19:18:44.303242', '2023-01-26 19:18:44.303242', NULL, 'Michael Bailey');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (303, 'تیموتی فریس', '<p>تیموتی فریس نویسنده چندین کتاب خودسازی است، از جمله پرفروش‌ترین کتاب <em>نیویورک تایمز</em>، <em>هفته‌کاری 4 ساعته</em>، با 1.3 میلیون نسخه فروخته شده در سراسر جهان. او همچنین یک فرشته سرمایه گذار برای استارت آپ ها و مشاور شرکت هایی مانند فیس بوک، توییتر و اوبر است.</p>', '2023-01-26 19:18:53.216304', '2023-01-26 19:18:53.216304', NULL, 'Timothy Ferriss');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (304, 'کامرون هرولد', '<p>کامرون هرولد بیست سال تجربه در کمک به موفقیت برخی از بزرگترین شرکت های آمریکایی دارد. او اکنون این تجربه را با میلیون ها نفر دیگر به عنوان سخنران انگیزشی و مشاور تجاری به اشتراک می گذارد.</p>', '2023-01-26 19:18:57.936527', '2023-01-26 19:18:57.936527', NULL, 'Cameron Herold');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (305, 'جیمز گلیک', '<p>جیمز گلیک در مورد تاریخ علم و تأثیر فناوری با تحسین فراوان نوشته است. نوشته های او جایزه نگارش علوم ادبی PEN/EO Wilson و جایزه انجمن سلطنتی وینتون را برای کتاب های علمی به ارمغان آورده است. کتاب‌های او نامزد نهایی جایزه پولیتزر و جایزه ملی کتاب شده‌اند. کتاب های قبلی او عبارتند از <em>اطلاعات: یک تاریخ، یک نظریه، یک سیل</em> (2012) و <em>نابغه: زندگی و علم ریچارد فاینمن </em>(1992).</p>', '2023-01-26 19:19:03.255255', '2023-01-26 19:19:03.255255', NULL, 'James Gleick');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (306, 'هنری مارش', '<p>هنری مارش یکی از برجسته ترین جراحان مغز و اعصاب بریتانیا به شمار می رود و سوژه دو فیلم مستند بوده است. او به عنوان مشاور ارشد در بیمارستان سنت جورج در لندن، به ایجاد یک روش جراحی انقلابی کمک کرد که بیماران را از طریق بی‌حسی موضعی بیدار نگه می‌دارد تا آسیب مغزی بیمار را در طول جراحی کاهش دهد.</p>', '2023-01-26 19:19:08.301609', '2023-01-26 19:19:08.301609', NULL, 'Henry Marsh');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (307, 'ریچارد روملت', '<p>ریچارد روملت دارای کرسی هری و السا کونین در تجارت و جامعه در دانشکده مدیریت اندرسون UCLA است. او همچنین توسط <em>اکونومیست</em> به‌عنوان یکی از 25 فرد زنده‌ای که قوی‌ترین تأثیر را بر مفاهیم مدیریتی دارند و توسط <em>مک‌کینزی کوارترلی «یک غول در زمینه استراتژی» معرفی شده است. /em>.</p>', '2023-01-26 19:19:13.682393', '2023-01-26 19:19:13.682393', NULL, 'Richard Rumelt');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (309, 'دیوید بورکوس', '<p>دیوید بورکوس استادیار مدیریت در کالج تجارت در دانشگاه اورال رابرتز در تولسا، اوکلاهاما است. او در زمینه های خلاقیت و نوآوری و همچنین در زمینه کارآفرینی و رفتار سازمانی تخصص دارد. او برای <em>Fast</em> <em>Company</em> و <em>Bloomberg</em> <em>Businessweek</em> نوشته است و برای <em>Microsoft</em> و <em>Microsoft</em> و <em>Stryker</em>.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (310, 'سلست هدلی', '<p>سلست هدلی روزنامه نگار و مجری برنامه خبری روزانه <em>On Second Thought</em> در پخش عمومی جورجیا است. او بیش از ده سال را با NPR گذرانده است، و همچنین یک خواننده آموزش دیده کلاسیک است. کتاب دوم او، <em>هیچ کاری نکن</em>، درباره نحوه لذت بردن از اوقات فراغت است.</p>', '2023-01-26 19:19:36.056864', '2023-01-26 19:19:36.056864', NULL, 'Celeste Headlee');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (311, 'پل مک گی', '<p>پل مک گی یکی از سخنرانان انگیزشی پیشرو در بریتانیا است. او هفت کتاب نوشته و در مورد موضوعاتی از پویایی محیط کار گرفته تا مدیریت استرس و اعتماد به نفس در 35 کشور سخنرانی کرده است. مک گی همچنین بنیانگذار Shut Up, Move On (SUMO) است، یک برنامه آموزشی زندگی که از درمان شناختی رفتاری استفاده می کند.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (312, 'کرتیس "50 سنت" جکسون', '<p>کرتیس جکسون - که با نام دیگر 50 سنت شناخته می‌شود - یک خواننده رپ، تهیه‌کننده اجرایی و ستاره <em>Power</em>، و نویسنده پرفروش <em>نیویورک تایمز</em> است. کتاب دوم او بر اساس اصول <em>قانون 50</em> استوار است و بینش های بیشتری در مورد موفقیت در دنیای شرکت ها ارائه می دهد. </p>', '2023-01-26 19:19:46.254321', '2023-01-26 19:19:46.254321', NULL, 'Curtis "50 Cent" Jackson');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (313, 'مارک اسپیتزناژل', '<p>مارک اسپیتزناژل موسس و رئیس <em>Universa Investments</em> است، یک مشاور سرمایه‌گذاری که در سود بردن از زیان شدید بازار سهام به عنوان ابزاری برای افزایش بازده سرمایه‌گذاری تخصص دارد. علاوه بر سرمایه‌گذاری در صندوق‌های تامینی، نقش‌های اسپیتزناگل در حرفه سرمایه‌گذاری بیست ساله‌اش از معامله‌گر مستقل در هیئت تجارت شیکاگو تا رئیس معاملات اختصاصی <em>مورگان استنلی</em> متغیر است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (314, 'تیم رایترمن در کنار جان جیکوبز', '<p>تیم رایترمن یک روزنامه نگار برنده جایزه است که بیش از یک سال را در جونزتاون به عنوان گزارشگر <em>آزمایشگاه سان فرانسیسکو</em> گذراند. او زمانی که یک نماینده کنگره آمریکا، سه خبرنگار و یک فراری از معبد مردم قبل از خودکشی دسته جمعی این گروه کشته شدند، حضور داشت. او همچنین به عنوان نویسنده و ویراستار برای <em>لس آنجلس تایمز</em> در طول پوشش برنده جایزه آن از شورش های لس آنجلس کار کرد. او معلم دانشکده روزنامه‌نگاری دانشگاه کالیفرنیا برکلی است.</p>', '2023-01-26 19:19:56.519549', '2023-01-26 19:19:56.519549', NULL, 'Tim Reiterman with John Jacobs ');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (315, 'کاس آر سانستاین', '<p> Cass R. Sunstein استاد دانشگاه هاروارد و بنیانگذار برنامه دانشکده در زمینه اقتصاد رفتاری و سیاست عمومی است. او برای دفتر امور اطلاعات و مقررات کاخ سفید و به عنوان عضوی از گروه بازبینی رئیس جمهور در زمینه فناوری های اطلاعاتی و ارتباطاتی کار کرده است. کتاب‌های دیگر او عبارتند از <em>Nudge: Improving Decisions about Health, Wealth, and Happiness</em> و<em>Simpler: The Future of Government</em>.</p>', '2023-01-26 19:20:01.978144', '2023-01-26 19:20:01.978144', NULL, 'Cass R. Sunstein');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (316, 'اوزان وارول', '<p>حرفه‌های متنوع اوزان وارول شامل علوم موشکی، حقوق، و تألیف کتاب‌های غیرداستانی است. وارول که یکی از اعضای سابق تیم مریخ نوردهای کاوش مریخ در سال 2003 بود، به <em>مثل یک دانشمند موشکی فکر کن</em> نوشت تا به غیر دانشمندان کمک کند تا به پتانسیل کامل خود دست یابند. مقالات برنده جوایز او در کالج ها و مدارس تحصیلات تکمیلی تدریس می شوند و آثار او به طور گسترده در رسانه های ایالات متحده و بین المللی به نمایش درآمده است.</p>', '2023-01-26 19:20:07.01262', '2023-01-26 19:20:07.01262', NULL, 'Ozan Varol');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (317, 'دیوید سولیومی', '<p>دیوید سولیومی، مدیرعامل سابق چندین شرکت، در سن 33 سالگی از سمت‌های شرکتی خود استعفا داد تا به‌عنوان یک سرمایه‌گذار تمام وقت شغلی را دنبال کند. سولیومی که اکنون یک مربی و سرمایه گذار است، با آموزش روش هایی که ثروت او را به دست آورده است، به دیگران در جهت آزادی مالی کمک می کند.</p>', '2023-01-26 19:20:12.213604', '2023-01-26 19:20:12.213604', NULL, 'David Solyomi');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (318, 'مگان مک آردل', '<p>مگان مک‌آردل روزنامه‌نگاری است که نوشته‌هایش درباره سیاست و اقتصاد در <em>The Economist</em>، <em>Bloomberg View</em> و <em>The Atlantic</em> منتشر شده است. <em>The Up Side of Down</em> اولین کار او است.</p>', '2023-01-26 19:20:17.10741', '2023-01-26 19:20:17.10741', NULL, 'Megan McArdle');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (319, 'والتر آیزاکسون', '<p>والتر آیزاکسون نویسنده زندگینامه های تحسین شده آلبرت انیشتین، استیو جابز و بنجامین فرانکلین است. او سردبیر سابق مجله <em>Time</em> و مدیر عامل فعلی موسسه Aspen است، یک سازمان غیرانتفاعی که در تلاش برای ترویج ایده‌های نوآورانه و رهبری است.</p>', '2023-01-26 19:20:21.625293', '2023-01-26 19:20:21.625293', NULL, 'Walter Isaacson');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (320, 'هانا فرای', '<p>دکتر هانا فرای مدرس ریاضیات در مرکز تحلیل فضایی پیشرفته دانشگاه کالج لندن است. او در استفاده از مدل‌های ریاضی برای مطالعه الگوهای رفتار انسان، از شورش تا خرید، تخصص دارد. فرای به طور مرتب در تلویزیون و رادیو در بریتانیا ظاهر می شود.</p>', '2023-01-26 19:20:26.337605', '2023-01-26 19:20:26.337605', NULL, 'Hannah Fry');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (321, 'استان واتانابه', '<p>کن واتانابه نویسنده ژاپنی است. او قبلاً مشاور McKinsey & Company بود و اکنون در توکیو مستقر است، جایی که شرکت آموزشی، رسانه و سرگرمی خود، Delta Studios را مدیریت می‌کند.</p>', '2023-01-26 19:20:32.437518', '2023-01-26 19:20:32.437518', NULL, 'Ken Watanabe');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (322, 'جانت گلیسون', '<p>جانت گلیسون نویسنده <em>Arcanum</em>، <em>جعبه Grenadillo</em> و <em>The Serpent in the Garden</em> است. او برای دپارتمان نقاشی امپرسیونیستی در ساتبیز کار کرده است و برای مجلات زیادی، به ویژه در مورد عتیقه جات و هنر نوشته است.</p>', '2023-01-26 19:20:37.029035', '2023-01-26 19:20:37.029035', NULL, 'Janet Gleeson');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (323, 'رابرت تی کیوساکی', '<p>رابرت کیوساکی یک سرمایه گذار و کارآفرین با ارزش خالص تخمینی بیش از 80 میلیون دلار است. برند <em>پدر پولدار</em> او بیش از 15 کتاب خودیاری مالی منتشر کرده است که بیش از 26 میلیون نسخه در سراسر جهان فروخته است.</p>', '2023-01-26 19:20:42.07034', '2023-01-26 19:20:42.07034', NULL, 'Robert T. Kiyosaki ');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (324, 'دی جی در قدیمی', '<p>ج. واناس صاحب کسب و کار، سخنران انگیزشی و نویسنده ای است که کاپیتان نیروی هوایی ایالات متحده بود. او از تبار Anishinaabe است و در کتاب های خود از اصول و ایده های بومیان آمریکا استفاده کرده است. او همچنین نویسنده <em>جنگجوی کوچک</em>و <em>روح در حال فرار</em> است.</p>', '2023-01-26 19:20:47.066025', '2023-01-26 19:20:47.066025', NULL, 'D.J. Vanas');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (325, 'کریس گیبو', '<p>کریس گیبو نویسنده، وبلاگ نویس و سخنران است. او <em>استارتاپ 100 دلاری</em> را نوشت که پرفروش‌ترین <em>نیویورک تایمز</em> بود. </em>او همچنین <em>The Art of Non-Conformity</em> را اداره می کند، وبلاگی که در میان 15000 وب سایت پربازدید در ایالات متحده قرار دارد. در سال 2013، او برنامه خود را برای بازدید از تمام کشورهای جهان تکمیل کرد.</p>', '2023-01-26 19:20:51.708294', '2023-01-26 19:20:51.708294', NULL, 'Chris Guillebeau');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (326, 'پتی آزارلو', '<p>پتی آزارلو، مدیر اجرایی، سخنران، نویسنده، مشاور و مشاور، بیش از 25 سال تجربه کار در تغییرات سازمانی دارد. او در سن 33 سالگی جوانترین مدیر کل هیولت پاکارد شد. از آن زمان، او ابتکارات موفق متعددی را برای تحول کسب و کار برای شرکت‌های بزرگ و کوچک رهبری کرده است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (327, 'پل دولان', '<p>پل دولان استاد علوم رفتاری در دانشکده اقتصاد لندن است. او که یک متخصص مشهور جهانی در زمینه رفتار انسان است، نویسنده پرفروش <em>Happiness by Design</em></p> است.', '2023-01-26 19:21:01.366107', '2023-01-26 19:21:01.366107', NULL, 'Paul Dolan');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (328, 'ویل اسمیت با مارک منسون', '<p>ویل اسمیت بازیگر، تهیه کننده و نوازنده است. او دو بار نامزد جایزه اسکار و برنده جایزه گرمی و جایزه NAACP شده است. حرفه او دنیای موسیقی، تلویزیون و فیلم را در بر می گیرد. او بیشتر به خاطر بازی در فیلم هایی مانند <em>پسرهای بد</em>، <em>روز استقلال</em>، <em>مردان سیاهپوش</em> و <em>علاءالدین</em> شناخته شده است. </p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (329, 'جیم دثمر', '<p>جیم دثمر، که با بسیاری از مدیران عامل Fortune 500 کار کرده است، یک سخنران و مربی حرفه ای است. دایانا چپمن، مشاور، با بیش از 700 رهبر سازمانی کار کرده است. کاله وارنر کلمپ یک سخنران حرفه ای و مربی اجرایی تحول آفرین است.</p>', '2023-01-26 19:21:11.989074', '2023-01-26 19:21:11.989074', NULL, 'Jim Dethmer');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (330, 'آلن دی باتن', '<p>آلن دو باتن یک فیلسوف روزمره است. نویسنده کتاب‌های پرفروش متعدد، به موضوعاتی از عشق تا معماری و از پروست تا سفر پرداخته است. او همچنین یکی از بنیانگذاران مدرسه زندگی است، یک موسسه مستقر در لندن که در تلاش برای توسعه اشکال جدید آموزش است.</p>', '2023-01-26 19:21:16.937574', '2023-01-26 19:21:16.937574', NULL, 'Alain De Botton');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (331, 'پیتر گادفری اسمیت', '<p>پیتر گادفری اسمیت دارای مدرک دکترای فلسفه از دانشگاه کالیفرنیا، سن دیگو است. او در حال حاضر هم در دانشگاه سیتی نیویورک و هم در دانشگاه سیدنی تدریس می کند، جایی که در فلسفه تاریخ و زیست شناسی تخصص دارد. کتاب قبلی او، <em>جمعیت‌های داروینی و انتخاب طبیعی</em>، جایزه لاکاتوش 2010 را برای کار برجسته‌ای در زمینه فلسفه علم دریافت کرد.</p>', '2023-01-26 19:21:21.865779', '2023-01-26 19:21:21.865779', NULL, 'Peter Godfrey-Smith');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (332, '99U و Jocelyn K. Glei', '<p>جوسلین کی. گلی سردبیر و مدیر <em>99U</em> است، یک مجله آنلاین که به ارائه نکات خلاقانه در مورد نحوه عملی کردن ایده های خود به مردم اختصاص دارد. علاوه بر این، او همچنین ویرایشگر ادامه این کتاب بود، <em>پتانسیل خود را به حداکثر برسانید</em>.</p>', '2023-01-26 19:21:26.961273', '2023-01-26 19:21:26.961273', NULL, '99U and Jocelyn K. Glei');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (333, 'جف تاف و استیون گلدباخ', '<p>استیون گلدباخ مدیر ارشد استراتژی شرکت مشاوره Deloitte است. جف توف مشاور اصلی در Deloitte است، جایی که او در زمینه پایداری و نوآوری تخصص دارد. گلدباخ و توف با هم کتاب پرفروش <em>منفجر شدن</em></p> را نوشتند.', '2023-01-26 19:27:01.466106', '2023-01-26 19:27:01.466106', NULL, 'Geoff Tuff and Steven Goldbach');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (334, 'جک شفر و ماروین کارلینز', '<p>جک شافر، مامور ویژه سابق اف بی آی، دکترای روانشناسی و استاد در بخش اجرای قانون و مدیریت عدالت دانشگاه ایلینوی غربی است. او همچنین به عنوان یک تحلیلگر رفتاری کار کرده است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (335, 'نیکوس مورکوگیانیس', '<p> نیکوس مورکوگیانیس یک رهبر فکری مشهور بین‌المللی و یک شریک ارشد در موسسه مشاوره نخبگان Panthea است که در آنجا مشاوره‌های تخصصی به مدیران عامل از سراسر جهان ارائه کرده است. Mourkogiannis همچنین سمت‌های تاثیرگذاری را به‌عنوان رئیس چندین شرکت در سطح جهانی داشته است و قبلاً مشاور اجرایی برای رهبری در گروه مشاوره جهانی Booz Allen Hamilton بوده است.</p>', '2023-01-26 19:27:10.860364', '2023-01-26 19:27:10.860364', NULL, 'Nikos Mourkogiannis');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (336, 'داگلاس ون پرات', '<p>داگلاس ون پرات، بنیانگذار نام تجاری ناخودآگاه، یک مشاور استراتژی برند با تمرکز بر علم رفتار است. او معاون اجرایی Deutsch LA بود که در آنجا مسئول حساب فولکس واگن بود. او به خاطر ایجاد آگهی بازرگانی «نیرو» فولکس واگن، با دارث ویدر «مینی» خاطره‌انگیز آن، پر اشتراک‌گذاری‌ترین آگهی در تاریخ Super Bowl، تحسین شده است.</p>', '2023-01-26 19:27:16.045897', '2023-01-26 19:27:16.045897', NULL, 'Douglas van Praet');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (337, 'اسکات برکون', '<p>اسکات برکون نویسنده و سخنران آمریکایی است. او قبلاً روی توسعه اینترنت اکسپلورر در مایکروسافت کار می کرد. آثار او در <em>نیویورک تایمز</em> و <em>واشنگتن پست</em> منتشر شده است، و او تفکر خلاق را در دانشگاه واشنگتن تدریس کرده است.</p>', '2023-01-26 19:27:21.68631', '2023-01-26 19:27:21.68631', NULL, 'Scott Berkun');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (338, 'جو استادول', '<p>جو استودول یک روزنامه‌نگار، وبلاگ‌نویس و سخنران عمومی است که در حال حاضر در دانشگاه کمبریج مدرک دکترای خود را می‌گذراند.</p>', '2023-01-26 19:27:27.289774', '2023-01-26 19:27:27.289774', NULL, 'Joe Studwell');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (339, 'ریچارد داوکینز', '<p>ریچارد داوکینز اخلاق شناس، زیست شناس تکاملی و از اعضای انجمن سلطنتی است. او نویسنده چندین کتاب است که معروف‌ترین آنها <em>ژن خودخواه</em> است که دیدگاه ژن محوری تکامل را رایج کرد.</p>', '2023-01-26 19:27:33.224045', '2023-01-26 19:27:33.224045', NULL, 'Richard Dawkins');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (340, 'هنری کلود و جان تاونسند', '<p>دکتر هنری کلود یک روانشناس بالینی و متخصص رهبری است. دکتر جان تاونسند یک مشاور تجاری، مربی رهبری و روانشناس است. به طور جداگانه، هر کدام چندین کتاب در زمینه رهبری و روانشناسی تألیف کرده اند. آنها با هم از نویسندگان پرفروش‌ترین <em>نیویورک تایمز</em> <em>Boundaries</em>و رهبران مجموعه کارگاه‌های تحسین‌شده GrowthSkills هستند.</p>', '2023-01-26 19:27:43.011285', '2023-01-26 19:27:43.011285', NULL, 'Henry Cloud and John Townsend');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (341, 'Thich Nhat Hanh', '<p>Thich Nhat Hanh یک راهب بودایی ویتنامی بود. او هم معلم معنوی ذهن آگاهی بود که در سراسر جهان شناخته شده بود و هم نویسنده ای پرکار در مقالات، کتاب ها و اشعار. کتاب‌های قبلی او شامل پرفروش‌ترین کتاب‌های <em>خشم: حکمت برای خنک کردن شعله‌ها</em>و <em>معجزه ذهن آگاهی</em></p> است.', '2023-01-26 19:27:47.853028', '2023-01-26 19:27:47.853028', NULL, 'Thich Nhat Hanh');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (342, 'هاروکی موراکامی', '<p>هاروکی موراکامی نویسنده ژاپنی است که بیشتر به خاطر داستان‌های عجیب و غریب خود از جمله رمان‌های پرفروشی مانند <em>چوب نروژی</em>، <em>تواریخ پرنده بادگیر</em> و <em شناخته شده است. >کافکا در ساحل</em>. علاوه بر این، بیش از 40 اثر غیرداستانی از جمله <em>زیرزمینی</em> و <em>پرتره‌ها در جاز</em></p> منتشر شده است.', '2023-01-26 19:27:52.984267', '2023-01-26 19:27:52.984267', NULL, 'Haruki Murakami');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (343, 'اورن کلاف', '<p>اورن کلاف یک بانکدار سرمایه‌گذاری است که در 13 سال گذشته بیش از 400 میلیون دلار سرمایه جذب کرده است و با نرخ دو میلیون دلار در سال به این کار ادامه می‌دهد. او این کار را با روش منحصربه‌فرد خود انجام داده است، روشی که در طول سال‌ها آزمون و خطا پس از خسته شدن از تکنیک‌های فروش ضعیف معمولی که نتیجه‌ای نداشت و بیشتر شبیه التماس به نظر می‌رسید، توسعه داد.</p>', '2023-01-26 19:27:57.792169', '2023-01-26 19:27:57.792169', NULL, 'Oren Klaff');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (344, 'الکس هاچینسون', '<p>الکس هاچینسون روزنامه‌نگار برنده جایزه و سردبیر مجله <em>Outside </em> است. آثار او همچنین در <em>نیویورکر</em>، <em>نیویورک تایمز</em>، <em> Globe and Mail</em>و <em>Runner''s World</em به نمایش درآمده است. > او با مدرک دکترای فیزیک از دانشگاه کمبریج، و همچنین اشتیاق واقعی به فضای باز و دویدن، واجد شرایط منحصر به فرد برای تحقیق در مورد علم پشت تناسب اندام و استقامت است.</p>', '2023-01-26 19:28:03.77308', '2023-01-26 19:28:03.77308', NULL, 'Alex Hutchinson');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (345, 'لیلی سینگ', '<p>لیلی سینگ یک کمدین، هنرپیشه و مشهور YouTube است که بیشتر با نام IISuperwomanII، نام کاربری یوتیوب او شناخته می‌شود. کانال یوتیوب او بیش از 13 میلیون مشترک دارد و موفقیت او منجر به تورها و اجراها در سراسر جهان شده است. <em>چگونه باوس باشیم</em> اولین کتاب او است.</p>', '2023-01-26 19:28:08.889302', '2023-01-26 19:28:08.889302', NULL, 'Lilly Singh');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (346, 'کری هاولز', '<p>دکتر کری هاولز نویسنده، مربی و رهبر فکری است که بیش از دو دهه تحقیق، تدریس و تمرین قدردانی کرده است. او نقش قدرتمند سپاسگزاری را در ایجاد روابط شکوفا، یک محیط کاری پر رونق، و جهانی هماهنگ‌تر در گفتگوهای بین‌المللی TEDx و سازمان ملل در میان دیگران مطرح کرده است.</p>', '2023-01-26 19:28:14.066598', '2023-01-26 19:28:14.066598', NULL, 'Kerry Howells');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (347, 'ویرایش ماسیمو پیگلیوچی', '<p>Massimo Pigliucci، Skye C. Cleary و Daniel A. Kaufman همگی فیلسوفانی هستند که مقیم ایالات متحده هستند. پیگلیوچی در ابتدا به عنوان یک دانشمند آموزش دید و قبل از اینکه دکترای دوم را در فلسفه انجام دهد، کار کرد و اکنون در مورد رواقی گرایی می نویسد. کلیری یک متخصص اگزیستانسیالیسم است و کافمن یک استاد فلسفه است که فصل این کتاب را در مورد ارسطویی نویسی کرده است.</p>', '2023-01-26 19:28:19.463541', '2023-01-26 19:28:19.463541', NULL, 'ed. Massimo Pigliucci');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (348, 'کریستوفر لیهان', '<p>بیل گوتنتاگ کارگردان برنده اسکار برنامه های متعددی برای شبکه های تلویزیونی از جمله ABC و HBO و مستندهایی از جمله <em>Nanking </em>و <em>Soundtrack است. </em>او همچنین یک مدرس در دانشکده تحصیلات تکمیلی دانشگاه استنفورد است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (349, 'دن سنور و سائول سینگر', '<p>دان سنور نویسنده، مشاور سیاسی و عضو ارشد مطالعات خاورمیانه در شورای روابط خارجی است. او سخنگوی ارشد حکومت موقت ائتلاف در عراق بود، سفرهای زیادی به خاورمیانه داشته و در اسرائیل و در مدرسه بازرگانی هاروارد تحصیل کرده است. او اغلب در <em>وال استریت ژورنال</em> همکاری می کند و برای <em>نیویورک تایمز</em> و <em>تایم</em> نوشته است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (350, 'چرا فورکیس؟', '<p>کن فورکیش پس از 20 سال حرفه، دنیای فناوری را پشت سر گذاشت تا دوباره به عنوان نانوایی آموزش ببیند، و او اکنون نانوایی Ken''s Artisan Bakery و همچنین Ken''s Artisan Pizza را در پورتلند، اورگان اداره می کند. <em>مخمر نمک آب آرد</em> اولین کتاب برنده جایزه او بود و از آن زمان او <em>عناصر پیتزا</em> را نوشت.</p>', '2023-01-26 19:28:36.624845', '2023-01-26 19:28:36.624845', NULL, 'Ken Forkish');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (351, 'سایمون سینک', '<p>سایمون سینک یک خوش‌بین است که مصمم به خلق آینده‌ای بهتر و روشن‌تر برای بشریت است. Sinek یک سخنران و مربی تأثیرگذار، به سازمان هایی در سراسر جهان مانند مایکروسافت، امریکن اکسپرس، سازمان ملل متحد و پنتاگون کمک کرده است تا به کارکنان خود الهام بخشند. او همچنین نویسنده <em>رهبران آخرین غذا خوردن</em> و <em>با هم بهتر است</em> است.</p>', '2023-01-26 19:28:42.71917', '2023-01-26 19:28:42.71917', NULL, 'Simon Sinek');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (352, 'گیل هاسون', '<p>دونا باتلر یک روان درمانگر یکپارچه و متخصص تروما است که بیش از 30 سال در سرویس بهداشت ملی بریتانیا کار کرده است. گیل هاسون، نویسنده، بیش از 20 کتاب در مورد رشد شخصی، سلامت روان و رفاه نوشته است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (353, 'کوین کروزه', '<p>کوین کروز نویسنده <em>نیویورک تایمز</em> پرفروش‌ترین کتاب شش کتاب است، از جمله <em>Eployee Engagement 2.0</em>و <em>15 راز که افراد موفق درباره مدیریت زمان می‌دانند. em>. کارآفرین سریال و میزبان پادکست <em>LEADx Leadership</em>، Kruse آموزش رهبری را در 192 کشور از طریق پلتفرم آموزش آنلاین رایگان خود، LEADx Academy ارائه می‌دهد.</p>', '2023-01-26 19:28:58.047895', '2023-01-26 19:28:58.047895', NULL, 'Kevin Kruse');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (354, 'نت باکل', '<p>صفی باهکال یک فیزیکدان و کارآفرین زیستی است. او در سال 1995 دکترای خود را از استنفورد دریافت کرد و به عنوان همکار میلر در رشته فیزیک به فعالیت علمی خود در دانشگاه برکلی ادامه داد. پس از یک دوره سه ساله در شرکت مشاوره مک کینزی، او یکی از بنیانگذاران Synta Pharmaceuticals، یک شرکت بیوتکنولوژی متخصص در توسعه داروهای جدید برای درمان سرطان بود. <em>Loonshots</em>، اولین کتاب باکال، توسط <em>واشنگتن پست</em>، <em>Inc</em>و <em>Business Insider</em> به عنوان یک عنوان خواندنی معرفی شده است. >.</p>', '2023-01-26 19:29:04.027357', '2023-01-26 19:29:04.027357', NULL, 'Safi Bahcall');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (355, 'باب گاف', '<p>باب گاف نویسنده، سخنران عمومی و وکیل حرفه ای است. کتاب های قبلی او شامل دو کتاب پرفروش <em>نیویورک تایمز</em> بود -<em>عشق می کند </em>و <em>همه، همیشه</em>. او همچنین بنیانگذار Love Does است، یک سازمان غیرانتفاعی که حقوق بشر و آموزش را در مناطق درگیری جهانی ترویج می کند. Goff در حال حاضر در کالیفرنیا مستقر است.</p>', '2023-01-26 19:29:09.512003', '2023-01-26 19:29:09.512003', NULL, 'Bob Goff');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (356, 'جوکو ویلینک و لیف بابین', '<p>جوکو ویلینک و لیف بابین دو افسر سابق نیروی دریایی SEAL و از بنیانگذاران Echelon Front، یک سازمان آموزش رهبری هستند. <em>دوگانگی رهبری</em>اصولی را که در اولین کتاب خود، پرفروش‌ترین <em>مالکیت افراطی، بیان کرده‌اند، گسترش داده و بهبود می‌بخشد. </em>Willink همچنین میزبان پادکست با رتبه برتر <em>پادکست Jocko</em></p> است.', '2023-01-26 19:29:15.041424', '2023-01-26 19:29:15.041424', NULL, 'Jocko Willink & Leif Babin');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (357, 'دیوید ژرمن', '<p>دیوید دویچ یک محقق بسیار تأثیرگذار در زمینه فیزیک کوانتومی است. او در آکسفورد زندگی و کار می کند و از سال 1999 استاد مدعو فیزیک بوده است. در سال 1998، دویچ جایزه و مدال مؤسسه فیزیک پل دیراک را که یکی از برترین جوایز فیزیک نظری است، دریافت کرد.</p>', '2023-01-26 19:29:20.823747', '2023-01-26 19:29:20.823747', NULL, 'David Deutsch');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (358, 'وال مک درمید', '<p>وال مک‌درمید یک رمان‌نویس جنایی برنده جوایز است که کار خود را به عنوان رئیس دفتر یک روزنامه ملی بریتانیا آغاز کرد. رمان های پرفروش تونی هیل او الهام بخش مجموعه تلویزیونی محبوب بریتانیا <em>Wire in the Blood</em> بودند.</p>', '2023-01-26 19:29:26.839342', '2023-01-26 19:29:26.839342', NULL, 'Val McDermid');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (359, 'جیم کالینز و مورتن تی هانسن', '<p>جیم کالینز یک مشاور تجاری و نویسنده بسیاری از پرفروش‌ها از جمله <em>از خوب تا عالی</em>و <em>ساخت تا آخر است. </em>کتاب‌های او بیش از ده میلیون نسخه در سراسر جهان فروخته است. او اکنون یک آزمایشگاه مدیریت دارد که در آن تحقیق و تدریس می کند.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (360, 'دن همپتونز', '<p>دان همپتون یک نویسنده پرفروش <em>نیویورک تایمز</em> است که به مدت 20 سال در نیروی هوایی ایالات متحده خدمت کرد و به یک افسر بسیار برجسته، با قلب بنفش و چهار صلیب پرنده برجسته تبدیل شد. کتاب های قبلی او عبارتند از <em>خلبان افعی</em> و <em>قاتلان شکارچی</em>.</p>', '2023-01-26 19:29:37.974443', '2023-01-26 19:29:37.974443', NULL, 'Dan Hampton');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (361, 'کالین ارنستروم و آلیشا ال بروس', '<p>کالین ارنستروم دارای دکترای روانشناسی است که در حال حاضر در دپارتمان امور کهنه سربازان در دنور، کلرادو کار می کند، جایی که در درمان پذیرش و تعهد (ACT) و همچنین درمان شناختی رفتاری (CBT) تخصص دارد.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (362, 'دالایلاما', '<p>حضرت دالایی لاما برنده جایزه صلح نوبل و رهبر معنوی مردم تبت است. او از زمانی که نیروهای چینی در سال 1959 به تبت حمله کردند و آن را ضمیمه کردند، در دارمسالا، هند در تبعید زندگی می کرد و تا زمان بازنشستگی خود در سال 2011 به عنوان رئیس دولت تبت فعالیت می کرد.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (363, 'گای راز', '<p>روزنامه نگار گای راز مجری برنامه <em>How I Built This</em> است، یک برنامه رادیویی عمومی ملی که در آن با کارآفرینان موفق در مورد مسیرهای موفقیت آنها مصاحبه می کند. او همچنین خالق یا همکار چهار برنامه دیگر است. در مجموع، نمایش های او توسط 19 میلیون نفر در ماه شنیده می شود.</p>', '2023-01-26 19:29:55.710628', '2023-01-26 19:29:55.710628', NULL, 'Guy Raz');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (364, 'سوزان کین', '<p> سوزان کین نویسنده و مدرس است که سخنرانی TED او در مورد قدرت درونگراها بیش از 40 میلیون بار دیده شده است. کتاب بعدی او، <em>آرام: قدرت درونگراها در دنیایی که نمی تواند از حرف زدن دست بکشد، </em>بیش از 2 میلیون نسخه فروخته و به 30 زبان ترجمه شده است.</p>', '2023-01-26 19:30:00.652465', '2023-01-26 19:30:00.652465', NULL, 'Susan Cain');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (365, 'توماس اس. کوهن', '<p>توماس کوهن (1922-1996) یک فیزیکدان، فیلسوف و مورخ بسیار تأثیرگذار بود. معروف ترین اثر او، <em>ساختار انقلاب های علمی، </em>نحوه تفکر ما را در مورد تاریخ علم تغییر داد.</p>', '2023-01-26 19:30:06.320495', '2023-01-26 19:30:06.320495', NULL, 'Thomas S. Kuhn');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (366, 'جنیفر بی. کانویلر', '<p>جنیفر بی. کانویلر، متخصص یادگیری و توسعه، متخصص درونگراها است. او به سازمان هایی مانند جنرال الکتریک و ناسا مشاوره داده است. Kahnweiler دارای مدرک Ph.D. در مشاوره و توسعه سازمانی و دارای گواهی حرفه ای صحبت کردن (CSP) است. <em>نابغه مخالفان</em> سومین کتاب پرفروش او است.</p>', '2023-01-26 19:30:11.254702', '2023-01-26 19:30:11.254702', NULL, 'Jennifer B. Kahnweiler');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (367, 'الیزابت دان و مایکل نورتون', '<p>الیزابت دان دانشیار روانشناسی در دانشگاه بریتیش کلمبیا در ونکوور است. کارهای او در مجلات برتر دانشگاهی و صدها رسانه در سراسر جهان به نمایش درآمده است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (368, 'استفانی کی جانسون', '<p>دکتر استفانی کی جانسون دانشیار دانشکده بازرگانی لیدز، دانشگاه کلرادو بولدر است، جایی که به دانشجویان در مورد رهبری و فراگیری آموزش می دهد. او یکی از همکاران مکرر در <em>Harvard Business Review</em> بوده است و آثار او نیز توسط <em>وال استریت ژورنال</em>، <em>Newsweek</em> و <em منتشر شده است. > اقتصاددان</em>.</p>', '2023-01-26 19:30:22.272521', '2023-01-26 19:30:22.272521', NULL, 'Stefanie K. Johnson');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (369, 'آلیس بی توکلاس', '<p>آلیس بی توکلاس به خاطر نقش او در آوانگارد پاریس در دهه‌های 1920 و 30 و همچنین کتاب‌ها و نامه‌های متعددش به یاد می‌آید. او شریک زندگی نویسنده گرترود استاین بود که نزدیک به 40 سال با او زندگی، سفر و سرگرمی داشت.</p>', '2023-01-26 19:30:27.526437', '2023-01-26 19:30:27.526437', NULL, 'Alice B. Toklas');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (396, 'دانکن کلارک', '<p>دانکن کلارک بیش از 20 سال تجربه به عنوان یک بانکدار سرمایه گذاری در چین دارد، جایی که یاد گرفته به زبان ماندارین روان صحبت کند. در تمام این مدت، او توسعه شرکت‌های مبتنی بر اینترنت در چین را دنبال کرده است و با بنیانگذار علی‌بابا، جک ما، به خوبی آشنا شده است.</p>', '2023-01-26 19:33:11.808385', '2023-01-26 19:33:11.808385', NULL, 'Duncan Clark');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (370, 'جیسون دبلیو ووماک', '<p>Jason W. Womack سخنران و مربی تحسین شده مدیران عامل، مدیران، کارمندان و کارآفرینان است. او بیش از 1200 کارگاه آموزشی عملکرد در محل کار در سراسر جهان برگزار کرده است و توصیه های تخصصی خود را در مورد چگونگی کار هوشمندانه تر و افزایش عملکرد به اشتراک گذاشته است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (371, 'برایان سولیس', '<p>برایان سولیس یک تحلیلگر و سخنران دیجیتال مشهور جهانی است. او نزدیک به 30 سال را صرف مطالعه تأثیر فناوری بر جامعه و تجارت کرده است و به استارت‌آپ‌ها و برندهای برتر کمک کرده است تا استراتژی‌های تحول دیجیتال و نوآوری را توسعه دهند. سولیس نویسنده هشت کتاب پرفروش است، از جمله <em>آینده تجارت چیست</em> و <em>پایان تجارت طبق معمول</em>.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (372, 'جفری ساکس', '<p>در سن 28 سالگی، جفری ساکس در دانشگاه هاروارد به عنوان استادی در اقتصاد اعطا شد. اکنون او مؤسسه زمین را در دانشگاه کلمبیا اداره می کند و به عنوان مشاور ویژه در اهداف توسعه هزاره دبیر کل سازمان ملل متحد خدمت می کند.</p>', '2023-01-26 19:30:45.489252', '2023-01-26 19:30:45.489252', NULL, 'Jeffrey Sachs');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (373, 'مایک ویکینگ', '<p>Meik Wiking مدیر عامل موسسه تحقیقات شادی در کپنهاگ است. پس از تحصیل در سیاست و تجارت، به رفاه و کیفیت زندگی علاقه مند شد. او چندین کتاب نوشته و سخنرانی های عمومی در سراسر جهان در مورد این موضوعات دارد.</p>', '2023-01-26 19:30:50.539193', '2023-01-26 19:30:50.539193', NULL, 'Meik Wiking');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (374, 'گری ال توماس', '<p>کار گری توماس بر این تمرکز دارد که چگونه می توان حکمت متون مقدس را در زندگی مدرن ما ادغام کرد. او استاد حوزه علمیه غربی در پورتلند، اورگان است. نویسنده چندین کتاب؛ و یک مهمان مکرر در پادکست <em>FamilyLife Today</em>.</p>', '2023-01-26 19:30:55.375744', '2023-01-26 19:30:55.375744', NULL, 'Gary L. Thomas');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (375, 'جیسون فانگ', '<p> جیسون فانگ متخصص کلیه و رئیس برنامه مدیریت رژیم غذایی فشرده در بیمارستان اسکاربرو در انتاریو، کانادا است. فانگ، متخصص معروف دیابت نوع 2 و چاقی، نویسنده <em>کد دیابت</em>، <em>راه حل طول عمر</em>و <em>راهنمای کامل روزه‌داری</em> است. em>.</p>', '2023-01-26 19:31:00.110302', '2023-01-26 19:31:00.110302', NULL, 'Jason Fung');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (376, 'مینال بوپایا', '<p>مینال بوپایا سخنران، نویسنده و استراتژیست است که انگیزه اش اشتیاق مادام العمر برای ایجاد دنیایی فراگیرتر و عادلانه تر است. او بنیانگذار شرکت استراتژی و طراحی Brevity & Wit است که سازمان‌ها را از طریق فرآیند وارد کردن تنوع، دسترسی و انصاف در ساختارها و فرآیندهایشان راهنمایی می‌کند. Bopaiah به طور مرتب برای سخنرانی در کنفرانس‌ها دعوت می‌شود و مهمان پادکست‌ها و برنامه‌های رادیویی متعددی از جمله نمایش Kojo Nnamdi بوده است.</p>', '2023-01-26 19:31:05.963582', '2023-01-26 19:31:05.963582', NULL, 'Minal Bopaiah');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (377, 'رنگان چاترجی', '<p>دکتر Rangan Chatterjee<strong> </strong>یک پزشک بریتانیایی است. او نویسنده پرفروش سه کتاب قبلی از جمله <em>طرح چهار ستون است. </em>او همچنین در سریال تلویزیونی پرطرفدار BBC One <em>Doctor in the House</em></p> بازی می‌کند.', '2023-01-26 19:31:11.482995', '2023-01-26 19:31:11.482995', NULL, 'Rangan Chatterjee');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (378, 'بیلی هالیدی با ویلیام دافتی', '<p>بیلی هالیدی یکی از تاثیرگذارترین خوانندگان تاریخ موسیقی آمریکا بود. او با ویلیام اف. دافتی، روزنامه نگار و سردبیر روزنامه که با یکی از بهترین دوستانش ازدواج کرده بود، <em>Lady Sings the Blues</em> را نوشت.</p>', '2023-01-26 19:31:16.706442', '2023-01-26 19:31:16.706442', NULL, 'Billie Holiday with William Dufty');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (379, 'نیک ماگیولی', '<p>نیک ماگیولی، افسر عملیاتی و دانشمند داده در مدیریت ثروت Ritholtz است. او همچنین نویسنده <em>دلارها و داده ها</em> است، یک وبلاگ محبوب که نگاهی مبتنی بر داده به امور مالی شخصی دارد. مگیولی در مورد پول برای <em>وال استریت ژورنال</em>، <em>لس آنجلس تایمز</em> و CNBC نوشته است. </p>', '2023-01-26 19:31:21.742878', '2023-01-26 19:31:21.742878', NULL, 'Nick Maggiulli');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (380, 'جیسون گدیس', '<p>جیسون گدیس متخصص تعارضات بین فردی و حل آن است. بنیانگذار Relationship School، او همچنین نویسنده و سخنران است و <em>پادکست زوج هوشمند</em> را میزبانی می کند.</p>', '2023-01-26 19:31:26.762594', '2023-01-26 19:31:26.762594', NULL, 'Jayson Gaddis');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (381, 'جیمز مارتین', '<p>کشیش جیمز مارتین یک کشیش، الهی‌دان و نویسنده چندین کتاب پرفروش <em>نیویورک تایمز</em> در مورد دین است، از جمله <em>عیسی: یک زیارت</em>و <em> راهنمای یسوعی برای (تقریباً) همه چیز</em>. مارتین که فارغ‌التحصیل مدرسه بازرگانی وارتون بود، در سن 27 سالگی به یسوعی‌ها پیوست. او به طور مکرر در رسانه‌هایی مانند <em>وال استریت ژورنال</em>، NPR و <em>The Colbert Report همکاری می‌کند. /em>. </p>', '2023-01-26 19:31:31.956539', '2023-01-26 19:31:31.956539', NULL, 'James Martin');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (382, 'درموت کراولی', '<p>درموت کرولی یک مربی، سخنران، رهبر فکری و متخصص بهره‌وری با بیش از بیست سال تجربه در صنعت بهره‌وری است. او مدیر Adapt Productivity، یک شرکت آموزشی مستقر در سیدنی است که او در سال 2002 تأسیس کرد. او همچنین نویسنده پرفروش‌ترین راهنمای بهره‌وری شخصی <em>Smart Work</em>(2016) است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (383, 'خشت شیرکی', '<p>کلی شیرکی در مورد اینکه چگونه اینترنت بر جامعه تأثیر می گذارد، آموزش می دهد و مشاوره می دهد. او در حال حاضر دانشیار برنامه ارتباطات تعاملی دانشگاه نیویورک و دپارتمان روزنامه نگاری است. او برای لگو، نیروی دریایی ایالات متحده، بی‌بی‌سی و پراکتر اند گمبل مشاوره کرده است و آثارش در <em>The</em> <em>New</em> <em>York</em> <em>Times منتشر شده است. </em>، <em>وال</em> <em>خیابان</em> <em>ژورنال</em> و مجله <em>Wired</em>.</p>', '2023-01-26 19:31:53.084677', '2023-01-26 19:31:53.084677', NULL, 'Clay Shirky');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (384, 'کریگ ال. بورون', '<p>Craig Bowron، MD، یک پزشک متخصص در سلامت مردان و پزشکی داخلی است. او نویسنده ای برای مایو کلینیک است و مقالاتی برای <em>Forbes</em>، <em>Slate</em>، و <em>واشنگتن پست</em> و غیره نوشته است. این اولین کتاب او است.</p>', '2023-01-26 19:31:59.295525', '2023-01-26 19:31:59.295525', NULL, 'Craig L. Bowron');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (385, 'هیو مک لئود', '<p>هیو مک‌لئود بیش از یک دهه به‌عنوان یک کپی‌رایتر تبلیغاتی کار کرد، در حالی که پشت کارت‌های ویزیت کار می‌کرد. اکنون او یک کاریکاتوریست، وبلاگ نویس، سخنران عمومی، نویسنده پرفروش و کارآفرین است.</p>', '2023-01-26 19:32:05.342646', '2023-01-26 19:32:05.342646', NULL, 'Hugh MacLeod');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (386, 'دالاس هارتویگ و ملیسا هارتویگ', '<p>ملیسا هارتویگ یک متخصص تغذیه ورزشی است که در چندین نشریه از جمله <em>The</em> <em>وال استریت ژورنال</em> معرفی شده است. دالاس هارتویگ یک فیزیوتراپیست و متخصص تغذیه ورزشی است. <em>با غذا شروع می‌شود</em> دومین کتاب پرفروش آنهاست.<strong><br></strong></p>', '2023-01-26 19:32:10.159643', '2023-01-26 19:32:10.159643', NULL, 'Dallas Hartwig and Melissa Hartwig');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (387, 'آرنولد شوارتزنگر', '<p>آرنولد شوارتزنگر فرماندار سابق کالیفرنیا، یکی از مشهورترین ستاره های هالیوود و قهرمان بین المللی بدنسازی است.</p>', '2023-01-26 19:32:15.040404', '2023-01-26 19:32:15.040404', NULL, 'Arnold Schwarzenegger');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (388, 'برایان کریستین و تام گریفیث', '<p>برایان کریستین نویسنده پرفروش و سخنران مشهوری است که در علوم شناختی تخصص دارد. آثار او برنده جوایز متعددی شده و آکادمی شاعران آمریکایی از او تجلیل شده است. او همچنین در <em>The New Yorker</em>،<em> Wired</em>، <em>The Guardian</em> و بسیاری از مجلات علمی همکاری دارد.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (389, 'آن هندلی', '<p>آن هندلی که در <em>Forbes</em> به‌عنوان تأثیرگذارترین زن در رسانه‌های اجتماعی ذکر شده، ستون‌نویس مجله <em>Entrepreneur</em>و مدیر ارشد محتوای <em>Profs Marketing</em> است. em>. او همچنین یکی از نویسندگان کتاب پرفروش <em>قوانین محتوا</em> است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (390, 'دیوید باخ و جان دیوید مان', '<p>دیوید باخ نویسنده و کارشناس مالی پرفروش است. او 9 کتاب پرفروش <em>نیویورک تایمز</em>، از جمله <em>میلیونر خودکار را نوشته است. </em>او به طور منظم در تعدادی از رسانه‌ها از جمله NBC، ABC، CNN و نمایش اپرا وینفری مشارکت می‌کند. از دسامبر 2018، شرکت مشاوره سرمایه گذاری او AE Wealth Management بیش از شش میلیارد دلار دارایی دارد.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (391, 'تیم فریس', '<p>تیم فریس یک سرمایه گذار و مشاور موفق برای استارت آپ های فناوری است. او در ایجاد شرکت‌هایی مانند اوبر، فیس‌بوک و علی‌بابا نقش داشته است. او همچنین خالق یک مجموعه پادکست معروف، <em>The Tim Ferriss Show</em> است. از دیگر کتاب‌های او می‌توان به <em>قبیله مربیان</em> و <em>ابزار تایتان‌ها</em> اشاره کرد.</p>', '2023-01-26 19:32:39.35161', '2023-01-26 19:32:39.35161', NULL, 'Tim Ferriss');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (392, 'کارل ریچاردز', '<p>کارل ریچاردز، برنامه‌ریز مالی معتبر، مدیر آموزش سرمایه‌گذاران BAM ALLIANCE، گروهی متشکل از بیش از 130 مشاور مستقل مدیریت ثروت است. او به <em>نیویورک تایمز</em> کمک کرده است و در Marketplace Money، Oprah.com و Forbes.com حضور داشته است.</p>', '2023-01-26 19:32:48.321959', '2023-01-26 19:32:48.321959', NULL, 'Carl Richards');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (393, 'دیوید آلن', '<p>دیوید آلن نویسنده و مشاوری است که در مدیریت موثر زمان تخصص دارد. روش بهره وری او <em>انجام کارها</em> شاگردانی را از بسیاری از اقشار جامعه، به ویژه در محل کار و کسب و کار، جذب کرد. او به مشتریان فردی و سازمانی مشاوره می دهد و به آنها قدرت می دهد تا از زمان خود بهترین استفاده را ببرند.</p>', '2023-01-26 19:32:52.973473', '2023-01-26 19:32:52.973473', NULL, 'David Allen');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (394, 'جو ناوارو', '<p>جو ناوارو بیش از 25 سال تجربه به عنوان یک پروفایل جنایی برای اداره تحقیقات فدرال دارد. او همچنین نویسنده کتاب پرفروش <em>چه بدنی می گوید: راهنمای مامور سابق اف بی آی برای افراد تندخوان</em> است.</p>', '2023-01-26 19:33:01.676473', '2023-01-26 19:33:01.676473', NULL, 'Joe Navarro');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (395, 'ملکه افوا', '<p>ملکه آفوا نویسنده پرفروش <em>نیویورک تایمز</em>، پزشک سلامت جامع، مربی سلامتی، و پیشگام در جنبش غذای سبز است. او خط تولید Heal Thyself و برنامه Sacred Woman Rites of Passage را تأسیس کرد و مدیر عامل مرکز سلامتی Queen Afua است.</p>', '2023-01-26 19:33:06.879333', '2023-01-26 19:33:06.879333', NULL, 'Queen Afua');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (397, 'بیل برنت', '<p>بیل برنت مدیر اجرایی برنامه طراحی دانشگاه استنفورد است و قبلاً به عنوان طراح در اپل کار می کرد. دیو ایوانز یکی از مدیران آزمایشگاه طراحی استانفورد و یکی از بنیانگذاران شرکت طراحی سرگرمی الکترونیک آرتز است. برنت و ایوانز همچنین از نویسندگان پرفروش شماره یک <em>نیویورک تایمز</em>، <em>طراحی زندگی شما</em> هستند.</p>', '2023-01-26 19:33:16.809068', '2023-01-26 19:33:16.809068', NULL, 'Bill Burnett');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (398, 'سالی هلگسن و مارشال گلداسمیت', '<p>سالی هلگسن یک سخنران اصلی و متخصص در موضوع رهبری زنان است. او به شرکت‌هایی مانند مایکروسافت، هیولت پاکارد و آی‌بی‌ام مشاوره داده است و کارهای او در <em>نیویورک تایمز</em> به نمایش درآمده است. مارشال گلداسمیت نویسنده و مربی اجرایی پرفروش <em>نیویورک تایمز</em> است. کتاب <em>Triggers</em>او در سال 2015 به عنوان بهترین کتاب تجاری سال آمازون انتخاب شد.</p>', '2023-01-26 19:33:21.851745', '2023-01-26 19:33:21.851745', NULL, 'Sally Helgesen and Marshall Goldsmith');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (399, 'فیصل هوک و دریک بائر', '<p> فیصل هوک کارآفرینی است که MiND2MiND Exchange و B2B ForeSight را تأسیس کرده است. او برای <em>The</em> <em>Wall Street Journal</em>، <em>Fast Company</em>، <em>Huffington Post</em> و <em>Forbes< مقالات نوشته است. /em>. او همچنین توسط <em>Ziff-Davis Enterprise به عنوان یکی از 100 فرد برتر با نفوذ در فناوری انتخاب شد. </em></p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (400, 'راب شالنبرگر و استیو شالنبرگر', '<p>استیو شالنبرگر موسس و رئیس شرکت آموزشی Becoming Your Best Global Leadership است. او همچنین به ایجاد مرکز رهبری استفن آر کاوی کمک کرد.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (401, 'جیسون دبلیو ووماک و جودی ووماک', '<p>جودی و جیسون دبلیو ووماک یک تیم زن و شوهر با 20 سال تجربه مشاوره تجاری از طریق شرکت خود، شرکت جیسون ووماک هستند. جیسون یک رهبر تجاری و مربی متخصص در مدیریت زمان و انگیزه و همچنین توسعه شخصی و حرفه ای است. جودی یک فعال برای زنان در تجارت و بنیانگذار شبکه کسب و کار زنان No More Nylons است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (402, 'فیلیپا پری', '<p>فیلیپا پری یک روان درمانگر و نویسنده بریتانیایی است. کتاب‌های قبلی او عبارتند از <em>داستان کاناپه: داستان گرافیکی روان‌درمانی </em>(2010) و <em>چگونه سالم بمانیم</em> (2012).</p>', '2023-01-26 19:33:46.207737', '2023-01-26 19:33:46.207737', NULL, 'Philippa Perry');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (403, 'ساچین خواجور', '<p>ساچین خواجوریا بیش از 25 سال تجربه در بخش مالی و سرمایه گذاری دارد. او شریک سابق آپولو - یکی از بزرگ‌ترین شرکت‌های مدیریت دارایی در جهان - و بنیان‌گذار کسب‌وکار سرمایه‌گذاری خصوصی Achilles Management است.</p>', '2023-01-26 19:33:50.950585', '2023-01-26 19:33:50.950585', NULL, 'Sachin Khajuria');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (404, 'تیموتی ویلیامسون', '<p>تیموتی ویلیامسون استاد منطق در دانشگاه آکسفورد و A. Whitney Griswold استاد مدعو فلسفه در دانشگاه ییل است. او چندین کتاب منتشر کرده است و بسیاری از آنها از جمله <em>فلسفه فلسفه</em> به زبان های دیگر ترجمه شده است<em>.</em> او همچنین در انتشارات مهمی از جمله <em> همکاری داشته است. مکمل ادبی تایمز</em> و <em>نیویورک تایمز</em>.</p>', '2023-01-26 19:33:56.19627', '2023-01-26 19:33:56.19627', NULL, 'Timothy Williamson');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (405, 'زینا ساچ و پاتریک مالون', '<p>زینا ساچ یکی از اعضای هیئت علمی برنامه های رهبری اجرایی کلیدی در دانشکده روابط عمومی در دانشگاه آمریکایی است که در آن دوره های رهبری، تیم سازی و برنامه ریزی جانشین پروری را تدریس می کند. او پیش از این در مدارس دولتی و خصوصی تدریس می‌کرد، به عنوان مدیر مدرسه دانش‌آموزان دارای اختلالات عاطفی و رفتاری، و معاون معاون دفتر مدیریت پرسنل بود.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (406, 'ارین لوری', '<p>ارین لوری نویسنده ای مقیم نیویورک و نویسنده دو کتاب در زمینه امور مالی شخصی است. لوری که به‌خاطر توصیه‌های بی‌معنی‌اش شناخته می‌شود، مهمان دائمی CBS Sunday Morning، CNBC و Fox & Friends است. او همچنین در مورد پول برای <em>Fast Company</em>، <em>Cosmopolitan</em> و <em>Refinery29</em> نوشته است. </p>', '2023-01-26 19:34:06.887476', '2023-01-26 19:34:06.887476', NULL, 'Erin Lowry');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (407, 'جینی دیتریش', '<p>جینی دیتریش شرکت بازاریابی و ارتباطات آرمنت دیتریش را تأسیس کرد. او همچنین بنیانگذار Spin Sucks Pro است که به متخصصان روابط عمومی و بازاریابی مشاوره می دهد. مشتریان او عبارتند از BASF، Bayer، Abbott و Sprint.</p>', '2023-01-26 19:34:12.72421', '2023-01-26 19:34:12.72421', NULL, 'Gini Dietrich');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (408, 'دیوید چانگ', '<p>دیوید چانگ یک سرآشپز، شخصیت تلویزیونی و بنیانگذار گروه رستوران موموفوکو است.</p>', '2023-01-26 19:34:17.871011', '2023-01-26 19:34:17.871011', NULL, 'David Chang');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (409, 'مایکل هریس', '<p>مایکل هریس کهنه کار وال استریت، بنیانگذار و مدیر عامل Insight Demand، یک شرکت آموزش فروش است.</p>', '2023-01-26 19:34:23.59644', '2023-01-26 19:34:23.59644', NULL, 'Michael Harris');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (410, 'سوخیندر سینگ کاسیدا', '<p> Sukhinder Singh Cassidy یک مدیر عامل و کارآفرین پیشرو در فناوری با چندین دهه تجربه در تأسیس، ساخت و هدایت شرکت‌هایی مانند Google، Stubhub، Amazon و غیره است. او بنیانگذار و رئیس فعلی TheBoardlist است، بازاری که کسب‌وکارها را به مجموعه‌ای از استعدادهای در حال رشد و متنوع متصل می‌کند.</p>', '2023-01-26 19:34:29.623609', '2023-01-26 19:34:29.623609', NULL, 'Sukhinder Singh Cassidy');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (411, 'گری چپمن', '<p>گری چپمن نویسنده، سخنران عمومی و مشاوری است که در کمک به زوج ها برای غلبه بر ناملایمات عاشقانه و بهبود ازدواجشان تخصص دارد. کار قبلی او شامل پرفروش‌ترین <em>پنج زبان عشق</em> است.</p>', '2023-01-26 19:34:35.516903', '2023-01-26 19:34:35.516903', NULL, 'Gary Chapman');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (412, 'برایان تریسی', '<p>برایان تریسی یک سخنران انگیزشی و نویسنده خودیاری است. او نویسنده بیش از 80 کتاب و مدیر عامل شرکت بین المللی برایان تریسی، یک شرکت آموزش توسعه رهبری است.</p>', '2023-01-26 19:34:41.70516', '2023-01-26 19:34:41.70516', NULL, 'Brian Tracy');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (413, 'وقاص احمد', '<p>وقاص احمد مدیر هنری مجموعه خلیلی است و در حال تحصیل در رشته علوم اعصاب در کینگز کالج لندن است. علاوه بر این، او به عنوان روزنامه نگار و سردبیر کار کرده و سفرهای زیادی داشته است. </p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (414, 'سانی بونل و اشلی هانسبرگر', '<p>سانی بونل و اشلی هانسبرگر بنیانگذاران Motto، یک آژانس برندسازی دیجیتال برنده جایزه هستند. رویکرد پویای آن‌ها به کسب‌وکار پوشش مثبتی برای آنها در همه جا از <em>Chicago Tribune</em> و <em>Forbes</em> گرفته تا<em> Huffington Post</em> و <em>Wall Street Journal داشته است. </em>.</p>', '2023-01-26 19:34:51.776829', '2023-01-26 19:34:51.776829', NULL, 'Sunny Bonnell and Ashleigh Hansberger');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (415, 'سوزه اورمان', '<p>سوزه اورمن سرمایه‌دار است که کار خود را با بازوی سرمایه‌گذاری بانک آمریکا، مریل لینچ آغاز کرد. اورمان نویسنده 9 کتاب پرفروش <em>نیویورک تایمز</em> در زمینه امور مالی شخصی، دو جایزه امی را برای کار خود به عنوان مجری تلویزیون دریافت کرده است و به عنوان یکی از 100 زن قدرتمند جهان توسط <em>Forbes رتبه بندی شده است. </em>. او همچنین یکی از سردبیران <em>O, The Oprah Magazine</em> است. </p>', '2023-01-26 19:34:56.766397', '2023-01-26 19:34:56.766397', NULL, 'Suze Orman');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (416, 'ناودان آوریل', '<p>آپریل رین یک سخنران، سرمایه گذار، ماجراجو و متخصص در جهت یابی تغییرات است. او فارغ التحصیل دانشکده حقوق هاروارد، محقق فولبرایت، یکی از 50 آینده پژوه برجسته زن، و یک رهبر جوان جهانی در مجمع جهانی اقتصاد است.</p>', '2023-01-26 19:35:01.98127', '2023-01-26 19:35:01.98127', NULL, 'April Rinne');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (417, 'طرح جیرجیر یک جاده فومی تاکو', '<p>ایچیرو کیشیمی و فومیتاکه کوگا دو نویسندگی ژاپنی هستند که <em> شجاعت دوست نداشتن</em>و ادامه آن <em>شجاعت برای شاد بودن را تالیف کردند. </em>هر دو کتاب بیش از یک میلیون نسخه فروخته اند. این دو در ابتدا به دلیل تحسین مشترکشان از آلفرد آدلر، روانشناس وینی اوایل قرن بیستم، با هم پیوند خوردند. آنها در کتاب‌های پرفروش خود، فلسفه‌های زندگی و یادگیری آدلر را بی‌وقفه برای مخاطبان معاصر ترجمه می‌کنند.</p>', '2023-01-26 19:35:07.237422', '2023-01-26 19:35:07.237422', NULL, 'Ichiro Kishimi and Fumitake Koga');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (418, 'استیون هاوکینگ و لئونارد ملودینو', '<p>استیون هاوکینگ (1942-2018) یکی از مشهورترین متفکران علمی جهان بود که با جوایز متعددی از جمله مدال آزادی ریاست جمهوری تجلیل شد. او به مدت 30 سال استاد ریاضیات در دانشگاه کمبریج بود و در آنجا روی بسیاری از مشهورترین نظریه های علمی خود کار کرد. او همچنین نویسنده بسیاری از کتاب‌های تاثیرگذار، از جمله <em>تاریخ مختصر زمان</em> و <em>جهان در یک کلام</em> بود.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (419, 'پتی مک کورد', '<p> پتی مک‌کورد تقریباً یک دهه و نیم با تیم اجرایی نتفلیکس خدمت کرد و جریان‌های کاری شرکت را آزمایش کرد و در نتیجه یک فرهنگ کاری با عملکرد بالا ایجاد کرد. مک کورد اکنون مشاوری است که به شرکت های بزرگ و استارت آپ های کوچکتر خدمات می دهد. او همچنین یک سخنران عمومی مکرر است و در نشریاتی مانند <em>Harvard Business Review</em> و NPR همکاری کرده است.</p>', '2023-01-26 19:35:17.459972', '2023-01-26 19:35:17.459972', NULL, 'Patty McCord');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (420, 'نیکولا لوئیس', '<p> نیکولا لوئیس یک سازمان دهنده حرفه ای خانه و خالق وب سایت و وبلاگ <em>This Girl Can Organize است. </em></p>', '2023-01-26 19:35:22.444435', '2023-01-26 19:35:22.444435', NULL, 'Nicola Lewis');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (421, 'کن بلانچارد و رندی کانلی', '<p>کن بلانچارد نویسنده، مشاور رهبری و سخنران انگیزشی است. او یکی از بنیانگذاران شرکت های کن بلانچارد، یک شرکت بین المللی آموزش و توسعه رهبری بود. او در طول زندگی حرفه‌ای خود بیش از 60 کتاب منتشر کرده است - از جمله <em>مدیر یک دقیقه‌ای</em> که بیش از 15 میلیون نسخه فروخته است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (422, 'نیکلاس بوثمن', '<p> نیکلاس بوثمن یک عکاس سابق مد و تبلیغات است که دو دهه گذشته را صرف مطالعه نحوه ارتباط و ارتباط افراد کرده است. او در برنامه نویسی عصبی-زبانی متخصص است.</p>', '2023-01-26 19:35:32.225518', '2023-01-26 19:35:32.225518', NULL, 'Nicholas Boothman');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (423, 'دیوید مرمن اسکات', '<p>دیوید میرمن اسکات، استراتژیست بازاریابی و فروش، سخنران و نویسنده پرفروش کتاب های تحسین شده بین المللی مانند <em>بازاریابی و روابط عمومی در زمان واقعی</em> و <em>فروش استراتژیک جدید</em> است. اسکات قبلاً معاون بازاریابی در NewsEdge Corporation بود که اکنون متعلق به تامسون رویترز است.</p>', '2023-01-26 19:35:36.995276', '2023-01-26 19:35:36.995276', NULL, 'David Meerman Scott');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (424, 'سارا استین گرینبرگ', '<p>سارا استین گرینبرگ مدیر اجرایی مدرسه استنفورد و سخنران عمومی در زمینه طراحی، تجارت و آموزش است. او همچنین به عنوان متولی سازمان جهانی حفاظت از محیط زیست Rare است.</p>', '2023-01-26 19:35:41.97872', '2023-01-26 19:35:41.97872', NULL, 'Sarah Stein Greenberg');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (425, 'کلودیو فرناندز-آرائوز', '<p>کلودیو فرناندز-آراوز نویسنده، سخنران و متخصص بین المللی شناخته شده در زمینه استعداد و رهبری است. او همچنین نویسنده کتاب پرفروش دیگری به نام <em>این نیست چگونه یا چه چیزی بلکه کیست</em> است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (426, 'جان مائده', '<p>جان مائدا یک طراح گرافیک، دانشمند کامپیوتر و هنرمند تجسمی، استاد هنر و علوم رسانه در MIT، و بنیانگذار کنسرسیوم SIMPLICITY در آزمایشگاه رسانه MIT است. او همچنین تعدادی کتاب نوشته است، از جمله <em>طراحی</em> <em>توسط</em> <em>Numbers.</em></p>.', '2023-01-26 19:35:51.746114', '2023-01-26 19:35:51.746114', NULL, 'John Maeda');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (427, 'خاکستر موریا', '<p>Ash Maurya بنیانگذار چندین استارت آپ، به ویژه WiredReach است. او از نزدیک با کارآفرینان دیگر همکاری می‌کند تا دیدگاه خود را در مورد «استارت‌آپ‌های ناب» ترویج کند و نقش‌های مربی را با شتاب‌دهنده‌های استارت‌آپ ایفا می‌کند.</p>', '2023-01-26 19:35:56.658288', '2023-01-26 19:35:56.658288', NULL, 'Ash Maurya');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (428, 'جیم کالینز', '<p>جیم کالینز نویسنده، مدرس و مشاور آمریکایی است که از جمله در دانشکده بازرگانی فارغ التحصیل دانشگاه استنفورد تدریس کرده است و مشارکت کننده مکرر در <em>Fortune</em>، <em>Business Week است. </em> و <em>Harvard Business Review</em>. کتاب دیگر او، <em>از خوب به عالی</em>، بیش از چهار میلیون نسخه فروخته است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (429, 'استیون دنینگ', '<p>استفان دنینگ یک مربی کسب‌وکار استرالیایی است که برای سازمان‌های سراسر جهان مشاوره می‌کند. او متخصص نوآوری های مدیریتی است و به کسب و کارها کمک می کند تا مسیر موفقیت خود را پیدا کنند. از دیگر کتاب‌های او می‌توان به <em>زبان مخفی رهبری: چگونه رهبران از طریق روایت‌ها الهام بخش عمل می‌شوند</em> و <em>راهنمای رهبر برای داستان‌گویی: تسلط بر هنر و نظم و انضباط روایت تجاری</em>.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (430, 'بیانکا بوشر', '<p>بیانکا بوسکر روزنامه نگار و نویسنده است. مقالات او در <em>آتلانتیک</em>، <em>نیویورک تایمز</em>، و <em>نیویورکر</em> و سایر نشریات منتشر شده است. <em>Cork Dork</em>، دومین کتاب او، پرفروش‌ترین کتاب <em>نیویورک تایمز</em> بود.</em> </p>', '2023-01-26 19:36:11.741031', '2023-01-26 19:36:11.741031', NULL, 'Bianca Bosker');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (431, 'ملودی وارنیک', '<p>ملودی وارنیک روزنامه‌نگار آزاد و مشارکت‌کننده در <em>Reader''s Digest، روز زن</em>و<em> آتلانتیک CityLab، </em>در میان سایر نشریات است. او در بلکسبورگ، ویرجینیا، شهری که با شرکت در آزمایش Love Where You Live عاشق آن شد، زندگی می‌کند.</p>', '2023-01-26 19:36:17.107552', '2023-01-26 19:36:17.107552', NULL, 'Melody Warnick');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (432, 'اسکات اندرسون', '<p> اسکات اندرسون روزنامه نگاری است که در تهیه گزارش از مناطق جنگ زده مانند لبنان، اسرائیل و بوسنی تخصص داشته است. آثار او در <em>Esquire</em>، <em>Vanity Fair</em> و <em>The New York Times Magazine</em> ظاهر شده است. از دیگر کتاب‌های او می‌توان به <em>مردی که تلاش کرد جهان را نجات دهد</em> و <em>قتل‌های ساعت 4</em>.</p> اشاره کرد.', '2023-01-26 19:36:22.015108', '2023-01-26 19:36:22.015108', NULL, 'Scott Anderson');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (433, 'دیل پارتریج', '<p>دیل پارتریج متخصص در برندسازی، روانشناسی مصرف کننده و روندهای تجاری است. او همچنین یک کارآفرین اجتماعی، بنیانگذار Sevenly.org و StartupCamp.com است.</p>', '2023-01-26 19:36:26.907573', '2023-01-26 19:36:26.907573', NULL, 'Dale Partridge');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (434, 'جواب بده', '<p>هال الرود یک مربی زندگی، سخنران انگیزشی و نویسنده است. پس از اینکه تقریباً در یک تصادف رانندگی جان خود را از دست داد و از شانس شکست دادن یک نوع سرطان نادر با نرخ بقای 20 تا 30 درصدی سرپیچی کرد، او یکی دو چیز در مورد معجزات می داند. امروز، او از بینش خود برای کمک به میلیون ها نفر در سراسر جهان استفاده می کند تا بر چالش های خود غلبه کنند و به پتانسیل کامل خود دست یابند. کتاب های قبلی او عبارتند از <em>صبح معجزه</em> (2012).</p>', '2023-01-26 19:36:31.910751', '2023-01-26 19:36:31.910751', NULL, 'Hal Elrod');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (450, 'مارک گولستون', '<p>مارک گولستون یک روانپزشک، مشاور تجاری و مربی است. او همچنین نویسنده پرفروش‌ترین کتاب‌های <em>فقط گوش کن</em> و <em>از راه خودت خارج شو</em> است.</p>', '2023-01-26 19:37:55.733574', '2023-01-26 19:37:55.733574', NULL, 'Mark Goulston');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (435, 'دیوید هیوم', '<p>دیوید هیوم فیلسوف، مورخ، اقتصاددان و دیپلمات اسکاتلندی بود که بیشتر به خاطر تجربه‌گرایی فلسفی رادیکال‌اش به یاد می‌آید. هیوم که اغلب به‌عنوان بزرگترین فیلسوفی که به زبان انگلیسی نوشته است، یکی از شخصیت‌های کلیدی عصر روشنگری و در واقع کل سنت فلسفی غرب محسوب می‌شود. یکی دیگر از متفکران کلیدی روشنگری، امانوئل کانت، بعدها هیوم را به بیدار کردن او از "خواب جزمی" نسبت داد.</p>', '2023-01-26 19:36:36.894599', '2023-01-26 19:36:36.894599', NULL, 'David Hume');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (436, 'مت هیگ', '<p>مت هیگ روزنامه نگار و نویسنده بریتانیایی است که بیش از 20 کتاب داستانی و غیرداستانی برای کودکان و بزرگسالان نوشته است. خاطرات او، <em>دلایل زنده ماندن</em>، جزئیات مبارزه او با افسردگی را شرح می دهد و یکی از پرفروش ترین های <em>ساندی تایمز</em> در بریتانیا بود. کتاب های کودکان او به بیش از 25 زبان ترجمه شده است.</p>', '2023-01-26 19:36:42.273713', '2023-01-26 19:36:42.273713', NULL, 'Matt Haig');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (437, 'کریستین هجسث', '<p>یک کارآفرین سریالی، کریستین هجسث همچنین بنیانگذار <em>Green Man Cannabis</em> است، یک شرکت معتبر ماری جوانا قانونی که دو بار برنده معتبرترین جایزه صنعت برای پرورش بهترین علف هرز در جهان شده است.< /p>', '2023-01-26 19:36:47.857382', '2023-01-26 19:36:47.857382', NULL, 'Christian Hageseth');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (438, 'دن مک کرام', '<p>دن مک‌کرام یک روزنامه‌نگار بریتانیایی با <em>Financial Times</em> است. او جوایز و جوایز متعددی را برای گزارش‌هایش در Wirecard دریافت کرده است. او در سال 2020 توسط جوایز روزنامه نگاری بریتانیا به عنوان روزنامه نگار سال انتخاب شد.</p>', '2023-01-26 19:36:53.348079', '2023-01-26 19:36:53.348079', NULL, 'Dan McCrum');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (439, 'نایل فرگوسن', '<p>نیل فرگوسن یکی از مشهورترین مورخان بریتانیایی است. او برای مؤسسات متعددی در بریتانیا و ایالات متحده آمریکا کار کرده است که عمدتاً بر تاریخ بین‌المللی و اقتصادی تمرکز دارد.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (440, 'ریچارد استتلی و اکونومیست', '<p><em>اکونومیست</em> یک مجله هفتگی انگلیسی زبان است که به دلیل پوشش جهانی و موضع اقتصادی لیبرال خود شناخته شده است. <em>The Economist: Numbers Guide</em>بخشی از مجموعه کتاب‌هایی است که شامل <em>راهنمای تجزیه و تحلیل شرکت‌ها</em>، <em>راهنمای بازارهای مالی</em> و <em>راهنمای ایده‌های مدیریتی است. .</em></p>', '2023-01-26 19:37:03.51079', '2023-01-26 19:37:03.51079', NULL, 'Richard Stutely & The Economist');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (441, 'جف اولسون', '<p><strong>درباره نویسنده</strong></p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (442, 'چارلز روولی', '<p>کارلو روولی یک فیزیکدان نظری و مدیر گروه تحقیقاتی گرانش کوانتومی در مرکز فیزیک Théorique در مارسی، فرانسه است. او چندین کتاب پرفروش در زمینه فیزیک نوشته است، از جمله <em>هفت درس مختصر در فیزیک</em>، <em>واقعیت آنطور که به نظر می‌رسد نیست</em>، و <em>نظم زمان</em>. </p>', '2023-01-26 19:37:14.689428', '2023-01-26 19:37:14.689428', NULL, 'Carlo Rovelli');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (443, 'جیل کنراث', '<p>جیل کنراث یک استراتژیست فروش برنده جایزه و نویسنده کتاب‌های <em>فروش به شرکت‌های بزرگ</em> و <em>فروش اسنپ</em>، در میان دیگر عناوین استراتژی تجاری و فروش است.</p>', '2023-01-26 19:37:19.90084', '2023-01-26 19:37:19.90084', NULL, 'Jill Konrath');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (444, 'جک میچل', '<p>جک میچل رئیس فروشگاه های زنجیره ای پوشاک بسیار موفق میچل، کسب و کار خانوادگی او است. او در مورد استراتژی شرکت می نویسد و در دانشگاه هاروارد سخنرانی کرده است.</p>', '2023-01-26 19:37:25.370988', '2023-01-26 19:37:25.370988', NULL, 'Jack Mitchell');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (445, 'جسیکا لاهی', '<p>جسیکا لاهی نویسنده، روزنامه نگار و سخنران است. او یک ستون دوهفته ای برای <em>نیویورک تایمز</em> می نویسد و یکی از نویسندگان مشارکت کننده در مجله <em>آتلانتیک</em> است.</p>', '2023-01-26 19:37:30.399934', '2023-01-26 19:37:30.399934', NULL, 'Jessica Lahey');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (446, 'مایکل سولومون و ریشون بلومبرگ', '<p>مایکل سولومون و ریشون بلومبرگ مدیران با استعدادی هستند که کار خود را در صنعت موسیقی آغاز کردند. پس از نمایندگی از نوازندگانی مانند جان مایر و ونسا کارلتون، آنها به دنیای فناوری گسترش یافتند و شرکت مدیریت استعداد 10x Management را در سال 2012 ایجاد کردند تا به تغییر روش کار برنامه نویسان برتر کمک کند.</p>', '2023-01-26 19:37:35.285485', '2023-01-26 19:37:35.285485', NULL, 'Michael Solomon and Rishon Blumberg');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (447, 'درو اریک ویتمن', '<p>درو اریک ویتمن برای بخش بازاریابی مستقیم بزرگترین آژانس تبلیغاتی در فیلادلفیا کار کرده است و اکنون مشاور و معلم روانشناسی رفتار مصرف کننده است. کار او توسط سازمان‌های بزرگ مانند مؤسسه تخصصی تبلیغات، American Legion و Texaco استفاده شده است.</p>', '2023-01-26 19:37:40.203516', '2023-01-26 19:37:40.203516', NULL, 'Drew Eric Whitman');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (448, 'رون عزیز', '<p>ران لیبر، علاوه بر نوشتن ستون پول شما برای <em>نیویورک تایمز</em>، نویسنده سه کتاب پرفروش، از جمله <em>Taking Time Off.</em></p> است.', '2023-01-26 19:37:45.422539', '2023-01-26 19:37:45.422539', NULL, 'Ron Lieber');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (449, 'بریجت شولت', '<p>روزنامه نگاری با <em>واشنگتن پست</em>، بریجید شولت در مورد مسائل کاری و زندگی و فقر می نویسد و مفهوم کار و اوقات فراغت در آمریکا را از نزدیک بررسی کرده است و این سوال را بررسی کرده است که چگونه همه ما می توانیم "زندگی خوب" را رهبری کنید. او همچنین برای <em>Style</em> و <em>Outlook</em> نوشته است.</p>', '2023-01-26 19:37:50.502711', '2023-01-26 19:37:50.502711', NULL, 'Brigid Schulte');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (452, 'دن وارد', '<p>با سه مدرک مهندسی و بیش از 20 سال با نیروی هوایی ایالات متحده، تخصص نویسنده دان وارد در مورد اصلاحات اکتساب دفاعی در نشریاتی که توسط کاخ سفید ایالات متحده، سنای ایالات متحده و پارلمان بریتانیا منتشر شده است، ارائه شده است.</p>', '2023-01-26 19:38:05.914959', '2023-01-26 19:38:05.914959', NULL, 'Dan Ward');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (453, 'جنیفر لی', '<p>جنیفر لی کتاب راهنمای پرفروش را نوشت، <em>طرح کسب و کار راست مغز</em>. او که قبلاً مشاور شرکت‌های Fortune 500 بود، از آن زمان یک موسسه مربیگری تأسیس کرده است تا هنرمندان و خلاقان را راهنمایی کند تا پتانسیل کامل خود را به‌کار ببرند.</p>', '2023-01-26 19:38:14.608781', '2023-01-26 19:38:14.608781', NULL, 'Jennifer Lee');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (454, 'پیتر اف دراکر', '<p>پیتر اف. دراکر (1909-2005) مشاور مدیریت، معلم، نویسنده، و یکی از بنیانگذاران بنیاد پیتر اف. دراکر برای مدیریت غیرانتفاعی اتریشی-آمریکایی بود. او ده سال ستون نویس <em>وال استریت ژورنال</em> بود و مرتباً برای <em>Economist</em>و <em>Harvard Business Review</em> می نوشت. او در مجموع 34 کتاب نوشت که به بیش از 70 زبان منتشر شده است. اینها عبارتند از<em> تمرین مدیریت، که توسط همکاران آکادمی مدیریت به عنوان سومین کتاب تاثیرگذار مدیریت در قرن بیستم انتخاب شد.</p>', '2023-01-26 19:38:19.941501', '2023-01-26 19:38:19.941501', NULL, 'Peter F. Drucker');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (455, 'گوردون مک کنزی', '<p>گوردون مکنزی به مدت 30 سال در شرکت کارت تبریک Hallmark کار کرد. با شروع به‌عنوان یک هنرمند، موقعیت او در شرکت طی سال‌ها تغییر کرد و در نهایت به نوعی گورو شرکت با عنوان <em>پارادوکس خلاق</em> تبدیل شد، کسی که مردم با ایده‌های خود به او روی می‌آورند.</p>', '2023-01-26 19:38:24.676345', '2023-01-26 19:38:24.676345', NULL, 'Gordon MacKenzie');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (456, 'روزابت ماس ​​کانتر', '<p>رزابث ماس کانتر استاد دانشکده بازرگانی هاروارد است که متخصص در استراتژی، رهبری و نوآوری از دیدگاه تغییرات اجتماعی است. او سردبیر سابق <em>Harvard Business Review</em> و نویسنده چندین کتاب، از جمله <em>اعتماد به نفس: چگونه رگه های برنده و باخت آغاز و پایان می یابد</em> است.</p>', '2023-01-26 19:38:29.888489', '2023-01-26 19:38:29.888489', NULL, 'Rosabeth Moss Kanter');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (457, 'ماریا پوپووا', '<p>ماریا پوپووا یک نویسنده آمریکایی بلغاری الاصل است که به خاطر وبلاگ خود <em>Brain Pickings</em> معروف است، که شامل نوشته های متنوع او در مورد کتاب، هنر، فلسفه و فرهنگ است. او به‌عنوان همکار «آینده‌های سرگرمی» MIT، به‌عنوان مدیر تحریریه در شبکه اجتماعی آموزش عالی Lore خدمت کرده است و برای <em>آتلانتیک</em>، <em>Wired UK</em>، و <em>نیویورک تایمز</em>.</p>', '2023-01-26 19:38:35.522894', '2023-01-26 19:38:35.522894', NULL, 'Maria Popova');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (458, 'ماسیمو پیگلیوچی و گریگوری لوپز', '<p>ماسیمو پیگلیوچی استاد فلسفه در کالج شهر نیویورک و همچنین عضو انجمن آمریکایی برای پیشرفت علم است. او همچنین شاگرد و شاگرد رواقی است. نوشته های او در نشریاتی مانند <em>Philosophy Now</em>، <em>نیویورک تایمز</em> و <em>وال استریت ژورنال</em> ظاهر شده است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (459, 'آلن بیتی', '<p>آلن بیتی دارای مدرک کارشناسی ارشد در اقتصاد از دانشگاه کمبریج است. او پس از کار به عنوان اقتصاددان برای بانک انگلستان، در سال 1998 به <em>فایننشال تایمز</em> پیوست و در سال 2004 سردبیر تجارت جهانی روزنامه شد.</p>', '2023-01-26 19:38:49.228105', '2023-01-26 19:38:49.228105', NULL, 'Alan Beattie');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (460, 'سامیر پریخ', '<p>سمیر پریخ یک مشاور بازرگانی، مدیر عمل و مدیر عامل مشاور با بیش از 25 سال تجربه در این صنعت است. او بنیانگذار شرکت مشاوره جهانی SP-Consulting است که پروژه های خود را در بیش از 50 کشور تکمیل کرده است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (461, 'پگی اورنشتاین', '<p>پگی اورنشتاین یک روزنامه نگار برنده جایزه، نویسنده پرفروش <em>نیویورک تایمز</em> و متخصص جنسیت و تمایلات جنسی است. کتاب <em>دختران و سکس</em> او با بررسی صریح زندگی جنسی دختران معاصر آمریکایی، زمینه جدیدی را ایجاد کرد و سخنرانی او در TED در مورد لذت جنسی دختران یک حس ویروسی بود.</p>', '2023-01-26 19:38:59.120565', '2023-01-26 19:38:59.120565', NULL, 'Peggy Orenstein');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (462, 'باربارا اوکلی', '<p>باربارا اوکلی استاد مهندسی در دانشگاه اوکلند و عضو موسسه آمریکایی مهندسی پزشکی و بیولوژیکی است. او به طور گسترده در مورد استراتژی های یادگیری نوشته است، و کار او در <em>وال استریت ژورنال</em> نشان داده شده است.</p>', '2023-01-26 19:39:04.155466', '2023-01-26 19:39:04.155466', NULL, 'Barbara Oakley');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (463, 'نیک لین', '<p>دکتر نیک لین در امپریال کالج لندن بیوشیمی خوانده و خواننده افتخاری دانشگاه کالج لندن است. او نویسنده <em>قدرت، جنسیت، خودکشی: میتوکندری و معنای زندگی</em> و <em>Life Ascending: The Ten Inventions Great of Evolution</em> است.</p>', '2023-01-26 19:39:09.208715', '2023-01-26 19:39:09.208715', NULL, 'Nick Lane');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (464, 'هاروی کارپ', '<p> هاروی کارپ نویسنده پرفروش و استادیار اطفال در دانشکده پزشکی USC است. استراتژی مراقبت از کودک او - <em>شادترین راه کودک</em> - توسط بسیاری از مربیان متخصص در بیمارستان ها و کلینیک ها در سراسر ایالات متحده و در سراسر جهان توصیه می شود.</p>', '2023-01-26 19:39:14.188698', '2023-01-26 19:39:14.188698', NULL, 'Harvey Karp');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (465, 'کیم پرل', '<p>کیم پرل یک کارآفرین، اجرایی و سرمایه گذار بسیار موفق است که قبل از 30 سالگی تبدیل به یک مولتی میلیونر شد. <em>Business Insider</em> او را یکی از قدرتمندترین زنان در تبلیغات موبایلی معرفی کرده است. Trailblazer فناوری بازاریابی توسط <em>AdAge</em> و کارآفرین سال توسط Ernst & Young. او مدیر عامل شرکت Amobee، یک شرکت فناوری نوآورانه بازاریابی جهانی است.</p>', '2023-01-26 19:39:19.940203', '2023-01-26 19:39:19.940203', NULL, 'Kim Perell');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (466, 'کارولین هیرونز', '<p>کارولین هیرونز، گوروی مراقبت از پوست، که میلیون‌ها خواننده از طریق وبلاگ محبوب خود می‌شناسند، ده‌ها سال تجربه در صنعت لوازم آرایشی دارد. او راه خود را از پیشخوان زیبایی Clarins بالا برد تا به یک زیبایی‌شناس پیشرفته، مشاور برند و صاحب اختیار در همه چیز پوست تبدیل شود. </p>', '2023-01-26 19:39:25.979895', '2023-01-26 19:39:25.979895', NULL, 'Caroline Hirons');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (467, 'الیزابت گریس ساندرز', '<p>الیزابت گریس ساندرز موسس و مدیر عامل شرکت مربیگری Real Life E است که با مشتریان شرکتی و خصوصی در شش قاره کار می کند. نوشته‌های او در <em>Forbes، Harvard Business Review</em> و <em>TIME</em> در میان بسیاری از نشریات دیگر منتشر شده است.</p>', '2023-01-26 19:39:30.877209', '2023-01-26 19:39:30.877209', NULL, 'Elizabeth Grace Saunders');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (468, 'جو پولیزی', '<p>جو پولیزی رهبر جنبش بازاریابی محتوا و بنیانگذار موسسه بازاریابی محتوا است. از دیگر کتاب‌های او می‌توان به <em>بازاریابی محتوای حماسی</em> اشاره کرد که مجله <em>Fortune </em> یکی از آنها را به‌عنوان «پنج کتاب برتر کسب‌وکار که باید بخوانید» نامید. در سال 2014، پولیزی جایزه یک عمر دستاورد جان کالدول را از شورای محتوا دریافت کرد.</p>', '2023-01-26 19:39:36.005882', '2023-01-26 19:39:36.005882', NULL, 'Joe Pulizzi');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (469, 'لوری روتیمن', '<p>لوری روتیمن حرفه ای در زمینه منابع انسانی شرکت را ترک کرد تا نویسنده، کارآفرین و سخنران شود. CNN او را به عنوان یکی از پنج مشاور شغلی برتر در ایالات متحده شناخته است. کارهای او در NPR و <em>نیویورکر، یو اس ای تودی</em> و <em>وال استریت ژورنال</em> به نمایش درآمده است.</p>', '2023-01-26 19:39:44.20609', '2023-01-26 19:39:44.20609', NULL, 'Laurie Ruettimann');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (470, 'چارلز اچ الیوت و لورا ال. اسمیت', '<p>چارلز اچ. الیوت، دکترا، روانشناس بالینی، یکی از اعضای مؤسس آکادمی درمان شناختی و استاد بازنشسته در دانشگاه فارغ التحصیل فیلدینگ است. او در درمان اختلالات عاطفی تخصص دارد.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (471, 'دوریس کرنز گودوین', '<p>دوریس کرنز گودوین یک مورخ ریاست جمهوری است که به عنوان یکی از اعضای کاخ سفید و کارمند دولت لیندون جانسون کار می کرد. پس از ترک دفتر، او به او کمک کرد تا خاطراتش را بنویسد، در حالی که ده سال بعد در دانشگاه هاروارد تدریس می کرد. او نویسنده کتاب برنده جایزه پولیتزر <em>بدون زمان معمولی: فرانکلین و النور روزولت: جبهه خانگی در جنگ جهانی دوم</em> و همچنین چندین کتاب پرفروش از جمله <em>لیندون جانسون و رویای آمریکایی</em>; <em>منبر قلدر: تئودور روزولت، ویلیام هاوارد تافت، و عصر طلایی روزنامه نگاری</em>؛ و <em>تیم رقبا: نابغه سیاسی آبراهام لینکلن</em>، که منبع منبع فیلم <em>لینکلن</em> استیون اسپیلبرگ را فراهم کرد.</p>', '2023-01-26 19:39:53.92886', '2023-01-26 19:39:53.92886', NULL, 'Doris Kearns Goodwin');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (472, 'جوزف مک کورمک', '<p>جوزف مک کورمک متخصص داستان سرایی شرکتی و انتقال اطلاعات از طریق روایت است. او مشاوره های ارتباطی را به طیف گسترده ای از متخصصان از رهبران نظامی گرفته تا مدیران ارشد شرکت هایی مانند SAP، MasterCard و Harley-Davidson ارائه کرده است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (473, 'تریستان تائورمینو', '<p>Tristan Taormino یک نویسنده فمینیست، مربی جنسی، و فعال است. او نویسنده هفت کتاب است، از جمله برنده جایزه Firecracker <em>راهنمای نهایی رابطه جنسی مقعدی برای زنان</em>. او همچنین چندین مجموعه شهوانی را ویرایش کرده و فیلم‌های پورنوگرافیک را کارگردانی کرده و در آن بازی کرده است.</p>', '2023-01-26 19:40:03.707382', '2023-01-26 19:40:03.707382', NULL, 'Tristan Taormino');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (474, 'نائومی کلاین', '<p>نائومی کلاین نویسنده و روزنامه نگار کانادایی برنده جوایز است که برای نشریات مختلف از جمله <em>New Statesman، نیویورک تایمز</em>و <em>Newsweek International نوشته است. </em>همراه با <em>No Logo</em> که در فهرست نهایی جایزه کتاب اول گاردین قرار گرفت، کلاین همچنین <em>دکترین شوک: ظهور سرمایه داری فاجعه را نوشت.</em></p>', '2023-01-26 19:40:12.183755', '2023-01-26 19:40:12.183755', NULL, 'Naomi Klein');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (475, 'ست گودین', '<p> ست گودین نویسنده، سخنران عمومی و کارآفرین پرفروش است. او ۱۹ کتاب نوشته است، از جمله پرفروش‌ترین <em>نیویورک تایمز</em> <em>قبایل</em>و پرفروش‌ترین <em>وال استریت ژورنال</em> <em>گاو بنفش</em>، که پیش درآمد <em>Free Prize Inside است.</em> او بنیانگذار Squidoo و Yoyodyne و همچنین altMBA - یک برنامه آموزشی آنلاین رهبری و مدیریت بود. در سال 2018، او به تالار مشاهیر بازاریابی معرفی شد. </p>', '2023-01-26 19:40:17.298162', '2023-01-26 19:40:17.298162', NULL, 'Seth Godin');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (476, 'جاناتان آلدرد', '<p>جاناتان آلدرد عضو کالج امانوئل، دانشگاه کمبریج است که در آنجا اقتصاد و اقتصاد زمین تدریس می کند. اولین کتاب او، <em>اقتصاددان شکاک</em>، در سال 2009 منتشر شد و به بررسی اخلاقیات نهفته در اقتصاد می پردازد.</p>', '2023-01-26 19:40:22.482799', '2023-01-26 19:40:22.482799', NULL, 'Jonathan Aldred');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (477, 'کریس سیمز و هیلاری لوئیز جانسون', '<p>کریس سیمز یک مربی خبره اسکرام، مربی چابک و بنیانگذار <em>Agile Learning Labs</em> است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (478, 'اد مایلت', '<p>اد مایلت یک سخنران کارآفرین و انگیزشی است. او بر اساس تجربیاتش به عنوان یک تاجر و پدر توصیه هایی در مورد اینکه چگونه بهترین خود باشید و بهترین عملکرد را ارائه می دهد. او همچنین نویسنده <em>Max Out Your Life</em> است.</p>', '2023-01-26 19:40:32.334079', '2023-01-26 19:40:32.334079', NULL, 'Ed Mylett');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (479, 'آوی لوب', '<p> آوی لوب فرانک بیرد جونیور، استاد علوم در دانشگاه هاروارد، رئیس گروه نجوم هاروارد، و رئیس هیئت فیزیک و نجوم آکادمی های ملی است. او بیش از 700 مقاله علمی در زمینه فضا، نجوم و اخترفیزیک نوشته است.</p>', '2023-01-26 19:40:37.449166', '2023-01-26 19:40:37.449166', NULL, 'Avi Loeb');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (480, 'تام آیزنمن', '<p>تام آیزنمن استاد مدیریت بازرگانی در مدرسه بازرگانی هاروارد است که در آنجا کارآفرینی تدریس می کند. او 130 مطالعه موردی را تالیف کرده است که در مدارس کسب و کار در سراسر جهان استفاده می شود. آیزنمن در ده‌ها سرمایه‌گذاری جدید سرمایه‌گذاری کرده است، در بسیاری از هیئت‌های مشاوره استارت‌آپ‌ها خدمت کرده است و هزاران دانش‌آموز را که می‌خواهند کارآفرین شوند، راهنمایی کرده است.</p>', '2023-01-26 19:40:41.989025', '2023-01-26 19:40:41.989025', NULL, 'Tom Eisenmann');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (481, 'آندره آغاسی', '<p>آندره آغاسی در سال 2006 از تنیس بازنشسته شد. در طول دوران حرفه ای خود، او در رتبه اول جهان قرار گرفت و هشت عنوان گرند اسلم را به دست آورد. او یکی از معدود تنیسورهایی است که به گلدن اسلم شغلی دست یافته است، شاهکار قهرمانی در هر تورنمنت گرند اسلم، و همچنین مدال طلا در المپیک. او اکنون وقت خود را به آکادمی مقدماتی کالج آندره آغاسی اختصاص می دهد که زندگی کودکان در معرض خطر را در زادگاهش لاس وگاس، نوادا بهبود می بخشد.</p>', '2023-01-26 19:40:46.731698', '2023-01-26 19:40:46.731698', NULL, 'Andre Agassi');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (482, 'مایکل تازه', '<p>Michael H. Frisch، Robert J. Lee، Karen L. Metzger، Jeremy Robinson و Judy Rosemarin همگی مربیان و مربیان اجرایی مستقر در شهر نیویورک با تجربه شرکتی، مشاوره و آکادمیک قابل توجهی هستند.</p>', '2023-01-26 19:40:51.469919', '2023-01-26 19:40:51.469919', NULL, 'Michael Frisch');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (483, 'مایکل گرگر و جین استون', '<p>Michael Greger، MD، یک پزشک، نویسنده و سخنران مشهور بین المللی است. علاوه بر این، او به عنوان مدیر بهداشت عمومی و کشاورزی حیوانات در انجمن انسانی ایالات متحده خدمت می کند و وب سایت NutritionFacts.org را اداره می کند.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (484, 'جک فیلیپس', '<p>جک فیلیپس یک محقق پیشرو در اندازه گیری و بازاریابی است. او بیش از 100 کتاب در این زمینه نوشته و ویرایش کرده است و رئیس موسسه مشاوره تحقیقاتی ROI است. </p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (485, 'کیم جان پین و لیزا ام راس', '<p>کیم جان پین متخصص در امر تربیت کودک با 27 سال تجربه در مشاوره مدرسه، بزرگسالان و خانواده است. از دیگر کتاب‌های او می‌توان به <em>بازی‌هایی که کودکان بازی می‌کنند </em> (1996) و <em>در بهترین حالت خود بودن وقتی بچه‌های شما در بدترین حالت خود هستند </em>(2017) اشاره کرد.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (486, 'رابرت تی کیوساکی', '<p>رابرت کیوساکی یک کارآفرین، نویسنده و مدرس امور مالی شخصی است. او با نام تجاری پدر پولدار خود، 26 کتاب با فروش بیش از 27 میلیون در سراسر جهان منتشر کرده است. او چندین کسب و کار راه اندازی کرده است و دارایی خالص تخمینی او 80 میلیون دلار است.</p>', '2023-01-26 19:41:16.120448', '2023-01-26 19:41:16.120448', NULL, 'Robert T. Kiyosaki');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (487, 'مارگارت هفرنان', '<p> مارگارت هفرنان که از یک پیشینه چندفرهنگی و تحصیل کرده در کمبریج آمده بود، به سمت مدیرعاملی بسیاری از شرکت‌ها از جمله <em>InfoMation</em>، <em> ZineZone </em>و <em>iCAST</em> تبدیل شد. em>. او همچنین نویسنده برنده جایزه <em>جایزه بزرگتر</em>و <em>کوری عمدی</em> است.</p>', '2023-01-26 19:41:21.285643', '2023-01-26 19:41:21.285643', NULL, 'Margaret Heffernan');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (488, 'ال دیوید مارکت', '<p>دیوید مارکته قبل از فرماندهی  از سال 1999 تا 2001 ناو یو اس اس سانتافه، یک زیردریایی تهاجمی سریع با موتور اتمی، از آکادمی نیروی دریایی ایالات متحده فارغ التحصیل شد. مارکت اکنون به عنوان مشاور رهبری کار می کند و عضو مادام العمر شورای روابط خارجی است.</p>', '2023-01-26 19:41:25.922708', '2023-01-26 19:41:25.922708', NULL, 'L. David Marquet');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (489, 'آنگوس دیتون', '<p>انگوس دیتون، استاد دانشگاه پرینستون و دانشکده روابط عمومی و بین‌الملل وودرو ویلسون، برنده جایزه نوبل اقتصاد 2015 شد. او همچنین نویسنده <em>تحلیل نظرسنجی های خانوار</em>و <em>اقتصاد و رفتار مصرف کننده</em> است.</p>', '2023-01-26 19:41:30.924104', '2023-01-26 19:41:30.924104', NULL, 'Angus Deaton');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (490, 'استفن آر. کاوی و سینتیا کاوی هالر', '<p>استفن آر. کاوی یک مربی، نویسنده، سخنران و تاجری بود که به دیگران کمک کرد تا زندگی مؤثرتر، دلسوزانه و معنادارتری داشته باشند. کتاب افسانه‌ای او، پرفروش‌ترین <em>7 عادت افراد بسیار مؤثر</em>، بیش از 50 میلیون نسخه در سراسر جهان فروخته و به بیش از 40 زبان منتشر شده است. در اواخر عمرش، کاوی احساس کرد که برای تکمیل کارش به یک جزء نهایی نیاز است. <em>Live Life in Crescendo</em> آخرین فصل است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (491, 'جیلیان تت', '<p>گیلیان تت سردبیر <em>فایننشال تایمز است.</em> او همچنین یک روزنامه نگار برنده جوایز و دارای مدرک دکترا در انسان شناسی فرهنگی است.</p>', '2023-01-26 19:41:40.751712', '2023-01-26 19:41:40.751712', NULL, 'Gillian Tett');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (492, 'امی کادی', '<p>امی کادی نویسنده و روانشناس است که در مدرسه بازرگانی هاروارد تدریس می کند. در سال 2012، او با سخنرانی TED خود در مورد مزایای ژست قدرت، شهرت جهانی یافت. اولین کتاب مهم او، <em>حضور</em>، پرفروش‌ترین کتاب <em>نیویورک تایمز</em> و <em>واشنگتن پست</em> است که به سی زبان ترجمه شده است.</p>', '2023-01-26 19:41:46.676757', '2023-01-26 19:41:46.676757', NULL, 'Amy Cuddy');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (493, 'کلایو ریچ', '<p>Clive Rich یک وکیل رسانه دیجیتال و سرگرمی، میانجی، داور و خالق برنامه Close my Deal است که به افراد کمک می کند مهارت های مذاکره خود را تقویت کنند.</p>', '2023-01-26 19:41:51.766928', '2023-01-26 19:41:51.766928', NULL, 'Clive Rich');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (494, 'استیون اسلومان و فیلیپ فرنباخ', '<p>استیون اسلومان، استاد زبان شناسی شناختی، در دانشگاه براون تدریس می کند. او همچنین سردبیر <em>Cognition</em>، یک مجله علمی است که به مطالعه علوم شناختی اختصاص دارد.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (495, 'رابین چیس', '<p>رابین چیس یک کارآفرین و یکی از بنیانگذاران Zipcar، بزرگترین شرکت اشتراک خودرو در جهان است. او در هیئت مدیره وزارت حمل و نقل ماساچوست و در کمیته مشاوره حمل و نقل فدرال کار کرده است. در سال 2009، مجله <em>تایم</em> او را در فهرست 100 تأثیرگذارترین افراد جهان قرار داد.</p>', '2023-01-26 19:42:05.505002', '2023-01-26 19:42:05.505002', NULL, 'Robin Chase');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (496, 'متیو دیکس', '<p>متیو دیکس پرفروش ترین نویسنده رمان هایی مانند <em>چیزی گمشده</em> و <em>خاطرات یک دوست خیالی</em> است. او همچنین مجری و معلم است. او هم قهرمان Moth StorySLAM و هم قهرمان GrandSLAM است.</p>', '2023-01-26 19:42:14.684174', '2023-01-26 19:42:14.684174', NULL, 'Matthew Dicks');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (497, 'تام و دیوید کلی', '<p>دیوید کلی موسس IDEO، یکی از شرکت‌های پیشرو در زمینه نوآوری و طراحی در جهان، و همچنین بنیانگذار موسسه طراحی دانشگاه استنفورد، d.school است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (498, 'آنا لمبکه', '<p>آنا لمبکه یک محقق بالینی، محقق برنده جوایز، و رئیس کلینیک تشخیص دوگانه پزشکی اعتیاد استانفورد است. او هم برای تحقیقات و هم برای تدریسش جوایزی را به دست آورده است، مقالات و مقالات بی شماری منتشر کرده است و دو کتاب قبلی درباره اعتیاد و همه گیری مواد مخدر نوشته است. </p>', '2023-01-26 19:42:25.703431', '2023-01-26 19:42:25.703431', NULL, 'Anna Lembke');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (499, 'هرب کوهن', '<p>هرب کوهن بیش از چهار دهه مذاکره کننده بوده است و طیف گسترده ای از موقعیت ها را از ادغام شرکت ها گرفته تا قراردادهای بین المللی خلع سلاح و مذاکرات گروگان را پوشش می دهد. او مهارت های مذاکره را در بسیاری از موسسات معتبر از جمله FBI، CIA و دانشگاه هاروارد تدریس کرده است. تحلیل‌ها و بینش‌های او او را به موضوع مقاله‌هایی در نشریات مختلفی مانند <em>نیویورکر، اکونومیست، مجله TIME </em>و<em> رولینگ استون</em> تبدیل کرده است. </p>', '2023-01-26 19:42:30.598196', '2023-01-26 19:42:30.598196', NULL, 'Herb Cohen');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (500, 'ریچ کارلگارد', '<p>ریچ کارلگارد ناشر <em>فوربس</em> است، جایی که ستون قواعد نوآوری<em> را نیز می نویسد.</em> کتاب او در سال 2004 <em>زندگی 2.0: چگونه مردم در سراسر آمریکا زندگی خود را تغییر می دهند زندگی با یافتن محل خوشبختی آنها</em> در فهرست پرفروش‌ترین‌های <em>وال استریت ژورنال</em> بود.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (501, 'لس مک کیون', '<p>لس مک کئون رئیس و مدیر عامل موفقیت قابل پیش بینی است. او شخصاً بیش از 40 شرکت را تأسیس کرده است، از جمله یک شرکت مشاوره جوجه کشی که خود صدها تجارت را در سراسر جهان راه اندازی کرده است. مشتریان او شامل ارتش ایالات متحده، دانشگاه هاروارد، مایکروسافت، VeriSign و غیره هستند. McKeown در CNN، ABC، BBC و <em> USA Today</em> و <em>New York Times</em> نمایش داده شده است.</p>', '2023-01-26 19:42:40.494593', '2023-01-26 19:42:40.494593', NULL, 'Les McKeown');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (502, 'لوله های گیر', '<p>گری تاوبز (متولد 1956) یک روزنامه نگار علمی آمریکایی است. او در کتاب‌هایش بحث‌های علمی را مورد بحث قرار می‌دهد و به خوانندگانش بینش‌های روشنی در زمینه‌های موضوعی پیچیده ارائه می‌دهد. اخیراً او به دلیل دیدگاه انتقادی خود نسبت به تأسیس علم تغذیه مورد توجه قرار گرفته است. </p>', '2023-01-26 19:42:45.089431', '2023-01-26 19:42:45.089431', NULL, 'Gary Taubes');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (503, 'جولی لیثکات-هیمز', '<p> جولی لیثکات هیمز به عنوان رئیس دانشجویان سال اول و مشاوره در مقطع کارشناسی در دانشگاه استنفورد خدمت کرده است و به طور گسترده در مورد فرزندپروری با هلیکوپتر صحبت کرده و نوشته است. او همچنین شاعر و نمایشنامه نویس است.</p>', '2023-01-26 19:42:49.846833', '2023-01-26 19:42:49.846833', NULL, 'Julie Lythcott-Haims');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (504, 'جی. ریچارد شل', '<p>G. ریچارد شل، استاد مدیریت در مدرسه وارتون دانشگاه پنسیلوانیا و خالق «دوره موفقیت» محبوب آن است. او در نزدیکی فیلادلفیا زندگی می کند.</p>', '2023-01-26 19:42:54.666127', '2023-01-26 19:42:54.666127', NULL, 'G. Richard Shell');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (505, 'آن اورنیش و دین اورنیش', '<p>دکتر دین اورنیش استاد بالینی پزشکی در دانشگاه کالیفرنیا، سانفرانسیسکو، و دانشگاه کالیفرنیا، سن دیگو است. تحقیقات او در مجلات پزشکی معتبر مانند <em>Journal of the American Medical Association،</em><em>New England Journal of Medicine</em>و <em>Lancet</em> منتشر شده است. em>. او نویسنده شش کتاب پرفروش از جمله <em>Dr. برنامه دین اورنیش برای معکوس کردن بیماری قلبی </em>(1990) و <em>طیف</em>(2008).</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (506, 'دبلیو. تیموتی گالوی', '<p>W. تیموتی گالوی قبل از اینکه مربی تنیس شود، خودش تنیس بازی می‌کرد و در آنجا قدرت تمرین ذهنی را کشف کرد. اکنون او یک نویسنده پرفروش و مربی کسب‌وکار است که «بازی درونی» را در طیف وسیعی از چالش‌ها و موقعیت‌های روزمره به کار می‌گیرد.</p>', '2023-01-26 19:43:04.875994', '2023-01-26 19:43:04.875994', NULL, 'W. Timothy Gallwey');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (507, 'الکس هیلی', '<p>مالکوم ایکس یکی از مهم ترین فعالان تاریخ حقوق آفریقایی-آمریکایی ها بود. روز مالکوم ایکس در 19 می هر سال در بسیاری از شهرها از جمله برکلی، کالیفرنیا، جایی که دفاتر و مدارس به طور رسمی تعطیل هستند، جشن گرفته می شود. او در فیلم های متعددی توسط بازیگرانی مانند مورگان فریمن و دنزل واشنگتن به تصویر کشیده شده است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (508, 'جوئل فورمن', '<p>جوئل فورمن، پزشک خانواده، یک پزشک خانواده است که بر استفاده از روش های تغذیه ای و طبیعی برای پیشگیری و معکوس کردن بیماری ها تمرکز دارد. او ابتکار Health Starts Here را برای غذاهای کامل ایجاد کرد و مدیر تحقیقات پروژه تحقیقات تغذیه ای انجمن ملی سلامت است.</p>', '2023-01-26 19:43:14.68956', '2023-01-26 19:43:14.68956', NULL, 'Joel Fuhrman');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (509, 'جرمی گاتچه', '<p>جرمی گوتچه، یکی از پرطرفدارترین سخنرانان امروزی، مدیرعامل و بنیانگذار TrendHunter.com است. او به‌عنوان یک متخصص نوآوری، یک سبد یک میلیارد دلاری برای بانک Capital One ایجاد کرد و با ارائه بینش‌های تجاری زیرک خود، به بیش از سیصد برند برتر از جمله کوکاکولا، سونی و IBM کمک کرد.</p>', '2023-01-26 19:43:19.701971', '2023-01-26 19:43:19.701971', NULL, 'Jeremy Gutsche');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (510, 'ایان آیرس', '<p>یان آیرس وکیل، اقتصاد دان و استاد دانشکده حقوق و دانشکده مدیریت ییل است. او همچنین یک ستون نویس برای <em>Forbes</em>، یک مفسر معمولی در <em>Marketplace</em> و نویسنده چندین کتاب از جمله <em>Carrots and Sticks: Unlock the Power of Incentives to Get Things Done< /em>.</p>', '2023-01-26 19:43:24.514332', '2023-01-26 19:43:24.514332', NULL, 'Ian Ayres');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (511, 'پاراماهانسا یوگاناندا', '<p>پاراماهانسا یوگاناندا (۱۸۹۳–۱۹۵۲) یک یوگی، راهب و گورو هندی بود که میلیون‌ها تن از جانبازان آمریکایی و غربی را در کریا یوگا آغاز کرد. او برای پیشبرد مأموریت خود، انجمن خود تحقق بخشی را تأسیس کرد که اکنون بیش از 500 معبد، آشرام و مرکز مراقبه در سراسر جهان را اداره می کند. برخی از کتاب ها و تفسیرهای منتشر شده او عبارتند از <em>یوگای عیسی، علم دین</em>، و <em>بی ترس زیستن</em>.</p>', '2023-01-26 19:43:29.766539', '2023-01-26 19:43:29.766539', NULL, 'Paramahansa Yogananda');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (512, 'جولی سوندرا دکر', '<p>از سال 1998، جولی سوندرا دکر با ارائه مصاحبه و بینش برای رسانه‌های اصلی مانند <em>نیویورک تایمز</em> و <em>ماری کلر</em> به افزایش آگاهی در مورد غیرجنس‌گرایی کمک کرده است. دکر همچنین یک هنرمند وب کمیک و نویسنده داستان های علمی تخیلی و فانتزی است. او که عاشقانه و غیرجنسی است، در حال حاضر، با خوشحالی مجرد، در فلوریدا زندگی می کند.</p>', '2023-01-26 19:43:35.620595', '2023-01-26 19:43:35.620595', NULL, 'Julie Sondra Decker');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (513, 'جیمز ریکاردز', '<p>جیمز ریکاردز یک اقتصاددان، وکیل و بانکدار سرمایه‌گذاری است که به‌خاطر پرفروش‌ترین ارز <em>New</em> <em>York</em> <em>Times</em> در سال 2011 شناخته شده است. </em> <em>جنگ ها</em>.</p>', '2023-01-26 19:43:40.575772', '2023-01-26 19:43:40.575772', NULL, 'James Rickards');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (514, 'ناتالی برگ و میا نایتز', '<p>ناتالی برگ یک متخصص خرده‌فروشی بریتانیایی و مشاور متخصص در تجارت، قیمت‌گذاری و تمرکز بر خریدار است. او مدیر سابق تحقیقات جهانی در Planet Retail است و مشاور NBK Retail را اداره می کند. میا نایتز، یکی از نویسندگان او، رئیس Industry Insight در شرکت دیجیتال مارکتینگ Eagle Eye است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (515, 'کیت سوبودا', '<p>Kate Swoboda یک مربی زندگی، مدیر گواهینامه Courageous Living Coach، و خالق YourCourageousLife.com است. او به <em>Forbes، USA Today، Entrepreneur، Business Insider، Lifetime Moms</em> و دیگران کمک کرده است.</p>', '2023-01-26 19:44:01.653095', '2023-01-26 19:44:01.653095', NULL, 'Kate Swoboda');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (516, 'ریچل بوتسمن و رو راجرز', '<p>ریچل بوتسمن یکی از تأثیرگذارترین متفکران در زمینه همکاری است. او بنیانگذار انکوباتور نوآوری <em>Collaborative Lab</em>و همچنین مدیر سابق بنیاد پرزیدنت کلینتون است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (517, 'ترزا تورس', '<p>ترزا تورس محصول و مشاور و سخنران است. او به شرکت‌ها در سراسر جهان کمک کرده است تا تصمیمات خود را در مورد کشف و طراحی محصول اصلاح کنند، و همچنین نویسنده وبلاگ Product Talk است. </p>', '2023-01-26 19:44:15.642215', '2023-01-26 19:44:15.642215', NULL, 'Teresa Torres');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (518, 'وندی بورن', '<p> Wendy Born یک متخصص توسعه و مدیریت کسب و کار با بیش از 25 سال تجربه مربیگری رهبران در صنایع مختلف است. او همچنین فارغ التحصیل مدرسه هاروارد کندی و نویسنده <em>زبان های رهبری</em> است.</p>', '2023-01-26 19:44:21.037953', '2023-01-26 19:44:21.037953', NULL, 'Wendy Born');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (519, 'ویلیام سی تیلور', '<p>ویلیام سی. تیلور نویسنده، سخنران عمومی و متخصص تجارت تأثیرگذار است. او مجله تجاری ماهانه <em>Fast Company</em> را تأسیس کرد. تیلور چندین کتاب تحسین شده در مورد استراتژی شرکت نوشته است، از جمله <em>Simply Brilliant </em> (2016) و یکی از نویسندگان <em>Mavericks at Work</em>(2006) است.</p>', '2023-01-26 19:44:29.301685', '2023-01-26 19:44:29.301685', NULL, 'William C. Taylor');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (520, 'اسکات اچ یانگ', '<p> اسکات اچ یانگ نویسنده، برنامه نویس و کارآفرینی است که اشتیاق به تسلط بر خود و پیشرفت شغلی دارد. او سال‌ها را صرف مطالعه زندگی و کار فراآموزان کرده است، استراتژی‌های یادگیری باورنکردنی آن‌ها را کشف کرده و آنها را به اصول ساده‌ای که برای بهینه‌سازی یادگیری برای همه طراحی شده‌اند، تقطیر کرده است. اما یانگ فقط فراآموزان را مطالعه نکرده است، او <em>یکی</em>است. از طریق اصول فراآموزی، او حسابان محاسباتی چند متغیره را تا یک سطح دانشگاهی به خود آموخته و در زبان چینی ماندارین، در میان سایر زبان ها، مهارت پیدا کرده است.</p>', '2023-01-26 19:44:34.146788', '2023-01-26 19:44:34.146788', NULL, 'Scott H. Young');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (521, 'اما سپالا', '<p>Emma Seppälä مدیر علمی مرکز تحقیقات و آموزش ترحم و نوع دوستی در دانشگاه استنفورد است. او در خط مقدم تحقیقات شادی، مرتباً در <em>Harvard Business Review</em>و <em>Psychology Today</em> مطالبی را منتشر می کند. <em> مسیر خوشبختی</em> اولین کتاب او است.</p>', '2023-01-26 19:44:39.942243', '2023-01-26 19:44:39.942243', NULL, 'Emma Seppälä');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (522, 'هارویل هندریکس', '<p> هارویل هندریکس یک مشاور روابط با بیش از 30 سال تجربه است. او مهمان محبوب اپرا است و حضورش در این برنامه به او کمک کرده است تا برنامه درمان رابطه ایماگو را به مخاطبان بین المللی معرفی کند. او همچنین کتاب‌های پرفروش <em>دریافت عشق</em> و <em>حفظ عشقی که یافتید</em> را نوشت.</p>', '2023-01-26 19:44:44.802816', '2023-01-26 19:44:44.802816', NULL, 'Harville Hendrix');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (523, 'کارلوس گیل', '<p>کارلوس گیل یک داستان‌سرای دیجیتال با سال‌ها تجربه در توسعه استراتژی‌های رسانه‌های اجتماعی برای مارک‌های پیشرو مانند LinkedIn، Winn-Dixie، Save-A-lot و BMC Software است. او مدیر عامل و بنیانگذار شرکت گیل مدیا مستقر در لس آنجلس است. <em>پایان بازاریابی</em> اولین کتاب او است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (524, 'جان سی ماکسول', '<p>جان سی. ماکسول یک متخصص رهبری، سخنران حرفه ای، کشیش و نویسنده است. او مرتباً در شرکت‌های <em>500 فورچون </em>، NFL، و آکادمی نظامی ایالات متحده در وست پوینت سخنرانی می‌کند. او همچنین بنیانگذار EQUIP، یک سازمان بین المللی توسعه رهبری است. کتاب های پرفروش او عبارتند از <em>توسعه رهبر درون شما</em>و <em>15 قانون ارزشمند رشد. </em></p>', '2023-01-26 19:44:54.595243', '2023-01-26 19:44:54.595243', NULL, 'John C. Maxwell');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (525, 'ریک هانسون با فارست هانسون', '<p>ریک هانسون یک روانشناس و نویسنده پرفروش است. او دارای مدرک دکترا در روانشناسی بالینی، عضو ارشد مرکز علمی خوب در دانشگاه کالیفرنیا برکلی، و بنیانگذار موسسه ولسپرینگ برای علوم اعصاب و خرد متفکرانه است. هانسون یک سخنران دعوت شده در ناسا، آکسفورد، استنفورد، هاروارد و سایر دانشگاه های بزرگ بوده و در مراکز مدیتیشن در سراسر جهان تدریس کرده است. کتاب های قبلی او عبارتند از <em>خوشبختی سخت</em>، <em>مغز بودا</em>، <em>فقط یک چیز</em>، و <em>پرورش مادر</em>. </p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (526, 'اسکات استراتن و آلیسون استراتن', '<p> اسکات استراتن و همسرش، آلیسون استراتن، سخنرانان مهمان شناخته شده ای در رویدادهای شرکتی در سراسر جهان هستند. اسکات قبلاً به عنوان استاد در دانشکده بازرگانی کالج شریدان کار می کرد. در سال 2012، او در فهرست 50 تأثیرگذار برتر رسانه های اجتماعی در جهان در <em>Forbes</em> به عنوان شماره پنج قرار گرفت. او به همراه آلیسون که قبلاً یک تجارت لباس زیر زنانه بارداری را اداره می کرد، چهار کتاب پرفروش از جمله <em>UnSelling</em> و <em>The Book of Business (UnAwesome)</em> نوشته است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (527, 'کن کلمن', '<p>کن کلمن یک کارشناس حرفه ای، پادکست و مجری رادیو است. او مجری <em>نمایش کن کلمن</em> است، برنامه ای محبوب که به مردم کمک می کند حرفه واقعی خود را کشف کنند و حرفه خود را تغییر دهند. کلمن همچنین نویسنده <em>یک سوال</em> است. </p>', '2023-01-26 19:45:12.418475', '2023-01-26 19:45:12.418475', NULL, 'Ken Coleman');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (528, 'ریانون بوبین و رزی لیزرویس', '<p>Rhiannon Beaubien سردبیر و نویسنده در Farnam Street Media در اتاوا، کانادا است. او توسعه مجموعه کتاب‌های <em>مدل‌های ذهنی بزرگ</em></p> را رهبری می‌کند
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (529, 'آلن گانت', '<p> آلن گانت مدیر عامل و بنیانگذار TrackMaven است، یک سرویس تجزیه و تحلیل بازاریابی که با شرکت هایی مانند Home Depot، مایکروسافت و هوندا کار کرده است. گارنت در فهرست کارآفرینان و رهبران جوان برتر "30 زیر 30 سال" مجله فوربس قرار گرفته است و همچنین به FastCompany.com کمک کرده است.</p>', '2023-01-26 19:45:26.458598', '2023-01-26 19:45:26.458598', NULL, 'Allen Gannett');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (530, 'کارلا هریس', '<p>کارلا ای. هریس یک کهنه سرباز وال استریت با بیش از 30 سال تجربه است. او نویسنده دو کتاب موفق دیگر، <em>Expect to Win</em> و <em>Lead to Win</em> است. او نایب رئیس مدیریت ثروت و مشاور ارشد مشتری در مورگان استنلی است. او دارای مدرک تحصیلی از دانشگاه هاروارد است و در هیئت مدیره چندین سازمان غیرانتفاعی حضور دارد که در کنار حرفه خوانندگی به آنها دستکاری می کند.</p>', '2023-01-26 19:45:31.100682', '2023-01-26 19:45:31.100682', NULL, 'Carla A. Harris');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (531, 'مینارد وب و کارلی آدلر', '<p>Maynard Webb یک سرمایه گذار، مدیر عامل سابق eBay و رئیس هیئت مدیره یاهو است. او در حمایت از استارت‌آپ‌های آینده‌دار تخصص دارد و همچنین استارت‌آپ خود به نام Everwise را دارد که به کارآفرینان مشاوره می‌دهد.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (532, 'جکی استاوروس و چری تورس', '<p> جکی استاوروس استاد دانشگاه فناوری لارنس با بیش از 30 سال تجربه در رهبری، توسعه سازمانی و مدیریت تغییر است. او کتاب‌ها و مقالات بسیاری از جمله <em>آموزش اوج گرفتن</em> را تالیف کرده است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (533, 'جی هاینریش', '<p> جی هاینریش یک سردبیر و مدیر انتشارات سابق است که اولین حرفه خود را رها کرد تا سخنوری را به شغل تمام وقت خود تبدیل کند. او درباره تکنیک های بلاغی وبلاگ می نویسد و کارگاه هایی را با هدف رایج کردن استدلال برگزار می کند.</p>', '2023-01-26 19:45:53.80992', '2023-01-26 19:45:53.80992', NULL, 'Jay Heinrichs');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (534, 'ملیسا هارتویگ و دالاس هارتویگ', '<p>ملیسا هارتویگ یک درمانگر تغذیه است که در کمک به افراد در تنظیم عادات غذایی خود تخصص دارد. او یکی از خالقان برنامه Whole30 و همچنین نویسنده و سخنران موفقی است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (535, 'گاوین فرانسیس', '<p>گاوین فرانسیس به عنوان پزشک اطفال، جراح، متخصص اورژانس، جراح مغز و اعصاب کارآموز و حتی پزشک اعزامی در قطب شمال و قطب جنوب کار کرده است. او اکنون با خانواده اش در ادینبورگ اسکاتلند زندگی می کند و به عنوان پزشک خانواده کار می کند. قبل از این کتاب، فرانسیس دو سفرنامه درباره تجربیات خود به عنوان یک پزشک اعزامی نوشت - <em>شمال واقعی: سفر در اروپای قطبی</em> و <em>امپراتوری قطب جنوب: یخ، سکوت، و پنگوئن‌های امپراتور</em>. کتاب اخیر برنده جایزه کتاب سال اسکاتلند برای سال 2013 شد.</p>', '2023-01-26 19:46:04.163599', '2023-01-26 19:46:04.163599', NULL, 'Gavin Francis');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (536, 'جفری گیتومر', '<p>جفری گیتومر یک نویسنده برنده جایزه، سخنران حرفه ای و مربی کسب و کار است که بر فروش، وفاداری مشتری و توسعه شخصی تمرکز دارد. او کتاب های متعددی از جمله <em>مفاهیم وفاداری مشتری</em>و <em>کتاب کوچک رهبری</em> نوشته است.</p>', '2023-01-26 19:46:09.035373', '2023-01-26 19:46:09.035373', NULL, 'Jeffrey Gitomer');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (537, 'دیو کرنشاو', '<p>Dave Crenshaw یک مربی تجاری بسیار مورد توجه است که به بهبود شرکت ها در سراسر جهان کمک کرده است. نوشته های او در نشریاتی مانند مجله <em>تایم </em>و<em>واشنگتن پست</em> منتشر شده است. چهارمین کتاب او، <em>قدرت تفریح،</em> قرار است در پاییز 2017 منتشر شود.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (538, 'هیروتاکا تاکوچی', '<p>ایکوجیرو نوناکا از دهه 1960 زمانی که شیوه‌های مدیریتی جدیدی را در فوجی الکتریک آغاز کرد، رویه‌های تجاری تأثیرگذار و تغییردهنده‌ای را توسعه داده است. او از آن زمان تاکنون به یکی از معتبرترین نظریه پردازان تجارت در جهان تبدیل شده است، با بینش خود در مورد مدیریت دانش، نحوه اداره بسیاری از شرکت ها را تغییر داده است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (539, 'تیم هارفورد', '<p>تیم هارفورد روزنامه‌نگار، گوینده و اقتصاددان است. او برنامه رادیو بی‌بی‌سی 4 <em>کم و بیش</em> را ارائه می‌کند که آماری را از داستان‌های خبری توضیح می‌دهد. او در سال 2006 برنده جایزه باستیا برای روزنامه نگاری خود شد.</p>', '2023-01-26 19:46:23.595597', '2023-01-26 19:46:23.595597', NULL, 'Tim Harford');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (540, 'سیلویا آن هیولت', '<p> سیلویا آن هیولت یک اقتصاددان و متخصص تجارت و همچنین بنیانگذار و مدیر عامل مرکز نوآوری استعدادها است. او 11 کتاب نوشته است که مورد تحسین منتقدان قرار گرفته است.</p>', '2023-01-26 19:46:28.121208', '2023-01-26 19:46:28.121208', NULL, 'Sylvia Ann Hewlett');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (541, 'دیوید آ. سینکلر و متیو دی. لاپلانت', '<p>David A. Sinclair، PhD، دانشمند برجسته و استاد ژنتیک در دانشکده پزشکی هاروارد است. مجله <em>تایم</em>او را یکی از 50 فرد تأثیرگذار در مراقبت های بهداشتی <em>و </em>یکی از 100 تأثیرگذارترین فرد در جهان معرفی کرده است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (542, 'مارتین لانیک', '<p>مارتین لانیک مدیر عامل Pinsight است، یک شرکت مشاوره که توسعه رهبری را تقویت می کند. رویکرد او که مستلزم جلسات تمرینی کوتاه است که در یک روز پخش می‌شوند، در <em>Forbes</em>،<em>Fast Company</em>،<em> Chief Learning Officer</em>و Monster.com به نمایش گذاشته شده است. . این تکنیک در شرکت هایی از جمله AIG و CenturyLink پیاده سازی شده است. Lanik دارای مدرک دکترا از دانشگاه ایالتی کلرادو در روانشناسی صنعتی-سازمانی است.</p>', '2023-01-26 19:46:37.902419', '2023-01-26 19:46:37.902419', NULL, 'Martin Lanik');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (543, 'جای سامیت', '<p>جی سامیت یک اخلالگر سریالی و یکی از کارشناسان برجسته کارآفرینی در جهان است. در طول سه دهه گذشته، او صدها میلیون دلار برای استارت‌آپ‌ها جمع‌آوری کرده است، به شرکت‌های Fortune 500 مشاوره داده و به تغییر کل صنایع کمک کرده است. او همچنین استادیار دانشکده مهندسی ویتربی دانشگاه کالیفرنیای جنوبی است.</p>', '2023-01-26 19:46:42.6715', '2023-01-26 19:46:42.6715', NULL, 'Jay Samit');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (544, 'مارتین والن', '<p>مارتین والن، استاد زبان انگلیسی در دانشگاه ایالتی اوکلاهاما و متخصص در مورد چگونگی ارتباط فرهنگ ما با حیوانات، به‌ویژه سگ‌ها و روباه‌ها است. او در سال 2004 کتاب <em>شهر سلامت، زمینه های بیماری</em> را منتشر کرد.</p>', '2023-01-26 19:46:48.06999', '2023-01-26 19:46:48.06999', NULL, 'Martin Wallen');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (545, 'ادگار اچ شاین', '<p>ادگار اچ. شاین، استاد بازنشسته مدیریت انجمن یاران اسلون در موسسه فناوری ماساچوست است و جوایز و افتخارات زیادی را در طول حرفه خود دریافت کرده است. او همچنین تعدادی کتاب نوشته است، از جمله <em>فرهنگ سازمانی و رهبری</em>و<em> راهنمای بقای فرهنگ شرکت</em>.</p>', '2023-01-26 19:46:52.879126', '2023-01-26 19:46:52.879126', NULL, 'Edgar H. Schein');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (546, 'روری ودن', '<p>روری وادن، MBA، نویسنده، کارآفرین و سخنران انگیزشی است. او به عنوان یکی از بنیانگذاران مشاوره ساوت وسترن، به مشتریان در سراسر جهان کمک می کند تا کسب و کار خود را توسعه دهند و تجربه مشتری خود را بهبود بخشند. اولین کتاب وادن، <em>از پله‌ها بردار</em>یک کتاب پرفروش <em>وال استریت ژورنال</em>بود. بینش بهره‌وری او در <em>CNN</em> و <em>Oprah Radio</em> نمایش داده شده است.</p>', '2023-01-26 19:46:57.944134', '2023-01-26 19:46:57.944134', NULL, 'Rory Vaden');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (547, 'مرلین شلدریک', '<p>مرلین شلدریک یک زیست شناس قارچی با مدرک دکترا در اکولوژی استوایی از دانشگاه کمبریج است. تحقیقات او در درجه اول بر روی بیولوژی قارچی و تاریخچه گیاه شناسی قومی آمازون متمرکز است. او همچنین یک نوازنده، آبجوساز و تخمیرکننده است.</p>', '2023-01-26 19:47:03.014562', '2023-01-26 19:47:03.014562', NULL, 'Merlin Sheldrake');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (548, 'لیندسی پولاک', '<p>لیندزی پولاک متخصص در مسائل محل کار و نسل هزاره است و برای مشتریان شرکتی مانند لینکدین، جایی که اکنون به عنوان سفیر رسمی در آنجا خدمت می کند، مشاوره کرده است. او نوشت <em>رفتن از دانشگاه به حرفه: راهنمای ضروری شما برای موفقیت در دنیای واقعی، و توصیه های او در رسانه های مشهوری مانند <em>CNN</em>، <em>The Wall ظاهر شده است. استریت ژورنال</em> و <em>نیویورک تایمز</em>.</p>', '2023-01-26 19:47:07.569716', '2023-01-26 19:47:07.569716', NULL, 'Lindsey Pollak');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (549, 'تاد هرمان', '<p>تاد هرمان یک کارشناس عملکرد مستقر در شهر نیویورک است. او بیش از دو دهه را به مربیگری مجریان نخبه، عمدتاً در زمینه ورزش و تجارت گذرانده است. او خالق سال 90 روز، یک برنامه نمایشی برنده جایزه است.</p>', '2023-01-26 19:47:12.545176', '2023-01-26 19:47:12.545176', NULL, 'Todd Herman');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (550, 'مارک ماهانی', '<p>مارک ماهانی مدیر عامل ارشد و رئیس تحقیقات اینترنت در Evercore ISI است. او همواره به عنوان یکی از برترین تحلیلگران اینترنتی توسط مجله <em>Institutional Investor</em> رتبه بندی شده است. <em>Nothing But Net</em>اولین کتاب اوست.</p>', '2023-01-26 19:47:17.240272', '2023-01-26 19:47:17.240272', NULL, 'Mark Mahaney');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (551, 'مارگوت لی شترلی', '<p>مارگو لی شترلی در همپتون، ویرجینیا بزرگ شد، جایی که با بسیاری از زنانی که در <em>شکل های پنهان</em> درباره آنها می نویسد، آشنا شد. او دریافت کننده کمک هزینه تحقیقاتی بنیاد ویرجینیا برای علوم انسانی و عضو کمک هزینه تحصیلی بنیاد آلفرد پی اسلون است.</p>', '2023-01-26 19:47:25.248255', '2023-01-26 19:47:25.248255', NULL, 'Margot Lee Shetterly');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (552, 'دونا مک جورج', '<p>دونا مک جورج نویسنده، سخنران و مربی محل کار است که دوران حرفه ای خود را صرف کمک به افراد در افزایش ارزش زمان صرف شده در محل کار خود کرده است. در طول 20 سال گذشته، او با همه افراد از نیسان موتورز گرفته تا جت استار کار کرده و برای <em>عصر</em> و <em>شرکت هوشمند</em> مقالاتی نوشته است، همگی با هدف کمک به شرکت‌ها و کارمندان در پیشرفت. بهره وری و اثربخشی در محل کار.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (553, 'جفری هایزلت در کنار جیم ایبر', '<p>جفری هایزلت مجری برجسته تلویزیونی و مجری پادکست است. او همچنین مدیر ارشد بازاریابی سابق یک شرکت Fortune 100 و مشارکت کننده منظم در صفحات تجاری <em>Forbes، Mashable</em> و <em>Marketing Week است. </em></p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (554, 'پل هال', '<p>پائولا هال نویسنده و روان درمانگری است که در کمک به زوج ها برای غلبه بر مشکلات جنسی و عاشقانه تخصص دارد. او همچنین بنیانگذار موسسه آموزش اعتیاد به سکس و رئیس بخش بازیابی پروژه حقیقت برهنه است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (555, 'دیو آسپری', '<p>دیو آسپری نویسنده پرفروش <em>نیویورک تایمز</em> و رئیس موسسه سلامت سیلیکون ولی است.</p>', '2023-01-26 19:47:45.05631', '2023-01-26 19:47:45.05631', NULL, 'Dave Asprey');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (556, 'آن بویر', '<p>آن بویر شاعر و مقاله‌نویس است و خود را "شخص معمولی" توصیف می‌کند. او استاد موسسه هنر کانزاس سیتی است. او در سال 2020 برنده جایزه پولیتزر شد.</p>', '2023-01-26 19:47:49.95437', '2023-01-26 19:47:49.95437', NULL, 'Anne Boyer');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (557, 'باربارا ارنرایش', '<p>باربارا ارنرایش نویسنده <em>نیویورک تایمز</em> پرفروش <em>نیکل و دایم</em> است، که افشاگری از مشاغل کم درآمد در آمریکا است. او همچنین دارای مدرک دکترای ایمونولوژی سلولی است.</p>', '2023-01-26 19:47:54.97791', '2023-01-26 19:47:54.97791', NULL, 'Barbara Ehrenreich');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (558, 'توماس سی فاستر', '<p>فاستر از سال 1975 به تدریس ادبیات پرداخته است. یک استاد انگلیسی در دانشگاه میشیگان-فلینت، کتاب او در بین معلمان و دانشجویان انگلیسی محبوبیت پیدا کرده است. فاستر همچنین در بسیاری از دبیرستان ها در سراسر ایالات متحده سخنران است و سخنرانی ها و کارگاه های آموزشی در مورد نحوه آموزش و درک ادبیات ارائه می دهد.</p>', '2023-01-26 19:48:00.032152', '2023-01-26 19:48:00.032152', NULL, 'Thomas C. Foster ');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (559, 'کارل بارت', '<p>کارل بارت متکلم سوئیسی (1886-1968) یکی از مهم ترین متفکران دینی قرن بیستم بود. آثار برجسته او عبارتند از <em>نامه به رومیان</em> و چهار جلدی ناتمام <em>جزمیات کلیسا</em>. او همچنین به خاطر نوشتن "اعلامیه بارمن" به عنوان بخشی از کلیسای اعتراف کننده آلمان - گروه پروتستانی که با رایش سوم مخالف بود، شناخته شده است. نوشته های بارت به چندین زبان ترجمه شده است و او در سال 1962 روی جلد مجله <em>Time</em> قرار گرفت.</p>', '2023-01-26 19:48:04.878389', '2023-01-26 19:48:04.878389', NULL, 'Karl Barth');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (560, 'ناپلئون هیل', '<p>ناپلئون هیل (1883-1970) از پیشگامان نوشتن انگیزشی و خودسازی بود. او برخی از اولین کتاب‌های خودیاری را در ایالات متحده نوشت، از جمله کتاب برجسته <em>تفکر کن و ثروتمند شو</em> (1937)، که به عنوان یکی از 20 کتاب پرفروش خودیاری در بین همه باقی مانده است. زمان. کتاب های او همچنان توسط میلیون ها نفر در سراسر جهان خوانده می شود.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (561, 'سارا سی مدنیک', '<p>سارا سی. مدنیک مدیر آزمایشگاه خواب و شناخت در دانشگاه کالیفرنیا، ایروین است، جایی که او همچنین استاد روانشناسی است. او همچنین نویسنده <em>Take a Nap است! زندگی خود را تغییر دهید</em> تحقیقات او از مؤسسه ملی بهداشت و بنیاد ملی علوم حمایت مالی شده است.</p>', '2023-01-26 19:48:14.840277', '2023-01-26 19:48:14.840277', NULL, ' Sara C. Mednick');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (587, 'برنادت سول', '<p>برنادت جیوا یک کارشناس داستان سرایی و بازاریابی برند استرالیایی است. او تعدادی کتاب پرفروش از جمله <em>ایده خود را مهم کنید</em> و <em>بازاریابی: داستان عشق</em> و وبلاگ‌هایی در thestoryoftelling.com نوشته است.</p>', '2023-01-26 19:50:38.736841', '2023-01-26 19:50:38.736841', NULL, 'Bernadette Jiwa');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (562, 'راشل پدرسن', '<p>ریچل پدرسن مدیر عامل آژانس بازاریابی دیجیتال SocialWorks برنده جایزه و بنیانگذار Social Media United، یک مرکز آنلاین پیشرو برای آموزش رسانه های اجتماعی است. راشل به‌عنوان مشاور و استراتژیست تمام وقت رسانه‌های اجتماعی، به صاحبان مشاغل و متخصصان رسانه‌های اجتماعی کمک می‌کند تا از رسانه‌های اجتماعی استفاده کنند و پتانسیل رشد خود را سریع دنبال کنند.</p>', '2023-01-26 19:48:19.858345', '2023-01-26 19:48:19.858345', NULL, 'Rachel Pedersen');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (563, 'لیزا ارل مک لئود', '<p>لیزا ارل مک‌لئود یک کارشناس فروش است که برای شرکت‌های پیشرو مانند Procter & Gamble، Apple و Kimberly-Clark کار کرده است. او مفسر وب سایت تجاری Forbes.com است و برای <em>نیویورک تایمز</em> و <em>وال استریت ژورنال</em> نوشته است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (564, 'نثر فرانسین', '<p>فرانسین پرز نویسنده و مقاله نویس پرفروش است. او همچنین برنده چندین جایزه ادبی و فینالیست جایزه ملی کتاب در سال 2000 برای رمانش به نام <em>فرشته آبی</em> شد.</p>', '2023-01-26 19:48:29.643699', '2023-01-26 19:48:29.643699', NULL, 'Francine Prose');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (565, 'نیکلاس شاکسون', '<p> نیکلاس شاکسون روزنامه نگار و همکار موسسه سلطنتی امور بین الملل است. او نویسنده <em>چاههای مسموم: سیاست کثیف نفت آفریقا</em> و همچنین محقق شبکه عدالت مالیاتی است.</p>', '2023-01-26 19:48:35.43117', '2023-01-26 19:48:35.43117', NULL, 'Nicholas Shaxson');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (566, 'پیتر زیهان', '<p>پیتر زیهان متخصص ژئوپلیتیک است، که به مطالعه چگونگی تأثیر موقعیت جغرافیایی بر تحولات اقتصادی، فرهنگی، سیاسی و نظامی می‌پردازد. کارهای او در <em>Forbes</em>،<em> Bloomberg</em>، <em>نیویورک تایمز</em> و <em>وال استریت ژورنال</em></p به نمایش درآمده است. >', '2023-01-26 19:48:40.268557', '2023-01-26 19:48:40.268557', NULL, 'Peter Zeihan');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (567, 'مری آباجی', '<p>Mary Abbajay نویسنده، سخنران و مشاور مدیریت است. Abbajay به عنوان رئیس گروه مشاوره توسعه رهبری Cornerstone، به سازمان ها کمک می کند تا مهارت ها، استراتژی ها و فرهنگ محل کار مورد نیاز برای موفقیت قرن 21 را پرورش دهند. </p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (568, 'تیم براون', '<p>تیم براون، مدیر اجرایی IDEO، یک شرکت مشاوره بین‌المللی در زمینه طراحی و نوآوری است. او جوایز طراحی بسیاری را به دست آورده است و رویکرد "تفکر طراحی" خود را در کار خود برای شرکت های بین المللی، دولت ها و سایر موسسات به کار برده است.</p>', '2023-01-26 19:48:50.362915', '2023-01-26 19:48:50.362915', NULL, 'Tim Brown');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (569, 'جاش کافمن', '<p>جاش کافمن یک محقق مستقل در موضوعاتی مانند تجارت، کارآفرینی، بهره وری و روانشناسی رفتاری است. او به عنوان یکی از بهترین نویسندگان تجاری توسط آمازون رتبه بندی شده است. اولین کتاب او، <em>MBA شخصی: استاد هنر تجارت</em>، پرفروش‌ترین کتاب بود.</p>', '2023-01-26 19:48:55.44146', '2023-01-26 19:48:55.44146', NULL, 'Josh Kaufman');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (570, 'چاندرامولی ونکاتسان', '<p>چاندرامولی ونکاتسان نویسنده و کارشناس مدیریت با بیش از 26 سال تجربه در خط مقدم شرکت است. کارفرمایان قبلی او عبارتند از Asian Paints، بزرگترین تولید کننده رنگ در هند، غول بریتانیایی Cadbury و Mirc Electronics. Venkatesan در حال حاضر مدیر عامل شرکت Pidilite Industries است. او همچنین نویسنده <em>بهتر شدن در بهتر شدن</em> است.</p>', '2023-01-26 19:49:03.864377', '2023-01-26 19:49:03.864377', NULL, 'Chandramouli Venkatesan');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (571, 'داونا مارکووا', '<p>داونا مارکووا یک متخصص مشهور در روانشناسی یادگیری و ادراک انسان و نویسنده کتاب معروف <em>اعمال تصادفی مهربانی</em> است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (572, 'دیوید اورل و رومن هیری', '<p>دیوید اورل نویسنده کانادایی با مدرک دکترای ریاضیات از دانشگاه آکسفورد است. نوشته های او در چندین نشریه اقتصادی به نمایش درآمده است و کتاب های دیگر او عبارتند از <em>حقیقت یا زیبایی: علم </em>و <em>جستجوی نظم</em>.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (573, 'کیت راورث', '<p>کیت راورث یک همکار ارشد پژوهشی مهمان در موسسه تغییرات محیطی دانشگاه آکسفورد است. کار راورث که خود را مرتد در حرفه اقتصاد معرفی می کند، بر پایداری اجتماعی، اقتصادی و زیست محیطی در قرن بیست و یکم متمرکز شده است. او که توسط روزنامه <em>گاردین </em> به عنوان یکی از ده توئیتر برتر در حوزه کاری خود نامگذاری شده است، ایده های خود را از مجمع عمومی سازمان ملل گرفته تا جنبش اشغال را به همه ارائه کرده است.</p>', '2023-01-26 19:49:23.656506', '2023-01-26 19:49:23.656506', NULL, 'Kate Raworth');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (574, 'Thich Nhat Hanh و Lilian Cheung', '<p>Thich Nhat Hanh یک راهب بودایی مشهور بین المللی از ویتنام بود. او همچنین یک فعال صلح و نویسنده ای پرکار بود و در طول زندگی خود حدود 100 کتاب منتشر کرد. </p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (575, 'باب چپمن و راج سیسودیا', '<p>باب چپمن از سال 1975 مدیرعامل Barry-Wehmiller، یک شرکت تولیدی جهانی است. به لطف رهبری او، ارزش شرکت او 1.5 میلیارد دلار است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (576, 'ماه رمضان', '<p>الرمدان، دیو پترسون و کریستوفر لاچهد از بنیان‌گذاران Play Bigger Advisors هستند که در آنجا شرکت‌های فناوری را راهنمایی می‌کنند تا به آنها کمک کنند در دسته‌های بازار مربوطه خود تسلط داشته باشند. درباره کار آنها در www.playbigger.com بیشتر بیاموزید. </p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (577, 'سامی دیویس', '<p>سامی دیویس جونیور (1925-1990) یک خواننده، بازیگر، رقصنده، کمدین و خیلی چیزهای دیگر بود. او برای اولین بار در دهه 1950 به عنوان بخشی از سه گروه وودویل با پدرش به شهرت رسید. او بعداً با بازی در برادوی، لاس‌وگاس، در برنامه تلویزیونی خود و در فیلم‌های موفقی مانند Ocean''s 11 به شهرت رسید. او دو زندگی‌نامه نوشت، بله من می‌توانم، و چرا من؟</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (578, 'امیلی اصفهانی اسمیت', '<p>امیلی اصفهانی اسمیت ویراستار مؤسسه هوور دانشگاه استنفورد است و درباره فرهنگ و روانشناسی برای <em> معیار جدید</em> می نویسد. مقالات او همچنین در <em>وال استریت ژورنال</em>، <em>نیویورک تایمز</em> و <em>آتلانتیک</em> ظاهر شده است.</p>', '2023-01-26 19:49:48.597441', '2023-01-26 19:49:48.597441', NULL, 'Emily Esfahani Smith');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (579, 'بن مور', '<p>بن مور مدیر مرکز اخترفیزیک نظری و کیهان شناسی در دانشگاه زوریخ است. تحقیقات او بر روی کیهان شناسی، گرانش، فیزیک ذرات ستاره و تشکیل سیاره متمرکز است. او همچنین یک نوازنده است و موسیقی الکترونیک را با نام هنرمندش پروفسور مور و با گروه الکترو-راک Milk67 منتشر می‌کند.</p>', '2023-01-26 19:49:57.38073', '2023-01-26 19:49:57.38073', NULL, 'Ben Moore');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (580, 'الکس فرگوسن', '<p>سر الکس فرگوسن مدیر سابق تیم فوتبال بریتانیا منچستریونایتد است. او با کسب 49 جام، از جمله عناوین جام حذفی، لیگ برتر و لیگ قهرمانان، موفق ترین سرمربی بریتانیایی تمام دوران محسوب می شود. امروزه، فرگوسن یکی از اعضای برنامه آموزش اجرایی در مدرسه بازرگانی هاروارد است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (581, 'اورت ام راجرز', '<p>دکتر اورت ام راجرز از پیشگامان تحقیق در مورد انتشار نوآوری است و عبارت معروف «پذیرنده اولیه» را ابداع کرد. راجرز قبل از مرگش در سال 2004، یک استاد ممتاز و ممتاز در گروه ارتباطات و روزنامه نگاری در دانشگاه نیومکزیکو بود.</p>', '2023-01-26 19:50:07.452691', '2023-01-26 19:50:07.452691', NULL, 'Everett M. Rogers');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (582, 'جیمز والمن', '<p>جیمز والمن یک سخنران و مفسر فرهنگی مورد تقاضا است که در مکان هایی مانند آکادمی سلطنتی لندن و دفتر مرکزی گوگل سخنرانی کرده است. او رئیس یک شرکت پیش‌بینی روند است که مشتریانش شامل Eventbrite و KFC هستند و نوشته‌های او در نشریاتی از جمله <em>نیویورک تایمز</em> و <em>GQ</em> منتشر شده است. او همچنین نویسنده پرفروش‌ترین کتاب بین‌المللی <em>Stuffocation</em> (2013) است.</p>', '2023-01-26 19:50:12.950503', '2023-01-26 19:50:12.950503', NULL, 'James Wallman');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (583, 'سیمون ویزنتال', '<p>سایمون ویزنتال یک بازمانده از هولوکاست بود که زندگی خود را وقف محاکمه جنایتکاران جنگی نازی کرد. او کتاب های زیادی در این زمینه منتشر کرده است، از جمله <em>قاتلان در میان ما</em> و <em>عدالت نه انتقام</em>، و برای این کار در سطح بین المللی مورد تحسین قرار گرفته است. مرکز سیمون ویزنتال، که برای حقوق بشر یهودیان مبارزه می کند، در لس آنجلس مستقر است.</p>', '2023-01-26 19:50:18.416956', '2023-01-26 19:50:18.416956', NULL, 'Simon Wiesenthal');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (584, 'جیمز دونوان', '<p>جیمز دونووان نویسنده آمریکایی متخصص در تاریخ عامه پسند است. کتاب‌های پرفروش قبلی او عبارتند از <em>شکوه وحشتناک: کاستر و بیگورن کوچک – آخرین نبرد بزرگ غرب آمریکا</em> (2008)<em> </em>و<em> خون قهرمانان : مبارزه 13 روزه برای آلامو – و فداکاری که یک ملت را ساخت </em>(2012). او در دالاس، تگزاس زندگی می کند. </p>', '2023-01-26 19:50:23.292118', '2023-01-26 19:50:23.292118', NULL, 'James Donovan');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (585, 'آنیتا میترا', '<p>دکتر آنیتا میترا یک پزشک NHS است که در زمینه زنان و زایمان کار می کند. او دکترای خود را با مطالعه میکروبیوم واژن در پیش سرطان دهانه رحم و سرطان و همچنین عوارض باروری ناشی از پیش سرطان دهانه رحم دریافت کرد. او وبلاگ محبوب و حساب اینستاگرام @gynaegeek را اداره می کند.</p>', '2023-01-26 19:50:28.312892', '2023-01-26 19:50:28.312892', NULL, 'Anita Mitra');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (586, 'وین کاسیو و جان بودرو', '<p>Wayne F. Cascio یک استاد برجسته در دانشگاه کلرادو است و دارای کرسی رابرت اچ. رینولدز در رهبری جهانی در دانشگاه کلرادو دنور است. </p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (625, 'بندیکت کری', '<p>بندیکت کری گزارشگر علمی <em>نیویورک تایمز</em> است و تعدادی کتاب از جمله <em>Poison Most Vial</em>و <em>The Unknowns</em> نوشته است. .</p>', '2023-01-26 19:54:12.025747', '2023-01-26 19:54:12.025747', NULL, 'Benedict Carey');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (588, 'ژان تئوهاریس', '<p> جین تئوهاریس، دکترا، تحصیلات خود را در هاروارد و دانشگاه میشیگان به پایان رساند و استاد برجسته علوم سیاسی در کالج بروکلین در دانشگاه سیتی نیویورک است. او متخصص سیاست‌های نژادی معاصر در ایالات متحده است و چندین عنوان در این زمینه نوشته و با هم همکاری کرده است.</p>', '2023-01-26 19:50:48.213338', '2023-01-26 19:50:48.213338', NULL, 'Jeanne Theoharis');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (589, 'ماریسا اور', '<p>ماریسا اور تجربه دست اول گسترده ای از تلاش های نادرست شرکتی برای از بین بردن شکاف جنسیتی دارد - او به مدت 15 سال در گوگل و فیس بوک کار می کرد، همه در زمانی که مادر سه فرزند مجرد بود. در اینجا، کهنه‌کار صنعت فناوری، جایی که فمینیسم شرکت‌ها در حال شکست دادن زنان است را تشریح می‌کند و مشخص می‌کند که شرکت‌ها باید <em>واقعاً </em>چه کاری را برای ترویج برابری در محیط کار انجام دهند.</p>', '2023-01-26 19:50:53.441237', '2023-01-26 19:50:53.441237', NULL, 'Marissa Orr');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (590, 'استانزیونه برنده می شود', '<p>وینس استانزیونه، نویسنده و تاجر انگلیسی-آمریکایی، قبل از به دست آوردن ثروت در روزهای پر هیاهوی انقلاب مالی تاچری در لندن، کار خود را به عنوان یک آرایشگر شاگرد آغاز کرد. پس از سقوط در سقوط مالی سال 1987، او امپراتوری خود را با تمرکز بر مشاغل سفارش پستی و تجارت کالا بازسازی کرد. عنوان اولین او <em>انصراف میلیونر</em>یکی از پرفروش‌ترین کتاب‌های <em>نیویورک تایمز</em>است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (591, 'کیت رولاگ', '<p>کیت رولاگ دانشیار در کالج بابسون است. او در رفتار سازمانی و اجتماعی سازی و آموزش افراد تازه وارد تخصص دارد. آثار او در تعدادی از نشریات از جمله <em>به‌روزرسانی مدیریت هاروارد</em>، <em>بازبینی نوآوری اجتماعی استنفورد</em> و <em>Wired News</em> ظاهر شده است.</p>', '2023-01-26 19:51:04.221309', '2023-01-26 19:51:04.221309', NULL, 'Keith Rollag');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (592, 'موسسه دیزنی و تئودور کینی', '<p>مؤسسه دیزنی شرکت‌ها را از طریق سمینارها، کارگاه‌ها و ارائه‌های شیوه‌ها و دانش کسب‌شده و اجرا شده توسط شرکت والت دیزنی آموزش می‌دهد.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (593, 'کاترین ام راجرز', '<p>کاترین ام. راجرز، استاد بازنشسته ادبیات انگلیسی در دانشگاه سیتی نیویورک است و آثار فراوانی در مورد ادبیات قرن هجدهم و نوزدهم نوشته است. راجرز به عنوان یک نویسنده علاقه خود را به طیف وسیعی از موضوعات با کتاب هایی مانند <em>ملاحظات بی مهرگان</em> و <em>پورت – تاریخ جهانی</em> نشان داده است. راجرز اکنون بازنشسته است و در حال حاضر در مریلند زندگی می‌کند، جایی که در شور و شوق خود برای تاریخ ملی افراط می‌کند.</p>', '2023-01-26 19:51:14.573598', '2023-01-26 19:51:14.573598', NULL, 'Katharine M. Rogers');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (594, 'بعدش شد', '<p>سام کین در مجلات علمی متعددی، <em>نیویورک تایمز</em> و <em>روانشناسی امروز</em> مشارکت دارد. او دو کتاب پرفروش تاریخ علم دیگر منتشر کرده است: <em>قاشق در حال ناپدید شدن</em> و <em>The Violinist''s Thumb</em>.</p>', '2023-01-26 19:51:19.393522', '2023-01-26 19:51:19.393522', NULL, 'Sam Kean');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (595, 'ابزار و کاوازاکی', '<p>نویسنده پرفروش، گای کاوازاکی، سرمایه‌گذار و استاد بازاریابی مشهور سیلیکون ولی، برای اولین بار در دهه 1980 به عنوان یک «مبلغ نرم‌افزار» برای اپل نامی دست و پا کرد. او بعداً شرکت نرم افزاری خود را تأسیس کرد، به عنوان سفیر برند در مرسدس بنز خدمت کرد و به موتورولا مشاوره داد. کتاب های قبلی گای عبارتند از <em>راه مکینتاش </em>(1990)، <em>هنر شروع</em>(2004) و <em>افسون </em>(2011).</p>', '2023-01-26 19:51:24.323223', '2023-01-26 19:51:24.323223', NULL, 'Guy Kawasaki');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (596, 'لاخیانی می پوشند', '<p>ویشن لاخیانی یک کارآفرین مالزیایی الاصل است. او بنیانگذار و مدیر عامل شرکت Mindvalley است، شرکتی که برای آموزش و توانمندسازی افراد طراحی شده و به آنها کمک می کند تا به پتانسیل کامل خود دست یابند. لاخیانی یک سخنران مکرر در مورد بهبود ذهنیت های تجاری و فرهنگ شرکت است، و همچنین بنیانگذار Awesomeness Fest، یک رویداد توسعه شخصی برای کارآفرینان و نویسندگان است.</p>', '2023-01-26 19:51:29.879261', '2023-01-26 19:51:29.879261', NULL, 'Vishen Lakhiani');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (597, 'جفری دیویس', '<p>جفری دیویس نویسنده و مشاور برندسازی است که سرپرستی یک تیم خلاق در Tracking Wonder Consultancy را بر عهده دارد. او در کنفرانس ها و دانشگاه ها سخنرانی می کند و همچنین نویسنده <em>سفر از مرکز به صفحه</em> و دو مجموعه شعر است.</p>', '2023-01-26 19:51:34.599886', '2023-01-26 19:51:34.599886', NULL, 'Jeffrey Davis');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (598, 'رندی موشر', '<p>رندی موشر یک مرجع مشهور جهانی در زمینه آبجوسازی خانگی است. یکی از اعضای هیئت مدیره انجمن آبجوسازان خانگی آمریکا و انجمن آبجو شیکاگو، آثار قبلی او عبارتند از <em>همراه آبجو</em>، <em>آبجو برای همه فصول</em>، و <em>چشیدن آبجو</em>.</p>', '2023-01-26 19:51:39.840665', '2023-01-26 19:51:39.840665', NULL, 'Randy Mosher');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (599, 'پل آردن', '<p>پل آردن یک مغز متفکر خلاق با بیش از 30 سال تجربه در صنعت تبلیغات است. او با شرکت های بزرگی مانند تویوتا، بریتیش ایرویز و فوجی برای ایجاد برخی از موفق ترین کمپین های تبلیغاتی در بریتانیا کار کرده است. او همچنین نویسنده <em>هر چه فکر می کنی، برعکس فکر کن</em> (2006) و <em>خدا در تاکسی توضیح داد</em> (2007) است.</p>', '2023-01-26 19:51:44.563628', '2023-01-26 19:51:44.563628', NULL, 'Paul Arden');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (600, 'کریستوفر کارتر', '<p> کریستوفر کارتر یک مربی اجرایی و رهبر مدیتیشن است که در تقاطع تجارت و آگاهی کار می کند. پادکست او، <em>This Epic Life</em>، هزاران شنونده دارد که هر روز از آن برای تمرین مراقبه استفاده می کنند. کارتر که یک سخنران مشهور بین المللی است در Wisdom 2.0 و TEDx و همچنین در برنامه های خبری صبحگاهی CBS، NBC، FOX و ABC روی صحنه ظاهر شده است.</p>', '2023-01-26 19:51:50.474985', '2023-01-26 19:51:50.474985', NULL, 'Kristoffer Carter');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (601, 'جب بلونت', '<p>Jeb Blount یک مشاور شتاب دهنده فروش با چندین دهه تجربه در خط مقدم فروش است. او علاوه بر این که نویسنده ای پرفروش است، یک مربی کسب و کار و سخنران انگیزشی جستجوگر است. او توسط <em>مجله فروش برتر</em> به عنوان یکی از 50 رهبر برتر در فروش و بازاریابی و توسط <em>Forbes</em> یکی از 30 تأثیرگذار فروش اجتماعی برتر جهان شناخته شده است. p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (602, 'شارون سالزبرگ', '<p>شارون سالزبرگ یک معلم مشهور جهانی در زمینه مدیتیشن است. نویسنده کتاب پرفروش <em>نیویورک تایمز</em> <em>خوشبختی واقعی</em>، او پیشگام در آوردن ذهن آگاهی به فرهنگ جریان اصلی بوده است. از طریق بسیاری از عناوین دیگر او، ستون‌های منظم او برای <em>On Being</em> و <em>Huffington Post</em> و پادکست خودش - <em>ساعت متا</em> - سالزبرگ آموزه‌های بودایی را در دسترس قرار می‌دهد. برای مخاطبان غربی معاصر.</p>', '2023-01-26 19:52:00.360429', '2023-01-26 19:52:00.360429', NULL, 'Sharon Salzberg');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (603, 'جان آلن پائولوس', '<p>جان آلن پائولوس استاد ریاضیات در دانشگاه تمپل در فیلادلفیا است. او نویسنده بسیاری از کتاب های دیگر از جمله <em>یک ریاضیدان روزنامه می خواند</em> است و برای نشریاتی مانند <em>نیویورک تایمز</em> و ABCNEWS.com</p> نوشته است.', '2023-01-26 19:52:05.009629', '2023-01-26 19:52:05.009629', NULL, 'John Allen Paulos');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (604, 'دیوید هافلد', '<p> دیوید هافلد، مدیر عامل و کارشناس ارشد فروش در گروه هافلد، یک شرکت پیشرو در فروش و مشاوره است. رویکرد هوشمندانه او در زمینه فروش باعث شد که او در مدرسه کسب و کار هاروارد سخنرانی کند و در <em>وال استریت ژورنال</em>، <em>شرکت سریع</em> و <em>ایالات متحده آمریکا سخنرانی کند. اخبار و گزارش جهانی.</em></p>', '2023-01-26 19:52:10.248837', '2023-01-26 19:52:10.248837', NULL, 'David Hoffeld');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (605, 'اسپنسر جانسون', '<p>دکتر اسپنسر جانسون یک پزشک و روانشناس آمریکایی است. اثر مهم او، <em>چه کسی پنیر مرا جابه‌جا کرد</em>، تقریباً پنج سال در فهرست پرفروش‌ترین‌های کسب‌وکار <em>نیویورک تایمز</em> قرار داشت.</p>', '2023-01-26 19:52:15.504472', '2023-01-26 19:52:15.504472', NULL, 'Spencer Johnson');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (606, 'ران فریدمن', '<p>ران فریدمن یک روانشناس و مشاور برنده جایزه است که انگیزه را مطالعه می کند. <em>بهترین مکان برای کار</em> اولین کتاب پرفروش او است و در رسانه های جهانی از NPR تا <em>Guardian</em> نمایش داده شده است.</p>', '2023-01-26 19:52:20.966124', '2023-01-26 19:52:20.966124', NULL, 'Ron Friedman');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (607, 'الن روپل شل', '<p>الن روپل شل روزنامه نگار و استاد روزنامه نگاری علمی در دانشگاه بوستون است. او خبرنگار <em>ماهنامه آتلانتیک</em> است و دو کتاب موفق دیگر نوشته است: <em>ژن گرسنه: علم چربی و آینده لاغر</em> و <em>مکان کودک. : یک سال از زندگی یک مرکز مراقبت روزانه.</em></p>', '2023-01-26 19:52:25.839207', '2023-01-26 19:52:25.839207', NULL, 'Ellen Ruppel Shell');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (608, 'سو جانسون', '<p>دکتر سو جانسون روانشناس بالینی و زوج درمانگر و توسعه دهنده اصلی زوج های متمرکز بر عاطفه و خانواده درمانی است. او همچنین یک استاد پژوهشی در دانشگاه بین‌المللی آلیانت، در سن دیگو، و استاد بازنشسته در دانشگاه اتاوا است.</p>', '2023-01-26 19:52:30.901327', '2023-01-26 19:52:30.901327', NULL, 'Sue Johnson');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (609, 'سی اس لوئیس', '<p>C.S. لوئیس معلم ادبیات انگلیسی در دانشگاه آکسفورد بود که در اواسط قرن بیستم به یکی از محبوب‌ترین و تأثیرگذارترین روشنفکران بریتانیا تبدیل شد. او نویسنده ای پرکار بود که بیش از 30 کتاب در ژانرهای مختلف داستانی و غیرداستانی نوشت. او بیشتر به خاطر سریال کودکان مورد علاقه اش <em>تواریخ نارنیا</em>، داستان های تخیلی تمثیلی مسیحی، که بیش از 100 میلیون نسخه در سراسر جهان فروخته و چندین فیلم پرفروش ساخته شده است، شناخته شده است.</p>', '2023-01-26 19:52:36.540753', '2023-01-26 19:52:36.540753', NULL, 'C.S. Lewis');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (610, 'مایکل دی. گوردین', '<p>مایکل دی. گوردین استاد تاریخ مدرن و معاصر روزنگارتن و مدیر انجمن همکاران در هنرهای لیبرال در دانشگاه پرینستون است. کتاب‌های او عبارتند از <em>بابل علمی، جنگ‌های شبه‌علمی، </em>و <em>ابر سرخ در طلوع</em>.</p>', '2023-01-26 19:52:44.856293', '2023-01-26 19:52:44.856293', NULL, 'Michael D. Gordin');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (611, 'جانیس کاپلان و بارنابی مارش', '<p>جانیس کاپلان سردبیر مجله، تهیه کننده تلویزیون، نویسنده و روزنامه نگار است. او 13 کتاب نوشته است، از جمله پرفروش ترین کتاب <em>نیویورک تایمز</em>، <em>خاطرات سپاسگزاری</em>.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (612, 'آلن اچ پالمر', '<p>Alan H. Palmer فارغ التحصیل آکسفورد است که قبلاً در صنعت تبلیغات بین المللی کار می کرد. امروز، او سمینارهایی را برگزار می‌کند و برنامه‌های آموزشی را در سرتاسر جهان توسعه می‌دهد تا به مردم کمک کند مکالمات سازنده داشته باشند.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (613, 'نیل پاتل', '<p>نیل پاتل یک کارآفرین و بازاریاب دیجیتال است که با شرکت های بزرگی مانند NBC، HP و Viacom برای افزایش درآمد خود کار می کند. او یکی از بنیانگذاران پلتفرم های Hello Bar و Crazy Egg است که به مردم کمک می کند بازدیدکنندگان وب سایت هایشان را درک کنند.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (614, 'کیران ستیا', '<p>Kieran Setiya استاد فلسفه در موسسه فناوری ماساچوست است. او که متخصص در اخلاق، فلسفه ذهن و معرفت شناسی است، در مورد فلسفه عمومی نیز مطالب فراوانی نوشته است. او نویسنده <em>شناخت حق از نادرست، دانش عملی</em> و <em>دلایل بدون عقل گرایی</em></p> است.', '2023-01-26 19:53:11.067762', '2023-01-26 19:53:11.067762', NULL, 'Kieran Setiya');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (615, 'کریس ووس و تهل راز', '<p>کریس ووس یک مذاکره کننده ارشد سابق در مورد آدم ربایی با FBI است. تجربه چندین ساله او در مذاکره با انواع مجرمان او را به یک متخصص در این زمینه تبدیل کرده است. او بنیانگذار مشاوره مذاکره گروه قو سیاه و استادی است که دوره های مذاکره را در همه جا از دانشگاه هاروارد گرفته تا دانشکده مدیریت اسلون MIT تدریس کرده است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (616, 'بونو', '<p>پال هیوسون در دوبلین ایرلند به دنیا آمد و بونو به عنوان خواننده اصلی گروه راک U2 در جهان شناخته می شود. بونو علاوه بر آلبوم‌ها، تورها و همکاری‌های متعدد، بشردوستی است که به تأسیس ONE کمک کرد، سازمانی که به ریشه‌کن کردن فقر و بیماری‌های قابل پیشگیری اختصاص داشت. </p>', '2023-01-26 19:53:20.921838', '2023-01-26 19:53:20.921838', NULL, 'Bono');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (617, 'سیدارت موکرجی', '<p>سیذارتا موکرجی پزشک، ژنتیک، محقق، زیست شناس سلول های بنیادی و متخصص سرطان است. او همچنین نویسنده <em>امپراطور همه بیماری‌ها: بیوگرافی سرطان</em>، برنده جایزه کتاب اول گاردین و جایزه پولیتزر 2011 برای ادبیات غیرداستانی عمومی است.</p>', '2023-01-26 19:53:25.78699', '2023-01-26 19:53:25.78699', NULL, 'Siddhartha Mukherjee');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (618, 'گراهام آلکات', '<p> گراهام آلکات یکی از شناخته شده ترین کارشناسان بهره وری در بریتانیا است. آلکات علاوه بر تألیف کتاب‌هایی مانند <em>چگونه یک نینجا بهره‌وری باشیم </em>و <em>چگونه نینجا مطالعه‌ای باشیم</em>، بنیانگذار شرکت مشاوره بهره‌وری Think Productive و میزبان پادکست <em است. >فراتر از مشغله</em>. </p>', '2023-01-26 19:53:30.46785', '2023-01-26 19:53:30.46785', NULL, 'Graham Allcott');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (619, 'دیوید کریستال', '<p>دیوید کریستال یکی از دانشمندان برجسته زبان شناسی جهان است. او ده‌ها کتاب با موضوع زبان نوشته یا نوشته است، از جمله <em>داستان‌های انگلیسی</em> و <em>کلمات شکسپیر</em>. در سال 1995، به دلیل خدمات به زبان انگلیسی، نشان امپراتوری بریتانیا را دریافت کرد.</p>', '2023-01-26 19:53:39.906393', '2023-01-26 19:53:39.906393', NULL, 'David Crystal');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (620, 'کریگ رایت', '<p> کریگ رایت، استاد موسیقی در دانشگاه ییل است، جایی که دوره پرطرفدار Exploring the Nature of Genius را تدریس می کند. رایت که اصالتا اهل اوکلاهاما است، نویسنده <em>گوش دادن به موسیقی</em> و <em>پیچ وخم و جنگجو</em>، در میان آثار دیگر است.</p>', '2023-01-26 19:53:44.944302', '2023-01-26 19:53:44.944302', NULL, 'Craig Wright');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (621, 'کریس برنیسک و جک تاتار', '<p>جک تاتار نویسنده <em>معامله با بیت کوین چیست</em>، یکی از اولین کتاب‌ها در این زمینه است. او یک سرمایه‌گذار فرشته در استارت‌آپ‌های دارایی‌های دیجیتال است و بیش از دو دهه در صنعت خدمات مالی کار کرده است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (622, 'دیوید وایت', '<p>دیوید وایت شاعر انگلیسی است که به خاطر پر کردن شکاف بین شعر، هنر زندگی و تجارت مشهور است. انتشارات غیرداستانی دیگر او عبارتند از <em>عبور از دریای ناشناخته</em>و پرفروش ترین <em>قلب برانگیخته</em>.</p>', '2023-01-26 19:53:54.977027', '2023-01-26 19:53:54.977027', NULL, 'David Whyte');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (623, 'گری مک و دیوید کاستیونز', '<p>گری مک یک مشاور روانشناسی ورزشی است که با بسیاری از ورزشکاران حرفه ای کار کرده است. دیوید کاستیونز نویسنده <em>تلگرام ستاره فورت ورث</em> و نویسنده پرفروش است. <em>Mind Gym</em> اولین کتاب پرفروش آنها با هم است.</p>', '2023-01-26 19:53:59.827592', '2023-01-26 19:53:59.827592', NULL, 'Gary Mack & David Casstevens');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (624, 'کریستوفر هیچنز', '<p>کریستوفر هیچنز نویسنده، مناظره‌گر و روزنامه‌نگار انگلیسی بود. هیچنز که خود را سوسیالیست معرفی می کرد، اغلب مواضع بحث برانگیزی در مورد شخصیت های عمومی مشهور اتخاذ می کرد. در سال‌های پایانی زندگی، او قبل از اینکه در سال 2011 درگذشت، به دلیل نوشته‌های ضد مذهبی و حمایت قوی از جنگ عراق به شهرت رسید.</p>', '2023-01-26 19:54:06.797835', '2023-01-26 19:54:06.797835', NULL, 'Christopher Hitchens');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (626, 'جنیفر آنا گوستی-فرنسی', '<p>جنیفر آنا گوستی-فرنسی، استاد فلسفه در دانشگاه جان هاپکینز است. از دیگر آثار او می‌توان به <em>زندگی خیال</em>، <em>فضاهای عجیب و غریب در مدرنیسم آلمانی</em> و <em>The Ecstatic Quotidian</em> اشاره کرد. او همچنین نویسنده یک کتاب شعر به نام <em>After the Palace Burns</em> است که برنده جایزه نقد پاریس شد.</p>', '2023-01-26 19:54:17.352379', '2023-01-26 19:54:17.352379', NULL, 'Jennifer Anna Gosetti-Ferencei');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (627, 'کیت مک', '<p>دکتر کیتی مک یک اخترفیزیکدان نظری است که در حال بررسی طیفی از سؤالات در کیهان شناسی، مطالعه جهان از ابتدا تا انتها است. او در حال حاضر سمت صندلی هاوکینگ در کیهان شناسی و ارتباطات علوم در موسسه فیزیک نظری Perimeter را دارد، جایی که او تحقیقاتی را در مورد ماده تاریک و جهان اولیه انجام می دهد و برای دسترسی بیشتر فیزیک به عموم مردم تلاش می کند. او نویسنده کتاب <em>پایان همه چیز: (از نظر اخترفیزیکی</em>) است و برای تعدادی از نشریات مشهور مانند <em>Scientific American</em>، <em>Slate< /em>، <em>Sky & Telescope</em>، <em>Time</em>، و <em>Cosmos</em> magazine. او را می توان در توییتر با نام @AstroKatie پیدا کرد.</p>', '2023-01-26 19:54:22.530586', '2023-01-26 19:54:22.530586', NULL, 'Katie Mack');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (628, 'آناستازیا دی. وال', '<p>آناستازیا دی وال یک تحلیلگر سیاست اجتماعی است. او علاوه بر معاون و مدیر خانواده و آموزش در اندیشکده بریتانیایی سیویتاس، یک معلم مدرسه ابتدایی، پخش کننده و نویسنده واجد شرایط است. آناستازیا همچنین سرپرستی برنامه Visiting Women at Work را بر عهده دارد، یک موسسه خیریه که به دختران دبستانی درون شهر کمک می کند تا با زنان در طیف وسیعی از مشاغل ملاقات کنند.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (629, 'تام رایت و بردلی هوپ', '<p>تام رایت یک گزارشگر <em>وال استریت ژورنال</em> است که بیشتر به دلیل پوشش خبری مرگ اسامه بن لادن و فروپاشی کارخانه رانا پلازا در بنگلادش در سال 2013 شناخته شده است. رایت به طور مرتب از مالزی گزارش می دهد، توسط انجمن ناشران آسیا به عنوان روزنامه نگار سال 2016 انتخاب شد. </p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (630, 'الکس بنایان', '<p>در 18 سالگی، الکس بانایان از کالج استراحت کرد و پنج سال را در سفری گذراند که منجر به انتشار <em>درب سوم شد. بنایان برای <em>واشنگتن پست</em> و <em>TechCrunch</em> نوشته است و چارچوب درب سوم خود را در کنفرانس‌های تجاری در سراسر جهان ارائه کرده است.</p>', '2023-01-26 19:54:36.783426', '2023-01-26 19:54:36.783426', NULL, 'Alex Banayan');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (631, 'جرمی کوبیک و استیو کاکرام', '<p>جرمی کوبیک قبل از تبدیل شدن به یک نویسنده پرفروش، مدیر عامل کنفرانس های Leadercast بود، پلتفرمی که به رهبران کمک می کند تا به پتانسیل کامل خود دست یابند. کتاب های قبلی او عبارتند از <em>Making Your Leadership Come Live</em>(2011) و <em>5 Gears</em>(2015).</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (632, 'رنه دکارت', '<p> رنه دکارت فیلسوف فرانسوی و پدر سنت شکاکانه بود که از فلسفه قبلی مبتنی بر تفکر ارسطویی جدا شد. کار او در درجه اول بر هستی شناسی و معرفت شناسی متمرکز است و در زمان خود مورد تحسین و انتقاد قرار گرفت.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (633, 'شلی آزبورن', '<p><strong>درباره نویسنده</strong></p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (634, 'استفن ام آر کاوی', '<p> استیون ام آر کاوی یک متخصص مشهور جهانی در زمینه رهبری، اخلاق، الهام و همکاری است. او یکی از بنیانگذاران CoveyLink و فرانکلین-کاوی جهانی اعتماد است. او همچنین نویسنده کتاب پرفروش <em>سرعت اعتماد</em> (2006) است. و بله، این شباهت تصادفی نیست - او پسر استاد بهره وری مشهور جهان و نویسنده <em>7 عادت افراد بسیار مؤثر</em>، استفان آر. کاوی است.</p>', '2023-01-26 20:03:50.734611', '2023-01-26 20:03:50.734611', NULL, 'Stephen M.R. Covey');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (635, 'ماتیو ریکارد', '<p> ماتیو ریکار، متولد اکس‌ل‌بن، فرانسه، یک راهب بودایی است که در سنت تبتی تمرین می‌کند و مترجم فرانسوی دالایی لاما است. او در ابتدا زیست شناسی مولکولی خواند. امروز او یک نویسنده پرفروش و رهبر معنوی است که برای ادغام علم و معنویت تلاش می کند.</p>', '2023-01-26 20:04:03.043694', '2023-01-26 20:04:03.043694', NULL, 'Matthieu Ricard');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (636, 'دیوید گرابر', '<p>دیوید گریبر یک انسان شناس و فعال آنارشیست بود. یکی از سازمان‌دهندگان برجسته جنبش اجتماعی اشغال وال استریت، آثار و نوشته‌های گرابر در مورد انسان‌شناسی، آنارشیسم و ​​عدالت اجتماعی، تحسین‌های بسیاری را برای او به ارمغان آورد. </p>', '2023-01-26 20:04:10.183785', '2023-01-26 20:04:10.183785', NULL, 'David Graeber');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (637, 'کریس هوگان', '<p>کریس هوگان نویسنده و کارشناس مالی پرفروش، سخنران رویدادهای پویا و مربی مالی است. در بیش از یک دهه کار با Ramsey Solutions، او پیام امیدوارکننده خود را به مخاطبان در سراسر ایالات متحده رساند و به افراد بی‌شماری آموزش داد که چگونه کنترل امور مالی خود را در دست بگیرند و به اهداف خود برسند. پادکست او، <em>نمایش کریس هوگان</em>، قسمت‌های جدیدی را هر هفته منتشر می‌کند.</p>', '2023-01-26 20:04:17.016487', '2023-01-26 20:04:17.016487', NULL, 'Chris Hogan');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (638, 'ناتانیل پوپر', '<p>ناتانیل پوپر فارغ التحصیل دانشگاه هاروارد است که برای <em>لس آنجلس تایمز</em> و <em>Forward</em> نوشته است. او در حال حاضر به عنوان گزارشگر تجاری برای <em>نیویورک تایمز</em> کار می کند.</p>', '2023-01-26 20:04:24.26594', '2023-01-26 20:04:24.26594', NULL, 'Nathaniel Popper');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (639, 'تونی دیودو', '<p>تونی دیویدو نقش های رهبری ارشد را در طیفی از رهبران صنعت مانند مورگان استنلی، چارلز شواب و سرمایه گذاری گوگنهایم بر عهده داشته است. او رئیس T. Davidow Consulting است، شرکت مشاوره مستقل او بر محتوای مربوط به استراتژی های تخصیص دارایی، سرمایه گذاری های جایگزین، سرمایه گذاری پایدار و موضوعات دیگر تمرکز دارد. در سال 2020 جایزه تاثیر مدیریت ثروت توسط موسسه سرمایه گذاری و ثروت به او اعطا شد.</p>', '2023-01-26 20:04:31.255346', '2023-01-26 20:04:31.255346', NULL, 'Tony Davidow');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (640, 'ریچارد برانسون', '<p>ریچارد برانسون یکی از شناخته شده ترین کارآفرینان در جهان است که ریاست یکی از بزرگترین و شناخته شده ترین برندها را بر عهده دارد: گروه ویرجین. در طول سال‌ها، او یک رهبر تجاری معتبر در سفر، سرگرمی، سلامت و تناسب اندام، رسانه و ارتباطات باقی مانده است.</p>', '2023-01-26 20:04:38.949478', '2023-01-26 20:04:38.949478', NULL, 'Richard Branson');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (641, 'دیوید گیج', '<p>دیوید گیج یک روانشناس بالینی، استاد کمکی در دانشکده تجارت دانشگاه آمریکایی کوگود در واشنگتن دی سی و بنیانگذار BMS Associates، یک شرکت میانجیگری و مشاوره است.</p>', '2023-01-26 20:04:46.344962', '2023-01-26 20:04:46.344962', NULL, 'David Gage');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (642, 'الکسیس اوهانیان', '<p>الکسیس اوهانیان یک کارآفرین اینترنتی، بنیانگذار Reddit، سرمایه گذار و فعال اینترنت باز است که کتاب <em>بدون</em> <em>آنها</em> <em>اجازه</em>، یک <em> em>دیوار</em> <em>خیابان</em> <em>ژورنال</em> پرفروش‌ترین.</p>', '2023-01-26 20:04:53.490458', '2023-01-26 20:04:53.490458', NULL, 'Alexis Ohanian');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (643, 'مارک منسون', '<p>مارک منسون نویسنده و وبلاگ نویس مشهور است. در چند سال گذشته، وبلاگ او، www.markmanson.net، چندین میلیون نفر را دنبال کرده است. او در شهر نیویورک زندگی و کار می کند.</p>', '2023-01-26 20:05:00.8486', '2023-01-26 20:05:00.8486', NULL, 'Mark Manson');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (644, 'دانیل ام. کابل', '<p>دانیل ام. کیبل، استاد رفتار سازمانی در مدرسه تجارت لندن است. مشاور او، Essentic، با شرکت هایی مانند توییتر، کوکاکولا، و IKEA کار کرده است تا به کارکنان کمک کند تا نقاط قوت و استعدادهای منحصر به فرد خود را کشف کنند. او دو کتاب دیگر درباره روش‌شناسی خود نوشته است، <em>تغییر به عجیب</em> و <em>زنده در محل کار</em>.</p>', '2023-01-26 20:05:07.782837', '2023-01-26 20:05:07.782837', NULL, 'Daniel M. Cable');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (645, 'Epictetus', '<p>شارون لبل نویسنده پرفروش، موسیقیدان آموزش دیده کلاسیک و معلم بسیار محترم معنویت و فلسفه است. کارهای قبلی او عبارتند از <em>نام خودمان، نامگذاری فرزندانمان</em> و <em>موسیقی سکوت</em> که او به همراه برادرش آنها را نویسندگی کرد.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (646, 'آلن دو باتون', '<p>آلن دو باتن یک فیلسوف و نویسنده است. پرفروش‌ترین کتاب‌های او شامل موضوعاتی مانند بی‌خدایی، سکس، عشق، کار و معماری است. او بنیانگذار موسسه آموزشی جایگزین، مدرسه زندگی است.</p>', '2023-01-26 20:05:31.936272', '2023-01-26 20:05:31.936272', NULL, 'Alain de Botton');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (647, 'اریک جورجنسون', '<p>Eric Jorgenson یک استراتژیست محصول و نویسنده است. در سال 2011، او به تیم موسس Zaarly پیوست، شرکتی که به صاحبان خانه کمک می کند تا ارائه دهندگان خدمات قابل اعتماد را پیدا کنند. </p>', '2023-01-26 20:05:38.971913', '2023-01-26 20:05:38.971913', NULL, 'Eric Jorgenson');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (648, 'لیست ساترلند و کرستن جانن نلسون', '<p>لیزت ساترلند یک سخنران عمومی، نویسنده، کارآفرین و پادکست است. او که خودش یک کارگر از راه دور است، همچنین مدیر Collaboration Superpowers است، که کارگاه‌های آنلاین و حضوری را برای کمک به افراد برای کار از هر کجا فراهم می‌کند. این اولین کتاب او است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (674, 'متیو دیکسون و برنت آدامسون', '<p> متیو دیکسون مدیر اجرایی CEB، شرکت مشاوره مبتنی بر اعضا در جهان است. برنت آدامسون مدیر عامل و داستان سرای اصلی شرکت است.</p>', '2023-01-26 20:09:07.388338', '2023-01-26 20:09:07.388338', NULL, 'Matthew Dixon and Brent Adamson');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (649, 'کن فیشر و لارا هافمنز', '<p>کن فیشر موسس، مدیر عامل و رئیس شرکت جهانی مدیریت پول <em>Fisher Investments</em> و همچنین نویسنده تعدادی از پرفروش‌ترین کتاب‌های نیویورک تایمز، از جمله <em>The Only Three Questions شمارش </em>و <em>ده راه به سوی ثروت</em>. علاوه بر این، او ستون معروف <em>Forbes</em>Portfolio Strategy را در 25 سال گذشته نوشته است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (650, 'کاترین پرایس', '<p>کاترین پرایس یک نویسنده و روزنامه نگار علمی است که در فیلادلفیا زندگی می کند. نوشته های او در <em>نیویورک تایمز</em>، <em>واشنگتن پست</em> و <em>سان فرانسیسکو کرونیکل</em> ظاهر شده است. از دیگر کتاب‌های او می‌توان به <em>Vitamania </em>(2015) و <em>101 مکانی که قبل از مرگ نباید دید</em>(2010) اشاره کرد.</p>', '2023-01-26 20:06:00.908309', '2023-01-26 20:06:00.908309', NULL, 'Catherine Price');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (651, 'اسکات کوپر', '<p> اسکات کوپور شریک مدیریتی در Andreessen Horowitz، یکی از بزرگ‌ترین نام‌ها در سرمایه‌گذاری خطرپذیر است که بیش از ۷ میلیارد دلار دارایی دارد. در طول سال‌ها، آن‌ها در شرکت‌هایی سرمایه‌گذاری کرده‌اند که نام‌های معروفی پیدا کرده‌اند، مانند فیس‌بوک، توییتر، Airbnb و Groupon. کوپور همچنین در دانشگاه استنفورد دوره‌هایی را درباره سرمایه‌های مخاطره‌آمیز تدریس می‌کند و کالج مدیر سرمایه‌گذاری مخاطره‌آمیز این دانشگاه را تأسیس کرد.</p>', '2023-01-26 20:06:08.641944', '2023-01-26 20:06:08.641944', NULL, 'Scott Kupor');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (652, 'پاتریک لنسیونی', '<p>پاتریک لنسیونی موسس و رئیس گروه Table، یک شرکت مشاوره است. او همچنین یک سخنران عمومی بسیار تحسین شده است که ۱۱ کتاب پرفروش تجاری نوشته است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (653, 'جورج جی تامپسون و جری بی جنکینز', '<p>جرج جی. تامپسون روش Verbal Judo و موسسه همنام آن را ایجاد کرد. او قبل از اینکه افسر پلیس شود، انگلیسی تدریس می کرد و در کاراته تسلط داشت، حرکتی که به او کمک کرد روش ارتباطی خود را توسعه دهد. او در سال 2011 درگذشت.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (654, 'جان هال', '<p>جان هال یکی از بنیانگذاران شرکت Influence & Co است که به مشتریان کمک می کند محتوای قدرتمند و جذاب ایجاد کنند و کار او توسط <em>Forbes</em>و <em>Inc</em> مورد تحسین قرار گرفته است. در سال 2016، او و هم بنیانگذارانش جایزه کارآفرین سال EY را دریافت کردند. </p>', '2023-01-26 20:06:36.389398', '2023-01-26 20:06:36.389398', NULL, 'John Hall');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (655, 'جاش وایتزکین', '<p> جاش وایتزکین هشت بار قهرمان شطرنج ملی و برنده عناوین متعدد قهرمانی جهان و ملی در هنرهای رزمی است. او سمینارها و ارائه‌هایی در مورد روان‌شناسی عملکرد ارائه می‌کند و رئیس بنیاد غیرانتفاعی JW است که به حداکثر رساندن پتانسیل دانش‌آموزان از طریق فرآیندهای آموزشی غنی اختصاص دارد.</p>', '2023-01-26 20:06:43.206703', '2023-01-26 20:06:43.206703', NULL, 'Josh Waitzkin');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (656, 'محمد یونس', '<p>محمد یونس قبل از اینکه استاد اقتصاد در دانشگاه چیتاگونگ شود در بنگلادش به دنیا آمد و تحصیل کرد. او بنیانگذار و مدیر بانک گرامین در بنگلادش است.</p>', '2023-01-26 20:06:50.677044', '2023-01-26 20:06:50.677044', NULL, 'Muhammad Yunus');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (657, 'اوشو', '<p>اوشو، که با نام اوشو راجنیش نیز شناخته می‌شود، قبل از ترویج مدیتیشن پویا در دهه‌های 1970 و 80، مدرک کارشناسی ارشد فلسفه را در دانشگاه ساگار گرفت. او یک رهبر معنوی محبوب و با پیروان فداکار در سراسر جهان بود. او در سال 1990 درگذشت.</p>', '2023-01-26 20:07:02.793113', '2023-01-26 20:07:02.793113', NULL, 'Osho');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (658, 'مت مریت', '<p>مت مریت یک شاعر و پرنده نگر تحسین شده است که آثارش در بریتانیا، ایالات متحده و استرالیا منتشر شده است. مریت سردبیر<em>مجله تماشای پرندگان</em> و سردبیر شعر مجله ادبی <em>زیر رادار</em> است.</p>', '2023-01-26 20:07:10.032485', '2023-01-26 20:07:10.032485', NULL, 'Matt Merritt');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (659, 'دونالد سال و کاتلین آیزنهارت', '<p>دونالد سول استاد مدیریت و متخصص در زمینه استراتژی و اجرا در بازارهای آشفته است. او همچنین استاد سابق هاروارد و مدرسه تجارت لندن است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (660, 'استان رابینسون', '<p>کن رابینسون متفکر مشهور بریتانیایی در زمینه آموزش، خلاقیت و نوآوری است. او پروفسور ممتاز در دانشگاه وارویک، سخنران مکرر و نویسنده برنده جوایز، از جمله کتاب های دیگر، <em>مدارس خلاق</em> و <em>خارج از ذهن ما: یادگیری خلاق بودن</em است. </p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (661, 'ویلیام دبلیو لی', '<p>ویلیام دبلیو لی یک دانشمند، پزشک و نویسنده است. کار او با بنیاد Angiogenesis منجر به توسعه چندین روش درمانی و دستگاه های پزشکی پیشگامانه شده است. او از طریق کار خود بر سلامت بیش از 50 میلیون نفر در سراسر جهان تأثیر گذاشته است. دکتر لی همچنین در هر دو دانشگاه هاروارد و تافتز پست های هیئت علمی داشته است و سخنرانی TED او "آیا می توانیم برای گرسنگی دادن به سرطان غذا بخوریم؟" بیش از 11 میلیون بار مشاهده شده است.</p>', '2023-01-26 20:07:30.75016', '2023-01-26 20:07:30.75016', NULL, 'William W. Li');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (662, 'الیزابت گیلبرت', '<p>الیزابت گیلبرت نویسنده کتاب خاطرات و پرفروش‌ترین کتاب بین‌المللی <em>عشق دعا کن</em> است که به بیش از 30 زبان ترجمه شد و در فیلمی با بازی جولیا رابرتز اقتباس شد. مجله <em>Time</em> او را به عنوان یکی از 100 فرد تأثیرگذار در جهان معرفی کرد. آخرین رمان او، <em>امضای همه چیز</em>، همچنین پرفروش‌ترین کتاب <em>نیویورک تایمز</em> بود.</p>', '2023-01-26 20:07:43.041543', '2023-01-26 20:07:43.041543', NULL, 'Elizabeth Gilbert');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (663, 'هنری پولاک', '<p>هنری پولاک استاد ژئوفیزیک در دانشگاه میشیگان است. او به همراه همکارانش در هیئت بین المللی تغییرات آب و هوایی و معاون سابق رئیس جمهور ال گور، جایزه صلح نوبل را در سال 2007 دریافت کرد. پولاک به طور منظم به قطب جنوب سفر می کند و تحقیقات علمی در هر هفت قاره انجام داده است. او همچنین نویسنده <em>علم نامطمئن است. . . دنیای نامشخص</em>.</p>', '2023-01-26 20:07:50.31864', '2023-01-26 20:07:50.31864', NULL, 'Henry Pollack');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (664, 'رابین شارما', '<p>رابین شارما یکی از رهبران برجسته جهان و نویسنده پرفروش <em>راهبی که فراری خود را فروخت</em> است. او به میلیون ها نفر کمک کرده است تا رهبران بهتری شوند، بهره وری خود را بهبود بخشند و زندگی بهتری داشته باشند.</p>', '2023-01-26 20:07:57.007415', '2023-01-26 20:07:57.007415', NULL, 'Robin Sharma');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (665, 'کریس بیلی', '<p>کریس بیلی نویسنده و مشاور بهره وری از انتاریو، کانادا است. او برای<em>نیویورک تایمز</em>،<em>نشنال پست،</em> و <em>Harvard Business Review</em> نوشته است. او همچنین نویسنده <em>پروژه بهره وری</em> است.</p>', '2023-01-26 20:08:03.947476', '2023-01-26 20:08:03.947476', NULL, 'Chris Bailey');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (666, 'زیگ زیگلار', '<p>زیگ زیگلار نویسنده ای پرکار و سخنران انگیزشی بود که الهام بخش هزاران نفر بود تا پتانسیل کامل خود را باز کنند. از 28 کتابی که او نوشت، ده کتاب پرفروش شد. آثار او به نزدیک به 40 زبان ترجمه شده‌اند و سال‌ها پس از اولین انتشارشان همچنان محبوب هستند.</p>', '2023-01-26 20:08:10.827505', '2023-01-26 20:08:10.827505', NULL, 'Zig Ziglar');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (667, 'دیل ساید باتوم', '<p>Dale Sidebottom یک معلم سابق PE و اکنون مشاور تمام وقت «بازی» برای مدارس، شرکت‌ها و سازمان‌ها است. او شرکت های آموزشی و تناسب اندام بی شماری از جمله Jugar Life، Energetic Education و Bottoms Up Fitness ایجاد کرده است. </p>', '2023-01-26 20:08:17.951393', '2023-01-26 20:08:17.951393', NULL, 'Dale Sidebottom');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (668, 'کریس گیبو', '<p>کریس گیبو یک متخصص در زمینه خوداشتغالی خلاق و سفرهای بین المللی است که اخیراً به هدف خود برای بازدید از همه کشورهای جهان دست یافته است. او همچنین نویسنده پرفروش‌ترین <em>نیویورک تایمز</em> <em>استارت‌آپ 100 دلاری</em> و یکی از همکاران دائمی CNN.com، <em>Business Week</em>، em>هافینگتون پست</em> و سایر رسانه ها.</p>', '2023-01-26 20:08:25.136099', '2023-01-26 20:08:25.136099', NULL, 'Chris Guillebeau ');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (669, 'جان گاتمن', '<p> جان گاتمن، دکترا، استاد بازنشسته روانشناسی در دانشگاه واشنگتن است و دارنده جایزه دانشمندان پژوهشگران موسسه ملی سلامت روان است. از دیگر کتاب‌های او می‌توان به <em>هفت اصل برای موفقیت در ازدواج</em> و <em>تربیت کودک باهوش عاطفی</em></p> اشاره کرد.', '2023-01-26 20:08:32.50744', '2023-01-26 20:08:32.50744', NULL, 'John Gottman');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (670, 'لورا پاتنام', '<p>لورا پاتنام موسس و مدیرعامل Motion Infusion، یک شرکت مشاوره رفاهی است. پاتنام علاوه بر مشارکت شدید در انجمن قلب آمریکا، یک مربی، رقصنده و مشاور است و با سازمان های غیرانتفاعی، مؤسسات دانشگاهی و شرکت های Fortune 500 کار می کند.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (671, 'کالین بارو', '<p>کالین بارو بیش از 30 کتاب در زمینه کارآفرینی، مدیریت کسب و کار و توسعه دارایی بین المللی تالیف کرده است. قبل از اینکه نویسنده شود، از یک حرفه طولانی در مدیریت بازرگانی، داشتن کارکنان ارشد و سمت‌های خطی در سازمان‌های مختلف لذت می‌برد.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (672, 'آلانا مولر', '<p>آلانا مولر نویسنده و خالق وبلاگ Coffee Lunch Coffee (http://www.coffeelunchcoffee.com/) و رئیس Kauffman FastTrac، یک سازمان آموزشی غیرانتفاعی است که به کارآفرینان کمک می کند و آموزش می دهد. آلانا دارای مدرک کارشناسی ارشد در رشته مدیریت بازرگانی از دانشگاه شیکاگو است، اغلب کارگاه‌های تجاری را راه‌اندازی می‌کند و به Forbes.com و <em>هافینگتون پست</em> کمک کرده است.</p>', '2023-01-26 20:08:53.260713', '2023-01-26 20:08:53.260713', NULL, 'Alana Muller');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (673, 'موسسه زبان پرینستون و ابی مارکز بیل', '<p>ابی مارکز بیل بنیانگذار سازمان آموزش شرکتی The Corporate Educator، نویسنده <em>Success Skills: Strategies for Study and Lifelong Learning</em> و خالق Rev It Up Reading است، برنامه ای که به افراد کمک می کند خود را ارتقا دهند. مهارت های تندخوانی.</p>', '2023-01-26 20:09:00.052979', '2023-01-26 20:09:00.052979', NULL, 'The Princeton Language Institute and Abby Marks Beale');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (675, 'و هریس', '<p>دن هریس مجری اخبار چندین برنامه تلویزیونی آمریکایی، از جمله <em>Nightline</em>و <em>ABC News است. </em>او اخبار را از سراسر جهان گزارش کرده است، جنگ‌های افغانستان و عراق را پوشش می‌دهد و جوایز و افتخارات متعددی را برای روزنامه‌نگاری دریافت کرده است.</p>', '2023-01-26 20:09:14.499661', '2023-01-26 20:09:14.499661', NULL, 'Dan Harris');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (676, 'جان ام. گاتمن و نان سیلور', '<p>جان ام. گاتمن، استاد روانشناسی در دانشگاه واشنگتن و یکی از بنیانگذاران و یکی از مدیران مؤسسه زناشویی و خانواده سیاتل است. تحقیقات او در مورد زوج های عاشقانه 40 سال طول کشیده است و او چندین جایزه معتبر علمی را برای کار خود به دست آورده است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (677, 'اسکات دیویس', '<p>اسکات دیویس تحلیلگر سابق وال استریت با بیش از 25 سال تجربه است. او 16 سال به عنوان مدیر عامل و رئیس گروه تحقیقات صنعتی جهانی در مورگان استنلی گذراند. در حال حاضر، دیویس رئیس هیئت مدیره، مدیر عامل و تحلیلگر ارشد تحقیقاتی Melius Research است. این اولین کتاب دیویس است.</p>', '2023-01-26 20:09:29.207597', '2023-01-26 20:09:29.207597', NULL, 'Scott Davis');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (678, 'لو آدلر', '<p>لو آدلر یک کارشناس استخدام، نویسنده پرفروش، سخنران بین المللی و ستون نویس برای تعدادی از سایت های مهم استخدام از جمله لینکدین و اطلاعات کندی است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (679, 'بن هیوز و سباستین کلاین', '<p>سباستین کلاین یکی از بنیانگذاران و سردبیر Blinkist است. او قبلاً مشاور گروه مشاوره بوستون و یک کارآفرین سریالی بود. او در مهارت های چاقو مهارت دارد و یک بار بدون فرمان در کوالالامپور دوچرخه سواری کرد.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (680, 'جنیفر آکرمن', '<p>جنیفر آکرمن بیش از 20 سال است که در مورد علم می نویسد. کتاب‌های قبلی او عبارتند از <em>سکس بخواب، بنوش: یک روز در زندگی بدنت</em> و <em>آه چو: زندگی غیرمعمول سرماخوردگی تو. </em>او دریافت کننده جوایز و کمک هزینه های تحصیلی متعددی است، از جمله کمک هزینه تحصیلی ملی برای ادبیات غیرداستانی برای هنر.</p>', '2023-01-26 20:09:50.292935', '2023-01-26 20:09:50.292935', NULL, 'Jennifer Ackerman');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (681, 'آماندا پالمر', '<p>آماندا پالمر یک نوازنده، نویسنده و مجری است. پالمر که به عنوان یک مجری خیابانی شروع به کار کرد، بعداً به عنوان یکی از اعضای دو نفره The Dresden Dolls به موفقیت های موسیقی دست یافت. سخنرانی TED او در سال 2013، "هنر پرسیدن" بیش از هشت میلیون بار دیده شده است.</p>', '2023-01-26 20:09:57.72116', '2023-01-26 20:09:57.72116', NULL, 'Amanda Palmer');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (682, 'دیپاک چوپرا', '<p> دیپاک چوپرا یک پزشک آموزش دیده، مدافع سلامت جایگزین و پزشکی یکپارچه، نویسنده، معلم و چهره برجسته در جنبش عصر جدید است. او بیش از 80 کتاب منتشر کرده است، از جمله <em>درمان کوانتومی (1989) </em>و <em>سلامت کامل </em>(1990). چوپرا از طریق کارگاه‌ها و سخنرانی‌هایش در مرکز چوپرا، استراحتگاه سلامتی او در کارلزباد، کالیفرنیا، میلیون‌ها نفر را با به اشتراک گذاشتن روش‌های پیشگام خود در تحول شخصی توانمند کرده است.</p>', '2023-01-26 20:10:04.535976', '2023-01-26 20:10:04.535976', NULL, 'Deepak Chopra');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (683, 'اندرو هالام', '<p>اندرو هالام یک سخنران و نویسنده سرمایه گذاری است که اولین میلیون خود را در حین کار به عنوان معلم به دست آورد. هالام که اصالتاً اهل کانادا است، اکنون به عنوان یک «عشایر دیجیتالی» به سراسر جهان سفر می کند. او همچنین نویسنده <em>میلیونر مهاجر </em>(2017)<em> است.</em></p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (684, 'ادوارد گلیزر', '<p>ادوارد گلیزر استاد دانشگاه هاروارد است و متخصص در اقتصاد شهرها، مسکن، جداسازی و نوآوری است.</p>', '2023-01-26 20:10:18.705999', '2023-01-26 20:10:18.705999', NULL, 'Edward Glaeser');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (685, 'جف ساترلند', '<p>جف ساترلند یکی از بنیانگذاران و مدیر عامل شرکت اسکرام است. ساترلند، خلبان سابق جنگنده که در وست پوینت تحصیل کرده، در حال حاضر نقش مشاوره ای در 11 شرکت فناوری مختلف دارد.</p>', '2023-01-26 20:10:25.908417', '2023-01-26 20:10:25.908417', NULL, 'Jeff Sutherland');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (686, 'ثور هانسون', '<p>دکتر ثور هانسون نویسنده و زیست شناس برنده جایزه است. او نویسنده <em>پیروزی دانه ها</em> و <em>جنگل نفوذ ناپذیر</em> است. به او مدال جان باروز، جایزه AAAS/Subaru SB&F و دو جایزه کتاب اقیانوس آرام شمال غربی اهدا شد.</p>', '2023-01-26 20:10:32.870497', '2023-01-26 20:10:32.870497', NULL, 'Thor Hanson');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (711, 'مت کپنس', '<p> مت کپنس نویسنده ای متولد بوستون است که بیش از یک دهه است که تقریباً بی وقفه به سراسر جهان سفر می کند. از زمان اولین سفر طولانی خود به تایلند در سال 2005، او آنچه را که در وبلاگ محبوب خود، <em>NomadicMatt.com</em></p> می یابد، به اشتراک می گذارد.', '2023-01-26 20:13:50.126255', '2023-01-26 20:13:50.126255', NULL, 'Matt Kepnes');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (687, 'جردن سیات و مایکل واکانتی', '<p>جردن سیات بنیانگذار تجارت آنلاین مربی تناسب اندام Syatt Fitness است. او در حرفه خود به عنوان یک مربی شخصی، به مشتریان بی‌شماری کمک کرده است وزن خود را کاهش دهند، قدرت کسب کنند و از غذاهای مورد علاقه خود به روشی سالم و بدون احساس گناه لذت ببرند.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (688, 'مایکل مازلی و میمی اسپنسر', '<p>مایکل مازلی دارای مدرک پزشکی از دانشکده پزشکی رویال بیمارستان رایگان است. موزلی همچنین یک روزنامه نگار و تهیه کننده تلویزیونی در سال 1995 توسط انجمن پزشکی بریتانیا به عنوان خبرنگار پزشکی سال انتخاب شد.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (689, 'ملیسا اوربان', '<p>Melissa Urban یکی از بنیانگذاران Whole30 است، یک تنظیم مجدد رژیم غذایی 30 روزه که زندگی میلیون ها نفر را در سراسر جهان تغییر داده است. او همچنین نویسنده پرفروش <em>نیویورک تایمز</em>، میزبان پادکست و متخصص مرزها است.</p>', '2023-01-26 20:10:53.659082', '2023-01-26 20:10:53.659082', NULL, 'Melissa Urban');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (690, 'آریانا هافینگتون', '<p>آریانا هافینگتون یکی از بنیانگذاران و سردبیر <em>هافینگتون پست،</em> و از پیشگامان اجرای سیاست های خواب بهتر در دفاتر است. او نویسنده چندین کتاب پرفروش است، از جمله <em>جهان سوم آمریکا</em> و <em>در مورد بی باک شدن</em>.</p>', '2023-01-26 20:11:00.705887', '2023-01-26 20:11:00.705887', NULL, 'Arianna Huffington');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (691, 'شمن دورک', '<p>شمن دورک یک شمن نسل ششم و نویسنده پرفروش است. آثار دورک در نشریاتی از جمله مجلات <em>Elle </em>و <em>Marie Claire</em>به نمایش درآمده است و آموزه‌های او بر چهره‌های عمومی برجسته مانند گوئینت پالترو و نینا دوبرو تأثیر گذاشته است.</p>', '2023-01-26 20:11:08.499986', '2023-01-26 20:11:08.499986', NULL, 'Shaman Durek');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (692, 'آلبوم میچ', '<p>میچ آلبوم نویسنده آثار تخیلی و غیرداستانی متعددی از جمله هفت کتاب پرفروش <em>نیویورک تایمز</em>و <em>سه‌شنبه‌ها با موری</em>، پرفروش‌ترین خاطرات تمام دوران است. کتاب‌های او مجموعاً بیش از 40 میلیون نسخه در سراسر جهان فروخته و به 47 زبان ترجمه شده‌اند. آلبوم علاوه بر کتاب‌های منتشر شده‌اش، سیزده بار توسط ویراستاران ورزشی آسوشیتدپرس به عنوان بهترین ستون‌نویس ورزشی آمریکا انتخاب شده است. </p>', '2023-01-26 20:11:15.964108', '2023-01-26 20:11:15.964108', NULL, 'Mitch Albom');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (693, 'کوین آیکنبری و وین تورمل', '<p>کوین ایکنبری گروه Kevin Eikenberry را در سال 1993 تاسیس کرد و یکی از بنیانگذاران موسسه رهبری از راه دور است. او خالق سیستم یادگیری رهبری قابل توجه است، یک محصول یادگیری رهبری مبتنی بر عضویت. او نویسنده یا نویسنده سه کتاب پرفروش آمازون است: <em>رهبری قابل توجه</em>، <em>از جوانه تا رئیس</em>، و <em>رهبر در راه دور.</em></p. >
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (694, 'دکتر. دیوید بی و', '<p>دکتر دیوید بی آگوس یک پزشک و مهندس پزشکی است که به عنوان یکی از متخصصان برجسته سرطان آمریکا شناخته می شود. او تعدادی شرکت پزشکی را با تمرکز بر ارائه داروهای شخصی تاسیس کرده است. او همچنین نویسنده کتاب های دیگری مانند <em>پایان بیماری</em> و <em>راهنمای کوتاهی برای زندگی طولانی</em> است.</p>', '2023-01-26 20:11:35.298648', '2023-01-26 20:11:35.298648', NULL, 'Dr. David B. Agus');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (695, 'تی کالین کمپبل و توماس ام.کمپبل', '<p>T. کالین کمپبل استاد بازنشسته در دانشگاه کورنل است و بیشتر به عنوان نویسنده <em>مطالعه چین</em> شناخته می شود. کمپبل که در یک مزرعه لبنی به دنیا آمد، به تحصیل در رشته دامپزشکی ادامه داد. او دارای دکترای علوم تغذیه و بیوشیمی است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (696, 'سیندی مک گاورن', '<p>دکتر سیندی مک گاورن سخنران، مشاور فروش و بنیانگذار شرکت مشاوره برگ نارنجی است. مک گاورن آموزش فروش را برای صدها سازمان و فرد ارائه کرده است و به شرکت‌ها کمک می‌کند تا سود نهایی خود را افزایش دهند و کسب‌وکار جدیدی را از درب خود وارد کنند.</p>', '2023-01-26 20:11:49.524845', '2023-01-26 20:11:49.524845', NULL, 'Cindy McGovern');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (712, 'فره استور', '<p>فره استور روزنامه نگار و سردبیر است. در سال 2018، به عنوان سردبیر <em>Cosmopolitan</em>، یک جایزه PPA و یک جایزه BSME دریافت کرد. در سال 2017، او در فهرست 1000 تأثیرگذارترین افراد بریتانیا قرار گرفت. <em>منطقه ناراحتی</em>اولین کتاب اوست. </p>', '2023-01-26 20:13:57.201301', '2023-01-26 20:13:57.201301', NULL, 'Farrah Storr');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (697, 'استفان لابرژ و هوارد راینگولد', '<p>استفان لابرژ دارای مدرک دکتری است. در روان‌فیزیولوژی از دانشگاه استنفورد، جایی که او در مورد رویای شفاف تحقیق می‌کند. او نویسنده کتاب پرفروش <em>رویای شفاف</em> و بنیانگذار موسسه لوسیدیتی است که برای دانش بیشتر در مورد آگاهی کار می کند.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (698, 'جاش دیویس', '<p>جاش دیویس، استاد ارشد و مدیر تحقیقات موسسه NeuroLeadership است. او دکترای روانشناسی خود را از دانشگاه کلمبیا دریافت کرد و با حوزه های تحقیقاتی مانند شناخت تجسم یافته و تنظیم احساسات درگیر شد.</p>', '2023-01-26 20:12:08.354579', '2023-01-26 20:12:08.354579', NULL, 'Josh Davis');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (699, 'ببینید non r Oh. به هنگام', '<p>Mihir A. Desai یک اقتصاددان و نویسنده است. او در حال حاضر استاد امور مالی گروه مالی میزوهو در دانشکده بازرگانی هاروارد و استاد دانشکده حقوق هاروارد است. او در کمبریج، ماساچوست زندگی می کند. </p>', '2023-01-26 20:12:15.320065', '2023-01-26 20:12:15.320065', NULL, 'Mihir A. Desai');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (700, 'هری بکویث', '<p>هری بکویث قبل از تبدیل شدن به یک سخنران تاثیرگذار در موضوعات فروش و بازاریابی، حرفه بازاریابی موفقی داشت. او برای کارمندان شرکت‌های بزرگ ملی و همچنین دانشجویان دانشگاه‌های آیوی لیگ سخنرانی می‌کند و یکی از بهترین سخنرانان عمومی در حوزه کاری خود محسوب می‌شود. او پنج عنوان پرفروش نوشته است، از جمله <em>فروش نامرئی</em>و <em>بی فکر</em>.</p>', '2023-01-26 20:12:22.557739', '2023-01-26 20:12:22.557739', NULL, 'Harry Beckwith');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (701, 'وینی کوتو', '<p>Vinay Couto، John Plansky و Deniz Caglar همگی از اصول شرکت خدمات حرفه ای معتبر PricewaterhouseCoopers هستند. آنها ترکیبی از 70 سال تجربه مشاوره استراتژی با مشاغل در طیف گسترده ای از صنایع دارند.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (702, 'ششی ثارور', '<p>شاشی ثارور یک نماینده پارلمان هند، نویسنده و دیپلمات سابق است. او که عضو حزب کنگره ملی هند است، از سال 2009 نماینده ناحیه تیرووانانتاپورام در کرالا بوده است. کتاب های قبلی او شامل رمان <em>شورش </em>(2001) و <em>عصر تاریکی</em> می باشد. (2017)، مطالعه ای درباره حکومت نادرست بریتانیا در هند در طول دوره استعمار.</p>', '2023-01-26 20:12:36.584621', '2023-01-26 20:12:36.584621', NULL, 'Shashi Tharoor');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (703, 'ارسطو', '<p>ارسطو یک فیلسوف یونان باستان بود که به طور گسترده در مورد طیف گسترده ای از موضوعات، از جمله فیزیک، زیست شناسی، منطق، اخلاق، زبان شناسی، و سیاست نوشت. او به طور گسترده ای به عنوان یکی از اولین دانشمندان اصیل در تاریخ شناخته شده است، و نوشته های او به توسعه زمینه های کاملاً جدید مطالعه کمک کرد. ارسطو پس از آموزش زیر نظر فیلسوف یونانی افلاطون در آکادمی خود در آتن، معلم اسکندر مقدونی شد و سپس مدرسه خود را در آتن به نام لیسیوم تأسیس کرد.</p>', '2023-01-26 20:12:43.435495', '2023-01-26 20:12:43.435495', NULL, 'Aristotle');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (704, 'لوری آ. بروتو', '<p>دکتر لوری بروتو روانشناس کانادایی و متخصص شناخته شده در زمینه اختلالات جنسی زنان است. او پیشگام استفاده از ذهن آگاهی به عنوان تکنیکی برای درمان اختلالات جنسی و بهبود زندگی جنسی زنان بود.</p>', '2023-01-26 20:12:50.742954', '2023-01-26 20:12:50.742954', NULL, 'Lori A. Brotto');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (705, 'جین ماتیوس', '<p>جین متیوز نویسنده و متخصص بازاریابی است. او با سگش، روری، در سیدنی زندگی می‌کند و قبلاً <em>مانیفست میانسالی: راهنمای یک زن برای شکوفا شدن پس از چهل سالگی</em> نوشته بود.</p>', '2023-01-26 20:12:57.46707', '2023-01-26 20:12:57.46707', NULL, 'Jane Mathews');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (706, 'فیلیپ A. فیشر', '<p>Philip A. Fisher یکی از پدران اصلی نظریه سرمایه گذاری و بنیانگذار شرکت مشهور مدیریت پول، Fisher & Company است. کتاب او با نام <em> سهام عادی و سود غیرمعمول</em> که در ابتدا در سال 1956 منتشر شد، از آن زمان تاکنون در دست چاپ باقی مانده است.</p>', '2023-01-26 20:13:04.529413', '2023-01-26 20:13:04.529413', NULL, 'Philip A. Fischer');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (707, 'پاملا اسلیم', '<p>پاملا اسلیم نویسنده، سخنران و مربی تجاری است. در سال 2005، او وبلاگی به نام «فرار از ملت اتاقک» تأسیس کرد که بعداً مبنایی برای کتاب او به همین نام شد.</p>', '2023-01-26 20:13:17.017539', '2023-01-26 20:13:17.017539', NULL, 'Pamela Slim');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (708, 'دانا ساسکیند', '<p>دانا ساسکیند جراح متخصص کم شنوایی و کاشت حلزون است. او بنیانگذار ابتکار سی میلیون کلمه است، برنامه ای که بر اهمیت حیاتی قرار گرفتن در معرض زبان اولیه در یک کودک در حال رشد تمرکز دارد.</p>', '2023-01-26 20:13:23.769621', '2023-01-26 20:13:23.769621', NULL, 'Dana Suskind');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (709, 'جان لی دوما', '<p>جان لی دوماس بنیانگذار و میزبان پادکست برنده جایزه <em>Entrepreneurs on Fire</em> است که تا به امروز بیش از 3000 قسمت و بیش از 100 میلیون بار شنیده شده است. دوما پس از سال ها خدمت فعال در ارتش ایالات متحده، در امور مالی شرکت ها و املاک و مستغلات مشغول به کار شد. او همچنین یک سال را در دانشکده حقوق گذراند تا اینکه تصمیم گرفت از 9 تا 5 فرار کند و کارآفرین شود. او نویسنده <em>راه اندازی پادکست: راهنمای کامل برای راه اندازی پادکست</em> است.</p>', '2023-01-26 20:13:30.668425', '2023-01-26 20:13:30.668425', NULL, 'John Lee Dumas');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (710, 'Ximena Vengoechea', '<p>Ximena Vengoechea یک کاربر محقق ساکن سانفرانسیسکو است که در شرکت‌های مختلف متمرکز بر فناوری از جمله Pinterest، LinkedIn، و Twitter کار کرده است. او همچنین یک نویسنده و تصویرگر است که آثارش در <em>واشنگتن پست</em>، <em>نیوزویک، </em><em>هافینگتون پست، </em>و <em>Inc. Listen Like You Mean It </em>اولین کتاب او است.</p>', '2023-01-26 20:13:43.169126', '2023-01-26 20:13:43.169126', NULL, 'Ximena Vengoechea');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (713, 'دانیل ای لیبرمن', '<p>دانیل لیبرمن استاد زیست شناسی تکاملی انسان در دانشگاه هاروارد است. یک متخصص شناخته شده جهانی در زمینه تکامل و سلامت انسان، و نویسنده بیش از 150 مقاله با داوری، عناوین دیگر او عبارتند از <em>داستان بدن انسان</em> و <em>تکامل سر انسان</em> em>.</p>', '2023-01-26 20:13:59.328911', '2023-01-26 20:13:59.328911', NULL, 'Daniel E. Lieberman');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (714, 'رام چاران', '<p>رام چاران مشاور شرکتی مشهور دارای مدرک دکترا و MBA از دانشکده بازرگانی هاروارد است. او نویسنده بسیاری از کتاب های پرفروش است، از جمله <em>اجرا: نظم و انضباط انجام کارها</em>.</p>', '2023-01-26 20:14:06.147281', '2023-01-26 20:14:06.147281', NULL, 'Ram Charan');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (715, 'او هر دو را انجام داد', '<p>آدا کالهون نویسنده پرفروش <em>نیویورک تایمز</em> <em>نان تست های عروسی که هرگز نخواهم داد</em>و <em>سنت مارکز مرده است</em> است. گزارش‌های خبری ملی کالهون جوایز متعددی را دریافت کرده است، و او به طور منظم در نشریات معتبری مانند<em>نیویورکر</em>و<em>آتلانتیک</em> مشارکت دارد. او همچنین روزنامه نگاری و نویسندگی خلاق را تدریس می کند.</p>', '2023-01-26 20:14:18.733093', '2023-01-26 20:14:18.733093', NULL, 'Ada Calhoun');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (716, 'لی گالاگر', '<p>لی گالاگر دستیار ویرایشگر در <em>Fortune</em> است. او مجری <em>Fortune Live </em>و مهمان دائمی <em> Marketplace</em>، <em>CBS This Morning</em>، <em>CNBC</em> و برنامه های دیگر است. .</p>', '2023-01-26 20:14:30.906686', '2023-01-26 20:14:30.906686', NULL, 'Leigh Gallagher');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (717, 'پیتر بوقوسیان و جیمز لیندسی', '<p>پیتر بوقوسیان، استادیار فلسفه در دانشگاه ایالتی پورتلند، اورگان است. او سخنران مرکز تحقیقات است و در سطح بین المللی با بنیاد عقل و علم ریچارد داوکینز سخنرانی می کند. او همچنین نویسنده <em>راهنمای ایجاد آتئیست ها</em> است. </p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (718, 'عاطف میان و امیر صوفی', '<p>عطیف میان، استاد اقتصاد در دانشگاه پرینستون و مدیر مرکز سیاست عمومی و امور مالی جولیس-رابینوویتز است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (719, 'فیلیپ کوگان', '<p>فیلیپ کوگان یک ستون نویس در <em>The Economist</em> است و تعدادی کتاب از جمله <em>The Money Machine</em>و <em>The Economist Guide to Hedge Funds</em> نوشته است. > او همچنین به مدت 20 سال در <em>فایننشال تایمز</em> کار کرده است، که اخیراً به عنوان سردبیر سرمایه گذاری.</p>', '2023-01-26 20:14:52.500397', '2023-01-26 20:14:52.500397', NULL, 'Philip Coggan');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (720, 'آلوین راث', '<p>در سال 2012، آلوین ای راث جایزه نوبل اقتصاد را دریافت کرد. راث یکی از متخصصان برجسته جهان در نظریه بازی و طراحی بازار است و استاد اقتصاد در دانشگاه استنفورد و دانشگاه هاروارد است.</p>', '2023-01-26 20:14:59.344139', '2023-01-26 20:14:59.344139', NULL, 'Alvin Roth');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (721, 'لیزا کونگدون و مگ متئو ایلاسکو', '<p>لیزا کونگدون یک تصویرگر است و برای <em>موزه مدرن آر</em>t،<em> کمپین اوباما</em> و<em>سایمون و شوستر</em> کار کرده است. آثار او همچنین در <em>گالری بدفورد</em> و <em>موزه یهودیان معاصر</em> نمایش داده شده است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (722, 'پاتریک بازگشت و کریستف مورین', '<p>پاتریک رنواز بنیانگذار و رئیس SalesBrain است. او در طول دوران حرفه‌ای خود قراردادهایی به ارزش بیش از ۲ میلیارد دلار بسته است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (723, 'جاناتان ایگ', '<p>جاناتان ایگ نویسنده و روزنامه نگار اهل نیویورک است که چندین کتاب تحسین شده و پرفروش نوشته است. موضوعات جذاب بیوگرافی او شامل بازیکنان افسانه ای بیسبال لو گریگ و جکی رابینسون و گانگستر بدنام شیکاگو آل کاپون است.</p>', '2023-01-26 20:15:20.844455', '2023-01-26 20:15:20.844455', NULL, 'Jonathan Eig');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (724, 'ترن گریفین', '<p>ترن گریفین یکی از مدیران ارشد مایکروسافت و نویسنده <em>مذاکره‌کننده جهانی</em> است که راهنمای تحسین‌شده‌ای برای مذاکره در سطح بین‌المللی است. گریفین همچنین یک شریک سابق در Eagle River، یک شرکت سهام خصوصی متخصص در نرم‌افزار، مخابرات و سایر سرمایه‌گذاری‌های فناوری است.</p>', '2023-01-26 20:15:27.666505', '2023-01-26 20:15:27.666505', NULL, 'Tren Griffin');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (725, 'سان تزو', '<p>سان تزو یک استراتژیست نظامی، مشاور، فیلسوف و نویسنده چینی بود که تصور می‌شود ۲۵۰۰ سال پیش زندگی و کار کرده است.</p>', '2023-01-26 20:15:34.968107', '2023-01-26 20:15:34.968107', NULL, 'Sun Tzu');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (726, 'هاینز شیلینگ', '<p>هاینز شیلینگ، استاد بازنشسته تاریخ در دانشگاه هومبولت در برلین است. آثار شیلینگ بر تاریخ دین متمرکز است و او آثار آکادمیک متعدد و تاریخ های عامه پسندی را منتشر کرده است. کتاب او <em>مارتین لوتر: شورشی در عصر آشوب</em> استاندارد طلایی زندگی نامه های لوتر در نظر گرفته می شود.</p>', '2023-01-26 20:15:41.834193', '2023-01-26 20:15:41.834193', NULL, 'Heinz Schilling');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (768, 'جیسون فرید و دیوید هاین مایر هانسون', '<p>جیسون فرید یکی از بنیانگذاران 37signals، یک شرکت توسعه وب است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (727, 'گری کلر و جی پاپاسان', '<p>گری کلر یکی از بنیانگذاران و رئیس هیئت مدیره Keller Williams Realty International است، شرکتی که او از یک دفتر کوچک در آستین، تگزاس رشد کرد تا به بزرگترین شرکت املاک و مستغلات در ایالات متحده تبدیل شود. سه کتاب قبلی او مجموعه املاک میلیونر را تشکیل دادند و همگی پرفروش بودند.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (728, 'دین بروکس', '<p>Dane Brookes یک کارشناس بازاریابی محتوا و ارتباطات است که در زمینه روزنامه نگاری تجاری و استراتژی محتوا سابقه دارد. بروکس رئیس بخش تحریریه یک انتشارات بزرگ بود و بازاریابی دیجیتال را برای چندین شرکت دیگر مدیریت کرده است.</p>', '2023-01-26 20:15:56.421551', '2023-01-26 20:15:56.421551', NULL, 'Dane Brookes');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (729, 'کیم کریستفورت و سوزان ویکبرگ', '<p>کیم کریستفورت دارای مدرک MBA از دانشکده تحصیلات تکمیلی استنفورد است و بیش از هجده سال تجربه مشاوره مدیریت دارد. او در حال حاضر تیم Deloitte Greenhouse را رهبری می کند، گروهی که در تقویت تیم ها و تسریع پیشرفت تخصص دارد. </p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (730, 'مری پیفر', '<p>مری پیفر یک روانشناس بالینی و نویسنده متخصص در زمینه تروما، سلامت روان زنان و تأثیر فرهنگ بر بهزیستی روانشناختی است. پیفر ​​چندین کتاب پرفروش <em>نیویورک تایمز</em>، از جمله <em>احیای اوفلیا</em> و <em>کشوری دیگر</em> را نوشته است.</p>', '2023-01-26 20:16:11.172396', '2023-01-26 20:16:11.172396', NULL, 'Mary Pipher');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (731, 'جرمی ریفکین', '<p>جرمی ریفکین یکی از محبوب ترین رهبران فکری زمان ماست. او علاوه بر مشاوره به شرکت‌های پیشرو، سران کشورها و حتی اتحادیه اروپا، پرفروش‌ترین نویسنده 20 کتاب از جمله <em>پایان کار</em>و <em>تمدن همدلانه</em است. >.</p>', '2023-01-26 20:16:18.360985', '2023-01-26 20:16:18.360985', NULL, 'Jeremy Rifkin');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (732, 'امیلی ناگوسکی و آملیا ناگوسکی', '<p>امیلی ناگوسکی دارای مدرک دکترای رفتار سلامت از دانشگاه ایندیانا است و در حال حاضر در کالج اسمیت در ماساچوست به عنوان مدیر آموزش سلامتی کار می کند. او بیش از دو دهه تجربه به عنوان یک مربی جنسی دارد و نویسنده کتاب <em>همانطور که هستی بیا: علم جدید شگفت انگیزی که زندگی جنسی شما را متحول خواهد کرد</em>(2015).</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (733, 'بیل برایسون', '<p>بیل برایسون یک نویسنده انگلیسی-آمریکایی است که به خاطر نوشتن شوخ و جذاب خود در مورد همه چیز، از زبان گرفته تا تاریخ، شهرت دارد. اکنون، پس از بازگشت به بریتانیا، برایسون عضو افتخاری انجمن سلطنتی است. کتاب‌های قبلی او عبارتند از <em>A Walk in the Woods </em>(1995)، یک اثر زندگی‌نامه‌ای که برای تبدیل شدن به یک فیلم سینمایی بزرگ با بازی رابرت ردفورد، نیک نولته و اما تامپسون اقتباس شد.</p>', '2023-01-26 20:16:42.761206', '2023-01-26 20:16:42.761206', NULL, 'Bill Bryson');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (734, 'باغ اینا', '<p>اینا گارتن نویسنده محبوب کتاب آشپزی آمریکایی، مجری <em>Food Network</em> و سرآشپز مشهور است. او کار خود را در زمینه غذا با یک فروشگاه غذاهای ویژه فوق العاده محبوب در همپتون به نام Barefoot Contessa آغاز کرد. او در برنامه <em>شبکه غذایی</em> خود با همین نام، میلیون ها بیننده را با غذاهای خوشمزه و آشنا که برای همسرش جفری پخته شده بود، مجذوب خود کرد.</p>', '2023-01-26 20:16:50.533349', '2023-01-26 20:16:50.533349', NULL, 'Ina Garten');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (735, 'بن رایدر', '<p>بن رایتر یک روزنامه نگار مقیم نیویورک و مشارکت کننده منظم <em>Sports Illustrated</em>، <em>Time</em> و <em>Village Voice</em> است. <em>اختربال</em>اولین کتاب اوست.</p>', '2023-01-26 20:16:57.756215', '2023-01-26 20:16:57.756215', NULL, 'Ben Reiter');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (736, 'جودیت گریزل', '<p>جودیت گریسل، عصب شناس و روانشناس مستقر در دانشگاه باکنل در پنسیلوانیا است. گریسل قبل از موفقیت در حرفه آکادمیک، یک معتاد به مواد مخدر بود. تجربه شخصی او از اعتیاد و غلبه بر آن، رویکرد حرفه ای و نویسندگی او را نشان می دهد.</p>', '2023-01-26 20:17:04.498843', '2023-01-26 20:17:04.498843', NULL, 'Judith Grisel');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (737, 'گری کلر با دیو جنکس و جی پاپاسان', '<p>گری کلر نویسنده و سخنران عمومی است که بزرگترین امتیاز املاک و مستغلات را در آمریکای شمالی تأسیس کرد.</p>', '2023-01-26 20:17:11.387626', '2023-01-26 20:17:11.387626', NULL, 'Gary Keller with Dave Jenks and Jay Papasan');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (738, 'رابرت آی ساتن و هاگی رائو', '<p>هاگی رائو استاد رفتار سازمانی در دانشگاه استنفورد است. او کتاب <em>Market</em> <em>Rebels:</em> <em>How</em> <em>Activists</em> <em>Make</em> <em>یا را منتشر کرده است. </em> <em>شکستن</em> <em>رادیکال</em> <em>نوآوری</em>. رابرت آی ساتن استاد علوم مدیریت و مهندسی در دانشگاه استنفورد است. از جمله کتاب های او می توان به <em>خوب</em> <em>رئیس،</em> <em>بد</em> <em>رئیس</em> و <em>The</em> <em>نه اشاره کرد. </em> <em>اشل</em> <em>قانون </em>(همچنین در چشمک ها موجود است).</p>', '2023-01-26 20:17:18.392371', '2023-01-26 20:17:18.392371', NULL, 'Robert I. Sutton and Huggy Rao');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (739, 'جورج لئونارد', '<p>جرج لئونارد نویسنده، ویراستار و مربی آمریکایی بود که به خاطر کتاب‌های <em>تحول</em>و <em>راه آیکیدو</em> شهرت داشت. او رئیس موسسه Esalen، رئیس انجمن روانشناسی انسانی، بنیانگذار آموزش انرژی لئونارد (LET) - تمرینی که از هنر رزمی آیکیدو الهام گرفته شده است - و یکی از بنیانگذاران دوجو Aikido Tamalpais در کالیفرنیا بود. p>', '2023-01-26 20:17:25.103708', '2023-01-26 20:17:25.103708', NULL, 'George Leonard');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (740, 'E. F. شوماخر', '<p>ارنست فردریش شوماخر، شاگرد جان مینارد کینز، یک اقتصاددان مشهور بود. از سال 1950 تا 1970، او به عنوان مشاور ارشد اقتصادی هیئت ملی زغال سنگ بریتانیا خدمت کرد.</p>', '2023-01-26 20:17:32.479977', '2023-01-26 20:17:32.479977', NULL, 'E. F. Schumacher');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (741, 'فرد کوفمن', '<p>فرد کوفمن رئیس و بنیانگذار شرکت مشاوره Axialent است. او همچنین کتاب <em>Metamanagement</em> را نوشت و در سال 1992 "معلم سال" در دانشکده مدیریت اسلون موسسه فناوری ماساچوست بود.</p>', '2023-01-26 20:17:39.685392', '2023-01-26 20:17:39.685392', NULL, 'Fred Kofman');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (742, 'اندی دان', '<p>اندی دان دارای مدرک MBA از استنفورد است، جایی که او در سال 2007 با برایان اسپالی، یک برند پوشاک مردانه مستقیماً به مصرف کننده، Bonobos را پایه گذاری کرد. او قبل از خرید آن در سال 2017 به عنوان مدیر عامل Bonobos خدمت می کرد. اکنون یک سرمایه گذار فرشته است که مدیریت آن را بر عهده دارد. شرکت سرمایه گذاری خطرپذیر Red Swan، او در مجموع از بیش از 80 استارتاپ حمایت کرده است.</p>', '2023-01-26 20:17:46.574668', '2023-01-26 20:17:46.574668', NULL, 'Andy Dunn');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (743, 'جاناتان بریل', '<p>جاناتان بریل از چندین دهه تجربه به‌عنوان یک کارآفرین، مدیر فناوری Fortune 50 و شریک مدیریت مشاوران نوآوری که بیش از 350 محصول را برای مشتریان از جمله سامسونگ، مایکروسافت و ورایزون توسعه داده‌اند، اقتباس می‌کند. امروز، او مدیر عامل Resilient Growth Partners و یکی از همکاران نشریات برجسته از جمله <em>Forbes</em> و <em>Harvard Business Review</em> است.</p>', '2023-01-26 20:17:53.565219', '2023-01-26 20:17:53.565219', NULL, 'Jonathan Brill');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (744, 'کارن آرمسترانگ', '<p>کارن آرمسترانگ نویسنده بریتانیایی و راهبه سابق است که در سال 2008 جایزه 100000 دلاری TED را دریافت کرد. علاوه بر این، او منشور دلسوزی را ایجاد کرد که توسط بیش از 100000 نفر در سراسر جهان امضا شده است. از دیگر کتاب‌های او می‌توان به <em>پرونده خدا</em> و <em>تحول بزرگ</em> اشاره کرد.</p>', '2023-01-26 20:18:01.756204', '2023-01-26 20:18:01.756204', NULL, 'Karen Armstrong');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (745, 'ساویو چان و مایکل زاکور', '<p>Savio Chan مدیر عامل شرکت US China Partners Inc.، یک شرکت مشاوره است که به سازمان‌ها کمک می‌کند تا استراتژی‌های مصرف‌کننده خود را در چین طراحی و اجرا کنند. او در <em>نیویورک تایمز</em> و <em>فوربس</em> معرفی شده است و به عنوان عضو کمیته ملی روابط ایالات متحده و چین است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (746, 'جیل گریفین و مایکل دبلیو لوونشتاین', '<p>Michael W. Lowenstein مدیر عامل Customer Retention Associates و نویسنده تعدادی کتاب، از جمله <em>Customer Retention</em>و <em>Customer Loyalty Hermid است. </em></p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (747, 'امی راموس', '<p>ایمی راموس یک متخصص سلامت کل نگر و یک سرآشپز حرفه ای با بیش از 25 سال تجربه در تهیه دستور العمل ها و کمک به افرادی است که رژیم های غذایی محدود پزشکی دارند. او همچنین مدافع رژیم کتوژنیک و سبک زندگی کم کربوهیدرات است و نویسنده کتاب آشپزی پرفروش <em>آشپزی آسان رژیم کتوژنیک</em> (2017).</p>', '2023-01-26 20:18:23.727823', '2023-01-26 20:18:23.727823', NULL, 'Amy Ramos');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (748, 'دنیس لی یوون', '<p>دنیس لی یون، کارشناس برندسازی و رهبری برند، مشاور کسب‌وکار، سخنران اصلی و نویسنده تأثیرگذار تجاری است. او که به طور منظم در <em>Harvard Business Review</em> و <em>Forbes</em> همکاری می کند، همچنین نویسنده <em>برندهای بزرگ چه می کنند: هفت اصل برندسازی که بهترین ها را از استراحت</em>.</p>', '2023-01-26 20:18:30.759406', '2023-01-26 20:18:30.759406', NULL, 'Denise Lee Yohn');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (749, 'دارین ام. مک ماهون', '<p>دارین ام. مک ماهون یک استاد تاریخ آمریکایی است. او نویسنده <em>دشمنان روشنگری: ضدروشنگری فرانسوی و ساختن مدرنیته</em> و <em>خشم الهی: تاریخ نابغه</em> است. آثار او در <em>نیویورک تایمز</em>، <em>وال استریت ژورنال</em> و <em>واشنگتن پست</em></p> ظاهر شده است.
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (750, 'آنات شنکر اوسوریو', '<p>Anat Shenker-Osorio یک متخصص ارتباطات استراتژیک، محقق و کارشناس متخصص در امور عمومی و مسائل اجتماعی در ایالات متحده است. مشتریان قبلی او شامل بنیاد فورد، موسسه روزولت، انجمن پیشرو کنگره و بنیاد خانم بودند.</p>', '2023-01-26 20:18:50.796949', '2023-01-26 20:18:50.796949', NULL, 'Anat Shenker-Osorio');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (751, 'جیمز آنجلوس', '<p>جیمز آنجلوس روزنامه نگار و خبرنگار سابق <em>وال استریت ژورنال</em> است و همچنین برای <em>نیویورک تایمز</em> نوشته است.</p>', '2023-01-26 20:18:58.027755', '2023-01-26 20:18:58.027755', NULL, 'James Angelos');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (752, 'نانسی لیز استپان', '<p>نانسی لیز استپان استاد تاریخ بهداشت عمومی در دانشگاه کلمبیا است. او روی اصلاح نژاد و آمریکای لاتین تمرکز دارد.</p>', '2023-01-26 20:19:04.950233', '2023-01-26 20:19:04.950233', NULL, 'Nancy Leys Stepan');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (753, 'ویکی هالزی', '<p>ویکی هالسی یک طراح آموزشی، سخنران و نویسنده با تجربه به عنوان معلم، مشاور و مدیر مدرسه است. در حال حاضر، او به عنوان معاون آموزش کاربردی شرکت های Ken Blanchard که در زمینه یادگیری در محل کار، بهره وری و آموزش رهبری تخصص دارند، خدمت می کند. او نویسنده <em>رهبری در سطح بالاتر، انقلاب همستر، </em>و <em>انقلاب همستر برای جلسات</em></p> است.', '2023-01-26 20:19:12.0307', '2023-01-26 20:19:12.0307', NULL, 'Vicki Halsey');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (754, 'استفان گیز', '<p>استفان گیز نویسنده، وبلاگ نویس و محققی است که در رشد شخصی و یادگیری سرگرم کننده تخصص دارد. آخرین کتاب او <em>چگونه یک ناکامل گرا باشیم</em> نام دارد.</p>', '2023-01-26 20:19:19.568776', '2023-01-26 20:19:19.568776', NULL, 'Stephen Guise');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (755, 'ماریانا مازوکاتو', '<p>ماریانا مازوکاتو، استاد مشهور اقتصاد نوآوری است که در دانشگاه ساسکس تدریس می‌کند. <em>وضعیت کارآفرین</em>کتاب سال <em>فایننشال تایمز</em> و <em>هافینگتون پست</em> بود.</p>', '2023-01-26 20:19:26.716446', '2023-01-26 20:19:26.716446', NULL, 'Mariana Mazzucato');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (756, 'جرد دایموند', '<p>جارد دایموند استاد جغرافیا در دانشگاه کالیفرنیا، لس آنجلس است. الماس که برنده جایزه پولیتزر برای رمان پرفروش <em>اسلحه، میکروب و فولاد</em> است، مدال ملی علم و بورسیه بنیاد مک آرتور را نیز دریافت کرده است.</p>', '2023-01-26 20:19:34.010546', '2023-01-26 20:19:34.010546', NULL, 'Jared Diamond');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (757, 'راب مور', '<p> راب مور یک سرمایه گذار بریتانیایی بسیار موفق در ملک است که در سن 30 سالگی میلیونر شد و چند سال قبل از آن یک هنرمند بی سابقه بود. او نویسنده هشت کتاب است و میزبان <em>The Disruptive Entrepreneur</em>، یکی از موفق ترین پادکست های تجاری بریتانیا است. </p>', '2023-01-26 20:19:40.766888', '2023-01-26 20:19:40.766888', NULL, 'Rob Moore');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (758, 'فیل نایت', '<p>فیل نایت یک تاجر آمریکایی است که شرکت نایک را تاسیس کرد و به عنوان مدیر عامل آن خدمت کرد.</p>', '2023-01-26 20:19:47.556779', '2023-01-26 20:19:47.556779', NULL, 'Phil Knight');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (759, 'آرون دیگنان', '<p>آرون دیگنان بنیانگذار The Ready، یک شرکت مربیگری و طراحی سازمانی با مشتریانی مانند مایکروسافت، Airbnb، و جانسون و جانسون است. او همچنین یک سرمایه گذار فرشته است و در هیئت های مشاوره PepsiCo، American Express و GE حضور داشته است. </p>', '2023-01-26 20:19:54.46546', '2023-01-26 20:19:54.46546', NULL, 'Aaron Dignan');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (760, 'فیلد ترفز', '<p>آلن ترفلر موسس، مدیر عامل و رئیس هیئت مدیره Pegasystems است. او در سال 2009 به عنوان مدیر عامل نرم افزار سال جوایز کسب و کار آمریکا انتخاب شد و در سال 2011 توسط شورای رهبری فناوری ماساچوست به عنوان مدیر عامل شرکت عمومی انتخاب شد.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (761, 'جروم ترنینک', '<p>جروم ترنینک یک کارآفرین، نویسنده و بنیانگذار SmartRecruiters است - یک رهبر در دنیای جذب استعدادهای جهانی. او بیش از 30 سال تجربه در کمک به کسب و کارها در جهت یابی بازار کار جهان دارد.</p>', '2023-01-26 20:20:08.666873', '2023-01-26 20:20:08.666873', NULL, 'Jerome Ternynck');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (762, 'رابرت جی اندرسون و ویلیام آدامز', '<p>رابرت جی. اندرسون موسس و مدیر ارشد توسعه حلقه رهبری، یک سازمان توسعه رهبری است. او همچنین خالق پروفایل حلقه رهبری است، یک ابزار یکپارچه ارزیابی رهبری که توسط هزاران کسب و کار در سراسر جهان استفاده شده است. </p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (763, 'پما چودرون', '<p>پما چودرون یک معلم سابق دبستان است که با استاد چوگیام ترونگپا رینپوچه به مطالعه بودیسم ادامه داد. در هنگ کنگ، در سال 1981، او یک راهبه بودایی کاملاً منصوب شد و وقف آموزش رهبانیت بودایی تیبرتان در ایالات متحده و کانادا است. </p>', '2023-01-26 20:20:28.323264', '2023-01-26 20:20:28.323264', NULL, 'Pema Chödrön');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (764, 'دیوید ارمیا', '<p>دیوید ارمیا یک واعظ انجیلی از اوهایو است. او بنیانگذار وزارتخانه های رادیو و تلویزیون نقطه عطف است که موعظه های او را پخش می کند. او همچنین کشیش ارشد کلیسای جامعه سایه کوه، یک کلیسای بزرگ باپتیست جنوبی در ال کاجون، کالیفرنیا است. او در هیئت مشاوران انجیلی پرزیدنت ترامپ خدمت کرد.</p>', '2023-01-26 20:20:35.437527', '2023-01-26 20:20:35.437527', NULL, 'David Jeremiah');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (765, 'مارک اپستاین', '<p>مارک اپستاین یک روان درمانگر، پزشک بودایی و نویسنده تحصیل کرده در هاروارد است. چندین عنوان او مورد تأیید حضرت دالایی لاما قرار گرفته است.</p>', '2023-01-26 20:20:47.85258', '2023-01-26 20:20:47.85258', NULL, 'Mark Epstein');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (766, 'نیل اشتراوس', '<p>نیل اشتراوس نویسنده سابق موسیقی <em>The</em> <em>New</em> <em>York</em> <em>Times</em> و یک شهروند پارانوئید خودخوانده است. ساکن او همچنین نویسنده کتاب پرفروش <em>The</em> <em>Game:</em> <em>Penetrating</em> <em>the</em> <em>Secret</em> em> <em>انجمن</em> <em>از</em> <em>پیکاپ</em> <em>هنرمندان</em>.</p>', '2023-01-26 20:20:54.729186', '2023-01-26 20:20:54.729186', NULL, 'Neil Strauss');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (767, 'برایان جی رابرتسون', '<p>برایان جی رابرتسون خالق هولاکراسی است. او آن را با آزمایش روش ها و شیوه های مختلف سازمانی در راه اندازی نرم افزار خود توسعه داد. او همچنین شرکت HolacracyOne را تأسیس کرده است که به شرکت‌هایی که در حال انتقال به سیستم‌های مدیریت Holacratic هستند مشاوره می‌دهد.</p>', '2023-01-26 20:21:02.09268', '2023-01-26 20:21:02.09268', NULL, 'Brian J. Robertson');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (769, 'مگان لیهی', '<p>مگان لیهی یک ستون نویس در "درباره والدین" در <em> واشنگتن پست</em> و یک مربی معتبر والدین است. او در NPR و ABC ظاهر شده است و نوشته های او در نشریات متعددی به نمایش درآمده است.</p>', '2023-01-26 20:21:21.9979', '2023-01-26 20:21:21.9979', NULL, 'Meghan Leahy');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (770, 'جی IA جیانگ', '<p>نویسنده و کارآفرین جیا جیانگ، بنیانگذار وبلاگ و مجموعه محبوب YouTube،<em> 100 Days of Rejection</em> است. جیانگ همچنین خالق یک دوره و انجمن آنلاین است که به دیگران می آموزد چگونه بر ترس خود از رد شدن غلبه کنند.</p>', '2023-01-26 20:21:34.226935', '2023-01-26 20:21:34.226935', NULL, 'Jia Jiang');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (771, 'لی واترز', '<p>لی واترز یک روانشناس است که مدرک دکترای خود را در دانشگاه دیکین استرالیا دریافت کرده است. او بیش از 20 سال است که در زمینه آموزش کودکان تحقیق می کند. او در کار خود به عنوان یک روانشناس، دیده است که تمرکز بر نقاط قوت کودک چه تأثیری بر رشد کودک و رفاه کل خانواده دارد. او طیف وسیعی از مقالات علمی در این زمینه منتشر کرده است.</p>', '2023-01-26 20:21:41.242461', '2023-01-26 20:21:41.242461', NULL, 'Lea Waters');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (772, 'رابی کلمن باکستر', '<p>رابی کلمن باکستر مشاور و سخنران برجسته است. مشتریان قبلی او عبارتند از Netflix، Yahoo و eBay.</p>', '2023-01-26 20:21:53.913969', '2023-01-26 20:21:53.913969', NULL, 'Robbie Kellman Baxter');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (773, 'کوین هورسلی', '<p>کوین هورسلی در مورد نحوه عملکرد ذهن متخصص است. او به‌عنوان یکی از معدود افرادی که عنوان استاد بزرگ بین‌المللی حافظه را دریافت کرده است، در حال حاضر به‌عنوان مشاور سازمان‌های سراسر جهان در مورد چگونگی رویکرد یادگیری، انگیزه و خلاقیت کار می‌کند.</p>', '2023-01-26 20:22:01.254229', '2023-01-26 20:22:01.254229', NULL, 'Kevin Horsley');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (774, 'دین جنسن', '<p>Dane Jensen مدیر عامل شرکت مشاوره فاکتور سوم است که در آن برنامه‌های توسعه رهبری در آمریکای شمالی را نیز مدیریت می‌کند. جنسن همچنین در برنامه MBA اجرایی در مدرسه تجارت اسمیت در انتاریو تدریس می کند و به ورزشکاران و مربیان در سازمان های المپیک و پارالمپیک مشاوره می دهد. این اولین کتاب او است.</p>', '2023-01-26 20:22:08.085078', '2023-01-26 20:22:08.085078', NULL, 'Dane Jensen');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (775, 'تیم تحریریه محتوا', '<p>تیم تحریریه محتوا در Blinkist افراد پرشور پشت هزاران محتوایی هستند که در برنامه خواهید یافت. چشمک می‌زند، راهنما، یا کوتاه: تیم تحریریه ما می‌داند که چگونه مرتبط‌ترین اطلاعات را از کتاب‌ها و پادکست‌ها انتخاب و ارائه کند که به شما آموزش و سرگرمی می‌دهد.</p>', '2023-01-26 20:22:15.51057', '2023-01-26 20:22:15.51057', NULL, 'The Content Editorial Team');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (776, 'ایو کوری', '<p>او کوری (1904-2007) دختر ماری و پیر کوری بود. او یک روزنامه‌نگار و گزارشگر جنگی پیشگام و بعدها از حامیان سرسخت یونیسف بود. بیوگرافی مادرش که در سال 1937 منتشر شد، بسیار مورد تحسین قرار گرفت. برنده جایزه کتاب ملی برای غیرداستانی شد.</p>', '2023-01-26 20:33:37.838019', '2023-01-26 20:33:37.838019', NULL, 'Eve Curie');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (777, 'جورج مونبیوت', '<p>جرج مونبیوت یک جانورشناس آموزش دیده است و به عنوان روزنامه نگار طبیعت و همچنین برای سازمان های دوستدار محیط زیست کار کرده است. او مدت‌هاست در بریتانیا اقامت دارد و به طور منظم در <em>گاردین</em> همکاری می‌کند. او چندین کتاب منتشر کرده است، از جمله <em>Captive State</em> و <em>Age of Consent</em>.</p>', '2023-01-26 20:33:44.945862', '2023-01-26 20:33:44.945862', NULL, 'George Monbiot');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (778, 'آنتونی لولی', '<p>آنتونی لولی بنیانگذار و مدیر عامل امتیاز Rapid Realty - سریعترین شرکت املاک و مستغلات در نیویورک است. او همچنین مدرسه املاک و مستغلات اکسپرس را تأسیس کرد که به هزاران دانش آموز کمک کرده است تا مجوزهای املاک خود را دریافت کنند.</p>', '2023-01-26 20:33:51.907951', '2023-01-26 20:33:51.907951', NULL, 'Anthony Lolli');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (779, 'جیمز دبلیو پنه بیکر', '<p>جیمز دبلیو پنه بیکر رئیس بخش روانشناسی دانشگاه تگزاس در آستین است و نویسنده <em>نوشتن برای شفا</em> و <em>باز کردن</em> است.</p> >', '2023-01-26 20:33:59.090595', '2023-01-26 20:33:59.090595', NULL, 'James W. Pennebaker');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (780, 'دکتر ویلیام دیویس', '<p>دکتر ویلیام دیویس یک متخصص قلب آمریکایی و نویسنده پرفروش <em>نیویورک تایمز</em> است که بیشتر به خاطر حمایت پرشور خود از سبک زندگی بدون گندم شناخته شده است. از دیگر کتاب‌های او می‌توان به <em>کتاب آشپزی شکم گندم</em> (2012) و <em>بدون دکتر: چرا مراقبت‌های بهداشتی با شکست مواجه شد و چگونه می‌توانی باهوش‌تر از پزشک خود شوی </em> (2017) نام برد.</p>', '2023-01-26 20:34:11.635316', '2023-01-26 20:34:11.635316', NULL, 'Dr. William Davis');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (781, 'راشل هالیس', '<p>ریچل هالیس بنیانگذار TheChicSite.com، مادر چهار فرزند، یک مسیحی معتقد و یک نیروگاه انگیزشی همه جانبه است. کتاب‌های دیگر او شامل کتاب دستور غذا، <em>شام‌های زندگی واقعی</em>، و مجموعه رمان‌های <em>دختر</em> بر اساس زندگی یک برنامه‌ریز رویدادهای جوان در لس‌آنجلس است.</p>', '2023-01-26 20:34:24.921234', '2023-01-26 20:34:24.921234', NULL, 'Rachel Hollis');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (782, 'برنارد راث', '<p>برنارد راث استاد مهندسی و مدیر آکادمیک موسسه طراحی هاسو پلاتنر در دانشگاه استنفورد است. او یکی از پیشگامان جهان در رباتیک و متخصص در سینماتیک، علم حرکت است.</p>', '2023-01-26 20:34:32.04779', '2023-01-26 20:34:32.04779', NULL, 'Bernard Roth');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (783, 'برایان موری', '<p>برایان موری موسس و مدیر عامل واشنگتن استریت پرپرتیز، یک شرکت تجاری سرمایه گذاری در املاک و مستغلات و یکی از شرکت های خصوصی با سریع ترین رشد در آمریکا است. در سال 2015، جایزه طلایی استیوی برای مدیر املاک و مستغلات سال در جوایز سالانه کسب و کار آمریکا به او اهدا شد.</p>', '2023-01-26 20:34:39.492372', '2023-01-26 20:34:39.492372', NULL, 'Brian Murray');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (784, 'ویم هوف', '<p>ویم هوف یک ورزشکار افراطی از هلند است. او با نام مستعار «مرد یخی» رکوردهای مواجهه با سرما از جمله بالا رفتن از قله کلیمانجارو با شلوارک، دویدن نیمه ماراتن بر فراز دایره قطب شمال با پای برهنه، و شنا کردن زیر یخ به طول 66 متر را شکست.</p>', '2023-01-26 20:34:46.850484', '2023-01-26 20:34:46.850484', NULL, 'Wim Hof');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (785, 'دیو رمزی و دخترش ریچل کروز', '<p> دیو رمزی و دخترش ریچل کروز در زمینه ساختن و حفظ موفقیت مالی شخصی متخصص هستند. رمزی به مردم کمک می کند تا از بدهی خارج شوند در حالی که کروز به مردم کمک می کند در وهله اول از بدهی خود دور بمانند. از دیگر کتاب‌های رمزی می‌توان به <em>آرامش مالی </em>و <em>معادل کل پول</em> اشاره کرد. از دیگر کتاب‌های کروز می‌توان به <em>زندگی خود را دوست داشته باشید نه مال آنها</em>و <em>خود را بدانید که پول خود را بدانید.</em></p>', '2023-01-26 20:34:53.898928', '2023-01-26 20:34:53.898928', NULL, 'Dave Ramsey and his daughter Rachel Cruze');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (786, 'نسا کری', '<p> نسا کری دارای دکترای ویروس شناسی از دانشگاه ادینبورگ است و قبلاً مدرس ارشد زیست شناسی مولکولی در کالج امپریال لندن بود. او اکنون Carey International Impact Training را اجرا می‌کند و نویسنده دو کتاب دیگر به نام‌های <em>Junk DNA</em>و<em> Hacking the Code of Life است.</em></p>', '2023-01-26 20:35:00.930145', '2023-01-26 20:35:00.930145', NULL, 'Nessa Carey');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (787, 'اوری سوارتز', '<p>Avery Swartz یک مشاور بازاریابی دیجیتال، نویسنده فناوری و سخنران است که در بین 50 زن برتر در بازاریابی توسط <em>Search Engine Journal</em> رتبه بندی شده است. او همچنین بنیانگذار و مدیر عامل کمپ تک است، شرکتی که آموزش بازاریابی دیجیتال را برای کسب و کارهای کوچک و سازمان ها در سراسر کانادا ارائه می دهد. </p>', '2023-01-26 20:35:08.11527', '2023-01-26 20:35:08.11527', NULL, 'Avery Swartz');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (788, 'لیندا کاپلان تالر و رابین کووال', '<p>لیندا کاپلان تالر یک نماد تبلیغاتی تالار مشاهیر و ذهنی است که در پس برخی از شناخته‌شده‌ترین کمپین‌های تبلیغاتی زمان ما قرار دارد. او رئیس Publicis Kaplan Thaler است و مدیرعامل و همچنین یکی از بنیانگذاران گروه Kaplan Thaler بود.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (789, 'دالایی لاما و دزموند توتو', '<p> عالیجناب، دالایی لاما برنده جایزه صلح نوبل و رهبر معنوی مردم تبت است. آموزه های او از شفقت و بودیسم حمایت می کند، و او چندین کتاب در مورد آنها نوشته است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (790, 'پرواز شاپیرو', '<p>بن شاپیرو یکی از مفسران محافظه کار پیشرو در ایالات متحده امروز است. پادکست او، <em>نمایش بن شاپیرو</em>، برترین پادکست محافظه کار کشور است. او نویسنده <em>نیویورک تایمز</em> پرفروش‌ترین عناوین از جمله <em>Primimetime Propaganda</em> و <em>The People vs. باراک اوباما</em>.</p>', '2023-01-26 20:35:35.191876', '2023-01-26 20:35:35.191876', NULL, 'Ben Shapiro');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (791, 'شین اسنو', '<p>شین اسنو یک روزنامه نگار برنده جایزه و یکی از بنیانگذاران شرکت فناوری محتوا Contently است. او نویسنده پرفروش <em>Smartcuts</em> (2014) و نویسنده همکار <em>The Storytelling Edge</em> (2018) است.</p>', '2023-01-26 20:35:42.337398', '2023-01-26 20:35:42.337398', NULL, 'Shane Snow');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (792, 'الن روگین و لیزا کوئنگ', '<p>الن روگین یک حسابدار رسمی و برنامه ریز مالی. او بیش از 20 سال به عنوان مشاور مالی کار کرده است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (793, 'رایان هالیدی و استیون هانسلمن', '<p>رایان هالیدی نویسنده، استراتژیست رسانه ای و صاحب کتابفروشی آمریکایی است. او همچنین میزبان پادکست Daily Stoic است. کتاب‌های دیگر او شامل <em>زندگی رواقیون، شجاعت فرا می‌خواند</em> و <em>موانع راه است</em> است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (794, 'قزل آلای فصلی میو', '<p>شونمیو ماسونو یک راهب ذن ژاپنی و یک طراح باغ مشهور است. ماسونو نه تنها رهبر معبد بودایی ذن کنکو جی است، بلکه استاد طراحی محیطی در دانشگاه هنر تاما توکیو است. </p>', '2023-01-26 20:36:09.041642', '2023-01-26 20:36:09.041642', NULL, 'Shunmyo Masuno');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (795, 'کلوتر راپایل', '<p>دکتر کلوتر راپایل یک مربی بازاریابی بین المللی و بنیانگذار Archetype Discoveries Worldwide است که بینش بازاریابی جهانی را در مورد برخی از بزرگترین برندهای جهان ارائه کرده است. او همچنین نویسنده کتاب‌های متعددی در زمینه بازاریابی، جامعه‌شناسی، روان‌شناسی و انسان‌شناسی فرهنگی است، از جمله <em>کد فرهنگ: روشی مبتکرانه برای درک اینکه چرا مردم در سراسر جهان همانطور که می‌کنند زندگی می‌کنند و خرید می‌کنند. </em></p>', '2023-01-26 20:36:15.88617', '2023-01-26 20:36:15.88617', NULL, 'Clotaire Rapaille');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (796, 'زک را ببلع', '<p>دورا زک مشاور رهبری و بنیانگذار شرکت Only Connect Consulting است. موفقیت او در مشاوره رهبری مبنایی برای بسیاری از کتاب‌های او بوده است، از جمله <em>شبکه‌سازی برای افرادی که</em> <em>شبکه‌سازی متنفرند</em>و <em>مدیریت برای افرادی که از مدیریت متنفرند</em> .</p>', '2023-01-26 20:36:23.198092', '2023-01-26 20:36:23.198092', NULL, 'Devora Zack');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (845, 'کتی مور', '<p>کتی مور یک طراح آموزشی مشهور بین‌المللی، سخنران مورد تقاضا، نویسنده تجاری و وبلاگ‌نویس است که سیستم نقشه‌برداری Action او طراحی آموزشی را برای شرکت‌ها و سازمان‌ها در سراسر جهان، از آمازون گرفته تا برنامه جهانی غذای سازمان ملل متحد، بهبود بخشیده است.</p> >', '2023-01-26 20:42:40.825528', '2023-01-26 20:42:40.825528', NULL, 'Cathy Moore');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (797, 'دیوید اس ویلیامز', '<p>دیوید ویلیامز مدیر عامل آژانس بازاریابی عملکرد مرکل است. او یکی از سخنرانان مکرر رویدادهای صنعت است و مقالات و مقالات سفید متعددی در زمینه بازاریابی پایگاه داده و تجزیه و تحلیل، بازاریابی ارتباط با مشتری و فناوری بازاریابی نوشته است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (798, 'تیم سندرز', '<p>تیم سندرز به عنوان مشاور برای شرکت های Fortune 1000 خدمت کرده است، چندین کتاب پرفروش نوشته و در سرتاسر جهان صحبت کرده است. او از دانش عمیق خود در زمینه تجارت، روانشناسی و بازاریابی استفاده می کند تا به مردم و شرکت ها کمک کند تا در هر اقتصادی به بهترین شکل ممکن دست یابند.</p>', '2023-01-26 20:36:42.597212', '2023-01-26 20:36:42.597212', NULL, 'Tim Sanders');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (799, 'روبرتا چینسکی ماتوسون', '<p>Roberta Chinsky Matuson رئیس مشاور Matuson و وبلاگ نویس متخصص برای <em>Fast Company</em> و <em>Forbes</em> است. او به شرکت هایی مانند Best Buy، Monster و Staples در مورد جذب استعدادها و رشد شرکت مشاوره داده است.</p>', '2023-01-26 20:36:50.083707', '2023-01-26 20:36:50.083707', NULL, 'Roberta Chinsky Matuson ');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (800, 'شریل سندبرگ و آدام گرانت', '<p>شریل سندبرگ، مدیر عامل فیس بوک و یک بشردوست فعال است که به زنان کمک می کند تا به اهداف خود برسند. او قبلاً معاون فروش آنلاین در گوگل و همچنین رئیس کارکنان وزارت خزانه داری ایالات متحده بود. اولین کتاب او پرفروش ترین کتاب <em>Lean In.</em></p> بود
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (801, 'تاد دیویس', '<p>تاد دیویس دارای چندین دهه تجربه در زمینه منابع انسانی است و در استخدام و توسعه استعدادها متخصص است. او معاون اجرایی شرکت مشاوره فرانکلین کووی است که مسئولیت دفاتر توسعه استعدادهای جهانی آن را نیز بر عهده دارد. دیویس همچنین نویسنده <em>Talent Unleashed: 3 Leadership Conversation to Ignite the Unlimited Potential in People</em> است.</p>', '2023-01-26 20:37:04.201479', '2023-01-26 20:37:04.201479', NULL, 'Todd Davis');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (802, 'پیتر لینچ', '<p>پیتر لینچ یک سرمایه گذار و مدیر صندوق سرمایه گذاری مشترک است. او 13 سال را در راس صندوق چند میلیارد دلاری Fidelity Magellan گذراند و تحت رهبری او به موفق ترین صندوق در جهان تبدیل شد. لینچ همچنین نویسنده کتاب های پرفروش <em>Beating the Street</em> و <em>Learn to Earn</em> است.</p>', '2023-01-26 20:37:11.315837', '2023-01-26 20:37:11.315837', NULL, 'Peter Lynch');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (803, 'جیم گری', '<p>جیم گری برنده دوازده جایزه امی، پخش کننده ورزشی تالار مشاهیر، و مصاحبه کننده مشهور است. او ورزش‌هایی را در سرتاسر جهان پخش کرده است، از جمله بازی‌های المپیک، سوپربول، سری جهانی، فینال‌های NBA، مسترها، بازی‌های ستاره‌ها و مبارزات قهرمانی بوکس.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (804, 'روزاموند استون زاندر و بنجامین زاندر', '<p>روزاموند استون زاندر یک خانواده درمانگر و مربی اجرایی است که کارش بر اساس این مفهوم است که انسان ها ذاتاً خلاق هستند. او سیستم‌هایی را توسعه می‌دهد که از شرکت‌ها، موسسات و تیم‌ها در مولد شدن و مولد شدن پشتیبانی می‌کنند. </p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (805, 'آن هندلی و سی.سی. چپمن', '<p>Ann Handley مدیر ارشد محتوای MarketingProfs است، شرکتی که منابع بازاریابی و آموزش را به 442000 مشترک ارائه می دهد. او نویسنده <em>Everybody Writes: Your Go-To Guide to Creating Ridiculously Good Content</em> است که پرفروش ترین کتاب <em>وال استریت ژورنال</em> است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (806, 'کارولین ال آرنولد', '<p>کارولین ال. آرنولد مدیر اجرایی یک بانک سرمایه گذاری پیشرو وال استریت است و یکی از رهبران فناوری در وال استریت محسوب می شود. او همچنین برنده جایزه وال استریت و فناوری برای نوآوری است.</p>', '2023-01-26 20:37:40.479166', '2023-01-26 20:37:40.479166', NULL, 'Caroline L. Arnold');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (807, 'ناتالی لو', '<p>ناتالی لو متخصص اشتباهات جدایی است که باید از آنها اجتناب کرد. چرا؟ زیرا او بیشتر از سهم خود ساخته است. اما در سال 2005 که از دلشکستگی خسته شده بود، خود را به چالش کشید تا عادات بد رابطه را کنار بگذارد و حس خود را بازیابد. اکنون، او وبلاگ‌ها و پادکست‌های مربوط به روابط و جدایی‌ها را از طریق برند بسیار محبوبش «بازپس‌گیری چمدان» می‌نویسد.</p>', '2023-01-26 20:37:47.217906', '2023-01-26 20:37:47.217906', NULL, 'Natalie Lue');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (808, 'برایان فترستونهاگ', '<p>برایان فترستونهاگ مدیر عامل OgilvyOne Worldwide است، یک آژانس بازاریابی موفق که از سال 1983 به کسب و کارهای بزرگ کمک می کند. در طول سال ها، او به هزاران نفر مشاوره و راهنمایی داده است و در دانشگاه هایی مانند ییل، هاروارد و کلمبیا در مورد استراتژی شغلی سخنرانی کرده است. .</p>', '2023-01-26 20:37:54.287025', '2023-01-26 20:37:54.287025', NULL, 'Brian Fetherstonhaugh');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (809, 'سرینیواس رائو', '<p>Srinivas Rao نویسنده و میزبان پادکست محبوب <em>خلاقیت ناپذیر</em> است که هر هفته با مجموعه ای از ذهن های خلاق مصاحبه های روشنگری ارائه می دهد. او با کمک به مردم برای گوش دادن به صدای خلاقانه آنها تلاش می کند تا جهان را به مکانی هنری تر تبدیل کند. کتاب‌های قبلی او شامل کتاب پرفروش <em>هنر بی‌گمان بودن</em> است.</p>', '2023-01-26 20:38:01.826924', '2023-01-26 20:38:01.826924', NULL, 'Srinivas Rao');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (810, 'ترنس رئال', '<p>ترنس رئال یک خانواده درمانگر، سخنران، نویسنده و پیشگام روش درمانی زندگی رابطه ای است. توصیه‌های قدرتمند و کاربردی او برای زوج‌هایی که به دنبال بهبود اعتماد، صمیمیت و ارتباطات هستند در The Today Show، Good Morning America، و Oprah و همچنین در <em>نیویورک تایمز</em> ارائه شده است.</p>', '2023-01-26 20:38:08.995038', '2023-01-26 20:38:08.995038', NULL, 'Terrence Real');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (811, 'استیون دی. لویت و استفن جی دوبنر', '<p>Steven D. Levitt یک اقتصاددان آمریکایی با مدرک تحصیلی از دانشگاه هاروارد و موسسه فناوری ماساچوست است و در تحقیق در مورد جرم و جنایت و فساد تخصص دارد. او در حال حاضر در دانشگاه شیکاگو تدریس می کند.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (812, 'ادوارد اسلینجرلند', '<p>ادوارد سلینگرلند یک دانشگاهی و نویسنده است که در علوم شناختی و تفکر چینی تخصص دارد. او قبلاً <em>What Science Offers the Humanities</em></p> را نوشته است', '2023-01-26 20:38:24.143801', '2023-01-26 20:38:24.143801', NULL, 'Edward Slingerland');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (813, 'راندال مونرو', '<p>رندال مونرو رباتیک سابق ناسا و خالق وب کمیک بسیار محبوب <em>xkcd</em> است. در سال 2013، به درخواست تعدادی از <em>xkcd </em>علاقه‌مندان، سیارک 4942 Munroe توسط اتحادیه بین‌المللی نجوم به نام او نامگذاری شد.</p>', '2023-01-26 20:38:31.21929', '2023-01-26 20:38:31.21929', NULL, 'Randall Munroe');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (814, 'کانر ریچاردسون', '<p>کانر ریچاردسون به‌عنوان یک حسابدار دولتی خبره، نکات و نکات مربوط به بودجه‌بندی، مدیریت پول و استراتژی سرمایه‌گذاری صحیح را می‌داند. به عنوان یک هزاره، او همچنین بینش شخصی نسبت به چالش‌های مالی منحصربه‌فردی دارد که نسلش با آن مواجه است. ماموریت ریچاردسون آموزش همتایان خود در مورد بهترین استراتژی‌ها برای دستیابی به موفقیت مالی از طریق وب‌سایت محبوب او، <em>Millenial Money Makeover</em> است.</p>', '2023-01-26 20:38:39.030077', '2023-01-26 20:38:39.030077', NULL, 'Conor Richardson');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (815, 'سایمون بلکبرن', '<p>سایمون بلکبرن، استاد بازنشسته فلسفه در دانشگاه کمبریج، و پژوهشگر برجسته فلسفه در دانشگاه کارولینای شمالی، چپل هیل است. بلکبرن همراه با سهم قابل توجهی که در فلسفه آکادمیک - به ویژه در فرااخلاق و شبه واقع‌گرایی دارد - به خاطر کتاب‌هایش که مخاطبان عام را هدف قرار می‌دهند، مانند کتاب پرفروش <em>Think شناخته می‌شود. </em></p>', '2023-01-26 20:38:51.631693', '2023-01-26 20:38:51.631693', NULL, 'Simon Blackburn');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (816, 'آری مایزل و نیک سوننبرگ', '<p>آری مایزل قبل از تشخیص بیماری کرون در سال 2006، توسعه‌دهنده املاک و مستغلات بود که کار کردن را برای او غیرممکن می‌کرد. او باید روش جدیدی برای انجام کارها ایجاد می کرد، بنابراین سیستم بهره وری Less Doing را که به تفصیل در کتاب <em>Less Doing, More Living</em></p> شرح داده شده است، تأسیس کرد.
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (817, 'راغورام سی راجان', '<p>یکی از معدود کارشناسانی که سقوط 2008 را دیده است، Raghuram G. Rajan، اقتصاددان ارشد سابق صندوق بین المللی پول (IMF)، استاد امور مالی (در مرخصی از سال 2013) در دانشکده تحصیلات تکمیلی است. کسب و کار در دانشگاه شیکاگو و رئیس بانک مرکزی هند.</p>', '2023-01-26 20:39:05.737708', '2023-01-26 20:39:05.737708', NULL, 'Raghuram G. Rajan');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (818, 'ریچارد کخ', '<p>ریچارد کخ، شریک سابق شرکت مشاوره Bain & Co، نویسنده، کارآفرین و سرمایه‌گذار بسیار مورد توجه است.</p>', '2023-01-26 20:39:07.840168', '2023-01-26 20:39:07.840168', NULL, 'Richard Koch');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (819, 'اسکات پیپ', '<p>اسکات پیپ نویسنده، مفسر رادیویی و مشاور سرمایه‌گذاری استرالیایی و همچنین ستون‌نویس چندین مقاله از جمله <em>Australian Daily Telegraph</em> است. او از نظر حرفه ای دوست دارد به عنوان "سرمایه گذار پابرهنه" شناخته شود. Pape یک برنامه تلویزیونی در CNBC با همین نام دارد.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (858, 'سارا میتلند', '<p>سارا میتلند یک رمان نویس و فمینیست برجسته بریتانیایی است. او آثار متعدد داستانی و غیرداستانی نوشته است، از جمله <em>کتاب سکوت</em>، اولین اثر او، و <em>دختر اورشلیم</em>، رمانی که برنده جایزه سامرست موام شد.</em> p>', '2023-01-26 20:50:21.02498', '2023-01-26 20:50:21.02498', NULL, 'Sara Maitland');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (820, 'دو پاتنیک و پیتر مورتنسن', '<p>Dev Patnaik بنیانگذار و مدیر عامل شرکت استراتژی رشد Jump Associates است که با مشتریانی مانند نایک، سامسونگ و کرایسلر کار کرده است. Patnaik همچنین سخنران و استاد کمکی در دانشگاه استنفورد است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (821, 'هلن کلر', '<p>هلن کلر (1880-1968) نویسنده، سخنران و فعال سیاسی آمریکایی بود که بخشی از جنبش حق رای زنان بود و به عنوان عضوی از حزب سوسیالیست برای طبقات کارگر سخنرانی می کرد. او زندگی خود را وقف کمک به دیگران کرد. او همچنین به تأسیس اتحادیه آزادی های مدنی آمریکا کمک کرد.</p>', '2023-01-26 20:39:34.464669', '2023-01-26 20:39:34.464669', NULL, 'Helen Keller');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (822, 'آلن دبلیو واتس', '<p>آلن واتس یک الهی‌دان جایگزین و فیلسوف عصر جدید بود که در سال 1973 درگذشت. او متخصص ذن بودیسم و ​​سایر فلسفه‌ها و مذاهب شرقی بود. بسیاری از انتشارات او عبارتند از <em>کیهان شناسی شاد</em>، <em>راه ذن</em> و <em>حکمت ناامنی</em>.</p>', '2023-01-26 20:39:41.382727', '2023-01-26 20:39:41.382727', NULL, 'Alan W. Watts');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (823, 'اریکا کسوین', '<p>Erica Keswin یک استراتژیست در محل کار است که برای برخی از نمادین ترین شرکت های جهان مشاوره کرده است. بینش او در نشریاتی مانند <em>Harvard Business Review</em>، <em>Forbes</em> و <em>Fast Company</em> به نمایش گذاشته شده است. در سال 2020، <em>Business Insider</em>کسوین را یکی از مبتکرترین مربیان جهان معرفی کرد. </p>', '2023-01-26 20:39:48.280659', '2023-01-26 20:39:48.280659', NULL, 'Erica Keswin');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (824, 'جی.جی. ساترلند', '<p>جی.جی. ساترلند یک روزنامه‌نگار برنده جایزه و بنیانگذار Scrum Inc است. او علاوه بر تألیف <em>کتاب میدانی اسکرام</em>، <em>Scrum: The Art of Doing Twice the Work in Half Time</em> را نیز در نویسندگی مشترک خود نوشت. em>، با پدرش و یکی از خالقان اسکرام، جف ساترلند.</p>', '2023-01-26 20:39:55.610737', '2023-01-26 20:39:55.610737', NULL, 'J.J. Sutherland');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (825, 'گابریل واینبرگ و جاستین مارس', '<p>گابریل واینبرگ، بنیانگذار و مدیر عامل موتور جستجوی اینترنتی DuckDuckGo است که حریم خصوصی است. جاستین مارس یک بنیانگذار استارت آپ با تخصص در سلامت موبایل و چاپ سه بعدی است. هر دوی آنها در استارت آپ هایی که به مبلغ هشت رقمی فروخته می شدند، مدیران بوده اند.</p>', '2023-01-26 20:40:03.415677', '2023-01-26 20:40:03.415677', NULL, 'Gabriel Weinberg and Justin Mares');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (826, 'اسپنسر راسکوف و استن هامفریس', '<p>اسپنسر راسکوف وب‌سایت مسافرتی تخفیف Hotwire را تأسیس کرد. پس از فروش استارت آپ خود به Expedia، او در سال 2005 به راه اندازی موتور جستجوی املاک Zillow کمک کرد. استن هامفریس اقتصاددان ارشد Zillow و مفسر مکرر روندهای مسکن برای CNBC، بلومبرگ TV و فاکس بیزینس نیوز است.</p>', '2023-01-26 20:40:05.691141', '2023-01-26 20:40:05.691141', NULL, 'Spencer Rascoff and Stan Humphries');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (827, 'تیک عکس l Shapiro', '<p>دانیل شاپیرو برنامه مذاکره بین المللی هاروارد را تأسیس کرد و دانشیار روانشناسی در دانشکده پزشکی هاروارد است. او همچنین مشاور شرکت های Fortune 500 و موسسات دولتی مختلف است و چندین طرح حل مناقشه در آسیا، اروپا و خاورمیانه ایجاد کرده است.</p>', '2023-01-26 20:40:12.839632', '2023-01-26 20:40:12.839632', NULL, 'Daniel Shapiro');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (828, 'کاترین مانیکس', '<p>کاترین مانیکس یک پزشک بریتانیایی و درمانگر رفتار شناختی است که بیش از سه دهه با بیماران لاعلاج کار کرده است. از سال 1986، او در مراقبت های تسکینی تخصص دارد. این شاخه از پزشکی به کاهش درد و رنج بیماران اختصاص دارد. او همچنین یک پزشک، مدافع و پیشگام ادغام رفتار درمانی شناختی (CBT) در مراقبت تسکینی است. او اولین کلینیک CBT در بریتانیا را که برای کمک به بیماران مراقبت های تسکینی اختصاص یافته بود، راه اندازی کرد و یک برنامه آموزشی "کمک های اولیه CBT" را برای سایر پزشکان مراقبت های تسکینی ایجاد کرد.</p>', '2023-01-26 20:40:20.278595', '2023-01-26 20:40:20.278595', NULL, 'Kathryn Mannix');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (829, 'برایان اس. کوهن و جان کادور', '<p>برایان اس. کوهن نویسنده، کارآفرین اجتماعی، استراتژیست رسانه های فناوری و رئیس نیویورک فرشتگان است، یک گروه سرمایه گذار که بیش از 50 میلیون دلار در استارت آپ های فناوری در مراحل اولیه سرمایه گذاری کرده است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (830, 'دکتر دیوید اسنور', '<p>دکتر دیوید شنارچ یک روانشناس بالینی و درمانگر جنسی مجاز است. او همچنین نویسنده کتاب های متعددی در مورد صمیمیت، تمایلات جنسی و روابط است، از جمله کتاب های پرفروش همیشگی <em>ازدواج پرشور: سکس، عشق و صمیمیت در روابط متعهد عاطفی</em> و <em>رستاخیز جنسی: حل و فصل جنسی. مشکلات و جوان سازی رابطه شما</em>.</p>', '2023-01-26 20:40:40.327362', '2023-01-26 20:40:40.327362', NULL, 'Dr. David Schnarch');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (831, 'دیوید اپستین', '<p>دیوید اپستاین نویسنده <em>Sports Illustrated</em> است که متخصص علوم ورزشی است. اپستاین همچنین دارای مدرک کارشناسی ارشد در علوم محیطی است.</p>', '2023-01-26 20:40:47.443015', '2023-01-26 20:40:47.443015', NULL, 'David Epstein');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (832, 'دارن هاردی', '<p>دارن هاردی یک گورو کارآفرین است. او ناشر مجله موفقیت است، به عنوان سخنران انگیزشی کار می کند و نویسنده <em>اثر مرکب</em>، کتاب انگیزشی درباره شکل دادن به سرنوشت خود از طریق تصمیم گیری های روزمره است.</p>', '2023-01-26 20:40:54.908533', '2023-01-26 20:40:54.908533', NULL, 'Darren Hardy');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (859, 'گری فاستر', '<p>گری فاستر روان‌شناسی در روان‌پزشکی در دانشگاه پنسیلوانیا تدریس می‌کند و همچنین مدیر ارشد علمی WW (که قبلا به عنوان Weight Watchers شناخته می‌شد) است. او نویسنده بیش از 200 مقاله و سه کتاب در مورد درمان چاقی است.</p>', '2023-01-26 20:51:00.16724', '2023-01-26 20:51:00.16724', NULL, 'Gary Foster');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (833, 'مایکل السبرگ و برایان فرانکلین', '<p>مایکل السبرگ یک کپی‌نویس آزاد و فعال برای آزادی‌های مدنی است. او چندین کتاب از جمله <em>آموزش میلیونرها: همه چیزهایی که در دانشگاه درباره چگونگی موفق بودن نمی آموزید</em>.</p> تالیف کرده است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (834, 'بلا مکی', '<p>بلا مکی نویسنده و روزنامه نگار است. او قبل از نوشتن اولین کتاب خود <em>Jog On</em>، برای روزنامه <em>گاردین </em>، <em>ووگ</em> و مجله <em>Vice </em> نوشت. </p>', '2023-01-26 20:41:09.991909', '2023-01-26 20:41:09.991909', NULL, 'Bella Mackie');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (835, 'دونالد رابرتسون', '<p>دونالد رابرتسون در اسکاتلند به دنیا آمد و به مدت دو دهه به عنوان روان درمانگر در لندن کار کرد. از سال 2011، او به اجرای سالانه هفته رواقی کمک کرده است، رویدادی بین المللی که به دانش آموزان آموزش می دهد چگونه فلسفه رواقی را با روانشناسی مدرن ترکیب کنند.</p>', '2023-01-26 20:41:16.810637', '2023-01-26 20:41:16.810637', NULL, 'Donald Robertson');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (836, 'دکتر الکساندر الدر', '<p>الکساندر الدر، M.D.، در روسیه به دنیا آمد و در استونی بزرگ شد. او در سن 16 سالگی وارد دانشکده پزشکی شد و در 23 سالگی در ایالات متحده پناهندگی سیاسی گرفت. او به عنوان یک روانپزشک در شهر نیویورک کار کرد، تجربه ای که به او بینش منحصر به فردی در مورد روانشناسی تجارت داد. امروزه او یک تاجر حرفه ای و معلم بازرگانی است. از دیگر کتاب های معاملاتی او می توان به <em>Come Into My Trading Room</em> و <em>Sell & Sell Short</em> اشاره کرد.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (837, 'رابرت بروس شاو', '<p>رابرت بروس شاو یک مشاور مدیریتی است که به مدیران ارشد کمک می کند تا عملکرد رهبری را بهبود بخشند و تغییرات استراتژیک سازمانی را مدیریت کنند. او مقالات متعددی در مورد مدیریت و همچنین کتاب دیگری به نام <em>اعتماد به تعادل</em></p> نوشته است.
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (838, 'کلی لئونارد و تام یورتون', '<p>کلی لئونارد معاون اجرایی شهر دوم است. از سال 1988، او همکاری هایی را با Lyric Opera Chicago، خط کروز نروژی و <em>The Chicago Tribune</em> در میان سازمان های دیگر تقویت کرده است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (839, 'کیت ورونز', '<p> کیت ورونز برای Gawker Media و Alpha Brand Media نوشته است. در سال 2011 دکترای خود را در رشته شیمی از دانشگاه آلاباما در بیرمنگام دریافت کرد. او همچنین نویسنده <em>Plugged In: Comic Book Professionals Working in the Video Industry است.</em></p>', '2023-01-26 20:41:50.901635', '2023-01-26 20:41:50.901635', NULL, 'Keith Veronese');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (840, 'فیلیپ کاتلر', '<p> پروفسور فیلیپ کاتلر مدیر سابق انجمن بازاریابی آمریکا است و به عنوان یکی از بنیانگذاران بازاریابی مدرن شناخته می شود. او بازاریابی بین المللی را در دانشکده مدیریت کلوگ در دانشگاه نورث وسترن<em> تدریس می کند. </em></p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (841, 'راشل کروز', '<p>ریچل کروز کارشناس امور مالی شخصی و نویسنده کتابهای پرفروش <em>نیویورک تایمز</em> <em>زندگی خود را دوست داشته باشید، نه زندگی آنها</em> و <em>پول هوشمند، کودکان باهوش</em> > او یکی از مجریان برنامه راشل کروز، یک ویلگ درباره پول موجود در یوتیوب و فیس بوک، و همچنین پادکست راشل کروز شو است.</p>', '2023-01-26 20:42:05.564316', '2023-01-26 20:42:05.564316', NULL, 'Rachel Cruze');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (842, 'جیمز برنهام', '<p>جیمز برنهام نظریه‌پرداز و فیلسوف سیاسی آمریکایی بود. در زندگی بعدی، او یک روشنفکر برجسته عمومی بود که به طور منظم در نشریاتی مانند <em>نشنال ریویو</em> همکاری می کرد.</p>', '2023-01-26 20:42:12.782866', '2023-01-26 20:42:12.782866', NULL, 'James Burnham');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (843, 'به پدرو شجاع', '<p>پدرام شجاعی کشیش صومعه اژدهای زرد در چین، استاد چیگونگ و دکترای طب شرقی است. کتاب های قبلی او عبارتند از <em>راهب شهری</em>، پرفروش ترین<em>نیویورک تایمز</em>. او همچنین میزبان پادکستی به همین نام است.</p>', '2023-01-26 20:42:20.563083', '2023-01-26 20:42:20.563083', NULL, 'Pedram Shojai');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (844, 'مارگی وارل', '<p>مارگی وارل دوره های رفتاری در ارتباطات را برای شرکت ها و موسسات ارائه می دهد. مشتریان او شامل ناسا، بنیاد سازمان ملل و AOL هستند. او همچنین به طور منظم برای رسانه هایی مانند <em>هافینگتون پست</em> و <em>Forbes</em> همکاری می کند. </p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (846, 'استفن آر. کاوی', '<p>استفن آر. کاوی یک استاد و نویسنده آمریکایی بود که کار خود را بر روی ادبیات و مذهب خودیاری متمرکز کرد. شناخته شده ترین اثر او، <em>هفت</em> <em>هفت</em> <em>عادت</em> <em>از</em> <em>بسیار موثر</em> <em> </em> <em>People</em>، بیش از 25 میلیون نسخه در سراسر جهان فروخته است. او در سال 1996 توسط مجله <em>Time</em> به عنوان یکی از "25 آمریکایی برتر با نفوذ" معرفی شد.', '2023-01-26 20:42:53.707506', '2023-01-26 20:42:53.707506', NULL, 'Stephen R. Covey');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (847, 'ناتان لاتکا', '<p>ناتان لاتکا کارآفرینی است که در 19 سالگی راه موفقیت خود را با تنها 119 دلار در حساب بانکی خود آغاز کرد. او بنیانگذار Heyo است، اپلیکیشنی که به کسب‌وکارها کمک می‌کند خدمات خود را در فیس‌بوک و شرکت محاسبات ابری SaaS بازاریابی کنند. Latka همچنین میزبان <em>Top Entrepreneurs</em> است، یک پادکست محبوب که در آن با مدیران اجرایی برجسته جهان مصاحبه می کند. <em>چگونه بدون سرمایه یک سرمایه دار باشیم</em>اولین کتاب اوست.</p>', '2023-01-26 20:47:07.295468', '2023-01-26 20:47:07.295468', NULL, 'Nathan Latka');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (848, 'ریچارد نورتون اسمیت', '<p>ریچارد نورتون اسمیت یک زندگی‌نامه‌نویس تحسین‌شده و مشارکت‌کننده مکرر در PBS و ABC News است. او به عنوان مدیر تعدادی از کتابخانه های ریاست جمهوری، از جمله کتابخانه های اختصاص داده شده به آبراهام لینکلن و دوایت آیزنهاور، خدمت کرده است.</p>', '2023-01-26 20:47:22.478184', '2023-01-26 20:47:22.478184', NULL, 'Richard Norton Smith');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (849, 'استیو بلنک', '<p> استیو بلنک موسس هشت استارت آپ و معلم در دانشگاه کالیفرنیا در برکلی، دانشگاه استنفورد و دانشگاه کلمبیا است. او چندین کتاب در زمینه کارآفرینی نوشته است.</p>', '2023-01-26 20:47:38.225265', '2023-01-26 20:47:38.225265', NULL, 'Steve Blank');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (850, 'جرمی ان. اسمیت', '<p>جرمی ان. اسمیت یک نویسنده و روزنامه نگار آزاد است. آثار او در <em> Atlantic</em>، <em>Discover</em> و<em>New York Times</em> ظاهر شده است. او همچنین نویسنده کتاب <em>در حال رشد یک باغ شهر</em> است که بینشی در مورد چگونگی ایجاد جوامع از طریق باغ ها و مزارع محلی ارائه می دهد.</p>', '2023-01-26 20:47:53.932701', '2023-01-26 20:47:53.932701', NULL, 'Jeremy N. Smith');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (851, 'جان گوردون و دیمون وست', '<p>جان گوردون سخنران انگیزشی و نویسنده ای پرکار است. او 18 کتاب نوشته است که شش تای آن ها در فهرست های <em>وال استریت ژورنال</em> و <em>واشنگتن پست پرفروش ترین کتاب ها بودند. </em>این موفقیت‌ها عبارتند از <em>اتوبوس انرژی</em>، <em>تو ابتدا در رختکن برنده می‌شوی</em> و <em>قدرت رهبری مثبت</em>. </p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (852, 'کری نیوهوف', '<p>Carey Nieuwhof یک نویسنده پرفروش، مشاور رهبری و میزبان پادکست است که محتوای آن هر ماه به 1.5 میلیون نفر می رسد. کشیش موسس سابق یکی از کلیساهای با رشد سریع در آمریکای شمالی، امروز با رهبران سراسر جهان برای کمک به موفقیت سازمان‌هایشان همکاری می‌کند.</p>', '2023-01-26 20:48:26.0293', '2023-01-26 20:48:26.0293', NULL, 'Carey Nieuwhof');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (853, 'هارولد ایوانز', '<p> هارولد ایوانز یکی از معتبرترین ویراستارانی است که امروزه کار می کند. در طول دوران کاری درخشان خود، او 14 سال را برای <em>ساندی تایمز</em> و هفت سال را به عنوان رئیس و ناشر در Random House، ایالات متحده گذراند. در سال 2004، به پاس کار برجسته اش به عنوان سردبیر روزنامه، نشان شوالیه را دریافت کرد.</p>', '2023-01-26 20:48:41.948132', '2023-01-26 20:48:41.948132', NULL, 'Harold Evans');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (854, 'گریگوری زاکرمن', '<p>گرگوری زاکرمن نویسنده ویژه <em>وال استریت ژورنال</em> است. او سه بار برنده جایزه جرالد لوب است که بالاترین افتخار در روزنامه نگاری تجاری است. او علاوه بر <em>مردی که بازار را حل کرد</em>، نویسنده <em>The Frackers</em>و <em>The Greatest Trade Ever</em> است.</p>', '2023-01-26 20:48:56.785855', '2023-01-26 20:48:56.785855', NULL, 'Gregory Zuckerman');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (855, 'ران چرنو', '<p>ران چرنو نویسنده برنده جایزه چندین کتاب پرفروش از جمله <em>خانه مورگان</em>، <em>واربورگ ها</em>، <em>واشنگتن: یک زندگی</em> است. em> و <em>الکساندر همیلتون</em>. او علاوه بر هفت مدرک دکترای افتخاری، جایزه کتاب ملی، جایزه جورج اس. اکلس و جایزه پولیتزر را دریافت کرده است.</p>', '2023-01-26 20:49:11.998656', '2023-01-26 20:49:11.998656', NULL, 'Ron Chernow');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (856, 'مایکل سوان', '<p>Mikkel Svane بنیانگذار و مدیر عامل Zendesk، یک شرکت نرم افزاری برای پشتیبانی مشتری مستقر در سانفرانسیسکو است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (857, 'بیل جورج', '<p>بیل جورج استاد مدیریت در دانشکده بازرگانی هاروارد است و در حال حاضر عضو هیئت مدیره شرکت‌های ExxonMobil، Goldman Sachs و Novartis است. او همچنین نویسنده کتاب پرفروش <em>رهبری معتبر است. </em></p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (860, 'مری بافت با شان سی', '<p>مری بافت نویسنده کتاب‌های پرفروش <em> Buffettology</em> است که به روشن کردن شیوه‌های تجاری برنده وارن بافت کمک کرده است. او همچنین یک سخنران و مشاور تجاری مورد تقاضا است. کتاب‌های او شامل <em>تائو وارن بافت</em> و <em>رازهای مدیریت وارن بافت</em> است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (861, 'یوجنیا چنگ', '<p>یوجنیا چنگ در مأموریتی است تا ترس بشریت از ریاضیات را از بین ببرد. از سال 2007، سخنرانی‌های چنگ در یوتیوب، دانشمند و دانشگاهی، بیش از یک میلیون بار مشاهده شده است. کتاب‌های دیگر چنگ عبارتند از <em>چگونه پی را بپزیم</em> و <em>Beyond Infinity</em> که در سال 2017 در فهرست نهایی قرار گرفتند. جایزه کتاب علم انجمن سلطنتی.</p>', '2023-01-26 20:51:43.009464', '2023-01-26 20:51:43.009464', NULL, 'Eugenia Cheng');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (862, 'مایکل یوسم', '<p>Michael Useem استاد دانشکده وارتون دانشگاه پنسیلوانیا و همچنین مدیر مرکز مدیریت رهبری و تغییر است. یوسم که به دلیل تخصص خود در تئوری رهبری مشهور است، همچنین نویسنده <em>چک لیست رهبر</em> و <em>نقطه حرکت: وقتی زمان تصمیم گیری است</em> است.</p>', '2023-01-26 20:51:58.75003', '2023-01-26 20:51:58.75003', NULL, 'Michael Useem');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (863, 'گایا وینس', '<p>گایا وینس یک نویسنده علمی، روزنامه‌نگار و پخش‌کننده متخصص در محیط‌زیست است. او سردبیر سابق <em>Nature</em>، یکی از مشهورترین مجلات علمی در جهان است. آثار او در روزنامه ها و مجلات از جمله <em> گاردین</em>، <em> تایمز</em>، <em>ساینتفیک آمریکایی</em> و <em>دانشمند جدید</em> ظاهر شده است. او همچنین در مورد علم برای رادیو و تلویزیون، از جمله بی بی سی می نویسد.</p>', '2023-01-26 20:52:13.985436', '2023-01-26 20:52:13.985436', NULL, 'Gaia Vince');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (864, 'لیز وایزمن', '<p>لیز وایزمن محقق، مشاور اجرایی و مدیر عامل سازمان توسعه استعداد و تحقیقات گروه وایزمن است. او همچنین نویسنده کتاب‌های پرفروش <em>نیویورک تایمز</em><em> اثر چند برابری</em> و پرفروش‌ترین کتاب <em>وال استریت ژورنال</em> <em>هوش‌های تازه کار</em><em> است. >.</em></p>', '2023-01-26 20:52:40.771176', '2023-01-26 20:52:40.771176', NULL, 'Liz Wiseman');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (865, 'چت هلمز', '<p>چت هولمز یک مشاور فروش و استاد بازاریابی بود که در طول عمر خود به بیش از شصت شرکت فورچون 500 مشاوره می داد، صاحب چهارده کسب و کار بود و میلیون ها صاحب و کارمند کسب و کار را از طریق سمینارها و مقالات خود در طول عمر خود آموزش می داد.</p>', '2023-01-26 20:52:55.966361', '2023-01-26 20:52:55.966361', NULL, 'Chet Holmes');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (866, 'کارل سافینا', '<p>کارل سافینا دارای کرسی وقفی برای طبیعت و بشریت در دانشگاه استونی بروک است و همچنین یکی از کارکنان مرکز علوم ارتباطات آلن آلدا است. او در <em>نشنال جئوگرافیک</em> و همچنین <em>نیویورک تایمز</em> مطالب منتشر کرده است و مجری یک سریال PBS است.</p>', '2023-01-26 20:53:11.099796', '2023-01-26 20:53:11.099796', NULL, 'Carl Safina');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (867, 'بتانی مکلین', '<p>بتانی مک‌لین مقاله <em>Fortune''s</em>مارس 2001 را با عنوان "آیا انرون بیش از حد گران است؟" و با انجام این کار، اولین فردی در یک نشریه ملی شد که آشکارا از آنچه در انرون گذشت سوال کرد. مک لین اکنون به عنوان ویراستار در <em>Vanity Fair</em> و ستون نویس در رویترز کار می کند.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (868, 'سالی هاگزهد', '<p>سالی هاگزهد یکی از بازاریابان و نویسندگان تبلیغاتی پیشرو در ایالات متحده است و استراتژی های بازاریابی را برای شرکت های پیشرو مانند استارباکس و مایکروسافت توسعه می دهد. هاگزهد از دانشگاه دوک فارغ التحصیل شد و زمانی که تنها 27 سال داشت آژانس تبلیغاتی خود را تأسیس کرد.</p>', '2023-01-26 20:53:42.067467', '2023-01-26 20:53:42.067467', NULL, 'Sally Hogshead');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (869, 'دیوید لوئیس و جی رایلی میلز', '<p>دیوید لوئیس یک نویسنده است. اولین کتاب او، <em>خاک اره و اسپنگل ها</em>، برنده جایزه افتخاری NAPPA در سال 2007 شد، در حالی که موزیکال او در سال 2012 برادوی <em>صد لباس</em> نامزد جایزه نمایش برجسته شد. جی. رایلی میلز یکی از بنیانگذاران شرکت Pinnacle Performance و مربی است که مهارت های ارتباطی را به مدیران عامل در سراسر جهان آموزش داده است. میلز و لوئیس همچنین نویسندگان مشترک <em>اصل رها کردن پین</em> هستند.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (870, 'داخل اولین', '<p>دارین اولین یک متخصص تغذیه مشهور، فرمول‌دهنده مکمل‌ها و مغز متفکر خط محبوب <em>Shakeology</em> از لرزش سلامت است. او بیشتر به خاطر میزبانی مشترک سریال نتفلیکس <em>Down to Earth با زک افرون</em> و همچنین برای پادکست برتر خود، <em>Darin Olien Show</em> شناخته شده است. او همچنین به عنوان یک شکارچی غذای عجیب و غریب که از جوامع بومی در سراسر جهان در جستجوی گیاهان کمتر شناخته شده با پتانسیل سوپرغذایی بازدید می کند، نامی برای خود دست و پا کرده است.</p>', '2023-01-26 20:54:12.803076', '2023-01-26 20:54:12.803076', NULL, 'Darin Olien');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1359, 'ژاکی مک نیش و شان سیلکاف', '<p>ژاکی مک‌نیش نویسنده پرفروش و خبرنگار ارشد <em>وال استریت ژورنال</em> است. شان سیلکاف، خبرنگار <em>The Globe and Mail</em>، یک نویسنده تجاری برنده جوایز است.</p>', '2023-01-27 02:45:37.416773', '2023-01-27 02:45:37.416773', NULL, 'Jacquie McNish and Sean Silcoff');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (871, 'رابرت بی میلر', '<p>رابرت بی. میلر با بسیاری از شرکت های Fortune 500 از جمله فورد و جنرال موتورز مشورت کرده و فروش داشته است. او سیستم های فروش مورد استفاده در Miller Heiman را ایجاد کرد، یک سازمان معتبر که برنامه ها و سیستم های فروش را به متخصصان ارائه می دهد. او همچنین نویسنده کتاب های پرفروشی مانند <em>فروش مفهومی</em> و <em>5 راه برای متقاعدسازی</em> است.</p>', '2023-01-26 20:54:28.18134', '2023-01-26 20:54:28.18134', NULL, 'Robert B. Miller');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (872, 'دنیل جی سیگل و تینا پین برایسون', '<p>دکتر دانیل جی. سیگل روانپزشکی را در UCLA تدریس می کند و مؤسسه Mindsight را رهبری می کند، یک سازمان آموزشی که برای آگاه کردن مردم از فرآیندهای درون ذهن ما کار می کند. او نویسنده چندین کتاب پرفروش درباره ذهن آگاهی و رشد مغز است. </p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (873, 'آن بابر', '<p>Anne Baber، Lynne Waymon، André Alphonso و Jim Wylde همکاران در Contacts Count LLC، یک شرکت آموزشی و مشاوره بین المللی هستند که به مدت 24 سال در شبکه های تجاری تخصص داشته است. بابر و ویمون 24 سال پیش این شرکت را تأسیس کردند و در میان دیگر کتاب‌های شبکه، کتاب پرفروشی را با هم نوشتند: <em>تعداد مخاطبین خود را افزایش دهید: دانش شبکه‌سازی برای موفقیت در کسب و کار و شغل</em>. مشتریان برجسته آنها عبارتند از eBay، Lockheed Martin و KPMG.</p>', '2023-01-26 20:54:59.932837', '2023-01-26 20:54:59.932837', NULL, 'Anne Baber');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (874, 'کلر سیل', '<p>کلر سیل اکانت محبوب اینستاگرام @myfrugalyear را اداره می کند که جزئیات زندگی بدهکار او را شرح می دهد. مقالات او در مورد امور مالی، بدهی، و چالش های پیش روی هزاره ها در <em>تلگراف، هافینگتون پست، گرازیا، </em>و <em>سلام منتشر شده است! مجله</em>.</p>', '2023-01-26 20:55:15.947398', '2023-01-26 20:55:15.947398', NULL, 'Clare Seal');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (875, 'گرانت ساباتیر', '<p>Grant Sabatier یک کارآفرین، نویسنده و میلیونر خودساخته است. او توصیه هایی در مورد کسب استقلال مالی به بیش از ده میلیون خواننده از طریق وب سایت خود، Millennial Money ارائه کرده است. <em>آزادی مالی</em>اولین کتاب او است.</p>', '2023-01-26 20:55:31.07429', '2023-01-26 20:55:31.07429', NULL, 'Grant Sabatier');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (876, 'بورلی ای جونز', '<p>بورلی ای. جونز مسیر شغلی پر پیچ و خم خود را از نویسنده تا رهبر برنامه های دانشگاهی برای زنان دنبال کرده است تا تبدیل به یک وکیل زن در واشنگتن شود. او از سال 2002 به عنوان مربی اجرایی و مشاور رهبری کار کرده است.</p>', '2023-01-26 20:55:46.468522', '2023-01-26 20:55:46.468522', NULL, 'Beverly E. Jones');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (877, 'ماریا شاراپووا', '<p>ماریا شاراپووا، یک فوق ستاره واقعی تنیس، پنج عنوان گرند اسلم را به دست آورده است. شاراپووا که در بلاروس به دنیا آمد، با کمک پدرش به آمریکا نقل مکان کرد و از آنجا بود که کار او به عنوان یک تنیس باز حرفه ای آغاز شد. او چندین بار در رتبه اول جهان قرار گرفته است.</p>', '2023-01-26 20:56:01.799987', '2023-01-26 20:56:01.799987', NULL, 'Maria Sharapova');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (878, 'تیم وو', '<p>تیم وو استاد دانشکده حقوق کلمبیا است. او قبلاً مشاور ارشد کمیسیون تجارت فدرال ایالات متحده، یک مشاور ارشد اجرایی در دفتر دادستان کل نیویورک و یکی از اعضای شورای اقتصاد ملی دولت اوباما بود. به عنوان یک مدافع سیاست، او بیشتر به خاطر عبارت «بی طرفی شبکه» که در مقاله تأثیرگذار خود در سال 2003 با عنوان «بی طرفی شبکه، تبعیض باند پهن» ابداع کرد، شناخته شده است. او نویسنده <em>The Master Switch</em> و <em>The Attention Merchants</em> است.</p>', '2023-01-26 20:56:17.527299', '2023-01-26 20:56:17.527299', NULL, 'Tim Wu');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (879, 'اریک مازلی و درک اروین', '<p>اریک موزلی یکی از بنیانگذاران و مدیرعامل Workhuman است، یک شرکت چند ملیتی که راه حل های نرم افزاری برای مدیریت عملکرد بر اساس شناخت اجتماعی ارائه می دهد.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (880, 'ماکس اچ بازرمن', '<p>مکس بازرمن استاد مدیریت بازرگانی در دانشکده بازرگانی هاروارد است. او نویسنده چندین کتاب تحسین شده درباره تصمیم گیری و مذاکره است، از جمله <em>نابغه مذاکره</em> و<em>نقاط کور</em>.</p>', '2023-01-26 20:57:01.368368', '2023-01-26 20:57:01.368368', NULL, 'Max H. Bazerman');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (881, 'استفانی ساکس', '<p>استفانی ساکس نویسنده، مربی، سخنران و مشاور پرفروش است. او همچنین یک متخصص تغذیه آشپزی با بیش از 25 سال تجربه، از جمله مدرک کارشناسی ارشد در رشته تغذیه از دانشگاه کلمبیا است.</p>', '2023-01-26 20:57:16.799635', '2023-01-26 20:57:16.799635', NULL, 'Stefanie Sacks');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (882, 'یان کاول', '<p>Jan Cavelle یک کارآفرین نیمه بازنشسته از انگلستان است که اکنون به عنوان سخنران و نویسنده مستقل کار می کند. او چندین کسب و کار، از جمله یک شرکت طراحی مبلمان، تاسیس کرده و برای تعدادی از نشریات تجاری نوشته است. <em>مقیاس موفقیت</em> اولین کتاب او است.</p>', '2023-01-26 20:57:54.000657', '2023-01-26 20:57:54.000657', NULL, 'Jan Cavelle');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (883, 'کال نیوپورت', '<p> کال نیوپورت استاد دانشگاه جورج تاون است که در آنجا علوم کامپیوتر تدریس می کند و مکرراً در مورد تأثیر فناوری بر زندگی روزمره ما می نویسد. کتاب های قبلی او عبارتند از <em>کار عمیق: قوانینی برای موفقیت متمرکز در دنیای پریشان</em> (2016).</p>', '2023-01-26 20:58:20.533431', '2023-01-26 20:58:20.533431', NULL, 'Cal Newport');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (884, 'دکتر مارک هایمن', '<p>مارک هیمن یک پزشک خانواده شاغل، مدیر مرکز کلینیک کلیولند برای طب عملکردی، و نویسنده یازده کتاب پرفروش <em>نیویورک تایمز</em> در مورد تغذیه است. موسس مرکز UltraWellness، یک مشاور سلامت و تندرستی شخصی، هایمن همچنین در هیئت مدیره موسسه پزشکی کاربردی خدمت می کند. او به طور منظم در برنامه های تلویزیونی مانند <em>CBS This Morning</em>، <em>Today Show</em> و <em>Dr. اوز نمایش</em>. </p>', '2023-01-26 20:58:36.274199', '2023-01-26 20:58:36.274199', NULL, 'Dr. Mark Hyman');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (885, 'برد بلانتون', '<p>دکتر برد بلانتون در زمینه گشتالت درمانی آموزش دید و سال ها روان درمانی کرد. در کنار <em>صداقت رادیکال</em>، کتاب‌های او عبارتند از <em>تمرین صداقت رادیکال</em>، <em>والدگری رادیکال</em>، و <em>حقیقت‌گویان</em>. او همچنین کارگاه هایی را در مورد صداقت رادیکال در دره Shenandoah، ویرجینیا برگزار می کند.</p>', '2023-01-26 20:58:51.403903', '2023-01-26 20:58:51.403903', NULL, 'Brad Blanton');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (886, 'لیزی پنی و الکس هرست', '<p>الکس هرست یکی از والدین شاغل و یکی از بنیانگذاران Hoxby است - یک جامعه جهانی که به ایجاد دنیایی شادتر، فراگیرتر و سازنده تر از طریق تجدید طرز فکر ما در مورد کار اختصاص دارد. شریک تجاری و هم بنیانگذار او لیزی پنی یک مادر، رهبر و استراتژیست تجاری است. در سال 2015، آن‌ها در حین برخورد با فرسودگی شغلی و چالش‌های تبدیل شدن به والدین شاغل، به مفهوم سبک کاری دست یافتند.</p>', '2023-01-26 20:59:08.507077', '2023-01-26 20:59:08.507077', NULL, 'Lizzie Penny and Alex Hirst');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (887, 'تیم جکسون', '<p>تیم جکسون استاد توسعه پایدار در دانشگاه ساری است. او بسیاری از ابتکارات تحقیقاتی و سیاستی در زمینه مصرف و تولید پایدار را رهبری کرده است که مهمترین آنها برنامه تعریف مجدد رفاه کمیسیون توسعه پایدار بریتانیا است. او همچنین یک نمایشنامه‌نویس حرفه‌ای برنده جوایز با اعتبارات زیادی است، از جمله یک درام محیطی برای رادیو بی‌بی‌سی.</p>', '2023-01-26 20:59:23.86979', '2023-01-26 20:59:23.86979', NULL, 'Tim Jackson');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (888, 'سارا باکول', '<p>سارا بیکول نویسنده ای اهل بورنموث، انگلستان است. او دوران کودکی خود را در سفر و زندگی در استرالیا با پدر و مادرش گذراند و در نهایت به بریتانیا بازگشت. در آنجا، او در دانشگاه اسکس فلسفه خواند و به عنوان فهرست نویس و متصدی کتاب های چاپ اولیه در کتابخانه Wellcome لندن برای تاریخ پزشکی کار کرد. او نویسنده چهار کتاب از جمله <em>هوشمند، دانمارکی انگلیسی</em> و<em> چگونه زندگی کنیم: زندگی مونتین است.</em></p>', '2023-01-26 20:59:50.208998', '2023-01-26 20:59:50.208998', NULL, 'Sarah Bakewell');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (889, 'بری جی. نالباف و آدام ام. براندنبرگر', '<p> بری جی. نالباف، استاد میلتون اشتاینباخ در دانشکده مدیریت ییل است. Adam M. Brandenburger استاد دانشکده بازرگانی استرن در دانشگاه نیویورک است و قبلاً استاد دانشکده بازرگانی هاروارد بود. هر دو نویسنده تحقیقات گسترده ای در مورد نظریه بازی انجام داده اند.</p>', '2023-01-26 21:00:05.648454', '2023-01-26 21:00:05.648454', NULL, 'Barry J. Nalebuff and Adam M. Brandenburger');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (890, 'کیمبرلی پالمر', '<p>کیمبرلی پالمر یک وبلاگ نویس برای <em>U.S. News & World Report</em>که تخصصش در مدیریت پول، او را به یک مهمان مورد توجه شبکه های NBC، CNBC، CNN و دیگر شبکه ها تبدیل کرده است. پالمر برای روزنامه هایی از جمله <em>واشنگتن پست</em> و <em>وال استریت ژورنال</em> مقاله نوشته است.</p>', '2023-01-26 21:00:20.968196', '2023-01-26 21:00:20.968196', NULL, 'Kimberly Palmer');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (891, 'آماندا لیتل', '<p>آماندا لیتل یک روزنامه‌نگار محیط‌زیست برنده جایزه است که نوشته‌هایش در <em>مجله نیویورک تایمز</em>، <em>Wired، </em>و <em>Vanity Fair</em> منتشر شده است، در میان بسیاری دیگر. او استاد روزنامه نگاری تحقیقی و نویسندگی علمی در دانشگاه واندربیلت و نویسنده <em>سفر قدرت: داستان عشق آمریکا با انرژی</em> است.</p>', '2023-01-26 21:00:36.270686', '2023-01-26 21:00:36.270686', NULL, 'Amanda Little');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (892, 'گابور میت', '<p>گابور ماته یک پزشک با بیست سال تجربه در پزشکی خانواده و مراقبت های تسکینی است. او خالق یک رویکرد روان درمانی است که به عنوان تحقیق دلسوزانه شناخته می شود، که برای کشف انگیزه های رفتاری ناخودآگاه بیمار استفاده می شود. کتاب او <em>در قلمرو ارواح گرسنه، </em>درباره علل اساسی اعتیاد، برنده جایزه غیرداستانی هوبرت ایوانز در سال 2009 شد.</p>', '2023-01-26 21:00:51.968934', '2023-01-26 21:00:51.968934', NULL, 'Gabor Maté');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (893, 'تام هاجکینسون', '<p>تام هاجکینسون بنیانگذار و سردبیر مجله<em> Idler </em>است. او نویسنده پرفروش <em>چگونه بیکار باشیم، چگونه آزاد باشیم، دنیای قدیمی شجاع</em> و <em>والد بیکار</em> است. او همچنین به همراه شریک زندگی خود، بنیانگذار آکادمی Idler of Philosophy, Husbandry and Merriment است که دوره های آنلاین و آفلاین را در طیف گسترده ای از موضوعات - از تجارت گرفته تا فلسفه ارائه می دهد. </p>', '2023-01-26 21:01:08.248143', '2023-01-26 21:01:08.248143', NULL, 'Tom Hodgkinson');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (894, 'دوان پترسن', '<p>دوان پترسن یک مدیر پروژه باتجربه و بنیانگذار و مدیر عامل UltiMentors است. او به طور گسترده در چین کار کرده است، جایی که اخیراً به هفت فرماندار استان و تعداد زیادی از بانکداران در اجرای رویه‌های جدید مدیریت پروژه کمک کرده است.</p>', '2023-01-26 21:01:23.511638', '2023-01-26 21:01:23.511638', NULL, 'Duane Petersen');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (895, 'ریچارد روزن', '<p>ریچارد روزن نویسنده آمریکایی و مربی یوگای مدرن است. روزن یکی از بنیانگذاران استودیو Nest Yoga در اوکلند و همچنین رئیس بنیاد یوگا دانا است.</p>', '2023-01-26 21:01:38.609522', '2023-01-26 21:01:38.609522', NULL, 'Richard Rosen');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (896, 'cha-men gt پرس', '<p>چاد منگ تان قبل از اینکه به تدریج جنبه معنوی خود را کشف کند، کار خود را به عنوان یک مهندس آغاز کرد. او به‌عنوان نویسنده‌ای پرفروش و خالق تعدادی از دوره‌های تمرکز حواس پرطرفدار، اکنون بینش‌های خود را درباره شادی با مردم در سراسر جهان به اشتراک می‌گذارد.</p>', '2023-01-26 21:01:54.357478', '2023-01-26 21:01:54.357478', NULL, 'Chade-Meng Tan');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (897, 'متیو سید', '<p>متیو سید یک روزنامه‌نگار بریتانیایی و دانش‌آموخته آکسفورد، و همچنین سه بار قهرمان مسابقات انفرادی مردان در مسابقات قهرمانی تنیس روی میز مشترک المنافع است. او همچنین نویسنده <em>Bounce</em> است.</p>', '2023-01-26 21:02:10.626229', '2023-01-26 21:02:10.626229', NULL, 'Matthew Syed');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (898, 'جان کراکائر', '<p>جان کراکائر، کوهنورد و نویسنده، مقاله ای نه هزار کلمه ای را برای مجله <em>Outside</em> در اولین کتاب خود گسترش داد: <em>Into the Wild. </em>دو سال را در فهرست پرفروش‌ترین‌های<em> نیویورک تایمز </em> گذراند و در فیلمی به کارگردانی شان پن اقتباس شد. از آن زمان کراکائر چندین کتاب پرفروش دیگر از جمله<em>به هوا</em> و <em>زیر پرچم بهشت</em> نوشته است.</p>', '2023-01-26 21:02:47.827109', '2023-01-26 21:02:47.827109', NULL, 'Jon Krakauer');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (899, 'آتش جولی ز', '<p> جولی ژو، معاون طراحی فیسبوک و دارای مدرک علوم کامپیوتر از دانشگاه استنفورد است. ژو علاوه بر کاوش در رهبری، طراحی و فناوری در وبلاگ خود <em>The Year of the Looking Glass</em>، همچنین برای نشریاتی مانند <em>نیویورک تایمز</em> و <em>Fast Company می نویسد. . </em></p>', '2023-01-26 21:03:03.167292', '2023-01-26 21:03:03.167292', NULL, 'Julie Zhuo');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (900, 'پاملا میچل', '<p>پاملا میچل یک مربی حرفه ای، سخنران عمومی و شخصیت رسانه ای است که در طول زندگی خود چندین بار حرفه خود را ابداع کرده است. او بنیانگذار و مدیر عامل موسسه Reinvention است، سازمانی که وقف کمک به حرفه ای ها برای تغییر حرفه خود است.</p>', '2023-01-26 21:03:19.271361', '2023-01-26 21:03:19.271361', NULL, 'Pamela Mitchell');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (901, 'دیوید باخ', '<p>دیوید باخ یک کارشناس مالی مشهور جهانی است که به افراد بی‌شماری کمک کرده تا وضعیت مالی خود را بهبود بخشند. او همچنین نویسنده پرکار کتاب های بسیاری است که در فهرست های پرفروش <em>نیویورک تایمز</em>، <em>وال استریت ژورنال</em>، <em>BusinessWeek</em> و <em>USA Today</em>. این کتاب‌ها عبارتند از <em>زنان باهوش ثروتمند می‌شوند</em> و <em>دیر شروع کنید، ثروتمند شوید</em>.</p>', '2023-01-26 21:03:34.912642', '2023-01-26 21:03:34.912642', NULL, 'David Bach');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (902, 'نیکو دی بروین', '<p> نیکو دی بروین پس از گرفتن مدرک در رشته تغذیه عاشق بازاریابی شد زیرا متوجه شد که قلبش دیگر در آن نیست. از آن زمان او تمام آنچه را که در مورد تکنیک های بازاریابی مدرن می دانست مطالعه می کند. ناتوان از یافتن نوع راهنمای کاملی برای بازاریابی دیجیتال که به دنبال آن بود، شروع به مصاحبه با رهبران این حوزه کرد و اولین کتاب خود را با نام <em>ما همه بازاریاب هستیم</em> نوشت. </p>', '2023-01-26 21:04:25.079051', '2023-01-26 21:04:25.079051', NULL, 'Nico De Bruyn');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (903, 'آنتونی تجان', '<p>Anthony Tjan نویسنده، کارآفرین، مشاور تجاری و مدیر عامل گروه Cue Ball است - یک شرکت سرمایه گذاری مستقر در ایالات متحده با فلسفه مردم اول و تمرکز بر سرمایه انسانی. پیش از این، Tjan یکی از نویسندگان <em>قلب، هوشمندی، جرات و شانس: آنچه برای کارآفرین بودن و ایجاد یک تجارت عالی لازم است</em> (2012) بود.</p>', '2023-01-26 21:04:52.579152', '2023-01-26 21:04:52.579152', NULL, 'Anthony Tjan');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (904, 'ایوان اوسنوس', '<p>ایوان اوسنوس یک روزنامه نگار آمریکایی است که هم به عنوان رئیس دفتر <em>Chicago Tribune</em>و هم به عنوان خبرنگار <em>New Yorker</em>چین کار کرده است. علاوه بر این، او در مجموعه ای در مورد استانداردهای ایمنی دولتی که برنده جایزه پولیتزر برای گزارش تحقیقی شد، همکاری کرد و دو جایزه باشگاه مطبوعاتی خارج از کشور را دریافت کرد. اولین کتاب او، <em>عصر جاه طلبی</em>، در سال 2014 برنده جایزه ملی کتاب غیرداستانی شد.</p>', '2023-01-26 21:05:08.331824', '2023-01-26 21:05:08.331824', NULL, 'Evan Osnos');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (905, 'برایانت تری', '<p>برایانت تری یک سرآشپز وگان برنده جایزه و نویسنده چندین کتاب آشپزی، از جمله <em>پادشاهی سبزیجات</em> در سال ۲۰۲۰ است. او همچنین یک فعال عدالت غذایی و بنیانگذار b-healthy! است، ابتکاری که جوانان را برای ایجاد یک سیستم غذایی عادلانه تر و پایدارتر توانمند می کند. </p>', '2023-01-26 21:12:13.538238', '2023-01-26 21:12:13.538238', NULL, 'Bryant Terry');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (906, 'کریستن ویلومر', '<p>کریستن ویلومیر قبل از تبدیل شدن به یک دانشجوی فوق دکتری در بخش نورولوژی در مرکز پزشکی Cedars-Sinai در لس آنجلس، در دانشگاه کالیفرنیا در رشته نوروبیولوژی تحصیل کرد. او که برنده جایزه کمک هزینه تحصیلی NIH از موسسه ملی سلامت روان است، یک متخصص مشهور بین المللی در زمینه بیماری های عصبی و آسیب های ناشی از ضربه به سر است.</p>', '2023-01-26 21:12:28.831035', '2023-01-26 21:12:28.831035', NULL, 'Kristen Willeumier');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (907, 'دیوید ریچو', '<p> دیوید ریکو یک روان درمانگر، معلم، نویسنده و رهبر کارگاه است. کار او بر تمرکز حواس و مهربانی به عنوان پایه رشد شخصی و رفاه عاطفی تاکید دارد.</p>', '2023-01-26 21:12:43.94982', '2023-01-26 21:12:43.94982', NULL, 'David Richo');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (908, 'ریچارد استرنز', '<p>ریچارد استرنز به مدت 20 سال رئیس سازمان بین المللی امداد مسیحی World Vision ایالات متحده بود. او در مورد فقر و ایدز برای روزنامه ها و مجلات مختلف ایالات متحده می نویسد و چندین کتاب نوشته است، از جمله کتاب پرفروش برنده جایزه <em>حفره در انجیل ما</em>.</p>', '2023-01-26 21:12:59.210445', '2023-01-26 21:12:59.210445', NULL, 'Richard Stearns');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (909, 'گرگ ال. ویت', '<p>Gregg L. Witt یک استراتژیست بازاریابی جوانان است. او به برندهای معروفی از جمله Procter & Gamble، Qualcomm و The Walt Disney Company کمک کرده است تا استراتژی هایی را ایجاد کنند که با ژنرال Z ارتباط برقرار کند. در سال 2016، Gregg به عنوان "برترین بازاریاب جوان برای دنبال کردن" توسط <em>Inc انتخاب شد. </em>مجله<em>. </em></p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (910, 'جون استیل', '<p>جان استیل در حال حاضر مدیر برنامه ریزی در گروه WPP و مدیر ارشد استراتژی در جورج پترسون Y&R است. او دهه‌ها را در صدر صنعت تبلیغات در سه قاره آمریکا، استرالیا و اروپا گذرانده است و با برندهای نمادینی مانند سونی، بادوایزر، هیولت پاکارد، نایک و پورشه کار کرده است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (911, 'گری فرگوسن', '<p>گری فرگوسن نویسنده، طبیعت شناس و سخنران عمومی برنده جایزه است که متخصص در تلاقی محیط زیست و روانشناسی است. او بیش از 25 کتاب از جمله <em>The Carry Home</em>، <em>Shouting at the Sky</em> و <em>Hawks Rest</em> را تالیف کرده است که اولین کتابی بود که تا به حال کتاب نام گرفت. بهترین سال توسط انجمن کتابفروشان شمال غرب اقیانوس آرام و انجمن کتابفروشان کوهستان و دشت.</p>', '2023-01-26 21:13:59.465953', '2023-01-26 21:13:59.465953', NULL, 'Gary Ferguson');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (912, 'تونی رابینز', '<p>تونی رابینز یک سخنران انگیزشی مشهور جهانی است که مشتاق بهبود زندگی دیگران است. او قبلاً به عنوان مشاور اوج عملکرد برای مدیران شرکت‌هایی مانند IBM، AT&T و تیم‌های مختلف ورزشی حرفه‌ای کار می‌کرد.</p>', '2023-01-26 21:14:15.080757', '2023-01-26 21:14:15.080757', NULL, 'Tony Robbins');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (913, 'جوسلین کی گلی', '<p>جوسلین کی. گلی سردبیر 99U است، سازمانی که اختصاص داده شده به خلاقیت‌ها در زمینه مهارت‌هایی که در مدرسه آموزش داده نمی‌شوند، اما برای تحقق ایده‌ها ضروری هستند. علاوه بر این، او انتشارات قبلی 99U را ویرایش کرده است، <em>مدیریت روز به روز خود</em>و <em>به حداکثر رساندن پتانسیل خود.</em></p>.', '2023-01-26 21:14:30.742516', '2023-01-26 21:14:30.742516', NULL, 'Jocelyn K. Glei');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (914, 'جوزف کالاوی و جوآن کالاوی', '<p>جوزف و جوآن کالاوی مشاوران املاک و مستغلات هستند که در ده سال اول کسب و کار خود توانستند به 1 میلیارد دلار فروش املاک و مستغلات برسند. آنها بیش از 5000 خانه فروخته اند و با انجمن ها و گروه های مختلف از ساحل به ساحل گفتگو می کنند.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (915, 'لئو بابوتا', '<p> بهره وری و مینیمالیسم دو موضوع اصلی هستند که لئو بابوتا در وبلاگ خود <em>zenhabits.net</em> به آنها می پردازد. بابوتا در طول زندگی حرفه ای خود به عنوان وبلاگ نویس، سیگار را ترک کرد، شروع به دویدن کرد، وزن مورد نیاز خود را از دست داد، وگان شد و تمام بدهی های خود را پرداخت کرد. مجله <em>Time</em> او را در میان 25 وبلاگ نویس برتر جهان قرار می دهد.</p>', '2023-01-26 21:15:01.047782', '2023-01-26 21:15:01.047782', NULL, 'Leo Babauta');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (916, 'کریس مک چسنی', '<p>کریس مک‌چزنی و جیم هولینگ رهبران فرانکلین کووی هستند، شرکتی که به افراد و مشاغل کمک می‌کند تا عملکرد خود را بهبود بخشند.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (917, 'سام هورن', '<p>سام هورن، که به عنوان "کارشناس دسیسه" نیز شناخته می شود، یک استراتژیست پیام رسانی و برندسازی با 20 سال تجربه کار با مشتریانی مانند اینتل، ناسا و بوئینگ است. او همچنین به هزاران کارآفرین و مدیر در تولید کتاب، سخنرانی‌های اصلی و سخنرانی‌های TEDx کمک کرده است.</p>', '2023-01-26 21:15:23.502588', '2023-01-26 21:15:23.502588', NULL, 'Sam Horn');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (918, 'جاستین', '<p>جاستین، تراویس و گریفین مک‌الروی میزبان پادکست‌های برتر نموداری مانند <em>برادرم، برادر من و من هستند. <em>استخوان اره</em>؛ <em>شمانرز; </em>و <em>منطقه ماجراجویی</em>، در میان دیگران. پادکست‌های آن‌ها همچنین الهام‌بخش یک برنامه تلویزیونی اسپین‌آف و کتاب پرفروش‌ترین کتاب و رمان‌های گرافیکی<em>نیویورک تایمز</em> هستند.</p>', '2023-01-26 21:15:34.141871', '2023-01-26 21:15:34.141871', NULL, 'Justin');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (919, 'دونالد ای. نورمن', '<p>دونالد نورمن پروفسور ممتاز علوم شناختی در دانشگاه کالیفرنیا، سن دیگو است. از دیگر کتاب‌های او می‌توان به پرفروش‌ترین <em>طراحی احساسی</em> و <em>زندگی با پیچیدگی</em> اشاره کرد.</p>', '2023-01-26 21:15:44.218817', '2023-01-26 21:15:44.218817', NULL, 'Donald A. Norman');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (920, 'جاشوا فیلدز میلبرن و رایان نیکودیموس', '<p> جاشوا فیلدز میلبورن و رایان نیکودیموس هر دو در مسیر سریع شرکت بودند و قبل از اینکه متوجه شوند زندگی در این رویای فرضی چقدر تحقق نیافتنی است، حقوق شش رقمی دریافت می کردند. بنابراین آنها تصمیم گرفتند همه چیز را در بسته بندی کنند تا زندگی ساده تر و رضایت بخشی داشته باشند. از آن زمان، آنها سفر خود و درس‌های زیادی را که در این مسیر آموخته‌اند در وب‌سایت محبوب خود به اشتراک می‌گذارند: <em>theminimalists.com</em></p>', '2023-01-26 21:15:54.506579', '2023-01-26 21:15:54.506579', NULL, 'Joshua Fields Millburn and Ryan Nicodemus');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (921, 'نیل مشروب', '<p>نیل شوبین یک دیرینه شناس است که در کلمبیا، هاروارد، و دانشگاه کالیفرنیا، برکلی آموزش دیده است. او اکنون یک استاد برجسته در دانشگاه شیکاگو و نویسنده دو کتاب دیگر است: <em>ماهی درونی شما</em> و <em>جهان درون</em>.</p>', '2023-01-26 21:16:13.445042', '2023-01-26 21:16:13.445042', NULL, 'Neil Shubin');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (933, 'توماس ال فریدمن', '<p>توماس ال. فریدمن گزارشگر، ستون نویس و برنده سه بار جایزه پولیتزر است. او در حال حاضر ستون نویس امور خارجی برای<em>نیویورک تایمز</em> است و نویسنده کتاب های دیگری مانند <em>از بیروت تا اورشلیم، لکسوس و درخت زیتون</em> و <em> است. جهان مسطح است. </em></p>', '2023-01-26 21:57:19.742726', '2023-01-26 21:57:19.742726', NULL, 'Thomas L. Friedman');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (922, 'دیوید هورساگر', '<p>David Horsager، MA، CSP، CPAE، مدیر عامل موسسه رهبری Trust Edge، Trust Expert in Residence در دانشگاه High Point، و نویسنده پرفروش The Trust Edge وال استریت ژورنال است. دیوید به رهبران مشاوره داده و سخنرانی‌های متحول کننده زندگی را در شش قاره ارائه کرده است، با مخاطبان از فدرال اکسپرس، تویوتا، MIT و دولت‌های جهانی گرفته تا نیویورک یانکیز و وزارت امنیت داخلی. Get free resources and more at <a href="https://urldefense.proofpoint.com/v2/url?u=http-3A__www.DavidHorsager.com&d=DwMGaQ&c=jGUuvAdBXp_VqQ6t0yah2g&r=07pag7Gehe-0t4YH0eMHaPco7hz5Rl9Hgu03h2HZknVLqL6RiBRjoDT-FmkEX7ys&m=sFRbQFGvRBJnmR__C_iI8jqYcRv2H04Z96jzrIH5wmk&s=mjUKsy_536WLA7KqP7tnG0-2J2INIKDSYQ04JZAOeOE&e =" rel="nofollow">www.DavidHorsager.com</a> و <a href="https://urldefense.proofpoint.com/v2/url?u=http-3A__www.TrustEdge.com&d=DwMGaQ&c=jGUuvAdBXp_VqQG6t0h =07pag7Gehe-0t4YH0eMHaPco7hz5Rl9Hgu03h2HZknVLqL6RiBRjoDT-FmkEX7ys&m=sFRbQFGvRBJnmR__C_iI8jqYcRv2H04Z96jzrIH5wmk&s=k3ps6ZoR91VmzjwTmqde6zi4CE19hI2cD6a1EvNNfOk&e=" rel="nofollow">www.TrustEdge.com</a></p>', '2023-01-26 21:16:23.533136', '2023-01-26 21:16:23.533136', NULL, 'David Horsager');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (923, 'آن لاموت', '<p>آن لاموت یک رمان‌نویس، خاطره‌نویس و معلم نویسندگی است. او هفت رمان منتشر کرده است، از جمله <em>سفر</em> <em>رحمت</em> و <em>سخت</em> <em>خنده</em>.</p>', '2023-01-26 21:16:33.796724', '2023-01-26 21:16:33.796724', NULL, 'Anne Lamott');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (924, 'جورجیا مورچ', '<p>Georgia Murch یک متخصص فرهنگ بازخورد با بیش از 20 سال تجربه است. او به سازمان‌ها در سراسر جهان کمک می‌کند فرهنگ‌های بازخورد مؤثر طراحی کنند و به طور منظم در مورد موضوعاتی مانند تیم‌های با عملکرد بالا، فرهنگ و رهبری، و ارتباطات و بازخورد صحبت می‌کند. او همچنین نویسنده پرفروش <em>رفع بازخورد</em> و <em>جریان بازخورد</em> است.</p>', '2023-01-26 21:16:44.807728', '2023-01-26 21:16:44.807728', NULL, 'Georgia Murch');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (925, 'محمد ع.الریان', '<p>محمد الاریان رئیس <em>شورای توسعه جهانی</em> پرزیدنت اوباما و مشاور ارشد اقتصادی در <em>Allianz</em>، شرکت مادر PIMCO است. او همچنین سردبیر <em>فایننشال تایمز</em>، ستون نویس <em>بلومبرگ</em> است و به عنوان معاون صندوق بین المللی پول خدمت کرده است. نوشته های او در <em>Fortune</em>،<em>وال استریت ژورنال</em>، <em>واشنگتن پست</em> و تعدادی از نشریات دیگر ظاهر شده است.</p>', '2023-01-26 21:16:56.164974', '2023-01-26 21:16:56.164974', NULL, 'Mohamed A. El-Erian');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (926, 'ایگناسیو پالاسیوس-هورتا', '<p>ایگناسیو پالاسیوس-هورتا استاد مدیریت، اقتصاد و استراتژی در دانشکده اقتصاد لندن است. علاوه بر این، او برای اتلتیک کلاب دو بیلبائو، یکی از باشگاه‌های فوتبال حرفه‌ای اسپانیا، به عنوان رئیس شناسایی استعدادها کار می‌کند.</p>', '2023-01-26 21:17:08.652842', '2023-01-26 21:17:08.652842', NULL, 'Ignacio Palacios-Huerta');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (927, 'پیتر والش', '<p>پیتر والش یک متخصص سازمان محبوب است که چندین برنامه تلویزیونی را در این زمینه میزبانی کرده است، از جمله <em>Extreme Clutter</em> و <em>Clean Sweep</em>. او همچنین مهمان دائمی <em>Rachael Ray Show</em> است. تفکر والش عمیقاً تحت تأثیر تجربه دست اول او از کوچک کردن خانه دوران کودکی خود پس از مرگ والدینش بود. او نویسنده هفت عنوان دیگر از جمله پرفروش‌ترین کتاب‌های <em>نیویورک تایمز</em> <em>همه چیز خیلی زیاد است</em>و <em>از قبل کافی است</em> است.</p>', '2023-01-26 21:17:19.409793', '2023-01-26 21:17:19.409793', NULL, 'Peter Walsh');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (928, 'روز قبر', '<p>Bola Sokunbi یک مربی معتبر آموزش مالی، کارشناس امور مالی، سخنران، پادکست و تأثیرگذار است. او همچنین بنیانگذار و مدیر عامل پلتفرم محبوب آموزش مالی <em>Clever Girl Finance</em> است که راهنمایی های مالی، دوره ها، راهنمایی و یک جامعه آنلاین را ارائه می دهد.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (929, 'جنیفر دولسکی', '<p> جنیفر دولسکی مدیر اجرایی استارت‌آپ‌های بلندپروازانه و شرکت‌های اینترنتی غول‌پیکر مانند یاهو بوده است. او قبل از نقش فعلی خود به عنوان رئیس بخش گروه و انجمن در فیس بوک، مدیر اجرایی و رئیس Change.org بود. نوشته های او در مورد روندهای مدرن در رهبری و کارآفرینی در نشریاتی مانند <em>هافینگتون پست</em> و مجله <em>فورچون</em> ارائه شده است.</p>', '2023-01-26 21:17:40.904027', '2023-01-26 21:17:40.904027', NULL, 'Jennifer Dulski');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (930, 'الیزابت استوکوی', '<p>الیزابت استوکو استاد تعامل اجتماعی در دانشگاه لافبورو است، جایی که او در تحلیل مکالمه تخصص دارد. او روش CARM (نقش-بازی تحلیلی مکالمه) را توسعه داد که از ضبط مکالمات بلادرنگ برای شناسایی مشکلات و الگوهای معمول در مکالمه استفاده می کند. به عنوان یک تحلیلگر مکالمه، او در مورد استراتژی مکالمه در زمینه هایی از مذاکره با گروگان گرفته تا دوستیابی سریع مشورت کرده است.</p>', '2023-01-26 21:56:47.335167', '2023-01-26 21:56:47.335167', NULL, 'Elizabeth Stokoe');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (931, 'واتسیایانا', '<p>واتسیایانا یک عالم دینی بود که کمتر از قرن چهارم پس از میلاد می‌زیست. او <em>کاما سوترا</em> را تا حدی از منابع حتی قدیمی‌تر گردآوری کرد. مترجم، آلن دانیلو (1907-1994)، محقق و موسیقیدان فرانسوی بود که سال‌های زیادی را در هند گذراند و کتاب‌های متعددی درباره دین، تاریخ و فلسفه هند نوشت.</p>', '2023-01-26 21:56:58.874664', '2023-01-26 21:56:58.874664', NULL, 'Vātsyāyana');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (932, 'آدام کلارک', '<p>آدام کلارک یک مشاور بهینه سازی موتور جستجو دارای گواهینامه گوگل است. او به شرکت‌های بزرگ و کوچک کمک کرده است تا وب‌سایت‌های خود را به صفحه اول نتایج جستجوی آنلاین Google ارتقا دهند و شخصاً تعدادی از رتبه‌های برتر را در دهه گذشته ثبت کرده است.</p>', '2023-01-26 21:57:09.492378', '2023-01-26 21:57:09.492378', NULL, 'Adam Clarke');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (934, 'قیصر فانگ', '<p>Kaiser Fung یک آماردان و نویسنده کتاب <em>Numbersense: How to Use Big Data to Your Advantage است.</em> او همچنین خالق دو وبلاگ محبوب <em>Junk Charts</em> است. و <em>Big Data, Plainly Speken.</em> او MBA خود را از دانشکده بازرگانی هاروارد دریافت کرد و دارای مدرک مهندسی و آمار به ترتیب از دانشگاه پرینستون و دانشگاه کمبریج است.</p>', '2023-01-26 21:57:30.117923', '2023-01-26 21:57:30.117923', NULL, 'Kaiser Fung');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (935, 'رابین A. Ferracone', '<p>رابین A. Ferracone بیش از 30 سال تجربه به عنوان مشاور جبران خسارت اجرایی دارد.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (936, 'اریک لارسون', '<p>اریک لارسون برای <em>وال استریت ژورنال</em>، <em>Time </em>و سایر نشریات نوشته است. او همچنین نویسنده چندین کتاب از جمله<em>در باغ جانوران، بیداری مرده، رعد و برق</em> و<em>طوفان ایزاک</em> است.</p>', '2023-01-26 21:57:51.803905', '2023-01-26 21:57:51.803905', NULL, 'Erik Larson');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (937, 'سارا گیلبرت و کاترین گرین', '<p> پروفسور سارا گیلبرت، استاد سعید واکسینولوژی در دانشگاه آکسفورد و یکی از بنیانگذاران Vaccitech، یک شرکت بیوتکنولوژی است که واکسن‌ها و ایمنی‌درمانی‌ها را توسعه می‌دهد. پروفسور گیلبرت متخصص در ساخت واکسن برای ویروس‌های مختلف، از جمله آنفولانزا، و واکسن Oxford-AstraZeneca COVID-19 است. این اولین کتاب او است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (938, 'فقط مخلص', '<p>جن سینرو یک مربی زندگی، سخنران انگیزشی و نویسنده چندین راهنمای پرفروش برای خودسازی است. آثار او عبارتند از <em>شما یک بدجنس هستید،</em> <em>شما هر روز یک بدجنس هستید،</em> و <em>شما در کسب درآمد بد هستید</em>.</p>', '2023-01-26 21:58:13.527797', '2023-01-26 21:58:13.527797', NULL, 'Jen Sincero');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (939, 'یونی هونگ', '<p>یونی هونگ نویسنده کتاب <em>تولد باحال کره ای</em> و روزنامه نگاری است که برای نشریاتی مانند<em>نیویورک تایمز</em>،<em>واشنگتن نوشته است. پست</em> و<em>وال استریت ژورنال</em>. او در سن 12 سالگی از حومه شیکاگو به کره جنوبی نقل مکان کرد بدون اینکه بداند چگونه کره ای صحبت کند. در عرض یک سال او در صدر کلاس خود قرار گرفت - به لطف تسلطش بر نونهال. </p>', '2023-01-26 21:58:25.752065', '2023-01-26 21:58:25.752065', NULL, 'Euny Hong');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (940, 'دیوید اسپینکس', '<p>دیوید اسپینکس CMX را تأسیس کرد، شبکه ای برای متخصصان جامعه که بیش از 20000 عضو دارد. او همچنین معاون انجمن در پلتفرم نرم افزار سازمانی Bevy است که CMX را در سال 2019 به دست آورد.</p>', '2023-01-26 21:58:37.43261', '2023-01-26 21:58:37.43261', NULL, 'David Spinks');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (941, 'جیم کالینز و بیل لازیر', '<p>بیل لازیر استاد بازرگانی در استنفورد و یک کارآفرین راهگشا بود. او همچنین مربی جیم کالینز بود، که اکنون یک مشاور پرطرفدار و نویسنده پرفروش کتاب‌های رهبری، از جمله <em>از خوب به عالی</em>و <em>ساخت تا آخر</em> است. کالینز و لزیر با هم <em>Beyond Entrepreneurship</em> را نوشتند. Lazier در سال 2005 درگذشت. کالینز اکنون این متن تجاری کلاسیک را برای کارآفرین امروزی اصلاح و به روز کرده است.</p>', '2023-01-26 21:58:48.238952', '2023-01-26 21:58:48.238952', NULL, 'Jim Collins and Bill Lazier');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (942, 'گریه جدید', '<p>Navi Radjou یک مشاور مستقل در زمینه نوآوری و رهبری مستقر در پالو آلتو، کالیفرنیا، و همچنین یکی از همکاران دانشکده بازرگانی دانشگاه کمبریج است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (943, 'پ.ک. نیوبی', '<p>P.K. نیوبی یک "آکادمیک در حال بهبود" است. او دارای مدرک دکترا از هاروارد، چند مدرک کارشناسی ارشد از کلمبیا است و در هیئت علمی دانشگاه هاروارد و بوستون خدمت کرده است. از سال 2012، او نویسنده و کارآفرینی است که بر روی بی‌حرمتی کردن علم ناخواسته و کمک به مردم برای تصمیم‌گیری بهتر در مورد آنچه می‌خورند تمرکز کرده است. کتاب‌های دیگر او عبارتند از <em>Superfoods</em> (2016) و <em>Foods for Health</em>(2014).</p>', '2023-01-26 21:59:16.896696', '2023-01-26 21:59:16.896696', NULL, 'P.K. Newby');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (944, 'نایجل واربرتون', '<p>نایجل واربرتون فیلسوف، ستون نویس و مجری پادکست بریتانیایی است. او پادکست <em>Philosophy Bites</em><em> </em> را از سال 2007 ارائه کرده است و نویسنده <em>Philosophy: The Basics</em>، در میان کتاب های دیگر است.</p>', '2023-01-26 21:59:35.107677', '2023-01-26 21:59:35.107677', NULL, 'Nigel Warburton');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (945, 'استیو گلاوسکی', '<p> استیو گلاوسکی یکی از بنیانگذاران و مدیر عامل کلکتیو پردیس، شتاب دهنده نوآوری مستقر در استرالیا و سنگاپور است. او همچنین میزبان پادکست Future Squared برنده جایزه است و نویسنده پرفروش <em>Time Rich</em> است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (946, 'دکتر آلن کریستینسون', '<p>آلن کریستینسون یک پزشک معروف و متخصص طب طبیعی است که در غدد درون ریز طبیعی تخصص دارد. او بنیانگذار سلامت یکپارچه است، یک گروه پزشکی که به حمایت از افراد مبتلا به بیماری تیروئید و چاقی برای کاهش وزن و بازیابی سلامتشان اختصاص دارد. کتاب او در سال 2014 <em>رژیم غذایی تنظیم مجدد آدرنال</em><strong><em> </em></strong>به پرفروش ترین کتاب <em>نیویورک تایمز</em> تبدیل شد. او همچنین در رسانه های چاپی و برنامه های تلویزیونی متعددی مانند <em>Dr. اوز نمایش</em>.</p>', '2023-01-26 21:59:55.490448', '2023-01-26 21:59:55.490448', NULL, 'Dr. Alan Christianson');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (947, 'بیل مک گوان و آلیسا بومن', '<p>بیل مک گوان مدیر عامل شرکت Clarity Media Group و خبرنگار برنده جایزه امی است. او صدها مصاحبه به‌عنوان یک روزنامه‌نگار انجام داده است و در مهارت‌های ارتباطی افراد مشهوری مانند الی منینگ، مدافع نیویورک جاینتز و مدیران اجرایی مانند شریل سندبرگ را مربیگری کرده است. آلیسا بومن روزنامه نگار، وبلاگ نویس، همکار کتاب، و نویسنده و نویسنده چندین کتاب، از جمله <em>پروژه:</em> <em>خوشبختانه</em> <em>همیشه</em> <em> است. بعد از</em>.</p>', '2023-01-26 22:00:06.227775', '2023-01-26 22:00:06.227775', NULL, 'Bill McGowan and Alisa Bowman');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (948, 'دیوید لوئیس', '<p>دکتر دیوید لوئیس، "پدر بازاریابی عصبی"، پیشروترین روانشناسی است که یافته های علوم اعصاب را در مغز خریدار به کار می برد. او به‌عنوان یکی از بنیان‌گذاران و مدیر تحقیقات Mindlab International، با شرکت‌های Fortune 500 کار کرده و چندین کتاب پرفروش، از جمله <em>روح مصرف‌کننده جدید: اصالت - آنچه می‌خریم و چرا در اقتصاد جدید</em> نوشته است. >.</p>', '2023-01-26 22:00:16.594204', '2023-01-26 22:00:16.594204', NULL, 'David Lewis');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (949, 'ارین رودز', '<p>Erin Rhoads شناخته شده ترین وبلاگ نویس استرالیایی است. از سال 2013، او سبک زندگی بدون زباله خود را در وبلاگ <em>Rogue Ginger</em> ثبت کرده است و در حال حاضر به عنوان مشاور کاهش زباله کار می کند. رودز به طور منظم در رادیو ABC، سرویس جهانی بی‌بی‌سی و <em>گاردین</em> مشارکت داشته است.</p>', '2023-01-26 22:00:26.849873', '2023-01-26 22:00:26.849873', NULL, 'Erin Rhoads');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (950, 'راجر فیشر', '<p>راجر فیشر (۱۹۲۲–۲۰۱۲) استاد آمریکایی در دانشکده حقوق هاروارد بود. او با همکارانش <em>پروژه مذاکره هاروارد</em> را تأسیس کرد.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (951, 'مارتا بک', '<p>مارتا بک نویسنده، مربی زندگی، و سخنران پرفروشی است که تخصصش کمک به افراد برای دستیابی به موفقیت شخصی و حرفه ای است. او کتاب های متعددی نوشته است و به طور منظم با مجله <em>O </em> همکاری می کند. او دارای دکترای جامعه شناسی از هاروارد است. </p>', '2023-01-26 22:00:47.251776', '2023-01-26 22:00:47.251776', NULL, 'Martha Beck');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (952, 'کاتلین فلین', '<p>کاتلین فلین نویسنده پرفروش کتاب خاطرات <em>چاقوی تیزتر، کمتر گریه می کنی</em> است که به جزئیات تجربیات او به عنوان یک سرآشپز مشتاق در مدرسه آشپزی Le Cordon Bleu و <em> می پردازد. نان تست سوخته باعث می شود خوب بخوانی – </em>خاطرات بین نسلی درباره اهمیت غذا در خانواده اش. او همچنین در نشریاتی مانند <em>Smithsonian، USA Weekend</em>، و <em>Globe and Mail مشارکت دارد. وقتی در مورد غذا نمی نویسد، به دیگران می آموزد که آن را در محبوبیت خود ایجاد کنند. کارگاه های آشپزی.</p>', '2023-01-26 22:01:06.062195', '2023-01-26 22:01:06.062195', NULL, 'Kathleen Flinn');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (953, 'جودی کولبرتسون', '<p>جودی کولبرتسون در سازمان‌دهی متخصص است - به‌قدری که سمینارهایی را در مورد چگونگی بی‌معنا کردن زندگی یک نفر هدایت می‌کند. او همچنین نویسنده <em>نور سفر</em> است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (954, 'تیلور پیرسون', '<p>تیلور پیرسون، یک کارآفرین، بازاریاب و مشاور، به نویسندگان، کارآفرینان و مدیران عامل در مورد نحوه گسترش، شفاف سازی و بازاریابی کسب و کار خود توصیه می کند.</p>', '2023-01-26 22:01:26.762586', '2023-01-26 22:01:26.762586', NULL, 'Taylor Pearson');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (955, 'لورا استک', '<p>برای چندین دهه، لورا استک به سازمان‌ها کمک کرده است تا نتایج قابل توجهی کسب کنند. او رئیس و مدیر عامل شرکت Production Pro, Inc.، عضو تالار مشاهیر سخنران CPAE و نویسنده پرفروش است. از دیگر کتاب‌های او می‌توان به <em>Execution is the Strategy</em>و <em>The Exhaustion Cure</em> اشاره کرد.</p>', '2023-01-26 22:01:45.710585', '2023-01-26 22:01:45.710585', NULL, 'Laura Stack');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (956, 'گرانت آچاتز و نیک کوکوناس', '<p>گرنت آچاتز جوایز متعددی را برای آشپزی خود دریافت کرده است، از جمله لقب بهترین سرآشپز آمریکایی و داشتن بهترین رستوران آمریکایی. او صاحب سه رستوران شیکاگو است: Alinea، Next و The Aviary.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (957, 'جورج آکرلوف و رابرت جی شیلر', '<p> جورج آکرلوف، برنده جایزه نوبل، اقتصاددان و استاد دانشگاه جورج تاون است. او در سال 2001 جایزه نوبل اقتصاد را دریافت کرد.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (958, 'وال رایت', '<p>وال رایت یک متخصص نوآوری و رهبری شناخته شده بین المللی است. او با بسیاری از شرکت‌های Fortune 500 به عنوان شتاب‌دهنده رشد کار کرده است، از جمله مایکروسافت، <em>Financial Times</em>، آمازون، و LA Lakers. او همچنین نویسنده <em>Thoughtfully Ruthless</em> (2016) است که توسط جوایز بزرگ کتاب نیویورک و جوایز مطبوعات مستقل به عنوان بهترین کتاب تجاری انتخاب شد.</p>', '2023-01-26 22:02:26.273101', '2023-01-26 22:02:26.273101', NULL, 'Val Wright');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (959, 'دانا پرینو', '<p>دانا پرینو به عنوان دبیر مطبوعاتی دولت جورج دبلیو بوش خدمت کرد. او در حال حاضر یکی از اعضای پنل در برنامه تلویزیونی فاکس نیوز، <em>The Five</em> است.</p>', '2023-01-26 22:02:36.527566', '2023-01-26 22:02:36.527566', NULL, 'Dana Perino');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (960, 'کیت مور', '<p> کیت مور یک نویسنده پرفروش است که آثارش به بیش از 12 زبان ترجمه شده است. از دیگر کتاب‌های او می‌توان به <em>فلیکس گربه راه‌آهن</em> اشاره کرد که در فهرست <em>ساندی تایمز</em>پرفروش‌ترین‌ها به رتبه سوم رسید.</p>', '2023-01-26 22:02:46.782112', '2023-01-26 22:02:46.782112', NULL, 'Kate Moore');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (961, 'برای او لاندو', '<p>ایدو لاندو، استاد فلسفه در دانشگاه حیفا، اسرائیل است. او در مورد معنای زندگی مطالب زیادی منتشر کرده است.</p>', '2023-01-26 22:02:58.555848', '2023-01-26 22:02:58.555848', NULL, 'Iddo Landau');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (962, 'رومن کرزناریچ', '<p>رومن کرزناریچ، فیلسوف و نویسنده اجتماعی است. او به همراه آلن دو باتون بنیانگذار مدرسه زندگی در لندن است. او جامعه شناسی و سیاست را در دانشگاه کمبریج و دانشگاه سیتی لندن تدریس کرده است.</p>', '2023-01-26 22:03:08.627093', '2023-01-26 22:03:08.627093', NULL, 'Roman Krznaric');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (963, 'لئونارد ملودینو', '<p>لئونارد ملودینو دارای دکترای فیزیک از دانشگاه کالیفرنیا در برکلی است و نویسنده بسیاری از کتابهای علمی موفق مانند <em>A</em> <em>Briefer</em> <em>تاریخ< /em> <em>از</em> <em>زمان</em> و <em>فاینمن</em> <em>رنگین کمان:</em> <em>A</em> <em>جستجو< /em> <em>برای</em> <em>زیبایی</em> <em>در</em> <em>فیزیک</em> <em>و</em> <em>در</em> > <em>زندگی</em>. او همچنین برای مجموعه های تلویزیونی <em>MacGyver</em> و <em>Star</em> <em>Trek:</em> <em>The</em> <em>Next</em> نوشته است. <em>نسل</em>.</p>', '2023-01-26 22:03:19.228761', '2023-01-26 22:03:19.228761', NULL, 'Leonard Mlodinow');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (964, 'نیکلاس وایمن', '<p> نیکلاس وایمن فارغ التحصیل مدرسه بازرگانی هاروارد است که نقاط قوت واقعی خود را در کارآموزی خدمات آشپزخانه کشف کرد. او به‌عنوان مدیر عامل مؤسسه مهارت‌ها و نوآوری در محل کار، به هزاران نفر در یافتن نقاط قوت و شغل مناسب کمک می‌کند.</p>', '2023-01-26 22:03:29.542831', '2023-01-26 22:03:29.542831', NULL, 'Nicholas Wyman');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (965, 'جورج مامفورد', '<p>جرج مامفورد مشاور روانشناسی ورزشی تیم بسکتبال مردان کالج بوستون و مربی مدیتیشن در لس آنجلس لیکرز است. او که یک سخنران عمومی است، تکنیک های معروف خود را با تعدادی از تیم های NBA به اشتراک گذاشته و در ورزش های دیگر نیز مربی ورزشکاران بوده است.</p>', '2023-01-26 22:03:43.20776', '2023-01-26 22:03:43.20776', NULL, 'George Mumford');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (966, 'کوری کوجون', '<p>کوری کوگون یک تاجر و نویسنده است. او در حال حاضر معاون رئیس‌جمهور در FranklinCovey است، و همچنین رهبر عملکرد جهانی این شرکت برای بهره‌وری است. دیگر عناوین او شامل <em>Presentation Advantage</em>و <em>The 5 Choices</em></p> است.
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (967, 'چارلی پاونال', '<p>چارلی پاونال یک مربی روابط عمومی است که در رسانه های اجتماعی تخصص دارد. او در مورد نحوه مدیریت این کانال های عمومی و جلوگیری از آسیب رساندن به شهرت، توصیه های تخصصی به سازمان های دولتی و شرکتی ارائه می دهد. او همچنین در <em>Public Affairs Asia</em>، <em>Social Media Today</em> و <em>Public Affairs</em></p> مشارکت دارد.
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (968, 'کارل ریدر', '<p> کارل ریدر یک کارآفرین و سخنران انگیزشی است که در طول حرفه خود کسب و کارهای بی شماری را تأسیس کرده و روی آنها سرمایه گذاری کرده است. او رئیس d&t، یک شرکت مشاوره کسب و کار است و در <em>City AM</em> 100 کارآفرین برتر سال 2016 فهرست شده است.</p>', '2023-01-26 22:04:25.710251', '2023-01-26 22:04:25.710251', NULL, 'Carl Reader');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (969, 'دکتر دیوید لودویگ', '<p>دکتر دیوید لودویگ، متخصص غدد، محقق در بیمارستان کودکان بوستون و استاد تغذیه در دانشگاه هاروارد T.H. دانشکده بهداشت عمومی چان.</p>', '2023-01-26 22:04:36.34058', '2023-01-26 22:04:36.34058', NULL, 'Dr. David Ludwig');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (970, 'دیل کارنگی', '<p>دیل کارنگی نویسنده اصلی خودیاری است. کتاب پرفروش او در سال 1936 <em>چگونه دوستان به دست آوریم و بر مردم تأثیر بگذاریم</em> هنوز هم عنوانی محبوب است و 15 میلیون نسخه فروخته است. او <em>چگونه نگرانی را متوقف کنیم و زندگی را شروع کنیم</em> نوشت زیرا احساس می کرد به دلیل نگرانی بیش از حد "یکی از ناخوشایندترین پسران نیویورک" است و می خواست بداند چگونه باید متوقف شود.</p>', '2023-01-26 22:04:47.064017', '2023-01-26 22:04:47.064017', NULL, 'Dale Carnegie ');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (993, 'استوارت فریموند', '<p>دکتر استوارت فریموند نویسنده، مجری و مربی علم و پزشکی است. او نویسنده کتاب های پرفروش <em>علم آشپزی</em> و <em>علم ادویه</em> است. از سال 2017 او دانشمند غذا برای برنامه بی بی سی <em>در داخل کارخانه</em> است.</p>', '2023-01-27 01:26:56.987409', '2023-01-27 01:26:56.987409', NULL, 'Stuart Farrimond');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (971, 'فیل استوتز و بری میشلز', '<p>فیل استوتز یک روانپزشک و مربی مورد تقاضا است که مدرک دکترای خود را از دانشگاه نیویورک دریافت کرده است. در سال 2022، روش های درمانی پیشگام او موضوع مستند <em>Stutz بازیگر جونا هیل بود. </em></p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (972, 'دیوید رابرتسون در کنار بیل برین', '<p>دیوید سی رابرتسون مشاور سابق <em>مک کینزی و شرکت</em> است که در حال حاضر در مدرسه وارتون دانشگاه پنسیلوانیا تدریس می‌کند.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (973, 'بکی کندی', '<p>دکتر بکی کندی یک روانشناس بالینی، مادر سه فرزند و بنیانگذار Good Inside است، یک پلتفرم عضویت که به والدین آموزش و مهارت‌هایی را می‌دهد که برای بهبود خانواده‌شان و حرکت رو به جلوی قدرتمند و سرشار از عشق به خود و فرزندانشان نیاز دارند. همراه با کتاب <em>در درون خوب</em>، دکتر بکی کارگاه‌های آموزشی ارائه می‌دهد، پادکست اجرا می‌کند، و از حساب‌های پررونق خود در رسانه‌های اجتماعی استفاده می‌کند تا تکنیک‌های فرزندپروری خود را تا حد امکان در دسترس افراد قرار دهد.</p>', '2023-01-26 22:05:27.197159', '2023-01-26 22:05:27.197159', NULL, 'Becky Kennedy');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (974, 'کامرون هانس', '<p>کامرون هانس یک شکارچی کمان، دونده اولتراماراتن و مرد خانواده است. وقتی او در بیابان دور افتاده شمال غرب آمریکا و آلاسکا حرکت نمی کند، در مورد اشتیاق خود به شکار کمان می نویسد. او دو کتاب منتشر کرده است: <em>Bowhunting Trophy Blacktail</em> و <em>Back-Country Bowhunting</em>.</p>', '2023-01-26 22:05:37.639612', '2023-01-26 22:05:37.639612', NULL, 'Cameron Hanes');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (975, 'ریچارد پرستون', '<p>ریچارد پرستون نویسنده ای برنده جایزه است که در دانشگاه آیووا و دانشگاه پرینستون نویسندگی غیرداستانی تدریس کرده است. کتاب های قبلی او عبارتند از <em>منطقه داغ</em> (1994)، <em>درختان وحشی</em> (2007) و <em>دیو در فریزر </em>(2007). p>', '2023-01-26 22:05:48.378243', '2023-01-26 22:05:48.378243', NULL, 'Richard Preston');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (976, 'مارک کوبان', '<p>مارک کوبان اولین شرکت خود را با نام <em>MicroSolutions</em> تأسیس کرد، در حالی که در یک آپارتمان سه خوابه با شش نفر زندگی می کرد. او از آن زمان تا کنون راه خود را در دنیای تجارت پیش برده است تا مالک امتیاز NBA دالاس ماوریکس و یکی از ثروتمندترین کارآفرینان تاریخ شود.</p>', '2023-01-26 22:05:59.031807', '2023-01-26 22:05:59.031807', NULL, 'Mark Cuban');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (977, 'توسط جاشوا براون و برایان پورتنوی ویرایش شده است', '<p>جاش براون یکی از بنیانگذاران و مدیر عامل Ritholtz Wealth Management است، یک شرکت خدمات مالی که بیش از 1 میلیارد دلار دارایی را برای طیف وسیعی از مشتریان فردی، شرکتی و سازمانی مدیریت می کند. او نویسنده <em>Backstage Wall Street</em> و <em>Clash of the Financial Pundits</em> است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (978, 'جودیت والنته', '<p>جودیت والنته یک روزنامه‌نگار، مقاله‌نویس و شاعر برنده جایزه است که یکی از نویسندگان کارکنان نشریاتی از جمله <em>وال استریت ژورنال</em> و <em> واشنگتن پست</em> بوده است. او همچنین در تلویزیون و رادیو کار کرده است و به سخنرانی پرداخته است و به قدرت شعر و زندگی کاری معنادارتر منجر شده است. از دیگر کتاب‌های او می‌توان به <em>هنر مکث: مراقبه‌هایی برای افراد پرکار و غرق‌شده</em> اشاره کرد.</p>', '2023-01-26 22:06:37.407852', '2023-01-26 22:06:37.407852', NULL, 'Judith Valente');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (979, 'کال رائوستیالا و کریستوفر اسپریگمن', '<p>Kal Raustiala استاد حقوق در UCLA و همچنین نویسنده <em>آیا قانون اساسی از پرچم پیروی می کند؟</em> تحقیقات او عمدتاً بر حقوق بین الملل، روابط بین الملل و مالکیت معنوی متمرکز است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (980, 'جان آدایر', '<p>جان آدیر یک دانشگاهی از بریتانیا است. قبل از ورود به دانشگاه، او در بسیاری از زمینه ها از جمله در یک سالن جراحی بیمارستان و در یک کشتی ترال قطب شمال کار کرد. او بیش از 50 کتاب تألیف کرده است که تعدادی از آنها به بیش از 30 زبان ترجمه شده است.</p>', '2023-01-26 22:06:59.485415', '2023-01-26 22:06:59.485415', NULL, 'John Adair');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (981, 'جولی هالند', '<p>دکتر جولی هالند یک روانپزشک آمریکایی و نویسنده <em>آخر هفته ها در Bellevue</em>، خاطرات پرفروش<em> است. </em>او مهمان دائمی <em>امروز</em> <em>نمایش</em> و CNN است.</p>', '2023-01-26 22:07:09.920826', '2023-01-26 22:07:09.920826', NULL, 'Julie Holland');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (994, 'مایکل تاد', '<p>مایکل تاد نویسنده پرفروش <em>نیویورک تایمز</em> <em>اهداف رابطه</em> است. او همچنین از سال 2015 کشیش اصلی کلیسای تبدیل در تولسا، اوکلاهاما بوده است.</p>', '2023-01-27 01:27:15.53142', '2023-01-27 01:27:15.53142', NULL, 'Michael Todd');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1008, 'بل بوگز', '<p>داستان‌ها و مقالات بل بوگز در <em>Harper''s</em>، <em>Paris Review،</em> <em>Orion، Slate</em> و بسیاری از نشریات دیگر ظاهر شده‌اند. او استاد برنامه MFA دانشگاه ایالتی کارولینای شمالی و نویسنده <em>Mattaponi Queen</em> است.</p>', '2023-01-27 01:44:33.433963', '2023-01-27 01:44:33.433963', NULL, 'Belle Boggs');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (982, 'تئو اسمیت و آماندا کربی', '<p>تئو اسمیت یک رهبر جذب استعداد و یکی از اعضای منابع 100 رهبران است. او استراتژی استخدام را در NICE، مؤسسه ملی تعالی بهداشت و مراقبت رهبری کرد. </p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (983, 'زک فریدمن', '<p>زک فریدمن موسس و مدیر عامل شرکت مالی شخصی آنلاین Make Lemonade است. او همچنین یک سخنران عمومی مورد توجه است و میلیون ها خواننده را از طریق مشارکت های خود در نشریاتی مانند مجله فوربس الهام بخش کرده است. فریدمن دارای مدرک تحصیلی از هاروارد، کلمبیا، وارتون و جانز هاپکینز است.</p>', '2023-01-27 00:52:22.128041', '2023-01-27 00:52:22.128041', NULL, 'Zack Friedman');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (984, 'اریک ریس', '<p>اریک ریس یک کارآفرین موفق است. او یکی از بنیانگذاران شبکه اجتماعی IMVU است که از آواتارهای سه بعدی استفاده می کند. امروز او یک مشاور و سخنران عمومی است.</p>', '2023-01-27 00:52:42.754437', '2023-01-27 00:52:42.754437', NULL, 'Eric Ries');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (985, 'Bohdanna Zazulak', '<p> Bohdanna Zazulak دکتر فیزیوتراپی، محقق و عضو هیئت علمی در بیمارستان Yale New Haven و دانشکده پزشکی دانشگاه Yale است. او اولین کسی بود که تحقیقاتی را منتشر کرد که ثبات مرکزی را به کاهش میزان آسیب مرتبط می‌کرد و به همین دلیل جایزه رز انجمن فیزیوتراپی آمریکا را دریافت کرد. تحقیقات پیشگام او در مجلات و کتاب های درسی معتبر پزشکی ظاهر شده است و از طرف زنان در پزشکی به عنوان "دکتر برتر" معرفی شده است. </p>', '2023-01-27 00:53:09.433546', '2023-01-27 00:53:09.433546', NULL, 'Bohdanna Zazulak');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (986, 'استفن ام آر کاوی با ربکا آر مریل', '<p>استفن ام آر کاوی یک سخنران، نویسنده و مشاور الهام بخش در مورد اعتماد است. او پسر استفن آر. کاوی فقید است، مغزهای پشت سر فیلم پرفروش <em>7 عادت افراد بسیار مؤثر</em>. او بنیانگذار و مدیر عامل CoveyLink Worldwide است، شرکتی که هدف آن تأثیرگذاری بر رهبران از طریق آموزش اعتماد به آنها است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (987, 'کارول کرشاو و بیل وید', '<p>کارول کرشاو یک روانشناس بالینی است که در هیپنوتیزم بالینی تخصص دارد. او به همراه همسرش بیل وید ریاست موسسه میلتون اریکسون هیوستون را بر عهده دارد. تلاش می کند روان درمانی را برای افراد، خانواده ها و زوج های جامعه ارائه دهد. کرشاو نویسنده <em>رقص هیپنوتیزم زوج</em> و نویسنده همکار <em>درمان تغییر مغز: مداخلات بالینی برای تغییر خود است.</em></p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (988, 'اسکات جفری میلر', '<p> اسکات جفری میلر معاون اجرایی رهبری فکری در FranklinCovey است، شرکتی که مدل سازی کسب و کار را برای تقویت موفقیت توسعه می دهد. جفری میلر، یک متخصص رهبری، میزبان <em>زندگی عالی، شغل عالی با اسکات میلر</em>، یک برنامه رادیویی هفتگی، و همچنین پادکست هفتگی <em>درباره رهبری با اسکات میلر است.</em></p. >
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (989, 'شارون معلم', '<p> شارون معلم MD، دکترا، دانشمند، پزشک و نویسنده ای است که متخصص در نشان دادن نحوه کار تکامل، ژنتیک، زیست شناسی و پزشکی به جهان است. کتاب های او، از جمله <em>Survival of the Sickest</em> و <em>Sex چگونه کار می کند</em>، به بیش از 20 زبان ترجمه شده است.</p>', '2023-01-27 01:24:56.002736', '2023-01-27 01:24:56.002736', NULL, 'Sharon Moalem');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (990, 'دیوید گوگینز', '<p>دیوید گوگینز یک دونده اولترا ماراتن و رکورددار سابق جهانی برای بیشترین تعداد کشش انجام شده در 24 ساعت است. گوگینز همچنین یک نیروی دریایی سابق ایالات متحده SEAL است که در هر دو جنگ افغانستان و عراق نقش فعالی داشته است.</p>', '2023-01-27 01:25:17.883085', '2023-01-27 01:25:17.883085', NULL, 'David Goggins');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (991, 'لیگ بین المللی لا لچه', '<p>دایان ویسینگر، دایانا وست و ترزا پیتمن مادران و رهبران سازمان بین‌المللی لا لچه لیگ هستند. لیگ La Leche که در سال 1956 تأسیس شد، برای کمک به عادی سازی شیردهی و ارائه حمایت از مادران در سراسر جهان تشکیل شد.</p>', '2023-01-27 01:25:39.44739', '2023-01-27 01:25:39.44739', NULL, 'La Leche League International');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (992, 'مایکل ای. گربر', '<p>Michael E. Gerber یک افسانه کارآفرین است. او یکی از بنیانگذاران و رئیس شرکت های Michael E. Gerber است، سازمانی که به کسب و کارها و کارآفرینان کمک می کند بدون توجه به صنعت موفق شوند. او بیش از دوازده کتاب در زمینه کارآفرینی نوشته است.</p>', '2023-01-27 01:26:03.04292', '2023-01-27 01:26:03.04292', NULL, 'Michael E. Gerber');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (995, 'آرتور سی بروکس', '<p>آرتور سی بروکس، دانشمند علوم اجتماعی، استاد دانشگاه هاروارد، و ستون نویس <em> آتلانتیک است. </em>بیش از یک دهه، او به عنوان رئیس موسسه امریکن اینترپرایز خدمت کرد. عناوین گذشته او عبارتند از <em>دشمنان خود را دوست داشته باشید، قلب محافظه کار، راه آزادی، خوشبختی ملی، </em>و <em>چه کسی واقعاً اهمیت می دهد؟</em></p>', '2023-01-27 01:42:38.597055', '2023-01-27 01:42:38.597055', NULL, 'Arthur C. Brooks');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (996, 'لسلی هزلتون', '<p>لسلی هزلتون یک متخصص مشهور خاورمیانه است. کتاب های دیگر او عبارتند از <em>پس از پیامبر</em> که به عنوان فینالیست جایزه غیرداستانی PEN در سال 2010 انتخاب شد.</p>', '2023-01-27 01:42:51.218364', '2023-01-27 01:42:51.218364', NULL, 'Lesley Hazleton');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (997, 'جورج اس. کلاسون', '<p>جرج اس. کلاسون یک تاجر و نویسنده برجسته آمریکایی بود. او بیشتر به خاطر نوشتن مجموعه‌ای از جزوه‌ها درباره موفقیت‌های مالی در بابل باستان شناخته می‌شود و بهترین این جزوه‌ها بعداً در <em>ثروتمندترین مرد بابل</em></p> جمع‌آوری شد.', '2023-01-27 01:42:58.519354', '2023-01-27 01:42:58.519354', NULL, 'George S. Clason');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (998, 'توماس جی اندرسون', '<p>توماس جی اندرسون یک بانکدار سرمایه گذاری و بنیانگذار پلتفرم های فناوری مالی Supernova Technology و Anasova است. او همچنین نویسنده پرفروش‌ترین کتاب‌های مشاوره مالی <em>نیویورک تایمز</em> مانند <em>پول بدون مرز</em>، <em>ارزش بدهی،</em> و <em> است. ارزش بدهی در بازنشستگی</em>.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (999, 'موسیقی پل چوداری', '<p>سنگیت پل چودری مدیر عامل پلتفرم استراتژی لبز است. او برای چندین نشریه برجسته مانند TechCrunch، Forbes، <em>Wall Street Journal</em> و <em>Wired</em> نوشته است.</p>', '2023-01-27 01:43:12.812994', '2023-01-27 01:43:12.812994', NULL, 'Sangeet Paul Choudary');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1000, 'ماکس لوگاور', '<p>Max Lugavere یک روزنامه نگار، شخصیت تلویزیونی و فیلمساز است که مسائل مربوط به سلامت و علم را پوشش می دهد. او <em>Bread Head</em> را کارگردانی کرد - مستندی با تمرکز بر این که چگونه انتخاب سبک زندگی می تواند از زوال عقل جلوگیری کند. لوگاور مهمان مکرر <em>نمایش دکتر اوز</em> است و در موسسات معتبر از جمله آکادمی علوم نیویورک و پزشکی ویل کورنل و همچنین نشست Biohacker در سوئد در سراسر جهان سخنرانی کرده است. /p>', '2023-01-27 01:43:25.05655', '2023-01-27 01:43:25.05655', NULL, 'Max Lugavere');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1001, 'رید هافمن و بن کاسنوچا', '<p>رید هافمن یک کارآفرین، سرمایه‌دار و نویسنده آمریکایی است. او یا در تعدادی از شرکت‌های مطرح، از جمله PayPal، Zynga و فیس‌بوک سرمایه‌گذاری کرده یا برای آن کار کرده است، اما شاید بیشتر به خاطر یکی از بنیان‌گذاران و رئیس لینکدین شناخته شده است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1002, 'مایک واینبرگ', '<p>مایک واینبرگ متخصص توسعه کسب و کار جدید و مدیریت فروش است. او نه تنها یک نویسنده پرفروش، بلکه یک مشاور، مربی و سخنران است. او که توسط <em>Forbes</em> و OpenView Labs به‌عنوان تأثیرگذار فروش برتر نام‌گذاری شد، قبل از راه‌اندازی دفتر مشاوره‌اش، تولیدکننده برتر سه شرکت مختلف بود.</p>', '2023-01-27 01:43:45.077238', '2023-01-27 01:43:45.077238', NULL, 'Mike Weinberg');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1003, 'تیفانی بووا', '<p>تیفانی بووا یک مشاور رشد متخصص در رشد مشتری و نوآوری جهانی در Salesforce است. او میزبان <em>What''s Next!</em> است، پادکستی که بستری برای گفتگو با رهبران کسب و کار در مورد روندهای نوظهور، نوآوری و آخرین استراتژی های رشد فراهم می کند. <em>IQ رشد</em>اولین کتاب او است.</p>', '2023-01-27 01:43:51.996591', '2023-01-27 01:43:51.996591', NULL, 'Tiffani Bova');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1004, 'دیو رمزی', '<p> دیو رمزی نویسنده، مجری رادیویی، شخصیت تلویزیونی و سخنران انگیزشی آمریکایی است که بر امور مالی و آزادی بدهی تمرکز دارد. او بیشتر برای نمایش رادیویی‌اش، <em>نمایش دیو رمزی</em> شناخته می‌شود، که در آن به تماس‌گیرندگان از سراسر ایالات متحده مشاوره مالی ارائه می‌کند.</p>', '2023-01-27 01:43:58.672162', '2023-01-27 01:43:58.672162', NULL, 'Dave Ramsey');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1005, 'بگو آدم', '<p>آدام کاهان شرکت Reos Partners را تأسیس کرد، جایی که او به عنوان کارگردان کار می کند. او بیش از 30 سال تجربه در کمک به مشاغل، دولت و جامعه مدنی برای حل مشکلات به ظاهر غیرقابل حل دارد. او نویسنده چهار کتاب پرفروش، از جمله <em>حل مشکلات سخت: راه باز صحبت کردن، گوش دادن، و ایجاد واقعیت های جدید است.</em></p>', '2023-01-27 01:44:06.171242', '2023-01-27 01:44:06.171242', NULL, 'Adam Kahane');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1006, 'اریکا اندرسن', '<p>اریکا اندرسن شریک موسس و مدیر عامل Proteus International است، یک شرکت مشاوره مربی که به مدیران ارشد در مورد بهترین تکنیک های مدیریت و رهبری مشاوره می دهد. اندرسون همچنین یک سخنران بین المللی است و در <em>نیویورک تایمز</em> و مجله <em>فورچون</em> حضور داشته است.</p>', '2023-01-27 01:44:18.369466', '2023-01-27 01:44:18.369466', NULL, 'Erika Andersen');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1007, 'رابرت اسکیدلسکی و ادوارد اسکیدلسکی', '<p>رابرت اسکیدلسکی نویسنده مشهور زندگینامه سه جلدی درباره اقتصاددان جان مینارد کینز و همچنین استاد بازنشسته اقتصاد سیاسی در دانشگاه وارویک است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1009, 'داگلاس استون', '<p>داگلاس استون در دانشکده حقوق هاروارد سخنرانی می کند و در مذاکره و ارتباطات متخصص است. او یکی از بنیانگذاران گروه مشاوره Triad، یک شرکت مشاوره ارتباطی و آموزشی است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1010, 'دیوید بی یوفی و ​​مایکل آ. کوزومانو', '<p>دیوید بی. یوفی، علاوه بر اینکه طولانی ترین عضو هیئت مدیره اینتل است، مدیریت بازرگانی را در مدرسه بازرگانی هاروارد تدریس می کند. او نویسنده ای پرکار و نویسنده یا ویراستار 9 کتاب است، از جمله پرفروش ترین کتاب <em>رقابت در زمان اینترنت </em>(نوشته شده با کوزومانو)<em>.</em></p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1011, 'جودیت ریچ هریس', '<p>جودیت هریس یک روانشناس آمریکایی است که دارای مدرک از دانشگاه هاروارد است. او محققی ماهر است که فهرستی طولانی از انتشارات خود را در دست دارد، کتاب های درسی روان شناسی رشد نوشته است و نویسنده کتاب <em>دو نفر شبیه هم نیستند</em> است.</p>', '2023-01-27 01:44:55.469099', '2023-01-27 01:44:55.469099', NULL, 'Judith Rich Harris');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1012, 'نادیا بولز وبر', '<p>نادیا بولز وبر یک الهی‌دان عمومی، یک کشیش لوتری منصوب شده، و بنیانگذار خانه همه گناهکاران و قدیسان است - کلیسایی در دنور، کلرادو. او به طور مکرر در مورد مسائل معنوی و ایمان صحبت می کند و توسط <em>واشنگتن پست</em>،<em>نیویورکر</em>، سی ان ان و بی بی سی معرفی شده است. بولز وبر همچنین نویسنده دو کتاب پرفروش <em>نیویورک تایمز</em> است، <em>Pastrix: The Cranky, Beautiful Faith of A Sinner & Saint</em> و <em>Accidental Saints: Finding God In همه افراد اشتباه</em>.</p>', '2023-01-27 01:45:02.849915', '2023-01-27 01:45:02.849915', NULL, 'Nadia Bolz-Weber');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1013, 'اسکات ای پیج', '<p>Scott E. Page یک دانشمند علوم اجتماعی آمریکایی مستقر در دانشگاه میشیگان است، جایی که او استاد دانشگاه ممتاز پیچیدگی، علوم اجتماعی و مدیریت است. او نویسنده چندین عنوان دیگر از جمله <em>پاداش تنوع</em> و <em>تفاوت</em> است.</p>', '2023-01-27 01:45:10.176071', '2023-01-27 01:45:10.176071', NULL, 'Scott E. Page');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1014, 'مایک استیونز', '<p>مایک استیونز یک کارآفرین و نویسنده بریتانیایی است. او قبل از اینکه برند خود، Peppersmith را تأسیس کند، در سمت‌های رهبری در Innocent Drinks کار کرد. </p>', '2023-01-27 01:45:18.104578', '2023-01-27 01:45:18.104578', NULL, 'Mike Stevens');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1015, 'سوزان ال. اسمالی و دایانا وینستون', '<p>سوزان ال. اسمالی بنیانگذار و رهبر مرکز تحقیقات آگاهی ذهنی در دانشگاه کالیفرنیا در لس آنجلس است. او یک استاد روانپزشکی است که تحقیقاتش بر روی مزایای ذهن آگاهی تمرکز دارد. دایانا وینستون یک معلم محبوب ذهن آگاهی است که در سراسر ایالات متحده و آسیا تدریس می کند. او همچنین رئیس بخش آموزش ذهن آگاهی در دانشگاه کالیفرنیا در لس آنجلس است.</p>', '2023-01-27 01:45:25.376556', '2023-01-27 01:45:25.376556', NULL, 'Susan L. Smalley and Diana Winston');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1016, 'جیم بنسون و تونیان دماریا بری', '<p>جیم بنسون برای طیف وسیعی از سازمان‌ها کار کرده است - از سازمان‌های دولتی گرفته تا شرکت‌های Fortune 10 تا استارت‌آپ‌ها. او مالک نسخه توسعه نرم افزار <em>Modus Cooperandi</em> است و یک مشاور مدیریتی است که از <em>Kanban شخصی</em> برای بهبود محیط های کاری استفاده می کند.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1017, 'دیوید انریچ', '<p>دیوید انریچ سردبیر شرکت مالی <em> وال استریت ژورنال</em> است، جایی که او تیمی از روزنامه نگاران تحقیقی را رهبری می کند. گزارشگری او برنده جوایز متعددی شده است، از جمله جایزه جرالد لوب 2016 برای کارش در مورد رسوایی لیبور، که او آن را به کتاب خود، <em>شبکه عنکبوتی</em> گسترش داد.</p>', '2023-01-27 01:45:40.944195', '2023-01-27 01:45:40.944195', NULL, 'David Enrich');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1018, 'اریک شلوسر', '<p>اریک شلوسر، روزنامه نگار تحقیقی، نویسنده پرفروش <em>کشور فست فود</em> است. آثار او همچنین در <em> New Yorker</em>، <em>Vanity Fair </em>و<em> Atlantic</em>، در میان سایر نشریات ظاهر شده است.</p>', '2023-01-27 01:45:47.991777', '2023-01-27 01:45:47.991777', NULL, 'Eric Schlosser');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1019, 'لوک دو براباندر و آلن اینی', '<p>لوک دو براباندر، محقق و مشاور ارشد گروه مشاوره بوستون در پاریس است. او 12 کتاب از جمله <em>نیمه فراموش شده تغییر</em> را نوشته و تالیف کرده است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1020, 'امیلی بالستیس', '<p>امیلی بالستیس، دکترا، روانشناس اجتماعی و دانشیار دانشگاه نیویورک است. او بیش از 70 مقاله علمی را تالیف کرده و جوایز متعددی را برای کار خود دریافت کرده است.</p>', '2023-01-27 01:46:02.172026', '2023-01-27 01:46:02.172026', NULL, 'Emily Balcetis');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1021, 'کنفوسیوس', '<p>کنفوسیوس در ایالت چین باستانی لو به دنیا آمد و بین سالهای 551 تا 479 قبل از میلاد زندگی می کرد. اطلاعات بسیار کمی در مورد زندگی او وجود دارد، اگرچه اعتقاد بر این است که او با امکاناتی متواضع به دنیا آمده و به عنوان یک مقام دولتی سطح پایین کار کرده است. او در طول زندگی خود یک معلم و فیلسوف بود که شاگردانش را با نام Kǒngzǐ می شناختند. </p>', '2023-01-27 01:46:09.885788', '2023-01-27 01:46:09.885788', NULL, 'Confucius');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1022, 'کارولین وبر', '<p>کارولین وبر متخصص فرهنگ فرانسه در قرن هجدهم است. قبل از اینکه استادیار ادبیات فرانسه و ادبیات تطبیقی ​​در کالج بارنارد دانشگاه کلمبیا شود، در دانشگاه پنسیلوانیا و دانشگاه ییل تدریس می کرد. نوشته های او در <em>Vogue، Bookforum</em>، <em>واشنگتن پست</em> و <em>نیویورک تایمز</em> ظاهر شده است.</p>', '2023-01-27 01:46:16.721223', '2023-01-27 01:46:16.721223', NULL, 'Caroline Weber ');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1023, 'مارک سیبرت', '<p>مارک سیبرت متخصص در زمینه حق رای دادن و بنیانگذار گروه iFranchise است که در روابط با فرانچایز تخصص دارد. او در طول زندگی حرفه ای خود با شرکت هایی مانند مک دونالد، مترو و نستله همکاری داشته است. او همچنین به عنوان مدرس در دانشگاه نورث وسترن و دانشگاه شیکاگو کار کرده است.</p>', '2023-01-27 01:46:28.336175', '2023-01-27 01:46:28.336175', NULL, 'Mark Siebert');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1024, 'ریچارد لوو', '<p>ریچارد لوو نویسنده و روزنامه نگاری است که علایقش حول ارتباط خانواده ها و جوامع با طبیعت است. او همچنین یکی از بنیانگذاران سازمان غیرانتفاعی Children & Nature Network است. آثار لوو در <em>The</em> <em>نیویورک تایمز</em> و همچنین سایر نشریات ظاهر شده است و در سال 2008 مدال Audubon به او اعطا شد. </p>', '2023-01-27 01:46:35.082333', '2023-01-27 01:46:35.082333', NULL, 'Richard Louv');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1025, 'رابین رایان', '<p>رابین رایان کارشناس کاریابی، مشاور شغلی و نویسنده پرفروش کتاب‌هایی در مورد شکار شغل، مصاحبه، نوشتن رزومه و مذاکرات حقوق و دستمزد است. او مهمان <em>اپرا </em> بوده است، جایی که درباره کتابش بحث کرده و در مورد تکنیک های استخدام مشاوره می دهد.</p>', '2023-01-27 01:46:41.990918', '2023-01-27 01:46:41.990918', NULL, 'Robin Ryan');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1026, 'آنا وینر', '<p>آنا وینر یک نویسنده مشارکت کننده برای <em>نیویورکر</em> است که در مورد دره سیلیکون، فرهنگ راه اندازی و فناوری گزارش می دهد. او همچنین در<em>  Atlantic</em>، <em>Harper’s Magazine</em>، the<em>New Republic</em> و <em>New York</em> همکاری داشته است. این اولین کتاب او است.</p>', '2023-01-27 01:46:48.705646', '2023-01-27 01:46:48.705646', NULL, 'Anna Wiener');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1027, 'روری ساترلند', '<p>روری ساترلند به عنوان نایب رئیس آژانس تبلیغاتی برنده جوایز Ogilvy شناخته می شود که از سال 1988 در آنجا کار کرده است. ساترلند علاوه بر اینکه یکی از تأثیرگذارترین متخصصان تبلیغات در جهان امروز است، کتابی به نام <em منتشر کرده است. > مرد ویکی</em> (2011) و بارها در تد گلوبال سخنرانی کرده است. او اکنون یک نویسنده معمولی برای مجلات، <em>Spectator</em>، <em>Market Leader، </em>و <em>Impact</em> است. </p>', '2023-01-27 01:46:56.57885', '2023-01-27 01:46:56.57885', NULL, 'Rory Sutherland');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1028, 'وندی نیومن', '<p> وندی نیومن کارگاه های آشنایی، روابط و رابطه جنسی را رهبری می کند. او برای نوشتن این کتاب از 121 اولین ملاقاتی که قبل از ملاقات با شریک زندگی اش رفت، الهام گرفت.</p>', '2023-01-27 01:47:03.608482', '2023-01-27 01:47:03.608482', NULL, 'Wendy Newman');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1029, 'لی جی بولمن و ترنس ای دیل', '<p>لی جی. بولمن استاد دانشکده تجارت بلوخ در میسوری است که در آن در رهبری و سازماندهی تخصص دارد. او همچنین یک سخنران محبوب و رهبر کارگاه برای شرکت ها، ارگان های دولتی و دانشگاه ها در ایالات متحده و خارج از کشور است. ترنس ای دیل، استاد بازنشسته آموزش در دانشگاه کالیفرنیای جنوبی است. او در بسیاری از معتبرترین دانشگاه‌های ایالات متحده کار کرده است و بر سازمان‌ها و روش‌هایی که برای مقابله با نمادگرایی و اختلال به کار می‌گیرند، تمرکز کرده است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1030, 'آیزایا هنکل', '<p> آیزایا هنکل دارای دکترای زیست شناسی و استعداد مربیگری افراد در زمینه تمرکز ذهنی و روانشناسی رفتاری است. او همچنین نویسنده ای موفق در این زمینه ها و همچنین نویسنده ای است که در نشریاتی مانند <em>گاردین</em> و <em>مجله کارآفرین</em> همکاری می کند. کتاب قبلی او، <em>Black Hole Focus </em>(2014)، یکی از پرفروش ترین های بین المللی در ژانر کتاب تجاری بود.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1031, 'جنی بلیک', '<p>جنی بلیک یک استراتژیست حرفه ای و کسب و کار و سخنران بین المللی است که به افراد کمک می کند تا مشاغلی مطابق با استعدادها و علایق خود ایجاد کنند. او پس از کار به عنوان اولین کارمند در یک استارت آپ نظرسنجی سیاسی در سیلیکون ولی، به آموزش و توسعه شغلی در گوگل پرداخت و در آنجا برنامه گورو شغلی را ایجاد کرد. بلیک در سال 2011 مشاور کسب و کار تمام وقت شد. او همچنین نویسنده <em>زندگی پس از کالج</em> است.</p>', '2023-01-27 01:47:25.50382', '2023-01-27 01:47:25.50382', NULL, 'Jenny Blake');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1096, 'پل آفیت', '<p> Paul A. Offit، MD، رئیس بخش بیماری‌های عفونی و مدیر مرکز آموزش واکسن در بیمارستان کودکان فیلادلفیا است. او نویسنده <em>پیامبران دروغین اوتیسم</em>، <em> واکسینه شده</em> و <em>انتخاب های مرگبار</em> است.</p>', '2023-01-27 01:56:52.650137', '2023-01-27 01:56:52.650137', NULL, 'Paul A. Offit');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1032, 'جاناتان هاسکل و استیان وست لیک', '<p>جاناتان هسکل، عضو کمیته سیاست پولی بانک انگلستان، استاد اقتصاد در دانشکده تجارت امپریال کالج لندن است. استیان وست لیک، رئیس سابق اندیشکده علم و نوآوری NESTA، در حال حاضر به عنوان مشاور وزیر دولت بریتانیا در امور دانشگاه‌ها، علوم، تحقیقات و نوآوری فعالیت می‌کند.</p>', '2023-01-27 01:47:33.233899', '2023-01-27 01:47:33.233899', NULL, 'Jonathan Haskel and Stian Westlake');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1033, 'لوک فری', '<p>دکتر لوک فری یک فیلسوف فرانسوی و نویسنده پرکار است که کتاب‌های او شامل <em>درباره عشق: فلسفه برای قرن بیست و یکم</em> (2012) و <em>نظم جدید اکولوژیک</em> (1992) است. بین سالهای 1996 تا 2011 او استاد فلسفه در دانشگاه دیدرو پاریس بود و از سال 2002 تا 2004 وزیر آموزش دولت فرانسه بود.</p>', '2023-01-27 01:47:40.603109', '2023-01-27 01:47:40.603109', NULL, 'Luc Ferry');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1034, 'مکس مک کیون', '<p>Max McKeown مشاوری است که با برخی از بزرگترین شرکت‌های جهان از جمله Microsoft، Virgin، Sony و Vodafone کار کرده است. هنگامی که او به رهبران کسب و کار کمک نمی کند تا برنامه ریزی استراتژیک خود را تنظیم کنند، مک کیون را در مدار سخنرانی خواهید دید که درباره نوآوری، ایجاد تعامل و تضمین مزیت رقابتی صحبت می کند. کتاب های قبلی او عبارتند از <em>حقیقت درباره نوآوری </em>(2008) و <em>بانک استراتژی</em>(2012).</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1035, 'شیلا قلهاتکر', '<p>شیله کلهاتکار یکی از نویسندگان کارکنان <em> نیویورکر</em> است. او همچنین برای <em> آتلانتیک</em>، <em> نیویورک تایمز</em> و <em>تایم </em>مجله نوشته است. او سخنران عمومی و مفسر در زمینه تجارت، اقتصاد، وال استریت، مقررات و جرایم مالی است. کلهاتکار قبل از اینکه روزنامه نگار شود، یک تحلیلگر در دو صندوق تامینی نیویورک بود.</p>', '2023-01-27 01:47:56.538155', '2023-01-27 01:47:56.538155', NULL, 'Sheelah Kolhatkar');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1036, 'جنیفر کانویلر', '<p>جنیفر کانویلر یک مربی اجرایی مشهور است که در توسعه رهبران درونگرا تخصص دارد. او به عنوان مشاور برای شرکت های Fortune 500 کار کرده است و همچنین نویسنده <em>نفوذ آرام: راهنمای درونگرا برای ایجاد تفاوت</em> است.</p>', '2023-01-27 01:48:04.678847', '2023-01-27 01:48:04.678847', NULL, 'Jennifer Kahnweiler');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1037, 'مارک بلیت', '<p>مارک بلیت استاد دانشگاه براون است، جایی که او اقتصاد سیاسی تدریس می کند و به دلیل انتقاد از سیاست ریاضتی شهرت دارد. او همچنین نویسنده <em>تحولات بزرگ: ایده های اقتصادی و تغییرات نهادی در قرن بیستم</em> است.</p>', '2023-01-27 01:48:11.878411', '2023-01-27 01:48:11.878411', NULL, 'Mark Blyth');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1038, 'جو دو سن', '<p>جو د سنا مدیر عامل و یکی از بنیانگذاران <em>مسابقه اسپارتان</em> است، مجموعه‌ای از دوره‌های موانع در سراسر جهان برگزار می‌شود. او در خانواده‌ای ثروتمند به دنیا آمد، اما همه چیز خود را در سقوط بازار سهام در دهه 1980 از دست داد، قبل از اینکه با تأسیس و توسعه کسب‌وکار چند میلیون دلاری خود، به اوج برگردد.</p>', '2023-01-27 01:48:19.099991', '2023-01-27 01:48:19.099991', NULL, 'Joe de Sena');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1039, 'اسکات سوننشاین', '<p>Scott Sonenshein یک محقق، معلم و مشاور برنده جایزه است. او با شرکت هایی مانند AT&T و مایکروسافت در مورد استراتژی تجاری مشورت کرده است و استاد دانشگاه رایس است.</p>', '2023-01-27 01:48:32.146585', '2023-01-27 01:48:32.146585', NULL, 'Scott Sonenshein');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1040, 'برنت شلندر و ریک تتزلی', '<p>برنت شلندر بیش از دو دهه استیو جابز را برای <em>وال استریت ژورنال</em> و <em>Fortune</em> پوشش داد. او که یکی از وقایع نگاران اصلی انقلاب رایانه شخصی است، بارها با جابز مصاحبه کرد.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1041, 'پاتریک اوشاگنسی', '<p>پاتریک اوشاگنسی مدیر نمونه کارها و نویسنده نشریاتی مانند <em>وال استریت ژورنال</em> است.</p>', '2023-01-27 01:48:52.000972', '2023-01-27 01:48:52.000972', NULL, 'Patrick O’Shaughnessy');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1042, 'جف هادن', '<p>جف هدن یک نویسنده ارواح، سخنران، تأثیرگذار لینکدین و نویسنده مشارکت کننده در <em>Inc است. مجله</em>. آثار او در <em>Time، </em>the<em> Huffington Post، Fast Company، </em>و <em>Business Insider، </em>و در Yahoo! کسب و کار کوچک و MSNBC.</p>', '2023-01-27 01:48:59.078342', '2023-01-27 01:48:59.078342', NULL, 'Jeff Haden');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1043, 'دکتر وین دایر', '<p>دکتر وین دبلیو دایر دارای دکترای مشاوره تحصیلی و دانشیار در دانشگاه سنت جان بود. او از آن زمان تاکنون ده ها کتاب نوشته و به یک سخنران محبوب در موضوع خودسازی تبدیل شده است. از دیگر کتاب‌های او می‌توان به پرفروش‌ترین کتاب‌های <em>نیویورک تایمز</em> <em>قدرت نیت</em> (2004) و <em>10 راز موفقیت و آرامش درونی</em> (2001) اشاره کرد. </p>', '2023-01-27 01:49:06.555221', '2023-01-27 01:49:06.555221', NULL, 'Dr. Wayne W. Dyer');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1044, 'نایل کیستینی', '<p>نیل کیشتینی استاد دانشکده اقتصاد لندن و دانشگاه وارویک است. او معتقد است که مطالعه تاریخ اقتصاد می تواند چیزهای زیادی را در مورد دوران مدرن ما توضیح دهد و به ما کمک کند تا به روشی بهتر به جلو برویم. </p>', '2023-01-27 01:49:14.547521', '2023-01-27 01:49:14.547521', NULL, 'Niall Kishtainy');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1068, 'جسیکا هونگر', '<p> جسیکا هونگر که در اصل یک کارمند توسعه و آموزش بود، Noonday Collection را تأسیس کرد، یک خرده فروش مستقیم برای جواهرات و مد که توسط صنعتگران در کشورهای در حال توسعه ایجاد شده و اکنون یک تجارت 17 میلیون دلاری است. هونگر در سال 2017 به عنوان ارنست و کارآفرین جوان سال انتخاب شد. او مادر سه فرزند است و با خانواده اش در آستین، تگزاس زندگی می کند.</p>', '2023-01-27 01:52:50.448214', '2023-01-27 01:52:50.448214', NULL, 'Jessica Honegger');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1045, 'ادوارد بی برگر و مایکل استاربرد', '<p>ادوارد بی برگر مشاور آموزشی و تجاری و رئیس دانشگاه ساوت وسترن در تگزاس است. تدریس و آثار علمی او افتخارات بسیاری را در ایالات متحده و همچنین بزرگترین جایزه تدریس در جهان انگلیسی زبان را برای او به ارمغان آورده است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1046, 'جفری توبین', '<p>جفری توبین نویسنده کارکنان <em>نیویورکر</em> و نویسنده چندین کتاب پرفروش دیگر، از جمله <em>سوگند، نه</em> و <em>توطئه گسترده</em> است. em>. او همچنین یک تحلیلگر ارشد حقوقی در CNN است.</p>', '2023-01-27 01:49:29.747343', '2023-01-27 01:49:29.747343', NULL, 'Jeffrey Toobin');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1047, 'بنجامین گراهام و نظرات جیسون تسوایگ', '<p>بنجامین گراهام (1884-1976) کار خود را به عنوان سرمایه گذار در سال 1914 آغاز کرد، پس از آن مجبور شد با زیان های قابل توجهی در طول سقوط اقتصادی در دهه 1920 مقابله کند. کتاب <em>سرمایه گذار هوشمند</em> او مجموعه ای از درس هایی است که او به عنوان یک سرمایه گذار جوان آموخته است.</p>', '2023-01-27 01:49:37.646549', '2023-01-27 01:49:37.646549', NULL, 'Benjamin Graham and comments by Jason Zweig');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1048, 'جما دیل', '<p>جما دیل کارشناس منابع انسانی، بنیانگذار Work Consultancy، و مدرس قانون استخدام، رفتار سازمانی و رفاه در مدرسه بازرگانی دانشگاه جان مورز لیورپول است. او وبلاگ برنده جایزه <em>People Stuff</em> را می نویسد.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1049, 'و شوبل', '<p>Dan Schawbel در همه موارد مربوط به آینده محل کار متخصص است. بنیانگذار workplacetrends.com، بزرگترین گردآورنده تحقیقات در مورد مسائل محل کار، یک کارآفرین، پادکست، سخنران و نویسنده تحسین شده است. او دو کتاب پرفروش دیگر درباره زندگی در محل کار منتشر کرده است، <em>خود را ارتقا دهید</em> و <em>Me 2.0</em>.</p>', '2023-01-27 01:49:53.578453', '2023-01-27 01:49:53.578453', NULL, 'Dan Schawbel');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1050, 'ریچارد ان. بولز با کاترین بروکس', '<p>ریچارد ان. بولز در زمینه توسعه شغلی پیشگام بود. کتابچه راهنمای کارجوی او، <em>چتر نجات شما چه رنگی است، برای اولین بار در سال 1970 منتشر شد و از آن زمان هر سال بازبینی و به روز شده است. این عنوان به عنوان یکی از 100 کتاب غیرداستانی تأثیرگذار مجله <em>Time</em> انتخاب شد. نسخه 2021 توسط کاترین بروکس، مدیر مرکز شغلی در دانشگاه واندربیلت به روز شد.</p>', '2023-01-27 01:50:01.294808', '2023-01-27 01:50:01.294808', NULL, 'Richard N. Bolles with Katharine Brooks');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1051, 'جان اسکالی', '<p>جان اسکالی، کارآفرین، مربی و سرمایه‌گذار، قبلاً مدیرعامل شرکت پپسی و اپل بود. او همچنین کتاب <em>Odyssey: Pepsi to Apple</em> را نوشته است.</p>', '2023-01-27 01:50:15.43426', '2023-01-27 01:50:15.43426', NULL, 'John Sculley');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1052, 'چهارشنبه مارتین', '<p> چهارشنبه مارتین نویسنده و منتقد فرهنگی با دکترای ادبیات تطبیقی ​​و مطالعات فرهنگی از دانشگاه ییل است. او درباره مسائل جنسی، جنسیت و فرزندپروری برای نشریاتی مانند<em>نیویورک تایمز</em>، <em>Harper’s Bazaar</em> و<em>آتلانتیک</em> نوشته است. او همچنین نویسنده <em>Stepmonste</em>r و <em>Primates of Park Avenue</em> است - پرفروش‌ترین <em>نیویورک تایمز</em>. </p>', '2023-01-27 01:50:33.617924', '2023-01-27 01:50:33.617924', NULL, 'Wednesday Martin');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1053, 'دنی راجرز', '<p>روزنامه نگار دنی راجرز یک متخصص رسانه و بازاریابی است که بیش از دو دهه در مورد مسائل ارتباطات گزارش می دهد. او به عنوان سردبیر با نشریاتی مانند <em>Campaign</em>،<em> Media Week</em>، <em>PRWeek</em> و <em>Brand Republic Group</em> کار کرده است.< /p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1054, 'بروس واتسون', '<p>بروس واتسون یکی از همکاران مکرر مجله <em>Smithsonian</em> است که در آن درباره همه چیز از مارماهی گرفته تا پی، هنرمندان و نویسندگان می نویسد. از دیگر کتاب‌های او می‌توان به <em>نان و گل سرخ</em>، <em> ساکو و وانزتی</em> و <em>تابستان آزادی</em> اشاره کرد.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1055, 'دن بوتنر', '<p>دان بوتنر، که کارش بر اسرار زندگی طولانی تمرکز دارد، نویسنده پرفروش و عضو نشنال جئوگرافیک است. پروژه بزرگ بعدی او معرفی اصول زندگی طولانی است که او در چندین شهر ایالات متحده کشف کرده است.</p>', '2023-01-27 01:50:56.118285', '2023-01-27 01:50:56.118285', NULL, 'Dan Buettner');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1056, 'جوآن دیدیون', '<p>جوان دیدیون نویسنده آمریکایی بود. آثار تحسین شده او طیف گسترده ای از ژانرها و فرم ها را شامل می شود: ادبیات، فیلمنامه، خاطرات، مقاله و روزنامه نگاری. آنها عبارتند از <em>خم شدن به سوی بیت لحم</em>، که یکی از آثار مهم جنبش روزنامه نگاری جدید بود. <em>Play It as It Las</em>، که مجله <em>Time</em> یکی از "100 رمان برتر انگلیسی زبان از سال 1923 تا 2005" نام برد. و فیلمنامه <em>اعترافات واقعی</em> که او با همسرش جان گرگوری دان نوشته است.</p>', '2023-01-27 01:51:08.395604', '2023-01-27 01:51:08.395604', NULL, 'Joan Didion');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1069, 'دانیل لیبرمن', '<p>دانیل لیبرمن دیرینه‌انتروپولوژیست در دانشگاه هاروارد است، جایی که او رئیس بخش زیست‌شناسی تکاملی انسان است. او بیشتر به دلیل تحقیقات برنده جایزه خود در مورد تکامل سر و بدن انسان شناخته شده است. او بیش از صد مقاله برای مجلات علمی معتبر از جمله <em>Nature</em>و <em>Science</em> نوشته است. کتاب های قبلی او عبارتند از <em>تکامل سر انسان </em>(2011).</p>', '2023-01-27 01:52:57.893877', '2023-01-27 01:52:57.893877', NULL, 'Daniel Lieberman');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1057, 'دانیل لاپین', '<p>خاخام دانیل لاپین میزبان یک برنامه رادیویی در KSFO در سانفرانسیسکو است که توصیه هایی بر اساس سنت باستانی یهودی ارائه می دهد. مقالات او در بسیاری از نشریات از جمله <em>وال استریت ژورنال</em> و <em>نشنال ریویو</em> منتشر شده است. او نویسنده <em>جنگ واقعی آمریکا</em> است، کتابی که از بازگشت به سنت‌های یهودی-مسیحی حمایت می‌کند.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1058, 'لیز پریمو', '<p>لیز پریمو، یک طرفدار مغرور سیر و باغبان مشتاق، سردبیر موسس مجله <em>Canadian Gardening</em> است. نویسنده کتاب های پرفروش <em>باغ های حیاط جلو</em> و <em>تاریخ طبیعی من</em>، همچنین به طور گسترده در مورد تخصص خود در زمینه باغبانی در سراسر آمریکای شمالی صحبت کرده است.</p>', '2023-01-27 01:51:22.642581', '2023-01-27 01:51:22.642581', NULL, 'Liz Primeau');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1059, 'بس کاست', '<p>باس کاست، نویسنده علم آلمانی، روانشناسی و زیست شناسی را در دانشگاه کنستانس و ام آی تی خوانده است. او بعداً به عنوان روزنامه‌نگار آموزش دید و در <em>Nature، GEO، </em>و<em> </em>the<em> Berliner Tageszeitung کار کرد. </em>مقالات و کتاب‌های او جوایز بسیاری را برای او به ارمغان آورده است، از جمله <em>Bild der Wissenschaft</em>کتاب علمی سال برای <em>The Diet Compass</em></p>.', '2023-01-27 01:51:30.69606', '2023-01-27 01:51:30.69606', NULL, 'Bas Kast');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1060, 'جیمز کوزز و بری پوزنر', '<p>جیمز ام. کوزز، عضو اجرایی رئیس دانشکده تجارت لیوی دانشگاه سانتا کلارا است. او یک سخنران محبوب در مورد موضوع رهبری برای شرکت ها و سازمان های دولتی است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1061, 'النور روزولت', '<p>النور روزولت (1884-1962) در خانواده ای ثروتمند و با نفوذ نیویورکی به دنیا آمد. عموی او رئیس جمهور تئودور روزولت بود. او در سال 1905 با سیاستمدار آینده دار فرانکلین دلانو روزولت ازدواج کرد. در سال 1934، فرانکلین به عنوان رئیس جمهور ایالات متحده انتخاب شد و النور بانوی اول شد. النور از موقعیت و نفوذ خود برای مقابله با نابرابری و بی عدالتی در طول زندگی اش استفاده می کرد. پس از جنگ جهانی دوم، او با هیئت آمریکایی در سازمان ملل متحد خدمت کرد و نقش مهمی در ایجاد اعلامیه جهانی حقوق بشر ایفا کرد.</p>', '2023-01-27 01:51:50.370827', '2023-01-27 01:51:50.370827', NULL, 'Eleanor Roosevelt');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1062, 'تیم دیوید', '<p>تیم دیوید یک شعبده باز، ذهنی و مربی حرفه ای است. او یک کانال محبوب YouTube را اداره می‌کند و بر کمک به دیگران برای ایجاد مهارت‌های ارتباطی مؤثرتر تمرکز می‌کند.</p>', '2023-01-27 01:51:58.148548', '2023-01-27 01:51:58.148548', NULL, 'Tim David');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1063, 'گای دویچر', '<p>گای دویچر یک زبان شناس و پژوهشگر افتخاری در دانشگاه منچستر است. دویچر علاوه بر مشارکت‌های دانشگاهی متعدد، نویسنده <em>گشودن زبان</em> نیز هست.</p>', '2023-01-27 01:52:11.232869', '2023-01-27 01:52:11.232869', NULL, 'Guy Deutscher');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1064, 'تریستان گولی', '<p>تریستان گولی نویسنده، کاوشگر و دریانورد طبیعت است که در ساسکس در بریتانیا زندگی می کند. او اکسپدیشن های طبیعت را در هر پنج قاره رهبری می کند و یکی از معدود افرادی است که به صورت انفرادی از اقیانوس اطلس عبور می کند. او عضو انجمن سلطنتی جغرافیایی و موسسه سلطنتی ناوبری است. کتاب‌های دیگر او عبارتند از <em>راهنمای واکر برای سرنخ‌ها و نشانه‌های فضای باز</em>و <em>چگونه آب بخوانیم.</em></p>.', '2023-01-27 01:52:18.930788', '2023-01-27 01:52:18.930788', NULL, 'Tristan Gooley');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1065, 'تام راث', '<p>تام راث نویسنده پرفروشی است که در تفکر تجاری نوآورانه تخصص دارد. دیگر کتاب‌های او شامل پرفروش‌ترین کتاب‌های <em>نیویورک تایمز</em> <em>سطل شما چقدر پر است؟</em> و <em>رهبری مبتنی بر نقاط قوت</em> است.</p>', '2023-01-27 01:52:27.121422', '2023-01-27 01:52:27.121422', NULL, 'Tom Rath');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1066, 'جودی آرچر و متیو ال. جوکرز', '<p>جودی آرچر نویسنده و ویراستار سابق انتشارات پنگوئن در بریتانیا است. او دارای مدرک دکترا از دانشگاه استنفورد است و به عنوان مشاور برای نویسندگان و مشاغل ادبی مختلف عمل کرده است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1067, 'جو ویکز', '<p>جوزف ویکس یک مربی تناسب اندام، مجری تلویزیونی و نویسنده بریتانیایی است. کتاب‌های قبلی او شامل مجموعه‌های <em>لاغر با تمرکز بر رژیم غذایی و ورزش در 15 </em> است که بیش از یک میلیون نسخه در سراسر جهان فروخته است. وی همچنین مجری برنامه <em>مربی بدن</em> شبکه چهار است. او پس از دریافت 955158 بازدید در 24 مارس 2020، رکورد جهانی گینس را برای "بیشترین بیننده برای پخش زنده تمرین بدنسازی در YouTube" به دست آورد.</p>', '2023-01-27 01:52:42.770689', '2023-01-27 01:52:42.770689', NULL, 'Joe Wicks');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1070, 'Sadhguru Jaggi Vasudev', '<p>Sadhguru Jaggi Vasudev یک عارف هندی است. او به جای تمرین زهد، به داشتن زندگی کامل و با نشاط اعتقاد دارد. او علاوه بر مأموریت معنوی خود، بنیانگذار یک سازمان خیریه است که برای کاهش فقر در هند فعالیت می کند.</p>', '2023-01-27 01:53:05.480496', '2023-01-27 01:53:05.480496', NULL, 'Sadhguru Jaggi Vasudev');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1071, 'دین گرازیوسی', '<p> گرازیوسی میلیونری است که ثروت خود را به عنوان صاحب کسب و کار، کارآفرین، بازاریاب، سرمایه گذار املاک و مستغلات و مربی موفقیت به دست آورده است. او در 15 سال گذشته هر روز از طریق شرکت خود، Dean Enterprises - یک شرکت تولید تلویزیونی متخصص در تبلیغات اطلاعاتی، در تلویزیون ظاهر شده است. گرازیوسی با وجود نارساخوانی، نویسنده چندین کتاب پرفروش <em>نیویورک تایمز</em> از جمله <em>میلیونر املاک باشید</em>، <em>در حال حاضر از املاک سود ببرید</em>، و <em>30 روز تا سود املاک و مستغلات.</em></p>', '2023-01-27 01:53:13.421523', '2023-01-27 01:53:13.421523', NULL, 'Dean Graziosi');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1072, 'لیزا دامور', '<p>لیزا دامور یک روانشناس بالینی و مدیر مرکز تحقیقات دختران مدرسه لورل و همچنین یکی از همکاران مرکز مطالعات کودک شوبرت است. کار او بر کمک به نوجوانان و والدین آنها متمرکز است. او مادر پرافتخار دو دختر است.</p>', '2023-01-27 01:53:20.99777', '2023-01-27 01:53:20.99777', NULL, 'Lisa Damour');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1073, 'البرت هابارد', '<p>البرت هابارد (1856-1915) نویسنده، هنرمند و فیلسوف آمریکایی بود. مقاله او <em>پیامی به گارسیا</em> بیش از 40 میلیون نسخه فروخت و به 37 زبان ترجمه شد.</p>', '2023-01-27 01:53:34.093865', '2023-01-27 01:53:34.093865', NULL, 'Elbert Hubbard');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1074, 'جان تیرول', '<p>ژان تیرول، اقتصاددان مشهور فرانسوی و برنده جایزه نوبل علوم اقتصادی 2014 است. تیرول علاوه بر مطالعه برنده جایزه خود در مورد مقررات خدمات شهری، کتاب های متعددی از جمله <em>نظریه مالی شرکت</em>، <em>بحران های مالی</em>و <em>نظام پولی بین المللی</em> را تالیف کرده است. em>.</p>', '2023-01-27 01:53:47.200345', '2023-01-27 01:53:47.200345', NULL, 'Jean Tirole');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1075, 'جیک کنپ و جان زراتسکی', '<p>جیک کنپ و جان زراتسکی هر دو از خودی‌های سابق صنعت فناوری هستند که از استراتژی و تاکتیک‌های ذکر شده در این پلک‌ها استفاده کردند تا زمان خود را از زندگی پرمشغله خود به دست آورند و به دنبال علایق واقعی خود بروند، که در نهایت منجر به تغییرات عمده در حرفه‌شان شد.</ p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1076, 'تاد هنری', '<p>تاد هنری یک سخنران، مربی و نویسنده بین المللی، و همچنین بنیانگذار و مدیر عامل شرکت Accidental Creative، یک شرکت مشاوره است که توسعه شخصی و خلاقیت را ارتقا می دهد. در سال 2006، او <em>خلاقیت تصادفی</em> را آغاز کرد، یک پادکست تجاری بسیار موفق، قبل از انتشار ایده های خود در قالب کتاب.</p>', '2023-01-27 01:54:06.945936', '2023-01-27 01:54:06.945936', NULL, 'Todd Henry');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1077, 'میشل تیلیس لدرمن', '<p>میشل تیلیس لدرمن یک سخنران انگیزشی و مربی حرفه ای است. او بنیانگذار و مدیر اجرایی Executive Essentials است، شرکتی که برنامه های ارتباطی و رهبری را برای مشاغل و حرفه ای ها به طور یکسان اجرا می کند. او نویسنده کتاب های پرفروش متعددی است، از جمله <em>مصاحبه را میخکوب، شغل را به ارمغان بیاور.</em></p>', '2023-01-27 01:54:14.495061', '2023-01-27 01:54:14.495061', NULL, 'Michelle Tillis Lederman');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1078, 'بری نالباف', '<p>بری نالباف استاد میلتون اشتاینباخ مدیریت در دانشکده مدیریت ییل است. او همچنین چندین کسب و کار موفق مانند چای صادق را تأسیس کرده است. دوره مقدماتی او در زمینه مذاکره بیش از 350000 دانش آموز در دانشگاه ییل و آنلاین ثبت نام کرده است.</p>', '2023-01-27 01:54:21.80566', '2023-01-27 01:54:21.80566', NULL, 'Barry Nalebuff');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1079, 'تارا وستور', '<p>تارا وستور در سال 1986 در آیداهو به دنیا آمد. او مدرک لیسانس خود را از دانشگاه بریگام یانگ دریافت کرد و بورسیه گیتس کمبریج دریافت کرد. او دکترای خود را در تاریخ در سال 2014 به پایان رساند و همچنین عضو مدعو در دانشگاه هاروارد بود. <em>تحصیل کرده</em> اولین کتاب او است.</p>', '2023-01-27 01:54:28.942801', '2023-01-27 01:54:28.942801', NULL, 'Tara Westover');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1080, 'آلبر کامو', '<p>آلبرت کامو فیلسوف، رمان‌نویس و روزنامه‌نگار فرانسوی بود که کارش حول محورهای اگزیستانسیالیستی بود. او شاید بیشتر به خاطر آثار ادبی خود، به ویژه <em>غریبه</em>، <em>طاعون</em> و <em>پاییز</em> مشهور است. او در سال 1957 جایزه نوبل ادبیات را دریافت کرد.</p>', '2023-01-27 01:54:35.762562', '2023-01-27 01:54:35.762562', NULL, 'Albert Camus');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1081, 'دی جی روستا', '<p>نیچی هاجسون روزنامه‌نگار، پخش‌کننده و نویسنده بریتانیایی مقیم لندن است. او به طور منظم در خبرگزاری‌هایی مانند <em>گاردین</em>، <em>معاون</em> و <em>دیلی تلگراف</em> همکاری می‌کند و در موضوعاتی مانند سیاست جنسی، دوستیابی و فناوری تخصص دارد. اولین کتاب او، <em>Bound to You</em>، در سال 2012 منتشر شد.</p>', '2023-01-27 01:54:42.921147', '2023-01-27 01:54:42.921147', NULL, 'Nichi Hodgson');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1082, 'الکس اپستاین', '<p>الکس اپستاین نظریه‌پرداز انرژی و متخصص سیاست‌های صنعتی است. او بنیانگذار و رئیس <em>مرکز پیشرفت صنعتی</em>، یک اتاق فکر انتفاعی است. <em>مورد اخلاقی برای سوخت‌های فسیلی</em> یک کتاب پرفروش <em>نیویورک تایمز</em> است.</p>', '2023-01-27 01:54:49.919658', '2023-01-27 01:54:49.919658', NULL, 'Alex Epstein');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1083, 'لیزا رندال', '<p>لیزا رندال استاد علوم در دانشگاه هاروارد است که در کیهان‌شناسی و فیزیک ذرات نظری تخصص دارد. در سال 2007، او به عنوان یکی از "100 فرد تاثیرگذار" مجله <em>تایم</em> انتخاب شد و نویسنده کتاب‌های دیگری از جمله <em>گذرهای منحرف شده</em> است.</p>', '2023-01-27 01:54:57.528186', '2023-01-27 01:54:57.528186', NULL, 'Lisa Randall');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1084, 'دیل لودویگ و گرگ اوون بوگر', '<p>Dale Ludwig بنیانگذار و رئیس Turpin Communication است که به افراد کمک می کند مهارت ها و مهارت های خود را برای برتری در ارائه ارائه دهند. او دارای دکترای ارتباطات است و مدرس دانشگاه ایلینویز در Urbana-Champaign بوده است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1085, 'ربکا هندرسون', '<p>ربکا هندرسون یک اقتصاددان و استاد دانشگاه جان و نتی مک آرتور در هاروارد است، جایی که دوره محبوب سرمایه داری را دوباره به تصویر می کشد. او همچنین یکی از اعضای هیئت مدیره در آزمایشگاه‌های Amgen و IDEXX، هر دو شرکت S&P 500 است.</p>', '2023-01-27 01:55:14.320917', '2023-01-27 01:55:14.320917', NULL, 'Rebecca Henderson');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1086, 'لبخند واسلاو', '<p>واسلاو اسمیل استاد بازنشسته در دانشگاه مانیتوبا است و بیش از 400 مقاله و 35 کتاب منتشر کرده است، از جمله <em>ساخت دنیای مدرن</em>و <em>باید گوشت بخوریم</em>. او در کنار حرفه آکادمیک گسترده خود، به عنوان مشاور برای چندین موسسه مختلف ایالات متحده، اتحادیه اروپا و بین المللی کار کرده است.</p>', '2023-01-27 01:55:28.228384', '2023-01-27 01:55:28.228384', NULL, 'Vaclav Smil');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1087, 'جوئل بکرمن در کنار تایلر گری', '<p>جوئل بکرمن آهنگساز برنده جایزه، تهیه کننده تلویزیونی و بنیانگذار Man Made Music، شرکتی متخصص در برندسازی صوتی است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1088, 'استر پرل', '<p> استر پرل یک روان درمانگر ساکن نیویورک است که به دلیل رویکرد پیشگامانه اش در روابط شخصی شناخته شده است. با تکیه بر بیش از دو دهه تجربه به عنوان یک زوج درمانگر، اولین کتاب پرل <em>جفت گیری در اسارت</em>به پرفروش ترین کتاب <em>نیویورک تایمز</em> تبدیل شد و به 24 زبان ترجمه شد. سخنرانی TED او در سال اول به بیش از 5 میلیون بیننده رسید، و پادکست او، <em>از کجا باید شروع کنیم؟،</em> به شنونده اجازه می دهد در طول جلسات درمانی خود با زوج ها، مگس بر دیوار باشد.</p >', '2023-01-27 01:55:43.743855', '2023-01-27 01:55:43.743855', NULL, 'Esther Perel');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1089, 'سم والتون با جان هیوی', '<p>سام والتون Walmart را تأسیس کرد، فروشگاه های زنجیره ای خرده فروشی که در سال 2015 نزدیک به 500 میلیارد دلار فروش داشت. والتون در سال 1992 درگذشت.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1090, 'جوسلین فریمن و آرون فریمن', '<p>جوسلین و آرون فریمن یک زوج متاهل هستند که مجموعه‌ای از دوره‌های آنلاین The Couples Workshop و Empowered Couples University را اداره می‌کنند. آنها به هزاران زوج در سراسر جهان کمک کرده اند تا روابط بهتری ایجاد کنند.</p>', '2023-01-27 01:55:59.022444', '2023-01-27 01:55:59.022444', NULL, 'Jocelyn Freeman and Aaron Freeman');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1091, 'اسکات بلسکی', '<p> اسکات بلسکی معاون انجمن در Adobe و همچنین بنیانگذار و مدیر عامل پلتفرم توسعه محصول Behance است. او برای شرکت‌های Fortune 500 و غول‌های رسانه‌های جدید مشاوره کرده و به عنوان مهمان در دانشگاه کرنل، دانشگاه هاروارد و دانشگاه برکلی سخنرانی کرده است. لیست "100 خلاق ترین افراد در تجارت" شرکت Fast شامل اسکات در سال 2010 بود.</p>', '2023-01-27 01:56:07.183751', '2023-01-27 01:56:07.183751', NULL, 'Scott Belsky');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1092, 'استفانی مارش', '<p>Stephanie Marsh یک کارشناس تحقیقات کاربر مستقر در بریتانیا است. او رئیس تحقیقات و تحلیل کاربران برای سرویس دیجیتال دولتی است، یک نهاد رسمی که وظیفه دیجیتالی کردن خدمات عمومی را بر عهده دارد. مارش قبل از تصدی سمت فعلی خود، مشاور و رهبری شرکت طراحی تجربه کاربر، Bunnyfoot بود. مشتریان قبلی او عبارتند از بی بی سی، باشگاه فوتبال آرسنال و ایزی جت. </p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1093, 'اسکات آدامز', '<p>اسکات آدامز خالق <em>Dilbert</em> است، یک کمیک استریپ معروف که جنبه های طنز زندگی اداری را به نمایش می گذارد. در سراسر جهان و در روزنامه های بی شماری به چاپ رسیده است. او همچنین نویسنده کتاب‌های زیادی است، از جمله کتاب پرفروش <em>نیویورک تایمز</em> <em>برنده بزرگ</em>.</p>', '2023-01-27 01:56:23.246104', '2023-01-27 01:56:23.246104', NULL, 'Scott Adams');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1094, 'اکاترینا والتر و جسیکا جوگلیو', '<p>Ekaterina Walter یکی از بنیانگذاران و مدیر ارشد اجرایی Branderati و نویسنده <em>Think like Zuck</em> است. او قبلاً استراتژیست جهانی رسانه های اجتماعی اینتل بود.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1095, 'آلن ویس', '<p>آلن وایس موسس گروه مشاوره سامیت است و بیش از 50 کتاب از جمله <em>شروع</em> <em>شروع</em> <em>در</em> <em>مشاوره< /em> و <em>میلیون</em> <em>دلار</em> <em>ارجاعات</em>. او علاوه بر اینکه در میان یک درصد برتر از بهترین سخنرانان عمومی جهان در انجمن ملی سخنرانان قرار دارد، برای شرکت‌های بی‌شماری نیز مشاوره کرده است که به طور مداوم بیش از ۱ میلیون دلار در سال درآمد داشته است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1097, 'سندور الیکس کاتز', '<p>ساندور الیکس کاتز خودخوانده "احیای تخمیر" است که علاقه به این موضوع از علایق او به آشپزی، باغبانی و علوم تغذیه ناشی شده است. کاتز کارگاه های تخمیر را در سراسر ایالات متحده رهبری می کند. او نویسنده <em>تخمیر وحشی</em>، <em>انقلاب در مایکروویو نمی شود</em>، و <em>هنر تخمیر</em> است، که برای آنها بنیاد جیمز بیرد دریافت کرد. جایزه در سال 2013.</p>', '2023-01-27 01:56:59.594521', '2023-01-27 01:56:59.594521', NULL, 'Sandor Ellix Katz');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1098, 'استفان کاوی', '<p>استفان کاوی نویسنده کتاب پرفروش بین المللی <em>7 عادت افراد بسیار موثر</em> است که بیش از 25 میلیون نسخه فروخته است. به دلیل کارش در جهت توسعه تجارت و آموزش، او به عنوان یکی از 25 آمریکایی تأثیرگذار مجله <em>Time</em> شناخته شد.</p>', '2023-01-27 01:57:06.499778', '2023-01-27 01:57:06.499778', NULL, 'Stephen Covey');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1099, 'چارلز دوهیگ', '<p>چارلز دوهیگ خبرنگار برنده جایزه پولیتزر برای <em>نیویورک تایمز</em> است. اولین کتاب او، <em>قدرت عادت</em>، بیش از 60 هفته در فهرست پرفروش‌های <em>Times</em> باقی ماند.</p>', '2023-01-27 01:57:13.768494', '2023-01-27 01:57:13.768494', NULL, 'Charles Duhigg');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1100, 'مونگی نگومانه', '<p>Mungi Ngomane یک مدافع پرشور حقوق بشر، با تمرکز ویژه بر دختران و زنان، و حمایت از پناهندگان است. او روی ابتکاراتی برای پرداختن به اسلام هراسی در ایالات متحده، حل مناقشه در خاورمیانه و آزادی مردم فلسطین کار کرده است. نگومانه، نوه اسقف اعظم معروف دزموند توتو، ردای خانواده را برای مبارزه برای عدالت و کرامت انسانی به دست گرفته است.</p>', '2023-01-27 01:57:21.091656', '2023-01-27 01:57:21.091656', NULL, 'Mungi Ngomane');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1101, 'ویلیام پاندستون', '<p>ویلیام پاوندستون نویسنده کتاب‌های غیرداستانی مختلفی است، از جمله <em>آیا برای کار در Google به اندازه کافی باهوش هستید؟</em> و <em>Fortune’s Formula</em>.</p>', '2023-01-27 01:57:38.639857', '2023-01-27 01:57:38.639857', NULL, 'William Poundstone');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1102, 'جیکوب مورگان', '<p>جاکوب مورگان یک نویسنده پرفروش، آینده پژوه، سخنران اصلی و مشاور تجاری است. او یک مرجع پیشرو در آینده کار، تجربه کارمند و روش هایی است که در آن محل کار مدرن در حال تغییر است. او دو کتاب پرفروش دیگر نوشته است: <em>آینده کار</em>(2010) و <em>سازمان مشارکتی</em>(2012).</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1103, 'سونیا بارلو', '<p>سونیا بارلو یک کارآفرین، سخنران عمومی و مربی کسب و کار متنوع است. در سال 2018، او شبکه LMF را تأسیس کرد، یک سازمان غیرانتفاعی جامعه‌سازی و مربیگری برای زنان و اقلیت‌ها، و میزبان شبکه آسیایی بی‌بی‌سی <em>The Everyday Hustle</em> و Capital One''s <em>Champions of Change است. </em> پادکست. او در سال 2017 جایزه We Are the City Rising Star را دریافت کرد و در هر دو سال 2020 و 2021، توسط Computer Weekly به عنوان یکی از تأثیرگذارترین زنان در فناوری بریتانیا انتخاب شد.</p>', '2023-01-27 01:57:54.521789', '2023-01-27 01:57:54.521789', NULL, 'Sonya Barlow');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1104, 'مولی کارمل', '<p><strong>درباره نویسنده</strong></p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1105, 'شین اسنو و جو لازاوسکاس', '<p>جو لازاوسکاس مدیر استراتژی محتوا و سردبیر Contently است، یک شرکت فناوری جهانی که به شرکت‌های Fortune 500 کمک می‌کند داستان‌های جذابی بسازند. Contently توسط نویسنده همکار Lazauskas، Shane Snow تاسیس شد. هر دو واژه ساز آموزش دیده با پیشینه روزنامه نگاری هستند.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1106, 'اسکات تاننبام و ادواردو سالاس', '<p> اسکات تاننبام، رئیس گروه اثربخشی سازمانی است، جایی که او در 25 سال گذشته با صدها کسب و کار و سازمان در سراسر جهان مشورت کرده است. او استاد سابق مدیریت بازرگانی است و تحقیقات او به طور گسترده منتشر شده است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1107, 'پاتریک کیف', '<p>پاتریک رادن کیف نویسنده و روزنامه نگار برنده جایزه است. از دیگر کتاب‌های او می‌توان به <em>سر مار</em> و <em>گفتگو</em> اشاره کرد. کیف همچنین نویسنده مجله <em>نیویورکر</em> است و در سال 2014 جایزه مجله ملی را برای فیلمنامه نویسی دریافت کرد.</p>', '2023-01-27 01:58:33.674485', '2023-01-27 01:58:33.674485', NULL, 'Patrick Keefe');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1108, 'تام دکتروف', '<p>تام دکتروف، مدیر اجرایی <em>J. والتر تامپسون</em>در منطقه آسیا و اقیانوسیه. Doctoroff با بیش از 20 سال تجربه بازاریابی، برخی از بزرگترین برندهای جهان مانند <em>Nestle</em>و <em>Microsoft</em> را شکل داده است.</p>', '2023-01-27 01:58:41.371313', '2023-01-27 01:58:41.371313', NULL, 'Tom Doctoroff');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1109, 'آلیس شرودر', '<p>آلیس شرودر قبل از قبول پیشنهاد وارن بافت و تبدیل شدن به یک نویسنده تمام وقت، کار خود را به عنوان یک تحلیلگر بیمه آغاز کرد. او در حال حاضر ستون نویس <em>اخبار بلومبرگ</em> است. <em>گلوله برفی</em> توسط مجله <em>Time </em></em> به عنوان یکی از ده کتاب برتر سال 2008 انتخاب شد.', '2023-01-27 01:58:53.945066', '2023-01-27 01:58:53.945066', NULL, 'Alice Schroeder');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1110, 'جوناس آلتمن', '<p> جوناس آلتمن سخنران، نویسنده و کارآفرین است. هدف طراحی او، Social Fabric، انسانی‌تر کردن دنیای کار است. نوشته های او در <em> گاردین، کوارتز</em> و<em>ساندی تایمز</em> منتشر شده است.</p>', '2023-01-27 01:59:07.587895', '2023-01-27 01:59:07.587895', NULL, 'Jonas Altman');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1111, 'برایان متیمور', '<p>برایان متیمور متخصص نوآوری و بنیانگذار شرکت خودش، Growth Engine، مستقر در کانکتیکات است. Mattimore به عنوان رهبر جلسات برای سازمان ها و مشاور برای شرکت های بزرگ از جمله فورد، یونیلور و پپسی، خلاقیت را پرورش داده است. او همچنین خالق Bright Ideas است، یک بازی که برای کمک به ما در آموزش خلاقیت طراحی شده است.</p>', '2023-01-27 01:59:15.237278', '2023-01-27 01:59:15.237278', NULL, 'Bryan Mattimore');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1112, 'رابرت تويگر', '<p>رابرت تویگر نویسنده بریتانیایی است که در دانشگاه آکسفورد سیاست و فلسفه خوانده است. او چندین اثر داستانی و همچنین مقالاتی برای نشریاتی مانند <em>دیلی تلگراف</em> و <em>ساندی تایمز</em> نوشته است.</p>', '2023-01-27 01:59:23.388949', '2023-01-27 01:59:23.388949', NULL, 'Robert Twigger');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1113, 'استیون اورمن', '<p>استیون اورمن یک متخصص بازاریابی و یک سخنران عمومی مشهور است که اخیراً به عنوان مدیر ارشد بازاریابی به کداک پیوسته است. اورمن علاوه بر تأسیس شرکت مشاوره بازاریابی Match & Candle، یکی از اولین کارمندان مجله <em>Wired</em> بود.</p>', '2023-01-27 01:59:31.16917', '2023-01-27 01:59:31.16917', NULL, 'Steven Overman');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1114, 'فرانک لونتز', '<p>دکتر فرانک لونتز یک نظرسنجی مشهور و گورو افکار عمومی است که به طور منظم به عنوان مشاور ارتباطات برای سیاستمداران آمریکایی کار می کند. او بیش از 1500 نظرسنجی و گروه های متمرکز را رهبری کرده و در کمپین های سیاسی و شرکتی متعددی مشارکت داشته است.</p>', '2023-01-27 01:59:38.527568', '2023-01-27 01:59:38.527568', NULL, 'Frank Luntz');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1115, 'راب فیتزپاتریک', '<p>راب فیتزپاتریک یک کارآفرین فناوری و شریک در Founder Centric است، جایی که به دانشگاه‌ها، کسب‌وکارها و استارت‌آپ‌های دارای بودجه اتحادیه اروپا کمک می‌کند تا برنامه‌های آموزشی بهتری را طراحی و ارائه کنند.</p>', '2023-01-27 01:59:46.223569', '2023-01-27 01:59:46.223569', NULL, 'Rob Fitzpatrick');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1116, 'برد استون', '<p>براد استون نویسنده و روزنامه نگار آمریکایی است که برای <em>نیویورک تایمز</em> و <em>هفته تجاری بلومبرگ</em> در میان سایر نشریات می نویسد.</p>', '2023-01-27 01:59:53.90148', '2023-01-27 01:59:53.90148', NULL, 'Brad Stone');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1117, 'آنا ملر', '<p>آنا ملر مربی و مشاور بریتانیایی تعادل بین کار و زندگی است. ملر با سابقه ای در روانشناسی شغلی، 25 سال گذشته را صرف کمک به زنان حرفه ای برای ایجاد تعادل مجدد در مشاغل شرکتی خود کرده است. ملر دارای مدرک کارشناسی ارشد در رفتار سازمانی و عضو موسسه منشور کارکنان و توسعه است.</p>', '2023-01-27 02:00:01.151361', '2023-01-27 02:00:01.151361', NULL, 'Anna Meller');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1118, 'دن سالیوان با بنجامین هاردی', '<p>دن سالیوان یک مربی، مشاور و برنامه‌ریز استراتژیک کارآفرین است. سالیوان به عنوان موسس و رئیس شرکت The Strategic Coach به کارآفرینان در سراسر جهان در دستیابی به اهداف شخصی و حرفه ای کمک کرده است. او نویسنده یا نویسنده کتاب‌ها و نشریات متعددی است، از جمله <em>می‌خواهید قهرمان چه کسی شوید؟</em> و <em>شکاف و سود</em>.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1119, 'پیتر وولبن', '<p>پیتر وولبن یک جنگل‌بان آلمانی و نویسنده پرفروش <em>نیویورک تایمز</em>است. <em>زندگی پنهان درختان</em>. او سالها به عنوان کارمند دولتی در کمیسیون جنگلداری کار کرد. او اکنون در جنگل خود کار می کند، جایی که سعی می کند از روش های جنگلداری جایگزین و سازگار با محیط زیست استفاده کند.</p>', '2023-01-27 02:00:22.499527', '2023-01-27 02:00:22.499527', NULL, 'Peter Wohlleben');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1120, 'جوئل گرینبلات', '<p>جوئل گرینبلات یک مدیر و نویسنده آمریکایی است. کتاب‌های او شامل <em>شما می‌توانید نابغه بازار سهام باشید: مخفی‌گاه‌های مخفی سودهای بازار سهام را کشف کنید</em> و <em>راز بزرگ برای سرمایه‌گذار کوچک: مسیری جدید برای موفقیت در سرمایه‌گذاری بلندمدت< /em>. او همچنین به عنوان استاد کمکی در دانشکده کسب و کار فارغ التحصیل دانشگاه کلمبیا تدریس می کند.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1121, 'دیوید کیدر', '<p>دیوید کیدر نویسنده، سخنران و کارآفرینی است که شرکت نرم افزار تبلیغاتی Clickable را تأسیس کرده است. او در حال حاضر مدیر عامل شرکت Bionic است که به دنبال ایجاد ذهنیت های رشد در بزرگترین شرکت های جهان است. کریستینا والاس یک کارآفرین سریالی، معاون رشد در Bionic و مجری مشترک <em>Limit Does Not Exist</em>، پادکست Forbes است که بر تقاطع آموزش STEM و هنر متمرکز است.</p >', '2023-01-27 02:00:38.139057', '2023-01-27 02:00:38.139057', NULL, 'David Kidder');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1122, 'آدام رادرفورد', '<p>آدام رادرفورد یک نویسنده علمی، پادکست و پخش کننده است. او یک شخصیت ثابت بی‌بی‌سی و مشارکت‌کننده مکرر <em>گاردین</em> است، او همچنین نویسنده چندین کتاب در مورد تکامل انسان است. او دارای دکترای ژنتیک از دانشگاه کالج لندن است و سخنران محبوبی در بین مخاطبان دانشگاهی و غیر روحانی است.</p>', '2023-01-27 02:00:52.07215', '2023-01-27 02:00:52.07215', NULL, 'Adam Rutherford');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1123, 'دنی اینی', '<p>دنی اینی موسس و مدیر عامل Mirasee، یک شرکت آموزش کسب و کار آنلاین است. او سخنرانی‌های مهمان در دانشگاه‌هایی مانند مک گیل و ییل داشته است و نویسنده پرفروش 9 کتاب، از جمله <em>Teach and Grow Rich</em> و <em>The Audience Revolution است. </em></p>', '2023-01-27 02:00:59.784348', '2023-01-27 02:00:59.784348', NULL, 'Danny Iny');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1124, 'ویتنی جانسون', '<p> ویتنی جانسون یکی از بنیانگذاران تاثیرگذار Rose Park Advisors و مدافع قوی استفاده از اختلال به عنوان راهی برای پیشرفت، هم در زندگی و هم در کار است. او همچنین یکی از همکاران <em>Harvard Business Review</em> و نویسنده چندین کتاب پرفروش، از جمله <em>Dare، Dream، Do</em> است.</p>', '2023-01-27 02:01:13.109544', '2023-01-27 02:01:13.109544', NULL, 'Whitney Johnson');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1125, 'کریستوفر شلینگ', '<p>کریستوفر شلینگ یک سرمایه گذار نهادی با تجربه است که در طول 20 سال زندگی حرفه ای خود 5 میلیارد دلار اختصاص داده است. او در حال حاضر به عنوان مدیر عامل Windmuehle Funds در آستین، تگزاس فعالیت می کند. او همچنین در نشریاتی مانند <em>Institutional Investor</em> و<em> Wall Street Journal</em> مشارکت دارد.</p>', '2023-01-27 02:01:21.034424', '2023-01-27 02:01:21.034424', NULL, 'Christopher Schelling');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1126, 'پیتر داوورگن و جین لیستر', '<p>پل داوورگن، استاد علوم سیاسی و مدیر موسسه لیو برای مسائل جهانی در دانشگاه بریتیش کلمبیا است. او چندین کتاب از جمله <em>Timber</em> و <em>Shadows of Consumption: Consequences for the Global Environment</em> را تالیف کرده و در نویسندگی مشترکی نیز بر عهده داشته است. </p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1127, 'گرگ بروکس', '<p>گرگ بروکس یک کارآفرین سریالی و استراتژیست بازاریابی است که بودجه تبلیغاتی چند میلیون دلاری را مدیریت کرده است.</p>', '2023-01-27 02:01:37.532692', '2023-01-27 02:01:37.532692', NULL, 'Greg Brooks');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1128, 'تونی حسیه', '<p>تونی هسیه یک کارآفرین آمریکایی و سرمایه‌دار خطرپذیر است که بیشتر به عنوان مدیر عامل Zappos.com شناخته می‌شود. او در سال 1999 شرکت قبلی خود، LinkExchange را به قیمت 265 میلیون دلار به مایکروسافت فروخت.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1129, 'رشمی بانسال', '<p>رشمی بانسال یک کارآفرین هندی و نویسنده غیرداستانی است. او دارای مدرک MBA از موسسه مدیریت هند است و هشت کتاب از جمله <em>گرسنه بمانید احمق بمانید</em> (2008)، <em>Poor Little Rich Slum </em>(2012) و <em> نوشته است. آشپزخانه خود خدا</em> (2017).</p>', '2023-01-27 02:01:53.820874', '2023-01-27 02:01:53.820874', NULL, 'Rashmi Bansal');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1130, 'گای وینچ', '<p>گای وینچ یک روانشناس شاغل در شهر نیویورک است و به دلیل تحقیقاتش در مورد سلامت عاطفی شهرت دارد. سخنرانی او در TED "چرا همه ما نیاز به تمرین کمک های اولیه احساسی داریم" توسط میلیون ها نفر در سراسر جهان مشاهده شده است.</p>', '2023-01-27 02:02:01.840669', '2023-01-27 02:02:01.840669', NULL, 'Guy Winch');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1131, 'جری کولونا', '<p>جری کولونا مدیر عامل و یکی از بنیانگذاران Reboot.io، یک شرکت مربیگری اجرایی است که تمرکز اصلی آن بر توسعه رهبرانی با انسانیت، انعطاف پذیری و استعداد است. او همچنین یکی از موفق‌ترین برنامه‌های سرمایه‌گذاری در مراحل اولیه در نیویورک، Flatiron Partners را تأسیس کرد و شریک سابق JPMorgan Partners است. او در بولدر، کلرادو زندگی می کند.</p>', '2023-01-27 02:02:09.278443', '2023-01-27 02:02:09.278443', NULL, 'Jerry Colonna');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1132, 'سوتری ویلسون', '<p>سوتری ویلسون یک کارآفرین سریالی است که اولین سرمایه گذاری خود را در نوجوانی آغاز کرد. او دو شرکت تاسیس کرده و اولین زن سیاهپوست در نیواورلئان است که بیش از یک میلیون دلار سرمایه سرمایه گذاری کرده است. در سال 2010، ویلسون جایزه جفرسون را دریافت کرد - چیزی که جایزه نوبل برای خدمات عمومی در نظر گرفته می‌شود - و او در رسانه‌های خبری به دلیل فعالیت‌هایش در تجارت و فناوری معرفی شده است.</p>', '2023-01-27 02:02:17.225698', '2023-01-27 02:02:17.225698', NULL, 'Sevetri Wilson');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1133, 'تاد هنری با ران پنر', '<p>تاد هنری بنیانگذار و مدیر عامل Accidental Creative است، یک شرکت مشاوره که توسعه شخصی و خلاقیت را ارتقا می دهد. او همچنین نویسنده کتاب <em>خلاق تصادفی</em> است.</p>', '2023-01-27 02:02:19.538843', '2023-01-27 02:02:19.538843', NULL, 'Todd Henry with Ron Penner');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1134, 'کن بلانچارد', '<p> کن بلانچارد یک کارآفرین و نویسنده متخصص در مسائل مدیریت است. کتاب پرفروش او <em>مدیر یک دقیقه ای</em> بیش از 15 میلیون نسخه فروخت. شرکت او، Ken Blanchard Companies، خدمات مشاوره و آموزش مدیریت بین المللی ارائه می دهد.</p>', '2023-01-27 02:02:26.543715', '2023-01-27 02:02:26.543715', NULL, 'Ken Blanchard');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1135, 'ساندرا آمودت', '<p>ساندرا آمودت یک عصب شناس و نویسنده علوم محبوب است. او سردبیر سابق <em>علوم اعصاب طبیعت</em> و نویسنده کتاب های <em>به مغز شما خوش آمدید</em>و <em>به مغز کودک خود خوش آمدید</em>< است. /p>', '2023-01-27 02:02:34.687237', '2023-01-27 02:02:34.687237', NULL, 'Sandra Aamodt');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1136, 'کاترین گراهام', '<p>کاترین گراهام ناشر <em>واشنگتن پست</em> از سال 1963 تا 1979 بود. به عنوان اولین زنی که ریاست یک رسانه بزرگ آمریکایی را بر عهده گرفت، گراهام بر کار روزنامه در سالهای پرتلاطم ریاست جمهوری نیکسون نظارت داشت. و <em>پست</em> افشای رسوایی واترگیت.</p>', '2023-01-27 02:02:42.304676', '2023-01-27 02:02:42.304676', NULL, 'Katharine Graham');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1137, 'راجر کانرز و تام اسمیت', '<p>راجر کانرز و تام اسمیت از بنیانگذاران شرکت مشاوره مدیریت و آموزش رهبری، Partners In Leadership, Inc هستند. آنها با هم سه <em>The</em> <em>New York Times </em را نوشته اند. >کتاب های پرفروش.</p>', '2023-01-27 02:02:55.511043', '2023-01-27 02:02:55.511043', NULL, 'Roger Connors and Tom Smith');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1138, 'لیزا مارگونلی', '<p>لیزا مارگونلی یک روزنامه نگار برنده جایزه و نویسنده <em>نفت روی مغز</em> است که یک مطالعه پرفروش در مورد صنعت سوخت فسیلی است. او یک سردبیر ارشد در رسانه جهانی <em> میدان عمومی Zócalo</em> است. او درباره علم، سیاست و فناوری برای <em>Atlantic</em>، <em>Wired</em>، <em>Scientific American</em> و <em>New York Times</em> نوشته است. em>، در میان دیگران. او در حال حاضر در ایالات متحده مستقر است. </p>', '2023-01-27 02:03:03.537586', '2023-01-27 02:03:03.537586', NULL, 'Lisa Margonelli');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1139, 'کیم اسکات', '<p> کیم اسکات یک مدیر عامل با تجربه است که برای شرکت‌های مختلف دره سیلیکون از جمله توییتر، دراپ باکس و گوگل کار کرده است. او یکی از اعضای هیئت علمی سابق دانشگاه اپل و مدیر عامل فعلی Candor, Inc. است - شرکتی که او برای تامین منابع بیشتر برای مدیران و روسایی که نیاز به حمایت دارند، تأسیس کرد.</p>', '2023-01-27 02:03:11.147579', '2023-01-27 02:03:11.147579', NULL, 'Kim Scott');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1140, 'نورمن وینسنت پیل', '<p>نورمن وینسنت پیل وزیری در شهر نیویورک بود که به خاطر آثار پرفروشی مانند <em>هنر</em> <em>هنر</em> <em></em> <em>زندگی</em> شهرت داشت. >، <em>الهام بخش</em> <em>پیام</em> <em>برای</em> <em>روزانه</em> <em>زندگی</em>، و <em>A</em> em> <em>راهنما</em> <em>برای</em> <em>با اعتماد به نفس</em> <em>زندگی</em>. او همچنین در تلویزیون و رادیو فعال بود و بنیانگذار بنیاد مثبت اندیشی بود.</p>', '2023-01-27 02:03:18.738262', '2023-01-27 02:03:18.738262', NULL, 'Norman Vincent Peale');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1141, 'کاترین می', '<p>کاترین می یک نویسنده داستانی و غیرداستانی است که شیفتگی خاصی به ریتم های دنیای طبیعی دارد. از دیگر کتاب‌های او می‌توان به <em>الکتریسیته هر موجود زنده</em> و <em>باشگاه شنای Whitstable High Tide</em> اشاره کرد. او قبلاً مدیر برنامه نویسندگی خلاق در دانشگاه کانتربری کریست چرچ بود.</p>', '2023-01-27 02:03:32.738805', '2023-01-27 02:03:32.738805', NULL, 'Katherine May');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1142, 'دیوید کوامن', '<p>دیوید کوامن نویسنده پانزده کتاب است. او که نویسنده ای برای <em>نشنال جئوگرافیک</em> است، مقالاتی را نیز در <em>نیویورک تایمز بوک ریویو</em>، <em> آتلانتیک</em> و <em>هارپرز</em> منتشر کرده است. em>. کتاب‌های قبلی او عبارتند از <em>Spillover: Animal Infections and the Human Next Pandemic</em> که فینالیست جایزه حلقه ملی منتقدان کتاب در ادبیات غیرداستانی بود و <em>شمپانزه و رودخانه: چگونه ایدز از جنگل آفریقا</em>.</p>', '2023-01-27 02:03:40.752344', '2023-01-27 02:03:40.752344', NULL, 'David Quammen');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1143, 'جیمز آلتوچر و کلودیا آزولا آلتوچر', '<p>جیمز آلتوچر یک کارآفرین، استاد شطرنج، معلم معنوی و نویسنده است که دوازده کتاب نوشته است، از جمله کتاب های پرفروش <em>خودت را انتخاب کن</em> و <em>من کور بودم اما اکنون می بینم</em> .</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1144, 'اندرو اس. گروو', '<p>اندرو اس. گرو، مهندس و تاجر مجارستانی الاصل، رئیس و مدیر عامل سابق اینتل است. او دوره‌هایی را در دانشکده بازرگانی دانشگاه استنفورد تدریس می‌کند.</p>', '2023-01-27 02:03:56.614117', '2023-01-27 02:03:56.614117', NULL, 'Andrew S. Grove');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1145, 'بث کامستاک با تال راز', '<p> بت کامستاک اولین زن معاون جنرال الکتریک بود و همچنین به عنوان مدیر ارشد بازاریابی و بازرگانی این شرکت خدمت کرد. در هر دو سال 2015 و 2016، <em>مجله فوربس</em> کامستاک را یکی از 100 زن قدرتمند جهان معرفی کرد.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1146, 'بردلی تاسک', '<p> بردلی تاسک بنیانگذار Tusk Strategies است، یک شرکت مشاوره که به استارت‌آپ‌ها کمک می‌کند تا مشکلات سیاسی را حل کنند، و Tusk Ventures، یک صندوق سرمایه‌گذاری خطرپذیر برای استارت‌آپ‌های در معرض سیاسی. او به عنوان مدیر مبارزات انتخاباتی شهردار نیویورک، مایکل بلومبرگ، مدیر ارتباطات سناتور چاک شومر، و خود معاون فرماندار ایلینوی بوده است. او برای <em>Observer</em> می نویسد و پادکست را میزبانی می کند، <em>Firewall</em>.</p>', '2023-01-27 02:04:12.701706', '2023-01-27 02:04:12.701706', NULL, 'Bradley Tusk');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1147, 'داچر کلتنر', '<p> داچر کلتنر استاد روانشناسی در دانشگاه کالیفرنیا، برکلی است. او در طول زندگی حرفه ای خود بیش از 190 مقاله در نشریاتی مانند<em>نیویورک تایمز</em>و<em>وال استریت ژورنال</em> منتشر کرده است. او همچنین نویسنده چندین کتاب پرفروش است، از جمله <em>Born to Be Good: The Science of a Meaningful Life</em> و <em>The Compassionate Instinct</em>.</p>', '2023-01-27 02:04:20.51651', '2023-01-27 02:04:20.51651', NULL, 'Dacher Keltner');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1148, 'الکساندرا واتکینز', '<p>الکساندرا واتکینز موسس شرکت نامگذاری Eat My Words و یک متخصص شناخته شده در زمینه نام های تجاری است.</p>', '2023-01-27 02:04:33.645909', '2023-01-27 02:04:33.645909', NULL, 'Alexandra Watkins');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1149, 'حالا پدرم', '<p>آلن آلدا یک بازیگر برنده جایزه است که برنده هفت جایزه امی شده است. او احتمالاً بیشتر برای بازی در نقش Hawkeye Pierce در <em>M*A*S*H</em> مشهور است. پس از میزبانی <em>Scientific American Frontiers</em> PBS، آلدا الهام گرفت تا به دانشمندان کمک کند تا راه‌های بهتری برای برقراری ارتباط پیدا کنند.</p>', '2023-01-27 02:04:41.473887', '2023-01-27 02:04:41.473887', NULL, 'Alan Alda');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1150, 'آلن مور', '<p>آلن مور یک طراح، هنرمند و کارآفرین بریتانیایی است. او سمت‌های مشاوره‌ای در شرکت‌های بزرگی مانند هیولت پاکارد، مایکروسافت و کوکا کولا داشته است تا به آنها کمک کند تا کسب‌وکار خود را بهبود بخشند و محصولات و خدمات بهتری ارائه دهند. او نویسنده چهار کتاب در زمینه خلاقیت، بازاریابی و طراحی کسب و کار از جمله <em>بدون خطوط مستقیم: ایجاد حس دنیای غیرخطی ما</em> (2011) است. مور تلاش می کند تا زندگی خود را به زیبایی هر روز رهبری کند.</p>', '2023-01-27 02:04:54.572253', '2023-01-27 02:04:54.572253', NULL, 'Alan Moore');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1151, 'فریتیوف کاپرا', '<p>فریتیوف کاپرا دارای مدرک دکترای فیزیک نظری از دانشگاه وین است. او نویسنده و سخنران پرکار جنبه های فلسفی علم مدرن است. از دیگر کتاب‌های کاپرا می‌توان به <em>نقطه عطف</em>، <em>عقل غیرمتعارف</em> و <em>Web of Life</em> اشاره کرد.</p>', '2023-01-27 02:05:08.411837', '2023-01-27 02:05:08.411837', NULL, 'Fritjof Capra');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1152, 'کارولین وب', '<p>کارولین وب یک مشاور مدیریتی است که قبل از راه‌اندازی شرکت خود، Sevenshift، به مدت 12 سال برای McKinsey کار می‌کرد، که متخصص در کمک به مشتریان برای افزایش بهره‌وری، انرژی و اشتیاق است. کارهای او در <em>نیویورک تایمز</em> و <em>فوربس</em> به نمایش درآمده است.</p>', '2023-01-27 02:05:15.516906', '2023-01-27 02:05:15.516906', NULL, 'Caroline Webb');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1153, 'جوکو ویلینک و لیف بابین', '<p>نویسندگان به عنوان افسران نیروی دریایی SEAL در طول نبرد رمادی، در عراق خدمت کردند و رهبری آنچه را که با افتخارترین واحد عملیات ویژه در جنگ عراق تبدیل شد، بر عهده داشتند. آنها اکنون یک شرکت مشاوره رهبری را اداره می کنند که به رهبران کسب و کار می آموزد که چگونه تیم های خود را با عملکرد بالا بسازند.</p>', '2023-01-27 02:05:22.708108', '2023-01-27 02:05:22.708108', NULL, 'Jocko Willink and Leif Babin');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1154, 'ویلیام یوری', '<p>ویلیام اوری یکی از بنیانگذاران برنامه مذاکره هاروارد است، او نویسنده آکادمیک و پرفروش <em>Getting to Yes</em> و چندین کتاب دیگر است. اوری پس از کار به عنوان میانجی در خاورمیانه و اتحاد جماهیر شوروی، با رئیس جمهور جیمی کارتر همکاری کرد تا شبکه بین المللی مذاکره را راه اندازی کند.</p>', '2023-01-27 02:05:35.568078', '2023-01-27 02:05:35.568078', NULL, 'William Ury');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1155, 'جان دوئر', '<p>جان دوئر یک سرمایه گذار و سرمایه گذار آمریکایی است که مدیران و بنیانگذاران بی شماری را در مورد جادوی OKR ها راهنمایی کرده است. او علاوه بر کار در شرکت سرمایه‌گذاری مخاطره‌آمیز کلاینر پرکینز، به‌عنوان عضو هیئت مشورتی بهبود اقتصادی پرزیدنت اوباما نیز خدمت کرد.</p>', '2023-01-27 02:05:43.915358', '2023-01-27 02:05:43.915358', NULL, 'John Doerr');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1156, 'استفان مانکوزو', '<p>استفانو مانکوسو استاد گیاه‌شناسی در دانشگاه فلورانس و متخصص برجسته جهان در نوروبیولوژی گیاهی است. او بیش از 250 مقاله علمی و عناوین پرطرفدار مانند<em>Brilliant Green: The Surprising History and Science of Plant Intelligence</em>و <em>The Revolutionary Genius of Plants: A New Understanding of Plant Intelligence and Behavior< منتشر کرده است. /em>.</p>', '2023-01-27 02:05:51.520934', '2023-01-27 02:05:51.520934', NULL, 'Stefano Mancuso');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1157, 'زاخاری وانگ', '<p>زاکاری وانگ یک مشاور مدیریت و مربی رهبری است که در اثربخشی سازمانی و شخصی متخصص است. او با تیم های پروژه، هیئت های بازبینی و انجمن های صنعتی مشورت کرده است. وانگ همچنین در دانشگاه کالیفرنیا، برکلی اکستنشن، و دانشگاه کالیفرنیا، دیویس تدریس می‌کند.</p>', '2023-01-27 02:06:09.843677', '2023-01-27 02:06:09.843677', NULL, 'Zachary Wong');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1158, 'سوزان مک فرسون', '<p>سوزان مک فرسون یک "اتصال سریال" و بنیانگذار و مدیر عامل McPherson Strategies است، یک شرکت مشاوره ارتباطی که بر تقاطع بین برندها و تاثیر اجتماعی تمرکز دارد. او در مجلات <em>Harvard Business Review، Fast Company</em> و <em>Forbes</em> همکاری داشته است.</p>', '2023-01-27 02:06:17.732853', '2023-01-27 02:06:17.732853', NULL, 'Susan McPherson');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1159, 'هوارد شولتز و دوری جونز یانگ', '<p> هاوارد شولتز تاجر آمریکایی و رئیس هیئت مدیره و مدیرعامل استارباکس است. او از یک پیشینه متوسط ​​و اولین فردی در خانواده اش که به دانشگاه رفت، قهوه خانه کوچک را به یک شرکت میلیارد دلاری تبدیل کرد. در سال 2007 او برنده جایزه FIRST برای سرمایه داری مسئول شد.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1160, 'الیور برکمن', '<p>الیور برکمن یک روزنامه نگار بریتانیایی است که ستون هفتگی پرطرفدار "این ستون زندگی شما را تغییر خواهد داد" را برای <em>The</em> <em>Guardian</em> می نویسد. او جایزه روزنامه‌نگار جوان سال انجمن مطبوعات خارجی را از آن خود کرد و در فهرست نهایی جایزه اورول قرار گرفت. <em></em> <em>پادزهر</em> (2013) دومین کتاب اوست. او در حال حاضر در شهر نیویورک زندگی می کند. </p>', '2023-01-27 02:06:33.172062', '2023-01-27 02:06:33.172062', NULL, 'Oliver Burkeman');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1161, 'آتل گاونده', '<p> Atul Gawande پزشک، نویسنده، محقق و استاد دانشکده بهداشت عمومی هاروارد است. او دو کتاب دیگر به نام‌های <em>عوارض</em> (2007) و <em>مانیفست فهرست چک </em>(2011) نوشته است.</p>', '2023-01-27 02:06:40.997804', '2023-01-27 02:06:40.997804', NULL, 'Atul Gawande');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1162, 'دیوید اس کیدر', '<p>دیوید اس. کیدر یک کارآفرین و نویسنده است. اخیراً، او شرکت بازاریابی آنلاین Clickable را تأسیس کرد و در سال 2008 جایزه کارآفرین سال ارنست و جوان را دریافت کرد.</p>', '2023-01-27 02:06:49.456795', '2023-01-27 02:06:49.456795', NULL, 'David S. Kidder');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1163, 'رز جورج', '<p>رز جورج نویسنده و روزنامه نگار بریتانیایی است که آثارش در <em>The</em> <em>گاردین</em>و <em>نیویورک تایمز منتشر شده است. </em>کتاب‌های قبلی او شامل <em>نود درصد از همه چیز </em>(2013)، نگاهی به صنعت حمل و نقل بین‌المللی، و <em>نیاز بزرگ </em>(2008)<strong>، < /strong>پژوهشی در دنیای زباله‌های انسانی و بهداشت.</p>', '2023-01-27 02:07:02.862013', '2023-01-27 02:07:02.862013', NULL, 'Rose George');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1164, 'کوین روز', '<p>کوین روز نویسنده <em>شاگرد بعید</em> است و برای <em> نیویورک تایمز</em> و <em>مجله نیویورک</em> نوشته است. او در حال حاضر سردبیر ارشد و تهیه‌کننده اجرایی سرمایه‌گذاری مشترک <em>ABC</em>–<em>Univision</em>، <em>Fusion</em> است.</p>', '2023-01-27 02:07:10.869252', '2023-01-27 02:07:10.869252', NULL, 'Kevin Roose');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1165, 'میچ میرسون', '<p>میچ میرسون مشاور، سخنران عمومی، ترانه سرا و نویسنده 11 کتاب در زمینه تجارت و توسعه شخصی است. او از پزشکان بسیار ماهر خواسته است که بهترین نکات خود را در <em>رازهای موفقیت سوپراستارهای بازاریابی آنلاین</em> به اشتراک بگذارند.</p>', '2023-01-27 02:07:18.191903', '2023-01-27 02:07:18.191903', NULL, 'Mitch Meyerson');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1166, 'وندی کی اسمیت', '<p>وندی اسمیت استاد مدیریت در دانشگاه دلاور است. ماریان لوئیس رئیس دانشکده بازرگانی لیندنر در دانشگاه سینسیناتی است. هر دو رهبران فکری در زمینه پارادوکس سازمانی هستند و بررسی کرده اند که چگونه برندها، شرکت ها و دولت ها می توانند به طور موثر به موقعیت های متناقض واکنش نشان دهند. </p>', '2023-01-27 02:07:25.252945', '2023-01-27 02:07:25.252945', NULL, 'Wendy K. Smith');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1167, 'ها جون چانگ', '<p>ها-جون چانگ یکی از منتقدان برجسته اقتصاد بازار آزاد است. او استاد دانشگاه کمبریج و متخصص در اقتصاد نهادی و توسعه است و کتاب‌های بسیار مورد بحث درباره توسعه اقتصادی مانند <em>بد</em> <em>سامری‌ها</em> و <em>لگد زدن</em> را منتشر کرده است. em> دور</em> <em></em> <em>نردبان</em>.</p>', '2023-01-27 02:07:38.528971', '2023-01-27 02:07:38.528971', NULL, 'Ha-Joon Chang');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1168, 'جی بائر و دنیل لمین', '<p>جی بائر بنیانگذار Convince & Convert است، یک شرکت مشاوره متخصص در ایجاد و حفظ پایگاه مشتری. او نویسنده <em>متنفرانتان را در آغوش بگیرید</em>و <em>جوانمردی</em> است. دانیل لمین رهبر سابق ارتباطات گوگل و یکی از بنیانگذاران پلتفرم تغذیه سالم Selectivor است. او نویسنده <em>Manipurated.</em></p> است', '2023-01-27 02:07:45.549952', '2023-01-27 02:07:45.549952', NULL, 'Jay Baer and Daniel Lemin');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1169, 'مایکل تی اوسترهولم و مارک اولشاکر', '<p>دکتر مایکل اوسترهولم یک اپیدمیولوژیست مشهور جهان است. او مدیر مؤسس مرکز تحقیقات و سیاست بیماری‌های عفونی (CIDRAP) در دانشگاه مینه‌سوتا و همچنین کرسی وقف ریاست‌جمهوری مک نایت در بهداشت عمومی است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1170, 'گای اسپایر', '<p>گای اسپایر یک سرمایه گذار مستقر در زوریخ است که به مدت 17 سال <em>صندوق آکوامارین</em> را اداره کرد و به یک چهره پیشرو در شبکه سرمایه گذاران ارزش تبدیل شد. کارهای او از وارن بافت و مهنیش پابرای الهام گرفته شده است و او اکنون یک مفسر معمولی برای رسانه های مالی است.</p>', '2023-01-27 02:08:05.147708', '2023-01-27 02:08:05.147708', NULL, 'Guy Spier');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1171, 'کارولین وبر', '<p>کارولین وبر متخصص فرهنگ فرانسه در قرن هجدهم است. قبل از اینکه استادیار ادبیات فرانسه و ادبیات تطبیقی ​​در کالج بارنارد دانشگاه کلمبیا شود، در دانشگاه پنسیلوانیا و دانشگاه ییل تدریس می کرد. نوشته های او در <em>Vogue، Bookforum</em>، <em>واشنگتن پست</em> و <em>نیویورک تایمز</em> ظاهر شده است. </p>', '2023-01-27 02:08:12.548148', '2023-01-27 02:08:12.548148', NULL, 'Caroline Weber');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1172, 'ریچارد کارلسون', '<p>ریچ کارلسون روان‌درمانگر با مجموعه‌ای از چیزهای کوچک عرق نکن، که در بیش از 130 کشور منتشر شد، به محبوبیت جهانی تبدیل شد. کارلسون در مدیریت استرس به زبان ساده تخصص داشت: عبارت جذاب او به بخش مهمی از فرهنگ آمریکایی تبدیل شد.</p>', '2023-01-27 02:08:25.154253', '2023-01-27 02:08:25.154253', NULL, 'Richard Carlson');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1173, 'جان اچ. نایت و ریچارد منینگ', '<p>John J. Ratey، MD، دانشیار بالینی روانپزشکی در دانشکده پزشکی هاروارد و نویسنده کتاب پرفروش <em>Spark</em> است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1174, 'توسط سری سوامی ساچیدانانا ترجمه و تفسیر شده است', '<p>پاتانجالی یک معلم روحانی باستانی هندی بود - یا احتمالاً نام، یا به تعدادی از معلمان داده شده است. او بین 500 سال قبل از میلاد تا 300 پس از میلاد زندگی می کرد و سوتراهای او یکی از متون اساسی یوگا را تشکیل می دهند. </p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1175, 'میرا کوتاند', '<p>Meera Kothand یک استراتژیست بازاریابی آنلاین است که متخصص در کمک به وبلاگ نویسان و کارآفرینان جدید برای راه اندازی و راه اندازی مشاغل خود است. او همچنین یک وبلاگ نویس و صاحب meerakothand.com است.</p>', '2023-01-27 02:08:47.848837', '2023-01-27 02:08:47.848837', NULL, 'Meera Kothand');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1190, 'التون جان', '<p> سر التون جان، فرمانده عالی ترین نظم امپراتوری بریتانیا، خواننده، ترانه سرا و آهنگساز انگلیسی است. او یکی از پرفروش ترین هنرمندان موسیقی جهان است و بیش از 300 میلیون آلبوم به فروش رسانده است. جان همچنین پنج جایزه گرمی، پنج جایزه بریت و یک جایزه اسکار دریافت کرده است.</p>', '2023-01-27 02:10:48.667988', '2023-01-27 02:10:48.667988', NULL, 'Elton John');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1176, 'بی جی فاگ', '<p>بی‌جی فاگ متخصص فناوری‌های متقاعدکننده و روشی که محصولات محاسباتی تعاملی و نرم‌افزار بر رفتار ما تأثیر می‌گذارند است. موسس آزمایشگاه طراحی رفتار در دانشگاه استنفورد، فاگ از تخصص علمی خود برای کمک به نوآوران صنعت کمک می کند تا به نحوه عملکرد واقعی رفتار انسان دست پیدا کنند. <em>عادات کوچک</em> پنجمین کتاب اوست. </p>', '2023-01-27 02:08:55.79286', '2023-01-27 02:08:55.79286', NULL, 'BJ Fogg');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1177, 'لورن اسمیت برودی', '<p>لورن اسمیت برودی سردبیر اجرایی سابق مجله <em>Glamour</em>و بنیانگذار جنبش سه ماهه پنجم است که والدین و مشاغل جدید را گرد هم می آورد و به آنها کمک می کند تا مکان های کاری مناسب برای خانواده ایجاد کنند.</p>', '2023-01-27 02:09:03.123656', '2023-01-27 02:09:03.123656', NULL, 'Lauren Smith Brody');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1178, 'راه را بنویس', '<p>میچیو کاکو یک فیزیکدان و مدرس علم مشهور جهان است. او استاد فیزیک در دانشگاه سیتی نیویورک است و چندین کتاب پرفروش از جمله <em> فراتر از اینشتین، آینده بشریت</em>، <em>آینده ذهن</em> و <em> فیزیک غیرممکن</em>.</p>', '2023-01-27 02:09:10.91496', '2023-01-27 02:09:10.91496', NULL, 'Michio Kaku');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1179, 'برج تینا', '<p> تینا تاور یک کارآفرین و نویسنده است. او برنده جایزه زن تاجر جوان سال Telstra و قهرمان کسب و کار استرالیا شده است. دوره های آنلاین او به صدها نفر آموزش داده است که چگونه کسب و کار آنلاین خود را ایجاد کنند، و برنامه او Her Empire Builder به ویژه برای کمک به زنان در دستیابی به رویاهای تجاری خود طراحی شده است.</p>', '2023-01-27 02:09:18.156048', '2023-01-27 02:09:18.156048', NULL, 'Tina Tower');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1180, 'باربارا کارلاس', '<p>باربارا کارلاس یک مربی زندگی، مربی جنسی، تسهیل کننده کارگاه، مدرس دانشگاه، سخنران انگیزشی، و هنرمند تئاتر است. او همچنین نویسنده <em>خلسه ضروری است: راهنمای عملی برای رابطه جنسی، روابط و خیلی بیشتر</em>، و <em>محبت مجلل: الهامات تانتریک برای شور و لذت</em> است.</em>. p>', '2023-01-27 02:09:25.603088', '2023-01-27 02:09:25.603088', NULL, 'Barbara Carrellas');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1181, 'گلنون دویل', '<p>گلنون دویل یک خاطره نویس معمولی نیست. کتاب‌های روح‌انگیز او، از جمله <em>جنگجوی عشق </em>و <em>رام نشده</em>، پرفروش‌ترین کتاب‌های چند میلیون نسخه‌ای هستند. دویل اپرا و ادل را از جمله طرفداران بسیار خود می داند. مجله <em>People </em> او را "قدیس حامی توانمندسازی زنان" توصیف کرده است. دویل علاوه بر نویسنده بودن، یک فعال، سخنران و بنیانگذار سازمان غیرانتفاعی Together Rising نیز هست.</p>', '2023-01-27 02:09:38.909176', '2023-01-27 02:09:38.909176', NULL, 'Glennon Doyle');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1182, 'جان کی', '<p>جان کی استاد اقتصاد است و از سال 1970 عضو کالج سنت جان در دانشگاه آکسفورد بوده است. او همچنین به طور منظم در <em>فایننشال تایمز</em> و نویسنده کتاب ها همکاری می کند. <em>انحراف</em> و <em>طولانی و کوتاه آن</em>.</p>', '2023-01-27 02:09:46.618844', '2023-01-27 02:09:46.618844', NULL, 'John Kay');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1183, 'اینگرید فتل لی', '<p>اینگرید فتل لی یک طراح است که وبلاگ طراحی خود را با نام <em>زیبایی شناسی شادی</em> اداره می کند. او مقالاتی را در <em>نیویورک تایمز</em>، <em>روانشناسی امروز</em>، و <em>Wired</em> ارائه کرده است، و در سال 2018 یک سخنرانی پربازدید در TED در مورد طراحی ارائه کرده است. p>', '2023-01-27 02:09:54.506197', '2023-01-27 02:09:54.506197', NULL, 'Ingrid Fetell Lee');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1184, 'جنی آلن', '<p>جنی آلن IF:Gathering را تأسیس کرد، یک سازمان عظیم و مجموعه ای از رویدادها که به زنان کمک می کند کلام خدا را گسترش دهند. او به‌خاطر فعالیت‌های رسانه‌ای‌اش شناخته می‌شود و چندین کتاب نوشته است، از جمله <em>بی‌قرار</em> و <em>هیچ چیز برای اثبات</em>. او همچنین در بسیاری از رویدادها صحبت می کند و یک پادکست محبوب دارد.</p>', '2023-01-27 02:10:02.28772', '2023-01-27 02:10:02.28772', NULL, 'Jennie Allen');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1185, 'بنی لوئیس', '<p>بنی لوئیس نویسنده و چند زبان ایرلندی با سابقه تحصیل و مهندسی برق است. او به بیش از دوازده زبان از جمله چینی ماندارین و زبان اشاره آمریکایی صحبت می کند، در دو کنفرانس TEDx ارائه کرده است و در سال 2013 به عنوان مسافر سال <em>نشنال جئوگرافیک</em> انتخاب شده است.</p>', '2023-01-27 02:10:10.252979', '2023-01-27 02:10:10.252979', NULL, 'Benny Lewis');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1186, 'لوک سالیوان با سم بنت', '<p>لوک سالیوان به دلیل فعالیت 32 ساله خود در تبلیغات زیر نظر آژانس های برجسته ای مانند Fallon و GSD&M مشهور است. او در حال حاضر رئیس بخش تبلیغات در کالج هنر و طراحی ساوانا است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1187, 'لارنس جی پیتر و ریموند هال', '<p>لارنس جی پیتر به عنوان مشاور، روانشناس مدرسه، مربی زندان، مشاور، استاد و نویسنده کار کرده است. ریموند هال نمایشنامه‌های صحنه‌ای و همچنین مقالاتی برای <em>Esquire</em>، <em>Punch</em>، <em>Maclean''s</em>، در میان سایر نشریات نوشت.</p>', '2023-01-27 02:10:25.632165', '2023-01-27 02:10:25.632165', NULL, 'Laurence J. Peter and Raymond Hull');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1188, 'دیوید والاس ولز', '<p>دیوید والاس ولز ستون نویس و معاون سردبیر مجله <em>نیویورک </em> است. او همچنین یک عضو ملی در New America است، یک اتاق فکر متمرکز بر مسائل سیاست عمومی، از سلامت و جنسیت گرفته تا محیط زیست.</p>', '2023-01-27 02:10:33.751814', '2023-01-27 02:10:33.751814', NULL, 'David Wallace-Wells');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1189, 'مولی بک', '<p>مولی بک خالق وبلاگ سبک زندگی موفق <em>هوشمند، زیبا و بی دست و پا</em> و بنیانگذار Messy Bun، وب سایتی برای ضبط، ویرایش و انتشار پادکست است.</p>', '2023-01-27 02:10:41.084482', '2023-01-27 02:10:41.084482', NULL, 'Molly Beck');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1191, 'آنتونی مرسینو', '<p>آنتونی مرسینو مربی تحول چابک و مدیر برنامه فناوری اطلاعات است.</p>', '2023-01-27 02:10:56.701729', '2023-01-27 02:10:56.701729', NULL, 'Anthony Mersino');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1192, 'جیسون سلک', '<p>دکتر جیسون سلک مدیر آموزش ذهنی سنت لوئیس کاردینالز، یک تیم لیگ برتر بیسبال در ایالات متحده است. او همچنین نویسنده <em>سختی 10 دقیقه ای</em> و <em>سختی اجرایی</em> است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1193, 'Yotam Ottolenghi و Ixta Belfrage', '<p>Yotam Ottolenghi یک سرآشپز، نویسنده غذا، و صاحب رستوران اسرائیلی الاصل است. پرفروش‌ترین کتاب‌های آشپزی او <em>Simple، Plenty، </em>و<em> Plenty More</em> به دلیل ایجاد انقلاب در آشپزی مبتنی بر گیاه مورد تحسین گسترده قرار گرفته است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1194, 'نوح فلمینگ', '<p>نوآ فلمینگ یک متخصص بازاریابی استراتژیک است. او برای<em>Fast Company</em> وبلاگ می نویسد و در بخش تجاری <em>The Globe and Mail</em> مشارکت می کند. او یکی از تنها 36 نفر در سراسر جهان است که برای آموزش برنامه مربیگری و چرخه رشد آلن وایس معتبر هستند.</p>', '2023-01-27 02:11:30.757979', '2023-01-27 02:11:30.757979', NULL, 'Noah Fleming');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1195, 'الکساندر استروالدر و ایو پیگنور', '<p>Alexander Osterwalder یکی از بنیانگذاران Strategyzer، یک راه حل SaaS برای تولید مدل کسب و کار است. او دوره های آنلاین ایجاد مدل های کسب و کار نوآورانه را ارائه می دهد.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1196, 'ماری کوندو و اسکات سوننشاین', '<p>ماری کوندو از زمانی که دختر جوانی بود، علاقه زیادی به مرتب کردن وسایل داشت. او پس از پذیرفتن چند مشتری در بیست سالگی، به زودی اشتیاق خود را به حرفه تبدیل کرد. او به‌عنوان نویسنده <em>جادوی مرتب کردن زندگی در حال تغییر </em> (2011)، روند خود را به اشتراک گذاشت که به روش KonMari معروف است، که خانه‌های بی‌نظم را با خودآگاهی ترکیب می‌کرد. از آن زمان، او به یک نویسنده و شخصیت تلویزیونی مشهور جهانی تبدیل شده است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1197, 'تیموتی کلر با کتی کلر', '<p>تیموتی کلر کشیش کلیسای پروتستان رستگار در شهر نیویورک است. او که فارغ‌التحصیل دانشگاه باکنل، مدرسه علمیه گوردون-کانول و مدرسه علمیه وست مینستر بود، قبل از اینکه به همراه همسرش کتی کلر و سه فرزندشان به شمال برود، در زادگاهش ویرجینیا وزیر بود.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1198, 'کاترین شاناهان و لوک شاناهان', '<p>Catherine Shanahan، M.D یک پزشک خانواده معتبر است که پس از تحصیل در دانشگاه کرنل و دانشکده پزشکی رابرت وود جانسون، بیش از یک دهه در هاوایی طبابت کرده است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1199, 'جولیانا استانکامپیانو', '<p> جولیانا استانکامپیانو مدیر عامل شرکت مشاوره مدیریت اکسیژن است. Stancampiano بیش از 15 سال تجربه در کمک به رهبران ارشد در اجرای استراتژی های تجاری و فروش جدید دارد. </p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1200, 'دیوید هاروی', '<p>دیوید هاروی استاد برجسته مردم شناسی در دانشکده تحصیلات تکمیلی دانشگاه شهر نیویورک است، جایی که او و دانشجویانش دوره ای را در مورد <em>سرمایه</em> کارل مارکس ایجاد کردند که توسط بیش از 2 میلیون نفر در سراسر جهان دانلود شده است. . او همچنین کتاب های مختلفی درباره سرمایه داری نوشته است، از جمله <em>معمای سرمایه</em>.</p>', '2023-01-27 02:12:14.65726', '2023-01-27 02:12:14.65726', NULL, 'David Harvey');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1201, 'برایان گرین', '<p>برایان گرین یک فیزیکدان نظری و نظریه پرداز ریسمان است. او نویسنده پنج کتاب در زمینه فیزیک است که برای عموم مردم نوشته شده است. او به همراه همسرش یکی از بنیانگذاران جشنواره جهانی علم است که هدف آن پرورش عموم مردم آگاه از علم است.</p>', '2023-01-27 02:12:22.113916', '2023-01-27 02:12:22.113916', NULL, 'Brian Greene');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1202, 'دیانا هنری', '<p>دایانا هنری یک نویسنده مواد غذایی برنده جوایز متعدد است. کتاب <em>A Change of Appetite</em>او در سال 2015 توسط انجمن نویسندگان غذا به عنوان کتاب آشپزی سال انتخاب شد و <em>پرنده ای در دست </em>در سال 2016 برنده جایزه جیمز ریش شد. همچنین برای ساندی تلگراف، غذای خوب بی‌بی‌سی و خانه و باغ و بسیاری از رسانه‌های دیگر می‌نویسد. قبل از اینکه نویسنده غذا شود، ده سال به عنوان تهیه کننده تلویزیون برای بی بی سی کار کرد.</p>', '2023-01-27 02:12:29.101718', '2023-01-27 02:12:29.101718', NULL, 'Diana Henry');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1203, 'شان ام. کارول', '<p>شان کارول یک فیزیکدان نظری برنده جایزه است که در موسسه فناوری کالیفرنیا کار می کند. او از سازمان های معتبری مانند بنیاد ملی علوم، ناسا، موسسه فیزیک آمریکا و انجمن سلطنتی لندن تقدیر شده است. در سال 2015 بورسیه گوگنهایم به او اعطا شد. کتاب های دیگر او عبارتند از <em>از ابدیت تا اینجا</em>و <em>ذره در انتهای جهان</em>.</p>', '2023-01-27 02:12:36.692137', '2023-01-27 02:12:36.692137', NULL, 'Sean M. Carroll');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1204, 'اریک فیشر و جیم وودز', '<p>Erik Fisher میزبان <em>Beyond the To-Do List</em> است - پادکستی که به مردم کمک می کند تا بهره وری خود را بهبود بخشند. او به همراه جیم وودز، مربی بهره‌وری، <em>تقویت‌کننده تمرکز: شفافیت بیشتر داشته باشید تصمیم‌های بهتر بگیرید زندگی بهتری داشته باشید</em> نوشته است.</p>', '2023-01-27 02:12:49.436423', '2023-01-27 02:12:49.436423', NULL, 'Erik Fisher and Jim Woods');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1205, 'برایان گریزر و چارلز فیشمن', '<p>برایان گریزر یکی از موفق ترین تهیه کنندگان هالیوود از دهه 1990 بوده است. او فیلم هایی مانند <em>Apollo 13</em> و <em>A Beautiful Mind</em> را تولید کرده است که در سال 2002 برنده جایزه اسکار بهترین فیلم شد.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1206, 'جوکو ویلینک', '<p>جوکو ویلینک به مدت 20 سال به عنوان نیروی دریایی SEAL خدمت کرد و چندین تور در عراق انجام داد. پس از بازگشت به خانه، ویلینک یک مربی SEAL شد و Echelon Front را تأسیس کرد، یک مشاور آموزش رهبری که آموزش SEAL را برای رهبری شرکت اعمال می کند. </p>', '2023-01-27 02:13:04.46808', '2023-01-27 02:13:04.46808', NULL, 'Jocko Willink');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1207, 'سونیا فا طبق برنامه', '<p>سونیا فاروقی فارغ التحصیل دارتموث و بانکدار سابق سرمایه گذاری وال استریت است که شغل شرکتی خود را ترک کرد تا به اصلاح صنعت غذا و بهبود زندگی مردم و حیوانات در همه جا کمک کند.</p>', '2023-01-27 02:13:12.604597', '2023-01-27 02:13:12.604597', NULL, 'Sonia Faruqi');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1208, 'اسکات ریکنز', '<p> اسکات ریکنز تهیه کننده، نویسنده و کارآفرین نامزد جایزه امی است. او قبل از اینکه FIRE را دنبال کند، فیلم‌ها و ویدئوهایی را برای شرکت‌هایی مانند WIRED، Facebook و NBC تولید می‌کرد. او اخیراً مستندی درباره تجربه خود در جنبش FIRE به نام <em>بازی با آتش</em></p> به پایان رساند.', '2023-01-27 02:13:19.965811', '2023-01-27 02:13:19.965811', NULL, 'Scott Rieckens');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1209, 'امی گالو', '<p>امی گالو یک ویرایشگر مشارکت کننده برای <em>Harvard Business Review</em> و میزبان پادکست محبوب <em>زنان در محل کار</em> است. او به طور گسترده در مورد پویایی بین فردی، جنسیت و ارتباطات موثر می نویسد.</p>', '2023-01-27 02:13:27.527828', '2023-01-27 02:13:27.527828', NULL, 'Amy Gallo');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1210, 'پاتریک اسونسون', '<p>پاتریک سونسون در نزدیکی رودخانه‌ای در سوئد بزرگ شد، جایی که پدرش به او ماهیگیری مارماهی را آموخت. او اکنون یک روزنامه نگار فرهنگ و هنر برای روزنامه سوئدی <em>Sydsvenskan</em> است. پاتریک با خانواده اش در مالمو، شهری در جنوب غربی کشور زندگی می کند.</p>', '2023-01-27 02:13:41.527014', '2023-01-27 02:13:41.527014', NULL, 'Patrik Svensson');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1211, 'دیوید بی و', '<p>David B. Agus یک پزشک، سرطان شناس و محقق زیست پزشکی آمریکایی است. علاوه بر این، او استاد پزشکی و مهندسی و رئیس مرکز سرطان Westside در دانشگاه کالیفرنیای جنوبی است. کتاب او، <em>راهنمای کوتاهی برای زندگی طولانی</em>، پرفروش است.</p>', '2023-01-27 02:13:54.778553', '2023-01-27 02:13:54.778553', NULL, 'David B. Agus');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1212, 'دیوید مارکت', '<p>L. دیوید مارکت 28 سال را در نیروی دریایی ایالات متحده سپری کرد تا اینکه مشاور رهبری برای تجارت در سراسر جهان شد. در کتاب پرفروش خود در سال 2013 <em>کشتی را بچرخانید! داستانی واقعی از تبدیل پیروان به رهبران، </em>او دوران خود را به عنوان فرمانده USS <em>سانتافه</em>، یک زیردریایی هسته ای که او کمک کرد از بدترین عملکرد ناوگان به بهترین تبدیل شود، مستند می کند.</p >', '2023-01-27 02:14:02.005836', '2023-01-27 02:14:02.005836', NULL, 'David Marquet');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1213, 'مونیکا سی ورلین و جین ای داتون', '<p>Monica C. Worline یک دانشمند محقق در مرکز تحقیقات و آموزش ترحم و نوع دوستی دانشگاه استنفورد است. او در روانشناسی شفقت و نوع دوستی تخصص دارد. او همچنین مدیر عامل EnlivenWork است، شرکتی که به کسب و کارها در توسعه رهبری دلسوزانه آموزش می دهد.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1214, 'ژول ایوانز', '<p>جولز ایوانز نویسنده، روزنامه نگار و وبلاگ نویس است که مرکز تاریخ احساسات را در دانشگاه لندن نیز اداره می کند. او همچنین رئیس کلوپ فلسفه لندن، بزرگترین باشگاه فلسفه در جهان است. او در http://philosophyforlife.org/</p> وبلاگ می نویسد', '2023-01-27 02:14:28.354349', '2023-01-27 02:14:28.354349', NULL, 'Jules Evans');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1215, 'ماگدالنا گرین', '<p>Magdalena Yesil یک نیروی مستقر در سیلیکون ولی، با سابقه حرفه ای متنوع است که شامل موسس Broadway Angels، گروهی از سرمایه گذاران فرشته زن، و شرکت های فناوری UUnet، CyberCash و MarketPay می شود. در حال حاضر، او یک سرمایه گذار موسس و عضو هیئت مدیره غول محاسباتی مبتنی بر ابر به نام Salesforce است. او اخیراً به عنوان کارآفرین سال مجله <em>Red Herring</em> انتخاب شد.</p>', '2023-01-27 02:14:37.334385', '2023-01-27 02:14:37.334385', NULL, 'Magdalena Yesil');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1216, 'کوین اشتون', '<p>کوین اشتون به عنوان یکی از بنیانگذاران مرکز Auto-ID در MIT، پیشگام نسل جدیدی از محاسبات بود که او آن را "اینترنت اشیا" می نامد. اشتون علاوه بر صحبت در مورد نوآوری و فناوری، بسیاری از استارت‌آپ‌های موفق فناوری و برخی آزمایش‌های اجتماعی جالب را رهبری کرده است.</p>', '2023-01-27 02:14:44.999932', '2023-01-27 02:14:44.999932', NULL, 'Kevin Ashton');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1217, 'لیندا گدس', '<p>لیندا گدس روزنامه نگاری است که در علوم فناوری، زیست شناسی و پزشکی تخصص دارد. او هم به عنوان نویسنده و هم ویراستار برای <em>دانشمند جدید</em> کار کرده است و جایزه بهترین روزنامه نگاری تحقیقی را از انجمن نویسندگان علمی بریتانیا دریافت کرده است.</p>', '2023-01-27 02:14:52.902008', '2023-01-27 02:14:52.902008', NULL, 'Linda Geddes');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1218, 'دیلیپ جست با اسکات لافی', '<p> دیلیپ جست یک روانپزشک عصبی است که بیش از دو دهه را صرف مطالعه اجزای خرد و فرآیند پیری کرده است. او استاد روانپزشکی و علوم اعصاب در دانشگاه کالیفرنیا سن دیگو است و قبلاً رئیس انجمن روانپزشکی آمریکا بود.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1219, 'ویل استور', '<p>ویل استور نویسنده و روزنامه نگار برنده جوایزی است که جوایزی مانند جایزه AFM برای بهترین روزنامه نگاری تحقیقی و جایزه باشگاه مطبوعاتی ملی برای برتری را کسب کرده است. نوشته های او در رسانه هایی مانند <em>نیویورک تایمز</em> و <em>گاردین</em> منتشر شده است و او نویسنده چندین کتاب مورد تحسین منتقدان مانند <em>سلفی: چگونه غرب شد خود وسواس</em>، و رمان او <em>گرسنگی و زوزه کیلیان تنها</em>. او علاوه بر نویسندگی، در کلاس های داستان نویسی تدریس می کند و کارگاه های آموزشی علم قصه گویی را رهبری می کند. </p>', '2023-01-27 02:15:08.875853', '2023-01-27 02:15:08.875853', NULL, 'Will Storr');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1220, 'دون میگل رویز با جانت میلز', '<p>دون میگل روئیز نویسنده و معلم معنوی است که به روش تولتک ها، مردم باستانی میانآمریکایی آموزش دیده است. یکی از کتاب‌های او، <em>چهار توافق، </em>علاوه بر پرفروش‌ترین کتاب <em>نیویورک تایمز</em>، در <em>اپرا</em> نیز به نمایش درآمد. روئیز به طور مرتب سخنرانی می کند و در سرتاسر ایالات متحده اعتکاف برگزار می کند.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1221, 'آچاریا شونیا', '<p>آچاریا شونیا یک معلم معنوی برنده جایزه، رئیس بنیاد خود بیدار و بنیانگذار سازمان غیرانتفاعی بشردوستانه ودیکا گلوبال است. شونیا اولین دارنده اصل و نسب زن در ردیف 2000 ساله معلمان ودایی هندی است. کتاب‌های قبلی او شامل <em>عقل سبک زندگی آیورودا</em> است. </p>', '2023-01-27 02:15:30.616217', '2023-01-27 02:15:30.616217', NULL, 'Acharya Shunya');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1222, 'تی کالین کمبل', '<p>T. کالین کمپبل یک بیوشیمیست و متخصص در زمینه سلامت و تغذیه است. او همچنین پروفسور ممتاز دانشگاه کرنل و نویسنده مشهور و پرفروش کتاب بسیار تأثیرگذار <em> مطالعه چین</em> است. </p>', '2023-01-27 02:15:38.434578', '2023-01-27 02:15:38.434578', NULL, 'T. Colin Campbell');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1223, 'امیلی پی فریمن', '<p>امیلی پی فریمن نویسنده پرفروش‌ترین کتاب‌های <em>وال استریت ژورنال</em> <em>سه شنبه </em>(2015) و <em>یک میلیون راه کوچک</em> است. (2013). هدف پادکست <em>The Next Right Thing</em> او این است که زندگی شخصی و معنوی شنوندگان خود را غنی کند.</p>', '2023-01-27 02:15:52.520299', '2023-01-27 02:15:52.520299', NULL, 'Emily P. Freeman');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1224, 'دیو هالیس', '<p> دیو هالیس یک مدیر سابق دیزنی است که اکنون به عنوان مدیر عامل شرکت Hollis کار می کند، که از رسانه ها برای کمک به افراد برای ایجاد ذهنیت رشد استفاده می کند. هالیس یک شوهر، پدر چهار فرزند و شکاک سابق به خودیاری است. <em>از راه خودت خارج شو</em> اولین کتاب او و پرفروش ترین کتاب <em>نیویورک تایمز</em>است. </p>', '2023-01-27 02:16:00.289163', '2023-01-27 02:16:00.289163', NULL, 'Dave Hollis');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1225, 'جیم مک کلوی', '<p>جیم مک‌کلوی یک کارآفرین و مخترع سریالی است. در سال 2009، او اسکوئر را تأسیس کرد، شرکت پرداخت مالی تحسین شده ای که اکنون بیش از 100 میلیارد دلار ارزش دارد. در سال 2016، او Invisibly را تأسیس کرد که پرداخت های خرد را برای محتوای آنلاین فراهم می کند. مک‌کلوی قبل از فرار کارآفرینی‌اش، زندگی‌اش را به عنوان یک هنرمند شیشه‌ای می‌گذراند.</p>', '2023-01-27 02:16:07.780618', '2023-01-27 02:16:07.780618', NULL, 'Jim McKelvey');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1226, 'کریستین کوه و آشا دورنفست', '<p>دکتر کریستین کوه یک روانشناس متخصص در علوم رفتاری و شناختی است. Koh پست‌های وبلاگ و مقالاتی در مورد سبک زندگی و فرزندپروری می‌نویسد و خود نمونه‌ای عالی از چگونگی ایجاد تعادل سالم بین والدین و حرفه‌ای بودن است. <em>والدین مینیمالیستی</em> اولین کتاب پرفروش او است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1227, 'موسونیوس روفوس', '<p>گایوس موسونیوس روفوس در حدود سال 30 پس از میلاد در منطقه امروزی لاتزیو ایتالیا به دنیا آمد که در آن زمان در قلب امپراتوری رو به رشد روم بود. موسونیوس که در زمان سلطنت نرون معلمی در رم بود، یکی از تأثیرگذارترین فیلسوفان رواقی قرن اول بود. او در حدود سال 101 پس از میلاد درگذشت.</p>', '2023-01-27 02:16:27.798737', '2023-01-27 02:16:27.798737', NULL, 'Musonius Rufus');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1228, 'زانسکو زیبا', '<p> بلا زانسکو یک استراتژیست مشهور زندگی و تندرستی است که از تکنیک های خودیاری خود برای غلبه بر تجربیات خود از افسردگی، دلشکستگی، فرسودگی شغلی و نارضایتی شغلی استفاده کرده است. او از آن زمان قهرمان قایقرانی جهان شد، <em>عکاس سفر سال روزنامه استرالیایی</em> و ملکه بازگشت دختر هوشمند که خود را نامیده است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1229, 'جنیفر آکر', '<p> جنیفر آکر یک روانشناس اجتماعی و بازاریاب است که در حال حاضر استاد بازاریابی در دانشکده تحصیلات تکمیلی کسب و کار دانشگاه استنفورد است. آثار او در چندین مجله برجسته از جمله <em>The</em> <em>Economist</em> و <em>The</em> <em>New</em> <em>York</em> به نمایش درآمده است. em> <em>زمان‌ها</em>.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1230, 'امیلی فلچر', '<p>امیلی فلچر یک متخصص برجسته در مدیتیشن برای عملکرد بالا است. او به عنوان خالق تکنیک Ziva و بنیانگذار مدیتیشن Ziva، در <em>نیویورک تایمز</em> و <em>ووگ</em> و همچنین در <em>Today Show حضور داشته است. </em> و <em>ABC News</em>. او همچنین در مورد مدیتیشن و عملکرد در گوگل، مدرسه بازرگانی هاروارد و زیاکوم صحبت کرده است.</p>', '2023-01-27 02:16:50.858153', '2023-01-27 02:16:50.858153', NULL, 'Emily Fletcher');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1231, 'جولیا اندرز', '<p> جولیا اندرز دارای مدرک دکترا از موسسه میکروبیولوژی و بهداشت بیمارستان ها در فرانکفورت آم ماین، آلمان است. در سال 2012، نظریه های او در مورد روده انسان برنده یک رقابت علمی در کارلسروهه و برلین شد.</p>', '2023-01-27 02:16:59.173378', '2023-01-27 02:16:59.173378', NULL, 'Giulia Enders');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1232, 'جیلیان زوئی سگال', '<p>گیلیان زوئی سگال قبل از اینکه علاقه واقعی خود به عکاسی را دنبال کند، حرفه حقوقی را آغاز کرد. او <em>رفتن به آنجا</em> را نوشت تا داستان افرادی را به نمایش بگذارد که ریسک کرده اند و سخت تلاش کرده اند تا رویاهای خود را زندگی کنند. نوشته های او در <em>Forbes</em>و <em>نیویورک تایمز</em> ظاهر شده است.</p>', '2023-01-27 02:17:06.533902', '2023-01-27 02:17:06.533902', NULL, 'Gillian Zoe Segal');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1233, 'مایکل حیات و دانیل هارکاوی', '<p>مایکل هایت، مدیر عامل سابق ناشران توماس نلسون، نویسنده <em>پلتفرم: در دنیای پر سر و صدا مورد توجه قرار بگیر</em>، پرفروش‌ترین کتاب <em>نیویورک تایمز</em> است<em> . </em>هر ماه،<em> </em>بیش از 300000 شنونده پادکست او را دانلود می کنند، <em>This Is Your Life</em>.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1234, 'اورین به سمت مبل می رود', '<p>اورن جی سوفر یک پزشک تجربه جسمانی و یک مربی خبره ارتباطات بدون خشونت است. او در سرتاسر جهان جلسات و کارگاه های آموزشی مراقبه و ارتباط را آموزش می دهد. او همچنین بنیانگذار Next Step Dharma، یک پلتفرم دوره مدیتیشن، و یکی از بنیانگذاران Mindful Healthcare است که آموزش هایی را در زمینه تمرکز حواس و ارتباط به کارکنان مراقبت های بهداشتی ارائه می دهد.</p>', '2023-01-27 02:17:23.405166', '2023-01-27 02:17:23.405166', NULL, 'Oren Jay Sofer');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1235, 'تیم گرهل', '<p>تیم گرال نویسنده و مشاور است. او جدا از نوشتن کتاب های پرفروش خود، با نویسندگان پرفروش دانیل پینک، چیپ و دن هیث، دن آریلی و پاملا اسلیم کار کرده است. گرال رئیس Out:think است، شرکتی که به نویسندگان کمک می‌کند تا استراتژی‌های بازاریابی را توسعه دهند، با خوانندگان ارتباط برقرار کنند و مهم‌تر از همه،<em>کتاب بفروشند</em>.</p>', '2023-01-27 02:17:36.338968', '2023-01-27 02:17:36.338968', NULL, 'Tim Grahl');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1236, 'بیل پرکینز', '<p>بیل پرکینز مدیر صندوق سرمایه گذاری و تهیه کننده فیلم است. او در سرمایه گذاری خطرپذیر و بازارهای انرژی متخصص است.</p>', '2023-01-27 02:17:44.375709', '2023-01-27 02:17:44.375709', NULL, 'Bill Perkins');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1237, 'راس دبلیو گرین', '<p>دکتر راس دبلیو. گرین بیش از 20 سال در هیئت علمی دانشکده پزشکی هاروارد خدمت کرد. او بنیانگذار و مدیر Lives in Balance و خالق رویکرد راه حل های مشارکتی و پیشگیرانه است. او در سراسر جهان سخنرانی می کند و در مدارس، مراکز روانپزشکی و مراکز بازداشت نوجوانان مشاوره می دهد. </p>', '2023-01-27 02:17:52.166939', '2023-01-27 02:17:52.166939', NULL, 'Ross W. Greene');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1238, 'کنت رومن و جوئل رافائلسون', '<p> کنت رومن و جوئل رافائلسون مدیران سابق آژانس تبلیغاتی و روابط عمومی Ogilvy & Mather هستند. رومن به عنوان مدیر عامل شرکت و رافائلسون مدیر اجرایی خلاقیت بود.</p>', '2023-01-27 02:18:00.096941', '2023-01-27 02:18:00.096941', NULL, 'Kenneth Roman and Joel Raphaelson');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1239, 'دنداپانی', '<p>دنداپانی یک کارآفرین و کشیش هندو است که در سطح بین‌المللی در مورد موضوعات تمرکز و آگاهی برگرفته از تجربه خود به عنوان پدر و راهب سابق صحبت می‌کند.</p>', '2023-01-27 02:18:08.299729', '2023-01-27 02:18:08.299729', NULL, 'Dandapani');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1240, 'سلیم اسماعیل', '<p>سلیم اسماعیل نویسنده که قبلاً معاون <em>Yahoo</em> بود، اکنون مدیر اجرایی مؤسس دانشگاه Singularity است. مایکل اس. مالون نویسنده برجسته فناوری است که نزدیک به 20 کتاب برنده جایزه نوشته است و در <em>The</em> <em>وال استریت ژورنال</em> معرفی شده است. یوری ون گیست یک سخنران اصلی بین المللی است و به عنوان مشاور برای <em>Google</em>، <em>Heineken</em> و <em>ING Bank</em> خدمت کرده است.</p>', '2023-01-27 02:18:16.185034', '2023-01-27 02:18:16.185034', NULL, 'Salim Ismail');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1241, 'جان ام. هال', '<p> جان ام. هال (1935-2015) استاد تعلیم و تربیت دینی و الهیات و نویسنده کتاب های متعددی در زمینه آموزش، الهیات و معلولیت بود. او در سال 2012 جایزه یک عمر دستاورد را از سوی مؤسسه ملی سلطنتی افراد نابینا (RNIB) به دلیل مشارکت در ادبیات نابینایی دریافت کرد.</p>', '2023-01-27 02:18:23.691102', '2023-01-27 02:18:23.691102', NULL, 'John M. Hull');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1242, 'نیر باشان', '<p>نیر باشان یک کارآفرین برنده جوایز است که در زمینه تبلیغات، سرگرمی، مشاوره و سخنرانی عمومی کار کرده است. امروز، باشان یک متخصص خلاقیت مشهور جهانی است که به رهبران برتر در سراسر جهان می آموزد که چگونه از قدرت خلاقیت برای افزایش فروش، پیشبرد نوآوری و رشد کسب و کار خود استفاده کنند.</p>', '2023-01-27 02:18:31.221731', '2023-01-27 02:18:31.221731', NULL, 'Nir Bashan');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1243, 'بن هوروویتز', '<p>بن هوروویتز سرمایه‌دار، کارشناس مدیریت و نویسنده پرفروش <em>نیویورک تایمز</em>است. او یکی از بنیانگذاران شرکت سرمایه گذاری خطرپذیر Andreessen Horowitz و رئیس سابق و مدیر عامل شرکت نرم افزاری Opsware است که توسط هیولت پاکارد به مبلغ 1.6 میلیارد دلار در سال 2007 خریداری شد.</p>', '2023-01-27 02:18:39.22681', '2023-01-27 02:18:39.22681', NULL, 'Ben Horowitz');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1244, 'آلیسا فاینرمن', '<p>آلیسا فاینرمن قبل از انجام این حرکت جسورانه برای تبدیل شدن به یک مربی حرفه ای زندگی حرفه ای خود را در امور مالی در وال استریت آغاز کرد.</p>', '2023-01-27 02:18:46.734236', '2023-01-27 02:18:46.734236', NULL, 'Alissa Finerman');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1245, 'استیون پینکر', '<p>استیون پینکر یک روانشناس تجربی و همچنین استاد روانشناسی در دانشگاه هاروارد است. او نویسنده شش کتاب است که دو تای آنها، <em>ذهن چگونه کار می کند</em> و <em>لوح خالی</em>، نامزدهای نهایی جایزه پولیتزر بودند.</p>', '2023-01-27 02:18:54.781352', '2023-01-27 02:18:54.781352', NULL, 'Steven Pinker');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1246, 'داگلاس هاردینگ', '<p>داگلاس هاردینگ فیلسوف، عارف و معلم معنوی انگلیسی بود. او نویسنده کتاب های بسیاری از جمله <em>سلسله مراتب آسمان و زمین</em> بود. نویسنده مشهور و متکلم مسیحی سی. اس. لوئیس مقدمه آن کتاب را نوشت و در آنجا آن را «اثری با بالاترین نبوغ» ستود. در طرف مقابل طیف مذهبی، بخش‌هایی از <em>On Having Head</em> توسط آتئیست و عصب‌شناس برجسته سام هریس حمایت شده است.</p>', '2023-01-27 02:19:03.061988', '2023-01-27 02:19:03.061988', NULL, 'Douglas Harding');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1247, 'فرد ووگلشتاین', '<p>فرد ووگلشتاین روزنامه‌نگار و نویسنده سابق کارکنان <em>Fortune</em> و <em>وال استریت ژورنال</em> است. او همچنین یک سردبیر در مجله <em>Wired </em> است. <em>سگ مبارزه</em> اولین کتاب او است.</p>', '2023-01-27 02:19:11.368683', '2023-01-27 02:19:11.368683', NULL, 'Fred Vogelstein');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1248, 'سونیا شاه', '<p>سونیا شاه نویسنده و روزنامه نگاری است که آثارش در <em>نیویورک تایمز</em>،<em> Scientific American</em> و <em>وال استریت ژورنال</em> منتشر شده است. سخنرانی او در TED با عنوان "سه دلیل که هنوز از مالاریا خلاص نشده ایم" توسط بیش از یک میلیون نفر در سراسر جهان تماشا شد. کتاب‌های دیگر او عبارتند از <em>خام: داستان نفت</em> و <em>شکارچیان بدن</em>.</p>', '2023-01-27 02:19:19.313643', '2023-01-27 02:19:19.313643', NULL, 'Sonia Shah');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1249, 'پیتر بلاک', '<p>پیتر بلاک یک مشاور مشهور آمریکایی است و کتاب های زیادی در زمینه مشاوره، توانمندسازی و مسائل اجتماعی تالیف کرده است. او برنده جایزه یک عمر دستاورد سال 2008 از شبکه توسعه سازمان شد.</p>', '2023-01-27 02:19:27.180418', '2023-01-27 02:19:27.180418', NULL, 'Peter Block');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1250, 'ThinkApps', '<p>ThinkApps، مستقر در سانفرانسیسکو، شرکتی است که به مشتریان خود کمک می کند تا برنامه های وب، تلفن همراه و دستگاه های پوشیدنی خیره کننده بسازند. آنها مشتاق حمایت از استارت آپ های برتر دره سیلیکون و شرکت های نوآور سازمانی هستند و مسئول برنامه های مورد استفاده میلیون ها کاربر مانند PicPlayPost هستند.</p>', '2023-01-27 02:19:40.050118', '2023-01-27 02:19:40.050118', NULL, 'ThinkApps');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1251, 'استیون بوچمن', '<p>زیست‌شناس استفان بوخمن از دوران جوانی خود یک مراقب زنبور عسل و حشرات پرشور بوده است. او استادیار دانشگاه آریزونا با تخصص در اکولوژی گرده افشانی است. بوخمن نویسنده یازده کتاب، از جمله <em>گرده افشانان فراموش شده</em>، نامزد نهایی جایزه کتاب <em>لس آنجلس تایمز</em> است.</p>', '2023-01-27 02:19:48.1172', '2023-01-27 02:19:48.1172', NULL, 'Stephen Buchmann');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1252, 'کیت روزن', '<p> کیت روزن مدیر عامل شرکت Profit Builder است که متخصص در فروش و آموزش مربیگری است. مجله <em>Inc.</em> و <em>Fast Company</em> روزن را یکی از پنج مربی برتر اجرایی با نفوذ معرفی کردند.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1253, 'لوئیس اسمایل', '<p>لوئیس اسمایل زندگی عجیب و غریبی داشته است که او را از خواننده اصلی گروه Soulful Repetition در دهه 1990 به متخصص در زمینه بهبود حافظه تبدیل کرده است. از دیگر کتاب‌های او می‌توان به <em>اسکریپت‌های MLM</em> و <em>مربع جادویی</em> اشاره کرد.</p>', '2023-01-27 02:20:03.761635', '2023-01-27 02:20:03.761635', NULL, 'Lewis Smile');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1254, 'رابرت گرین', '<p>رابرت گرین نویسنده ای پرفروش است. او <em>48 قانون قدرت</em>و <em>33 استراتژی جنگ و تسلط را نوشت.</em> او دارای مدرک مطالعات کلاسیک است.</p>', '2023-01-27 02:20:11.161792', '2023-01-27 02:20:11.161792', NULL, 'Robert Greene');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1255, 'آستین کلئون', '<p>Austin Kleon نویسنده پرفروش <em>نیویورک تایمز</em> است <em>Steal Like An Artist</em> و <em>Show Your Work!</em> همراه با <em>Keep Going. </em>، این کتاب ها سه گانه ای را تشکیل می دهند که بیش از یک میلیون نسخه چاپ شده و به بیش از دوجین زبان ترجمه شده است. او همچنین یک سخنران عمومی است که فعالیت های سخنرانی او شامل سازمان های سطح بالایی مانند گوگل و پیکسار است. هم در کتاب‌هایش و هم در سخنرانی‌های عمومی‌اش، کار او بر ارتقای خلاقیت در دنیای مدرن متمرکز است. </p>', '2023-01-27 02:20:18.753064', '2023-01-27 02:20:18.753064', NULL, 'Austin Kleon');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1256, 'جان کابات زین', '<p>جان کابات زین به عنوان استاد ذهن آگاهی توصیف شده است. کابات زین به عنوان دانشمند، نویسنده و معلم مراقبه شهرت بین المللی به دست آورده است. او همچنین پیشگام MBSR، تکنیک کاهش استرس مبتنی بر ذهن آگاهی است که به هزاران نفر کمک کرده است.</p>', '2023-01-27 02:20:26.416812', '2023-01-27 02:20:26.416812', NULL, 'Jon Kabat-Zinn');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1257, 'چیپ کانلی', '<p>کانلی نویسنده و سخنران آمریکایی است که بیشتر به خاطر داستان موفقیت کارآفرینی خود به عنوان بنیانگذار هتل های زنجیره ای Joie de Vivre شناخته می شود. او به عنوان کارآفرین سال املاک و مستغلات کالیفرنیای شمالی و همچنین بازاریاب چریکی سال توسط مدیران بازاریابی مسافرتی آمریکا اعطا شده است. کسب‌وکارهای بسیار موفق او و روحیه هنرپیشگی او باعث شده تا او داستان‌هایی را در <em>The</em> <em>Wall</em> <em>خیابان</em> <em>ژورنال،</em> <em>The</em> <em>Wall</em> em>The</em> <em>New</em> <em>York</em> <em>Times</em>، <em>Time</em> و <em>People</em>. </p>', '2023-01-27 02:20:34.518276', '2023-01-27 02:20:34.518276', NULL, 'Chip Conley');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1258, 'جف کولوین', '<p>جف کالوین ویراستار و ستون نویس <em>Fortune</em>، و یک مفسر و سخنران بسیار مورد توجه در موضوعاتی مانند روندهای تجاری و رهبری است. او همچنین روزانه با نظرات تجاری در شبکه رادیویی CBS همکاری می کند.</p>', '2023-01-27 02:20:41.881769', '2023-01-27 02:20:41.881769', NULL, 'Geoff Colvin');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1259, 'اریک استنداپ با الیزا پترینی', '<p>اریک استندوپ کار پرقدرت خود را 15 سال پیش ترک کرد، زمانی که یک رویارویی با یک چهره خوان در کیپ تاون به چالش کشید که او فکر می کرد می توان از چهره یک شخص دیگر به دست آورد. او برای آشنایی با چهره خوانی و تکنیک های تشخیصی آن، سفری به سراسر جهان را آغاز کرد. امروز او یک سخنران، مشاور و متخصص چهره خوانی است. او همچنین بنیانگذار آکادمی چهره خوانی است.</p>', '2023-01-27 02:20:49.903423', '2023-01-27 02:20:49.903423', NULL, 'Eric Standop with Elisa Petrini');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1260, 'غار تاماسین و اندی روول', '<p>Tamasin Cave و Andy Rowell مدیران Spinwatch هستند، یک سازمان غیرانتفاعی که آگاهی عمومی را در مورد تبلیغات دولتی و تجاری و عدم شفافیت در تجارت لابی‌گری افزایش می‌دهد.</p>', '2023-01-27 02:21:03.662131', '2023-01-27 02:21:03.662131', NULL, 'Tamasin Cave and Andy Rowell');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1261, 'آنی دوک', '<p>آنی دوک در تصمیم گیری حرفه ای ایجاد کرده است. او مهارت های خود را به عنوان یک بازیکن حرفه ای قدیمی پوکر تقویت کرد و بیش از 4 میلیون دلار برنده شد و همچنین در سری مسابقات جهانی قهرمانان پوکر قهرمان شد. او اکنون به عنوان مشاور و نویسنده کار می کند. کتاب های دیگر او عبارتند از <em>چگونه تصمیم بگیریم</em> و پرفروش ترین کتاب <em>تفکر در شرط بندی</em>. </p>', '2023-01-27 02:21:16.801116', '2023-01-27 02:21:16.801116', NULL, 'Annie Duke');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1262, 'جوزف A. Maciariello', '<p>جوزف مکیاریلو دارای مدرک دکترای اقتصاد از دانشگاه نیویورک است. او استاد فعلی ماری رنکین کلارک در رشته علوم اجتماعی و مدیریت در دانشکده مدیریت ارشد پیتر اف. دراکر و ماساتوشی ایتو است. ماسیارلو، همکار و هم از آشنایان نزدیک پیتر دراکر، تعدادی کتاب در مورد بینش های مدیریتی دراکر نوشته است.</p>', '2023-01-27 02:21:24.93063', '2023-01-27 02:21:24.93063', NULL, 'Joseph A. Maciariello');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1263, 'دانیل گلمن و ریچارد جی دیویدسون', '<p>دانیل گلمن نویسنده و فارغ التحصیل هاروارد است. یکی از شناخته شده ترین کتاب های او <em>هوش عاطفی</em> (1995) است. علاقه گلمن به مدیتیشن با یک سفر دو ساله به هند در دوران دانشجویی آغاز شد.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1278, 'جاشوا بکر', '<p>جاشوا بکر بنیانگذار <em>مینیمالیست شدن</em> است، وبلاگی که الهام بخش میلیون ها نفر است تا خانه های خود را شلوغ کنند و معنای بیشتری در زندگی خود بیابند. او به طور منظم در <em>Time</em>، <em>Wall Street Journal</em>، <em>USA Today</em> و <em>Christianity Today</em> و همچنین مهمان مکرر <em>HuffPost Live</em>.</p>', '2023-01-27 02:24:03.421407', '2023-01-27 02:24:03.421407', NULL, 'Joshua Becker');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1264, 'جاناتان سافران فوئر', '<p>جاناتان سافران فوئر یک رمان نویس جوان آینده دار از نیویورک است که پرفروش ترین های بین المللی <em>همه چیز روشن است</em> و <em>بسیار بلند و باورنکردنی نزدیک</em> را نوشته است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1265, 'جولیان گنج', '<p>Julian Treasure یک سخنران بین المللی تحسین شده است که سخنرانی های TED او بیش از 40 میلیون بازدید جمع آوری کرده است و در بین ده سخنرانی برتر TED در تمام دوران رتبه بندی شده است.</p>', '2023-01-27 02:21:53.746264', '2023-01-27 02:21:53.746264', NULL, 'Julian Treasure');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1266, 'جیمز آلن', '<p>جیمز آلن (۱۸۶۴–۱۹۱۲) نویسنده بریتانیایی بود که بیشتر به خاطر نظریه‌هایش درباره قدرت اندیشه شهرت داشت. مشهورترین اثر او، <em>همانطور که انسان فکر می‌کند</em>، الهام‌بخش نسل‌های نویسندگان خودیاری بوده است.</p>', '2023-01-27 02:22:08.025056', '2023-01-27 02:22:08.025056', NULL, 'James Allen');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1267, 'Bogumil K. Baranowski', '<p>Bogumil K. Baranowski یک متخصص سرمایه گذاری در نیویورک است که یک صندوق سرمایه گذاری خصوصی را در مدیریت دارایی توکویل مدیریت می کند.</p>', '2023-01-27 02:22:15.373872', '2023-01-27 02:22:15.373872', NULL, 'Bogumil K. Baranowski');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1268, 'آرتور بنجامین', '<p>آرتور بنجامین یک سخنران منظم در سخنرانی های TED و استاد ریاضیات در کالج هاروی ماد است. او دارای مدرک دکترا از دانشگاه جانز هاپکینز است و همچنین نویسنده <em>اسرار ریاضیات ذهنی</em> است.</p>', '2023-01-27 02:22:29.579141', '2023-01-27 02:22:29.579141', NULL, 'Arthur Benjamin');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1269, 'جردن لی دولی', '<p>جردن لی دولی یک کارآفرین، نویسنده پرفروش، مربی کسب و کار، مسیحی مفتخر و ستاره اینستاگرام است. به عنوان دانشجوی کالج، او یک فروشگاه کوچک Etsy تاسیس کرد که به یک برند جهانی گرمکن تبدیل شد. امروز او به زنان کمک می کند تا هدف و موفقیت در تجارت و زندگی پیدا کنند. دولی یک پادکست با رتبه برتر به نام SHE دارد و The Own It Academy، یک مدرسه کسب و کار آنلاین را اداره می کند. </p>', '2023-01-27 02:22:37.130981', '2023-01-27 02:22:37.130981', NULL, 'Jordan Lee Dooley');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1270, 'آدام براون', '<p>آدام براون Pencils of Promise را در سال 2008 تاسیس کرد. او در هر دو <em>Forbes</em>'' "30 Under 30" و <em>Wired</em> "50 People Who Will The Change the World" نام گرفته شده است. فهرست‌ها.</p>', '2023-01-27 02:22:44.490697', '2023-01-27 02:22:44.490697', NULL, 'Adam Braun');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1271, 'Saifdean Ammous', '<p>سیفدین آموس، عضو سابق مرکز سرمایه داری و جامعه در دانشگاه کلمبیا نیویورک، یک اقتصاددان مستقر در دانشکده تجارت عدنان کسار در لبنان است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1272, 'گی هندریکس', '<p>گی هندریکس یک روانشناس است که مدتهاست در زوج درمانی و ترویج استفاده از تنفس آگاهانه به عنوان ابزاری برای حفظ روابط تخصص داشته است. او همچنین نویسنده پرفروش بسیاری از کتاب های خودیاری، از جمله <em>پنج آرزو</em> و <em>زندگی آگاهانه</em> است.</p>', '2023-01-27 02:22:59.315446', '2023-01-27 02:22:59.315446', NULL, 'Gay Hendricks');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1273, 'جرمی کی بالکین', '<p>جرمی کی. بالکین، رهبر محترم در موضوع بانکداری و مالی اخلاقی، اغلب به عنوان "ضد گرگ وال استریت" توصیف می شود. بالکین که سخنران ارزشمندی است در سازمان ملل و مجمع جهانی اقتصاد سخنرانی کرده است. سخنرانی TED او در مورد بانکداری اخلاقی بیش از یک چهارم میلیون بار مشاهده شده است.</p>', '2023-01-27 02:23:18.4959', '2023-01-27 02:23:18.4959', NULL, 'Jeremy K. Balkin');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1274, 'دانیل تی ویلینگهام', '<p>دانیل تی ویلینگهام یک روانشناس شناختی است که استاد گروه روانشناسی دانشگاه ویرجینیا است. دانیل تی ویلینگهام دکترای خود را از دانشگاه هاروارد به دست آورد و کتاب های متعددی در زمینه آموزش و روانشناسی تألیف کرده است. اینها عبارتند از <em>شناخت</em>: <em>حیوان متفکر</em> (2001) و <em>تربیت کودکانی که می‌خوانند </em>(2015).</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1275, 'بلیک جی. هریس', '<p>بلیک جی. هریس یک نویسنده و فیلمساز است که یک مستند بر اساس <em>Console Wars</em> را نیز کارگردانی می کند. هریس همچنین تهیه کننده اجرایی <em>سونی</em>اقتباسی فیلم بلند از این کتاب است.</p>', '2023-01-27 02:23:40.210917', '2023-01-27 02:23:40.210917', NULL, 'Blake J. Harris');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1276, 'پل اسمیت', '<p>پل اسمیت یک سخنران کلیدی محبوب و همچنین یک مربی شرکتی در تکنیک های رهبری و داستان سرایی است. او قبلاً یکی از مدیران اجرایی و 20 ساله شرکت <em>پروکتر اند گمبل</em> بوده و دو کتاب به نام‌های <em>Lead with a Story</em>و <em>Parenting with a Story</em> تالیف کرده است. em>.</p>', '2023-01-27 02:23:47.906533', '2023-01-27 02:23:47.906533', NULL, 'Paul Smith');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1277, 'استیو بروسات', '<p>استیو بروسات دیرینه شناس آمریکایی در دانشگاه ادینبورگ است. او برای <em>Scientific American</em> نوشته است و مشاور <em>Walking with Dinosaurs</em> بی بی سی بوده است. او همچنین با شخصیت‌های مهم در دیرینه‌شناسی کار کرده است و اکتشافات پیشگامانه‌اش او را به عنوان یک متخصص جهانی در این زمینه معرفی کرده است.</p>', '2023-01-27 02:23:55.802087', '2023-01-27 02:23:55.802087', NULL, 'Steve Brusatte');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1304, 'مارگارت گرینبرگ و سنیا میمین', '<p>مارگارت گرینبرگ مربی اجرایی شرکت های Fortune 500 و موسس مشاوره گروه گرینبرگ است. سنیا میمین دارای دکترای رفتار سازمانی از استانفورد است و برای مشتریانی از جمله گوگل و اینتل مشاوره کرده است.</p>', '2023-01-27 02:27:57.210154', '2023-01-27 02:27:57.210154', NULL, 'Margaret Greenberg and Senia Maymin');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1279, 'Maisie Hill', '<p>Maisie Hill یک متخصص بهداشت قاعدگی است که به مشتریانش کمک می کند تا با چرخه قاعدگی خود کار کنند و بی نظمی های هورمونی را درمان کنند. او در طب چینی، طب سوزنی و ATMAT (<em>تکنیک های آرویگو در درمان شکم مایا)</em> آموزش دیده است. او به عنوان یک متخصص پیشرو برای مسائل قاعدگی، هورمونی و باروری، در نشریات <em>گاردین</em>به <em>گرازیا نقل قول شده است. </em></p>', '2023-01-27 02:24:16.732901', '2023-01-27 02:24:16.732901', NULL, 'Maisie Hill');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1280, 'دیوید گیلز لوئیس', '<p>دیوید لوئیس یک مشاور تجاری جهانی با بیش از سه دهه تجربه در صنعت و دانشگاه است. </p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1281, 'پرم روات', '<p>برای بیش از 50 سال، پرم روات به سراسر جهان سفر کرده و با صدها میلیون نفر صحبت کرده است تا پیام صلح خود را منتشر کند. راوات بنیانگذار بنیاد پریم راوات است که هدف آن ارتقای عزت، صلح و رفاه از طریق طرح هایی مانند برنامه آموزش صلح و غذا برای مردم است. او نویسنده <em>صلح ممکن است</em> است و همچنین یک عکاس، آهنگساز و خلبان است.</p>', '2023-01-27 02:24:31.730887', '2023-01-27 02:24:31.730887', NULL, 'Prem Rawat');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1282, 'زیگ زیگلار با تام زیگلار', '<p>زیگ زیگلار فروشنده، سخنران انگیزشی و نویسنده موفقی بود. در طول چهار دهه، او به طور گسترده سفر کرد و در مقابل میلیون ها نفر سخنرانی کرد. او بیش از 30 کتاب درباره موضوعاتی مانند ایمان و رشد شخصی نوشت، از جمله پرفروش‌ترین کتاب‌های<em> شما را در بالای صفحه می‌بینم</em>، <em>چگونه برنده باشیم</em>، و <em>موفقیت و تصویر از خود</em>.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1283, 'چلسی فاگان و لورن ور هیج', '<p>Chelsea Fagan خالق وب‌سایت و کانال محبوب YouTube <em>The Financial Diet</em> است. او همچنین برای <em>Atlantic, Cosmopolitan </em>and<em> VICE</em> نوشته است و نویسنده کتاب دیگری به نام <em>I''m Only Here for the WiFi</em> است. </p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1284, 'پیت کاملی', '<p>پیت کاملی نویسنده و مشاور سابق بینش در شرکت خود، Join the Dots است. این موسسه در سال 1998 تاسیس شد و اولین آژانس تحقیقات بازار آنلاین در بریتانیا بود. او دو کتاب دیگر به نام های <em>میمون با سنجاق</em>و <em>مالیات تورمی: طرح مقابله با بدهی ها</em></p> را منتشر کرده است.', '2023-01-27 02:25:03.857048', '2023-01-27 02:25:03.857048', NULL, 'Pete Comley');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1285, 'گونتر مولر-استیونز', '<p>گونتر مولر-استیونز پروفسور ممتاز مدیریت در موسسه مدیریت و استراتژی در دانشگاه سنت گالن است و قبلاً مدیر اجرایی آن بود. او مجله <em>M&A Review</em> را تأسیس کرد و عضو هیئت تحریریه متعدد و همچنین هیئت های مشاوره چندین شرکت بین المللی است. او همچنین به عنوان مشاور و مربی برای سازمان های مختلف فعالیت می کند. انتشارات او شامل <em>تحول مدل کسب و کار رادیکال</em> و <em>مدیریت لوکس</em> است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1286, 'جیسون سلک و الن رید', '<p>جیسون سلک یک مربی عملکرد، متخصص بهداشت روان دارای مجوز، و مدیر سابق آموزش ذهنی تیم بیسبال سنت لوئیس کاردینالز است. او نویسنده پرفروش ترین کتاب های <em>سختی اجرایی</em> و <em>سختی 10 دقیقه ای</em> است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1287, 'ناتان جمیل', '<p>ناتان جمیل یک مشاور مدیریت، مربی شرکتی و حرفه‌ای سابق فروش است. جمیل از طریق پرفروش‌ترین کتاب‌های تجاری، کارگاه‌ها و سخنرانی‌های کلیدی خود، استراتژی‌های خود را برای موفقیت شرکت به اشتراک می‌گذارد.</p>', '2023-01-27 02:25:32.013791', '2023-01-27 02:25:32.013791', NULL, 'Nathan Jamail');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1288, 'ویلیام هارت', '<p>ویلیام هارت یکی از اولین دستیار معلمانی بود که توسط S. N. Goenka برای آموزش مراقبه ویپاسانا منصوب شد. کتاب او، <em>هنر زندگی</em>،<em> </em>به اثر قطعی در مورد مراقبه و فلسفه ویپاسانا تبدیل شده است و به 25 زبان مختلف ترجمه شده است.</p>', '2023-01-27 02:25:40.505108', '2023-01-27 02:25:40.505108', NULL, 'William Hart');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1289, 'جان سی. ماکسول و راب هاسکینز', '<p>جان سی ماکسول یکی از پرفروش‌ترین نویسنده، مربی و گوینده <em>نیویورک تایمز</em> است که بیش از 30 میلیون کتاب به پنجاه زبان فروخته است. </p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1290, 'جیمی ناتر و مدی گرانت', '<p>جمی ناتر و مدی گرانت با سازمان‌ها در مورد تغییر فرهنگ از طریق شرکتشان «فرهنگ که کار می‌کند»، با تخصص خاص در تغییر فناوری و تعامل داخلی (کارمند) و خارجی (مشتری) مشورت می‌کنند.</p>', '2023-01-27 02:25:50.849825', '2023-01-27 02:25:50.849825', NULL, 'Jamie Notter and Maddie Grant');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1291, 'راینور وین', '<p>رینور وین یک پیاده‌روی و نویسنده مسافت‌های طولانی است. او درباره طبیعت، بی خانمانی، و کمپینگ وحشی نوشته است. <em>مسیر نمک</em>، خاطراتی از تجربیات خودش، اولین کتاب او است.</p>', '2023-01-27 02:26:02.617062', '2023-01-27 02:26:02.617062', NULL, 'Raynor Winn');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1292, 'دومینیک آنتیگلیو', '<p>دومینیک آنتیگلیو یک سوفرولوژیست و استئوپات متولد سوئیس است که در سن 15 سالگی برای غلبه بر مشکلات جدی سلامتی، سوفرولوژی را آغاز کرد. او پس از تحصیل در اسپانیا نزد بنیانگذار این روش، پروفسور آلفونسو کایسدو، در سال 2006 مدرک کارشناسی ارشد خود را در سوفرولوژی کیسدی به دست آورد. در سال 2011، او یک کلینیک پیشرو سوفرولوژی به نام BeSophro را در لندن تأسیس کرد. </p>', '2023-01-27 02:26:09.602302', '2023-01-27 02:26:09.602302', NULL, 'Dominique Antiglio');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1293, 'آدام کوچارسکی', '<p>آدام کوچارسکی یک ریاضیدان آموزش دیده و دانشیار دانشکده بهداشت و پزشکی استوایی لندن است. او همچنین یکی از همکاران TED و برنده جایزه 2012 Wellcome Trust Science Writing Prize است. او نویسنده <em>شرط کامل</em>(2012) و همچنین یکی از همکاران <em>Scientific American</em>، <em>Financial Times</em>، و <em> است. ناظر</em>.</p>', '2023-01-27 02:26:16.975089', '2023-01-27 02:26:16.975089', NULL, 'Adam Kucharski');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1294, 'الکساندرا اچ. سولومون', '<p>الکساندرا اچ. سولومون، دکترا، روانشناس بالینی و استادیار روانشناسی در موسسه خانواده در دانشگاه نورث وسترن است. یک کارشناس مورد تقاضا در موضوعات عشق و عاشقی، آثار او در <em>O</em>،<em>هافینگتون پست</em>، و<em>آتلانتیک</em> ظاهر شده است.</em> p>', '2023-01-27 02:26:24.135393', '2023-01-27 02:26:24.135393', NULL, 'Alexandra H. Solomon');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1295, 'ماریان ویلیامسون', '<p> ماریان ویلیامسون نویسنده، معلم معنوی و بنیانگذار Project Angel Food است، یک برنامه غذای روی چرخ در لس آنجلس. او همچنین در اتحاد صلح و سازمان نتایج مشارکت دارد، که هر دو برای پایان دادن به فقر و ترویج صلح در ایالات متحده و در سراسر جهان تلاش می کنند. بسیاری از کتاب‌های او پرفروش‌ترین کتاب‌های <em>نیویورک تایمز</em> بوده‌اند، از جمله <em>عصر معجزات</em>و <em>شفای روح آمریکا</em>.</p>', '2023-01-27 02:26:36.853634', '2023-01-27 02:26:36.853634', NULL, 'Marianne Williamson');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1296, 'برایان پورتنوی', '<p>برایان پورتنوی یک مشاور سرمایه گذاری در Virtus Investment Partners است، مشاوره ای که به مشتریان کمک می کند آینده مالی خود را برنامه ریزی کنند و تصمیمات سرمایه گذاری درستی بگیرند. پورتنوی همچنین نویسنده <em>پارادوکس سرمایه گذار</em> است. <em>هندسه ثروت</em> دومین کتاب اوست. </p>', '2023-01-27 02:26:44.387594', '2023-01-27 02:26:44.387594', NULL, 'Brian Portnoy');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1297, 'جوزف گلدشتاین', '<p>جوزف گلدشتاین بیش از پنج دهه را صرف انتقال روش‌های ویپاسانا، سنت بودایی ذهن‌آگاهی، به مخاطبان غربی کرده است. گلدشتاین نویسنده <em>قلبی پر از صلح</em>و <em>یک دارما: بودیسم غربی در حال ظهور</em> است.</p>', '2023-01-27 02:26:51.72933', '2023-01-27 02:26:51.72933', NULL, 'Joseph Goldstein');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1298, 'لارنس آ. کانینگهام', '<p>لارنس ای. کانینگهام، استاد حقوق هنری سنت جورج تاکر سوم در دانشگاه جورج واشنگتن در واشنگتن دی سی است. نوشته های او در مجلات دانشگاهی و در نشریاتی مانند <em>فایننشال تایمز</em> منتشر شده است. <em>نیویورک پست</em> و <em></em> <em>نیویورک تایمز</em>. کتاب های دیگر عبارتند از <em>داستان AIG</em>(با موریس ای. گرینبرگ) و <em>چگونه مانند بنجامین گراهام فکر کنیم</em> <em>و مانند وارن بافت سرمایه گذاری کنیم.</em></p. >', '2023-01-27 02:27:03.286482', '2023-01-27 02:27:03.286482', NULL, 'Lawrence A. Cunningham');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1299, 'گابریل برنشتاین', '<p>گابریل برنشتاین نویسنده پرفروش <em>نیویورک تایمز</em> از عناوینی مانند <em>جهان پشت شماست</em> و <em>معجزات اکنون</em> نامگذاری شده است. برنشتاین «رهبر فکری نسل بعدی» اثر اپرا، بیش از یک دهه است که دیگران را از طریق نوشتن، سخنرانی در جمع و جلسات مراقبه گروهی به سوی تحقق معنوی راهنمایی می‌کند. </p>', '2023-01-27 02:27:16.388256', '2023-01-27 02:27:16.388256', NULL, 'Gabrielle Bernstein');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1300, 'متیو مک کانهی', '<p>متیو مک‌کانهی بازیگر برنده اسکار است که فعالیت حرفه‌ای‌اش به <em>گیج و گیج‌شده</em> در سال ۱۹۹۳ بازمی‌گردد و شامل آثاری چون <em>زمانی برای کشتن</em>، <em>وکیل لینکلن است. </em>، <em>Interstellar</em>، و <em>True Detective</em>. او همچنین استاد تمرین در دانشگاه تگزاس در آستین و یکی از خالقان بوربن بلند ترکی وحشی است.</p>', '2023-01-27 02:27:23.127715', '2023-01-27 02:27:23.127715', NULL, 'Matthew McConaughey');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1301, 'بتی دادسون', '<p>بتی دادسون، دکترا، مربی جنسی، هنرمند، و نویسنده چندین کتاب در مورد تمایلات جنسی آمریکایی بود. او جایزه خدمات عمومی را از انجمن مطالعات علمی جنسیت و جایزه استاد و جانسون را که توسط انجمن سکس درمانی و تحقیقات ارائه شده بود دریافت کرد. او به عنوان یک متخصص برجسته جنسی در نظر گرفته شد و توسط مجله <em>Cosmopolitan</em> به عنوان یکی از ده انقلابی برتر جنسی معرفی شد.', '2023-01-27 02:27:30.509646', '2023-01-27 02:27:30.509646', NULL, 'Betty Dodson');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1302, 'ارین بابلر و لارا گالووی', '<p>ارین بابلر یک کارآفرین و سخنران عمومی است. شرکت مربی او <em>کارگاه ماگنولیا</em> نیازهای زنان تاجر را برآورده می کند. </em>بابلر در <em>سوپ مرغ برای سوپ</em>l و <em>پنج راز که باید برای دختر کالج امروزی بدانید</em> همکاری کرد.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1303, 'شاعر را فروتن کن', '<p>کانور سینگ - یا همانطور که به طور حرفه ای او را می شناسند، شاعر فروتن - معلم سابق مدرسه است که تبدیل به هنرمند، رپر، فیلم ساز، طراح، تأثیرگذار و سخنران انگیزشی شده است. او همچنین نویسنده بین المللی پرفروش ترین کتاب های <em>Unlearn</em>و <em>Unlearn – Beneath the Surface</em></p> است.', '2023-01-27 02:27:45.153003', '2023-01-27 02:27:45.153003', NULL, 'Humble the Poet');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1305, 'ناتان فور و پل آلستروم', '<p>ناتان فور استاد و محقق کارآفرینی است. او در راه اندازی و مشاوره چندین شرکت مشارکت داشته است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1306, 'ایون شوینارد', '<p>Yvon Chouinard موسس و مالک پاتاگونیا، مستقر در Ventura، کالیفرنیا است. او کار خود را با طراحی ابزار صخره نوردی آغاز کرد و سپس به سراغ انواع محصولات سازگار با محیط زیست و پایدار برای ماجراجویان در فضای باز رفت. او همچنین چندین ابتکار و موسسه خیریه را تأسیس کرده است که از اهداف زیست محیطی حمایت می کنند.</p>', '2023-01-27 02:28:17.357174', '2023-01-27 02:28:17.357174', NULL, 'Yvon Chouinard');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1307, 'اد یانگ', '<p>اد یونگ نویسنده علمی و سخنران مشهوری است که آثار او در صفحات <em> اقیانوس اطلس</em>، <em>طبیعت</em>، <em>علمی آمریکایی</em>، <em> New York Times</em>، <em>Wired،</em> و بسیاری دیگر. او همچنین وبلاگی را در وب‌سایت <em>نشنال جئوگرافیک</em> با عنوان <em>نه دقیقاً علم موشک</em> ویرایش می‌کند.</p>', '2023-01-27 02:28:24.360249', '2023-01-27 02:28:24.360249', NULL, 'Ed Yong ');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1308, 'امانوئل آکو', '<p>امانوئل آکو یک مدافع خط سابق NFL است که به کلیولند براونز فراخوانده شد و بعداً برای فیلادلفیا ایگلز بازی کرد. او در سال 2015 از این ورزش بازنشسته شد تا حرفه ای را در رسانه دنبال کند. او در حال حاضر به عنوان تحلیلگر برای Fox Sports 1 کار می کند و مجری سریال <em>مکالمات ناراحت کننده با یک مرد سیاه پوست در یوتیوب است. </em>کتاب‌های <em>مکالمه‌های ناراحت‌کننده با یک مرد سیاه پوست</em>و <em>گفت‌وگوهای ناراحت‌کننده با یک پسر سیاه پوست</em>هر دو پرفروش‌ترین <em>نیویورک تایمز</em>بودند. p>', '2023-01-27 02:28:37.147327', '2023-01-27 02:28:37.147327', NULL, 'Emmanuel Acho');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1309, 'اسکات دی سامپسون', '<p>Scott D. Sampson دیرینه شناس دایناسور و ارتباط دهنده علم است. او همچنین سفیر برنامه <em>Nature Rocks</em> است، ابتکاری توسط The Nature Conservancy برای الهام بخشیدن به خانواده ها برای کشف طبیعت.</p>', '2023-01-27 02:28:49.156178', '2023-01-27 02:28:49.156178', NULL, 'Scott D. Sampson');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1310, 'دمی مور', '<p>دمی مور یک بازیگر، تهیه کننده، کارگردان و فعال است. او بیشتر به خاطر نقش‌هایش در <em>St Elmo’s Fire، Ghost، A Few Good Men، Indecent Proposal،</em>و<em>G.I. جین </em>او همچنین یکی از بنیانگذاران Thorn است، یک سازمان غیرانتفاعی که فناوری ایجاد می کند تا از کودکان در برابر سوء استفاده جنسی دفاع کند. او در لس آنجلس و هیلی، آیداهو زندگی می کند.</p>', '2023-01-27 02:28:56.323434', '2023-01-27 02:28:56.323434', NULL, 'Demi Moore');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1311, 'جو مارچانت', '<p>Jo Marchant، دکترا، میکروبیولوژیست، روزنامه‌نگار علمی برنده جایزه و نویسنده <em>رمزگشایی بهشت‌ها</em> و <em>شاه سایه</em> است. او سردبیر مجلات علمی مختلفی مانند <em>New Scientist </em>و <em>Nature</em> بوده است و علاوه بر نوشتن برای <em>The Guardian</em> و <em>The </em> <em>اقتصاددان</em>.</p>', '2023-01-27 02:29:03.634645', '2023-01-27 02:29:03.634645', NULL, 'Jo Marchant');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1312, 'فرانک آبگنال و استن ردینگ', '<p>فرانک آبگنال که به عنوان یک کلاهبردار سابق اعتماد شناخته می‌شود، اکنون مشاور و مدرس حرفه‌ای در واحد جرایم مالی دفتر تحقیقات فدرال ایالات متحده است.</p>', '2023-01-27 02:29:10.621376', '2023-01-27 02:29:10.621376', NULL, 'Frank Abagnale and Stan Redding');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1313, 'وندی موگل', '<p>وندی موگل، دکترا، روانشناس اجتماعی- بالینی، سخنران عمومی مشهور و نویسنده پرفروش است. به عنوان مشاور علمی مجله <em>Parents</em>، هدف او ارتقای خوداتکایی، انعطاف پذیری و مسئولیت پذیری در کودکان و والدین است. کتاب های دیگر او عبارتند از <em>برکت یک زانوی پوستی</em>و <em>برکت یک بی منهای. </em></p>', '2023-01-27 02:29:18.010996', '2023-01-27 02:29:18.010996', NULL, 'Wendy Mogel');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1314, 'اسکیم', '<p>Skimm که توسط کارلی زاکین و دانیل وایزبرگ تأسیس شد، یک خبرنامه آنلاین محبوب است که در ابتدا قصد داشت تا هزاره‌های زن را برای تصمیم‌گیری آگاهانه‌تر توانمند کند. از زمان راه اندازی در سال 2012، Skimm به طور پیوسته مشترکین بیشتری را جذب کرده است و اکنون منبعی ارزشمند برای بیش از هفت میلیون عضو است.</p>', '2023-01-27 02:29:25.523298', '2023-01-27 02:29:25.523298', NULL, 'The Skimm');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1315, 'رایان لوسک', '<p>Ryan Levesque که به عنوان "نابغه تبدیل" شناخته می شود، حرفه ای موفق در تجارت داشته است و به کسب و کارها در 23 صنعت مختلف کمک کرده است تا تبدیل خود را افزایش دهند و درآمد کسب کنند. این اولین کتاب او است.</p>', '2023-01-27 02:29:32.922716', '2023-01-27 02:29:32.922716', NULL, 'Ryan Levesque');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1316, 'راجر داوسون', '<p>راجر داوسون نویسنده و سخنران تمام وقت در موضوعات مذاکره، متقاعدسازی، تصمیم گیری و حل مسئله از سال 1982 بوده است. قبل از این، او حرفه ای موفق به عنوان مذاکره کننده قدرت در صنعت املاک و مستغلات داشت. او اسرار موفقیت خود را از طریق برنامه های صوتی، سمینارها و سخنرانی ها به صدها هزار نفر آموزش داده است. از دیگر کتاب‌های او می‌توان به <em>Secrets of Power Problem Solving</em> (2010)، <em>Secrets of Power Salary Negotiating</em> (2006) و <em>Secrets of Power Persuasion</em> (1992) اشاره کرد. . در سال 1991 به تالار مشاهیر سخنران راه یافت. </p>', '2023-01-27 02:29:40.274887', '2023-01-27 02:29:40.274887', NULL, 'Roger Dawson');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1317, 'کیتی بیچر', '<p>کتی بیچر یک مشاور مجاز و متخصص پزشکی با 30 سال تجربه است. مشتریان او شامل افراد مشهور و مدیران عامل هستند و کارهای او در Goop به نمایش درآمده است. <em>شفا از درون </em>اولین کتاب او است.</p>', '2023-01-27 02:29:47.874004', '2023-01-27 02:29:47.874004', NULL, 'Katie Beecher');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1318, 'لورا کلاین', '<p>لورا کلاین بیش از دو دهه مهندس، طراح UX، مدیر محصول و مشاور بوده است و در سیلیکون ولی با شرکت‌های نوپا کوچک و شرکت‌های بزرگ کار می‌کند. او یک وبلاگ پرطرفدار به نام <em>کاربران می‌دانند، </em> دارد، و او مجری دو پادکست است: <em>What Is Wrong With UX</em>و<em>Engsplaining</em>. او یک کتاب دیگر نوشته است، <em>محصولات بهتر بسازید</em>.</p>', '2023-01-27 02:29:55.432827', '2023-01-27 02:29:55.432827', NULL, 'Laura Klein');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1319, 'جک ولش با سوزی ولش', '<p>نام جک ولش مترادف با رهبری استاندارد طلایی و مدیریت موفق شرکت است. او چهل سال را در جنرال الکتریک (GE) گذراند و در بیست سال گذشته به عنوان مدیر عامل شرکت کرد و آنقدر موفقیت کسب کرد که به یک اسطوره زنده در دنیای تجارت تبدیل شد.</p>', '2023-01-27 02:30:03.26022', '2023-01-27 02:30:03.26022', NULL, 'Jack Welch with Suzy Welch');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1320, 'هال ادوارد رانکل', '<p>هال ادوارد رانکل یک درمانگر خانواده و ازدواج، معلم و سخنران در موضوعاتی مانند روابط خانوادگی است. <em>Screamfree Parenting</em> اولین کتاب پرفروش او در یک سری کتاب در مورد روابط بدون جیغ بود.</p>', '2023-01-27 02:30:10.382189', '2023-01-27 02:30:10.382189', NULL, 'Hal Edward Runkel');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1321, 'مارک هرست', '<p>مارک هرست فارغ التحصیل MIT و همچنین بنیانگذار و مدیر عامل Creative Good است، یک سرویس مشاوره با تمرکز بر بهبود تجربه مشتری. او همچنین کتاب بسیار تحسین شده <em>مشتریان شامل</em> را نوشت.</p>', '2023-01-27 02:30:22.504116', '2023-01-27 02:30:22.504116', NULL, 'Mark Hurst');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1322, 'بن گلداکر', '<p>بن گلداکر یک پزشک، روزنامه نگار و نویسنده دو کتاب است. ستون علوم بد او در <em>گاردین</em> به طب جایگزین حمله کرد و نقطه شروع این کتاب بود که در فهرست نهایی جایزه ساموئل جانسون بی‌بی‌سی برای ادبیات غیرداستانی قرار گرفت.</p>', '2023-01-27 02:40:19.450702', '2023-01-27 02:40:19.450702', NULL, 'Ben Goldacre');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1323, 'دیوید جی مک نف', '<p>دیوید جی. مک‌نف یک مربی اجرایی برای شرکت‌های سراسر جهان و مدیر عامل گروه مشاوره پیک است. کتاب‌های قبلی او شامل <em>درس‌هایی از پرتگاه</em> است.</p>', '2023-01-27 02:40:26.55083', '2023-01-27 02:40:26.55083', NULL, 'David J. McNeff');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1324, 'آبهیجیت وی بانرجی و استر دوفلو', '<p>ابهیجیت وی. بانرجی و استر دوفلو برنده جایزه نوبل اقتصاد 2019 به پاس کمک هایشان در زمینه اقتصاد توسعه شدند. کتاب قبلی آنها <em>Poor Economics</em> تحقیقی پیشگام در مورد معنای فقیر بودن و چگونگی ارائه مؤثرترین کمک به جوامع در حال مبارزه بود. آنها هر دو استاد دانشگاه MIT هستند و افتخارات و جوایز متعدد علمی دریافت کرده اند. </p>', '2023-01-27 02:40:40.290785', '2023-01-27 02:40:40.290785', NULL, 'Abhijit V. Banerjee and Esther Duflo');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1325, 'ریچارد اچ. تالر و کاس آر. سانستاین', '<p>ریچارد اچ. تالر (متولد 1945) استاد علوم رفتاری و اقتصاد در دانشگاه شیکاگو است. Cass R. Sunstein (متولد 1954) استاد دانشکده حقوق هاروارد است و به عنوان مشاور رئیس جمهور باراک اوباما خدمت می کند.</p>', '2023-01-27 02:40:48.000848', '2023-01-27 02:40:48.000848', NULL, 'Richard H. Thaler and Cass R. Sunstein');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1326, 'میشل جیلان', '<p>میشل جیلان، نویسنده پرفروش، روزنامه نگار و استاد برجسته دوره شادی اپرا است. گزارش کار او در مورد بحران مالی سال 2008 به عنوان یک مجری اخبار ملی CBS، در نهایت باعث شد تا او مؤسسه تحقیقات مثبت کاربردی را تأسیس کند.</p>', '2023-01-27 02:40:55.962506', '2023-01-27 02:40:55.962506', NULL, 'Michelle Gielan');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1327, 'ملودی بیتی', '<p>ملودی بیتی از پیشگامان ادبیات خودیاری، مشاور سابق بهبودی، و الکلی و وابسته به هم در حال بهبودی است. آثار دیگر او عبارتند از <em>Beyond Codependency</em>و <em>The Language of Letting Go. </em></p>', '2023-01-27 02:41:03.639716', '2023-01-27 02:41:03.639716', NULL, 'Melody Beattie');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1328, 'بیل مک کیبن', '<p>بیل مک کیبن استاد مطالعات محیطی در کالج میدلبری در ورمونت، بنیانگذار سازمان محیط زیست 350.org و نویسنده 17 کتاب است. این کتاب ها شامل سه کتاب پرفروش است: <em>پایان طبیعت</em>، <em>اقتصاد عمیق</em> و <em>زمین: ساختن زندگی در سیاره جدید سخت</em>. او همچنین جایزه گاندی، جایزه توماس مرتون، و جایزه زندگی درست را برای فعالیت سیاسی و حمایت از تغییرات آب و هوا دریافت کرده است.</p>', '2023-01-27 02:41:11.201407', '2023-01-27 02:41:11.201407', NULL, 'Bill McKibben');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1329, 'کریس سی داکر', '<p>کریس سی داکر بنیانگذار و مدیر عامل سه کسب و کار است و به طور گسترده به عنوان یک مرجع پیشرو در برون سپاری در نظر گرفته می شود. او یک سخنران، وبلاگ نویس و پادکست بین المللی محبوب است و تعدادی کتاب الکترونیکی نوشته است.</p>', '2023-01-27 02:41:19.191433', '2023-01-27 02:41:19.191433', NULL, 'Chris C. Ducker');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1330, 'پیتر دزبرگ و جفری دیویس', '<p>پیتر دزبرگ استاد بازنشسته در دانشگاه ایالتی کالیفرنیا و همچنین یک روانشناس فعال است. او 23 کتاب در طول زندگی حرفه‌ای خود نوشته است و برای شرکت‌هایی مانند اپل، تویوتا و بوئینگ مشاوره ارائه کرده است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1331, 'جولی دیرکسن', '<p> جولی دیرکسن یک طراح آموزشی، مشاور یادگیری و نویسنده است. او راه‌حل‌های آموزش الکترونیکی نوآورانه‌ای را برای برخی از بزرگترین شرکت‌های جهان - از جمله گوگل، مایکروسافت، و فدرال اکسپرس (FedEx) طراحی کرده است.</p>', '2023-01-27 02:41:40.438815', '2023-01-27 02:41:40.438815', NULL, 'Julie Dirksen');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1345, 'نوام واسرمن', '<p>نوام واسرمن استاد دانشکده بازرگانی هاروارد است. او در سال 2010 جایزه آکادمی مدیریت نوآوری در آموزش را برای دوره ای که بر اساس <em>معضلات بنیانگذار</em> تدریس کرد، دریافت کرد. همچنین به عنوان یکی از برترین دوره های کارآفرینی در کشور توسط <em>Inc. مجله</em> در سال 2011.</p>', '2023-01-27 02:43:49.796653', '2023-01-27 02:43:49.796653', NULL, 'Noam Wasserman');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1332, 'مایکل روبرتو', '<p>مایکل روبرتو، استاد معتمد مدیریت در دانشگاه برایانت در رود آیلند است. او استراتژی کسب‌وکار، تصمیم‌گیری مدیریتی و رهبری را تدریس می‌کند و نویسنده کتاب‌های متعددی در این زمینه‌ها است، از جمله <em>چرا رهبران بزرگ به‌عنوان پاسخ بله را نمی‌پذیرند</em>. </p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1333, 'بو برلینگهام', '<p>Bo Burlingham سردبیر مجله <em>Inc.</em> است و برای نشریات دیگری مانند <em>Mother Jones</em>، <em>Boston Magazine</em> و <em نوشته است. >Esquire.</em> او همچنین عضو هیئت مدیره <em>Body Shop Inc.</em> بوده و شبکه تجاری جهانی <em>PAC World</em> را تأسیس کرده است.</p>', '2023-01-27 02:42:01.161905', '2023-01-27 02:42:01.161905', NULL, 'Bo Burlingham');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1334, 'لورا تونبریج', '<p>لورا تونبریج محقق رمانتیسم آلمانی و موسیقی قرن نوزدهم است. او سه مونوگراف نوشته است، از جمله یکی درباره آهنگساز آلمانی رابرت شومان، و در حال حاضر استاد موسیقی و عضو هنفری در کالج سنت کاترین، دانشگاه آکسفورد است.</p>', '2023-01-27 02:42:08.856591', '2023-01-27 02:42:08.856591', NULL, 'Laura Tunbridge');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1335, 'دایانا ریچاردسون', '<p>دایانا ریچاردسون از سال 1993 مدیتیشن و تانترا را به زوج ها آموزش می دهد. او همچنین یک درمانگر بدن آموزش دیده است و کتاب های پرفروش <em>جنس تانتریک برای مردان</em>، <em>قلب تانتریک را نوشته است. سکس،</em> و <em>ارگاسم تانتریک برای زنان</em>.</p>', '2023-01-27 02:42:16.912756', '2023-01-27 02:42:16.912756', NULL, 'Diana Richardson');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1336, 'استیون هیل', '<p>استیون هیل از اعضای ارشد بنیاد آمریکای جدید است. نوشته های او در<em>نیویورک تایمز</em>، <em>گاردین</em> و <em>هافینگتون پست</em> منتشر شده است، و کتاب های پرفروش او شامل <em است که بسیار تحسین شده است. >وعده اروپا</em>.</p>', '2023-01-27 02:42:30.676071', '2023-01-27 02:42:30.676071', NULL, 'Steven Hill');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1337, 'کریستی شن و برایس لیونگ', '<p>کریستی شن و برایس لیونگ هر دو قبل از اینکه تصمیم بگیرند مسابقه موش را ترک کنند و زودتر بازنشسته شوند، به عنوان مهندس در کانادا آموزش دیدند. امروز، آنها میلیونر هستند و وقت خود را صرف سفر به دنیا، سخنرانی و نوشتن مقاله برای پلتفرم خودیاری خود، انقلاب هزاره می کنند. داستان زندگی واقعی الهام بخش آنها در رسانه های سراسر جهان از جمله <em>نیویورک تایمز</em>، <em>ایندیپندنت</em> بریتانیا، <em>هندلزبلات</em> آلمان و <em>مجله سلامت زنان </em>در استرالیا. </p>', '2023-01-27 02:42:38.530356', '2023-01-27 02:42:38.530356', NULL, 'Kristy Shen and Bryce Leung');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1338, 'جیادا دی لورنتیس', '<p>گیادا دی لورنتیس یک سرآشپز، شخصیت تلویزیونی و نویسنده ایتالیایی-آمریکایی است. او ستاره برنامه های <em>ایتالیایی روزمره</em>، <em>بازی های آخر هفته گیادا</em> و <em>گیادا در بهشت</em> از شبکه غذایی است. او مرتباً به عنوان مشارکت‌کننده و مهماندار در <em>Today</em> NBC ظاهر می‌شود.</p>', '2023-01-27 02:42:45.987811', '2023-01-27 02:42:45.987811', NULL, 'Giada De Laurentiis');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1339, 'هلن راسل', '<p>هلن راسل روزنامه نگار و نویسنده بریتانیایی است که آثارش در <em>The</em> <em>Times</em>، <em>Guardian</em>، <em>The</em> ظاهر شده است. > <em>وال استریت ژورنال</em> و سایر انتشارات.</p>', '2023-01-27 02:42:53.870288', '2023-01-27 02:42:53.870288', NULL, 'Helen Russell');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1340, 'راب نایت با برندان بوهلر', '<p> راب نایت استاد دپارتمان اطفال و دپارتمان علوم کامپیوتر UC San Diego است. او همچنین سردبیر ارشد <em>ISME Journal</em> و یکی از بنیانگذاران پروژه American Gut است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1341, 'ونسا استویکوف', '<p>ونسا استویکوف بنیانگذار و مدیر اجرایی گروه رسانه ای Evolution، یک شرکت تولیدی است. بینش های مالی استوکوف در نشریاتی مانند News.com.au،<em>Daily Telegraph</em>و<em>Money Magazine</em> به نمایش گذاشته شده است، و او همچنین خالق برنامه تلویزیونی استرالیایی <em است. >از Money Masters—The Investment Series</em>.</p> بیاموزید
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1342, 'توماس لوئیس', '<p>این کتاب توسط سه روانپزشک نوشته شده است: توماس لوئیس، فری امینی و ریچارد لنون که استادان دانشکده پزشکی دانشگاه کالیفرنیا، سانفرانسیسکو هستند. لوئیس استادیار بالینی روانپزشکی است. امینی، استاد روانپزشکی؛ و لنون، ​​دانشیار بالینی روانپزشکی.</p>', '2023-01-27 02:43:22.179215', '2023-01-27 02:43:22.179215', NULL, 'Thomas Lewis');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1343, 'قهوه ای آدرین ماری', '<p>آدرین ماری براون نویسنده، دولا و فعالی است که در برنامه‌های اجتماعی متعددی از جمله ائتلاف کاهش آسیب و انجمن راکوس شرکت داشته است. او قبلاً ستون‌نویس مجله <em>Bitch </em> بود و نویسنده <em>Emergent Strategy</em> و ویراستار <em>Octavia''s Brood</em> است - که هر دو بر اساس کار اکتاویا ای. باتلر، نویسنده علمی تخیلی و فانتزی برنده جایزه.</p>', '2023-01-27 02:43:30.053589', '2023-01-27 02:43:30.053589', NULL, 'adrienne maree brown');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1344, 'ایندرا نویی', '<p>ایندرا نویی بیشتر به خاطر حرفه قابل توجه خود در PepsiCo شناخته می شود. نویی از سال 2006 تا 2018 مدیر عامل شرکت بود و مسئول یک استراتژی نوآورانه با تمرکز بر سلامت و پایداری محیط زیست بود. او اغلب به عنوان یکی از قدرتمندترین زنان جهان رتبه بندی شده است.</p>', '2023-01-27 02:43:42.593349', '2023-01-27 02:43:42.593349', NULL, 'Indra Nooyi');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1347, 'Mirjam Neelen & Paul A. Kirschner', '<p>میرجام نیلن رئیس طراحی یادگیری جهانی و علوم یادگیری در Novartis است. او در 15 سال گذشته در نقش‌های طراحی یادگیری مختلف کار کرده است، از جمله در Accenture، Google، و Houghton Mifflin Harcourt.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1348, 'مایکل اریک دایسون', '<p>مایکل اریک دایسون یک روشنفکر عمومی مورد احترام است و نویسنده پرفروش‌ترین کتاب‌های <em>نیویورک تایمز</em> <em>اشک‌هایی که نمی‌توانیم متوقف کنیم</em> و <em>حقیقت چگونه به نظر می‌رسد</em> em>. او همچنین نویسنده نظر برای <em>نیویورک تایمز</em> و سردبیری در <em>New Republic</em> و <em>The Undefeated</em> در ESPN است. دایسون مقام برجسته ای را به عنوان استاد جامعه شناسی دانشگاه در دانشگاه جورج تاون دارد، جایی که او یک دوره تحسین شده در مورد زندگی و کار جی زی تدریس می کند. </p>', '2023-01-27 02:44:12.719208', '2023-01-27 02:44:12.719208', NULL, 'Michael Eric Dyson');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1349, 'درن براون', '<p>درن براون نویسنده و مجری تلویزیونی است که بیشتر به خاطر سریال 2000 خود <em>کنترل ذهن</em> شناخته می شود، کاوشی جذاب و گهگاهی آزاردهنده در مورد دستکاری روانی. براون همچنین نویسنده <em>ترفندهای ذهن</em>و <em>اعترافات یک جادوگر</em> است. </p>', '2023-01-27 02:44:19.735895', '2023-01-27 02:44:19.735895', NULL, 'Derren Brown');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1350, 'لری داونز و پل نونز', '<p>لاری داونز یک تحلیلگر صنعت اینترنت است که ستون‌هایش برای <em>Forbes </em>و CNET در مورد تأثیرات فناوری مخرب بر سیاست و تجارت بحث می‌کند. از دیگر کتاب های او می توان به <em>Unleashing the Killer App</em>(1998) و <em>The Laws of Disruption</em> (2009) اشاره کرد.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1351, 'لورا واتلی', '<p>لورا واتلی یک روزنامه نگار برنده جایزه است که در امور مالی مصرف کننده تخصص دارد. او بیشتر به خاطر ستون عمه عمه اش با مضمون پول - که با نام مستعار «اشکال یاب» نوشته شده است - که برای <em>تایمز</em> می نویسد، مشهور است. او همچنین در مورد موضوع مالی شخصی برای نشریات دیگری مانند <em>The Guardian</em>، <em>The Observer</em>، <em>Dow Jones</em> و <em>Moneywise< می نویسد. /em> مجله.</p>', '2023-01-27 02:44:41.944989', '2023-01-27 02:44:41.944989', NULL, 'Laura Whateley');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1352, 'کن بلانچارد و اسپنسر جانسون', '<p>کن بلانچارد مشاور تجاری، سخنران و نویسنده پرفروش، و همچنین مدیر ارشد معنوی شرکت‌های کن بلانچارد است که غول‌های چندملیتی از شل تا مرک را مربیگری کرده‌اند. اسپنسر جانسون، دکتر، نویسنده <em>نیویورک تایمز</em> برترین نمودار <em>چه کسی پنیر من را جابجا کرد؟ </em>و عضو سابق رهبری در مدرسه بازرگانی هاروارد.</p>', '2023-01-27 02:44:44.513197', '2023-01-27 02:44:44.513197', NULL, 'Ken Blanchard and Spencer Johnson');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1353, 'اندرس اریکسون و رابرت پول', '<p>اندرس اریکسون استاد روانشناسی و محقق برجسته کنرادی در دانشگاه ایالتی فلوریدا است. آثار او در کتاب‌های پرفروش <em>راهپیمایی ماه با انیشتین</em> و <em>چگونه کودکان موفق می‌شوند</em> ذکر شده است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1354, 'لئو هامبلین', '<p>لئو همبلین مربی و بنیانگذار کوچینگ همبلین است.</p>', '2023-01-27 02:44:59.976135', '2023-01-27 02:44:59.976135', NULL, 'Leo Hamblin');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1355, 'پادشاه بدجنس', '<p>Vex King یک تأثیرگذار، نویسنده و کارآفرین بریتانیایی هندی در رسانه های اجتماعی است. او همچنین بنیانگذار Bon Vita است، یک برند سبک زندگی که بر دیدگاه‌های نشاط‌آور، بینش‌های معنوی و راه‌حل‌های قابل دسترس تمرکز دارد.</p>', '2023-01-27 02:45:07.53421', '2023-01-27 02:45:07.53421', NULL, 'Vex King');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1356, 'مارک اچ مک کورمک', '<p>مارک اچ. مک کورمک (1930-2003) گروه مدیریت بین المللی (IMG) را تأسیس کرد و چندین سال ریاست آن را برعهده داشت، یک سازمان بین المللی که خدمات مشاوره، بازاریابی و مدیریت را به چهره های برجسته ورزش و همچنین سایر افراد مشهور ارائه می دهد. مک کورمک زمانی خودش یک گلف باز مشتاق بود و بعداً به دنیای تجارت روی آورد. او همچنین یک وکیل و نویسنده بود و چندین کتاب از جمله <em>حقیقت وحشتناک درباره وکلا</em> نوشت.</p>', '2023-01-27 02:45:15.441156', '2023-01-27 02:45:15.441156', NULL, 'Mark H. McCormack');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1357, 'جیسون گیگنارد', '<p>Jason Gaignard یک کارآفرین سریالی است که رویدادهای شبکه بزرگی را برای کارآفرینان و افراد تجاری سازماندهی می کند و همچنین میزبان یک پادکست تجاری با رتبه بالا در iTunes است.</p>', '2023-01-27 02:45:23.310339', '2023-01-27 02:45:23.310339', NULL, 'Jayson Gaignard');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1358, 'استیو جی. مارتین', '<p>دکتر نوح گلدشتاین دانشیار مدیریت و سازمان در دانشکده مدیریت UCLA اندرسون است و همچنین قرار ملاقات های مشترکی در بخش روانشناسی و دانشکده پزشکی دیوید گفن دارد. او برنده جوایزی هم در زمینه تدریس و هم در پژوهش است و در <em>هیئت مشاوره علمی</em> دو شرکت <em>Fortune Global 500</em> بود.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1360, 'اریکا استنفورد', '<p>اریکا استنفورد یک مدرس و متخصص در زمینه ارزهای دیجیتال است. او Crypto Curry Club، برترین انجمن شبکه‌های ارزهای دیجیتال در بریتانیا را تأسیس کرد و خبرنامه مرتبط با پرخواننده <em>Crypto Currier</em> را ویرایش می‌کند.</p>', '2023-01-27 02:45:44.757714', '2023-01-27 02:45:44.757714', NULL, 'Erica Stanford');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1361, 'النا بوتلهو و کیم پاول', '<p>النا بوتلهو و کیم پاول هر دو پیشینه‌ای در تجارت دارند، که باعث شد روی ghSMART کار کنند، بزرگترین مطالعه‌ای که تاکنون در مورد شخصیت و ذهنیت رهبران تجارت جهانی انجام شده است. بوتلهو و پاول همچنین به مدیران ارشد اجرایی و مدیران ارشد مشاوره می دهند.</p>', '2023-01-27 02:45:52.006228', '2023-01-27 02:45:52.006228', NULL, 'Elena Botelho and Kim Powell');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1362, 'ویلیام ای. پل', '<p>ویلیام ای. پال، دکتر، رئیس آزمایشگاه ایمونولوژی در مؤسسه ملی آلرژی و بیماری‌های عفونی، یکی از مؤسسه‌های ملی بهداشت بود. او همچنین به عنوان رئیس انجمن ایمونولوژیست های آمریکا خدمت کرد.</p>', '2023-01-27 02:45:59.322698', '2023-01-27 02:45:59.322698', NULL, 'William E. Paul');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1363, 'لیام وان', '<p>لیام وان یک خبرنگار تحقیقی است که برای <em>اخبار بلومبرگ</em>و <em>بلومبرگ</em> <em>بیزینس‌ویک</em> در لندن می‌نویسد. او جایزه هارولد وینکات را برای بهترین روزنامه نگاری مالی در سال 2013 به عنوان بخشی از تیم <em>Bloomberg</em> و جایزه جرالد لوب برای برتری در روزنامه نگاری تجاری در سال 2014 دریافت کرد.</p>', '2023-01-27 02:46:06.942663', '2023-01-27 02:46:06.942663', NULL, 'Liam Vaughan');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1364, 'دیوید اشپیگلهالتر', '<p>دیوید اشپیگلهالتر آماردان بریتانیایی و ارتباط دهنده آمار است. او که یکی از پژوهشگران معتبر و تاثیرگذار در زمینه خود است، به عنوان استاد وینتون برای درک عمومی از ریسک در آزمایشگاه آماری دانشگاه کمبریج خدمت می کند. او در سال‌های 2017 و 2018 رئیس انجمن سلطنتی آمار بود.</p>', '2023-01-27 02:46:13.821954', '2023-01-27 02:46:13.821954', NULL, 'David Spiegelhalter');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1365, 'سیسیل وودهام اسمیت', '<p>سسیل وودهام اسمیت نویسنده برجسته و برنده جوایز کتاب های تاریخی مربوط به دوران ویکتوریا بود. او پس از گذراندن نه سال دقیق برای تحقیق و نوشتن اولین کتاب خود، در مورد فلورانس نایتینگل، به انتشار کتاب‌هایی درباره قحطی بزرگ ایرلند و اتهام بدنام تیپ نور ادامه داد.</p>', '2023-01-27 02:46:20.556666', '2023-01-27 02:46:20.556666', NULL, 'Cecil Woodham Smith');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1366, 'پگی جی. کلاین پلاتز و آ. دانا منارد', '<p>Peggy J. Kleinplatz، دکترا، در دانشگاه اتاوا، کانادا کار می کند، جایی که او استاد دانشکده پزشکی و مدیر آموزش جنسی و زوج درمانی است. او نویسنده <em>جهت‌های جدید در رابطه جنسی درمانی</em>، در میان آثار دیگر است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1367, 'بیلی جین کینگ', '<p>بیلی جین کینگ از بازی تنیس در زمین‌های عمومی در جنوب کالیفرنیا به بازیکن زن شماره یک جهان تبدیل شد. او رهبری اولین تور تنیس حرفه ای زنان را بر عهده داشت و در این راه 39 عنوان گرند اسلم را به دست آورد. او یکی از بنیانگذاران ابتکار رهبری Billie Jean King و سفیر جهانی جام Billie Jean King است.</p>', '2023-01-27 02:46:34.073618', '2023-01-27 02:46:34.073618', NULL, 'Billie Jean King');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1368, 'و آریلی', '<p>دن آریلی، استاد روانشناسی و اقتصاد رفتاری در دانشگاه دوک، نویسنده سه بار پرفروش <em>نیویورک تایمز</em> و بنیانگذار مرکز آینده نگری پیشرفته است.</p>', '2023-01-27 02:46:41.013346', '2023-01-27 02:46:41.013346', NULL, 'Dan Ariely');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1369, 'وارن برگر', '<p>وارن برگر نویسنده، روزنامه نگار و وبلاگ نویس آمریکایی در سایت <em>یک سوال زیباتر</em> است. او تعدادی کتاب، از جمله <em>Glimmer</em> و <em>No Opportunity Wasted</em> را نوشته و در نویسندگی مشترکی بر عهده داشته است.</p>', '2023-01-27 02:46:47.730614', '2023-01-27 02:46:47.730614', NULL, 'Warren Berger');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1370, 'آدام اسمیت', '<p>آدام اسمیت یک فیلسوف و اقتصاددان اسکاتلندی بود که اغلب او را "پدر اقتصاد مدرن" می نامند، زیرا او اولین بار از بازار آزاد به عنوان راهی به سوی رفاه حمایت کرد. <em>ثروت ملل</em> اثر بزرگ او و اثری است که هنوز هم تاثیرگذار است.</p>', '2023-01-27 02:46:55.012727', '2023-01-27 02:46:55.012727', NULL, 'Adam Smith');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1371, 'رابرت مورر', '<p>رابرت مورر یک روانشناس بالینی در UCLA و دانشکده پزشکی دانشگاه واشنگتن است. او سخنرانی‌ها و سمینارهای منظمی در مورد کایزن ترتیب می‌دهد و نویسنده <em>روح کایزن</em>و <em>مسلط بر ترس</em> است.</p>', '2023-01-27 02:47:03.252328', '2023-01-27 02:47:03.252328', NULL, 'Robert Maurer');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1372, 'مایک پایپر', '<p>مایک پایپر نویسنده هشت کتاب مالی و همچنین وبلاگ محبوب Oblivious Investor است. پایپر که یک حسابدار رسمی رسمی است، مقالاتی را در <em>وال استریت ژورنال</em>، <em>Money</em> و <em>Forbes</em> منتشر کرده است.</p>', '2023-01-27 02:47:10.336137', '2023-01-27 02:47:10.336137', NULL, 'Mike Piper');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1373, 'جین فینکل', '<p>جین فینکل دو دهه گذشته را صرف کمک به افراد برای دستیابی به پتانسیل کامل در محل کار خود با ارائه ارزیابی های شغلی، راهنمایی جستجوی شغل و خدمات تنظیم محل کار کرده است. فینکل قبل از تأسیس دفتر مشاوره خود، خدمات مشاوره شغلی را در دانشگاه پنسیلوانیا به دانشجویان ارائه کرد. </p>', '2023-01-27 02:47:17.810233', '2023-01-27 02:47:17.810233', NULL, 'Jane Finkle');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1374, 'برندون بورچارد', '<p>برندون بورچارد یکی از موفق‌ترین مربیان با عملکرد بالا و بنیان‌گذار آکادمی متخصصان و آکادمی با عملکرد بالا است. او همچنین پرفروش‌ترین نویسنده کتاب‌هایی مانند <em>مانیفست انگیزه، پیام‌رسان میلیونر</em>و<em> اتهام</em> است.</p>', '2023-01-27 02:47:25.471528', '2023-01-27 02:47:25.471528', NULL, 'Brendon Burchard');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1375, 'شعبه دیوید', '<p>دیوید تسوایگ نویسنده ای پرکار است که آثارش در<em> ماهنامه آتلانتیک، </em><em> نیویورک تایمز </em>و<em>وال استریت ژورنال</em> به نمایش درآمده است. او همچنین خواننده، گیتاریست و تهیه کننده است و دو آلبوم منتشر کرده است. اولین رمان او <em>شنا در درون خورشید</em> نام داشت.</p>', '2023-01-27 02:48:00.298682', '2023-01-27 02:48:00.298682', NULL, 'David Zweig');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1376, 'اس. کریس ادموندز', '<p>کریس ادموندز موسس و مدیر عامل یک شرکت مشاوره فرهنگ سازمانی به نام گروه فرهنگ هدفمند است. او نویسنده ای پرکار و استاد کمکی در دانشکده بازرگانی دانشگاه سن دیگو است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1377, 'مارک لوینسون', '<p>مارک لوینسون روزنامه نگار و نویسنده ای است که استراتژی اقتصادی و تجاری را با دیدگاه تاریخی ترکیب می کند. او پنج کتاب پرفروش و مقالات بی‌شماری نوشته است که مسائل پیچیده اقتصادی را در قالبی به راحتی قابل درک هضم می‌کند.</p>', '2023-01-27 02:48:19.540518', '2023-01-27 02:48:19.540518', NULL, 'Marc Levinson');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1378, 'چه استارکی', '<p> کیو استارک نویسنده و استاد کمکی در برنامه ارتباطات از راه دور فارغ التحصیل دانشگاه نیویورک است. او علاوه بر انجام تحقیقات فعال در زمینه یادگیری و آموزش، رمانی با عنوان <em>من را دنبال کنید</em> نیز منتشر کرده است.</p>', '2023-01-27 02:48:26.505376', '2023-01-27 02:48:26.505376', NULL, 'Kio Stark');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1379, 'استیو هاگن', '<p>استیو هاگن یک کشیش ذن و معلم بودیسم است. او همچنین نویسنده <em>جهان چگونه می تواند اینگونه باشد: تحقیقی برای هزاره جدید در علم، فلسفه و ادراک است. </em></p>', '2023-01-27 02:48:33.241079', '2023-01-27 02:48:33.241079', NULL, 'Steve Hagen');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1380, 'جولی مورگنسترن', '<p> جولی مورگنسترن شرکت سازماندهی حرفه ای Taskmasters را تأسیس کرد، یک شرکت مشاوره با مشتریانی مانند American Express. وقتی او کسب و کار خود را اداره نمی کند، ایده های خود را به عنوان یک ستون نویس منتشر می کند یا در مورد آنها در تلویزیون صحبت می کند. سازماندهی از درون بیرون اولین کتاب پرفروش او بود.</p>', '2023-01-27 02:48:40.91459', '2023-01-27 02:48:40.91459', NULL, 'Julie Morgenstern');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1381, 'گروه لائو تی', '<p>لائوتسه مدت‌هاست که نویسنده اصلی <em>تائو ته چینگ</em> در نظر گرفته می‌شود، اگرچه هم درباره نویسندگی و هم وجود او به عنوان یک شخصیت تاریخی بحث‌های زیادی وجود دارد. برخی معتقدند او معاصر کنفوسیوس بوده و در قرن ششم قبل از میلاد زندگی می‌کرده است، برخی دیگر معتقدند زندگی او به قرن چهارم قبل از میلاد باز می‌گردد.</p>', '2023-01-27 02:48:48.2527', '2023-01-27 02:48:48.2527', NULL, 'Lao Tzu');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1382, 'توماس جی استنلی و ویلیام دی. دانکو', '<p>توماس جی استنلی محقق و نویسنده چندین کتاب برنده جایزه در مورد ثروتمندان است، از جمله <em>زنان میلیونر همسایه</em>، <em>بازاریابی برای مرفه</em> و <em> فروش به مرفهان</em>.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1383, 'بالتاسار گراسیان یا مورالس', '<p>بالتاسار گراسیان یک کشیش، فیلسوف و رمان‌نویس یسوعی اسپانیایی قرن هفدهم بود. در طول قرن‌ها، <em>هنر حکمت دنیوی</em> او بارها به بیش از ده‌ها زبان تجدید چاپ شده است. در سال 1992، یک ترجمه جدید انگلیسی بیش از 200000 نسخه فروخت و در صدر فهرست پرفروش‌ترین‌های آمریکا قرار گرفت.</p>', '2023-01-27 02:49:08.901513', '2023-01-27 02:49:08.901513', NULL, 'Baltasar Gracián y Morales');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1384, 'نیکولای جی. فاس و پیتر جی کلاین', '<p>Nicolai J. Foss و Peter G. Klein به ترتیب استادان استراتژی و کارآفرینی هستند. هر دو تحقیقات و نوشته های گسترده ای در مورد استراتژی کسب و کار و مطالعات سازمانی انجام داده اند. آنها بیش از 20 سال است که با یکدیگر همکاری می کنند و همچنین از نویسندگان <em>سازمان داوری کارآفرینی</em>و <em>دیدگاه های اتریشی در مورد کارآفرینی، استراتژی و سازمان</em></p> هستند.', '2023-01-27 02:49:17.360481', '2023-01-27 02:49:17.360481', NULL, 'Nicolai J. Foss & Peter G. Klein');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1385, 'دریک کینی', '<p>دریک کینی مدیر عامل Good Money Framework، مجری پادکست Good Money، و صدای تاثیرگذار در موضوع استفاده از پول برای خوب است. او که قبلاً مشاور مالی بود، تجارت چند میلیون دلاری خود را فروخت تا به جای آن روی Good Money Framework کار کند. </p>', '2023-01-27 02:49:48.743497', '2023-01-27 02:49:48.743497', NULL, 'Derrick Kinney');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1386, 'شریل کرشنباوم', '<p>شریل کرشنبام یک زیست شناس دریایی، نویسنده، سخنران عمومی و دانشمند پژوهشگر است. او در<em>Science Friday</em>و<em>Scientific American</em> NPR همکاری می کند و در <em>The Best American Science Writing 2010</em> حضور داشت.</p>', '2023-01-27 02:49:56.324916', '2023-01-27 02:49:56.324916', NULL, 'Sheril Kirshenbaum');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1387, 'کریستوفر لئونارد', '<p>کریستوفر لئونارد یک خبرنگار تجاری است. در میان انتشارات دیگر، آثار او در <em>فورچون</em>، <em>وال استریت ژورنال</em> و <em>واشنگتن پست</em> منتشر شده است. کتاب قبلی او، <em>The راکت گوشت</em>، به عنوان کتاب قابل توجه سال 2014 توسط <em>واشنگتن پست</em> فهرست شد. در سال 2017، <em>Kochland </em>برنده جایزه معتبر J. Anthony Lukas Work-in-Progress Award شد. </p>', '2023-01-27 02:50:04.31442', '2023-01-27 02:50:04.31442', NULL, 'Christopher Leonard');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1428, 'توماس ناگل', '<p>توماس ناگل، جان هوگان و جوزف زیل رهبران صنعت در قیمت‌گذاری استراتژیک هستند، که سهم قابل توجهی در تئوری و عمل قیمت‌گذاری، و همچنین توسعه نرم‌افزار برای کمک به کسب‌وکارها در سراسر جهان داشته‌اند. هوگان و زیل شرکای مانیتور دیلویت هستند، یک مرکز مشاوره استراتژی پیشرو مستقر در کمبریج، ماساچوست.</p>', '2023-01-27 02:55:48.977933', '2023-01-27 02:55:48.977933', NULL, 'Thomas Nagle');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1388, 'اروین شرودینگر', '<p>اروین شرودینگر، که در فرهنگ عامه به دلیل آزمایش فکری "گربه شرودینگر" شناخته می شود، یکی از تاثیرگذارترین فیزیکدانان تمام دوران بود. او برنده جایزه نوبل در سال 1933 برای پیشرفت هایش در نظریه اتمی، کمک های قابل توجهی در زمینه نظریه کوانتومی، و نوشتن در طیف گسترده ای از موضوعات دیگر مرتبط با فیزیک است. او یکی از چندین فیزیکدانی است که اغلب از آنها به عنوان "پدر مکانیک کوانتومی" یاد می شود.</p>', '2023-01-27 02:50:12.299538', '2023-01-27 02:50:12.299538', NULL, 'Erwin Schrödinger');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1389, 'توماس ام استرنر', '<p>توماس ام. استرنر فلسفه شرق و غرب و روانشناسی ورزش مدرن را مطالعه کرد. او که به عنوان تکنسین ارشد کنسرت برای یک مرکز بزرگ هنرهای نمایشی کار می کرد، پیانوی بزرگ کنسرت محل را برای صدها نوازنده مشهور جهان تهیه و نگهداری کرد. او همچنین یک برنامه رادیویی درباره ذهن تمرین‌کننده تولید کرد و همچنان تکنیک‌های خود را به تاجران و در کلینیک‌های ورزشی آموزش می‌دهد.</p>', '2023-01-27 02:50:24.887613', '2023-01-27 02:50:24.887613', NULL, 'Thomas M. Sterner');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1390, 'جنبش کارل کینز', '<p>کارول کینزی گومان مربی رهبری، مشاور مدیریت، سخنران اصلی و رئیس خدمات مشاوره کینزی است. او یازده کتاب منتشر کرده است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1391, 'تیموتی کلر', '<p>تیموتی کلر کشیش بنیانگذار کلیسای پروتستان رستگار در منهتن است، کلیسایی با جامعه ای متنوع از 5000 عبادت کننده هفتگی. کتابهای پرفروش <em>نیویورک تایمز</em> <em>دلیل خدا</em>و <em>خدای ولگرد</em>بیش از دو میلیون نسخه فروخته است.</p>', '2023-01-27 02:50:38.961501', '2023-01-27 02:50:38.961501', NULL, 'Timothy Keller');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1392, 'جیمز کالینز', '<p>جیمز کالینز یک متخصص تغذیه ورزشی و ورزشی پیشرو است که در ورزش نخبه تخصص دارد. او با تیم های المپیک بریتانیا کار کرده است و قبلاً رئیس تغذیه در باشگاه فوتبال آرسنال بود. </p>', '2023-01-27 02:50:45.729268', '2023-01-27 02:50:45.729268', NULL, 'James Collins');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1393, 'ندرا گلاور تواب', '<p>ندرا گلوور تواب یک درمانگر و گورو روابط دارای مجوز با بیش از 12 سال تجربه است که به افراد کمک می کند تا مشکلات رابطه خود را حل کنند. او بر اساس این فلسفه عمل می کند که علت اصلی اکثر مشکلات روابط، مرزهای ناسالم است. تواب همچنین یک درمانگر اینستاگرامی بسیار تأثیرگذار است که از این پلت فرم برای به اشتراک گذاشتن ابزارهای درمانی و میزبانی منظم پرسش و پاسخ در مورد مرزها و روابط استفاده می کند.</p>', '2023-01-27 02:50:52.57213', '2023-01-27 02:50:52.57213', NULL, 'Nedra Glover Tawwab');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1394, 'مایکل دی. آیزنر با آرون کوهن', '<p>Michael D. Eisner برای بیش از 40 سال پیشرو در صنعت سرگرمی آمریکا بوده است. پس از مدتی به عنوان رئیس و مدیرعامل <em>Paramount Pictures</em>، او بیش از 20 سال، از سال 1984 تا 2005، مدیر عامل <em>شرکت والت دیزنی</em> بود.', '2023-01-27 02:50:59.695375', '2023-01-27 02:50:59.695375', NULL, 'Michael D. Eisner with Aaron Cohen');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1395, 'دانیل ام. وگنر و کرت گری', '<p>دانیل ام. وگنر یک روانشناس برجسته، نویسنده <em>توهم اراده آگاه</em> و دریافت کننده، در میان بسیاری از جوایز دیگر، <em>جایزه مشارکت علمی برجسته</em> در سال 2011 بود. انجمن روانشناسی آمریکا.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1396, 'برایان بارو', '<p>برایان بارو و جان هلیار روزنامه نگارانی تحقیقی هستند که ماجرای خرید RJR Nabisco را در همان حال پوشش دادند. تحقیقات عمیق و مصاحبه های گسترده آنها تصویری جذاب از دوره ای منحصر به فرد در تاریخ وال استریت را ترسیم می کند.</p>', '2023-01-27 02:51:14.401747', '2023-01-27 02:51:14.401747', NULL, 'Bryan Burrough');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1397, 'جولیان باربور', '<p> جولیان باربور فیزیکدان نظری و استاد مدعو سابق در دانشگاه آکسفورد است. او نویسنده کتاب پرفروش <em>پایان زمان</em>است که در آن این نظریه را مطرح می کند که زمان صرفا یک توهم است.</p>', '2023-01-27 02:51:22.136953', '2023-01-27 02:51:22.136953', NULL, 'Julian Barbour');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1398, 'دیوید ژلز', '<p></p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1399, 'فارس یعقوب', '<p>فریس یاکوب یکی از بنیانگذاران Genius Steals است که یک مشاور استراتژی و نوآوری جهانی است. <em>توجه شد</em> اولین کتاب پرفروش اوست.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1400, 'دانیل لرنر و آلن شلتر', '<p>دانیل لرنر یک مربی بالینی در دانشگاه نیویورک است، جایی که او کلاس انتخابی بسیار محبوب "علم شادی" را با همکارش آلن شلچتر تدریس می کند. او با سابقه خود در روانشناسی مثبت، همچنین به عنوان مربی اجرا برای بسیاری از هنرمندان و مدیران برجسته کار می کند.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1401, 'بنجامین اسپال و مایکل زاندر', '<p>بنجامین اسپال یک نویسنده آمریکایی است که در طیف گسترده ای از نشریات از جمله <em>هافینگتون پست</em> همکاری داشته است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1402, 'جنیفر A. Doudna و ساموئل H. Sternberg', '<p> جنیفر آ. داودنا، دکترا، استاد شیمی و زیست‌شناسی مولکولی و سلولی در دانشگاه کالیفرنیا، برکلی است. او یک متخصص بین المللی پیشرو در زیست شناسی و مهندسی ژنوم CRISPR است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1403, 'الکساندر لوید', '<p>الکساندر لوید، دکترا، روانشناس، متخصص طبیعت و مدرس مشهور است. او همچنین نویسنده پرفروش ترین کتاب بین المللی، <em>رمز شفا</em> است.</p>', '2023-01-27 02:52:08.098755', '2023-01-27 02:52:08.098755', NULL, 'Alexander Loyd');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1404, 'مایک میکالوویچ', '<p>مایک میکالوویچ یک کارآفرین، متخصص تجارت و نویسنده شش کتاب است، از جمله <em>اول سود، کار ساعت، طرح کدو تنبل، </em>و<em> کارآفرین دستمال توالت. </em>میکالوویچ از طریق این کتاب‌ها، رویدادهای سخنرانی عمومی و مجموعه سخنرانی‌هایش برای برنامه‌های کارآفرینی دانشگاهی، به صاحبان مشاغل می‌آموزد که چگونه شرکت‌های خود را بهینه کنند.</p>', '2023-01-27 02:52:16.49088', '2023-01-27 02:52:16.49088', NULL, 'Mike Michalowicz');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1405, 'سنکا', '<p>لوسیوس آنائوس سنکا یا همان‌طور که بیشتر شناخته می‌شود، سنکا جوان، فیلسوف و دولتمرد رومی در قرن اول پس از میلاد بود. سنکا بخشی از مکتب فلسفی رواقی بود. او طیف گسترده ای از آثار، از جمله مقالات، نامه ها، تراژدی ها، زندگی نامه پدرش و حتی یک طنز منیپی نوشت.</p>', '2023-01-27 02:52:23.836497', '2023-01-27 02:52:23.836497', NULL, 'Seneca');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1406, 'ماری اف', '<p>ماری مونگان مدیر موسسه HypnoBirthing در نیوهمپشایر بود، بیش از چهار دهه تجربه به عنوان یک مشاور مجاز داشت و همچنین یک هیپنوتراپیست معتبر بود. در سال 2013، مونگان جایزه یک عمر دستاورد را از انجمن بین المللی مشاوران و درمانگران دریافت کرد. او در سال 2019 درگذشت. </p>', '2023-01-27 02:52:31.253064', '2023-01-27 02:52:31.253064', NULL, 'Marie F. Mongan');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1407, 'دیو کرپن', '<p> دیو کرپن نویسنده، سخنران و یکی از بنیانگذاران شرکت بازاریابی رسانه های اجتماعی Likeable Media است که جوایزی را دریافت کرده است. از دیگر کارهای او می توان به <em> کسب و کار دوست داشتنی</em>، <em>رهبری دوست داشتنی،</em> و <em>هنر مردم: 11 مهارت افراد ساده برای به دست آوردن هر چیزی که می خواهید</em> اشاره کرد.</p> >', '2023-01-27 02:52:39.643168', '2023-01-27 02:52:39.643168', NULL, 'Dave Kerpen');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1408, 'ناتالی هولت', '<p>کار ناتالیا هولت در <em>نیویورک تایمز</em>، <em>لس آنجلس تایمز</em>، <em>ساینس عامه پسند</em>و <em>آتلانتیک< به نمایش درآمده است. /em>. او سال ها با زنان JPL صحبت کرد و داستان های آنها را جمع آوری کرد. او همچنین نویسنده <em>درمان شده: افرادی که HIV را شکست دادند</em> است.</p>', '2023-01-27 02:52:47.377906', '2023-01-27 02:52:47.377906', NULL, 'Nathalia Holt');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1409, 'شلی آرچامبو', '<p> Shellye Archambeau یک تاجر با بیش از 30 سال تجربه در سازمان های فناوری پیشرو است. او 15 سال را در IBM گذراند و بعداً مدیرعامل یک شرکت دره سیلیکون شد که به MetricStream تبدیل شد - یک رهبر بازار جهانی در راه‌حل‌های نرم‌افزاری حاکمیت، ریسک و انطباق. او یکی از اعضای هیئت مدیره Fortune 500 است و همچنین در مدرسه وارتون دانشگاه پنسیلوانیا سخنرانی می کند.</p>', '2023-01-27 02:53:00.478939', '2023-01-27 02:53:00.478939', NULL, 'Shellye Archambeau');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1410, 'کریستوفر ام. شرودر', '<p>کریستوفر ام. شرودر یک کارآفرین و سرمایه گذار است. او برای <em>وال استریت ژورنال</em>، <em>Harvard Business Review</em>، <em>TechCrunch </em>و دیگران مطالب زیادی در مورد استارت‌آپ‌ها و خاورمیانه نوشته است.</p >', '2023-01-27 02:53:08.586976', '2023-01-27 02:53:08.586976', NULL, 'Christopher M. Schroeder');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1411, 'کارل سیگان', '<p>کارل سیگان ستاره شناس، نویسنده و محبوب کننده مشهور علم آمریکایی بود. او در نویسندگی و گویندگی مجموعه تلویزیونی <em>Cosmos: A Personal Voyage</em> که بر اساس کتاب پرفروش او ساخته شده بود، همکاری کرد. جوایز متعددی برای او به ارمغان آورد، از جمله جایزه امی برای دستاوردهای فردی برجسته.</p>', '2023-01-27 02:53:21.456983', '2023-01-27 02:53:21.456983', NULL, 'Carl Sagan');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1412, 'پیتر شنکمن', '<p>پیتر شنکمن یک کارآفرین آمریکایی و مشاور خدمات مشتری، بازاریابی، روابط عمومی و رسانه های اجتماعی است. او نویسنده چهار کتاب است، از جمله <em>آیا ما می توانیم این کار را انجام دهیم؟!', '2023-01-27 02:53:34.750174', '2023-01-27 02:53:34.750174', NULL, 'Peter Shankman');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1413, 'راس مک کمون', '<p>راس مک کامون، سردبیر ارشد مجله <em>Esquire</em> از سال 2005 و ستون نویس قدیمی مجله <em>Entrepreneur</em>، متخصص در آداب معاشرت تجاری است. او همچنین نویسنده <em>راهنمای فریبنده</em> است.</p>', '2023-01-27 02:53:42.46737', '2023-01-27 02:53:42.46737', NULL, 'Ross McCammon');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1414, 'رابرت اچ فرانک', '<p>رابرت فرانک یک اقتصاددان مشهور جهان و استاد اقتصاد گلدوین اسمیت در دانشگاه کرنل است. او مرتباً ستون «نمای اقتصادی» را برای <em>نیویورک تایمز </em> می نویسد و کتاب های بسیاری از جمله <em>طبیعت شناس اقتصادی</em>، <em>جامعه برنده همه چیز را می نویسد. em>، و <em>تحت نفوذ</em>.</p>', '2023-01-27 02:53:49.770529', '2023-01-27 02:53:49.770529', NULL, 'Robert H. Frank');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1415, 'مارتین سلیگمن', '<p>مارتین سلیگمن استاد روانشناسی و رئیس انجمن روانشناسی آمریکا است. او یکی از چهره‌های پیشرو در روان‌شناسی مثبت‌نگر است که بر رشد جنبه‌های مثبت روان انسان تمرکز دارد (برخلاف «روان‌شناسی سنتی» که عمدتاً به بیماری‌های روانی می‌پردازد). از دیگر کتاب های پرفروش او می توان به <em>کودک خوش بین</em>، <em>خوشبختی اصیل</em>و <em>شکوفایی</em> اشاره کرد.</p>', '2023-01-27 02:53:56.787551', '2023-01-27 02:53:56.787551', NULL, 'Martin Seligman');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1416, 'استیسی آبرامز', '<p>استیسی آبرامز سیاستمدار، فعال حقوق رای، وکیل و نویسنده آمریکایی است. او از سال 2007 تا 2017 در مجلس نمایندگان جورجیا خدمت کرد و از سال 2011 تا 2017 رهبر اقلیت بود.</p>', '2023-01-27 02:54:03.752873', '2023-01-27 02:54:03.752873', NULL, 'Stacey Abrams');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1417, 'آدرین هربرت', '<p>آدرین هربرت میزبان پادکست هفتگی <em>Power Hour</em>است که تا به امروز بیش از 1.5 میلیون دانلود داشته است. هربرت همچنین به عنوان مدیر نوآوری و عملکرد در Fiit، برترین برنامه تناسب اندام بریتانیا، فعالیت می کند. او که یک سخنران حرفه ای و انگیزشی است، سخنرانی های TEDx و همچنین صحبت های خصوصی در مشاغلی مانند اپل و WeWork داشته است. این اولین کتاب او است.</p>', '2023-01-27 02:54:11.308355', '2023-01-27 02:54:11.308355', NULL, 'Adrienne Herbert');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1418, 'دیوید فاستر والاس', '<p>دیوید فاستر والاس، رمان‌نویس، مقاله‌نویس و داستان‌نویس آمریکایی بود<em>.</em> در جوانی، تنیس رقابتی سطح بالا بازی می‌کرد.</p>', '2023-01-27 02:54:32.282602', '2023-01-27 02:54:32.282602', NULL, 'David Foster Wallace');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1419, 'جکی رزس و لورن واینبرگ', '<p>جکی رزس مدیر عامل شرکت فین‌تک Luna Financial Group است. او به عنوان یکی از <em>فوربس</em><em> </em> "زنان خودساخته" و <em>Fast Company</em> "خلاق ترین افراد در تجارت" انتخاب شده است. لورن واینبرگ، مدیر ارشد بازاریابی Square، ارائه‌دهنده جعبه ابزار تجاری است. او به چندین استارت آپ و The Women’s Startup Lab، شتاب دهنده ای برای بنیانگذاران زن، مشاوره می دهد. </p>', '2023-01-27 02:54:40.168291', '2023-01-27 02:54:40.168291', NULL, 'Jackie Reses and Lauren Weinberg');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1420, 'گابریل زوکمان', '<p>گابریل زوکمن نویسنده فرانسوی و استاد اقتصاد در دانشگاه کالیفرنیا، برکلی است. او همچنین یکی از همکاران مکرر <em>فصلنامه اقتصاد</em> است.</p>', '2023-01-27 02:54:47.838273', '2023-01-27 02:54:47.838273', NULL, 'Gabriel Zucman');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1421, 'فیلیپ لیمبری با ایزابل اوکشات', '<p> فیلیپ لیمبری، مدیر اجرایی Compassion in World Farming است. او همچنین یک فعال حقوق حیوانات و مدیر سابق ارتباطات انجمن جهانی برای حمایت از حیوانات است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1422, 'ویولا دیویس', '<p>وایولا دیویس تنها بازیگر سیاه‌پوستی است که به «تاج سه‌گانه» بازیگری، برنده اسکار، امی، و تونی برای کارهایش در سینما، تلویزیون و تئاتر دست یافته است. <em>نیویورک تایمز</em>دیویس را یکی از ده بازیگر بزرگ قرن بیست و یکم معرفی کرد. او علاوه بر کار بازیگری، یک تهیه کننده و نیکوکار تحسین شده است. </p>', '2023-01-27 02:55:02.180254', '2023-01-27 02:55:02.180254', NULL, 'Viola Davis');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1423, 'سباستین کلاین', '<p>سباستین کلاین و بن هیوز در حین کار با هم در استارت آپ Blinkist شروع به بررسی آینده کاری خود کردند. آنها رویکرد Loop را در TheDive توسعه دادند، یک مرکز متمرکز بر مسئولیت اجتماعی و کارآفرینی، و آن را در شرکت هایی مانند Audi Business Innovation، Deutsche Bahn، Deutsche Telekom و Europace آزمایش و اصلاح کردند. </p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1424, 'گری همل', '<p>گری همل استاد مدعو مدیریت استراتژیک و بین المللی در مدرسه تجارت لندن است. <em>وال استریت ژورنال</em>همل را به‌عنوان تأثیرگذارترین متفکر تجاری جهان معرفی کرد. کتاب های پرفروش او عبارتند از <em>رهبری انقلاب</em>و <em>رقابت برای آینده.</em></p>.
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1425, 'جی بائر', '<p>جی بائر کارشناس بازاریابی و رئیس شرکت مشاوره جهانی Convince & Convert است. او به برخی از نمادین‌ترین سازمان‌های جهان از جمله نایک و سازمان ملل مشاوره داده است و نویسنده پنج کتاب پرفروش <em>نیویورک تایمز</em> است.</p>', '2023-01-27 02:55:24.160875', '2023-01-27 02:55:24.160875', NULL, 'Jay Baer');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1426, 'دنیل کویل', '<p>دانیل کویل نویسنده پرفروش کتاب‌هایی از جمله برنده جایزه <em>لنس </em><em>آرمسترانگ</em>: <em>تور </em><em>de </em>< em>Force</em> و <em></em><em>Secret </em><em>Race</em>: <em>Inside</em><em>the</em>< em>پنهان</em><em>جهان</em><em>از</em><em>تور</em><em>تور</em><em>از</em><em> فرانسه</em>. او همچنین به طور منظم با مجلاتی مانند <em>New </em><em>York </em><em>Times Magazine</em> و <em>Sports</em><em>Illustrated</em> همکاری می کند. em> em>، و یک سردبیر در مجله <em>Outside</em>.</p>', '2023-01-27 02:55:32.519992', '2023-01-27 02:55:32.519992', NULL, 'Daniel Coyle');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1427, 'استیون هاوکینگ', '<p>استیون هاوکینگ، دکترا، (1942-2018) یک فیزیکدان نظری، کیهان شناس و نویسنده بود که بیشتر به خاطر کارش در مورد کاوش در مورد تشعشعات هاوکینگ و قضایای پنروز-هاوکینگ شهرت داشت. هاوکینگ بین سال‌های 1979 تا 2009 به‌عنوان پروفسور ریاضیات لوکاسی در دانشگاه کمبریج، دریافت‌کننده مدال آزادی ریاست‌جمهوری، عضو افتخاری انجمن سلطنتی هنر و عضو مادام العمر آکادمی علوم پاپی بود. /p>', '2023-01-27 02:55:40.913274', '2023-01-27 02:55:40.913274', NULL, 'Stephen Hawking ');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1429, 'جان لوئیس گدیس', '<p>جان لوئیس گدیس، استاد تاریخ در دانشگاه ییل است، جایی که او به مدت بیش از 15 سال درسی در مورد تاریخ نظامی و دریایی تدریس می کند. او همچنین نویسنده محترم کتاب های <em>جنگ سرد: یک تاریخ جدید</em> (2005) و <em>جرج اف کنان: یک زندگی آمریکایی</em>(2011) است که به خاطر آن موفق به دریافت جایزه شد. جایزه پولیتزر.</p>', '2023-01-27 02:55:56.681717', '2023-01-27 02:55:56.681717', NULL, 'John Lewis Gaddis');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1430, 'گرگ کرابتری و بورلی بلر هارزوگ', '<p>گرگ کرابتری یک شرکت حسابداری عمومی معتبر را تأسیس کرد که به کارآفرینان مشاوره و کمک می‌کند.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1431, 'کیت کرک پاتریک', '<p>کیت کرک پاتریک در مورد دین، فلسفه و فرهنگ در کالج کینگ لندن، در بریتانیا سخنرانی می کند. او علاوه بر <em>بوووار شدن</em>، کتاب هایی درباره ژان پل سارتر نوشته است، از جمله <em>سارتر و الهیات</em> و <em>سارتر در مورد گناه</em></p>.', '2023-01-27 02:56:12.762544', '2023-01-27 02:56:12.762544', NULL, 'Kate Kirkpatrick');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1432, 'شان کارول', '<p>شان کارول، استاد هوم وود فلسفه طبیعی در دانشگاه جان هاپکینز است. او در کیهان‌شناسی، نظریه میدان و گرانش متخصص است. او چندین کتاب دیگر از جمله <em>چیزی عمیقا پنهان</em>، <em>فضا زمان و هندسه</em>، و <em>تصویر بزرگ</em> نوشته است. او همچنین میزبان پادکست <em>Mindscape است. ،</em> که در آن علم، فلسفه، فرهنگ و هنر را مورد بحث قرار می دهد.</p>', '2023-01-27 02:56:20.747821', '2023-01-27 02:56:20.747821', NULL, 'Sean Carroll');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1433, 'مارکوس باکینگهام', '<p>مارکوس باکینگهام نویسنده پرفروش <em>نیویورک تایمز</em> و همچنین مشاور و سخنران است. او یکی از نویسندگان کتاب های پرفروش <em>اول، شکستن همه قوانین</em>و <em>یک چیزی که باید بدانید</em> است.</p>', '2023-01-27 02:56:28.279401', '2023-01-27 02:56:28.279401', NULL, 'Marcus Buckingham');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1434, 'سیدنی فینکلشتاین', '<p>سیدنی فینکلشتاین متخصص در رهبری و استراتژی کسب و کار است و 19 کتاب منتشر کرده است، از جمله <em>چرا مدیران باهوش شکست می‌خورند</em> (2003) و <em>دوباره فکر کنید: چرا رهبران خوب تصمیم‌های بد می‌گیرند و چگونه نگه دارید آن را از اتفاق برای شما</em> (2009). فینکلشتاین همچنین استاد مدیریت استیون راث و مدیر دانشکده در دانشکده تجارت تاک در کالج دارتموث است.</p>', '2023-01-27 02:56:41.94446', '2023-01-27 02:56:41.94446', NULL, 'Sydney Finkelstein');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1435, 'آنتونیو گارسیا مارتینز', '<p>آنتونیو گارسیا مارتینز قبل از راه‌اندازی شرکت خود، AdGrok و سپس تبدیل شدن به یک مدیر در تیم تبلیغاتی فیس‌بوک، در وال استریت به عنوان معامله‌گر برای گلدمن ساکس کار می‌کرد. او در یک قایق بادبانی در نزدیکی سانفرانسیسکو زندگی می کند.</p>', '2023-01-27 02:56:49.932089', '2023-01-27 02:56:49.932089', NULL, 'Antonio Garcia Martinez');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1436, 'ریچارد وایزمن', '<p>ریچارد وایزمن استاد دانشگاه هرتفوردشایر و یکی از تحسین‌شده‌ترین روانشناسان بریتانیا است. او به دلیل ایجاد مفاهیم پیچیده برای عموم مردم از طریق ویدیوهای محبوب یوتیوب و پرفروش‌ترین کتاب‌هایش، مانند <em>59 ثانیه</em> و <em>Quirkology</em> تحسین می‌شود.</p>', '2023-01-27 02:56:58.61658', '2023-01-27 02:56:58.61658', NULL, 'Richard Wiseman');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1437, 'پل کالنیتی', '<p>پل کالانیتی نویسنده هندی-آمریکایی و جراح برنده جایزه بود. او در دانشکده پزشکی ییل تحصیل کرد و دوره رزیدنتی خود را در دانشگاه استنفورد به پایان رساند.</p>', '2023-01-27 02:57:06.486347', '2023-01-27 02:57:06.486347', NULL, 'Paul Kalanithi');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1438, 'استیون جانسون', '<p>استیون جانسون نویسنده علوم محبوب آمریکایی است. او مرتباً به <em>وال استریت ژورنال</em>، <em>نیویورک تایمز</em> و <em>فایننشال تایمز</em> کمک می‌کند، و پرفروش‌ترین‌های قبلی او شامل <em>همه چیز بد است. برای شما خوب است</em> و <em>نقشه شبح</em>.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1439, 'آلن جی رابینسون و دین ام. شرودر', '<p>Alan G. Robinson نویسنده و مشاور تجاری است که با بیش از 200 شرکت پیشرو از جمله IKEA و Kraft کار کرده است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1440, 'ویلیام زینسر', '<p>ویلیام زینسر، روزنامه‌نگار و مقاله‌نویس تحسین‌شده، ۱۹ کتاب در موضوعات مختلف از بیسبال تا جاز تألیف کرد. در دهه 1970، زینسر رئیس کارگاه نویسندگی تأثیرگذار دانشگاه ییل بود. کتاب‌های هنری او، از جمله <em>درباره خوب نوشتن</em> و <em>نوشتن برای یادگیری</em>، به‌عنوان آثار کلاسیک در این ژانر در نظر گرفته می‌شوند.', '2023-01-27 02:57:33.747529', '2023-01-27 02:57:33.747529', NULL, 'William Zinsser');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1441, 'اریک گریتنز', '<p>اریک گریتنز سابق نیروی دریایی SEAL و کارمند کمک های بشردوستانه است. او بنیانگذار مرکز رهبری شهروندی است، یک سازمان غیرانتفاعی که به جانبازان کمک می کند تا با زندگی در خانه سازگار شوند. گریتنس نویسنده <em>قدرت و شفقت است که تجربیات او به عنوان یک امدادگر بشردوستانه را شرح می دهد.</p>', '2023-01-27 02:57:41.54263', '2023-01-27 02:57:41.54263', NULL, 'Eric Greitens');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1442, 'شارما را گیج کرد', '<p>میهیر شارما یک اقتصاددان تحصیل کرده در هاروارد است که کار خود را به عنوان روزنامه نگار برای <em>Indian Express</em> آغاز کرد. او به عنوان ویراستار نظر برای صفحه گسترده هندی <em>استاندارد تجاری</em> خدمت می کند.</p>', '2023-01-27 02:57:49.452421', '2023-01-27 02:57:49.452421', NULL, 'Mihir Sharma');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1443, 'نیل دگراس تایسون', '<p>نیل دگراس تایسون یک اخترفیزیکدان، مدیر افلاک‌نمای هیدن و میزبان پادکست <em>StarTalk</em> است. او همچنین مجری برنامه تلویزیونی محبوب PBS <em>NOVA ScienceNow </em> بود و در سال 2015 مدال رفاه عمومی آکادمی ملی علوم ایالات متحده را به دلیل کمک هایش به علم عمومی دریافت کرد.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1444, 'دکتر استیون گاندری', '<p>دکتر استیون گاندری مؤسسه بین‌المللی قلب و ریه و مرکز طب ترمیمی را تأسیس و اداره می‌کند که در آنجا تحقیقات پزشکی و عملکرد بالینی مستقل را انجام می‌دهد. او قبلاً استاد دانشکده پزشکی دانشگاه مریلند و دانشکده پزشکی دانشگاه لوما لیندا بود. او نویسنده کتاب های پرفروش <em>نیویورک تایمز</em> <em>پارادوکس گیاهی</em> و <em>کتاب آشپزی پارادوکس گیاهی</em> است.</p>', '2023-01-27 02:58:05.62673', '2023-01-27 02:58:05.62673', NULL, 'Dr. Steven Gundry');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1445, 'مت بریتون', '<p> مت بریتون موسس و مدیر عامل MRY است، یک آژانس خلاق جهانی که در بازاریابی جوانان تخصص دارد. مشتریان آنها شامل مایکروسافت، ویزا و جانسون اند جانسون هستند. بریتون مقالاتی در <em>وال استریت ژورنال</em>، <em>بلومبرگ</em> و <em>نیویورک تایمز</em></p> دارد.
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1446, 'سی. اتو شارمر', '<p> اتو شارمر یک مدرس ارشد و رئیس برنامه IDEAS در موسسه فناوری ماساچوست است. او با چندین دولت و شرکت های معتبر مانند گوگل و فوجیتسو برای ایجاد برنامه های نوآوری برای آنها کار کرده است.</p>', '2023-01-27 02:58:21.960462', '2023-01-27 02:58:21.960462', NULL, 'C. Otto Scharmer');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1447, 'سارا ایکل', '<p>سارا اکل یک نویسنده آزاد است که مقالات و انتقادات او در تعدادی از نشریات از جمله <em> واشنگتن پست</em> و <em>Glamour</em> منتشر شده است. <em>تو نیستی</em>، بر اساس ستون محبوب عشق مدرن او برای <em>نیویورک تایمز</em>، اولین کتاب او است.</p>', '2023-01-27 02:58:29.842378', '2023-01-27 02:58:29.842378', NULL, 'Sara Eckel');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1448, 'لیل لوندز', '<p>لیل لوندز نویسنده و سخنران عمومی است که کارش بر کمک به مردم برای ایجاد ابزارهای بهتر برای برقراری ارتباط با یکدیگر متمرکز است. او با چندین دهه تجربه، بسیاری از سیگنال‌های ظریف و ناخودآگاه را که می‌توانند باعث ایجاد یا شکستن روابط شوند، تشخیص داده است. از دیگر کتاب‌های محبوب او می‌توان به <em>چگونه فوراً با هر کسی ارتباط برقرار کرد </em>(2009) و <em>چگونه یک آهن‌ربای مردم باشیم </em>(2002) نام برد.</p>', '2023-01-27 02:58:37.574737', '2023-01-27 02:58:37.574737', NULL, 'Leil Lowndes');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1449, 'دنیل اورت', '<p>دانیل اورت یک زبان شناس و نویسنده آمریکایی است که چهار دهه را در میان پیراها زندگی و کار کرده است. او رئیس هنر و علوم در دانشگاه بنتلی در ماساچوست است.</p>', '2023-01-27 02:58:44.419038', '2023-01-27 02:58:44.419038', NULL, 'Daniel Everett');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1450, 'اریک سیگل', '<p>Eric Siegel یک رهبر مشهور جهانی در زمینه تجزیه و تحلیل پیش‌بینی‌کننده و بنیان‌گذار مجموعه کنفرانس جهانی پیش‌بینی‌کننده است. استاد سابق دانشگاه کلمبیا، او همچنین سردبیر اجرایی <em>Predictive Analytics Times</em> است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1451, 'جیم لوهر و تونی شوارتز', '<p>Jim Loehr مدیر عامل LGE Performance System است و به دلیل مشارکت در زمینه روانشناسی عملکرد در سراسر جهان شناخته شده است. </p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1452, 'پدر تالگام', '<p>ایتای تالگام رهبر ارکستر اسرائیلی است که با اکثر ارکسترهای اسرائیل کار کرده است. از زمان آغاز به کار به عنوان رهبر ارکستر در سال 1987، او همچنین با بسیاری از مشهورترین ارکسترهای جهان از جمله فیلارمونیک سن پترزبورگ و اپرای لایپزیگ کار کرده است. او همچنین از تجربیات خود در دنیای موسیقی و رهبری برای ارائه سخنرانی‌ها و سخنرانی‌های کلیدی در مورد رهبری در تجارت استفاده کرده است.</p>', '2023-01-27 02:59:10.513115', '2023-01-27 02:59:10.513115', NULL, 'Itay Talgam');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1453, 'رابرت برایس', '<p>رابرت برایس نویسنده و روزنامه نگار آمریکایی است. او برای <em>نیویورک تایمز، </em><em> وال استریت ژورنال</em> و <em>واشنگتن پست</em> در مورد صنعت انرژی و تغییرات آب و هوایی نوشته است. برایس همچنین نویسنده <em>Power Hungry</em> و <em>Gusher of Lies</em> است.</p>', '2023-01-27 02:59:17.473522', '2023-01-27 02:59:17.473522', NULL, 'Robert Bryce');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1454, 'کوین هورسلی و لوئیس فوری', '<p>کوین هورسلی یک مربی، مشاور و سخنران مورد تقاضا است که به شرکت‌ها در افزایش انگیزه و بهبود تفکر خلاق و فرآیندهای یادگیری کمک می‌کند. او به لطف پیروزی های متعدد خود در مسابقات حافظه قهرمانی در سراسر جهان، عنوان استاد بزرگ بین المللی حافظه را نیز به خود اختصاص داده است. </p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1455, 'گلن الیوت و دبرا کوری', '<p>گلن الیوت یک کارآفرین، نویسنده و سخنران برنده جوایز و همچنین بنیانگذار Reward Gateway، یک فناوری پیشرو در استخدام است. دبرا کوری یک نویسنده و سخنران و همچنین یک متخصص منابع انسانی باتجربه است. او بیش از 30 سال تجربه در سطح هیئت مدیره در شرکت هایی از جمله Gap، Quintiles و Merlin Entertainment دارد. او در حال حاضر با Reward Gateway کار می کند.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1456, 'لورا جردن بامباخ', '<p>لورا جردن بامباخ یک طراح دیجیتال و یکی از بنیانگذاران سازمان فمینیستی بریتانیایی SheSays است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1457, 'درو نایسر', '<p>درو نایسر بنیانگذار Renegade است، شرکت بازاریابی منحصراً B2B برنده جایزه. او به ده‌ها شرکت کمک کرد تا برندهای بی‌رقیب ایجاد کنند و داستان‌های بیش از 400 مدیر ارشد اجرایی الهام‌بخش را در پادکست <em>Renegade Thinkers Unite</em> به اشتراک گذاشت. نایسر یک ستون معمولی برای <em>عصر تبلیغات</em> منتشر می‌کند و در ABC News، CNBC، و رادیو CBS نمایش داده شده است.</p>', '2023-01-27 02:59:59.78789', '2023-01-27 02:59:59.78789', NULL, 'Drew Neisser');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1458, 'دی دنور', '<p>دی دنور استاد ژنتیک تکاملی در دانشگاه ایالتی اورگان است که در مطالعه جهش DNA و تکامل ژنوم تخصص دارد. او در حال حاضر روی یک پروژه چند رشته‌ای کار می‌کند که به بررسی آنچه بودایی‌ها و زیست‌شناسان می‌توانند از یکدیگر بیاموزند، می‌پردازد.</p>', '2023-01-27 03:00:08.37371', '2023-01-27 03:00:08.37371', NULL, 'Dee Denver');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1459, 'میسون کری', '<p>میسون کری سردبیر مجله و نویسنده مستقل است. آثار او در <em>نیویورک تایمز</em> و <em>Slate</em> منتشر شده است.</p>', '2023-01-27 03:00:16.378222', '2023-01-27 03:00:16.378222', NULL, 'Mason Currey');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1460, 'میکا h همه خانه ها', '<p>میکا زنکو متخصص پیشگیری از درگیری، امنیت ملی ایالات متحده و استراتژی نظامی است. او به عنوان کارشناس ارشد در شورای روابط خارجی کار می کند. در سال 2010، او اولین کتاب خود را با نام <em>بین تهدیدها و جنگ</em> منتشر کرد.</p>', '2023-01-27 03:00:24.624051', '2023-01-27 03:00:24.624051', NULL, 'Micah Zenko');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1461, 'تام ویل رایت', '<p> تام ویل رایت موسس و مدیر عامل ProVision، برترین شرکت حسابدار عمومی خبره در جهان است. او متخصص برجسته در زمینه مشارکت و استراتژی های مالیاتی شرکت ها است و خدمات مشاوره مالیاتی، تجاری و ثروت نوآورانه ای ایجاد کرده است. او علاوه بر نوشتن چندین مقاله برای مجلات حرفه ای، در کتاب های <em>کتاب واقعی املاک</em>، <em>چه کسی پول من را گرفت؟</em> و <em>مزایای ناعادلانه< همکاری کرده است. /em>.</p>', '2023-01-27 03:00:38.703102', '2023-01-27 03:00:38.703102', NULL, 'Tom Wheelwright');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1462, 'ریچارد روهر', '<p>ریچارد روهر یک کشیش فرانسیسکن است. او بیش از 20 کتاب نوشته است و به عنوان سخنران به سراسر جهان سفر کرده و در مورد موضوعاتی مانند معنویت، کتاب مقدس، طبیعت و مراقبت از زمین تدریس می کند. او همچنین برای مجلات <em>Radical Grace، Sojourners</em> و <em>Tikkun</em> می نویسد.</p>', '2023-01-27 03:00:46.184318', '2023-01-27 03:00:46.184318', NULL, 'Richard Rohr');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1463, 'مایکل هایت و مگان هایت میلر', '<p>Michael Hyatt نویسنده و بنیانگذار و رئیس مایکل هایت و شرکت، یک شرکت توسعه رهبری است. او قبلاً مدیرعامل ناشران توماس نلسون بود و کارهایش در<em>وال استریت ژورنال،</em> <em>Forbes،</em> و <em>Fast Company به نمایش درآمده است. </em>مگان حیات میلر، دخترش، مدیر اجرایی مایکل هایت و شرکت است. او همچنین مجری پادکست محبوب <em>Lead to Win</em> است.</p>', '2023-01-27 03:00:59.780234', '2023-01-27 03:00:59.780234', NULL, 'Michael Hyatt and Megan Hyatt Miller');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1464, 'جیم مرکوری', '<p>جیم کویک یک متخصص مشهور جهانی در فرایادگیری است - فرآیند یادگیری نحوه یادگیری. یک تصادف در دوران کودکی باعث شد که کویک دچار ناتوانی یادگیری شود. او سال ها در مدرسه تلاش کرد، اما پس از آن کویک شروع به کشف رازهای یادگیری خود کرد. یافته‌های او اساس <em>Kwik Learning، </em>برنامه آموزشی است که توسط افراد و شرکت‌ها در بیش از 100 کشور مورد استفاده قرار می‌گیرد. </p>', '2023-01-27 03:01:08.177635', '2023-01-27 03:01:08.177635', NULL, 'Jim Kwik');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1465, 'الکس سوجونگ-کیم پانگ', '<p>Alex Soojung-Kim Pang بنیانگذار Restful Company است، یک شرکت مشاوره مستقر در سیلیکون ولی که به سازمان ها می آموزد که چگونه از طریق گفتگوها و کارگاه های آموزشی تعادل بین کار و زندگی خود را بهتر ایجاد کنند. پانگ که یکی از اعضای مهمان دانشگاه استنفورد است، نویسنده <em>اعتیاد به حواس پرتی</em> است. او همچنین برای <em>Slate</em>، <em>Wired</em>، <em>Atlantic Monthly</em> و <em>Scientific American</em> نوشته است.</p>', '2023-01-27 03:01:16.099123', '2023-01-27 03:01:16.099123', NULL, 'Alex Soojung-Kim Pang');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1466, 'چیپ هیث و دن هیث', '<p>چیپ هیث استاد رفتار سازمانی در دانشگاه استنفورد است. او دارای مدرک کارشناسی مهندسی صنایع و دکترای روانشناسی است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1467, 'اسکات بری کافمن و کارولین گرگوار', '<p>دکتر اسکات بری کافمن، دکترا، دانشمند و نویسنده و همچنین مدیر موسسه تخیل در دانشگاه پنسیلوانیا است. او هفت کتاب با موضوعات خلاقیت و هوش نوشته یا تالیف کرده است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1468, 'هدر هانسون ویکمن', '<p>هدر هانسون ویکمن یک مربی اجرایی و توسعه‌دهنده رهبری با مدرک دکترا در سیستم‌های سازمانی است. پس از یک حرفه موفق در مراقبت های بهداشتی شرکتی، او شرکت خود را به نام Untethered Consulting تأسیس کرد.</p>', '2023-01-27 03:01:50.621034', '2023-01-27 03:01:50.621034', NULL, 'Heather Hanson Wickman');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1469, 'زن', '<p>John Amaechi OBE یک بسکتبالیست حرفه ای سابق است که تبدیل به روانشناس سازمانی، مربی اجرایی و بنیانگذار شرکت مشاوره APS شده است. Amaechi نویسنده پرفروش کتاب خاطرات <em>Man in the Middle</em>، همچنین مدافع حقوق LGBTQIA+ در ورزش است. </p>', '2023-01-27 03:02:04.312347', '2023-01-27 03:02:04.312347', NULL, 'John Amaechi');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1470, 'راس رابرتز', '<p>راس رابرتز میزبان پادکست هفتگی برنده جایزه EconTalk است که در سال 2006 آغاز کرد. او همچنین رئیس کالج Shalem در اورشلیم و نویسنده <em>چگونه آدام اسمیت می تواند زندگی شما را تغییر دهد</em> و < em>قمار با پول دیگران</em>.</p>', '2023-01-27 03:02:12.26779', '2023-01-27 03:02:12.26779', NULL, 'Russ Roberts');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1471, 'کن دیویس', '<p>کن دیویس نویسنده و سخنران آمریکایی است. علاوه بر این، او آموزش دهنده مهارت های ارتباطی و مجری برنامه های رادیویی است.</p>', '2023-01-27 03:02:19.898633', '2023-01-27 03:02:19.898633', NULL, 'Ken Davis');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1472, 'کوبی برایانت', '<p> کوبی برایانت نیازی به معرفی برای طرفداران بسکتبال ندارد. او در سال 2006 در مقابل تورنتو رپتورز 81 امتیاز کسب کرد و در سال 2014 از امتیاز 32292 مایکل جردن پیشی گرفت و سومین گلزن برتر تاریخ NBA شد. برایانت پس از کسب پنج قهرمانی NBA، 18 بار تبدیل شدن به یک ستاره آل استار و دو بار MVP فینال NBA، اغلب به عنوان یکی از بهترین بسکتبالیست های تمام دوران معرفی می شود و پس از مرگ به تالار مشاهیر بسکتبال در سال 2020 رأی داده شد. .</p>', '2023-01-27 03:02:36.601054', '2023-01-27 03:02:36.601054', NULL, 'Kobe Bryant');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1473, 'آلیسا کوهن', '<p>آلیسا کوهن بیش از بیست سال است که مربی بنیانگذاران استارت آپ بوده است. او در جوایز مربیان جهانی Thinkers50/Marshall Goldsmith به عنوان مربی برتر استارت آپی در جهان معرفی شد. او همچنین مربی اجرایی Runway Accelerator Program در Cornell Tech است و مرتباً برای <em>Harvard Business Review</em>،<em> Forbes</em>،<em> </em>و <em>Inc< /em>.</p>', '2023-01-27 03:02:43.778741', '2023-01-27 03:02:43.778741', NULL, 'Alisa Cohn');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1474, 'جی کنراد لوینسون', '<p>جی کنراد لوینسون برای ابداع اصطلاح "بازاریابی چریکی" شناخته شده است. او روی کمپین های بازاریابی موفقی برای شرکت هایی مانند <em>Mercedes</em>،<em>Visa</em> و <em>Rolling Stone</em> کار کرده است و همچنین مسئول توسعه نماد <em> بوده است. مرد مارلبورو</em>.</p>', '2023-01-27 03:02:50.749534', '2023-01-27 03:02:50.749534', NULL, 'Jay Conrad Levinson');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1475, 'جان مکی', '<p>جان مکی بنیانگذار و مدیرعامل Whole Foods Market است. او همچنین مؤسس سازمان غیرانتفاعی سرمایه داری آگاهانه بود. </p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1476, 'جاناتان گوتشال', '<p>جاناتان گوتشال یک محقق ادبی در کالج واشنگتن و جفرسون و همچنین نویسنده شش کتاب است. او علاوه بر انتشارات کتاب‌هایش، به <em>مجله نیویورک تایمز</em>، <em>طبیعت</em>، <em>ساینتیفیک آمریکایی</em>و دیگران کمک می‌کند.</p>', '2023-01-27 03:03:04.189479', '2023-01-27 03:03:04.189479', NULL, 'Jonathan Gottschall	');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1477, 'سرکه مارک', '<p>مارک اسیگ دارای دکترای تاریخ است و نویسنده <em>ادیسون و صندلی الکتریکی</em> است. او همچنین برای <em>The</em> <em>نیویورک تایمز، </em><em>سان فرانسیسکو کرونیکل</em> و <em>لس آنجلس تایمز</em> نوشته است. p>', '2023-01-27 03:03:16.425728', '2023-01-27 03:03:16.425728', NULL, 'Mark Essig');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1478, 'مارک مینروینی', '<p>مارک مینروینی، کهنه‌کار وال استریت، یکی از موفق‌ترین معامله‌گران سهام تا کنون است – و او اعداد و ارقامی برای پشتیبانی از آن دارد. مینوروینی که تنها با چند هزار دلار شروع شد، در سن 34 سالگی به سرعت ثروت خود را به میلیون‌ها رساند. دیگر کتاب‌های پرفروش او در زمینه تجارت عبارتند از <em>مثل قهرمان بیندیش و تجارت کن</em> و <em>رازهای ذهنیت برای برنده شدن</em>.</p>', '2023-01-27 03:03:23.247032', '2023-01-27 03:03:23.247032', NULL, 'Mark Minervini');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1479, 'اندرو دبلیو لو', '<p>اندرو دبلیو لو مدیر آزمایشگاه مهندسی مالی در MIT و استاد دانشکده مدیریت اسلون MIT است. او همچنین رئیس و استراتژیست شرکت مدیریت سرمایه گذاری AlphaSimplex Group است. برخی از نوشته‌های او درباره اقتصاد و سرمایه‌گذاری را می‌توان در کتاب <em>Hedge Funds، </em>و همچنین کتاب‌های دیگری که او تالیف کرده است، از جمله <em>A Non-Random Walk Down Wall Street</em>و مشاهده کرد. <em>اقتصاد بازارهای مالی.</em></p>', '2023-01-27 12:50:00.750289', '2023-01-27 12:50:00.750289', NULL, 'Andrew W. Lo');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1480, 'متیو بارزون', '<p>متیو بارزون یک تاجر، جمع آوری کننده کمک های مالی سیاسی و دیپلمات سابق ایالات متحده در سوئد و بریتانیا است. او کار خود را به عنوان مدیر بازرگانی برای شرکت رسانه ای CNET Networks آغاز کرد. در دوران نامزدی ریاست جمهوری سال 2008 باراک اوباما، او پیشگام رویدادهای جمع آوری کمک های مالی با دلار بود که به پیروزی در انتخابات کمک کرد. </p>', '2023-01-27 12:50:22.264659', '2023-01-27 12:50:22.264659', NULL, 'Matthew Barzun');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1481, 'پل گوستاوسون و استوارت لیف', '<p>پل گوستاوسون یک مشاور طراحی سازمان و بنیانگذار سازمان برنامه ریزی و طراحی است، شرکتی که تیم های با عملکرد بالا را در سراسر جهان ایجاد و حفظ می کند. او همچنین <em>قدرت زندگی با طراحی</em> و <em>دویدن در باد</em></p> را تالیف کرد.
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1482, 'متیو بی کرافورد', '<p>متیو بی کرافورد یک فیلسوف و مکانیک موتور سیکلت است. او مدرک دکتری گرفت. در فلسفه سیاسی مشغول به کار شد و در یک اتاق فکر واشنگتن دی سی مشغول به کار شد اما راضی نشد. بنابراین او مسیر خود را تغییر داد و یک تعمیرگاه مستقل موتورسیکلت باز کرد و همچنان به عنوان پژوهشگر در مؤسسه مطالعات پیشرفته در فرهنگ در دانشگاه ویرجینیا مشغول به تحصیل است.</p>', '2023-01-27 12:51:28.71586', '2023-01-27 12:51:28.71586', NULL, 'Matthew B. Crawford ');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1483, 'جاش لینکر', '<p>جاش لینکنر به عنوان مدیر عامل Detroit Venture Partners نقشی کلیدی در احیای تجارت در شهر ایفا کرده است. او نویسنده کتاب پرفروش <em>نیویورک تایمز</em>،<em>رویای منضبط،</em> است و جایزه قهرمان تغییر رئیس جمهور اوباما را دریافت کرده است.</p>
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1484, 'رابرت کولکر', '<p>رابرت کولکر یک نویسنده پرفروش و روزنامه نگار تحقیقی است که آثارش در نشریاتی مانند <em>مجله نیویورک</em> و <em>Bloomberg Businessweek</em> منتشر شده است. کتاب بسیار تحسین شده او، <em>دختران گمشده</em> (2013)، در مورد یک سری از قتل های حل نشده در لانگ آیلند، در فیلمی به همین نام که در سال 2020 منتشر شد اقتباس شد.</p>', '2023-01-27 12:52:35.387846', '2023-01-27 12:52:35.387846', NULL, 'Robert Kolker');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1485, 'لیدیا دنورث', '<p>لیدیا دنورث نویسنده‌ای است که آثارش در <em>نیویورک تایمز</em>، <em>نیوزویک</em> و <em>وال استریت ژورنال</em> بوده است. او به عنوان استاد کمکی روزنامه نگاری در دانشگاه فوردهام و دانشگاه لانگ آیلند خدمت کرد. <em>من می توانم تو را زمزمه کنم</em> دومین کتاب پرفروش اوست.</p>', '2023-01-27 12:53:19.842264', '2023-01-27 12:53:19.842264', NULL, 'Lydia Denworth');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1486, 'مارتی نویمایر', '<p>مارتی نویمایر کارشناس برندسازی است که با <em>Apple</em>، <em>Netscape</em>، <em>Eastman</em> <em>Kodak</em> و دیگر نمادها کار کرده است. شرکت ها.</p>', '2023-01-27 12:53:46.724038', '2023-01-27 12:53:46.724038', NULL, 'Marty Neumeier');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1487, 'لایت واتکینز', '<p>از سال 1998، لایت واتکینز معلم ذهن آگاهی و مراقبه و همچنین بنیانگذار جنبش درخشش بوده است. آموزه‌های واتکینز از طریق دوره‌ها، کتاب‌ها، سخنرانی‌های TEDx و خبرنامه ایمیلی به صدها هزار نفر در سراسر جهان رسیده است. </p>', '2023-01-27 12:54:09.833047', '2023-01-27 12:54:09.833047', NULL, 'Light Watkins');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1488, 'جی ابراهیم', '<p>جی آبراهام بنیانگذار و مدیر عامل گروه آبراهام است، یک مشاور تجاری و بازاریابی بسیار موفق که به شرکت های بزرگ بی شماری کمک کرده است تا به آنچه امروز هستند تبدیل شوند. او همچنین یک سخنران مکرر در کنفرانس ها و نویسنده چندین کتاب دیگر از جمله <em>سیستم بازاریابی MasterMind</em> و <em>راه حل نقطه چسبنده</em> است.</p>', '2023-01-27 12:54:30.345073', '2023-01-27 12:54:30.345073', NULL, 'Jay Abraham');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1489, 'جان مک وورتر', '<p>جان مک وورتر استاد ادبیات انگلیسی در دانشگاه کلمبیا است. او بیشتر به خاطر نوشته هایش در مورد زبان انگلیسی و تاریخ آن شناخته شده است. کتاب های قبلی او عبارتند از <em>حقه زبانی</em>(2014) و <em>زبان حرامزاده باشکوه ما</em> (2009). مک وورتر همچنین به طور منظم در روزنامه های مهم از جمله <em>نیویورک تایمز</em>و <em>لس آنجلس تایمز</em> همکاری می کند.</p>', '2023-01-27 12:54:54.063229', '2023-01-27 12:54:54.063229', NULL, 'John McWhorter');
INSERT INTO "public"."authors" ("id", "name", "bio", "created_at", "updated_at", "deleted_at", "original_name") VALUES (1490, 'جاستین لی', '<p>جاستین لی بیش از 20 سال تجربه در حمایت از مسیحیان دگرباشان جنسی دارد که به او بینش منحصربه فردی در مورد چگونگی پر کردن شکاف بین شکاف های سیاسی و الهیاتی ارائه کرده است. او همچنین مدیر اجرایی Nuance Ministries و نویسنده <em>Torn: Rescuing the Gospel from the Gays- vs. -Christians Debate</em> (2012) است.</p>', '2023-01-27 12:55:19.767155', '2023-01-27 12:55:19.767155', NULL, 'Justin Lee');
