INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (2, 'عصر کریپتوکارنسی', 'چگونه بیت کوین و پول دیجیتال نظم اقتصادی جهانی را به چالش می کشند؟', 'چگونه بیت کوین و پول دیجیتال نظم اقتصادی جهانی را به چالش می کشند؟', 16, 7, 'book', 't', '<p><em>عصر کریپتوکارنسی</em> مروری بر تاریخچه و ماهیت بیت کوین ارائه می دهد. تعریف «پول» را بررسی می کند و تأثیرات شگرفی را که ارزهای رمزنگاری شده مانند بیت کوین بر اقتصاد ما و به طور کلی جهان خواهند داشت، توضیح می دهد.</p>', '2015-03-17 00:00:00', 4, 282, 'https://images.blinkist.io/images/books/5506253a666365000a2f0000/1_1/470.jpg', '/en/books/the-age-of-cryptocurrency-en/purchase', 'عصر-کریپتوکارنسی', '2023-01-26 18:46:26.545903', '2023-01-26 18:46:26.545903', NULL, 'The Age of Cryptocurrency');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (3, 'ساخته شده برای فروش', 'ایجاد یک کسب و کار که می تواند بدون شما پیشرفت کند', 'ایجاد یک کسب و کار که می تواند بدون شما پیشرفت کند', 15, 8, 'book', 'f', '<p><em>ساخت‌شده برای فروش</em> استراتژی‌های کلیدی برای رشد یک شرکت خدماتی کوچک و آماده‌سازی کسب‌وکار برای فروش آینده را شرح می‌دهد. این چشمک‌ها با بیان داستان الکس استپلتون، مالک یک آژانس بازاریابی، و دوست مشاوره‌دهنده‌اش، تد گوردون، که یک کارآفرین موفق است، این بینش‌ها را نشان می‌دهد.</p>', '2014-09-22 00:00:00', 4, 49, 'https://images.blinkist.io/images/books/541c23f26431620008050000/1_1/470.jpg', '/en/books/built-to-sell-en/purchase', 'ساخته-شده-برای-فروش', '2023-01-26 18:46:37.884869', '2023-01-26 18:46:37.884869', NULL, 'Built to Sell');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (5, 'چیز سخت درباره چیزهای سخت', 'ایجاد یک کسب و کار زمانی که هیچ پاسخ آسانی وجود ندارد', 'ایجاد یک کسب و کار زمانی که هیچ پاسخ آسانی وجود ندارد', 28, 13, 'book', 't', '<p>این پلک‌ها توضیح می‌دهند که چرا شغل یک مدیر عامل یکی از سخت‌ترین و تنهاترین شغل‌های دنیاست، و چگونه می‌توانید از استرس و ناراحتی‌های موجود جان سالم به در ببرید.</p>', '2014-04-08 12:14:41', 4, 336, 'https://images.blinkist.io/images/books/53444a3a6432320007040000/1_1/470.jpg', '/en/books/the-hard-thing-about-hard-things-en/purchase', 'چیز-سخت-درباره-چیزهای-سخت', '2023-01-26 18:46:54.35438', '2023-01-26 18:46:54.35438', NULL, 'The Hard Thing About Hard Things');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (6, 'نمایندگان اعتماد', 'استفاده از وب برای ایجاد نفوذ، بهبود شهرت و کسب اعتماد', 'استفاده از وب برای ایجاد نفوذ، بهبود شهرت و کسب اعتماد', 15, 9, 'book', 'f', '<p><em>Trust</em> <em>Agents</em> توضیح می‌دهد که چگونه هر کسی می‌تواند از وب برای تبدیل شدن به یک نماینده اعتماد استفاده کند - یعنی کسی که به ابزارهای وب مسلط است و بسیار تأثیرگذار است. و به این دلیل اعتماد کرد.</p>', '2014-05-06 10:51:50', NULL, 6, 'https://images.blinkist.io/images/books/536a0e676631340007d00000/1_1/470.jpg', '/en/books/trust-agents-en/purchase', 'نمایندگان-اعتماد', '2023-01-26 18:47:00.036425', '2023-01-26 18:47:00.036425', NULL, 'Trust Agents');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (7, 'ذهن آگاهی', 'برنامه ای هشت هفته ای برای یافتن صلح در دنیایی از کوره در رفته', 'برنامه ای هشت هفته ای برای یافتن صلح در دنیایی از کوره در رفته', 21, 7, 'book', 't', '<p><em>ذهن‌آگاهی</em> (2011) خوانندگان را در هشت هفته مدیتیشن هدایت می‌کند که به‌ویژه برای ایجاد آرامش بیشتر طراحی شده است. نتیجه همکاری بین یک بیوشیمیست و یک روانشناس بالینی، این یک دوره علمی مبتنی بر پایه است که راه را برای بهزیستی ذهنی بیشتر هموار می‌کند و در عین حال افسانه‌های زیادی را در این راه از بین می‌برد.</p>', '2018-07-30 00:00:00', 5, 188, 'https://images.blinkist.io/images/books/5b5e6d19b238e10007a4bba1/1_1/470.jpg', '/en/books/mindfulness-en/purchase', 'ذهن-آگاهی', '2023-01-26 18:47:13.008209', '2023-01-26 18:47:13.008209', NULL, 'Mindfulness');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (8, 'وقتی نابغه شکست خورد', 'ظهور و سقوط مدیریت سرمایه بلندمدت', 'ظهور و سقوط مدیریت سرمایه بلندمدت', 19, 8, 'book', 't', '<p><em>When Genius Failed</em> (2001) به دنبال ظهور و سقوط مدیریت سرمایه بلند مدت، بزرگترین صندوق سرمایه گذاری جهان است. این کتاب حقایق ناراحت کننده ای را در مورد ماهیت سرمایه گذاری و شکنندگی مدل هایی که برای ارزیابی ریسک استفاده می کنیم، نشان می دهد.</p>', '2015-03-30 00:00:00', 4, 57, 'https://images.blinkist.io/images/books/5518968a3961320007190000/1_1/470.jpg', '/en/books/when-genius-failed-en/purchase', 'وقتی-نابغه-شکست-خورد', '2023-01-26 18:47:24.86857', '2023-01-26 18:47:24.86857', NULL, 'When Genius Failed');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (382, 'پول مبارک', 'علم جدید مخارج هوشمندانه', 'علم جدید مخارج هوشمندانه', 16, 7, 'book', 't', '<p><em>Happy Money</em> (2013) توضیح می دهد که چگونه می توانید و باید پول خود را برای به حداکثر رساندن شادی خود خرج کنید، از طریق پنج اصل ساده که می تواند در زندگی روزمره شما اعمال شود.</p>', '2014-10-31 00:00:00', 4, 121, 'https://images.blinkist.io/images/books/5450254c3831390009250000/1_1/470.jpg', '/en/books/happy-money-en/purchase', 'پول-مبارک', '2023-01-26 19:30:17.498375', '2023-01-26 19:30:17.498375', NULL, 'Happy Money');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (4, 'تفکر در سیستم‌ها', 'به اول', 'به اول', 17, 8, 'book', 't', '<p><em>تفکر در سیستم ها</em> (2008) مقدمه ای بر تفکر سیستمی است. این پلک‌ها به شما یاد می‌دهند که چگونه جهان را بر حسب شبکه‌های به هم پیوسته ببینید، در حالی که جزئیات، چگونه عناصر، روابط و اهداف مختلف، هر ساختار معین را اجرا می‌کنند.</p>', '2016-04-20 00:00:00', 4, 162, 'https://images.blinkist.io/images/books/5713c25a5236f20007c16fce/1_1/470.jpg', '/en/books/thinking-in-systems-en/purchase', 'تفکر-در-سیستم-ها', '2023-01-26 18:46:49', '2023-01-26 18:46:49', NULL, 'Thinking in Systems');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (10, 'اشتراک بیش از حد', 'چگونه افرادی را که صف می کشند تا با شما تجارت کنند', 'چگونه افرادی را که صف می کشند تا با شما تجارت کنند', 16, 6, 'book', 't', '<p><em>Overssubscribed</em> (2015) توضیح می‌دهد که چگونه می‌توان کسب‌وکاری ایجاد کرد که تقاضای بیشتری نسبت به عرضه آن ایجاد کند. مدل کسب و کار اشتراک بیش از حد که توسط اپل برای ایجاد یک پایگاه مشتری پرشور و وفادار و توسط مارک های بوتیک برای ایجاد تمایل و کسب سودهای کلان استفاده می شود، هم مورد توجه قرار می گیرد و هم آن را حفظ می کند. در این چشمک‌ها، نحوه عملکرد آن را خواهید آموخت.</p>', '2017-12-22 00:00:00', 4, 53, 'https://images.blinkist.io/images/books/5a37c15eb238e1000765baff/1_1/470.jpg', '/en/books/oversubscribed-en/purchase', 'اشتراک-بیش-از-حد', '2023-01-26 18:47:42.017563', '2023-01-26 18:47:42.017563', NULL, 'Oversubscribed');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (11, 'عادت اکنون', 'برنامه ای استراتژیک برای غلبه بر تعلل و لذت بردن از بازی بدون گناه', 'برنامه ای استراتژیک برای غلبه بر تعلل و لذت بردن از بازی بدون گناه', 20, 9, 'book', 't', '<p><em></em> <em>اکنون</em> <em>عادت</em> مشکلی را بررسی می‌کند که بسیاری از مردم امروز می‌توانند با آن مرتبط باشند: به تعویق انداختن کار. چرا مردم کارهای مهم را تا آخرین ثانیه ممکن به تعویق می اندازند؟ و چگونه می توان به آنها کمک کرد؟ <em></em> <em>اکنون</em> <em>عادت</em> توضیح می‌دهد که این پدیده از کجا می‌آید، و کدام طرز فکر و ابزار می‌تواند به ما در غلبه بر آن کمک کند.</p>', '2014-05-20 14:01:33', 5, 203, 'https://images.blinkist.io/images/books/537caff83465300007fe0000/1_1/470.jpg', '/en/books/the-now-habit-en/purchase', 'عادت-اکنون', '2023-01-26 18:47:55.10029', '2023-01-26 18:47:55.10029', NULL, 'The Now Habit');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (12, 'مدل های ذهنی بزرگ جلد 2', 'فیزیک، شیمی و زیست شناسی', 'فیزیک، شیمی و زیست شناسی', 23, 7, 'book', 't', '<p><em>مدل‌های ذهنی بزرگ جلد 2 </em> (2019) همه چیز درباره هنر ایجاد ارتباطات غیرمنتظره است. ریشه در علوم "سخت" دارد و مفاهیم اصلی فیزیک، شیمی و زیست شناسی را باز می کند. اما این فقط در مورد الکترون ها، عناصر و تکامل نیست. ایده های پوشش داده شده در این تاریخ فکری جذاب را می توان در زندگی روزمره نیز به کار برد.</p>', '2020-11-11 00:00:00', 4, 104, 'https://images.blinkist.io/images/books/5fa58af56cee070006d9faf1/1_1/470.jpg', '/en/books/the-great-mental-models-volume-2-en/purchase', 'مدل-های-ذهنی-بزرگ-جلد-2', '2023-01-26 18:47:59.947417', '2023-01-26 18:47:59.947417', NULL, 'The Great Mental Models Volume 2');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (13, 'صبر کن', 'هنر مفید اهمال کاری', 'هنر مفید اهمال کاری', 17, 8, 'book', 't', '<p><em>صبر کنید</em> (2012) راهنمای نهایی برای ایجاد تعادل بین کنش و بی‌عملی و یادگیری نحوه تشخیص لحظه‌ای عالی است که باید حرکتی انجام دهید. این پلک‌ها توضیح می‌دهند که چگونه وقت گذاشتن می‌تواند تأثیر عمیقی بر همه چیز در زندگی شما داشته باشد، از بازی تنیس و خرید سهام گرفته تا حتی یافتن عشق زندگی‌تان.</p>', '2016-04-07 00:00:00', 4, 28, 'https://images.blinkist.io/images/books/57000ac7840c420007000027/1_1/470.jpg', '/en/books/wait-en/purchase', 'صبر-کن', '2023-01-26 18:48:06.109432', '2023-01-26 18:48:06.109432', NULL, 'Wait');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (14, 'خوشبین منطقی', 'چگونه رفاه تکامل می یابد', 'چگونه رفاه تکامل می یابد', 16, 11, 'book', 'f', '<p><em>خوش‌بین منطقی</em> به مشکلات عمده‌ای می‌پردازد که از طلوع تمدن با بشر مواجه بوده‌اند و توضیح می‌دهد که چگونه روش‌های مبادله و تخصص راه‌حل‌های نوآورانه‌ای را برای مقابله با هر مانع جدید ایجاد کردند. نویسنده از طریق علم، اقتصاد و مثال‌های تاریخی، دلایل بسیاری را برای خوش‌بین بودن به ناملایماتی که امروز با آن مواجه هستیم یا ممکن است در آینده با آن مواجه شویم، آشکار می‌کند.</p>', '2013-11-27 09:01:42', 4, 65, 'https://images.blinkist.io/images/books/529364c9623136000c0b0000/1_1/470.jpg', '/en/books/the-rational-optimist-en/purchase', 'خوشبین-منطقی', '2023-01-26 18:48:12.78433', '2023-01-26 18:48:12.78433', NULL, 'The Rational Optimist');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (15, 'حل پازل بهره وری', 'نحوه جذب، ایجاد انگیزه و توسعه کارکنان برای بهبود عملکرد فردی و تجاری', 'نحوه جذب، ایجاد انگیزه و توسعه کارکنان برای بهبود عملکرد فردی و تجاری', 22, 7, 'book', 't', '<p><em>حل معمای بهره وری </em>(2020) راهنمایی برای متخصصان مدیریت افراد است. موضوعاتی مانند یادگیری و توسعه، انگیزه نیروی کار و استراتژی های برنامه ریزی را پوشش می دهد. خواندن آن برای متخصصان منابع انسانی که می‌خواهند فرهنگی بسازند که در آن افراد بتوانند پیشرفت کنند ضروری است.</p>', '2022-01-10 00:00:00', 4, 135, 'https://images.blinkist.io/images/books/61dc0f116cee070008edb91c/1_1/470.jpg', '/en/books/solving-the-productivity-puzzle-en/purchase', 'حل-پازل-بهره-وری', '2023-01-26 18:48:18.466166', '2023-01-26 18:48:18.466166', NULL, 'Solving the Productivity Puzzle');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (38, 'کارت شاخص', 'چرا امور مالی شخصی نباید پیچیده باشد؟', 'چرا امور مالی شخصی نباید پیچیده باشد؟', 15, 6, 'book', 't', '<p><em>کارت شاخص </em>(2016) امور مالی شخصی را ساده می کند. این چشمک‌ها همه چیز را پوشش می‌دهند، از دریافت وام مسکن شما تا تضمین بیمه عمر با کیفیت، راه‌اندازی حساب پس‌انداز خود و حتی انتخاب یک مشاور مالی.</p>', '2018-01-16 00:00:00', 4, 47, 'https://images.blinkist.io/images/books/5a5b9785b238e100078c4fd8/1_1/470.jpg', '/en/books/the-index-card-en/purchase', 'کارت-شاخص', '2023-01-26 18:51:02.88301', '2023-01-26 18:51:02.88301', NULL, 'The Index Card');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (16, 'عمل با قدرت', 'چرا ما قدرتمندتر از آن چیزی هستیم که فکر می کنیم؟', 'چرا ما قدرتمندتر از آن چیزی هستیم که فکر می کنیم؟', 23, 8, 'book', 't', '<p><em>عملکردن با قدرت </em>(2020) این رمز و راز را از قدرت بیرون می‌کشد و این راز را از بین می‌برد که واقعاً چیست و چگونه از آن به طور مؤثر در هر کجا که خودمان را پیدا می‌کنیم استفاده کنیم. این پلک‌ها با استفاده از تکنیک‌هایی از عرصه بازیگری، نحوه مقابله با این پلک‌ها را نیز توضیح می‌دهند که وقتی احساس می‌کنیم برای نقش‌های قدرتمند عصبی یا آماده نیستیم، یا زمانی که می‌خواهیم قدرت بیشتری نسبت به آنچه به ما داده شده است، مقابله کنیم.</p>', '2020-08-16 00:00:00', 4, 120, 'https://images.blinkist.io/images/books/5f31998c6cee070006c6583a/1_1/470.jpg', '/en/books/acting-with-power-en/purchase', 'عمل-با-قدرت', '2023-01-26 18:48:30.432536', '2023-01-26 18:48:30.432536', NULL, 'Acting with Power');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (17, 'نام من را بدانید', 'یک خاطره', 'یک خاطره', 26, 9, 'book', 't', '<p>در <em>نام من را بشناس </em> (۲۰۱۹)، شانل میلر جنبه‌ی خود را از آنچه اتفاق افتاد که توسط براک ترنر، دانشجوی دانشگاه استنفورد مورد تجاوز جنسی قرار گرفت و مجبور شد یک محاکمه طولانی و آسیب‌زا را در چشمان عمومی تحمل کند، ارائه می‌کند. او با ترسیم شباهت هایی بین تجربه خود و بدرفتاری ساختاری با زنان در سیستم دادگاه، توضیح می دهد که چه چیزی او را مصمم به اشتراک گذاری داستان خود و توانمندسازی سایر بازماندگان کرده است.</p>', '2019-11-28 00:00:00', 5, 21, 'https://images.blinkist.io/images/books/5ddd46436cee0700082ba035/1_1/470.jpg', '/en/books/know-my-name-en/purchase', 'نام-من-را-بدانید', '2023-01-26 18:48:43.134269', '2023-01-26 18:48:43.134269', NULL, 'Know My Name');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (18, 'قانون 3 دقیقه', 'کمتر بگویید تا از هر طرح یا ارائه ای بیشتر به دست آورید', 'کمتر بگویید تا از هر طرح یا ارائه ای بیشتر به دست آورید', 27, 10, 'book', 't', '<p><em>"در پایان سه دقیقه، مخاطبان شما از قبل به پیشنهاد شما متمایل خواهند شد بله یا خیر. از آن نقطه به بعد، می توانید تا 57 دقیقه دیگر به غمگینی ادامه دهید، اما قالب از قبل ریخته شده است."< /em></p>
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (19, 'مکث کنید', 'شما یک لیست برای انجام نیست', 'شما یک لیست برای انجام نیست', 18, 6, 'book', 't', '<p><em>مکث انجام دهید</em> (2019) مزایای فشار دادن مکث در گردباد زندگی مدرن را بررسی می‌کند. این پلک زدن ها با از بین بردن افسانه های مخرب مربوط به بهره وری و موفقیت، نشان می دهد که چرا، چگونه و چه زمانی باید استراحت کنید. </p>', '2020-01-20 00:00:00', 4, 270, 'https://images.blinkist.io/images/books/5e21a2b16cee070006957794/1_1/470.jpg', '/en/books/do-pause-en/purchase', 'مکث-کنید', '2023-01-26 18:49:00.1778', '2023-01-26 18:49:00.1778', NULL, 'Do Pause');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (20, 'کتاب راهنمای بچه شاد', 'چگونه در دنیای پر استرس فرزندانی شاد تربیت کنیم؟', 'چگونه در دنیای پر استرس فرزندانی شاد تربیت کنیم؟', 15, 7, 'book', 't', '<p><em>راهنمای بچه شاد</em> (2015) مؤلفه‌های کلیدی دوران کودکی شاد را توضیح می‌دهد که به کودکان اجازه می‌دهد به عنوان افراد منحصربه‌فرد رشد کنند. چه فرزند شما درون گرا یا برونگرا باشد، این پلک زدن ها شما را از طریق کمک به درک استرس، احساسات منفی، روابط اجتماعی و اهمیت یافتن آرامش در زندگی خود راهنمایی می کند.</p>', '2016-12-23 00:00:00', 4, 82, 'https://images.blinkist.io/images/books/58582e33d1a2f300047968ab/1_1/470.jpg', '/en/books/the-happy-kid-handbook-en/purchase', 'کتاب-راهنمای-بچه-شاد', '2023-01-26 18:49:12.84764', '2023-01-26 18:49:12.84764', NULL, 'The Happy Kid Handbook');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (21, 'قانون لجستیک', 'والمارت و معماری تحقق', 'والمارت و معماری تحقق', 23, 7, 'book', 't', '<p><em>قاعده لجستیک</em> (2016) به شبکه پیچیده و گسترده زیرساختی می پردازد که Walmart محلی شما را زنده می کند. این گزارش جذاب با بررسی عناصر تاریخ، اقتصاد و تئوری معماری، چگونگی تبدیل شدن یک خرده‌فروش از آرکانزاس به یکی از بزرگترین شرکت‌های جهان و تغییر چشم‌انداز آمریکا را در این فرآیند نشان می‌دهد.</p>', '2020-03-14 00:00:00', 4, 40, 'https://images.blinkist.io/images/books/5e68ef686cee070006d37ba5/1_1/470.jpg', '/en/books/the-rule-of-logistics-en/purchase', 'قانون-لجستیک', '2023-01-26 18:49:18.432307', '2023-01-26 18:49:18.432307', NULL, 'The Rule of Logistics');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (22, 'سرد', 'چگونه جست و جوی پنهان مغز برای سرگرمی، اقتصاد ما را به حرکت در می آورد و دنیای ما را شکل می دهد', 'چگونه جست و جوی پنهان مغز برای سرگرمی، اقتصاد ما را به حرکت در می آورد و دنیای ما را شکل می دهد', 9, 4, 'book', 'f', '<p><em>Cool</em> (2015) توضیح می‌دهد که چگونه میل اجتماعی به تناسب و به رسمیت شناخته شدن انسان را به مصرف سوق می‌دهد. با تکیه بر همه چیز از علوم اعصاب گرفته تا زیست شناسی تکاملی گرفته تا اقتصاد و تاریخ، <em>Cool</em> توضیح می دهد که چرا تمایل به خرید طبیعی است.</p>', '2016-01-18 00:00:00', 4, 14, 'https://images.blinkist.io/images/books/569c97e9e37b120007000000/1_1/470.jpg', '/en/books/cool-en/purchase', 'سرد', '2023-01-26 18:49:24.194869', '2023-01-26 18:49:24.194869', NULL, 'Cool');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (69, 'مدیتیشن ها', 'تفکر رواقی یک فیلسوف-شاه', 'تفکر رواقی یک فیلسوف-شاه', 10, 5, 'book', 't', '<p><em>مدیتیشن‌ها</em> (170-180 بعد از میلاد) سفری است در ذهن امپراتور بزرگ روم، مارکوس اورلیوس. این پلک‌ها نشخوار فکری فلسفی در مورد معنای مرگ و عدالت، ماهیت جهان و اینکه چرا همه چیز به این شکل اتفاق می‌افتد، ارائه می‌کند.</p>', '2016-04-20 00:00:00', 4, 582, 'https://images.blinkist.io/images/books/5713be4f5236f20007c16fa7/1_1/470.jpg', '/en/books/meditations-en/purchase', 'مدیتیشن-ها', '2023-01-26 18:53:50.07499', '2023-01-26 18:53:50.07499', NULL, 'Meditations');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (23, 'حل مسئله ضد گلوله', 'مهارتی که همه چیز را تغییر می دهد', 'مهارتی که همه چیز را تغییر می دهد', 19, 6, 'book', 't', '<p><em>حل مسئله ضد گلوله </em>(2019) به یکی از مهم‌ترین مهارت‌هایی که در محیط کار مدرن نادیده گرفته می‌شود، می‌پردازد: حل مسئله. با کاهش مشاغل معمول در سراسر جهان، کارمندان بیشتری وظیفه مقابله با چالش‌های بی‌پایان را بر عهده دارند. همانطور که در این چشمک‌ها خواهیم دید، برای اینکه یک حل‌کننده عالی مشکل باشید، نیازی به مدرک تحصیلی پیشرفته در تجزیه و تحلیل آماری ندارید – فقط به خلاقیت و استراتژی‌های مناسب نیاز دارید. </p>', '2021-03-26 00:00:00', 4, 241, 'https://images.blinkist.io/images/books/6054747b6cee0700076902a4/1_1/470.jpg', '/en/books/bulletproof-problem-solving-en/purchase', 'حل-مسئله-ضد-گلوله', '2023-01-26 18:49:36.398596', '2023-01-26 18:49:36.398596', NULL, 'Bulletproof Problem Solving');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (24, 'موشک', 'هشت درس برای تضمین رشد بی نهایت', 'هشت درس برای تضمین رشد بی نهایت', 13, 6, 'book', 't', '<p><em>راکت</em> (2015) نگاهی درونی به موفقیت برندهایی مانند استارباکس و ویکتوریا سیکرت است که رشد سریع آنها هیچ ربطی به شانس نداشت. این پلک‌ها علم اثبات شده ساخت برند را به اشتراک می‌گذارند که شرکت‌هایی مانند اینها را به چنین رشد چشمگیر و موفقیتی عظیم سوق داده است.</p>', '2016-03-29 00:00:00', 4, 14, 'https://images.blinkist.io/images/books/56f3b87e2bf5b9000700003b/1_1/470.jpg', '/en/books/rocket-en/purchase', 'موشک', '2023-01-26 18:49:41.846958', '2023-01-26 18:49:41.846958', NULL, 'Rocket');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (25, 'پسران در قایق', 'سفری حماسی به قلب برلین هیتلر', 'سفری حماسی به قلب برلین هیتلر', 21, 11, 'book', 't', '<p><em>پسران در قایق</em> (2013) داستان این است که چگونه گروهی از پسران دانشگاهی بی ادعا از دانشگاه واشنگتن از رکود بزرگ به پیروزی در المپیک 1936 برلین رسیدند. .</p>', '2016-03-14 00:00:00', 4, 15, 'https://images.blinkist.io/images/books/56e696ce9854a50007000004/1_1/470.jpg', '/en/books/the-boys-in-the-boat-en/purchase', 'پسران-در-قایق', '2023-01-26 18:49:53.878151', '2023-01-26 18:49:53.878151', NULL, 'The Boys in the Boat');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (26, 'کد استرس', 'از بقا تا شکوفا شدن: یک مدل علمی', 'از بقا تا شکوفا شدن: یک مدل علمی', 24, 8, 'book', 't', '<p><em>رمز استرس</em> (2018) نقش استرس را در زندگی روزمره ما بررسی می کند. این بررسی می کند که چرا استرس برای سلامتی ما کشنده است و چه تأثیراتی بر اقتصاد جهانی دارد. ساتون استراتژی‌های مبتنی بر علم را برای مدیریت استرس ارائه می‌کند تا به شما کمک کند سلامت روحی و جسمی خود را بهبود بخشیده و به پتانسیل خود در سطح شخصی و حرفه‌ای دست یابید.</p>', '2020-05-30 00:00:00', 5, 149, 'https://images.blinkist.io/images/books/5ecd701a6cee0700068125aa/1_1/470.jpg', '/en/books/the-stress-code-en/purchase', 'کد-استرس', '2023-01-26 18:49:59.325883', '2023-01-26 18:49:59.325883', NULL, 'The Stress Code');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (27, 'بهترین سال شما', 'یک برنامه 5 مرحله ای برای دستیابی به مهمترین اهداف', 'یک برنامه 5 مرحله ای برای دستیابی به مهمترین اهداف', 18, 7, 'book', 't', '<p><em>بهترین سال شما</em> (2018) دستورالعمل‌های واضح و آسانی را در مورد اینکه چه چیزی در زندگی خود تغییر دهید - و چگونه - ارائه می‌کند تا بتوانید به پتانسیل کامل خود برسید. بخش‌های کلیدی را برای شما مشخص می‌کند که می‌توانید روی آنها کار کنید، و همچنین موانعی را که باید قبل از اینکه بتوانید خودتان را بهبود ببخشید، فتح کنید.</p>', '2018-06-18 00:00:00', 4, 304, 'https://images.blinkist.io/images/books/5b25cbc6b238e10007b07af4/1_1/470.jpg', '/en/books/your-best-year-ever-en/purchase', 'بهترین-سال-شما', '2023-01-26 18:50:05.08073', '2023-01-26 18:50:05.08073', NULL, 'Your Best Year Ever');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (28, 'معاملات سرمایه گذاری', 'از وکیل و سرمایه دار خود باهوش تر باشید', 'از وکیل و سرمایه دار خود باهوش تر باشید', 21, 9, 'book', 't', '<p><em>معاملات مخاطره‌آمیز</em> بینش‌های داخلی را در مورد مکانیسم‌های حاکم بر معاملات سرمایه‌گذاری خطرپذیر و همچنین ترفندهایی ارائه می‌دهد که به شما کمک می‌کند از مذاکرات با سرمایه‌گذاران بیشترین بهره را ببرید. این قراردادهای سرمایه گذاری خطرپذیر را به گونه ای تنظیم می کند که به راحتی قابل درک باشد و به شما در میز مذاکره برتری دهد.</p>', '2014-11-21 00:00:00', 4, 74, 'https://images.blinkist.io/images/books/546bddf43435300008780000/1_1/470.jpg', '/en/books/venture-deals-en/purchase', 'معاملات-سرمایه-گذاری', '2023-01-26 18:50:11.543535', '2023-01-26 18:50:11.543535', NULL, 'Venture Deals');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (29, 'ویکینومیکس', 'چگونه همکاری جمعی همه چیز را تغییر می دهد', 'چگونه همکاری جمعی همه چیز را تغییر می دهد', 15, 9, 'book', 'f', '<p><em>ویکی‌نامیک</em> نشان می‌دهد که چگونه همکاری گسترده افراد شبیه به ویکی‌پدیا، جامعه و تجارت را متحول می‌کند، و چرا این واقعاً برای شرکت‌ها و عموم خوب است.</p>', '2014-05-20 13:29:31', 3, 12, 'https://images.blinkist.io/images/books/537ca8c53465300007d30000/1_1/470.jpg', '/en/books/wikinomics-en/purchase', 'ویکینومیکس', '2023-01-26 18:50:16.701262', '2023-01-26 18:50:16.701262', NULL, 'Wikinomics');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (30, 'طراحی ارزش پیشنهادی', 'چگونه محصولات و خدمات مورد نظر مشتریان را ایجاد کنیم', 'چگونه محصولات و خدمات مورد نظر مشتریان را ایجاد کنیم', 15, 6, 'book', 't', '<p><em>طراحی ارزش پیشنهادی</em> (2014) راهنمای جامعی برای طراحی محصولات و خدمات متقاعد کننده است. ارزش واقعی از همدلی با مشتریان برای یافتن اینکه در چه مشاغل و وظایف روزمره به کمک نیاز دارند، ناشی می شود. با این حال، ارائه محصولی که به مشتریان کمک می کند این کارها و وظایف را تکمیل کنند، تنها آغاز کار است.</p>', '2017-02-15 00:00:00', 4, 110, 'https://images.blinkist.io/images/books/58a068c9cb5c28000403161e/1_1/470.jpg', '/en/books/value-proposition-design-en/purchase', 'طراحی-ارزش-پیشنهادی', '2023-01-26 18:50:21.492474', '2023-01-26 18:50:21.492474', NULL, 'Value Proposition Design');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (31, 'نکات ساده، ایده های هوشمند', 'یک تجارت بزرگتر و بهتر بسازید', 'یک تجارت بزرگتر و بهتر بسازید', 23, 8, 'book', 't', '<p><em>نکات ساده، ایده‌های هوشمند</em> (2019) راهنمای کسب‌وکارهای کوچک است که به وعده عنوان خود عمل می‌کند. Erica Wolfe-Murray دانش پیشرفته صنعت در مورد رشد کسب و کار، بازاریابی هوشمندانه و نوآوری پایدار را در طیف وسیعی از نکات و ایده‌های آسان برای دنبال کردن، تقطیر می‌کند، که همگی برای کسب‌وکارهایی طراحی شده‌اند که بیشتر به بوتیک‌ها نسبت به غول‌های بزرگ منحرف می‌شوند. </p>', '2020-04-20 00:00:00', 4, 134, 'https://images.blinkist.io/images/books/5e9974576cee070006b2afc5/1_1/470.jpg', '/en/books/simple-tips-smart-ideas-en/purchase', 'نکات-ساده،-ایده-های-هوشمند', '2023-01-26 18:50:26.837092', '2023-01-26 18:50:26.837092', NULL, 'Simple Tips, Smart Ideas');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (32, 'تکنیک پومودورو', 'روشی موثر برای ساختاردهی روز کاری خود به تکه های کوچک و قابل مدیریت', 'روشی موثر برای ساختاردهی روز کاری خود به تکه های کوچک و قابل مدیریت', 16, 8, 'book', 't', '<p><em>تکنیک پومودورو </em>(2009) روشی ساده و در عین حال موثر برای ساختار روز کاری شما ارائه می دهد. این روش با تقسیم کارهای بزرگ یا پیچیده به قطعات کوچک و قابل مدیریت به غلبه بر بی انگیزگی شما کمک می کند. با استفاده از این تکنیک‌ها، کنترل بیشتری بر کار خود به دست خواهید آورد، در نتیجه شما را به کارگر مؤثرتری تبدیل می‌کنید و کار را با پاداش‌تر انجام می‌دهید.</p>', '2014-05-13 14:29:27', 5, 422, 'https://images.blinkist.io/images/books/537379cf6434360007680100/1_1/470.jpg', '/en/books/the-pomodoro-technique-en/purchase', 'تکنیک-پومودورو', '2023-01-26 18:50:31.873965', '2023-01-26 18:50:31.873965', NULL, 'The Pomodoro Technique');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (33, 'کاری کنید که تغییر برای شما کارساز باشد', 'ده راه برای اثبات آینده خود، بدون ترس نوآوری کنید و با وجود عدم اطمینان موفق شوید', 'ده راه برای اثبات آینده خود، بدون ترس نوآوری کنید و با وجود عدم اطمینان موفق شوید', 16, 7, 'book', 't', '<p><em>تغییر را به کار بیندازید</em> <em>شما </em>کاوشی جست و جوی در مورد اینکه چرا ما در مقابل تغییر مقاومت می کنیم و چرا باید در عوض آن را به عنوان یک فرصت ببینیم، ارائه می دهید. در بررسی برخی از موفق‌ترین شرکت‌ها و کارآفرینان آمریکایی، این کتاب چندین مطالعه موردی در مورد چگونگی سازگاری موفقیت‌آمیز با تغییر - به عنوان یک کارمند، رهبر تیم، یا حتی مدیر عامل ارائه می‌دهد.</p>', '2015-03-12 00:00:00', 4, 51, 'https://images.blinkist.io/images/books/54feba8c626661000aaf0000/1_1/470.jpg', '/en/books/make-change-work-for-you-en/purchase', 'کاری-کنید-که-تغییر-برای-شما-کارساز-باشد', '2023-01-26 18:50:36.820159', '2023-01-26 18:50:36.820159', NULL, 'Make Change Work for You');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (34, 'کلمات می توانند مغز شما را تغییر دهند', '12 استراتژی مکالمه برای ایجاد اعتماد، حل تعارض و افزایش صمیمیت', '12 استراتژی مکالمه برای ایجاد اعتماد، حل تعارض و افزایش صمیمیت', 19, 6, 'book', 't', '<p><em>واژه‌ها می‌توانند مغز شما را تغییر دهند </em>(2012) راهنمای ساده‌ای درباره هنر ارتباط مؤثر و دلسوزانه است. این پلک‌ها که از رفتار و پاسخ‌های طبیعی مغز مطلع می‌شوند، اقداماتی را بیان می‌کنند که می‌توانیم برای بهتر شدن در گوش دادن، بیان خود و تقویت اعتماد و همکاری با دیگران انجام دهیم. </p>', '2020-08-17 00:00:00', 4, 356, 'https://images.blinkist.io/images/books/5f3599516cee070006005242/1_1/470.jpg', '/en/books/words-can-change-your-brain-en/purchase', 'کلمات-می-توانند-مغز-شما-را-تغییر-دهند', '2023-01-26 18:50:41.95332', '2023-01-26 18:50:41.95332', NULL, 'Words Can Change Your Brain');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (35, 'انجام دهید', 'دوشنبه را نجات دهید، کار خود را دوباره اختراع کنید و هرگز گیر نکنید', 'دوشنبه را نجات دهید، کار خود را دوباره اختراع کنید و هرگز گیر نکنید', 11, 5, 'book', 't', '<p><em>Do Over </em>(2015) توضیح می دهد که چرا تغییر شدید در حرفه شما به سختی چیزی است که از آن ترسید - یعنی تا زمانی که ابزارهای مورد نیاز خود را دارید. این پلک‌ها شما را در ایجاد حساب پس‌انداز شغلی خود راهنمایی می‌کنند که حاوی نکات و ترفندهایی است تا شغل بن‌بست خود را به فرصتی برای انجام کاری کاملاً جدید تبدیل کنید.</p>', '2015-04-08 00:00:00', 4, 47, 'https://images.blinkist.io/images/books/5524612230666500070b0000/1_1/470.jpg', '/en/books/do-over-en/purchase', 'انجام-دهید', '2023-01-26 18:50:47.077723', '2023-01-26 18:50:47.077723', NULL, 'Do Over');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (36, 'بازپس گیری مکالمه', 'قدرت گفتگو در عصر دیجیتال', 'قدرت گفتگو در عصر دیجیتال', 18, 8, 'book', 't', '<p><em>بازیابی مکالمه</em> (2015) نشان دهنده نحوه تعامل ما با یکدیگر در دنیای دیجیتالی فزاینده ما است. وقفه‌های مداوم، بی‌پاسخ گذاشتن پیام‌ها و عدم علاقه، همگی در دنیای مملو از دستگاه‌های موبایل و صفحه‌نمایش به یک امر عادی تبدیل شده‌اند. اما آیا این همان چیزی است که ما می خواهیم؟ و اگر نه، چه کاری می توانیم در مورد آن انجام دهیم؟</p>', '2016-02-21 00:00:00', 4, 62, 'https://images.blinkist.io/images/books/56cb59b69bb2160007000039/1_1/470.jpg', '/en/books/reclaiming-conversation-en/purchase', 'بازپس-گیری-مکالمه', '2023-01-26 18:50:52.335297', '2023-01-26 18:50:52.335297', NULL, 'Reclaiming Conversation');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (37, 'ابر پیش بینی', 'هنر و علم پیش بینی', 'هنر و علم پیش بینی', 16, 7, 'book', 't', '<p>بر اساس دهه‌ها تحقیق و نتایج یک تورنمنت پیش‌بینی عظیم با بودجه دولتی، <em>Superforecasting </em> (2015) نحوه دقیق‌تر کردن پیش‌بینی‌های خود را توضیح می‌دهد، خواه در تلاش برای پیش‌بینی تغییرات در بازار سهام، سیاست یا زندگی روزمره.</p>', '2016-01-13 00:00:00', 4, 104, 'https://images.blinkist.io/images/books/5694af982f68270007000012/1_1/470.jpg', '/en/books/superforecasting-en/purchase', 'ابر-پیش-بینی', '2023-01-26 18:50:57.516875', '2023-01-26 18:50:57.516875', NULL, 'Superforecasting');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (39, 'چگونه برندها رشد می کنند', 'آنچه بازاریابان نمی دانند', 'آنچه بازاریابان نمی دانند', 18, 9, 'book', 't', '<p>در <em>برندها چگونه رشد می‌کنند</em>، بایرون شارپ با خرد بازاریابی مرسوم مقابله می‌کند، بسیاری از افسانه‌های بازاریابی مرسوم را با حقایق علمی رد می‌کند و برخی از اصول علمی اثبات‌شده را که بازاریابان باید از آن استفاده کنند، ایجاد می‌کند.</p>', '2014-04-15 06:12:08', 4, 81, 'https://images.blinkist.io/images/books/534d52776633610007620000/1_1/470.jpg', '/en/books/how-brands-grow-en/purchase', 'چگونه-برندها-رشد-می-کنند', '2023-01-26 18:51:07.834275', '2023-01-26 18:51:07.834275', NULL, 'How Brands Grow');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (40, 'بزرگ کردن عزیزم', 'یک مادر آمریکایی حکمت والدین فرانسوی را کشف می کند', 'یک مادر آمریکایی حکمت والدین فرانسوی را کشف می کند', 13, 6, 'book', 't', '<p>ممکن است درست به نظر برسد، اما در فرانسه، نوزادان و کودکان در طول شب می خوابند، سبزیجات خود را می خورند و آنچه والدینشان به آنها می گویند را انجام می دهند. در <em>Bringing Up Bébé</em> (2011)، پاملا دراکرمن، مادری آمریکایی که در پاریس زندگی می کند، اسرار والدین فرانسوی را که در دوران خارج از کشور کشف کرده بود، فاش می کند.</p>', '2016-09-28 00:00:00', 5, 88, 'https://images.blinkist.io/images/books/57e6c3f0afd7bf0003b7052d/1_1/470.jpg', '/en/books/bringing-up-bebe-en/purchase', 'بزرگ-کردن-عزیزم', '2023-01-26 18:51:12.57164', '2023-01-26 18:51:12.57164', NULL, 'Bringing Up Bébé');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (41, 'هریت تابمن', 'راه آزادی', 'راه آزادی', 18, 9, 'book', 't', '<p><em>Harriet Tubman: The Road to Freedom </em>(2004) زندگی جذاب هریت تابمن را روشن می کند، زنی پیشگام که نه تنها از بندهای برده داری فرار کرد، بلکه به صدها نفر دیگر نیز کمک کرد تا این کار را انجام دهند. یکسان. علاوه بر این، این کتاب بینش هایی در مورد نقش حیاتی او در جنگ داخلی آمریکا و در مبارزه برای حقوق برابر برای زنان و آفریقایی-آمریکایی ها ارائه می دهد.</p>', '2016-09-26 00:00:00', 5, 15, 'https://images.blinkist.io/images/books/57e6b20cafd7bf0003b704d9/1_1/470.jpg', '/en/books/harriet-tubman-en/purchase', 'هریت-تابمن', '2023-01-26 18:51:17.50468', '2023-01-26 18:51:17.50468', NULL, 'Harriet Tubman');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (43, 'ثروت استارت آپ', 'چگونه بهترین سرمایه گذاران فرشته در استارت آپ ها کسب درآمد می کنند', 'چگونه بهترین سرمایه گذاران فرشته در استارت آپ ها کسب درآمد می کنند', 11, 5, 'book', 't', '<p><em>ثروت استارت‌آپ</em> (2015) راهنمای شما برای سرمایه‌گذاری بهتر است. از سرمایه گذاران حرکتی گرفته تا سرمایه گذاران ارزشی و سرمایه گذاران جایگزین، طیف وسیعی از استراتژی های سرمایه گذاری فرشته گسترده است. این پلک‌ها به شما کمک می‌کند بهتر تشخیص دهید کدام یک از استارت‌آپ‌های امروزی ارزش وقت و پول نقد شما را دارند.</p>', '2016-04-06 00:00:00', 4, 24, 'https://images.blinkist.io/images/books/570250f48fb8ff000700000e/1_1/470.jpg', '/en/books/start-up-wealth-en/purchase', 'ثروت-استارت-آپ', '2023-01-26 18:51:27.972876', '2023-01-26 18:51:27.972876', NULL, 'Start-up Wealth');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (44, 'عادت رشد درآمد', 'هنر ساده رشد 15 درصدی کسب و کار شما در 15 دقیقه در روز', 'هنر ساده رشد 15 درصدی کسب و کار شما در 15 دقیقه در روز', 14, 6, 'book', 't', '<p><em>عادت رشد درآمد </em>(2015) مجموعه ای از استراتژی ها برای افزایش درآمد شما و افزایش قرار گرفتن در معرض مشتریان بالقوه و فعلی است. این روش ها سریع، آسان و مقرون به صرفه هستند - برای رساندن پیام شما به افرادی که بیشترین اهمیت را دارند، عالی هستند.</p>', '2017-03-30 00:00:00', 4, 35, 'https://images.blinkist.io/images/books/58da5b4f232de90004a6e635/1_1/470.jpg', '/en/books/the-revenue-growth-habit-en/purchase', 'عادت-رشد-درآمد', '2023-01-26 18:51:32.894183', '2023-01-26 18:51:32.894183', NULL, 'The Revenue Growth Habit');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (45, 'یک اتوبیوگرافی', 'داستان آزمایش های من با حقیقت', 'داستان آزمایش های من با حقیقت', 29, 11, 'book', 't', '<p><em>A Autobiography</em> (اولین بار در دو جلد منتشر شد؛ جلد 1، 1927، و جلد 2، 1929) زندگینامه یکی از مشهورترین نمادهای سیاسی جهان - Mohandas Karamchand گاندی است. این کتاب دوران کودکی شورشی او، فعالیت‌های اولیه‌اش در آفریقای جنوبی و فعالیت‌های او برای جنبش استقلال هند تا سال 1920 را طی می‌کند و بینشی از فلسفه شخصی گاندی و جستجوی مادام‌العمر او برای حقیقت می‌دهد.</p>', '2019-03-28 00:00:00', 4, 64, 'https://images.blinkist.io/images/books/5c9b86556cee070007d517f7/1_1/470.jpg', '/en/books/an-autobiography-en/purchase', 'یک-اتوبیوگرافی', '2023-01-26 18:51:38.018636', '2023-01-26 18:51:38.018636', NULL, 'An Autobiography');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (53, 'اصل عدم احتمال', 'چرا تصادفات، معجزات، و اتفاقات نادر هر روز اتفاق می افتد؟', 'چرا تصادفات، معجزات، و اتفاقات نادر هر روز اتفاق می افتد؟', 15, 8, 'book', 'f', '<p><em></em> <em>عدم احتمال</em> <em>اصل</em> زمینه علمی شانس و احتمال را روشن می کند. در نهایت نشان می‌دهد که حتی رویدادهایی که در غیر این صورت «معجزه‌آسا» در نظر می‌گیریم، تا زمانی که اطلاعات درستی داشته باشیم، واقعاً قابل انتظار هستند.</p>', '2014-07-01 00:00:00', 4, 17, 'https://images.blinkist.io/images/books/53b3c2693262310007060000/1_1/470.jpg', '/en/books/the-improbability-principle-en/purchase', 'اصل-عدم-احتمال', '2023-01-26 18:52:17.41913', '2023-01-26 18:52:17.41913', NULL, 'The Improbability Principle');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (46, 'سکس در سپیده دم', 'اینکه چگونه جفت می‌شویم، چرا منحرف می‌شویم، و چه معنایی برای روابط مدرن دارد', 'اینکه چگونه جفت می‌شویم، چرا منحرف می‌شویم، و چه معنایی برای روابط مدرن دارد', 22, 10, 'book', 't', '<p><em>سکس</em> <em>در</em> <em>سپیده دم</em> استدلال می‌کند که آرمانی‌سازی تک‌همسری در جوامع غربی اساساً با طبیعت انسان ناسازگار است. این کتاب با کاوش در تاریخ و تکامل تمایلات جنسی انسان، با تمرکز قوی بر اجداد نخستی ما و اختراع کشاورزی، مورد قانع‌کننده‌ای برای طبیعت ناپسند ذاتی ما است. <em>سکس</em> <em>در</em> <em>سپیده دم</em> با این استدلال که دیدگاه تحریف شده ما نسبت به تمایلات جنسی سلامت ما را خراب می کند و ما را از شاد بودن باز می دارد، توضیح می دهد که چگونه بازگشت به یک رویکرد معمولی تر رابطه جنسی می تواند به طور کلی برای روابط بین فردی و جوامع مفید باشد.</p>', '2014-08-19 00:00:00', 4, 355, 'https://images.blinkist.io/images/books/53f22f373162620008500000/1_1/470.jpg', '/en/books/sex-at-dawn-en/purchase', 'سکس-در-سپیده-دم', '2023-01-26 18:51:43.772426', '2023-01-26 18:51:43.772426', NULL, 'Sex at Dawn');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (47, 'نوآوری و کارآفرینی', 'کشف کنید که چگونه هر کسی در هر شغلی می تواند یک کارآفرین باشد', 'کشف کنید که چگونه هر کسی در هر شغلی می تواند یک کارآفرین باشد', 16, 9, 'book', 'f', '<p><em>نوآوری</em> <em>و</em> <em>کارآفرینی</em> (2006) نشان می‌دهد که چگونه نوآور باشید و استراتژی‌هایی را نشان می‌دهد که مشتریانی را برای نوآوری شما ایجاد می‌کنند. این نشان می‌دهد که چگونه کارآفرینی می‌تواند توسط هر کسی آموخته و اجرا شود و چگونه می‌توان از مهارت‌های کارآفرینی نه تنها در سرمایه‌گذاری‌های جدید، بلکه در شرکت‌های معتبر استفاده کرد.</p>', '2014-06-03 13:35:41', 4, 51, 'https://images.blinkist.io/images/books/538f1caf3761300007710000/1_1/470.jpg', '/en/books/innovation-and-entrepreneurship-en/purchase', 'نوآوری-و-کارآفرینی', '2023-01-26 18:51:48.591021', '2023-01-26 18:51:48.591021', NULL, 'Innovation and Entrepreneurship');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (48, 'بدون اختلال معمولی', 'چهار نیروی جهانی در حال شکستن همه روندها', 'چهار نیروی جهانی در حال شکستن همه روندها', 19, 8, 'book', 't', '<p><em>بدون اختلال معمولی</em> (2015) به جزئیات چهار نیرویی می‌پردازد که بازارهای جهان را به روش‌های عمیقی تغییر می‌دهند. این پلک‌ها به شما نشان می‌دهند که چگونه دنیای تجارت، مشاغلی که از آن حمایت می‌کنند و بازاری که آن را شکل می‌دهد، در حال تغییر هستند و شرکت‌ها، دولت‌ها و افراد چه کاری باید انجام دهند تا نه تنها بقای خود را ادامه دهند، بلکه در این نظم جدید جهانی موفق شوند.</p>', '2015-12-01 00:00:00', 4, 26, 'https://images.blinkist.io/images/books/565c7dd7990675000700004c/1_1/470.jpg', '/en/books/no-ordinary-disruption-en/purchase', 'بدون-اختلال-معمولی', '2023-01-26 18:51:53.482342', '2023-01-26 18:51:53.482342', NULL, 'No Ordinary Disruption');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (49, 'آناتومی یک اپیدمی', 'گلوله های جادویی، داروهای روانپزشکی، و افزایش حیرت انگیز بیماری های روانی در آمریکا', 'گلوله های جادویی، داروهای روانپزشکی، و افزایش حیرت انگیز بیماری های روانی در آمریکا', 19, 7, 'book', 't', '<p><em>آناتومی یک اپیدمی</em>(2010) توسعه داروهای سلامت روان و رابطه بین شرکت های داروسازی و حوزه روانپزشکی را ردیابی می کند. این پلک‌ها افسانه‌هایی را که در مورد چنین داروهایی به ما گفته‌اند، از بین می‌برند، و در این فرآیند، ممکن است شما را در مورد حکمت مبارزه با بیماری‌های روانی با انبوهی از قرص‌ها زیر سوال ببرند.</p>', '2017-02-24 00:00:00', 4, 40, 'https://images.blinkist.io/images/books/58a9a3438e98580004e55629/1_1/470.jpg', '/en/books/anatomy-of-an-epidemic-en/purchase', 'آناتومی-یک-اپیدمی', '2023-01-26 18:51:58.096271', '2023-01-26 18:51:58.096271', NULL, 'Anatomy of an Epidemic');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (50, 'بانک آمریکا', 'مبارزه حماسی برای ایجاد قانون فدرال رزرو', 'مبارزه حماسی برای ایجاد قانون فدرال رزرو', 18, 8, 'book', 't', '<p>در <em>America’s Bank</em> (2015)، داستان جذاب فدرال رزرو ایالات متحده یا "Fed" را خواهید دید. این چشمک‌ها تاریخچه توسعه و یکپارچگی سیستم بانکی آمریکا را نشان می‌دهد و شبکه پیچیده منافع و بازیگرانی را نشان می‌دهد که امروزه به شکل‌دهی سیستم ادامه می‌دهند.</p>', '2016-09-23 00:00:00', 4, 26, 'https://images.blinkist.io/images/books/57d6735a08c9270003b19235/1_1/470.jpg', '/en/books/americas-bank-en/purchase', 'بانک-آمریکا', '2023-01-26 18:52:01.766875', '2023-01-26 18:52:01.766875', NULL, 'America’s Bank');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (51, 'من یک دیگری هستم', 'زندگی مخفی استعاره و چگونگی شکل دادن آن به روشی که ما جهان را می بینیم', 'زندگی مخفی استعاره و چگونگی شکل دادن آن به روشی که ما جهان را می بینیم', 16, 9, 'book', 'f', '<p><em>من</em> <em>آیا</em> <em>یک</em> <em>دیگری</em> نشان می‌دهد که استعاره فقط یک ابزار ادبی نیست، بلکه راهی اساسی است که ما داریم. کشف و درک جهان نویسنده راه‌های مختلفی را نشان می‌دهد که در آن استعاره‌ها در زمینه‌های مختلف مانند سیاست، اقتصاد، روان‌شناسی، علم، تجارت و موارد دیگر استفاده می‌شوند.</p>', '2014-08-19 00:00:00', NULL, 4, 'https://images.blinkist.io/images/books/53f48a743433390008450100/1_1/470.jpg', '/en/books/i-is-an-other-en/purchase', 'من-یک-دیگری-هستم', '2023-01-26 18:52:06.939465', '2023-01-26 18:52:06.939465', NULL, 'I is an Other');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (52, 'استراتژی اقیانوس آبی', 'چگونه فضای بازار بی‌رقیب ایجاد کنیم و رقابت را بی‌ربط کنیم', 'چگونه فضای بازار بی‌رقیب ایجاد کنیم و رقابت را بی‌ربط کنیم', 8, 2, 'book', 't', '<p><em>استراتژی اقیانوس آبی</em> (2004) یک کلاسیک تجاری است که طرز تفکر شرکت ها در مورد رقابت بازار را متحول کرد. این توضیح می‌دهد که چرا برخی از کسب‌وکارها می‌توانند بدون رقابت رشد کنند، در حالی که بقیه در یک محیط بیش‌رقابتی یکدیگر را تکه تکه می‌کنند.</p>', '2023-01-03 00:00:00', 4, 216, 'https://images.blinkist.io/images/books/63ab132d73bf6d0009f220ff/1_1/470.jpg', '/en/books/blue-ocean-strategy-en/purchase', 'استراتژی-اقیانوس-آبی', '2023-01-26 18:52:12.231257', '2023-01-26 18:52:12.231257', NULL, 'Blue Ocean Strategy');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (54, 'زندگی فراتر از "چه می شد اگر؟"', 'محدودیت ها را رها کنید و رویاهای خود را محقق کنید', 'محدودیت ها را رها کنید و رویاهای خود را محقق کنید', 19, 6, 'book', 't', '<p><em>زندگی فراتر از «چه می‌شد اگر؟» </em>(2021) یک کتاب راهنمای همدلانه برای تحقق رویاهای شماست. حکایات صمیمی و مؤثر را به اشتراک می گذارد و راهنمای گام به گامی برای غلبه بر ترس های شما و دستیابی به موفقیت ارائه می دهد.</p>', '2021-11-15 00:00:00', 4, 480, 'https://images.blinkist.io/images/books/618d0b8b6cee070007adc7c7/1_1/470.jpg', '/en/books/living-beyond-what-if-en/purchase', 'زندگی-فراتر-از-"چه-می-شد-اگر؟"', '2023-01-26 18:52:30.106067', '2023-01-26 18:52:30.106067', NULL, 'Living Beyond “What If?”');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (55, 'یک زندگی رمزگشایی شده', 'ژنوم من: زندگی من', 'ژنوم من: زندگی من', 19, 8, 'book', 't', '<p><em>A Life Decoded</em> (2007) زندگینامه بیوشیمی دان و ژنتیک برجسته آمریکایی کریگ ونتر است که نقش کلیدی در یکی از بزرگترین دستاوردهای علمی عصر ما - رمزگشایی انسان - ایفا کرد. کد ژنتیکی. این پلک‌ها تجربیات شخصی را توصیف می‌کنند که منجر به تحقیقات علمی او شده است، حتی در زمان‌هایی که روش‌های او توسط جامعه علمی مورد حمله قرار می‌گرفت.</p>', '2015-10-05 00:00:00', 4, 23, 'https://images.blinkist.io/images/books/5612504bfd22820009000002/1_1/470.jpg', '/en/books/a-life-decoded-en/purchase', 'یک-زندگی-رمزگشایی-شده', '2023-01-26 18:52:35.090471', '2023-01-26 18:52:35.090471', NULL, 'A Life Decoded');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (56, '1% باد باد', 'چگونه شرکت های موفق از قیمت برای سود و رشد استفاده می کنند', 'چگونه شرکت های موفق از قیمت برای سود و رشد استفاده می کنند', 16, 6, 'book', 't', '<p><em>1% Windfall</em> (2010) استراتژی تعیین قیمت اغلب نادیده گرفته شده را معرفی می کند و نشان می دهد که چگونه شرکت ها می توانند با اتخاذ تصمیمات هوشمندانه قیمت گذاری حتی بیشتر رشد کنند. چگونه یک شرکت نه تنها می‌تواند در شرایط رقابت سخت بازار یا حتی دوره‌های تورمی یا رکود اقتصادی، زنده بماند، بلکه رشد کند؟ این پلک زدن ها به شما کمک می کند تا مسیر جذب مشتریان مورد نظر و حفظ مشتریانی را که دارید پیدا کنید.</p>', '2015-06-17 00:00:00', 4, 23, 'https://images.blinkist.io/images/books/557da7936533380007900000/1_1/470.jpg', '/en/books/the-1-percent-windfall-en/purchase', '1%-باد-باد', '2023-01-26 18:52:39.786127', '2023-01-26 18:52:39.786127', NULL, 'The 1% Windfall');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (57, 'توافقنامه پنجم', 'راهنمای عملی تسلط بر خود', 'راهنمای عملی تسلط بر خود', 14, 7, 'book', 't', '<p>ادراکات ما از خود واقعی مان توسط جامعه ای که در آن زندگی می کنیم و افراد اطرافمان تیره شده است. <em>توافقنامه پنجم</em> (2010) پنج پیمان را معرفی می کند که به شما کمک می کند تا این باورهای غلط را از بین ببرید و حقیقت را در مورد اینکه واقعاً چه کسی هستید - بدون فرار به قله کوه برای گوشه نشینی، آشکار کنید.</p>', '2015-08-07 00:00:00', 5, 130, 'https://images.blinkist.io/images/books/55c123923439630007ff0000/1_1/470.jpg', '/en/books/the-fifth-agreement-en/purchase', 'توافقنامه-پنجم', '2023-01-26 18:52:45.604566', '2023-01-26 18:52:45.604566', NULL, 'The Fifth Agreement');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (58, 'اولین نیش', 'چگونه غذا خوردن را یاد می گیریم', 'چگونه غذا خوردن را یاد می گیریم', 16, 7, 'book', 't', '<p><em>First Bite</em>(2015) ریشه واقعی مشکلات خوردن را آشکار می کند: اولین تجربیات دوران کودکی ما با غذا. این پلک ها با پشتوانه مطالعات علمی جذاب، خطرات بازاریابی غذا برای کودکان و تأثیر منفی هنجارهای جنسیتی و خانواده های خوش نیت را توضیح می دهند. در نهایت، آنها ما را به سمت تغییر مثبت رژیم غذایی هدایت می کنند.</p>', '2016-05-16 00:00:00', 4, 26, 'https://images.blinkist.io/images/books/57344a4ce2369000032901be/1_1/470.jpg', '/en/books/first-bite-en/purchase', 'اولین-نیش', '2023-01-26 18:52:50.899295', '2023-01-26 18:52:50.899295', NULL, 'First Bite');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (59, 'بحران آسایش', 'ناراحتی را در آغوش بگیرید تا خود وحشی، شاد و سالم خود را بازیابی کنید', 'ناراحتی را در آغوش بگیرید تا خود وحشی، شاد و سالم خود را بازیابی کنید', 20, 7, 'book', 't', '<p><em>بحران آسایش </em>(2021) درمانی برای مشکلات سلامت جسمی و روانی زندگی مدرن ارائه می دهد. همه چیز در مورد راحت شدن با ناراحتی است، که می تواند معنایی از خشن کردن آن در بیابان تا تفکر مرگ داشته باشد.</p>', '2021-07-22 00:00:00', 4, 160, 'https://images.blinkist.io/images/books/60f13ed56cee070007765a4a/1_1/470.jpg', '/en/books/the-comfort-crisis-en/purchase', 'بحران-آسایش', '2023-01-26 18:52:55.71279', '2023-01-26 18:52:55.71279', NULL, 'The Comfort Crisis');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (60, 'نوشتن اشتباهات من', 'زندگی، مرگ و رستگاری در یک زندان آمریکایی', 'زندگی، مرگ و رستگاری در یک زندان آمریکایی', 13, 6, 'book', 't', '<p><em>Writing My Wrongs </em>(2013) داستان مردی را روایت می کند که در طول اپیدمی کرک در دهه 1980 دیترویت بزرگ می شود. این پلک ها شما را به سفری از دوران کودکی شادش به زندگی پر از مواد مخدر، باند، قتل و محکومیت 19 ساله زندان می برد - و اینکه چگونه او از طریق نوشتن به امید و رستگاری دست یافت.</p>', '2017-04-20 00:00:00', NULL, 8, 'https://images.blinkist.io/images/books/58f49c2e1507cf00046b9938/1_1/470.jpg', '/en/books/writing-my-wrongs-en/purchase', 'نوشتن-اشتباهات-من', '2023-01-26 18:53:00.56472', '2023-01-26 18:53:00.56472', NULL, 'Writing My Wrongs');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (61, 'تمرکز', 'آینده شرکت شما به آن بستگی دارد', 'آینده شرکت شما به آن بستگی دارد', 19, 9, 'book', 't', '<p><em>Focus </em>(1996)<em> </em>توضیح می‌دهد که چگونه شرکت‌ها در آمریکا با تمرکز بر رشد، سود خود را از دست می‌دهند. این توضیح می دهد که استراتژی های مدیریتی پیشرو شرکت ها چیست و چرا آنها اشتباه هستند. علاوه بر این، در مورد استراتژی هایی که شرکت ها باید به جای آن اتخاذ کنند و چگونه می توانند شرکت خود را برای موفقیت بیشتر متمرکز کنند، توضیح می دهد.</p>', '2014-03-05 11:53:58', 4, 36, 'https://images.blinkist.io/images/books/53170e3d37646500086e0000/1_1/470.jpg', '/en/books/focus-en-al-ries/purchase', 'تمرکز', '2023-01-26 18:53:05.324449', '2023-01-26 18:53:05.324449', NULL, 'Focus');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (62, 'تله نصیحت', 'متواضع باشید، کنجکاو بمانید و راه هدایت خود را برای همیشه تغییر دهید', 'متواضع باشید، کنجکاو بمانید و راه هدایت خود را برای همیشه تغییر دهید', 17, 7, 'book', 't', '<p><em>تله نصیحت </em>(2020) راهنمای عملی برای رام کردن هیولای مشاوره درونی شما است. بسیاری از ما به دلیل ناامنی بودن و می‌خواهیم موقعیت‌هایی را که در آن قرار داریم کنترل کنیم، اجباراً نصیحت می‌کنیم. اما این به قیمت بیگانگی از دیگران و سرکوب نوآوری در محل کار است. به جای پرش با راه حل ها، باید حس کنجکاوی عمیقی را در خود پرورش دهیم و واقعاً یاد بگیریم که به دیگران گوش دهیم.</p>', '2020-06-19 00:00:00', 5, 416, 'https://images.blinkist.io/images/books/5ee88d016cee070006eacca4/1_1/470.jpg', '/en/books/the-advice-trap-en/purchase', 'تله-نصیحت', '2023-01-26 18:53:09.780466', '2023-01-26 18:53:09.780466', NULL, 'The Advice Trap');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (63, 'امروز نه', '9 عادت بهره وری فوق العاده', '9 عادت بهره وری فوق العاده', 24, 7, 'book', 't', '<p><em>Not Today</em>(2021) توضیح می‌دهد که چگونه می‌توانید از طریق 9 مرحله ساده بسیار سازنده شوید. نویسندگان بسیاری از این درس ها را در حین اداره تجارت خود و همزمان با مراقبت از پسر خردسال خود که به شدت بیمار است، آموختند.</p>', '2021-09-20 00:00:00', 4, 352, 'https://images.blinkist.io/images/books/61444c7f6cee070007e04d28/1_1/470.jpg', '/en/books/not-today-en/purchase', 'امروز-نه', '2023-01-26 18:53:15.126396', '2023-01-26 18:53:15.126396', NULL, 'Not Today');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (64, 'در یک بحران ارتباط برقرار کنید', 'رفتار مصرف کننده را درک کنید، درگیر کنید و بر آن تأثیر بگذارید تا اعتماد به برند را به حداکثر برسانید', 'رفتار مصرف کننده را درک کنید، درگیر کنید و بر آن تأثیر بگذارید تا اعتماد به برند را به حداکثر برسانید', 27, 8, 'book', 't', '<p><em>ارتباط در بحران</em> (2019) به بررسی این موضوع می‌پردازد که چگونه برندها می‌توانند به طور حساس و مؤثر در یک بحران ارتباط برقرار کنند. نویسنده کیت هارتلی توضیح می دهد که چرا مصرف کنندگان با برندها ارتباط نزدیک دارند و چرا رسانه های اجتماعی تهدیدی برای مشاغل هستند. او همچنین توصیه های ارزشمندی را برای نحوه اجرای یک طرح ارتباطی بحران ارائه می دهد.</p>', '2020-06-25 00:00:00', 4, 68, 'https://images.blinkist.io/images/books/5ef1d8256cee07000685117a/1_1/470.jpg', '/en/books/communicate-in-a-crisis-en/purchase', 'در-یک-بحران-ارتباط-برقرار-کنید', '2023-01-26 18:53:19.796245', '2023-01-26 18:53:19.796245', NULL, 'Communicate in a Crisis');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (65, 'سکون کلید است', 'فلسفه جاودانه رواقی و بودایی', 'فلسفه جاودانه رواقی و بودایی', 32, 10, 'book', 't', '<p><em>سکوت کلید است</em>(۲۰۱۹) اهمیت سکون را به ما نشان می‌دهد – توانایی تفکر واضح، اجتناب از حواس‌پرتی، غلبه بر انگیزه‌ها و یافتن شادی. این پلک ها با تکیه بر حکمت بزرگ ترین فیلسوفان تاریخ و عادات ورزشکاران، رهبران و هنرمندان برجسته نشان می دهد که چگونه دستیابی به سکون راهی قدرتمند برای کسب رضایت و موفقیت در زندگی است. </p>', '2019-10-01 00:00:00', 5, 1561, 'https://images.blinkist.io/images/books/5d9054c96cee070008710ee8/1_1/470.jpg', '/en/books/stillness-is-the-key-en/purchase', 'سکون-کلید-است', '2023-01-26 18:53:23.17302', '2023-01-26 18:53:23.17302', NULL, 'Stillness Is the Key');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (66, 'حذف بی رحمانه عجله', 'چگونه در هرج و مرج دنیای مدرن از نظر عاطفی سالم و از نظر روحی زنده بمانیم؟', 'چگونه در هرج و مرج دنیای مدرن از نظر عاطفی سالم و از نظر روحی زنده بمانیم؟', 25, 9, 'book', 't', '<p>در <em>حذف بی‌رحمانه عجله</em> (2019)، کشیش جان مارک کومر به ما می‌گوید که چگونه مشغله بیش از حد سلامت روان او را از بین برده، بر روابطش تأثیر می‌گذارد، و ارتباط او با ایمانش را ضعیف می‌کند. او با کاهش سرعت و محدود کردن تعهدات خود، شادی و خوشبختی را در هر بخش از زندگی خود به دست آورد. در اینجا او چهار تمرین ساده را به اشتراک می گذارد که به شما امکان می دهد لذت های یک زندگی بدون عجله را تجربه کنید. </p>', '2019-12-25 00:00:00', 5, 190, 'https://images.blinkist.io/images/books/5dfcada96cee07000788a1f4/1_1/470.jpg', '/en/books/the-ruthless-elimination-of-hurry-en/purchase', 'حذف-بی-رحمانه-عجله', '2023-01-26 18:53:27.857896', '2023-01-26 18:53:27.857896', NULL, 'The Ruthless Elimination of Hurry');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (67, 'سکس، دروغ و دست خط', 'یک متخصص برتر اسرار پنهان در دست خط شما را فاش می کند', 'یک متخصص برتر اسرار پنهان در دست خط شما را فاش می کند', 14, 5, 'book', 't', '<p><em>سکس، دروغ، و دست خط </em>(2006) یک راهنمای آموزنده برای شناسایی سرنخ هایی در دست خط یک فرد است که ماهیت واقعی آنها را آشکار می کند. این پلک‌ها که مملو از مثال‌های واقعی هستند، بینش‌های شگفت‌انگیزی از دنیای تحلیل دست‌خط و آنچه که هر بار که قلم روی کاغذ می‌گذاریم درباره خود آشکار می‌کنیم، ارائه می‌دهد. با این اطلاعات، دیگر هرگز به امضای یکسان نگاه نخواهید کرد!</p>', '2017-08-03 00:00:00', 4, 35, 'https://images.blinkist.io/images/books/597f2665b238e10005084460/1_1/470.jpg', '/en/books/sex-lies-and-handwriting-en/purchase', 'سکس،-دروغ-و-دست-خط', '2023-01-26 18:53:32.945198', '2023-01-26 18:53:32.945198', NULL, 'Sex, Lies, and Handwriting');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (68, 'نمک نمک چربی', 'غول های غذا چگونه ما را به خود جذب کردند', 'غول های غذا چگونه ما را به خود جذب کردند', 19, 8, 'book', 't', '<p><em>نمک</em> <em>شکر</em> <em>چربی</em> به بررسی ظهور صنعت مواد غذایی فرآوری شده در آمریکا و در سطح جهان می پردازد و چرا این صنعت توسط لیبرال ها تقویت شده است. استفاده از نمک، شکر و چربی این سه ماده برای ما انسان ها تقریبا غیرقابل مقاومت هستند، اما استفاده بیش از حد از آنها اثرات مخربی بر سلامتی نیز دارد.</p>', '2014-05-06 10:23:07', 4, 80, 'https://images.blinkist.io/images/books/536a073a6631340007900000/1_1/470.jpg', '/en/books/salt-sugar-fat-en/purchase', 'نمک-نمک-چربی', '2023-01-26 18:53:38.041405', '2023-01-26 18:53:38.041405', NULL, 'Salt Sugar Fat');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (70, 'تنها باید درخواست کنید', 'چگونه بر مهمترین مهارت برای موفقیت مسلط شویم', 'چگونه بر مهمترین مهارت برای موفقیت مسلط شویم', 28, 8, 'book', 't', '<p><em>همه کاری که باید انجام دهید این است که بپرسید</em> (2020) مجموعه ای از ابزارها را ارائه می دهد که به شما کمک می کند توانایی خود را برای درخواست چیزهایی که به موفقیت کمک می کند بهبود بخشید. این هشت مانع اصلی را شناسایی می‌کند که ما را از ارائه درخواست باز می‌دارند و بررسی می‌کند که چگونه می‌توان بر آنها غلبه کرد یا دور زد.</p>', '2020-10-27 00:00:00', 4, 111, 'https://images.blinkist.io/images/books/5f929df16cee070007038db0/1_1/470.jpg', '/en/books/all-you-have-to-do-is-ask-en/purchase', 'تنها-باید-درخواست-کنید', '2023-01-26 18:53:55.078384', '2023-01-26 18:53:55.078384', NULL, 'All You Have to Do Is Ask');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (71, 'رهبری نیمی از داستان است', 'نگاهی تازه به پیروی، رهبری و همکاری', 'نگاهی تازه به پیروی، رهبری و همکاری', 11, 5, 'book', 't', '<p><em>رهبری نیمی از داستان است</em> (2015) رهبری را به عنوان حالتی سیال معرفی می کند که افراد می توانند و باید با تغییر شرایط وارد و خارج شوند. با اتخاذ چنین رویکردی، می توانید همکاری را افزایش دهید و موفقیت را افزایش دهید.</p>', '2017-10-01 23:00:00', 4, 22, 'https://images.blinkist.io/images/books/59d11246b238e10006d636c7/1_1/470.jpg', '/en/books/leadership-is-half-the-story-en/purchase', 'رهبری-نیمی-از-داستان-است', '2023-01-26 18:54:00.129264', '2023-01-26 18:54:00.129264', NULL, 'Leadership is Half the Story');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (72, 'پارادوکس گیاهی', 'خطرات پنهان در غذاهای "سالم" که باعث بیماری و افزایش وزن می شوند', 'خطرات پنهان در غذاهای "سالم" که باعث بیماری و افزایش وزن می شوند', 13, 6, 'book', 't', '<p><em>پارادوکس گیاهی</em> (2017) به ما در مورد خطرات خوردن غذاهای گیاهی به ظاهر سالم هشدار می دهد. تفاوت‌های بین رژیم‌های غذایی ما و اجدادمان را بررسی می‌کند و به ما می‌گوید برای بهبود هضم و حفظ وزن مطلوب از کدام محصولات غذایی باید استفاده کنیم و از کدام محصولات اجتناب کنیم.</p>', '2018-03-23 00:00:00', 3, 193, 'https://images.blinkist.io/images/books/5ab4324db238e10005bf5837/1_1/470.jpg', '/en/books/the-plant-paradox-en/purchase', 'پارادوکس-گیاهی', '2023-01-26 18:54:05.09585', '2023-01-26 18:54:05.09585', NULL, 'The Plant Paradox');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (73, 'گفتگوهایی که می فروشند', 'با خریداران همکاری کنید و هر مکالمه‌ای را حساب کنید', 'با خریداران همکاری کنید و هر مکالمه‌ای را حساب کنید', 16, 9, 'book', 'f', '<p><em>مکالمه‌هایی که می‌فروشند </em>(2013) ماهیت متغیر فروش را نشان می‌دهد زیرا تمرکز آن از غزلیات در مورد محصول به نشان دادن تعهد به نیازهای خریدار تغییر می‌کند. از آماده‌سازی تا حل مشکل، این پلک‌ها شما را به یک مکالمه فروش برنده و یک حرفه فروش قوی راهنمایی می‌کنند.</p>', '2015-06-08 00:00:00', 4, 27, 'https://images.blinkist.io/images/books/55758e3e3935610007020000/1_1/470.jpg', '/en/books/conversations-that-sell-en/purchase', 'گفتگوهایی-که-می-فروشند', '2023-01-26 18:54:10.650444', '2023-01-26 18:54:10.650444', NULL, 'Conversations That Sell');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (74, 'صدایت را بلند کن', 'مانیفست علت', 'مانیفست علت', 9, 4, 'book', 't', '<p><em>صدای خود را بلند کنید</em> (2014) یک کتاب راهنما برای انتقال پیام شما به عنوان یک سازمان غیرانتفاعی است. این پلک‌ها همه چیزهایی را که باید بدانید برای ایجاد یک استراتژی ارتباطی خیره‌کننده توضیح می‌دهد که حامیان خود را جلب می‌کند و مردم را نسبت به ماموریت شما مشتاق نگه می‌دارد.</p>', '2016-06-03 00:00:00', NULL, 7, 'https://images.blinkist.io/images/books/57483c67c678450003db710f/1_1/470.jpg', '/en/books/raise-your-voice-en/purchase', 'صدایت-را-بلند-کن', '2023-01-26 18:54:15.880838', '2023-01-26 18:54:15.880838', NULL, 'Raise Your Voice');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (75, 'چگونه افراد موفق تربیت کنیم', 'درس های ساده برای نتایج رادیکال', 'درس های ساده برای نتایج رادیکال', 21, 7, 'book', 't', '<p><em>چگونه افراد موفق تربیت کنیم</em> (2019) اسرار والدین عالی را بررسی می کند. استر وویچیکی، مربی و مادر، با تکیه بر یک عمر تجربه در کسب بهترین نتیجه از جوانان، بررسی می کند که چگونه می توانید فرزندان خود را نه تنها موفق، بلکه مهربان و مستقل تربیت کنید. </p>', '2019-05-07 00:00:00', 4, 117, 'https://images.blinkist.io/images/books/5cd0bf836cee070008f3fd3f/1_1/470.jpg', '/en/books/how-to-raise-successful-people-en/purchase', 'چگونه-افراد-موفق-تربیت-کنیم', '2023-01-26 18:54:21.089487', '2023-01-26 18:54:21.089487', NULL, 'How to Raise Successful People');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (76, 'آناتومی صلح', 'چگونه قلب تضاد را حل کنیم', 'چگونه قلب تضاد را حل کنیم', 10, 4, 'book', 't', '<p><em>آناتومی صلح</em> (2006) به یک واقعیت ناخوشایند می پردازد: چقدر متداول است که مردم به تعارض به عنوان راهی برای حل و فصل اختلافات در خانه، محل کار و به طور کلی در جهان متوسل شوند. . دلایل این طرز فکر و اینکه چگونه می توانیم راه بهتری برای حرکت رو به جلو پیدا کنیم را بیاموزید. دلیلی وجود ندارد که فکر کنیم همه چیز باید به این شکل باشد که امروز است. با کمی درک، همه ما می توانیم راه صلح را انتخاب کنیم.</p>', '2017-06-21 00:00:00', 4, 52, 'https://images.blinkist.io/images/books/59450deab238e10005eece5e/1_1/470.jpg', '/en/books/the-anatomy-of-peace-en/purchase', 'آناتومی-صلح', '2023-01-26 18:54:26.306246', '2023-01-26 18:54:26.306246', NULL, 'The Anatomy of Peace');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (77, 'چگونه رژیم نگیریم', 'علم پیشگامانه کاهش وزن سالم و دائمی', 'علم پیشگامانه کاهش وزن سالم و دائمی', 32, 11, 'book', 't', '<p><em>چگونه رژیم نگیریم</em> (2019) به بررسی این موضوع می پردازد که چگونه یک رژیم غذایی سالم و گیاهی می تواند به کاهش وزن موثر، سالم و پایدار دست یابد. همچنین بررسی می کند که چرا بسیاری از افراد اضافه وزن دارند و راهنمای واضح و دقیقی برای مقابله با این مشکل ارائه می دهد. در اینجا هیچ راه‌حل سریع یا رژیم‌های معمولی وجود ندارد، فقط توصیه‌های علمی دقیقی است که می‌توانید به آنها اعتماد کنید.</p>', '2020-02-06 00:00:00', 5, 473, 'https://images.blinkist.io/images/books/5e3a84eb6cee070006ee6aee/1_1/470.jpg', '/en/books/how-not-to-diet-en/purchase', 'چگونه-رژیم-نگیریم', '2023-01-26 18:54:31.43032', '2023-01-26 18:54:31.43032', NULL, 'How Not to Diet');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (78, 'چگونه می‌توان بسیار جذاب بود', 'چسباندن انگشت به قانون جذب و انگشت شست به سمت عمل', 'چسباندن انگشت به قانون جذب و انگشت شست به سمت عمل', 13, 6, 'book', 't', '<p><em>How to be F*cking Awesome</em>(2016) شما را در گام های واقعی و عملی راهنمایی می کند تا بدون هیچ بهانه ای به اهداف خود برسید. این کتاب اصول ساده‌ای را ارائه می‌کند که به شما کمک می‌کند از خلأهای رایجی که افراد را از زندگی موفق باز می‌دارد اجتناب کنید.</p>', '2018-02-20 00:00:00', 4, 190, 'https://images.blinkist.io/images/books/5a88cd2eb238e1000705416a/1_1/470.jpg', '/en/books/how-to-be-f-star-cking-awesome-en/purchase', 'چگونه-می‌توان-بسیار-جذاب-بود', '2023-01-26 18:54:36.23734', '2023-01-26 18:54:36.23734', NULL, 'How to be F*cking Awesome');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (79, 'افتادن به گریس', 'بینش در مورد پایان رنج', 'بینش در مورد پایان رنج', 23, 7, 'book', 't', '<p><em>Falling into Grace </em>(2011) به بررسی چرایی رنج انسان ها می پردازد و راه هایی را به اشتراک می گذارد که از طریق آنها می توان مبارزه وجودی را رها کرد. با استفاده از بینش های عمیق معنوی، نشان می دهد که نحوه تفسیر ذهنی ما از جهان در ریشه اکثر مشکلات انسان نهفته است، و این که روش دیگری برای نگرش به جهان امکان پذیر است – که غنی و عاری از رنج باشد. </p>', '2021-06-26 00:00:00', 4, 40, 'https://images.blinkist.io/images/books/60d31ecc6cee070007e95e85/1_1/470.jpg', '/en/books/falling-into-grace-en/purchase', 'افتادن-به-گریس', '2023-01-26 18:54:41.147732', '2023-01-26 18:54:41.147732', NULL, 'Falling into Grace');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (80, 'تماس هوشمند', 'ترس، شکست و رد تماس سرد را از بین ببرید', 'ترس، شکست و رد تماس سرد را از بین ببرید', 15, 7, 'book', 't', '<p><em>تماس هوشمند</em> (2010) همه چیز در مورد هنر تماس سرد است، یک روش تجاری مهم که حتی فروشندگان باتجربه از آن می ترسند. بسیاری از ما تمایل داریم تماس سرد را با اتاقک‌های مرکز تماس، کسالت یا استراتژی‌های دستکاری مرتبط کنیم - اما لازم نیست اینطور باشد. این پلک‌ها توضیح می‌دهند که چگونه می‌توانید بر چالش‌های تماس سرد غلبه کنید و تجربه‌ای دلپذیرتر و رضایت‌بخش‌تر برای خود و مشتری، سرمایه‌گذار یا کارفرمای احتمالی‌تان ایجاد کنید.</p>', '2016-08-01 00:00:00', 4, 37, 'https://images.blinkist.io/images/books/5799d754355cc30003d1fed1/1_1/470.jpg', '/en/books/smart-calling-en/purchase', 'تماس-هوشمند', '2023-01-26 18:54:46.313779', '2023-01-26 18:54:46.313779', NULL, 'Smart Calling');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (81, 'چیزهایی که یک پرنده کوچک به من گفت', 'اعترافات یک ذهن خلاق', 'اعترافات یک ذهن خلاق', 15, 9, 'book', 'f', '<p><em>چیزهایی</em> <em>a</em> <em>کوچک</em> <em>پرنده</em> <em>گفته</em> <em>من</em> > داستان این است که چگونه بیز استون توانست توییتر را تأسیس کند و بینش های ارزشمندی را که او را به آنجا هدایت کرده است بررسی می کند. استون با تشویق دیگران به داشتن اعتماد به نفس متهورانه و متمرکز، و آگاهی از چگونگی کمک به دیگران، سرمایه داری جدیدی را برای عصر وب پیشنهاد می کند.</p>', '2014-05-27 14:08:36', 4, 18, 'https://images.blinkist.io/images/books/5385ec7a6162380007ca0000/1_1/470.jpg', '/en/books/things-a-little-bird-told-me-en/purchase', 'چیزهایی-که-یک-پرنده-کوچک-به-من-گفت', '2023-01-26 18:54:51.50155', '2023-01-26 18:54:51.50155', NULL, 'Things a Little Bird Told Me');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (82, 'این را بخر، نه آن را', 'چگونه راه خود را به سوی ثروت و آزادی سپری کنید', 'چگونه راه خود را به سوی ثروت و آزادی سپری کنید', 20, 4, 'book', 't', '<p><em>این را بخر، نه آن را </em>(2022) راهنمای نهایی شما برای دستیابی به استقلال مالی و آزادی است. به شما می گوید چه چیزی بخرید، چه مقدار خرج کنید، و چگونه بیشترین استفاده را از پول خود ببرید.</p>', '2022-10-10 00:00:00', 4, 304, 'https://images.blinkist.io/images/books/633e8c176cee0700080349b4/1_1/470.jpg', '/en/books/buy-this-not-that-en/purchase', 'این-را-بخر،-نه-آن-را', '2023-01-26 18:54:56.393186', '2023-01-26 18:54:56.393186', NULL, 'Buy This, Not That');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (83, 'باز شدن معجزه', 'خاطراتی از زندگی، مرگ و هر آنچه پس از آن می آید', 'خاطراتی از زندگی، مرگ و هر آنچه پس از آن می آید', 25, 8, 'book', 't', '<p>جولی ییپ ویلیامز به عنوان یک کودک نابینا از فقر ویتنام جنگ زده به وفور صلح آمیز لس آنجلس فرار کرد. برای اکثر مردم، این می‌توانست برجسته‌ترین رویداد زندگی آنها باشد - اما جولی برای یک زندگی عادی قرار نداشت. جولی در خاطرات صریح خود، <em>باز شدن معجزه </em> (2019)، ما را به سفری خارق‌العاده در زمان به همان اندازه خارق‌العاده‌اش روی زمین می‌برد - از تولد و نابینایی‌اش تا سفرهای جهانی‌اش و نبرد با سرطان نهایی. .</p>', '2019-08-23 00:00:00', 4, 24, 'https://images.blinkist.io/images/books/5d5bcf2b6cee0700075bd350/1_1/470.jpg', '/en/books/the-unwinding-of-the-miracle-en/purchase', 'باز-شدن-معجزه', '2023-01-26 18:55:01.33049', '2023-01-26 18:55:01.33049', NULL, 'The Unwinding of the Miracle');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (84, 'رشد می کند', 'دلایل شگفت انگیزی که چرا برخی از بچه ها مبارزه می کنند و برخی دیگر می درخشند', 'دلایل شگفت انگیزی که چرا برخی از بچه ها مبارزه می کنند و برخی دیگر می درخشند', 25, 7, 'book', 't', '<p><em>Thrivers </em>(2021) مطالعه ای است در مورد معنای کودک بودن در دنیای پر سرعت، فوق رقابتی و دیجیتال امروزی. بچه‌ها بیشتر و بیشتر به موفقیت می‌رسند، اما هرگز تا این حد احساس تنهایی و استرس نکرده‌اند. در عجله خود برای آماده کردن آنها برای آینده ای نامطمئن، به آنها یاد داده ایم که برای کسب افتخارات تلاش کنند، اما فراموش کرده ایم که موفقیت - و خوشبختی - بیشتر از نمرات و نمرات آزمون است. چیزی که کم است، تأکید بر کمک به رشد آنهاست.</p>', '2021-08-13 00:00:00', 4, 177, 'https://images.blinkist.io/images/books/610d30ab6cee070007ec8813/1_1/470.jpg', '/en/books/thrivers-en/purchase', 'رشد-می-کند', '2023-01-26 18:55:06.38571', '2023-01-26 18:55:06.38571', NULL, 'Thrivers');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (85, 'پول بیشتر از خدا', 'صندوق های تامینی و ایجاد نخبگان جدید', 'صندوق های تامینی و ایجاد نخبگان جدید', 20, 9, 'book', 't', '<p><em>پول بیشتر از خدا</em> نگاهی انتقادی به صندوق‌های تامینی، سازمان‌های قدرتمند و اغلب مرموز دارد که تأثیر زیادی بر امور مالی جهانی و زندگی روزمره ما دارند. با نگاهی به تاریخچه این روش سرمایه گذاری تاثیرگذار، نشان می دهد که صندوق های تامینی چگونه توسعه یافته اند و چگونه امروز کار می کنند.</p>', '2014-11-07 00:00:00', 4, 58, 'https://images.blinkist.io/images/books/54595aa13734660008400000/1_1/470.jpg', '/en/books/more-money-than-god-en/purchase', 'پول-بیشتر-از-خدا', '2023-01-26 18:55:12.085133', '2023-01-26 18:55:12.085133', NULL, 'More Money Than God');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (86, 'ساختن مغز دوم', 'روشی اثبات شده برای سازماندهی زندگی دیجیتالی و باز کردن پتانسیل خلاقانه شما', 'روشی اثبات شده برای سازماندهی زندگی دیجیتالی و باز کردن پتانسیل خلاقانه شما', 19, 4, 'book', 't', '<p><em>ساخت مغز دوم</em>توسط کارشناس بهره وری تیاگو فورته راه حل های ساده، موثر و قابل اجرا را برای یکی از بزرگترین چالش هایی که امروز با آن روبرو هستیم ارائه می دهد: اضافه بار اطلاعات. فورته با استفاده از چهار اصل سازمانی کلیدی نشان می‌دهد که چگونه می‌توانید از ابزارهای دیجیتال برای ایجاد یک سیستم ذخیره‌سازی دانش به اندازه مغز دوم بصری و کارآمد استفاده کنید. </p>', '2022-11-14 00:00:00', 5, 402, 'https://images.blinkist.io/images/books/636a372d11a60c0008278720/1_1/470.jpg', '/en/books/building-a-second-brain-en/purchase', 'ساختن-مغز-دوم', '2023-01-26 18:55:17.728438', '2023-01-26 18:55:17.728438', NULL, 'Building a Second Brain');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (87, 'تعویض', 'وقتی تغییر سخت است چگونه چیزها را تغییر دهیم', 'وقتی تغییر سخت است چگونه چیزها را تغییر دهیم', 20, 10, 'book', 't', '<p><em>Switch </em>بررسی می‌کند که چرا تغییر رفتار برای افراد اغلب دشوار است و چگونه با درک ذهن، می‌توان میان‌برهایی را یافت که تغییر را آسان‌تر می‌کنند. از طریق مطالعات علمی و حکایات، <em>Switch</em> ابزارهای ساده و در عین حال مؤثر برای اجرای تغییرات ارائه می‌کند.</p>', '2013-08-10 00:00:00', 4, 192, 'https://images.blinkist.io/images/books/516bbffde4b01b686deb9b1c/1_1/470.jpg', '/en/books/switch-en/purchase', 'تعویض', '2023-01-26 18:55:22.960128', '2023-01-26 18:55:22.960128', NULL, 'Switch');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (88, 'اول پدرم را کشتند', 'یک دختر کامبوج به یاد می آورد', 'یک دختر کامبوج به یاد می آورد', 14, 6, 'book', 't', '<p><em>First They Killed My Father</em> (2006) خاطرات لونگ اونگ از تجربیات دوران کودکی‌اش است که در دهه 1970 تحت رژیم خمرهای سرخ در کامبوج زندگی می‌کرد. او داستان خود را زمانی آغاز می‌کند که خمرهای سرخ قدرت را در دست می‌گیرند و خانواده‌اش را مجبور می‌کنند تا از پایتخت کشور، پنوم پن، فرار کنند، اما در ترس دائمی از اینکه شخصاً توسط رژیم هدف قرار بگیرند، به عنوان برده‌کار زندگی می‌کنند.</p>', '2018-06-29 00:00:00', 4, 12, 'https://images.blinkist.io/images/books/5b2ff607b238e10006f8a88f/1_1/470.jpg', '/en/books/first-they-killed-my-father-en/purchase', 'اول-پدرم-را-کشتند', '2023-01-26 18:55:28.446119', '2023-01-26 18:55:28.446119', NULL, 'First They Killed My Father');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (89, 'ماجراهای تجاری', 'دوازده داستان کلاسیک از دنیای وال استریت', 'دوازده داستان کلاسیک از دنیای وال استریت', 29, 13, 'book', 't', '<p><em>کسب و کار</em> <em>ماجراجویی</em> شامل دوازده مطالعه موردی جذاب از تحولات کلیدی در تجارت، اقتصاد و امور مالی است. در حالی که آنها به رویدادها و شرکت هایی مربوط می شوند که ممکن است هرگز نام آنها را نشنیده باشید، مطالعات موردی بسیار سرگرم کننده هستند و درس های آموخته شده از آنها هنوز هم امروزه قابل استفاده است.</p>', '2014-08-13 00:00:00', 4, 107, 'https://images.blinkist.io/images/books/53e4ff1932633900073d0000/1_1/470.jpg', '/en/books/business-adventures-en/purchase', 'ماجراهای-تجاری', '2023-01-26 18:55:33.022695', '2023-01-26 18:55:33.022695', NULL, 'Business Adventures');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (90, 'افسر ارشد شادی', 'چگونه رهبران بزرگ انرژی انسان را بالا می برند و ترس را از بین می برند', 'چگونه رهبران بزرگ انرژی انسان را بالا می برند و ترس را از بین می برند', 21, 7, 'book', 't', '<p>در <em>Chief Joy Officer </em> (2018)، ریچارد شریدان نحوه ایجاد فرهنگ شرکتی مبتنی بر شادی را به اشتراک می گذارد. کتاب شریدان مملو از حکایات حرفه‌ای خودش است و راهنمای روشنی برای ساختن شرکتی با هدف و محل کاری است که مردم می‌توانند آن را دوست داشته باشند.</p>', '2019-01-25 00:00:00', 5, 28, 'https://images.blinkist.io/images/books/5c49e2896cee070007b962ac/1_1/470.jpg', '/en/books/chief-joy-officer-en/purchase', 'افسر-ارشد-شادی', '2023-01-26 18:55:38.064166', '2023-01-26 18:55:38.064166', NULL, 'Chief Joy Officer');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (91, 'شروع به پایان', 'چگونه از ایده به پایان برسیم', 'چگونه از ایده به پایان برسیم', 19, 7, 'book', 't', '<p><em>شروع به اتمام </em>(2019) راهنمایی برای تبدیل ایده های خود به پروژه هایی است که می توانید تا پایان راه را پیش ببرید. مراحل و نکاتی را برای انتخاب ایده مناسب، امکان‌پذیر ساختن آن و غلبه بر چالش‌هایی که ممکن است در این مسیر با آن‌ها روبرو شوید، به اشتراک می‌گذارد. </p>', '2021-06-05 00:00:00', 5, 94, 'https://images.blinkist.io/images/books/60b617076cee070007ae2e64/1_1/470.jpg', '/en/books/start-finishing-en/purchase', 'شروع-به-پایان', '2023-01-26 18:55:42.760698', '2023-01-26 18:55:42.760698', NULL, 'Start Finishing');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (92, 'جهل', 'چگونه علم را هدایت می کند', 'چگونه علم را هدایت می کند', 19, 8, 'book', 't', '<p><em>جهل</em> به بررسی نقاط قوت و ضعف روش علمی می‌پردازد و اهمیت پرسیدن سؤالات درست را نسبت به کشف حقایق ساده نشان می‌دهد. با استفاده از مثال‌های واقعی از تاریخ، <em>جهل</em> نشان می‌دهد که آگاهی ما از آنچه که <em>نمی‌دانیم</em> است که باعث کشف علمی می‌شود.</p>', '2014-09-09 00:00:00', 4, 10, 'https://images.blinkist.io/images/books/540de8a866613400083c0000/1_1/470.jpg', '/en/books/ignorance-en/purchase', 'جهل', '2023-01-26 18:55:47.708946', '2023-01-26 18:55:47.708946', NULL, 'Ignorance');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (93, '12 قانون برای زندگی', 'پادزهری برای آشوب', 'پادزهری برای آشوب', 33, 12, 'book', 't', '<p><em>12 Rules For Life</em> (2018) فهرستی از مبرم ترین نگرانی های زندگی و مسائلی را که از زمان های قدیم در روان انسان وجود داشته است در اختیار خوانندگان قرار می دهد. نویسنده جوردن بی پیترسون برخی از ماندگارترین اظهارات فلسفی و مذهبی و همچنین درس‌هایی از ارزشمندترین داستان‌های ما را جمع‌آوری کرده است تا 12 دستورالعمل برای اطمینان از زندگی معنادار به ما ارائه دهد. با تکیه بر فلسفه، روانشناسی، تاریخ و اسطوره، اینها اصول روشن و ثابتی هستند که همه می توانند بر اساس آنها زندگی کنند.</p>', '2018-04-09 00:00:00', 4, 1915, 'https://images.blinkist.io/images/books/5acbf46ab238e100074fca22/1_1/470.jpg', '/en/books/12-rules-for-life-en/purchase', '12-قانون-برای-زندگی', '2023-01-26 18:55:52.698188', '2023-01-26 18:55:52.698188', NULL, '12 Rules For Life');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (94, 'آخرین سخنرانی', 'انعکاس الهام بخش زندگی در آخرین لحظاتش', 'انعکاس الهام بخش زندگی در آخرین لحظاتش', 21, 6, 'book', 't', '<p><em>آخرین سخنرانی </em>(2008) نشخواری صمیمانه و روشنگرانه در مورد زندگی، مرگ و ارزش دنبال کردن رویاهایتان است. در این متن منحصر به فرد، رندی پاوش، دانشمند کامپیوتر، مرگ و میر پس از دریافت تشخیص نهایی سرطان را منعکس می کند. </p>', '2021-08-28 00:00:00', 4, 195, 'https://images.blinkist.io/images/books/611fc93a6cee0700070603ba/1_1/470.jpg', '/en/books/the-last-lecture-en/purchase', 'آخرین-سخنرانی', '2023-01-26 18:55:57.564706', '2023-01-26 18:55:57.564706', NULL, 'The Last Lecture');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (95, 'بدون چراغ قرمز', 'تاملی در مورد زندگی، 50 سال در سرمایه گذاری خطرپذیر، و هرگز به تنهایی رانندگی نکنید', 'تاملی در مورد زندگی، 50 سال در سرمایه گذاری خطرپذیر، و هرگز به تنهایی رانندگی نکنید', 29, 12, 'book', 't', '<p><em>No Red Lights </em>(2022) بخشی از زندگینامه است، بخشی از کتاب راهنمای جمع آوری اصول اصلی حرفه شما. این برنامه عمدتاً برای سرمایه‌گذاران سرمایه‌گذاری خطرپذیر مشتاق است، اما برای هر کسی که به تجارت علاقه دارد مفید است، مملو از درس‌های آموزنده و توصیه‌های مفید است. به طور همزمان، نگاهی اجمالی به زندگی انسانی است که 50 سال را صرف آموختن - و زندگی - ترفندهای این حرفه کرده است.</p>', '2022-05-06 00:00:00', 4, 112, 'https://images.blinkist.io/images/books/6274d5b06cee07000829ec9a/1_1/470.jpg', '/en/books/no-red-lights-en/purchase', 'بدون-چراغ-قرمز', '2023-01-26 18:56:02.976774', '2023-01-26 18:56:02.976774', NULL, 'No Red Lights');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (96, 'یک رشته نامرئی', 'داستان واقعی یک پانهندلر 11 ساله، یک مدیر فروش شلوغ و یک ملاقات بعید با سرنوشت', 'داستان واقعی یک پانهندلر 11 ساله، یک مدیر فروش شلوغ و یک ملاقات بعید با سرنوشت', 18, 9, 'book', 't', '<p><em>An Invisible Thread</em>(2011) داستان دوستی باورنکردنی و بعید بین یک تاجر موفق و یک پسر جوان فقیر را بازگو می کند - دوستی که در نهایت زندگی هر دوی آنها را برای همیشه تغییر داد.</em><em> p>', '2015-12-17 00:00:00', 5, 12, 'https://images.blinkist.io/images/books/566ffa83cf6aa30007000043/1_1/470.jpg', '/en/books/an-invisible-thread-en/purchase', 'یک-رشته-نامرئی', '2023-01-26 18:56:08.556485', '2023-01-26 18:56:08.556485', NULL, 'An Invisible Thread');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (97, 'ثروت از عقل سلیم', 'چرا سادگی ترامپ از پیچیدگی در هر طرح سرمایه گذاری جلوگیری می کند؟', 'چرا سادگی ترامپ از پیچیدگی در هر طرح سرمایه گذاری جلوگیری می کند؟', 14, 6, 'book', 't', '<p><em>A Wealth of Common Sense</em> (2015) نشان می دهد که چگونه تصمیمات درست می تواند شما را به عنوان یک سرمایه گذار به موفقیت بلندمدت برساند. این پلک ها نکاتی را ارائه می دهند که هر سرمایه گذار باید از همان ابتدا بداند و توضیح می دهد که چگونه می توانید یک استراتژی متنوع و منسجم ایجاد کنید که در آزمون زمان مقاومت کند.</p>', '2016-06-21 00:00:00', 4, 99, 'https://images.blinkist.io/images/books/576177ea0beabd0003161b19/1_1/470.jpg', '/en/books/a-wealth-of-common-sense-en/purchase', 'ثروت-از-عقل-سلیم', '2023-01-26 18:56:13.780906', '2023-01-26 18:56:13.780906', NULL, 'A Wealth of Common Sense');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (98, 'چه چیزی ما را انسان می کند؟', 'دلایل متفاوت بودن ما', 'دلایل متفاوت بودن ما', 31, 13, 'book', 't', '<p>در <em>What Makes Us Human</em> (2007)، گروهی از متخصصان نظرات خود را در مورد این سوال چند صد ساله به اشتراک می گذارند. این پلک‌ها اعماق اسرار گونه ما را نشان می‌دهند تا دریابند چرا انسان‌ها به تنهایی غذا می‌پزند تا بخورند، خلاقانه فکر کنند و علت و معلول را درک کنند.</p>', '2016-08-08 00:00:00', 4, 19, 'https://images.blinkist.io/images/books/57a4d5394098350003c58841/1_1/470.jpg', '/en/books/what-makes-us-human-en/purchase', 'چه-چیزی-ما-را-انسان-می-کند؟', '2023-01-26 18:56:18.530631', '2023-01-26 18:56:18.530631', NULL, 'What Makes Us Human?');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (99, 'راه حل خواب', 'چرا خواب شما شکسته است و چگونه آن را برطرف کنید', 'چرا خواب شما شکسته است و چگونه آن را برطرف کنید', 18, 8, 'book', 't', '<p><em>راه حل خواب </em>(2017) اصول خواب را مورد بحث قرار می دهد. این توضیح می‌دهد که چرا حفظ یک ریتم و برنامه ثابت مهم است و چگونه بی‌خوابی کمبود خواب نیست، بلکه نتیجه برخورد نامناسب با خواب نامرغوب است. یاد خواهید گرفت که چگونه الگوهای خواب خود را بهبود ببخشید و در نتیجه کیفیت زندگی خود را بهبود ببخشید.</p>', '2017-09-21 00:00:00', 4, 329, 'https://images.blinkist.io/images/books/59bf93d1b238e100052dbd5c/1_1/470.jpg', '/en/books/the-sleep-solution-en/purchase', 'راه-حل-خواب', '2023-01-26 18:56:23.349429', '2023-01-26 18:56:23.349429', NULL, 'The Sleep Solution');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (100, 'منطقه برای برنده شدن', 'سازماندهی برای رقابت در عصر اختلال', 'سازماندهی برای رقابت در عصر اختلال', 18, 8, 'book', 't', '<p><em>Zone to Win </em>(2015) راهنمای نهایی سازماندهی شرکت شما برای رقابت موثر در عصر اختلال است. این پلک‌ها به شما نشان می‌دهند که چگونه با نوآوری‌های ثابت بازار همراه شوید و در عین حال اختلالات سودآوری را برای خودتان ایجاد کنید.</p>', '2016-10-28 00:00:00', 4, 38, 'https://images.blinkist.io/images/books/580bb680d4d2ce0003dd24fe/1_1/470.jpg', '/en/books/zone-to-win-en/purchase', 'منطقه-برای-برنده-شدن', '2023-01-26 18:56:28.234948', '2023-01-26 18:56:28.234948', NULL, 'Zone To Win');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (101, 'ابتدا تمام قوانین را زیر پا بگذارید', 'کارهایی که بزرگترین مدیران جهان متفاوت انجام می دهند', 'کارهایی که بزرگترین مدیران جهان متفاوت انجام می دهند', 26, 12, 'book', 't', '<p><em>اول، شکستن همه قوانین</em> (1999) نشان می‌دهد که مدیریت عالی چقدر با رویکردهای مرسوم متفاوت است. نویسندگان نشان می دهند که چگونه برخی از تصورات رایج در مورد شغل و مدیریت واقعا گمراه کننده هستند. بر اساس مصاحبه های انجام شده با مدیران موفق (تحقیقی که نویسندگان برای گالوپ انجام دادند)، این کتاب خوانندگان خود را با مفاهیم کلیدی آشنا می کند که مدیران بزرگ - کسانی که کارکنان خود را برای دستیابی به عملکرد عالی ترغیب می کنند - در شغل خود استفاده می کنند.</p>', '2014-02-19 09:00:00', 4, 111, 'https://images.blinkist.io/images/books/530466a53439370008160000/1_1/470.jpg', '/en/books/first-break-all-the-rules-en/purchase', 'ابتدا-تمام-قوانین-را-زیر-پا-بگذارید', '2023-01-26 18:56:32.863856', '2023-01-26 18:56:32.863856', NULL, 'First, Break all the Rules');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (102, 'شجاعت در بیابان', 'تلاش برای تعلق واقعی و شجاعت تنها ماندن', 'تلاش برای تعلق واقعی و شجاعت تنها ماندن', 16, 6, 'book', 't', '<p><em>Braving The Wilderness </em>(2017) مفاهیم رایج در مورد معنای تعلق را به چالش می کشد. این احساس عدم تعلق را به احساس خشم و ناآرامی، هم در ایالات متحده و هم در خارج از کشور مرتبط می کند. برنه براون از ترکیبی قوی از تحقیقات علمی و داستان سرایی استفاده می کند تا معنای واقعی تعلق را آشکار کند. این شامل داستان‌های قابل‌توجهی از درد و رنج است که نشان می‌دهد مردم چقدر مایلند برای به دست آوردن احساس تعلق پیش بروند.</p>', '2018-01-29 00:00:00', 4, 270, 'https://images.blinkist.io/images/books/5a6c4741b238e100076e8489/1_1/470.jpg', '/en/books/braving-the-wilderness-en/purchase', 'شجاعت-در-بیابان', '2023-01-26 18:56:38.39155', '2023-01-26 18:56:38.39155', NULL, 'Braving the Wilderness');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (103, 'طرز فکر Serendipity', 'هنر و علم ایجاد خوش شانسی', 'هنر و علم ایجاد خوش شانسی', 30, 10, 'book', 't', '<p><em>ذهنیت Serendipity </em>(2020) راهنمای عملی برای استقبال از نتایج مثبت و اتفاقی تر در زندگی شما ارائه می دهد. این توضیح می دهد که چگونه تغییرات ظریف در نگرش و ادراک شما می تواند منجر به تفاوت های چشمگیر در توانایی شما برای استقامت و گرفتن نتایج مثبت شود.</p>', '2020-09-24 00:00:00', 4, 196, 'https://images.blinkist.io/images/books/5f691c4f6cee0700061eb443/1_1/470.jpg', '/en/books/the-serendipity-mindset-en/purchase', 'طرز-فکر-Serendipity', '2023-01-26 18:56:44.148789', '2023-01-26 18:56:44.148789', NULL, 'The Serendipity Mindset');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (104, 'راه حل کاغذ', 'چه چیزی را تکه تکه کنید، چه چیزی را ذخیره کنید، و چگونه از تسخیر زندگی خود جلوگیری کنید', 'چه چیزی را تکه تکه کنید، چه چیزی را ذخیره کنید، و چگونه از تسخیر زندگی خود جلوگیری کنید', 22, 7, 'book', 't', '<p><em>راه حل کاغذ: چه چیزی را خرد کنید، چه چیزی را ذخیره کنید، و چگونه از تسخیر زندگی خود جلوگیری کنید </em>(2020)<em></em>راهنمای مدیریت شلوغی کاغذ است که بسیاری از مردم را آزار می دهد. این روش جدیدی را برای پاک کردن زباله‌ها، ارزیابی اسناد و توسعه سیستم‌هایی برای پردازش کاغذها به محض ورود ارائه می‌کند - به شما این امکان را می‌دهد که فضای و آزادی خود را بازیابی کنید.</p>', '2021-03-08 00:00:00', 4, 74, 'https://images.blinkist.io/images/books/6041fba16cee0700073e4177/1_1/470.jpg', '/en/books/the-paper-solution-en/purchase', 'راه-حل-کاغذ', '2023-01-26 18:56:49.385324', '2023-01-26 18:56:49.385324', NULL, 'The Paper Solution');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (105, 'کودک متصل', 'برای خانواده فرزندخوانده خود امید و شفا بیاورید', 'برای خانواده فرزندخوانده خود امید و شفا بیاورید', 27, 9, 'book', 't', '<p><em>کودک متصل</em>(2007) راهنمای روشنگری برای والدین فرزندان خوانده و خوانده شده است. کودکانی که دارای زمینه های محروم یا بدرفتار هستند نیازهای منحصر به فردی دارند. با اتخاذ یک رویکرد چند جانبه از جمله مداخلات رفتاری، رژیم غذایی خوب و ورزش، و مراقبت های فراوان، والدین می توانند نقشی حیاتی در کمک به بهبودی فرزندان خود ایفا کنند. </p>', '2021-03-13 00:00:00', 5, 49, 'https://images.blinkist.io/images/books/6041fd836cee0700073e41a1/1_1/470.jpg', '/en/books/the-connected-child-en/purchase', 'کودک-متصل', '2023-01-26 18:56:54.182484', '2023-01-26 18:56:54.182484', NULL, 'The Connected Child');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (106, 'مرد کارخانه', 'چگونه یک سازنده مبلمان با خارج از کشور مبارزه کرد، محلی ماند و به نجات یک شهر آمریکایی کمک کرد', 'چگونه یک سازنده مبلمان با خارج از کشور مبارزه کرد، محلی ماند و به نجات یک شهر آمریکایی کمک کرد', 15, 8, 'book', 'f', '<p><em>مرد کارخانه</em> از جنبه تاریک جهانی شدن پرده برداری می کند. یعنی تأثیر وحشتناکی که بر تجارت آمریکایی و زندگی کارگران کارخانه داشته است. در بررسی دقیق خود از تولید مبلمان قرن بیستم، نشان می دهد که چگونه می توان با مرگ اقتصاد محلی مبارزه کرد و مهمتر از آن، چرا این مبارزه ارزشش را دارد.</p>', '2015-03-10 00:00:00', NULL, 4, 'https://images.blinkist.io/images/books/54fdbdea626661000a250000/1_1/470.jpg', '/en/books/factory-man-en/purchase', 'مرد-کارخانه', '2023-01-26 18:56:58.956079', '2023-01-26 18:56:58.956079', NULL, 'Factory Man');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (107, 'کد', 'بیوگرافی ماهی هایی که دنیا را تغییر دادند', 'بیوگرافی ماهی هایی که دنیا را تغییر دادند', 14, 6, 'book', 't', '<p><em>Cod</em> (1997) ظهور و سقوط ماهی کاد را ترسیم می کند. ماهی کاد یکی از کالاهای اصلی در بازار اروپا در طول کشف دنیای جدید، منجر به درگیری های ملی شد و به دلیل صید بی رویه، در نهایت در معرض انقراض قرار گرفت. دریابید که چگونه این ماهی جهان را تغییر داد تا در آستانه فراموشی قرار گیرد.</p>', '2016-08-04 00:00:00', 4, 37, 'https://images.blinkist.io/images/books/5799e999e0bc1b000321bcb9/1_1/470.jpg', '/en/books/cod-en/purchase', 'کد', '2023-01-26 18:57:11.6789', '2023-01-26 18:57:11.6789', NULL, 'Cod');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (108, 'داستان هایی برای کار', 'راهنمای ضروری برای داستان سرایی کسب و کار', 'راهنمای ضروری برای داستان سرایی کسب و کار', 27, 9, 'book', 't', '<p>در <em>داستان‌هایی برای کار </em> (2017)، گابریل دولان اثربخشی یک داستان قدرتمند را توضیح می‌دهد و اینکه چگونه متخصصان کسب‌وکار می‌توانند از این ابزار برای انتقال ایده‌ها، ایجاد انگیزه در کارکنان، متقاعد کردن مشتریان و دستیابی به اهداف استفاده کنند. Dolan شما را با توصیه های عملی در مورد ارائه داستان های خود و نحوه اعمال آنها در طیف وسیعی از سناریوهای تجاری راهنمایی می کند.</p>', '2019-01-31 00:00:00', 4, 122, 'https://images.blinkist.io/images/books/5c5033c36cee070007d815a0/1_1/470.jpg', '/en/books/stories-for-work-en/purchase', 'داستان-هایی-برای-کار', '2023-01-26 18:57:17.632543', '2023-01-26 18:57:17.632543', NULL, 'Stories for Work');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (109, 'ساعتی بین سگ و گرگ', 'چگونه ریسک پذیری ما، بدن و ذهن را متحول می کند', 'چگونه ریسک پذیری ما، بدن و ذهن را متحول می کند', 22, 10, 'book', 't', '<p><em>ساعت بین سگ و گرگ</em>نگاهی روشنگر به تأثیر فیزیولوژی انسان بر تفکر و رفتار معامله‌گران بازار سهام است. نویسنده، با الهام از تجربیات خود در بازار معاملات، اساس هورمونی تصمیم‌گیری مالی را بررسی می‌کند و روشی را نشان می‌دهد که مکانیسم‌های بدن می‌توانند بازارهای مالی ما را بی‌ثبات کنند. این کتاب همچنین توضیح می دهد که برای کاهش اثرات مضر زیست شناسی ما در بازار چه کاری می توان انجام داد، و حتی چگونه می توانیم از این دانش به نفع مالی خود استفاده کنیم.</p>', '2014-10-20 00:00:00', 4, 51, 'https://images.blinkist.io/images/books/5444b35f6161330008170000/1_1/470.jpg', '/en/books/the-hour-between-dog-and-wolf-en/purchase', 'ساعتی-بین-سگ-و-گرگ', '2023-01-26 18:57:22.643167', '2023-01-26 18:57:22.643167', NULL, 'The Hour Between Dog and Wolf');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (110, 'علم ثروتمند شدن', 'کلید اصلی موفقیت شما', 'کلید اصلی موفقیت شما', 11, 5, 'book', 't', '<p><em>علم ثروتمند شدن </em>(1910) یک کلاسیک خودیاری است که در آن نویسنده راهنمای خود را برای دستیابی به یک زندگی سرشار ارائه می دهد. این پلک ها نحوه استفاده از تفکر جهت دار را برای جذب فرصت ها و ثروت و در حین انجام هر چیزی که می خواهید توضیح می دهد.</p>', '2017-12-19 00:00:00', 4, 170, 'https://images.blinkist.io/images/books/5a3562feb238e100077286d4/1_1/470.jpg', '/en/books/the-science-of-getting-rich-en/purchase', 'علم-ثروتمند-شدن', '2023-01-26 18:57:27.783571', '2023-01-26 18:57:27.783571', NULL, 'The Science of Getting Rich');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (111, 'شبکه', 'ابزار تصمیم گیری برای هر کسب و کار (از جمله شما)', 'ابزار تصمیم گیری برای هر کسب و کار (از جمله شما)', 24, 8, 'book', 't', '<p><em>گرید </em>(2017) مجموعه‌ای از عوامل را شناسایی می‌کند که می‌توانند باعث ایجاد یا شکست کسب‌وکار شوند. این چشمک‌ها که ریشه در رویکردی جامع دارند، به شما کمک می‌کنند تا ایده‌های تجاری را ارزیابی کنید، تأثیر تصمیم‌هایتان را پیش‌بینی کنید و از تغییرات در بازار استفاده کنید. این اصول را در شرکت خود به کار ببرید و به جای درمان ساده علائم، می توانید علل واقعی مشکلات را شناسایی کنید. </p>', '2020-06-13 00:00:00', 4, 120, 'https://images.blinkist.io/images/books/5ee007c16cee070006be04f1/1_1/470.jpg', '/en/books/the-grid-en-matt-watkinson/purchase', 'شبکه', '2023-01-26 18:57:32.572711', '2023-01-26 18:57:32.572711', NULL, 'The Grid');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (112, 'برای موجودات کوچکی مانند ما', 'آیین‌هایی برای یافتن معنا در دنیای بعید ما', 'آیین‌هایی برای یافتن معنا در دنیای بعید ما', 23, 8, 'book', 't', '<p><em>برای موجودات کوچکی مانند ما </em>(2019) یک کتاب راهنما برای کسانی است که به دنبال جشن گرفتن نقاط عطف زندگی - هم شاد و هم دردناک - در یک زمینه غیر مذهبی هستند. نویسنده ساشا ساگان، با کاوش در مراسم سنتی از طریق دریچه‌ای علمی، از افراد سکولار دعوت می‌کند تا آیین‌های معنادار خود را توسعه دهند که شگفتی ایجاد می‌کند و راحتی را فراهم می‌کند.</p>', '2019-12-13 00:00:00', 4, 76, 'https://images.blinkist.io/images/books/5df2128e6cee0700089be5ea/1_1/470.jpg', '/en/books/for-small-creatures-such-as-we-en/purchase', 'برای-موجودات-کوچکی-مانند-ما', '2023-01-26 18:57:37.845308', '2023-01-26 18:57:37.845308', NULL, 'For Small Creatures Such as We');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (113, 'مشکل شروع سرد', 'نحوه شروع و مقیاس افکت های شبکه', 'نحوه شروع و مقیاس افکت های شبکه', 20, 6, 'book', 't', '<p><em>مشکل شروع سرد </em>(2021) توضیح می دهد که اثرات شبکه چیست، چگونه در عمل کار می کنند، در حالی که آنها را با نمونه های دنیای واقعی از شرکت هایی مانند Zoom، Airbnb و Uber نشان می دهد. از راه اندازی شرکت های فناوری در قرن بیست و یکم، تا پویایی جمعیت مریکات، <em>مشکل شروع سرد </em>نگاهی عمیق به نحوه توسعه و تعامل شبکه ها با یکدیگر است.</p >', '2022-04-12 00:00:00', 4, 162, 'https://images.blinkist.io/images/books/6253eb766cee070008dbe6a4/1_1/470.jpg', '/en/books/the-cold-start-problem-en/purchase', 'مشکل-شروع-سرد', '2023-01-26 18:57:43.377378', '2023-01-26 18:57:43.377378', NULL, 'The Cold Start Problem');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (114, 'همه شادی و بدون سرگرمی', 'پارادوکس والدین مدرن', 'پارادوکس والدین مدرن', 15, 6, 'book', 't', '<p><em>همه شادی و بدون سرگرمی</em> (2014) کتابی است درباره آزمایش‌ها و مصیبت‌های بزرگ کردن بچه‌ها. Senior چالش های فرزندپروری را بررسی می کند و در عین حال ما را از لذت ها و پاداش های ناشی از آن آگاه می کند.</p>', '2015-04-29 00:00:00', 4, 17, 'https://images.blinkist.io/images/books/553fba136136310007410000/1_1/470.jpg', '/en/books/all-joy-and-no-fun-en/purchase', 'همه-شادی-و-بدون-سرگرمی', '2023-01-26 18:57:48.593104', '2023-01-26 18:57:48.593104', NULL, 'All Joy and no Fun');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (359, 'چگونه یک Bawse باشیم', 'راهنمای تسخیر زندگی', 'راهنمای تسخیر زندگی', 18, 8, 'book', 't', '<p><em>How to Be a Bawse (2017)</em> بینش های عمده ای در مورد چگونگی دستیابی به موفقیت در زندگی ارائه می دهد. لیلی سینگ، محبوب YouTube، با تکیه بر دانش دست اول از رسیدن به ستاره شدن، موضوعاتی مانند انگیزه و نظم را پوشش می دهد و آنها را با حکایات شخصی و نکات عملی کامل می کند.</p>', '2018-03-02 00:00:00', 4, 32, 'https://images.blinkist.io/images/books/5a968b0bb238e10008828405/1_1/470.jpg', '/en/books/how-to-be-a-bawse-en/purchase', 'چگونه-یک-Bawse-باشیم', '2023-01-26 19:28:09.103228', '2023-01-26 19:28:09.103228', NULL, 'How to Be a Bawse');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (115, '6 نوع نابغه کاری', 'راهی بهتر برای درک هدایای خود، ناامیدی‌ها و تیمتان', 'راهی بهتر برای درک هدایای خود، ناامیدی‌ها و تیمتان', 12, 6, 'book', 't', '<p><em>6 نوع نابغه کاری</em> (2022) یک راهنمای روشنگر برای تطبیق استعداد مناسب با کار مناسب در محل کار است. همچنین نشان می‌دهد که چگونه می‌توانید روابط خود را با همکاران خود ارتقا دهید - و راه‌های مشخصی برای تبدیل سازمان شما به مکانی ارائه می‌دهد که مردم می‌خواهند در آن کار کنند.</p>', '2022-11-21 00:00:00', 4, 279, 'https://images.blinkist.io/images/books/6374a4bd6ac3e6000813d948/1_1/470.jpg', '/en/books/the-6-types-of-working-genius-en/purchase', '6-نوع-نابغه-کاری', '2023-01-26 18:57:53.350261', '2023-01-26 18:57:53.350261', NULL, 'The 6 Types of Working Genius');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (116, 'جمعه به جلو', 'الهام و انگیزه برای پایان دادن به هفته خود قویتر از آنچه شروع شده است', 'الهام و انگیزه برای پایان دادن به هفته خود قویتر از آنچه شروع شده است', 21, 8, 'book', 't', '<p><em>جمعه به پیش </em>(2020)، درست مانند خبرنامه موفق نویسنده رابرت گلیزر با همین نام، مملو از داستان‌های الهام‌بخش و استراتژی‌های هوشمند است که شما را برای رسیدن به پتانسیل کامل خود سوق می‌دهند. رویکرد منحصربه‌فرد «چهار ظرفیت» گلیزر، چیستی‌ها، چرایی‌ها و روش‌های شناسایی و عمل به رویاهای شما را تجزیه می‌کند.</p>', '2020-09-08 00:00:00', 5, 165, 'https://images.blinkist.io/images/books/5f5263fb6cee07000608478f/1_1/470.jpg', '/en/books/friday-forward-en/purchase', 'جمعه-به-جلو', '2023-01-26 18:57:58.660246', '2023-01-26 18:57:58.660246', NULL, 'Friday Forward');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (117, 'آزمایشگاه رهبری', 'درک رهبری در قرن بیست و یکم', 'درک رهبری در قرن بیست و یکم', 21, 7, 'book', 't', '<p><em>آزمایشگاه رهبری (2018)</em> نگاهی به تغییرات کلیدی در قرن ما، تأثیرات مثبت و منفی آنها، و نحوه هدایت رهبران در آنها می‌اندازد. پلک‌های <em>آزمایشگاه رهبری</em> همچنین به رهبران راهنمایی می‌کند که چگونه به طور مؤثر ارتباط برقرار کنند، کارایی تیم‌ها را به حداکثر برسانند و مشارکت را تشویق کنند، و همچنین نحوه نشان دادن صبر و شکیبایی و تقویت اعتماد.</p>', '2020-06-24 00:00:00', 4, 27, 'https://images.blinkist.io/images/books/5eec93f46cee0700064eb356/1_1/470.jpg', '/en/books/the-leadership-lab-en/purchase', 'آزمایشگاه-رهبری', '2023-01-26 18:58:03.628673', '2023-01-26 18:58:03.628673', NULL, 'The Leadership Lab');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (118, 'کار مهربان را انجام دهید', 'بی حد و حصر فکر کن، هدفمند کار کن، عاشقانه زندگی کن', 'بی حد و حصر فکر کن، هدفمند کار کن، عاشقانه زندگی کن', 15, 7, 'book', 't', '<p><em>کار مهربان را انجام دهید</em> (2015) درس‌های ارزشمندی را که نویسنده در هنگام ساختن برند موفق و اخلاقی خود آموخته است، ارائه می‌کند. این پلک ها شما را از طریق ده اصل اساسی ایجاد کسب و کاری راهنمایی می کند که به نفع فرد و جهان باشد و همچنین موفق باشد.</p>', '2015-07-15 00:00:00', 4, 15, 'https://images.blinkist.io/images/books/55a38f5b37386100078a0000/1_1/470.jpg', '/en/books/do-the-kind-thing-en/purchase', 'کار-مهربان-را-انجام-دهید', '2023-01-26 18:58:08.709164', '2023-01-26 18:58:08.709164', NULL, 'Do the KIND Thing');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (119, 'برنامه بازاریابی یک هفته ای', 'رویکرد تنظیم و فراموش کردن آن برای رشد سریع کسب و کار شما', 'رویکرد تنظیم و فراموش کردن آن برای رشد سریع کسب و کار شما', 19, 8, 'book', 't', '<p>بسیاری از مردم فکر می کنند که بازاریابی دشوار است، به زمان زیادی نیاز دارد، مقدار زیادی پول و ارتباطات قدرتمند زیادی نیاز دارد، اما <em>برنامه بازاریابی یک هفته ای</em> (2014) این افسانه را از بین می برد. این پلک ها خواننده را در فرآیند ساخت یک استراتژی بازاریابی سفارشی، ارزان و قدرتمند برای عصر اطلاعات راهنمایی می کند.</p>', '2015-08-20 00:00:00', 4, 46, 'https://images.blinkist.io/images/books/55d0fc75688f67000900007f/1_1/470.jpg', '/en/books/the-one-week-marketing-plan-en/purchase', 'برنامه-بازاریابی-یک-هفته-ای', '2023-01-26 18:58:13.413717', '2023-01-26 18:58:13.413717', NULL, 'The One Week Marketing Plan');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (120, 'تعصب جنسیتی را شکست دهید', 'چگونه در دنیایی فراگیرتر نقش بهتری ایفا کنیم', 'چگونه در دنیایی فراگیرتر نقش بهتری ایفا کنیم', 17, 6, 'book', 't', '<p><em>Beat Gender Bias</em> (2020)<em></em>باورها و رفتارهایی را بررسی می‌کند که زیربنای سقف شیشه‌ای است و زنان و دختران را از دستیابی به پتانسیل کامل خود باز می‌دارد. این تداوم جنسیت گرایی در محل کار را بررسی می کند و توضیح می دهد که چگونه رهبران می توانند با آن مقابله کنند.</p>', '2022-04-15 00:00:00', 4, 112, 'https://images.blinkist.io/images/books/625408da6cee070008f338f9/1_1/470.jpg', '/en/books/beat-gender-bias-en/purchase', 'تعصب-جنسیتی-را-شکست-دهید', '2023-01-26 18:58:18.57624', '2023-01-26 18:58:18.57624', NULL, 'Beat Gender Bias');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (121, 'سافاری استراتژی', 'یک تور با راهنما از طریق طبیعت مدیریت استراتژیک', 'یک تور با راهنما از طریق طبیعت مدیریت استراتژیک', 25, 11, 'book', 't', '<p><em>Strategy Safari </em>راهنمای جامعی برای شکل‌گیری استراتژی است که با خلاصه‌ای از تمام مکاتب فکری اصلی آن کامل شده است. با توضیح نقاط قوت و محدودیت های اولیه هر مدرسه، <em>Strategy Safari </em>ابزارهایی را در اختیار شما قرار می دهد تا استراتژی مناسب برای کسب و کار خود را شکل دهید.</p>', '2015-02-20 00:00:00', 4, 53, 'https://images.blinkist.io/images/books/54e3d909303764000ad80000/1_1/470.jpg', '/en/books/strategy-safari-en/purchase', 'سافاری-استراتژی', '2023-01-26 18:58:23.818265', '2023-01-26 18:58:23.818265', NULL, 'Strategy Safari');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (142, 'رویای برندگان', 'سفری از فروشگاه گوشه تا دفتر گوشه', 'سفری از فروشگاه گوشه تا دفتر گوشه', 15, 8, 'book', 'f', '<p><em>Winners Dream</em> راهنمای دستیابی به اهداف خود را با پیروی از زندگی و الگوی بیل مک درموت، مدیر عامل فعلی SAP، بزرگترین شرکت نرم افزاری در جهان، ارائه می دهد. با شناسایی رویای برنده خود، می توانید انگیزه ای برای غلبه بر همه موانع سر راه خود پیدا کنید و به دیگران در این راه کمک کنید.</p>', '2015-03-02 00:00:00', NULL, 9, 'https://images.blinkist.io/images/books/54f442e6333035000a040000/1_1/470.jpg', '/en/books/winners-dream-en/purchase', 'رویای-برندگان', '2023-01-26 19:00:14.873505', '2023-01-26 19:00:14.873505', NULL, 'Winners Dream');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (122, 'در مورد منشاء گونه ها', 'با استفاده از انتخاب طبیعی، یا حفظ نژادهای مورد علاقه در مبارزه برای زندگی', 'با استفاده از انتخاب طبیعی، یا حفظ نژادهای مورد علاقه در مبارزه برای زندگی', 23, 10, 'book', 't', '<p><em>منشاء گونه ها </em> (1859) اثر بزرگ چارلز داروین است. این چشمک‌ها نظریه‌ای را در مورد چگونگی انتخاب ویژگی‌ها توسط طبیعت، از کجا نشات گرفته از تنوع فوق‌العاده حیات روی زمین و نحوه توزیع حیوانات و گیاهان در سراسر سیاره نشان می‌دهد.</p>', '2017-03-23 00:00:00', 5, 83, 'https://images.blinkist.io/images/books/58d12bb7ed3a570004158175/1_1/470.jpg', '/en/books/on-the-origin-of-species-en/purchase', 'در-مورد-منشاء-گونه-ها', '2023-01-26 18:58:28.485303', '2023-01-26 18:58:28.485303', NULL, 'On the Origin of Species');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (123, 'تسلا', 'مرد خارج از زمان', 'مرد خارج از زمان', 22, 10, 'book', 't', '<p><em>تسلا</em> (1981) گزارشی روشنگر و صمیمی از زندگی و دستاوردهای یکی از مخترع ترین و مبتکرترین مخترعان تاریخ ارائه می دهد. این پلک‌ها زندگی حرفه‌ای نیکولا تسلا را از نبردهای اولیه‌اش با توماس ادیسون تا بحث جنجالی بر سر اختراع ارتباطات رادیویی نشان می‌دهند.</p>', '2016-02-15 00:00:00', 5, 83, 'https://images.blinkist.io/images/books/56c1d105587c82000700001a/1_1/470.jpg', '/en/books/tesla-en/purchase', 'تسلا', '2023-01-26 18:58:34.016457', '2023-01-26 18:58:34.016457', NULL, 'Tesla');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (124, 'قبل از خوشبختی', '5 کلید پنهان برای دستیابی به موفقیت، گسترش شادی و تداوم تغییرات مثبت', '5 کلید پنهان برای دستیابی به موفقیت، گسترش شادی و تداوم تغییرات مثبت', 24, 8, 'book', 't', '<p><em>پیش از شادی </em>(2013) یک راهنمای خودیاری با پیچ و تاب است. این یک راه طلایی برای خوشبختی و موفقیت ایجاد نمی کند. در عوض، آنچه را که ما باید قبل از رسیدن به این چیزها داشته باشیم بررسی می کند. پاسخ چیزی کمتر از یک انقلاب در نحوه نگرش ما به واقعیت و رویکرد به چالش های زندگی مان نیست. </p>', '2021-04-08 00:00:00', 5, 159, 'https://images.blinkist.io/images/books/60648e3f6cee0700070180fe/1_1/470.jpg', '/en/books/before-happiness-en/purchase', 'قبل-از-خوشبختی', '2023-01-26 18:58:39.193839', '2023-01-26 18:58:39.193839', NULL, 'Before Happiness');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (125, 'آشپزی یک تجارت', 'درس هایی از عاشقان غذا که شور و شوق خود را به شغل تبدیل کردند و چگونه شما نیز می توانید', 'درس هایی از عاشقان غذا که شور و شوق خود را به شغل تبدیل کردند و چگونه شما نیز می توانید', 14, 6, 'book', 't', '<p><em>آشپزی برای کسب و کار</em> (2013) خواندن انگیزشی ضروری برای هر کارآفرینی است که اهل غذا است. چه در حال آزمایش آب با یک محصول جدید باشید یا به دنبال احیای استراتژی شرکت خود باشید، این پلک ها راهنمایی همراه با داستان های واقعی از کارآفرینان پیشرو را به شما ارائه می دهند.</p>', '2016-01-15 00:00:00', NULL, 7, 'https://images.blinkist.io/images/books/5694b4ca2f68270007000036/1_1/470.jpg', '/en/books/cooking-up-a-business-en/purchase', 'آشپزی-یک-تجارت', '2023-01-26 18:58:44.32929', '2023-01-26 18:58:44.32929', NULL, 'Cooking Up a Business');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (126, 'وسواس داشته باشید یا متوسط ​​باشید', 'یک زنگ بیداری جسورانه و متضاد برای هر کسی که واقعاً برای موفقیت آماده است', 'یک زنگ بیداری جسورانه و متضاد برای هر کسی که واقعاً برای موفقیت آماده است', 16, 7, 'book', 't', '<p><em>وسواس باش یا متوسط ​​باش </em>(2016) راهنمای کامل زندگی کردن است. Cardone دیدگاه منحصر به فرد خود را برای تبدیل شدن به یک رهبر تجاری با انگیزه و پرشور با گرسنگی لازم برای رتبه بندی در بین بهترین ها در جهان ارائه می دهد.</p>', '2018-02-05 00:00:00', 4, 137, 'https://images.blinkist.io/images/books/5a74f698b238e10006541187/1_1/470.jpg', '/en/books/be-obsessed-or-be-average-en/purchase', 'وسواس-داشته-باشید-یا-متوسط-​​باشید', '2023-01-26 18:58:49.147117', '2023-01-26 18:58:49.147117', NULL, 'Be Obsessed or Be Average');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (127, 'سفر فراتر از ترس', 'از سه ستون مثبت برای ساختن موفقیت خود استفاده کنید', 'از سه ستون مثبت برای ساختن موفقیت خود استفاده کنید', 20, 5, 'book', 't', '<p><em>سفر فراتر از ترس</em> (2021) راهنمای غلبه بر ترس و دستیابی به پتانسیل کامل است. هیگل در طول 40 سال فعالیت خود در سیلیکون ولی، سه ابزار عملی را شناسایی کرده است که هر کسی می تواند از آنها بهره مند شود. در اینجا، او دقیقاً نحوه استفاده از آنها را توضیح می دهد تا بتوانید از فرصت های جدید هیجان انگیز در زندگی حرفه ای و شخصی خود نهایت استفاده را ببرید.</p>', '2022-06-27 00:00:00', 4, 279, 'https://images.blinkist.io/images/books/62b454bf6cee070008d3bf72/1_1/470.jpg', '/en/books/the-journey-beyond-fear-en/purchase', 'سفر-فراتر-از-ترس', '2023-01-26 18:58:54.233919', '2023-01-26 18:58:54.233919', NULL, 'The Journey Beyond Fear');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (128, 'هیچ برنامه ریزی کوچکی نداشته باشید', 'درس هایی درباره بزرگ اندیشی، تعقیب رویاها و ایجاد جامعه', 'درس هایی درباره بزرگ اندیشی، تعقیب رویاها و ایجاد جامعه', 22, 5, 'book', 't', '<p><em>برنامه‌های کوچک نسازید </em>(2022) داستان درونی این است که چگونه گروهی از کارآفرینان جوان یکی از هیجان‌انگیزترین پلت‌فرم‌های جهان را برای رویدادها و کنفرانس‌های جهانی ایجاد کردند - Summit Series. اگرچه این فقط فرصتی برای آنها نیست که تاریخچه شرکت خود را بازگو کنند. مملو از نکات قابل اجرا و خرد تجاری، این کتاب برای الهام بخشیدن به خوانندگان در سفرهای کارآفرینی خود طراحی شده است.</p>', '2022-06-06 00:00:00', 4, 273, 'https://images.blinkist.io/images/books/6298833f6cee070008553a61/1_1/470.jpg', '/en/books/make-no-small-plans-en/purchase', 'هیچ-برنامه-ریزی-کوچکی-نداشته-باشید', '2023-01-26 18:58:59.047668', '2023-01-26 18:58:59.047668', NULL, 'Make No Small Plans');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (150, 'کشش', 'کسب و کار خود را کنترل کنید', 'کسب و کار خود را کنترل کنید', 14, 6, 'book', 't', '<p><em>کشش</em> راهنمای شما برای اداره یک تجارت قوی و پر رونق است. این پلک ها توضیح می دهند که چگونه ابزار ارزشمندی به نام سیستم عامل کارآفرینی (EOS) کار می کند و چگونه می توانید از آن برای ایجاد کسب و کار خود استفاده کنید.</p>', '2017-02-08 00:00:00', 4, 202, 'https://images.blinkist.io/images/books/58950b020be35600040371c4/1_1/470.jpg', '/en/books/traction-en-gino-wickman/purchase', 'کشش', '2023-01-26 19:00:59.439496', '2023-01-26 19:00:59.439496', NULL, 'Traction');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (129, 'سال 12 هفته', 'در 12 هفته بیشتر از دیگران در 12 ماه انجام دهید', 'در 12 هفته بیشتر از دیگران در 12 ماه انجام دهید', 21, 8, 'book', 't', '<p><em>سال 12 هفته</em> (2013) طرحی را برای تغییر برنامه ریزی، تحویل و بهره وری شما ارائه می دهد. بسیاری از افراد، سازمان‌ها و کسب‌وکارها حول یک چرخه سالانه برنامه‌ریزی می‌کنند، اما تقریباً غیرممکن است که برنامه‌ریزی دقیق برای یک سال کامل انجام دهیم، و به همان اندازه سخت است که تمرکز یک سال را به خود اختصاص دهیم. این کتاب جایگزینی را ارائه می‌دهد که نحوه برنامه‌ریزی برای یک دوره 12 هفته‌ای، اجرای وظایف حیاتی و بهبود اساسی نتایج را توضیح می‌دهد.</p>', '2018-04-26 00:00:00', 5, 222, 'https://images.blinkist.io/images/books/5ade2b8ab238e10007bda180/1_1/470.jpg', '/en/books/the-12-week-year-en/purchase', 'سال-12-هفته', '2023-01-26 18:59:04.218519', '2023-01-26 18:59:04.218519', NULL, 'The 12 Week Year');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (130, 'احاطه شده توسط شکست', 'تبدیل موانع به موفقیت (وقتی همه چیز به جهنم می رود)', 'تبدیل موانع به موفقیت (وقتی همه چیز به جهنم می رود)', 20, 7, 'book', 't', '<p><em>در محاصره شکست‌ها </em>(2021) یک راهنمای عملی برای دستیابی به اهدافتان علیرغم موانعی است که به‌طور اجتناب‌ناپذیر در این راه با آنها روبرو خواهید شد. همه ما در زندگی خود با شکست مواجه می شویم. برخی از آنها جزئی و قابل تعمیر خواهند بود، در حالی که برخی دیگر کاملاً خارج از کنترل ما خواهند بود. اما با یادگیری مدیریت پاسخ‌های خود به انواع ناملایمات، با پذیرفتن مسئولیت کامل زندگی‌تان، و سرسختانه در رویکرد خود، می‌توانید به رویاهای خود برسید.</p>', '2022-01-31 00:00:00', 5, 298, 'https://images.blinkist.io/images/books/61f005996cee070009169c72/1_1/470.jpg', '/en/books/surrounded-by-setbacks-en/purchase', 'احاطه-شده-توسط-شکست', '2023-01-26 18:59:09.949135', '2023-01-26 18:59:09.949135', NULL, 'Surrounded by Setbacks');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (131, 'طرز فکر مبادله', 'چارچوبی که عمدتاً فراموش شده برای تسلط بر مذاکره بعدی', 'چارچوبی که عمدتاً فراموش شده برای تسلط بر مذاکره بعدی', 18, 7, 'book', 't', '<p><em>ذهنیت مبادله ای </em>(2019) روشی را برای مذاکره شرح می دهد که مجموعه ذهنی اقتصادهای مبادله ای گذشته را که در آن مردم کالاها و خدمات را برای به دست آوردن آنچه مورد نیاز خود مبادله می کردند، به پول امروزی اعمال می کند. اقتصاد. با تجزیه ذهنیت مبادله ای به یک فرآیند پنج مرحله ای، این پلک زدن ها به شما کمک می کند رویکرد پیچیده تری برای مذاکره ایجاد کنید.</p>', '2019-07-10 00:00:00', 4, 60, 'https://images.blinkist.io/images/books/5d211e426cee07000704d9d8/1_1/470.jpg', '/en/books/the-bartering-mindset-en/purchase', 'طرز-فکر-مبادله', '2023-01-26 18:59:14.611245', '2023-01-26 18:59:14.611245', NULL, 'The Bartering Mindset');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (132, 'بهترین شغل همیشه', 'در حرفه خود تجدید نظر کنید، ثروتمند را دوباره تعریف کنید، زندگی خود را متحول کنید', 'در حرفه خود تجدید نظر کنید، ثروتمند را دوباره تعریف کنید، زندگی خود را متحول کنید', 12, 5, 'book', 't', '<p><em>بهترین شغل همیشه</em> (2016) راهنمای ایجاد تغییر شغلی است که برای خوشحالی از زندگی حرفه ای خود به آن نیاز دارید. این پلک‌ها شما را در فرآیند دشوار تغییر شغل، تغییر رشته و امتحان کردن کاری که همیشه می‌خواستید انجام دهید، اما نمی‌دانستید چگونه شروع کنید، راهنمایی می‌کند.</p>', '2017-01-30 00:00:00', 4, 29, 'https://images.blinkist.io/images/books/588d15541a56850004e76d92/1_1/470.jpg', '/en/books/best-job-ever-en/purchase', 'بهترین-شغل-همیشه', '2023-01-26 18:59:19.695743', '2023-01-26 18:59:19.695743', NULL, 'Best Job Ever');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (133, 'شخصیت شامل نمی شود', 'چرا شرکت ها اصالت خود را از دست می دهند و چگونه مارک های بزرگ آن را پس می گیرند؟', 'چرا شرکت ها اصالت خود را از دست می دهند و چگونه مارک های بزرگ آن را پس می گیرند؟', 15, 7, 'book', 't', '<p><em>شخصیت گنجانده نشده است</em> (2008) توضیح می دهد که چگونه یک چهره عمومی عالی برای شرکت خود بسازید. این پلک ها به شما می آموزند که چگونه شخصیتی قوی برای کسب و کار خود ایجاد کنید، توضیح می دهد که چرا این بسیار مهم است و به شما کمک می کند موانع بین خود و موفقیت کسب و کار را برطرف کنید.</p>', '2017-06-27 00:00:00', 4, 14, 'https://images.blinkist.io/images/books/594efa76b238e10005bb48c9/1_1/470.jpg', '/en/books/personality-not-included-en/purchase', 'شخصیت-شامل-نمی-شود', '2023-01-26 18:59:24.410387', '2023-01-26 18:59:24.410387', NULL, 'Personality Not Included');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (134, 'گیمیفیکیشن برای کسب و کار', 'چرا مبتکران و تغییر دهندگان از بازی ها برای شکستن سیلوها، ایجاد تعامل و ایجاد اعتماد استفاده می کنند', 'چرا مبتکران و تغییر دهندگان از بازی ها برای شکستن سیلوها، ایجاد تعامل و ایجاد اعتماد استفاده می کنند', 20, 7, 'book', 't', '<p><em>Gamification for Business</em> (2018) به بررسی این موضوع می‌پردازد که چگونه کسب‌وکارها می‌توانند از بازی‌ها برای غلبه بر چالش‌های سازمانی و بهینه‌سازی عملکرد استفاده کنند. Sune Gudiksen و Jake Inlove با تکیه بر تجربه گسترده خود در طراحی و نوآوری بازی، نشان می‌دهند که چگونه می‌توان از بازی‌ها برای تشویق کار تیمی، تقویت انگیزه کارکنان و ترسیم مسیرهای جدید برای پیشرفت و تغییر استفاده کرد. </p>', '2020-03-19 00:00:00', 4, 71, 'https://images.blinkist.io/images/books/5e70d0d96cee070006c42c21/1_1/470.jpg', '/en/books/gamification-for-business-en/purchase', 'گیمیفیکیشن-برای-کسب-و-کار', '2023-01-26 18:59:29.895198', '2023-01-26 18:59:29.895198', NULL, 'Gamification for Business');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (488, 'عامل اجرا', 'تنها مهارتی که باعث موفقیت می شود', 'تنها مهارتی که باعث موفقیت می شود', 29, 11, 'book', 't', '<p><em>عامل اجرا</em> (2018) پنج ویژگی مشترک افرادی را که می‌دانند چگونه رویاها و اهداف خود را به طور مؤثر انجام دهند، شناسایی می‌کند. کیم پرل با به اشتراک گذاشتن اصول کلی و نکات خاص در مورد نحوه پرورش آنها، نشان می دهد که چگونه خود را به چنین فردی تبدیل کنید.</p>', '2018-12-11 00:00:00', 5, 50, 'https://images.blinkist.io/images/books/5c0d9ca36cee0700076a0454/1_1/470.jpg', '/en/books/the-execution-factor-en/purchase', 'عامل-اجرا', '2023-01-26 19:39:20.209171', '2023-01-26 19:39:20.209171', NULL, 'The Execution Factor');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (135, 'قدرت تمرکز', 'چگونه با اطمینان مطلق به اهداف تجاری، شخصی و مالی خود برسید', 'چگونه با اطمینان مطلق به اهداف تجاری، شخصی و مالی خود برسید', 22, 7, 'book', 't', '<p><em>قدرت تمرکز</em>(2001) ابزارهایی را در اختیار خوانندگان قرار می دهد تا زندگی و کار خود را در جهتی متمرکز کنند که هدف زندگی آنها را برآورده کند و موفقیت مالی را برای سرمایه گذاری های تجاری آنها به ارمغان بیاورد. مملو از تمرین‌های عملی، نویسندگان اهمیت عادات موفق، غلبه بر موانع، حفظ روابط برد-برد، و پرسیدن سؤالات درست را نشان می‌دهند.</p>', '2021-09-06 00:00:00', 4, 287, 'https://images.blinkist.io/images/books/613081d96cee070008bb9cd4/1_1/470.jpg', '/en/books/the-power-of-focus-en/purchase', 'قدرت-تمرکز', '2023-01-26 18:59:34.886642', '2023-01-26 18:59:34.886642', NULL, 'The Power of Focus');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (136, 'مهم ترین چیز', 'عقل غیرمعمول برای سرمایه گذار متفکر', 'عقل غیرمعمول برای سرمایه گذار متفکر', 17, 8, 'book', 't', '<p>در <em>مهم‌ترین چیز</em>، هاوارد مارکس فلسفه سرمایه‌گذاری گاهی بحث‌برانگیز را که از طریق سال‌ها تجربه بازار توسعه داده و به آن ارتقا داده است، تشریح می‌کند. به نظر او، سرمایه گذاری موفق مستلزم آن است که به بسیاری از جنبه های مختلف بازار فعلی توجه دقیق داشته باشیم و اغلب از این اطلاعات برای مقابله با روندهای غالب استفاده کنیم.</p>', '2014-10-27 00:00:00', 4, 123, 'https://images.blinkist.io/images/books/544cd0596563320008000000/1_1/470.jpg', '/en/books/the-most-important-thing-en/purchase', 'مهم-ترین-چیز', '2023-01-26 18:59:39.995312', '2023-01-26 18:59:39.995312', NULL, 'The Most Important Thing');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (137, 'مردی که دنیا را تغذیه کرد', 'نورمن بورلاگ برنده جایزه صلح نوبل و نبرد او برای پایان دادن به گرسنگی در جهان', 'نورمن بورلاگ برنده جایزه صلح نوبل و نبرد او برای پایان دادن به گرسنگی در جهان', 21, 9, 'book', 't', '<p><em></em> <em>مرد</em> <em>که</em> <em>غذا</em> <em></em> <em>جهان</em > داستان نورمن بورلاگ، برنده جایزه صلح نوبل، و کار او در مبارزه با گرسنگی در جهان را روایت می کند. گذشته و آینده کشاورزی جهان و گرسنگی مورد بررسی قرار می گیرد.</p>', '2014-08-19 00:00:00', 5, 12, 'https://images.blinkist.io/images/books/53f460d53433390008350000/1_1/470.jpg', '/en/books/the-man-who-fed-the-world-en/purchase', 'مردی-که-دنیا-را-تغذیه-کرد', '2023-01-26 18:59:45.124693', '2023-01-26 18:59:45.124693', NULL, 'The Man Who Fed the World');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (138, 'کلمه به کلمه', 'زندگی مخفی دیکشنری ها', 'زندگی مخفی دیکشنری ها', 20, 8, 'book', 't', '<p><em>Word by Word </em>(2017) درباره یک شی و حرفه مرتبط با آن است که مردم به ندرت از فکری برای آن صرف نظر می کنند: فرهنگ لغت و شغل شریف فرهنگ نویسی. کوری استمپر دنیای شگفت‌انگیز طبقه‌بندی کلمات را از طریق تجربه خود در Merriam-Webster معرفی می‌کند و نشان می‌دهد که فرهنگ‌های لغت چه کاری می‌توانند انجام دهند و مهمتر از همه، چه کارهایی را انجام نمی‌دهند.</p>', '2018-02-13 00:00:00', NULL, 9, 'https://images.blinkist.io/images/books/5a80e500b238e100072f701d/1_1/470.jpg', '/en/books/word-by-word-en/purchase', 'کلمه-به-کلمه', '2023-01-26 18:59:50.442242', '2023-01-26 18:59:50.442242', NULL, 'Word by Word');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (139, 'پایان های ضروری', 'کارمندان، مشاغل و روابطی که همه ما برای حرکت رو به جلو باید آنها را رها کنیم', 'کارمندان، مشاغل و روابطی که همه ما برای حرکت رو به جلو باید آنها را رها کنیم', 13, 6, 'book', 't', '<p><em>پایان‌های ضروری </em>(2010) به پایان‌ها می‌پردازد و اینکه چرا گاهی اوقات بهتر است برخی از روابط تجاری یا شخصی به پایان برسد. چه در زندگی کاری و چه در زندگی خصوصی، اگر می‌خواهیم رشد کنیم و رویاهایمان را محقق کنیم، پایان‌ها ضروری هستند. اما پایان دادن به ندرت - اگر هرگز - آسان است. این کتاب در چشمک‌ها توصیه‌های خوبی در مورد نحوه مهندسی آنها به نفع خود ارائه می‌دهد.</p>', '2017-10-06 00:00:00', 4, 57, 'https://images.blinkist.io/images/books/59d5f601b238e10006d63752/1_1/470.jpg', '/en/books/necessary-endings-en/purchase', 'پایان-های-ضروری', '2023-01-26 18:59:56.564264', '2023-01-26 18:59:56.564264', NULL, 'Necessary Endings');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (140, '22 قانون تغییرناپذیر بازاریابی', 'آنها را در معرض خطر خود نقض کنید!', 'آنها را در معرض خطر خود نقض کنید!', 16, 6, 'book', 't', '<p><em>22 قانون تغییرناپذیر بازاریابی </em>(1994) دانش ضروری برای ایجاد استراتژی های بازاریابی قدرتمند را به شما می دهد. با مثال‌های عملی و واقعی، این پلک‌ها به شما نشان می‌دهند که چگونه از اشتباهات رایج اجتناب کنید و در عین حال اطمینان حاصل کنید که فشار بازاریابی شما در برابر سخت‌ترین رقابت‌ها سریع خواهد بود.</p>', '2015-10-21 00:00:00', 4, 89, 'https://images.blinkist.io/images/books/562422ae32646600074d0000/1_1/470.jpg', '/en/books/the-22-immutable-laws-of-marketing-en/purchase', '22-قانون-تغییرناپذیر-بازاریابی', '2023-01-26 19:00:02.949461', '2023-01-26 19:00:02.949461', NULL, 'The 22 Immutable Laws of Marketing');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (141, 'بحران در منطقه یورو', 'ریشه بحران منطقه یورو را درک کنید.', 'ریشه بحران منطقه یورو را درک کنید.', 16, 9, 'book', 'f', '<p>این پلک ها ریشه بحران منطقه یورو را به روشی جامع و روشمند توضیح می دهند. آنها مشکلات ساختاری عمیقی را که منطقه یورو با آن مواجه است روشن می‌کنند و سناریوهایی را ترسیم می‌کنند که می‌تواند به بازگرداندن رقابت در میان کشورهای حاشیه جنوبی منطقه کمک کند.</p>', '2014-10-17 00:00:00', 4, 12, 'https://images.blinkist.io/images/books/543e75243065650008400000/1_1/470.jpg', '/en/books/crisis-in-the-eurozone-en/purchase', 'بحران-در-منطقه-یورو', '2023-01-26 19:00:08.896865', '2023-01-26 19:00:08.896865', NULL, 'Crisis in the Eurozone');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (489, 'مراقبت از پوست', 'راهنمای نهایی بدون مزخرف', 'راهنمای نهایی بدون مزخرف', 21, 8, 'book', 't', '<p><em>مراقبت از پوست </em>(2020) پرایمر عالی برای دستیابی و حفظ پوست خوب است. صرف نظر از سن، بودجه یا نگرانی‌های مراقبت از پوست شما، توصیه‌های بیهوده‌ای را ارائه می‌کند که برای ثابت کردن روال خود و نشان دادن بهترین چهره خود به آن نیاز دارید.</p>', '2020-09-17 00:00:00', 4, 62, 'https://images.blinkist.io/images/books/5f5be34b6cee070006c62e15/1_1/470.jpg', '/en/books/skincare-en/purchase', 'مراقبت-از-پوست', '2023-01-26 19:39:26.13725', '2023-01-26 19:39:26.13725', NULL, 'Skincare');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (143, 'کنجکاو', 'میل به دانستن و اینکه چرا آینده شما به آن بستگی دارد', 'میل به دانستن و اینکه چرا آینده شما به آن بستگی دارد', 19, 9, 'book', 't', '<p><em>کنجکاو</em> همه چیز در مورد یکی از اساسی ترین نیروها برای موفقیت ما و همچنین درک ما از جهان اطراف است: کنجکاوی ما. این کتاب نگاهی منحصربه‌فرد به نحوه عملکرد کنجکاوی، آنچه می‌توانید برای پرورش آن انجام دهید و انواع رفتارهایی که آن را خفه می‌کنند، ارائه می‌دهد.</p>
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (144, 'آن را دریافت کنید', 'پنج گام برای جنسیت، حقوق و موفقیتی که می خواهید', 'پنج گام برای جنسیت، حقوق و موفقیتی که می خواهید', 19, 6, 'book', 't', '<p><em>دریافتش کنید</em> (2020) یک راهنمای یک مرحله ای برای کنترل صدای خود است تا بتوانید با موفقیت در سخت ترین مکالمات زندگی پیمایش کنید. به شما می آموزد که چگونه با اجتناب از تقلب های رایج، بهداشت مکالمه خود را تمیز کنید و به شما نشان می دهد که چگونه بهترین خود را به دیگران نشان دهید. هنگامی که بدانید چگونه مکالمات را به سمت نتایجی که می خواهید هدایت کنید، مطمئناً در عشق، کار و فراتر از آن به موفقیت خواهید رسید.</p>', '2020-12-01 00:00:00', 4, 125, 'https://images.blinkist.io/images/books/5fc0d8906cee070006c0f752/1_1/470.jpg', '/en/books/get-it-en/purchase', 'آن-را-دریافت-کنید', '2023-01-26 19:00:26.587183', '2023-01-26 19:00:26.587183', NULL, 'Get It');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (145, 'جنبه مثبت استرس', 'چرا استرس برای شما خوب است و چگونه در آن خوب شوید؟', 'چرا استرس برای شما خوب است و چگونه در آن خوب شوید؟', 16, 7, 'book', 't', '<p><em>موارد مثبت استرس</em> قدرت نگرش ما را در مقابله با استرس بررسی می کند. این پلک‌ها عملکرد درونی پاسخ‌های بیولوژیکی و روان‌شناختی ما به استرس را توضیح می‌دهند و دیدگاه‌های جدیدی را در مورد اینکه چگونه استرس می‌تواند به رشد ما کمک کند باز می‌کند.</p>', '2015-11-04 00:00:00', 4, 163, 'https://images.blinkist.io/images/books/5637732c62346500075d0000/1_1/470.jpg', '/en/books/the-upside-of-stress-en/purchase', 'جنبه-مثبت-استرس', '2023-01-26 19:00:31.7474', '2023-01-26 19:00:31.7474', NULL, 'The Upside of Stress');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (146, 'برندسازی بین گوش ها', 'استفاده از علوم شناختی برای ایجاد ارتباطات پایدار با مشتری', 'استفاده از علوم شناختی برای ایجاد ارتباطات پایدار با مشتری', 21, 6, 'book', 't', '<p><em>برندینگ بین گوش</em> (2021) به بررسی این موضوع می‌پردازد که چگونه بازاریابان می‌توانند آخرین بینش‌های علمی را در استراتژی برندسازی خود اعمال کنند. این بررسی می‌کند که مغز انسان چگونه به تبلیغات واکنش نشان می‌دهد و چگونه مصرف‌کنندگان واقعاً تصمیم به خرید یا عدم خرید می‌گیرند.</p>', '2022-05-17 00:00:00', 4, 138, 'https://images.blinkist.io/images/books/628243776cee0700081e067e/1_1/470.jpg', '/en/books/branding-between-the-ears-en/purchase', 'برندسازی-بین-گوش-ها', '2023-01-26 19:00:37.733929', '2023-01-26 19:00:37.733929', NULL, 'Branding Between the Ears');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (147, 'نقشه فرهنگ', 'شکستن مرزهای نامرئی تجارت جهانی', 'شکستن مرزهای نامرئی تجارت جهانی', 15, 8, 'book', 'f', '<p><em>نقشه فرهنگ</em> چارچوبی را برای رسیدگی به تفاوت‌های بین فرهنگی در تجارت ارائه می‌کند و چگونگی درک فرهنگ‌های مختلف از جهان را نشان می‌دهد. این به ما کمک می کند تا این تفاوت ها را درک کنیم، و با انجام این کار توانایی ما را برای واکنش به رفتارهای خاصی که ممکن است زمانی عجیب به نظر می رسید، بهبود بخشد. با این دانش، می‌توانیم از سوء تفاهم جلوگیری کنیم و بدون در نظر گرفتن اینکه در کجای جهان هستیم، ارتباطات بدون درگیری را حفظ کنیم.</p>', '2014-10-21 00:00:00', 5, 108, 'https://images.blinkist.io/images/books/54451e1a6161330008550000/1_1/470.jpg', '/en/books/the-culture-map-en/purchase', 'نقشه-فرهنگ', '2023-01-26 19:00:43.433991', '2023-01-26 19:00:43.433991', NULL, 'The Culture Map');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (148, 'مربیگری چالش برانگیز', 'فراتر از مربیگری سنتی برای رویارویی با واقعیت ها', 'فراتر از مربیگری سنتی برای رویارویی با واقعیت ها', 22, 9, 'book', 't', '<p><em>چالش‌انگیز</em> <em>کوچینگ</em> استدلال می‌کند که مربیگری سنتی به دلیل ریشه‌های درمانی آن محدود است. Blakey and Day یک جایگزین بهتر برای محیط کسب و کار قرن بیست و یکم معرفی می کنند: رویکرد FACTS. تاکید آن بر درخواست چالش برانگیز <em>بازخورد</em>، <em>مسئولیت پذیری</em>، <em>شجاع</em> اهداف، <em>تنش</em> و <em>سیستم ها</em> <em>تفکر</em> مشتری را به سمت دستیابی به پتانسیل کامل خود سوق می دهد.</p>', '2014-07-08 00:00:00', 4, 60, 'https://images.blinkist.io/images/books/53bbf86d6165630007020000/1_1/470.jpg', '/en/books/challenging-coaching-en/purchase', 'مربیگری-چالش-برانگیز', '2023-01-26 19:00:48.206538', '2023-01-26 19:00:48.206538', NULL, 'Challenging Coaching');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (149, 'چگونه در قرن بیست و یکم یک ضدسرمایه دار باشیم؟', 'راهنمای استراتژیک عملگرایانه برای ساختن یک سیستم اقتصادی جایگزین', 'راهنمای استراتژیک عملگرایانه برای ساختن یک سیستم اقتصادی جایگزین', 35, 12, 'book', 't', '<p><em>چگونه در قرن بیست و یکم یک ضدسرمایه دار باشیم </em>(۲۰۱۹) هم نقد اخلاقی سرمایه داری و هم یک راهنمای استراتژی عملگرایانه برای ساختن یک سیستم اقتصادی جایگزین است. با اقتباس از چهار دهه کار اریک اولین رایت در جامعه شناسی، توضیح دقیقی از این که چرا سوسیالیسم دموکراتیک هم ممکن و هم مطلوب است، ارائه می دهد.</p>', '2021-02-14 00:00:00', 4, 76, 'https://images.blinkist.io/images/books/601d1a666cee070007e6c13f/1_1/470.jpg', '/en/books/how-to-be-an-anticapitalist-in-the-21st-century-en/purchase', 'چگونه-در-قرن-بیست-و-یکم-یک-ضدسرمایه-دار-باشیم؟', '2023-01-26 19:00:53.933004', '2023-01-26 19:00:53.933004', NULL, 'How to Be an Anticapitalist in the 21st Century');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (151, 'مقیاس', 'قوانین جهانی رشد، نوآوری، پایداری و سرعت زندگی در موجودات، شهرها، اقتصادها و شرکت ها', 'قوانین جهانی رشد، نوآوری، پایداری و سرعت زندگی در موجودات، شهرها، اقتصادها و شرکت ها', 23, 9, 'book', 't', '<p><em>مقیاس</em> (2017) نگاهی اجمالی به دنیای پنهان و جذاب روابط ریاضی است که جهان را به هم گره می زند. پلک‌ها توضیح می‌دهند که چگونه چنین قوانینی همه چیز را از موجودات میکروسکوپی گرفته تا کلان‌شهرهای بین‌المللی را به هم متصل می‌کند و آنچه می‌توانند در مورد رفتار سیستم‌های پیچیده به ما بگویند.</p>', '2017-12-01 00:00:00', 4, 51, 'https://images.blinkist.io/images/books/5a1c0fdfb238e10006529825/1_1/470.jpg', '/en/books/scale-en/purchase', 'مقیاس', '2023-01-26 19:01:04.794859', '2023-01-26 19:01:04.794859', NULL, 'Scale');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (152, 'زندگی بدون پیوند', 'فراتر از مخمصه انسانی', 'فراتر از مخمصه انسانی', 20, 5, 'book', 't', '<p><em>Living Untethered</em>(2022) راهنمای شما برای یافتن خودآگاهی و شادی بی قید و شرط است. راهنمایی عملی برای حرکت فراتر از افکار، احساسات و عواطف شما ارائه می‌کند و به شما کمک می‌کند تا دست از مبارزه بردارید و زندگی را به‌طور کامل تجربه کنید.</p>', '2022-10-27 00:00:00', 4, 228, 'https://images.blinkist.io/images/books/6357a15b42ae0a00093edca8/1_1/470.jpg', '/en/books/living-untethered-en/purchase', 'زندگی-بدون-پیوند', '2023-01-26 19:01:11.282147', '2023-01-26 19:01:11.282147', NULL, 'Living Untethered');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (153, 'دوست داشتن آنچه هست', 'چهار سوالی که می تواند زندگی شما را تغییر دهد', 'چهار سوالی که می تواند زندگی شما را تغییر دهد', 9, 4, 'book', 't', '<p><em>دوست داشتن چیزی که هست</em> (2002) توضیح می‌دهد که چگونه می‌توانید افسردگی را از طریق تمرینی پیشگامانه به نام «کار» غلبه کنید که به شما کمک می‌کند مشکلات را حل کنید، تجزیه و تحلیل کنید و در نهایت بر مشکلات غلبه کنید تا به شادی و آرامش درونی برسید.</em><em> p>', '2015-07-16 00:00:00', 4, 104, 'https://images.blinkist.io/images/books/55a39b583738610007f00000/1_1/470.jpg', '/en/books/loving-what-is-en/purchase', 'دوست-داشتن-آنچه-هست', '2023-01-26 19:01:17.12628', '2023-01-26 19:01:17.12628', NULL, 'Loving What Is');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (154, 'راه طولانی رفته', 'خاطرات یک پسر سرباز', 'خاطرات یک پسر سرباز', 16, 7, 'book', 't', '<p><em>راه طولانی رفته </em>(2007) داستانی است که نشان می‌دهد چگونه نویسنده در دوران یک پسر جوان در سیرالئون، خود را گرفتار یک جنگ داخلی می‌بیند و به عنوان یک کودک سرباز استخدام می‌شود. در طول سفر دلخراش او، در نهایت نجات و بهبودی که از طریق مهربانی و لطف افراد دوست داشتنی هدایت می‌شود، همراه او سفر خواهید کرد.</p>', '2015-12-04 00:00:00', 4, 21, 'https://images.blinkist.io/images/books/565c83b99906750007000076/1_1/470.jpg', '/en/books/a-long-way-gone-en/purchase', 'راه-طولانی-رفته', '2023-01-26 19:01:23.147942', '2023-01-26 19:01:23.147942', NULL, 'A Long Way Gone');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (155, 'اعترافات یک مرد تبلیغاتی', 'توصیه ها و تکنیک هایی برای ساختن امپراتوری های تبلیغاتی از دوران Mad Men', 'توصیه ها و تکنیک هایی برای ساختن امپراتوری های تبلیغاتی از دوران Mad Men', 16, 10, 'book', 'f', '<p><em>اعترافات یک مرد تبلیغاتی</em>(1963) مجموعه ای از توصیه ها و تکنیک ها برای ایجاد کمپین ها و آژانس های تبلیغاتی موفق است. این کتاب که در دوره مردان دیوانه نوشته شده است، هنوز هم در صنعت تبلیغات به عنوان مطالعه ضروری در نظر گرفته می شود، اما همچنین توصیه هایی را برای مدیران مشتاق در هر کسب و کاری ارائه می دهد.</p>', '2013-04-13 00:00:00', 5, 36, 'https://images.blinkist.io/images/books/51274f47e4b0714805cbbe98/1_1/470.jpg', '/en/books/confessions-of-an-advertising-man-en/purchase', 'اعترافات-یک-مرد-تبلیغاتی', '2023-01-26 19:01:27.824486', '2023-01-26 19:01:27.824486', NULL, 'Confessions of an Advertising Man');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (156, 'سازمان بهداشت جهانی', 'روشی برای استخدام', 'روشی برای استخدام', 19, 8, 'book', 't', '<p><em>Who</em> (2008) راهنمای شما برای بزرگ‌ترین مشکلی است که هر رهبر تجاری با آن مواجه است: نحوه استخدام کارکنان شایسته. این پلک‌ها مملو از نکات عملی در مورد چگونگی اطمینان از اینکه شرکت شما دارای منبع ثابتی از نامزدهای ماهر برای انتخاب است و اینکه همه استخدام‌های شما در راستای اهداف شما هستند، هستند.</p>', '2017-11-22 00:00:00', 4, 138, 'https://images.blinkist.io/images/books/5a1408abb238e1000652970b/1_1/470.jpg', '/en/books/who-en/purchase', 'سازمان-بهداشت-جهانی', '2023-01-26 19:01:32.475327', '2023-01-26 19:01:32.475327', NULL, 'Who');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (157, 'آزمایش الکل', 'یک چالش 30 روزه بدون الکل برای قطع عادت های شما و کمک به کنترل شما', 'یک چالش 30 روزه بدون الکل برای قطع عادت های شما و کمک به کنترل شما', 17, 6, 'book', 't', '<p><em>آزمایش الکل </em>(2018) راهنمای عملی شما برای ترک الکل به مدت 30 روز - یا شاید یک عمر است. مملو از نکات علمی و حکایات شخصی، دیدگاه جدیدی در مورد الکل ارائه می دهد و به بررسی این موضوع می پردازد که چرا آن را می نوشیم، واقعاً چه کاری برای ما انجام می دهد، و چگونه می توانیم آن را ترک کنیم.</p>', '2020-12-31 00:00:00', 5, 152, 'https://images.blinkist.io/images/books/5fdb18e16cee07000670aff7/1_1/470.jpg', '/en/books/the-alcohol-experiment-en/purchase', 'آزمایش-الکل', '2023-01-26 19:01:37.241328', '2023-01-26 19:01:37.241328', NULL, 'The Alcohol Experiment');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (158, 'بازگشت به جاه طلبی', 'یک رویکرد رادیکال برای موفقیت، رشد و رفاه شما', 'یک رویکرد رادیکال برای موفقیت، رشد و رفاه شما', 20, 6, 'book', 't', '<p><em>بازگشت به جاه طلبی </em>(2021) یک راهنمای معقول و عملی برای دستیابی به موفقیت و دستیابی به اهدافتان است. بر اساس عادات و استراتژی‌هایی که توسط افراد با عملکرد بالا و قابل توجه به کار می‌رود، بینش‌هایی به دست می‌دهد که می‌توانید بلافاصله در زندگی خود اعمال کنید.</p>', '2021-09-13 00:00:00', 4, 274, 'https://images.blinkist.io/images/books/613db6f76cee070007f35d94/1_1/470.jpg', '/en/books/return-on-ambition-en/purchase', 'بازگشت-به-جاه-طلبی', '2023-01-26 19:01:42.299851', '2023-01-26 19:01:42.299851', NULL, 'Return on Ambition');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (159, 'زیست شناسی باور', 'آزاد کردن قدرت آگاهی، ماده و معجزه', 'آزاد کردن قدرت آگاهی، ماده و معجزه', 20, 10, 'book', 't', '<p><em></em> <em>زیست شناسی</em> <em></em> <em>باور</em> یک تغییر انقلابی در زیست شناسی را توصیف می کند و رویکرد جدیدی را برای ارتباط بین ذهن و ماده لیپتون با استفاده از مثال‌ها و توضیحات به‌راحتی در دسترس، جایگزینی اساسی برای درک ما از تأثیر ژن‌ها در تعیین رفتار و هویت ما ارائه می‌کند.</p>', '2014-07-08 00:00:00', 4, 138, 'https://images.blinkist.io/images/books/53bceba23633360007080000/1_1/470.jpg', '/en/books/the-biology-of-belief-en/purchase', 'زیست-شناسی-باور', '2023-01-26 19:01:47.364487', '2023-01-26 19:01:47.364487', NULL, 'The Biology of Belief');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (160, 'قدرت شروع یک چیز احمقانه', 'چگونه ترس را از بین ببریم، رویاها را محقق کنیم و بدون پشیمانی زندگی کنیم', 'چگونه ترس را از بین ببریم، رویاها را محقق کنیم و بدون پشیمانی زندگی کنیم', 14, 6, 'book', 't', '<p><em>قدرت شروع یک چیز احمقانه </em> توضیح می دهد که چرا در حال حاضر بهترین زمان برای شماست تا ترس های خود را به رختخواب بکشید و رویاهای خود را تعقیب کنید. با نکات مفید در مورد اینکه چگونه می توانید به اهداف خود برسید و از زندگی در پشیمانی جلوگیری کنید، این پلک زدن ها نشان می دهد که چگونه ایده های به ظاهر احمقانه ممکن است در واقع کلید موفقیت و تحقق شما باشند.</p>', '2015-03-20 00:00:00', 4, 38, 'https://images.blinkist.io/images/books/55062e73666365000a8f0000/1_1/470.jpg', '/en/books/the-power-of-starting-something-stupid-en/purchase', 'قدرت-شروع-یک-چیز-احمقانه', '2023-01-26 19:01:52.700991', '2023-01-26 19:01:52.700991', NULL, 'The Power of Starting Something Stupid');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (161, '#دختر دختر', 'داستان دگرگونی سوفیا آموروسو، از ترک تحصیل در دبیرستان به مدیرعاملی یک امپراتوری مد چند میلیون دلاری', 'داستان دگرگونی سوفیا آموروسو، از ترک تحصیل در دبیرستان به مدیرعاملی یک امپراتوری مد چند میلیون دلاری', 17, 8, 'book', 't', '<p>در <em>#GIRLBOSS</em>، نویسنده سوفیا آموروسو داستان تحول خود را از ترک تحصیل در دبیرستان تا مدیر اجرایی یک امپراتوری مد چند میلیون دلاری تعریف می‌کند. چه شروع یک کسب و کار از ابتدا، چه ایجاد یک جامعه قدرتمند یا انتخاب سرمایه گذاران مناسب، Amoruso به شما می گوید که امروز برای یک زن در تجارت چه چیزی لازم است.</p>', '2014-10-30 00:00:00', 4, 48, 'https://images.blinkist.io/images/books/544fce09376133000a2b0000/1_1/470.jpg', '/en/books/number-girlboss-en/purchase', '#دختر-دختر', '2023-01-26 19:01:57.8195', '2023-01-26 19:01:57.8195', NULL, '#GIRLBOSS');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (162, 'منطقه ناراحتی', 'چگونه رهبران گفتگوهای دشوار را به پیشرفت تبدیل می کنند', 'چگونه رهبران گفتگوهای دشوار را به پیشرفت تبدیل می کنند', 13, 6, 'book', 't', '<p><em>منطقه ناراحتی</em> روشی را برای مقابله با مکالمات سخت و ناخوشایندی که همه ما هر از گاهی با آن مواجه می‌شویم تشریح می‌کند. کلید پیمایش موفقیت آمیز آنها این است که واقعاً به آنچه که شخص دیگر می گوید گوش دهید.</p>', '2015-02-09 00:00:00', 4, 64, 'https://images.blinkist.io/images/books/54d88dcb383963000a010000/1_1/470.jpg', '/en/books/the-discomfort-zone-en/purchase', 'منطقه-ناراحتی', '2023-01-26 19:02:03.061318', '2023-01-26 19:02:03.061318', NULL, 'The Discomfort Zone');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (163, 'رهبری با سپاس', 'هشت روش رهبری برای نتایج کسب و کار فوق العاده', 'هشت روش رهبری برای نتایج کسب و کار فوق العاده', 23, 8, 'book', 't', '<p><em>رهبری با قدردانی </em>(2020) ابزار شگفت‌انگیز اما فوق‌العاده قدرتمندی را بررسی می‌کند که رهبران می‌توانند از آن برای افزایش چشمگیر بهره‌وری و انسجام تیم و در عین حال افزایش حفظ کارکنان استفاده کنند. رهبران با یادگیری نحوه ابراز قدردانی به روش‌های معنادار، می‌توانند فرهنگ محل کار را بهبود بخشند، به راه‌حل‌های بهتری دست یابند و بهره‌وری را سر به فلک بکشند. </p>', '2020-05-04 00:00:00', 4, 80, 'https://images.blinkist.io/images/books/5eabfb9d6cee0700060f4cd8/1_1/470.jpg', '/en/books/leading-with-gratitude-en/purchase', 'رهبری-با-سپاس', '2023-01-26 19:02:08.706515', '2023-01-26 19:02:08.706515', NULL, 'Leading with Gratitude');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (164, 'پایان کالج', 'ایجاد آینده یادگیری و دانشگاه همه جا', 'ایجاد آینده یادگیری و دانشگاه همه جا', 18, 7, 'book', 't', '<p>پایان کالج (2015) درباره سیستم آموزش عالی آمریکا است. این پلک ها نمای کلی تاریخی از نحوه نگرش نویسنده به توسعه دانشگاه آمریکایی و تکامل آن از مدل های اروپایی ارائه می دهد. او وضعیت فعلی آن را ارزیابی می کند و از<em>دانشگاه همه جا</em> - دانشگاهی در آینده که از راه دور قابل دسترسی است، حمایت می کند.</p>', '2017-06-02 00:00:00', 4, 22, 'https://images.blinkist.io/images/books/592c22a9b238e1000507d15a/1_1/470.jpg', '/en/books/the-end-of-college-en/purchase', 'پایان-کالج', '2023-01-26 19:02:13.352765', '2023-01-26 19:02:13.352765', NULL, 'The End of College');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (165, 'همانطور که داریم حرف می زنیم', 'چگونه نقطه نظر خود را بسازید و آن را ثابت نگه دارید', 'چگونه نقطه نظر خود را بسازید و آن را ثابت نگه دارید', 14, 6, 'book', 't', '<p>چه بخواهید در جلسات کاری موثرتر صحبت کنید یا یک سخنرانی به یاد ماندنی در مدرسه ارائه دهید، <em>As We Speak</em> (2012) تکنیک های مناسب برای جلب نظر مخاطبان را در عرض چند ثانیه بیان می کند. شما یاد خواهید گرفت که چگونه با هدف حرکت کنید و صحبت کنید و پیام خود را منتقل کنید.</p>', '2016-05-06 00:00:00', 5, 66, 'https://images.blinkist.io/images/books/572603a6f2d1b1000391f2c8/1_1/470.jpg', '/en/books/as-we-speak-en/purchase', 'همانطور-که-داریم-حرف-می-زنیم', '2023-01-26 19:02:17.949723', '2023-01-26 19:02:17.949723', NULL, 'As We Speak');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (520, 'توهم دانش', 'چرا ما هرگز به تنهایی فکر نمی کنیم', 'چرا ما هرگز به تنهایی فکر نمی کنیم', 31, 11, 'book', 't', '<p><em>توهم دانش </em>(2017) کاوشی عمیق در ذهن انسان است. این نظریه مخالف این دیدگاه است که هوش صرفاً یک ویژگی فردی است، و استدلال‌های قانع‌کننده‌ای برای اینکه چگونه موفقیت ما به‌عنوان یک گونه بدون جامعه دانش غیرممکن می‌بود، ارائه می‌کند.</p>', '2018-08-29 00:00:00', 5, 73, 'https://images.blinkist.io/images/books/5b8319c2b238e10007d7deea/1_1/470.jpg', '/en/books/the-knowledge-illusion-en/purchase', 'توهم-دانش', '2023-01-26 19:41:57.012895', '2023-01-26 19:41:57.012895', NULL, 'The Knowledge Illusion');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (166, 'خیلی بیشتر از یک چیز خوب', 'چگونه چهار ویژگی کلیدی بقا در حال حاضر ما را می کشند', 'چگونه چهار ویژگی کلیدی بقا در حال حاضر ما را می کشند', 15, 8, 'book', 't', '<p>بدن انسان به گونه‌ای تکامل یافته که به ما امکان می‌دهد در دنیایی بسیار متفاوت از دنیایی که امروز در آن زندگی می‌کنیم زنده بمانیم. این پلک‌ها توضیح می‌دهند که چرا ما با دنیای مدرن سازگار نیستیم و در نتیجه از عوارض سلامتی ما رنج می‌بریم.</p>', '2016-05-20 00:00:00', 4, 10, 'https://images.blinkist.io/images/books/573483e9e236900003290232/1_1/470.jpg', '/en/books/too-much-of-a-good-thing-en/purchase', 'خیلی-بیشتر-از-یک-چیز-خوب', '2023-01-26 19:02:22.694043', '2023-01-26 19:02:22.694043', NULL, 'Too Much of a Good Thing');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (167, 'حرفه ای Squiggly', 'نردبان را رها کنید، فرصت ها را در آغوش بگیرید و مسیر خود را در دنیای سخت کار بپیچید', 'نردبان را رها کنید، فرصت ها را در آغوش بگیرید و مسیر خود را در دنیای سخت کار بپیچید', 22, 8, 'book', 't', '<p><em>The Squiggly Career </em>(2020) تحقیقات و نکاتی را در مورد چگونگی بهترین مسیریابی در حرفه ای پر از تغییرات مکرر و چالش های امروزی پوشش می دهد. اگر یاد بگیریم نقاط قوت، ارزش‌ها، اهداف و انگیزه‌های خود را شناسایی کنیم، می‌توانیم آن‌ها را بیشتر در محل کار به کار ببریم – و متوجه شویم که چه زمانی نادیده گرفته می‌شوند. نویسندگان نحوه ایجاد شبکه با کمک به دیگران، شایستگی های شروع یک پروژه جانبی و نحوه استفاده از کنترل جدید بر روی شغل خود را نشان می دهند.</p>', '2020-10-08 00:00:00', 5, 132, 'https://images.blinkist.io/images/books/5f76e46e6cee07000602f194/1_1/470.jpg', '/en/books/the-squiggly-career-en/purchase', 'حرفه-ای-Squiggly', '2023-01-26 19:02:26.885755', '2023-01-26 19:02:26.885755', NULL, 'The Squiggly Career');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (168, 'انجام خوب بهتر', 'یک راه رادیکال جدید برای ایجاد تفاوت', 'یک راه رادیکال جدید برای ایجاد تفاوت', 14, 7, 'book', 't', '<p><em>انجام خوب بهتر </em>(2015) راهنمایی برای ایجاد بیشترین تأثیر مثبت ممکن از طریق کمک های خیریه است. این کتاب در بررسی بسیاری از تصورات غلط رایج در مورد بخشش مؤثر، همه ابزارهایی را که برای ایجاد تفاوت واقعی نیاز دارید در اختیار شما قرار می دهد.</p>', '2016-07-27 00:00:00', 4, 145, 'https://images.blinkist.io/images/books/57924c5cb3b9b300032e80f2/1_1/470.jpg', '/en/books/doing-good-better-en/purchase', 'انجام-خوب-بهتر', '2023-01-26 19:02:31.905077', '2023-01-26 19:02:31.905077', NULL, 'Doing Good Better');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (169, 'زندگی هدفمند', 'من برای چه اینجا هستم؟', 'من برای چه اینجا هستم؟', 11, 5, 'book', 't', '<p><em>The Purpose Driven Life </em>(2002) پاسخ مسیحی به این سوال قدیمی را به اشتراک می گذارد: چرا من اینجا هستم؟ از یافتن لحظات عبادت در کارهای روزمره گرفته تا جستجوی یک جامعه حامی و اجازه دادن به روح القدس شما را در موقعیت های سخت راهنمایی کند، این پلک ها راهنمای جذابی برای زندگی به عنوان یک مسیحی امروزی هستند.</p>', '2016-01-27 00:00:00', 4, 108, 'https://images.blinkist.io/images/books/56a6ab95fb7e870007000014/1_1/470.jpg', '/en/books/the-purpose-driven-life-en/purchase', 'زندگی-هدفمند', '2023-01-26 19:02:36.952329', '2023-01-26 19:02:36.952329', NULL, 'The Purpose Driven Life');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (170, 'چگونه از زندگی و شغل خود لذت ببرید', 'درک خود از طبیعت انسان را افزایش دهید تا کاملتر زندگی کنید', 'درک خود از طبیعت انسان را افزایش دهید تا کاملتر زندگی کنید', 27, 8, 'book', 't', '<p><em>چگونه از زندگی و شغل خود لذت ببرید </em>(1955) با تولید انرژی بیشتر در روز کاری و بهبود روابط شخصی خود راهنمایی هایی را در مورد بهره گیری بیشتر از زندگی روزمره ارائه می دهد. این نشان می دهد که چگونه طبیعت انسان بر نحوه رفتار ما تأثیر می گذارد، بنابراین می توانید مهارت های بین فردی خود را بهبود بخشید و درک خود را عمیق تر کنید.</p>', '2021-07-19 00:00:00', 5, 484, 'https://images.blinkist.io/images/books/60f14b996cee0700071a5fed/1_1/470.jpg', '/en/books/how-to-enjoy-your-life-and-your-job-en/purchase', 'چگونه-از-زندگی-و-شغل-خود-لذت-ببرید', '2023-01-26 19:02:42.326065', '2023-01-26 19:02:42.326065', NULL, 'How to Enjoy Your Life and Your Job');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (171, 'پروژه طول عمر', 'اکتشافات شگفت انگیز برای سلامتی و زندگی طولانی از مطالعه تاریخی هشت دهه', 'اکتشافات شگفت انگیز برای سلامتی و زندگی طولانی از مطالعه تاریخی هشت دهه', 15, 6, 'book', 't', '<p><em>پروژه طول عمر</em> (2012) در مورد مطالعه تاثیرگذار و آشکار ترمن است که گروهی از مردم را به مدت هشت دهه دنبال کرد تا دریابد که چه عادات و اقداماتی به آنها کمک کرد تا زندگی طولانی و سالم داشته باشند. . این پلک‌ها توضیح می‌دهند که چرا ازدواج ممکن است آنطور که فکر می‌کنید سالم نباشد و چه کاری می‌توانید انجام دهید تا شانس خوشبختی و طول عمر خود را افزایش دهید.</p>', '2016-11-10 00:00:00', 4, 80, 'https://images.blinkist.io/images/books/581f1c7bf52436000382a5e9/1_1/470.jpg', '/en/books/the-longevity-project-en/purchase', 'پروژه-طول-عمر', '2023-01-26 19:02:47.455013', '2023-01-26 19:02:47.455013', NULL, 'The Longevity Project');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (172, 'روابط قدرت', '26 قانون انکارناپذیر برای ایجاد روابط فوق العاده', '26 قانون انکارناپذیر برای ایجاد روابط فوق العاده', 23, 9, 'book', 't', '<p><em>روابط قدرت</em> (2013) نگاهی کامل به نوع روابط متحول کننده ای دارد که می تواند یک حرفه را تعریف کند. اینها مشارکت‌های حرفه‌ای هستند که زندگی مردم را غنی می‌کنند و آنها را به ارتفاعاتی می‌رسانند که در غیر این صورت ممکن نبود. نویسندگان به ما نشان می‌دهند که چگونه روابط قدرت را برقرار کنیم، پرورش دهیم و از پاداش‌های آن بهره ببریم. با این دانش، مشتریان بیشتری جذب خواهید کرد و این ارتباطات را برای یک عمر کار پربار حفظ خواهید کرد.</p>', '2019-04-29 00:00:00', 4, 109, 'https://images.blinkist.io/images/books/5cc44bb86cee070008220f7d/1_1/470.jpg', '/en/books/power-relationships-en/purchase', 'روابط-قدرت', '2023-01-26 19:02:52.221417', '2023-01-26 19:02:52.221417', NULL, 'Power Relationships');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (173, 'آشنایی عمیق تر', 'چگونه بازی های اغواگری را کنار بگذاریم و قدرت صمیمیت را کشف کنیم', 'چگونه بازی های اغواگری را کنار بگذاریم و قدرت صمیمیت را کشف کنیم', 18, 6, 'book', 't', '<p><em>دوست‌یابی عمیق‌تر </em>(2014) نقشه‌ای برای صمیمیت و روابط عاشقانه است. این نشان می‌دهد که چگونه نگاه به درون می‌تواند به ما کمک کند تا انواع افرادی را که عمیق‌تر با آن‌ها در ارتباط هستیم، شناسایی کنیم، و ابزارهایی را برای یافتن این افراد و تقویت روابطی به اشتراک می‌گذارد که الهام‌بخش و تحقق ما باشد.</p>', '2021-03-11 00:00:00', 4, 244, 'https://images.blinkist.io/images/books/604203776cee070007be7ccd/1_1/470.jpg', '/en/books/deeper-dating-en/purchase', 'آشنایی-عمیق-تر', '2023-01-26 19:03:03.908799', '2023-01-26 19:03:03.908799', NULL, 'Deeper Dating');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (174, 'بازاندیشی در برندینگ پرستیژ', 'اسرار برندهای اوبر', 'اسرار برندهای اوبر', 17, 7, 'book', 't', '<p><em>بازاندیشی در برندینگ پرستیژ </em>(2015) راهنمای شما به دنیای کاملاً متحول شده برندهای معتبر است. این پلک‌ها توضیح می‌دهند که چگونه رویه ایجاد یک برند معتبر تغییر کرده است، مشتریان امروز چه می‌خواهند و چه کارهایی باید انجام دهید تا برند خود را به یک هدف مورد علاقه تبدیل کنید.</p>', '2017-01-24 00:00:00', 4, 36, 'https://images.blinkist.io/images/books/588636d15806db0004d7ff30/1_1/470.jpg', '/en/books/rethinking-prestige-branding-en/purchase', 'بازاندیشی-در-برندینگ-پرستیژ', '2023-01-26 19:03:08.490198', '2023-01-26 19:03:08.490198', NULL, 'Rethinking Prestige Branding');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (175, 'بنیانگذار قابل تعویض', 'بیاموزید که چگونه افسار را رها کنید و اجازه دهید کسب و کارتان بدون شما اوج بگیرد', 'بیاموزید که چگونه افسار را رها کنید و اجازه دهید کسب و کارتان بدون شما اوج بگیرد', 25, 11, 'book', 't', '<p><em>بنیانگذار قابل تعویض</em> (2018) نگاهی منحصر به فرد به این دارد که چگونه رهبران می توانند کار ارزشمندی را که منسوخ کردن خود است انجام دهند. با ایجاد ساختارهای سازمانی قوی، از جمله فرآیندهای تولید و استخدام کارآمد، بنیانگذاران شرکت می توانند سازمان هایی را ایجاد کنند که مطمئناً بدون آنها کار می کنند و حتی پیشرفت می کنند. این یک سناریوی ایده‌آل است زیرا به بنیانگذار جاه‌طلب اجازه می‌دهد تا روی چیزی که بیشتر دوست دارد تمرکز کند: ایده‌های نوآورانه را به زندگی ببخشد و شرکت‌هایی ایجاد کند که نوید تجربه‌های کاری عالی را برای همه می‌دهد.</p>', '2019-06-04 00:00:00', 4, 92, 'https://images.blinkist.io/images/books/5cf2a7a86cee070008ddbc41/1_1/470.jpg', '/en/books/the-replaceable-founder-en/purchase', 'بنیانگذار-قابل-تعویض', '2023-01-26 19:03:13.688409', '2023-01-26 19:03:13.688409', NULL, 'The Replaceable Founder');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (176, 'تصادفات مبارک', 'قدرت دگرگون کننده «بله، و» در کار و زندگی', 'قدرت دگرگون کننده «بله، و» در کار و زندگی', 21, 7, 'book', 't', '<p><em>Happy Accidents</em> (2017) درباره تجربیات نویسندگان در چهار روز آخر هفته - یک گروه کمدی بداهه از فورت ورث، تگزاس است. این داستان موفقیت چهار روزه آخر هفته را در طول 20 سال نشان می دهد و نشان می دهد که چگونه هر کسی می تواند از اصول کمدی بداهه استفاده کند تا مثبت تر، خلاق تر شود و در برخورد با موانع زندگی بهتر شود.</p>', '2020-03-09 00:00:00', 4, 48, 'https://images.blinkist.io/images/books/5e64dfe66cee070006a1dbb8/1_1/470.jpg', '/en/books/happy-accidents-en/purchase', 'تصادفات-مبارک', '2023-01-26 19:03:18.5372', '2023-01-26 19:03:18.5372', NULL, 'Happy Accidents');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (177, 'هرگز شغل "واقعی" پیدا نکنید', 'چگونه رئیس خود را رها کنید، کسب و کار بسازید و خراب نشوید', 'چگونه رئیس خود را رها کنید، کسب و کار بسازید و خراب نشوید', 20, 7, 'book', 't', '<p> بر اساس تجربه و مشاهدات در دنیای واقعی، راهنمای کاملی برای جمع‌آوری و راه‌اندازی آن ارائه می‌کند.</p>', '2019-01-11 00:00:00', 4, 69, 'https://images.blinkist.io/images/books/5c35bd256cee0700076845a1/1_1/470.jpg', '/en/books/never-get-a-real-job-en/purchase', 'هرگز-شغل-"واقعی"-پیدا-نکنید', '2023-01-26 19:03:23.316305', '2023-01-26 19:03:23.316305', NULL, 'Never Get a “Real” Job');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (178, 'ملکه سرخ', 'جنسیت و تکامل طبیعت انسان', 'جنسیت و تکامل طبیعت انسان', 22, 8, 'book', 't', '<p><em>ملکه سرخ</em> (1993) نگاهی دقیق به مسیرهای تکاملی دارد و اینکه چگونه آنها بیشتر از طریق تولید مثل هدایت شده اند تا بقا. این پلک ها توضیح می دهند که چگونه جستجو برای جفت مناسب، پدیده های قابل توجهی مانند دم های تماشایی طاووس ها و هوش قدرتمند انسان ها را به وجود آورده است.</p>', '2017-04-10 00:00:00', 5, 61, 'https://images.blinkist.io/images/books/58eb3b45a54bbb000464bab8/1_1/470.jpg', '/en/books/the-red-queen-en/purchase', 'ملکه-سرخ', '2023-01-26 19:03:26.778842', '2023-01-26 19:03:26.778842', NULL, 'The Red Queen');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (179, 'خوردن شهودی', 'یک رویکرد انقلابی ضد رژیم غذایی', 'یک رویکرد انقلابی ضد رژیم غذایی', 21, 7, 'book', 't', '<p><em>غذاهای شهودی </em>(2012) دو هدف دارد: افشای وعده‌های شکسته‌شده صنعت رژیم غذایی و پی‌ریزی پایه‌های یک رویکرد منطقی‌تر به تغذیه سالم. این استدلال می‌کند که ما نباید کورکورانه محدودیت‌های غالباً نامفهوم رژیم‌های غذایی مد روز را بپذیریم - در عوض، بهتر است به بدن خود گوش دهیم. برخلاف ذهن ما که به شدت پذیرای ایده های غیرمنطقی در مورد غذا است، بدن ما به طور شهودی می داند چه چیزی برای ما بهتر است. </p>', '2021-09-21 00:00:00', 4, 278, 'https://images.blinkist.io/images/books/614469af6cee070007e05178/1_1/470.jpg', '/en/books/intuitive-eating-en/purchase', 'خوردن-شهودی', '2023-01-26 19:03:31.634224', '2023-01-26 19:03:31.634224', NULL, 'Intuitive Eating');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (180, 'شما مدیون شما هستید', 'قدرت، هدف و چرایی خود را روشن کنید', 'قدرت، هدف و چرایی خود را روشن کنید', 15, 6, 'book', 't', '<p>You Owe You (2022) هیچ شکی برای شما باقی نمی گذارد که چه کسی مسئول تغییر مسیر زندگی شما است. از شما می خواهد که هدف خود را شناسایی کنید و سپس استعدادهای منحصر به فرد خود را به دارایی هایی تبدیل کنید که باعث می شود به موفقیتی افسارگسیخته دست یابید.</p>', '2022-12-19 00:00:00', 4, 383, 'https://images.blinkist.io/images/books/639c3f3f73bf6d0009f1e651/1_1/470.jpg', '/en/books/you-owe-you-en/purchase', 'شما-مدیون-شما-هستید', '2023-01-26 19:03:37.059609', '2023-01-26 19:03:37.059609', NULL, 'You Owe You');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (181, 'بیوگرافی قبل از خواب: RBG بدنام', 'زندگی و زمانه روت بادر گینزبورگ', 'زندگی و زمانه روت بادر گینزبورگ', 38, 6, 'book', 't', '<p><strong>به روایت والری راس</strong></p>
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (182, 'پول شما یا زندگی شما', '9 گام برای تغییر رابطه خود با پول و دستیابی به استقلال مالی', '9 گام برای تغییر رابطه خود با پول و دستیابی به استقلال مالی', 26, 9, 'book', 't', '<p><em>پول یا زندگی شما </em>(1992) یک راهنمای 9 مرحله ای برای کنترل امور مالی است - بنابراین می توانید به جای اینکه صرفاً امرار معاش کنید، از زندگی خود لذت ببرید. شما یاد خواهید گرفت که چگونه نگرش خود را نسبت به پول و زمان خود تنظیم کنید، از بدهی خارج شوید، شروع به پس انداز کنید و در نهایت به استقلال مالی برسید. </p>', '2021-11-18 00:00:00', 4, 277, 'https://images.blinkist.io/images/books/618d11f06cee070007adc7e9/1_1/470.jpg', '/en/books/your-money-or-your-life-en/purchase', 'پول-شما-یا-زندگی-شما', '2023-01-26 19:03:47.080021', '2023-01-26 19:03:47.080021', NULL, 'Your Money or Your Life');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (183, 'دشمنان', 'اختلال حماسی در صنعت تبلیغات (و هر چیز دیگر)', 'اختلال حماسی در صنعت تبلیغات (و هر چیز دیگر)', 19, 6, 'book', 't', '<p><em>Frenemies</em> (2018) به بررسی نیروهایی می‌پردازد که در حال حاضر صنایع سنتی تبلیغات و بازاریابی را مختل می‌کنند. به این می پردازد که چگونه عصر اینترنت صنعت تبلیغات را مجبور به تغییر و انطباق کرده است، به ویژه اینکه چگونه فناوری، علم و سفارشی سازی نقش آژانس تبلیغاتی سنتی را متحول کرده است.</p>', '2018-07-26 00:00:00', 4, 22, 'https://images.blinkist.io/images/books/5b58510bb238e10007a4bb40/1_1/470.jpg', '/en/books/frenemies-en/purchase', 'دشمنان', '2023-01-26 19:03:51.465313', '2023-01-26 19:03:51.465313', NULL, 'Frenemies');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (184, 'راه مهر و موم', 'استحکام ذهنی و عملکرد بالا را مانند یک Navy SEAL پرورش دهید', 'استحکام ذهنی و عملکرد بالا را مانند یک Navy SEAL پرورش دهید', 17, 9, 'book', 't', '<p><em>راه</em> <em>راه</em> <em></em> <em></em> <em>SEAL</em> از تجربه نیروی دریایی SEAL استفاده می‌کند به تشریح اصولی که آنها را قادر می سازد سرسختی ذهنی و برتری را پرورش دهند. تمرینات ذهنی لازم برای مقابله با هر چالشی را در مسیر دستیابی به اهدافتان ارائه می دهد.</p>', '2014-05-06 12:37:37', 4, 73, 'https://images.blinkist.io/images/books/5369f94366313400070b0000/1_1/470.jpg', '/en/books/the-way-of-the-seal-en/purchase', 'راه-مهر-و-موم', '2023-01-26 19:03:55.78154', '2023-01-26 19:03:55.78154', NULL, 'The Way of the SEAL');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (185, 'بدون دردسر', 'انجام کارهای درست را آسان کنید', 'انجام کارهای درست را آسان کنید', 19, 6, 'book', 't', '<p><em>Effortless</em>(2021) این ایده را به چالش می‌کشد که دستیابی به هر چیزی ارزشمند به معنای تلاش بیش از حد است. این راهنمای آسان به دنبال چگونگی آسان کردن کارها و پروژه‌ها، اقداماتی که می‌توانیم برای به حداکثر رساندن تلاش‌هایمان انجام دهیم و تکنیک‌هایی برای افزایش خروجی و در عین حال پایین نگه داشتن ورودی‌هایمان را توضیح می‌دهد.</p>', '2021-06-21 00:00:00', 4, 367, 'https://images.blinkist.io/images/books/60cc419a6cee07000810fdca/1_1/470.jpg', '/en/books/effortless-en/purchase', 'بدون-دردسر', '2023-01-26 19:04:00.540247', '2023-01-26 19:04:00.540247', NULL, 'Effortless');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (186, 'اتصال', 'کتاب راهنمای راز لینکدین برای ایجاد سرنخ، ایجاد روابط و افزایش چشمگیر فروش شما', 'کتاب راهنمای راز لینکدین برای ایجاد سرنخ، ایجاد روابط و افزایش چشمگیر فروش شما', 18, 8, 'book', 't', '<p><em>Connect </em>(2015) مؤثرترین راه‌ها را برای استفاده از پتانسیل لینکدین برای شروع موفقیت در بازاریابی ارائه می‌کند. با کمک مطالعات موردی، یاد خواهید گرفت که چگونه از LinkedIn به عنوان یک ابزار فروش ارزشمند استفاده کنید، وبینارهای عالی را میزبانی کنید و مخاطبان مشتاق خود را به مشتریان جدید تبدیل کنید.</p>', '2016-01-06 00:00:00', 4, 35, 'https://images.blinkist.io/images/books/568afcd0de78c00007000021/1_1/470.jpg', '/en/books/connect-en/purchase', 'اتصال', '2023-01-26 19:04:05.34479', '2023-01-26 19:04:05.34479', NULL, 'Connect');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (187, 'برو دهنده', 'داستانی کوچک درباره یک ایده قدرتمند تجاری', 'داستانی کوچک درباره یک ایده قدرتمند تجاری', 12, 6, 'book', 'f', '<p><em>Go-Giver </em> پنج اصل ساده را به اشتراک می گذارد که راز دستیابی به موفقیت واقع بینانه در زندگی - در عین حال تبدیل شدن به یک فرد بهتر است. این پلک‌ها از نمونه‌هایی از مشاغل واقعی استفاده می‌کنند که به ما کمک می‌کنند با استفاده از سخاوت و اصالت به اهداف و رویاهای خود برسیم.</p>', '2014-12-25 00:00:00', 5, 74, 'https://images.blinkist.io/images/books/549131833633390009420000/1_1/470.jpg', '/en/books/the-go-giver-en/purchase', 'برو-دهنده', '2023-01-26 19:04:10.893433', '2023-01-26 19:04:10.893433', NULL, 'The Go-Giver');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (188, 'ذن و هنر تعمیر و نگهداری موتورسیکلت', 'تحقیق در مورد ارزش ها', 'تحقیق در مورد ارزش ها', 11, 5, 'book', 't', '<p><em>ذن و هنر تعمیر و نگهداری موتورسیکلت</em> (1974)، با استفاده از تمثیل یک سفر جاده‌ای با موتور سیکلت، شما را در پرسش‌های فردی از نظم فلسفی و متافیزیکی جهان راهنمایی می‌کند.</p>', '2015-11-26 00:00:00', 4, 198, 'https://images.blinkist.io/images/books/565425406362640007610000/1_1/470.jpg', '/en/books/zen-and-the-art-of-motorcycle-maintenance-en/purchase', 'ذن-و-هنر-تعمیر-و-نگهداری-موتورسیکلت', '2023-01-26 19:04:15.592707', '2023-01-26 19:04:15.592707', NULL, 'Zen and the Art of Motorcycle Maintenance');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (189, 'بیشتر سریعتر انجام دهید', 'درس های Techstars برای سرعت بخشیدن به استارتاپ شما', 'درس های Techstars برای سرعت بخشیدن به استارتاپ شما', 13, 6, 'book', 't', '<p><em>سریعتر انجام دهید </em>(2011) یک راهنمای گام به گام برای راه اندازی استارت آپ شما ارائه می دهد. این بسیار مهم است که در مسیر حرکت به سمت موفقیت، از تقویت ایده های خود گرفته تا یافتن تیم مناسب و جذب سرمایه گذار، در مسیر خود بمانید. نویسنده همچنین بر اهمیت تعادل کار و زندگی تاکید می‌کند و در عین حال به شما نشان می‌دهد که چگونه <em>سریع‌تر انجام دهید</em>.</p>', '2016-05-05 00:00:00', 4, 51, 'https://images.blinkist.io/images/books/57225a695ed4340003a94ae2/1_1/470.jpg', '/en/books/do-more-faster-en/purchase', 'بیشتر-سریعتر-انجام-دهید', '2023-01-26 19:04:20.067152', '2023-01-26 19:04:20.067152', NULL, 'Do More Faster');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (190, 'آزاد برای انتخاب', 'تحقیق کلاسیک در رابطه بین آزادی و اقتصاد', 'تحقیق کلاسیک در رابطه بین آزادی و اقتصاد', 15, 10, 'book', 'f', '<p><em>انتخاب آزاد </em>(1980) رابطه بین آزادی و انتخاب‌هایی که یک فرد مجاز است در رابطه با اقتصاد انجام دهد را بررسی می‌کند. فریدمن به ما نشان می دهد که آزادی اقتصادی بخش اساسی آزادی است. او روش‌های بی‌شماری را توضیح می‌دهد که در آن مقررات و مداخلات دولتی حق اساسی ما برای تصمیم‌گیری در راستای منافع شخصی‌مان را از بین می‌برد.</p>', '2014-02-04 09:00:00', 4, 72, 'https://images.blinkist.io/images/books/52f113e23565360011000000/1_1/470.jpg', '/en/books/free-to-choose-en/purchase', 'آزاد-برای-انتخاب', '2023-01-26 19:04:24.780316', '2023-01-26 19:04:24.780316', NULL, 'Free to Choose');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (191, 'پایان آلرژی غذایی', 'اولین برنامه برای جلوگیری و معکوس کردن اپیدمی قرن 21', 'اولین برنامه برای جلوگیری و معکوس کردن اپیدمی قرن 21', 30, 10, 'book', 't', '<p><em>پایان آلرژی غذایی</em> (2020) نشان می‌دهد که چگونه پیشرفت‌های اخیر در علم و پزشکی شروع به حل مشکلی می‌کنند که هزاران سال است که بشریت را درگیر کرده است. با ترکیب تحقیقات مبتنی بر داده با داستان سرایی الهام‌بخش، پنجره‌ای به یکی از بزرگترین انقلاب‌های علمی و پزشکی زمان ما ارائه می‌کند.</p>', '2020-12-08 00:00:00', 4, 51, 'https://images.blinkist.io/images/books/5fca0d1e6cee07000677d175/1_1/470.jpg', '/en/books/the-end-of-food-allergy-en/purchase', 'پایان-آلرژی-غذایی', '2023-01-26 19:04:29.729067', '2023-01-26 19:04:29.729067', NULL, 'The End of Food Allergy');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (192, 'شجاعت فراخوان است', 'فورچون به نفع شجاعان است', 'فورچون به نفع شجاعان است', 18, 6, 'book', 't', '<p><em>شجاعت فرا می خواند </em>(2021) هم مراقبه در مورد شجاعت است و هم راهنمای شجاعت. از چگونگی از بین بردن ترس‌هایتان گرفته تا فواید برداشتن قدم‌های کوچک، توصیه‌های ملموسی برای ایجاد شجاعت می‌دهد، و با نوشتنی سرشار از حکایت، راه‌های ساده‌ای را بیان می‌کند که هر یک از ما می‌توانیم کمی شجاع‌تر شویم.</p >', '2021-10-14 00:00:00', 4, 215, 'https://images.blinkist.io/images/books/6166fac46cee0700087a4856/1_1/470.jpg', '/en/books/courage-is-calling-en/purchase', 'شجاعت-فراخوان-است', '2023-01-26 19:04:33.103089', '2023-01-26 19:04:33.103089', NULL, 'Courage is Calling');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (193, 'حمام کردن جنگل', 'چگونه درختان می توانند به شما در یافتن سلامتی و شادی کمک کنند', 'چگونه درختان می توانند به شما در یافتن سلامتی و شادی کمک کنند', 20, 6, 'book', 't', '<p><em>حمام کردن جنگل</em>(2018) راهنمای عمل ژاپنی <em>حمام کردن جنگل</em> است. این کتاب به بررسی باورها، فرهنگ و سنت های پشت حمام کردن جنگل و همچنین مطالعات مختلف در مورد فواید سلامتی آن می پردازد<em>. </em>همچنین مراحل آسانی را برای تمرین حمام کردن در جنگل در هر محیطی ارائه می‌کند.</p>', '2021-05-10 00:00:00', 5, 245, 'https://images.blinkist.io/images/books/60950a3c6cee070007151f86/1_1/470.jpg', '/en/books/forest-bathing-en/purchase', 'حمام-کردن-جنگل', '2023-01-26 19:04:37.687396', '2023-01-26 19:04:37.687396', NULL, 'Forest Bathing');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (194, 'استعداد نابجا', 'راهنمای تصمیم گیری افراد بهتر', 'راهنمای تصمیم گیری افراد بهتر', 12, 5, 'book', 't', '<p><em>استعداد نابجا</em>(2015) یک راهنمای عملی برای استخدام کارمندی است که به بهترین وجه برای شغل مناسب است و چگونه می توان آن کارمند را راضی و خوشحال نگه داشت. بسیاری از کسب‌وکارها حتی نمی‌دانند که باید به دنبال چه مهارت‌هایی در یک کارمند بگردند – یا اگر بدانند، پس از حضور در کارمند، انگیزه نگه داشتن آن کارمند را فراموش می‌کنند. این مهم است که بدانید چگونه هر دوی این کارها را انجام دهید، بنابراین بیابید که چگونه از همه دام های نامرتب اجتناب کنید و نیروی کار خود را راضی نگه دارید.</p>', '2017-06-16 00:00:00', 4, 15, 'https://images.blinkist.io/images/books/593e8479b238e10005ae417d/1_1/470.jpg', '/en/books/misplaced-talent-en/purchase', 'استعداد-نابجا', '2023-01-26 19:04:49.627644', '2023-01-26 19:04:49.627644', NULL, 'Misplaced Talent');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (195, 'گیاه شناسی آرزو', 'نمایی از چشم گیاهی از جهان', 'نمایی از چشم گیاهی از جهان', 16, 7, 'book', 't', '<p><em>گیاه شناسی آرزو</em> (2001) رابطه پیچیده و جذاب بین انسان و گیاهان را بررسی می کند. در این پلک‌ها، خواهیم دید که چگونه گیاهان با بهره‌گیری از چهار خواسته اصلی ما برای شیرینی، زیبایی، مسمومیت و کنترل، انسان‌ها را دستکاری می‌کنند و چگونه به نوبه خود به گیاهان کمک می‌کنیم تا تولید مثل کنند و حتی قوی‌تر شوند.</p>', '2016-04-05 00:00:00', 4, 52, 'https://images.blinkist.io/images/books/56fe54708249800007000039/1_1/470.jpg', '/en/books/the-botany-of-desire-en/purchase', 'گیاه-شناسی-آرزو', '2023-01-26 19:04:54.069113', '2023-01-26 19:04:54.069113', NULL, 'The Botany of Desire');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (521, 'سر و صدا', 'زندگی و رهبری زمانی که هیچ کس نمی تواند تمرکز کند', 'زندگی و رهبری زمانی که هیچ کس نمی تواند تمرکز کند', 17, 6, 'book', 't', '<p><em>نویز </em>(2019) پادزهری برای زمان پریشان ما است. در عصر کاهش دامنه توجه و تمرکز تقسیم شده، به ما نشان می دهد که چگونه قدرت تمرکز طبیعی خود را بازیابی کنیم.</p>', '2021-01-07 00:00:00', 4, 117, 'https://images.blinkist.io/images/books/5fdb1ed26cee0700073571c7/1_1/470.jpg', '/en/books/noise-en/purchase', 'سر-و-صدا', '2023-01-26 19:42:00.562493', '2023-01-26 19:42:00.562493', NULL, 'Noise');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (196, 'شما می توانید زندگی خود را درمان کنید', 'کلاسیک خودآگاهی با توصیه های عملی و معنوی برای مشکلات عاطفی و جسمی', 'کلاسیک خودآگاهی با توصیه های عملی و معنوی برای مشکلات عاطفی و جسمی', 23, 7, 'book', 't', '<p><em>شما می توانید زندگی خود را شفا دهید </em>(1984) کلاسیک خودشناسی و شفا است. این کتاب با بیش از 39 میلیون نسخه چاپ شده، توصیه های عملی و معنوی را ترکیب می کند تا به شما کمک کند بر مشکلات عاطفی و جسمی غلبه کنید و زندگی شما را برای همیشه متحول کند.</p>', '2021-03-20 00:00:00', 5, 173, 'https://images.blinkist.io/images/books/605097066cee070007a43e5d/1_1/470.jpg', '/en/books/you-can-heal-your-life-en/purchase', 'شما-می-توانید-زندگی-خود-را-درمان-کنید', '2023-01-26 19:04:59.683503', '2023-01-26 19:04:59.683503', NULL, 'You Can Heal Your Life');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (197, 'به نشان دادن ادامه دهید', 'چگونه دیوانه عاشق بمانیم وقتی عشق شما را دیوانه می کند', 'چگونه دیوانه عاشق بمانیم وقتی عشق شما را دیوانه می کند', 20, 7, 'book', 't', '<p><em>Keep Showing Up</em> (2019) به بررسی تفاوت‌هایی می‌پردازد که می‌توانند زوج‌های متاهل را از هم جدا کنند و پیشنهادات الهام‌بخشی را برای غلبه بر این موانع ارائه می‌دهد. این تکنیک‌ها همسران را به هم نزدیک‌تر می‌کند و همچنین به تأیید مجدد ایمان آنها به مسیحیت کمک می‌کند.</p>', '2020-01-31 00:00:00', 4, 77, 'https://images.blinkist.io/images/books/5e338d016cee070007b1e537/1_1/470.jpg', '/en/books/keep-showing-up-en/purchase', 'به-نشان-دادن-ادامه-دهید', '2023-01-26 19:05:04.799388', '2023-01-26 19:05:04.799388', NULL, 'Keep Showing Up');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (198, 'بهتر از قبل', 'تسلط بر عادات زندگی روزمره ما', 'تسلط بر عادات زندگی روزمره ما', 15, 7, 'book', 't', '<p><em>بهتر از قبل</em> (2015) راهکارهایی را در اختیار شما قرار می دهد که هم عادت های خوب و سالم ایجاد کرده و هم حفظ کنید و هم عادت هایی را که به شما کمک نمی کنند را ترک کنید.</p>', '2015-03-23 00:00:00', 4, 255, 'https://images.blinkist.io/images/books/550fef8f666564000a200000/1_1/470.jpg', '/en/books/better-than-before-en/purchase', 'بهتر-از-قبل', '2023-01-26 19:05:10.137423', '2023-01-26 19:05:10.137423', NULL, 'Better Than Before');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (199, 'دلایل خودخواهانه برای داشتن فرزندان بیشتر', 'چرا پدر و مادر عالی بودن کار کمتر و سرگرم کننده تر از آن چیزی است که فکر می کنید؟', 'چرا پدر و مادر عالی بودن کار کمتر و سرگرم کننده تر از آن چیزی است که فکر می کنید؟', 15, 8, 'book', 'f', '<p><em>خودخواه</em> <em>دلایل</em> <em>برای</em> <em>داشتن</em> <em>بیشتر</em> <em>کودکان</em> > خواسته های فرزندپروری مدرن را بررسی می کند و اینکه چرا امروزه مردم تصمیم می گیرند فرزندان کمتر و کمتری داشته باشند. نویسنده استدلال می‌کند که این روند به این دلیل است که والدین مدرن انتظارات زیادی از خود دارند، حتی زمانی که سبک فرزندپروری بسیار آرام‌تر کار را به همان خوبی انجام می‌دهد و کل تجربه را لذت‌بخش‌تر می‌کند.</p>', '2014-07-22 00:00:00', 4, 25, 'https://images.blinkist.io/images/books/53cf890f3630650007470100/1_1/470.jpg', '/en/books/selfish-reasons-to-have-more-kids-en/purchase', 'دلایل-خودخواهانه-برای-داشتن-فرزندان-بیشتر', '2023-01-26 19:05:14.923054', '2023-01-26 19:05:14.923054', NULL, 'Selfish Reasons to Have More Kids');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (200, 'عبور از شکاف', 'بازاریابی و فروش محصولات مخرب به مشتریان اصلی', 'بازاریابی و فروش محصولات مخرب به مشتریان اصلی', 17, 9, 'book', 't', '<p><em>عبور از شکاف</em> (1991) به بررسی پویایی بازاری می‌پردازد که محصولات جدید نوآورانه با آن مواجه هستند، به‌ویژه شکاف دلهره‌آوری که بین بازارهای اولیه تا جریان اصلی وجود دارد.</p>
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (201, 'اجرای کسب و کار برای نتایج', 'راهنمای عملی برای رهبران شرکت های کوچک تا متوسط', 'راهنمای عملی برای رهبران شرکت های کوچک تا متوسط', 14, 6, 'book', 't', '<p><em>اجرای کسب و کار برای نتایج</em> (2013) راهنمای ایجاد یک کسب و کار بهتر است. این پلک ها یک برنامه عملی برای تعیین اهداف مناسب و انجام تجزیه و تحلیل های لازم برای ایجاد یک استراتژی تجاری برنده ارائه می دهند که شرکت شما را مستقیماً به سمت بالا هدایت می کند.</p>', '2017-07-06 00:00:00', 4, 48, 'https://images.blinkist.io/images/books/595a238eb238e100069fb380/1_1/470.jpg', '/en/books/business-execution-for-results-en/purchase', 'اجرای-کسب-و-کار-برای-نتایج', '2023-01-26 19:05:22.735588', '2023-01-26 19:05:22.735588', NULL, 'Business Execution for RESULTS');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (202, 'ضربه زدن، ضربه زدن، ضربه زدن، قلاب راست', 'چگونه داستان خود را در یک دنیای اجتماعی پر سر و صدا بگویید', 'چگونه داستان خود را در یک دنیای اجتماعی پر سر و صدا بگویید', 11, 6, 'book', 't', '<p><em>Jab, Jab, Jab, Right Hook</em> توضیح می‌دهد که چگونه مدیران، بازاریابان و کسب‌وکارهای کوچک می‌توانند از پلتفرم‌های رسانه‌های اجتماعی مانند Facebook برای افزایش نمایه عمومی خود سرمایه‌گذاری کنند. یک کمپین بازاریابی رسانه‌های اجتماعی عالی می‌تواند آن ضربه مهلک را وارد کند - «قلاب مناسب» که مصرف‌کنندگان را مجبور به خرید محصولشان می‌کند. نویسنده حرکات رسانه‌های اجتماعی را به شما آموزش می‌دهد که باعث می‌شود محصول شما مانند یک پروانه شناور باشد و مانند یک زنبور نیش بزند.</p>', '2014-12-05 00:00:00', 4, 121, 'https://images.blinkist.io/images/books/547df29a61393200081b0000/1_1/470.jpg', '/en/books/jab-jab-jab-right-hook-en/purchase', 'ضربه-زدن،-ضربه-زدن،-ضربه-زدن،-قلاب-راست', '2023-01-26 19:05:27.412275', '2023-01-26 19:05:27.412275', NULL, 'Jab, Jab, Jab, Right Hook');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (203, 'لهش کن!', 'چرا اکنون زمان آن است که از علاقه خود پول نقد کنید؟', 'چرا اکنون زمان آن است که از علاقه خود پول نقد کنید؟', 16, 9, 'book', 't', '<p><em>آن را له کن! </em>یک متن انگیزشی، نقشه و راهنمای کسانی است که می خواهند علاقه خود را به یک تجارت تبدیل کنند. این کتاب با استفاده از زندگی نویسنده به عنوان مثال، جزئیات این کتاب را توضیح می‌دهد که چگونه همه می‌توانند آن را «درهم بشکنند»، یعنی امکان زندگی کردن به اشتیاق خود، تعیین معیشت خود و کسب درآمد از کاری که دوست دارند انجام دهند.</p>', '2014-04-23 09:00:34', 4, 70, 'https://images.blinkist.io/images/books/534ec2ec65316600074d0000/1_1/470.jpg', '/en/books/crush-it-en/purchase', 'لهش-کن!', '2023-01-26 19:05:31.2502', '2023-01-26 19:05:31.2502', NULL, 'Crush It!');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (204, 'خوردن بخوابید کار را تکرار کنید', '30 هک برای ایجاد شادی در شغل شما', '30 هک برای ایجاد شادی در شغل شما', 24, 8, 'book', 't', '<p><em>Eat Sleep Work Repeat (2020) </em>به سوالی که بسیاری از ما با آن روبرو هستیم پاسخ می دهد: چرا ما در محل کار اینقدر ناراضی هستیم و چه کاری می توانیم در مورد آن انجام دهیم؟ با تکیه بر تحقیقات مختلف، مشکلات زیربنایی ناراحتی در محل کار را شناسایی کرده و طیف گسترده ای از راه حل های عملی را پیشنهاد می کند. </p>', '2020-07-13 00:00:00', 4, 232, 'https://images.blinkist.io/images/books/5f082e1a6cee070007e4f8c3/1_1/470.jpg', '/en/books/eat-sleep-work-repeat-en/purchase', 'خوردن-بخوابید-کار-را-تکرار-کنید', '2023-01-26 19:05:35.757065', '2023-01-26 19:05:35.757065', NULL, 'Eat Sleep Work Repeat');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (205, 'یک زمین جدید', 'بیداری برای هدف زندگی شما', 'بیداری برای هدف زندگی شما', 13, 6, 'book', 't', '<p><em>A New Earth</em> (2005) آموزه های معنوی نویسنده را گسترش می دهد و بر چگونگی زندگی مردم در لحظه حال تمرکز می کند. این پلک‌ها نشان می‌دهند که چگونه فراتر از نفس انسانی برای شادی فردی مهم است و می‌تواند به رنج جهانی پایان دهد. شما یاد خواهید گرفت که چگونه نفس خود را رها کنید و به رضایت واقعی در زندگی برسید!</p>', '2015-12-09 00:00:00', 4, 383, 'https://images.blinkist.io/images/books/56660d46cb2fee0007000012/1_1/470.jpg', '/en/books/a-new-earth-en/purchase', 'یک-زمین-جدید', '2023-01-26 19:05:41.285158', '2023-01-26 19:05:41.285158', NULL, 'A New Earth ');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (206, 'باران', 'تاریخ طبیعی و فرهنگی', 'تاریخ طبیعی و فرهنگی', 10, 5, 'book', 't', '<p><em>باران</em> (2015) داستان یکی از ارزشمندترین، مخرب ترین و الهام بخش ترین نیروهای طبیعی سیاره ما را روایت می کند. این چشمک‌ها سفری را از پرستش باران در فرهنگ‌های باستانی تا استفاده از پیش‌بینی آب و هوا در طول اعصار - و حتی توضیح علمی پشت قورباغه‌های بارانی نشان می‌دهد.</p>', '2016-01-27 00:00:00', NULL, 9, 'https://images.blinkist.io/images/books/56a6ad35fb7e87000700001a/1_1/470.jpg', '/en/books/rain-en/purchase', 'باران', '2023-01-26 19:05:47.028601', '2023-01-26 19:05:47.028601', NULL, 'Rain');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (207, 'مهارت های مردم', 'چگونه خود را ابراز کنید، به دیگران گوش دهید و تضادها را حل کنید', 'چگونه خود را ابراز کنید، به دیگران گوش دهید و تضادها را حل کنید', 24, 6, 'book', 't', '<p><em>مهارت های مردمی </em>(1979) کتاب راهنمای یادگیری مهارت های ارتباط موثر است. موانع مکالمه‌ای را که مانع از برقراری ارتباط خوب و آسیب به روابط می‌شوند را روشن می‌کند - و روش‌های جایگزینی برای گوش دادن، ابراز وجود و رسیدگی به تعارض ارائه می‌دهد.</p>', '2022-03-14 00:00:00', 4, 338, 'https://images.blinkist.io/images/books/622f04f66cee070009051f85/1_1/470.jpg', '/en/books/people-skills-en/purchase', 'مهارت-های-مردم', '2023-01-26 19:05:52.391262', '2023-01-26 19:05:52.391262', NULL, 'People Skills');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (208, 'سخنرانی های TED', 'راهنمای رسمی TED برای سخنرانی عمومی', 'راهنمای رسمی TED برای سخنرانی عمومی', 16, 7, 'book', 't', '<p><em>TED Talks</em> (2016) راهنمای قطعی برای ارائه یک سخنرانی عمومی قاتل است. این پلک‌ها همه چیز را از ترس صحنه گرفته تا انتخاب لباس مناسب پوشش می‌دهند و برای ارائه سخنرانی آماده می‌شوند که هر مخاطبی را الهام‌بخش می‌کند.</p>', '2016-08-12 00:00:00', 4, 95, 'https://images.blinkist.io/images/books/57a8de971c2e11000357fb15/1_1/470.jpg', '/en/books/ted-talks-en/purchase', 'سخنرانی-های-TED', '2023-01-26 19:05:57.56753', '2023-01-26 19:05:57.56753', NULL, 'TED Talks');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (209, 'ساخت یک برند داستانی', 'پیام خود را روشن کنید تا مشتریان به آن گوش دهند', 'پیام خود را روشن کنید تا مشتریان به آن گوش دهند', 22, 9, 'book', 't', '<p><em>ساخت یک برند داستانی</em> (2017) یک راهنمای عملی برای بازاریابی موثر شرکت یا محصول شما است. این پلک ها با نشان دادن قدرت چارچوب داستان گویی هفت قسمتی، به شما و شرکتتان کمک می کند تا پیامی واضح ایجاد کنید که هیچ مشتری آن را نادیده نمی گیرد<strong>.</strong></p>', '2018-03-02 00:00:00', 5, 274, 'https://images.blinkist.io/images/books/5a9687f9b238e100088283f4/1_1/470.jpg', '/en/books/building-a-storybrand-en/purchase', 'ساخت-یک-برند-داستانی', '2023-01-26 19:06:03.141633', '2023-01-26 19:06:03.141633', NULL, 'Building a StoryBrand');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (210, 'داوود و جالوت', 'Underdogs، Misfits، و هنر مبارزه با غول ها', 'Underdogs، Misfits، و هنر مبارزه با غول ها', 20, 9, 'book', 't', '<p><em>دیوید و جالوت (2013) </em>داستان‌های بی‌شماری از افراد ضعیفی را به اشتراک می‌گذارد که بر خلاف همه شانس پیروز شدند. با کنار گذاشتن ایده‌های سنتی ما در مورد آنچه برای موفقیت لازم است، دیدگاه‌های غیرمتعارفی در مورد موضوعاتی مانند جنبه‌های منفی امتیازات، مزایای مشکلات یادگیری، و نحوه برخورد مقامات با شهروندان خود ارائه می‌دهد. این درس‌ها با مطالعات آکادمیک، نمونه‌های تاریخی و مصاحبه‌های مفصل با خود افراد زیردست همراه است.</p>', '2014-01-29 09:15:00', 4, 138, 'https://images.blinkist.io/images/books/52e8dd993635320011240000/1_1/470.jpg', '/en/books/david-and-goliath-en/purchase', 'داوود-و-جالوت', '2023-01-26 19:06:08.096367', '2023-01-26 19:06:08.096367', NULL, 'David and Goliath');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (211, 'در بین', 'پذیرش تنش بین اکنون و چیز بزرگ بعدی', 'پذیرش تنش بین اکنون و چیز بزرگ بعدی', 12, 7, 'book', 'f', '<p>بیشتر مردم زندگی خود را بی صبرانه در انتظار وقوع اتفاق بزرگ بعدی می گذرانند. اما چه می‌شد اگر آن لحظات بین رویدادهای بزرگ واقعاً بر هویت و زندگی ما تأثیرگذار بود؟ چه می شود اگر به جای تمرکز بر روی آن رویدادهای بزرگ، سرعت خود را کم کنیم و از آن لحظه های میانی لذت ببریم؟ <em>In-Between</em> (2013) شامل مجموعه ای از تجربیات تغییر دهنده زندگی جف گوینز است که در این بین اتفاق افتاده است و او مایل است با خوانندگان به اشتراک بگذارد.</p>', '2014-02-19 08:05:45', 4, 12, 'https://images.blinkist.io/images/books/530335606431310008270000/1_1/470.jpg', '/en/books/the-in-between-en/purchase', 'در-بین', '2023-01-26 19:06:13.265841', '2023-01-26 19:06:13.265841', NULL, 'The In-Between');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (212, 'افزایش', 'کوبی برایانت و تعقیب جاودانگی', 'کوبی برایانت و تعقیب جاودانگی', 22, 7, 'book', 't', '<p><em>ظهور </em> (2022) گزارشی صمیمی از سالهای اولیه زندگی حرفه ای کوبی برایانت ارائه می دهد. این اثر به بررسی تأثیراتی می‌پردازد که به برایانت کمک کرد تا به بسکتبال علاقه‌مند شود و نشان می‌دهد که چگونه استعداد قابل توجه او به تبدیل تیم دبیرستان حومه شهر به برنده مسابقات قهرمانی ایالتی کمک کرد. همچنین نشان می‌دهد که چگونه برایانت از دوران کودکی میراث خود را با دقت خلق کرده است، و نشان می‌دهد که در طول زندگی حرفه‌ای خود از هوش رسانه‌ای پیشرفته‌ای برخوردار است.</p>', '2022-06-17 00:00:00', 4, 210, 'https://images.blinkist.io/images/books/62a9f8e46cee070008d5256f/1_1/470.jpg', '/en/books/the-rise-en-mike-sielski/purchase', 'افزایش', '2023-01-26 19:06:17.580915', '2023-01-26 19:06:17.580915', NULL, 'The Rise');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (213, 'کار به سادگی', 'استقبال از قدرت سبک بهره وری شخصی شما', 'استقبال از قدرت سبک بهره وری شخصی شما', 11, 4, 'book', 't', '<p>در <em>Work Simply</em> (2015)، نویسنده کارسون تیت از تجربیات شغلی خود استفاده می‌کند تا به شما نشان دهد چگونه کارآمدتر شوید. با درک سبک بهره‌وری خود، می‌توانید کارها را سبک‌تر انجام دهید و به اهداف زندگی خود برسید.</p>', '2015-04-30 00:00:00', 4, 177, 'https://images.blinkist.io/images/books/553ffbf16233390007000000/1_1/470.jpg', '/en/books/work-simply-en/purchase', 'کار-به-سادگی', '2023-01-26 19:06:22.176602', '2023-01-26 19:06:22.176602', NULL, 'Work Simply');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (214, 'داده های کوچک', 'سرنخ های کوچکی که روندهای بزرگ را آشکار می کند', 'سرنخ های کوچکی که روندهای بزرگ را آشکار می کند', 12, 5, 'book', 't', '<p><em>Small Data</em> (2016) راهنمای استفاده از جزئیات جزئی در مورد زندگی افراد برای ارتباط با آنها و فروش آنها بر روی تصویر برند شما است. این پلک‌ها مشاهدات فرهنگ‌های سراسر جهان را در بر می‌گیرد تا به احساسات و خواسته‌هایی اشاره کند که به برندها کمک می‌کند تا نام‌های معروفی پیدا کنند.</p>', '2016-05-23 00:00:00', 4, 41, 'https://images.blinkist.io/images/books/573f039c679fb60003483ffb/1_1/470.jpg', '/en/books/small-data-en/purchase', 'داده-های-کوچک', '2023-01-26 19:06:26.751325', '2023-01-26 19:06:26.751325', NULL, 'Small Data');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (215, 'رسانه های اجتماعی مزخرف است', 'چرا رسانه های اجتماعی بیش از حد تبلیغاتی هستند', 'چرا رسانه های اجتماعی بیش از حد تبلیغاتی هستند', 18, 11, 'book', 'f', '<p><em>رسانه‌های اجتماعی مزخرف است</em>با افشای اقتصاد پشت آن و پرداختن به تصورات غلط رایج در مورد ارزش شبکه‌های اجتماعی برای تجارت، هیاهوی رسانه‌های اجتماعی را کاهش می‌دهد. در حالی که رسانه‌های اجتماعی می‌توانند دارایی ارزشمندی برای شرکت‌های خاصی باشند، <em>این</em> درمانی نیست که بازاریابان و متخصصان رسانه‌های اجتماعی از شما می‌خواهند آن را باور کنید!</p>', '2014-05-13 13:21:01', 4, 24, 'https://images.blinkist.io/images/books/53736c0764343600070b0100/1_1/470.jpg', '/en/books/social-media-is-bullshit-en/purchase', 'رسانه-های-اجتماعی-مزخرف-است', '2023-01-26 19:06:30.956964', '2023-01-26 19:06:30.956964', NULL, 'Social Media is Bullshit');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (216, '90 روز اول', 'استراتژی های اثبات شده برای رسیدن به سرعت سریعتر و هوشمندتر', 'استراتژی های اثبات شده برای رسیدن به سرعت سریعتر و هوشمندتر', 8, 2, 'book', 't', '<p><em>90 روز اول</em> (2006) دوره گذار حیاتی را برای هر رهبر تجاری که نقش جدیدی را برعهده می گیرد، ترسیم می کند. این استراتژی‌های جامع و عملی برای زنده ماندن – و شکوفایی – در سه ماه اول ارائه می‌کند.</p>', '2022-12-14 00:00:00', 3, 80, 'https://images.blinkist.io/images/books/63985be873bf6d0009f1af94/1_1/470.jpg', '/en/books/the-first-90-days-en/purchase', '90-روز-اول', '2023-01-26 19:06:35.284164', '2023-01-26 19:06:35.284164', NULL, 'The First 90 Days');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (217, 'چرا فریاد می زنیم؟', 'هنر اختلاف نظر مولد', 'هنر اختلاف نظر مولد', 23, 8, 'book', 't', '<p>در <em>چرا فریاد می زنیم؟ </em>(2019) باستر بنسون اختلاف نظر را تحقیر می کند. بنسون می‌گوید استدلال‌ها بد نیستند، مگر اینکه بی‌مولد باشند. علاوه بر این، یادگیری مخالفت به خوبی می تواند به شما کمک کند روابط شخصی خود را تقویت کنید، عملکرد حرفه ای بهتری داشته باشید و دیدگاه خود را نسبت به جهان گسترش دهید. </p>', '2019-12-26 00:00:00', 4, 97, 'https://images.blinkist.io/images/books/5dfcb1b16cee07000788a1fc/1_1/470.jpg', '/en/books/why-are-we-yelling-en/purchase', 'چرا-فریاد-می-زنیم؟', '2023-01-26 19:06:40.001513', '2023-01-26 19:06:40.001513', NULL, 'Why Are We Yelling?');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (218, 'بازخورد (و دیگر کلمات کثیف)', 'چرا از آن می ترسیم، چگونه آن را برطرف کنیم', 'چرا از آن می ترسیم، چگونه آن را برطرف کنیم', 22, 7, 'book', 't', '<p><em>بازخورد (و سایر کلمات کثیف)</em> (2019) یک راهنمای هوشمندانه و کاربردی برای چیزی است که بسیاری از ما از آن می ترسیم: جستجو، دادن و دریافت بازخورد. توضیح می‌دهد که چگونه می‌توانیم از واکنش‌های روان‌شناختی منفی بسیاری از ما نسبت به بازخورد اجتناب کنیم، و نکات عملی برای اینکه چگونه می‌توانیم یک فرهنگ بازخورد مثبت و مفید ایجاد کنیم، ارائه می‌کند. </p>', '2019-07-29 00:00:00', 4, 92, 'https://images.blinkist.io/images/books/5d3ccfee6cee070008098135/1_1/470.jpg', '/en/books/feedback-and-other-dirty-words-en/purchase', 'بازخورد-(و-دیگر-کلمات-کثیف)', '2023-01-26 19:06:44.460647', '2023-01-26 19:06:44.460647', NULL, 'Feedback (and Other Dirty Words)');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (219, 'ذهن ذن، ذهن مبتدی', 'گفتگوهای غیررسمی در مورد مدیتیشن و تمرین ذن', 'گفتگوهای غیررسمی در مورد مدیتیشن و تمرین ذن', 15, 7, 'book', 't', '<p><em>ذهن ذن، ذهن مبتدی </em>(1970) یک راهنمای آغازین برای ذن بودیسم است. این پلک ها توضیح می دهند که چگونه ذن نه تنها یک سیستم مراقبه، بلکه یک فلسفه زندگی است. آنها نحوه نشستن، نفس کشیدن و مشاهده را در حالی که ارتباط حیاتی با لحظه حال حفظ می کنند، توصیف می کنند.</p>', '2017-08-07 00:00:00', 4, 156, 'https://images.blinkist.io/images/books/5984e667b238e1000629007d/1_1/470.jpg', '/en/books/zen-mind-beginners-mind-en/purchase', 'ذهن-ذن،-ذهن-مبتدی', '2023-01-26 19:06:49.43169', '2023-01-26 19:06:49.43169', NULL, 'Zen Mind, Beginner’s Mind');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (220, 'خطوط خطا', 'خانواده های از هم پاشیده و چگونگی اصلاح آنها', 'خانواده های از هم پاشیده و چگونگی اصلاح آنها', 23, 8, 'book', 't', '<p><em>خطوط خطا</em>(2020) یک مشکل رایج را بررسی می کند که هیچ کس در مورد آن صحبت نمی کند: بیگانگی های خانوادگی. بیش از یک چهارم آمریکایی ها در طول زندگی خود از دوستان و خانواده خود دور شده اند که تأثیرات روانی ویرانگری دارد. <em>خطوط خطا</em> علل رایج بیگانگی را بررسی می‌کند و توصیه‌های شگفت‌انگیز و روشن‌گری در مورد چگونگی کار برای آشتی ارائه می‌دهد.</p>', '2021-04-07 00:00:00', 4, 29, 'https://images.blinkist.io/images/books/60645e806cee070007b3bc0a/1_1/470.jpg', '/en/books/fault-lines-en-karl-pillemer/purchase', 'خطوط-خطا', '2023-01-26 19:06:54.406768', '2023-01-26 19:06:54.406768', NULL, 'Fault Lines');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (221, 'منطق اکتشاف علمی', 'درباره معرفت شناسی علم مدرن', 'درباره معرفت شناسی علم مدرن', 19, 5, 'book', 't', '<p><em>منطق کشف علمی </em>(1935) اثر کلاسیک کارل پوپر در مورد هدف علم و دانش است. دانشمندان باید نظریه های خود را نه برای تأیید آنها، بلکه برای جعل آنها آزمایش کنند و از این رو دقیق تر شوند.</p>', '2022-05-08 00:00:00', 5, 395, 'https://images.blinkist.io/images/books/627514ab6cee07000829ee0a/1_1/470.jpg', '/en/books/the-logic-of-scientific-discovery-en/purchase', 'منطق-اکتشاف-علمی', '2023-01-26 19:06:59.33287', '2023-01-26 19:06:59.33287', NULL, 'The Logic of Scientific Discovery');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (222, 'خودت را شاد کن', 'بهترین نکات تمیز کردن برای براق کردن سینک و تسکین روح شما', 'بهترین نکات تمیز کردن برای براق کردن سینک و تسکین روح شما', 20, 8, 'book', 't', '<p><em>Hinch Yourself Happy </em>(2019) همه چیز در مورد جشن گرفتن جنبه سرگرم کننده نظافت است. در حالی که بسیاری از ما ممکن است به کارهای خانه به عنوان یک کار خسته کننده نگاه کنیم، خانم هینچ اینجاست تا اشتیاق خود را نسبت به آن به اشتراک بگذارد و به مردم کمک کند تا متوجه شوند که نباید از انجام آن اجتناب کرد یا به تأخیر انداخت. پس آماده شوید تا نگرش خود را بهار تمیز کنید و خانه خود را به یک واحه بی‌لکه و آرام تبدیل کنید.</p>', '2019-10-23 00:00:00', 3, 39, 'https://images.blinkist.io/images/books/5da9c86a6cee0700074e3b2e/1_1/470.jpg', '/en/books/hinch-yourself-happy-en/purchase', 'خودت-را-شاد-کن', '2023-01-26 19:07:04.464106', '2023-01-26 19:07:04.464106', NULL, 'Hinch Yourself Happy');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (223, 'میکروب های گم شده', 'چگونه استفاده بیش از حد از آنتی بیوتیک ها به طاعون مدرن ما دامن می زند؟', 'چگونه استفاده بیش از حد از آنتی بیوتیک ها به طاعون مدرن ما دامن می زند؟', 12, 6, 'book', 't', '<p><em>Missing Microbes</em>(2014) دنیای عجیب و غریب و میکروسکوپی درون روده شما را بررسی می کند. این نقش مهمی را که میکروب ها بازی می کنند - موجودات کوچکی که بدن شما را شاد و سالم نگه می دارند - روشن می کند و خطرات استفاده بیش از حد از آنتی بیوتیک ها را توضیح می دهد.</p>', '2016-03-11 00:00:00', 4, 27, 'https://images.blinkist.io/images/books/56e033f126ea84000700006d/1_1/470.jpg', '/en/books/missing-microbes-en/purchase', 'میکروب-های-گم-شده', '2023-01-26 19:07:09.337235', '2023-01-26 19:07:09.337235', NULL, 'Missing Microbes');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (224, 'الون ماسک', 'تسلا، اسپیس ایکس و تلاش برای آینده ای خارق العاده', 'تسلا، اسپیس ایکس و تلاش برای آینده ای خارق العاده', 23, 10, 'book', 't', '<p><em>الون ماسک </em>(2015) بینشی از شخصیت درخشان و دشوار نوآورترین کارآفرین امروزی به ما می دهد. این پلک ها که با جزئیات زندگی خصوصی آشفته او در هم آمیخته است، نشان می دهد که چرا ایلان ماسک اینقدر مصمم است تا نسل بشر را نجات دهد، چگونه تا کنون برای رسیدن به این هدف تلاش کرده است، و همچنین آنچه در افق بالقوه ثروتمندترین و قدرتمندترین مرد ماست وجود دارد. آینده.</p>', '2015-06-05 00:00:00', 4, 329, 'https://images.blinkist.io/images/books/556c53313236630007010000/1_1/470.jpg', '/en/books/elon-musk-en/purchase', 'الون-ماسک', '2023-01-26 19:07:14.448074', '2023-01-26 19:07:14.448074', NULL, 'Elon Musk');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (225, 'این کار را متوقف کنید', 'به خود خرابکاری پایان دهید و زندگی خود را پس بگیرید', 'به خود خرابکاری پایان دهید و زندگی خود را پس بگیرید', 14, 5, 'book', 't', '<p><em>Stop Doing That Sh*t</em> (2019) در ضمیر ناخودآگاه فرو می رود تا بررسی کند که چگونه و چرا خودمان را خراب می کنیم. کشف کنید که چرا فقط مثبت اندیشی یا تصمیم به تغییر به ما کمک نمی کند که واقعا خودمان را بهبود ببخشیم. سپس روشی را بیاموزید تا در نهایت بر افکار پنهانی که ناخودآگاه بر زندگی ما حاکم بوده اند غلبه کنیم. </p>', '2023-01-16 00:00:00', 4, 28, 'https://images.blinkist.io/images/books/63be94b982ae2f0008904680/1_1/470.jpg', '/en/books/stop-doing-that-sh-star-t-en/purchase', 'این-کار-را-متوقف-کنید', '2023-01-26 19:07:19.655322', '2023-01-26 19:07:19.655322', NULL, 'Stop Doing That Sh*t');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (261, 'رمانتیک تجاری', 'همه چیز را بده، هیچ چیز را کمیت نکن و چیزی بزرگتر از خودت خلق کن', 'همه چیز را بده، هیچ چیز را کمیت نکن و چیزی بزرگتر از خودت خلق کن', 13, 6, 'book', 't', '<p><em>The Business Romantic </em>(2015) یک رویکرد جایگزین برای انجام کسب‌وکار ارائه می‌کند که در آن شور و شوق، نه سود، بیشترین اهمیت را دارد. این پلک‌ها شما را از طریق استراتژی‌هایی راهنمایی می‌کنند که اعتبار و اتصال را به محل کار شما می‌آورند.</p>', '2016-01-01 00:00:00', NULL, 9, 'https://images.blinkist.io/images/books/5681bd45704a880007000069/1_1/470.jpg', '/en/books/the-business-romantic-en/purchase', 'رمانتیک-تجاری', '2023-01-26 19:10:31.609964', '2023-01-26 19:10:31.609964', NULL, 'The Business Romantic');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (226, 'بیش از حد کافی', 'ادعای فضا برای کسی که هستید (مهم نیست چه می گویند)', 'ادعای فضا برای کسی که هستید (مهم نیست چه می گویند)', 30, 10, 'book', 't', '<p><em>بیش از به اندازه کافی </em>(2019) بخشی از خاطرات، بخشی از مانیفست است. این به جزئیات پیروزی‌ها و زحمات سفر الین ولتروت به سوی موفقیت می‌پردازد، که از دوران کودکی او در شهر کوچک شروع می‌شود و با تصمیم او برای ترک صندلی خود به عنوان سردبیر <em>Teen Vogue</em> پایان می‌یابد. اما این بیش از یک داستان موفقیت الهام بخش است. همچنین حکمت، راهنمایی، هشدار و تشویق را برای هر کسی که تا به حال به آنها گفته شده است که به اندازه کافی کافی نیستند، ارائه می دهد. </p>', '2019-08-06 00:00:00', 4, 32, 'https://images.blinkist.io/images/books/5d4468396cee07000809a601/1_1/470.jpg', '/en/books/more-than-enough-en/purchase', 'بیش-از-حد-کافی', '2023-01-26 19:07:25.017502', '2023-01-26 19:07:25.017502', NULL, 'More Than Enough');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (227, '7 عادت کاری که باعث عملکرد بالا می شود', 'ارزش ها و رفتارهای سازمانی که باعث موفقیت می شوند', 'ارزش ها و رفتارهای سازمانی که باعث موفقیت می شوند', 22, 7, 'book', 't', '<p><em>7 عادت تجاری که باعث عملکرد بالا می‌شوند </em>(2014) ارزش‌ها و رفتارهای سازمانی که باعث موفقیت می‌شوند را مشخص می‌کند. این پلک‌ها چگونگی رقابت کسب‌وکارهای با عملکرد بالا را از رقبای خود نشان می‌دهند و توضیح می‌دهند که چگونه هر شرکتی می‌تواند فعالیت‌های روزمره خود را تغییر دهد تا سود نهایی خود را افزایش دهد. </p>', '2020-09-02 00:00:00', 4, 102, 'https://images.blinkist.io/images/books/5f4cb5fa6cee070006e1958e/1_1/470.jpg', '/en/books/7-business-habits-that-drive-high-performance-en/purchase', '7-عادت-کاری-که-باعث-عملکرد-بالا-می-شود', '2023-01-26 19:07:30.720903', '2023-01-26 19:07:30.720903', NULL, '7 Business Habits That Drive High Performance');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (228, 'آزمایشگاه لیدر', 'مهارت های اصلی برای تبدیل شدن به یک مدیر عالی، سریعتر', 'مهارت های اصلی برای تبدیل شدن به یک مدیر عالی، سریعتر', 21, 6, 'book', 't', '<p><em>آزمایشگاه رهبر </em>(2021) یک کتاب راهنما برای هر کسی است که می خواهد مهارت های مدیریتی خود را به سرعت بهبود بخشد. نویسندگان از طریق تحقیقات گسترده و آموزش بیش از 200000 مدیر، رفتارها و مهارت‌های اصلی را که همه مدیران بزرگ به اشتراک می‌گذارند، شناسایی کرده‌اند. آن‌ها نکات و روش‌هایی ساده و کاربردی ارائه می‌دهند که می‌توان برای نتایج سریع از آنها استفاده کرد.</p>', '2022-07-08 00:00:00', 5, 347, 'https://images.blinkist.io/images/books/62c5a1e46cee070008104e31/1_1/470.jpg', '/en/books/the-leader-lab-en/purchase', 'آزمایشگاه-لیدر', '2023-01-26 19:07:35.94886', '2023-01-26 19:07:35.94886', NULL, 'The Leader Lab');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (229, 'زندگی به دست آمده', 'پشیمانی را از دست بدهید، تحقق را انتخاب کنید', 'پشیمانی را از دست بدهید، تحقق را انتخاب کنید', 19, 5, 'book', 't', '<p><em>زندگی به دست آمده</em> (2022) یک سوال ساده و در عین حال عمیق را مطرح می کند: چرا یک زندگی با موفقیت مداوم اغلب باعث می شود احساس پوچی کنیم؟ پاسخ را می توان در حکمت بودایی باستان یافت: رسیدن به اهداف بلندپروازانه نیست، بلکه کار روی اهداف معنادار است که واقعاً تحقق و شادی را به همراه دارد. </p>', '2022-09-26 00:00:00', 4, 418, 'https://images.blinkist.io/images/books/632976386cee070008583c61/1_1/470.jpg', '/en/books/the-earned-life-en/purchase', 'زندگی-به-دست-آمده', '2023-01-26 19:07:42.808897', '2023-01-26 19:07:42.808897', NULL, 'The Earned Life');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (230, 'مغز', 'داستان تو', 'داستان تو', 17, 6, 'book', 't', '<p><em>مغز </em>(2015) آخرین تحقیقات عصب‌شناسی را باز می‌کند و به پرسش‌هایی می‌پردازد که هزاران سال است که فیلسوفان را گیج کرده است. چه چیزی یک شخصیت را تعریف می کند؟ چرا مدام تغییر می کند؟ آیا واقعیت واقعاً «آن بیرون» است یا ما فقط توهم داریم؟ این کتاب با ظاهری جذاب و ناراحت کننده، ایده شما را از زندگی عجیب و غریب ذهن بازتعریف می کند.</p>', '2019-02-15 00:00:00', 5, 317, 'https://images.blinkist.io/images/books/5c63d9c06cee0700078d6f2b/1_1/470.jpg', '/en/books/the-brain-en/purchase', 'مغز', '2023-01-26 19:07:47.599027', '2023-01-26 19:07:47.599027', NULL, 'The Brain');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (231, 'به مدیریت خوش آمدید', 'چگونه از یک عملکرد برتر به یک رهبر عالی تبدیل شوید', 'چگونه از یک عملکرد برتر به یک رهبر عالی تبدیل شوید', 17, 7, 'book', 't', '<p><em>به مدیریت خوش آمدید </em>(2020) راهنمای چگونگی انتقال هموار از یک مشارکت کننده با عملکرد برتر به تبدیل شدن به یک رهبر تیم است. با استفاده از مطالعات موردی، حکایات شخصی و مصاحبه ها، نشان می دهد که رهبری موثر در طیف وسیعی از زمینه ها چگونه به نظر می رسد. همچنین یک چارچوب عملی در مورد چگونگی رشد خود به یک رهبر و هدایت تیم خود به موفقیت پایدار ارائه می دهد.</p>', '2021-01-27 00:00:00', 5, 200, 'https://images.blinkist.io/images/books/600aa5706cee070007562cda/1_1/470.jpg', '/en/books/welcome-to-management-en/purchase', 'به-مدیریت-خوش-آمدید', '2023-01-26 19:07:52.388604', '2023-01-26 19:07:52.388604', NULL, 'Welcome to Management');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (232, 'واژن', 'یک آموزش مجدد', 'یک آموزش مجدد', 30, 9, 'book', 't', 'هدف <p><em>واژن </em> (2019) ارائه درک بیشتر از اندام‌های جنسی زنانه است که توسط علم، آموزش و فرهنگ به طور کلی مورد سوء تفاهم قرار گرفته و نادیده گرفته شده‌اند. لین انرایت از افشای افسانه همیشگی پرده بکارت گرفته تا افشای نیروهای اقتصادی و اجتماعی که قاعدگی شما را به یک کابوس تبدیل می‌کند، همه چیزهایی را که درباره سلامت جنسی زنان به ما یاد نداده‌اند را بررسی و روشن می‌کند.</p>', '2020-08-28 00:00:00', 4, 112, 'https://images.blinkist.io/images/books/5f43d17e6cee070006d1dc98/1_1/470.jpg', '/en/books/vagina-en/purchase', 'واژن', '2023-01-26 19:07:57.453936', '2023-01-26 19:07:57.453936', NULL, 'Vagina');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (776, 'وعده های کاغذی', 'پول، بدهی و نظم نوین جهانی', 'پول، بدهی و نظم نوین جهانی', 13, 7, 'book', 'f', '<p><em>وعده‌های کاغذی </em>نگاهی هشیارانه از ماهیت پول، بحران مالی اخیر جهانی و معنای نگرش ما در مورد بدهی برای نسل‌های آینده ارائه می‌دهد.</p>', '2015-02-18 00:00:00', 4, 13, 'https://images.blinkist.io/images/books/54e36d08303764000a600000/1_1/470.jpg', '/en/books/paper-promises-en/purchase', 'وعده-های-کاغذی', '2023-01-26 20:14:52.650783', '2023-01-26 20:14:52.650783', NULL, 'Paper Promises');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (233, 'افراد باهوش باید چیزهایی بسازند', 'چگونه فرهنگ موفقیت خود را بازیابی کنیم، مسیری برای کارآفرینان بسازیم و مشاغل جدید در آمریکا ایجاد کنیم', 'چگونه فرهنگ موفقیت خود را بازیابی کنیم، مسیری برای کارآفرینان بسازیم و مشاغل جدید در آمریکا ایجاد کنیم', 19, 8, 'book', 't', '<p><em>هوشمند</em> <em>افراد</em> <em>باید</em> <em>ساخت</em> <em>چیزها</em> پیامدهای خطرناک دانش‌آموزان برتر را بررسی می‌کند. انتخاب های شغلی در ایالات متحده، و راه حل های عملی برای بازنشانی مسیر کشور به سمت رفاه با تشویق دانش آموزان به اتخاذ نگرش کارآفرینی ارائه می دهد. در طول مسیر، نویسنده توصیه‌های محکمی برای کارآفرینان نوپا در اولین ماجراجویی خود در تجارت ارائه می‌کند.</p>', '2014-07-01 00:00:00', 5, 35, 'https://images.blinkist.io/images/books/53b071bf3435310007090000/1_1/470.jpg', '/en/books/smart-people-should-build-things-en/purchase', 'افراد-باهوش-باید-چیزهایی-بسازند', '2023-01-26 19:08:02.64439', '2023-01-26 19:08:02.64439', NULL, 'Smart People Should Build Things');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (234, '30 راه برای راه اندازی مجدد بدن', 'کتابچه راهنمای کاربر کامل برای دریافت بهترین نتیجه از بدن انسان', 'کتابچه راهنمای کاربر کامل برای دریافت بهترین نتیجه از بدن انسان', 10, 4, 'book', 't', '<p><em>30 راه برای راه اندازی مجدد بدن</em> (2015) کلیدهای ترمیم و بازسازی بدن را در اختیار شما قرار می دهد تا بتوانید اهداف سلامتی و تناسب اندام خود را به سطح بعدی ارتقا دهید. این پلک ها اهمیت سلامت دستگاه گوارش، ورزش سبک و روتین های جامد را توضیح می دهند. آماده باشید تا ایده های خود را در مورد رژیم غذایی و ورزش به چالش بکشید.</p>', '2016-06-06 00:00:00', 4, 367, 'https://images.blinkist.io/images/books/575410843ead360003c8e752/1_1/470.jpg', '/en/books/30-ways-to-reboot-your-body-en/purchase', '30-راه-برای-راه-اندازی-مجدد-بدن', '2023-01-26 19:08:07.552411', '2023-01-26 19:08:07.552411', NULL, '30 Ways to Reboot Your Body');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (235, 'فضا سازی', 'چگونه زمان را مدیریت کنیم و تمرکز، بهره وری و موفقیت را پیدا کنیم', 'چگونه زمان را مدیریت کنیم و تمرکز، بهره وری و موفقیت را پیدا کنیم', 26, 9, 'book', 't', '<p><em>ایجاد فضا</em> (2018) مجموعه ای از ابزارها و روش های بسیاری است که درک دریپر در نقش خود به عنوان مربی برای رهبران کسب و کار در سراسر جهان استفاده می کند. دراپر به عنوان یک روانشناس مجرب و مشاور مورد نیاز، دانش خود را تقویت کرده است و سخاوتمندانه در به اشتراک گذاشتن آنچه در طول سال ها آموخته و مشاهده کرده است، عمل می کند. چه مدیر عامل باشید یا یک کارآموز، یا جایی در این بین، بینش های ارزشمند دریپر به شما کمک می کند تا شغلی متعادل و موفق ایجاد کنید.</p>', '2019-01-17 00:00:00', 5, 110, 'https://images.blinkist.io/images/books/5c3c5c006cee0700074bfc2c/1_1/470.jpg', '/en/books/create-space-en/purchase', 'فضا-سازی', '2023-01-26 19:08:12.266588', '2023-01-26 19:08:12.266588', NULL, 'Create Space');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (236, 'نام تجاری مخل', 'چگونه در زمان تغییر برنده شویم', 'چگونه در زمان تغییر برنده شویم', 21, 6, 'book', 't', '<p><em>برندسازی مخرب</em> (2019) اهمیت و ماهیت برندسازی را در دنیای مخرب و مبتنی بر فناوری ما بررسی می‌کند. با تکیه بر بهترین نمونه‌های کلاس و راهنماهای عملی، این طرحی واضح برای هر کسی است که می‌خواهد از یک نام تجاری قوی برای به دست آوردن نتایج تجاری استفاده کند.</p>', '2020-03-26 00:00:00', 4, 160, 'https://images.blinkist.io/images/books/5e79e3ba6cee070007e0d941/1_1/470.jpg', '/en/books/disruptive-branding-en/purchase', 'نام-تجاری-مخل', '2023-01-26 19:08:17.275494', '2023-01-26 19:08:17.275494', NULL, 'Disruptive Branding');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (237, '18 دقیقه', 'تمرکز خود را پیدا کنید، حواس پرتی را به دست آورید و کارهای درست را انجام دهید', 'تمرکز خود را پیدا کنید، حواس پرتی را به دست آورید و کارهای درست را انجام دهید', 11, 5, 'book', 't', '<p><em>18 دقیقه</em> (2011) راهنمای مفیدی برای انجام کارها با تمرکز بر کار معنی دار، رسیدن به اهداف و جلوگیری از حواس پرتی است. این پلک‌ها نشان می‌دهند که چگونه می‌توانید نوع کاری را که برای شما مناسب است شناسایی کنید و چگونه در مسیر باقی بمانید و به اهداف خود ضربه بزنید.</p>', '2016-09-16 00:00:00', 4, 219, 'https://images.blinkist.io/images/books/57d6696e08c9270003b19200/1_1/470.jpg', '/en/books/18-minutes-en/purchase', '18-دقیقه', '2023-01-26 19:08:22.881631', '2023-01-26 19:08:22.881631', NULL, '18 Minutes');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (238, 'نیرویی برای خیر', 'چشم انداز دالایی لاما برای بشریت', 'چشم انداز دالایی لاما برای بشریت', 26, 12, 'book', 't', '<p><em>A Force For Good </em>(2015) نشان می دهد که چگونه می توانید افکار منفی خود را با اقدامات مثبت عوض کنید. با نگاهی دقیق‌تر به خرد و بینش دالایی لاما، این پلک‌ها توضیح می‌دهند که چگونه افراد مثبت‌نگر با هم می‌توانند نیروی جهانی خوبی را تشکیل دهند و از طریق شفقت متقابل، در دنیای ما تغییر ایجاد کنند.</p>', '2015-11-04 00:00:00', 4, 45, 'https://images.blinkist.io/images/books/563770c262346500074a0000/1_1/470.jpg', '/en/books/a-force-for-good-en/purchase', 'نیرویی-برای-خیر', '2023-01-26 19:08:26.397079', '2023-01-26 19:08:26.397079', NULL, 'A Force for Good');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (239, 'پرورش قابیل', 'حفاظت از زندگی عاطفی پسران', 'حفاظت از زندگی عاطفی پسران', 19, 8, 'book', 't', '<p><em>تربیت قابیل</em> (1999) توضیح می‌دهد که چگونه پسرها باید در جامعه‌ای که مملو از افکار نادرست درباره مردانگی است و پر از همکلاسی‌های بی‌رحمانه‌ای است که آماده حمله به هر نشانه‌ای از ضعف هستند، حرکت کنند. کشف کنید که چگونه این شرایط می تواند باعث ایجاد کوتاهی عاطفی و خودکشی در مردان جوان شود و دریابید که قبل از اینکه خیلی دیر شود برای بهبود وضعیت آنها چه کاری می توان انجام داد.</p>', '2016-10-21 00:00:00', 4, 40, 'https://images.blinkist.io/images/books/5800df32230ff80003a1b856/1_1/470.jpg', '/en/books/raising-cain-en/purchase', 'پرورش-قابیل', '2023-01-26 19:08:31.603659', '2023-01-26 19:08:31.603659', NULL, 'Raising Cain');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (240, 'چتر نجات شما چه رنگی است؟', 'کتابچه راهنمای عملی برای شکارچیان شغل و افراد تغییر دهنده شغل', 'کتابچه راهنمای عملی برای شکارچیان شغل و افراد تغییر دهنده شغل', 15, 6, 'book', 't', '<p><em>چتر نجات شما چه رنگی است؟ </em>(2017) یک راهنمای عملی است که به شما کمک می کند شغل مورد نظر خود را پیدا کنید و شغل خود را تغییر دهید. از آنجایی که برای اولین بار در سال 1970 منتشر شد، این کتاب یک راهنما برای هر شکارچی شغلی بوده است، همراه با نکاتی در مورد چگونگی تقویت مهارت های مصاحبه خود و مذاکره برای دستمزد خوب. این جدیدترین نسخه همچنین پیشنهادهای ارزشمندی برای موفقیت در دنیای دیجیتال امروزی دارد.</p>', '2017-08-16 00:00:00', 4, 61, 'https://images.blinkist.io/images/books/59909ca2b238e100050b8876/1_1/470.jpg', '/en/books/what-color-is-your-parachute-en/purchase', 'چتر-نجات-شما-چه-رنگی-است؟', '2023-01-26 19:08:37.374764', '2023-01-26 19:08:37.374764', NULL, 'What Color is Your Parachute?');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (241, 'Zoobiquity', 'ارتباط شگفت انگیز بین سلامت انسان و حیوانات', 'ارتباط شگفت انگیز بین سلامت انسان و حیوانات', 19, 11, 'book', 'f', '<p><em>Zoobiquity</em> شباهت‌های صمیمی بین انسان و حیوانات دیگر را با بررسی موضوعاتی مانند تمایلات جنسی، سلامت و رشد روانی توصیف می‌کند. این نشان می‌دهد که چگونه ما به‌عنوان انسان، می‌توانیم با افزایش درک خود از حیواناتی که سیاره‌مان را با آنها اشتراک داریم، چیزهای زیادی به دست آوریم.</p>', '2014-09-02 00:00:00', 5, 11, 'https://images.blinkist.io/images/books/5406ed9b3933310008c70000/1_1/470.jpg', '/en/books/zoobiquity-en/purchase', 'Zoobiquity', '2023-01-26 19:08:42.083338', '2023-01-26 19:08:42.083338', NULL, 'Zoobiquity');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (242, 'کد احساسات', 'چگونه احساسات به دام افتاده خود را برای سلامتی، عشق و شادی فراوان رها کنید', 'چگونه احساسات به دام افتاده خود را برای سلامتی، عشق و شادی فراوان رها کنید', 25, 9, 'book', 't', '<p><em>رمز عاطفه</em>(2007) رویکردی جدید و توانمند برای درمان خود و دیگران ارائه می دهد. از طریق شواهد علمی، تجربیات دست اول فراوان، و احترام زیادی برای نیروهای پرانرژی و معنوی که همه ما را فراتر می‌برند و متحد می‌کنند،<em>رمز عواطف </em>روشی انقلابی برای یافتن و رهاسازی احساسات به دام افتاده ارائه می‌کند. با این کار به خود فرصت می دهیم تا از محدودیت های خود فراتر برویم و شکوفا شویم.</p>', '2020-04-01 00:00:00', 4, 168, 'https://images.blinkist.io/images/books/5e7e1f6d6cee07000723f87f/1_1/470.jpg', '/en/books/the-emotion-code-en/purchase', 'کد-احساسات', '2023-01-26 19:08:46.865719', '2023-01-26 19:08:46.865719', NULL, 'The Emotion Code');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (243, 'به دل خود اعتماد نکنید', 'استفاده از داده ها برای به دست آوردن آنچه واقعاً در زندگی می خواهید', 'استفاده از داده ها برای به دست آوردن آنچه واقعاً در زندگی می خواهید', 18, 5, 'book', 't', '<p><em>به دل خود اعتماد نکنید </em>(2022) این حکمت آزموده شده در مورد اعتماد به دل خود را به ذهن خود تبدیل می کند. نه تنها اعتماد به غریزه درونی‌تان اغلب شما را به تصمیم <em>اشتباه </em>می‌کشاند، بلکه روشی کاملاً بی‌خبر وجود دارد تا اطمینان حاصل شود که تصمیم <em>درست </em> را می‌گیرید – تجزیه و تحلیل داده‌های موجود و اقدام بر اساس آن. آن.</p>', '2022-10-02 00:00:00', 4, 206, 'https://images.blinkist.io/images/books/63357f946cee0700081b3b01/1_1/470.jpg', '/en/books/dont-trust-your-gut-en/purchase', 'به-دل-خود-اعتماد-نکنید', '2023-01-26 19:08:51.688619', '2023-01-26 19:08:51.688619', NULL, 'Don’t Trust Your Gut');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (244, 'خانه گوچی', 'داستانی هیجان انگیز از قتل، جنون، زرق و برق و طمع', 'داستانی هیجان انگیز از قتل، جنون، زرق و برق و طمع', 38, 9, 'book', 't', '<p><em>خانه گوچی</em> (2000) داستان واقعی ظهور شهاب‌سنگ خانواده گوچی - و نزدیک به سقوط - را در دنیای مد لباس بازگو می‌کند. پر از پیچ و تاب‌های داستانی ناشی از اشتیاق و طمع، پشت نمای براق این برند می‌رود تا نشان دهد که هر چیزی که می‌درخشد طلا نیست.</p>', '2022-02-08 00:00:00', 5, 144, 'https://images.blinkist.io/images/books/620232f06cee0700080875a8/1_1/470.jpg', '/en/books/house-of-gucci-en/purchase', 'خانه-گوچی', '2023-01-26 19:08:57.193938', '2023-01-26 19:08:57.193938', NULL, 'House of Gucci');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (245, 'طراحی زندگی شما', 'چگونه یک زندگی خوب و شاد بسازیم', 'چگونه یک زندگی خوب و شاد بسازیم', 14, 6, 'book', 't', '<p><em>طراحی زندگی شما </em>(2016) در مورد کنترل زندگی خود با ایجاد برنامه ای است که یک روال 9 تا 5 بدون الهام را از بین می برد و شغلی را که واقعاً دوست دارید آغاز می کند. . توصیه‌ها و تمرین‌هایی خواهید یافت که شما را به سمت تماس واقعی‌تان راهنمایی می‌کنند، همراه با ایده‌های پیشرو که محدودیت‌های مشاوره شغلی سنتی را به چالش می‌کشند.</p>
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (246, '168 ساعت', 'شما بیشتر از آنچه فکر می کنید زمان دارید', 'شما بیشتر از آنچه فکر می کنید زمان دارید', 21, 8, 'book', 't', '<p><em>168 ساعت </em>(2010) یک استراتژی انقلابی برای مدیریت زمان شما ارائه می دهد. نویسنده لورا واندرکام کشف کرده است که افراد موفق طرز فکر منحصر به فردی دارند، طرز فکری که به آنها کمک می کند هر چیزی را که برایشان ارزش قائل هستند در هفته خود جای دهند. با یادگیری مدیریت زمان مانند آنها، می توانید خود را از مشغله های روزانه رها کنید و بر آنچه واقعاً مهم است تمرکز کنید. </p>', '2020-11-04 00:00:00', 4, 370, 'https://images.blinkist.io/images/books/5f9be7a26cee070006ca164b/1_1/470.jpg', '/en/books/168-hours-en/purchase', '168-ساعت', '2023-01-26 19:09:09.209549', '2023-01-26 19:09:09.209549', NULL, '168 Hours');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (247, 'رژیم غذایی وحشی', 'برای سوزاندن چربی، غلبه بر هوس و کاهش 20 پوندی در 40 روز فراتر از پالئو بروید', 'برای سوزاندن چربی، غلبه بر هوس و کاهش 20 پوندی در 40 روز فراتر از پالئو بروید', 12, 5, 'book', 't', '<p><em>رژیم غذایی وحشی</em> (2015) راهنمای شما برای استفاده از بیولوژی چربی سوزی برای کاهش وزن است. این پلک‌ها توضیح می‌دهند که چه چیزی باعث می‌شود ورزش با شدت بالا، رژیم‌های گیاهی، غنی از پروتئین و هیدراتاسیون موثر باشد، و هک‌های سلامتی را در اختیار شما قرار می‌دهد که می‌توانید فوراً شروع به استفاده از آنها کنید.</p>', '2017-05-08 00:00:00', 4, 131, 'https://images.blinkist.io/images/books/590e586cb238e1000792caff/1_1/470.jpg', '/en/books/the-wild-diet-en/purchase', 'رژیم-غذایی-وحشی', '2023-01-26 19:09:14.598149', '2023-01-26 19:09:14.598149', NULL, 'The Wild Diet');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (248, 'خیره به پایین گرگ', '7 تعهد رهبری که تیم های نخبه را شکل می دهد', '7 تعهد رهبری که تیم های نخبه را شکل می دهد', 17, 7, 'book', 't', '<p><em>Staring Down the Wolf </em>(2020) یک راهنمای رهبری برای تشکیل تیم های بزرگ در مواجهه با ناملایمات است. با تکیه بر آموزه‌های نیروی دریایی، یکی از نخبه‌ترین واحدهای نظامی جهان، نشان می‌دهد که برای فرماندهی یک تیم نخبه چه چیزی لازم است.</p>', '2021-06-18 00:00:00', 4, 278, 'https://images.blinkist.io/images/books/60c32d166cee070008703e8a/1_1/470.jpg', '/en/books/staring-down-the-wolf-en/purchase', 'خیره-به-پایین-گرگ', '2023-01-26 19:09:18.803322', '2023-01-26 19:09:18.803322', NULL, 'Staring Down the Wolf');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (249, 'مردان موشک', 'ادیسه جسورانه آپولو 8 و فضانوردانی که اولین سفر انسان به ماه را انجام دادند', 'ادیسه جسورانه آپولو 8 و فضانوردانی که اولین سفر انسان به ماه را انجام دادند', 24, 8, 'book', 't', '<p><em>Rocket Men</em> (2018) داستان جذاب آپولو 8 را روایت می‌کند، مأموریت ماه که ایالات متحده را در مسابقه فضایی از اتحاد جماهیر شوروی جلوتر قرار داد. در سال 1968، ناسا تصمیم گرفت همه چیز را به خطر بیندازد. آنها باید شوروی را به ماه می بردند، و آنها فقط چهار ماه فرصت داشتند تا این کار را انجام دهند.</p>', '2018-07-05 00:00:00', 5, 14, 'https://images.blinkist.io/images/books/5b3abab1b238e100071d7d78/1_1/470.jpg', '/en/books/rocket-men-en/purchase', 'مردان-موشک', '2023-01-26 19:09:24.714629', '2023-01-26 19:09:24.714629', NULL, 'Rocket Men');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (250, 'آزمایش ایده های تجاری', 'راهنمای میدانی برای آزمایش سریع', 'راهنمای میدانی برای آزمایش سریع', 24, 7, 'book', 't', '<p><em>تست ایده‌های کسب‌وکار </em>(2021) بررسی می‌کند که چگونه کارآفرینان می‌توانند از آزمایش استفاده کنند تا به سرمایه‌گذاری جدید خود بهترین شانس موفقیت را بدهند. منطق پشت آزمایش را تشریح می کند و چارچوبی را برای تصمیم گیری در مورد چگونگی ادامه شرح می دهد. </p>', '2021-06-03 00:00:00', 4, 73, 'https://images.blinkist.io/images/books/60b4e4c16cee070007c62a6b/1_1/470.jpg', '/en/books/testing-business-ideas-en/purchase', 'آزمایش-ایده-های-تجاری', '2023-01-26 19:09:30.119784', '2023-01-26 19:09:30.119784', NULL, 'Testing Business Ideas');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (251, 'تست A/B', 'قدرتمندترین راه برای تبدیل کلیک ها به مشتری', 'قدرتمندترین راه برای تبدیل کلیک ها به مشتری', 16, 7, 'book', 't', '<p>همه ما می دانیم که اینترنت روش کسب و کار ما را تغییر داده است. به هر حال، امروزه تقریباً هر شرکتی یک وب‌سایت دارد، اما چه تعداد از کسب‌وکارها موفق به بهینه‌سازی مؤثر حضور آنلاین خود می‌شوند؟ خب، <em>آزمایش A/B</em> به شما نشان می‌دهد که چگونه وب‌سایت خود را از طریق آزمایش و ارزیابی ساده توسعه و اصلاح کنید - همه اینها برای جذب مشتریان بیشتر و افزایش درآمد شما.</p>', '2015-01-16 00:00:00', 4, 55, 'https://images.blinkist.io/images/books/54b3b2cc64663300095f0000/1_1/470.jpg', '/en/books/a-slash-b-testing-en/purchase', 'تست-A/B', '2023-01-26 19:09:35.372438', '2023-01-26 19:09:35.372438', NULL, 'A/B Testing');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (252, 'چگونه افراد باهوش را رهبری کنیم', 'رهبری برای حرفه ای ها', 'رهبری برای حرفه ای ها', 22, 7, 'book', 't', '<p><em>چگونه افراد باهوش را رهبری کنیم </em>(2019) توصیه های عملی برای رهبری در چشم انداز جهانی در حال تغییر امروزی ارائه می دهد. در این پلک‌ها، رهبران می‌توانند بیاموزند که چگونه یک تیم پویا را پرورش دهند که هم چالش برانگیز باشد و هم الهام‌بخش باشد.</p>', '2020-08-12 00:00:00', 4, 67, 'https://images.blinkist.io/images/books/5f2d3d026cee07000669b67c/1_1/470.jpg', '/en/books/how-to-lead-smart-people-en/purchase', 'چگونه-افراد-باهوش-را-رهبری-کنیم', '2023-01-26 19:09:40.705573', '2023-01-26 19:09:40.705573', NULL, 'How to Lead Smart People');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (253, 'پیش بینی کنید', 'هنر رهبری با نگاه کردن به آینده', 'هنر رهبری با نگاه کردن به آینده', 15, 7, 'book', 't', '<p><em>پیش بینی </em>(2015) نشان می دهد که برای تبدیل شدن به یک رهبر رویایی چه چیزی لازم است. از سه رکن رهبری ارسطو گرفته تا شیوه‌ها و طرز فکرهایی که توانایی‌های رهبری شما را تقویت می‌کنند، این پلک‌ها نشان می‌دهند که داشتن چشم‌انداز چیزی نیست که شما با آن متولد شده‌اید، بلکه چیزی است که روی آن کار می‌کنید.</p>', '2015-06-04 00:00:00', 4, 26, 'https://images.blinkist.io/images/books/556c718c3236630007ad0000/1_1/470.jpg', '/en/books/anticipate-en/purchase', 'پیش-بینی-کنید', '2023-01-26 19:09:46.095897', '2023-01-26 19:09:46.095897', NULL, 'Anticipate');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (269, 'قدرت انتخاب', 'پذیرش اثربخشی برای هدایت شغلی شما', 'پذیرش اثربخشی برای هدایت شغلی شما', 20, 6, 'book', 't', '<p><em>قدرت انتخاب </em>(2020) راهنمای حرفه ای هایی است که در حوزه کاری خود نمایندگی کمتری دارند یا در تلاش هستند تا با فرهنگ محل کار خود سازگار شوند. با تکیه بر مجموعه‌ای عملی از اصول، نشان می‌دهد که چگونه هر کسی می‌تواند با پذیرش مسئولیت شخصی، مشکلات را در محل کار پشت سر بگذارد. همچنین شامل نکاتی در مورد چگونگی بهبود اعتماد به نفس و بسیج روابط حرفه ای برای رشد شغلی طولانی مدت است.</p>', '2021-10-21 00:00:00', 4, 166, 'https://images.blinkist.io/images/books/616d2b596cee07000730d490/1_1/470.jpg', '/en/books/the-power-of-choice-en/purchase', 'قدرت-انتخاب', '2023-01-26 19:11:20.232011', '2023-01-26 19:11:20.232011', NULL, 'The Power of Choice');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (254, 'فرمول زمان آزاد', 'یافتن شادی، تمرکز و بهره وری مهم نیست که چقدر مشغول هستید', 'یافتن شادی، تمرکز و بهره وری مهم نیست که چقدر مشغول هستید', 21, 8, 'book', 't', '<p><em>فرمول زمان آزاد</em> (2018) یک راهنمای عملی برای مدیریت بهتر زمان است که به مشکلی که همه ما با آن دست و پنجه نرم کرده‌ایم رسیدگی می‌کند: احساس اینکه ساعات کافی در روز وجود ندارد. برای انجام کارهایی که بیشترین ارزش را داریم این پلک‌ها نشان می‌دهند که مشکل معمولاً خود زمان نیست، بلکه درک است. جف سندرز استدلال می‌کند زمانی که مفهوم زمان خود را مجدداً تنظیم کنیم، می‌توانیم اولویت‌های واقع بینانه تعیین کنیم و از روزهای خود بیشترین بهره را ببریم.</p>', '2019-03-19 00:00:00', 4, 176, 'https://images.blinkist.io/images/books/5c8b576b6cee070007e09ad6/1_1/470.jpg', '/en/books/the-free-time-formula-en/purchase', 'فرمول-زمان-آزاد', '2023-01-26 19:09:51.389034', '2023-01-26 19:09:51.389034', NULL, 'The Free-Time Formula');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (255, 'چگونه کتاب بخوانیم', 'راهنمای کلاسیک برای خواندن هوشمند', 'راهنمای کلاسیک برای خواندن هوشمند', 15, 8, 'book', 't', '<p>از زمانی که <em>چگونه یک کتاب بخوانیم </em> برای اولین بار در سال 1940 منتشر شد، برگه خالی کاغذی که هنگام شروع مقاله یا گزارش در مقابل شما قرار می گیرد با مکان نما چشمک زن در یک سند Word خالی جایگزین شده است. مهم نیست: این کتاب پرفروش کلاسیک، که در سال 1972 بازبینی شده است، هنوز هم یک راهنمای عالی برای مقابله با یک لیست طولانی خواندن، استخراج تمام اطلاعات مرتبط و سازماندهی نتیجه گیری شماست. با این رویکرد مؤثر برای خواندن و درک متون از همه نوع، رئیس کتاب‌ها باشید.</p>', '2015-11-11 00:00:00', 4, 283, 'https://images.blinkist.io/images/books/564079743866330007420000/1_1/470.jpg', '/en/books/how-to-read-a-book-en/purchase', 'چگونه-کتاب-بخوانیم', '2023-01-26 19:09:56.710457', '2023-01-26 19:09:56.710457', NULL, 'How to Read a Book');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (256, 'آگاه', 'علم و عمل حضور', 'علم و عمل حضور', 20, 8, 'book', 't', '<p><em>آگاه</em> (2018) نگاهی بی‌معنی و مبتنی بر تجربی به رشته‌ای است که به طور سنتی بیشتر با راهبان مرتبط است تا پزشکان: مدیتیشن. با تکیه بر آخرین تحقیقات علوم اعصاب، روانپزشک دانیل جی سیگل نشان می دهد که تمرکز حواس بسیار بیشتر از آخرین هک سبک زندگی است - به سلامت روان و جسم شما کمک می کند. پاداش اضافه شده؟ همچنین تجربه شما از زندگی را معنادارتر، شادتر و عمیق تر می کند!</p>', '2018-12-24 00:00:00', 5, 174, 'https://images.blinkist.io/images/books/5c1eb6276cee070008e79f42/1_1/470.jpg', '/en/books/aware-en/purchase', 'آگاه', '2023-01-26 19:10:02.679742', '2023-01-26 19:10:02.679742', NULL, 'Aware');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (257, 'ساده فکر کن', 'چگونه رهبران باهوش پیچیدگی را شکست می دهند', 'چگونه رهبران باهوش پیچیدگی را شکست می دهند', 24, 8, 'book', 't', '<p><em>Think Simple</em>(2020) به ما نشان می دهد که چگونه سادگی کلید کسب و کارهای موفق است، از هیوندای گرفته تا Whole Foods. در اینجا، کن سگال، کارشناس اپل، به ما می آموزد که چگونه با پیچیدگی مبارزه کنیم و روی آنچه واقعاً در یک سازمان برنده اهمیت دارد تمرکز کنیم.</p>', '2020-09-14 00:00:00', 4, 243, 'https://images.blinkist.io/images/books/5f5b38cf6cee070006a80b61/1_1/470.jpg', '/en/books/think-simple-en/purchase', 'ساده-فکر-کن', '2023-01-26 19:10:08.129809', '2023-01-26 19:10:08.129809', NULL, 'Think Simple');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (258, 'روند شناسی', 'ایجاد مزیت از طریق بازاریابی زمان واقعی مبتنی بر داده', 'ایجاد مزیت از طریق بازاریابی زمان واقعی مبتنی بر داده', 16, 9, 'book', 'f', '<p><em>Trendology </em>(2014) بررسی می‌کند که چگونه برندها می‌توانند از رسانه‌های اجتماعی مانند توییتر برای برقراری ارتباط مستقیم با پایگاه مشتریان خود استفاده کنند و می‌توانند از بهره‌برداری از روندها در گفتگوی رسانه‌های اجتماعی بهره ببرند. علاوه بر تئوری رسانه های اجتماعی، <em>Trendology </em>راهنمای گام به گام در مورد چگونگی ایجاد یک برنامه رسانه اجتماعی موفق و موفقیت در بازاریابی بلادرنگ ارائه می دهد.</p>', '2015-01-28 00:00:00', NULL, 8, 'https://images.blinkist.io/images/books/54c651b837323900093a0000/1_1/470.jpg', '/en/books/trendology-en/purchase', 'روند-شناسی', '2023-01-26 19:10:14.259807', '2023-01-26 19:10:14.259807', NULL, 'Trendology');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (259, 'بر هم زدن بازی', 'از برانکس تا نوک نینتندو', 'از برانکس تا نوک نینتندو', 19, 6, 'book', 't', '<p><em>اختلال در بازی</em> (2022) داستان الهام‌بخش صعود رجی فیلس‌آیمه به صدر صنعت بازی‌های ویدیویی را روایت می‌کند – سفر او از بزرگ شدن در دوران کودکی در برانکس تا تبدیل شدن به او را ترسیم می‌کند. رئیس و مدیر عامل نینتندو آمریکا. در طول مسیر، درس هایی را که او در مورد رهبری و ترسیم مسیر شغلی آموخته به اشتراک می گذارد.</p>', '2022-09-06 00:00:00', 4, 178, 'https://images.blinkist.io/images/books/630dda776cee070008eea5a6/1_1/470.jpg', '/en/books/disrupting-the-game-en/purchase', 'بر-هم-زدن-بازی', '2023-01-26 19:10:19.720745', '2023-01-26 19:10:19.720745', NULL, 'Disrupting the Game');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (260, 'جملات قدرتمند برای برخورد با افراد مشکل', 'بیش از 325 کلمه و عبارات آماده برای کار با شخصیت های چالش برانگیز', 'بیش از 325 کلمه و عبارات آماده برای کار با شخصیت های چالش برانگیز', 18, 8, 'book', 't', '<p><em>عبارات قدرتمند برای برخورد با افراد مشکل</em> (2013) تاکتیک های عملی را برای هدایت مکالمات سخت در محل کار ارائه می دهد. همراه با بیش از 325 عبارت، شامل ده ها نمونه مکالمه است که عبارات را در عمل نشان می دهد.</p>', '2023-01-12 00:00:00', 4, 49, 'https://images.blinkist.io/images/books/63bd05f3e8fd3c00080b3acb/1_1/470.jpg', '/en/books/powerful-phrases-for-dealing-with-difficult-people-en/purchase', 'جملات-قدرتمند-برای-برخورد-با-افراد-مشکل', '2023-01-26 19:10:26.050949', '2023-01-26 19:10:26.050949', NULL, 'Powerful Phrases for Dealing with Difficult People');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (262, 'ژاکوبن های سیاه', 'Toussaint L’Ouverture و انقلاب سن دومینگو', 'Toussaint L’Ouverture و انقلاب سن دومینگو', 28, 13, 'book', 't', '<p><em>ژاکوبن‌های سیاه</em> (1938) تاریخ قابل توجه انقلاب را در مستعمره سان دومینگو فرانسه (هائیتی امروزی) دنبال می‌کند. وقایعی را توصیف می کند که به انقلاب کمک کرد تا به اولین شورش بردگان در تاریخ تبدیل شود.</p>
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (263, 'برای نفوذ ارتباط برقرار کنید', 'چگونه مخاطبان خود را به عمل ترغیب کنیم', 'چگونه مخاطبان خود را به عمل ترغیب کنیم', 23, 10, 'book', 't', '<p><em>ارتباط برای تأثیرگذاری</em> (2015) راهنمای دقیقی برای برقراری ارتباط مؤثر است. این همه چیز از انتخاب صدای مناسب گرفته تا دانستن نحوه ساختاربندی و ارائه پیام شما را پوشش می دهد. درک بهتری از مشکلات سخنرانی عمومی به دست آورید تا بدانید از چه چیزهایی باید اجتناب کنید، و برخی از ابزارهای خارق العاده را کشف کنید که به تبدیل اطلاعات شما به یک دعوت الهام بخش برای اقدام کمک می کند.</p>', '2018-01-15 00:00:00', 4, 116, 'https://images.blinkist.io/images/books/5a5b93b3b238e100078c4fc8/1_1/470.jpg', '/en/books/communicate-to-influence-en/purchase', 'برای-نفوذ-ارتباط-برقرار-کنید', '2023-01-26 19:10:42.010648', '2023-01-26 19:10:42.010648', NULL, 'Communicate to Influence');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (264, 'تربیت انسانهای خوب', 'راهنمای آگاهانه برای شکستن چرخه والدین واکنشی و تربیت کودکان مهربان و با اعتماد به نفس', 'راهنمای آگاهانه برای شکستن چرخه والدین واکنشی و تربیت کودکان مهربان و با اعتماد به نفس', 18, 8, 'book', 't', '<p><em>تربیت انسان های خوب</em> (2019) یک راهنمای تربیتی آگاهانه است که به شما می آموزد چگونه فریاد زدن را متوقف کنید و زمین گیر شوید. این دارای شیوه های سالمی است که می تواند به شما کمک کند چرخه های نسلی را بشکنید و والدین بهتری باشید.</p>', '2023-01-04 00:00:00', 5, 46, 'https://images.blinkist.io/images/books/63aeb5c3f9d4a6000702305b/1_1/470.jpg', '/en/books/raising-good-humans-en/purchase', 'تربیت-انسانهای-خوب', '2023-01-26 19:10:46.931412', '2023-01-26 19:10:46.931412', NULL, 'Raising Good Humans');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (265, 'پروفسور وارد است', 'راهنمای ضروری برای تبدیل Ph.D. به یک شغل', 'راهنمای ضروری برای تبدیل Ph.D. به یک شغل', 16, 9, 'book', 'f', '<p><em>The Professor Is In</em> (2015) چالش‌های پیش روی دانشجویان فارغ‌التحصیل در جستجوی کار را بیان می‌کند و توصیه‌های عمل‌گرایانه‌ای را در مورد چگونگی بهتر کردن شانس رسیدن به یک موقعیت علمی در یک بازار رقابتی فزاینده ارائه می‌دهد.</em><em> p>', '2016-01-04 00:00:00', NULL, 6, 'https://images.blinkist.io/images/books/568a62378944a60007000009/1_1/470.jpg', '/en/books/the-professor-is-in-en/purchase', 'پروفسور-وارد-است', '2023-01-26 19:10:58.855147', '2023-01-26 19:10:58.855147', NULL, 'The Professor Is In');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (266, 'F#ck بازاریابی محتوا', 'برای افزایش تقاضا، درآمد و روابط، روی تجربه محتوا تمرکز کنید', 'برای افزایش تقاضا، درآمد و روابط، روی تجربه محتوا تمرکز کنید', 19, 7, 'book', 't', '<p>علی رغم آنچه عنوان می گوید، <em>F#ck Content Marketing</em> (2019) مخالف بازاریابی محتوا نیست. بلکه در مورد رفع سردرگمی و تمرکز مجدد بر این است که چگونه از تلاش‌های بازاریابی محتوا بیشترین بهره را ببریم. برای این منظور، رندی فریش، نویسنده، می‌خواهد تاکید بر تولید محتوا را کنار بگذارد و آن را در جایی که به آن تعلق دارد قرار دهد: در مورد اینکه چگونه محتوای خود را مورد توجه قرار دهید و از آن برای ایجاد یک تجربه مشتری معنادار استفاده کنید.</p>', '2019-11-20 00:00:00', 4, 75, 'https://images.blinkist.io/images/books/5dd403526cee070007fe36e1/1_1/470.jpg', '/en/books/f-number-ck-content-marketing-en/purchase', 'F#ck-بازاریابی-محتوا', '2023-01-26 19:11:04.052443', '2023-01-26 19:11:04.052443', NULL, 'F#ck Content Marketing');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (267, 'اثر تلومر', 'رویکردی انقلابی برای زندگی جوان تر، سالم تر و طولانی تر', 'رویکردی انقلابی برای زندگی جوان تر، سالم تر و طولانی تر', 21, 8, 'book', 't', '<p><em>اثر تلومر</em> (2017) توضیح می‌دهد که چرا برخی از افراد جوان‌تر از دیگران به نظر می‌رسند و احساس می‌کنند. این پلک ها شما را در علم تلومرها که در ریشه سلولی فرآیند پیری هستند راهنمایی می کند. شما یاد خواهید گرفت که چگونه می توان با تلومرهای خود درست عمل کرد و عمر طولانی تری داشت.</p>', '2017-06-05 00:00:00', 4, 124, 'https://images.blinkist.io/images/books/593485fab238e10008fda20b/1_1/470.jpg', '/en/books/the-telomere-effect-en/purchase', 'اثر-تلومر', '2023-01-26 19:11:09.329411', '2023-01-26 19:11:09.329411', NULL, 'The Telomere Effect');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (268, 'چابکی عاطفی', 'رها شوید، تغییر را در آغوش بگیرید و در کار و زندگی پیشرفت کنید', 'رها شوید، تغییر را در آغوش بگیرید و در کار و زندگی پیشرفت کنید', 19, 8, 'book', 't', '<p><em>چابکی عاطفی </em>(2016) نظریه ها و ابزارهایی را ارائه می دهد که شما را از قاعده بی ثبات احساسات رها می کند. اگر بتوانید از گره های خشم و ترس در شکم خود فاصله بگیرید، می توانید به تدریج آرام شدن و بهبودی را یاد بگیرید.</p>', '2017-11-03 00:00:00', 4, 255, 'https://images.blinkist.io/images/books/59f5e58eb238e10006f6076f/1_1/470.jpg', '/en/books/emotional-agility-en/purchase', 'چابکی-عاطفی', '2023-01-26 19:11:15.095398', '2023-01-26 19:11:15.095398', NULL, 'Emotional Agility');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (270, 'چگونه اشتباه نکنیم', 'ریاضیات پنهان زندگی روزمره', 'ریاضیات پنهان زندگی روزمره', 20, 8, 'book', 't', '<p><em>چگونه اشتباه نکنیم</em> به ما نگاهی اجمالی به نحوه تفکر ریاضیدانان و اینکه چگونه می توانیم از طرز تفکر آنها بهره مند شویم، به ما می دهد. همچنین توضیح می‌دهد که وقتی ابزارهای ریاضی را نادرست به کار می‌بریم چقدر راحت اشتباه می‌کنیم، و راهنمایی می‌کند که چگونه می‌توانیم در عوض راه‌حل‌های درست پیدا کنیم.</p>', '2014-10-08 08:00:00', 4, 101, 'https://images.blinkist.io/images/books/54338ec23437360008000000/1_1/470.jpg', '/en/books/how-not-to-be-wrong-en/purchase', 'چگونه-اشتباه-نکنیم', '2023-01-26 19:11:25.545212', '2023-01-26 19:11:25.545212', NULL, 'How Not to Be Wrong');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (271, 'انقلاب خدمات مشتری', 'براندازی کسب و کار متعارف، الهام بخشیدن به کارمندان، و تغییر جهان', 'براندازی کسب و کار متعارف، الهام بخشیدن به کارمندان، و تغییر جهان', 11, 6, 'book', 't', '<p><em>انقلاب خدمات مشتری </em>(2015) اسرار واقعی خدمات مشتری درخشان را آشکار می کند. این پلک‌ها راهنمای عملی برای ارتقای خدمات مشتری شما به سطح بعدی ارائه می‌کند، به ایجاد تجربه‌ای فوق‌العاده برای مشتریانتان و ایجاد نیروی کار مشتاق مبتنی بر بینش کمک می‌کند.</p>', '2016-03-04 00:00:00', 4, 37, 'https://images.blinkist.io/images/books/56d5b96394333d000700009c/1_1/470.jpg', '/en/books/the-customer-service-revolution-en/purchase', 'انقلاب-خدمات-مشتری', '2023-01-26 19:11:30.686422', '2023-01-26 19:11:30.686422', NULL, 'The Customer Service Revolution');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (272, 'نوآوری برای افراد خسته', 'چگونه یک فرهنگ خلاقیت عمیق بسازیم', 'چگونه یک فرهنگ خلاقیت عمیق بسازیم', 21, 8, 'book', 't', '<p><em>نوآوری برای افراد خسته </em>(2019) با نفرین دنیای شرکت ها دست و پنجه نرم می کند: خستگی نوآوری. بسیاری از سازمان‌ها به‌جای اختراع هر چیز مفید یا جدید، درگیر صداهای شیک درباره «اختلال» و «تفکر آسمان آبی» هستند. لایه‌های مزخرف را جدا می‌کند تا ببینیم چگونه شرکت‌ها می‌توانند یک فرهنگ نوآوری عمیق و هدفمند ایجاد کنند.</p>', '2020-01-02 00:00:00', 4, 95, 'https://images.blinkist.io/images/books/5dfcc3096cee07000788a282/1_1/470.jpg', '/en/books/innovation-for-the-fatigued-en/purchase', 'نوآوری-برای-افراد-خسته', '2023-01-26 19:11:35.311803', '2023-01-26 19:11:35.311803', NULL, 'Innovation for the Fatigued');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (273, 'کد قهرمان', 'درس های آموخته شده از زندگی های خوب زندگی شده', 'درس های آموخته شده از زندگی های خوب زندگی شده', 19, 6, 'book', 't', '<p><em>The Hero Code </em>(2021) یک راهنمای دریاسالار چهار ستاره برای قهرمانی مدرن است. با تکیه بر تجربیات دریاسالار مک‌ریون در میدان و زندگی غیرنظامی، توصیه‌های هیجان‌انگیز زندگی را با حکایات جذاب و دراماتیک آمیخته است.</p>', '2021-06-10 00:00:00', 4, 105, 'https://images.blinkist.io/images/books/60c070ad6cee0700072578bc/1_1/470.jpg', '/en/books/the-hero-code-en/purchase', 'کد-قهرمان', '2023-01-26 19:11:41.239638', '2023-01-26 19:11:41.239638', NULL, 'The Hero Code');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (274, 'جداسازی آگاهانه', '5 قدم برای شاد زیستن حتی بعد از آن', '5 قدم برای شاد زیستن حتی بعد از آن', 23, 8, 'book', 't', '<p><em> جداسازی هوشیارانه </em>(2015) راهنمای حرکتی زیبا از یک رابطه ناکارآمد و به مرحله بعدی زندگی است. این یک روش آگاهانه برای پیمایش جداسازی در پنج مرحله ساده ارائه می دهد.</p>', '2020-05-13 00:00:00', 4, 150, 'https://images.blinkist.io/images/books/5eb5e6406cee070006697f72/1_1/470.jpg', '/en/books/conscious-uncoupling-en/purchase', 'جداسازی-آگاهانه', '2023-01-26 19:11:46.022969', '2023-01-26 19:11:46.022969', NULL, 'Conscious Uncoupling');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (275, 'قدرت قصد', 'یاد بگیرید که دنیای خود را به روش خودتان بسازید', 'یاد بگیرید که دنیای خود را به روش خودتان بسازید', 20, 7, 'book', 't', '<p><strong>درباره چیست؟</strong></p>
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (276, 'خودت را دوباره اختراع کن', 'تغییر تنها ثابت است', 'تغییر تنها ثابت است', 17, 6, 'book', 't', '<p><em>خودت را دوباره اختراع کن</em> (2016) تکنیک‌های عملی را به اشتراک می‌گذارد که چگونه به طور مستمر رویکرد خود را نسبت به زندگی و کسب و کار مورد ارزیابی مجدد قرار داده و مجدداً تنظیم کنید تا مسیر خود را به سوی موفقیت بپیمایید. نویسنده جیمز آلتوچر چگونگی انجام این کار را با استفاده از داستان‌های الهام‌بخش برگرفته از رهبران مذهبی، هنرمندان و کارآفرینان میلیاردر که هنر خودسازی را از آنها آموخته است، نشان می‌دهد.</p>', '2018-10-22 00:00:00', 4, 301, 'https://images.blinkist.io/images/books/5bcc764b6cee07000720639d/1_1/470.jpg', '/en/books/reinvent-yourself-en/purchase', 'خودت-را-دوباره-اختراع-کن', '2023-01-26 19:11:55.646445', '2023-01-26 19:11:55.646445', NULL, 'Reinvent Yourself');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (277, 'رهبری بدون اقتدار', 'چگونه قدرت جدید Co-Elevation می تواند سیلوها را خراب کند، تیم ها را متحول کند و همکاری را دوباره ابداع کند', 'چگونه قدرت جدید Co-Elevation می تواند سیلوها را خراب کند، تیم ها را متحول کند و همکاری را دوباره ابداع کند', 19, 7, 'book', 't', '<p><em>رهبری بدون اختیار </em>(2020) به بررسی این موضوع می پردازد که چگونه کارمندان غیرمدیریت می توانند تغییر ایجاد کنند و بر همکاران خود تأثیر بگذارند. این پلک‌ها تکنیک‌های ساده‌ای را برای ایجاد تأثیر بزرگ در محل کار، صرف‌نظر از عنوان رسمی شما، نشان می‌دهند.</p>', '2020-10-12 00:00:00', 4, 158, 'https://images.blinkist.io/images/books/5f802a0f6cee07000629e8d4/1_1/470.jpg', '/en/books/leading-without-authority-en/purchase', 'رهبری-بدون-اقتدار', '2023-01-26 19:12:00.797398', '2023-01-26 19:12:00.797398', NULL, 'Leading Without Authority');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (278, 'قانون 5 دوم', 'زندگی، کار و اعتماد به نفس خود را با شجاعت روزمره متحول کنید', 'زندگی، کار و اعتماد به نفس خود را با شجاعت روزمره متحول کنید', 13, 6, 'book', 't', '<p><em>قانون 5 دوم </em>(2017) یک کتاب راهنمای تحول آفرین برای اقدام، تغییر رفتار و زندگی با ترس کمتر و شجاعت بیشتر است. نکات موجود در داخل به یاد ماندنی، آسان برای اجرا و فورا موثر هستند. هرکسی می‌تواند از همین امروز برای کنترل زندگی خود استفاده از آن‌ها را شروع کند و با اطمینان به سوی فردای روشن‌تر حرکت کند.</p>', '2017-10-26 00:00:00', 4, 952, 'https://images.blinkist.io/images/books/59ec7f64b238e1000737fddc/1_1/470.jpg', '/en/books/the-5-second-rule-en/purchase', 'قانون-5-دوم', '2023-01-26 19:12:05.452685', '2023-01-26 19:12:05.452685', NULL, 'The 5 Second Rule');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (279, 'فریکس ها زمین را به ارث خواهند برد', 'کارآفرینی برای افراد عجیب و غریب، نامناسب و سلطه گران جهان', 'کارآفرینی برای افراد عجیب و غریب، نامناسب و سلطه گران جهان', 13, 7, 'book', 't', '<p>در <em>The Freaks Shall The Earth</em> (2014)، شما با "فریک‌های" امروزی روبرو خواهید شد، نسل جدیدی از متفکران دور از دسترس که تغییر فرهنگ کسب و کار مدرن کارآفرینانی که کمی دیوانه هستند، که از دمدمی مزاج بودن نمی‌ترسند، می‌توانند به شما نشان دهند که چگونه می‌توانید یک کسب‌وکار موفق ایجاد کنید.</p>', '2015-10-16 00:00:00', 4, 19, 'https://images.blinkist.io/images/books/561c3dc23635640007c30000/1_1/470.jpg', '/en/books/the-freaks-shall-inherit-the-earth-en/purchase', 'فریکس-ها-زمین-را-به-ارث-خواهند-برد', '2023-01-26 19:12:10.409804', '2023-01-26 19:12:10.409804', NULL, 'The Freaks Shall Inherit the Earth');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (280, 'خودت انتخاب کن', 'شاد باشید، میلیون ها نفر به دست آورید، رویا را زندگی کنید', 'شاد باشید، میلیون ها نفر به دست آورید، رویا را زندگی کنید', 22, 9, 'book', 't', '<p>نویسنده جیمز آلتوچر توضیح می‌دهد که پس از بحران اقتصادی جهانی در سال 2008، نمی‌توانید صبر کنید تا انتخاب شوید. شما باید <em>خودتان</em> <em>را انتخاب کنید.</em> این بدان معناست که شما باید مسئولیت کامل موفقیت و خوشبختی خود را با بازپس گیری کنترل آرزوها و رویاهای خود بپذیرید. برای انجام این کار، این کتاب ابزارها و تمرین‌های مؤثری را در اختیار شما قرار می‌دهد تا از نظر جسمی، ذهنی، عاطفی و روحی سالم بمانید.</p>', '2014-09-02 00:00:00', 4, 190, 'https://images.blinkist.io/images/books/54033ed56464630008000000/1_1/470.jpg', '/en/books/choose-yourself-en/purchase', 'خودت-انتخاب-کن', '2023-01-26 19:12:14.286396', '2023-01-26 19:12:14.286396', NULL, 'Choose Yourself');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (281, 'مدیر اولین بار', 'راهنمای پیشرو با بهترین شیوه های قابل اعتماد برای مدیران جدید', 'راهنمای پیشرو با بهترین شیوه های قابل اعتماد برای مدیران جدید', 23, 8, 'book', 't', '<p><em>مدیر اولین بار </em>(1981) راهنمای پیشرو برای مدیران جدید در هر زمینه ای است. این پلک‌ها که موضوعاتی از تفویض اختیار و انگیزه گرفته تا استخدام و اخراج را در بر می‌گیرد، به شما مهارت‌هایی را برای هدایت واقعیت‌های مدیریت افراد مجهز می‌کند تا بتوانید از دام‌های رایج اجتناب کنید و موفقیت خود را در نقش رهبری جدید خود به حداکثر برسانید. </p>', '2021-07-07 00:00:00', 5, 199, 'https://images.blinkist.io/images/books/60ddca406cee07000754f876/1_1/470.jpg', '/en/books/the-first-time-manager-en/purchase', 'مدیر-اولین-بار', '2023-01-26 19:12:20.19448', '2023-01-26 19:12:20.19448', NULL, 'The First-Time Manager');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (282, 'ساختن یک رهبر', 'آنچه ورزش نخبگان می تواند در مورد رهبری، مدیریت و عملکرد به ما بیاموزد', 'آنچه ورزش نخبگان می تواند در مورد رهبری، مدیریت و عملکرد به ما بیاموزد', 21, 7, 'book', 't', '<p><em>ساخت یک رهبر </em>(2020) گنجینه ارزشمندی از خرد رهبری است. با تکیه بر مصاحبه با هفت مربی در اوج حرفه خود، نه تنها یک رهبر بزرگ را توضیح می دهد، بلکه توضیح می دهد که چگونه می توانید خود را به یک رهبر تبدیل کنید.</p>', '2020-11-02 00:00:00', 4, 80, 'https://images.blinkist.io/images/books/5f9be6926cee07000676b6f9/1_1/470.jpg', '/en/books/the-making-of-a-leader-en/purchase', 'ساختن-یک-رهبر', '2023-01-26 19:12:26.315877', '2023-01-26 19:12:26.315877', NULL, 'The Making of a Leader');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (283, 'وکلا، دروغگوها و هنر داستان سرایی', 'استفاده از داستان ها برای حمایت، تأثیرگذاری و متقاعد کردن', 'استفاده از داستان ها برای حمایت، تأثیرگذاری و متقاعد کردن', 13, 6, 'book', 't', '<p><em>وکلا، دروغگوها و هنر داستان سرایی </em>(2016) رابطه غیرمنتظره بین فیلمنامه نویسی و هنر ارائه یک پرونده حقوقی را آشکار می کند. اینها دو رشته هستند که هر دو بر مهارت های داستان نویسی عالی و بلاغت موثر متکی هستند. بنابراین با کمک مثال‌ها و نکات واقعی زندگی مردم در تلویزیون و فیلم، خواهید فهمید که چگونه می‌توانید از هنر قصه‌گویی برای ایجاد پرونده‌های قانع‌کننده استفاده کنید که دادگاه را پرچوب نگه می‌دارد.</p>
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (341, '15 تعهد رهبری آگاهانه', 'پارادایم جدید برای موفقیت پایدار', 'پارادایم جدید برای موفقیت پایدار', 17, 8, 'book', 't', '<p><em>15 تعهد رهبری آگاهانه </em>(2014) به شما می آموزد که چگونه به یک رهبر <em>آگاه</em> تبدیل شوید - رهبری که الهام بخش تغییرات مثبت است، فضای کاری عالی ایجاد می کند و روابط نزدیک ایجاد می کند. روابط در زندگی شخصی آنها زیرا رهبری چیزی فراتر از دستور دادن است.</p>', '2015-07-22 00:00:00', 5, 69, 'https://images.blinkist.io/images/books/55ac313165363800075b0000/1_1/470.jpg', '/en/books/the-15-commitments-of-conscious-leadership-en/purchase', '15-تعهد-رهبری-آگاهانه', '2023-01-26 19:21:12.342215', '2023-01-26 19:21:12.342215', NULL, 'The 15 Commitments of Conscious Leadership');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (284, 'تخت خواب', 'راهنمای داده محور برای والدین بهتر و آرام تر، از تولد تا پیش دبستانی', 'راهنمای داده محور برای والدین بهتر و آرام تر، از تولد تا پیش دبستانی', 27, 9, 'book', 't', '<p><em>Cribsheet</em> (2019) دیدگاه منحصر به فرد و روشنگری در مورد فرزندپروری در دوران کودکی ارائه می دهد - دیدگاه یک اقتصاددان. با توجه به تمرکز آن بر تصمیم گیری، تجزیه و تحلیل هزینه و فایده، ارزیابی ریسک و تفسیر داده ها، رشته دانشگاهی اقتصاد یک چارچوب شگفت انگیز مفید برای فکر کردن در مورد تصمیمات دشواری که والدین جدید باید هنگام بزرگ کردن نوزادان خود بگیرند، فراهم می کند.</p >', '2019-06-05 00:00:00', 4, 85, 'https://images.blinkist.io/images/books/5cf2b6386cee070008ddbc50/1_1/470.jpg', '/en/books/cribsheet-en/purchase', 'تخت-خواب', '2023-01-26 19:12:37.315619', '2023-01-26 19:12:37.315619', NULL, 'Cribsheet');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (285, 'رهبری قبایل', 'استفاده از گروه های طبیعی برای ایجاد یک سازمان پر رونق', 'استفاده از گروه های طبیعی برای ایجاد یک سازمان پر رونق', 18, 8, 'book', 't', '<p>این کتاب توضیح می‌دهد که چگونه اعضای یک محل کار با هم به عنوان یک قبیله عمل می‌کنند. هر قبیله دارای فرهنگی است که بهره وری آن را تعیین می کند و فرهنگ قبیله ای دارای پنج مرحله متمایز است. <em>قبیله</em> <em>رهبری</em> نشان خواهد داد که چگونه شما، به عنوان "رهبر قبیله"، می توانید قبیله <em>خود</em> را به سطوح بالاتر هدایت کنید و در نتیجه سالمتر و بازدهی بیشتری داشته باشید. محیط کار.</p>', '2014-08-19 00:00:00', 4, 57, 'https://images.blinkist.io/images/books/53f4698f34333900084d0000/1_1/470.jpg', '/en/books/tribal-leadership-en/purchase', 'رهبری-قبایل', '2023-01-26 19:12:43.039539', '2023-01-26 19:12:43.039539', NULL, 'Tribal Leadership');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (286, 'صاحب روز باشید، صاحب زندگی خود شوید', 'تمرین های بهینه برای بیداری، کار، یادگیری، غذا خوردن، تمرین، بازی، خواب و رابطه جنسی', 'تمرین های بهینه برای بیداری، کار، یادگیری، غذا خوردن، تمرین، بازی، خواب و رابطه جنسی', 12, 6, 'book', 't', '<p><em>مالک روز باشید، صاحب زندگی خود شوید </em>(2018) هک های مفیدی را ارائه می دهد که به شما امکان می دهد در همه زمینه های زندگی خود موفق شوید. صرف نظر از رژیم غذایی، زندگی جنسی یا ورزش، این کتاب توصیه‌هایی را ارائه می‌کند که به راحتی می‌توان آن را در سبک زندگی‌تان گنجاند تا بتوانید از هر روز بیشترین بهره را ببرید.</p>', '2019-01-02 00:00:00', 4, 443, 'https://images.blinkist.io/images/books/5c28f2fc6cee070008e7a3d7/1_1/470.jpg', '/en/books/own-the-day-own-your-life-en/purchase', 'صاحب-روز-باشید،-صاحب-زندگی-خود-شوید', '2023-01-26 19:12:48.973514', '2023-01-26 19:12:48.973514', NULL, 'Own the Day, Own Your Life');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (287, 'رازهای ارائه استیو جابز', 'تسلط بر استاندارد طلایی برای ارائه', 'تسلط بر استاندارد طلایی برای ارائه', 16, 11, 'book', 't', '<p><em>رازهای ارائه استیو جابز </em>(2009)<em> </em>توضیح می دهد که چگونه هر مجری می تواند به اندازه استیو جابز افسانه ای متقاعد کننده و الهام بخش باشد. از برنامه‌ریزی گرفته تا تمرین و تحویل، کارمین گالو جزئیات آناتومی یک ارائه عالی را شرح می‌دهد.</p>', '2013-01-13 00:00:00', 5, 99, 'https://images.blinkist.io/images/books/509cdc6ce4b0a13d41357e10/1_1/470.jpg', '/en/books/the-presentation-secrets-of-steve-jobs-en/purchase', 'رازهای-ارائه-استیو-جابز', '2023-01-26 19:12:53.935488', '2023-01-26 19:12:53.935488', NULL, 'The Presentation Secrets of Steve Jobs');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (288, 'هیچ درمانی برای انسان بودن نیست', '(و حقایقی دیگر که باید بشنوم)', '(و حقایقی دیگر که باید بشنوم)', 32, 8, 'book', 't', '<p><em>هیچ درمانی برای انسان بودن وجود ندارد </em>(2021) وقایع متفکرانه تلاش های کیت باولر برای استفاده حداکثری از زندگی خود پس از تشخیص وحشیانه سرطان در تنها 35 سالگی است. بخشی از خاطرات، بخشی در نقد موارد گسترده وسواس با مثبت اندیشی، <em>هیچ درمانی برای انسان بودن وجود ندارد</em>یک پیام کوبنده از مرز شکننده بین زندگی و مرگ است.</p>', '2022-03-08 00:00:00', 4, 235, 'https://images.blinkist.io/images/books/6225d89e6cee070008741f46/1_1/470.jpg', '/en/books/no-cure-for-being-human-en/purchase', 'هیچ-درمانی-برای-انسان-بودن-نیست', '2023-01-26 19:12:58.801207', '2023-01-26 19:12:58.801207', NULL, 'No Cure for Being Human');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (289, 'Joy Inc.', 'چگونه یک محل کار ساختیم که مردم دوست دارند', 'چگونه یک محل کار ساختیم که مردم دوست دارند', 14, 6, 'book', 't', '<p>در <em>Joy Inc.</em>، نویسنده Rich Sheridan به شما نشان می‌دهد که چگونه فرهنگ شادی می‌تواند مبنای هر شرکت موفقی باشد. نویسنده با استفاده از نمونه هایی از تجربه خود به عنوان مدیر عامل شرکت نرم افزار Menlo Innovations، نشان می دهد که چگونه تقویت ارتباطات باز، شفافیت و مثبت اندیشی می تواند یک محل کار را متحول کند.</p>', '2015-03-11 00:00:00', 4, 13, 'https://images.blinkist.io/images/books/54fdc7f6626661000a670000/1_1/470.jpg', '/en/books/joy-inc-en/purchase', 'Joy-Inc.', '2023-01-26 19:13:04.141985', '2023-01-26 19:13:04.141985', NULL, 'Joy Inc.');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (290, 'حقوق بازنشستگی شما', 'چگونه از پس انداز بازنشستگی در طول عمر خود برای پرداخت درآمد خود در دوران بازنشستگی استفاده کنید', 'چگونه از پس انداز بازنشستگی در طول عمر خود برای پرداخت درآمد خود در دوران بازنشستگی استفاده کنید', 22, 7, 'book', 't', '<p><em>حقوق بازنشستگی شما </em>(2019) به یک سوال مهم که پس‌اندازهایی که به سن بازنشستگی نزدیک می‌شوند می‌پردازد: چگونه پس‌انداز خود را به درآمدی تبدیل می‌کنید که سال‌های غروب شما را ببیند؟ ریچارد دایسون و ریچارد ایوانز با تکیه بر سال‌ها تجربه در پاسخگویی به سؤالات مالی شخصی خوانندگان برای یک روزنامه برجسته بریتانیایی، بینش‌های فراوانی را برای استفاده حداکثری از صندوق بازنشستگی ارائه می‌دهند. </p>', '2019-10-15 00:00:00', 4, 83, 'https://images.blinkist.io/images/books/5da083616cee0700074e2c2e/1_1/470.jpg', '/en/books/your-retirement-salary-en/purchase', 'حقوق-بازنشستگی-شما', '2023-01-26 19:13:09.376167', '2023-01-26 19:13:09.376167', NULL, 'Your Retirement Salary');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (291, 'خودیاری که کار می کند', 'منابعی برای بهبود سلامت عاطفی و تقویت روابط', 'منابعی برای بهبود سلامت عاطفی و تقویت روابط', 30, 9, 'book', 't', '<p><em>Self-Help That Works </em>(2013، نسخه چهارم) خدمات ارزشمندی را ارائه می دهد که توصیه های برتر متخصصان بهداشت روان در ایالات متحده را دریافت می کند و نتایج را در یک جلد مفید جمع آوری می کند. دریابید که متخصصان در مورد بیش از 40 موضوع از محبوب‌ترین موضوعات، کدام منابع خودیاری را توصیه می‌کنند.</p>', '2021-03-28 00:00:00', 4, 50, 'https://images.blinkist.io/images/books/60547aed6cee0700073c37b2/1_1/470.jpg', '/en/books/self-help-that-works-en/purchase', 'خودیاری-که-کار-می-کند', '2023-01-26 19:13:15.188138', '2023-01-26 19:13:15.188138', NULL, 'Self-Help That Works');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (292, 'معادله تاثیر', 'آیا کاری می کنید که اتفاق بیفتد یا فقط سر و صدا ایجاد می کنید؟', 'آیا کاری می کنید که اتفاق بیفتد یا فقط سر و صدا ایجاد می کنید؟', 17, 6, 'book', 't', '<p><em>معادله تأثیر</em> (2012) نگاهی تازه به این دارد که چگونه شرکت‌ها می‌توانند با موفقیت محصولی را با حداکثر تأثیر به بازار معرفی کنند و آن را در بلندمدت مرتبط نگه دارند. این پلک‌ها به شما یاد می‌دهند که چگونه پیام خود را بیان کنید، آن را به طور مؤثر به مخاطبان خود ارائه دهید و اعتماد لازم را برای بازگرداندن مشتریان برای کسب اطلاعات بیشتر ایجاد کنید.</p>', '2015-11-03 00:00:00', 4, 11, 'https://images.blinkist.io/images/books/56376c7862346500072d0000/1_1/470.jpg', '/en/books/the-impact-equation-en/purchase', 'معادله-تاثیر', '2023-01-26 19:13:18.960305', '2023-01-26 19:13:18.960305', NULL, 'The Impact Equation');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (293, 'جابجایی قدرت', 'هر موقعیتی را تغییر دهید، هر معامله ای را ببندید و به هر نتیجه ای برسید', 'هر موقعیتی را تغییر دهید، هر معامله ای را ببندید و به هر نتیجه ای برسید', 17, 6, 'book', 't', '<p><em>Powershift </em>(2020) راهنمایی برای آماده کردن خود برای موفقیت است. با تکیه بر تجربه نویسنده دیموند جان به عنوان یک کارآفرین در صنعت لباس و کسب و کار نمایش، مجموعه ای از نکات، ترفندها و ایده هایی را ارائه می دهد که به شما کمک می کند نفوذ خود را گسترش دهید و دیگران را به هدف خود جلب کنید.</p>', '2020-11-10 00:00:00', 4, 103, 'https://images.blinkist.io/images/books/5fa5572c6cee070006bad8ea/1_1/470.jpg', '/en/books/powershift-en/purchase', 'جابجایی-قدرت', '2023-01-26 19:13:24.756583', '2023-01-26 19:13:24.756583', NULL, 'Powershift');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (294, 'پس از کرونا', 'از بحران تا فرصت', 'از بحران تا فرصت', 19, 6, 'book', 't', '<p><em>Post Corona </em>(2020) تحلیلی بیرحمانه از چگونگی شکل گیری مجدد جهان ما توسط شیوع COVID-19 است. این نظرسنجی از چشم‌انداز کسب‌وکار پس از همه‌گیری نشان می‌دهد که چه کسانی از این ویروس سود می‌برند و چه کسانی آسیب دیده‌اند.</p>', '2021-01-21 00:00:00', 4, 94, 'https://images.blinkist.io/images/books/6007f93c6cee070007a81d3f/1_1/470.jpg', '/en/books/post-corona-en/purchase', 'پس-از-کرونا', '2023-01-26 19:13:30.442094', '2023-01-26 19:13:30.442094', NULL, 'Post Corona');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (295, 'سقوط کرد', 'چگونه یک دهه بحران مالی جهان را تغییر داد؟', 'چگونه یک دهه بحران مالی جهان را تغییر داد؟', 29, 9, 'book', 't', '<p><em>Crashed </em>(2018) لرزه نگار استعاری را برای اندازه گیری یک زلزله اقتصادی باز می کند که لرزش آن هنوز هم می تواند احساس شود - بحران مالی 2008. آدام توز که با توجه به تأثیرات جهانی آنچه که اکنون به عنوان "رکود بزرگ" شناخته می شود، نوشته شده است، امواج شوک سقوط را از مرکز آن در بازارهای مالی آمریکا تا نتایج آنها در کریمه، لندن، آتن و سایر نقاط داغ ژئوپلیتیک دنبال می کند.</p> >', '2019-05-10 00:00:00', 4, 90, 'https://images.blinkist.io/images/books/5cd15bfb6cee070008f3fe25/1_1/470.jpg', '/en/books/crashed-en/purchase', 'سقوط-کرد', '2023-01-26 19:13:35.863316', '2023-01-26 19:13:35.863316', NULL, 'Crashed');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (296, 'قدرت یک تیم مثبت', 'اصول و تمرین های اثبات شده ای که تیم های بزرگ را عالی می کند', 'اصول و تمرین های اثبات شده ای که تیم های بزرگ را عالی می کند', 16, 6, 'book', 't', '<p><em>قدرت یک تیم مثبت</em> (2018) اصول اثبات شده ای را به اشتراک می گذارد که به تیم های خوب کمک می کند تا عالی شوند. با استفاده از مثال‌های واقعی از سال‌ها کار نویسنده در مشاوره کسب‌وکار، پلک‌ها توضیح می‌دهند که چگونه می‌توانید ارتباطات و تعهد تیم خود را بهبود بخشید و در عین حال منفی‌ها را از بین ببرید.</p>', '2019-03-14 00:00:00', 4, 85, 'https://images.blinkist.io/images/books/5c878ee96cee0700075fb783/1_1/470.jpg', '/en/books/the-power-of-a-positive-team-en/purchase', 'قدرت-یک-تیم-مثبت', '2023-01-26 19:13:42.442854', '2023-01-26 19:13:42.442854', NULL, 'The Power of a Positive Team');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (297, 'کپی رایتینگ متقاعد کننده', 'سر و صدا را قطع کنید و با ضربه ارتباط برقرار کنید', 'سر و صدا را قطع کنید و با ضربه ارتباط برقرار کنید', 18, 6, 'book', 't', '<p><em>کپی رایتینگ متقاعد کننده</em> (2019) راهنمای ارزشمندی برای دنیای کپی‌رایتینگ است، با نکاتی در مورد چگونگی جلب توجه و حفظ علاقه مشتریان، و همچنین ایجاد آن فروش‌های بسیار مهم برای مشتری شما اندی ماسلن، نویسنده، تکنیک‌های آزمایش‌شده با زمان را که برای نسل‌ها ثابت شده است، استفاده می‌کند و نشان می‌دهد که چگونه این تکنیک‌ها با موفقیت در دنیای آنلاینی که به طور فزاینده‌ای بر بازاریابی محتوا متمرکز شده است، استفاده می‌شوند.</p>', '2019-10-08 00:00:00', 4, 151, 'https://images.blinkist.io/images/books/5d9b3e9c6cee0700074e2289/1_1/470.jpg', '/en/books/persuasive-copywriting-en/purchase', 'کپی-رایتینگ-متقاعد-کننده', '2023-01-26 19:13:47.700492', '2023-01-26 19:13:47.700492', NULL, 'Persuasive Copywriting');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (412, 'ساخت آن همه کار', 'برنده شدن در بازی کار و تجارت زندگی', 'برنده شدن در بازی کار و تجارت زندگی', 21, 10, 'book', 't', '<p>این پلک‌ها بر اساس اصولی هستند که در موفقیت قبلی دیوید آلن در مدیریت زمان، <em>انجام کارها </em> (همچنین در چشمک‌ها موجود است). توضیح می دهد که چگونه می توانید وظایف خود را مدیریت کنید و اهداف معنی دار زندگی خود را دنبال کنید.</p>', '2014-04-15 05:53:29', 4, 98, 'https://images.blinkist.io/images/books/534d4f1666336100074b0000/1_1/470.jpg', '/en/books/making-it-all-work-en/purchase', 'ساخت-آن-همه-کار', '2023-01-26 19:32:53.229386', '2023-01-26 19:32:53.229386', NULL, 'Making It All Work');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (298, 'ذهنیت بیرونی', 'دیدن فراتر از خود: چگونه زندگی‌ها را تغییر دهیم و سازمان‌ها را متحول کنیم', 'دیدن فراتر از خود: چگونه زندگی‌ها را تغییر دهیم و سازمان‌ها را متحول کنیم', 10, 4, 'book', 't', '<p><em>ذهنیت بیرونی</em> (2016) توضیح می دهد که چگونه تغییر دیدگاه شما می تواند جهان را متحول کند. این پلک ها در مورد اینکه چگونه تمرکز بر نیازهای شخصی نیازهای دیگران را پنهان می کند و اینکه چگونه با شناسایی اهداف جمعی، افراد می توانند تغییرات جمعی قدرتمندی در جامعه ایجاد کنند، بحث می کند.</p>', '2017-04-28 00:00:00', 4, 39, 'https://images.blinkist.io/images/books/5901bb3fb238e10008b14ec1/1_1/470.jpg', '/en/books/the-outward-mindset-en/purchase', 'ذهنیت-بیرونی', '2023-01-26 19:13:51.290062', '2023-01-26 19:13:51.290062', NULL, 'The Outward Mindset');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (299, 'لیسانس رهبری', 'درست کردن محل کار و مشاغل یک حقیقت در یک زمان', 'درست کردن محل کار و مشاغل یک حقیقت در یک زمان', 20, 8, 'book', 't', '<p><em>Leadership BS </em>(2015) به دنیای کثیف مدیران تجاری نگاه می کند تا ببیند واقعاً زندگی در بالای نردبان شرکت چگونه است. چیزی که می‌یابیم چیزی کاملاً متفاوت از تصویری است که اغلب رهبران انگیزشی و زندگی‌نامه‌های مدیران اجرایی سعی می‌کنند به شما بفروشند. کشف کنید که اگر می‌خواهید در دنیای کسب‌وکار بی‌نظیر امروز به یک رهبر موفق تبدیل شوید، واقعاً باید وارد چه تجارت بدی شوید.</p>', '2017-09-18 13:00:00', 4, 254, 'https://images.blinkist.io/images/books/59bf946cb238e100052dbd64/1_1/470.jpg', '/en/books/leadership-bs-en/purchase', 'لیسانس-رهبری', '2023-01-26 19:13:56.192304', '2023-01-26 19:13:56.192304', NULL, 'Leadership BS');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (300, 'برو طرفدار', 'هفت گام برای حرفه ای شدن در بازاریابی شبکه ای', 'هفت گام برای حرفه ای شدن در بازاریابی شبکه ای', 12, 6, 'book', 'f', '<p><em>Go Pro </em>یک دوره آموزشی کامل در بازاریابی شبکه ای ارائه می دهد. خلاصه‌ای از تمام مهارت‌هایی را که برای حرفه‌ای شدن در بازاریابی شبکه‌ای نیاز دارید به شما ارائه می‌دهد و الهام‌بخش شما می‌شود تا نگرشی را ایجاد کنید که زحمات شما را به ثروت تبدیل کند.</p>', '2015-01-19 00:00:00', 4, 16, 'https://images.blinkist.io/images/books/54bd1d75633234000a1d0000/1_1/470.jpg', '/en/books/go-pro-en/purchase', 'برو-طرفدار', '2023-01-26 19:14:00.829542', '2023-01-26 19:14:00.829542', NULL, 'Go Pro');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (301, 'همکاری رادیکال', 'پنج مهارت ضروری برای غلبه بر حالت دفاعی و ایجاد روابط موفق', 'پنج مهارت ضروری برای غلبه بر حالت دفاعی و ایجاد روابط موفق', 18, 8, 'book', 't', '<p><em>همکاری رادیکال </em>(2004) روشهای ارزشمندی را برای کمک به ایجاد روابط مشارکتی مؤثر و با عملکرد بالا و همچنین استراتژی هایی برای مدیریت هر نوع درگیری که ممکن است با آن مواجه شوید ارائه می دهد. در قلب این روش‌ها پنج مهارت وجود دارد که می‌تواند هر کسی را به هم تیمی بهتری تبدیل کند و هر سازمانی را به یک مشارکت کارآمد و سازنده تبدیل کند.</p>', '2017-05-26 00:00:00', 4, 42, 'https://images.blinkist.io/images/books/5922e745b238e10007b6af1b/1_1/470.jpg', '/en/books/radical-collaboration-en/purchase', 'همکاری-رادیکال', '2023-01-26 19:14:06.006978', '2023-01-26 19:14:06.006978', NULL, 'Radical Collaboration');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (302, 'شما باید آن را تست کنید!', 'بهینه سازی تبدیل برای مشتریان بیشتر، فروش و سود یا هنر و علم بازاریابی بهینه', 'بهینه سازی تبدیل برای مشتریان بیشتر، فروش و سود یا هنر و علم بازاریابی بهینه', 20, 9, 'book', 't', '<p><em>شما باید آن را آزمایش کنید! </em>(2013) عمیقاً به علم بهینه سازی نرخ تبدیل می پردازد و به خوانندگان طیف گسترده ای از نکات و ترفندها را ارائه می دهد که می توانند از آنها برای تبدیل بازدید از سایت خود به فروش استفاده کنند.</p>', '2015-04-20 00:00:00', 5, 21, 'https://images.blinkist.io/images/books/5534f6736638630007210000/1_1/470.jpg', '/en/books/you-should-test-that-en/purchase', 'شما-باید-آن-را-تست-کنید!', '2023-01-26 19:14:12.317861', '2023-01-26 19:14:12.317861', NULL, 'You Should Test That!');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (303, 'زندگی در سیاره ما', 'بیانیه شاهد من و چشم اندازی برای آینده', 'بیانیه شاهد من و چشم اندازی برای آینده', 16, 6, 'book', 't', '<p><em>A Life on Our Planet</em>(2020) شرح طبیعت شناس مشهور دیوید آتنبرو از شگفتی های باورنکردنی است که در 94 سال زندگی خود روی زمین دیده است - و هشدار واضحی درباره آنچه اتفاق می افتد اگر به زندگی خود ادامه دهیم. مسیر فعلی این مستند با یک مستند نتفلیکس به همین نام همراه است.</p>', '2020-12-13 00:00:00', 5, 188, 'https://images.blinkist.io/images/books/5fce40cd6cee070006005b76/1_1/470.jpg', '/en/books/a-life-on-our-planet-en/purchase', 'زندگی-در-سیاره-ما', '2023-01-26 19:14:17.207531', '2023-01-26 19:14:17.207531', NULL, 'A Life on Our Planet');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (304, 'استراتژی رقابتی', 'تکنیک هایی برای تجزیه و تحلیل صنایع و رقبا', 'تکنیک هایی برای تجزیه و تحلیل صنایع و رقبا', 18, 8, 'book', 't', '<p><em>استراتژی رقابتی</em> بررسی کاملی از ماهیت رقابت صنعتی و همچنین استراتژی‌های رایجی که کسب‌وکارهای موفق برای پیشرفت به کار می‌گیرند، ارائه می‌کند. این نه تنها بینش‌های ارزشمندی را در مورد نحوه رقابت در بازار ارائه می‌دهد، بلکه نشان می‌دهد که چگونه شرکت‌ها می‌توانند از اطلاعات رقبای خود برای بهترین عملکرد در بازی خود استفاده کنند.</p>', '2015-01-28 00:00:00', 4, 67, 'https://images.blinkist.io/images/books/54c653f73732390009470000/1_1/470.jpg', '/en/books/competitive-strategy-en/purchase', 'استراتژی-رقابتی', '2023-01-26 19:14:22.3368', '2023-01-26 19:14:22.3368', NULL, 'Competitive Strategy');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (305, 'تیم تیم ها', 'قوانین جدید نامزدی برای یک دنیای پیچیده', 'قوانین جدید نامزدی برای یک دنیای پیچیده', 20, 8, 'book', 't', '<p><em>Team of Teams </em>(2015) راه‌های زیادی را ارائه می‌کند که حتی سازمان‌های بزرگ نیز می‌توانند از چابکی و هوشمندی تیم‌های کوچک بهره ببرند. با ایجاد تیمی از تیم‌ها، شرکت‌ها می‌توانند مسائل پیچیده و بهم پیوسته‌ای را که اغلب به معنای مرگ یا زندگی یک شرکت است، بهتر مدیریت کنند.</p>', '2015-08-28 00:00:00', 4, 131, 'https://images.blinkist.io/images/books/55db3bc52647b100090000b6/1_1/470.jpg', '/en/books/team-of-teams-en/purchase', 'تیم-تیم-ها', '2023-01-26 19:14:27.515818', '2023-01-26 19:14:27.515818', NULL, 'Team of Teams');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (306, 'نافرمانی هوشمندانه', 'انجام درست زمانی که کاری که به شما گفته می شود انجام دهید اشتباه است', 'انجام درست زمانی که کاری که به شما گفته می شود انجام دهید اشتباه است', 14, 6, 'book', 't', '<p><em>نافرمانی هوشمند </em>(2015) بینشی در مورد اینکه چرا ما خیلی سریع دستورات را دنبال می کنیم - حتی زمانی که می دانیم نباید انجام دهیم، ارائه می دهد. همه ابزارهایی را که برای مقاومت موثر در برابر قوانین، مقررات و دستوراتی که می‌دانید اشتباه یا مضر هستند در اختیار شما قرار می‌دهد - بدون اینکه خودتان را در معرض خطر قرار دهید.</p>', '2015-10-19 00:00:00', 4, 11, 'https://images.blinkist.io/images/books/5623b6013264660007110000/1_1/470.jpg', '/en/books/intelligent-disobedience-en/purchase', 'نافرمانی-هوشمندانه', '2023-01-26 19:14:32.13775', '2023-01-26 19:14:32.13775', NULL, 'Intelligent Disobedience');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (307, 'آنچه ما می گوییم مهم است', 'تمرین ارتباطات بدون خشونت', 'تمرین ارتباطات بدون خشونت', 15, 6, 'book', 't', '<p><em>آنچه ما می گوییم مهم است</em> (2009) راهنمایی برای برقراری ارتباط با شفقت، صراحت و صداقت است. این پلک‌ها نحوه ارتباط با نیازهای خود و دیگران را توضیح می‌دهند، در حالی که به گونه‌ای صحبت می‌کنید که احساسات شما را به وضوح و بدون ایجاد رنج بیان می‌کند.</p>', '2017-02-28 00:00:00', 4, 105, 'https://images.blinkist.io/images/books/58b405fbafd1210004c15f64/1_1/470.jpg', '/en/books/what-we-say-matters-en/purchase', 'آنچه-ما-می-گوییم-مهم-است', '2023-01-26 19:14:37.335163', '2023-01-26 19:14:37.335163', NULL, 'What We Say Matters');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (308, 'چگونه', 'توصیه علمی پوچ برای مشکلات رایج دنیای واقعی', 'توصیه علمی پوچ برای مشکلات رایج دنیای واقعی', 23, 8, 'book', 't', '<p><em>How To </em>(2019) یک راهنمای عمداً غیرعملی و ساده برای انجام طیف گسترده ای از وظایف به روش های بسیار عجیب و غریب اما قابل قبول است. <em>How To</em> با ترسیم از علوم، ریاضی و تاریخ و ترکیب آنها با حس شوخ طبعی منحصر به فرد، شما را به سفری سرگرم کننده در میان برخی از عجیب ترین احتمالات واقعیت می برد. </p>', '2019-10-04 00:00:00', 4, 61, 'https://images.blinkist.io/images/books/5d93e6ac6cee0700080bd258/1_1/470.jpg', '/en/books/how-to-en/purchase', 'چگونه', '2023-01-26 19:18:20.259334', '2023-01-26 19:18:20.259334', NULL, 'How To');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (309, 'قوانین ترمودینامیک', 'یک مقدمه بسیار کوتاه', 'یک مقدمه بسیار کوتاه', 29, 10, 'book', 't', '<p><em>قوانین ترمودینامیک </em>(2010) مقدمه ای کوتاه و در دسترس برای ترمودینامیک است، رشته ای از فیزیک که به روابط بین اشکال مختلف انرژی مربوط می شود. این کتاب که توسط یکی از مقامات برجسته جهان در این زمینه به نام پیتر اتکینز نوشته شده است، چهار قانون حاکم بر جهان را توضیح می دهد - قوانین صفر، اول، دوم و سوم. در طول راه، <em>قوانین ترمودینامیک</em> عملکرد مفاهیم آشنا مانند دما و همچنین ایده‌های عجیب‌تری مانند آنتروپی و حالت‌های انرژی را آشکار می‌کند.</p>', '2020-02-12 00:00:00', 4, 60, 'https://images.blinkist.io/images/books/5e40adac6cee070006b5f901/1_1/470.jpg', '/en/books/the-laws-of-thermodynamics-en/purchase', 'قوانین-ترمودینامیک', '2023-01-26 19:18:25.555405', '2023-01-26 19:18:25.555405', NULL, 'The Laws of Thermodynamics');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (310, 'اقتصاد روایی', 'چگونه داستان‌ها ویروسی می‌شوند و رویدادهای اقتصادی بزرگ را به پیش می‌برند', 'چگونه داستان‌ها ویروسی می‌شوند و رویدادهای اقتصادی بزرگ را به پیش می‌برند', 25, 8, 'book', 't', '<p><em>اقتصاد روایتی </em>(2019) توضیح می‌دهد که چگونه روایت‌های محبوب بر نحوه رفتار اقتصادها تأثیر می‌گذارند. از رشد ناگهانی بیت کوین تا سقوط بازار سهام، <em>اقتصاد روایتی </em> فراتر از آمار به نظر می رسد تا داستان های انسانی جمعی که این رویدادها را هدایت می کنند. </p>', '2020-06-28 00:00:00', 4, 354, 'https://images.blinkist.io/images/books/5ef1ecfc6cee0700070a8b2f/1_1/470.jpg', '/en/books/narrative-economics-en/purchase', 'اقتصاد-روایی', '2023-01-26 19:18:30.423987', '2023-01-26 19:18:30.423987', NULL, 'Narrative Economics');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (311, 'نوری که ما حمل می کنیم', 'غلبه بر زمان نامشخص', 'غلبه بر زمان نامشخص', 18, 3, 'book', 't', 'میشل اوباما، بانوی اول سابق ایالات متحده، بانوی اول سابق ایالات متحده، در <em>نوری که ما حمل می‌کنیم </em> (۲۰۲۲)، به پرسش‌های پیچیده درباره جامعه، هویت و روابط با صمیمیت و صداقت علامت تجاری می‌پردازد. اوباما معتقد است که همه ما در درون خود نوری را حمل می کنیم - در این کتاب، او به ما می گوید که چگونه آن نور را بتابانیم تا پتانسیل امید و شفا و مسیرهایی به سوی دنیایی بهتر را روشن کند.</p>', '2022-12-05 00:00:00', 4, 349, 'https://images.blinkist.io/images/books/638751297a8e39000936154c/1_1/470.jpg', '/en/books/the-light-we-carry-en/purchase', 'نوری-که-ما-حمل-می-کنیم', '2023-01-26 19:18:34.385286', '2023-01-26 19:18:34.385286', NULL, 'The Light We Carry');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (312, 'هدف گذاری شده است', 'چگونه فناوری تبلیغات را متحول می کند و راه رسیدن شرکت ها به مشتریان', 'چگونه فناوری تبلیغات را متحول می کند و راه رسیدن شرکت ها به مشتریان', 8, 4, 'book', 't', '<p><em>هدفمند</em> (2014) شما را به سفری از روزهای اولیه تبلیغات اینترنتی تا مبادلات پیچیده تبلیغات آنلاین امروزی می برد. در راه، نویسنده اهمیت حیاتی استفاده از قدرت بازاریابی موتورهای جستجو یا SEM را برای هدف قرار دادن مشتریانی که برای رشد شرکت خود نیاز دارید، آشکار می کند.</p>', '2016-12-27 00:00:00', 4, 14, 'https://images.blinkist.io/images/books/584abb8666f3e20004cb68f5/1_1/470.jpg', '/en/books/targeted-en/purchase', 'هدف-گذاری-شده-است', '2023-01-26 19:18:39.616371', '2023-01-26 19:18:39.616371', NULL, 'Targeted');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (350, 'اسطوره های نوآوری', 'پرفروش ترین کتاب تاریخ ایده ها', 'پرفروش ترین کتاب تاریخ ایده ها', 14, 6, 'book', 't', '<p><em>افسانه های نوآوری</em> (2007) به تصورات غلط رایج در مورد آنچه که برای تبدیل شدن به یک مبتکر موفق نیاز است، می پردازد. برکون با وام گرفتن نمونه‌های واقعی از تاریخ کسب‌وکار و هنرهای اخیر، نشان می‌دهد که ایده‌های خوب واقعاً از کجا می‌آیند.</p>', '2018-02-09 00:00:00', 4, 72, 'https://images.blinkist.io/images/books/5a783282b238e10006541210/1_1/470.jpg', '/en/books/the-myths-of-innovation-en/purchase', 'اسطوره-های-نوآوری', '2023-01-26 19:27:21.957385', '2023-01-26 19:27:21.957385', NULL, 'The Myths of Innovation');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (313, 'متوقف کردن. فکر. سرمایه گذاری.', 'یک چارچوب مالی رفتاری برای بهینه سازی پرتفوی سرمایه گذاری', 'یک چارچوب مالی رفتاری برای بهینه سازی پرتفوی سرمایه گذاری', 27, 6, 'book', 't', '<p><em>توقف کنید. فکر. سرمایه گذاری. </em>(2022) نگاهی به اقتصاد رفتاری می‌اندازد، حوزه‌ای از مطالعات که نقش احساسات و رفتار انسان را در تصمیم‌گیری مالی بررسی می‌کند. این بررسی می‌کند که چگونه سوگیری‌های ناخودآگاه و بیزاری‌های ذاتی افراد بر تصمیم‌گیری‌های آنها در هر جنبه از فرآیند سرمایه‌گذاری تأثیر می‌گذارد.</p>', '2022-04-01 00:00:00', 4, 276, 'https://images.blinkist.io/images/books/62458d2c6cee0700084a61b0/1_1/470.jpg', '/en/books/stop-think-invest-en/purchase', 'متوقف-کردن.-فکر.-سرمایه-گذاری.', '2023-01-26 19:18:44.619622', '2023-01-26 19:18:44.619622', NULL, 'Stop. Think. Invest.');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (314, 'آنچه شما را به اینجا رساند، شما را به آنجا نخواهد رساند', 'چقدر افراد موفق حتی موفق تر می شوند!', 'چقدر افراد موفق حتی موفق تر می شوند!', 18, 9, 'book', 't', '<p>مهارت های افراد شما هر چه بیشتر از نردبان موفقیت بالا بروید اهمیت بیشتری پیدا می کند. <em>آنچه شما را به اینجا رساند، شما را به آنجا نخواهد برد </em>(2007) برخی از عادات بدی را که معمولاً افراد موفق را عقب می اندازند توصیف می کند و توضیح می دهد که چگونه آنها را تغییر دهید.</p>', '2015-06-12 00:00:00', 4, 157, 'https://images.blinkist.io/images/books/5575b07a3935610007d00000/1_1/470.jpg', '/en/books/what-got-you-here-wont-get-you-there-en/purchase', 'آنچه-شما-را-به-اینجا-رساند،-شما-را-به-آنجا-نخواهد-رساند', '2023-01-26 19:18:48.381033', '2023-01-26 19:18:48.381033', NULL, 'What Got You Here, Won’t Get You There');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (315, 'بدن 4 ساعته', 'راهنمای غیر معمول برای از دست دادن سریع چربی، رابطه جنسی باورنکردنی و تبدیل شدن به ابرانسان', 'راهنمای غیر معمول برای از دست دادن سریع چربی، رابطه جنسی باورنکردنی و تبدیل شدن به ابرانسان', 19, 7, 'book', 't', '<p><em>بدن 4 ساعته </em>(2010) مجموعه ای از تحقیقات و یافته ها در مورد روش های غیر متعارف تنظیم بدن توسط پزشکان، دانشمندان، مربیان حرفه ای ورزش و ورزشکاران برتر جهان است. این روش‌ها شخصاً توسط نویسنده مورد آزمایش قرار می‌گیرند، و او را به کشف میان‌برهای تغییردهنده زندگی برای بهبود بدن و سبک زندگی خود هدایت می‌کنند.</p>', '2018-04-23 00:00:00', 4, 764, 'https://images.blinkist.io/images/books/5adcac42b238e10007596e3a/1_1/470.jpg', '/en/books/the-4-hour-body-en/purchase', 'بدن-4-ساعته', '2023-01-26 19:18:53.384349', '2023-01-26 19:18:53.384349', NULL, 'The 4-Hour Body');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (316, 'جلسات مزخرف', 'تبدیل یکی از منفورترین عناصر تجارت به یکی از با ارزش ترین', 'تبدیل یکی از منفورترین عناصر تجارت به یکی از با ارزش ترین', 16, 7, 'book', 't', '<p><em>Meetings Suck </em>(2016) راهنمایی است که به شرکت شما کمک می کند تا با از بین بردن مشکلات رایج جلسات خسته کننده و غیرمولد، در زمان و هزینه خود صرفه جویی کند. جلسات نباید ترسناک و وحشتناک باشند. آنها می توانند یک لذت واقعی باشند. از این گذشته، جلسات جایی است که ایده‌ها متولد می‌شوند، اطلاعات به اشتراک گذاشته می‌شود و افراد مهارت‌هایی را به دست می‌آورند که برای تبدیل شدن به رهبران الهام‌بخش فردا نیاز دارند.</p>', '2017-09-26 13:00:00', 4, 43, 'https://images.blinkist.io/images/books/59ca0d28b238e10005c2021f/1_1/470.jpg', '/en/books/meetings-suck-en/purchase', 'جلسات-مزخرف', '2023-01-26 19:18:58.093899', '2023-01-26 19:18:58.093899', NULL, 'Meetings Suck');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (317, 'اسحاق نیوتن', 'حقیقت پشت افسانه را بیاموزید', 'حقیقت پشت افسانه را بیاموزید', 20, 7, 'book', 't', '<p><em>ایزاک نیوتن </em>(2003) خوانندگان را به گشتی روشنگرانه در زندگی و ذهن یکی از بزرگترین متفکران تاریخ می برد. این بیش از یک گزارش ساده از زندگی و دستاوردهای نیوتن است. در عوض، نگاهی آشکار به عادات، وسواس‌ها و عجیب‌وغریب‌های او داریم. همه اینها یک بیوگرافی آشکار و ارزشمند را ایجاد می کند.</p>', '2018-06-07 00:00:00', 4, 85, 'https://images.blinkist.io/images/books/5b15516cb238e100070f468a/1_1/470.jpg', '/en/books/isaac-newton-en/purchase', 'اسحاق-نیوتن', '2023-01-26 19:19:03.430136', '2023-01-26 19:19:03.430136', NULL, 'Isaac Newton');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (318, 'آسیب نرسان', 'داستان های زندگی، مرگ و جراحی مغز', 'داستان های زندگی، مرگ و جراحی مغز', 10, 4, 'book', 't', '<p><em>آسیب نزنید </em>(2014) خاطرات جراح مغز و اعصاب برجسته لندنی هنری مارش است که حکایات و خاطراتش نگاهی صمیمی به اتاق عمل ارائه می دهد. مارش آموخته است که بسیاری از حرفه او در یک منطقه خاکستری اخلاقی قرار می گیرد - و در زندگی نیز همینطور است.</p>', '2015-09-09 00:00:00', 4, 24, 'https://images.blinkist.io/images/books/55ed2b7b11ad1a000900005a/1_1/470.jpg', '/en/books/do-no-harm-en/purchase', 'آسیب-نرسان', '2023-01-26 19:19:08.516047', '2023-01-26 19:19:08.516047', NULL, 'Do No Harm');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (319, 'استراتژی خوب، استراتژی بد', 'تفاوت و چرا اهمیت دارد', 'تفاوت و چرا اهمیت دارد', 21, 10, 'book', 't', '<p><em>استراتژی خوب، استراتژی بد </em>راهبردهای خوب را با استفاده از نمونه‌های تاریخی از زمینه‌های مختلف تشریح می‌کند و بینشی در مورد توسعه استراتژی‌های مؤثر خودمان از طریق توصیه‌های عملی و یک طرح اولیه ارائه می‌دهد.</p>
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (320, 'متولد شده برای دویدن', 'یک قبیله پنهان، ابر ورزشکاران و بزرگترین مسابقه ای که جهان هرگز ندیده است', 'یک قبیله پنهان، ابر ورزشکاران و بزرگترین مسابقه ای که جهان هرگز ندیده است', 33, 8, 'book', 't', '<p><em>Born to Run</em> (2009) به بررسی ظرفیت انسان برای دویدن در مسافت های طولانی می پردازد. گزارش‌های دست اول، مواجهه با یک قبیله مخفی و فوق‌العاده دونده و تحقیقات پیشرفته در کنار هم این ایده را مطرح می‌کنند که ممکن است ما برای دویدن به دنیا آمده باشیم.</p>', '2016-08-05 00:00:00', 4, 131, 'https://images.blinkist.io/images/books/5799f1f8e0bc1b000321bcf2/1_1/470.jpg', '/en/books/born-to-run-en/purchase', 'متولد-شده-برای-دویدن', '2023-01-26 19:19:19.178683', '2023-01-26 19:19:19.178683', NULL, 'Born to Run');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (321, 'اسطوره های خلاقیت', 'حقیقت در مورد اینکه چگونه شرکت ها و افراد نوآور ایده های عالی تولید می کنند', 'حقیقت در مورد اینکه چگونه شرکت ها و افراد نوآور ایده های عالی تولید می کنند', 14, 6, 'book', 't', '<p><em>افسانه های خلاقیت </em> تصورات غلط رایج ما را در مورد نحوه عملکرد خلاقیت از بین می برد. بینش عملی و توصیه‌های ارزشمندی را در مورد چگونگی ایجاد ایده‌های جدید و اجازه دادن به آنها شکوفا می‌کند و نمونه‌هایی از دنیای واقعی از تاریخ و خلاقیت‌های شناخته‌شده اخیر ارائه می‌دهد.</p>', '2014-11-24 00:00:00', 4, 55, 'https://images.blinkist.io/images/books/5471a95739353600091b0000/1_1/470.jpg', '/en/books/the-myths-of-creativity-en/purchase', 'اسطوره-های-خلاقیت', '2023-01-26 19:19:31.176035', '2023-01-26 19:19:31.176035', NULL, 'The Myths of Creativity');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (322, 'ما باید صحبت کنیم', 'چگونه مکالمات مهمی داشته باشیم', 'چگونه مکالمات مهمی داشته باشیم', 21, 7, 'book', 't', '<p><em>نیاز به صحبت کردن داریم</em> (2017) شما را در هنر مکالمه خوب راهنمایی می کند - مهارتی حیاتی اما اغلب کم ارزش. این نشان می دهد که چگونه مکالمه مؤثر منجر به روابط معنادارتر و درک بیشتر افراد دیگر می شود. این کتاب همچنین توصیه هایی در مورد چگونگی بهبود مهارت های مکالمه خود ارائه می دهد.</p>', '2020-12-24 00:00:00', 4, 171, 'https://images.blinkist.io/images/books/5fda3c436cee07000670aed2/1_1/470.jpg', '/en/books/we-need-to-talk-en/purchase', 'ما-باید-صحبت-کنیم', '2023-01-26 19:19:36.294479', '2023-01-26 19:19:36.294479', NULL, 'We Need to Talk');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (323, 'چگونه نگران نباشیم', 'حقیقت قابل توجه در مورد اینکه چگونه یک تغییر کوچک می تواند به شما کمک کند استرس کمتری داشته باشید و بیشتر از زندگی لذت ببرید', 'حقیقت قابل توجه در مورد اینکه چگونه یک تغییر کوچک می تواند به شما کمک کند استرس کمتری داشته باشید و بیشتر از زندگی لذت ببرید', 24, 8, 'book', 't', '<p><em>چگونه نگران نباشیم </em>(2012) یک نقشه راه عملی و در دسترس برای غلبه بر اضطراب، استرس و نگرانی است. رویکرد پل مک گی، مربی زندگی منطقی و واضح، همه چیز درباره تغییرات کوچک است که تفاوت بزرگی ایجاد می کند. او نشان می‌دهد که با تفکر تحلیلی، می‌توانید به طور منطقی با نگرانی‌ها برخورد کنید و فضای ارزشمندی را برای فعالیت‌های لذت‌بخش‌تر آزاد کنید.</p>', '2018-11-15 00:00:00', 4, 155, 'https://images.blinkist.io/images/books/5bebf0016cee070007d42986/1_1/470.jpg', '/en/books/how-not-to-worry-en/purchase', 'چگونه-نگران-نباشیم', '2023-01-26 19:19:41.311781', '2023-01-26 19:19:41.311781', NULL, 'How Not to Worry');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (324, 'سخت تر، باهوش تر حرکت کن', 'درس های پیشرفته و توصیه های سخت به دست آمده در مورد بازگشت', 'درس های پیشرفته و توصیه های سخت به دست آمده در مورد بازگشت', 8, 3, 'book', 't', '<p><em>Hustle Harder, Hustle Smarter</em> (2021) درس‌های زندگی را از کورتیس جکسون ارائه می‌دهد - خواننده رپ 50 Cent. از خرد خیابانی گرفته تا هنر معامله، جکسون داستان‌ها و حکمت‌هایی را از صعود مداوم خود به اوج به اشتراک می‌گذارد. </p>', '2023-01-02 00:00:00', 4, 34, 'https://images.blinkist.io/images/books/63ab0d3673bf6d0009f220d6/1_1/470.jpg', '/en/books/hustle-harder-hustle-smarter-en/purchase', 'سخت-تر،-باهوش-تر-حرکت-کن', '2023-01-26 19:19:46.398585', '2023-01-26 19:19:46.398585', NULL, 'Hustle Harder, Hustle Smarter');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (325, 'دائوی سرمایه', 'سرمایه گذاری اتریشی در دنیای تحریف شده', 'سرمایه گذاری اتریشی در دنیای تحریف شده', 18, 8, 'book', 't', '<p><em>دائوی سرمایه</em>خواننده را به سفری از چین باستان به وین قرن نوزدهم و بیستم، به بازارهای مدرن و جهانی می برد. با استفاده از مثال‌های فراوان، رویکرد «سرمایه‌گذاری دورگرد» یا «سرمایه‌گذاری اتریشی» را ترسیم می‌کند، که مبتنی بر خرد باستانی دائوئیست «به‌دست آوردن از طریق از دست دادن» است. ببینید چگونه سرمایه گذاری استراتژیک، به جای سرمایه گذاری سریع و شتابزده، می تواند شما را به موفقیت مالی بزرگ برساند.</p>', '2014-11-05 00:00:00', 4, 54, 'https://images.blinkist.io/images/books/54579b7c3365660008980000/1_1/470.jpg', '/en/books/the-dao-of-capital-en/purchase', 'دائوی-سرمایه', '2023-01-26 19:19:51.840227', '2023-01-26 19:19:51.840227', NULL, 'The Dao of Capital');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (326, 'کلاغ سیاه', 'داستان ناگفته کشیش جیم جونز و مردمش', 'داستان ناگفته کشیش جیم جونز و مردمش', 15, 6, 'book', 't', '<p><em>Raven </em> (1982) داستان ناگفته جیم جونز و معبد مردمش در جونزتاون را نشان می دهد، محل یک قتل دسته جمعی که در آن 917 نفر در یک روز سرنوشت ساز در سال 1979 جان خود را از دست دادند. به شما نگاه دقیق‌تری به جونز می‌اندازد، و روشن می‌کند که چگونه او به قدرت رسید و چرا پیروانش با چنین پایان وحشتناکی روبرو شدند.</p>', '2016-11-23 00:00:00', NULL, 7, 'https://images.blinkist.io/images/books/58321c312b89ea0004096a4e/1_1/470.jpg', '/en/books/raven-en/purchase', 'کلاغ-سیاه', '2023-01-26 19:19:56.741757', '2023-01-26 19:19:56.741757', NULL, 'Raven');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (463, 'هلگولند', 'درک انقلاب کوانتومی', 'درک انقلاب کوانتومی', 23, 7, 'book', 't', '<p><em>هلگولند </em>(2021) یک کاوش رویایی و شاعرانه در مکانیک کوانتومی است. این حجم باریک، دنیای زیراتمی عجیبی را توصیف می‌کند که در آن هیچ چیز کاملاً قطعی نیست.</p>', '2021-06-12 00:00:00', 4, 132, 'https://images.blinkist.io/images/books/60ba33eb6cee07000725646b/1_1/470.jpg', '/en/books/helgoland-en/purchase', 'هلگولند', '2023-01-26 19:37:14.921113', '2023-01-26 19:37:14.921113', NULL, 'Helgoland');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (327, 'جهان به روایت جنگ ستارگان', 'آنچه جنگ ستارگان می تواند در مورد دنیایی که در آن زندگی می کنیم به ما بیاموزد', 'آنچه جنگ ستارگان می تواند در مورد دنیایی که در آن زندگی می کنیم به ما بیاموزد', 12, 5, 'book', 't', '<p><em>جهان بر اساس جنگ ستارگان</em> (2016) درس‌های زیادی از زندگی را که باید از فیلم‌های <em>جنگ ستارگان</em> جورج لوکاس آموخت، آشکار می‌کند. کشف کنید که داستان های علمی تخیلی عامه پسند چه چیزهایی را درباره خودمان به ما می گوید، <em>جنگ ستارگان</em> در مورد سیاست محبوبیت و نحوه تفسیر فیلم ها و تزریق داستان های مورد علاقه خود با ایده های خودمان چه می گوید.</p>', '2016-11-10 00:00:00', 4, 137, 'https://images.blinkist.io/images/books/581e6bad7882c20003e52cc9/1_1/470.jpg', '/en/books/the-world-according-to-star-wars-en/purchase', 'جهان-به-روایت-جنگ-ستارگان', '2023-01-26 19:20:02.157341', '2023-01-26 19:20:02.157341', NULL, 'The World According to Star Wars');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (328, 'مانند یک دانشمند موشکی فکر کنید', 'استراتژی های ساده ای که می توانید برای ایجاد جهش های بزرگ در کار و زندگی استفاده کنید', 'استراتژی های ساده ای که می توانید برای ایجاد جهش های بزرگ در کار و زندگی استفاده کنید', 20, 8, 'book', 't', '<p><em>Think Like a Rocket Scientist </em>(2020) استراتژی هایی را که دانشمندان موشکی برای نوآوری، حل مسئله و به ثمر رساندن غیرقابل تصور استفاده می کنند، نشان می دهد. با یادگیری تکنیک هایی که دانشمندان هر روز از آنها استفاده می کنند، ابزارهای قدرتمندی به دست خواهید آورد که به شما کمک می کند تا رویاهای حرفه ای و شخصی خود را برآورده کنید.</p>', '2020-10-05 00:00:00', 5, 244, 'https://images.blinkist.io/images/books/5f76e2226cee07000602f183/1_1/470.jpg', '/en/books/think-like-a-rocket-scientist-en/purchase', 'مانند-یک-دانشمند-موشکی-فکر-کنید', '2023-01-26 19:20:07.239407', '2023-01-26 19:20:07.239407', NULL, 'Think Like a Rocket Scientist');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (329, 'روش فالکون', 'یک سیستم اثبات شده برای ایجاد درآمد غیرفعال و ثروت از طریق سرمایه گذاری سهام', 'یک سیستم اثبات شده برای ایجاد درآمد غیرفعال و ثروت از طریق سرمایه گذاری سهام', 25, 8, 'book', 't', '<p><em>روش FALCON </em>(2017) یک استراتژی سرمایه گذاری دقیق و اعداد محور را برای سرمایه گذاران معمولی ارائه می دهد. روش FALCON به سرمایه‌گذاران کمک می‌کند مجموعه‌ای از دارایی‌ها را ارزیابی کنند تا بهترین فرصت‌ها را بیابند و این کار را با استفاده از شاخص‌های مالی قابل اعتماد و یک رویکرد ساختاریافته برای محدود کردن سوگیری روان‌شناختی انجام می‌دهند.</p>', '2019-02-25 00:00:00', 4, 123, 'https://images.blinkist.io/images/books/5c7244b76cee070008ba6570/1_1/470.jpg', '/en/books/the-falcon-method-en/purchase', 'روش-فالکون', '2023-01-26 19:20:12.448337', '2023-01-26 19:20:12.448337', NULL, 'The FALCON Method');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (330, 'سمت بالا از پایین', 'چرا خوب شکست خوردن، کلید موفقیت است؟', 'چرا خوب شکست خوردن، کلید موفقیت است؟', 16, 9, 'book', 'f', '<p><em>The Up Side of Down </em>موضوع شکست را به‌عنوان بخش ارزشمندی از روند رشد ما ارائه می‌کند، و چیزی که باید از آن استقبال کنیم. علاوه بر این، این کتاب توصیه‌های درستی برای چگونگی مدیریت بهتر و کاهش شکست ما به عنوان یک فرد و جامعه ارائه می‌دهد.</p>', '2015-02-17 00:00:00', 4, 16, 'https://images.blinkist.io/images/books/54e35758303764000a030000/1_1/470.jpg', '/en/books/the-up-side-of-down-en/purchase', 'سمت-بالا-از-پایین', '2023-01-26 19:20:17.260445', '2023-01-26 19:20:17.260445', NULL, 'The Up Side of Down');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (331, 'لئوناردو داوینچی', 'بیوگرافی', 'بیوگرافی', 25, 10, 'book', 't', '<p><em>لئوناردو داوینچی</em> (2017) روایتی روشنگر و متفکرانه از یکی از مشهورترین افراد تاریخ است. ایزاکسون زندگی نامه ها و گزارش های قبلی از زندگی لئوناردو - از جمله اولین مورد از قرن شانزدهم - و همچنین یادداشت های فراوان لئوناردو را مطالعه کرده است. ایزاکسون پرتره ای بسیار انسانی از هنرمند و مهندس افسانه ای رنسانس می کشد. اگرچه لئوناردو یکی از معدود افرادی در تاریخ است که واقعاً می‌توان او را نابغه نامید، اما تنها انسان بود و از کنجکاوی و رویکرد او به زندگی چیزهای زیادی می‌توان آموخت.</p>', '2021-04-29 11:42:34.548', 5, 104, 'https://images.blinkist.io/images/books/608a9a3e6cee070007228a05/1_1/470.jpg', '/en/books/leonardo-da-vinci-en/purchase', 'لئوناردو-داوینچی', '2023-01-26 19:20:21.890094', '2023-01-26 19:20:21.890094', NULL, 'Leonardo Da Vinci');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (332, 'ریاضیات عشق', 'الگوها، اثبات ها و جستجوی معادله نهایی', 'الگوها، اثبات ها و جستجوی معادله نهایی', 20, 9, 'book', 't', '<p>عشق پر از الگوهاست - از تعداد شرکای جنسی که داریم تا نحوه انتخاب همسران احتمالی از وب‌سایت‌های دوستیابی. هانا فرای در <em>ریاضیات عشق</em> (2015)، این الگوها را روشن می‌کند و به شما می‌آموزد که چگونه شانس خود را برای یافتن The One محاسبه کنید، یک استدلال ریاضی برای توجیه نزدیک شدن به کسی در یک میله بیان کنید، و برای برنامه ریزی عروسی خود از یک ترفند ریاضی استفاده کنید.</p>', '2015-11-09 00:00:00', 4, 52, 'https://images.blinkist.io/images/books/5640536838663300070e0000/1_1/470.jpg', '/en/books/the-mathematics-of-love-en/purchase', 'ریاضیات-عشق', '2023-01-26 19:20:26.645894', '2023-01-26 19:20:26.645894', NULL, 'The Mathematics of Love');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (333, 'حل مسئله 101', 'کتابی ساده برای افراد باهوش', 'کتابی ساده برای افراد باهوش', 13, 6, 'book', 't', '<p><em>حل مسئله 101 </em>(2009) یک راهنمای کوتاه و سریع برای حل مسئله است. این کتاب که در اصل برای کمک به بچه‌ها برای حل مشکلات بهتر نوشته شده است، می‌تواند به هر کسی که می‌خواهد توانایی خود را برای حل مشکلات، بدون توجه به بزرگ یا کوچک بودن، بهبود بخشد.</p>', '2018-03-07 00:00:00', 4, 100, 'https://images.blinkist.io/images/books/5a9b37b1b238e1000791094a/1_1/470.jpg', '/en/books/problem-solving-101-en/purchase', 'حل-مسئله-101', '2023-01-26 19:20:32.586542', '2023-01-26 19:20:32.586542', NULL, 'Problem Solving 101');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (334, 'میلیونر', 'فیلاندرر، قمارباز و دوئلیستی که امور مالی مدرن را اختراع کرد', 'فیلاندرر، قمارباز و دوئلیستی که امور مالی مدرن را اختراع کرد', 20, 8, 'book', 't', '<p><em>میلیونر </em>(1999) داستان قمارباز و اقتصاددان اواخر قرن هفدهم جان لا را روایت می کند. در حالی که او اولین زندگی خود را به عنوان یک شیک پوش در انگلستان گذراند، به یک مقام مالی و اقتصاددان افسانه ای در قاره اروپا تبدیل شد. اگرچه ایده های لا در مورد اقتصاد و پول به طور خلاصه برای او و ملت فرانسه ثروتی باورنکردنی به ارمغان آورد، اما خطر ذاتی سفته بازی و رونق و رکود اقتصادی را نیز نشان داد. علیرغم شکست در زمان خود، چندین ایده او در طول زمان ارزش زیادی پیدا کردند و جزء ذاتی سیستم اقتصادی مدرن باقی ماندند.</p>', '2017-04-06 00:00:00', 4, 32, 'https://images.blinkist.io/images/books/58e20472fe685600046c935a/1_1/470.jpg', '/en/books/millionaire-en/purchase', 'میلیونر', '2023-01-26 19:20:37.290891', '2023-01-26 19:20:37.290891', NULL, 'Millionaire');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (335, 'پدر پولدار، بابای فقیر', 'آنچه ثروتمندان در مورد پول به فرزندان خود می آموزند – که فقرا و طبقه متوسط ​​نمی دهند!', 'آنچه ثروتمندان در مورد پول به فرزندان خود می آموزند – که فقرا و طبقه متوسط ​​نمی دهند!', 18, 9, 'book', 't', '<p>با ترکیب زندگی‌نامه و توصیه‌های شخصی، <em>پولدار</em> <em>پدر، پدر فقیر </em>(1997) چگونگی تبدیل شدن به استقلال مالی و ثروتمند شدن را تشریح می‌کند. نویسنده استدلال می کند که آنچه در این کتاب پرفروش <em>نیویورک تایمز</em> تدریس می کند، چیزهایی است که هرگز در جامعه به ما آموزش داده نمی شود، و آنچه طبقه بالا به فرزندان خود منتقل می کند دانش لازم برای به دست آوردن آن است ( و ماندن) ثروتمند. او به عنوان مدرکی برای حمایت از ادعاهای خود، از حرفه بسیار موفق خود به عنوان یک سرمایه گذار و بازنشستگی خود در سن 47 سالگی استناد می کند.</p>
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (336, 'جنگجوی درون', 'قدرت خود را برای خدمت، مبارزه، محافظت و شفا داشته باشید', 'قدرت خود را برای خدمت، مبارزه، محافظت و شفا داشته باشید', 16, 6, 'book', 't', '<p><em>The Warrior Within </em>(2022) به شما نشان می دهد که چگونه قدرت درونی خود را مهار و تقویت کنید تا بتوانید نقش های خود را در تجارت و زندگی ایفا کنید. بیابید که چگونه روحیه جنگجوی خود را پرورش دهید و با قدرت، فروتنی و ارتباط زندگی کنید.</p>', '2022-11-16 00:00:00', 4, 326, 'https://images.blinkist.io/images/books/637351fb73bf6d000e2d5851/1_1/470.jpg', '/en/books/the-warrior-within-en/purchase', 'جنگجوی-درون', '2023-01-26 19:20:47.228576', '2023-01-26 19:20:47.228576', NULL, 'The Warrior Within');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (337, 'ساید Hustle', 'از ایده تا درآمد در 27 روز', 'از ایده تا درآمد در 27 روز', 14, 6, 'book', 't', '<p><em>Side Hustle</em> (2017) توضیح می دهد که هر کسی می تواند یک پروژه جانبی سودآور را طراحی و راه اندازی کند. این جزئیات نحوه ایجاد درآمد در کوتاه مدت، با منابعی که از قبل در اختیار دارید، و بدون اینکه ریسک ترک شغل روزانه خود را بپذیرید، توضیح می دهد.</p>', '2017-10-05 00:00:00', 4, 121, 'https://images.blinkist.io/images/books/59d26133b238e10006d63700/1_1/470.jpg', '/en/books/side-hustle-en/purchase', 'ساید-Hustle', '2023-01-26 19:20:51.853262', '2023-01-26 19:20:51.853262', NULL, 'Side Hustle');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (338, 'حرکت', 'چگونه رهبران قاطع استراتژی را با وجود موانع، عقب‌نشینی‌ها و توقف اجرا می‌کنند', 'چگونه رهبران قاطع استراتژی را با وجود موانع، عقب‌نشینی‌ها و توقف اجرا می‌کنند', 21, 8, 'book', 't', '<p><em>Move</em> (2017) یک چارچوب عملی برای ایجاد تغییرات بلندمدت سازمانی ارائه می‌کند و مدل MOVE را معرفی می‌کند، که به کسب‌وکارها کمک می‌کند بر مسائل مزمن غلبه کنند، از شک و تردید کارکنان و اولویت‌بندی وظایف تا تبدیل ساختار مجدد به بخشی جدایی‌ناپذیر. فرهنگ شرکت.</p>', '2018-06-29 00:00:00', 4, 22, 'https://images.blinkist.io/images/books/5b2ff989b238e10007cdd536/1_1/470.jpg', '/en/books/move-en/purchase', 'حرکت', '2023-01-26 19:20:56.565737', '2023-01-26 19:20:56.565737', NULL, 'Move');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (339, 'همیشه شاد', 'فرار از افسانه زندگی کامل', 'فرار از افسانه زندگی کامل', 20, 7, 'book', 't', '<p><em>Happy Ever After</em> (2018) از ما می‌خواهد تا روایت‌های اجتماعی قدرتمندی را که بر زندگی ما تأثیر می‌گذارند، زیر سوال ببریم. این نشان می‌دهد که بسیاری از ایده‌هایی که بدون فکر به آن‌ها فکر می‌کنیم، از احساس اینکه باید سخت کار کنیم و پول بیشتری به دست آوریم تا تمایل به ازدواج با فرزندان، لزوما ما را خوشحال نمی‌کند. و این یک استدلال قوی ارائه می دهد که ما باید مسیر خود را برای یک زندگی کامل پیدا کنیم.</p>', '2019-02-07 00:00:00', 4, 74, 'https://images.blinkist.io/images/books/5c5aa30d6cee0700085d0fa1/1_1/470.jpg', '/en/books/happy-ever-after-en/purchase', 'همیشه-شاد', '2023-01-26 19:21:01.774046', '2023-01-26 19:21:01.774046', NULL, 'Happy Ever After');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (340, 'اراده', 'مشاهدات الهام بخش و درس های زندگی', 'مشاهدات الهام بخش و درس های زندگی', 24, 7, 'book', 't', '<p><em>ویل </em> (2022) روایتی دست اول از یکی از بهترین حرفه های هالیوود است. با این حال ویل اسمیت فقط موفقیت‌های متعدد خود را محاسبه نمی‌کند. او همچنین در مورد مبارزات، کاستی‌ها و کمک‌هایی که در این راه دریافت کرده است، صحبت می‌کند.</p>', '2022-03-31 00:00:00', 4, 240, 'https://images.blinkist.io/images/books/624587fe6cee070008e2032b/1_1/470.jpg', '/en/books/will-en/purchase', 'اراده', '2023-01-26 19:21:07.061757', '2023-01-26 19:21:07.061757', NULL, 'Will');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (342, 'هنر سفر', 'بیاموزید که چگونه از ماجراجویی سفر بعدی خود بیشترین بهره را ببرید', 'بیاموزید که چگونه از ماجراجویی سفر بعدی خود بیشترین بهره را ببرید', 22, 8, 'book', 't', '<p><em>هنر سفر </em>(2002) یک راهنمای غیرمتعارف برای سفر است. برخلاف راهنماهای معمولی سفر، کتاب آلن دو باتون بیشتر یک کتاب راهنمای فلسفی جهانگردی است که دلایل تمایل ما به کشف مکان‌های جدید را بررسی می‌کند و نکات کلی را برای لذت‌بخش‌تر کردن سفر ارائه می‌دهد.</p>', '2018-07-04 00:00:00', 4, 66, 'https://images.blinkist.io/images/books/5b39b299b238e10007ffd9bf/1_1/470.jpg', '/en/books/the-art-of-travel-en/purchase', 'هنر-سفر', '2023-01-26 19:21:17.091582', '2023-01-26 19:21:17.091582', NULL, 'The Art of Travel');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (343, 'ذهن های دیگر', 'اختاپوس و تکامل زندگی هوشمند', 'اختاپوس و تکامل زندگی هوشمند', 15, 6, 'book', 't', '<p><em>Other Minds </em>(2016) کاوشی در مورد تکامل اختاپوس است. اختاپوس زمانی موجودی لنگ مانندی بود که در اعماق اقیانوس می خزید، اکنون یک شکارچی باهوش و منحصر به فرد است. پیتر گادفری اسمیت خواننده را از طریق میلیاردها سال تاریخ تکاملی راهنمایی می کند تا توسعه زندگی پیچیده را توضیح دهد و در عین حال یکی از جذاب ترین حیوانات جهان را روشن کند.</p>', '2018-03-21 00:00:00', 4, 99, 'https://images.blinkist.io/images/books/5aae8ab3b238e100069e8f83/1_1/470.jpg', '/en/books/other-minds-en/purchase', 'ذهن-های-دیگر', '2023-01-26 19:21:22.01647', '2023-01-26 19:21:22.01647', NULL, 'Other Minds');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (344, 'روز به روز خود را مدیریت کنید', 'روال خود را بسازید، تمرکز خود را پیدا کنید و ذهن خلاق خود را تیز کنید', 'روال خود را بسازید، تمرکز خود را پیدا کنید و ذهن خلاق خود را تیز کنید', 18, 8, 'book', 't', '<p><em>مدیریت روزانه خود</em> مجموعه ای از ایده ها، حکمت ها و نکات افراد خلاق شناخته شده است. این به خوانندگان بینش ارزشمندی در مورد چگونگی توسعه روال های کاری مؤثر، متمرکز ماندن و رها کردن خلاقیت آنها ارائه می دهد.</p>', '2014-10-07 00:00:00', 4, 158, 'https://images.blinkist.io/images/books/54327f0c3835330008730000/1_1/470.jpg', '/en/books/manage-your-day-to-day-en/purchase', 'روز-به-روز-خود-را-مدیریت-کنید', '2023-01-26 19:21:27.096075', '2023-01-26 19:21:27.096075', NULL, 'Manage Your Day-To-Day');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (345, 'جرات رهبری (نسخه جدید)', 'کار شجاعانه گفتگوهای سخت قلب های کامل', 'کار شجاعانه گفتگوهای سخت قلب های کامل', 21, 6, 'book', 't', '<p><em>جرات رهبری</em> (2018) به بررسی چگونگی یافتن شجاعت درونی برای رهبری یک تیم عالی می پردازد. با تکیه بر تحقیقات و تجربه برنه براون به عنوان یک مربی رهبری، نشان می دهد که چگونه می توانید احساسات خود را مهار کنید، ترس از شکست خود را از بین ببرید، و به یک رهبر جسور در دنیای رقابتی تبدیل شوید. </p>', '2022-07-06 00:00:00', 4, 391, 'https://images.blinkist.io/images/books/62bd96bd6cee0700092f2083/1_1/470.jpg', '/en/books/dare-to-lead-new-version-en/purchase', 'جرات-رهبری-(نسخه-جدید)', '2023-01-26 19:26:56.403412', '2023-01-26 19:26:56.403412', NULL, 'Dare to Lead (New Version)');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (346, 'تحریک', 'چگونه رهبران آینده را با غلبه بر نقص های مرگبار انسانی شکل می دهند', 'چگونه رهبران آینده را با غلبه بر نقص های مرگبار انسانی شکل می دهند', 18, 4, 'book', 't', '<p><em>Provoke </em>(2021) از کارآفرینان تحریک‌آمیز درس‌هایی می‌گیرد که روندهای کلیدی را زود شناسایی کرده و آنها را به موفقیت خارق‌العاده رساندند. علاوه بر این، با تشریح اصول کلیدی استراتژی آینده‌محور، نشان می‌دهد که چگونه هر کسی می‌تواند برای برانگیختن نتایج آینده‌ای که برای کسب‌وکار خود می‌خواهد عمل کند.</p>', '2022-11-28 00:00:00', 5, 21, 'https://images.blinkist.io/images/books/637ccf6b4b900400085fa86b/1_1/470.jpg', '/en/books/provoke-en/purchase', 'تحریک', '2023-01-26 19:27:01.623031', '2023-01-26 19:27:01.623031', NULL, 'Provoke');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (347, 'سوئیچ لایک', 'راهنمای یک مامور سابق اف بی آی برای تأثیرگذاری، جذب و جلب نظر مردم', 'راهنمای یک مامور سابق اف بی آی برای تأثیرگذاری، جذب و جلب نظر مردم', 13, 6, 'book', 't', '<p>در <em>The Like Switch</em>، نویسنده جک شفر قلمرو نشانه‌های اجتماعی غیرکلامی و سایر شیوه‌های ارتباطی را که افراد را به سمت یکدیگر می‌کشاند، بررسی می‌کند. شفر یک مامور سابق اف بی آی و دکترای روانشناسی، استراتژی های مفیدی را برای پیدا کردن دوستان جدید و تاثیرگذاری بر مردم ارائه می دهد.</p>', '2015-03-19 00:00:00', 4, 160, 'https://images.blinkist.io/images/books/55062be3666365000a7a0000/1_1/470.jpg', '/en/books/the-like-switch-en/purchase', 'سوئیچ-لایک', '2023-01-26 19:27:06.356177', '2023-01-26 19:27:06.356177', NULL, 'The Like Switch');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (348, 'هدف', 'نقطه شروع شرکت های بزرگ', 'نقطه شروع شرکت های بزرگ', 18, 8, 'book', 't', '<p><em>هدف</em> (2006) نشان می دهد که چقدر ارزش ها برای رهبری قوی در قرن بیست و یکم مهم است. این پلک‌ها چهار شکل مختلف هدف را توضیح می‌دهند که به شما و کسب‌وکارتان اجازه می‌دهد تا پیشرفت کنید، از زیربنای اخلاقی آن‌ها تا استفاده موفقیت‌آمیز آن‌ها توسط تأثیرگذارترین رهبران امروزی.</p>', '2015-08-14 00:00:00', 4, 34, 'https://images.blinkist.io/images/books/55c8b1fe38646400074d0000/1_1/470.jpg', '/en/books/purpose-en/purchase', 'هدف', '2023-01-26 19:27:11.014534', '2023-01-26 19:27:11.014534', NULL, 'Purpose');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (349, 'نام تجاری ناخودآگاه', 'چگونه علوم اعصاب می تواند بازاریابی را تقویت کند (و الهام بخشد).', 'چگونه علوم اعصاب می تواند بازاریابی را تقویت کند (و الهام بخشد).', 20, 9, 'book', 't', '<p><em>برندسازی ناخودآگاه </em>(2012) نشان می‌دهد که چگونه بازاریابان می‌توانند از ضمیر ناخودآگاه ما استفاده کنند و مشارکت و حمایت ما از برندهای شرکت را تشویق کنند. تنها در هفت مرحله، استراتژی‌های جدیدی را کشف خواهید کرد تا شرکت خود را به سمت توسعه برندی هدایت کنید که مشتریان بتوانند با آن یک رابطه واقعی ایجاد کنند.</p>', '2015-09-08 00:00:00', 5, 86, 'https://images.blinkist.io/images/books/55ed285511ad1a000900002c/1_1/470.jpg', '/en/books/unconscious-branding-en/purchase', 'نام-تجاری-ناخودآگاه', '2023-01-26 19:27:16.171307', '2023-01-26 19:27:16.171307', NULL, 'Unconscious Branding');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (351, 'آسیا چگونه کار می کند', 'موفقیت و شکست در پویاترین منطقه جهان', 'موفقیت و شکست در پویاترین منطقه جهان', 19, 8, 'book', 't', '<p><em>چگونه آسیا کار می کند</em> توسعه اقتصادی 9 کشور آسیایی را بررسی می کند و در این فرآیند، طرحی را برای سایر کشورهای در حال توسعه که به دنبال دستیابی به رشد اقتصادی پایدار هستند ترسیم می کند. جو استادول توضیح می دهد که چرا برخی از اقتصادهای آسیایی رونق گرفته اند در حالی که برخی دیگر عقب مانده اند و نشان می دهد که تاریخ چه چیزی کار می کند - و چه چیزی کار نمی کند.</p>', '2015-12-23 00:00:00', 4, 46, 'https://images.blinkist.io/images/books/567866de0bac9b0007000015/1_1/470.jpg', '/en/books/how-asia-works-en/purchase', 'آسیا-چگونه-کار-می-کند', '2023-01-26 19:27:27.407005', '2023-01-26 19:27:27.407005', NULL, 'How Asia Works');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (352, 'جادوی واقعیت', 'چگونه می دانیم چه چیزی واقعاً درست است', 'چگونه می دانیم چه چیزی واقعاً درست است', 26, 11, 'book', 't', '<p><em>جادوی واقعیت </em>(2011) با مرور روش هایی که دانشمندان پدیده های طبیعی را که زمانی تصور می شد ماوراء طبیعی هستند توضیح داده اند، مقدمه ای بر تفکر علمی ارائه می دهد. استدلال علمی چه برای روشن کردن اجزای سازنده جهان و چه توضیح منشأ حیات، پاسخی دارد.</p>', '2015-11-05 00:00:00', 4, 108, 'https://images.blinkist.io/images/books/56377e6c6234650007b60000/1_1/470.jpg', '/en/books/the-magic-of-reality-en/purchase', 'جادوی-واقعیت', '2023-01-26 19:27:33.457136', '2023-01-26 19:27:33.457136', NULL, 'The Magic of Reality');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (353, 'لذت حرکت', 'چگونه ورزش به ما کمک می کند تا شادی، امید، ارتباط و شجاعت را پیدا کنیم', 'چگونه ورزش به ما کمک می کند تا شادی، امید، ارتباط و شجاعت را پیدا کنیم', 22, 7, 'book', 't', '<p><em>لذت حرکت </em>(2019) یک مورد الهام‌بخش و بسیار بدیع برای ورزش می‌سازد. نویسنده کلی مک گونیگال با تکیه بر آخرین بینش‌های زیست‌شناسی، علوم اعصاب و روان‌شناسی تکاملی به ما نشان می‌دهد که مزایای ورزش بسیار فراتر از بهبود سلامت جسمانی ماست. او با علم سخت و حکایات واقعی زندگی نشان می دهد که چگونه حرکت به ما امید، معنا و ارتباط می دهد - و توضیح می دهد که چگونه همه می توانند از قدرت های مثبت آن استفاده کنند.</p>', '2020-02-19 00:00:00', 5, 201, 'https://images.blinkist.io/images/books/5e4bc50a6cee070006209ee5/1_1/470.jpg', '/en/books/the-joy-of-movement-en/purchase', 'لذت-حرکت', '2023-01-26 19:27:37.405145', '2023-01-26 19:27:37.405145', NULL, 'The Joy of Movement');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (354, 'مرزها', 'چه زمانی بله بگوییم، چگونه نه بگوییم تا کنترل زندگی خود را در دست بگیریم', 'چه زمانی بله بگوییم، چگونه نه بگوییم تا کنترل زندگی خود را در دست بگیریم', 23, 8, 'book', 't', '<p><em>Boundaries</em>(1992) یک کتاب راهنما برای کسانی است که نمی توانند نه بگویند، کسانی که نه را به عنوان پاسخ قبول نمی کنند، و همه افراد در این بین. این کتاب که به طور مساوی در ایمان مسیحی و روانشناسی معاصر استوار است، استدلالی شیوا برای ضرورت عاطفی و معنوی مرزهای محکم و سالم است.</p>', '2020-07-09 00:00:00', 4, 456, 'https://images.blinkist.io/images/books/5eff4a216cee070006b9c3f3/1_1/470.jpg', '/en/books/boundaries-en/purchase', 'مرزها', '2023-01-26 19:27:43.328317', '2023-01-26 19:27:43.328317', NULL, 'Boundaries');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (355, 'چگونه دوست داشته باشیم', 'درس های آگاهانه در مورد عشق', 'درس های آگاهانه در مورد عشق', 21, 8, 'book', 't', '<p><em>چگونه عشق بورزیم </em>(2015) مجموعه ای ضروری از آموزه های مربوط به عشق از استاد مشهور جهان ذن بودایی، تیچ نات هان است. مملو از خرد و بصیرت، این کتابچه راهنما رمز و راز عشق واقعی را در کاوش در مورد معنای دوست داشتن خود، شرکایمان و خود جهان باز می کند.</p>', '2018-12-25 00:00:00', 4, 298, 'https://images.blinkist.io/images/books/5c1ebe216cee070007b45c00/1_1/470.jpg', '/en/books/how-to-love-en/purchase', 'چگونه-دوست-داشته-باشیم', '2023-01-26 19:27:48.076551', '2023-01-26 19:27:48.076551', NULL, 'How to Love');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (356, 'وقتی درباره دویدن صحبت می کنم از چه چیزی صحبت می کنم', 'خاطره ای در مورد دویدن و نوشتن', 'خاطره ای در مورد دویدن و نوشتن', 24, 8, 'book', 't', '<p><em>What I Talk About When I Talk About Running </em>(2009) خاطراتی است درباره تلاقی دو شور انفرادی: دویدن و نوشتن. در این اثر شخصی، نویسنده هاروکی موراکامی نگاهی صمیمانه به نحوه اطلاع رسانی این دو عمل به دنیای درونی او می‌کند. </p>', '2020-08-15 00:00:00', 4, 105, 'https://images.blinkist.io/images/books/5f3192d56cee07000660655d/1_1/470.jpg', '/en/books/what-i-talk-about-when-i-talk-about-running-en/purchase', 'وقتی-درباره-دویدن-صحبت-می-کنم-از-چه-چیزی-صحبت-می-کنم', '2023-01-26 19:27:53.141338', '2023-01-26 19:27:53.141338', NULL, 'What I Talk About When I Talk About Running');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (357, 'هر چیزی را بپیچانید', 'روشی نوآورانه برای ارائه، متقاعد کردن و برنده شدن در معامله', 'روشی نوآورانه برای ارائه، متقاعد کردن و برنده شدن در معامله', 17, 9, 'book', 't', '<p><em>Pitch Anything</em> (2011) یک روش منحصر به فرد و جدید برای طرح ایده ها معرفی می کند. کلاف از طریق روانشناسی، علوم اعصاب و حکایات شخصی، تاکتیک ها و تکنیک های مورد نیاز برای ارائه موفقیت آمیز هر چیزی را برای هر کسی توضیح می دهد.</p>', '2013-03-01 00:00:00', 4, 207, 'https://images.blinkist.io/images/books/50d7294be4b045383aa45e1e/1_1/470.jpg', '/en/books/pitch-anything-en/purchase', 'هر-چیزی-را-بپیچانید', '2023-01-26 19:27:58.028279', '2023-01-26 19:27:58.028279', NULL, 'Pitch Anything');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (358, 'تحمل کن', 'ذهن، بدن و محدودیت های عجیب الاستیک عملکرد انسان', 'ذهن، بدن و محدودیت های عجیب الاستیک عملکرد انسان', 22, 8, 'book', 't', '<p><em>Endure</em> (2018) نگاهی ژرف به آنچه که ورزشکاران خاصی را که مرز را فشار می دهند قادر می سازد به دیوار درد و تلاش ضربه بزنند - و همچنان ادامه دهند، می کند. الکس هاچینسون عوامل متعدد و پیچیده ای را بررسی می کند که به دوندگان ماراتن و دوچرخه سواران اجازه می دهد رکوردها را بشکنند و به ارتفاعات جدیدی در استقامت انسانی دست یابند.</p>', '2018-06-28 00:00:00', 4, 147, 'https://images.blinkist.io/images/books/5b2fe66cb238e10006f8a875/1_1/470.jpg', '/en/books/endure-en/purchase', 'تحمل-کن', '2023-01-26 19:28:03.945423', '2023-01-26 19:28:03.945423', NULL, 'Endure');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (360, 'گره گشای تو', 'چگونه می توانم سپاسگزار باشم وقتی اینقدر احساس رنجش می کنم؟', 'چگونه می توانم سپاسگزار باشم وقتی اینقدر احساس رنجش می کنم؟', 25, 4, 'book', 't', '<p><em>تو را باز کردن</em> (2021) راهنمایی برای دستیابی به قدردانی از طریق نقطه مقابل مفهومی آن، رنجش است. با تکیه بر تحقیقات، حکایات و بینش‌های عملی، چگونگی حرکت از رنجش به قدردانی به شما کمک می‌کند تا روابط را بهبود بخشید و زندگی شادتر و سالم‌تری داشته باشید.</p>', '2022-09-05 00:00:00', 5, 250, 'https://images.blinkist.io/images/books/630dd04a6cee070008008249/1_1/470.jpg', '/en/books/untangling-you-en/purchase', 'گره-گشای-تو', '2023-01-26 19:28:14.442411', '2023-01-26 19:28:14.442411', NULL, 'Untangling You');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (361, 'چگونه یک زندگی خوب داشته باشیم', 'راهنمای انتخاب فلسفه شخصی', 'راهنمای انتخاب فلسفه شخصی', 27, 9, 'book', 't', '<p><em>چگونه یک زندگی خوب داشته باشیم </em>(2020)، ویرایش شده توسط ماسیمو پیگلیوچی، اسکای کلیری و دانیل کافمن، مقدمه ای است بر 15 فلسفه برای زندگی کردن. از ایدئولوژی های باستانی، از طریق ادیان اصلی، تا مکاتب فکری معاصر، 15 محقق برجسته ما را با فلسفه هایی که زندگی آنها را هدایت می کند، روشن می کنند.</p>', '2020-07-03 00:00:00', 4, 418, 'https://images.blinkist.io/images/books/5ef9ecc86cee07000655a097/1_1/470.jpg', '/en/books/how-to-live-a-good-life-en/purchase', 'چگونه-یک-زندگی-خوب-داشته-باشیم', '2023-01-26 19:28:19.602541', '2023-01-26 19:28:19.602541', NULL, 'How to Live a Good Life');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (362, 'استادان فاجعه', 'ده فرمان کنترل خسارت', 'ده فرمان کنترل خسارت', 13, 7, 'book', 'f', '<p><em>Masters of Disaster </em>شما را به سفری در بحرانی می برد که مشخصه عصر اطلاعات امروز است. نویسندگان با تکیه بر عملیات کنترل آسیب، ده فرمان را برای کمک به هر سیاستمدار، سلبریتی یا شرکتی ایجاد کرده اند تا از رسوایی و شهرت لکه دار جلوگیری کند.</p>', '2015-03-03 00:00:00', NULL, 2, 'https://images.blinkist.io/images/books/54f579dc373031000a010000/1_1/470.jpg', '/en/books/masters-of-disaster-en/purchase', 'استادان-فاجعه', '2023-01-26 19:28:25.389583', '2023-01-26 19:28:25.389583', NULL, 'Masters of Disaster');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (363, 'ملت استارت آپ', 'داستان معجزه اقتصادی اسرائیل', 'داستان معجزه اقتصادی اسرائیل', 13, 7, 'book', 'f', '<p>برای یک کشور کوچک، اسرائیل به عنوان مرکز جهانی نوآوری و کارآفرینی فناوری، بسیار بالاتر از وزن خود است. <em>ملت استارت‌آپ</em> تاریخ، ژئوپلیتیک و فرهنگ کشور را بررسی می‌کند تا بفهمد این انرژی خلاق از کجا می‌آید، و داستان‌هایی از شرکت‌هایی ارائه می‌دهد که نمونه‌ای از روش‌های متمایز هدایت این انگیزه هستند.</p >', '2015-03-05 00:00:00', 4, 22, 'https://images.blinkist.io/images/books/54f59ff6623735000a850000/1_1/470.jpg', '/en/books/start-up-nation-en/purchase', 'ملت-استارت-آپ', '2023-01-26 19:28:31.041868', '2023-01-26 19:28:31.041868', NULL, 'Start-Up Nation');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (364, 'مخمر نمک آب آرد', 'اصول نان و پیتزا صنعتگر', 'اصول نان و پیتزا صنعتگر', 28, 9, 'book', 't', '<p><em>مخمر نمک آب آرد</em> (2012) توسط کن فورکیش، راهنمای اصولی است که در زمینه پخت با کیفیت بالا وجود دارد، که می توانید آن را برای پخت خود در خانه اعمال کنید. با یادگیری اصول اولیه و ایجاد یک تکنیک خوب، می توانید بر هنر پخت خانگی تسلط داشته باشید و سبک پخت فردی خود را توسعه دهید.</p>', '2020-05-16 00:00:00', 4, 19, 'https://images.blinkist.io/images/books/5ebd213b6cee070006b320e9/1_1/470.jpg', '/en/books/flour-water-salt-yeast-en/purchase', 'مخمر-نمک-آب-آرد', '2023-01-26 19:28:36.837131', '2023-01-26 19:28:36.837131', NULL, 'Flour Water Salt Yeast');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (365, 'با چرا شروع کنید', 'چگونه رهبران بزرگ همه را تشویق به اقدام می کنند', 'چگونه رهبران بزرگ همه را تشویق به اقدام می کنند', 22, 7, 'book', 't', '<p><em>شروع با چرا</em>(2011) به یک سوال اساسی می پردازد: چه چیزی باعث می شود برخی سازمان ها و افراد نوآورتر، تاثیرگذارتر و سودآورتر از سایرین باشند؟ بر اساس سخنرانی بسیار تاثیرگذار سایمون سینک، نویسنده پرفروش، به همین نام، سومین سخنرانی پربیننده TED در تمام دوران، این پلک ها پاسخ این معما را باز می کنند. همانطور که نمونه‌های سینک از دنیای تجارت، سیاست و فناوری نشان می‌دهد، همه چیز در مورد پرسیدن «چرا؟» است. به جای «چی؟»</p>', '2014-02-04 09:00:00', 5, 1032, 'https://images.blinkist.io/images/books/52bec76a3933330008000000/1_1/470.jpg', '/en/books/start-with-why-en/purchase', 'با-چرا-شروع-کنید', '2023-01-26 19:28:42.850855', '2023-01-26 19:28:42.850855', NULL, 'Start with Why');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (366, 'Livewired', 'داستان درونی مغز در حال تغییر', 'داستان درونی مغز در حال تغییر', 21, 7, 'book', 't', '<p><em>Livewired </em>(2020) کاوشی در مورد چگونگی پیکربندی مجدد مغز دائماً خود است. با یادگیری اطلاعات جدید در مورد دنیای اطراف، مغز تغییر شکل می دهد. ما همیشه بیشتر در مورد سازگاری شگفت انگیز آن کشف می کنیم.</p>', '2021-04-01 00:00:00', 5, 223, 'https://images.blinkist.io/images/books/6061d7046cee0700078c0d78/1_1/470.jpg', '/en/books/livewired-en/purchase', 'Livewired', '2023-01-26 19:28:46.792357', '2023-01-26 19:28:46.792357', NULL, 'Livewired');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (367, 'سلامت روان و رفاه در محیط کار', 'راهنمای عملی برای کارفرمایان و کارمندان', 'راهنمای عملی برای کارفرمایان و کارمندان', 18, 6, 'book', 't', '<p><em>سلامت روان و رفاه در محیط کار </em>(2020) توضیح می‌دهد که چگونه سازمان‌ها و افراد می‌توانند سلامت روانی بهتر در محل کار را ارتقا دهند. نویسندگان علل و اثرات سلامت روان ضعیف در مطب را بررسی می‌کنند و مسیر بازگشت به سلامتی را روشن می‌کنند.</p>', '2020-10-26 00:00:00', 4, 150, 'https://images.blinkist.io/images/books/5f929f8b6cee07000608db5d/1_1/470.jpg', '/en/books/mental-health-and-wellbeing-in-the-workplace-en/purchase', 'سلامت-روان-و-رفاه-در-محیط-کار', '2023-01-26 19:28:52.403567', '2023-01-26 19:28:52.403567', NULL, 'Mental Health and Wellbeing in the Workplace');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (368, 'رهبران بزرگ هیچ قانونی ندارند', 'اصول رهبری متضاد برای متحول کردن تیم و تجارت شما', 'اصول رهبری متضاد برای متحول کردن تیم و تجارت شما', 27, 8, 'book', 't', '<p><em>رهبران بزرگ قوانینی ندارند </em>(2019) رهبران را به چالش می کشد تا رویکردی متضاد را برای مدیریت افراد و زمان خود اتخاذ کنند تا آنها راحت تر و سریع تر به موفقیت دست یابند. با شناسایی ایرادات در شیوه‌های رهبری سنتی یا معمولی، نشان می‌دهد که چرا مخالفت با اصول منجر به نتایج بهتری می‌شود.</p>', '2021-05-27 00:00:00', 5, 201, 'https://images.blinkist.io/images/books/60ae4f566cee0700084a2b60/1_1/470.jpg', '/en/books/great-leaders-have-no-rules-en/purchase', 'رهبران-بزرگ-هیچ-قانونی-ندارند', '2023-01-26 19:28:58.280538', '2023-01-26 19:28:58.280538', NULL, 'Great Leaders Have No Rules');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (369, 'Loonshots', 'چگونه می توان ایده های دیوانه کننده ای را پرورش داد که در جنگ ها پیروز می شوند، بیماری ها را درمان می کنند و صنایع را متحول می کنند', 'چگونه می توان ایده های دیوانه کننده ای را پرورش داد که در جنگ ها پیروز می شوند، بیماری ها را درمان می کنند و صنایع را متحول می کنند', 26, 8, 'book', 't', '<p><em>Loonshots </em> (2019) موضوعی را بررسی می کند که برای موفقیت ارتش ایالات متحده به همان اندازه که برای شرکت هایی که آن را در میدان نبرد استعاری مطرح می کنند مهم است: نوآوری. صفی باکال با تکیه بر انبوهی از نمونه های تاریخی روشنگر نشان می دهد که اکتشافات و اختراعات راهگشا محصول نوابغ منزوی نیست که شیارهای تنهایی خود را شخم می زنند، بلکه نتیجه ساختارهای سازمانی است که تفکر خارج از چارچوب را تقویت می کند. /p>', '2019-04-18 00:00:00', 5, 176, 'https://images.blinkist.io/images/books/5cb5cef86cee070007d4e0e6/1_1/470.jpg', '/en/books/loonshots-en/purchase', 'Loonshots', '2023-01-26 19:29:04.39094', '2023-01-26 19:29:04.39094', NULL, 'Loonshots');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (370, 'حواس پرت نشده', 'هدف خود را ضبط کنید. شادی خود را دوباره کشف کنید.', 'هدف خود را ضبط کنید. شادی خود را دوباره کشف کنید.', 19, 5, 'book', 't', '<p><em>بی حواس پرتی </em>(2022) فراخوانی است به سلاح در برابر یکی از بزرگترین نیروهایی که شما را از داشتن بهترین زندگی باز می دارد: حواس پرتی. زندگی پر از آن است. چرخه اخبار 24 ساعته. گوشی هوشمند شما نگران این هستید که همکارانتان چه فکر می کنند و همسایگانتان چه دارند. لیست کارهای بی پایان همه آن منابع حواس پرتی مانع از آنچه واقعاً مهم است - زندگی پر از شادی، عشق، و نیت.</p>', '2022-05-23 00:00:00', 4, 381, 'https://images.blinkist.io/images/books/628799266cee07000852a9c1/1_1/470.jpg', '/en/books/undistracted-en/purchase', 'حواس-پرت-نشده', '2023-01-26 19:29:09.848808', '2023-01-26 19:29:09.848808', NULL, 'Undistracted');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (371, 'دوگانگی رهبری', 'متعادل کردن چالش های مالکیت افراطی برای رهبری و پیروزی', 'متعادل کردن چالش های مالکیت افراطی برای رهبری و پیروزی', 18, 6, 'book', 't', '<p><em>دوگانگی رهبری </em>(2018) تجربیات خارق العاده دو فرمانده سابق نیروی دریایی SEAL را روایت می کند. جوکو ویلینک و لیف بابین، زمانی که در بغداد و رمادی در طول جنگ عراق مستقر بودند، تجربیاتی را جمع آوری کردند که به آنها کمک کرد تا رهبران مؤثری شوند. پس از بازگشت به زندگی غیرنظامی، آنها متوجه شدند که این مهارت های رهبری در دنیای تجارت به همان اندازه موثر است. آنها دریافتند که در هر دو زمینه جنگی و غیر جنگی، شما فقط می توانید بر دوگانگی های رهبری غلبه کنید و با یافتن حس تعادل بین نیروهای مخالف، سازمان را به طور مؤثر اداره کنید.</p>', '2019-04-08 00:00:00', 4, 101, 'https://images.blinkist.io/images/books/5ca9a7646cee070007843440/1_1/470.jpg', '/en/books/the-dichotomy-of-leadership-en/purchase', 'دوگانگی-رهبری', '2023-01-26 19:29:15.178291', '2023-01-26 19:29:15.178291', NULL, 'The Dichotomy of Leadership');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (372, 'آغاز بی نهایت', 'توضیحاتی که جهان را متحول می کند', 'توضیحاتی که جهان را متحول می کند', 20, 10, 'book', 't', '<p>هر روز، ما از پیشرفت های عظیمی در تئوری و عمل علمی بهره مند می شویم. چه چیزی باعث این پیشرفت شد؟ فیزیکدان دیوید دویچ در <em>آغاز بی نهایت</em> (2011) - سفری در زمینه های اساسی علم و فلسفه - استدلال می کند که تمام پیشرفت ها از یک فعالیت انسانی منتج می شود: جستجو برای توضیح. خلاقیت انسان فرصت های بی حد و حصری را برای پیشرفت باز می کند و دانش را به "آغاز بی نهایت" تبدیل می کند.</p>', '2015-12-02 00:00:00', 4, 126, 'https://images.blinkist.io/images/books/565c7e8c9906750007000051/1_1/470.jpg', '/en/books/the-beginning-of-infinity-en/purchase', 'آغاز-بی-نهایت', '2023-01-26 19:29:20.942703', '2023-01-26 19:29:20.942703', NULL, 'The Beginning of Infinity');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (373, 'پزشکی قانونی', 'آنچه اشکالات، سوختگی ها، چاپ ها، DNA و موارد دیگر در مورد جرم به ما می گویند', 'آنچه اشکالات، سوختگی ها، چاپ ها، DNA و موارد دیگر در مورد جرم به ما می گویند', 29, 12, 'book', 't', '<p><em>Forensics</em> (2014) نگاهی درونی به دنیای بیمارگونه تحقیقات پزشکی قانونی ارائه می دهد. پر از تاریخچه و حکایات جذاب از پرونده های جنایی واقعی، <em>پزشکی قانونی</em> یک نمای کلی کامل و قانع کننده از همه چیزهایی که در طول بررسی صحنه جرم اتفاق می افتد به شما ارائه می دهد.</p>', '2015-10-22 00:00:00', 5, 13, 'https://images.blinkist.io/images/books/562498fb63613100070f0000/1_1/470.jpg', '/en/books/forensics-en/purchase', 'پزشکی-قانونی', '2023-01-26 19:29:26.972486', '2023-01-26 19:29:26.972486', NULL, 'Forensics');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (381, 'نابغه مخالفان', 'چگونه درونگراها و برونگراها با هم به نتایج فوق العاده ای دست می یابند', 'چگونه درونگراها و برونگراها با هم به نتایج فوق العاده ای دست می یابند', 9, 4, 'book', 't', '<p><em>The Genius of Opposites </em>(2015) پتانسیل مشارکت بین تیپ های شخصیتی ظاهراً ناسازگار را روشن می کند: برونگراها و درونگراها. این پلک ها پنج مرحله اساسی را نشان می دهد که می تواند نامحتمل ترین شراکت های تجاری را به موفق ترین آنها تبدیل کند. </p>', '2016-02-03 00:00:00', 4, 22, 'https://images.blinkist.io/images/books/56afa5d7377c160007000052/1_1/470.jpg', '/en/books/the-genius-of-opposites-en/purchase', 'نابغه-مخالفان', '2023-01-26 19:30:11.691306', '2023-01-26 19:30:11.691306', NULL, 'The Genius of Opposites');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (374, 'عالی با انتخاب', 'عدم قطعیت، هرج و مرج، و شانس - چرا برخی با وجود همه آنها پیشرفت می کنند؟', 'عدم قطعیت، هرج و مرج، و شانس - چرا برخی با وجود همه آنها پیشرفت می کنند؟', 17, 8, 'book', 't', '<p>جهان مکانی نامشخص است، دائماً در حال تغییر و اغلب آشفته است. در حالی که بسیاری از شرکت ها نمی توانند در این هرج و مرج دوام بیاورند، برخی از شرکت ها نه تنها قادر به ادامه حیات در این شرایط در حال تغییر هستند، بلکه حتی در آنها پیشرفت می کنند. <em>Great by Choice</em> تجزیه و تحلیل می کند که چرا این شرکت ها موفق می شوند در حالی که اکثر شرکت ها شکست می خورند. </p>
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (375, 'پرواز', 'گذرگاه متهورانه و جاودانه چارلز لیندبرگ در سال 1927', 'گذرگاه متهورانه و جاودانه چارلز لیندبرگ در سال 1927', 20, 7, 'book', 't', '<p><em>پرواز </em>(2017) روایتی جذاب از پرواز انفرادی پیشگامانه چارلز لیندبرگ در سراسر اقیانوس اطلس، از نیویورک به پاریس است. نویسنده دن همپتون علاوه بر شرح مفصلی از وضعیت لیندبرگ در کابین خلبان، زمینه تاریخی و بیوگرافی ارزشمندی را اضافه می کند که نشان می دهد چرا پرواز <em>روح سنت لوئیس</em> برای بسیاری از افراد بسیار مهم بوده است. مردم. </p>', '2019-12-27 00:00:00', 4, 28, 'https://images.blinkist.io/images/books/5dfcb81a6cee0700087f97c9/1_1/470.jpg', '/en/books/the-flight-en/purchase', 'پرواز', '2023-01-26 19:29:38.187621', '2023-01-26 19:29:38.187621', NULL, 'The Flight');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (376, 'به مبارزه بی خوابی پایان دهید', 'راهنمای گام به گام برای کمک به خوابیدن و ماندن در خواب', 'راهنمای گام به گام برای کمک به خوابیدن و ماندن در خواب', 14, 6, 'book', 't', '<p><em>پایان دادن به مبارزه بی خوابی</em> (2016) راهنمایی برای داشتن یک خواب خوب شبانه است. این پلک ها مملو از توصیه های عملی در مورد نحوه کنترل بی خوابی است. آن‌ها، از جمله، نحوه پیگیری مشکلات خواب، درک علم بی‌خوابی و به کارگیری استراتژی‌های مختلفی را توضیح می‌دهند که به شما کمک می‌کند تا به استراحتی که نیاز دارید برسید.</p>', '2017-08-17 00:00:00', 4, 65, 'https://images.blinkist.io/images/books/59930812b238e100058f78c3/1_1/470.jpg', '/en/books/end-the-insomnia-struggle-en/purchase', 'به-مبارزه-بی-خوابی-پایان-دهید', '2023-01-26 19:29:43.898851', '2023-01-26 19:29:43.898851', NULL, 'End the Insomnia Struggle');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (377, 'هنر شادی', 'کتاب راهنمای زندگی', 'کتاب راهنمای زندگی', 18, 9, 'book', 't', '<p><em>هنر شادی</em> (1998) بر اساس مصاحبه‌های حضرت دالایی لاما که توسط روان‌پزشک هوارد سی. کاتلر انجام شده است. ترکیب سنت معنوی بودایی تبتی با دانش دکتر کاتلر از روش‌های درمانی غربی و مطالعات علمی، این کتاب را به راهنمای بسیار قابل دسترس برای شادی روزمره تبدیل می‌کند. این کتاب ۹۷ هفته در فهرست پرفروش‌ترین‌های <em>نیویورک تایمز</em> بود.</p>', '2013-01-03 00:00:00', 5, 348, 'https://images.blinkist.io/images/books/510170ffe4b0991857b92611/1_1/470.jpg', '/en/books/the-art-of-happiness-en/purchase', 'هنر-شادی', '2023-01-26 19:29:49.678658', '2023-01-26 19:29:49.678658', NULL, 'The Art of Happiness');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (378, 'چگونه این را ساختم', 'مسیرهای غیرمنتظره موفقیت توسط الهام بخش ترین کارآفرینان جهان', 'مسیرهای غیرمنتظره موفقیت توسط الهام بخش ترین کارآفرینان جهان', 16, 6, 'book', 't', '<p><em>چگونه این را ساختم </em>(2020) سفری در امتداد جاده پر پیچ و خم به سوی موفقیت کارآفرینی است. بر اساس برترین پادکست تجاری در iTunes، با ۲۰۰ میلیون بارگیری تا به امروز، <em>How I Built This</em> عروج ده ها تن از الهام بخش ترین کارآفرینان جهان را به تصویر می کشد، تاریک ترین لحظات و همچنین بزرگترین پیروزی های آنها را بررسی می کند. </p>', '2020-10-12 00:00:00', 4, 123, 'https://images.blinkist.io/images/books/5f802b3b6cee07000646ad41/1_1/470.jpg', '/en/books/how-i-built-this-en/purchase', 'چگونه-این-را-ساختم', '2023-01-26 19:29:55.96166', '2023-01-26 19:29:55.96166', NULL, 'How I Built This');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (379, 'تلخ و شیرین', 'چگونه اندوه و حسرت ما را کامل می کند', 'چگونه اندوه و حسرت ما را کامل می کند', 26, 4, 'book', 't', '<p><em>تلخ شیرین </em>(2022) یک مراقبه عمیق در مورد یک تجربه عاطفی است که اغلب نادیده گرفته می شود - تلخ و شیرین. این استدلال می کند که گشودن به چیزهای تلخ، جایی که درد و شادی در هم می آمیزند، به ما امکان می دهد تا زندگی را به طور کامل تجربه کنیم. همچنین نشان می‌دهد که چگونه آسیب‌پذیری می‌تواند نقطه قوت باشد، اشتیاق می‌تواند راهنما باشد، و غم می‌تواند ما را در مسیر شادی و رضایت قرار دهد. </p>', '2022-05-12 00:00:00', 5, 298, 'https://images.blinkist.io/images/books/627cb1896cee07000912b0c8/1_1/470.jpg', '/en/books/bittersweet-en/purchase', 'تلخ-و-شیرین', '2023-01-26 19:30:00.77744', '2023-01-26 19:30:00.77744', NULL, 'Bittersweet');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (380, 'ساختار انقلاب های علمی', 'یک مطالعه پیشگامانه در مورد چگونگی پیشرفت علم', 'یک مطالعه پیشگامانه در مورد چگونگی پیشرفت علم', 13, 5, 'book', 't', '<p><em>ساختار انقلاب‌های علمی</em> (1962) مطالعه‌ای پیشگامانه در تاریخ علم و فلسفه است. توضیح می دهد که دانشمندان چگونه تحقیقات انجام می دهند و توضیح جالب (اگر بحث برانگیز) پیشرفت علمی ارائه می دهد.</p>', '2015-03-27 10:00:00', 4, 66, 'https://images.blinkist.io/images/books/55102d47666564000a920000/1_1/470.jpg', '/en/books/the-structure-of-scientific-revolutions-en/purchase', 'ساختار-انقلاب-های-علمی', '2023-01-26 19:30:06.55661', '2023-01-26 19:30:06.55661', NULL, 'The Structure of Scientific Revolutions');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (383, 'شامل شود', 'قدرت منحصر به فرد بودن و تعلق به ایجاد تیم های نوآور', 'قدرت منحصر به فرد بودن و تعلق به ایجاد تیم های نوآور', 22, 7, 'book', 't', '<p><em>Inclusify </em>(2020) برای مدیران و مدیران عاملی که می خواهند تنوع نیروی کار خود را افزایش دهند، راهنمایی های ارزشمندی ارائه می دهد. حقایق نشان می دهد که تنوع نقش موثری در موفقیت در سطوح مختلف دارد. <em>شامل</em> مراحل اثبات شده‌ای را معرفی می‌کند که بزرگ‌ترین و بهترین کسب‌وکارها برای فراگیرتر و موفق‌تر شدن انجام می‌دهند.</p>', '2020-11-05 00:00:00', 4, 113, 'https://images.blinkist.io/images/books/5f9be6db6cee07000676b703/1_1/470.jpg', '/en/books/inclusify-en/purchase', 'شامل-شود', '2023-01-26 19:30:22.543668', '2023-01-26 19:30:22.543668', NULL, 'Inclusify');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (384, 'کتاب آلیس بی توکلاس کوک', 'دستور العمل های سنتی فرانسوی و پنجره ای به آوانگارد پاریس', 'دستور العمل های سنتی فرانسوی و پنجره ای به آوانگارد پاریس', 19, 6, 'book', 't', '<p>کتاب کوک آلیس بی توکلاس (1954) به همان اندازه که یک کتاب آشپزی است به همان اندازه که دریچه ای به دنیای خانه مهاجران پاریسی قبل از جنگ جهانی دوم است. ما توکلاس و شریک زندگی او، نویسنده گرترود استین را دنبال می کنیم، در حالی که با فورد مدل T خود در سرتاسر کشور سفر می کنند و افراد برجسته هنری مانند پیکاسو و همینگوی را سرگرم می کنند و در طول مسیر دستور غذاها را جمع آوری می کنند. با پختن دستور العمل های توکلاس، ما فرصت نادری برای شرکت در عصری که مدت هاست از احساس بی خیالی گذشته است را داریم. </p>', '2020-05-16 00:00:00', 4, 12, 'https://images.blinkist.io/images/books/5ebd2ca66cee070006b32105/1_1/470.jpg', '/en/books/the-alice-b-toklas-cook-book-en/purchase', 'کتاب-آلیس-بی-توکلاس-کوک', '2023-01-26 19:30:27.669578', '2023-01-26 19:30:27.669578', NULL, 'The Alice B. Toklas Cook Book');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (385, 'بهترین شما فقط بهتر شد', 'هوشمندتر کار کنید، بزرگتر فکر کنید، بیشتر بسازید', 'هوشمندتر کار کنید، بزرگتر فکر کنید، بیشتر بسازید', 10, 5, 'book', 't', '<p><em>بهترین شما فقط بهتر شد</em> (2012) موثرترین تکنیک ها را برای تعیین اهداف و استفاده از زمان خود برای رسیدن به آنها بیان می کند. این پلک زدن ها نشان می دهد که کدام بخش از زندگی شما انگیزه شما را تخلیه می کند، و همچنین نشان می دهد که چه کاری می توانید انجام دهید تا جاه طلبی خود را به سطح بعدی برسانید.</p>', '2015-04-13 00:00:00', 4, 71, 'https://images.blinkist.io/images/books/552bd7e964663400071e0000/1_1/470.jpg', '/en/books/your-best-just-got-better-en/purchase', 'بهترین-شما-فقط-بهتر-شد', '2023-01-26 19:30:32.520448', '2023-01-26 19:30:32.520448', NULL, 'Your Best Just Got Better');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (386, 'رهبران آخرین بار می خورند', 'چرا برخی از تیم ها با هم جمع می شوند و برخی دیگر نه؟', 'چرا برخی از تیم ها با هم جمع می شوند و برخی دیگر نه؟', 19, 8, 'book', 't', '<p><em>رهبران</em> <em>خوردن</em> <em>آخرین</em> تأثیر مواد شیمیایی عصبی بر احساس و در نتیجه عملکرد افراد را بررسی می‌کند و تفاوت‌های بین نحوه بدن ما را بررسی می‌کند. برای عملکرد و نحوه عملکرد آنها طراحی شده اند. در نهایت، ما به رهبران واقعی نیاز داریم تا ما را به مسیر درست برگردانند.</p>', '2014-06-17 00:00:00', 4, 530, 'https://images.blinkist.io/images/books/53a195b66335360007300000/1_1/470.jpg', '/en/books/leaders-eat-last-en/purchase', 'رهبران-آخرین-بار-می-خورند', '2023-01-26 19:30:36.21809', '2023-01-26 19:30:36.21809', NULL, 'Leaders Eat Last');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (387, 'مقیاس زندگی', 'چگونه یک زندگی خلاق تر، سازنده تر و شادتر داشته باشیم', 'چگونه یک زندگی خلاق تر، سازنده تر و شادتر داشته باشیم', 24, 8, 'book', 't', '<p><em>Lifescale </em>(2019) به مبارزه مدرن برای متمرکز ماندن در دنیایی که برای پرت کردن حواس شما طراحی شده است می پردازد. این راه حل های عملی برای افزایش بهره وری شما در حالی که با فاصله توجه کوتاه شده مبارزه می کند، ارائه می دهد. همچنین راه‌هایی برای شناسایی معنا، ارزش‌ها و اهدافی که شما را به جلو سوق می‌دهد، مشخص می‌کند.</p>', '2020-11-21 00:00:00', 5, 94, 'https://images.blinkist.io/images/books/5fae64c06cee070006bb4305/1_1/470.jpg', '/en/books/lifescale-en/purchase', 'مقیاس-زندگی', '2023-01-26 19:30:41.112615', '2023-01-26 19:30:41.112615', NULL, 'Lifescale');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (388, 'پایان فقر', 'امکانات اقتصادی برای زمان ما', 'امکانات اقتصادی برای زمان ما', 19, 9, 'book', 't', '<p><em>پایان فقر</em> (2005) راهنمای پایان دادن به فقر شدید یکبار برای همیشه است. این پلک ها توضیح می دهند که واقعاً چقدر سرمایه گذاری کمی برای تغییر زندگی میلیون ها نفر لازم است. یعنی تا زمانی که عاقلانه خرج شده باشد.</p>', '2017-08-31 00:00:00', 4, 51, 'https://images.blinkist.io/images/books/59a2c749b238e10005eeb738/1_1/470.jpg', '/en/books/the-end-of-poverty-en/purchase', 'پایان-فقر', '2023-01-26 19:30:45.649567', '2023-01-26 19:30:45.649567', NULL, 'The End of Poverty');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (389, 'کتاب کوچک Hygge', 'روش دانمارکی برای خوب زندگی کردن', 'روش دانمارکی برای خوب زندگی کردن', 13, 5, 'book', 't', '<p>کشورهای مختلف، مانند افراد مختلف، شخصیت‌های متفاوتی دارند. برخی خوشبین تر هستند. برخی افسرده ترند از بین تمام کشورهای جهان، دانمارک اغلب به عنوان شادترین رتبه بندی می شود. و این به این دلیل است که دانمارک <em>hygge</em> دارد. <em>کتاب کوچک Hygge</em> (2016) این مفهوم را به طور کامل توضیح می دهد و نکاتی را در مورد چگونگی دستیابی به آن - در هر کجا که زندگی می کنید - ارائه می دهد.</p>', '2017-04-26 00:00:00', 4, 122, 'https://images.blinkist.io/images/books/58fc9a67a6d7cf0004aeb91c/1_1/470.jpg', '/en/books/the-little-book-of-hygge-en/purchase', 'کتاب-کوچک-Hygge', '2023-01-26 19:30:50.674476', '2023-01-26 19:30:50.674476', NULL, 'The Little Book of Hygge');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1563, 'بازاریابی ساده', 'راهنمای گام به گام StoryBrand برای هر کسب و کاری', 'راهنمای گام به گام StoryBrand برای هر کسب و کاری', 17, 6, 'book', 't', '<p><em>بازاریابی ساده </em>(2020) راهنمای مفیدی برای رشد نام تجاری شماست. این کتابچه راهنمای عملی یک سیستم پنج نقطه ای را برای هدایت موثر مشتریان جدید به کسب و کار شما آموزش می دهد.</p>', '2022-02-11 00:00:00', 4, 190, 'https://images.blinkist.io/images/books/6200fa4f6cee070008fdef44/1_1/470.jpg', '/en/books/marketing-made-simple-en/purchase', 'بازاریابی-ساده', '2023-01-27 02:48:12.74378', '2023-01-27 02:48:12.74378', NULL, 'Marketing Made Simple');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (390, 'ازدواج مقدس', 'چه می‌شد اگر خدا ازدواج را طوری طراحی کرده بود که ما را بیشتر مقدس کند تا ما را خوشحال کند؟', 'چه می‌شد اگر خدا ازدواج را طوری طراحی کرده بود که ما را بیشتر مقدس کند تا ما را خوشحال کند؟', 21, 7, 'book', 't', '<p><em>ازدواج مقدس </em>(2000) کاوشی در مورد چگونگی آوردن خدا به ازدواجتان است. با بررسی مرزهای عشق، توصیه‌های عملی و حکمت معنوی ارائه می‌کند تا به شما و ازدواج‌تان کمک کند تا به مکان مقدس‌تر بروید.</p>', '2022-01-15 00:00:00', 3, 248, 'https://images.blinkist.io/images/books/61e1a68a6cee0700087b7e24/1_1/470.jpg', '/en/books/sacred-marriage-en/purchase', 'ازدواج-مقدس', '2023-01-26 19:30:55.567186', '2023-01-26 19:30:55.567186', NULL, 'Sacred Marriage');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (391, 'کد چاقی', 'کشف رازهای کاهش وزن', 'کشف رازهای کاهش وزن', 22, 8, 'book', 't', '<p><em>کد چاقی</em> (2016) به افزایش نگران کننده جهانی چاقی می پردازد و از ما می پرسد که چه کاری می توانیم انجام دهیم تا خطرات سلامتی خود را به حداقل برسانیم. جیسون فانگ استدلال می‌کند که بهترین مکان برای شروع، پاک کردن باورهای غلط رایج در مورد علل چاقی است، با اره قدیمی که همه چربی‌های رژیمی مقصر هستند. این بدان معناست که نگاهی دقیق‌تر به آخرین شواهد داشته باشید و به مقصر واقعی آن بپردازید: مقاومت به انسولین.</p>', '2019-04-05 00:00:00', 5, 313, 'https://images.blinkist.io/images/books/5ca332946cee070007a59377/1_1/470.jpg', '/en/books/the-obesity-code-en/purchase', 'کد-چاقی', '2023-01-26 19:31:00.268368', '2023-01-26 19:31:00.268368', NULL, 'The Obesity Code');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (392, 'انصاف', 'چگونه سازمان هایی را طراحی کنیم که همه در آن پیشرفت کنند', 'چگونه سازمان هایی را طراحی کنیم که همه در آن پیشرفت کنند', 21, 6, 'book', 't', '<p><em>Equity</em> (2021) راهنمای شما برای ایجاد سیستم‌های عادلانه در قرن بیست و یکم است. این برنامه برای کمک به رهبران آگاه اجتماعی در انجام وظیفه چالش برانگیز ایجاد سازمان‌های منصفانه و فراگیر که برای همه کار می‌کنند، طراحی شده است.</p>', '2021-10-26 00:00:00', 4, 144, 'https://images.blinkist.io/images/books/6171532a6cee0700087ab68c/1_1/470.jpg', '/en/books/equity-en/purchase', 'انصاف', '2023-01-26 19:31:06.207414', '2023-01-26 19:31:06.207414', NULL, 'Equity');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (393, 'احساس عالی داشته باشید، وزن کم کنید', 'عادات ساده و طولانی مدت برای کاهش وزن پایدار و پایدار', 'عادات ساده و طولانی مدت برای کاهش وزن پایدار و پایدار', 20, 8, 'book', 't', '<p><em>Feel Great Lose Weight</em>(2020)<em> </em>فقط یک کتاب رژیم غذایی دیگر از راه‌حل‌های سریع و مدها نیست. با تکیه بر تخصص دکتر رنگان چاترجی، ابزارهایی را در اختیار شما قرار می دهد تا مکانیک سلامت خود باشید و به شما نشان می دهد که چگونه عادات غذایی و سبک زندگی خود را تنظیم کنید تا وزن خود را به طور پایدار کاهش دهید و در طولانی مدت احساس خوبی داشته باشید.</p>', '2021-06-13 00:00:00', 5, 313, 'https://images.blinkist.io/images/books/60ba47d96cee07000896dc26/1_1/470.jpg', '/en/books/feel-great-lose-weight-en/purchase', 'احساس-عالی-داشته-باشید،-وزن-کم-کنید', '2023-01-26 19:31:11.651292', '2023-01-26 19:31:11.651292', NULL, 'Feel Great, Lose Weight');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (394, 'بانو بلوز را می خواند', 'نسخه پنجاهمین سالگرد با دیسکوگرافی اصلاح شده', 'نسخه پنجاهمین سالگرد با دیسکوگرافی اصلاح شده', 18, 6, 'book', 't', '<p><em>بانو بلوز می خواند</em> (1956) خاطرات بیلی هالیدی است. خواننده افسانه ای جاز زندگی خود را از کودکی بی رحمانه در بالتیمور تا شروع حرفه موسیقی خود در هارلم و - در نهایت - ستاره شدن آغشته به نژادپرستی و اعتیاد به مواد را بازگو می کند. </p>', '2022-12-18 00:00:00', 4, 126, 'https://images.blinkist.io/images/books/63986e62ac4463000945871c/1_1/470.jpg', '/en/books/lady-sings-the-blues-en/purchase', 'بانو-بلوز-را-می-خواند', '2023-01-26 19:31:16.867661', '2023-01-26 19:31:16.867661', NULL, 'Lady Sings the Blues');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (395, 'فقط به خرید ادامه دهید', 'راه های اثبات شده برای پس انداز پول و ایجاد ثروت', 'راه های اثبات شده برای پس انداز پول و ایجاد ثروت', 22, 5, 'book', 't', '<p><em>فقط به خرید ادامه دهید</em> (2022) یک راهنمای بی معنی برای امور مالی شخصی است که از شکستن اسطوره ها و از بین بردن کلیشه های قدیمی لذت می برد. با پاسخگویی به سؤالات مهمی مانند پس انداز و سرمایه گذاری، روانشناسی پشت پول را بررسی می کند و راهنمای واقع بینانه ای برای تصمیم گیری های مالی درست ارائه می دهد. </p>', '2022-09-29 00:00:00', 4, 413, 'https://images.blinkist.io/images/books/63316abf6cee070008fbc9ce/1_1/470.jpg', '/en/books/just-keep-buying-en/purchase', 'فقط-به-خرید-ادامه-دهید', '2023-01-26 19:31:22.000602', '2023-01-26 19:31:22.000602', NULL, 'Just Keep Buying');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (396, 'رسیدن به صفر', 'چگونه در روابط پرمخاطره خود از طریق تعارض کار کنید', 'چگونه در روابط پرمخاطره خود از طریق تعارض کار کنید', 28, 9, 'book', 't', '<p><em>نفر به صفر </em>(2021) راهنمایی برای مقابله با تعارض در روابط صمیمی و پرمخاطره - روابطی با خانواده، دوستان خوب و شرکای شما. فرآیندی را برای «به صفر رسیدن» با دستیابی به حل و فصل و بسته شدن پس از درگیری توصیف می‌کند.</p>', '2021-12-23 00:00:00', 5, 265, 'https://images.blinkist.io/images/books/61c073f36cee0700086527e6/1_1/470.jpg', '/en/books/getting-to-zero-en/purchase', 'رسیدن-به-صفر', '2023-01-26 19:31:26.887704', '2023-01-26 19:31:26.887704', NULL, 'Getting to Zero');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (397, 'یادگیری نماز خواندن', 'یک راهنما برای همه', 'یک راهنما برای همه', 22, 7, 'book', 't', '<p><em>یادگیری دعا </em>(2021) یکی از مهم ترین جنبه های زندگی معنوی را که در عین حال سوء تفاهم نشده است، باز می کند: دعا. هدف از دعا چیست؟ چگونه "صحیح" دعا می کنید؟ هنگام دعا باید چه انتظاری داشته باشید؟ اینها تنها برخی از سؤالاتی است که اغلب بین مؤمنان و این عمل عمیقاً ثواب وجود دارد. و برای پاسخ دادن به آنها راهی بهتر از نگاه کردن به سبک‌ها و آداب دعای مختلف موجود در سنت مسیحی وجود ندارد. </p>', '2021-04-20 00:00:00', 4, 134, 'https://images.blinkist.io/images/books/607d9b4c6cee07000799124b/1_1/470.jpg', '/en/books/learning-to-pray-en/purchase', 'یادگیری-نماز-خواندن', '2023-01-26 19:31:39.247553', '2023-01-26 19:31:39.247553', NULL, 'Learning to Pray');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (398, 'هنر سخنرانی عمومی', 'به یک سخنران عمومی با اعتماد به نفس و مؤثر تبدیل شوید', 'به یک سخنران عمومی با اعتماد به نفس و مؤثر تبدیل شوید', 23, 8, 'book', 't', '<p><em>هنر سخنرانی در جمع </em>(1915) یکی از محبوب ترین و پرخواننده ترین راهنماها برای بیان سخنرانی های عمومی مؤثر است. زبان قابل دسترس و نکات کاربردی آن بیش از یک قرن است که سخنرانان بالقوه را به سخنوران چیره دست تبدیل کرده است.</p>', '2018-11-26 00:00:00', 5, 193, 'https://images.blinkist.io/images/books/5bf9d2786cee070007cf02e5/1_1/470.jpg', '/en/books/the-art-of-public-speaking-en/purchase', 'هنر-سخنرانی-عمومی', '2023-01-26 19:31:42.630835', '2023-01-26 19:31:42.630835', NULL, 'The Art of Public Speaking');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (399, 'تیم های هوشمند', 'چگونه با هم بهتر کار کنیم', 'چگونه با هم بهتر کار کنیم', 21, 8, 'book', 't', '<p><em>تیم های هوشمند </em>(2018) راهنمای عملی برای افزایش بهره وری تیم شما است. این ابزارها و استراتژی هایی را در اختیار شما قرار می دهد که می توانید از آنها برای کمک به شما و تیمتان برای برقراری ارتباط بهتر، همکاری موثر و رفع اختلالاتی که شما را از دستیابی به اهدافتان باز می دارند، استفاده کنید.</p>', '2020-03-16 00:00:00', 4, 110, 'https://images.blinkist.io/images/books/5e6b77726cee070007dabd36/1_1/470.jpg', '/en/books/smart-teams-en/purchase', 'تیم-های-هوشمند', '2023-01-26 19:31:48.004992', '2023-01-26 19:31:48.004992', NULL, 'Smart Teams');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (400, 'اینجا همه می آیند', 'قدرت سازماندهی بدون سازمان', 'قدرت سازماندهی بدون سازمان', 17, 8, 'book', 't', '<p>به لطف پیشرفت‌های فناوری‌های ارتباطی و در دسترس بودن گسترده اینترنت، اکنون می‌توانیم با یکدیگر تماس گرفته و اطلاعات را با نرخ‌های بی‌سابقه به اشتراک بگذاریم. <em>اینجا</em> <em>می آید</em> <em>همه</em> توضیح می دهد که چگونه این تغییرات فقط بر نحوه ارتباط ما تأثیر نمی گذارد. آنها بر نحوه سازماندهی ما نیز تأثیر می گذارند. از آنجایی که موانع و هزینه های ارتباط کاهش می یابد و دامنه ارتباط ما گسترش می یابد، اکنون در حال تجربه یک تغییر قابل توجه در روش های دور هم هستیم.</p>', '2014-07-22 00:00:00', 4, 13, 'https://images.blinkist.io/images/books/53cf931e6434330007140000/1_1/470.jpg', '/en/books/here-comes-everybody-en/purchase', 'اینجا-همه-می-آیند', '2023-01-26 19:31:53.220132', '2023-01-26 19:31:53.220132', NULL, 'Here Comes Everybody');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (401, 'مرد دریا!', 'راه نجات پزشکی برای مردان سالخورده', 'راه نجات پزشکی برای مردان سالخورده', 18, 4, 'book', 't', '<p><em>Man Overboard!</em> (2022) راهنمای جامعی برای رایج‌ترین چالش‌های سلامتی است که مردان احتمالاً با افزایش سن با آن‌ها مواجه می‌شوند. این نه تنها تفاوت بین تستوسترون پایین و اختلال نعوظ و مواردی که باید در مورد چاقی و انواع کشنده سرطان مراقب باشند را توضیح می دهد، بلکه ابزارهایی را برای مردان فراهم می کند تا کنترل سلامت خود را در دست بگیرند تا زندگی فعال خود را بدون شگفتی های ناخوشایند زیاد ادامه دهند.< /p>', '2023-01-18 00:00:00', 4, 10, 'https://images.blinkist.io/images/books/63c7a7a03784800008d66e89/1_1/470.jpg', '/en/books/man-overboard-en/purchase', 'مرد-دریا!', '2023-01-26 19:31:59.426686', '2023-01-26 19:31:59.426686', NULL, 'Man Overboard!');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (402, 'همه را نادیده بگیرید', 'و 39 کلید دیگر برای خلاقیت', 'و 39 کلید دیگر برای خلاقیت', 13, 6, 'book', 't', '<p>در <em>همه را نادیده بگیرید، </em>نویسنده هیو مک‌لئود شما را تشویق می‌کند که روح خلاق درونی خود را باز کنید و در آغوش بگیرید و رویای هنری خود را زندگی کنید. مک‌لئود برگرفته از تجربیات شخصی و حرفه‌ای‌اش، به ما یادآوری می‌کند که الهام گرفتن می‌تواند در هر زمانی اتفاق بیفتد، و برای موفقیت واقعی، نمی‌توانید اجازه دهید انتقاد شما را پایین بیاورد. اگر می‌خواهید به خاطر زندگی هنری، شغل میز خود را رها کنید، این کتاب به شما کمک می‌کند این کار را انجام دهید و در عین حال توصیه‌های حکیمانه‌ای در مورد نحوه ارائه کارتان به دنیای گسترده‌تر ارائه می‌دهد.</p>', '2015-01-20 00:00:00', 4, 41, 'https://images.blinkist.io/images/books/54bd21d1633234000a530000/1_1/470.jpg', '/en/books/ignore-everybody-en/purchase', 'همه-را-نادیده-بگیرید', '2023-01-26 19:32:05.647127', '2023-01-26 19:32:05.647127', NULL, 'Ignore Everybody');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (403, 'با غذا شروع می شود', 'WHOLE30 را کشف کنید و زندگی خود را به روش های غیرمنتظره تغییر دهید', 'WHOLE30 را کشف کنید و زندگی خود را به روش های غیرمنتظره تغییر دهید', 15, 7, 'book', 't', '<p><em>این با غذا شروع می‌شود</em> (2012) به شما اطلاعاتی در مورد تأثیرات عمیق غذا بر بدن و سلامتی شما می‌دهد. نکته مهم این است که این پلک ها توضیح می دهند که چگونه می توانید رژیم غذایی خود را تغییر دهید تا هم وزن خود را کاهش دهید و هم احساس بهتری، جسم و روح داشته باشید.</p>', '2016-03-22 00:00:00', 4, 57, 'https://images.blinkist.io/images/books/56ebe0f770f3820007000001/1_1/470.jpg', '/en/books/it-starts-with-food-en/purchase', 'با-غذا-شروع-می-شود', '2023-01-26 19:32:10.310902', '2023-01-26 19:32:10.310902', NULL, 'It Starts With Food');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (404, 'فراخوان کل', 'داستان زندگی باورنکردنی واقعی من', 'داستان زندگی باورنکردنی واقعی من', 15, 6, 'book', 't', '<p><em>Total Recall </em>(2013) داستان باورنکردنی به دست آوردن شهرت جهانی آرنولد شوارتزنگر را از آغاز فروتنانه‌اش در روستاهای اتریش بیان می‌کند. این پلک‌ها با شروع دوران سخت کودکی‌اش، مبارزات و پیروزی‌های شوارتزنگر در حرفه بدنسازی، هالیوود و سیاست ایالات متحده را نشان می‌دهند و بر مثبت‌اندیشی بی‌وقفه و نگرش او که می‌توانستند، روشن شود.</p>', '2018-05-02 00:00:00', 4, 58, 'https://images.blinkist.io/images/books/5ae3e1dcb238e10007f7894a/1_1/470.jpg', '/en/books/total-recall-en/purchase', 'فراخوان-کل', '2023-01-26 19:32:15.203463', '2023-01-26 19:32:15.203463', NULL, 'Total Recall');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (405, 'الگوریتم هایی برای زندگی کردن', 'علوم کامپیوتر تصمیمات انسانی', 'علوم کامپیوتر تصمیمات انسانی', 22, 10, 'book', 't', '<p><em>Algorithms to Live By</em> (2016) یک راهنمای عملی و مفید است که نشان می دهد چگونه الگوریتم ها خیلی بیشتر از آنچه فکر می کنید با زندگی روزمره ارتباط دارند. و نه فقط این؛ آنها همچنین می توانند با کمک به شما در حل مشکلات، تصمیم گیری و انجام کارهای بیشتر به زندگی بهتری منجر شوند.</p>', '2016-11-18 00:00:00', 4, 125, 'https://images.blinkist.io/images/books/5829dd0f92e9210004940bf6/1_1/470.jpg', '/en/books/algorithms-to-live-by-en/purchase', 'الگوریتم-هایی-برای-زندگی-کردن', '2023-01-26 19:32:20.340172', '2023-01-26 19:32:20.340172', NULL, 'Algorithms to Live By');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (406, 'همه می نویسند', 'راهنمای شما برای ایجاد محتوای مضحک خوب', 'راهنمای شما برای ایجاد محتوای مضحک خوب', 11, 5, 'book', 't', '<p><em>Everybody Writes</em> (2014) به شما توصیه های ارزشمندی در مورد نحوه ایجاد محتوای عالی می دهد، از استفاده از دستور زبان صحیح گرفته تا ایجاد پست ها، توییت ها و ایمیل های جذاب. تنها با چند قانون ساده، این پلک زدن ها به شما کمک می کند تا درک بهتری از نحوه استفاده از کلمات مناسب به دست آورید تا مشتریان را برای کسب اطلاعات بیشتر برگردند.</p>', '2015-04-16 00:00:00', 4, 117, 'https://images.blinkist.io/images/books/552be9406466340007e10000/1_1/470.jpg', '/en/books/everybody-writes-en/purchase', 'همه-می-نویسند', '2023-01-26 19:32:25.551422', '2023-01-26 19:32:25.551422', NULL, 'Everybody Writes');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (407, 'فاکتور لاته', 'چرا برای ثروتمند شدن لازم نیست ثروتمند باشید', 'چرا برای ثروتمند شدن لازم نیست ثروتمند باشید', 15, 5, 'book', 't', '<p><em>The Latte Factor </em>(2019) داستان زوئی، زن جوان خیالی را روایت می کند که در اواخر دهه 20 زندگی خود در بروکلین زندگی می کند. در حالی که او شغل خوبی در منهتن دارد، نمی تواند بفهمد چگونه پول پس انداز کند. خوشبختانه، او با پیرمرد خردمندی به نام هنری آشنا می شود که سه راز آزادی مالی را برای او فاش می کند و با این کار، زندگی او را تغییر می دهد.</p>', '2019-06-03 00:00:00', 4, 383, 'https://images.blinkist.io/images/books/5cf2a14c6cee070007e047c3/1_1/470.jpg', '/en/books/the-latte-factor-en/purchase', 'فاکتور-لاته', '2023-01-26 19:32:30.759949', '2023-01-26 19:32:30.759949', NULL, 'The Latte Factor');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (408, 'هنرمندان واقعی گرسنگی نمی کشند', 'استراتژی های بی انتها برای شکوفایی در عصر خلاقیت جدید', 'استراتژی های بی انتها برای شکوفایی در عصر خلاقیت جدید', 16, 6, 'book', 't', '<p><em>هنرمندان واقعی گرسنه نمی‌مانند </em>(2017) زنگ خطری برای کسانی است که فکر می‌کنند هنرمند بودن یک کار واقع‌گرایانه یا عملی نیست. در اینجا، شواهد فراوانی برای رد افسانه‌هایی که هنرمندان را به‌عنوان چهره‌های گرسنه و منزوی نشان می‌دهند، پیدا خواهید کرد که باید برای هنر خود زجر بکشند. این روزها یک رنسانس جدید در جریان است - دریابید که چگونه می توانید بخشی از آن باشید!</p>', '2017-08-21 00:00:00', 4, 51, 'https://images.blinkist.io/images/books/599817dbb238e10006a125cb/1_1/470.jpg', '/en/books/real-artists-dont-starve-en/purchase', 'هنرمندان-واقعی-گرسنگی-نمی-کشند', '2023-01-26 19:32:34.50695', '2023-01-26 19:32:34.50695', NULL, 'Real Artists Don’t Starve');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (409, 'هفته کاری 4 ساعته', 'Escape 9–5، Live Anywhere، و به ثروتمندان جدید بپیوندید', 'Escape 9–5، Live Anywhere، و به ثروتمندان جدید بپیوندید', 28, 12, 'book', 't', '<p><em>هفته کاری 4 ساعته </em>(2009) زندگی ثروتمندان جدید را توصیف می کند، افرادی که خود را از بردگی کار اداری رها کرده اند و زندگی مبتنی بر شادی را در اینجا و اکنون بنا کرده اند. . اگر شما هم می‌خواهید چنین زندگی‌ای داشته باشید، باید با بهره‌وری بیشتر و یافتن منبعی از درآمد مداوم – و تقریباً کاملاً منفعل – شروع کنید. این پلک ها به شما نشان می دهند که چگونه.</p>', '2012-10-16 11:52:22', 4, 1705, 'https://images.blinkist.io/images/books/5282267434613800112a0000/1_1/470.jpg', '/en/books/the-4-hour-workweek-en/purchase', 'هفته-کاری-4-ساعته', '2023-01-26 19:32:39.589378', '2023-01-26 19:32:39.589378', NULL, 'The 4-Hour Workweek');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (410, 'مانع راه است', 'هنر جاودانه تبدیل آزمایش ها به پیروزی', 'هنر جاودانه تبدیل آزمایش ها به پیروزی', 31, 9, 'book', 't', '<p>در <em>موانع راه است </em> (2014)، رایان هالیدی حکمت دیرینه فلسفه رواقی را به روز می کند. هالیدی با بررسی مبارزات شخصیت‌های تاریخی الهام‌بخش انعطاف‌پذیری، نه تنها نشان می‌دهد که چگونه موانع نتوانستند جلوی آنها را بگیرند، بلکه مهم‌تر از آن، چگونه این افراد دقیقاً <em>به دلیل</em> موانع پیشرفت کردند. تعطیلات نشان می‌دهد که چگونه می‌توانیم موانع را به نفع خود تبدیل کنیم، و چگونه می‌توانیم موانع ظاهری را به موفقیت تبدیل کنیم، هم در تجارت و هم در زندگی شخصی‌مان.</p>', '2014-05-20 09:38:09', 4, 474, 'https://images.blinkist.io/images/books/537c71fe34653000076b0000/1_1/470.jpg', '/en/books/the-obstacle-is-the-way-en/purchase', 'مانع-راه-است', '2023-01-26 19:32:43.398388', '2023-01-26 19:32:43.398388', NULL, 'The Obstacle is the Way');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (411, 'شکاف رفتاری', 'راه های ساده برای جلوگیری از انجام کارهای احمقانه با پول', 'راه های ساده برای جلوگیری از انجام کارهای احمقانه با پول', 18, 10, 'book', 'f', '<p>این پلک‌ها به شما کمک می‌کند تا تصمیمات بهتری در مورد پول بگیرید. ریچاردز با تعریف <em>شکاف رفتار</em> - شکاف بین آنچه که <em>باید انجام دهیم</em> و آنچه که <em>در واقع انجام می‌دهیم</em> - و توضیح چگونگی بستن آن، دستورالعمل‌هایی ارائه می‌کند. برای اتخاذ تصمیمات مالی هوشمندانه برای زندگی.</p>', '2014-10-07 00:00:00', 4, 84, 'https://images.blinkist.io/images/books/5432753b38353300084f0000/1_1/470.jpg', '/en/books/the-behavior-gap-en/purchase', 'شکاف-رفتاری', '2023-01-26 19:32:48.541033', '2023-01-26 19:32:48.541033', NULL, 'The Behavior Gap');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (413, 'شروع با چرا (نسخه جدید)', 'چگونه رهبران بزرگ همه را تشویق به اقدام می کنند', 'چگونه رهبران بزرگ همه را تشویق به اقدام می کنند', 21, 3, 'book', 't', '<p><em>شروع با چرا</em>(2009) به یک سوال اساسی می پردازد: چه چیزی باعث می شود برخی از سازمان ها و افراد نوآورتر، تاثیرگذارتر و سودآورتر از سایرین باشند؟ بر اساس سخنرانی بسیار تاثیرگذار سایمون سینک، نویسنده پرفروش، به همین نام، سومین سخنرانی پربیننده TED در تمام دوران، این پلک ها پاسخ این معما را باز می کنند. همانطور که مثال‌های سینک نشان می‌دهد، همه چیز در مورد پرسیدن <em>چرا</em> است نه <em>چی</em>.</p>', '2022-07-06 00:00:00', 5, 528, 'https://images.blinkist.io/images/books/62c43b546cee07000842ea17/1_1/470.jpg', '/en/books/start-with-why-new-version-en/purchase', 'شروع-با-چرا-(نسخه-جدید)', '2023-01-26 19:32:56.688122', '2023-01-26 19:32:56.688122', NULL, 'Start With Why (New Version)');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (414, 'شخصیت های خطرناک', 'یک نمایه کننده FBI به شما نشان می دهد چگونه شخصیت های مضر را شناسایی کرده و از خود محافظت کنید.', 'یک نمایه کننده FBI به شما نشان می دهد چگونه شخصیت های مضر را شناسایی کرده و از خود محافظت کنید.', 17, 6, 'book', 't', '<p><em>شخصیت های خطرناک</em> (2014) راهنمایی به سمت تاریک روان انسان است. این نگاهی به ذهن برخی از خطرناک‌ترین افراد جهان دارد و انواع شخصیت‌هایی را که بیشترین جان‌ها را گرفته‌اند و همچنین بیشترین تلفات را بر جامعه وارد کرده‌اند را بررسی می‌کند. ویژگی‌های قاتلان زنجیره‌ای و آن‌هایی که در مورد دزدیدن پس‌انداز زندگی‌تان دو بار فکر نمی‌کنند را بیاموزید. چه کسی می داند، ممکن است بتوانید مشکل را قبل از اینکه فرصتی برای حمله پیدا کند، تشخیص دهید.</p>', '2017-09-15 00:00:00', 4, 72, 'https://images.blinkist.io/images/books/59b6a7d5b238e100052dbc69/1_1/470.jpg', '/en/books/dangerous-personalities-en/purchase', 'شخصیت-های-خطرناک', '2023-01-26 19:33:01.825147', '2023-01-26 19:33:01.825147', NULL, 'Dangerous Personalities');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (415, 'زن مقدس', 'راهنمای شفای بدن، ذهن و روح زنانه', 'راهنمای شفای بدن، ذهن و روح زنانه', 17, 5, 'book', 't', '<p><em>زنان مقدس</em> (2000) یک راهنمای اساسی برای شفای کل نگر برای زنان است. از طریق حلقه‌های شفابخش، تغییر سبک زندگی، و حکمت خالق الهی، می‌توانید مسیر خود را به سوی یک زندگی پر از شادی و هدف ترسیم کنید.</p>', '2023-01-24 00:00:00', NULL, 0, 'https://images.blinkist.io/images/books/63ca5f5278120c00099e496c/1_1/470.jpg', '/en/books/sacred-woman-en/purchase', 'زن-مقدس', '2023-01-26 19:33:07.024098', '2023-01-26 19:33:07.024098', NULL, 'Sacred Woman');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (416, 'علی بابا', 'خانه ای که جک ما ساخت', 'خانه ای که جک ما ساخت', 20, 8, 'book', 't', '<p><em>Alibaba </em>(2016) روند صعود نجومی به برتری خرده فروشی جهانی جک ما و کسب و کار آنلاین او علی بابا را ترسیم می کند. جک ما از آغاز متواضعانه خود به عنوان معلم مدرسه ثابت کرد که یک کارآفرین رویایی است که بسیار جلوتر از زمان خود بود. این داستان مردی است که پتانسیل اینترنت را می‌دید، زمانی که دیگران هنوز سرشان را روی ایمیل می‌خراشند، و اگرچه مشکلاتی را یکی پس از دیگری به وجود می‌آورد، اما هرگز قدرت خود را از دست نداد تا بهتر از بقیه باشد.< /p>', '2017-10-17 00:00:00', 4, 44, 'https://images.blinkist.io/images/books/59e51ce4b238e100062ad240/1_1/470.jpg', '/en/books/alibaba-en/purchase', 'علی-بابا', '2023-01-26 19:33:12.033201', '2023-01-26 19:33:12.033201', NULL, 'Alibaba');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (417, 'طراحی زندگی کاری', 'چگونه شکوفا شویم و تغییر کنیم و در محل کار خوشبختی پیدا کنیم', 'چگونه شکوفا شویم و تغییر کنیم و در محل کار خوشبختی پیدا کنیم', 23, 8, 'book', 't', '<p><em>طراحی زندگی کاری شما </em>(2020)، کتاب راهنما از استادان طراحی بیل برنت و دیو ایوانز، به خوانندگان می آموزد که چگونه اصول طراحی خوب را در حرفه خود اعمال کنند. برنت و ایوانز به جای تغییر شغل، از طراحی مجدد شغلی که در حال حاضر دارید برای ایجاد زندگی کاری رویاهای خود دفاع می کنند.</p>', '2020-08-27 00:00:00', 4, 124, 'https://images.blinkist.io/images/books/5f3fd2266cee070006d1d28b/1_1/470.jpg', '/en/books/designing-your-work-life-en/purchase', 'طراحی-زندگی-کاری', '2023-01-26 19:33:17.042334', '2023-01-26 19:33:17.042334', NULL, 'Designing Your Work Life');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (418, 'چگونه زنان برمی خیزند', '12 عادتی که شما را از ارتقاء شغلی، ترفیع یا شغل بعدی خود باز می دارد، بشکنید', '12 عادتی که شما را از ارتقاء شغلی، ترفیع یا شغل بعدی خود باز می دارد، بشکنید', 15, 6, 'book', 't', '<p><em>چگونه زنان برمی خیزند</em> (2018) به بررسی چیزهای شگفت انگیزی می پردازد که زنان در محل کار می گویند، انجام می دهند و فکر می کنند و آنها را از پیشرفت باز می دارد. با استفاده از مثال‌های دنیای واقعی و توصیه‌های عملی، پلک‌ها توضیح می‌دهند که چگونه زنان حرفه‌ای می‌توانند پتانسیل کامل خود را برآورده کنند و به بالاترین نردبان شغلی انتخابی خود برسند.</p>', '2018-12-13 00:00:00', 5, 109, 'https://images.blinkist.io/images/books/5c10ea5b6cee070007f43dc8/1_1/470.jpg', '/en/books/how-women-rise-en/purchase', 'چگونه-زنان-برمی-خیزند', '2023-01-26 19:33:22.081015', '2023-01-26 19:33:22.081015', NULL, 'How Women Rise');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (419, 'همه چیز متصل می شود', 'چگونه در عصر خلاقیت، نوآوری و پایداری متحول و رهبری کنیم', 'چگونه در عصر خلاقیت، نوآوری و پایداری متحول و رهبری کنیم', 13, 7, 'book', 'f', '<p>مدیتیشن توسط مدیران اجرایی، چالش‌های سیاست شرکت، تفاوت‌های اجتماعی بین اعضای تیم و رضایت مشتری: همه اینها به هم مرتبط هستند. با استفاده از یک رویکرد جامع، <em>همه چیز متصل می‌شود</em> (2014) به شما کمک می‌کند محیط کاری خود را به محیطی تبدیل کنید که چنین ارتباطاتی را درک کرده و از آن پشتیبانی کند و همچنین خلاقیت و نوآوری را افزایش دهد.</p>', '2015-03-31 00:00:00', 4, 27, 'https://images.blinkist.io/images/books/551898f93961320007380000/1_1/470.jpg', '/en/books/everything-connects-en/purchase', 'همه-چیز-متصل-می-شود', '2023-01-26 19:33:27.037052', '2023-01-26 19:33:27.037052', NULL, 'Everything Connects');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (420, 'آنچه را که مهمتر است انجام دهید', 'با چشم انداز رهبری کنید، با برنامه مدیریت کنید، زمان خود را اولویت بندی کنید', 'با چشم انداز رهبری کنید، با برنامه مدیریت کنید، زمان خود را اولویت بندی کنید', 19, 6, 'book', 't', '<p><em>آنچه مهمتر است را انجام دهید </em>(2021) راهنمای مدیریت کارآمدتر زمانتان است. این به شما کمک می کند تا عملکرد را افزایش دهید و روی آنچه که مهمتر است متمرکز بمانید. این بسته مجموعه کاملی از ترفندها را ارائه می‌کند، مانند توسعه چشم‌انداز شخصی، تعیین اهداف سالانه، و دنبال کردن یک لیست هفتگی از اولویت‌ها.</p>', '2021-10-11 00:00:00', 5, 755, 'https://images.blinkist.io/images/books/615dbc406cee070007bf994b/1_1/470.jpg', '/en/books/do-what-matters-most-en/purchase', 'آنچه-را-که-مهمتر-است-انجام-دهید', '2023-01-26 19:33:32.373793', '2023-01-26 19:33:32.373793', NULL, 'Do What Matters Most');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (421, 'اتوبوس انرژی', '10 قانون برای تامین انرژی مثبت زندگی، کار و تیم شما', '10 قانون برای تامین انرژی مثبت زندگی، کار و تیم شما', 18, 8, 'book', 't', '<p><em>اتوبوس انرژی</em> (2007) کتاب راهنمای انرژی مثبت و موفقیت طولانی مدت در زندگی شخصی و حرفه ای شماست. این پلک‌ها مملو از توصیه‌های عملی در مورد چگونگی حذف احساسات منفی، جایگزینی آن‌ها با افکار مثبت و سوخت‌رسانی به سفر زندگی‌تان با افراد متعهد و دیدگاهی قابل انجام است.</p>
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (422, 'شتاب بگیرید', 'چگونه وقتی گیر کرده اید شروع کنید', 'چگونه وقتی گیر کرده اید شروع کنید', 12, 5, 'book', 't', '<p><em>Get Momentum</em> (2016) شما را از طریق استراتژی‌های ساده و در عین حال مؤثر راهنمایی می‌کند تا بتوانید به‌طور پایدار در جهت اهداف شخصی و حرفه‌ای خود کار کنید. از مدیریت زمان در کوتاه‌مدت و بلندمدت، تا نظارت بر پیشرفت، تغییر رویکرد و جشن گرفتن پیروزی‌های کوچک در طول مسیر، این پلک‌ها کلیدهای کسب و حفظ انگیزه را نشان می‌دهند.</p>', '2017-04-04 00:00:00', 4, 64, 'https://images.blinkist.io/images/books/58de68f12b329600041cc1a2/1_1/470.jpg', '/en/books/get-momentum-en/purchase', 'شتاب-بگیرید', '2023-01-26 19:33:41.188711', '2023-01-26 19:33:41.188711', NULL, 'Get Momentum');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (423, 'کتابی که دوست داشتید والدینتان خوانده بودند (و فرزندانتان از خواندن شما خوشحال خواهند شد)', 'توصیه صحیح والدین بر اساس روانشناسی', 'توصیه صحیح والدین بر اساس روانشناسی', 19, 6, 'book', 't', '<p><em>کتابی که آرزو می‌کنید والدینتان می‌خواندند (و فرزندانتان از خواندن شما خوشحال خواهند شد) </em>(2019) دقیقاً همان چیزی است که به نظر می‌رسد: کتابی در مورد تربیت کودکان و گنجینه‌ای از دانش عملی که نمی توانید فکر نکنید دوران کودکی شما از آن سود می برد. این کتاب با توجه به سلامت روان و رشد عاطفی، رویکردی جایگزین برای فرزندپروری دارد که برای دنیای مدرن ما مناسب است.</p>', '2019-05-20 00:00:00', 5, 503, 'https://images.blinkist.io/images/books/5cdfd0246cee0700086aa1f1/1_1/470.jpg', '/en/books/the-book-you-wish-your-parents-had-read-and-your-children-will-be-glad-that-you-did-en/purchase', 'کتابی-که-دوست-داشتید-والدینتان-خوانده-بودند-(و-فرزندانتان-از-خواندن-شما-خوشحال-خواهند-شد)', '2023-01-26 19:33:46.363904', '2023-01-26 19:33:46.363904', NULL, 'The Book You Wish Your Parents Had Read (and Your Children Will Be Glad That You Did)');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (424, 'دو و بیست', 'چگونه استادان سهام خصوصی همیشه برنده می شوند', 'چگونه استادان سهام خصوصی همیشه برنده می شوند', 16, 4, 'book', 't', '<p><em>Two and Twenty</em> (2022) روایتی نزدیک و شخصی از دنیای مرموز سرمایه خصوصی ارائه می دهد. اطلاعاتی در مورد این شاخه منحصر به فرد از بخش مالی ارائه می دهد و توضیح می دهد که چه چیزی آن را از سایر مدل های سرمایه گذاری متمایز می کند.</p>', '2022-11-15 00:00:00', 5, 323, 'https://images.blinkist.io/images/books/63734fe873bf6d000e2d5833/1_1/470.jpg', '/en/books/two-and-twenty-en/purchase', 'دو-و-بیست', '2023-01-26 19:33:51.090256', '2023-01-26 19:33:51.090256', NULL, 'Two and Twenty');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (425, 'انجام فلسفه', 'از کنجکاوی مشترک تا استدلال منطقی', 'از کنجکاوی مشترک تا استدلال منطقی', 26, 9, 'book', 't', '<p><em>انجام فلسفه</em> (2018) برخی از کلیشه‌هایی را که همچنان در شکار فیلسوفان وجود دارد، از بین می‌برد. به‌ویژه، این ایده فراگیر را هدف قرار می‌دهد که فلسفه با توجه به موفقیت علوم طبیعی بی‌ربط شده است و دلیل قانع‌کننده‌ای برای این است که چرا فلسفه هنوز هم امروز مهم و تأثیرگذار است.</p>', '2019-11-04 00:00:00', 4, 89, 'https://images.blinkist.io/images/books/5dbb2f486cee070008edc695/1_1/470.jpg', '/en/books/doing-philosophy-en/purchase', 'انجام-فلسفه', '2023-01-26 19:33:56.318312', '2023-01-26 19:33:56.318312', NULL, 'Doing Philosophy');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (426, 'پیشرو با عشق و خنده', 'رها کردن و واقعی شدن در محل کار', 'رها کردن و واقعی شدن در محل کار', 19, 6, 'book', 't', '<p><em>رهبری با عشق و خنده </em>(2021) بررسی می‌کند که چگونه رویکرد عشق و خنده به رهبری می‌تواند منجر به عملکرد بهتر تیم، بهبود روحیه، اعتماد، خلاقیت و بهبود سلامت شود. اطلاعات مورد نیاز برای رهبران برای نشان دادن عشق و هدایت مشکلات احتمالی شوخ طبعی در محل کار را فراهم می کند.</p>', '2021-11-19 00:00:00', 4, 149, 'https://images.blinkist.io/images/books/618d19bb6cee0700079bc1e8/1_1/470.jpg', '/en/books/leading-with-love-and-laughter-en/purchase', 'پیشرو-با-عشق-و-خنده', '2023-01-26 19:34:01.377364', '2023-01-26 19:34:01.377364', NULL, 'Leading with Love and Laughter');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (427, 'هزاره را شکست', 'خراشیدن را متوقف کنید و زندگی مالی خود را با هم بسازید', 'خراشیدن را متوقف کنید و زندگی مالی خود را با هم بسازید', 21, 8, 'book', 't', '<p><em>Broke Millennial </em>(2017) یک راهنمای هوشمند برای امور مالی شخصی است که برای کمک به بیست و سی و چند ساله‌هایی که پول نقد ندارند، طراحی شده است تا خودشان را برای آینده آماده کنند. این پلک‌ها با نکات و ترفندهای ساده و در عین حال مؤثر، به شما کمک می‌کنند تا از خراشیدن خودداری کنید و از نظر مالی و شخصی پیشرفت کنید. </p>', '2020-07-09 00:00:00', 4, 128, 'https://images.blinkist.io/images/books/5eff4c606cee070006b9c400/1_1/470.jpg', '/en/books/broke-millennial-en/purchase', 'هزاره-را-شکست', '2023-01-26 19:34:07.116769', '2023-01-26 19:34:07.116769', NULL, 'Broke Millennial');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (428, 'اسپین سوکس', 'ارتباطات و مدیریت شهرت در عصر دیجیتال', 'ارتباطات و مدیریت شهرت در عصر دیجیتال', 19, 9, 'book', 't', '<p><em>Spin Sucks</em> (2014) کلیشه های بازاریابی قدیمی را کاهش می دهد و ارتباطات تجاری را برای عصر رسانه های اجتماعی به روز می کند، جایی که خدمات مشتری در پیام های نام تجاری محو می شود و هر اشتباهی برای آیندگان حفظ می شود. این به شما می آموزد که چگونه قدرت سئو و بازاریابی محتوا خود را به حداکثر برسانید تا به مخاطبان محصول خود دسترسی پیدا کنید - و آنها را حفظ کنید.</p>', '2015-09-30 00:00:00', 4, 10, 'https://images.blinkist.io/images/books/560928178a14e60009000059/1_1/470.jpg', '/en/books/spin-sucks-en/purchase', 'اسپین-سوکس', '2023-01-26 19:34:12.927126', '2023-01-26 19:34:12.927126', NULL, 'Spin Sucks');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (429, 'هلو بخور', 'یک خاطره', 'یک خاطره', 24, 8, 'book', 't', '<p><em>یک هلو بخورید </em> (2020) خاطرات صریح است که به دنبال ظهور سرآشپز آمریکایی دیوید چانگ به ستاره شدن در آشپزی است. این یک گزارش خام و صادقانه از مبارزات چانگ با بیماری روانی، افکار او در مورد فرهنگ و هویت، و نحوه اجرای دیدگاه خود از شیوه جدید غذا خوردن در آمریکا است.</p>', '2020-11-06 00:00:00', NULL, 9, 'https://images.blinkist.io/images/books/5fa01d2c6cee070006d9e3cc/1_1/470.jpg', '/en/books/eat-a-peach-en/purchase', 'هلو-بخور', '2023-01-26 19:34:17.984655', '2023-01-26 19:34:17.984655', NULL, 'Eat a Peach');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (430, 'فروش بینش', 'با سناریوهای بینش، ارزش را بفروشید و محصول خود را متمایز کنید', 'با سناریوهای بینش، ارزش را بفروشید و محصول خود را متمایز کنید', 10, 5, 'book', 'f', '<p><em>فروش بینش</em> (2014) با تنظیم سناریوهایی که خریدار را روشن می کند و اعتماد ایجاد می کند، تکنیک های جدیدی را برای فروشندگان روشن می کند تا فروش بیشتری را به دست آورند. با استفاده از "سناریوهای بینش"، یک تیم فروش نه تنها می تواند روابط فروش را مستحکم کند، بلکه حجم فروش را نیز به میزان قابل توجهی افزایش می دهد!</p>', '2015-06-15 00:00:00', 4, 23, 'https://images.blinkist.io/images/books/557d9d3565333800071d0000/1_1/470.jpg', '/en/books/insight-selling-en/purchase', 'فروش-بینش', '2023-01-26 19:34:23.854373', '2023-01-26 19:34:23.854373', NULL, 'Insight Selling');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (431, 'امکان را انتخاب کنید', 'به دنبال تغییر باشید، ریسک کنید و پیشرفت کنید (حتی وقتی شکست می خورید)', 'به دنبال تغییر باشید، ریسک کنید و پیشرفت کنید (حتی وقتی شکست می خورید)', 28, 9, 'book', 't', '<p><em>Choose Possibility</em> (2021) یک نقشه راه برای ایجاد هوشمندی و شجاعت لازم برای تبدیل شدن به یک استاد ریسک ارائه می دهد. برگرفته از مسیر پر پیچ و خم سوخیندر سینگ کسیدی، رهبر فناوری در کسب و کار،<em> </em>این افسانه را که ریسک مربوط به انتخاب‌های منحصر به فرد و تغییردهنده زندگی است، از بین می‌برد. در عوض،<em> </em>نشان می‌دهد که چگونه ریسک‌پذیری یک فرآیند، تمرین و مهارتی است که می‌تواند پتانسیل حرفه‌ای شما را باز کند.</p>', '2021-10-16 00:00:00', 5, 94, 'https://images.blinkist.io/images/books/616805766cee0700089d642f/1_1/470.jpg', '/en/books/choose-possibility-en/purchase', 'امکان-را-انتخاب-کنید', '2023-01-26 19:34:29.881639', '2023-01-26 19:34:29.881639', NULL, 'Choose Possibility');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (432, 'وقتی دوست دارید همسرتان را ترک کنید دوست داشته باشید', 'کمک واقعی برای قلب های ناامید در ازدواج های دشوار', 'کمک واقعی برای قلب های ناامید در ازدواج های دشوار', 21, 8, 'book', 't', '<p><em>دوست داشتن همسرتان وقتی احساس می‌کنید می‌خواهید دور شوید </em>(2008) درباره ازدواج‌های دشوار و چگونگی حل همه‌چیز در زمانی است که بیشتر وسوسه می‌شوید دکمه بیرون را فشار دهید. این انعکاس صبورانه و متفکرانه در مورد ازدواج های سخت که توسط یک مشاور ازدواج با سال ها تجربه عملی نوشته شده است، در نهایت سرشار از امید است. گری چپمن استدلال می کند که با درک کافی، همدلی و ارتباط روشن، ازدواج های کمی وجود دارد که نمی توان آنها را نجات داد.</p>', '2018-11-08 00:00:00', 4, 126, 'https://images.blinkist.io/images/books/5be2be216cee07000722b228/1_1/470.jpg', '/en/books/loving-your-spouse-when-you-feel-like-walking-away-en/purchase', 'وقتی-دوست-دارید-همسرتان-را-ترک-کنید-دوست-داشته-باشید', '2023-01-26 19:34:35.765286', '2023-01-26 19:34:35.765286', NULL, 'Loving Your Spouse When You Feel Like Walking Away');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (433, 'اهداف!', 'چگونه هر آنچه را که می خواهید به دست آورید - سریعتر از آنچه فکر می کنید ممکن است', 'چگونه هر آنچه را که می خواهید به دست آورید - سریعتر از آنچه فکر می کنید ممکن است', 21, 7, 'book', 't', '<p><em>اهداف! </em>(2003) قدرت هدف گذاری را بررسی می کند. نکات و تکنیک هایی را برای دستیابی به مهم ترین اهداف شما در زندگی بیان می کند و ارتباط بین هدف گذاری و موفقیت را بررسی می کند.</p>', '2021-05-24 00:00:00', 5, 468, 'https://images.blinkist.io/images/books/60a780ba6cee070007790e83/1_1/470.jpg', '/en/books/goals-en/purchase', 'اهداف!', '2023-01-26 19:34:41.983903', '2023-01-26 19:34:41.983903', NULL, 'Goals!');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (434, 'پولیمات', 'باز کردن قدرت تطبیق پذیری انسان', 'باز کردن قدرت تطبیق پذیری انسان', 24, 8, 'book', 't', '<p>The Polymath (2019) توضیح می دهد که چگونه <em>تخصصی بیش از حد</em> تشویق شده توسط جامعه، رشد، خلاقیت و خودشکوفایی افراد را خفه می کند. در عوض، این کتاب استدلال می‌کند که همه باید ظرفیت‌های چند ریاضی خود را پرورش دهند و ساختارهای آموزشی و حرفه‌ای باید دوباره پیکربندی شوند تا پتانسیل ذاتی انسانی ما را برای تفکر، یادگیری و کار در زمینه‌های مختلف و به روش‌های مختلف منعکس کند.</p>', '2019-09-26 00:00:00', 4, 127, 'https://images.blinkist.io/images/books/5d89ecf66cee0700095f1aa9/1_1/470.jpg', '/en/books/the-polymath-en/purchase', 'پولیمات', '2023-01-26 19:34:47.047538', '2023-01-26 19:34:47.047538', NULL, 'The Polymath');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (435, 'نژاد نادر', 'راهنمای موفقیت برای افراد نافرمانی، خطرناک و متفاوت', 'راهنمای موفقیت برای افراد نافرمانی، خطرناک و متفاوت', 14, 7, 'book', 't', '<p><em>نژاد کمیاب </em>(2019) راهنمای موفقیت تجاری و شخصی برای کسانی است که به ضرب و شتم خود می روند. این مانیفست جسورانه از شما می‌خواهد از همنوایی خودداری کنید و در عوض ویژگی‌هایی را که شما را متمایز می‌کند، بپذیرید.</p>', '2020-08-18 00:00:00', 4, 54, 'https://images.blinkist.io/images/books/5f359f7e6cee0700065032a6/1_1/470.jpg', '/en/books/rare-breed-en/purchase', 'نژاد-نادر', '2023-01-26 19:34:51.93629', '2023-01-26 19:34:51.93629', NULL, 'Rare Breed');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (436, 'راهنمای نهایی بازنشستگی برای 50+', 'استراتژی های برنده برای ماندگاری پول در طول عمر', 'استراتژی های برنده برای ماندگاری پول در طول عمر', 23, 8, 'book', 't', '<p><em>راهنمای نهایی بازنشستگی برای 50+ </em>(2020) راهنمای بازنشستگی توسط یکی از مشهورترین کارشناسان پولی آمریکا - سوزه اورمن است. مملو از نکات و ترفندهای عملی در مورد همه چیز، از کوچک سازی گرفته تا سرمایه گذاری عاقلانه، به شما کمک می کند تا یک برنامه بازنشستگی ایجاد کنید که رفاه مالی و آرامش خاطر را تضمین می کند.</p>', '2020-06-09 00:00:00', 4, 236, 'https://images.blinkist.io/images/books/5edac2526cee0700064e702c/1_1/470.jpg', '/en/books/the-ultimate-retirement-guide-for-50-plus-en/purchase', 'راهنمای-نهایی-بازنشستگی-برای-50+', '2023-01-26 19:34:57.085814', '2023-01-26 19:34:57.085814', NULL, 'The Ultimate Retirement Guide for 50+');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (437, 'شار', '8 ابرقدرت برای رشد در تغییر مداوم', '8 ابرقدرت برای رشد در تغییر مداوم', 27, 8, 'book', 't', '<p><em>Flux </em>(2021) طرز فکری را برای تغییر رابطه شما با تغییر از ترس به امید ارائه می دهد. فرقی نمی‌کند تحت فشار همه‌گیری باشید، با پایان یک رابطه روبرو شده‌اید، یا نگران تغییرات آب و هوایی هستید، این پلک‌ها به جزئیات هشت روش ضروری برای پیمایش تغییرات هم از نظر شخصی و هم از نظر حرفه‌ای می‌پردازند.</p>', '2021-10-12 00:00:00', 4, 166, 'https://images.blinkist.io/images/books/6160356f6cee0700075f27dc/1_1/470.jpg', '/en/books/flux-en/purchase', 'شار', '2023-01-26 19:35:02.194614', '2023-01-26 19:35:02.194614', NULL, 'Flux');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (438, 'شجاعت شاد بودن', 'رضایت واقعی در توان شماست', 'رضایت واقعی در توان شماست', 15, 8, 'book', 't', '<p><em>شجاعت شاد بودن </em>(2019)<em></em>فلسفه های آموزشی و نظریه های رشد کودکی آلفرد آدلر، روانشناس اوایل قرن بیستم را می گیرد و آنها را در زندگی و یادگیری معاصر به کار می برد. نویسندگان کیشیمی و کوگا نشان می‌دهند که آموزه‌های مترقی آدلر به همان اندازه که در آغاز قرن گذشته بود، امروز نیز مرتبط هستند.</p>', '2020-06-05 00:00:00', 4, 67, 'https://images.blinkist.io/images/books/5ed6b6226cee0700060d2135/1_1/470.jpg', '/en/books/the-courage-to-be-happy-en/purchase', 'شجاعت-شاد-بودن', '2023-01-26 19:35:07.560942', '2023-01-26 19:35:07.560942', NULL, 'The Courage to be Happy');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (439, 'طرح بزرگ', 'چگونه علم اسرار جهان را باز کرد', 'چگونه علم اسرار جهان را باز کرد', 19, 8, 'book', 't', '<p><em>طراحی بزرگ</em> (2010) داستان شگفت انگیزی را بیان می کند که چگونه انسان ها به وجود آمدند و چگونه شروع به استفاده از روش علمی برای توضیح رشد چشمگیر خود به عنوان یک گونه و جهان پیرامون خود کردیم. از قوانین بنیادی نیوتن و انیشتین گرفته تا علم فیزیک کوانتومی که ذهن را خم می کند، دریابید که تا چه حد پیش رفته ایم و چقدر به پاسخ به سؤالات بزرگ زندگی نزدیک شده ایم.</p>', '2017-08-30 00:00:00', 4, 218, 'https://images.blinkist.io/images/books/59a2dc86b238e10005eeb75d/1_1/470.jpg', '/en/books/the-grand-design-en/purchase', 'طرح-بزرگ', '2023-01-26 19:35:12.416667', '2023-01-26 19:35:12.416667', NULL, 'The Grand Design');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (440, 'قدرتمند', 'ساختن فرهنگ آزادی و مسئولیت', 'ساختن فرهنگ آزادی و مسئولیت', 18, 8, 'book', 't', '<p>بر اساس شیوه‌های کاری در Netflix، <em>Powerful</em> (2017) راهنمای ایجاد یک فرهنگ کاری است که می‌تواند با بازارهای پر سرعت و همیشه در حال تغییر امروز سازگار شود. بینش هایی را ارائه می دهد که ریشه در روشی غیر متعارف برای مدیریت افراد دارد. شما هشت شیوه مدیریت را کشف خواهید کرد که به شما کمک می کند فرهنگ کاری و کسب و کار موفقی ایجاد کنید.</p>', '2018-04-12 00:00:00', 4, 40, 'https://images.blinkist.io/images/books/5acca03fb238e1000747de8b/1_1/470.jpg', '/en/books/powerful-en/purchase', 'قدرتمند', '2023-01-26 19:35:17.59639', '2023-01-26 19:35:17.59639', NULL, 'Powerful');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (441, 'ذهن بیش از درهم ریختگی', 'راه خود را به خانه ای آرام و شاد تمیز کنید', 'راه خود را به خانه ای آرام و شاد تمیز کنید', 15, 5, 'book', 't', '<p><em>ذهن بیش از به هم ریختگی </em>(2019)<em> </em>نکات و تکنیک های ساده ای را برای دور نگه داشتن خانه از درهم ریختگی بررسی می کند. این پلک‌ها همچنین تأثیر آشفتگی را بر سلامت روان شما نشان می‌دهد و توضیح می‌دهد که چگونه می‌توانید بدون نیاز به مواد شیمیایی خشن به کارهای خانه به روشی سازگارتر با محیط زیست برخورد کنید. </p>', '2020-07-26 00:00:00', 4, 180, 'https://images.blinkist.io/images/books/5f160d976cee0700068ac1df/1_1/470.jpg', '/en/books/mind-over-clutter-en/purchase', 'ذهن-بیش-از-درهم-ریختگی', '2023-01-26 19:35:22.681991', '2023-01-26 19:35:22.681991', NULL, 'Mind Over Clutter');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (442, 'حقایق ساده رهبری', '52 راه برای خدمتگزار بودن و ایجاد اعتماد', '52 راه برای خدمتگزار بودن و ایجاد اعتماد', 20, 12, 'book', 't', '<p><em>حقیقت های ساده رهبری </em>(2022) اصول ساده ای را بررسی می کند که رهبران را از خوب به عالی ارتقا می دهد. اشتباهات رایجی را که رهبران مرتکب می شوند آشکار می کند - و رفتارهایی را که منجر به عملکرد بهتر تیم و روابط کاری نزدیک تر می شود، آشکار می کند. </p>', '2022-03-17 00:00:00', 5, 258, 'https://images.blinkist.io/images/books/6232f9f76cee0700084f372b/1_1/470.jpg', '/en/books/simple-truths-of-leadership-en/purchase', 'حقایق-ساده-رهبری', '2023-01-26 19:35:27.337981', '2023-01-26 19:35:27.337981', NULL, 'Simple Truths of Leadership');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (443, 'چگونه در 90 ثانیه یا کمتر مردم را دوست داشته باشیم؟', 'ارتباطات فوری و معنادار برای مصاحبه، فروش، مدیریت، طرح ریزی ایجاد کنید', 'ارتباطات فوری و معنادار برای مصاحبه، فروش، مدیریت، طرح ریزی ایجاد کنید', 18, 7, 'book', 't', '<p><em>چگونه در 90 ثانیه یا کمتر مردم را دوست داشته باشیم</em> (2000) راهنمای ارتباط، برقراری ارتباط و گسترش دنیای اجتماعی شما است. این پلک ها به شما یاد می دهد که چگونه با غریبه ها گفتگو کنید و آنها را دوست داشته باشید. همچنین به شما نشان می دهد که چگونه حتی ظریف ترین حرکات آنها را رمزگشایی کنید.</p>
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (444, 'قوانین جدید بازاریابی و روابط عمومی', 'نحوه استفاده از رسانه های اجتماعی، ویدیوی آنلاین، برنامه های کاربردی موبایل، وبلاگ ها، نسخه های جدید و بازاریابی ویروسی برای دسترسی مستقیم به خریداران', 'نحوه استفاده از رسانه های اجتماعی، ویدیوی آنلاین، برنامه های کاربردی موبایل، وبلاگ ها، نسخه های جدید و بازاریابی ویروسی برای دسترسی مستقیم به خریداران', 17, 7, 'book', 't', '<p><em>قوانین جدید بازاریابی و روابط عمومی </em>(2007) راهنمای شما برای دنیای استراتژی های بازاریابی آنلاین است. این پلک‌ها توضیح می‌دهند که چگونه و چرا برقراری ارتباط با اصالت و چابکی در رسانه‌های اجتماعی به شما کمک می‌کند به مشتریان بیشتری دست پیدا کنید و برند خود را به سطح بعدی ببرید.</p>', '2016-06-07 00:00:00', 4, 59, 'https://images.blinkist.io/images/books/574ffbd862588b00033e0e5f/1_1/470.jpg', '/en/books/the-new-rules-of-marketing-and-pr-en/purchase', 'قوانین-جدید-بازاریابی-و-روابط-عمومی', '2023-01-26 19:35:37.166026', '2023-01-26 19:35:37.166026', NULL, 'The New Rules of Marketing &amp; PR');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (445, 'کارهای خلاقانه برای افراد کنجکاو', 'چگونه به روش های غیر متعارف فکر کنیم، خلق کنیم و رهبری کنیم', 'چگونه به روش های غیر متعارف فکر کنیم، خلق کنیم و رهبری کنیم', 23, 8, 'book', 't', '<p><em>اعمال خلاق برای افراد کنجکاو </em>(2021) بینش‌هایی را درباره خلاقیت و طراحی جمع‌آوری می‌کند که در کلاس‌های مدرسه طراحی مشهور هاسو پلاتنر استنفورد، که به d.school نیز معروف است، آموزش داده می‌شود. علاوه بر مقالاتی در مورد طرز فکر و مهارت های مورد نیاز برای اقدام خلاق، بیش از 80 تمرین عملی ارائه می دهد که توسط مربیان ده ها زمینه از جمله پزشکی، آموزش و غیرانتفاعی برای کمک به بهبود توانایی شما در حل مشکلات، چه شخصی و چه در مقیاس جهانی استفاده می شود. .</p>', '2022-01-06 00:00:00', 4, 224, 'https://images.blinkist.io/images/books/61c1b7e56cee07000833470a/1_1/470.jpg', '/en/books/creative-acts-for-curious-people-en/purchase', 'کارهای-خلاقانه-برای-افراد-کنجکاو', '2023-01-26 19:35:42.119912', '2023-01-26 19:35:42.119912', NULL, 'Creative Acts for Curious People');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (446, 'تصمیمات افراد بزرگ', 'چرا آنها بسیار مهم هستند، چرا آنها بسیار سخت هستند و چگونه می توانید بر آنها تسلط پیدا کنید', 'چرا آنها بسیار مهم هستند، چرا آنها بسیار سخت هستند و چگونه می توانید بر آنها تسلط پیدا کنید', 18, 9, 'book', 't', '<p><em>تصمیمات افراد بزرگ</em> (2007) راه های بسیاری را توضیح می دهد که از طریق آن انتخاب های پرسنل می تواند یک سازمان را ایجاد یا شکست دهد. این راهنمای گام به گام برای یافتن و استخدام کاندیدای مناسب برای شغل مناسب، پر از توصیه های عملی و فوری قابل اجرا، برای کسب و کارها در هر شکل و اندازه مفید است.</p>', '2015-10-08 00:00:00', 4, 15, 'https://images.blinkist.io/images/books/561437d036323300071f0000/1_1/470.jpg', '/en/books/great-people-decisions-en/purchase', 'تصمیمات-افراد-بزرگ', '2023-01-26 19:35:47.01441', '2023-01-26 19:35:47.01441', NULL, 'Great People Decisions');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (447, 'قوانین سادگی', 'طراحی، فناوری، تجارت، زندگی', 'طراحی، فناوری، تجارت، زندگی', 18, 9, 'book', 't', '<p><em></em> <em>قوانین</em> <em></em> <em>سادگی</em> از مجموعه‌ای از "قوانین" تشکیل شده است که توسط نویسنده برای تلاش برای معنی و ماهیت سادگی را درک کنید. در طول مسیر، توصیه های مفیدی در مورد چگونگی معرفی سادگی به زندگی روزمره، تجارت و طراحی محصول ارائه می دهد.</p>', '2014-06-03 14:45:53', 4, 51, 'https://images.blinkist.io/images/books/538f2fc33761300007170100/1_1/470.jpg', '/en/books/the-laws-of-simplicity-en/purchase', 'قوانین-سادگی', '2023-01-26 19:35:51.973314', '2023-01-26 19:35:51.973314', NULL, 'The Laws of Simplicity');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (448, 'دویدن لاغر', 'از طرح A به برنامه ای که کار می کند تکرار کنید', 'از طرح A به برنامه ای که کار می کند تکرار کنید', 14, 6, 'book', 't', '<p><em>Running Lean </em>راهبردی بی خطر را به شما ارائه می دهد تا محصول جدید خود را با موفقیت وارد بازار کنید. این کتاب با ترویج روشی برای آزمایش هوشمندانه و برنامه‌ریزی پیش رو، راهنمای گام به گام در ساختن یک مدل کسب‌وکار به شما ارائه می‌دهد که در عین صرفه‌جویی در زمان، هزینه و تلاش عمل می‌کند.</p>', '2015-02-17 00:00:00', 4, 56, 'https://images.blinkist.io/images/books/54e359e2303764000a240000/1_1/470.jpg', '/en/books/running-lean-en/purchase', 'دویدن-لاغر', '2023-01-26 19:35:56.81989', '2023-01-26 19:35:56.81989', NULL, 'Running Lean');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (449, 'ساخته شده برای آخرین', 'عادات موفق شرکت های رویایی', 'عادات موفق شرکت های رویایی', 19, 9, 'book', 't', '<p><em>Built to Last</em> (1994) 18 شرکت خارق‌العاده و قابل احترام را بررسی می‌کند تا کشف کند چه چیزی آنها را برای دهه‌ها و در برخی موارد برای نزدیک به دو قرن پیشرفت کرده است. این مطالعه پیشگامانه تفاوت های ساده اما الهام بخش را نشان می دهد که این شرکت های رویایی را از رقبای کمتر موفق خود متمایز می کند.</p>
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (450, 'راهنمای رهبر برای مدیریت رادیکال', 'اختراع مجدد محل کار برای قرن بیست و یکم', 'اختراع مجدد محل کار برای قرن بیست و یکم', 17, 7, 'book', 't', '<p><em>راهنمای رهبر برای مدیریت رادیکال </em>(2010) هفت اصل کلیدی را ارائه می دهد که به مدیران کمک می کند تا روی خوشحال کردن مشتریان خود متمرکز شوند. متوجه خواهید شد که ابزارهای کاربردی ارائه شده در این چشمک ها نه تنها سود شما را افزایش می دهند. آنها شما و نیروی کارتان را روی آنچه واقعا مهم است متمرکز نگه می دارند.</p>', '2017-10-27 00:00:00', 4, 63, 'https://images.blinkist.io/images/books/59ec853bb238e1000645541f/1_1/470.jpg', '/en/books/the-leaders-guide-to-radical-management-en/purchase', 'راهنمای-رهبر-برای-مدیریت-رادیکال', '2023-01-26 19:36:07.049412', '2023-01-26 19:36:07.049412', NULL, 'The Leader’s Guide to Radical Management');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (451, 'چوب پنبه دورک', 'ماجراجویی با شراب در میان ساملی‌های وسواسی، شکارچیان بطری بزرگ و دانشمندان سرکشی که به من آموختند برای طعم زندگی کنم', 'ماجراجویی با شراب در میان ساملی‌های وسواسی، شکارچیان بطری بزرگ و دانشمندان سرکشی که به من آموختند برای طعم زندگی کنم', 24, 8, 'book', 't', '<p><em>Cork Dork</em> (2019) دنیای شراب را از نگاه یک متخصص مشتاق شراب بررسی می کند. بیانکا بوسکر شغل خود را در روزنامه نگاری رها کرد و یک هدف بلندپروازانه برای خود تعیین کرد: تبدیل شدن به یک روزنامه نگار خبره. علیرغم داشتن دانش قبلی کمی از شراب، او تنها در هجده ماه به این امر دست یافت. در طول راه، او همه چیزهایی را که باید درباره شراب دانست - درست کردن، سرو کردن، چشیدن آن و صحبت کردن در مورد آن، یاد گرفت.</p>', '2020-01-17 00:00:00', 4, 50, 'https://images.blinkist.io/images/books/5e1db1956cee070008a883a6/1_1/470.jpg', '/en/books/cork-dork-en/purchase', 'چوب-پنبه-دورک', '2023-01-26 19:36:12.049481', '2023-01-26 19:36:12.049481', NULL, 'Cork Dork');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (452, 'این جایی است که شما تعلق دارید', 'هنر و علم دوست داشتن مکانی که در آن زندگی می کنید', 'هنر و علم دوست داشتن مکانی که در آن زندگی می کنید', 13, 6, 'book', 't', '<p><em>This is Where You Belong</em> (2016) راهنمای دوست داشتن شهری است که در آن زندگی می کنید. این پلک ها توضیح می دهند که چگونه از زندگی خود در هر کجا که هستید با کشف همه فرصت های شگفت انگیزی که شهرتان دارد لذت ببرید. پیشنهاد.</p>', '2016-10-25 00:00:00', 4, 13, 'https://images.blinkist.io/images/books/580b66aad4d2ce0003dd2443/1_1/470.jpg', '/en/books/this-is-where-you-belong-en/purchase', 'این-جایی-است-که-شما-تعلق-دارید', '2023-01-26 19:36:17.274935', '2023-01-26 19:36:17.274935', NULL, 'This Is Where You Belong');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (453, 'لارنس در عربستان', 'جنگ، فریب، حماقت امپراتوری و ساخت خاورمیانه مدرن', 'جنگ، فریب، حماقت امپراتوری و ساخت خاورمیانه مدرن', 33, 15, 'book', 't', '<p><em>لارنس در عربستان</em> (2013) نشان می دهد که چگونه یک گروه کوچک از شخصیت ها خاورمیانه را برای همیشه در طول جنگ جهانی اول و شورش عرب تغییر دادند. در مرکز آن T. E. Lawrence، یک افسر نظامی جوان وحشی و آموزش ندیده بود که بین دو ملت در هم گسیخته بود و وعده های شکسته شده سیاست و وحشت جنگ را از نزدیک تجربه کرد.</p>', '2016-05-27 00:00:00', 5, 78, 'https://images.blinkist.io/images/books/5741c2992edd1b00032e6c0e/1_1/470.jpg', '/en/books/lawrence-in-arabia-en/purchase', 'لارنس-در-عربستان', '2023-01-26 19:36:22.168462', '2023-01-26 19:36:22.168462', NULL, 'Lawrence in Arabia');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (454, 'مردم بیش از سود', 'سیستم را بشکنید، با هدف زندگی کنید، موفق تر باشید', 'سیستم را بشکنید، با هدف زندگی کنید، موفق تر باشید', 17, 7, 'book', 't', '<p><em>People Over Profit</em>(2015) راهنمای شما برای سرمایه داری، گذشته، حال و آینده است. این پلک‌ها توضیح می‌دهند که واقعاً چه چیزی شرکت‌های شرور را ایجاد می‌کند، و اصولی را که شما را راهنمایی می‌کند تا یک کسب‌وکار را با صداقت ایجاد کرده و رشد دهید.</p>', '2015-09-23 00:00:00', 5, 29, 'https://images.blinkist.io/images/books/55fffb2f615cd1000900008a/1_1/470.jpg', '/en/books/people-over-profit-en/purchase', 'مردم-بیش-از-سود', '2023-01-26 19:36:27.277486', '2023-01-26 19:36:27.277486', NULL, 'People Over Profit');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (464, 'فروش چابک', 'به سرعت در دنیای فروش در حال تغییر امروزی به سرعت برسید', 'به سرعت در دنیای فروش در حال تغییر امروزی به سرعت برسید', 18, 7, 'book', 't', '<p>در <em>Agile Selling، </em> خواهید فهمید که چگونه بهره وری خود را افزایش دهید و یاد بگیرید که در هر نوع محیط فروش پیشرفت کنید. این کتاب استراتژی‌های فروشندگان عالی و نحوه سازگاری آنها با شرایط جدید را بررسی می‌کند و توصیه‌های عملی در مورد اینکه چگونه شما نیز می‌توانید در کسب و کار خود سازگارتر شوید، ارائه می‌دهد.</p>', '2014-11-26 00:00:00', 4, 58, 'https://images.blinkist.io/images/books/54734ba736356100098e0000/1_1/470.jpg', '/en/books/agile-selling-en/purchase', 'فروش-چابک', '2023-01-26 19:37:20.128986', '2023-01-26 19:37:20.128986', NULL, 'Agile Selling');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (455, 'معادله معجزه', 'دو تصمیمی که بزرگترین اهداف شما را از ممکن، به محتمل و اجتناب ناپذیر می‌برد.', 'دو تصمیمی که بزرگترین اهداف شما را از ممکن، به محتمل و اجتناب ناپذیر می‌برد.', 23, 8, 'book', 't', '<p><em>معادله معجزه </em>(2019) یک راهنمای عملی برای بهترین زندگی و تحقق رویاهایتان است. با تکیه بر خرد معجزه سازان قدیمی و جدید، نویسنده پرفروش و سخنران انگیزشی، هال الرود، نشان می دهد که چگونه پرنده ها با پایبندی به دو اصل اساسی به موفقیت می رسند: تعهد تزلزل ناپذیر و تلاش فوق العاده. مملو از توصیه های عملی در مورد همه چیز از مقابله با دردهای عاطفی گرفته تا اولویت بندی اهداف، این پلک زدن ها به شما کمک می کند گذشته را پشت سر بگذارید و به سمت آینده ای درخشان حرکت کنید.</p>', '2019-05-16 00:00:00', 4, 222, 'https://images.blinkist.io/images/books/5cdc6b3c6cee0700086a9a88/1_1/470.jpg', '/en/books/the-miracle-equation-en/purchase', 'معادله-معجزه', '2023-01-26 19:36:32.177495', '2023-01-26 19:36:32.177495', NULL, 'The Miracle Equation ');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (456, 'تحقیقی در مورد درک انسانی', 'کلاسیک در ادبیات فلسفی مدرن', 'کلاسیک در ادبیات فلسفی مدرن', 24, 7, 'book', 't', '<p><em>An Inquiry Concerning Human Understanding</em> (1748) خلاصه ای مختصر از فلسفه تجربی و شکاک هیوم را ارائه می دهد و یکی از تأثیرگذارترین متون اوایل دوره مدرن است. در دعوت به استفاده از عقل در رد "خرافات" فلسفه و دین متافیزیکی، این متن به ارائه مبنای فلسفی برای روش علمی که در آن زمان در اروپای روشنگری برجسته می شد کمک کرد. حتی امروزه، <em>تحقیق</em> هیوم یکی از بهترین مقدمه‌های فلسفه مدرن است.</p>', '2021-07-18 00:00:00', 5, 229, 'https://images.blinkist.io/images/books/60eff8286cee070007aa56dd/1_1/470.jpg', '/en/books/an-enquiry-concerning-human-understanding-en/purchase', 'تحقیقی-در-مورد-درک-انسانی', '2023-01-26 19:36:37.123676', '2023-01-26 19:36:37.123676', NULL, 'An Enquiry Concerning Human Understanding');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (457, 'یادداشت هایی در مورد یک سیاره عصبی', 'کیت بقای قرن بیست و یکمی خود را بسازید', 'کیت بقای قرن بیست و یکمی خود را بسازید', 21, 8, 'book', 't', '<p><em>یادداشت‌هایی درباره یک سیاره عصبی </em>(2018) راهنمای دلسوزانه‌ای در مورد چگونگی شاد و سلامت ماندن در دنیای مدرن و آشفته است. نویسنده مت هیگ با تکیه بر تجربیات شخصی به بررسی این موضوع می پردازد که چگونه فناوری می تواند استرس، افسردگی و اضطراب را تشدید کند، و راه هایی برای محافظت در برابر این موضوع ارائه می دهد.</p>', '2019-09-05 00:00:00', 5, 137, 'https://images.blinkist.io/images/books/5d6d29bb6cee0700081a68dc/1_1/470.jpg', '/en/books/notes-on-a-nervous-planet-en/purchase', 'یادداشت-هایی-در-مورد-یک-سیاره-عصبی', '2023-01-26 19:36:42.547192', '2023-01-26 19:36:42.547192', NULL, 'Notes on a Nervous Planet');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (458, 'علف هرز بزرگ', 'ماجراجویی‌های پرمخاطره یک کارآفرین در تجارت قانونی ماری جوانا', 'ماجراجویی‌های پرمخاطره یک کارآفرین در تجارت قانونی ماری جوانا', 14, 6, 'book', 't', '<p><em>Big Weed</em> (2015) روایت اول شخص از موفقیت کارآفرین کریستین هاگزت در تجارت در حال توسعه ماری جوانا قانونی است. او تمام موارد ضروری را که باید در مورد آینده در این بازار جدید بدانید را فاش می کند، و کمی در مورد اصول اولیه ماری جوانا که هر کارآفرین نوپایی باید بداند توضیح می دهد.</p>', '2015-07-08 00:00:00', 4, 13, 'https://images.blinkist.io/images/books/559bc55d3966610007650000/1_1/470.jpg', '/en/books/big-weed-en/purchase', 'علف-هرز-بزرگ', '2023-01-26 19:36:48.055436', '2023-01-26 19:36:48.055436', NULL, 'Big Weed');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (459, 'مردان پول', 'یک استارتاپ داغ، یک تقلب میلیارد دلاری، یک مبارزه برای حقیقت', 'یک استارتاپ داغ، یک تقلب میلیارد دلاری، یک مبارزه برای حقیقت', 21, 6, 'book', 't', '<p><em>Money Men </em>(2022) داستان شگفت انگیز ظهور و سقوط Wirecard است. زمانی که به عنوان PayPal اروپا توصیف می‌شد، گروه کوچکی از تحلیلگران، افشاگران و سرسختی یک روزنامه‌نگار لازم بود تا سرانجام این خانه از کارت‌ها را از بین ببرند.</p>', '2022-12-09 00:00:00', 5, 20, 'https://images.blinkist.io/images/books/6391e901dfab8000071bbcd7/1_1/470.jpg', '/en/books/money-men-en/purchase', 'مردان-پول', '2023-01-26 19:36:53.512514', '2023-01-26 19:36:53.512514', NULL, 'Money Men');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (460, 'صعود پول', 'تاریخ مالی جهان', 'تاریخ مالی جهان', 21, 11, 'book', 't', '<p><em> صعود پول </em> توضیحی است درباره اینکه چگونه رویدادهای تاریخی مختلف منجر به توسعه سیستم مالی فعلی شده است.</p>
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (461, 'اکونومیست: راهنمای اعداد', 'ملزومات اعداد تجاری', 'ملزومات اعداد تجاری', 19, 7, 'book', 't', '<p><em>The Economist:</em> <em>Numbers Guide</em> (1991) انواع ابزارهای ریاضی را بررسی می کند که در طیف وسیعی از محیط های تجاری بسیار مفید هستند. این پلک‌ها نشان می‌دهند که مدیریت ریسک با کمی کردن آن چقدر ساده است و به بهبود تصمیم‌گیری در فرآیند کمک می‌کند. مفاهیم ریاضی کتاب در سطح پایه توضیح داده شده است، بنابراین نیازی به دانش ریاضی قبلی نیست.</p>', '2015-06-15 00:00:00', 4, 36, 'https://images.blinkist.io/images/books/557d98c16533380007000000/1_1/470.jpg', '/en/books/the-economist-numbers-guide-en/purchase', 'اکونومیست:-راهنمای-اعداد', '2023-01-26 19:37:03.667431', '2023-01-26 19:37:03.667431', NULL, 'The Economist: Numbers Guide');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (462, 'لبه کوچک', 'تبدیل رشته های ساده به موفقیت و خوشبختی عظیم', 'تبدیل رشته های ساده به موفقیت و خوشبختی عظیم', 20, 7, 'book', 't', '<p><strong>درباره چیست؟</strong></p>
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (465, 'مشتریان خود را در آغوش بگیرید', 'هنوز راه اثبات شده ای برای شخصی سازی فروش و دستیابی به نتایج خیره کننده است', 'هنوز راه اثبات شده ای برای شخصی سازی فروش و دستیابی به نتایج خیره کننده است', 13, 6, 'book', 't', '<p><em>مشتریان خود را در آغوش بگیرید</em> (2003) بر اساس پنج دهه تجربه نویسنده در ایجاد کسب و کار مشتری محور کامل است. "در آغوش گرفتن" مشتریان شما به معنای برآوردن نیازهای آنها و سازماندهی کل شرکت شما در اطراف آنها است. ایجاد فرهنگ در آغوش گرفتن مؤثرترین راه برای دستیابی به موفقیت مالی و راضی نگه داشتن مشتریان است.</p>', '2015-10-07 00:00:00', 4, 26, 'https://images.blinkist.io/images/books/56142f0a3632330007010000/1_1/470.jpg', '/en/books/hug-your-customers-en/purchase', 'مشتریان-خود-را-در-آغوش-بگیرید', '2023-01-26 19:37:25.546198', '2023-01-26 19:37:25.546198', NULL, 'Hug Your Customers');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (466, 'هدیه شکست', 'چگونه بهترین والدین یاد می گیرند که رها کنند تا فرزندانشان موفق شوند', 'چگونه بهترین والدین یاد می گیرند که رها کنند تا فرزندانشان موفق شوند', 16, 7, 'book', 't', '<p>در <em>هدیه شکست</em> (2015)، لاهی دلایل قانع‌کننده‌ای برای مراقبان ارائه می‌کند تا کنترل فرزندان خود را رها کنند و اجازه دهند آنها شکست بخورند. لاهی استدلال می کند که با اتخاذ این رویکرد، فرصت مهمی به کودکان می دهد تا در مورد ارزش ها و مهارت های خود بیاموزند و در عین حال اعتماد به نفس، استقلال و احساس مسئولیت را در آنها تقویت می کند.</p>', '2016-03-07 00:00:00', 5, 40, 'https://images.blinkist.io/images/books/56dd900e24b39b000700001a/1_1/470.jpg', '/en/books/the-gift-of-failure-en/purchase', 'هدیه-شکست', '2023-01-26 19:37:30.615077', '2023-01-26 19:37:30.615077', NULL, 'The Gift of Failure');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (467, 'تغییر دهنده ی بازی', 'چگونه در اقتصاد استعداد 10 برابر باشیم', 'چگونه در اقتصاد استعداد 10 برابر باشیم', 19, 7, 'book', 't', '<p><em>تغییر بازی </em>(2020) راهنمای جذب استعدادهای فوق ستاره‌ای است که اقتصاد مدرن را تقویت می‌کنند. با توضیح چگونگی شناسایی و مدیریت استعدادهای برتر، به شما کمک می‌کند تا بفهمید چه استراتژی‌هایی برای شرکت‌ها و کارگران مورد نیاز است تا بتوانند در لبه برتر بمانند.</p>', '2020-11-26 00:00:00', 4, 52, 'https://images.blinkist.io/images/books/5fb7bba36cee070007a49929/1_1/470.jpg', '/en/books/game-changer-en/purchase', 'تغییر-دهنده-ی-بازی', '2023-01-26 19:37:35.524114', '2023-01-26 19:37:35.524114', NULL, 'Game Changer');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (468, 'تبلیغات نقدی', 'چگونه از بیش از 100 راز روانشناسی آژانس تبلیغاتی برای کسب درآمد بزرگ از فروش هر چیزی به هر کسی استفاده کنیم', 'چگونه از بیش از 100 راز روانشناسی آژانس تبلیغاتی برای کسب درآمد بزرگ از فروش هر چیزی به هر کسی استفاده کنیم', 23, 10, 'book', 't', '<p><em>تبلیغات نقدی </em>(2009) نشان می دهد که چگونه برای جذب مشتریان به یک کمپین تبلیغاتی میلیون دلاری نیاز ندارید. تنها چیزی که باید بدانید این است که چگونه و چرا تصمیم می گیریم خرید کنیم. این کتاب مملو از نکات کاربردی فوری است، همه چیزهایی را که باید در مورد چگونگی تبدیل تبلیغات خود به سود بدانید به شما می گوید.</p>', '2015-07-28 00:00:00', 5, 45, 'https://images.blinkist.io/images/books/55b76d2d3235390007210000/1_1/470.jpg', '/en/books/cashvertising-en/purchase', 'تبلیغات-نقدی', '2023-01-26 19:37:40.356622', '2023-01-26 19:37:40.356622', NULL, 'Cashvertising');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (469, 'مخالف خراب', 'تربیت کودکانی که در مورد پول مستقر، سخاوتمند و باهوش هستند', 'تربیت کودکانی که در مورد پول مستقر، سخاوتمند و باهوش هستند', 14, 6, 'book', 't', '<p><em>تضاد خراب</em> (2015) راهنمای اساسی برای تربیت کودکان صبور و سخاوتمند از طریق آموزش مالی است. این پلک‌ها به شما نشان می‌دهند که چگونه با صحبت کردن با او در مورد پول، مشارکت دادن او در تصمیم‌گیری‌های مالی و نشان دادن اهمیت سخاوت و کار، رشد فرزندتان را راهنمایی کنید.</p>', '2015-07-01 00:00:00', 4, 49, 'https://images.blinkist.io/images/books/559255356561380007000000/1_1/470.jpg', '/en/books/the-opposite-of-spoiled-en/purchase', 'مخالف-خراب', '2023-01-26 19:37:45.572986', '2023-01-26 19:37:45.572986', NULL, 'The Opposite of Spoiled');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (470, 'غرق', 'وقتی کسی وقت ندارد کار، عشق و بازی کنید', 'وقتی کسی وقت ندارد کار، عشق و بازی کنید', 19, 7, 'book', 't', '<p><em> Overwhelmed </em>(2014) نشان می‌دهد که چگونه نگرش‌های قدیمی ما نسبت به جنسیت، والدین و نژاد همه ما را تحت فشار و عصبانی می‌کند. نویسنده بریجید شولت نشان می دهد که چگونه چنین ایده های قدیمی ما را از زندگی شادتر و با رضایت بیشتر باز می دارند. با این حال، لازم نیست اینگونه باشد. راه های جایگزینی برای زندگی وجود دارد، فقط باید یاد بگیریم که چگونه آنها را اجرا کنیم.</p>', '2015-04-08 00:00:00', 3, 22, 'https://images.blinkist.io/images/books/552463b03066650007270000/1_1/470.jpg', '/en/books/overwhelmed-en/purchase', 'غرق', '2023-01-26 19:37:50.665924', '2023-01-26 19:37:50.665924', NULL, 'Overwhelmed');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (471, 'صحبت کردن با دیوانه', 'چگونه با افراد غیرمنطقی و غیرممکن زندگی خود برخورد کنید؟', 'چگونه با افراد غیرمنطقی و غیرممکن زندگی خود برخورد کنید؟', 19, 9, 'book', 't', '<p><em>Talking to Crazy</em> (2015) تصدیق می کند که هر فردی این پتانسیل را دارد که کمی دیوانه شود و در هنگام بروز خلق و خوی رفتار غیرمنطقی انجام دهد. این پلک‌ها توصیه‌های درستی درباره نحوه همدلی و برقراری ارتباط با یک فرد در «حالت دیوانه‌وار» ارائه می‌دهند تا بتوانید خود را از دور زدن عمیق نیز دور نگه دارید.</p>', '2016-01-29 00:00:00', 4, 39, 'https://images.blinkist.io/images/books/56a6b069fb7e870007000033/1_1/470.jpg', '/en/books/talking-to-crazy-en/purchase', 'صحبت-کردن-با-دیوانه', '2023-01-26 19:37:55.926539', '2023-01-26 19:37:55.926539', NULL, 'Talking to Crazy');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (472, 'جادوی متحول کننده زندگی نه دادن به فک', 'چگونه از سپری کردن زمانی که ندارید با افرادی که دوست ندارید کارهایی را که نمی خواهید انجام دهید متوقف کنید', 'چگونه از سپری کردن زمانی که ندارید با افرادی که دوست ندارید کارهایی را که نمی خواهید انجام دهید متوقف کنید', 12, 6, 'book', 't', '<p><em>جادوی متحول کننده زندگی در مورد ضرب و شتم نکردن </em>(2015) راهنمای قطعی شما برای آزاد کردن زمان، پول و انرژی است. این پلک ها به شما می آموزند که چگونه به چیزهایی که به شما کمک نمی کنند اهمیت دهید تا بتوانید توجه خود را بر روی بخش هایی از زندگی متمرکز کنید که باعث شادی شما می شوند. </p>', '2017-02-27 00:00:00', 3, 112, 'https://images.blinkist.io/images/books/58b21329ae485a00045cfcee/1_1/470.jpg', '/en/books/the-life-changing-magic-of-not-giving-a-f-star-ck-en/purchase', 'جادوی-متحول-کننده-زندگی-نه-دادن-به-فک', '2023-01-26 19:38:01.134914', '2023-01-26 19:38:01.134914', NULL, 'The Life-Changing Magic of Not Giving a F*ck');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (473, 'آتش.', 'روش‌های سریع، ارزان، محدود و شیک چگونه نوآوری را شعله‌ور می‌کنند', 'روش‌های سریع، ارزان، محدود و شیک چگونه نوآوری را شعله‌ور می‌کنند', 12, 5, 'book', 't', '<p>این کتاب (2014) روش <em>F.I.R.E.</em> برای شروع نوآوری را تشریح می کند، فرآیندی تضمین شده که شما و تیمتان را با ساده کردن منابع و خلاقیت تحریک می کند. در هسته خود، F.I.R.E. در مورد تعیین محدودیت‌ها است تا بتوانید نتایج بسیار بیشتری ایجاد کنید.</p>', '2016-04-19 00:00:00', 4, 33, 'https://images.blinkist.io/images/books/5713b1825236f20007c16f6c/1_1/470.jpg', '/en/books/fire-en/purchase', 'آتش.', '2023-01-26 19:38:06.07285', '2023-01-26 19:38:06.07285', NULL, 'F.I.R.E.');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (474, 'آشوب', 'ساختن یک علم جدید', 'ساختن یک علم جدید', 22, 9, 'book', 't', '<p><em>آشوب </em>(1987) به جدیدترین انقلاب نظری در فیزیک می پردازد: نظریه آشوب. در دهه 1970، دانشمندان شروع به کشف کردند که جهان آنطور که فیزیک کلاسیک نشان می‌دهد، رفتار منظمی ندارد. از آب و هوا گرفته تا جمعیت حیوانات گرفته تا ضربان قلب ما - بی نظمی ها، بی نظمی ها و هرج و مرج جهان ما را فرا گرفته است. و با این حال، به نظر می رسد نظم عجیبی در هرج و مرج زندگی وجود دارد. <em>آشوب</em> تاریخچه این علم جدید را بررسی می‌کند، یافته‌های شگفت‌انگیز آن را آشکار می‌کند، و در مورد مفاهیم آن فکر می‌کند.</p>', '2021-09-19 00:00:00', 5, 238, 'https://images.blinkist.io/images/books/6144495a6cee070007c18416/1_1/470.jpg', '/en/books/chaos-en/purchase', 'آشوب', '2023-01-26 19:38:09.887453', '2023-01-26 19:38:09.887453', NULL, 'Chaos');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (475, 'کسب و کار خود را به روشی درست بسازید', 'موفقیت پایدار برای کارآفرین خلاق', 'موفقیت پایدار برای کارآفرین خلاق', 18, 8, 'book', 't', '<p><em>ایجاد کسب و کار شما به روش درست مغز</em> (2014) با تمرکز بر نقاط قوت نیمکره راست مغز، ترجمه ای عملی از اصول کارآفرینی به زبانی ارائه می دهد که خلاقان به راحتی می توانند آن را درک کنند. مانند خلاقیت، احساس و تجسم.</p>', '2015-04-28 00:00:00', 4, 21, 'https://images.blinkist.io/images/books/553f5ee16136310007240000/1_1/470.jpg', '/en/books/building-your-business-the-right-brain-way-en/purchase', 'کسب-و-کار-خود-را-به-روشی-درست-بسازید', '2023-01-26 19:38:14.78969', '2023-01-26 19:38:14.78969', NULL, 'Building Your Business the Right-Brain Way');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (476, 'مدیریت خود', 'رمز موفقیت', 'رمز موفقیت', 5, 2, 'book', 't', '<p><em>Managing Oneself</em>(1999) ابتدا در <em>Harvard Business Review</em> منتشر شد. این راهنمای شناسایی نقاط قوت و ضعف شما، درک نحوه عملکرد و شناخت ارزش‌هایتان است. با انجام این کار، می توانید خود را از یک کارگر معمولی به یک مجری برجسته تبدیل کنید.</p>', '2022-12-01 00:00:00', 4, 348, 'https://images.blinkist.io/images/books/6380a7d9ba31850008d6c4a4/1_1/470.jpg', '/en/books/managing-oneself-en/purchase', 'مدیریت-خود', '2023-01-26 19:38:20.321014', '2023-01-26 19:38:20.321014', NULL, 'Managing Oneself');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (477, 'در حال چرخش به دور گلوله موی غول پیکر', 'راهنمای احمق شرکتی برای زنده ماندن با گریس', 'راهنمای احمق شرکتی برای زنده ماندن با گریس', 12, 5, 'book', 't', '<p><em>Orbiting the Giant Hairball</em> (1996) راهنمایی برای زنده ماندن در یک شرکت و در عین حال حفظ خلاقیت شما است. این پلک‌ها توضیح می‌دهند که چگونه می‌توان از گرداب تاریک و خفه‌کننده خلاقیت بوروکراسی شرکتی با ایجاد تعادل بین محدودیت‌های شرکت و خلاقیت شخصی فرار کرد.</p>', '2016-09-27 00:00:00', 4, 13, 'https://images.blinkist.io/images/books/57e6b9a7afd7bf0003b704f7/1_1/470.jpg', '/en/books/orbiting-the-giant-hairball-en/purchase', 'در-حال-چرخش-به-دور-گلوله-موی-غول-پیکر', '2023-01-26 19:38:24.930837', '2023-01-26 19:38:24.930837', NULL, 'Orbiting the Giant Hairball');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (478, 'SuperCorp', 'چگونه شرکت های پیشتاز نوآوری، سود، رشد و خیر اجتماعی ایجاد می کنند', 'چگونه شرکت های پیشتاز نوآوری، سود، رشد و خیر اجتماعی ایجاد می کنند', 14, 6, 'book', 't', '<p><em>SuperCorp</em> (2009) مقدمه ای بر نوع جدیدی از تجارت است: شرکت پیشتاز. دریابید که چگونه این شرکت‌ها می‌توانند در عین حال که نیازهای اجتماعی را برآورده می‌کنند و به‌عنوان نیروهای خیر در جوامع خود عمل می‌کنند، سود سالم به دست آورند.</p>', '2017-11-09 00:00:00', 4, 16, 'https://images.blinkist.io/images/books/5a00d872b238e100067eaf38/1_1/470.jpg', '/en/books/supercorp-en/purchase', 'SuperCorp', '2023-01-26 19:38:30.052127', '2023-01-26 19:38:30.052127', NULL, 'SuperCorp');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (479, 'رقم زدن', 'کاوشی از ارتباطات شگفت انگیز بین شخصیت های تاریخی', 'کاوشی از ارتباطات شگفت انگیز بین شخصیت های تاریخی', 23, 8, 'book', 't', '<p><em>Figuring </em>(2019) شبکه پیچیده‌ای را ردیابی می‌کند که چهره‌های مهم تاریخ بشر را به هم متصل می‌کند، از شاعر آلمانی یوهان ولفگانگ فون گوته و مخترع نیکولا تسلا تا اولین ستاره‌شناس زن آمریکایی ماریا میچل و شاعر رالف والدو امرسون. این پلک‌ها نقاشی‌های این زندگی‌های متفاوت را نشان می‌دهند، تأثیری را که بر روند تاریخ گذاشته‌اند را ردیابی می‌کنند، و نیروی محرکه پنهانی را که همه آنها را متحد می‌کند، آشکار می‌کند.</p>', '2020-02-06 00:00:00', 4, 61, 'https://images.blinkist.io/images/books/5e3a81c26cee07000682afed/1_1/470.jpg', '/en/books/figuring-en/purchase', 'رقم-زدن', '2023-01-26 19:38:35.653256', '2023-01-26 19:38:35.653256', NULL, 'Figuring');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (480, 'کتابی برای رواقیون جدید', 'چگونه در جهانی خارج از کنترل شما پیشرفت کنیم؟', 'چگونه در جهانی خارج از کنترل شما پیشرفت کنیم؟', 23, 8, 'book', 't', '<p><em>دستنامه ای برای رواقیون جدید </em>(2019) راهنمای گام به گام برای درک و تمرین فلسفه رواقی گری است. شما یک مرور کلی مفید و همچنین تمرین های توصیه شده برای شروع و تبدیل شدن به تدریج به یک دانش آموز پیشرفته فلسفه رایج خواهید یافت. </p>', '2020-08-31 00:00:00', 5, 590, 'https://images.blinkist.io/images/books/5f47d8d36cee070006d18d79/1_1/470.jpg', '/en/books/a-handbook-for-new-stoics-en/purchase', 'کتابی-برای-رواقیون-جدید', '2023-01-26 19:38:40.526231', '2023-01-26 19:38:40.526231', NULL, 'A Handbook for New Stoics');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (481, 'سازندگان', 'انقلاب صنعتی جدید', 'انقلاب صنعتی جدید', 12, 5, 'book', 't', '<p><em>Makers</em> (2012) تغییرات بنیادینی را که در دنیای تولید در حال وقوع است، که توسط اینترنت و فناوری‌های تولید دیجیتال امکان‌پذیر شده است، تشریح می‌کند و پیامدهای آن را برای تجارت و جامعه بررسی می‌کند.</p>', '2015-05-15 00:00:00', 4, 11, 'https://images.blinkist.io/images/books/55512d976332630007e40000/1_1/470.jpg', '/en/books/makers-en/purchase', 'سازندگان', '2023-01-26 19:38:44.305682', '2023-01-26 19:38:44.305682', NULL, 'Makers');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (482, 'اقتصاد کاذب', 'تاریخ اقتصادی شگفت انگیز جهان', 'تاریخ اقتصادی شگفت انگیز جهان', 16, 7, 'book', 't', '<p><em>اقتصاد کاذب</em> (2009) دیدگاه جدیدی در مورد اینکه چگونه و چرا برخی از کشورهای جهان به نیروگاه های اقتصادی تبدیل شده اند و برخی دیگر به فاجعه مالی ختم شده اند ارائه می دهد. خواهید دید که سرنوشت ملت ها را دستبند نمی کند. بلکه موفقیت یا شکست اقتصادی آنها بر اساس انتخاب هایی است که انجام می دهند.</p>', '2016-09-16 00:00:00', 4, 121, 'https://images.blinkist.io/images/books/57da983de4ac3900031ce2e4/1_1/470.jpg', '/en/books/false-economy-en/purchase', 'اقتصاد-کاذب', '2023-01-26 19:38:49.382973', '2023-01-26 19:38:49.382973', NULL, 'False Economy');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (483, 'کتابچه راهنمای مشاور', 'راهنمای عملی برای ارائه خدمات با ارزش و متمایز در یک بازار رقابتی', 'راهنمای عملی برای ارائه خدمات با ارزش و متمایز در یک بازار رقابتی', 22, 8, 'book', 't', '<p><em>راهنمای مشاور </em>(2015) یک راهنمای میدانی ضروری برای دنیای مشاوره است. مملو از نکات برتر، مثال‌های روشنگر و توصیه‌های عملی، توضیحی عالی برای مشاوران گذشته، حال و آینده، و همچنین هر کسی که مشتاق است برخی از ترفندهای مشاوره را برای افزایش عملکرد خود در صنایع مجاور انتخاب کند.</p>
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (484, 'پسران و جنسیت', 'مردان جوان در ارتباط، عشق، پورن، رضایت، و پیمایش مردانگی جدید', 'مردان جوان در ارتباط، عشق، پورن، رضایت، و پیمایش مردانگی جدید', 26, 8, 'book', 't', '<p>در <em>Boys & Sex </em> (2020)، روزنامه‌نگار مشهور پگی اورنشتاین از مردان جوان درباره زندگی جنسی آنها می‌پرسد - و پاسخ‌های بدون سانسور را دریافت می‌کند. Orenstein با تکیه بر دو سال مصاحبه با مردان جوان، دانشگاهیان، روانشناسان و مربیان جنسی، دیدگاهی بدون فیلتر و در عین حال آگاهانه در مورد رابطه مردان جوان با رابطه جنسی، از لذت بخش تا مشکل ساز ارائه می دهد.</p>', '2020-03-12 00:00:00', 4, 90, 'https://images.blinkist.io/images/books/5e68d02b6cee070006d37ad9/1_1/470.jpg', '/en/books/boys-and-sex-en/purchase', 'پسران-و-جنسیت', '2023-01-26 19:38:59.280628', '2023-01-26 19:38:59.280628', NULL, 'Boys &amp; Sex');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (485, 'ذهنی برای اعداد', 'چگونه در ریاضیات و علوم اکسل کنیم (حتی اگر جبر را پرت کرده باشید)', 'چگونه در ریاضیات و علوم اکسل کنیم (حتی اگر جبر را پرت کرده باشید)', 18, 8, 'book', 't', '<p><em>ذهنی برای اعداد</em> بینشی در مورد نحوه دریافت و پردازش اطلاعات توسط مغز ما ارائه می دهد. راهبردهایی را بیان می‌کند که می‌تواند به شما کمک کند تا به طور مؤثرتری یاد بگیرید، مخصوصاً وقتی صحبت از ریاضیات و علوم می‌شود. حتی اگر مفاهیم ریاضی یا علمی به طور طبیعی به شما نمی رسد، می توانید با فداکاری و پشتکار مناسب بر آنها مسلط شوید - و این کتاب به شما یاد می دهد که چگونه.</p>', '2015-01-23 00:00:00', 4, 147, 'https://images.blinkist.io/images/books/54be8273623238000a000000/1_1/470.jpg', '/en/books/a-mind-for-numbers-en/purchase', 'ذهنی-برای-اعداد', '2023-01-26 19:39:04.381744', '2023-01-26 19:39:04.381744', NULL, 'A Mind for Numbers');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (486, 'اکسیژن', 'مولکولی که جهان را ساخت', 'مولکولی که جهان را ساخت', 16, 8, 'book', 't', '<p><em>اکسیژن</em> (2002) راهنمای عنصری است که آنقدر برای وجود ما ضروری است که گاهی اوقات فراموش می کنیم حتی وجود دارد. این پلک‌ها توضیح می‌دهند که چگونه اکسیژن حیات روی زمین را قادر می‌سازد و آن را تقویت می‌کند و در عین حال آن را تهدید می‌کند.</p>', '2016-03-21 00:00:00', 4, 23, 'https://images.blinkist.io/images/books/56eeae56dbb9a40007000000/1_1/470.jpg', '/en/books/oxygen-en/purchase', 'اکسیژن', '2023-01-26 19:39:09.366624', '2023-01-26 19:39:09.366624', NULL, 'Oxygen');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (487, 'شادترین کودک در بلوک', 'روشی جدید برای آرام کردن گریه و کمک به نوزاد تازه متولد شده خود برای طولانی تر خوابیدن', 'روشی جدید برای آرام کردن گریه و کمک به نوزاد تازه متولد شده خود برای طولانی تر خوابیدن', 10, 5, 'book', 't', '<p><em>خوشحال‌ترین نوزاد در بلوک</em> (2002) با یکی از بزرگترین مشکلاتی که والدین جدید با آن مواجه خواهند شد، مقابله می‌کند: ناله‌ها و گریه‌های مداوم نوزادشان. این پلک‌ها توضیح می‌دهند که چرا بقای کودک شما به پاسخ شما به گریه‌های او بستگی دارد، و چگونه می‌توانید با تحریک رفلکس آرامش، به کودک خود احساس آرامش و امنیت کنید.</p>', '2016-06-29 00:00:00', 4, 66, 'https://images.blinkist.io/images/books/576ba534e0dd250003d615a6/1_1/470.jpg', '/en/books/the-happiest-baby-on-the-block-en/purchase', 'شادترین-کودک-در-بلوک', '2023-01-26 19:39:14.420688', '2023-01-26 19:39:14.420688', NULL, 'The Happiest Baby on the Block');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (490, '3 راز برای سرمایه گذاری موثر در زمان', 'با استرس کمتر به موفقیت بیشتری دست پیدا کنید', 'با استرس کمتر به موفقیت بیشتری دست پیدا کنید', 14, 7, 'book', 't', '<p><em>3 راز برای سرمایه گذاری در زمان موثر</em> (2013) یک راهنمای عملی برای زندگی با طراحی به جای انگیزه است. این برنامه استراتژی‌های گام به گام برای برنامه‌ریزی روزهایتان در مورد تعهداتی که واقعاً برای شما مهم هستند، تنظیم روال‌های مؤثر و یافتن افرادی که به شما کمک می‌کنند در مسیر درست بمانید، ارائه می‌کند. همچنین اهمیت برخورد با توشه‌های احساسی مانند گناه و شرم را نشان می‌دهد، که می‌تواند حتی بهترین برنامه‌ها را از مسیر خارج کند.</p>', '2021-01-20 00:00:00', 4, 275, 'https://images.blinkist.io/images/books/60016e376cee070006e82068/1_1/470.jpg', '/en/books/the-3-secrets-to-effective-time-investment-en/purchase', '3-راز-برای-سرمایه-گذاری-موثر-در-زمان', '2023-01-26 19:39:31.123298', '2023-01-26 19:39:31.123298', NULL, 'The 3 Secrets to Effective Time Investment');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (491, 'شرکت محتوا', 'چگونه کارآفرینان از محتوا برای ایجاد مخاطبان عظیم و ایجاد کسب و کارهای کاملاً موفق استفاده می کنند', 'چگونه کارآفرینان از محتوا برای ایجاد مخاطبان عظیم و ایجاد کسب و کارهای کاملاً موفق استفاده می کنند', 15, 7, 'book', 't', '<p><em>Content, Inc. </em>(2015) راهنمای مفید و کاربردی در مورد نحوه استفاده از مدیریت محتوا برای بازاریابی کسب و کار، جذب مخاطب و ارائه ایده های خود به جهان است. این پلک ها مملو از نکات و ترفندهایی است که به شما کمک می کند آن مخاطب را به مشترکین وفادار تبدیل کنید و به شما امکان می دهد برند خود را متنوع کنید و به خط مقدم صنعت خود بروید.</p>', '2016-10-10 00:00:00', 5, 56, 'https://images.blinkist.io/images/books/57f8ad5cdbad80000386b30d/1_1/470.jpg', '/en/books/content-inc-en/purchase', 'شرکت-محتوا', '2023-01-26 19:39:36.172652', '2023-01-26 19:39:36.172652', NULL, 'Content Inc.');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (492, 'فروش به شرکت های بزرگ', 'بیاموزید که چگونه سر و صدا را کاهش دهید و مشتریان بزرگتری را به دست آورید.', 'بیاموزید که چگونه سر و صدا را کاهش دهید و مشتریان بزرگتری را به دست آورید.', 16, 9, 'book', 'f', '<p><em>فروش به شرکت‌های بزرگ </em>(2006) به بررسی دقیق و دقیق برخورد با تصمیم‌گیرندگان شرکت می‌پردازد. از برقراری تماس اولیه تا توسعه فروش خود، این کتاب همه ابزارهایی را که برای فروش به شرکت‌های بزرگ نیاز دارید در اختیار شما قرار می‌دهد.</p>', '2015-04-01 00:00:00', 4, 20, 'https://images.blinkist.io/images/books/55189df73961320007770000/1_1/470.jpg', '/en/books/selling-to-big-companies-en/purchase', 'فروش-به-شرکت-های-بزرگ', '2023-01-26 19:39:39.729626', '2023-01-26 19:39:39.729626', NULL, 'Selling To Big Companies');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (493, 'شرط بندی روی شما', 'چگونه خود را در اولویت قرار دهید و (در نهایت) کنترل شغل خود را در دست بگیرید', 'چگونه خود را در اولویت قرار دهید و (در نهایت) کنترل شغل خود را در دست بگیرید', 23, 8, 'book', 't', '<p><em>شرط بندی روی شما </em>(2021) یک راهنمای عملی برای پیمایش در محل کار مدرن است. اگر در یک شرکت بزرگ کارمند هستید، ممکن است احساس کنید هیچ نمایندگی در زندگی کاری خود ندارید. اما با قرار دادن خود در اولویت و تغییر طرز فکرتان در مورد کار، می توانید تغییرات بزرگی در جایی که هستید ایجاد کنید. و اگر نیاز به ترک شغل خود دارید، می توانید برای فصل بعدی برنامه ریزی استراتژیک داشته باشید.</p>', '2021-08-23 00:00:00', 4, 219, 'https://images.blinkist.io/images/books/611fba2a6cee07000706030e/1_1/470.jpg', '/en/books/betting-on-you-en/purchase', 'شرط-بندی-روی-شما', '2023-01-26 19:39:44.370417', '2023-01-26 19:39:44.370417', NULL, 'Betting on You');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (494, 'مدیریت خشم برای آدمک ها', 'راهنمای یک مرحله ای شما برای مدیریت خشم', 'راهنمای یک مرحله ای شما برای مدیریت خشم', 13, 6, 'book', 't', '<p><em>مدیریت خشم برای آدمک ها</em> (2015) راهنمایی برای مقابله با عصبانیت درونی شماست. این پلک زدن ها ابزارهایی را در اختیار شما قرار می دهد که برای درک و - مهمتر از آن - تسلط بر عصبانیت خود نیاز دارید. روش‌هایی را برای از بین بردن استرس، مقابله با تحریکات و حتی متوقف کردن عصبانیت‌ها در مسیر آنها یاد خواهید گرفت.</p>', '2016-07-22 00:00:00', 4, 103, 'https://images.blinkist.io/images/books/57878390c6cd380003a5c5ca/1_1/470.jpg', '/en/books/anger-management-for-dummies-en/purchase', 'مدیریت-خشم-برای-آدمک-ها', '2023-01-26 19:39:49.09661', '2023-01-26 19:39:49.09661', NULL, 'Anger Management for Dummies');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (495, 'رهبری', 'در زمان آشفته', 'در زمان آشفته', 24, 9, 'book', 't', '<p><em>رهبری: در زمان آشفته </em>(2018) زندگی چهار تن از تحول آفرین ترین روسای جمهور تاریخ ایالات متحده را بررسی می کند: آبراهام لینکلن، تئودور روزولت، فرانکلین روزولت و لیندون جانسون. نویسنده دوریس کرنز گودوین، با نگاهی به شباهت‌ها و تفاوت‌های بین نحوه تبدیل شدن این مردان به رهبران بزرگ، بینشی در مورد چگونگی و چرایی آن‌ها در مقاطع مهم تاریخ آمریکا ارائه می‌دهد.</p>', '2018-10-26 00:00:00', 5, 73, 'https://images.blinkist.io/images/books/5bd0960a6cee0700072063fc/1_1/470.jpg', '/en/books/leadership-en/purchase', 'رهبری', '2023-01-26 19:39:54.076134', '2023-01-26 19:39:54.076134', NULL, 'Leadership');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (496, 'مختصر', 'با کمتر گفتن تأثیر بیشتری بگذارید', 'با کمتر گفتن تأثیر بیشتری بگذارید', 15, 7, 'book', 't', '<p><em>Brief </em>(2014) راهنمایی برای تأثیرگذاری و تأثیرگذاری بیشتر با گفتن کمتر است. این پلک‌ها قدرت اختصار را در عصر اطلاعات به خواننده نشان می‌دهند، موانع مختصر بودن را توضیح می‌دهند و دستورالعمل‌های مفیدی را در مورد چگونگی بهبود ارتباطات خود و در عین حال صرفه‌جویی در وقت خود و دیگران ارائه می‌دهند.</p>', '2015-08-11 00:00:00', 5, 63, 'https://images.blinkist.io/images/books/55c7c6436664360007420000/1_1/470.jpg', '/en/books/brief-en/purchase', 'مختصر', '2023-01-26 19:39:59.121041', '2023-01-26 19:39:59.121041', NULL, 'Brief');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (497, 'باز کردن', 'راهنمای ایجاد و حفظ روابط باز', 'راهنمای ایجاد و حفظ روابط باز', 23, 8, 'book', 't', '<p><em>Opening Up </em>(2008) روابط غیر تک همسری را ابهام می کند و نشان می دهد که راه های مختلفی برای ایجاد مشارکت های عاشقانه و ایجاد خانواده های جایگزین وجود دارد. با باز کردن روابط خود، افراد می توانند خواسته های پنهان را کشف کنند، سرگرمی زیادی داشته باشند و مهارت های ارتباطی و خودآگاهی خود را به طور اساسی بهبود بخشند.</p>', '2020-08-07 00:00:00', 4, 94, 'https://images.blinkist.io/images/books/5f2915376cee07000784d21a/1_1/470.jpg', '/en/books/opening-up-en/purchase', 'باز-کردن', '2023-01-26 19:40:03.869605', '2023-01-26 19:40:03.869605', NULL, 'Opening Up');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (498, 'شادتر در خانه', 'بیشتر ببوسید، بیشتر بپرید، کنترل خود را کنار بگذارید، و دیگر آزمایش‌های من در زندگی روزمره', 'بیشتر ببوسید، بیشتر بپرید، کنترل خود را کنار بگذارید، و دیگر آزمایش‌های من در زندگی روزمره', 12, 6, 'book', 't', '<p><em>Happier at Home</em>(2012) راهنمای تبدیل خانه شما به پناهگاهی است که شخصیت خانواده شما را منعکس می کند. این کتاب با کمک به شما در شناسایی نیازهای خود و خانواده‌تان، همه چیزهایی را که برای شروع تغییر خانه و زندگی خانوادگی برای بهتر شدن نیاز دارید در اختیار شما قرار می‌دهد.</p>', '2016-02-12 00:00:00', 4, 68, 'https://images.blinkist.io/images/books/56b8e9a7d119f900070000cd/1_1/470.jpg', '/en/books/happier-at-home-en/purchase', 'شادتر-در-خانه', '2023-01-26 19:40:07.347069', '2023-01-26 19:40:07.347069', NULL, 'Happier at Home');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (499, 'بدون لوگو', 'افزایش قدرت برندها', 'افزایش قدرت برندها', 16, 10, 'book', 't', '<p><em>No Logo</em> نگاهی می‌اندازد به اینکه چگونه قدرت برندها از دهه 1980 رشد کرده است و چگونه شرکت‌ها بر تصویر برند خود به جای محصولات واقعی خود تأکید کرده‌اند. <em>بدون لوگو</em> نشان می‌دهد که چگونه این استراتژی بر کارمندان در جهان صنعتی و غیر توسعه‌یافته تأثیر گذاشته است. <em>No Logo</em> همچنین خواننده را با فعالان و مبارزانی که رهبری مبارزه با شرکت‌های چندملیتی و برندهای آنها را رهبری می‌کنند، معرفی می‌کند.</p>', '2014-01-01 13:57:30.834', 4, 54, 'https://images.blinkist.io/images/books/52b89892373766000c1f0000/1_1/470.jpg', '/en/books/no-logo-en/purchase', 'بدون-لوگو', '2023-01-26 19:40:12.331365', '2023-01-26 19:40:12.331365', NULL, 'No Logo');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (500, 'جایزه رایگان داخل', 'ایده بزرگ بعدی بازاریابی', 'ایده بزرگ بعدی بازاریابی', 29, 10, 'book', 't', '<p><em>Free Prize Inside </em>(2004) پاسخ های عملی به یکی از مبرم ترین سؤالات پیش روی بازاریابان، کارآفرینان و صاحبان مشاغل امروزی ارائه می دهد: در دنیایی که مردم دیگر به تبلیغات سنتی توجه نمی کنند، چگونه آیا می توانید از میان جمعیت متمایز شوید و به مخاطبان خود دسترسی پیدا کنید؟ ست گودین نشان می‌دهد که با بهره‌گیری از قدرت نوآوری‌های کوچک، می‌توانید محصول، خدمات یا شرکت خود را آنقدر برجسته کنید که برای شکستن سر و صدای زندگی مدرن، سر و صدای کافی ایجاد کند. </p>', '2020-01-14 00:00:00', 5, 96, 'https://images.blinkist.io/images/books/5e186c4a6cee0700089b4ba9/1_1/470.jpg', '/en/books/free-prize-inside-en/purchase', 'جایزه-رایگان-داخل', '2023-01-26 19:40:17.602312', '2023-01-26 19:40:17.602312', NULL, 'Free Prize Inside');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (501, 'مجوز بد بودن', 'چگونه اقتصاد ما را فاسد کرد', 'چگونه اقتصاد ما را فاسد کرد', 27, 9, 'book', 't', '<p><em>Licence to Be Bad </em>(2019) توضیح می دهد که چگونه در 50 سال گذشته تعداد انگشت شماری از اقتصاددانان طرز تفکر ما را در مورد موضوع به شدت تغییر داده اند. ایده هایی از جمله نظریه بازی، تئوری انتخاب عمومی و سواری آزاد راه خود را به ذهن و گفتمان ما وارد کرده اند و ظاهراً به ما اجازه می دهند که رفتار بدی داشته باشیم.</p>', '2020-12-12 00:00:00', 4, 89, 'https://images.blinkist.io/images/books/5fca017a6cee07000677d0f6/1_1/470.jpg', '/en/books/licence-to-be-bad-en/purchase', 'مجوز-بد-بودن', '2023-01-26 19:40:22.639873', '2023-01-26 19:40:22.639873', NULL, 'Licence to be Bad');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (502, 'عناصر اسکرام', 'راهنمای تمام جنبه های اسکرام', 'راهنمای تمام جنبه های اسکرام', 16, 6, 'book', 't', '<p><em>Elements of Scrum</em> (2011) توضیح می‌دهد که چگونه فرآیندهای توسعه نرم‌افزار منسوخ شده شرکت‌ها را در بازار همیشه در حال تغییر عقب نگه می‌دارند. تیم های موفق امروزی باید چابک و انعطاف پذیر باشند. و بهترین شرکت ها این کار را با اتخاذ روشی به نام <em>scrum</em> انجام می دهند. این کتاب همه چیزهایی را که برای شروع یک فرآیند مبتنی بر اسکرام در سازمان خود نیاز دارید، به شما می دهد.</p>', '2015-12-30 00:00:00', 4, 88, 'https://images.blinkist.io/images/books/5681b4aa704a880007000041/1_1/470.jpg', '/en/books/the-elements-of-scrum-en/purchase', 'عناصر-اسکرام', '2023-01-26 19:40:27.491676', '2023-01-26 19:40:27.491676', NULL, 'The Elements of Scrum');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (503, 'قدرت یکی بیشتر', 'راهنمای نهایی برای خوشبختی و موفقیت', 'راهنمای نهایی برای خوشبختی و موفقیت', 7, 5, 'book', 't', '<p><em>قدرت یکی دیگر</em> (2022) از این ایده پیروی می کند که انجام "یکی دیگر" در هر شرایطی می تواند برای شما عظمت به ارمغان بیاورد و فرصت های بیشتری را باز کند.</p>', '2023-01-23 00:00:00', NULL, 5, 'https://images.blinkist.io/images/books/63c7d2f0ca3d9100087f4463/1_1/470.jpg', '/en/books/the-power-of-one-more-en/purchase', 'قدرت-یکی-بیشتر', '2023-01-26 19:40:32.562492', '2023-01-26 19:40:32.562492', NULL, 'The Power of One More');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (504, 'فرازمینی', 'اولین نشانه حیات هوشمند فراتر از زمین', 'اولین نشانه حیات هوشمند فراتر از زمین', 25, 7, 'book', 't', '<p><em>فراز زمینی </em>(2021) بررسی "Oumuamua"، اولین جرم بین ستاره‌ای است که تاکنون کشف شده است. این بررسی اجمالی تحریک آمیز استدلال می کند که این شی عجیب می تواند تکه ای از فناوری بیگانه باشد. </p>', '2021-03-25 00:00:00', 5, 122, 'https://images.blinkist.io/images/books/6059c74c6cee0700073c3f96/1_1/470.jpg', '/en/books/extraterrestrial-en/purchase', 'فرازمینی', '2023-01-26 19:40:37.682749', '2023-01-26 19:40:37.682749', NULL, 'Extraterrestrial');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (505, 'چرا استارت آپ ها شکست می خورند', 'نقشه راه جدید برای موفقیت کارآفرینی', 'نقشه راه جدید برای موفقیت کارآفرینی', 24, 8, 'book', 't', '<p><em>چرا استارت‌آپ‌ها شکست می‌خورند </em>(2021) شش دلیل اصلی شکست استارت‌آپ‌ها را شناسایی می‌کند. این چارچوبی برای تجزیه و تحلیل شکست استارت‌آپ ارائه می‌کند که چگونگی کارکرد جنبه‌های مختلف یک کسب‌وکار را با هم بررسی می‌کند. کارآفرینان می توانند از این چارچوب برای ارزیابی سلامت سرمایه گذاری های خود استفاده کنند. </p>', '2021-10-20 00:00:00', 5, 205, 'https://images.blinkist.io/images/books/616814026cee0700089d6a92/1_1/470.jpg', '/en/books/why-startups-fail-en/purchase', 'چرا-استارت-آپ-ها-شکست-می-خورند', '2023-01-26 19:40:42.143103', '2023-01-26 19:40:42.143103', NULL, 'Why Startups Fail');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (506, 'باز کن', 'یک اتوبیوگرافی', 'یک اتوبیوگرافی', 20, 9, 'book', 't', '<p><em>Open</em> (2009) گزارشی آشکار از زندگی پرتلاطم یکی از بهترین تنیس بازان تاریخ آمریکا است. بیش از هر چیز دیگری، این داستان نبرد آغاسی برای تعادل و درک خود است، همه اینها در حالی که با جریان دائمی عوارض ناشی از شهرت و بررسی عمومی سر و کار دارد.</p>', '2017-10-31 00:00:00', 5, 39, 'https://images.blinkist.io/images/books/59f7bd60b238e10006f6080a/1_1/470.jpg', '/en/books/open-en/purchase', 'باز-کن', '2023-01-26 19:40:46.882945', '2023-01-26 19:40:46.882945', NULL, 'Open');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (507, 'تبدیل شدن به یک مربی اجرایی استثنایی', 'از دانش، تجربه و شهود خود برای کمک به رهبران اکسل استفاده کنید', 'از دانش، تجربه و شهود خود برای کمک به رهبران اکسل استفاده کنید', 13, 7, 'book', 'f', '<p><em> تبدیل شدن به یک مربی اجرایی استثنایی</em> (2012) با هدف تعمیق درک شما از معنای ایفای نقش مربیگری است. این چشمک‌ها عناصر اصلی روابط مربی-مشتری را برای ارائه رویکردی انعطاف‌پذیر و غنی به کوچینگ اجرایی نشان می‌دهند.</p>', '2015-10-26 00:00:00', 4, 32, 'https://images.blinkist.io/images/books/562e12ee38643100070a0000/1_1/470.jpg', '/en/books/becoming-an-exceptional-executive-coach-en/purchase', 'تبدیل-شدن-به-یک-مربی-اجرایی-استثنایی', '2023-01-26 19:40:51.839453', '2023-01-26 19:40:51.839453', NULL, 'Becoming an Exceptional Executive Coach');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (508, 'چگونه نمرد', 'غذاهایی را که از نظر علمی برای پیشگیری و معکوس کردن بیماری ها اثبات شده است، کشف کنید', 'غذاهایی را که از نظر علمی برای پیشگیری و معکوس کردن بیماری ها اثبات شده است، کشف کنید', 23, 9, 'book', 't', '<p><em>چگونه نمی‌میریم</em> (2015) توضیح می‌دهد که چگونه یک رژیم غذایی گیاهی می‌تواند عمر شما را افزایش دهد و در عین حال کیفیت زندگی شما را تغییر دهد. این پلک‌ها اطلاعات تغذیه‌ای برای تقویت سلامتی و توصیه‌های عملی رژیمی ارائه می‌دهند که از پزشکتان دریافت نمی‌کنید.</p>', '2017-07-13 00:00:00', 5, 297, 'https://images.blinkist.io/images/books/596111c5b238e10006ad56cc/1_1/470.jpg', '/en/books/how-not-to-die-en/purchase', 'چگونه-نمرد', '2023-01-26 19:40:56.746259', '2023-01-26 19:40:56.746259', NULL, 'How Not to Die');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (509, 'سعادت تعقیب', 'جستجویی را بیابید که هدف را به زندگی شما می آورد', 'جستجویی را بیابید که هدف را به زندگی شما می آورد', 18, 8, 'book', 't', '<p><em>خوشبختی از تعقیب</em> در مورد شروع تلاش برای پر کردن زندگی خود با احساس هدف است. این توضیح می دهد که چگونه روند یافتن و دنبال کردن یک سفر شخصی می تواند عمیقاً پاداش دهنده و تأیید کننده زندگی باشد. خواننده می تواند انتظار داشته باشد که با بسیاری از مطالعات موردی جالب در مورد افرادی مواجه شود که علایق خود را دنبال کرده اند - از یک جوان محیط زیست که یک سال را در یک درخت تاسمانی زندگی می کرد تا یک زن اوکلاهاما که خود را وقف پختن یک وعده غذایی از همه کشورهای جهان کرد. </p>', '2014-12-24 00:00:00', 5, 33, 'https://images.blinkist.io/images/books/548a16e733633700096e0000/1_1/470.jpg', '/en/books/the-happiness-of-pursuit-en/purchase', 'سعادت-تعقیب', '2023-01-26 19:41:00.481606', '2023-01-26 19:41:00.481606', NULL, 'The Happiness of Pursuit');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (510, 'بازگشت سرمایه در بازاریابی', 'رویکرد تفکر طراحی برای اندازه‌گیری، اثبات و بهبود ارزش بازاریابی', 'رویکرد تفکر طراحی برای اندازه‌گیری، اثبات و بهبود ارزش بازاریابی', 11, 6, 'book', 't', '<p><em>ROI در بازاریابی </em>(2020) چارچوبی را برای برنامه ریزی و اجرای ابتکارات بازاریابی موثر که نتایج مالی خوبی ارائه می دهد، ارائه می دهد. با استفاده از اصول تفکر طراحی، <em>ROI در بازاریابی </em>نحوه ایجاد زنجیره‌های تأثیرگذاری در کمپین‌های بازاریابی و نظارت بر اثربخشی آن‌ها برای اطمینان از بازدهی مثبت سرمایه‌گذاری را بررسی می‌کند.</p>', '2021-02-04 00:00:00', 4, 53, 'https://images.blinkist.io/images/books/6014114b6cee070008ada76e/1_1/470.jpg', '/en/books/roi-in-marketing-en/purchase', 'بازگشت-سرمایه-در-بازاریابی', '2023-01-26 19:41:06.591721', '2023-01-26 19:41:06.591721', NULL, 'ROI in Marketing');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (511, 'فرزندپروری ساده', 'استفاده از قدرت فوق‌العاده کمتر برای تربیت کودکان آرام‌تر، شادتر و ایمن‌تر', 'استفاده از قدرت فوق‌العاده کمتر برای تربیت کودکان آرام‌تر، شادتر و ایمن‌تر', 13, 5, 'book', 't', '<p><em>فرزندپروری ساده </em>(2009) به والدین می آموزد که چگونه سطح استرس را که فرزندانشان تجربه می کنند کاهش دهند. والدین می توانند این کار را با کنترل محیط فرزندان خود، محدود کردن دسترسی آنها به دنیای بزرگسالان و ارائه یک برنامه منظم و ریتمیک برای آنها انجام دهند. انجام این مراحل ساده زندگی خانوادگی را برای همه افراد درگیر بهبود می بخشد. </p>', '2017-11-08 00:00:00', 4, 109, 'https://images.blinkist.io/images/books/5a00d4f3b238e100073f3a27/1_1/470.jpg', '/en/books/simplicity-parenting-en/purchase', 'فرزندپروری-ساده', '2023-01-26 19:41:11.804876', '2023-01-26 19:41:11.804876', NULL, 'Simplicity Parenting');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (512, 'راهنمای پدر ثروتمند برای سرمایه گذاری', 'آنچه ثروتمندان روی آن سرمایه گذاری می کنند، که طبقه فقیر و متوسط ​​انجام نمی دهند!', 'آنچه ثروتمندان روی آن سرمایه گذاری می کنند، که طبقه فقیر و متوسط ​​انجام نمی دهند!', 18, 8, 'book', 't', 'رابرت کیوساکی در<em> راهنمای پدر ثروتمند برای سرمایه گذاری</em>g (1998)، چگونگی سرمایه گذاری افراد ثروتمند را بیان می کند. او با استفاده از توصیه "پدر ثروتمند" خود، دوست خانوادگی که ثروت زیادی جمع آوری کرده است، نشان می دهد که افراد ثروتمند اساساً تصمیمات متفاوتی با افراد فقیر و طبقه متوسط ​​می گیرند. کیوساکی توضیح می‌دهد که چگونه می‌توانید روش تصمیم‌گیری مالی را تغییر دهید و راه رسیدن به ثروت را بیابید.</p>', '2018-08-13 00:00:00', 4, 528, 'https://images.blinkist.io/images/books/5b70ac9fb238e10007ba456e/1_1/470.jpg', '/en/books/rich-dads-guide-to-investing-en/purchase', 'راهنمای-پدر-ثروتمند-برای-سرمایه-گذاری', '2023-01-26 19:41:16.29166', '2023-01-26 19:41:16.29166', NULL, 'Rich Dad’s Guide to Investing');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (513, 'فراتر از اندازه گیری', 'تاثیر بزرگ تغییرات کوچک', 'تاثیر بزرگ تغییرات کوچک', 11, 5, 'book', 't', '<p><em>Beyond Measure</em>(2015) نشان می دهد که تبدیل یک شرکت در حال مبارزه به یک شرکت پر رونق، یک موضوع ساده از ایجاد تغییرات کوچک سیستمی است که افراد را برای صحبت، همکاری و اشتراک گذاری توانمند می کند. کشف کنید که می توانید از کنترل شرکت خود توسط یک مدیر عامل پرکار جلوگیری کنید و آن را به یک نیروگاه خلاقانه تبدیل کنید که در آن ایده ها می توانند شکوفا شوند.</p>', '2016-07-06 00:00:00', 5, 21, 'https://images.blinkist.io/images/books/57753eef3588860003e8240e/1_1/470.jpg', '/en/books/beyond-measure-en/purchase', 'فراتر-از-اندازه-گیری', '2023-01-26 19:41:21.586968', '2023-01-26 19:41:21.586968', NULL, 'Beyond Measure');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (514, 'کشتی را بچرخانید', 'داستان واقعی تبدیل پیروان به رهبر', 'داستان واقعی تبدیل پیروان به رهبر', 12, 5, 'book', 't', '<p><em>Turn the Ship Around </em>داستانی را نشان می دهد که چگونه یک کاپیتان نیروی دریایی ایالات متحده توانست یک خدمه ناراضی زیردریایی را به یک تیم قابل احترام و قابل احترام تبدیل کند. اما چگونه این کار را انجام داد؟ با تغییر طرز تفکر ما درباره رهبری، این داستان به شما نشان می دهد که در درون، همه ما قدرت رهبری شدن را داریم.</p>', '2015-01-05 00:00:00', 4, 149, 'https://images.blinkist.io/images/books/54a986006233320009000000/1_1/470.jpg', '/en/books/turn-the-ship-around-en/purchase', 'کشتی-را-بچرخانید', '2023-01-26 19:41:26.077641', '2023-01-26 19:41:26.077641', NULL, 'Turn the Ship Around');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (515, 'فرار بزرگ', 'سلامتی، ثروت و منشأ نابرابری', 'سلامتی، ثروت و منشأ نابرابری', 17, 8, 'book', 't', '<p><em>فرار بزرگ</em> (2013) به وضوح توضیح می دهد که بشریت بهتر از همیشه پیش می رود. اما همه از پیشرفت های تکنولوژیکی و سیاسی که شکوفایی ما را ممکن ساخته است، بهره مند نشده اند. این کتاب با بررسی نابرابری تاریخی و مدرن، توصیه‌های محکمی در مورد چگونگی کم کردن این شکاف ارائه می‌کند.</p>', '2016-03-17 00:00:00', 4, 23, 'https://images.blinkist.io/images/books/56e6f1289854a50007000141/1_1/470.jpg', '/en/books/the-great-escape-en/purchase', 'فرار-بزرگ', '2023-01-26 19:41:31.301076', '2023-01-26 19:41:31.301076', NULL, 'The Great Escape');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (516, 'زندگی در کرشندو', 'مهمترین کار شما همیشه پیش روی شماست', 'مهمترین کار شما همیشه پیش روی شماست', 18, 4, 'book', 't', '<p><em>Live Life in Crescendo </em>(2022) به طور حکایتی به بسیاری از سوالات در مورد زندگی پاسخ می دهد: مهم نیست چند سال دارید، چگونه بهترین زندگی خود را سپری می کنید؟ چگونه به چالش های تغییر دهنده زندگی پاسخ می دهید؟ اگر دچار بحران میانسالی شوید چه می کنید؟ این نشان می‌دهد که چگونه می‌توان <em>زندگی را</em> <em>در اوج گرفت</em> - به طور پیوسته در مشارکت، یادگیری و تأثیر افزایش می‌یابد.</p>', '2022-10-13 00:00:00', 5, 108, 'https://images.blinkist.io/images/books/634540a26cee0700086c40f8/1_1/470.jpg', '/en/books/live-life-in-crescendo-en/purchase', 'زندگی-در-کرشندو', '2023-01-26 19:41:36.155625', '2023-01-26 19:41:36.155625', NULL, 'Live Life in Crescendo');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (517, 'اثر سیلو', 'خطر تخصص و وعده شکستن موانع', 'خطر تخصص و وعده شکستن موانع', 17, 7, 'book', 't', '<p><em>اثر سیلو</em> (2015) خطرات حفظ بخش‌های تجاری یا سیستم‌های اجتماعی را در «سیلوها» شناسایی می‌کند، که بین آن‌ها ایده‌ها می‌میرند و ارتباطات به هم می‌ریزد. چنین سازمانی با وجود معایب بسیار در دنیای تجارت امروزی معمول است. این پلک ها به شما نشان می دهند که چگونه سازمان خود را بازسازی کنید تا سیلوها را برای همیشه خراب کنید.</p>', '2015-11-17 00:00:00', 4, 22, 'https://images.blinkist.io/images/books/5649f9a166343100072b0000/1_1/470.jpg', '/en/books/the-silo-effect-en/purchase', 'اثر-سیلو', '2023-01-26 19:41:41.009624', '2023-01-26 19:41:41.009624', NULL, 'The Silo Effect');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (518, 'حضور', 'جسورترین خود را به بزرگترین چالش های خود برسانید', 'جسورترین خود را به بزرگترین چالش های خود برسانید', 23, 8, 'book', 't', '<p><em>Presence </em>(2016) نگاهی ارزشمند به رابطه بین ذهن و بدن ما دارد و اینکه چگونه می تواند بر روانشناسی و توانایی ما برای برقراری ارتباط موثر تأثیر بگذارد. نویسنده امی کادی با بررسی زبان بدن و حالت‌های بدن، نکات ساده‌ای را نشان می‌دهد که می‌تواند زندگی افراد خجالتی و خودآگاه را به نیروگاه‌هایی با اعتماد به نفس تبدیل کند. </p>', '2019-12-04 00:00:00', 4, 190, 'https://images.blinkist.io/images/books/5de13acf6cee070008b71dcb/1_1/470.jpg', '/en/books/presence-en/purchase', 'حضور', '2023-01-26 19:41:46.896203', '2023-01-26 19:41:46.896203', NULL, 'Presence');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (519, 'کتاب بله', 'هنر مذاکره بهتر', 'هنر مذاکره بهتر', 14, 6, 'book', 't', '<p><em>کتاب بله</em> (2013) راهنمای شما برای مذاکره است. این پلک‌ها توضیح می‌دهند که مذاکره مدرن چگونه به همکاری بستگی دارد و توصیه‌های عملی ارائه می‌دهد که شما را در پیشبرد اهدافتان در هر مرحله از فرآیند چانه‌زنی نگه می‌دارد.</p>', '2017-07-12 00:00:00', 4, 32, 'https://images.blinkist.io/images/books/596169cab238e10006ad5732/1_1/470.jpg', '/en/books/the-yes-book-en/purchase', 'کتاب-بله', '2023-01-26 19:41:51.905635', '2023-01-26 19:41:51.905635', NULL, 'The Yes Book');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (522, 'شرکت همتایان', 'چگونه مردم و پلتفرم ها اقتصاد مشارکتی را اختراع می کنند و سرمایه داری را دوباره اختراع می کنند', 'چگونه مردم و پلتفرم ها اقتصاد مشارکتی را اختراع می کنند و سرمایه داری را دوباره اختراع می کنند', 13, 6, 'book', 't', '<p><em>Peers Inc</em> (2015) نگاه خودی را در مورد اینکه چگونه اقتصاد اشتراک‌گذاری مدرن در حال تغییر نحوه تجارت شرکت‌ها و مصرف‌کنندگان است ارائه می‌دهد. همچنین توضیح می‌دهد که چگونه این اقتصاد ممکن است درمانی برای بسیاری از بیماری‌های این سیاره، از افزایش دما گرفته تا کاهش منابع باشد.</p>', '2017-05-17 00:00:00', NULL, 9, 'https://images.blinkist.io/images/books/5918c9c5b238e100066a4e7f/1_1/470.jpg', '/en/books/peers-inc-en/purchase', 'شرکت-همتایان', '2023-01-26 19:42:05.8997', '2023-01-26 19:42:05.8997', NULL, 'Peers Inc');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (523, 'چرایی خود را پیدا کنید', 'راهنمای عملی برای کشف هدف برای شما و تیم شما', 'راهنمای عملی برای کشف هدف برای شما و تیم شما', 17, 7, 'book', 't', '<p><em>Find Your WHY</em> (2017) چیزی را ارائه می دهد که هر شخص و کسب و کاری به دنبال آن است: یک هدف واقعی. نویسندگان استراتژی‌ها و تمرین‌هایی را ارائه می‌کنند که افراد و تیم‌ها به طور یکسان می‌توانند از آنها برای کشف قوی‌ترین انگیزه‌های خود و دلایل آن‌ها برای بیدار شدن در صبح و شروع روز کاری استفاده کنند. اگر به دنبال شغل مناسب هستید، سعی می کنید کارمندان مناسب را استخدام کنید یا امیدوارید درک بهتری از خود و افرادی که با آنها زندگی و کار می کنید به دست آورید، این یک راهنمای مفید است.</p>
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (524, 'قابل داستان', 'با قدرت داستان سرایی، زندگی خود را درگیر کنید، آموزش دهید، متقاعد کنید و تغییر دهید', 'با قدرت داستان سرایی، زندگی خود را درگیر کنید، آموزش دهید، متقاعد کنید و تغییر دهید', 18, 6, 'book', 't', '<p><em>Storyworthy</em> (2018) توضیح می‌دهد که چگونه یک داستان را برای حداکثر تأثیر بسازید. این پلک‌ها از آغازهای جذاب تا پایان‌های رضایت‌بخش و هر آنچه در این میان است، نکات و تکنیک‌های ساده و مؤثری را برای جذب مخاطب و به ارمغان آوردن سرگرمی، اصالت و فوریت به داستان‌سرایی شما ارائه می‌کنند.</p>', '2019-01-17 00:00:00', 4, 211, 'https://images.blinkist.io/images/books/5c3c586a6cee0700074bfc11/1_1/470.jpg', '/en/books/storyworthy-en/purchase', 'قابل-داستان', '2023-01-26 19:42:14.958205', '2023-01-26 19:42:14.958205', NULL, 'Storyworthy');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (525, 'اعتماد به نفس خلاق', 'آزادسازی پتانسیل خلاق در درون همه ما', 'آزادسازی پتانسیل خلاق در درون همه ما', 21, 9, 'book', 't', '<p><em>خلاقیت</em> <em>اعتماد به ما</em> ارزش و تأثیر شگفت انگیزی را که خلاقیت در زندگی روزمره ما دارد به ما نشان می دهد. در واقع، توانایی تفکر خلاق می تواند شادی و موفقیت شما را در هر دو حوزه حرفه ای و شخصی افزایش دهد. خوشبختانه، هنرمندان و نوازندگان انحصار خلاقیت را ندارند. با تکنیک ها و طرز فکر مناسب، هر کسی می تواند خلاقانه فکر کند.</p>', '2014-08-26 00:00:00', 4, 161, 'https://images.blinkist.io/images/books/53fcd12e3762620008000000/1_1/470.jpg', '/en/books/creative-confidence-en/purchase', 'اعتماد-به-نفس-خلاق', '2023-01-26 19:42:20.882702', '2023-01-26 19:42:20.882702', NULL, 'Creative Confidence');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (526, 'ملت دوپامین', 'یافتن تعادل در عصر عیش و نوش', 'یافتن تعادل در عصر عیش و نوش', 24, 7, 'book', 't', '<p><em>ملت دوپامین</em> (2021) ارتباط بین لذت و درد را بررسی می کند. دنیای مدرن ما بیش از هر زمان دیگری پر از محرک های دوپامین است - از جمله همه چیز از مواد مخدر و رابطه جنسی گرفته تا گوشی های هوشمند و خرید. این کتاب با استناد به سال‌ها تجربه بالینی و داستان‌های بیماران، به درک اعتیاد کمک می‌کند و چگونگی دستیابی به تعادل سالم در زندگی‌مان را توضیح می‌دهد. </p>', '2021-11-04 00:00:00', 5, 374, 'https://images.blinkist.io/images/books/617a949f6cee0700082055ec/1_1/470.jpg', '/en/books/dopamine-nation-en/purchase', 'ملت-دوپامین', '2023-01-26 19:42:25.878429', '2023-01-26 19:42:25.878429', NULL, 'Dopamine Nation');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (527, 'شما می توانید هر چیزی را مذاکره کنید', 'هر چی بخوای بهش رسیدی', 'هر چی بخوای بهش رسیدی', 16, 8, 'book', 't', '<p><em>You Can Negotiate Anything</em> (1980) نشان می‌دهد که مذاکرات در هر جنبه‌ای از زندگی اتفاق می‌افتد و داشتن مهارت‌ها و درک برای مقابله با آن موقعیت‌ها حیاتی است. این کتاب عوامل کلیدی موثر بر موفقیت مذاکره و همچنین راه‌های مذاکره برای راه‌حل‌های برد-برد را بیان می‌کند.</p>', '2013-01-13 00:00:00', 4, 259, 'https://images.blinkist.io/images/books/50cf7a86e4b0cc0df4ce964e/1_1/470.jpg', '/en/books/you-can-negotiate-anything-en/purchase', 'شما-می-توانید-هر-چیزی-را-مذاکره-کنید', '2023-01-26 19:42:30.757713', '2023-01-26 19:42:30.757713', NULL, 'You Can Negotiate Anything');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (528, 'لبه نرم', 'جایی که شرکت های بزرگ به موفقیت پایدار می رسند', 'جایی که شرکت های بزرگ به موفقیت پایدار می رسند', 13, 7, 'book', 'f', '<p>این کتاب (2014) درباره "لبه نرم" - یعنی جنبه انسانی - تجارت است. اگر نمی‌خواهید در پی رقبایتان بنیانگذار باقی بمانید، شرکت شما به چیزی <em>بیشتر</em> نیاز دارد - خلاقیت و انعطاف‌پذیری بیشتر، اشتیاق بیشتر. لبه نرم سرچشمه چنین ویژگی هایی است. لبه نرم شرکت شما ممکن است در ابتدا گریزان به نظر برسد، اما به یاد داشته باشید: یافتن آن برای موفقیت طولانی مدت کاملاً حیاتی است.</p>', '2015-04-14 00:00:00', 4, 15, 'https://images.blinkist.io/images/books/552bd9e86466340007380000/1_1/470.jpg', '/en/books/the-soft-edge-en/purchase', 'لبه-نرم', '2023-01-26 19:42:35.955776', '2023-01-26 19:42:35.955776', NULL, 'The Soft Edge');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (529, 'موفقیت قابل پیش بینی', 'سازمان خود را در مسیر رشد قرار دهید - و آن را در آنجا نگه دارید', 'سازمان خود را در مسیر رشد قرار دهید - و آن را در آنجا نگه دارید', 16, 7, 'book', 't', '<p><em>موفقیت قابل پیش بینی</em> (2010) راهنمای گام به گامی است که مراحل مختلف توسعه سازمانی را که در مسیر موفقیت پایدار رخ می دهد، نشان می دهد. نویسنده نکات و استراتژی‌هایی را برای هر مرحله از فرآیند ارائه می‌کند و به شما نشان می‌دهد که برای دستیابی به موفقیت قابل پیش‌بینی – و سپس حفظ – سال به سال چه چیزی لازم است.</p>', '2015-11-11 00:00:00', 4, 16, 'https://images.blinkist.io/images/books/564078413866330007370000/1_1/470.jpg', '/en/books/predictable-success-en/purchase', 'موفقیت-قابل-پیش-بینی', '2023-01-26 19:42:40.648827', '2023-01-26 19:42:40.648827', NULL, 'Predictable Success');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (530, 'چرا چاق می شویم', 'و در مورد آن چه باید کرد', 'و در مورد آن چه باید کرد', 23, 11, 'book', 't', '<p><em>چرا چاق می شویم </em>(2010) توضیح می دهد که چرا انواع خاصی از کربوهیدرات ها دلیل اصلی چاق شدن ما هستند. این کتاب نه تنها نشان می دهد که چرا افراد چاق می شوند، بلکه چرا موضوع بحث برانگیز است. همچنین در مورد اینکه چرا برخی افراد چاق می شوند و برخی دیگر چاق نمی شوند، نقش استعدادهای ژنتیکی در این فرآیند و اینکه همه ما باید از کدام غذاها اجتناب کنیم صحبت می کند. </p>', '2014-01-08 19:25:51.126', 4, 77, 'https://images.blinkist.io/images/books/52cab29c6435330012000000/1_1/470.jpg', '/en/books/why-we-get-fat-en/purchase', 'چرا-چاق-می-شویم', '2023-01-26 19:42:45.245828', '2023-01-26 19:42:45.245828', NULL, 'Why We Get Fat');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (531, 'چگونه یک بزرگسال را بزرگ کنیم', 'از دام بیش از حد والدین رها شوید و فرزندتان را برای موفقیت آماده کنید', 'از دام بیش از حد والدین رها شوید و فرزندتان را برای موفقیت آماده کنید', 16, 7, 'book', 't', '<p><em>How to Raise an Adul</em>t (2015) روش‌هایی را نشان می‌دهد که رایج‌ترین روش فرزندپروری امروزه، فرزندپروری با هلیکوپتر، بیش از آنکه مفید باشد، چه برای والدین و چه برای فرزندان مضر است. این پلک‌ها راه بهتری را برای والدین نشان می‌دهند – راهی که در واقع کودکان را به گونه‌ای تربیت می‌کند که به بزرگسالان مستقلی تبدیل شوند.</p>', '2016-01-06 00:00:00', 5, 94, 'https://images.blinkist.io/images/books/568b01e7de78c0000700002d/1_1/470.jpg', '/en/books/how-to-raise-an-adult-en/purchase', 'چگونه-یک-بزرگسال-را-بزرگ-کنیم', '2023-01-26 19:42:50.017727', '2023-01-26 19:42:50.017727', NULL, 'How to Raise an Adult');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (532, 'چانه زنی برای مزیت', 'استراتژی های مذاکره برای افراد منطقی', 'استراتژی های مذاکره برای افراد منطقی', 25, 8, 'book', 't', '<p><em>معامله برای مزیت </em>(1999) راهنمایی برای تبدیل شدن به یک مذاکره کننده کارآمدتر و باهوش تر است. این کتاب با ترکیب بینش‌های حاصل از تحقیقات مذاکره با تاکتیک‌های آزمایش‌شده و آزمایش‌شده توسط برخی از کارشناسان برجسته تجارت جهان، برای هر کسی که می‌خواهد مهارت‌های چانه‌زنی خود را بهبود بخشد، مناسب است.</p>', '2020-07-27 00:00:00', 4, 101, 'https://images.blinkist.io/images/books/5f19fefb6cee070006090e28/1_1/470.jpg', '/en/books/bargaining-for-advantage-en/purchase', 'چانه-زنی-برای-مزیت', '2023-01-26 19:42:54.945089', '2023-01-26 19:42:54.945089', NULL, 'Bargaining for Advantage');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (533, 'لغو آن!', 'چگونه تغییرات ساده سبک زندگی می تواند اکثر بیماری های مزمن را معکوس کند؟', 'چگونه تغییرات ساده سبک زندگی می تواند اکثر بیماری های مزمن را معکوس کند؟', 25, 8, 'book', 't', '<p><em>واگرد آن! </em>(2019) قدرت شگفت انگیز ایجاد تغییرات ساده در سبک زندگی را نشان می دهد که نه تنها می تواند از طیف وسیعی از بیماری های مزمن جلوگیری کند، بلکه حتی معکوس کند. این ممکن است مانند یک تفکر آرزویی به نظر برسد، اما با مجموعه ای غنی از تحقیقات که در مجلات علمی معتبر منتشر شده است پشتیبانی می شود و منعکس کننده یک اجماع رو به رشد در جامعه پزشکی جریان اصلی است.</p>', '2019-02-08 00:00:00', 4, 82, 'https://images.blinkist.io/images/books/5c5aafc26cee0700085d0fb4/1_1/470.jpg', '/en/books/undo-it-en/purchase', 'لغو-آن!', '2023-01-26 19:42:59.936723', '2023-01-26 19:42:59.936723', NULL, 'Undo It!');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (534, 'بازی درونی تنیس', 'راهنمای نهایی برای جنبه ذهنی اوج عملکرد', 'راهنمای نهایی برای جنبه ذهنی اوج عملکرد', 13, 6, 'book', 't', '<p><em>بازی درونی تنیس</em> (1972) تنش بین ذهن خودآگاه و ناخودآگاه شما را توضیح می‌دهد و این که چگونه این تضاد با عملکرد، به ویژه از طریق لنز تنیس، ارتباط دارد. این پلک‌ها توصیه‌های ملموسی را در مورد چگونگی مهار توانایی طبیعی خود و برتری در زمین و بیرون ارائه می‌دهند.</p>', '2017-07-03 00:00:00', 4, 107, 'https://images.blinkist.io/images/books/595a0a96b238e100069fb34b/1_1/470.jpg', '/en/books/the-inner-game-of-tennis-en/purchase', 'بازی-درونی-تنیس', '2023-01-26 19:43:05.230603', '2023-01-26 19:43:05.230603', NULL, 'The Inner Game of Tennis');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (535, 'زندگی نامه مالکوم ایکس', 'همانطور که به الکس هیلی گفته شد', 'همانطور که به الکس هیلی گفته شد', 17, 11, 'book', 't', '<p><em>زندگی نامه مالکوم ایکس</em> (1965) روایتی عمیق و شخصی از سفر یک مرد از ترک تحصیل و ورود به زندگی جنایتکارانه و اعتیاد به مواد مخدر تا یافتن رستگاری از طریق فعالیت های حقوق بشری است. این پلک ها داستان یک ذهن کنجکاو و در حال تکامل را روایت می کند: مردی که زندگی خود را وقف کمک به آفریقایی-آمریکایی ها برای کسب هویت و رهایی از ظلم به هر وسیله ای کرد.</p>', '2016-04-28 00:00:00', 5, 105, 'https://images.blinkist.io/images/books/571e1609da6afc00037e2599/1_1/470.jpg', '/en/books/the-autobiography-of-malcolm-x-en/purchase', 'زندگی-نامه-مالکوم-ایکس', '2023-01-26 19:43:09.787639', '2023-01-26 19:43:09.787639', NULL, 'The Autobiography of Malcolm X');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (536, 'ایمنی فوق العاده', 'راهنمای تغذیه ضروری برای تقویت سیستم دفاعی بدن برای زندگی طولانی تر، قوی تر و عاری از بیماری', 'راهنمای تغذیه ضروری برای تقویت سیستم دفاعی بدن برای زندگی طولانی تر، قوی تر و عاری از بیماری', 16, 7, 'book', 't', '<p><em>Super Immunity</em> (2011) راز سیستم ایمنی بهتر، قوی‌تر و بدن سالم‌تر را فاش می‌کند: سوپر غذاها. این پلک ها کاستی های پزشکی مدرن را روشن می کند و به شما می آموزد که چگونه از قدرت شفابخش غذاهای گیاهی سرشار از مواد مغذی و فیتوکمیکال استفاده کنید.</p>', '2016-03-31 00:00:00', 4, 203, 'https://images.blinkist.io/images/books/56fa9d80df8142000700003d/1_1/470.jpg', '/en/books/super-immunity-en/purchase', 'ایمنی-فوق-العاده', '2023-01-26 19:43:14.845227', '2023-01-26 19:43:14.845227', NULL, 'Super Immunity');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (537, 'بهتر و سریعتر', 'مسیر اثبات شده برای ایده های غیرقابل توقف', 'مسیر اثبات شده برای ایده های غیرقابل توقف', 15, 6, 'book', 't', '<p><em>بهتر و سریعتر</em>(2015) مجموعه خاصی از ابزارها و دستورالعمل‌هایی را که خوانندگان می‌توانند برای پیشی گرفتن از رقابت خود و دستیابی به موفقیت در بازار آشفته و غیرقابل پیش‌بینی مدرن استفاده کنند، تشریح می‌کند. جرمی گوتچه با استفاده از مثال‌های بی‌شماری از زندگی واقعی - هم داستان‌های هشداردهنده و هم داستان‌های موفقیت الهام‌بخش - مسیری را برای یافتن فرصت‌ها و توسعه ایده‌های تجاری موفق ترسیم می‌کند.</p>', '2015-09-01 00:00:00', 5, 49, 'https://images.blinkist.io/images/books/55e4c089a95dad0009000000/1_1/470.jpg', '/en/books/better-and-faster-en/purchase', 'بهتر-و-سریعتر', '2023-01-26 19:43:19.863671', '2023-01-26 19:43:19.863671', NULL, 'Better and Faster');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (538, 'سوپر کرانچر', 'چرا فکر کردن بر اساس اعداد راه جدیدی برای هوشمند بودن است؟', 'چرا فکر کردن بر اساس اعداد راه جدیدی برای هوشمند بودن است؟', 13, 6, 'book', 't', '<p>از ساخت یک انبار شراب تا یافتن خوشبختی خود، زندگی مدرن به طور فزاینده ای تحت کنترل اعداد و الگوریتم ها قرار می گیرد. <em>Super Crunchers </em>(2007) درباره قدرت محض مجموعه داده های بزرگی است که به الگوریتم ها وارد می شوند و روشی که آنها در کسب و کار، درمان پزشکی و حتی دولت های ما متحول می شوند.</p>', '2015-09-30 00:00:00', 4, 17, 'https://images.blinkist.io/images/books/560940f78a14e6000900008a/1_1/470.jpg', '/en/books/super-crunchers-en/purchase', 'سوپر-کرانچر', '2023-01-26 19:43:24.680867', '2023-01-26 19:43:24.680867', NULL, 'Super Crunchers');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (539, 'زندگی نامه یک یوگی', 'زندگی و آموزه های یکی از شخصیت های بزرگ روحانی', 'زندگی و آموزه های یکی از شخصیت های بزرگ روحانی', 17, 6, 'book', 't', '<p><em>زندگی نامه یک یوگی </em> (1946) روایتی عمیقاً معنوی و در عین حال سبک از زندگی فرستاده برجسته یوگای هند به غرب است. در این حماسه، پاراماهانسا یوگاناندا رویارویی خود را با گوروهای افسانه‌ای، سوامی‌ها، قدیسین و موجودات اختری روایت می‌کند که او را به سوی انجام مأموریتش برای متحد کردن شرق و غرب تحت یک خدا از طریق تمرین شخصی و علمی کریا یوگا راهنمایی کردند.</p >', '2023-01-15 00:00:00', 4, 25, 'https://images.blinkist.io/images/books/63be807be8fd3c00080b4085/1_1/470.jpg', '/en/books/autobiography-of-a-yogi-en/purchase', 'زندگی-نامه-یک-یوگی', '2023-01-26 19:43:29.925924', '2023-01-26 19:43:29.925924', NULL, 'Autobiography of a Yogi');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (540, 'جهت گیری نامرئی', 'مقدمه‌ای بر غیرجنس‌گرایی', 'مقدمه‌ای بر غیرجنس‌گرایی', 16, 6, 'book', 't', '<p><em>جهت نامرئی</em> (2014) مقدمه مفیدی برای غیرجنسی ارائه می دهد، شامل اطلاعات ارزشمندی در مورد اینکه چه چیزی هست و چه چیزی نیست. همچنین در مورد اینکه مردم چگونه این گرایش جنسی را تجربه می‌کنند، مشکلات ناشی از آن، و اینکه چرا نیازی به درمان آن، تسلیم شدن به آن یا در نظر گرفتن افراد غیرجنسی با من یا شما وجود ندارد، آشنا خواهید شد.</p>', '2016-06-16 00:00:00', 5, 17, 'https://images.blinkist.io/images/books/57593d49496d1c0003e862cb/1_1/470.jpg', '/en/books/the-invisible-orientation-en/purchase', 'جهت-گیری-نامرئی', '2023-01-26 19:43:35.776289', '2023-01-26 19:43:35.776289', NULL, 'The Invisible Orientation');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (541, 'مرگ پول', 'فروپاشی آینده سیستم پولی بین المللی', 'فروپاشی آینده سیستم پولی بین المللی', 16, 9, 'book', 'f', '<p><em>مرگ</em> <em></em> <em>پول</em> سیستم پولی جهانی فعلی را که حول محور دلار متمرکز شده است، بررسی می‌کند. اگر سیاست های فعلی ادامه یابد، یک فروپاشی کامل قریب الوقوع است. شما باید برای بدترین ها آماده شوید.</p>', '2014-07-29 00:00:00', 4, 48, 'https://images.blinkist.io/images/books/53d779383661640007000000/1_1/470.jpg', '/en/books/the-death-of-money-en/purchase', 'مرگ-پول', '2023-01-26 19:43:40.963255', '2023-01-26 19:43:40.963255', NULL, 'The Death of Money');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (542, 'تخت خود را مرتب کن', 'چیزهای کوچکی که می توانند زندگی شما را تغییر دهند... و شاید دنیا', 'چیزهای کوچکی که می توانند زندگی شما را تغییر دهند... و شاید دنیا', 11, 5, 'book', 't', '<p><em>تختت را درست کن</em> (2017) مجموعه ای از ده تجربه ارزشمند شخصی نویسنده در طول سالها خدمت او در نیروی دریایی ایالات متحده SEAL است. هر کدام یک توصیه ساده و در عین حال ارزشمند است که تأثیر مثبتی بر زندگی شما خواهد داشت.</p>', '2017-09-11 12:00:00', 4, 418, 'https://images.blinkist.io/images/books/59b64d39b238e10005c1faa5/1_1/470.jpg', '/en/books/make-your-bed-en/purchase', 'تخت-خود-را-مرتب-کن', '2023-01-26 19:43:44.238665', '2023-01-26 19:43:44.238665', NULL, 'Make your Bed');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (543, 'در دفاع از غذا', 'مانیفست یک غذاخور', 'مانیفست یک غذاخور', 25, 11, 'book', 't', '<p><em>در دفاع از غذا</em>بررسی دقیق افزایش تغذیه گرایی در فرهنگ ما و گزارشی تاریخی از صنعتی شدن غذا است. مایکل پولن، نویسنده متخصص در بوم شناسی مواد غذایی، نگاهی به روشی می اندازد که در آن صنعت غذا تمرکز رژیم غذایی ما را از "غذا" به "مواد مغذی" تغییر داد و بنابراین هدف از غذا خوردن را به حفظ سلامت جسمی محدود کرد. انجام نشد.</p>', '2014-11-24 00:00:00', 5, 64, 'https://images.blinkist.io/images/books/5471a6d13935360009000000/1_1/470.jpg', '/en/books/in-defense-of-food-en/purchase', 'در-دفاع-از-غذا', '2023-01-26 19:43:48.349195', '2023-01-26 19:43:48.349195', NULL, 'In Defense of Food');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (544, 'آمازون', 'چگونه بی امان ترین خرده فروش جهان به انقلاب تجارت ادامه خواهد داد', 'چگونه بی امان ترین خرده فروش جهان به انقلاب تجارت ادامه خواهد داد', 24, 8, 'book', 't', '<p><em>Amazon (2019) </em> ظهور مخرب‌ترین خرده‌فروش آنلاین قرن بیست و یکم، از کتابفروشی آنلاین ساده تا امپراتوری تجاری جهانی را بررسی می‌کند. کارشناسان خرده‌فروشی ناتالی برگ و میا نایتز با تکیه بر داده‌های صنعت و دانش خودی توضیح می‌دهند که چرا آمازون بر بازار تجارت الکترونیک امروزی تسلط دارد، چگونه به انقلاب خرده‌فروشی ادامه می‌دهد، و کسب‌وکارهای دیگر برای ادامه دادن چه کاری می‌توانند انجام دهند.</p>', '2020-01-02 00:00:00', 4, 148, 'https://images.blinkist.io/images/books/5dfcc3cf6cee07000788a284/1_1/470.jpg', '/en/books/amazon-en/purchase', 'آمازون', '2023-01-26 19:43:53.407918', '2023-01-26 19:43:53.407918', NULL, 'Amazon');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (545, 'قدرت', 'چرا برخی از مردم آن را دارند و برخی دیگر ندارند', 'چرا برخی از مردم آن را دارند و برخی دیگر ندارند', 16, 8, 'book', 't', '<p><em>Power</em> (2010) یک راهنمای <em>realpolitik</em>برای هدایت یک حرفه موفق است. بینش‌ها و توصیه‌های غیرمعمولی را ارائه می‌کند که معمولاً در سایر ادبیات شغلی نمی‌یابید، با نکات و تکنیک‌هایی که می‌توانید از هم اکنون برای دستیابی به موفقیت بلندمدت استفاده کنید.</p>', '2014-12-08 00:00:00', 4, 78, 'https://images.blinkist.io/images/books/5485c5396331620009220000/1_1/470.jpg', '/en/books/power-en/purchase', 'قدرت', '2023-01-26 19:43:57.000223', '2023-01-26 19:43:57.000223', NULL, 'Power');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (546, 'عادت شجاعت', 'چگونه ترس های خود را بپذیرید، گذشته را رها کنید و زندگی شجاعانه خود را داشته باشید', 'چگونه ترس های خود را بپذیرید، گذشته را رها کنید و زندگی شجاعانه خود را داشته باشید', 21, 7, 'book', 't', '<p><em>عادت شجاعت</em> (2018) نگاهی به نقش ترس در زندگی ما دارد و یک برنامه چهار مرحله ای برای تبدیل شدن به شجاع ترین خود و دنبال کردن رویاهای خود ارائه می دهد. با استفاده از مثال‌های الهام‌بخش و نکات عملی که ریشه در درمان شناختی رفتاری، یا CBT، و درمان پذیرش و تعهد، یا ACT دارد، راه‌هایی را بیان می‌کند که همه می‌توانند شجاعت لازم برای تغییر زندگی خود را پرورش دهند.</p>', '2020-03-09 00:00:00', 4, 309, 'https://images.blinkist.io/images/books/5e64dcec6cee0700064b99a8/1_1/470.jpg', '/en/books/the-courage-habit-en/purchase', 'عادت-شجاعت', '2023-01-26 19:44:01.956622', '2023-01-26 19:44:01.956622', NULL, 'The Courage Habit');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (547, 'تحت مدیریت جدید', 'چگونه سازمان های پیشرو کسب و کار خود را به طور معمول در حال توسعه هستند', 'چگونه سازمان های پیشرو کسب و کار خود را به طور معمول در حال توسعه هستند', 16, 6, 'book', 't', '<p><em>تحت مدیریت جدید </em>(2016) درباره تغییر نقش مدیران در دنیایی است که انعطاف پذیری و کار دانش به نشانه های بارز تبدیل شده است. این چشمک‌ها توضیح می‌دهند که چگونه برخی از حکمت‌های مدیریت استاندارد دیگر اعمال نمی‌شوند و در عوض چه باید کرد.</p>', '2017-01-03 00:00:00', 4, 26, 'https://images.blinkist.io/images/books/5852cacd58b1350004ed16e3/1_1/470.jpg', '/en/books/under-new-management-en/purchase', 'تحت-مدیریت-جدید', '2023-01-26 19:44:05.716202', '2023-01-26 19:44:05.716202', NULL, 'Under New Management');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (548, 'آنچه مال من است مال توست', 'چگونه مصرف مشارکتی روش زندگی ما را تغییر می دهد', 'چگونه مصرف مشارکتی روش زندگی ما را تغییر می دهد', 15, 8, 'book', 'f', '<p><em>آنچه من مال توست </em>تصویر شگفت انگیزی از آینده ما ترسیم می کند اگر در مسیر فعلی خود باقی بمانیم. مصرف بیش از حد گسترده و مدل‌های تولید سنتی منجر به عذاب حتمی می‌شود – یعنی مگر اینکه بتوانیم چشم‌انداز اقتصادی جدیدی را که جلوی چشمان ما در حال تکامل است، پرورش دهیم: «مصرف مشارکتی».</p>', '2015-01-07 00:00:00', NULL, 4, 'https://images.blinkist.io/images/books/54a98d006233320009510000/1_1/470.jpg', '/en/books/whats-mine-is-yours-en/purchase', 'آنچه-مال-من-است-مال-توست', '2023-01-26 19:44:10.908116', '2023-01-26 19:44:10.908116', NULL, 'What’s Mine Is Yours');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (549, 'عادات کشف مستمر', 'محصولاتی را کشف کنید که ارزش مشتری و ارزش تجاری ایجاد می کنند', 'محصولاتی را کشف کنید که ارزش مشتری و ارزش تجاری ایجاد می کنند', 20, 5, 'book', 't', '<p><em>عادات کشف مستمر</em>(2021) به بررسی این موضوع می‌پردازد که چگونه مدیران محصول و طراحان می‌توانند همچنان تأثیر مثبتی بر زندگی مشتریان خود بگذارند. این یک فرآیند تصمیم‌گیری بهینه را برای تیم‌های محصول بررسی می‌کند تا بتوانند به بهبود پیشنهادات خود ادامه دهند. </p>', '2022-04-14 00:00:00', 4, 188, 'https://images.blinkist.io/images/books/6253fb7b6cee070008dbe6e6/1_1/470.jpg', '/en/books/continuous-discovery-habits-en/purchase', 'عادات-کشف-مستمر', '2023-01-26 19:44:15.85489', '2023-01-26 19:44:15.85489', NULL, 'Continuous Discovery Habits ');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (550, 'پرورش رهبران', 'استفاده از اصول والدین در محل کار برای تبدیل شدن به یک رهبر عالی و ایجاد رهبران بزرگ', 'استفاده از اصول والدین در محل کار برای تبدیل شدن به یک رهبر عالی و ایجاد رهبران بزرگ', 23, 7, 'book', 't', '<p><em>افزایش رهبران </em>(2020) مقدمه ای متفکرانه در مورد رهبری معاصر است. این راهنما شباهت‌های شگفت‌انگیز بین تربیت کودکان قوی و مستقل و پرورش تیم‌های موفق و سازنده را بیان می‌کند.</p>', '2021-04-22 00:00:00', 4, 48, 'https://images.blinkist.io/images/books/607956da6cee070007bf9430/1_1/470.jpg', '/en/books/raising-leaders-en/purchase', 'پرورش-رهبران', '2023-01-26 19:44:21.323754', '2023-01-26 19:44:21.323754', NULL, 'Raising Leaders');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (644, 'عشق واقعی', 'هنر ارتباط آگاهانه', 'هنر ارتباط آگاهانه', 25, 8, 'book', 't', '<p><em>عشق واقعی</em> (2017) توجه ما را به عادات و شرایط فرهنگی که ما را از ایجاد ارتباط عمیق با دیگران باز می دارد، جلب می کند. شارون سالزبرگ با دعوت از ما برای گسترش مفاهیم عشق و روش هایی که در زندگی روزمره خود به آن عمل می کنیم، توصیه های عملی در مورد اینکه چگونه می توانیم روابط خود را تقویت کنیم و لذت بیشتری را تجربه کنیم، ارائه می دهد. </p>', '2019-10-25 00:00:00', 5, 312, 'https://images.blinkist.io/images/books/5db097b16cee070008d0b9d5/1_1/470.jpg', '/en/books/real-love-en/purchase', 'عشق-واقعی', '2023-01-26 19:52:00.514518', '2023-01-26 19:52:00.514518', NULL, 'Real Love');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (551, 'ابزار تایتان ها', 'تاکتیک‌ها، روال‌ها و عادات میلیاردرها، نمادها و مجریان درجه یک', 'تاکتیک‌ها، روال‌ها و عادات میلیاردرها، نمادها و مجریان درجه یک', 16, 7, 'book', 't', '<p><em>Tools of Titans </em>(2016) داستان ها، استراتژی ها و موفقیت های برخی از الهام بخش ترین دستاوردها، متفکران و انجام دهندگان دوران مدرن را شرح می دهد. این پلک‌ها به شما یاد می‌دهند که چگونه بدن و ذهن خود را تقویت کنید، همه در حین ایجاد کسب‌وکار خلاقانه‌تان.</p>
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (552, 'عملا رادیکال', 'راه های نه چندان احمقانه برای متحول کردن شرکت، تکان دادن صنعت و به چالش کشیدن خود', 'راه های نه چندان احمقانه برای متحول کردن شرکت، تکان دادن صنعت و به چالش کشیدن خود', 19, 6, 'book', 't', '<p><em>عملاً رادیکال </em>(2011) یک راهنمای استراتژیک برای پیمایش در دنیای پرشتاب کسب و کار امروزی برای رهبرانی است که مایلند خود را از سایرین متمایز کنند. پر از نکات و بینش های هوشمندانه از مبتکرترین شرکت های امروزی، نیاز به بازنگری در روش های آزموده شده و یادگیری تفکر خارج از چارچوب را مطرح می کند.</p>', '2018-12-18 00:00:00', 5, 43, 'https://images.blinkist.io/images/books/5c157ea16cee070007d88939/1_1/470.jpg', '/en/books/practically-radical-en/purchase', 'عملا-رادیکال', '2023-01-26 19:44:29.52465', '2023-01-26 19:44:29.52465', NULL, 'Practically Radical');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (553, 'فراآموزی', 'شغل خود را تسریع کنید، وظایف سخت را به دست آورید و از رقابت پیشی بگیرید', 'شغل خود را تسریع کنید، وظایف سخت را به دست آورید و از رقابت پیشی بگیرید', 30, 10, 'book', 't', '<p> فراآموزان افراد عادی هستند که می توانند مهارت های دشوار را با سرعتی خارق العاده تسلط دهند. در نتیجه، آنها به موفقیت شخصی فوق العاده دست می یابند و مزیت حرفه ای جدی را پرورش می دهند. اما دقیقا چگونه آن را از بین می برند؟ در <em>UltraLearning</em>(2019)، اسکات اچ یانگ استراتژی های یادگیری تهاجمی و خودراهبر برخی از موفق ترین فراآموزان جهان را تجزیه و تحلیل می کند و آنها را به تکنیک ها و استراتژی هایی تقسیم می کند که هر کسی می تواند اجرا کند.</p >', '2019-09-04 00:00:00', 5, 939, 'https://images.blinkist.io/images/books/5d6c31e76cee0700081a65df/1_1/470.jpg', '/en/books/ultralearning-en/purchase', 'فراآموزی', '2023-01-26 19:44:34.356511', '2023-01-26 19:44:34.356511', NULL, 'Ultralearning');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (554, 'آهنگ شادی', 'چگونه از علم شادی برای تسریع موفقیت خود استفاده کنیم', 'چگونه از علم شادی برای تسریع موفقیت خود استفاده کنیم', 19, 9, 'book', 't', '<p><em>مسیر شادی</em> (2016) مراحل ساده‌ای را که می‌توانید برای شادتر و موفق‌تر شدن انجام دهید، تشریح می‌کند. این پلک‌ها با ارجاع به آخرین تحقیقات علمی، افسانه‌های رایج در مورد چگونگی موفقیت را از بین می‌برند و یک برنامه مشخص برای کاهش استرس در زندگی‌تان تنظیم می‌کنند.</p>', '2016-10-26 00:00:00', 5, 70, 'https://images.blinkist.io/images/books/580b6c9ed4d2ce0003dd2475/1_1/470.jpg', '/en/books/the-happiness-track-en/purchase', 'آهنگ-شادی', '2023-01-26 19:44:40.084247', '2023-01-26 19:44:40.084247', NULL, 'The Happiness Track');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (555, 'دریافت عشقی که می خواهید', 'راهنمای زوج ها', 'راهنمای زوج ها', 18, 7, 'book', 't', '<p><em>دریافت عشقی که می خواهید</em> (1988) توصیه های عملی در مورد چگونگی نجات یک رابطه شکست خورده و ایجاد یک رابطه قوی تر ارائه می دهد. این یک برنامه درمانی منحصر به فرد را برجسته می کند که یک راهنمای گام به گام برای کمک به شرکا برای رفع خواسته های سرکوب شده دوران کودکی و تبدیل شدن به افراد دلسوزتر ارائه می دهد.</p>', '2016-12-19 00:00:00', 4, 197, 'https://images.blinkist.io/images/books/58558f631219060004019dbd/1_1/470.jpg', '/en/books/getting-the-love-you-want-en/purchase', 'دریافت-عشقی-که-می-خواهید', '2023-01-26 19:44:45.059197', '2023-01-26 19:44:45.059197', NULL, 'Getting The Love You Want');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (556, 'پایان بازاریابی', 'انسانی کردن برند خود در عصر رسانه های اجتماعی و هوش مصنوعی', 'انسانی کردن برند خود در عصر رسانه های اجتماعی و هوش مصنوعی', 21, 7, 'book', 't', '<p><em>پایان بازاریابی</em> (2020) راهنمای نحوه استفاده برندها از رسانه های اجتماعی است. در عصری که بازاریابی سنتی دیگر وجود ندارد، کسب‌وکارها باید راه‌هایی بیابند تا به برندهای خود چهره انسانی ببخشند، توجه کاربران رسانه‌های اجتماعی را به خود جلب کنند و اعتماد آنها را جلب کنند.</p>', '2020-06-02 00:00:00', 4, 215, 'https://images.blinkist.io/images/books/5ed13fb86cee070006a5a2c2/1_1/470.jpg', '/en/books/the-end-of-marketing-en/purchase', 'پایان-بازاریابی', '2023-01-26 19:44:50.110679', '2023-01-26 19:44:50.110679', NULL, 'The End of Marketing');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (557, '۲۱ قانون انکار ناپذیر رهبری (نسخه جدید)', 'آنها را دنبال کنید تا مردم شما را دنبال کنند', 'آنها را دنبال کنید تا مردم شما را دنبال کنند', 20, 5, 'book', 't', '<p><em>21 قانون انکار ناپذیر رهبری </em>(1998) قوانین، اصول و نمونه های کلیدی را از مجموعه متنوعی از رهبران الهام بخش در طول تاریخ گردآوری می کند. ما اغلب در مورد "رهبران متولد شده" صحبت می کنیم، گویی که یک فرد یا عامل X ویژه رهبری را دارد یا ندارد. در واقع، رهبری آموخته می شود – و با مطالعه آنچه که بهترین رهبران جهان را قادر به جذب پیروان و تأثیرگذاری می کند، ما نیز می توانیم همین کار را انجام دهیم. </p>', '2022-07-06 00:00:00', 5, 344, 'https://images.blinkist.io/images/books/62bd98e26cee0700081cd67e/1_1/470.jpg', '/en/books/the-21-irrefutable-laws-of-leadership-new-version-en/purchase', '۲۱-قانون-انکار-ناپذیر-رهبری-(نسخه-جدید)', '2023-01-26 19:44:54.749859', '2023-01-26 19:44:54.749859', NULL, 'The 21 Irrefutable Laws of Leadership (New Version)');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (558, 'بیوگرافی قبل از خواب: هریت تابمن', 'راه آزادی', 'راه آزادی', 34, 7, 'book', 't', '<p><strong>به روایت والری راس<br><br>موسیقی توسط فدریکو کدرونی</strong></p>
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (559, 'ارتجاعی', 'چگونه یک هسته تزلزل ناپذیر از آرامش، قدرت و شادی را پرورش دهیم', 'چگونه یک هسته تزلزل ناپذیر از آرامش، قدرت و شادی را پرورش دهیم', 26, 8, 'book', 't', '<p><em>تاب آور </em>(2018) یک راهنمای عملی در مورد چگونگی پرورش قدرت های درونی و توسعه ویژگی هایی مانند شفقت، اعتماد به نفس و سخاوت است. از طریق تکنیک‌های ساده و مثال‌های عینی، روش‌هایی را توضیح می‌دهد که می‌توانید از منابع مغز خود برای مقابله با استرس و اضطراب استفاده کنید - و انگیزه دنبال کردن رویاهای خود را پیدا کنید.</p>', '2020-07-20 00:00:00', 4, 319, 'https://images.blinkist.io/images/books/5f10bf806cee070006c1f65e/1_1/470.jpg', '/en/books/resilient-en/purchase', 'ارتجاعی', '2023-01-26 19:45:03.148688', '2023-01-26 19:45:03.148688', NULL, 'Resilient');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (560, 'عدم بازاریابی', 'همه چیز تغییر کرده است و هیچ چیز متفاوت نیست', 'همه چیز تغییر کرده است و هیچ چیز متفاوت نیست', 22, 9, 'book', 't', '<p><em>UnMarketing</em> (2009) رویکرد جدیدی برای بازاریابی ارائه می‌کند که فراتر از روش‌های معمولی مانند تماس سرد و تبلیغات است. این پلک‌ها توضیح می‌دهند که چگونه، با کمک ابزارهای جدید و پیچیده‌تر، کسب‌وکارها می‌توانند با مشتریان خود روابط برقرار کنند تا آنها را به روشی طبیعی و مؤثرتر درگیر کنند.</p>', '2017-10-25 00:00:00', 5, 20, 'https://images.blinkist.io/images/books/59ef20c6b238e100064554d5/1_1/470.jpg', '/en/books/unmarketing-en/purchase', 'عدم-بازاریابی', '2023-01-26 19:45:07.917667', '2023-01-26 19:45:07.917667', NULL, 'UnMarketing');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (561, 'اصل مجاورت', 'استراتژی اثبات شده ای که منجر به شغلی می شود که دوست دارید', 'استراتژی اثبات شده ای که منجر به شغلی می شود که دوست دارید', 15, 6, 'book', 't', '<p><em>اصل مجاورت </em>(2019) یک طرح اثبات شده برای رسیدن به شغل رویایی شما و تبدیل شماره‌گیری شغلی شما از مزخرف به عالی ارائه می‌دهد. استراتژی کن کلمن به همان اندازه که قابل اجرا است، از افسانه‌های قدیمی درباره رزومه‌ها و رویدادهای شبکه‌ای صرف نظر می‌کند و آن را همانطور که هست بیان می‌کند. در قلب استدلال او یک معادله ساده اما مؤثر وجود دارد: افراد مناسب را بشناسید و خود را در مکان های مناسب قرار دهید و فرصت ها شروع به ارائه خود خواهند کرد. </p>', '2019-07-17 00:00:00', 4, 56, 'https://images.blinkist.io/images/books/5d2cdc446cee070008fd878f/1_1/470.jpg', '/en/books/the-proximity-principle-en/purchase', 'اصل-مجاورت', '2023-01-26 19:45:12.612012', '2023-01-26 19:45:12.612012', NULL, 'The Proximity Principle');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (562, 'دوست یک دوست', 'درک شبکه های پنهانی که می توانند زندگی و شغل شما را متحول کنند', 'درک شبکه های پنهانی که می توانند زندگی و شغل شما را متحول کنند', 20, 8, 'book', 't', '<p><em>Friend of a Friend</em> (2018) نشان می دهد که چگونه می توان از شبکه های اطراف ما استفاده کرد و از آنها بهره برد. البته شبکه‌سازی یک مهارت حیاتی برای موفقیت حرفه‌ای است – اما خود شبکه‌ها حتی عمیق‌تر می‌شوند و فقط به ایجاد تماس‌های جدید نیستند. نوآوری، پیشرفت شغلی و موفقیت در کسب و کار همگی نقش خود را دارند.</p>', '2018-10-08 00:00:00', 4, 48, 'https://images.blinkist.io/images/books/5bb93b71862c430007bf0a59/1_1/470.jpg', '/en/books/friend-of-a-friend-en/purchase', 'دوست-یک-دوست', '2023-01-26 19:45:16.371366', '2023-01-26 19:45:16.371366', NULL, 'Friend of a Friend');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (563, 'مدل های ذهنی بزرگ جلد 3', 'سیستم ها و ریاضیات', 'سیستم ها و ریاضیات', 25, 8, 'book', 't', '<p><em>مدل‌های ذهنی بزرگ جلد 3 </em> (2021) سومین کتاب از مجموعه‌ای است که نشان می‌دهد چگونه می‌توان از مدل‌های ذهنی از رشته‌های مختلف برای ایجاد تغییرات مثبت در زندگی‌تان استفاده کرد. این جلد بر روی مدل های ذهنی از سیستم ها و ریاضیات تمرکز دارد. این نشان می دهد که چگونه می توانید از ابزارهای شناختی برای بهبود همه چیز از تصمیم گیری و روابط گرفته تا تغذیه سالم و بهره وری شخصی استفاده کنید.</p>', '2022-02-08 00:00:00', 4, 249, 'https://images.blinkist.io/images/books/6200eef76cee0700088aeae1/1_1/470.jpg', '/en/books/the-great-mental-models-volume-3-en/purchase', 'مدل-های-ذهنی-بزرگ-جلد-3', '2023-01-26 19:45:21.436584', '2023-01-26 19:45:21.436584', NULL, 'The Great Mental Models Volume 3');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (564, 'منحنی خلاق', 'چگونه ایده مناسب را در زمان مناسب توسعه دهیم', 'چگونه ایده مناسب را در زمان مناسب توسعه دهیم', 18, 6, 'book', 't', '<p><em>Creative Curve</em> (2018) بینش های ارزشمندی را در مورد ماهیت واقعی استعداد ارائه می دهد. با استفاده از نمونه‌هایی از تحقیقات علمی، و همچنین شواهد حکایتی از مشاغل نابغه‌های معتبر، این پلک‌ها بررسی می‌کنند که آیا موفقیت خلاق نتیجه الهام منحصر به فرد است یا چیزی بسیار قابل پیش‌بینی‌تر.</p>', '2018-07-31 00:00:00', 5, 61, 'https://images.blinkist.io/images/books/5b5e72cab238e10007a4bbb0/1_1/470.jpg', '/en/books/the-creative-curve-en/purchase', 'منحنی-خلاق', '2023-01-26 19:45:26.683809', '2023-01-26 19:45:26.683809', NULL, 'The Creative Curve');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (565, 'استراتژی برای برنده شدن', 'راه جدید برای شروع، گام به گام، یا شروع دوباره در حرفه شما', 'راه جدید برای شروع، گام به گام، یا شروع دوباره در حرفه شما', 16, 7, 'book', 't', '<p><em>Strategize to win</em> (2014) یک راهنمای گام به گام برای کارمندان اولیه تا متوسط ​​است که در تلاش برای ترسیم یک مسیر شغلی موفق در محیط کار مدرن هستند. چرخه زندگی حرفه‌ای را دوباره به عنوان یک ماراتن تصور می‌کند - جایی که همه مسئولیت کسب مهارت‌ها و تجربیاتی را بر عهده می‌گیرند که آنها را برای چندین نقش آماده می‌کند، و هر نقش به عنوان یک پیشرفت طبیعی به سمت شغل رویایی‌شان تلقی می‌شود.</p>', '2022-12-12 00:00:00', 4, 31, 'https://images.blinkist.io/images/books/6391ebffdfab8000071bbce9/1_1/470.jpg', '/en/books/strategize-to-win-en/purchase', 'استراتژی-برای-برنده-شدن', '2023-01-26 19:45:31.354293', '2023-01-26 19:45:31.354293', NULL, 'Strategize to Win');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (566, 'بنیانگذار عزیز', 'نامه های مشاوره برای هر کسی که رهبری، مدیریت یا می خواهد یک کسب و کار راه اندازی کند', 'نامه های مشاوره برای هر کسی که رهبری، مدیریت یا می خواهد یک کسب و کار راه اندازی کند', 23, 8, 'book', 't', '<p><em>بنیانگذار عزیز</em> (2018) مقدمه ای جامع برای اصول اولیه راه اندازی کسب و کار و تأسیس یک استارت آپ پرطرفدار است. این پلک‌ها مملو از نکات مفید و توصیه‌های عملی از متخصصان باتجربه صنعت، شما را آماده می‌کند تا موانع روزمره را در راه رسیدن به اوج از پیش بگیرید و بر آن‌ها غلبه کنید.</p>', '2019-03-04 00:00:00', 4, 57, 'https://images.blinkist.io/images/books/5c7a592a6cee07000727d2dc/1_1/470.jpg', '/en/books/dear-founder-en/purchase', 'بنیانگذار-عزیز', '2023-01-26 19:45:36.66411', '2023-01-26 19:45:36.66411', NULL, 'Dear Founder');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (567, 'جایزه بزرگتر', 'چگونه می توانیم بهتر از رقابت انجام دهیم', 'چگونه می توانیم بهتر از رقابت انجام دهیم', 13, 6, 'book', 't', '<p><em>جایزه بزرگتر</em> (2014) توضیح می دهد که چگونه رقابت ما را عقب نگه می دارد. این پلک‌ها نشان می‌دهند که چگونه مدارس، اقتصاد و جامعه رقابتی ما - که اعتقاد بر این است که نمرات بالاتر، قیمت‌های پایین‌تر و نتایج بهتر را ایجاد می‌کنند - در واقع همکاری را خفه می‌کنند و ما را از تحقق پتانسیل کامل خود باز می‌دارند.</p>', '2016-08-03 00:00:00', NULL, 7, 'https://images.blinkist.io/images/books/5799e5ec355cc30003d1ff01/1_1/470.jpg', '/en/books/a-bigger-prize-en/purchase', 'جایزه-بزرگتر', '2023-01-26 19:45:40.411158', '2023-01-26 19:45:40.411158', NULL, 'A Bigger Prize');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (568, 'گفتگوهایی که ارزش داشتن را دارد', 'استفاده از پرس و جوی قدردانی برای ایجاد سوخت در تعامل سازنده و معنادار', 'استفاده از پرس و جوی قدردانی برای ایجاد سوخت در تعامل سازنده و معنادار', 19, 4, 'book', 't', '<p><em>مکالمات ارزش داشتن </em>(2018) به قدرت گفتگو در زندگی ما می پردازد و به آنچه که می توانیم برای برقراری ارتباط موثرتر در محل کار، روابطمان و در جامعه انجام دهیم، می پردازد. با تکیه بر داستان‌های واقعی و نظریه‌های مبتنی بر علمی، نشان می‌دهد که چگونه می‌توانیم سازمان‌ها و زندگی‌ها را با استفاده از اصل جستجوی قدردانی - گفتگوی مؤثر از طریق دیدگاه مثبت و پرسیدن سؤالات درست، بهبود بخشیم.</p>', '2022-11-30 00:00:00', 5, 437, 'https://images.blinkist.io/images/books/6380a0fdba31850008d6c47e/1_1/470.jpg', '/en/books/conversations-worth-having-en/purchase', 'گفتگوهایی-که-ارزش-داشتن-را-دارد', '2023-01-26 19:45:45.49948', '2023-01-26 19:45:45.49948', NULL, 'Conversations Worth Having');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (569, 'زندگی با سرعت نور', 'از مارپیچ دوگانه تا طلوع زندگی دیجیتال', 'از مارپیچ دوگانه تا طلوع زندگی دیجیتال', 22, 10, 'book', 't', '<p><em>زندگی در سرعت نور</em> (2013) شرح کار پیشگامانه نویسنده و تیمش در ایجاد اولین شکل زندگی مصنوعی در جهان است. با دنبال کردن کار پیشگامانه تیم در سنتز اولین ژنوم جهان و کاوش در انتقال از راه دور موجودات زنده، هیجان کشف را تجربه خواهید کرد.</p>', '2015-11-09 00:00:00', 5, 19, 'https://images.blinkist.io/images/books/564052163866330007000000/1_1/470.jpg', '/en/books/life-at-the-speed-of-light-en/purchase', 'زندگی-با-سرعت-نور', '2023-01-26 19:45:49.214192', '2023-01-26 19:45:49.214192', NULL, 'Life at the Speed of Light');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (570, 'از شما برای بحث متشکرم', 'آنچه ارسطو، لینکلن و هومر سیمپسون می توانند در مورد هنر متقاعدسازی به ما بیاموزند', 'آنچه ارسطو، لینکلن و هومر سیمپسون می توانند در مورد هنر متقاعدسازی به ما بیاموزند', 15, 7, 'book', 't', '<p><em>از شما برای بحث متشکرم</em> (2013) راهنمای هنر بلاغت است. این پلک‌ها توضیح می‌دهند که بلاغت واقعاً چیست، اقناع چگونه کار می‌کند و چگونه می‌توان با استفاده از تحقیقات عمیق، حکایات و نظریه‌های سخنوران بزرگ تاریخ، در یک بحث پیروز شد.</p>', '2016-04-21 00:00:00', 4, 161, 'https://images.blinkist.io/images/books/5714bba5344e1b0007a4c878/1_1/470.jpg', '/en/books/thank-you-for-arguing-en/purchase', 'از-شما-برای-بحث-متشکرم', '2023-01-26 19:45:53.974793', '2023-01-26 19:45:53.974793', NULL, 'Thank You for Arguing');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (571, 'کل30', 'راهنمای 30 روزه سلامت کامل و آزادی غذا', 'راهنمای 30 روزه سلامت کامل و آزادی غذا', 18, 8, 'book', 't', '<p><em>The Whole30 </em>(2015) یک برنامه غذایی با هدف بهبود سلامت و رفاه عمومی شما است. این مبتنی بر این ایده است که با حذف برخی از گروه های غذایی مضر و معرفی مجدد برخی دیگر، می توانید رژیم غذایی مناسب خود را پیدا کنید.</p>', '2018-02-27 00:00:00', 4, 65, 'https://images.blinkist.io/images/books/5a92795ab238e10006d0820f/1_1/470.jpg', '/en/books/the-whole30-en/purchase', 'کل30', '2023-01-26 19:45:59.116435', '2023-01-26 19:45:59.116435', NULL, 'The Whole30');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1572, 'چرا مدیران مهم هستند', 'خطرات شرکت بدون رئیس', 'خطرات شرکت بدون رئیس', 19, 5, 'book', 't', '<p><em>چرا مدیران اهمیت دارند</em> (2022) مزایا و معایب سبک‌های مختلف سازمانی شرکت را بیان می‌کند. این توضیح می دهد که چه زمانی و چرا یک شرکت ممکن است سلسله مراتب را در مقابل یک محیط بدون رئیس، بسته به گردش کار آن ترجیح دهد.</p>', '2022-12-19 00:00:00', 4, 154, 'https://images.blinkist.io/images/books/639c4198ac4463000945bfce/1_1/470.jpg', '/en/books/why-managers-matter-en/purchase', 'چرا-مدیران-مهم-هستند', '2023-01-27 02:49:17.494903', '2023-01-27 02:49:17.494903', NULL, 'Why Managers Matter');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (572, 'ماجراجویی در انسان', 'یک تور بزرگ از کرانیوم تا کالکانئوم', 'یک تور بزرگ از کرانیوم تا کالکانئوم', 21, 7, 'book', 't', '<p><em>Adventures in Human Being</em> (2015) نوعی راهنمای سفر آناتومیک است. مجموعه ای از تأملات فلسفی در مورد هر یک از اندام های اصلی بدن، این کتاب دیدگاه بالینی بدن را با داستان های منتخبی از تاریخ فرهنگی ما ترکیب می کند. نتیجه یک سری نشخوار فکری قابل توجه در مورد وضعیت انسان از زاویه غیر معمول آناتومی انسان است.</p>', '2020-03-31 00:00:00', 4, 70, 'https://images.blinkist.io/images/books/5e7de7876cee07000613d64a/1_1/470.jpg', '/en/books/adventures-in-human-being-en/purchase', 'ماجراجویی-در-انسان', '2023-01-26 19:46:04.382785', '2023-01-26 19:46:04.382785', NULL, 'Adventures in Human Being');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (573, 'کتاب مقدس فروش', 'منبع فروش نهایی', 'منبع فروش نهایی', 16, 9, 'book', 'f', '<p>برنامه مزیت فروش دیل کارنگی یکی از "ده کتابی که هر فروشنده باید داشته باشد و بخواند" در نظر گرفته شده است، <em></em> <em>کتاب مقدس فروش</em> (1994، اصلاح شده در سال 2015) یک کتاب کلاسیک است. موضوع استراتژی فروش این کتاب نگاهی عمیق به شیوه‌ها و تکنیک‌های فروش دارد که خود نویسنده برای دستیابی به موفقیت پایدار در فروش تسلط یافته است.</p>', '2015-03-25 00:00:00', 4, 149, 'https://images.blinkist.io/images/books/55102237666564000a630000/1_1/470.jpg', '/en/books/the-sales-bible-en/purchase', 'کتاب-مقدس-فروش', '2023-01-26 19:46:09.183613', '2023-01-26 19:46:09.183613', NULL, 'The Sales Bible');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (574, 'افسانه چندوظیفه ای', 'چگونه "انجام همه چیز" هیچ کاری انجام نمی دهد', 'چگونه "انجام همه چیز" هیچ کاری انجام نمی دهد', 12, 5, 'book', 't', '<p><em>افسانه چندوظیفگی</em> (2009) حقیقت مهمی را آشکار می‌کند: اینکه مفهوم چندوظیفه‌گی دروغی است که ما برای مدت طولانی آن را می‌خریم. حقیقت این است که ذهن انسان طوری ساخته نشده است که تمرکز خود را تقسیم کند و اگر می‌خواهید کار با کیفیت و به‌موقع و کارآمد انجام شود، باید کارها را یکی یکی انجام دهید.</p>', '2017-07-28 00:00:00', 4, 58, 'https://images.blinkist.io/images/books/5977927cb238e10005703396/1_1/470.jpg', '/en/books/the-myth-of-multitasking-en/purchase', 'افسانه-چندوظیفه-ای', '2023-01-26 19:46:14.150654', '2023-01-26 19:46:14.150654', NULL, 'The Myth of Multitasking');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (575, 'شرکت حکیم', 'چگونه شرکت ها نوآوری مستمر ایجاد می کنند', 'چگونه شرکت ها نوآوری مستمر ایجاد می کنند', 24, 8, 'book', 't', '<p><em>شرکت حکیم </em>(2019) دنباله‌ای بر کتاب تأثیرگذار نویسندگان <em>شرکت دانش‌آفرین</em> است. این تکنیک‌ها و شیوه‌های اجرای یک کسب‌وکار موفق را به قرن بیست و یکم می‌آورد، جایی که یک بازار سریع در حال تغییر و هرج و مرج یک امر عادی است.</p>', '2020-11-20 00:00:00', 4, 59, 'https://images.blinkist.io/images/books/5fb2451f6cee070006bb475a/1_1/470.jpg', '/en/books/the-wise-company-en/purchase', 'شرکت-حکیم', '2023-01-26 19:46:19.247115', '2023-01-26 19:46:19.247115', NULL, 'The Wise Company');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (576, 'سازگار شدن', 'چرا موفقیت همیشه با شکست شروع می شود؟', 'چرا موفقیت همیشه با شکست شروع می شود؟', 16, 9, 'book', 'f', '<p>جهان پیچیده و غیرقابل پیش بینی است، از عملکرد درونی توستر فروتن گرفته تا مشکلات بی شماری که وجود بشر با آن مواجه است. به جای استفاده از ابزارهای سنتی برای برخورد با مشکلات و مدیریت سازمان ها، باید از آزمون و خطا استفاده کنیم. تنها با آزمایش، زنده ماندن از شکست های اجتناب ناپذیر و تجزیه و تحلیل خود شکست ها، قادر خواهیم بود خود را با محیط های پیچیده و متغیری که در آن قرار داریم وفق دهیم.</p>', '2014-10-30 00:00:00', 4, 16, 'https://images.blinkist.io/images/books/544f8abb376133000a080000/1_1/470.jpg', '/en/books/adapt-en/purchase', 'سازگار-شدن', '2023-01-26 19:46:23.82069', '2023-01-26 19:46:23.82069', NULL, 'Adapt');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (577, 'حضور اجرایی', 'حلقه مفقوده بین شایستگی و موفقیت', 'حلقه مفقوده بین شایستگی و موفقیت', 17, 7, 'book', 't', '<p><em>حضور اجرایی</em> (2014) اجزای اساسی یک رهبر واقعی را آشکار می کند. از نگرش به ارتباطات گرفته تا ظاهر، تأثیرگذارترین رهبران امروزی نکات و مثال‌های عملی را به اشتراک می‌گذارند تا شما را در ایجاد حضوری قدرتمند و متقاعدکننده هر روز راهنمایی کنند.</p>', '2015-11-11 00:00:00', 4, 164, 'https://images.blinkist.io/images/books/56407b2138663300074e0000/1_1/470.jpg', '/en/books/executive-presence-en/purchase', 'حضور-اجرایی', '2023-01-26 19:46:28.287089', '2023-01-26 19:46:28.287089', NULL, 'Executive Presence');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (578, 'طول عمر', 'چرا ما پیر می شویم - و چرا مجبور نیستیم', 'چرا ما پیر می شویم - و چرا مجبور نیستیم', 24, 8, 'book', 't', '<p><em>Lifespan </em>(2019) به تحقیقات ژنتیکی پیشرفته می پردازد و نظریه های جدیدی را در مورد اینکه چرا پیر می شویم و چگونه می توانیم به طور کلی از پیری جلوگیری کنیم، ارائه می دهد. از تحقیقات آزمایشگاهی با فناوری پیشرفته گرفته تا استراتژی‌های تغذیه‌ای ساده، به عنوان راهنمای روش‌های متنوعی عمل می‌کند که در حال حاضر می‌توانیم یا به زودی می‌توانیم زندگی طولانی‌تر و بهتری داشته باشیم.</p>', '2021-02-27 00:00:00', 5, 416, 'https://images.blinkist.io/images/books/60337a006cee070007cf1808/1_1/470.jpg', '/en/books/lifespan-en/purchase', 'طول-عمر', '2023-01-26 19:46:33.228344', '2023-01-26 19:46:33.228344', NULL, 'Lifespan ');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (579, 'عادت رهبر', 'مهارت هایی را که باید در روز تنها در چند دقیقه رهبری کنید، تسلط پیدا کنید', 'مهارت هایی را که باید در روز تنها در چند دقیقه رهبری کنید، تسلط پیدا کنید', 19, 6, 'book', 't', '<p><em>عادت رهبر</em> (2018) رویکردی به توسعه رهبری را شرح می‌دهد که یادگیری تمرینی و عادتی را به یادگیری تکه‌ای دانش ترجیح می‌دهد. با نگاهی به روش‌های ایجاد عادت‌ها، و با تجزیه مهارت‌های لازم برای رهبری موفق به <em>رفتارهای خرد</em>، این پلک‌ها ساختاری برای تبدیل شدن به یک رهبر بهتر از طریق تمرین‌های آموزشی کوتاه ارائه می‌دهند.</p>', '2019-04-22 00:00:00', 4, 108, 'https://images.blinkist.io/images/books/5cbcca206cee070008bad256/1_1/470.jpg', '/en/books/the-leader-habit-en/purchase', 'عادت-رهبر', '2023-01-26 19:46:38.052741', '2023-01-26 19:46:38.052741', NULL, 'The Leader Habit');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (580, 'شما را مختل کند!', 'تسلط بر تحول شخصی، استفاده از فرصت ها و شکوفایی در عصر نوآوری بی پایان', 'تسلط بر تحول شخصی، استفاده از فرصت ها و شکوفایی در عصر نوآوری بی پایان', 20, 6, 'book', 't', '<p><em>تو را مختل کند! </em>(2015) یک راهنمای کارآفرین برای هدایت نوآوری و تأثیر است. این کتاب از برخی از بزرگترین داستان های موفقیت در تجارت استفاده می کند و نکات عملی را برای حل مشکلات دنیای واقعی و یافتن فرصت در هنگام شکست ارائه می دهد. </p>', '2021-08-02 00:00:00', 5, 246, 'https://images.blinkist.io/images/books/6102b8956cee070007d9f43f/1_1/470.jpg', '/en/books/disrupt-you-en/purchase', 'شما-را-مختل-کند!', '2023-01-26 19:46:42.865709', '2023-01-26 19:46:42.865709', NULL, 'Disrupt You!');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (581, 'روباه', 'تاریخ فرهنگی این حیوان عرفانی', 'تاریخ فرهنگی این حیوان عرفانی', 10, 4, 'book', 't', '<p> توضیح ساده حیوان شگفت‌انگیز معروف به روباه از نظر بیولوژیکی درست نیست. این حیوان اسرارآمیز از دیرباز موضوع داستان‌ها و افسانه‌های بی‌شماری بوده و فرهنگ‌ها در سراسر جهان درک منحصر به فرد خود را از این حیوان توسعه داده‌اند. <em>روباه</em> (2006) در این افسانه‌ها و داستان‌های فراوان فرو می‌رود و همچنین نشان می‌دهد که چگونه روباه همچنان بر زبان و فرهنگ ما تأثیر می‌گذارد.</p>', '2016-08-12 00:00:00', 4, 11, 'https://images.blinkist.io/images/books/57a8da241c2e11000357fb00/1_1/470.jpg', '/en/books/fox-en/purchase', 'روباه', '2023-01-26 19:46:48.208582', '2023-01-26 19:46:48.208582', NULL, 'Fox');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (582, 'پرسش فروتن', 'هنر ملایم پرسیدن به جای گفتن', 'هنر ملایم پرسیدن به جای گفتن', 15, 7, 'book', 't', '<p><em>حساب فروتنی</em> (2013) اصول اساسی هنر پرسیدن سؤالات درست به روش صحیح را بیان می کند. این بررسی می کند که چگونه رویکرد شما به تحقیق بر روابط شما در دفتر، توانایی شما برای تکمیل کار با کیفیت و در نهایت موفقیت شما به عنوان یک رهبر تأثیر می گذارد.</p>', '2014-12-01 00:00:00', 4, 57, 'https://images.blinkist.io/images/books/547c81a16363300009d30300/1_1/470.jpg', '/en/books/humble-inquiry-en/purchase', 'پرسش-فروتن', '2023-01-26 19:46:53.114329', '2023-01-26 19:46:53.114329', NULL, 'Humble Inquiry');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (583, 'به تعویق انداختن هدف', '5 مجوز برای چند برابر کردن زمان', '5 مجوز برای چند برابر کردن زمان', 19, 7, 'book', 't', '<p><em>به تعویق انداختن هدف</em>(2019) تکنیک های قدرتمند و در عین حال ساده ای را برای صرفه جویی در زمان و هزینه ارائه می دهد. این پلک‌ها با توصیه‌های مستقیم، چگونگی فرار از مشغله مداوم را روشن می‌کنند. آنها نشان می دهند که چگونه می توان بهره وری را با سبک کردن برنامه خود و تمرکز صرف بر روی اولویت های خود افزایش داد.</p>', '2019-09-26 00:00:00', 4, 332, 'https://images.blinkist.io/images/books/5d89dc116cee0700095f1a33/1_1/470.jpg', '/en/books/procrastinate-on-purpose-en/purchase', 'به-تعویق-انداختن-هدف', '2023-01-26 19:46:58.105957', '2023-01-26 19:46:58.105957', NULL, 'Procrastinate on Purpose');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (584, 'زندگی درهم تنیده', 'چگونه قارچ ها جهان ما را می سازند، ذهن ما را تغییر می دهند و آینده ما را شکل می دهند', 'چگونه قارچ ها جهان ما را می سازند، ذهن ما را تغییر می دهند و آینده ما را شکل می دهند', 26, 8, 'book', 't', '<p><em>Entangled Life </em>(2020) ما را به دنیای وسیع و پنهان قارچ ها می برد. در آن، ما کپک‌ها، مخمرها، گلسنگ‌ها و بسیاری از قارچ‌های دیگر را دنبال می‌کنیم که در خاک خزش می‌کنند، ما را با رایحه‌شان مست می‌کنند و دید مسحورکننده‌ای را القا می‌کنند. با تغییر در دیدگاه، می‌توانیم جهان را از دیدگاه قارچی‌تری ببینیم - و بفهمیم که چگونه این موجودات ممکن است کلید بقای آینده ما باشند.</p>', '2020-12-26 00:00:00', 5, 107, 'https://images.blinkist.io/images/books/5fda40d96cee070007356fd9/1_1/470.jpg', '/en/books/entangled-life-en/purchase', 'زندگی-درهم-تنیده', '2023-01-26 19:47:03.162885', '2023-01-26 19:47:03.162885', NULL, 'Entangled Life');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (585, 'رئیس شدن', 'قوانین جدید برای نسل بعدی رهبران', 'قوانین جدید برای نسل بعدی رهبران', 14, 7, 'book', 't', '<p><em>رئیس شدن</em> موانع بالقوه برای رهبران در عصر مدرن ما و چند نکته مفید در مورد نحوه مقابله با آنها را ارائه می دهد. پولاک برخی از اصول اساسی را توضیح می دهد که به هر کسی کمک می کند تا نه تنها یک رهبر شود، بلکه در نقش جدید خود برتر باشد. پولاک همچنین برخی از بهترین شیوه های جدید را برای مدیریت کارمندان خلاصه می کند و در مورد شبکه سازی حرفه ای و رشد شخصی توصیه می کند.</p>', '2015-02-02 00:00:00', 4, 29, 'https://images.blinkist.io/images/books/54cf8171323335000a100000/1_1/470.jpg', '/en/books/becoming-the-boss-en/purchase', 'رئیس-شدن', '2023-01-26 19:47:07.779952', '2023-01-26 19:47:07.779952', NULL, 'Becoming the Boss');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (586, 'اثر Alter Ego', 'قدرت هویت های مخفی برای متحول کردن زندگی شما', 'قدرت هویت های مخفی برای متحول کردن زندگی شما', 24, 8, 'book', 't', '<p><em>اثر Alter Ego </em>(2019) راهنمای دستیابی به اهداف شما از طریق استفاده از alter ego است. با نمونه‌های متعددی از افراد موفقی که خود را تغییر داده‌اند، راهبردهای واضح و عملی برای موفقیت در هر زمینه‌ای از زندگی ارائه می‌دهد.</p>', '2021-05-31 00:00:00', 5, 82, 'https://images.blinkist.io/images/books/60ae75e86cee0700084a2c43/1_1/470.jpg', '/en/books/the-alter-ego-effect-en/purchase', 'اثر-Alter-Ego', '2023-01-26 19:47:12.712184', '2023-01-26 19:47:12.712184', NULL, 'The Alter Ego Effect');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (587, 'چیزی جز نت', '10 درس بی انتها برای انتخاب سهام فناوری', '10 درس بی انتها برای انتخاب سهام فناوری', 19, 7, 'book', 't', '<p><em>هیچ چیز جز خالص </em>(2021) یک راهنمای عملی برای انتخاب سهام فناوری برای سرمایه گذاران است. ماهانی بر اساس سال ها تجربه خود به عنوان تحلیلگر فناوری وال استریت، بایدها و نبایدهای انتخاب شرکت ها را برای سرمایه گذاری بیان می کند. اگرچه دنیای سهام غیرقابل پیش بینی است، روش های اثبات شده ای وجود دارد که هر سرمایه گذار می تواند از آنها برای موفقیت بیشتر استفاده کند. </p>', '2022-05-20 00:00:00', 4, 129, 'https://images.blinkist.io/images/books/62850ea96cee0700083874d4/1_1/470.jpg', '/en/books/nothing-but-net-en/purchase', 'چیزی-جز-نت', '2023-01-26 19:47:17.391454', '2023-01-26 19:47:17.391454', NULL, 'Nothing But Net');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (588, 'بیوگرافی قبل از خواب: اسحاق نیوتن', 'حقیقت پشت افسانه را بیاموزید', 'حقیقت پشت افسانه را بیاموزید', 30, 5, 'book', 't', '<p><strong>روایت شده توسط </strong><strong>Cathleen McCarron</strong></p>
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (589, 'چهره های پنهان', 'رویای آمریکایی و داستان ناگفته ریاضیدانان زن سیاه پوست که به پیروزی در مسابقه فضایی کمک کردند', 'رویای آمریکایی و داستان ناگفته ریاضیدانان زن سیاه پوست که به پیروزی در مسابقه فضایی کمک کردند', 13, 5, 'book', 't', '<p><em>Hidden Figures</em> (2016) داستان ناگفته ریاضیدانان زن سیاهپوستی را نشان می دهد که به ارسال جان گلن در اولین مدار خود به دور زمین و نیل آرمسترانگ به ماه کمک کردند. این زنان شجاع و پیشرو با ترک شغل معلمی خود در مدارس جدا شده جنوب و کمک به شکل دادن به برنامه فضایی مدرن به ندای وظیفه پاسخ دادند.</p>', '2017-06-12 00:00:00', 5, 40, 'https://images.blinkist.io/images/books/593e4dbeb238e100051fdd93/1_1/470.jpg', '/en/books/hidden-figures-en/purchase', 'چهره-های-پنهان', '2023-01-26 19:47:25.413485', '2023-01-26 19:47:25.413485', NULL, 'Hidden Figures');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (590, '2 ساعت اول', 'از با ارزش ترین زمان خود بهتر استفاده کنید', 'از با ارزش ترین زمان خود بهتر استفاده کنید', 14, 6, 'book', 't', '<p><em>The First 2 Hours</em>(2019) یک راهنمای طراحی است که باید بخوانید تا یاد بگیرید چگونه روز کاری خود را بازنگری و بهینه کنید. در حالی که همه ما مملو از ایمیل‌ها و دعوت‌نامه‌های رویداد هستیم، این همه شلوغی با بهره‌وری برابری نمی‌کند. <em>۲ ساعت اول</em> هم تحقیقات علمی و هم درک ریتم‌های بدن را ترکیب می‌کند تا به شما کمک کند ساختار زندگی کاری خود را دوباره طراحی کنید.</p>', '2021-02-05 00:00:00', 4, 156, 'https://images.blinkist.io/images/books/6012eac16cee070007f48112/1_1/470.jpg', '/en/books/the-first-2-hours-en/purchase', '2-ساعت-اول', '2023-01-26 19:47:30.496123', '2023-01-26 19:47:30.496123', NULL, 'The First 2 Hours');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (591, 'عامل قهرمان', 'چگونه رهبران بزرگ سازمان ها را تغییر می دهند و فرهنگ های برنده ایجاد می کنند', 'چگونه رهبران بزرگ سازمان ها را تغییر می دهند و فرهنگ های برنده ایجاد می کنند', 19, 6, 'book', 't', '<p><em>The Hero Factor</em>(2018) توضیح می‌دهد که چرا رهبران کسب‌وکار باید به همان اندازه که روی سود خود تمرکز می‌کنند، روی افراد خود نیز تمرکز کنند. نویسندگان با استفاده از مثال‌های دنیای واقعی و الهام‌بخش داستان‌های واقعی موفقیت، معنای واقعی رهبری قهرمانانه در محل کار را بررسی می‌کنند.</p>', '2019-01-29 00:00:00', 4, 55, 'https://images.blinkist.io/images/books/5c4dfcca6cee07000731781a/1_1/470.jpg', '/en/books/the-hero-factor-en/purchase', 'عامل-قهرمان', '2023-01-26 19:47:35.53262', '2023-01-26 19:47:35.53262', NULL, 'The Hero Factor');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (592, 'بهبود رابطه شما برای آدمک ها', 'راهنمای عملی و عملی برای زوج ها', 'راهنمای عملی و عملی برای زوج ها', 21, 9, 'book', 't', '<p><em>بهبود رابطه شما برای آدمک‌ها</em> (2010) تکنیک‌های ساده‌ای را برای زوج‌هایی ارائه می‌کند که امیدوارند صمیمیت خود را تقویت کنند، ارتباطات خود را تیزتر کنند و بر چالش‌ها به روشی سازنده و سالم غلبه کنند. هم برای زوج‌های جدید که می‌خواهند با پای راست شروع کنند و هم برای زوج‌های بلندمدتی که امیدوارند اوضاع را به مسیر درست برگردانند، توصیه‌هایی ارائه می‌کند.</p>', '2016-06-16 00:00:00', 4, 64, 'https://images.blinkist.io/images/books/5759399f496d1c0003e862b0/1_1/470.jpg', '/en/books/improving-your-relationship-for-dummies-en/purchase', 'بهبود-رابطه-شما-برای-آدمک-ها', '2023-01-26 19:47:40.408796', '2023-01-26 19:47:40.408796', NULL, 'Improving Your Relationship For Dummies');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (593, 'رژیم ضد گلوله', 'تا یک پوند در روز کم کنید، انرژی و تمرکز خود را بازیابی کنید، زندگی خود را ارتقا دهید', 'تا یک پوند در روز کم کنید، انرژی و تمرکز خود را بازیابی کنید، زندگی خود را ارتقا دهید', 21, 9, 'book', 't', '<p><em>رژیم غذایی ضد گلوله</em> (2014) به شما نشان می دهد که چگونه بدن خود را هک کنید تا سلامت خود را بهینه کنید، وزن خود را کاهش دهید و عملکرد ذهنی خود را افزایش دهید. چگونه؟ یک رژیم غذایی پر از پروتئین و چربی مناسب داشته باشید و یاد بگیرید که به موثرترین شکل ممکن ورزش کنید و بخوابید.</p>', '2015-07-07 00:00:00', 4, 285, 'https://images.blinkist.io/images/books/559bbd4f3966610007010000/1_1/470.jpg', '/en/books/bulletproof-diet-en/purchase', 'رژیم-ضد-گلوله', '2023-01-26 19:47:45.231609', '2023-01-26 19:47:45.231609', NULL, 'Bulletproof Diet');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (594, 'Undying', 'درد، آسیب پذیری، مرگ و میر، پزشکی، هنر، زمان، رویاها، داده ها، خستگی، سرطان و مراقبت', 'درد، آسیب پذیری، مرگ و میر، پزشکی، هنر، زمان، رویاها، داده ها، خستگی، سرطان و مراقبت', 19, 6, 'book', 't', '<p><em>The Undying </em> (2019) روایتی شاعرانه و غم انگیز از سفر نویسنده در یک نوع تهاجمی سرطان سینه است. این همچنین ارزیابی موجی از تجربه زنان از این بیماری، در تاریخ و ادبیات، و همچنین در ایالات متحده کنونی است. </p>', '2020-06-22 00:00:00', 4, 131, 'https://images.blinkist.io/images/books/5eebd7946cee070006a75360/1_1/470.jpg', '/en/books/the-undying-en/purchase', 'Undying', '2023-01-26 19:47:50.196445', '2023-01-26 19:47:50.196445', NULL, 'The Undying');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (595, 'دلایل طبیعی', 'اپیدمی سلامتی، اطمینان از مردن، و خودکشی برای زندگی بیشتر', 'اپیدمی سلامتی، اطمینان از مردن، و خودکشی برای زندگی بیشتر', 15, 6, 'book', 't', '<p><em>علت طبیعی</em>es (2018) حقیقتی را که در پس تشویق دنیای پزشکی از روش‌ها، درمان‌ها و غربالگری‌های رایج وجود دارد، آشکار می‌کند. این مقاله به بررسی دقیق چرایی بیزاری جامعه غربی از پیری و وسواس ورزش کردن می پردازد و در طول مسیر، تأثیرات مدرنیته بر توانایی های ذهنی ما را بررسی می کند.</p>', '2018-07-13 00:00:00', 3, 63, 'https://images.blinkist.io/images/books/5b4759dfb238e10007b7ec83/1_1/470.jpg', '/en/books/natural-causes-en/purchase', 'دلایل-طبیعی', '2023-01-26 19:47:55.121547', '2023-01-26 19:47:55.121547', NULL, 'Natural Causes');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (596, 'چگونه ادبیات را مانند یک استاد بخوانیم', 'راهنمای سرزنده و سرگرم کننده برای خواندن بین خطوط', 'راهنمای سرزنده و سرگرم کننده برای خواندن بین خطوط', 15, 6, 'book', 't', '<p><em>چگونه ادبیات را مانند یک استاد بخوانیم</em> (2003) مقدمه ای در دسترس و جذاب برای تحلیل ادبی است. این پلک‌ها با مثال‌های روشن‌کننده برگرفته از ادبیات کلاسیک و معاصر، ابزارهایی را در اختیار خوانندگان قرار می‌دهند که برای تشخیص معنای عمیق‌تر در هر متن داستانی نیاز دارند.</p>', '2015-11-16 00:00:00', 4, 60, 'https://images.blinkist.io/images/books/5649f7de66343100071d0000/1_1/470.jpg', '/en/books/how-to-read-literature-like-a-professor-en/purchase', 'چگونه-ادبیات-را-مانند-یک-استاد-بخوانیم', '2023-01-26 19:48:00.264515', '2023-01-26 19:48:00.264515', NULL, 'How To Read Literature Like A Professor');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (597, 'خدا اینجا و اکنون', 'نشخوار فکری درباره اصول اعتقاد مسیحی', 'نشخوار فکری درباره اصول اعتقاد مسیحی', 21, 5, 'book', 't', '<p><em>خدا اینجا و اکنون</em> (1964) مجموعه ای از آدرس ها و مقالاتی است که اصول اساسی مسیحیت را از دیدگاه یک الهیدان پروتستان بررسی می کند. این کتاب با پوشش انجیل، ایمان، فیض، کتاب مقدس، کلیسا، اخلاق و انسان گرایی، سؤالاتی را در مورد معنای ملاقات با خدا در دنیای امروز مطرح می کند.</p>', '2022-09-11 00:00:00', 4, 141, 'https://images.blinkist.io/images/books/63175e756cee07000882ebd9/1_1/470.jpg', '/en/books/god-here-and-now-en/purchase', 'خدا-اینجا-و-اکنون', '2023-01-26 19:48:05.163499', '2023-01-26 19:48:05.163499', NULL, 'God Here and Now');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (598, 'قوانین طلایی ناپلئون هیل', 'نوشته های گمشده', 'نوشته های گمشده', 20, 8, 'book', 't', '<p><em>قوانین طلایی ناپلئون هیل</em> (2009) مجموعه گسترده ای از نکات و هک های زندگی را برای بهبود زندگی شما و نزدیکتر کردن شما به تحقق اهدافتان ارائه می دهد. نویسنده ناپلئون هیل تکنیک‌های خود را - که بسیاری از آنها از قدرت تفکر مثبت نشات می‌گیرند - تقریباً یک قرن پیش توسعه داد، اما هنوز هم سنگ بنای بسیاری از نظریه‌های خودیاری و توسعه شخصی امروزی هستند.</p>', '2018-09-28 00:00:00', 5, 264, 'https://images.blinkist.io/images/books/5bab5587862c43000738128d/1_1/470.jpg', '/en/books/napoleon-hills-golden-rules-en/purchase', 'قوانین-طلایی-ناپلئون-هیل', '2023-01-26 19:48:09.7823', '2023-01-26 19:48:09.7823', NULL, 'Napoleon Hill’s Golden Rules');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (599, 'قدرت پایین دولت', 'علم جدید برای مشتعل کردن انرژی، افزایش وضوح و بازیابی تعادل', 'علم جدید برای مشتعل کردن انرژی، افزایش وضوح و بازیابی تعادل', 22, 4, 'book', 't', '<p><em>Power of the Downstate </em>(2022) روش جدیدی برای نگاه کردن به نحوه خواب، غذا خوردن، ورزش و آرامش ارائه می دهد. با تکیه بر تحقیقات پیشگامانه نویسنده از آزمایشگاه خواب و شناخت او، نکاتی مبتنی بر شواهد در مورد چگونگی احساس انرژی بیشتر، استرس کمتر و بهترین عملکرد ارائه می دهد.</p>', '2022-09-15 12:00:00', 5, 400, 'https://images.blinkist.io/images/books/63205e006cee070008aacb39/1_1/470.jpg', '/en/books/the-power-of-the-downstate-en/purchase', 'قدرت-پایین-دولت', '2023-01-26 19:48:15.0042', '2023-01-26 19:48:15.0042', NULL, 'The Power of the Downstate');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (600, 'بدون فیلتر', 'استراتژی های اثبات شده برای شروع و رشد کسب و کار خود با رعایت نکردن قوانین', 'استراتژی های اثبات شده برای شروع و رشد کسب و کار خود با رعایت نکردن قوانین', 17, 7, 'book', 't', '<p><em>Unfiltered </em> (2022) یک کتابچه راهنمای کسب و کار عملی را با سفر الهام بخش راشل پدرسن از یک مادر مجرد در امور رفاهی تا مدیرعاملی دو شرکت چند میلیون دلاری ترکیب می کند. پدرسن با استفاده از چالش‌هایی که با آن مواجه شده و درس‌هایی که در این راه آموخته است، ابزارهایی را در اختیار کارآفرینان مشتاق قرار می‌دهد تا کسب‌وکار رویایی‌شان را با شرایط خودشان شروع کنند و رشد دهند.</p>', '2023-01-16 00:00:00', 4, 10, 'https://images.blinkist.io/images/books/63be9776e8fd3c00080b4126/1_1/470.jpg', '/en/books/unfiltered-en/purchase', 'بدون-فیلتر', '2023-01-26 19:48:20.093478', '2023-01-26 19:48:20.093478', NULL, 'Unfiltered');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (601, 'فروش با هدف شریف', 'چگونه درآمد کسب کنید و کاری را انجام دهید که باعث افتخار شما می شود', 'چگونه درآمد کسب کنید و کاری را انجام دهید که باعث افتخار شما می شود', 19, 8, 'book', 't', '<p><em>فروش با هدف نجیب </em>(2013) در مورد یافتن تعادل مناسب بین کسب درآمد و انجام کاری معنادار در زندگی شما است. به شما این امکان را می دهد که با تمرکز بر نیت خود بر روی مشتری و نحوه بهره مندی آنها از محصول شما، کار خود را دوباره چارچوب بندی کنید. این دیدگاهی است که کارکنان را شادتر، با انگیزه تر و موثرتر نگه می دارد. فروش نباید بر سود و طمع متمرکز باشد. همچنین می تواند در مورد تبدیل جهان به مکانی بهتر باشد.</p>', '2017-07-07 00:00:00', 4, 21, 'https://images.blinkist.io/images/books/595a326cb238e10007cd509b/1_1/470.jpg', '/en/books/selling-with-noble-purpose-en/purchase', 'فروش-با-هدف-شریف', '2023-01-26 19:48:25.077513', '2023-01-26 19:48:25.077513', NULL, 'Selling with Noble Purpose');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (602, 'خواندن مانند یک نویسنده', 'راهنمایی برای افرادی که عاشق کتاب هستند و برای کسانی که می خواهند آنها را بنویسند', 'راهنمایی برای افرادی که عاشق کتاب هستند و برای کسانی که می خواهند آنها را بنویسند', 18, 7, 'book', 't', '<p><em>Reading Like a Writer</em> (2006) به ما نشان می دهد که چگونه شاهکارهای ادبی را با چشمانی باز بخوانیم. این پلک‌ها الگوهای نوشتن را توضیح می‌دهند که داستان‌های داستانی را به یاد ماندنی، قدرتمند و معتبر می‌سازند و به ما کمک می‌کنند سرعت مطالعه‌مان را کاهش دهیم و در هر کتاب تجربیات لذت‌بخش‌تری پیدا کنیم.</p>', '2016-07-07 00:00:00', 4, 73, 'https://images.blinkist.io/images/books/577548db3588860003e82440/1_1/470.jpg', '/en/books/reading-like-a-writer-en/purchase', 'خواندن-مانند-یک-نویسنده', '2023-01-26 19:48:29.795817', '2023-01-26 19:48:29.795817', NULL, 'Reading Like a Writer');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (603, 'جزایر گنج', 'بهشت های مالیاتی و مردانی که دنیا را دزدیدند', 'بهشت های مالیاتی و مردانی که دنیا را دزدیدند', 16, 7, 'book', 't', '<p><em>جزایر گنج</em> بینشی را در مورد یکی از تاریک ترین بخش های دنیای مالی ارائه می دهد: بهشت ​​های مالیاتی. این توضیح می‌دهد که چگونه افراد و شرکت‌های ثروتمند می‌توانند با انتقال دارایی‌های خود به خارج از کشور از پرداخت مالیات اجتناب کنند. پناهگاه های مالیاتی برای همه افراد به جز درصد اندکی از افرادی که توانایی مالی استفاده از آنها را دارند، بسیار مضر است و به شکاف فزاینده بین فقیر و غنی کمک می کند.</p>', '2015-03-10 00:00:00', 5, 21, 'https://images.blinkist.io/images/books/54fdbba3626661000a080000/1_1/470.jpg', '/en/books/treasure-islands-en/purchase', 'جزایر-گنج', '2023-01-26 19:48:35.558896', '2023-01-26 19:48:35.558896', NULL, 'Treasure Islands');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (604, 'ابرقدرت تصادفی', 'نسل بعدی برتری آمریکا و اختلال جهانی آینده', 'نسل بعدی برتری آمریکا و اختلال جهانی آینده', 16, 7, 'book', 't', '<p>امروز، ایالات متحده به عنوان <em></em> ابرقدرت جهانی دارای دژی مستحکم است، اما جهان با سرعتی بی‌سابقه در حال تغییر است. این پلک ها دلایلی را که ایالات متحده از نظر سیاسی و اقتصادی بر سیاره سیاره تسلط یافت و آنچه را که می توانیم در دهه های آینده چه در ایالات متحده و چه در جهان به طور کلی انتظار داشته باشیم، نشان می دهد.</p>', '2016-06-02 00:00:00', 4, 107, 'https://images.blinkist.io/images/books/5746ddf9b49ff200039c4dcc/1_1/470.jpg', '/en/books/the-accidental-superpower-en/purchase', 'ابرقدرت-تصادفی', '2023-01-26 19:48:40.431141', '2023-01-26 19:48:40.431141', NULL, 'The Accidental Superpower');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (605, 'مدیریت تا', 'چگونه با هر نوع رئیسی به سمت بالا حرکت کنیم، در محل کار پیروز شویم و موفق شویم', 'چگونه با هر نوع رئیسی به سمت بالا حرکت کنیم، در محل کار پیروز شویم و موفق شویم', 20, 7, 'book', 't', '<p><em>Managing Up</em> (2018) راه‌هایی را برای بهبود رابطه شما با رئیستان بررسی می‌کند. استراتژی‌های مؤثر برای مقابله با هر نوع مدیری را نشان می‌دهد، توضیح می‌دهد که چگونه می‌توانید با رهبران دشوار کنار بیایید و چگونه یک رئیس بد را به فرصتی عالی برای رشد حرفه‌ای تبدیل کنید. </p>', '2019-10-21 00:00:00', 4, 116, 'https://images.blinkist.io/images/books/5da9b7826cee0700074e3a7f/1_1/470.jpg', '/en/books/managing-up-en/purchase', 'مدیریت-تا', '2023-01-26 19:48:45.904112', '2023-01-26 19:48:45.904112', NULL, 'Managing Up');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (606, 'تغییر بر اساس طراحی', 'چگونه تفکر طراحی سازمان ها را متحول می کند و الهام بخش نوآوری می شود', 'چگونه تفکر طراحی سازمان ها را متحول می کند و الهام بخش نوآوری می شود', 17, 7, 'book', 't', '<p><em>Change by Design </em>(2009) رویکردی جامع و بین رشته ای را برای طراحی راه حل هایی برای مقابله با هر نوع چالش نوآوری ارائه می دهد. با دنبال کردن این راهنمای گام به گام، می‌توانید داستان‌ها و الهام‌هایی را که منجر به نوآوری‌های فردا می‌شوند، خلاقانه‌تر توسعه دهید.</p>', '2015-04-08 00:00:00', 4, 123, 'https://images.blinkist.io/images/books/552465693066650007450000/1_1/470.jpg', '/en/books/change-by-design-en/purchase', 'تغییر-بر-اساس-طراحی', '2023-01-26 19:48:50.726083', '2023-01-26 19:48:50.726083', NULL, 'Change by Design');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (607, '20 ساعت اول', 'چگونه هر چیزی را یاد بگیریم… سریع', 'چگونه هر چیزی را یاد بگیریم… سریع', 12, 6, 'book', 't', '<p><em>20 ساعت اول </em>(2013) درباره یادگیری سریع مهارت های جدید است. این پلک زدن ها به شما کمک می کند این تصور را از خود دور کنید که برای گسترش افق های خود خیلی دیر شده است. چه بخواهید به یک زبان خارجی تسلط داشته باشید و چه می خواهید پرواز با هلیکوپتر را بیاموزید، در اینجا ده مرحله ساده برای شروع آورده شده است.</p>', '2018-02-21 00:00:00', 4, 226, 'https://images.blinkist.io/images/books/5a88cfd7b238e1000705417a/1_1/470.jpg', '/en/books/the-first-20-hours-en/purchase', '20-ساعت-اول', '2023-01-26 19:48:55.600487', '2023-01-26 19:48:55.600487', NULL, 'The First 20 Hours');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (608, 'همه، همیشه', 'تبدیل شدن به عشق در دنیایی پر از شکست و افراد دشوار', 'تبدیل شدن به عشق در دنیایی پر از شکست و افراد دشوار', 19, 7, 'book', 't', '<p><em>همه، همیشه</em> (2018) داستان الهام بخش باب گاف، نویسنده پرفروش، ماموریت تک نفره برای ترجمه پیام عشق و شفقت عیسی مسیح به تمرین روزمره را شرح می دهد. همانطور که خودش اعتراف می کند، همیشه آسان نیست. زندگی پر از شکست، موانع و افراد دشوار است. اما <em>امکان پذیر است. گاف با وفادار ماندن به اعتقاداتش و یافتن جسارت در زمان سخت شدن، تلاش می‌کند تا یک زندگی عاشقانه مثال زدنی داشته باشد.</p>', '2018-07-18 00:00:00', 5, 46, 'https://images.blinkist.io/images/books/5b4e8bf3b238e10007b7ece7/1_1/470.jpg', '/en/books/everybody-always-en/purchase', 'همه،-همیشه', '2023-01-26 19:48:59.15139', '2023-01-26 19:48:59.15139', NULL, 'Everybody, Always');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (609, 'کاتالیزور', 'استراتژی های نهایی در مورد چگونگی برنده شدن در کار و زندگی', 'استراتژی های نهایی در مورد چگونگی برنده شدن در کار و زندگی', 21, 8, 'book', 't', '<p><em>Catalyst</em> (2018) راهنمای نهایی A تا Z برای پیمایش در یکی از پیچیده‌ترین سفرهای زندگی است: شغل شما. مملو از بینش‌های عملی که ریشه در سال‌ها تجربه دست اول نویسنده Chandramouli Venkatesan با موفق‌ترین شرکت‌های بزرگ امروزی دارد، این پلک‌ها موضوعات کلیدی را از انتخاب رئیس مناسب تا ارزش آهسته بودن و تبدیل شدن به یک رهبر مؤثر روشن می‌کند. .</p>', '2019-05-17 00:00:00', 4, 92, 'https://images.blinkist.io/images/books/5cdc78636cee0700086a9a98/1_1/470.jpg', '/en/books/catalyst-en/purchase', 'کاتالیزور', '2023-01-26 19:49:04.020459', '2023-01-26 19:49:04.020459', NULL, 'Catalyst');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (610, 'دم دراز', 'چرا آینده کسب و کار فروش کمتر و بیشتر است؟', 'چرا آینده کسب و کار فروش کمتر و بیشتر است؟', 22, 10, 'book', 't', '<p><em>The Long Tail</em> با نگاهی به تأثیر گسترده اینترنت بر اقتصاد، مفاهیم موجود از بازار و صنعت سرگرمی را به چالش می‌کشد. با توجه به شیوه‌های جدید ایجاد و توزیع محتوا، ارائه تعداد زیادی و طیف گسترده‌ای از محصولات که برای گروه‌های مصرف‌کننده خاص جذاب باشد، به جای یک «موتور» خاص، مانند یک کتاب پرفروش یا پرفروش، می‌تواند سودآورتر باشد.</p >
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (611, 'هوش مشارکتی', 'فکر کردن با افرادی که متفاوت فکر می کنند', 'فکر کردن با افرادی که متفاوت فکر می کنند', 19, 9, 'book', 't', '<p><em>هوش مشارکتی</em> (2015) راهنمایی برای توسعه شکل شخصی هوش با استفاده از روش‌های منحصر به فرد تفکر شماست. این پلک ها به شما می آموزد که چگونه نقاط قوت خود و دیگران را شناسایی کرده و بر روی آنها بسازید و در عین حال ارتباطات خود را بر این اساس تنظیم کنید.</p>', '2015-12-08 00:00:00', 4, 90, 'https://images.blinkist.io/images/books/566607dbcb2fee0007000000/1_1/470.jpg', '/en/books/collaborative-intelligence-en/purchase', 'هوش-مشارکتی', '2023-01-26 19:49:13.091542', '2023-01-26 19:49:13.091542', NULL, 'Collaborative Intelligence');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (612, 'تکامل پول', 'از یونان باستان تا عصر دیجیتال', 'از یونان باستان تا عصر دیجیتال', 19, 8, 'book', 't', '<p><em>تکامل پول </em>(2016) نگاهی روشنگر به تاریخچه ارز در جامعه متمدن ارائه می دهد، از صدف و سکه گرفته تا دیجیتال و صفر حساب بانکی آنلاین. دریابید که چگونه سیستم‌های پولی همیشه مانند دین عمل کرده‌اند - بدون ایمان و اعتقاد، سقوط می‌کنند - و بیاموزید که آینده چه چیزی در انتظار شماست.</p>', '2017-06-08 00:00:00', 4, 65, 'https://images.blinkist.io/images/books/59353b13b238e10008fda248/1_1/470.jpg', '/en/books/the-evolution-of-money-en/purchase', 'تکامل-پول', '2023-01-26 19:49:18.364451', '2023-01-26 19:49:18.364451', NULL, 'The Evolution of Money');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (613, 'اقتصاد دونات', 'هفت راه برای فکر کردن مانند یک اقتصاددان قرن بیست و یکمی', 'هفت راه برای فکر کردن مانند یک اقتصاددان قرن بیست و یکمی', 27, 8, 'book', 't', '<p><em>Doughnut Economics</em> (2017) فراخوانی است برای یک رویکرد تازه به اقتصاد. همانطور که نابرابری افزایش می یابد و بحران زیست محیطی در حال ظهور است، سؤال اصلی کتاب هرگز مرتبط به نظر نمی رسید. چگونه می‌توانیم یک سیستم اقتصادی عادلانه بسازیم که به ما امکان می‌دهد در عین حفظ کره زمین، رشد کنیم؟ کیت راورث پیشنهاد می‌کند که یک مکان خوب برای شروع، حذف افسانه‌های قدیمی است که برای مدت طولانی تفکر اقتصادی را شکل داده‌اند. با توجه به "نقطه شیرین" به شکل دونات که در آن می توان نیازهای ما را به طور پایدار برآورده کرد، این یک مطالعه قابل تامل است که ممکن است فقط به نجات جهان کمک کند.</p>', '2018-06-22 00:00:00', 4, 128, 'https://images.blinkist.io/images/books/5b285192b238e1000787b444/1_1/470.jpg', '/en/books/doughnut-economics-en/purchase', 'اقتصاد-دونات', '2023-01-26 19:49:23.784299', '2023-01-26 19:49:23.784299', NULL, 'Doughnut Economics');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (614, 'مزه', 'تغذیه آگاهانه، زندگی آگاهانه', 'تغذیه آگاهانه، زندگی آگاهانه', 16, 11, 'book', 'f', '<p><em>Savor </em>(2010) درباره چگونگی یافتن آرامش درونی، شادی و قدرت - به ویژه برای کسانی که سعی در کاهش وزن پایدار دارند - با آموزه‌ها و تکنیک‌های بودایی برای درک غنای زندگی در لحظه حال همچنین از آخرین تحقیقات علوم تغذیه در مورد بهترین راه‌های غذا خوردن و ورزش استفاده می‌کند و روشی جامع را برای بهبود سلامت جسمی، روانی و معنوی و در نتیجه تغییر زندگی‌شان به خوانندگان ارائه می‌دهد.</p>', '2014-01-22 12:00:00', 4, 95, 'https://images.blinkist.io/images/books/516bc091e4b01b686deb9b1d/1_1/470.jpg', '/en/books/savor-en/purchase', 'مزه', '2023-01-26 19:49:28.637578', '2023-01-26 19:49:28.637578', NULL, 'Savor');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (615, 'همه مهم هستند', 'قدرت فوق العاده مراقبت از افراد مانند خانواده', 'قدرت فوق العاده مراقبت از افراد مانند خانواده', 13, 5, 'book', 't', '<p><em>همه مهم هستند </em>(2015) تلاش باب چپمن برای یافتن بهترین رویکرد برای کسب و کار و سبک رهبری را شرح می دهد. رویکردهای سنتی مدیریت اغلب با کارمندان مانند چرخ دنده های دستگاه برخورد می کند. نویسندگان توضیح می‌دهند که با مراقبت از کارمندان به گونه‌ای که انگار خانواده هستند، نه تنها می‌توانید موفقیت بی‌سابقه‌ای را تجربه کنید، بلکه می‌توانید وفاداری شرکت را القا کنید و به همه کارکنان اجازه دهید تا به پتانسیل کامل خود دست یابند.</p>', '2016-02-09 00:00:00', 4, 57, 'https://images.blinkist.io/images/books/56b8ae70d119f9000700003e/1_1/470.jpg', '/en/books/everybody-matters-en/purchase', 'همه-مهم-هستند', '2023-01-26 19:49:33.656216', '2023-01-26 19:49:33.656216', NULL, 'Everybody Matters');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (616, 'بازی بزرگتر', 'چگونه دزدان دریایی، رویاپردازان و مبتکران بر بازارها ایجاد و تسلط دارند', 'چگونه دزدان دریایی، رویاپردازان و مبتکران بر بازارها ایجاد و تسلط دارند', 11, 5, 'book', 't', '<p><em>بازی بزرگتر</em> (2016) استراتژی‌هایی را که می‌توانید برای ورود موفقیت‌آمیز به هر بازاری به کار ببرید، شرح می‌دهد. ایجاد یک محصول جدید آسان نیست، اما واداشتن مردم به خرید آن حتی سخت تر است. این کتاب به شما نشان می دهد که چگونه با ایجاد خودتان و جلب توجه مردم، بازار مناسب را برای محصول خود انتخاب کنید.</p>', '2017-02-17 00:00:00', 4, 48, 'https://images.blinkist.io/images/books/58a31e5db2613e0004fe6812/1_1/470.jpg', '/en/books/play-bigger-en/purchase', 'بازی-بزرگتر', '2023-01-26 19:49:38.806405', '2023-01-26 19:49:38.806405', NULL, 'Play Bigger');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (617, 'بیوگرافی قبل از خواب: بله می توانم', 'داستان سامی دیویس جونیور.', 'داستان سامی دیویس جونیور.', 36, 7, 'book', 't', '<p><strong>روایت شده توسط Jeannette Robinson</strong></p>
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (618, 'قدرت معنا', 'ساختن زندگی که مهم است', 'ساختن زندگی که مهم است', 18, 7, 'book', 't', '<p><em>قدرت معنا (2017)</em> چهار ستون معنایی را مورد بحث قرار می‌دهد که اگر فرد امیدوار است زندگی پرباری داشته باشد، باید به آنها احترام بگذارد. این کتاب خوانندگان را تشویق می کند تا با جستجوی هدفی در زندگی، ارتباط با دیگران، درگیر شدن در تعالی و یادگیری از آسیب های گذشته، خود را کشف کنند.</p>', '2017-12-25 00:00:00', 5, 307, 'https://images.blinkist.io/images/books/5a3bb4b7b238e10006e1ac09/1_1/470.jpg', '/en/books/the-power-of-meaning-en/purchase', 'قدرت-معنا', '2023-01-26 19:49:48.955205', '2023-01-26 19:49:48.955205', NULL, 'The Power Of Meaning');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (619, 'شیب', 'کتاب کوچکی که به شما می آموزد چه زمانی باید ترک کنید (و چه زمانی باید بچسبید)', 'کتاب کوچکی که به شما می آموزد چه زمانی باید ترک کنید (و چه زمانی باید بچسبید)', 21, 8, 'book', 't', '<p><em>The Dip </em>(2007) درباره مبارزه مشترکی است که همه ما هنگام انجام یک پروژه بلندپروازانه یا شروع یک حرفه جدید با آن روبرو می شویم. همانطور که نویسنده ست گودین اشاره می کند، ما می توانیم با آماده شدن برای فرو رفتن اجتناب ناپذیر در زمان های دشوار و دشوار، شانس موفقیت خود را تا حد زیادی افزایش دهیم. با انتخاب‌های سخت، پرهیز از حواس‌پرتی و تعیین اولویت‌ها، می‌توانید به خوبی مجهز شوید و قوی‌تر از قبل ظاهر شوید.</p>', '2019-02-22 00:00:00', 4, 146, 'https://images.blinkist.io/images/books/5c6d0f476cee0700079efb4e/1_1/470.jpg', '/en/books/the-dip-en/purchase', 'شیب', '2023-01-26 19:49:52.506287', '2023-01-26 19:49:52.506287', NULL, 'The Dip');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (620, 'ماه', 'گذشته، حال و آینده', 'گذشته، حال و آینده', 25, 8, 'book', 't', '<p><em>ماه </em>(2019) بیوگرافی ماه است. این رابطه ما با نزدیکترین همسایه بین ستاره ای ما را نشان می دهد - از آیین های قمری اولیه و اساطیر تا مکاشفه های خیره کننده یونانیان باستان. از خاطرات علمی تخیلی قرن نوزدهم تا فرود آپولو در سال 1969.</p>', '2019-12-05 00:00:00', 4, 57, 'https://images.blinkist.io/images/books/5de834056cee070008b723ee/1_1/470.jpg', '/en/books/moon-en/purchase', 'ماه', '2023-01-26 19:49:57.761251', '2023-01-26 19:49:57.761251', NULL, 'Moon');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (621, 'منتهی شدن', 'درس های بی انتها از بزرگترین مدیر تمام دوران', 'درس های بی انتها از بزرگترین مدیر تمام دوران', 11, 5, 'book', 't', '<p>در <em>Leading </em> (2015)، یکی از مشهورترین مربیان فوتبال جهان، درس‌هایی را که درباره کار گروهی، رهبری و عملکرد ورزشی باورنکردنی آموخته به اشتراک می‌گذارد. مشاهدات و تجربیات او بینش های بی انتها در مورد موفقیت در دنیای ورزش و فراتر از آن را ارائه می دهد.</p>', '2015-12-14 00:00:00', 4, 22, 'https://images.blinkist.io/images/books/566ebd0addd17a0007000011/1_1/470.jpg', '/en/books/leading-en/purchase', 'منتهی-شدن', '2023-01-26 19:50:02.950946', '2023-01-26 19:50:02.950946', NULL, 'Leading');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (622, 'انتشار نوآوری ها', 'دریابید که چگونه شانس پذیرش نوآوری خود را افزایش دهید', 'دریابید که چگونه شانس پذیرش نوآوری خود را افزایش دهید', 18, 11, 'book', 'f', '<p><em>گسترش</em> <em></em> <em>نوآوری</em>ها بررسی بسیاری از راه‌های پذیرش ایده‌ها و فناوری‌های جدید توسط کاربران است. به طور خاص، این کتاب به طور مفصل مراحلی را که یک نوآوری در مسیر پذیرش خود طی می‌کند، انواع مختلف افرادی که نوآوری‌ها را پذیرفته‌اند و نحوه تأثیرگذاری بر فرآیند انتشار توضیح می‌دهد.</p>', '2021-05-11 15:07:18.344', 4, 24, 'https://images.blinkist.io/images/books/6098fa886cee0700071523c4/1_1/470.jpg', '/en/books/diffusion-of-innovations-en/purchase', 'انتشار-نوآوری-ها', '2023-01-26 19:50:07.748186', '2023-01-26 19:50:07.748186', NULL, 'Diffusion of Innovations');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (645, 'بی شماری', 'بی سوادی ریاضی و پیامدهای آن', 'بی سوادی ریاضی و پیامدهای آن', 14, 5, 'book', 't', '<p><em>بی شماری</em> (1988) توضیح می دهد که چگونه بیزاری از ریاضیات و اعداد هر دو زندگی خصوصی و عمومی ما را فرا گرفته است. این کتاب با بررسی مثال‌های واقعی بی‌شماری و پیامدهای آن، راه‌حل‌های مفیدی برای مبارزه با این ترس غیرمنطقی و نادرست از ریاضی ارائه می‌کند.</p>', '2016-08-16 00:00:00', 4, 28, 'https://images.blinkist.io/images/books/57af79449400350003a45f15/1_1/470.jpg', '/en/books/innumeracy-en/purchase', 'بی-شماری', '2023-01-26 19:52:05.154886', '2023-01-26 19:52:05.154886', NULL, 'Innumeracy');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (623, 'زمان و نحوه صرف آن', '7 قانون برای روزهای ثروتمندتر و شادتر', '7 قانون برای روزهای ثروتمندتر و شادتر', 24, 8, 'book', 't', '<p><em>زمان و نحوه صرف آن</em> (2019) از تحقیقات علمی استفاده می کند تا به مردم کمک کند تا در مورد نحوه استفاده از اوقات فراغت خود تصمیمات بهتری بگیرند. با انتخاب‌های بسیار زیادی که این روزها برای جلب توجه ما رقابت می‌کنند، نویسنده جیمز والمن یک چک لیست ساده ارائه می‌کند که می‌تواند به مردم کمک کند وقت خود را به روش‌های معنادارتر و مفیدتر سپری کنند.</p>', '2019-05-22 00:00:00', 4, 228, 'https://images.blinkist.io/images/books/5cdffa156cee0700081dc30e/1_1/470.jpg', '/en/books/time-and-how-to-spend-it-en/purchase', 'زمان-و-نحوه-صرف-آن', '2023-01-26 19:50:13.099243', '2023-01-26 19:50:13.099243', NULL, 'Time and How to Spend It');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (624, 'گل آفتابگردان', 'در مورد امکانات و حدود بخشش', 'در مورد امکانات و حدود بخشش', 13, 5, 'book', 't', '<p><em>آفتابگردان</em> (1969) یک کاوش مهم در مورد بخشش است - هم امکانات و هم محدودیت های آن. در حالی که نویسنده تلاش می کند پاسخی برای یک سوال بسیار پیچیده بیابد: آیا یک زندانی اردوگاه کار اجباری یهودی می تواند یک سرباز نازی را در بستر مرگ ببخشد، با نویسنده همراه می شویم؟ طیف وسیعی از نظرات وجود دارد - از افرادی مانند پریمو لوی و دالایی لاما - اما آیا پاسخ درستی وجود دارد؟</p>', '2016-05-31 00:00:00', 4, 16, 'https://images.blinkist.io/images/books/5746c734b49ff200039c4d6f/1_1/470.jpg', '/en/books/the-sunflower-en/purchase', 'گل-آفتابگردان', '2023-01-26 19:50:18.637737', '2023-01-26 19:50:18.637737', NULL, 'The Sunflower');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (625, 'بیوگرافی قبل از خواب: برای ماه شلیک کنید', 'مسابقه فضایی و سفر فوق العاده آپولو 11', 'مسابقه فضایی و سفر فوق العاده آپولو 11', 40, 7, 'book', 't', '<p><strong>به روایت الیور مینز<br><br>موسیقی توسط فدریکو کدرونی</strong></p>
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (626, 'Gynae Geek', 'راهنمای بی‌معنی شما برای مراقبت‌های بهداشتی «آنجا پایین».', 'راهنمای بی‌معنی شما برای مراقبت‌های بهداشتی «آنجا پایین».', 18, 6, 'book', 't', '<p><em>Gynae Geek </em>(2019) یک راهنمای مستقیم برای سلامت زنان است که توسط متخصص زنان دکتر آنیتا میترا هدایت می‌شود. پاسخ تمام سوالاتی را که هرگز در مورد آناتومی، قاعدگی، سلامت جنسی، و باروری نپرسیده‌اید، خواهید آموخت.</p>', '2021-02-20 00:00:00', 4, 21, 'https://images.blinkist.io/images/books/602650916cee0700076917fa/1_1/470.jpg', '/en/books/the-gynae-geek-en/purchase', 'Gynae-Geek', '2023-01-26 19:50:28.589636', '2023-01-26 19:50:28.589636', NULL, 'The Gynae Geek');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (627, 'سرمایه گذاری روی افراد', 'تأثیر مالی ابتکارات منابع انسانی', 'تأثیر مالی ابتکارات منابع انسانی', 15, 8, 'book', 'f', '<p><em>سرمایه گذاری در افراد </em>(2011) منابع انسانی را روشن می کند، بخش مهمی در یک شرکت موفق که اغلب مورد کم ارزش گذاری و قدردانی قرار می گیرد. یک استراتژی پرسنل زیرک می‌تواند عملکرد شرکت را تنظیم کند و رفاه کارکنان را افزایش دهد. این کتاب یک فرآیند چهار مرحله‌ای ساده و آسان برای بهبود استراتژی‌های منابع انسانی شما ارائه می‌کند.</p>', '2015-07-28 00:00:00', 4, 12, 'https://images.blinkist.io/images/books/55b76af73235390007020000/1_1/470.jpg', '/en/books/investing-in-people-en/purchase', 'سرمایه-گذاری-روی-افراد', '2023-01-26 19:50:33.404728', '2023-01-26 19:50:33.404728', NULL, 'Investing In People');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (628, 'اصل کوکی فورچون', '20 کلید برای یک داستان برند عالی و چرا کسب و کار شما به آن نیاز دارد', '20 کلید برای یک داستان برند عالی و چرا کسب و کار شما به آن نیاز دارد', 11, 5, 'book', 't', '<p><em>اصل کوکی فورچون </em>(2013) یک راهنمای عملی برای ساختن یک برند موفق از طریق داستان سرایی قدرتمند، یک چشم انداز متقاعد کننده و یک هدف روشن است. این پلک ها توضیح می دهند که چگونه محصول خود را به معنایی که مشتریان بالقوه به دنبال آن هستند مرتبط کنید.</p>', '2017-04-11 00:00:00', 4, 30, 'https://images.blinkist.io/images/books/58eb977fa54bbb000464bb08/1_1/470.jpg', '/en/books/the-fortune-cookie-principle-en/purchase', 'اصل-کوکی-فورچون', '2023-01-26 19:50:38.907365', '2023-01-26 19:50:38.907365', NULL, 'The Fortune Cookie Principle');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (629, 'پروژه شادی', 'یا، چرا یک سال را صرف خواندن صبح‌ها کردم، کمدهایم را تمیز کردم، درست دعوا کنم، ارسطو بخوانم، و به طور کلی بیشتر لذت ببرم.', 'یا، چرا یک سال را صرف خواندن صبح‌ها کردم، کمدهایم را تمیز کردم، درست دعوا کنم، ارسطو بخوانم، و به طور کلی بیشتر لذت ببرم.', 24, 10, 'book', 't', '<p>خوشبختی چیست و چگونه می توانیم بیشتر آن را وارد زندگی خود کنیم؟ گرچن روبین این سوال را از خود پرسید زیرا اگرچه او تمام پیش نیازهای یک زندگی شاد - خانواده سالم، شغل خوب و پول کافی برای یک روز بارانی - را برآورده می کرد، اما اغلب خود را ناراضی می دید. او در طول یک سال <em>پروژه شادی</em> خود، در مورد تکنیک ها و نظریه های مختلف در مورد افزایش شادی مطالعه کرد و سعی کرد با کمک آنها شادتر شود.</p>
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (630, 'بیوگرافی قبل از خواب: زندگی سرکش خانم رزا پارکس', 'داستان زندگی نماد حقوق مدنی آمریکایی', 'داستان زندگی نماد حقوق مدنی آمریکایی', 30, 7, 'book', 't', '<p>این اثر برنده جایزه، با ارائه صادقانه و کامل، چالش‌های عمومی و شخصی را شرح می‌دهد که زندگی سیاسی روزا پارکس، فعال حقوق مدنی را تعریف می‌کند. از جمله جزئیات دیگر فعالیت او، کسانی که در اینجا ارائه می شوند، شخصیتی را که جرقه تحریم اتوبوس معروف را برانگیخت و به لحظه ای کلیدی در جنبش حقوق مدنی تبدیل شد، ثبت کردند.</p>', '2021-07-11 00:00:00', 5, 152, 'https://images.blinkist.io/images/books/60e84f146cee070008612d5b/1_1/470.jpg', '/en/books/bedtime-biography-the-rebellious-life-of-mrs-rosa-parks-en/purchase', 'بیوگرافی-قبل-از-خواب:-زندگی-سرکش-خانم-رزا-پارکس', '2023-01-26 19:50:48.45721', '2023-01-26 19:50:48.45721', NULL, 'Bedtime Biography: The Rebellious Life of Mrs. Rosa Parks');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (631, 'تکیه کردن', 'حقیقت در مورد زنان، قدرت و محل کار', 'حقیقت در مورد زنان، قدرت و محل کار', 24, 8, 'book', 't', '<p><em>Lean Out</em> (2019) نقدی پرشور از فمینیسم شرکتی است. به‌جای «تکیه» به ساختارهای مردسالارانه و سیستم‌های زن‌ستیزانه دنیای شرکت‌ها، به زنان پیشنهاد می‌کند که یک قدم به عقب بردارند و از تلاش برای عمل کردن مانند مردان برای پیشرفت دست بردارند.</p>', '2020-05-18 00:00:00', 4, 39, 'https://images.blinkist.io/images/books/5ebe6c306cee070006fdc89f/1_1/470.jpg', '/en/books/lean-out-en/purchase', 'تکیه-کردن', '2023-01-26 19:50:53.78001', '2023-01-26 19:50:53.78001', NULL, 'Lean Out');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (632, 'ترک تحصیل میلیونر', 'رئیس خود را اخراج کنید، کاری را که دوست دارید انجام دهید، زندگی خود را پس بگیرید!', 'رئیس خود را اخراج کنید، کاری را که دوست دارید انجام دهید، زندگی خود را پس بگیرید!', 25, 9, 'book', 't', '<p><em>انصراف میلیونر </em>(2013) یک کتابچه راهنمای الهام بخش برای هر کسی است که آماده افزایش درآمد <em>و</em>استاندارد زندگی خود است. بر اساس تجربه دست اول مولتی میلیونر خودساخته وینس استانزیونه در رسیدن به موفقیت، این پلک ها شما را در سفر دشوار اما در نهایت پر ارزش تغییر زندگی و استفاده حداکثری از پتانسیل خود راهنمایی می کند.</p>', '2019-04-25 00:00:00', 4, 57, 'https://images.blinkist.io/images/books/5cbced3c6cee070008bad282/1_1/470.jpg', '/en/books/the-millionaire-dropout-en/purchase', 'ترک-تحصیل-میلیونر', '2023-01-26 19:50:58.645163', '2023-01-26 19:50:58.645163', NULL, 'The Millionaire Dropout');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (633, 'وقتی تازه وارد هستید چه کاری باید انجام دهید', 'چگونه در شرایط جدید راحت، مطمئن و موفق باشیم؟', 'چگونه در شرایط جدید راحت، مطمئن و موفق باشیم؟', 15, 7, 'book', 't', '<p><em>وقتی جدید هستید چه کاری باید انجام دهید</em> (2015) نتیجه 20 سال تحقیق رولاگ در مورد اینکه چرا افراد در موقعیت های جدید مضطرب و استرس می شوند است. استراتژی هایی برای تغییر دیدگاه شما در مورد موقعیت های جدید ارائه می دهد و تکنیک هایی را برای مدیریت چنین موقعیت هایی با راحتی و اطمینان ارائه می دهد.</p>', '2016-03-30 00:00:00', 4, 34, 'https://images.blinkist.io/images/books/56fa9aa0df81420007000023/1_1/470.jpg', '/en/books/what-to-do-when-youre-new-en/purchase', 'وقتی-تازه-وارد-هستید-چه-کاری-باید-انجام-دهید', '2023-01-26 19:51:04.36205', '2023-01-26 19:51:04.36205', NULL, 'What to Do When You’re New');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (634, 'مهمان ما باش', 'به کمال رساندن هنر خدمات رسانی به مشتری', 'به کمال رساندن هنر خدمات رسانی به مشتری', 16, 7, 'book', 't', '<p><em>مهمان ما باشید</em> (2011) اصول و اصول کلیدی دیزنی در مورد خدمات مشتریان برجسته را آشکار می کند و اینکه چگونه پیروی از آنها به این شرکت کمک کرده است تا به امپراتوری تجاری موفق امروزی تبدیل شود.</p>', '2015-04-22 00:00:00', 5, 32, 'https://images.blinkist.io/images/books/553503426638630007ec0000/1_1/470.jpg', '/en/books/be-our-guest-en/purchase', 'مهمان-ما-باش', '2023-01-26 19:51:09.681389', '2023-01-26 19:51:09.681389', NULL, 'Be Our Guest');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (635, 'گربه', 'چگونه بشریت عاشق همراهان گربه سان ما شد', 'چگونه بشریت عاشق همراهان گربه سان ما شد', 11, 5, 'book', 't', '<p>Cat (2006) نگاهی دقیق و عاشقانه به تاریخ بیولوژیکی، تاریخی و فرهنگی دوستان گربه سان پشمالو ما ارائه می دهد. هر پلک زدن به مرحله متفاوتی از رشد نگاه می کند، و شرح می دهد که چگونه رابطه بین انسان و گربه از سوء تفاهم های وحشتناک خرافی به سعادت اهلی شده تبدیل شده است. میو!</p>', '2017-01-16 00:00:00', 4, 65, 'https://images.blinkist.io/images/books/587a825fa8cb0a000443a1ad/1_1/470.jpg', '/en/books/cat-en/purchase', 'گربه', '2023-01-26 19:51:14.794274', '2023-01-26 19:51:14.794274', NULL, 'Cat');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (636, 'داستان دوئل جراحان مغز و اعصاب', 'تاریخچه مغز انسان که توسط داستان های واقعی تروما، جنون و بهبودی فاش شده است', 'تاریخچه مغز انسان که توسط داستان های واقعی تروما، جنون و بهبودی فاش شده است', 24, 11, 'book', 't', '<p><em>داستان جراحان مغز و اعصاب دوئل</em> (2014) سفری به دنیای شگفت انگیز مغز انسان از طریق برخی از عجیب ترین مطالعات موردی روانشناختی در تاریخ است. تا همین اواخر، دانشمندان علوم اعصاب تنها با تجزیه و تحلیل افکار و رفتار افراد دارای مغز ناهنجار می توانستند مغز را مطالعه کنند. سم کین از این مطالعات موردی تاریخی برای ترسیم تصویری از اندامی که احساسات، شخصیت و آگاهی ما را ایجاد می کند، استفاده می کند.</p>', '2015-11-23 00:00:00', 4, 68, 'https://images.blinkist.io/images/books/56530e9232663500070b0000/1_1/470.jpg', '/en/books/the-tale-of-the-dueling-neurosurgeons-en/purchase', 'داستان-دوئل-جراحان-مغز-و-اعصاب', '2023-01-26 19:51:19.545615', '2023-01-26 19:51:19.545615', NULL, 'The Tale of the Dueling Neurosurgeons');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (662, 'ژن', 'یک تاریخ صمیمی', 'یک تاریخ صمیمی', 23, 11, 'book', 't', '<p><em>ژن</em> (2016) نگاهی عمیق به تاریخچه ژنتیک ارائه می دهد. این پلک ها شما را به سفری از آغاز فروتنانه این رشته تا کاربردهای امروزی آن در تشخیص بیماری ها، رد ادعاهای نژادپرستانه و ایجاد زندگی اصلاح شده ژنتیکی می برد. </p>', '2021-05-11 15:39:10.782', 5, 135, 'https://images.blinkist.io/images/books/608aaba86cee070008a8eebf/1_1/470.jpg', '/en/books/the-gene-en/purchase', 'ژن', '2023-01-26 19:53:25.952974', '2023-01-26 19:53:25.952974', NULL, 'The Gene');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (637, 'مرد عاقل', 'درس هایی از یک زندگی', 'درس هایی از یک زندگی', 24, 8, 'book', 't', '<p><em>Wise Guy </em>(2019) داستان زندگی گای کاوازاکی، کارآفرین و نویسنده پرفروش را روایت می کند. او در یک خانواده جاه طلب ژاپنی که در هاوایی زندگی می کردند متولد شد، پس از انصراف از تحصیل در رشته حقوق، به عنوان یکی از رهبران اپل درخشید. کاوازاکی همه چیز را دیده است. در این پلک‌ها، او خوانندگان را در فراز و نشیب‌ها و درس‌هایی که در طول راه به‌عنوان دانش‌آموز، استاد فناوری، والدین و موج‌سوار شصت و چند ساله آموخته، راهنمایی می‌کند.</p>', '2019-03-28 00:00:00', 4, 36, 'https://images.blinkist.io/images/books/5c9b81f86cee070007d517c6/1_1/470.jpg', '/en/books/wise-guy-en/purchase', 'مرد-عاقل', '2023-01-26 19:51:24.526634', '2023-01-26 19:51:24.526634', NULL, 'Wise Guy');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (638, 'کد ذهن فوق العاده', '10 قانون غیر متعارف برای تعریف مجدد زندگی و موفقیت در شرایط خود', '10 قانون غیر متعارف برای تعریف مجدد زندگی و موفقیت در شرایط خود', 10, 5, 'book', 'f', '<p><em>The Code of the Extraordinary Mind</em> (2016) روشی را برای غلبه بر جنون زندگی روزمره معرفی می کند، روشی که به هرکسی امکان می دهد از همه چیز متمایز شود و به فردی خارق العاده تبدیل شود. نویسنده ده قانونی را وضع می کند که هر کسی می تواند به راحتی از آنها پیروی کند تا تحولی اساسی را تجربه کند و در هر روز معنا و خوشبختی بیابد.</p>', '2016-09-12 00:00:00', 4, 305, 'https://images.blinkist.io/images/books/57d2824673d9bc0003c6819c/1_1/470.jpg', '/en/books/the-code-of-the-extraordinary-mind-en/purchase', 'کد-ذهن-فوق-العاده', '2023-01-26 19:51:30.037071', '2023-01-26 19:51:30.037071', NULL, 'The Code of the Extraordinary Mind');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (639, 'تعجب ردیابی', 'مسیر شگفت انگیز برای هدف، اتصال، و تحقق', 'مسیر شگفت انگیز برای هدف، اتصال، و تحقق', 15, 6, 'book', 't', '<p><em> Tracking Wonder: Reclaiming a Life of Meaning and Possibility in a World Obsested with Productivity </em>(2021) یک کاوش الهام بخش و عملی از شگفتی است. دیویس با بازیابی حالت کودکانه شگفت‌انگیز دنیا، نشان می‌دهد که چگونه می‌توانیم شادتر، سالم‌تر و خلاق‌تر شویم.</p>', '2022-05-06 00:00:00', 4, 156, 'https://images.blinkist.io/images/books/626afa326cee0700088408e5/1_1/470.jpg', '/en/books/tracking-wonder-en/purchase', 'تعجب-ردیابی', '2023-01-26 19:51:34.75037', '2023-01-26 19:51:34.75037', NULL, 'Tracking Wonder');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (640, 'تسلط بر Homebrew', 'راهنمای کامل دم کردن آبجو خوشمزه', 'راهنمای کامل دم کردن آبجو خوشمزه', 25, 8, 'book', 't', '<p><em>Mastering Homebrew </em>(2015) یک راهنمای قابل دسترس برای هنر درست کردن آبجو است. این کتابچه راهنمای عملی مروری گام به گام از کل فرآیند از دم کردن تا بطری کردن را ارائه می دهد.</p>', '2021-08-10 00:00:00', NULL, 9, 'https://images.blinkist.io/images/books/610d292a6cee0700074275d6/1_1/470.jpg', '/en/books/mastering-homebrew-en/purchase', 'تسلط-بر-Homebrew', '2023-01-26 19:51:39.993975', '2023-01-26 19:51:39.993975', NULL, 'Mastering Homebrew');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (641, 'مهم نیست که چقدر خوب هستید، مهم این است که چقدر می خواهید خوب باشید', 'پرفروش ترین کتاب جهان', 'پرفروش ترین کتاب جهان', 16, 6, 'book', 't', '<p><em>این چقدر خوب نیستی، بلکه چقدر خوب می‌خواهی باشی </em>(2003) توصیه‌های حکیمانه‌ای را به هر کسی که علاقه‌مند به تبدیل جاه‌طلبی‌های بزرگ خود به واقعیت است، ارائه می‌کند. پل آردن خوانندگان را به پشت صحنه دنیای تبلیغات می برد تا بهترین و مؤثرترین تکنیک ها را برای طرح ایده ها و جلب نظر مشتری برای گفتن بله نشان دهد. در سرتاسر، آردن ذهن‌های خلاق را تشویق می‌کند که بزرگ فکر کنند و از امور پیش پا افتاده و متوسط ​​جدا شوند.</p>', '2018-05-29 00:00:00', 4, 57, 'https://images.blinkist.io/images/books/5b0cba18b238e1000740dca0/1_1/470.jpg', '/en/books/its-not-how-good-you-are-its-how-good-you-want-to-be-en/purchase', 'مهم-نیست-که-چقدر-خوب-هستید،-مهم-این-است-که-چقدر-می-خواهید-خوب-باشید', '2023-01-26 19:51:44.751707', '2023-01-26 19:51:44.751707', NULL, 'It’s Not How Good You Are, It’s How Good You Want to Be');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (642, 'اجازه درخشش', 'راهنمای معنوی برای رهبری حماسی', 'راهنمای معنوی برای رهبری حماسی', 21, 7, 'book', 't', '<p><em>مجوز درخشش </em>(2021) نقشه راهی را در اختیار مدیران قرار می دهد تا با نیت و هدف رهبری کنند تا همه بتوانند به پتانسیل کامل خود دست یابند. با پذیرش چهار مجوز آن، نشان می‌دهد که چگونه رهبران می‌توانند نتایج و موفقیت‌های شخصی را با استفاده از قدرت خود و سپس راهنمایی دیگران به انجام همین کار به حداکثر برسانند.</p>', '2021-12-16 00:00:00', 4, 260, 'https://images.blinkist.io/images/books/61b1d17d6cee07000703a3db/1_1/470.jpg', '/en/books/permission-to-glow-en/purchase', 'اجازه-درخشش', '2023-01-26 19:51:50.655509', '2023-01-26 19:51:50.655509', NULL, 'Permission to Glow');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (643, 'جست و جوی متعصب', 'راهنمای نهایی برای باز کردن مکالمات فروش و پر کردن خط لوله با استفاده از فروش اجتماعی، تلفن، ایمیل، پیامک و تماس سرد', 'راهنمای نهایی برای باز کردن مکالمات فروش و پر کردن خط لوله با استفاده از فروش اجتماعی، تلفن، ایمیل، پیامک و تماس سرد', 28, 10, 'book', 't', '<p><em>جستجوی متعصب </em>(2015) مملو از حقایق خانگی و نکات و ترفندهایی است که برای کمک به فروشندگان طراحی شده است تا بازی خود را ارتقا دهند – این راهنمای بی‌معنی نهایی برای مهارت فروش است. پیام ساده است: اگر می خواهید به عنوان یک فوق ستاره فروش موفق شوید، باید خط لوله خود را پر از سرنخ نگه دارید. به هر حال، هیچ کس در صورتی که حتی از پسش برنمی‌آید، موفق به انجام یک بازی خانگی نمی‌شود. دستیابی به این رویکرد دقیقاً همان چیزی است که این پلک ها به شما یاد می دهند که چگونه انجام دهید.</p>', '2019-03-05 00:00:00', 5, 167, 'https://images.blinkist.io/images/books/5c7a614a6cee07000727d2ea/1_1/470.jpg', '/en/books/fanatical-prospecting-en/purchase', 'جست-و-جوی-متعصب', '2023-01-26 19:51:55.72328', '2023-01-26 19:51:55.72328', NULL, 'Fanatical Prospecting');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (646, 'علم فروش', 'استراتژی های اثبات شده برای تصمیم گیری، تأثیرگذاری بر تصمیمات و بستن معامله', 'استراتژی های اثبات شده برای تصمیم گیری، تأثیرگذاری بر تصمیمات و بستن معامله', 21, 7, 'book', 't', '<p><em>علم فروش </em>(2016) یک کتاب راهنمای مفصل در مورد علم فروش است. این راهنما با ترکیب بینش‌های علوم اعصاب و روان‌شناسی اجتماعی، رویکردی مبتنی بر شواهد را برای ارائه یک پیشنهاد قانع‌کننده ارائه می‌کند.</p>', '2020-09-25 00:00:00', 5, 243, 'https://images.blinkist.io/images/books/5f69b65b6cee070006a7313e/1_1/470.jpg', '/en/books/the-science-of-selling-en/purchase', 'علم-فروش', '2023-01-26 19:52:10.573358', '2023-01-26 19:52:10.573358', NULL, 'The Science of Selling');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (647, 'چه کسی پنیر مرا جابجا کرد؟', 'روشی شگفت انگیز برای مقابله با تغییر در کار و زندگی شما', 'روشی شگفت انگیز برای مقابله با تغییر در کار و زندگی شما', 11, 5, 'book', 't', '<p>حکمت تجاری را از طریق یک تمثیل مدرن آشکار می‌کند، <em>چه کسی پنیر مرا جابه‌جا کرد</em> (1998) درس‌های ارزشمندی در مورد چگونگی مدیریت بهترین تغییر در زندگی ارائه می‌دهد. چه در بحبوحه رکود کسب و کار در حال مبارزه باشید و چه در تلاش برای یافتن راهی برازنده برای مدیریت یک رابطه دشوار هستید، این کتاب ابزارهایی را در اختیار شما قرار می دهد تا ماهیت انسان را بهتر درک کنید و تغییر را به عنوان یک نیروی مثبت ببینید.</p>', '2015-09-24 00:00:00', 4, 211, 'https://images.blinkist.io/images/books/560000f8615cd100090000cc/1_1/470.jpg', '/en/books/who-moved-my-cheese-en/purchase', 'چه-کسی-پنیر-مرا-جابجا-کرد؟', '2023-01-26 19:52:15.685868', '2023-01-26 19:52:15.685868', NULL, 'Who Moved My Cheese?');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (648, 'بهترین مکان برای کار', 'هنر و علم ایجاد یک محل کار فوق العاده', 'هنر و علم ایجاد یک محل کار فوق العاده', 17, 7, 'book', 't', '<p>اگر می‌خواهید بهترین محل کار ممکن را طراحی کنید، رضایت کارکنان را بهبود ببخشید و در نهایت کارکنان خود را برای ارائه نتایج بهتر تشویق کنید، دیگر به دنبال آن نباشید. <em>بهترین مکان برای کار </em>شما را در روند بهبود محیط کاری راهنمایی می کند و به کارکنانی مشتاق و سازنده تر می انجامد.</p>', '2015-02-04 00:00:00', 4, 29, 'https://images.blinkist.io/images/books/54cf8c1e323335000a4a0000/1_1/470.jpg', '/en/books/the-best-place-to-work-en/purchase', 'بهترین-مکان-برای-کار', '2023-01-26 19:52:21.131299', '2023-01-26 19:52:21.131299', NULL, 'The Best Place to Work');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (649, 'ارزان', 'هزینه بالای فرهنگ تخفیف', 'هزینه بالای فرهنگ تخفیف', 15, 8, 'book', 'f', '<p><em>ارزان</em> بررسی قیمت هایی است که <em>واقعا</em> برای اقلام کم هزینه می پردازیم. تاریخچه وسواس آمریکا در یافتن کالاهای ارزان قیمت را نشان می دهد. <em>ارزان</em> همچنین توضیح می‌دهد که چگونه انسان‌ها غیرمنطقی هستند و چگونه شرکت‌ها ما را دستکاری می‌کنند تا چیزهایی را بخریم که به آنها نیاز نداریم یا حتی نمی‌خواهیم. تشنگی ما برای محصولات ارزان به کل جهان آسیب می رساند. ما باید خودمان را آموزش دهیم، بایستیم و کاری در مورد آن انجام دهیم.</p>', '2014-12-31 00:00:00', NULL, 7, 'https://images.blinkist.io/images/books/548f03fb6532350009f90000/1_1/470.jpg', '/en/books/cheap-en/purchase', 'ارزان', '2023-01-26 19:52:26.11926', '2023-01-26 19:52:26.11926', NULL, 'Cheap');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (650, 'حس عشق', 'علم جدید انقلابی روابط عاشقانه', 'علم جدید انقلابی روابط عاشقانه', 22, 8, 'book', 't', '<p><em>Love Sense </em>(2013) کاوشی در علم عشق است. این پلک زدن ها نشان می دهد که انسان ها به طور غریزی تمایل به ارتباط با یکدیگر دارند و مشکلات رابطه زمانی به وجود می آیند که عاشقان دیگر احساس امنیت نمی کنند. آنها همچنین استراتژی‌های عملی را برای چگونگی توسعه <em>حس عشق </em> ارائه می‌دهند – یعنی توانایی شما در ایجاد پیوندهای کامل و طولانی مدت با عزیزانتان.</p>', '2020-05-27 00:00:00', 4, 317, 'https://images.blinkist.io/images/books/5ec7be4f6cee070006a9d2df/1_1/470.jpg', '/en/books/love-sense-en/purchase', 'حس-عشق', '2023-01-26 19:52:31.098227', '2023-01-26 19:52:31.098227', NULL, 'Love Sense');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (651, 'مسیحیت صرف', 'تأملات جاودانه در دفاع از مسیحیت', 'تأملات جاودانه در دفاع از مسیحیت', 31, 9, 'book', 't', '<p><em>مسیحیت صرف </em>(1952) یکی از مشهورترین و تأثیرگذارترین عذرخواهی‌های دین مسیحی است که تاکنون نوشته شده است. این مجموعه از برنامه‌های رادیویی افسانه‌ای C.S. Lewis در جنگ جهانی دوم گردآوری شده است، مجموعه‌ای از بازتاب‌های جاودانه را که برای توضیح و دفاع از مسیحیت طراحی شده‌اند، گرد هم می‌آورد. <em>مسیحیت صرف</em> استدلال های لوئیس برای صدق آموزه مسیحی را تشریح می کند. همچنین بررسی می‌کند که زندگی مسیحی شامل چه چیزهایی می‌شود و چرا لوئیس فکر می‌کند همه ما به عنوان مسیحی وضعیت بهتری داریم.</p>', '2020-06-18 00:00:00', 5, 314, 'https://images.blinkist.io/images/books/5ee390fb6cee070006837810/1_1/470.jpg', '/en/books/mere-christianity-en/purchase', 'مسیحیت-صرف', '2023-01-26 19:52:36.84599', '2023-01-26 19:52:36.84599', NULL, 'Mere Christianity');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (652, 'اکونومیست مخفی', 'اقتصاد پشت تصمیمات روزمره', 'اقتصاد پشت تصمیمات روزمره', 16, 7, 'book', 't', '<p><em></em> <em>سرپوشیده</em> <em>اقتصاددان</em> توضیح می‌دهد که اقتصاد چگونه زندگی ما را تعریف می‌کند. از قیمت یک کاپوچینو گرفته تا میزان مه دود موجود در هوا، همه چیز به اقتصاد گره خورده است. این کتاب به ما نشان می دهد که چگونه اقتصاددانان جهان را درک می کنند و چگونه می توانیم از درک بهتر سیستم های اقتصادی بهره مند شویم.</p>', '2014-07-15 00:00:00', 4, 112, 'https://images.blinkist.io/images/books/53c63b703839340007de0000/1_1/470.jpg', '/en/books/the-undercover-economist-en/purchase', 'اکونومیست-مخفی', '2023-01-26 19:52:40.369208', '2023-01-26 19:52:40.369208', NULL, 'The Undercover Economist');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (653, 'در حاشیه', 'جایی که علم با شبه علم ملاقات می کند', 'جایی که علم با شبه علم ملاقات می کند', 22, 7, 'book', 't', '<p><em>در حاشیه </em>(2021) به آنچه شبه علم را در امتداد خطوط تاریخی و فلسفی تعریف می کند، می پردازد. با ظهور منکران و مخالفان تغییرات آب و هوا، درک مرزبندی بین علم و شبه علم یک فوریت جدید پیدا کرده است. با کاوش در علوم شبه مانند طالع بینی، مدل زمین مسطح و ESP، می توانیم در مورد ماهیت علم در گذشته و حال بیاموزیم.</p>', '2021-07-02 00:00:00', 4, 97, 'https://images.blinkist.io/images/books/60db390f6cee07000769ba96/1_1/470.jpg', '/en/books/on-the-fringe-en/purchase', 'در-حاشیه', '2023-01-26 19:52:45.023972', '2023-01-26 19:52:45.023972', NULL, 'On the Fringe');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (654, 'رهبری و خودفریبی', 'خارج شدن از جعبه', 'خارج شدن از جعبه', 18, 10, 'book', 't', '<p>این کتاب به شما نشان می‌دهد که چگونه و چرا اکثر مردم در حالت خودفریبی قرار دارند و نیازهای خود را مهم‌تر از نیازهای اطرافیان خود می‌دانند. این نشان دهنده تأثیر منفی این خودفریبی بر زندگی ما است، اما همچنین راهی برای خروج از این وضعیت نشان می دهد که به نفع زندگی خصوصی و حرفه ای ما است.</p>', '2014-02-25 08:00:00', 4, 94, 'https://images.blinkist.io/images/books/530c53d334623100081b0000/1_1/470.jpg', '/en/books/leadership-and-self-deception-en/purchase', 'رهبری-و-خودفریبی', '2023-01-26 19:52:48.281639', '2023-01-26 19:52:48.281639', NULL, 'Leadership and Self-Deception');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (655, 'چگونه شانس اتفاق می افتد', 'استفاده از علم شانس برای تغییر کار، عشق و زندگی', 'استفاده از علم شانس برای تغییر کار، عشق و زندگی', 17, 7, 'book', 't', '<p><em>چگونه شانس اتفاق می افتد</em> (2018) این افسانه را که شانس چیزی است که کنترلش بر آن صفر است را رد می کند و نشان می دهد که مطمئناً می توانیم بر سطح شانس در زندگی خود تأثیر بگذاریم. مملو از مثال‌ها و توصیه‌های عملی، این کتاب نشان می‌دهد که چگونه می‌توان شانس را در محل کار و همچنین در صحنه دوستیابی بهبود بخشید.</p>', '2018-03-08 00:00:00', 4, 170, 'https://images.blinkist.io/images/books/5a9d8657b238e100079a3abf/1_1/470.jpg', '/en/books/how-luck-happens-en/purchase', 'چگونه-شانس-اتفاق-می-افتد', '2023-01-26 19:52:53.271297', '2023-01-26 19:52:53.271297', NULL, 'How Luck Happens');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (656, 'ناب صحبت کن', 'جلسات کوتاهتر نتایج سریعتر روابط بهتر', 'جلسات کوتاهتر نتایج سریعتر روابط بهتر', 9, 4, 'book', 't', '<p><em>Talk Lean </em>به شما می آموزد که چگونه افکار خود را به شیوه ای مستقیم، صریح و در عین حال مودبانه بیان کنید. نویسنده نکات موثر و کاربردی را برای داشتن یک مکالمه سازنده به اشتراک می گذارد که به دستیابی به اهداف شما کمک می کند.</p>', '2015-03-06 00:00:00', 4, 65, 'https://images.blinkist.io/images/books/54f5b530646133000a330000/1_1/470.jpg', '/en/books/talk-lean-en/purchase', 'ناب-صحبت-کن', '2023-01-26 19:52:58.313593', '2023-01-26 19:52:58.313593', NULL, 'Talk Lean');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (657, 'فشار', 'قدرت شارژ کردن زندگی خود با پول، معنا و حرکت', 'قدرت شارژ کردن زندگی خود با پول، معنا و حرکت', 13, 6, 'book', 't', '<p><em>Hustle</em> (2016) راهنمای شما برای گذراندن کار در حین انجام کاری است که دوست دارید. این پلک‌ها همه‌گیری نارضایتی شغلی را توضیح می‌دهند و راه‌هایی را برای رهایی از زحمت‌های یکنواخت و ناتمام روزمره با تحقق رویاهایتان جستجو می‌کنند – هر چند دور از ذهن و دست نیافتنی به نظر برسند.</p>', '2017-07-31 00:00:00', 4, 132, 'https://images.blinkist.io/images/books/597bc3bbb238e10005703528/1_1/470.jpg', '/en/books/hustle-en/purchase', 'فشار', '2023-01-26 19:53:02.959652', '2023-01-26 19:53:02.959652', NULL, 'Hustle');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (658, 'روح بی بند و بار', 'سفر فراتر از خودتان', 'سفر فراتر از خودتان', 12, 6, 'book', 't', '<p><em>روح Untethered</em> همه چیز درباره شماست: احساسات، افکار و آگاهی شما. این کتاب با استفاده از تمرین‌های معنوی مختلف، توضیح می‌دهد که چگونه می‌توانید ذهن خود را هدایت کنید، با خودتان در تماس باشید و استاد خود شوید تا در نهایت به روشنگری برسید.</p>', '2015-02-26 00:00:00', 5, 335, 'https://images.blinkist.io/images/books/54eaf4b6393366000a7e0000/1_1/470.jpg', '/en/books/the-untethered-soul-en/purchase', 'روح-بی-بند-و-بار', '2023-01-26 19:53:06.360325', '2023-01-26 19:53:06.360325', NULL, 'The Untethered Soul');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (659, 'میانسالی', 'راهنمای فلسفی', 'راهنمای فلسفی', 19, 6, 'book', 't', '<p><em>Midlife</em>(2017) یک راهنمای فلسفی برای پیمایش مشکلاتی است که میانسالی می تواند ایجاد کند. این کتاب با تکیه بر متفکرانی از روم باستان تا انگلستان قرن نوزدهم، آرامشی ملایم در برابر مصائب میانسالی ارائه می‌کند.</p>', '2021-01-30 00:00:00', 5, 201, 'https://images.blinkist.io/images/books/600acde36cee070007dc7c1c/1_1/470.jpg', '/en/books/midlife-en/purchase', 'میانسالی', '2023-01-26 19:53:11.219539', '2023-01-26 19:53:11.219539', NULL, 'Midlife');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (660, 'هرگز تفاوت را تقسیم نکنید', 'طوری مذاکره کنید که انگار زندگی شما به آن بستگی دارد', 'طوری مذاکره کنید که انگار زندگی شما به آن بستگی دارد', 14, 6, 'book', 't', '<p><em>هرگز تفاوت را تقسیم نکنید</em> (2016) راهنمای شما برای مذاکره است. بر اساس کار گسترده FBI کریس ووس، نویسندگان توصیه‌های عملی در مورد چگونگی مذاکره در مسیر موفقیت، چه در دفتر، چه خانه، یا گروگان‌گیری ارائه می‌دهند.</p>', '2018-01-02 00:00:00', 4, 684, 'https://images.blinkist.io/images/books/5a3ee58db238e10007128bb2/1_1/470.jpg', '/en/books/never-split-the-difference-en/purchase', 'هرگز-تفاوت-را-تقسیم-نکنید', '2023-01-26 19:53:16.337818', '2023-01-26 19:53:16.337818', NULL, 'Never Split the Difference');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (661, 'تسلیم', '40 آهنگ، یک داستان', '40 آهنگ، یک داستان', 19, 6, 'book', 't', '<p><em>تسلیم: 40 آهنگ، یک داستان </em>(2022) یک تور شاعرانه در چهار دهه از زندگی بونو، خواننده اصلی گروه U2 - یکی از بزرگترین و ماندگارترین گروه‌های موسیقی جهان است. هر فصل با یک آهنگ و تصاویر در سرتاسر آن، کتاب خاطره‌ای است که با طنز، شوخ طبعی و تندخویی خودخوارکننده آغشته شده است.</p>', '2023-01-13 00:00:00', 4, 13, 'https://images.blinkist.io/images/books/63bd0c13e8fd3c00080b3af9/1_1/470.jpg', '/en/books/surrender-en/purchase', 'تسلیم', '2023-01-26 19:53:21.15089', '2023-01-26 19:53:21.15089', NULL, 'Surrender');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (663, 'چگونه یک نینجا بهره وری باشیم', 'کمتر نگران باشید، بیشتر به دست آورید و کاری را که انجام می دهید دوست داشته باشید', 'کمتر نگران باشید، بیشتر به دست آورید و کاری را که انجام می دهید دوست داشته باشید', 25, 8, 'book', 't', '<p><em>چگونه یک نینجا بهره وری باشیم </em>(2014) تکنیک های مدیریت زمان قدیمی و توصیه های بهره وری را به کتابچه راهنمای قرن بیست و یکم در مورد چگونگی هوشمندتر کار کردن - نه سخت تر تبدیل می کند. مطابق با واقعیت‌های کار و زندگی معاصر، مملو از راهنمایی‌ها و تمرین‌های عملی برای افزایش بهره‌وری است.</p>', '2022-01-24 00:00:00', 4, 544, 'https://images.blinkist.io/images/books/61e56faa6cee0700086d3433/1_1/470.jpg', '/en/books/how-to-be-a-productivity-ninja-en/purchase', 'چگونه-یک-نینجا-بهره-وری-باشیم', '2023-01-26 19:53:30.730584', '2023-01-26 19:53:30.730584', NULL, 'How to Be a Productivity Ninja');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (664, 'جعبه را فشار دهید', 'آخرین باری که برای اولین بار کاری انجام دادید کی بود؟', 'آخرین باری که برای اولین بار کاری انجام دادید کی بود؟', 13, 5, 'book', 't', '<p><em>Poke the Box </em>(2015) عمیقاً به اقتصاد متصل امروزی می پردازد، جایی که ابتکار و نوآوری مهمتر از سرمایه مالی یا اعتبار است. اگر می‌خواهید نوآوری را بپذیرید و اولین کسی باشید که با یک ایده جدید گردن خود را بیرون می‌کشید، باید بر ترس خود از شکست غلبه کنید و زمانی که زمین خوردید به عقب نشینی ادامه دهید. این یک کتاب راهنما برای کسانی است که نیاز به فشار دارند تا ایده های خود را از روی تخته طراحی بیرون بکشند و به دنیای واقعی وارد کنند<em>.</em></p>', '2018-05-17 00:00:00', 4, 61, 'https://images.blinkist.io/images/books/5af9748fb238e100073a227b/1_1/470.jpg', '/en/books/poke-the-box-en/purchase', 'جعبه-را-فشار-دهید', '2023-01-26 19:53:35.01772', '2023-01-26 19:53:35.01772', NULL, 'Poke the Box');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (665, 'زبان چگونه کار می کند', 'چگونه بچه ها حرف می زنند، کلمات معنی را تغییر می دهند و زبان ها زندگی می کنند یا می میرند', 'چگونه بچه ها حرف می زنند، کلمات معنی را تغییر می دهند و زبان ها زندگی می کنند یا می میرند', 20, 7, 'book', 't', '<p><em>زبان چگونه کار می کند</em> (2005) اسرار نحوه و چرایی ارتباط ما را آشکار می کند. زبان یکی از ویژگی های تعیین کننده ای است که انسان را انسان می سازد. اما از آنجایی که این مفهوم بسیار اساسی است، ما به ندرت وقت می‌گذاریم تا به این فکر کنیم که از کجا آمده یا چگونه تکامل می‌یابد. این پلک‌ها به بررسی ریشه‌های تاریخی و شخصی زبان و روش‌های مختلف تأثیرگذاری آن بر زندگی روزمره ما می‌پردازند.</p>', '2020-03-17 00:00:00', 4, 69, 'https://images.blinkist.io/images/books/5e6b90b56cee07000645d7ec/1_1/470.jpg', '/en/books/how-language-works-en/purchase', 'زبان-چگونه-کار-می-کند', '2023-01-26 19:53:40.12901', '2023-01-26 19:53:40.12901', NULL, 'How Language Works');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (666, 'عادات پنهان نابغه', 'فراتر از استعداد، ضریب هوشی و ذکاوت - باز کردن رازهای عظمت', 'فراتر از استعداد، ضریب هوشی و ذکاوت - باز کردن رازهای عظمت', 21, 6, 'book', 't', '<p><em>عادت های پنهان نابغه </em>(2020) راهنمای ویژگی هایی است که نوابغ را از بقیه ما متمایز می کند. این کتاب با تکیه بر زندگی خلاقان، متفکران و اخلالگران خارق العاده از یونان باستان تا ژاپن مدرن، عواملی را که پدیده پیچیده و جذابی را که ما آن را "نابغه" می نامیم، تشکیل می دهند، ردیابی می کند.</p>', '2021-07-26 00:00:00', 4, 291, 'https://images.blinkist.io/images/books/60fad41f6cee070007e59481/1_1/470.jpg', '/en/books/the-hidden-habits-of-genius-en/purchase', 'عادات-پنهان-نابغه', '2023-01-26 19:53:45.181308', '2023-01-26 19:53:45.181308', NULL, 'The Hidden Habits of Genius');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (667, 'دارایی های رمزنگاری شده', 'راهنمای سرمایه گذاران نوآور برای بیت کوین و فراتر از آن', 'راهنمای سرمایه گذاران نوآور برای بیت کوین و فراتر از آن', 24, 9, 'book', 't', '<p><em>Cryptoassets </em>(2017) هم تاریخچه مختصری از بیت کوین و هم راهنمای مفصلی برای سرمایه گذاری در دارایی های رمزنگاری شده است. این توضیح می‌دهد که چگونه فناوری بلاک چین به وجود آمده است و به سرمایه‌گذاران بالقوه کمک می‌کند تا نقش خود را در دنیای دارایی‌های رمزنگاری کنند.</p>', '2018-06-13 00:00:00', 4, 489, 'https://images.blinkist.io/images/books/5b1d66deb238e10007002590/1_1/470.jpg', '/en/books/cryptoassets-en/purchase', 'دارایی-های-رمزنگاری-شده', '2023-01-26 19:53:50.053263', '2023-01-26 19:53:50.053263', NULL, 'Cryptoassets');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (668, 'سه ازدواج', 'تجسم مجدد کار، خود و رابطه', 'تجسم مجدد کار، خود و رابطه', 18, 8, 'book', 't', '<p>در <em>The Three Marriages</em>(2009)، دیوید وایت تجربه و استعداد دنیوی خود را به عنوان یک شاعر ترکیب می کند تا سه عشق بزرگی را که در طول زندگی خود پرورش می دهیم کشف کند: عشق به یک حرفه، عشق به خود عمیق تر خودمان و عشق به شخص خاصی که زندگی خود را با او به اشتراک می گذاریم.</p>', '2016-04-04 00:00:00', 4, 19, 'https://images.blinkist.io/images/books/56fe4ced8249800007000003/1_1/470.jpg', '/en/books/the-three-marriages-en/purchase', 'سه-ازدواج', '2023-01-26 19:53:55.209697', '2023-01-26 19:53:55.209697', NULL, 'The Three Marriages');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (669, 'ورزشگاه ذهن', 'راهنمای یک ورزشکار برای تعالی درونی', 'راهنمای یک ورزشکار برای تعالی درونی', 12, 5, 'book', 't', '<p><em>Mind Gym</em> (2001) نقش مهمی را که ذهن ما در عملکرد فیزیکی و برتری ورزشی ایفا می کند روشن می کند. این پلک‌ها به کار مک با ورزشکاران حرفه‌ای کمک می‌کنند تا ابزارهایی را که برای به دست آوردن وضعیت ذهنی با عملکرد عالی نیاز دارید در اختیار شما قرار دهند.</p>', '2016-03-28 00:00:00', 4, 135, 'https://images.blinkist.io/images/books/56f3ae092bf5b90007000001/1_1/470.jpg', '/en/books/mind-gym-en/purchase', 'ورزشگاه-ذهن', '2023-01-26 19:53:59.973993', '2023-01-26 19:53:59.973993', NULL, 'Mind Gym');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (670, 'مقام مبلغین', 'مادر ترزا در تئوری و عمل', 'مادر ترزا در تئوری و عمل', 12, 5, 'book', 't', '<p><em>موقعیت میسیونری</em> (1995) داستان واقعی راهبه معروف معروف به مادر ترزا را روایت می کند. این پلک‌ها توضیح می‌دهند که چگونه اسطوره‌ای متقاعدکننده و در عین حال نادرست پیرامون این نماد تاریخی شکل گرفت که کار و انگیزه‌های آن به اندازه‌ای که ما تصور می‌کردیم نجیب نبود.</p>', '2017-08-04 00:00:00', 4, 78, 'https://images.blinkist.io/images/books/597f444ab238e100057035d9/1_1/470.jpg', '/en/books/the-missionary-position-en/purchase', 'مقام-مبلغین', '2023-01-26 19:54:06.949089', '2023-01-26 19:54:06.949089', NULL, 'The Missionary Position');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (671, 'چگونه یاد می گیریم', 'حقیقت شگفت انگیز درباره زمان، کجا و چرا اتفاق می افتد', 'حقیقت شگفت انگیز درباره زمان، کجا و چرا اتفاق می افتد', 17, 8, 'book', 't', '<p><em>چگونه یاد می گیریم </em>مکانیسم های جذابی را در ذهن ما که خاطرات را شکل می دهند و نگه می دارند توضیح می دهد و نشان می دهد که چگونه با این اطلاعات می توانیم اطلاعات را بهتر جذب و حفظ کنیم. شما بسیاری از کارکردهای مغز را بررسی خواهید کرد و توصیه های عملی در مورد چگونگی مطالعه و یادگیری بهتر دریافت خواهید کرد.</p>', '2014-10-15 00:00:00', 4, 137, 'https://images.blinkist.io/images/books/543b8dec36623900081c0000/1_1/470.jpg', '/en/books/how-we-learn-en/purchase', 'چگونه-یاد-می-گیریم', '2023-01-26 19:54:12.179781', '2023-01-26 19:54:12.179781', NULL, 'How We Learn');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (672, 'در مورد بودن و شدن', 'رویکرد اگزیستانسیالیستی به زندگی', 'رویکرد اگزیستانسیالیستی به زندگی', 23, 7, 'book', 't', '<p><em>درباره بودن و شدن</em> (2021) به طور همزمان مقدمه ای بر فلسفه اگزیستانسیالیسم و ​​راهنمای زندگی خوب است. این کتاب با تکیه بر طیف گسترده‌ای از نویسندگان اگزیستانسیالیست اواخر قرن نوزدهم و اوایل قرن بیستم، موضوعات و بینش‌های اصلی این جنبش را باز می‌کند و توضیح می‌دهد که این به چه معناست برای اینکه چگونه باید زندگی کنید.</p>', '2021-06-24 00:00:00', 5, 437, 'https://images.blinkist.io/images/books/60d30aa56cee070007bee54b/1_1/470.jpg', '/en/books/on-being-and-becoming-en/purchase', 'در-مورد-بودن-و-شدن', '2023-01-26 19:54:17.487867', '2023-01-26 19:54:17.487867', NULL, 'On Being and Becoming');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (673, 'پایان همه چیز', '(از نظر اخترفیزیکی)', '(از نظر اخترفیزیکی)', 26, 6, 'book', 't', '<p>جهان چگونه به پایان می رسد؟ آیا سرد می شود، پاره می شود یا حتی با یک جهان موازی برخورد می کند؟ پلک زدن به <em>پایان همه چیز</em> (2020) به دورترین نقاط زمان و مکان نگاه می‌کند و به پایان نهایی جهان و همه چیز در آن می‌تابد. این کتاب با تکیه بر آخرین تحقیقات پیشرفته در کیهان‌شناسی و فیزیک ذرات، ما را با پنج مورد از محتمل‌ترین سناریوهای روز رستاخیز کیهانی معرفی می‌کند و توصیف می‌کند که واقعاً تجربه آن‌ها چگونه خواهد بود.</p>', '2022-09-25 00:00:00', 5, 50, 'https://images.blinkist.io/images/books/63297d316cee070008583c7b/1_1/470.jpg', '/en/books/the-end-of-everything-en/purchase', 'پایان-همه-چیز', '2023-01-26 19:54:22.663216', '2023-01-26 19:54:22.663216', NULL, 'The End of Everything');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (674, 'راهنمای آماده کار', 'مهارت های استخدامی و استراتژی های موفقیت شغلی', 'مهارت های استخدامی و استراتژی های موفقیت شغلی', 24, 9, 'book', 't', '<p><em>راهنمای آماده کار </em>(2019) یک نقشه راه مفید برای هرکسی است که می خواهد خود را در اولین پله نردبان شغلی قرار دهد. علاوه بر ارائه مشاوره در مورد جستجوی شغل، نوشتن یک رزومه متقاعد کننده، و عملکرد خوب در مصاحبه ها، بینشی را در مورد آنچه کارفرمایان مدرن واقعاً به دنبال آن هستند ارائه می دهد.</p>', '2020-02-24 00:00:00', 4, 31, 'https://images.blinkist.io/images/books/5e52a7216cee0700079a1a4e/1_1/470.jpg', '/en/books/the-job-ready-guide-en/purchase', 'راهنمای-آماده-کار', '2023-01-26 19:54:27.354404', '2023-01-26 19:54:27.354404', NULL, 'The Job-Ready Guide');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (675, 'نهنگ میلیارد دلاری', 'مردی که وال استریت، هالیوود و جهان را فریب داد', 'مردی که وال استریت، هالیوود و جهان را فریب داد', 30, 10, 'book', 't', '<p><em>نهنگ میلیارد دلاری </em>(2018) گزارشی قطعی است از این که چگونه یک کوهنورد اجتماعی مالزیایی زودباور و حسابگر به نام جو لو از یک صندوق سرمایه گذاری ملی کلاهبرداری کرد و یکی از بهترین های قرن بیست و یکم را از بین برد. دزدی های جسورانه حاصل سال‌ها تحقیق پرزحمت دو تن از برترین روزنامه‌نگاران تحقیقی آمریکایی، بر عملکرد مبهم شبکه‌ای متشکل از کلاهبرداران، کلاهبرداران و کلاهبرداران در سراسر جهان روشن می‌شود.</p>', '2019-08-30 00:00:00', 5, 142, 'https://images.blinkist.io/images/books/5d6502606cee0700081a593a/1_1/470.jpg', '/en/books/billion-dollar-whale-en/purchase', 'نهنگ-میلیارد-دلاری', '2023-01-26 19:54:32.171828', '2023-01-26 19:54:32.171828', NULL, 'Billion Dollar Whale');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (676, 'درب سوم', 'جستجوی وحشی برای کشف اینکه چگونه موفق ترین افراد جهان شغل خود را راه اندازی کردند', 'جستجوی وحشی برای کشف اینکه چگونه موفق ترین افراد جهان شغل خود را راه اندازی کردند', 27, 10, 'book', 't', '<p><em>درب سوم</em> (2018) داستان یک دانشجوی 18 ساله جاه طلب و جاه طلب را روایت می کند که تصمیم گرفت بیل گیتس، وارن بافت، لیدی گاگا و بسیاری دیگر از بهترین های جهان را ردیابی کند. افراد مشهور برای اینکه بفهمند چگونه به موفقیت بزرگ خود رسیده اند. بنایان پس از هک نمایش بازی <em>The Price is Right</em>و تامین مالی ماجراجویی خود با برنده شدن، از چتزپا و پشتکار خود برای دسترسی به نخبگان جهانی و یادگیری اسرار آنها استفاده کرد.</p>', '2018-08-24 00:00:00', 4, 68, 'https://images.blinkist.io/images/books/5b7d22e5b238e1000722f82f/1_1/470.jpg', '/en/books/the-third-door-en/purchase', 'درب-سوم', '2023-01-26 19:54:37.107561', '2023-01-26 19:54:37.107561', NULL, 'The Third Door');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (677, '5 صدا', 'چگونه با همه کسانی که رهبری می کنید ارتباط موثر برقرار کنید', 'چگونه با همه کسانی که رهبری می کنید ارتباط موثر برقرار کنید', 21, 8, 'book', 't', '<p><em>5 Voices </em>(2016) کتابچه راهنمای طراحی شده برای کمک به شما در برقراری ارتباط موثرتر در زندگی حرفه ای و شخصی است. برای انجام این کار، جرمی کوبیک و استیو کاکرام، متخصصان رهبری، استدلال می‌کنند که باید در مورد نوع ارتباطی که هستید مطلع شوید. این پلک‌ها پنج استراتژی ارتباطی را تشریح می‌کنند و نکات و ترفندهای زیادی را ارائه می‌کنند که به شما کمک می‌کند تا بدون وارد شدن به چهره افراد، هدف خود را متوجه شوید.</p>', '2019-05-27 00:00:00', 4, 125, 'https://images.blinkist.io/images/books/5ce86e596cee0700073a5aa8/1_1/470.jpg', '/en/books/5-voices-en/purchase', '5-صدا', '2023-01-26 20:03:28.259159', '2023-01-26 20:03:28.259159', NULL, '5 Voices');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (678, 'تأملات در فلسفه اول', 'دکارت مشهورترین کلاسیک فلسفی', 'دکارت مشهورترین کلاسیک فلسفی', 11, 5, 'book', 't', '<p><em>مراقبه‌هایی درباره اولین فلسفه</em> (1641) یکی از تأثیرگذارترین آثار دکارت است که به عنوان منبع نقل قول کلاسیک شناخته می‌شود: «من فکر می‌کنم، پس هستم» یا «<em>cogito ergo sum. </em>." این پلک‌ها افکار دکارت را در مورد چگونگی دانستن آنچه می‌دانیم و تلاش‌های او برای اثبات وجود خدا در این راه نشان می‌دهد.</p>', '2015-08-24 00:00:00', 4, 155, 'https://images.blinkist.io/images/books/55daea881f4e6e0009000003/1_1/470.jpg', '/en/books/meditations-on-first-philosophy-en/purchase', 'تأملات-در-فلسفه-اول', '2023-01-26 20:03:36.180832', '2023-01-26 20:03:36.180832', NULL, 'Meditations on First Philosophy');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (679, 'ضرورت ارتقاء مهارت', '5 روش برای اینکه یادگیری را به روشی که کار می کنیم هسته اصلی کنیم', '5 روش برای اینکه یادگیری را به روشی که کار می کنیم هسته اصلی کنیم', 16, 8, 'book', 't', '<p><strong>درباره چیست؟</strong></p>
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (680, 'اعتماد کنید و الهام بگیرید', 'چگونه رهبران واقعا بزرگ عظمت را در دیگران آزاد می کنند', 'چگونه رهبران واقعا بزرگ عظمت را در دیگران آزاد می کنند', 22, 4, 'book', 't', '<p><em>Trust & Inspire</em>(2022) یک مدل رهبری جدید ارائه می دهد. به جای رویکرد سنتی «فرماندهی و کنترل»، کاوی رویکردی را پیشنهاد می‌کند که بر همکاری، اعتماد و رشد شخصی تمرکز دارد. مجموعه جدیدی از ابزارها را برای الهام بخشیدن و باز کردن پتانسیل عظیم یک نیروی کار مدرن ارائه می دهد. </p>', '2022-10-17 00:00:00', 5, 46, 'https://images.blinkist.io/images/books/63491deb6cee070008f4a548/1_1/470.jpg', '/en/books/trust-and-inspire-en/purchase', 'اعتماد-کنید-و-الهام-بگیرید', '2023-01-26 20:03:50.990256', '2023-01-26 20:03:50.990256', NULL, 'Trust and Inspire');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (681, 'فقط گوش کن', 'راز ارتباط با همه افراد را کشف کنید', 'راز ارتباط با همه افراد را کشف کنید', 17, 7, 'book', 't', '<p><em>فقط</em> <em>گوش دادن</em> (2009) تکنیک‌های متقاعدسازی و گوش دادن آزمایش‌شده با زمان را با روش‌های جدید ترکیب می‌کند تا به شما کمک کند پیام خود را به دیگران برسانید. با یادگیری اینکه چگونه شنونده بهتری باشید، مغز چگونه کار می‌کند و مردم چگونه فکر می‌کنند، می‌توانید به مردم انگیزه دهید تا آنچه را که می‌خواهید انجام دهند، زیرا نیازهای آن‌ها را بهتر درک خواهید کرد.</p>', '2014-09-18 08:00:00', 4, 155, 'https://images.blinkist.io/images/books/54198b156439610008530000/1_1/470.jpg', '/en/books/just-listen-en/purchase', 'فقط-گوش-کن', '2023-01-26 20:03:56.280048', '2023-01-26 20:03:56.280048', NULL, 'Just Listen');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (682, 'نوع دوستی', 'قدرت شفقت برای تغییر خود و جهان', 'قدرت شفقت برای تغییر خود و جهان', 21, 9, 'book', 't', '<p><em>نوع دوستی</em> (2015) نیاز ما به مراقبت از دیگران را بررسی می کند، اجباری که هم در انسان و هم در حیوانات ضروری است. این پلک‌ها توضیح می‌دهند که چگونه و چرا مراقبان کاری را که انجام می‌دهند از طریق دریچه فلسفه، اقتصاد و نظریه تکامل انجام می‌دهند.</p>', '2015-11-23 00:00:00', 4, 29, 'https://images.blinkist.io/images/books/5653212c32663500071c0000/1_1/470.jpg', '/en/books/altruism-en/purchase', 'نوع-دوستی', '2023-01-26 20:04:03.204486', '2023-01-26 20:04:03.204486', NULL, 'Altruism');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (683, 'بدهی', '5000 سال اول', '5000 سال اول', 16, 9, 'book', 'f', '<p>بسیاری از ما تصور می کنیم که پول - یا به طور کلی سرمایه داری - بخش اساسی جامعه بشری است. در <em>Debt </em>(2011)، نویسنده دیوید گرابر، بررسی انسان‌شناختی پول را ارائه می‌کند که مفروضات رایج را به چالش می‌کشد و ادعا می‌کند که پول و مفهوم بدهی در واقع محصول شرایط تاریخی خاص هستند.</p>', '2015-03-02 00:00:00', 5, 47, 'https://images.blinkist.io/images/books/54f444d5333035000a240000/1_1/470.jpg', '/en/books/debt-en/purchase', 'بدهی', '2023-01-26 20:04:10.333319', '2023-01-26 20:04:10.333319', NULL, 'Debt');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (691, 'استثنایی', 'حلقه هایلایت شخصی خود را بسازید و پتانسیل خود را باز کنید', 'حلقه هایلایت شخصی خود را بسازید و پتانسیل خود را باز کنید', 19, 7, 'book', 't', '<p><em>Exceptional </em>(2020) به شما نشان می دهد که چگونه نقاط قوت خود را کشف کنید و بر روی آنها بسازید تا به بهترین نسخه از خود تبدیل شوید. با ایجاد یک حلقه برجسته شخصی از زندگی خود، یاد خواهید گرفت که چگونه استعدادهای خود را شناسایی کنید، اعتماد به نفس ایجاد کنید و پتانسیل کامل خود را - هم در محل کار و هم در خانه - باز کنید.</p>', '2021-02-15 00:00:00', 5, 68, 'https://images.blinkist.io/images/books/6026570a6cee070007691831/1_1/470.jpg', '/en/books/exceptional-en/purchase', 'استثنایی', '2023-01-26 20:05:07.943265', '2023-01-26 20:05:07.943265', NULL, 'Exceptional');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (684, 'میلیونرهای روزمره', 'مردم عادی چگونه ثروت خارق‌العاده‌ای می‌ساختند – و چگونه شما هم می‌توانید', 'مردم عادی چگونه ثروت خارق‌العاده‌ای می‌ساختند – و چگونه شما هم می‌توانید', 22, 8, 'book', 't', '<p><em>میلیونرهای هر روز </em>(2019) از بزرگترین مطالعه ای که تاکنون در ایالات متحده در مورد میلیونرها انجام شده است استفاده می کند تا یک حقیقت اساسی را فاش کند - میلیونر شدن کاری است که هر کسی می تواند انجام دهد. مهم نیست پیشینه شما چیست، اکنون چقدر پول در می آورید یا چقدر خوش شانس هستید - فقط به دانش عملی و تعهد برای دنبال کردن یک برنامه نیاز دارد.</p>', '2019-02-14 00:00:00', 4, 206, 'https://images.blinkist.io/images/books/5c62e7e56cee0700078afede/1_1/470.jpg', '/en/books/everyday-millionaires-en/purchase', 'میلیونرهای-روزمره', '2023-01-26 20:04:17.146957', '2023-01-26 20:04:17.146957', NULL, 'Everyday Millionaires');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (685, 'طلای دیجیتال', 'داستان ناگفته بیت کوین', 'داستان ناگفته بیت کوین', 14, 6, 'book', 't', '<p><em>Digital Gold</em> (2015) داستان افراد مختلف - از جمله سایفرپانک‌ها، نردها، سرمایه‌گذاران، قماربازان و آینده‌نگران - را روایت می‌کند که در ظهور موفق‌ترین ارز دیجیتال جهان، بیت‌کوین، نقش داشته‌اند. این کتاب یک نمای کلی از روش توسعه بیت کوین ارائه می دهد و نشان می دهد که چگونه ارزش آن از هیچ به بیش از 1 میلیارد دلار رسیده است و داستان مراحل اولیه مشکل آن را بیان می کند.</p>', '2016-03-25 00:00:00', 4, 183, 'https://images.blinkist.io/images/books/56f13471f77893000700005e/1_1/470.jpg', '/en/books/digital-gold-en/purchase', 'طلای-دیجیتال', '2023-01-26 20:04:24.414166', '2023-01-26 20:04:24.414166', NULL, 'Digital Gold');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (686, 'سرمایه گذاری مبتنی بر اهداف', 'چارچوبی چشم انداز برای مدیریت ثروت', 'چارچوبی چشم انداز برای مدیریت ثروت', 25, 7, 'book', 't', '<p><em>سرمایه گذاری مبتنی بر اهداف </em>(2022) توضیح می دهد که چگونه صنعت مدیریت ثروت در حال تغییر است، چگونه تئوری مدرن پورتفولیو دیگر مدرن تلقی نمی شود و چگونه تکامل محصول و تغییرات نظارتی این کار را برای سرمایه گذاران و سرمایه گذاران آسان تر می کند. مشاوران برای دسترسی به بخش‌های بازار که زمانی در حوزه انحصاری مؤسسات بزرگ بودند.</p>', '2022-05-27 00:00:00', 4, 122, 'https://images.blinkist.io/images/books/628df2186cee0700084919a6/1_1/470.jpg', '/en/books/goals-based-investing-en/purchase', 'سرمایه-گذاری-مبتنی-بر-اهداف', '2023-01-26 20:04:31.47702', '2023-01-26 20:04:31.47702', NULL, 'Goals-based Investing');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (687, 'پیدا کردن بکارت من', 'زندگینامه جدید', 'زندگینامه جدید', 29, 12, 'book', 't', '<p><em>Finding My Virginity</em> (2017) دنباله‌ای برای اولین زندگی‌نامه ریچارد برانسون با نام <em>از دست دادن باکرگی</em> است که مدت‌ها منتظرش بودیم. درست از جایی که کتاب قبلی متوقف شد، در آغاز قرن جدید با باز شدن بازار دیجیتال و مجموعه‌ای از فرصت‌های تجاری جدید، از جمله فرصت راه‌اندازی یک شرکت برای بردن مردم به فضا، شروع می‌شود.</p >
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (688, 'منشور مشارکت', 'چگونه با شراکت تجاری جدید خود درست شروع کنید (یا شراکتی را که در آن هستید اصلاح کنید)', 'چگونه با شراکت تجاری جدید خود درست شروع کنید (یا شراکتی را که در آن هستید اصلاح کنید)', 13, 7, 'book', 'f', '<p><em>منشور مشارکت</em> (2004) توضیح می‌دهد که چگونه شرکای تجاری می‌توانند با اطمینان از صحبت آشکار در مورد همه چیز، از آسیب پایدار به یک رابطه تجاری جلوگیری کنند. با استفاده از یک فرآیند آزمایش شده، شرکای تجاری می توانند اختلافات را کنار بگذارند و با موفقیت یک شرکت قوی با هم بسازند.</p>', '2015-05-26 00:00:00', NULL, 6, 'https://images.blinkist.io/images/books/5563aa2f6461640007370000/1_1/470.jpg', '/en/books/the-partnership-charter-en/purchase', 'منشور-مشارکت', '2023-01-26 20:04:46.558487', '2023-01-26 20:04:46.558487', NULL, 'The Partnership Charter');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (689, 'بدون اجازه آنها', 'قرن بیست و یکم چگونه ساخته خواهد شد، نه مدیریت', 'قرن بیست و یکم چگونه ساخته خواهد شد، نه مدیریت', 15, 9, 'book', 'f', '<p><em>بدون</em> <em>آنها</em> <em>مجوز</em> موفقیت نویسنده را با وب‌سایت بسیار محبوبش، Reddit، و همچنین سایر داستان‌های مرتبط با اینترنت بررسی می‌کند و به بررسی می‌پردازد. دقیقاً چه چیزی در مورد اینترنت است که آن را به مکانی فوق العاده و پویا تبدیل می کند. در طول مسیر، نویسنده توصیه هایی را به کارآفرینان ارائه می دهد که به او کمک کرد تا تجارت بسیار موفق خود را شکل دهد.</p>', '2014-06-03 13:54:07', NULL, 9, 'https://images.blinkist.io/images/books/538f210b36323900075f0000/1_1/470.jpg', '/en/books/without-their-permission-en/purchase', 'بدون-اجازه-آنها', '2023-01-26 20:04:53.710577', '2023-01-26 20:04:53.710577', NULL, 'Without Their Permission');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (690, 'هنر ظریف نگفتن', 'یک رویکرد ضد شهودی برای داشتن یک زندگی خوب', 'یک رویکرد ضد شهودی برای داشتن یک زندگی خوب', 19, 8, 'book', 't', '<p><em>هنر ظریف کتک زدن نکردن</em> (2016) نشان می‌دهد که چگونه با اهمیت دادن به چیزهای کمتر، زندگی بهتری داشته باشیم. اگر از چند قانون ساده پیروی کنید، می توانید از زندگی شادتر و کم استرس تری لذت ببرید.</p>', '2017-05-30 00:00:00', 4, 4112, 'https://images.blinkist.io/images/books/592933bbb238e10007b6b0a5/1_1/470.jpg', '/en/books/the-subtle-art-of-not-giving-a-f-star-ck-en/purchase', 'هنر-ظریف-نگفتن', '2023-01-26 20:05:01.095076', '2023-01-26 20:05:01.095076', NULL, 'The Subtle Art of Not Giving a F*ck');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (692, 'زندگی سخت است', 'چگونه فلسفه می تواند به ما در یافتن راه کمک کند', 'چگونه فلسفه می تواند به ما در یافتن راه کمک کند', 13, 4, 'book', 't', '<p><em>زندگی سخت است</em>(2022) از دریچه فلسفه، و همچنین داستان‌ها، ورزش، تاریخ و همچنین به مبارزات رایج - مانند ضعف، تنهایی، اندوه و شکست - نگاهی دقیق می‌اندازد. حکایات شخصی با بررسی سختی های آشنای شرایط انسانی، می توانیم یاد بگیریم که چگونه خوب زندگی کنیم.</p>', '2022-12-20 00:00:00', 4, 295, 'https://images.blinkist.io/images/books/639c6365ac4463000945c04d/1_1/470.jpg', '/en/books/life-is-hard-en/purchase', 'زندگی-سخت-است', '2023-01-26 20:05:12.825989', '2023-01-26 20:05:12.825989', NULL, 'Life Is Hard');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (693, 'بی نظم', 'چگونه در دنیایی مرتب و منظم خلاق و انعطاف پذیر باشیم', 'چگونه در دنیایی مرتب و منظم خلاق و انعطاف پذیر باشیم', 12, 5, 'book', 't', '<p><em>مثل</em> (2016) همه چیز در مورد نظم و آراستگی است، یا بهتر است بگوییم که چرا آنها بیش از حد ارزیابی می شوند. این پلک ها توضیح می دهند که چگونه دل مشغولی به آراستگی می تواند بین ما و موفقیت قرار گیرد، چگونه بی نظمی می تواند خلاقیت را تقویت کند و چرا همه باید کمی بی نظمی را بپذیرند.</p>', '2017-06-01 00:00:00', 4, 109, 'https://images.blinkist.io/images/books/592c01e2b238e1000507d11c/1_1/470.jpg', '/en/books/messy-en/purchase', 'بی-نظم', '2023-01-26 20:05:18.069114', '2023-01-26 20:05:18.069114', NULL, 'Messy');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (694, 'هنر زندگی کردن', 'کتابچه راهنمای کلاسیک در مورد فضیلت، شادی و اثربخشی - تفسیری جدید توسط شارون لبل', 'کتابچه راهنمای کلاسیک در مورد فضیلت، شادی و اثربخشی - تفسیری جدید توسط شارون لبل', 21, 7, 'book', 't', '<p><em>هنر زندگی </em>(1995) مقدمه ای روشن و مختصر برای فلسفه رواقی است. این تفسیر مدرن از آموزه‌های اپکتتوس بینش بی‌زمانی را برای داشتن یک زندگی پایدار و رضایت‌بخش می‌دهد.</p>', '2022-01-23 00:00:00', 5, 531, 'https://images.blinkist.io/images/books/61e55e5f6cee0700086d33e5/1_1/470.jpg', '/en/books/the-art-of-living-en-epictetus/purchase', 'هنر-زندگی-کردن', '2023-01-26 20:05:25.247159', '2023-01-26 20:05:25.247159', NULL, 'The Art of Living');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (695, 'پروست چگونه می تواند زندگی شما را تغییر دهد', 'بینش‌های ارزشمند برای داشتن بهترین زندگی', 'بینش‌های ارزشمند برای داشتن بهترین زندگی', 26, 5, 'book', 't', '<p><em>چگونه پروست می تواند زندگی شما را تغییر دهد </em>(1997) بیوگرافی ادبی را با ساختار خودیاری ترکیب می کند تا استدلال کند که خواندن آثار مارسل پروست نویسنده فرانسوی قرن بیستم نه تنها از نظر فرهنگی غنی است، بلکه به طور بالقوه افزایش دهنده زندگی خواندن دقیق بوتون از شاهکار پروست، <em>در جستجوی زمان از دست رفته</em>، بینش شگفت انگیز و لذت بخشی را در مورد چگونگی بهتر زیستن ارائه می دهد.</p>', '2022-06-23 00:00:00', 5, 275, 'https://images.blinkist.io/images/books/62b1dad46cee0700083e888d/1_1/470.jpg', '/en/books/how-proust-can-change-your-life-en/purchase', 'پروست-چگونه-می-تواند-زندگی-شما-را-تغییر-دهد', '2023-01-26 20:05:32.099249', '2023-01-26 20:05:32.099249', NULL, 'How Proust Can Change Your Life');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (696, 'سالنامه ناوال راویکانت', 'راهنمای ثروت و خوشبختی', 'راهنمای ثروت و خوشبختی', 23, 7, 'book', 't', '<p><em>سالنامه ناوال راویکانت </em>(2020) خرد فیلسوف و کارآفرین ناوال راویکانت را به قطعاتی عملی و کوچک تبدیل می کند. اگرچه او موضوعات بسیاری را پوشش می دهد، این مجموعه بینش حول دو سوال عمیق است - چگونه ثروت بسازید و چگونه خوشبختی پیدا کنید؟ پاسخ راویکانت؟ هر دو مهارت هایی هستند که باید تمرین شوند.</p>', '2021-07-08 00:00:00', 5, 562, 'https://images.blinkist.io/images/books/60e423bb6cee070007a2be48/1_1/470.jpg', '/en/books/the-almanack-of-naval-ravikant-en-eric-jorgenson/purchase', 'سالنامه-ناوال-راویکانت', '2023-01-26 20:05:39.121039', '2023-01-26 20:05:39.121039', NULL, 'The Almanack of Naval Ravikant');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (697, 'هر جا با هم کار کنید', 'کتاب راهنمای کار از راه دور – با موفقیت – برای افراد، تیم ها و مدیران', 'کتاب راهنمای کار از راه دور – با موفقیت – برای افراد، تیم ها و مدیران', 24, 8, 'book', 't', '<p><em>Work Together Anywhere</em>(2018) با بررسی مزایایی که گزینه‌های کار از راه دور انعطاف‌پذیر می‌تواند برای کارکنان و مدیران به طور یکسان ارائه کند، آینده کار اداری را در نظر می‌گیرد. این مهارت ها و طرز فکر مورد نیاز برای کار در یک ظرفیت از راه دور - یا مدیریت تیمی از کارگران از راه دور - و همچنین استفاده از فناوری که همه این کارها را ممکن می کند را مشخص می کند. </p>
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (698, 'چگونه موش را بو کنیم', 'پنج نشانه کلاهبرداری مالی', 'پنج نشانه کلاهبرداری مالی', 16, 7, 'book', 't', '<p><em>چگونه موش را بو کنیم </em>ابزارهایی را در اختیار شما قرار می دهد که برای جلوگیری از قربانی شدن در تقلب مالی به آن نیاز دارید. ترفندهای مورد علاقه کلاهبرداران افسانه ای را فهرست می کند.</p>', '2015-03-12 00:00:00', 4, 22, 'https://images.blinkist.io/images/books/54fdd19b626661000a8d0000/1_1/470.jpg', '/en/books/how-to-smell-a-rat-en/purchase', 'چگونه-موش-را-بو-کنیم', '2023-01-26 20:05:53.713848', '2023-01-26 20:05:53.713848', NULL, 'How to Smell a Rat');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (714, 'جادوی بزرگ', 'زندگی خلاق فراتر از ترس', 'زندگی خلاق فراتر از ترس', 12, 6, 'book', 't', '<p><em>جادوی بزرگ</em> (2015) آنچه را که ما را می ترساند و هیجان زده می کند، بررسی می کند: تبدیل ایده های خلاقانه ما به واقعیت. این پلک‌ها استراتژی‌های مفیدی را ارائه می‌کنند که به شما امکان می‌دهد ترس‌ها، ناامیدی‌ها و موانع ایجاد را مدیریت کنید و به شما امکان می‌دهد بازیگوشی‌ای را که برای ابراز آزادانه نیاز دارید، کانالیزه کنید.</p>', '2015-12-16 00:00:00', 4, 174, 'https://images.blinkist.io/images/books/566fe2fdcf6aa3000700002f/1_1/470.jpg', '/en/books/big-magic-en/purchase', 'جادوی-بزرگ', '2023-01-26 20:07:43.200135', '2023-01-26 20:07:43.200135', NULL, 'Big Magic');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (699, 'چگونه با تلفن خود قطع رابطه کنیم', 'برنامه 30 روزه برای پس گرفتن زندگی شما', 'برنامه 30 روزه برای پس گرفتن زندگی شما', 26, 10, 'book', 't', '<p><em>چگونه با تلفن خود قطع رابطه کنیم </em>(2018) روابط آشکار و اغلب اعتیادآوری که ما با تلفن های خود داریم را بررسی می کند. این پلک‌ها به این موضوع اشاره می‌کنند که چگونه می‌توانیم با آگاهی بیشتری از تلفن‌ها استفاده کنیم. اگر به درستی انجام شود، می‌توانیم استفاده از دستگاه‌هایمان را برای ایجاد حواس‌پرتی بی‌پایان متوقف کنیم و در عوض از آنها به عنوان ابزاری برای بهبود زندگی‌مان استفاده کنیم.</p>', '2019-04-15 00:00:00', 4, 180, 'https://images.blinkist.io/images/books/5cb3b4e46cee070007005770/1_1/470.jpg', '/en/books/how-to-break-up-with-your-phone-en/purchase', 'چگونه-با-تلفن-خود-قطع-رابطه-کنیم', '2023-01-26 20:06:01.06651', '2023-01-26 20:06:01.06651', NULL, 'How to Break Up with Your Phone');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (700, 'اسرار جاده شن هیل', 'سرمایه خطرپذیر و نحوه دریافت آن', 'سرمایه خطرپذیر و نحوه دریافت آن', 19, 6, 'book', 't', '<p><em>Secrets of Sand Hill Road </em>(2019) از ساختار داخلی یکی از نمادین ترین خیابان های سیلیکون ولی پرده برداری می کند. بسیاری از برترین شرکت‌های سرمایه‌گذاری خطرپذیر منطقه در اینجا واقع شده‌اند و در تأمین مالی برخی از بزرگترین نام‌های فناوری امروز نقش داشته‌اند. اسکات کوپور، عضو VC، با بسیاری از آن‌ها کار کرده است، و این پلک‌ها رازهای خود را به اشتراک می‌گذارند - به بقیه ما اجازه می‌دهد رمز و راز سرمایه‌گذاری خطرپذیر، نحوه بدست آوردن آن و اینکه چرا می‌تواند باعث ایجاد یا شکست یک شرکت شود، رمزگشایی کنیم.</p>', '2019-07-03 00:00:00', 4, 123, 'https://images.blinkist.io/images/books/5d17de0b6cee070006febf06/1_1/470.jpg', '/en/books/secrets-of-sand-hill-road-en/purchase', 'اسرار-جاده-شن-هیل', '2023-01-26 20:06:08.95825', '2023-01-26 20:06:08.95825', NULL, 'Secrets of Sand Hill Road');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (701, 'بازیکن تیم ایده آل', 'چگونه سه فضیلت اساسی را بشناسیم و پرورش دهیم. افسانه رهبری', 'چگونه سه فضیلت اساسی را بشناسیم و پرورش دهیم. افسانه رهبری', 14, 6, 'book', 't', '<p><em>بازیکن تیم ایده‌آل</em> (2016) نقش کار گروهی را در محیط کسب‌وکار امروزی بررسی می‌کند و به شما نشان می‌دهد که چگونه تیمی را برای موفقیت بسازید. این پلک‌ها توضیح می‌دهند که چه چیزی یک بازیکن تیم خوب را می‌سازد، چگونه می‌توان آن‌ها را پیدا کرد و به چه استراتژی‌هایی برای ایجاد یک شرکت بر اساس مفهوم کار تیمی نیاز دارید.</p>', '2016-10-19 00:00:00', 5, 139, 'https://images.blinkist.io/images/books/580614c5319fa90003feb9b8/1_1/470.jpg', '/en/books/the-ideal-team-player-en/purchase', 'بازیکن-تیم-ایده-آل', '2023-01-26 20:06:17.42055', '2023-01-26 20:06:17.42055', NULL, 'The Ideal Team Player');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (702, 'داستان های دریا', 'زندگی من در عملیات ویژه', 'زندگی من در عملیات ویژه', 23, 8, 'book', 't', '<p><em>Sea Stories </em>(2019) مجموعه‌ای از داستان‌های زندگی ویلیام اچ. این پلک‌ها نگاهی شخصی به زندگی یک قهرمان جنگی شجاع و همچنین گزارش دست اولی از برخی از معروف‌ترین مأموریت‌های تاریخ اخیر ایالات متحده را ارائه می‌دهد.</p>', '2019-06-18 00:00:00', 4, 109, 'https://images.blinkist.io/images/books/5d056e516cee070007e3ca54/1_1/470.jpg', '/en/books/sea-stories-en/purchase', 'داستان-های-دریا', '2023-01-26 20:06:22.489103', '2023-01-26 20:06:22.489103', NULL, 'Sea Stories');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (703, 'جودوی کلامی', 'هنر ملایم متقاعدسازی', 'هنر ملایم متقاعدسازی', 19, 8, 'book', 't', '<p><em>جودوی کلامی </em>(1993) از دیدگاه افسر پلیس راهنمای شما برای برقراری ارتباط موثر است. این پلک‌ها توضیح می‌دهند که چرا برخی از تکنیک‌های ارتباطی رایج می‌توانند مانع شما شوند و چرا برخی دیگر ممکن است برای دستیابی به اهداف ارتباطی شما مناسب‌تر باشند.</p>', '2017-12-15 00:00:00', 4, 81, 'https://images.blinkist.io/images/books/5a2d7814b238e1000a9f2ca5/1_1/470.jpg', '/en/books/verbal-judo-en/purchase', 'جودوی-کلامی', '2023-01-26 20:06:29.206136', '2023-01-26 20:06:29.206136', NULL, 'Verbal Judo');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (704, 'بالای ذهن', 'از محتوا برای آزادسازی نفوذ خود و جذب کسانی که برای شما مهم هستند استفاده کنید', 'از محتوا برای آزادسازی نفوذ خود و جذب کسانی که برای شما مهم هستند استفاده کنید', 14, 5, 'book', 't', '<p><em>Top of Mind</em> (2017) با کمک به آنها در رهایی از روش های قدیمی و قدیمی و پذیرش جنبش جدید "You Marketing"، دیدگاه جدیدی هیجان انگیز در مورد بازاریابی را به خوانندگان ارائه می دهد. نویسنده جان هال ابزارها و بینش لازم برای پیمایش در دنیای جدید بازاریابی را فراهم می کند، به ویژه بر چگونگی جلب اعتماد مخاطب و هدف قرار دادن نیازهای آنها.</p>', '2018-07-05 00:00:00', 4, 65, 'https://images.blinkist.io/images/books/5b3ab75eb238e1000752dc4f/1_1/470.jpg', '/en/books/top-of-mind-en/purchase', 'بالای-ذهن', '2023-01-26 20:06:36.528793', '2023-01-26 20:06:36.528793', NULL, 'Top of Mind');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (705, 'هنر یادگیری', 'سفری درونی به سوی عملکرد بهینه', 'سفری درونی به سوی عملکرد بهینه', 15, 7, 'book', 't', '<p><em>هنر یادگیری </em>(2007) یک دوره ی تصادفی برای بهبود عملکرد ذهنی شما ارائه می دهد. در این پلک‌ها، نویسنده از تجربیات دوران حرفه‌ای شطرنج و تمرین هنرهای رزمی خود استفاده می‌کند تا طیف وسیعی از روش‌ها و تکنیک‌ها را ارائه دهد تا مغز شما را سخت‌تر، سریع‌تر و مؤثرتر کند.</p>', '2016-01-01 00:00:00', 4, 205, 'https://images.blinkist.io/images/books/5681bc7a704a880007000064/1_1/470.jpg', '/en/books/the-art-of-learning-en/purchase', 'هنر-یادگیری', '2023-01-26 20:06:43.482295', '2023-01-26 20:06:43.482295', NULL, 'The Art of Learning');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (738, 'پر', 'تکامل یک معجزه طبیعی', 'تکامل یک معجزه طبیعی', 13, 6, 'book', 't', '<p><em>Feathers</em> (2011) همه چیز در مورد تکامل و اهمیت رفقای ما، پرندگان است. این پلک‌ها توضیح می‌دهند که چگونه پرها به وجود آمده‌اند، چرا پرها منحصربه‌فرد هستند و چگونه بر همه چیز از فرهنگ انسانی گرفته تا فناوری تأثیر گذاشته‌اند.</p>', '2017-07-27 00:00:00', NULL, 9, 'https://images.blinkist.io/images/books/59773cc1b238e10005084241/1_1/470.jpg', '/en/books/feathers-en/purchase', 'پر', '2023-01-26 20:10:33.152772', '2023-01-26 20:10:33.152772', NULL, 'Feathers');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (706, 'ایجاد کسب و کار اجتماعی', 'نوع جدیدی از سرمایه داری که نیازهای مبرم بشریت را تامین می کند', 'نوع جدیدی از سرمایه داری که نیازهای مبرم بشریت را تامین می کند', 11, 5, 'book', 't', '<p><em>ساخت کسب‌وکار اجتماعی</em> (2010) راهنمای کسب‌وکارهای اجتماعی است، یعنی شرکت‌هایی که کارهای خوبی انجام می‌دهند. این پلک‌ها همه چیزهایی را که باید در مورد اینکه کسب‌وکارهای اجتماعی چیست، چگونه کار می‌کنند و برای راه‌اندازی کسب‌وکار خود به چه چیزی نیاز دارید بدانید را توضیح می‌دهد - و شروع به تغییر جهان برای بهتر شدن کنید.</p>', '2016-04-18 00:00:00', 4, 34, 'https://images.blinkist.io/images/books/5713abe15236f20007c16f59/1_1/470.jpg', '/en/books/building-social-business-en/purchase', 'ایجاد-کسب-و-کار-اجتماعی', '2023-01-26 20:06:50.815225', '2023-01-26 20:06:50.815225', NULL, 'Building Social Business');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (707, 'پتانسیل بزرگ', 'چگونه تغییر در جستجوی موفقیت باعث افزایش موفقیت، شادی و رفاه ما می شود', 'چگونه تغییر در جستجوی موفقیت باعث افزایش موفقیت، شادی و رفاه ما می شود', 19, 6, 'book', 't', '<p><em>پتانسیل بزرگ </em>(2018) نشان می‌دهد که چگونه می‌توانیم با همکاری با دیگران به جای رقابت با آنها، پتانسیل خود را به حداکثر برسانیم. تعقیب موفقیت فردی تنها به کسری از توانایی های ما کمک می کند. اما با برقراری ارتباط با افراد دیگر، یادگیری از آنها و حمایت از یکدیگر، می توانیم پتانسیل های پنهان را باز کنیم و به ارتفاعات جدیدی برسیم.</p>', '2020-09-21 00:00:00', 4, 177, 'https://images.blinkist.io/images/books/5f64be566cee07000623d52f/1_1/470.jpg', '/en/books/big-potential-en/purchase', 'پتانسیل-بزرگ', '2023-01-26 20:06:55.687026', '2023-01-26 20:06:55.687026', NULL, 'Big Potential');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (708, 'مراقبه', 'اولین و آخرین آزادی', 'اولین و آخرین آزادی', 25, 7, 'book', 't', '<p><em>مدیتیشن </em>(1988) نمای کلی ارزشمندی از مراقبه های اوشو ارائه می دهد - رویکردی به مراقبه که بر آگاهی تأکید دارد و از حرکت به عنوان راهی برای آماده سازی ذهن و بدن استفاده می کند. این اصول اساسی در پشت مدیتیشن اوشو، و همچنین چند تکنیک اساسی برای شروع شما را ارائه می دهد.</p>', '2021-08-14 00:00:00', 4, 221, 'https://images.blinkist.io/images/books/610d4a436cee070007ec88ad/1_1/470.jpg', '/en/books/meditation-en/purchase', 'مراقبه', '2023-01-26 20:07:02.949969', '2023-01-26 20:07:02.949969', NULL, 'Meditation');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (709, 'آسمان پر از پرندگان', 'در جستجوی قتل‌ها، سوژه‌ها و گردهمایی‌های بزرگ پرندگان بریتانیا', 'در جستجوی قتل‌ها، سوژه‌ها و گردهمایی‌های بزرگ پرندگان بریتانیا', 17, 7, 'book', 't', '<p><em>آسمان پر از پرندگان</em> (2016) جشن زندگی پرندگان در بریتانیا است. این پلک‌ها بینش‌های شگفت‌انگیزی از آیین‌های جفت‌گیری و الگوهای مهاجرت ارائه می‌دهند و اهمیت فرهنگی زمزمه‌ها، قتل‌ها، آوازهای قو و موارد دیگر را توضیح می‌دهند.</p>', '2016-07-12 00:00:00', NULL, 8, 'https://images.blinkist.io/images/books/577fa495c088090003fe9ebb/1_1/470.jpg', '/en/books/a-sky-full-of-birds-en/purchase', 'آسمان-پر-از-پرندگان', '2023-01-26 20:07:10.196154', '2023-01-26 20:07:10.196154', NULL, 'A Sky Full of Birds');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (710, 'قوانین ساده', 'چگونه در دنیای پیچیده پیشرفت کنیم', 'چگونه در دنیای پیچیده پیشرفت کنیم', 18, 8, 'book', 't', '<p><em>قوانین ساده</em> (2015) حاوی قوانین سرانگشتی نهایی است که شما را به اهدافتان در زندگی حرفه‌ای و همچنین زندگی شخصی‌تان راهنمایی می‌کند. نکات ارائه شده در این چشمک‌ها به شما کمک می‌کند تا سادگی را در دنیای مدرن مدرن و پیچیده‌تر کشف کنید، بدون اینکه شما را به یک چک لیست دیوانه‌وار که زندگی شما را تحت الشعاع قرار می‌دهد، بازیابی کنید.</p>', '2015-09-11 00:00:00', 4, 27, 'https://images.blinkist.io/images/books/55ed536211ad1a00090000ad/1_1/470.jpg', '/en/books/simple-rules-en/purchase', 'قوانین-ساده', '2023-01-26 20:07:17.027152', '2023-01-26 20:07:17.027152', NULL, 'Simple Rules');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (711, 'عنصر', 'چگونه یافتن علاقه خود همه چیز را تغییر می دهد', 'چگونه یافتن علاقه خود همه چیز را تغییر می دهد', 13, 6, 'book', 't', '<p><em>عنصر</em> (2009) در مورد ورود به منطقه و کشف دقیقاً چیزی است که شما را به حرکت در می آورد. آن درایور <em>عنصر</em> شما است و این پلک‌ها دقیقاً توضیح می‌دهند که چیست، چگونه آن را شناسایی کنید و چه معنایی برای زندگی شما خواهد داشت.</p>', '2017-07-19 00:00:00', 4, 93, 'https://images.blinkist.io/images/books/596b2ec7b238e10005430beb/1_1/470.jpg', '/en/books/the-element-en/purchase', 'عنصر', '2023-01-26 20:07:24.221202', '2023-01-26 20:07:24.221202', NULL, 'The Element');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (712, 'بخورید تا بیماری را شکست دهید', 'علم جدید چگونه بدن شما می تواند خود را درمان کند', 'علم جدید چگونه بدن شما می تواند خود را درمان کند', 19, 6, 'book', 't', '<p><em>Eat to Beat Disease</em> (2019) به سیستم های پیچیده ای که بدن برای دفاع از خود در برابر بیماری های کشنده استفاده می کند، نور می تاباند. این پلک‌ها با تکیه بر آخرین تحقیقات علمی، چگونگی حمایت از انتخاب‌های غذایی شما از این سیستم‌های دفاعی را بررسی می‌کنند و توضیح می‌دهند که چگونه، در مورد سلامتی شما، غذا واقعاً دارو است.</p>', '2019-05-02 00:00:00', 5, 259, 'https://images.blinkist.io/images/books/5cc8187b6cee070008221265/1_1/470.jpg', '/en/books/eat-to-beat-disease-en/purchase', 'بخورید-تا-بیماری-را-شکست-دهید', '2023-01-26 20:07:31.017872', '2023-01-26 20:07:31.017872', NULL, 'Eat to Beat Disease');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (713, 'تلقیح اعتیاد', 'تربیت فرزندان سالم در فرهنگ وابستگی', 'تربیت فرزندان سالم در فرهنگ وابستگی', 18, 6, 'book', 't', '<p><em>تلقیح اعتیاد </em>(2021) راهنمای والدینی برای تربیت کودکانی است که دانش، حمایت و اعتماد به نفس لازم برای دوری از خطرات دوگانه مصرف الکل و مواد مخدر را دارند. از فشار همسالان تا خودکارآمدی، خطراتی را که کودکان باید از آنها اجتناب کنند و دفاعی که باید برای داشتن زندگی شاد، سالم و بدون مواد به دست آورند، بررسی می‌کند.</p>', '2022-01-12 00:00:00', 4, 135, 'https://images.blinkist.io/images/books/61dc129e6cee070008adc943/1_1/470.jpg', '/en/books/the-addiction-inoculation-en/purchase', 'تلقیح-اعتیاد', '2023-01-26 20:07:36.2007', '2023-01-26 20:07:36.2007', NULL, 'The Addiction Inoculation');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (715, 'جهانی بدون یخ', 'چه اتفاقی می افتد اگر تغییرات آب و هوایی مسیر خود را طی کند؟', 'چه اتفاقی می افتد اگر تغییرات آب و هوایی مسیر خود را طی کند؟', 16, 7, 'book', 't', '<p><em>جهانی بدون یخ</em> (2009) درباره سیاره ما، آب و هوای آن، ساکنان انسانی آن - و یخ است. یخ همیشه نقش مهمی در آب و هوای زمین داشته است. این پلک‌ها توضیح می‌دهند که چرا ممکن است به زودی جهانی بدون یخ ببینیم، چرا این امر عواقب چشمگیری برای زمین و انسان‌ها دارد، و چگونه می‌توانیم با تغییرات آب و هوایی کنار بیاییم.</p>', '2016-02-21 00:00:00', 4, 22, 'https://images.blinkist.io/images/books/56cb410b9bb2160007000007/1_1/470.jpg', '/en/books/a-world-without-ice-en/purchase', 'جهانی-بدون-یخ', '2023-01-26 20:07:50.473566', '2023-01-26 20:07:50.473566', NULL, 'A World Without Ice');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (716, 'باشگاه ساعت 5 صبح', 'صاحب صبح خود شوید. زندگی خود را بالا ببرید.', 'صاحب صبح خود شوید. زندگی خود را بالا ببرید.', 22, 6, 'book', 't', '<p><em>باشگاه 5 صبح</em> (2018) نشان می‌دهد که چگونه پذیرفتن یک روال صبحگاهی انقلابی می‌تواند نتایج حماسی را به همراه داشته باشد. از طریق داستان دلربا یک کارآفرین، یک هنرمند، و مربی میلیاردر عجیب و غریب آنها، توضیح می‌دهد که چگونه می‌توانید از اولین ساعت روز خود برای رشد شخصی استفاده کنید و بیشترین بهره را از زندگی ببرید.</p>', '2019-01-22 00:00:00', 5, 6163, 'https://images.blinkist.io/images/books/5c43b2fa6cee07000701bf7a/1_1/470.jpg', '/en/books/the-5-am-club-en/purchase', 'باشگاه-ساعت-5-صبح', '2023-01-26 20:07:57.225399', '2023-01-26 20:07:57.225399', NULL, 'The 5 AM Club');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (717, 'تمرکز بیش از حد', 'چگونه کمتر کار کنیم تا بیشتر به دست آوریم', 'چگونه کمتر کار کنیم تا بیشتر به دست آوریم', 20, 6, 'book', 't', '<p><em>Hyperfocus </em>(2018) یک راهنمای ساده برای بازپس گیری توجه است که نشان می دهد چگونه می توانید بهره وری و خلاقیت خود را با یادگیری تغییر جهت دادن تمرکز خود افزایش دهید. ترکیب دوره‌های تمرکز شدید با طلسم‌های تفکر خلاق، پایه و اساس یک نسخه درخشان‌تر و کارآمدتر از شما را ایجاد می‌کند.</p>', '2021-04-03 00:00:00', 4, 495, 'https://images.blinkist.io/images/books/6062decd6cee070007a0b76d/1_1/470.jpg', '/en/books/hyperfocus-en/purchase', 'تمرکز-بیش-از-حد', '2023-01-26 20:08:04.199516', '2023-01-26 20:08:04.199516', NULL, 'Hyperfocus');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (718, 'اهداف', 'چگونه از زندگی خود بیشترین بهره را ببرید', 'چگونه از زندگی خود بیشترین بهره را ببرید', 18, 6, 'book', 't', '<p><em>اهداف </em>(2019) راهنمای جامعی برای تعیین اهداف و دستیابی به آنها ارائه می دهد. با یادگیری نحوه برنامه ریزی، مسئول نگه داشتن خود و تقویت ویژگی های شخصی که برای دنبال کردن رویاهای خود نیاز دارید، احتمال موفقیت شما بیشتر است.</p>', '2021-07-26 00:00:00', 5, 369, 'https://images.blinkist.io/images/books/60fad56d6cee070007e5948d/1_1/470.jpg', '/en/books/goals-en-zig-ziglar/purchase', 'اهداف', '2023-01-26 20:08:10.975758', '2023-01-26 20:08:10.975758', NULL, 'Goals');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (719, 'همه کار بدون پخش', 'راهنمای شگفت‌انگیز برای احساس آگاهی بیشتر، سپاسگزار و شاد', 'راهنمای شگفت‌انگیز برای احساس آگاهی بیشتر، سپاسگزار و شاد', 19, 6, 'book', 't', '<p><em>همه کار بدون بازی </em>(2021) ترفندها و نکاتی را برای کسب شادی و لذت بیشتر از زندگی روزمره آموزش می دهد. این کتاب راهنمای سرگرم‌کننده و کاربردی از استراتژی‌های تمرکز حواس مبتنی بر بازی استفاده می‌کند که به شما کمک می‌کند روابط را بهبود ببخشید، بهزیستی ذهنی را تقویت کنید و با کودک درونتان ارتباط برقرار کنید. </p>', '2021-07-29 00:00:00', 5, 306, 'https://images.blinkist.io/images/books/60fe5e096cee070007de23bf/1_1/470.jpg', '/en/books/all-work-no-play-en/purchase', 'همه-کار-بدون-پخش', '2023-01-26 20:08:18.183727', '2023-01-26 20:08:18.183727', NULL, 'All Work No Play');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (720, 'هنر عدم انطباق', 'قوانین خود را تنظیم کنید، زندگی را که می خواهید زندگی کنید و دنیا را تغییر دهید', 'قوانین خود را تنظیم کنید، زندگی را که می خواهید زندگی کنید و دنیا را تغییر دهید', 18, 8, 'book', 't', '<p>بر اساس وبلاگ نویسنده و مانیفست آنلاین، «راهنمای مختصری برای سلطه بر جهان»، <em>هنر عدم انطباق </em>(2010)<em></em>به روش‌های پیگیری غیرمتعارف می‌پردازد. زندگی می کنید و ابزارهایی را برای تنظیم قوانین خود، موفقیت با علایق و به جا گذاشتن میراث ارائه می دهد.</p>', '2014-02-19 11:42:31', 4, 106, 'https://images.blinkist.io/images/books/530493623439370008630000/1_1/470.jpg', '/en/books/the-art-of-non-conformity-en/purchase', 'هنر-عدم-انطباق', '2023-01-26 20:08:25.302876', '2023-01-26 20:08:25.302876', NULL, 'The Art Of Non-Conformity');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (721, 'چرا ازدواج ها موفق می شوند یا شکست می خورند؟', 'و چگونه می توانید مال خود را ماندگار کنید', 'و چگونه می توانید مال خود را ماندگار کنید', 22, 5, 'book', 't', '<p><em>چرا ازدواج ها موفق می شوند یا شکست می خورند </em>(1994) راهنمای روشنگری برای ایجاد روابط موفق است. این چهار پرچم قرمز را که باید در رابطه خود به آن توجه کنید، و چگونگی ترمیم الگوهای منفی و کشف مجدد آنچه که در وهله اول باعث شده است که عاشق شوید، توصیف می کند.</p>', '2022-04-22 00:00:00', 5, 159, 'https://images.blinkist.io/images/books/6257d97c6cee070008dbfa76/1_1/470.jpg', '/en/books/why-marriages-succeed-or-fail-en/purchase', 'چرا-ازدواج-ها-موفق-می-شوند-یا-شکست-می-خورند؟', '2023-01-26 20:08:32.643232', '2023-01-26 20:08:32.643232', NULL, 'Why Marriages Succeed or Fail');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (722, 'سلامت محل کار که کار می کند', '10 گام برای القای رفاه و سرزندگی در هر سازمانی', '10 گام برای القای رفاه و سرزندگی در هر سازمانی', 23, 10, 'book', 't', '<p><em>Workplace Wellness That Works</em> (2015) برداشت تازه ای از نحوه ایجاد رفاه بیشتر در هر سازمانی ارائه می دهد. این یک راهنمای 10 مرحله‌ای مملو از مثال‌های عملی از دنیای کسب‌وکار در مورد چگونگی آغاز، گسترش و حفظ جنبش رفاهی خود را ارائه می‌دهد.</p>', '2015-12-03 00:00:00', 4, 24, 'https://images.blinkist.io/images/books/565c8232990675000700006a/1_1/470.jpg', '/en/books/workplace-wellness-that-works-en/purchase', 'سلامت-محل-کار-که-کار-می-کند', '2023-01-26 20:08:39.825626', '2023-01-26 20:08:39.825626', NULL, 'Workplace Wellness that Works');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (723, 'کاهش هزینه ها نه گوشه ها', 'راهنمای عملی برای رقابتی ماندن و بهبود سود', 'راهنمای عملی برای رقابتی ماندن و بهبود سود', 15, 6, 'book', 't', '<p><em>Cut Costs Not Corners</em> (2010) راهنمایی برای مدیریت و به حداقل رساندن هزینه های هر کسب و کاری در عین حفظ کیفیت محصولات و خدمات آن است. این پلک‌ها مملو از نمونه‌های عملی است که به شما می‌آموزد چگونه چربی‌های بودجه خود را کاهش دهید و در عین حال مشتریان و کارمندان خود را راضی نگه دارید.</p>', '2015-11-26 00:00:00', 4, 13, 'https://images.blinkist.io/images/books/56542eb96362640007800000/1_1/470.jpg', '/en/books/cut-costs-not-corners-en/purchase', 'کاهش-هزینه-ها-نه-گوشه-ها', '2023-01-26 20:08:46.608167', '2023-01-26 20:08:46.608167', NULL, 'Cut Costs Not Corners');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (724, 'قهوه ناهار قهوه', 'راهنمای میدانی عملی برای شبکه های کارشناسی ارشد', 'راهنمای میدانی عملی برای شبکه های کارشناسی ارشد', 18, 9, 'book', 't', '<p><em>قهوه</em> <em>ناهار</em> <em>قهوه</em> (2012) یک راهنمای عملی برای شبکه است. نویسنده آلانا مولر با استفاده از تجربه شخصی و حرفه‌ای خود، همراه با نکات و تمرین‌ها، چگونگی توسعه مهارت‌های شبکه‌ای و ایجاد روابط پایدار را نشان می‌دهد که می‌تواند به ما در زندگی شخصی و حرفه‌ای کمک کند. برای هرکسی که می‌خواهد از نظر حرفه‌ای موفق شود، ضروری است.</p>', '2014-08-05 00:00:00', 4, 74, 'https://images.blinkist.io/images/books/53e1f9cf6339360007030000/1_1/470.jpg', '/en/books/coffee-lunch-coffee-en/purchase', 'قهوه-ناهار-قهوه', '2023-01-26 20:08:53.405091', '2023-01-26 20:08:53.405091', NULL, 'Coffee Lunch Coffee');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (725, '10 روز برای خواندن سریعتر', 'از طریق کتاب ها، مجلات و روزنامه ها زیپ کنید - هر چیزی را که می خوانید درک کنید و به خاطر بسپارید', 'از طریق کتاب ها، مجلات و روزنامه ها زیپ کنید - هر چیزی را که می خوانید درک کنید و به خاطر بسپارید', 14, 6, 'book', 't', '<p><em>10 Days to Faster Reading </em>(2001) قصد دارد به شما کمک کند تا از انبوه کتاب‌هایی که باید حتماً بخوانید، در حال رشد باشید. با شکستن ذهنیت ها و عادات بدی که مانع از خواندن موثر می شوند و جایگزینی آنها با تکنیک های خواندن بسیار کارآمد، سریعتر مطالعه خواهید کرد و بیش از هر زمان دیگری حفظ خواهید کرد.</p>', '2015-07-31 00:00:00', 4, 411, 'https://images.blinkist.io/images/books/55b7eee83235390007e80000/1_1/470.jpg', '/en/books/10-days-to-faster-reading-en/purchase', '10-روز-برای-خواندن-سریعتر', '2023-01-26 20:09:00.336374', '2023-01-26 20:09:00.336374', NULL, '10 Days to Faster Reading');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (726, 'فروش چلنجر', 'کنترل مکالمه با مشتری', 'کنترل مکالمه با مشتری', 18, 8, 'book', 't', '<p>استراتژی های فروش تغییر کرده است. به جای شیلینگ محصولات «یک اندازه»، نمایندگان فروش برتر امروزی با ارائه یک راه حل سفارشی برای یک مشکل منحصر به فرد برتری می یابند. برای انجام این کار، این نمایندگان فروش از مدل فروش "چلنگر" پیروی می کنند. در این کتاب خواهید آموخت که این مدل چیست و چگونه می تواند سازمان فروش شما را متحول کند.</p>', '2015-01-15 00:00:00', 5, 186, 'https://images.blinkist.io/images/books/54b5b2833262620009140000/1_1/470.jpg', '/en/books/the-challenger-sale-en/purchase', 'فروش-چلنجر', '2023-01-26 20:09:07.546597', '2023-01-26 20:09:07.546597', NULL, 'The Challenger Sale');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (727, '10% شادتر', 'چگونه صدای سرم را رام کردم، استرس را بدون از دست دادن قدرتم کاهش دادم و خودیاری پیدا کردم که واقعا کارساز است', 'چگونه صدای سرم را رام کردم، استرس را بدون از دست دادن قدرتم کاهش دادم و خودیاری پیدا کردم که واقعا کارساز است', 13, 7, 'book', 't', '<p><em>10% شادتر</em>با توضیح تحقیقات علمی اخیر و پیشرفته در مورد اینکه چگونه مدیتیشن بر بدن و ذهن شما تأثیر می گذارد، هنر باستانی مدیتیشن را ابهام می کند. مهمتر از همه، این به شما نشان می دهد که مراقبه چقدر می تواند برای مقابله با هرج و مرج و استرس زندگی مدرن ارزشمند باشد.</p>', '2014-11-11 00:00:00', 4, 285, 'https://images.blinkist.io/images/books/5460dd3331363000088e0000/1_1/470.jpg', '/en/books/10-percent-happier-en/purchase', '10%-شادتر', '2023-01-26 20:09:14.752977', '2023-01-26 20:09:14.752977', NULL, '10% Happier');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (728, 'هفت اصل برای عملی کردن ازدواج', 'راهنمای عملی از پیشروترین متخصص روابط کشور', 'راهنمای عملی از پیشروترین متخصص روابط کشور', 20, 9, 'book', 't', '<p><em>هفت اصل برای موفقیت در ازدواج</em> (1999) از داده های مطالعات روابط و مصاحبه ها استفاده می کند تا دقیقاً همان چیزی را که در عنوان خود وعده داده است انجام دهد. این پلک ها شما را از طریق تغییرات کلیدی که می توانید برای غلبه بر مشکلات رایجی که به روابط آسیب می زند و ایجاد یک ازدواج حمایتی و عاشقانه انجام دهید، غلبه کنید.</p>', '2015-05-06 00:00:00', 4, 215, 'https://images.blinkist.io/images/books/5547789d3666320007690000/1_1/470.jpg', '/en/books/the-seven-principles-for-making-marriage-work-en/purchase', 'هفت-اصل-برای-عملی-کردن-ازدواج', '2023-01-26 20:09:22.434607', '2023-01-26 20:09:22.434607', NULL, 'The Seven Principles for Making Marriage Work');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (729, 'درس هایی از تایتان ها', 'آنچه شرکت‌ها در اقتصاد جدید می‌توانند از غول‌های بزرگ صنعتی بیاموزند تا به موفقیت پایدار برسند', 'آنچه شرکت‌ها در اقتصاد جدید می‌توانند از غول‌های بزرگ صنعتی بیاموزند تا به موفقیت پایدار برسند', 27, 7, 'book', 't', '<p><em>درس هایی از تایتان ها </em>(2020) داستان ده شرکت صنعتی در ایالات متحده را روایت می کند. از جنرال الکتریک گرفته تا بوئینگ، هانیول تا یونایتد رنتالز، به این نگاه می‌شود که کدام تصمیمات استراتژیک منجر به موفقیت شد و کدام اشتباه فاجعه‌بار موانع جدیدی ایجاد کرد. با تجزیه و تحلیل عملکرد گذشته چنین مشاغل افسانه‌ای، بینش بیشتری در مورد اینکه کدام شرکت‌های امروزی می‌مانند – و کدام‌ها نه. </p>', '2021-09-08 00:00:00', 4, 40, 'https://images.blinkist.io/images/books/613218936cee070007631d6c/1_1/470.jpg', '/en/books/lessons-from-the-titans-en/purchase', 'درس-هایی-از-تایتان-ها', '2023-01-26 20:09:29.425837', '2023-01-26 20:09:29.425837', NULL, 'Lessons from the Titans');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (730, 'با سر خود استخدام کنید', 'استفاده از استخدام مبتنی بر عملکرد℠ برای ایجاد تیم های عالی', 'استفاده از استخدام مبتنی بر عملکرد℠ برای ایجاد تیم های عالی', 15, 7, 'book', 't', '<p><em>Hire With Your Head</em> (2007) قبل از تهیه پیش نویس یک پیشنهاد شغلی استاندارد که فقط افراد استاندارد را جذب می کند، دو بار فکر می کنید. بیاموزید که چه زمانی فروشنده و چه زمانی خریدار در بازار منابع انسانی باشید تا انتخاب کارمندان بالقوه را تضمین کنید. با بازنویسی فرآیند استخدام از آگهی تا مصاحبه، <em>Hire With Your Head</em> رویه استخدام شما را متحول خواهد کرد.</p>', '2015-08-19 00:00:00', 4, 31, 'https://images.blinkist.io/images/books/55d0f828688f670009000040/1_1/470.jpg', '/en/books/hire-with-your-head-en/purchase', 'با-سر-خود-استخدام-کنید', '2023-01-26 20:09:36.488095', '2023-01-26 20:09:36.488095', NULL, 'Hire With Your Head');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (731, 'چشمک زدن', 'مدیریت شرکت خود را رایگان و 100% نتیجه گرا کنید', 'مدیریت شرکت خود را رایگان و 100% نتیجه گرا کنید', 15, 6, 'book', 't', '<p><em>Blinkracy</em> (2015) همه چیز در مورد یک رویکرد سازمانی نوآورانه است که مبتنی بر توانمندسازی کارکنان و رفع نیاز به مدیران است. با دیدگاه‌های استارت‌آپ Blinkist مستقر در برلین، که محل کار خود را با استفاده از این مدل بازسازی کرد، این چشمک‌ها توضیح می‌دهند که چگونه می‌توانید آن را در شرکت خود اجرا کنید.</p>', '2015-05-07 00:00:00', 4, 10, 'https://images.blinkist.io/images/books/55477b5736663200078a0000/1_1/470.jpg', '/en/books/blinkracy-en/purchase', 'چشمک-زدن', '2023-01-26 20:09:43.278197', '2023-01-26 20:09:43.278197', NULL, 'Blinkracy');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (732, 'نابغه پرندگان', 'درخشش پرندگان را ببینید!', 'درخشش پرندگان را ببینید!', 20, 8, 'book', 't', '<p><em>نابغه پرندگان</em> (2016) همه چیز در مورد عقل باورنکردنی این موجودات بالدار است. این پلک‌ها روش‌های متعددی را که پرندگان هوش خود را نشان می‌دهند، از ساخت ابزار و ناوبری گرفته تا حافظه و آهنگ توضیح می‌دهند.</p>', '2016-08-30 00:00:00', 5, 19, 'https://images.blinkist.io/images/books/57c15f9c4a1a18000344dcd1/1_1/470.jpg', '/en/books/the-genius-of-birds-en/purchase', 'نابغه-پرندگان', '2023-01-26 20:09:50.657269', '2023-01-26 20:09:50.657269', NULL, 'The Genius of Birds');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (733, 'هنر پرسیدن', 'یا چگونه یاد گرفتم که دیگر نگران نباشم و اجازه دهم مردم کمک کنند', 'یا چگونه یاد گرفتم که دیگر نگران نباشم و اجازه دهم مردم کمک کنند', 18, 8, 'book', 't', '<p><em>هنر پرسیدن</em> (2014) شرح شخصی آماندا پالمر است که چگونه فلسفه خود را برای پرسیدن، اشتراک گذاری و ارتباط ایجاد کرد. از طریق این پلک‌ها، درک عمیقی از نحوه پذیرش کمک، جبران سخاوت دیگران و ایجاد پایگاهی فشرده و خانواده‌مانند برای حمایت از شما در هر کاری که انجام می‌دهید، به دست خواهید آورد.</p>', '2015-07-01 00:00:00', 4, 57, 'https://images.blinkist.io/images/books/559256cb65613800071b0000/1_1/470.jpg', '/en/books/the-art-of-asking-en/purchase', 'هنر-پرسیدن', '2023-01-26 20:09:57.907674', '2023-01-26 20:09:57.907674', NULL, 'The Art of Asking');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (734, 'متا انسان ها', 'آزاد کردن پتانسیل بی نهایت شما', 'آزاد کردن پتانسیل بی نهایت شما', 24, 8, 'book', 't', '<p>در <em>Metahuman </em> (2019)، نویسنده پرفروش و مبتکر عصر جدید، دیپاک چوپرا، از شما می‌خواهد که محدودیت‌های وجود روزانه‌تان را بشناسید، سپس از آن‌ها فراتر بروید تا به سطح آگاهی بالاتری برسید. چوپرا معتقد است که با دسترسی به این آگاهی بالاتر، همه ما این قدرت را داریم که از پتانسیل نامحدود بهره ببریم. با رها کردن پتانسیل کامل خود، می‌توانیم فراانسان شویم.</p>', '2019-11-29 00:00:00', 4, 183, 'https://images.blinkist.io/images/books/5ddd4fd76cee0700085f3200/1_1/470.jpg', '/en/books/metahuman-en/purchase', 'متا-انسان-ها', '2023-01-26 20:10:04.683962', '2023-01-26 20:10:04.683962', NULL, 'Metahuman');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (735, 'معلم میلیونر', '9 قانون ثروت که باید در مدرسه یاد بگیرید', '9 قانون ثروت که باید در مدرسه یاد بگیرید', 16, 6, 'book', 't', '<p><em>معلم میلیونر</em>(2011) توضیح می دهد که چگونه افراد با درآمد متوسط ​​می توانند از طریق مدیریت هوشمندانه پول ثروتمند شوند. از اهمیت صرفه جویی گرفته تا ارزش اوراق قرضه دولتی، این یک راهنمای ساده برای افزایش ثروت با ابزارهای متوسط ​​است.</p>', '2020-11-26 00:00:00', 4, 167, 'https://images.blinkist.io/images/books/5fb78a626cee070006e48e54/1_1/470.jpg', '/en/books/millionaire-teacher-en/purchase', 'معلم-میلیونر', '2023-01-26 20:10:11.670433', '2023-01-26 20:10:11.670433', NULL, 'Millionaire Teacher');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (736, 'پیروزی شهر', 'چگونه بزرگترین اختراع ما ما را ثروتمندتر، باهوش تر، سبزتر، سالم تر و شادتر می کند', 'چگونه بزرگترین اختراع ما ما را ثروتمندتر، باهوش تر، سبزتر، سالم تر و شادتر می کند', 15, 8, 'book', 'f', '<p><em>Triumph of the City</em> فضیلت های شهر را به عنوان یکی از بزرگترین اختراعات تمدن می ستاید. شهرها نه تنها مردم را به هم متصل می کنند، بلکه به آنها کمک می کنند تا کارهای بزرگی را انجام دهند. و اگرچه بسیاری از کلان شهرهای شهری امروزی با چالش های واقعی در نظم اقتصادی جدید روبرو هستند، راه های زیادی برای موفقیت شهرها وجود دارد.</p>', '2014-11-27 00:00:00', 4, 15, 'https://images.blinkist.io/images/books/54746ea36161360009330000/1_1/470.jpg', '/en/books/triumph-of-the-city-en/purchase', 'پیروزی-شهر', '2023-01-26 20:10:18.857987', '2023-01-26 20:10:18.857987', NULL, 'Triumph of the City');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (737, 'اسکرام', 'هنر انجام دو بار کار در نیمه زمان', 'هنر انجام دو بار کار در نیمه زمان', 17, 7, 'book', 't', '<p>درباره اسکرام، سیستم مدیریت پروژه که صنعت فناوری را متحول کرده است، همه چیز را بیاموزید. این یک سیستم منحصر به فرد سازگار و منعطف است که به تیم ها اجازه می دهد تا به طور واقع بینانه برنامه ریزی کنند و اهداف خود را از طریق بازخورد مداوم تنظیم کنند. با استفاده از Scrum، تیم شما می‌تواند بهره‌وری (و نتیجه نهایی) خود را بدون ایجاد استرس بی‌ضرور یا ساعات طولانی‌تر کار کردن، بهبود بخشد.</p>', '2015-01-02 00:00:00', 5, 247, 'https://images.blinkist.io/images/books/5492883f62633000095d0000/1_1/470.jpg', '/en/books/scrum-en/purchase', 'اسکرام', '2023-01-26 20:10:26.18963', '2023-01-26 20:10:26.18963', NULL, 'Scrum');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (739, 'بخورش!', 'پایدارترین رژیم غذایی و تمرینی که تا به حال ساخته شده است: چربی بسوزانید، قوی شوید و از غذاهای مورد علاقه خود بدون گناه لذت ببرید', 'پایدارترین رژیم غذایی و تمرینی که تا به حال ساخته شده است: چربی بسوزانید، قوی شوید و از غذاهای مورد علاقه خود بدون گناه لذت ببرید', 18, 4, 'book', 't', '<p><em>بخور! </em>(2022) یک برنامه کاهش وزن معقول، مبتنی بر واقعیت و اطمینان بخش را برای ما که از دنبال کردن آخرین روندهای رژیم خسته شده ایم، ارائه می دهد. توصیه های درست و رویکردی بدون احساس گناه برای کاهش وزن و خوردن معقول پیدا خواهید کرد.</p>', '2022-10-03 00:00:00', 5, 397, 'https://images.blinkist.io/images/books/63358cbe6cee070008031e48/1_1/470.jpg', '/en/books/eat-it-en/purchase', 'بخورش!', '2023-01-26 20:10:39.826848', '2023-01-26 20:10:39.826848', NULL, 'Eat It!');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (740, 'رژیم سریع', 'با راز ساده روزه داری متناوب وزن کم کنید، سالم بمانید و بیشتر عمر کنید', 'با راز ساده روزه داری متناوب وزن کم کنید، سالم بمانید و بیشتر عمر کنید', 14, 6, 'book', 't', '<p><em>رژیم غذایی سریع </em>(2013) راهنمای روزه داری متناوب و فواید آن برای سلامتی است. نسخه 2015 شامل یک نظریه بازنگری شده و گسترده در پشت روزه متناوب، همراه با توصیه هایی برای ورزش بدنی است.</p>', '2015-10-23 00:00:00', 4, 169, 'https://images.blinkist.io/images/books/56249ccd6361310007350000/1_1/470.jpg', '/en/books/the-fast-diet-en/purchase', 'رژیم-سریع', '2023-01-26 20:10:47.366611', '2023-01-26 20:10:47.366611', NULL, 'The Fast Diet');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (741, 'کتاب مرزها', 'محدودیت هایی را تعیین کنید که شما را آزاد می کند', 'محدودیت هایی را تعیین کنید که شما را آزاد می کند', 17, 6, 'book', 't', '<p><em>کتاب مرزها </em>(2022) یک راهنمای عملگرا و توانمند برای تعیین محدودیت های روابط سالم است. بیش از 130 اسکریپت ارائه می دهد تا اطمینان حاصل کند که همیشه کلمات مناسب برای تعیین مرزها و ایجاد روابط سالم تر و شادتر دارید.</p>', '2022-12-22 00:00:00', 4, 300, 'https://images.blinkist.io/images/books/63a17d4673bf6d0009f1ec14/1_1/470.jpg', '/en/books/the-book-of-boundaries-en/purchase', 'کتاب-مرزها', '2023-01-26 20:10:53.898786', '2023-01-26 20:10:53.898786', NULL, 'The Book of Boundaries');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (742, 'انقلاب خواب', 'یک شب در یک زمان زندگی خود را متحول کنید', 'یک شب در یک زمان زندگی خود را متحول کنید', 16, 8, 'book', 't', '<p>این پلک‌ها در مورد اهمیت یک نیاز اولیه انسانی است که ما اغلب آن را کنار می‌گذاریم: خواب. خواب کافی فقط به معنای داشتن احساس بهتر در صبح نیست، بلکه عملکرد کاری، سلامتی و حتی روابط شخصی شما را بهبود می بخشد. به طور مشابه، محرومیت از خواب محصول جانبی کار سخت نیست. بلکه <em>از</em> رسیدن شما به پتانسیل کامل خود جلوگیری می کند. <em>انقلاب خواب </em>(2016) توضیح می‌دهد که چرا خواب بسیار حیاتی است و برای به دست آوردن بیشتر آن چه کاری می‌توانید انجام دهید.</p>', '2016-07-04 00:00:00', 4, 181, 'https://images.blinkist.io/images/books/5776159b86883200034f4744/1_1/470.jpg', '/en/books/the-sleep-revolution-en/purchase', 'انقلاب-خواب', '2023-01-26 20:11:00.851015', '2023-01-26 20:11:00.851015', NULL, 'The Sleep Revolution');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (743, 'هک روح', 'کلیدهای شامانی برای بازیابی قدرت شخصی، تغییر خود و روشن کردن جهان', 'کلیدهای شامانی برای بازیابی قدرت شخصی، تغییر خود و روشن کردن جهان', 21, 7, 'book', 't', '<p><em>هک روح</em> (2019) یک راهنمای مبتدی برای شمنیسم ارائه می دهد. این پلک ها اعتقادات اصلی این تمرین معنوی را نشان می دهد و تکنیک های ساده ای را برای ادغام شمنیسم در زندگی شما شرح می دهد.</p>', '2020-09-17 00:00:00', 4, 111, 'https://images.blinkist.io/images/books/5f5be1e76cee070006c62e0b/1_1/470.jpg', '/en/books/spirit-hacking-en/purchase', 'هک-روح', '2023-01-26 20:11:08.664878', '2023-01-26 20:11:08.664878', NULL, 'Spirit Hacking');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (744, 'پیدا کردن چیکا', 'یک دختر کوچک، یک زلزله، و تشکیل خانواده', 'یک دختر کوچک، یک زلزله، و تشکیل خانواده', 22, 8, 'book', 't', '<p><em>Finding Chika </em> (2019) داستان واقعی دختر بچه ای از هائیتی است که از فاجعه زلزله و مرگ مادرش جان سالم به در می برد. با شجاعت، فضل و کنجکاوی عاشقانه، او سپس با یک تومور مغزی مبارزه می‌کند، در حالی که تحت سرپرستی نویسنده میچ آلبوم، که در مدت کوتاهی که با هم دارند، درس‌های قدرتمندی در مورد زندگی، عشق و خانواده می‌آموزد. </p>', '2019-12-20 00:00:00', 5, 23, 'https://images.blinkist.io/images/books/5df8ea136cee07000a94e936/1_1/470.jpg', '/en/books/finding-chika-en/purchase', 'پیدا-کردن-چیکا', '2023-01-26 20:11:16.229679', '2023-01-26 20:11:16.229679', NULL, 'Finding Chika');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (745, 'هم تیمی از راه دور', 'در هنگام کار در هر مکانی درگیر و متصل بمانید', 'در هنگام کار در هر مکانی درگیر و متصل بمانید', 18, 7, 'book', 't', '<p><em>هم تیمی از راه دور: در هنگام کار در هر مکانی درگیر و متصل بمانید </em>(2021) راهنمایی برای داشتن یک هم تیمی با کیفیت در حین کار از راه دور است. این به شما کمک می کند تا تمام مسائل بین فردی را که زمانی که دیگر در دفتری با همکاران خود به اشتراک نمی گذارید ظاهر می شوند، پیمایش کنید و در مورد نحوه ایجاد ارتباط با افرادی که ندیده اید راهنمایی می کند.</p>', '2021-06-22 00:00:00', 4, 88, 'https://images.blinkist.io/images/books/60d0ab8f6cee070007502a8f/1_1/470.jpg', '/en/books/the-long-distance-teammate-en/purchase', 'هم-تیمی-از-راه-دور', '2023-01-26 20:11:23.387692', '2023-01-26 20:11:23.387692', NULL, 'The Long-Distance Teammate');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (746, 'معجزه ذهن آگاهی', 'مقدمه ای بر تمرین مراقبه', 'مقدمه ای بر تمرین مراقبه', 20, 6, 'book', 't', '<p><em>معجزه ذهن آگاهی </em>(1975) توضیح می دهد که چگونه تمرین هنر باستانی بودایی ذهن آگاهی می تواند به بهبود رفاه و زندگی ما کمک کند. با استفاده از مثال‌های معمولی از زندگی روزمره‌مان، این پلک‌ها نشان می‌دهند که چگونه همه ما می‌توانیم از زمان حال بیشتر بهره ببریم و دوباره از معجزه زندگی قدردانی کنیم.</p>', '2019-03-13 00:00:00', 5, 507, 'https://images.blinkist.io/images/books/5c84cc076cee07000738ba83/1_1/470.jpg', '/en/books/the-miracle-of-mindfulness-en/purchase', 'معجزه-ذهن-آگاهی', '2023-01-26 20:11:28.650504', '2023-01-26 20:11:28.650504', NULL, 'The Miracle of Mindfulness');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (747, 'سال های خوش شانس', 'چگونه در دنیای جدید و شجاع سلامتی پیشرفت کنیم', 'چگونه در دنیای جدید و شجاع سلامتی پیشرفت کنیم', 19, 8, 'book', 't', '<p><em>سالهای خوش شانس </em>(2016) راهنمای شما برای درک پیشرفت های پیشرفته در علم پزشکی است که به مهم ترین مشکلات سلامت جامعه می پردازد. در حالی که به نظر می رسد پیشرفت در ژنتیک کلید درمان سرطان، ناباروری و پیری است، این پلک زدن ها نشان می دهد که راهبردهای سلامت ساده و معقول ممکن است به طور موثرتری سلامت و شادی جمعیت جهان را بهبود بخشد.</p>', '2017-03-23 00:00:00', 4, 15, 'https://images.blinkist.io/images/books/58d12492ed3a570004158157/1_1/470.jpg', '/en/books/the-lucky-years-en/purchase', 'سال-های-خوش-شانس', '2023-01-26 20:11:35.451771', '2023-01-26 20:11:35.451771', NULL, 'The Lucky Years');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (748, 'مطالعه چین', 'جامع ترین مطالعه در مورد تغذیه که تاکنون انجام شده و پیامدهای خیره کننده آن برای رژیم غذایی، کاهش وزن و سلامت طولانی مدت', 'جامع ترین مطالعه در مورد تغذیه که تاکنون انجام شده و پیامدهای خیره کننده آن برای رژیم غذایی، کاهش وزن و سلامت طولانی مدت', 13, 5, 'book', 't', '<p><em>مطالعه چین</em> (2005) کتابی بحث‌برانگیز است که ارتباط بین رژیم غذایی و بیماری را بررسی می‌کند و به شما نشان می‌دهد که چگونه یک رژیم غذایی سرشار از پروتئین‌های حیوانی می‌تواند منجر به انبوهی از مشکلات سلامتی شود. بر اساس داده های علمی، این پلک ها توضیح می دهند که چرا اگر می خواهید سالم بمانید، باید گیاهخوار شوید.</p>', '2016-05-09 00:00:00', 4, 118, 'https://images.blinkist.io/images/books/572b87f12c9d0b000358d97c/1_1/470.jpg', '/en/books/the-china-study-en/purchase', 'مطالعه-چین', '2023-01-26 20:11:42.318409', '2023-01-26 20:11:42.318409', NULL, 'The China Study');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (749, 'هر شغلی یک شغل فروش است', 'چگونه از هنر فروش برای برنده شدن در محل کار استفاده کنیم', 'چگونه از هنر فروش برای برنده شدن در محل کار استفاده کنیم', 18, 6, 'book', 't', '<p><em>Every Job Is a Sales Job (2019)</em> توضیح می دهد که چرا هنر فروش بدون در نظر گرفتن حرفه شما جزء لاینفک حرفه شما است. این پلک‌ها مزایای ادغام تکنیک‌های فروش در تعاملات روزانه شما را بررسی می‌کنند و نحوه کشف فرصت‌های پنهان برای فروش را توضیح می‌دهند.</p>', '2020-10-01 00:00:00', 4, 151, 'https://images.blinkist.io/images/books/5f6dbb8e6cee070007232392/1_1/470.jpg', '/en/books/every-job-is-a-sales-job-en/purchase', 'هر-شغلی-یک-شغل-فروش-است', '2023-01-26 20:11:49.663713', '2023-01-26 20:11:49.663713', NULL, 'Every Job Is a Sales Job');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (750, 'وقتی بمیری چه کسی گریه خواهد کرد؟', 'درس های زندگی از راهبی که فراری خود را فروخت', 'درس های زندگی از راهبی که فراری خود را فروخت', 23, 8, 'book', 't', '<p><em>Who Will Cry When You Die</em>(1999) حاوی حکمت زندگی است که به شما کمک می کند زندگی کامل و سخاوتمندانه ای داشته باشید. توصیه ها و استراتژی هایی را برای اینکه بهترین نسخه از خودتان باشید ارائه می دهد. این بدان معناست که وقتی بمیرید، عزیزانتان گریه خواهند کرد نه فقط به این دلیل که دلشان برای شما تنگ شده است، بلکه به این دلیل که برای همه چیزهایی که در طول زندگی خود انجام داده اید سپاسگزار هستند. </p>', '2019-06-28 00:00:00', 4, 361, 'https://images.blinkist.io/images/books/5d1329986cee07000880dc26/1_1/470.jpg', '/en/books/who-will-cry-when-you-die-en/purchase', 'وقتی-بمیری-چه-کسی-گریه-خواهد-کرد؟', '2023-01-26 20:11:54.644806', '2023-01-26 20:11:54.644806', NULL, 'Who Will Cry When You Die?');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (751, 'کاوش در دنیای رویای شفاف', 'راهنمای گام به گام رویای شفاف', 'راهنمای گام به گام رویای شفاف', 16, 8, 'book', 't', '<p><em>کاوش در دنیای رویاهای شفاف</em> (1990) راهنمای گام به گام دنیای شگفت انگیز رویاهای شفاف را ارائه می دهد. این روش تکنیک های مختلفی را در مورد چگونگی برانگیختن شفافیت و چگونگی استفاده از رویاهای شفاف برای غنی سازی زندگی بیداری شما معرفی می کند.</p>', '2015-06-23 00:00:00', 4, 60, 'https://images.blinkist.io/images/books/5589206c3466610007200000/1_1/470.jpg', '/en/books/exploring-the-world-of-lucid-dreaming-en/purchase', 'کاوش-در-دنیای-رویای-شفاف', '2023-01-26 20:12:01.687822', '2023-01-26 20:12:01.687822', NULL, 'Exploring the World of Lucid Dreaming');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (752, 'دو ساعت عالی', 'استراتژی‌های مبتنی بر علم برای استفاده از بهترین زمان و انجام مهم‌ترین کارهایتان', 'استراتژی‌های مبتنی بر علم برای استفاده از بهترین زمان و انجام مهم‌ترین کارهایتان', 11, 5, 'book', 't', '<p>بین دفاتر با پلان باز، مشاغل دورکاری و مشاغل آزاد در کافی شاپ ها، محل کار مدرن میدان مین حواس پرتی است. زمان آن است که با یک استراتژی لایف هک مغز خود را بازیابی کنید! <em>Two Awesome Hours</em> (2015) گام‌های غیرمنتظره و روشن‌فکرانه‌ای را برای شما مولدتر نشان می‌دهد، از مدیریت انرژی ذهنی‌تان تا اجازه دادن به ذهن‌تان سرگردان. 120 دقیقه تمام چیزی است که برای ایجاد تفاوت نیاز دارید. </p>', '2015-07-29 00:00:00', 4, 103, 'https://images.blinkist.io/images/books/55b7e1993235390007460000/1_1/470.jpg', '/en/books/two-awesome-hours-en/purchase', 'دو-ساعت-عالی', '2023-01-26 20:12:08.522556', '2023-01-26 20:12:08.522556', NULL, 'Two Awesome Hours');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (753, 'حکمت مالی', 'چگونه علوم انسانی می تواند امور مالی را روشن و بهبود بخشد', 'چگونه علوم انسانی می تواند امور مالی را روشن و بهبود بخشد', 24, 8, 'book', 't', '<p><em>حکمت مالی </em>(2017) نشان می‌دهد که دنیای مالی علیرغم شهرتش به بخل و بی مسئولیتی، چیزهای زیادی برای آموزش به ما دارد. و به همین ترتیب، امور مالی می‌تواند از تلاش‌های گسترده‌تر انسانی ما، مانند ادبیات، هنر و فلسفه بیاموزد.</p>', '2020-05-29 00:00:00', 4, 74, 'https://images.blinkist.io/images/books/5ecd654a6cee0700078a3fb0/1_1/470.jpg', '/en/books/the-wisdom-of-finance-en/purchase', 'حکمت-مالی', '2023-01-26 20:12:15.502969', '2023-01-26 20:12:15.502969', NULL, 'The Wisdom of Finance');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (754, 'فروش نامرئی', 'راهنمای میدانی برای بازاریابی مدرن', 'راهنمای میدانی برای بازاریابی مدرن', 22, 13, 'book', 't', '<p>خدمات بخش مهم و رو به رشدی از اقتصاد مدرن را نشان می دهند، اما بازاریابی آنها همچنان یک راز باقی مانده است. <em>فروش نامرئی</em> (1997) به عنوان راهنمای تبلیغ ناملموس عمل می کند. نحوه راه‌اندازی یک شرکت خدماتی قابل فروش و نحوه تبلیغ و ترویج آن کسب‌وکار را تشریح می‌کند.</p>', '2014-01-22 14:30:00', 4, 39, 'https://images.blinkist.io/images/books/50b3a29fe4b00d0268f2589f/1_1/470.jpg', '/en/books/selling-the-invisible-en/purchase', 'فروش-نامرئی', '2023-01-26 20:12:22.694794', '2023-01-26 20:12:22.694794', NULL, 'Selling the Invisible');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (755, 'مناسب برای رشد', 'راهنمای کاهش هزینه استراتژیک، تجدید ساختار و تجدید', 'راهنمای کاهش هزینه استراتژیک، تجدید ساختار و تجدید', 15, 6, 'book', 't', '<p><em>Fit for Growth</em> (2017) توضیح می دهد که چرا کاهش هزینه برای رشد یک شرکت بسیار مهم است. نویسندگان مجموعه‌ای از روش‌ها را پوشش می‌دهند، از تغییر ساختار مدل سازمانی شما تا کاهش بخش‌های تجاری اضافی و دستیابی به رشد پایدار برای شرکت شما.</p>', '2018-10-11 00:00:00', 4, 14, 'https://images.blinkist.io/images/books/5bbcde6e6cee0700070d6bf5/1_1/470.jpg', '/en/books/fit-for-growth-en/purchase', 'مناسب-برای-رشد', '2023-01-26 20:12:29.821449', '2023-01-26 20:12:29.821449', NULL, 'Fit for Growth');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (756, 'چرا من هندو هستم', 'راهنمای خودی برای تاریخ هندوئیسم', 'راهنمای خودی برای تاریخ هندوئیسم', 19, 6, 'book', 't', '<p><em>چرا من یک هندو هستم </em>(2018) تأملی در مورد مذهب و هویت ملی از دیدگاه یکی از سیاستمداران برجسته هند، شاشی ثارور است. این کتاب که با نگاهی به ظهور بنیادگرایی هندو نوشته شده است، تاریخچه 4000 ساله ایمان او را باز می کند و استدلال می کند که جنبش هندوتوای امروزی سنت باستانی تساهل و تنوع را منحرف می کند. ثارور نتیجه می گیرد که اگر هندی ها بخواهند کشورشان شکوفا شود، باید شوونیسم حزب حاکم را رد کنند و این میراث فرهنگی بزرگ را بپذیرند.</p>', '2019-05-31 00:00:00', 4, 131, 'https://images.blinkist.io/images/books/5cee52166cee0700070a588b/1_1/470.jpg', '/en/books/why-i-am-a-hindu-en/purchase', 'چرا-من-هندو-هستم', '2023-01-26 20:12:36.72811', '2023-01-26 20:12:36.72811', NULL, 'Why I Am a Hindu');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (757, 'هنر بلاغت', 'متقاعدسازی و اصول پشت مهارت سخنوری را کشف کنید', 'متقاعدسازی و اصول پشت مهارت سخنوری را کشف کنید', 20, 6, 'book', 't', '<p><em>هنر بلاغت </em> (قرن چهارم قبل از میلاد) یک کتابچه راهنمای عملی در مورد هنر سخنرانی عمومی و متقاعدسازی است. <em>هنر بلاغت</em> که تقریباً 2500 سال پیش نوشته شده است، یکی از دقیق ترین و جامع ترین مطالعاتی است که تاکنون در مورد بلاغت نوشته شده است.</p>', '2021-09-26 00:00:00', 5, 359, 'https://images.blinkist.io/images/books/614dca616cee0700077a7bfa/1_1/470.jpg', '/en/books/the-art-of-rhetoric-en/purchase', 'هنر-بلاغت', '2023-01-26 20:12:43.61312', '2023-01-26 20:12:43.61312', NULL, 'The Art of Rhetoric');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (758, 'رابطه جنسی بهتر از طریق ذهن آگاهی', 'چگونه زنان می توانند میل را پرورش دهند', 'چگونه زنان می توانند میل را پرورش دهند', 22, 8, 'book', 't', '<p>با تمرکز بر زنان، <em>رابطه جنسی بهتر از طریق ذهن آگاهی</em> (2018) به بررسی این موضوع می پردازد که چرا استرس و عدم توجه علت اصلی بسیاری از مشکلات جنسی است، و نشان می دهد که چگونه ذهن آگاهی می تواند به همه زنان کمک کند تا رضایت بیشتری داشته باشند. هم در داخل و هم در خارج از اتاق خواب.</p>', '2018-05-24 00:00:00', 4, 169, 'https://images.blinkist.io/images/books/5b01c04db238e100075e00d9/1_1/470.jpg', '/en/books/better-sex-through-mindfulness-en/purchase', 'رابطه-جنسی-بهتر-از-طریق-ذهن-آگاهی', '2023-01-26 20:12:50.89465', '2023-01-26 20:12:50.89465', NULL, 'Better Sex Through Mindfulness');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (759, 'هنر تنها زیستن و دوست داشتن آن', 'جعبه ابزار الهام بخش شما برای یک زندگی کامل و شاد', 'جعبه ابزار الهام بخش شما برای یک زندگی کامل و شاد', 22, 8, 'book', 't', '<p><em>هنر تنها زیستن و دوست داشتن آن</em> (2018) راهنمایی است که توضیح می دهد چگونه از طریق مثبت اندیشی و طرز فکر فعالانه زندگی را به تنهایی در آغوش بگیرید. با مواجهه رودررو با موقعیت خود، می توانید زندگی تنها را به تجربه ای غنی و شاد تبدیل کنید.</p>', '2020-05-09 00:00:00', 4, 138, 'https://images.blinkist.io/images/books/5eb09fc56cee070006f07eb2/1_1/470.jpg', '/en/books/the-art-of-living-alone-and-loving-it-en/purchase', 'هنر-تنها-زیستن-و-دوست-داشتن-آن', '2023-01-26 20:12:57.805124', '2023-01-26 20:12:57.805124', NULL, 'The Art of Living Alone and Loving It');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (760, 'سهام عادی و سود غیرمعمول و سایر نوشته ها', 'استراتژی سرمایه گذاری خود را بهبود بخشید', 'استراتژی سرمایه گذاری خود را بهبود بخشید', 18, 8, 'book', 't', '<p><em> سهام معمولی و سود غیرمعمول </em>همه اطلاعاتی را که برای سرمایه گذاری هوشمند نیاز دارید، صرف نظر از سبک سرمایه گذاری شما در اختیار شما قرار می دهد. چه به دنبال سودهای کلان باشید و چه صرفاً برای حفظ وجوه موجود، این کتاب مسیر موفقیت را به شما نشان می دهد.</p>', '2015-03-09 00:00:00', 4, 130, 'https://images.blinkist.io/images/books/54fd8f85303766000a050000/1_1/470.jpg', '/en/books/common-stocks-and-uncommon-profits-and-other-writings-en/purchase', 'سهام-عادی-و-سود-غیرمعمول-و-سایر-نوشته-ها', '2023-01-26 20:13:04.668103', '2023-01-26 20:13:04.668103', NULL, 'Common Stocks and Uncommon Profits and Other Writings');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (761, 'خرد کردنش!', 'کارآفرینان بزرگ چگونه کسب و کار خود را ایجاد می کنند و تأثیر می گذارند - و شما چگونه می توانید.', 'کارآفرینان بزرگ چگونه کسب و کار خود را ایجاد می کنند و تأثیر می گذارند - و شما چگونه می توانید.', 25, 10, 'book', 't', '<p><em>Crushing It!</em> (2018) توضیح می‌دهد و بررسی می‌کند که چرا داشتن یک برند شخصی قوی در تجارت بسیار مهم است. نویسنده با دنبال کردن پرفروش‌ترین کتاب سال 2009 خود، <em>Crush It!</em>، از تجربیات خود و خوانندگان استفاده می‌کند تا نشان دهد که چرا حضور قوی در چندین کانال رسانه‌های دیجیتال، طرحی برای موفقیت است. </p>', '2018-03-27 00:00:00', 4, 166, 'https://images.blinkist.io/images/books/5ab6ee2cb238e10005bf58f7/1_1/470.jpg', '/en/books/crushing-it-en/purchase', 'خرد-کردنش!', '2023-01-26 20:13:09.900374', '2023-01-26 20:13:09.900374', NULL, 'Crushing it!');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (762, 'فرار از Cubicle Nation', 'از زندانی شرکتی تا کارآفرین پررونق', 'از زندانی شرکتی تا کارآفرین پررونق', 12, 6, 'book', 'f', '<p><em>Escape From Cubicle Nation </em>(2009) یک راهنمای عملی و الهام بخش برای انتقال از یک شغل اداری سنتی به خوداشتغالی است. این پلک‌ها هم جنبه‌های احساسی و هم جنبه‌های فنی کارآفرین شدن را بررسی می‌کنند و توضیح می‌دهند که برای پشت سر گذاشتن دنیای شرکت‌ها چه چیزی لازم است.</p>', '2016-01-18 00:00:00', NULL, 8, 'https://images.blinkist.io/images/books/569c9988e37b120007000006/1_1/470.jpg', '/en/books/escape-from-cubicle-nation-en/purchase', 'فرار-از-Cubicle-Nation', '2023-01-26 20:13:17.258483', '2023-01-26 20:13:17.258483', NULL, 'Escape from Cubicle Nation');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (763, 'سی میلیون کلمه', 'ساختن مغز کودک', 'ساختن مغز کودک', 19, 8, 'book', 't', '<p><em>سی میلیون کلمه</em> (2015) اهمیت زبان را در رشد اولیه و موفقیت بلند مدت کودک توضیح می دهد. این پلک‌ها محیط بهینه زبان اولیه برای کودک را مشخص می‌کند و راه‌هایی را که والدین می‌توانند به فرزندانشان در این سال‌های حساس کمک کنند، برجسته می‌کند.</p>', '2016-10-28 00:00:00', 5, 20, 'https://images.blinkist.io/images/books/580bb1dbd4d2ce0003dd24e2/1_1/470.jpg', '/en/books/thirty-million-words-en/purchase', 'سی-میلیون-کلمه', '2023-01-26 20:13:24.036355', '2023-01-26 20:13:24.036355', NULL, 'Thirty Million Words');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (764, 'مسیر مشترک برای موفقیت غیر معمول', 'نقشه راه آزادی مالی و تحقق', 'نقشه راه آزادی مالی و تحقق', 25, 8, 'book', 't', '<p><em>مسیر مشترک برای موفقیت غیرمعمول </em>(2021) شما را با ابزارهایی برای ایجاد محتوای ارزشمند و تبدیل آن به استقلال مالی مسلح می کند. با استفاده از بیش از 3000 مصاحبه با کارآفرینان موفق، راه را برای تبدیل ایده بزرگ شما به یک تجارت سودآور باز می کند.</p>', '2021-08-16 00:00:00', 4, 154, 'https://images.blinkist.io/images/books/61162f886cee070007535b4d/1_1/470.jpg', '/en/books/the-common-path-to-uncommon-success-en/purchase', 'مسیر-مشترک-برای-موفقیت-غیر-معمول', '2023-01-26 20:13:30.838105', '2023-01-26 20:13:30.838105', NULL, 'The Common Path to Uncommon Success');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (765, 'کمتر انجام دادن، بیشتر زندگی کردن', 'همه چیز را در زندگی آسان تر کنید', 'همه چیز را در زندگی آسان تر کنید', 21, 9, 'book', 't', '<p><em>کار کمتر، زندگی بیشتر</em> (2014) شما را در 9 مرحله اساسی در سفر خود به سمت مؤثرتر شدن راهنمایی می کند. در این پلک‌ها، نویسنده ابزارها و تکنیک‌های مورد علاقه‌اش را برای بهینه‌سازی، خودکارسازی و برون‌سپاری همه چیز در فهرست کارهای مزاحم به اشتراک می‌گذارد، بنابراین به شما زمان می‌دهد تا کارهایی که در زندگی‌تان مهم هستند.</p>', '2014-04-23 09:22:36', 4, 895, 'https://images.blinkist.io/images/books/534f7d9b6531660007f50000/1_1/470.jpg', '/en/books/less-doing-more-living-en/purchase', 'کمتر-انجام-دادن،-بیشتر-زندگی-کردن', '2023-01-26 20:13:36.048687', '2023-01-26 20:13:36.048687', NULL, 'Less Doing, More Living');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (766, 'مثل اینکه منظورت این است گوش کن', 'بازیابی هنر گمشده ارتباط واقعی', 'بازیابی هنر گمشده ارتباط واقعی', 24, 8, 'book', 't', '<p><em>Listen Like You Mean It </em>(2021) یک راهنمای دوستانه و جامع برای تعمیق روابط از طریق قدرت گوش دادن است. خیلی اوقات، مکالمات ما با خانواده، دوستان و همکاران سطحی باقی می‌ماند - ما از کنار هم صحبت می‌کنیم، از نشان دادن آسیب‌پذیری خودداری می‌کنیم، یا گرفتار درهم‌تنه‌ای از سوءتفاهم می‌شویم. با نکات و اسکریپت هایی که از تجربه نویسنده به عنوان یک محقق کاربر گرفته شده است، می توانیم مهارت های شنیداری خود را بهبود بخشیم و با انجام این کار، خودمان شنیده و درک شویم.</p>', '2021-06-19 00:00:00', 4, 255, 'https://images.blinkist.io/images/books/60c21d006cee070007da2b85/1_1/470.jpg', '/en/books/listen-like-you-mean-it-en/purchase', 'مثل-اینکه-منظورت-این-است-گوش-کن', '2023-01-26 20:13:43.432885', '2023-01-26 20:13:43.432885', NULL, 'Listen Like You Mean It');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (767, 'چگونه با 50 دلار در روز به دنیا سفر کنیم؟', 'ارزان تر، طولانی تر، هوشمندانه تر سفر کنید', 'ارزان تر، طولانی تر، هوشمندانه تر سفر کنید', 19, 8, 'book', 't', '<p><em>چگونه با 50 دلار در روز به دنیا سفر کنیم</em> (2013) راهنمای هر کسی است که می خواهد بیشتر سفر کند اما نگران خطرات احتمالی و هزینه های گزاف است. مت کپنس نویسنده و وبلاگ نویس محبوب سفر توضیح می دهد که برای داشتن یک مسافر خوب آماده و باهوش چه چیزی لازم است – کسی که می تواند هزینه ها را کاهش دهد، از هزینه های بیهوده اجتناب کند و از همه چیزهایی که دنیا ارائه می دهد لذت ببرد.</p>', '2018-08-02 00:00:00', 4, 41, 'https://images.blinkist.io/images/books/5b61654eb238e10006c07c36/1_1/470.jpg', '/en/books/how-to-travel-the-world-on-50-dollars-a-day-en/purchase', 'چگونه-با-50-دلار-در-روز-به-دنیا-سفر-کنیم؟', '2023-01-26 20:13:50.284919', '2023-01-26 20:13:50.284919', NULL, 'How to Travel the World on $50 a Day');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (768, 'ورزش کرد', 'چرا کاری که ما هرگز برای انجام آن تکامل نیافته ایم سالم و مفید است؟', 'چرا کاری که ما هرگز برای انجام آن تکامل نیافته ایم سالم و مفید است؟', 25, 7, 'book', 't', '<p><em>ورزش شده </em>(2020) گزارشی پیشرفته از فعالیت بدنی، استراحت و سلامت انسان است. با تکیه بر تحقیقات پیشگامانه در زمینه‌های علم ورزش، نظریه تکامل و انسان‌شناسی، گزارشی منحصر به فرد از نیازها و توانایی‌های بدن انسان ارائه می‌کند.</p>', '2021-03-20 00:00:00', 4, 205, 'https://images.blinkist.io/images/books/60507e296cee070007c4dc7e/1_1/470.jpg', '/en/books/exercised-en/purchase', 'ورزش-کرد', '2023-01-26 20:13:59.567161', '2023-01-26 20:13:59.567161', NULL, 'Exercised');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (769, 'مزیت مهاجم', 'تبدیل عدم قطعیت به فرصت های پیشرفت', 'تبدیل عدم قطعیت به فرصت های پیشرفت', 14, 6, 'book', 't', '<p><em>مزیت مهاجم</em> (2015) یک برنامه بازی برای موفقیت در مواقع عدم اطمینان در اختیار شما قرار می دهد. این پلک‌ها به شما نشان می‌دهند که چگونه فرصت‌های پیش روی شما را تشخیص دهید و به شما امکان می‌دهد صنعت خود را برای بهتر شدن تکان دهید. شرکت شما روی پا خواهد ماند و هر بار رقبا را شکست خواهد داد!</p>', '2016-04-27 00:00:00', 4, 26, 'https://images.blinkist.io/images/books/5717a5b53f35690007554e30/1_1/470.jpg', '/en/books/the-attackers-advantage-en/purchase', 'مزیت-مهاجم', '2023-01-26 20:14:06.375071', '2023-01-26 20:14:06.375071', NULL, 'The Attacker’s Advantage');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (770, '5 زبان عشق', 'راز عشقی که ماندگار باشد', 'راز عشقی که ماندگار باشد', 20, 9, 'book', 't', '<p><em>5 زبان عشق</em> (2015) یک راهنمای معاصر برای ایجاد روابط عاشقانه مادام العمر است که می تواند به راحتی بر موانعی که زوج های مدرن با آن روبرو هستند غلبه کند. این پلک‌ها به جزئیات پنج روشی که مردم می‌دهند و احساس عشق می‌کنند، و اینکه چگونه هر زوجی می‌تواند از این دانش برای تقویت رابطه، محبت‌آمیزتر و دلسوزانه‌تر استفاده کند، توضیح می‌دهد.</p>', '2015-12-25 00:00:00', 5, 568, 'https://images.blinkist.io/images/books/56786ba60bac9b0007000029/1_1/470.jpg', '/en/books/the-5-love-languages-en/purchase', '5-زبان-عشق', '2023-01-26 20:14:11.707567', '2023-01-26 20:14:11.707567', NULL, 'The 5 Love Languages');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (771, 'چرا نمی توانیم بخوابیم', 'بحران جدید میانسالی زنان', 'بحران جدید میانسالی زنان', 22, 8, 'book', 't', '<p><em>چرا نمی توانیم بخوابیم</em> (2020) این سوال را بررسی می کند که چرا زنان آمریکایی از نسل X دچار بحران میانسالی می شوند. به این زنان این داستان فروخته شد که هیچ چیز آنها را از دستیابی به وحشیانه ترین رویاهایشان باز نمی دارد، در حالی که در واقعیت با چالش های عظیمی برای پیشرفت روبرو شده اند. آنها نه تنها در بازار کار فاجعه‌بار فارغ‌التحصیل شدند، بلکه با تبعیض جنسیتی و سنی نیز مواجه شدند و اغلب مجبور می‌شوند به طور همزمان از کودکان خردسال و والدین مسن مراقبت کنند. همه چیزهایی که آنها به دست آورده اند بر خلاف شانس های بزرگ بوده است. </p>', '2020-03-06 00:00:00', 4, 43, 'https://images.blinkist.io/images/books/5e5f970e6cee0700069aea34/1_1/470.jpg', '/en/books/why-we-cant-sleep-en/purchase', 'چرا-نمی-توانیم-بخوابیم', '2023-01-26 20:14:19.123156', '2023-01-26 20:14:19.123156', NULL, 'Why We Can’t Sleep');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (772, 'قدرت دیگری', 'تأثیرات خیره کننده ای که دیگران روی شما می گذارند، از اتاق هیئت مدیره گرفته تا اتاق خواب و فراتر از آن – و در مورد آن چه باید کرد', 'تأثیرات خیره کننده ای که دیگران روی شما می گذارند، از اتاق هیئت مدیره گرفته تا اتاق خواب و فراتر از آن – و در مورد آن چه باید کرد', 18, 8, 'book', 't', '<p><em>قدرت دیگری</em> (2016) به شما نشان می‌دهد که چگونه روابط در زندگی شما عمیقاً بر نحوه تفکر، عمل و احساس شما تأثیر می‌گذارد. این پلک ها بررسی می کنند که چرا برخی از روابط به ما آسیب می رسانند در حالی که دیگران ما را پرورش می دهند. مهمتر از همه، شما یاد خواهید گرفت که چگونه ارتباطات واقعی ایجاد کنید که شما را برآورده کند و به رشد شما به عنوان یک شخص کمک کند.</p>', '2016-09-06 00:00:00', 4, 56, 'https://images.blinkist.io/images/books/57c948a308dc1b000317fe6f/1_1/470.jpg', '/en/books/the-power-of-the-other-en/purchase', 'قدرت-دیگری', '2023-01-26 20:14:24.250131', '2023-01-26 20:14:24.250131', NULL, 'The Power of the Other');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (773, 'داستان Airbnb', 'چگونه سه مرد معمولی یک صنعت را مختل کردند و میلیاردها به دست آوردند. . . و جنجال زیادی ایجاد کرد', 'چگونه سه مرد معمولی یک صنعت را مختل کردند و میلیاردها به دست آوردند. . . و جنجال زیادی ایجاد کرد', 21, 8, 'book', 't', '<p><em>داستان Airbnb</em> (2017) داستان خارق‌العاده‌ای را در پس ظهور Airbnb بیان می‌کند. این پلک‌ها توضیح می‌دهند که چگونه در عرض حدود یک دهه، سه فارغ‌التحصیل اخیر کالج از عقب ماندن از اجاره بهای محبوب‌ترین پلت‌فرم محل اقامت در تعطیلات در تاریخ تبدیل شدند.</p>', '2018-01-09 00:00:00', 4, 53, 'https://images.blinkist.io/images/books/5a5163f3b238e10006337087/1_1/470.jpg', '/en/books/the-airbnb-story-en/purchase', 'داستان-Airbnb', '2023-01-26 20:14:31.051491', '2023-01-26 20:14:31.051491', NULL, 'The Airbnb Story');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (774, 'چگونه مکالمات غیرممکن داشته باشیم', 'یک راهنمای بسیار کاربردی', 'یک راهنمای بسیار کاربردی', 26, 8, 'book', 't', '<p><em>چگونه مکالمات غیرممکن داشته باشیم </em>(2019) راهنمایی برای داشتن مکالمات صریح است که به اشک ختم نمی شود. فیلسوف پیتر بوگوسیان و دانشمند جیمز لیندسی استدلال می‌کنند که هر چقدر هم که موضوع مهم باشد، همه ما وقتی اختلافات خود را بیان می‌کنیم سود می‌بریم - به شرط اینکه بخواهیم چیزی یاد بگیریم، نه اینکه فقط مخالفان خود را فریاد بزنیم. این پلک‌ها تکنیک‌هایی را بررسی می‌کنند که گفت‌وگوی محترمانه را تسهیل می‌کنند، از قوانین ایجاد رابطه تا هنر متقاعد کردن شریک جنگی خود برای بررسی مجدد مفروضاتش. </p>', '2020-05-12 00:00:00', 5, 564, 'https://images.blinkist.io/images/books/5eb5e2d16cee070006fe5a0f/1_1/470.jpg', '/en/books/how-to-have-impossible-conversations-en/purchase', 'چگونه-مکالمات-غیرممکن-داشته-باشیم', '2023-01-26 20:14:38.510628', '2023-01-26 20:14:38.510628', NULL, 'How to Have Impossible Conversations	');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (775, 'خانه بدهی', 'چگونه آنها (و شما) باعث رکود بزرگ شدند و چگونه می توانیم از وقوع مجدد آن جلوگیری کنیم', 'چگونه آنها (و شما) باعث رکود بزرگ شدند و چگونه می توانیم از وقوع مجدد آن جلوگیری کنیم', 15, 8, 'book', 'f', '<p>زمانی که بانک‌ها را در طول رکود بزرگ نجات دادیم، در واقع به عوامل واقعی که باعث رکود اقتصادی شده‌اند توجه نکردیم. مشکل واقعی مربوط به اعطای وام های رهنی بیش از حد به کسانی بود که توانایی پرداخت آن را نداشتند، که منجر به بدهی های سنگین و در نهایت سقوط بزرگ در هزینه های مصرف کننده شد. برای جلوگیری از عواقب این چرخه رونق و رکود در آینده، نویسندگان روش‌های جدیدی را برای تجدید ساختار بدهی و تحریک اقتصاد پیشنهاد می‌کنند.</p>', '2014-11-17 00:00:00', 4, 12, 'https://images.blinkist.io/images/books/5469fb6330343600090b0000/1_1/470.jpg', '/en/books/house-of-debt-en/purchase', 'خانه-بدهی', '2023-01-26 20:14:45.777143', '2023-01-26 20:14:45.777143', NULL, 'House of Debt');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (777, 'چه کسی چه چیزی را دریافت می کند - و چرا', 'اقتصاد جدید همسان سازی و طراحی بازار', 'اقتصاد جدید همسان سازی و طراحی بازار', 11, 5, 'book', 't', '<p>در <em>چه کسی چه می‌گیرد – و چرا </em> (2015)، برنده جایزه نوبل، آلوین راث، تحقیقات پیشگامانه‌اش در مورد طراحی بازار را برای مخاطبان گسترده‌تر و غیرمتخصصی ارائه می‌کند و توضیح می‌دهد که بازارها چگونه کار می‌کنند، چرا گاهی اوقات شکست می‌خورند و چه کاری می توانیم برای بهبود آنها انجام دهیم. راث با استفاده از مثال‌های معاصر، عوامل غیرمالی را که بازارها را شکل می‌دهند، تشریح می‌کند و نشان می‌دهد که چگونه می‌توانیم تصمیمات آگاهانه‌تری در بازار بگیریم.</p>', '2015-10-02 00:00:00', 4, 19, 'https://images.blinkist.io/images/books/56094ad78a14e600090000ea/1_1/470.jpg', '/en/books/who-gets-what-and-why-en/purchase', 'چه-کسی-چه-چیزی-را-دریافت-می-کند---و-چرا', '2023-01-26 20:14:59.495395', '2023-01-26 20:14:59.495395', NULL, 'Who Gets What – and Why');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (778, 'هنر، شرکت', 'راهنمای ضروری برای ایجاد شغل شما به عنوان یک هنرمند', 'راهنمای ضروری برای ایجاد شغل شما به عنوان یک هنرمند', 16, 7, 'book', 't', '<p><em>Art, Inc.</em> راهنمای عملی برای هنرمندانی است که می خواهند از انجام کاری که دوست دارند امرار معاش کنند. Art, Inc. جنبه تجاری دنیای هنر را به شیوه ای دلپذیر ارائه می دهد و توصیه های مفید و راهنمایی های عملی را به اشتراک می گذارد.</p>', '2014-11-04 00:00:00', 4, 40, 'https://images.blinkist.io/images/books/545795d03365660008740000/1_1/470.jpg', '/en/books/art-inc-en/purchase', 'هنر،-شرکت', '2023-01-26 20:15:06.640309', '2023-01-26 20:15:06.640309', NULL, 'Art, Inc.');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (779, 'بازاریابی عصبی', 'درک "دکمه های خرید" در مغز مشتری شما', 'درک "دکمه های خرید" در مغز مشتری شما', 19, 8, 'book', 't', '<p>با استفاده از تحقیقات مغزی و تکنیک‌های بازاریابی نوآورانه، <em>بازاریابی عصبی</em> (2002) بینش‌هایی را در مورد نحوه تصمیم‌گیری ما برای خرید ارائه می‌دهد. درک فرآیندهای قدیمی تصمیم گیری مغز شما را با ابزارهای لازم برای بستن معاملات و ایجاد انگیزه در افراد مجهز می کند.</p>', '2015-09-04 00:00:00', 4, 72, 'https://images.blinkist.io/images/books/55e616367a20120009000029/1_1/470.jpg', '/en/books/neuromarketing-en/purchase', 'بازاریابی-عصبی', '2023-01-26 20:15:13.73087', '2023-01-26 20:15:13.73087', NULL, 'Neuromarketing');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (780, 'یا', 'یک زندگی', 'یک زندگی', 24, 10, 'book', 't', '<p><em>علی </em>(2017) شما را به زندگی محمد علی می‌برد، مردی که داستان پیچیده‌اش نشان می‌دهد که او بسیار بیشتر از یکی از بزرگترین بوکسورهای سنگین وزن تاریخ است. نویسنده جاناتان ایگ، ​​خوانندگان را از آغاز فروتنانه کاسیوس کلی جوان، تبدیل شدن او به محمد علی و پیروزی‌ها و رسوایی‌های بسیاری که در پی آن رخ داد، می‌برد.</p>', '2018-04-03 00:00:00', 4, 20, 'https://images.blinkist.io/images/books/5ac05e7eb238e10007c07cbc/1_1/470.jpg', '/en/books/ali-en/purchase', 'یا', '2023-01-26 20:15:21.005737', '2023-01-26 20:15:21.005737', NULL, 'Ali');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (781, 'چارلی مانگر', 'سرمایه گذار کامل', 'سرمایه گذار کامل', 12, 5, 'book', 't', '<p><em>چارلی مانگر</em>(2015) راهنمای شما برای درک استراتژی‌ها و اصولی است که سال‌ها شریک مالی وارن بافت، چارلی مانگر، که یکی از موفق‌ترین سرمایه‌گذاران جهان به حساب می‌آید، هدایت کرده است. این پلک ها شما را با سیستم سرمایه گذاری ارزش گراهام که مانگر استفاده می کند آشنا می کند، اهمیت صبر و شجاعت را توضیح می دهد و به شما نشان می دهد که چگونه با استفاده از دانش بین رشته ای تصمیمات هوشمندانه بگیرید.</p>', '2016-07-13 00:00:00', 4, 141, 'https://images.blinkist.io/images/books/577faf66c088090003fe9ed5/1_1/470.jpg', '/en/books/charlie-munger-en/purchase', 'چارلی-مانگر', '2023-01-26 20:15:27.828865', '2023-01-26 20:15:27.828865', NULL, 'Charlie Munger');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (782, 'هنر جنگ (نسخه جدید)', 'استراتژی نظامی کلاسیک برای سیاست، تجارت و زندگی روزمره', 'استراتژی نظامی کلاسیک برای سیاست، تجارت و زندگی روزمره', 11, 4, 'book', 't', '<p><em>هنر جنگ </em> (قرن پنجم پیش از میلاد) یک رساله نظامی چینی است که بسیاری از شخصیت های جهانی، از جمله مائو تسه تونگ و داگلاس مک آرتور، از آن برای اطلاع رسانی استراتژی های رهبری خود استفاده کرده اند. همراه با تاکتیک های نظامی که می تواند در فرهنگ، سیاست، تجارت و ورزش اعمال شود، مهارت هایی را که رهبران خوب باید داشته باشند را برجسته می کند. </p>', '2022-07-06 00:00:00', 4, 640, 'https://images.blinkist.io/images/books/62bd9e316cee0700081cd687/1_1/470.jpg', '/en/books/the-art-of-war-new-version-en/purchase', 'هنر-جنگ-(نسخه-جدید)', '2023-01-26 20:15:35.260242', '2023-01-26 20:15:35.260242', NULL, 'The Art of War (New Version)');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (783, 'مارتین لوتر', 'شورش در عصر آشوب', 'شورش در عصر آشوب', 31, 13, 'book', 't', '<p><em>مارتین لوتر</em> (2017) جزئیات زندگی و زمانه یکی از مهم ترین شخصیت های تاریخ اروپا را شرح می دهد. پانصد سال پیش، کشیش آلمانی مارتین لوتر جرقه اصلاحات را زد، که در نهایت کلیسای پروتستان را به وجود آورد و در نتیجه شکاف دائمی بین کلیسای پروتستان و کلیسای کاتولیک روم ایجاد کرد. این کتاب تفسیر تازه‌ای از زندگی لوتر ارائه می‌کند و بررسی می‌کند که اقدامات او - و به طور کلی اصلاحات - درباره دنیای مدرن به ما می‌گوید.</p>', '2018-02-02 00:00:00', 4, 46, 'https://images.blinkist.io/images/books/5a71be6fb238e100076ea9d4/1_1/470.jpg', '/en/books/martin-luther-en/purchase', 'مارتین-لوتر', '2023-01-26 20:15:41.997964', '2023-01-26 20:15:41.997964', NULL, 'Martin Luther');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (814, 'عادات کوچک', 'عادات کوچکتر، نتایج بزرگتر', 'عادات کوچکتر، نتایج بزرگتر', 14, 7, 'book', 't', '<p><em>عادت های کوچک</em>(2013) منطق پشت یک رویکرد نوآورانه برای دستیابی به اهداف شما را توضیح می دهد. انگیزه و جاه طلبی لزوماً شما را به موفقیت سوق نمی دهند. بلکه این عادات کوچک روزانه شما هستند که واقعا شما را در مسیر درست قرار می دهند. بیاموزید که چگونه با این پلک ها از قدرت آنها استفاده کنید.</p>', '2015-11-19 00:00:00', 5, 378, 'https://images.blinkist.io/images/books/564a068266343100077f0000/1_1/470.jpg', '/en/books/mini-habits-en/purchase', 'عادات-کوچک', '2023-01-26 20:19:19.788157', '2023-01-26 20:19:19.788157', NULL, 'Mini Habits');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (784, 'یک چیز', 'حقیقت ساده شگفت انگیزی که در پس نتایج خارق العاده وجود دارد', 'حقیقت ساده شگفت انگیزی که در پس نتایج خارق العاده وجود دارد', 18, 12, 'book', 't', '<p><em>The ONE Thing</em> (2013) به شما کمک می‌کند تا مهم‌ترین هدف خود را کشف کنید، و ابزارهایی را در اختیار شما قرار می‌دهد تا اطمینان حاصل کنید که می‌توانید از زمان خود برای رسیدن به آن بهره‌مند استفاده کنید. این کتاب نشان می‌دهد که بسیاری از اصولی که ما به‌عنوان تمرین خوب می‌پذیریم، در واقع افسانه‌هایی هستند که فقط مانع پیشرفت ما می‌شوند. همچنین توصیه هایی در مورد چگونگی زندگی با اولویت، هدف و بهره وری ارائه می دهد، بدون اینکه سایر جنبه های زندگی را از حالت تعادل خارج کنید، زیرا این روشی برای انجام کاری متمرکز است که منجر به موفقیت بزرگ می شود.</p>', '2013-11-27 08:59:18', 5, 469, 'https://images.blinkist.io/images/books/52934d2d6231360018110000/1_1/470.jpg', '/en/books/the-one-thing-en/purchase', 'یک-چیز', '2023-01-26 20:15:49.15949', '2023-01-26 20:15:49.15949', NULL, 'The ONE Thing');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (785, 'انقلاب بازاریابی محتوا', 'کنترل بازار خود را در پنج مرحله به دست بگیرید', 'کنترل بازار خود را در پنج مرحله به دست بگیرید', 13, 6, 'book', 't', '<p><em>انقلاب بازاریابی محتوا </em>(2015) مقدمه شما برای راهبردهای جدید پیشگام در بازاریابی دیجیتال امروزی است. این پلک ها شما را در فرآیند توسعه و اجرای استراتژی بازاریابی محتوا راهنمایی می کنند و به شما کمک می کنند تا تلاش های تبلیغاتی خود را بهینه کنید. </p>', '2016-01-25 00:00:00', 4, 65, 'https://images.blinkist.io/images/books/56a5d7c4ce4ca9000700001f/1_1/470.jpg', '/en/books/content-marketing-revolution-en/purchase', 'انقلاب-بازاریابی-محتوا', '2023-01-26 20:15:56.575116', '2023-01-26 20:15:56.575116', NULL, 'Content Marketing Revolution');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (786, 'شیمی بازرگانی', 'جادوی عملی برای ایجاد روابط کاری قدرتمند', 'جادوی عملی برای ایجاد روابط کاری قدرتمند', 24, 8, 'book', 't', '<p><em>شیمی کسب و کار</em> (2018) تنش ها و مشکلات موجود در روابط کاری ما را بررسی می کند. این پلک‌ها حاوی نکات و ترفندهایی برای کلیک کردن با چالش‌برانگیزترین همکاران، راهنمای ضروری شما برای ایجاد ارتباطات معنی‌دار در محل کار است. </p>', '2020-01-13 00:00:00', 4, 43, 'https://images.blinkist.io/images/books/5e1861da6cee070008f4fa1d/1_1/470.jpg', '/en/books/business-chemistry-en/purchase', 'شیمی-بازرگانی', '2023-01-26 20:16:04.225602', '2023-01-26 20:16:04.225602', NULL, 'Business Chemistry');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (787, 'زنان قایقرانی شمال', 'حرکت در جریان زندگی و شکوفایی با افزایش سن', 'حرکت در جریان زندگی و شکوفایی با افزایش سن', 17, 6, 'book', 't', '<p><em>زنان قایقرانی شمال</em> (2019) به بررسی این موضوع می‌پردازد که چگونه زنان می‌توانند با ورود به دهه شصت و هفتاد سالگی به شکوفایی خود ادامه دهند. این پلک ها از طریق داستان های تکان دهنده از زندگی واقعی زنان، احتمالات شادی، دوستی و مشارکت اجتماعی را در مراحل بعدی زندگی بررسی می کنند.</p>', '2019-03-12 00:00:00', 4, 16, 'https://images.blinkist.io/images/books/5c83d8dc6cee070008d61295/1_1/470.jpg', '/en/books/women-rowing-north-en/purchase', 'زنان-قایقرانی-شمال', '2023-01-26 20:16:11.55591', '2023-01-26 20:16:11.55591', NULL, 'Women Rowing North');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (788, 'جامعه هزینه نهایی صفر', 'اینترنت اشیا، مشترکات مشترک و کسوف سرمایه داری', 'اینترنت اشیا، مشترکات مشترک و کسوف سرمایه داری', 20, 8, 'book', 't', '<p><em>جامعه هزینه نهایی صفر </em>(2014) یک مورد قوی برای ماهیت خود ویرانگر سرمایه داری ارائه می کند و نشان می دهد که چگونه بذرهای نابودی خود را می کارد. اما در پی آن، یک اقتصاد جدید، مشارکتی و دموکراتیک تحقق خواهد یافت - اقتصادی که توسط اینترنت ممکن شده است.</p>', '2015-04-22 00:00:00', 4, 26, 'https://images.blinkist.io/images/books/5534fdaa6638630007960000/1_1/470.jpg', '/en/books/the-zero-marginal-cost-society-en/purchase', 'جامعه-هزینه-نهایی-صفر', '2023-01-26 20:16:18.518738', '2023-01-26 20:16:18.518738', NULL, 'The Zero Marginal Cost Society');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (789, 'سوختن', 'راز باز کردن چرخه استرس', 'راز باز کردن چرخه استرس', 24, 8, 'book', 't', '<p><em>فرسودگی شغلی </em>(2019) به زنان نگاهی صادقانه و عملی به علل استرس و اضطراب روزمره آنها و راههای مختلفی که علم می تواند به آنها کمک کند ارائه می دهد. از آنجایی که زنان همچنان با مجموعه ای متفاوت از انتظارات از مردان روبرو هستند، منطقی است که زنان نیز با شکل متفاوتی از فرسودگی شغلی روبرو هستند. امیلی و آملیا ناگوسکی، نویسندگان، بینش علمی و همچنین شخصی را در مورد آنچه واقعاً در جریان است و آنچه زنان می‌توانند انجام دهند تا نه تنها در دنیای مدرن ادامه دهند، بلکه رشد کنند، ارائه می‌دهند.</p>', '2019-03-26 00:00:00', 4, 171, 'https://images.blinkist.io/images/books/5c9687686cee070008b872c9/1_1/470.jpg', '/en/books/burnout-en/purchase', 'سوختن', '2023-01-26 20:16:25.344159', '2023-01-26 20:16:25.344159', NULL, 'Burnout');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (790, 'چهار عشق', 'تامل در مورد محبت، دوستی، اروس و خیریه', 'تامل در مورد محبت، دوستی، اروس و خیریه', 21, 5, 'book', 't', '<p><em>چهار عشق </em>(1960) کاوشی در مورد عشق در اشکال مختلف آن است. نویسنده سی. اس. لوئیس، با ردیابی چگونگی انگیزه هر شکل، مواهب و کاستی های عشق را شناسایی می کند و نشان می دهد که چگونه عشق الهی خداوند می تواند همه روابط ما را زیبا کند.</p>', '2022-04-24 00:00:00', 4, 193, 'https://images.blinkist.io/images/books/62630a496cee0700085a408b/1_1/470.jpg', '/en/books/the-four-loves-en/purchase', 'چهار-عشق', '2023-01-26 20:16:30.736366', '2023-01-26 20:16:30.736366', NULL, 'The Four Loves');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (882, 'چه می شود اگر؟', 'پاسخ های علمی جدی به پرسش های فرضی پوچ', 'پاسخ های علمی جدی به پرسش های فرضی پوچ', 18, 8, 'book', 't', '<p>در <em>چه می‌شد؟</em> (2014)، راندال مونرو پاسخ‌های جدی و کاملاً تحقیق شده به سؤالات فرضی و پوچ را در قالبی بسیار سرگرم‌کننده و قابل هضم ارائه می‌کند. مونرو محبوب‌ترین پاسخ‌ها را از پرسش‌هایی که از طریق <em>What If? </em>وبلاگ، همراه با انبوهی از پرسش ها و پاسخ های جدید، لذت بخش، ذهن گیر. </p>', '2015-05-13 00:00:00', 4, 55, 'https://images.blinkist.io/images/books/5550b6c06332630007700000/1_1/470.jpg', '/en/books/what-if-en/purchase', 'چه-می-شود-اگر؟', '2023-01-26 20:38:31.363732', '2023-01-26 20:38:31.363732', NULL, 'What If?');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (791, 'بافت', 'ساخت یک سرمایه دار آمریکایی', 'ساخت یک سرمایه دار آمریکایی', 15, 6, 'book', 't', '<p><em>بافت</em> (1995) داستان وارن بافت را روایت می کند، از آغاز فروتنانه او به عنوان یک پسر با یک مسیر کاغذی برای <em> واشنگتن پست </em>تا موفقیت او به عنوان یکی از بزرگترین سهامدار روزنامه اما البته، این همه چیز نیست. امروزه وارن بافت یکی از ثروتمندترین افراد جهان و یکی از بزرگترین نیکوکاران آن است. دریابید که او چگونه به آنجا رسیده است و چگونه ترکیب منحصر به فرد خود را از سخت کوشی، ثبات و صرفه جویی به کار می گیرد.</p>', '2017-04-27 00:00:00', 5, 124, 'https://images.blinkist.io/images/books/58ff670db238e100061eedd5/1_1/470.jpg', '/en/books/buffett-en/purchase', 'بافت', '2023-01-26 20:16:35.849953', '2023-01-26 20:16:35.849953', NULL, 'Buffett');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (792, 'یادداشت هایی از یک جزیره کوچک', 'پرتره ای عاشقانه از بریتانیا', 'پرتره ای عاشقانه از بریتانیا', 22, 8, 'book', 't', '<p><em>یادداشت‌هایی از یک جزیره کوچک </em> (1995) توسط نویسنده آمریکایی تبار بیل برایسون نوشته شده است در حالی که او آماده می‌شد روستای کوچک یورکشایر را که 20 سال در آن زندگی می‌کرد ترک کند و به عقب برگردد. به ایالات متحده امریکا. قبل از عزیمت، او تصمیم گرفت تا با جزیره پذیرفته شده خود، بریتانیای کبیر خداحافظی کند. این سفرنامه، تور خداحافظی او را در مناظر، فرهنگ، آداب و رسوم و مکان‌های عجیب و غریب بریتانیا، که او بسیار دوست داشت، مستند می‌کند.</p>', '2018-06-25 00:00:00', 4, 47, 'https://images.blinkist.io/images/books/5b2fcfd5b238e10006f8a84c/1_1/470.jpg', '/en/books/notes-from-a-small-island-en/purchase', 'یادداشت-هایی-از-یک-جزیره-کوچک', '2023-01-26 20:16:43.00025', '2023-01-26 20:16:43.00025', NULL, 'Notes from a Small Island');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (793, 'غذای راحتی مدرن', 'کتاب آشپزی کونتسا پابرهنه', 'کتاب آشپزی کونتسا پابرهنه', 19, 6, 'book', 't', '<p><em>Modern Comfort Food </em>(2020) دوازدهمین کتاب آشپزی Ina Garten است که بر روی غذاهای مورد علاقه تمام آمریکایی‌ها تمرکز دارد تا احساس راحتی و مراقبت کنیم. اینا با استایل شیک و در عین حال قابل اعتنای همپتون‌هایش، دستور العمل‌های آرامش‌بخش را برای هر وعده غذایی در روز، از صبحانه تا ساعت کوکتل و دسر، سرو می‌کند.</p>', '2021-01-30 00:00:00', 4, 12, 'https://images.blinkist.io/images/books/600aa7d36cee070007562cec/1_1/470.jpg', '/en/books/modern-comfort-food-en/purchase', 'غذای-راحتی-مدرن', '2023-01-26 20:16:50.683236', '2023-01-26 20:16:50.683236', NULL, 'Modern Comfort Food');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (794, 'اختروبال', 'راه جدید برای برنده شدن در همه چیز', 'راه جدید برای برنده شدن در همه چیز', 21, 8, 'book', 't', '<p><em>Astroball</em> (2018) انقلاب مدیریتی را به تصویر می‌کشد که تیم بیسبال هیوستون آستروس را از سطح متوسط ​​لیگ به قهرمانی در سری جهانی 2017 سوق داد. راز؟ کنار گذاشتن سیاست‌های قدیمی جستجو و استخدام که متکی بر «غریزه درونی» و در آغوش گرفتن قدرت داده‌های بزرگ است. این کتاب پر از بینش های شگفت انگیز در مورد دنیای بیسبال آمریکایی، با تمام سنت ها و آداب آن، برای کسانی است که عاشق این ورزش هستند و همچنین برای هر کسی که مجذوب روشی است که فناوری در حال تغییر شکل دادن به جهان ما است، باید آن را بخواند.</p >', '2018-11-30 00:00:00', 4, 22, 'https://images.blinkist.io/images/books/5bfd73cb6cee070007f92271/1_1/470.jpg', '/en/books/astroball-en/purchase', 'اختروبال', '2023-01-26 20:16:57.961033', '2023-01-26 20:16:57.961033', NULL, 'Astroball');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (795, 'هیچوقت کافی نیست', 'علوم اعصاب و تجربه اعتیاد', 'علوم اعصاب و تجربه اعتیاد', 23, 8, 'book', 't', '<p><em>Never Enough</em> (2019) درباره مواد مخدر و اعتیاد است. نویسنده علم پشت مواد مخدر از الکل گرفته تا کوکائین را بررسی می‌کند و توضیح می‌دهد که چرا برخی افراد بیشتر از دیگران مستعد اعتیاد هستند.</p>', '2019-07-12 00:00:00', 4, 185, 'https://images.blinkist.io/images/books/5d25b6386cee0700075fd16f/1_1/470.jpg', '/en/books/never-enough-en/purchase', 'هیچوقت-کافی-نیست', '2023-01-26 20:17:04.644688', '2023-01-26 20:17:04.644688', NULL, 'Never Enough');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (796, 'نماینده املاک میلیونر', 'در مورد پول نیست', 'در مورد پول نیست', 18, 8, 'book', 't', '<p><em>نماینده املاک میلیونر</em> (2004) راهنمای شما برای موفقیت در تجارت املاک و مستغلات است. این پلک ها به جزئیات استراتژی های عملی برای ساختن یک امپراتوری املاک و مستغلات از پایه و سودآور نگاه داشتن آن می پردازند.</p>', '2016-08-25 00:00:00', 4, 93, 'https://images.blinkist.io/images/books/57bb4a45003a4b0003f1a856/1_1/470.jpg', '/en/books/the-millionaire-real-estate-agent-en/purchase', 'نماینده-املاک-میلیونر', '2023-01-26 20:17:11.537618', '2023-01-26 20:17:11.537618', NULL, 'The Millionaire Real Estate Agent');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (797, 'بالا بردن تعالی', 'رسیدن به بیشتر بدون رضایت به چیزهای کمتر', 'رسیدن به بیشتر بدون رضایت به چیزهای کمتر', 19, 9, 'book', 't', '<p><em>مقیاس‌سازی</em> <em>بالا</em> <em>تعالی</em> اولین نشریه تجاری بزرگی است که به چگونگی گسترش مؤثر شیوه‌های نمونه در سازمان خود توسط رهبران می‌پردازد. خوانندگان می توانند انتظار داشته باشند که در مورد آخرین تحقیقات در زمینه رفتار سازمانی، بسیاری از مطالعات موردی آموزنده در صنعت، و بسیاری از شیوه های مفید، استراتژی ها و اصول برای افزایش مقیاس اطلاعات کسب کنند.</p>
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (798, 'تسلط', 'کلیدهای موفقیت و تحقق بلندمدت', 'کلیدهای موفقیت و تحقق بلندمدت', 17, 6, 'book', 't', '<p><em>Mastery </em>(1992) نشان می دهد که چگونه می توانید طرز فکر خود را برای دستیابی به موفقیت بلندمدت در کارهای جدید تغییر دهید. این پلک‌ها با تکیه بر مثال‌های واقعی از آموزه‌های ورزش، روان‌شناسی و ذهن‌آگاهی، پنج عنصر ضروری برای دستیابی به تسلط در هر رشته‌ای را توضیح می‌دهند و ابزارهایی را در اختیار ما می‌گذارند که برای رهایی از دام‌ها در این راه نیاز داریم.</p>', '2016-12-14 00:00:00', 5, 82, 'https://images.blinkist.io/images/books/584c52bbaf38d6000494d518/1_1/470.jpg', '/en/books/mastery-en-george-leonard/purchase', 'تسلط', '2023-01-26 20:17:25.493781', '2023-01-26 20:17:25.493781', NULL, 'Mastery');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (799, 'کوچک زیباست', 'مطالعه اقتصاد به گونه ای که گویی مردم اهمیت دارند', 'مطالعه اقتصاد به گونه ای که گویی مردم اهمیت دارند', 17, 8, 'book', 't', '<p><em>کوچک زیباست </em>(1973) مجموعه ای از مقالات اقتصاددان مشهور بریتانیایی E. F. Schumacher است که نقد خود را از سیستم اقتصادی غرب بیان می کند. این مجموعه کلاسیک که برای اولین بار در سال 1973 منتشر شد، که اکنون به عنوان یکی از تأثیرگذارترین کتاب‌های منتشر شده از زمان جنگ جهانی دوم به حساب می‌آید، امروز به اندازه دهه 70 مرتبط است.</p>', '2015-09-15 00:00:00', 4, 42, 'https://images.blinkist.io/images/books/55f6d9f529161a0009000041/1_1/470.jpg', '/en/books/small-is-beautiful-en/purchase', 'کوچک-زیباست', '2023-01-26 20:17:32.683934', '2023-01-26 20:17:32.683934', NULL, 'Small is Beautiful');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (800, 'کسب و کار آگاهانه', 'چگونه از طریق ارزش ها ارزش بسازیم', 'چگونه از طریق ارزش ها ارزش بسازیم', 18, 8, 'book', 't', '<p><em>تجارت آگاهانه</em> (2006) فراتر از معیارهای متعارف موفقیت پیش می رود تا به شما نشان دهد چگونه یک سازمان پویا بر اساس ارزش های اصلی انسانی ایجاد کنید. خواهید آموخت که چرا شرکت هایی که به کارمندان قدرت می دهند تا کار خود را با ارزش هایی که برایشان مهم است هماهنگ کنند، شرکت هایی هستند که در بازار امروز موفق می شوند.</p>', '2015-11-04 00:00:00', 4, 53, 'https://images.blinkist.io/images/books/5637751f62346500076b0000/1_1/470.jpg', '/en/books/conscious-business-en/purchase', 'کسب-و-کار-آگاهانه', '2023-01-26 20:17:39.921862', '2023-01-26 20:17:39.921862', NULL, 'Conscious Business');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (801, 'میزان سوختگی', 'راه اندازی یک استارتاپ و از دست دادن ذهنم', 'راه اندازی یک استارتاپ و از دست دادن ذهنم', 30, 13, 'book', 't', '<p><em>Burn Rate </em>(2022) داستان بی‌نظیر اندی دان، یکی از بنیانگذاران استارت‌آپ پوشاک مردانه Bonobos، و مبارزات او با اختلال دوقطبی است. دان که مدت‌ها تشخیص خود را انکار می‌کرد، در نهایت با این بیماری مواجه شد - اما نه قبل از اینکه تقریباً همه چیز را برای او تمام کرده باشد.</p>', '2022-10-03 00:00:00', 5, 189, 'https://images.blinkist.io/images/books/633586ca6cee070008031e12/1_1/470.jpg', '/en/books/burn-rate-en/purchase', 'میزان-سوختگی', '2023-01-26 20:17:46.737834', '2023-01-26 20:17:46.737834', NULL, 'Burn Rate');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (802, 'امواج سرکش', 'آینده کسب و کار خود را برای بقا و سود از تغییرات رادیکال اثبات کنید', 'آینده کسب و کار خود را برای بقا و سود از تغییرات رادیکال اثبات کنید', 21, 6, 'book', 't', '<p><em>موج های سرکش </em>(2021) یک کتاب بازی برای هدایت شرکت شما در میان دریاهای طوفانی است. با برگرفته از موارد کسب و کار در دنیای واقعی، نکات قابل اجرا برای ماندن در میان تغییرات شدید را به اشتراک می گذارد.</p>', '2021-09-22 00:00:00', 4, 30, 'https://images.blinkist.io/images/books/61446c476cee070007e05181/1_1/470.jpg', '/en/books/rogue-waves-en/purchase', 'امواج-سرکش', '2023-01-26 20:17:53.81223', '2023-01-26 20:17:53.81223', NULL, 'Rogue Waves');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (803, 'دوازده قدم برای یک زندگی مهربان', 'راهنمای گام به گام برای آوردن شفقت بیشتر به جهان', 'راهنمای گام به گام برای آوردن شفقت بیشتر به جهان', 15, 8, 'book', 'f', '<p><em>دوازده قدم برای یک زندگی مهربان</em>راهنمای گام به گام برای آوردن شفقت بیشتر به جهان است. این به شما نشان می دهد که چگونه می توانید در زندگی روزمره خود شفقت را پرورش دهید و به شما کمک می کند نقش خود را در ساختن جهان به مکانی بهتر انجام دهید.</p>', '2015-02-24 00:00:00', 4, 37, 'https://images.blinkist.io/images/books/54eaecb1393366000a210000/1_1/470.jpg', '/en/books/twelve-steps-to-a-compassionate-life-en/purchase', 'دوازده-قدم-برای-یک-زندگی-مهربان', '2023-01-26 20:18:01.919373', '2023-01-26 20:18:01.919373', NULL, 'Twelve Steps to a Compassionate Life');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (804, 'مصرف کنندگان فوق العاده چین', '1 میلیارد مشتری چه می خواهند و چگونه آن را به آنها بفروشیم', '1 میلیارد مشتری چه می خواهند و چگونه آن را به آنها بفروشیم', 16, 6, 'book', 't', '<p><em>Cina''s Super Consumers</em> (2014) راهنمای قطعی برای شرکت های خارجی است که می خواهند محصولات خود را در بازار چین بفروشند. این پلک‌ها شما را در فرصت‌ها و چالش‌های این کشور وسیع و متنوع راهنمایی می‌کنند و اطلاعات ارزشمندی درباره نحوه موفقیت در زمینه کسب‌وکار منحصربه‌فرد آن به اشتراک می‌گذارند.</p>', '2017-12-05 00:00:00', 4, 29, 'https://images.blinkist.io/images/books/5a23a8bfb238e100062d55ad/1_1/470.jpg', '/en/books/chinas-super-consumers-en/purchase', 'مصرف-کنندگان-فوق-العاده-چین', '2023-01-26 20:18:09.178869', '2023-01-26 20:18:09.178869', NULL, 'China’s Super Consumers');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (805, 'وین بک مشتری', 'چگونه مشتریان از دست رفته را بازیابی کنیم - و آنها را وفادار نگه داریم', 'چگونه مشتریان از دست رفته را بازیابی کنیم - و آنها را وفادار نگه داریم', 14, 6, 'book', 't', '<p>حفظ پایگاه مشتری راضی نباید شبیه به گله داری گربه باشد. <em>Customer WinBack</em> (2001) نشان می‌دهد که چگونه شرکت‌ها می‌توانند مشتریان در معرض خطر را شناسایی کرده و قبل از ناپدید شدن از پایگاه‌های داده خود، آنها را به دست آورند. با استفاده از این ترفندهای زیرکانه، کسب‌وکارها می‌توانند به منظور کاهش هزینه‌ها و افزایش درآمد در درازمدت، دوباره بر روی مشتریان فعلی خود تمرکز کنند.</p>', '2015-04-22 00:00:00', 4, 14, 'https://images.blinkist.io/images/books/5534fb5466386300077a0000/1_1/470.jpg', '/en/books/customer-winback-en/purchase', 'وین-بک-مشتری', '2023-01-26 20:18:16.871378', '2023-01-26 20:18:16.871378', NULL, 'Customer WinBack');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (806, 'رژیم غذایی کتوژنیک کامل برای مبتدیان', 'راهنمای ضروری شما برای زندگی در سبک زندگی کتو', 'راهنمای ضروری شما برای زندگی در سبک زندگی کتو', 15, 5, 'book', 't', '<p>همانطور که از عنوان پیداست، <em>رژیم غذایی کامل کتوژنیک برای مبتدیان</em> (2016) مقدمه ای مفید برای رژیم کم کربوهیدرات و پرچرب است که می تواند به شما در سوزاندن پوندهای ناخواسته کمک کند. این شما را به یک تور گام به گام می برد که در هنگام «کتو رفتن» چه انتظاراتی داشته باشید و همچنین کارهایی را که می توانید انجام دهید تا مطمئن شوید که به سبک زندگی غذایی جدید پایبند هستید.</p>', '2018-12-07 00:00:00', 4, 118, 'https://images.blinkist.io/images/books/5c06ace16cee0700076d4aa8/1_1/470.jpg', '/en/books/the-complete-ketogenic-diet-for-beginners-en/purchase', 'رژیم-غذایی-کتوژنیک-کامل-برای-مبتدیان', '2023-01-26 20:18:23.878122', '2023-01-26 20:18:23.878122', NULL, 'The Complete Ketogenic Diet for Beginners');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (807, 'ذوب', 'چگونه یکپارچه سازی برند و فرهنگ به بزرگترین شرکت های جهان قدرت می دهد', 'چگونه یکپارچه سازی برند و فرهنگ به بزرگترین شرکت های جهان قدرت می دهد', 24, 9, 'book', 't', '<p><em>Fusion</em> (2018) به کسب‌وکارها توصیه می‌کند که دو حوزه شرکتی را که اغلب به‌عنوان مجزا در نظر گرفته می‌شوند، گرد هم بیاورند: برند و فرهنگ. اگر این دو حوزه با یکدیگر ترکیب شوند، می توانند نیروی محرکه جدید و قدرتمندی در هر کسب و کاری ایجاد کنند.</p>', '2018-07-06 00:00:00', 5, 14, 'https://images.blinkist.io/images/books/5b3ad9a0b238e100071d7d87/1_1/470.jpg', '/en/books/fusion-en/purchase', 'ذوب', '2023-01-26 20:18:30.904555', '2023-01-26 20:18:30.904555', NULL, 'Fusion');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (808, 'عادت مربیگری', 'کمتر بگویید، بیشتر بپرسید و راه هدایت خود را برای همیشه تغییر دهید', 'کمتر بگویید، بیشتر بپرسید و راه هدایت خود را برای همیشه تغییر دهید', 13, 6, 'book', 't', '<p><em>عادت مربیگری</em> (2016) عناصر کوچینگ را تجزیه می‌کند و نحوه مربیگری مؤثر را توضیح می‌دهد. برخلاف آنچه ممکن است فکر کنید، کوچینگ به معنای دادن توصیه نیست، بلکه به معنای راهنمایی کارکنان برای یافتن راه موفقیت است. این پلک ها نشان می دهد که چگونه شما نیز می توانید یک مربی بزرگ شوید.</p>', '2016-08-09 00:00:00', 5, 454, 'https://images.blinkist.io/images/books/57a5a51ebed677000322c475/1_1/470.jpg', '/en/books/the-coaching-habit-en/purchase', 'عادت-مربیگری', '2023-01-26 20:18:36.527281', '2023-01-26 20:18:36.527281', NULL, 'The Coaching Habit');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (809, 'خوشبختی', 'یک تاریخچه', 'یک تاریخچه', 13, 6, 'book', 't', '<p>در<em> شادی: تاریخچه </em>(2006)، ما در سفری در تاریخ به سر می بریم. از یونان باستان، از قرون تاریک و تا دوران مدرن، این سفر نشان می‌دهد که چگونه تصور ما از شادی در طول زمان تغییر کرده و تکامل یافته است.</p>', '2016-03-08 00:00:00', 4, 51, 'https://images.blinkist.io/images/books/56de9df43d0f8d000700001c/1_1/470.jpg', '/en/books/happiness-en-darrin-m-mcmahon/purchase', 'خوشبختی', '2023-01-26 20:18:43.777928', '2023-01-26 20:18:43.777928', NULL, 'Happiness');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (810, 'آن را نخرید', 'مشکل با حرف های بیهوده در مورد اقتصاد', 'مشکل با حرف های بیهوده در مورد اقتصاد', 20, 8, 'book', 't', '<p><em>آن را نخرید</em> (2012) راه هایی را بررسی می کند که زبان بر درک ما از مسائل پیچیده تأثیر می گذارد. آنات شنکر-اوسوریو تحقیقات و تخصص خود را به پرسشی می‌رساند که گریبانگیر مترقی‌ها می‌شود: چرا محافظه‌کاران همیشه در بحث‌های اقتصادی در ایالات متحده پیروز می‌شوند، علی‌رغم نابرابری عمیق و بی‌عدالتی ساختاری که مظهر سقوط مالی و رکود بزرگ است؟ این پلک ها با تجزیه و تحلیل زبان به کار رفته در هر دو طرف طیف سیاسی به این سوال پاسخ می دهند.</p>', '2015-07-21 00:00:00', NULL, 7, 'https://images.blinkist.io/images/books/55ac2f0f65363800073c0000/1_1/470.jpg', '/en/books/dont-buy-it-en/purchase', 'آن-را-نخرید', '2023-01-26 20:18:51.105037', '2023-01-26 20:18:51.105037', NULL, 'Don’t Buy It');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (811, 'فاجعه کامل', 'سفر در میان ویرانه های جدید یونان', 'سفر در میان ویرانه های جدید یونان', 21, 12, 'book', 'f', '<p><em>فاجعه کامل</em> (2015) شما را فراتر از سرفصل های مربوط به بحران بدهی یونان می برد تا دریابید که چگونه شهروندان یونان و فراتر از آن از آن جان سالم به در برده اند. نویسنده از طریق مصاحبه‌های واقعی با مردم روستاهای کوهستانی، استراحتگاه‌های توریستی و پایتخت آتن، تأثیرات کاهش بودجه دولت، سیاست‌های ریاضتی و فساد عمومی را آشکار می‌کند.</p>', '2015-10-12 00:00:00', NULL, 9, 'https://images.blinkist.io/images/books/561bdb803635640007320000/1_1/470.jpg', '/en/books/the-full-catastrophe-en/purchase', 'فاجعه-کامل', '2023-01-26 20:18:58.26978', '2023-01-26 20:18:58.26978', NULL, 'The Full Catastrophe');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (812, 'قلع و قمع', 'رهایی از دنیای بیماری ها برای همیشه', 'رهایی از دنیای بیماری ها برای همیشه', 16, 7, 'book', 't', '<p><em>ریشه‌کنی</em> (2011) درباره تلاش‌های جامعه سلامت برای ریشه‌کن کردن برخی بیماری‌ها از روی کره زمین است. این چشمک‌ها تاریخچه ریشه‌کنی بیماری، موفقیت‌ها و شکست‌های آن، و مسائل سیاسی پیچیده‌ای را که مطرح می‌کند، نشان می‌دهد.</p>', '2016-04-08 00:00:00', NULL, 8, 'https://images.blinkist.io/images/books/57026bf58fb8ff00070000a5/1_1/470.jpg', '/en/books/eradication-en/purchase', 'قلع-و-قمع', '2023-01-26 20:19:05.178109', '2023-01-26 20:19:05.178109', NULL, 'Eradication');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (813, 'درخشش با طراحی', 'ایجاد تجربیات یادگیری که به هم متصل، الهام بخش و درگیر شوند', 'ایجاد تجربیات یادگیری که به هم متصل، الهام بخش و درگیر شوند', 29, 7, 'book', 't', '<p><em>Brilliance by Design </em>(2011) همه چیز در مورد ایجاد تجربیات یادگیری است که درخشش را در هر دانش آموز نشان می دهد. مربیان، معلمان، مربیان و هر کسی که وقت خود را در کلاس درس می گذراند، یک مدل مفید و مفید برای طراحی آموزشی با تاثیر بالا ارائه می کند که الهام بخش و برانگیختن زبان آموزان است. </p>', '2022-04-17 00:00:00', 4, 139, 'https://images.blinkist.io/images/books/625abd936cee07000837f447/1_1/470.jpg', '/en/books/brilliance-by-design-en/purchase', 'درخشش-با-طراحی', '2023-01-26 20:19:12.180211', '2023-01-26 20:19:12.180211', NULL, 'Brilliance by Design');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (815, 'دولت کارآفرین', 'از بین بردن افسانه های عمومی در مقابل بخش خصوصی', 'از بین بردن افسانه های عمومی در مقابل بخش خصوصی', 9, 4, 'book', 'f', '<p><em>دولت کارآفرین </em>(2014) نقش ایالت را به عنوان یک سرمایه گذار جسور در فناوری نوظهور روشن می کند. از آیفون گرفته تا انرژی پایدار، این پلک‌ها نقش مرکزی دولت‌ها را در ایجاد دنیایی که امروز می‌شناسیم و اینکه چگونه می‌توانند به تامین امنیت آینده سیاره ما کمک کنند را نشان می‌دهد.</p>', '2016-01-25 00:00:00', 4, 22, 'https://images.blinkist.io/images/books/56a5d555ce4ca90007000002/1_1/470.jpg', '/en/books/the-entrepreneurial-state-en/purchase', 'دولت-کارآفرین', '2023-01-26 20:19:26.874994', '2023-01-26 20:19:26.874994', NULL, 'The Entrepreneurial State');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (816, 'چرا سکس سرگرم کننده است؟', 'تکامل جنسیت انسان', 'تکامل جنسیت انسان', 17, 7, 'book', 't', '<p>همه به رابطه جنسی فکر می کنند. با این حال، ما به ندرت در نظر می گیریم که تمایلات جنسی انسان تا چه حد با عادات تولیدمثلی گونه های دیگر متفاوت است. در <em>چرا سکس سرگرم کننده است؟</em> (1998)، جرد دایموند کاوشی در تاریخچه جنسی انسان ها ارائه می کند و توضیح می دهد که چگونه رفتار غیرعادی جنسی ما ممکن است دلیل صعود ما به بالای زنجیره غذایی باشد.< /p>
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (817, 'پول', 'بیشتر بدانید، بیشتر بسازید، بیشتر بدهید', 'بیشتر بدانید، بیشتر بسازید، بیشتر بدهید', 17, 6, 'book', 't', '<p><em>پول</em> (2019) برای همه کسانی است که زندگی خود را صرف تلاش برای پول می کنند به جای اینکه پول برای آنها سخت کار کند. این پلک ها طرحی برای استقلال مالی و ثروت پایدار ارائه می دهند. آنها بررسی می کنند که چگونه نگرش ریشه دار شما نسبت به پول ممکن است مانع شما شود و فرمول های ساده ای را برای کمک به شما در تسلط بر امور مالی تعیین می کنند. </p>', '2019-12-30 00:00:00', 4, 249, 'https://images.blinkist.io/images/books/5dfcbc466cee0700087f97cc/1_1/470.jpg', '/en/books/money-en/purchase', 'پول', '2023-01-26 20:19:40.914341', '2023-01-26 20:19:40.914341', NULL, 'Money');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (818, 'سگ کفش', 'خاطرات خالق نایک', 'خاطرات خالق نایک', 14, 6, 'book', 't', '<p><em>سگ کفش</em> (2016) داستان مردی را روایت می‌کند که پشت کمپانی معروف کفش نایک است. این پلک‌ها نگاهی به ذهن کارآفرین نابغه فیل نایت می‌اندازد و جزئیات سفر ترن هوایی را که او برای ایجاد شرکت خود طی کرده بود، نشان می‌دهد.</p>', '2016-10-03 00:00:00', 4, 235, 'https://images.blinkist.io/images/books/57ee366d216b4e00033a7d80/1_1/470.jpg', '/en/books/shoe-dog-en/purchase', 'سگ-کفش', '2023-01-26 20:19:47.712625', '2023-01-26 20:19:47.712625', NULL, 'Shoe Dog');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (819, 'کار جدید شجاع', 'آیا برای اختراع مجدد سازمان خود آماده هستید؟', 'آیا برای اختراع مجدد سازمان خود آماده هستید؟', 24, 9, 'book', 't', '<p><em>کار جدید شجاع</em> (2019) یک راهنمای غیرعادی برای تغییرات سازمانی است. به جای تجویز تکنیک هایی برای تغییر شرکت، پیشنهادات و مطالعات موردی را ارائه می دهد. کار واقعی تحول به عهده شماست.</p>', '2019-11-18 00:00:00', 5, 105, 'https://images.blinkist.io/images/books/5dceca5b6cee070007fe3291/1_1/470.jpg', '/en/books/brave-new-work-en/purchase', 'کار-جدید-شجاع', '2023-01-26 20:19:54.611423', '2023-01-26 20:19:54.611423', NULL, 'Brave New Work');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (820, 'ساخت برای تغییر', 'ایجاد انقلاب در تعامل با مشتری از طریق نوآوری دیجیتال مستمر', 'ایجاد انقلاب در تعامل با مشتری از طریق نوآوری دیجیتال مستمر', 12, 5, 'book', 't', '<p><em>ساخت برای تغییر </em>(2014) روابط متغیر بین مشتریان و کسب و کارها را روشن می کند. با توضیح عملکرد درونی وفاداری مشتری و برجسته کردن اهمیت پیشرفت‌های فناوری جدید، این پلک‌ها کسب‌وکارها را با ابزارهای مورد نیاز برای ایجاد یک پایگاه مشتری قدرتمند و پایدار تجهیز می‌کنند.</p>', '2016-01-06 00:00:00', 4, 20, 'https://images.blinkist.io/images/books/568ae29bde78c00007000000/1_1/470.jpg', '/en/books/build-for-change-en/purchase', 'ساخت-برای-تغییر', '2023-01-26 20:20:01.875534', '2023-01-26 20:20:01.875534', NULL, 'Build For Change');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (821, 'موفقیت در استخدام', 'چگونه مدیران عامل رویایی برای بهترین استعداد رقابت می کنند', 'چگونه مدیران عامل رویایی برای بهترین استعداد رقابت می کنند', 26, 8, 'book', 't', '<p><em>موفقیت در استخدام </em>(2020) به شما کمک می کند بهترین افراد را برای کسب و کار خود بیابید و حفظ کنید. این راهنمای بی‌معنی، تکنیک‌های لازم برای تماس، ارتباط با استعدادهای مناسب برای رسیدن به اهداف فعلی و آینده‌تان را توضیح می‌دهد.</p>', '2020-07-02 00:00:00', 4, 64, 'https://images.blinkist.io/images/books/5ef5fa566cee0700067fcf92/1_1/470.jpg', '/en/books/hiring-success-en/purchase', 'موفقیت-در-استخدام', '2023-01-26 20:20:08.827366', '2023-01-26 20:20:08.827366', NULL, 'Hiring Success');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (822, 'تسلط بر رهبری', 'یک چارچوب یکپارچه برای عملکرد موفقیت آمیز و نتایج کسب و کار فوق العاده', 'یک چارچوب یکپارچه برای عملکرد موفقیت آمیز و نتایج کسب و کار فوق العاده', 18, 6, 'book', 't', '<p><em>تسلط بر رهبری </em>(2015) ارتباط بین توسعه شخصی و رهبری عالی را بررسی می کند. این ذهنیت مورد نیاز برای رهبری مؤثر را آشکار می‌کند، و بررسی می‌کند که چگونه بینش‌های اسطوره‌شناسی کلاسیک می‌تواند به مدیران کمک کند تا رهبر قهرمان درونی خود را پیدا کنند. </p>', '2021-07-15 00:00:00', 4, 79, 'https://images.blinkist.io/images/books/60ec1fab6cee070007752b3e/1_1/470.jpg', '/en/books/mastering-leadership-en/purchase', 'تسلط-بر-رهبری', '2023-01-26 20:20:16.513425', '2023-01-26 20:20:16.513425', NULL, 'Mastering Leadership');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (823, 'چهار ثانیه', 'همیشه باید عادت های ضد تولید را کنار بگذارید و به نتایجی که می خواهید برسید', 'همیشه باید عادت های ضد تولید را کنار بگذارید و به نتایجی که می خواهید برسید', 15, 6, 'book', 't', '<p><em>چهار ثانیه</em> (2015) مثال های دقیقی از چگونگی خلاص شدن از شر عادت های خودزنی در محل کار، خانه و روابطتان ارائه می دهد. مکث چهار ثانیه ای به کاهش سرعت واکنش های عجولانه و ناراحت کننده کمک می کند و اولین گام برای بازنگری در نحوه برقراری ارتباط با دیگران و دریافت بازخورد از آنها است. اگر ابتدا یک نفس بکشید واقعاً می توانید برای هر چیزی آماده باشید.</p>', '2015-05-29 00:00:00', 4, 89, 'https://images.blinkist.io/images/books/55641bf86265620007000000/1_1/470.jpg', '/en/books/four-seconds-en/purchase', 'چهار-ثانیه', '2023-01-26 20:20:21.384119', '2023-01-26 20:20:21.384119', NULL, 'Four Seconds');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (824, 'استقبال از ناخواسته', 'زندگی با صمیم قلب در دنیایی با دل شکسته', 'زندگی با صمیم قلب در دنیایی با دل شکسته', 18, 6, 'book', 't', '<p><em>Welcoming the Unwelcome</em>(2019) مقدمه ای عملی برای برخی از اصول بودیسم ارائه می دهد که می تواند به مردم کمک کند تا بهتر با چالش های زندگی روزمره کنار بیایند. نویسنده Pema Chödrön بینش مفیدی را در مورد آموزه های بودایی و همچنین شیوه ها و تکنیک هایی که هر کسی می تواند استفاده کند ارائه می دهد.</p>', '2019-12-06 00:00:00', 5, 106, 'https://images.blinkist.io/images/books/5de8d2c36cee070008b7245d/1_1/470.jpg', '/en/books/welcoming-the-unwelcome-en/purchase', 'استقبال-از-ناخواسته', '2023-01-26 20:20:28.610325', '2023-01-26 20:20:28.610325', NULL, 'Welcoming the Unwelcome');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (825, 'رو به جلو', 'کشف حضور و هدف خداوند در فردای خود', 'کشف حضور و هدف خداوند در فردای خود', 21, 7, 'book', 't', '<p><em>به جلو </em>(2020) به شما نشان می دهد که چگونه می توانید در حال حاضر خدا را در زندگی خود کشف کنید. معلم کتاب مقدس دیوید ارمیا توضیح می دهد که چگونه می توان از حکمت کتاب مقدس برای دستیابی به تمرکز و هدف استفاده کرد و به شما کمک کرد تا به موفقیت و تحقق شخصی بزرگ برسید.</p>', '2020-12-24 00:00:00', 5, 71, 'https://images.blinkist.io/images/books/5fdc5b176cee070006eabc9c/1_1/470.jpg', '/en/books/forward-en/purchase', 'رو-به-جلو', '2023-01-26 20:20:35.635968', '2023-01-26 20:20:35.635968', NULL, 'Forward');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (826, 'اصول موفقیت', 'چگونه از جایی که هستید به جایی که می خواهید برسید', 'چگونه از جایی که هستید به جایی که می خواهید برسید', 19, 9, 'book', 't', '<p><em>اصول موفقیت</em> اصول عملی و دقیقی را ارائه می‌دهد تا به هر کسی کمک کند زندگی موفق‌تری داشته باشد. نویسنده جک کانفیلد از داستان‌ها و حکایات افرادی استفاده می‌کند که به اهداف بلندپروازانه دست یافته‌اند و موفقیت بسیار بالا را تجربه کرده‌اند.</p>', '2014-10-03 00:00:00', 5, 169, 'https://images.blinkist.io/images/books/542bfd7a62383100082c0000/1_1/470.jpg', '/en/books/the-success-principles-en/purchase', 'اصول-موفقیت', '2023-01-26 20:20:40.531758', '2023-01-26 20:20:40.531758', NULL, 'The Success Principles');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (827, 'افکار بدون متفکر', 'روان درمانی از دیدگاه بودایی', 'روان درمانی از دیدگاه بودایی', 17, 7, 'book', 't', '<p><em>افکار بدون متفکر</em> (1995) اصول بنیادی سنت بودایی را از طریق دریچه روانکاوی توصیف می کند. این پلک‌ها توضیح می‌دهند که چگونه مدیتیشن و تمرکز حواس می‌تواند ذهن را آرام کند، رنج را کاهش دهد و بیماری‌های روانی را التیام بخشد.</p>', '2017-06-06 00:00:00', 4, 102, 'https://images.blinkist.io/images/books/59363dbdb238e100051fdaec/1_1/470.jpg', '/en/books/thoughts-without-a-thinker-en/purchase', 'افکار-بدون-متفکر', '2023-01-26 20:20:48.012813', '2023-01-26 20:20:48.012813', NULL, 'Thoughts Without a Thinker');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (828, 'اضطراری', 'این کتاب زندگی شما را نجات خواهد داد', 'این کتاب زندگی شما را نجات خواهد داد', 18, 9, 'book', 't', '<p><em>اورژانس</em> داستان شخصی تبدیل نویسنده از یک شهرنشین درمانده به یک بقای مستقل است. این یک گزارش دست اول از نحوه آموزش برای خودمختاری کامل در صورت فروپاشی جامعه است.</p>', '2014-05-06 09:29:41', 3, 12, 'https://images.blinkist.io/images/books/5369fb166631340007220000/1_1/470.jpg', '/en/books/emergency-en/purchase', 'اضطراری', '2023-01-26 20:20:54.881786', '2023-01-26 20:20:54.881786', NULL, 'Emergency');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (829, 'هلاکراسی', 'سیستم مدیریت جدید که مدیریت را دوباره تعریف می کند', 'سیستم مدیریت جدید که مدیریت را دوباره تعریف می کند', 22, 9, 'book', 't', '<p><em>Holacracy</em> (2015) یک سیستم مدیریت انقلابی جدید را توصیف می کند که توسط برخی از آینده نگرترین شرکت های امروزی مانند Zappos و Medium حمایت می شود. این پلک ها توضیح می دهند که چگونه اقتدار و مسئولیت در یک هولاکراسی تعریف و توزیع می شود - و چرا این سیستم منجر به سازمانی موثرتر و پویاتر می شود.</p>', '2015-06-12 00:00:00', 4, 35, 'https://images.blinkist.io/images/books/5577d6313162620007010000/1_1/470.jpg', '/en/books/holacracy-en/purchase', 'هلاکراسی', '2023-01-26 20:21:02.235332', '2023-01-26 20:21:02.235332', NULL, 'Holacracy');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (830, 'تغییرات بازی', 'آنچه رهبران، مبتکران و ماوریک ها برای پیروزی در زندگی انجام می دهند', 'آنچه رهبران، مبتکران و ماوریک ها برای پیروزی در زندگی انجام می دهند', 30, 10, 'book', 't', '<p><em>تغییرکنندگان بازی</em> (2018) خرد 450 رهبر تجاری بسیار موفق، دانشمند، ورزشکار، نویسنده، هنرمندان، روزنامه‌نگار و سایر افراد را در صدر زمینه‌های کاری خود جمع‌آوری می‌کند. سپس این حکمت را با درک زیست شناسی و روانشناسی انسان ترکیب می کند. نتیجه؟ کتاب راهنمای گسترده و کاربردی برای موفقیت.</p>', '2019-02-15 00:00:00', 4, 192, 'https://images.blinkist.io/images/books/5c63d3296cee0700078d6f19/1_1/470.jpg', '/en/books/game-changers-en/purchase', 'تغییرات-بازی', '2023-01-26 20:21:07.895555', '2023-01-26 20:21:07.895555', NULL, 'Game Changers');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (831, 'واقعی شدن', 'راه هوشمندتر، سریعتر و آسانتر برای ساختن یک برنامه وب موفق', 'راه هوشمندتر، سریعتر و آسانتر برای ساختن یک برنامه وب موفق', 18, 8, 'book', 't', '<p><em>Getting Real</em> (2011) یک تفکیک جامع از چالش های پیش روی کارآفرینان در بازار برنامه های کاربردی وب ارائه می دهد. این پلک‌ها مملو از حقایق سخت و توصیه‌های محکم در مورد کارهایی است که باید هنگام راه‌اندازی کسب‌وکار اپلیکیشن جدید خود انجام دهید و چه کاری انجام ندهید. </p>', '2016-12-30 00:00:00', 5, 32, 'https://images.blinkist.io/images/books/585071463e967900044cb0e0/1_1/470.jpg', '/en/books/getting-real-en/purchase', 'واقعی-شدن', '2023-01-26 20:21:14.932197', '2023-01-26 20:21:14.932197', NULL, 'Getting Real');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (832, 'والدین خارج از خطوط', 'قوانین را فراموش کنید، به خرد خود ضربه بزنید و با فرزندتان ارتباط برقرار کنید', 'قوانین را فراموش کنید، به خرد خود ضربه بزنید و با فرزندتان ارتباط برقرار کنید', 20, 7, 'book', 't', '<p><em>والدین خارج از خط </em>(2020) یک راهنمای ضروری برای فراموش کردن همه چیزهایی است که تا به حال در مورد فرزندپروری آموخته اید - و در عوض از شهود خود پیروی کنید. به عنوان والدین، ما ناامن و ناامید هستیم تا آن را درست کنیم. بنابراین ما به جستجوی کتاب یا کارگاه مناسبی می‌پردازیم که به ما بگوید چگونه فرزندانمان را تربیت کنیم. اما حقیقتاً هیچ روش کاملی وجود ندارد. تنها کاری که می توانیم انجام دهیم این است که یاد بگیریم چگونه خودمان و فرزندانمان را هماهنگ کنیم و به موقعیت های خاص با انعطاف و مهربانی پاسخ دهیم.</p>', '2021-01-03 00:00:00', 5, 139, 'https://images.blinkist.io/images/books/5fdc5d346cee070007f858a4/1_1/470.jpg', '/en/books/parenting-outside-the-lines-en/purchase', 'والدین-خارج-از-خطوط', '2023-01-26 20:21:22.156184', '2023-01-26 20:21:22.156184', NULL, 'Parenting Outside the Lines');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (833, 'گاو بنفش', 'کسب و کار خود را با قابل توجه بودن متحول کنید', 'کسب و کار خود را با قابل توجه بودن متحول کنید', 16, 7, 'book', 't', '<p>این پلک‌ها توضیح می‌دهند که چرا بازاریابی سنتی دیگر جواب نمی‌دهد، و چرا برای موفقیت باید <em>گاوهای بنفش</em> بسازید، محصولات و خدمات قابل‌توجهی که از بین مردم متمایز هستند. آنها همچنین توضیح می دهند که چگونه می توانید پس از پیدا کردن گاو بنفش خود به بازار هدف خود برسید.</p>', '2014-04-01 08:11:53', 4, 245, 'https://images.blinkist.io/images/books/533ae8093430340007210000/1_1/470.jpg', '/en/books/purple-cow-en/purchase', 'گاو-بنفش', '2023-01-26 20:21:27.213233', '2023-01-26 20:21:27.213233', NULL, 'Purple Cow');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (834, 'اثبات رد', 'چگونه ترس را شکست دادم و در 100 روز رد شدن شکست ناپذیر شدم', 'چگونه ترس را شکست دادم و در 100 روز رد شدن شکست ناپذیر شدم', 16, 8, 'book', 't', '<p><em>اثبات رد </em>(2015) به شما می آموزد که چگونه با رد شدن رو در رو روبرو شوید و از سفر خودسازی، چه در داخل و چه در خارج استقبال کنید. با استفاده از "جعبه ابزار رد کردن" جیانگ، به درک بهتری از رد شدن خواهید رسید، نحوه شنیدن بیشتر "بله" را یاد خواهید گرفت و مزایای رد شدن را کشف خواهید کرد.</p>', '2015-07-02 00:00:00', 4, 43, 'https://images.blinkist.io/images/books/5592601765613800078e0000/1_1/470.jpg', '/en/books/rejection-proof-en/purchase', 'اثبات-رد', '2023-01-26 20:21:34.39338', '2023-01-26 20:21:34.39338', NULL, 'Rejection Proof');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (835, 'سوئیچ قدرت', 'چگونه علم جدید والدین مبتنی بر قدرت می تواند به شکوفایی کودک و نوجوان شما کمک کند', 'چگونه علم جدید والدین مبتنی بر قدرت می تواند به شکوفایی کودک و نوجوان شما کمک کند', 21, 8, 'book', 't', '<p><em>سوئیچ قدرت </em>(2017) نشان می‌دهد که چگونه والدین می‌توانند از فرزندپروری مبتنی بر قدرت در سناریوهای خانوادگی استفاده کنند. این نشان می دهد که اگر والدین به جای انتقاد بیش از حد، تمرکز خود را بر نقاط قوت فرزندشان بگذارند، کودکان می توانند شکوفا و شکوفا شوند.</p>', '2019-01-08 00:00:00', 4, 29, 'https://images.blinkist.io/images/books/5c31da206cee070008e7b0eb/1_1/470.jpg', '/en/books/the-strength-switch-en/purchase', 'سوئیچ-قدرت', '2023-01-26 20:21:41.465453', '2023-01-26 20:21:41.465453', NULL, 'The Strength Switch');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (836, 'صبح معجزه', 'راز نه چندان آشکاری که تضمین شده است زندگی شما را متحول کند (قبل از ساعت 8 صبح)', 'راز نه چندان آشکاری که تضمین شده است زندگی شما را متحول کند (قبل از ساعت 8 صبح)', 20, 10, 'book', 't', '<p>در <em> معجزه</em> <em>معجزه</em> <em>صبح </em> (2012)، هال الرود تکنیک هایی را توضیح می دهد که او را پس از یک تصادف رانندگی تقریباً مرگبار پشت سر گذاشت. . الرود متوجه شد که کلید یک زندگی موفق و رضایت بخش این است که هر روز مقداری زمان برای بهبود خودمان اختصاص دهیم. او شش گام مهمی را که می‌توانیم هر روز صبح برداریم، توضیح می‌دهد تا به ما کمک کند روزهایمان را شروع کنیم و ما را به خوبی در مسیر زندگی کامل قرار دهیم.</p>', '2014-09-02 00:00:00', 5, 730, 'https://images.blinkist.io/images/books/5404836e3663330008310000/1_1/470.jpg', '/en/books/the-miracle-morning-en/purchase', 'صبح-معجزه', '2023-01-26 20:21:46.729785', '2023-01-26 20:21:46.729785', NULL, 'The Miracle Morning');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (837, 'اقتصاد عضویت', 'کاربران فوق‌العاده خود را بیابید، بر تراکنش‌های ابدی مسلط شوید و درآمدهای تکراری ایجاد کنید', 'کاربران فوق‌العاده خود را بیابید، بر تراکنش‌های ابدی مسلط شوید و درآمدهای تکراری ایجاد کنید', 18, 8, 'book', 't', '<p>امروز، مالکیت تمام شده است. روند مصرف کننده نشان می دهد که مصرف کنندگان بیشتر و بیشتر خواهان دسترسی موقت هستند، نه مالکیت دائمی. و در این چشم‌انداز در حال تغییر، کسب‌وکارهای عضویت‌محور پادشاه هستند. <em>اقتصاد عضویت</em> (2015) استراتژی‌ها و تاکتیک‌های کلیدی را بر اساس مثال‌های واقعی برای ایجاد موفقیت‌آمیز یک سازمان عضویت بیان می‌کند.</p>', '2015-09-24 00:00:00', 4, 34, 'https://images.blinkist.io/images/books/55ffff58615cd100090000b6/1_1/470.jpg', '/en/books/the-membership-economy-en/purchase', 'اقتصاد-عضویت', '2023-01-26 20:21:54.071104', '2023-01-26 20:21:54.071104', NULL, 'The Membership Economy');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (838, 'حافظه نامحدود', 'نحوه استفاده از استراتژی های یادگیری پیشرفته برای یادگیری سریعتر، بیشتر به خاطر سپردن و بهره وری بیشتر', 'نحوه استفاده از استراتژی های یادگیری پیشرفته برای یادگیری سریعتر، بیشتر به خاطر سپردن و بهره وری بیشتر', 14, 6, 'book', 't', '<p><em>حافظه نامحدود</em> (2014) تکنیک های حافظه را توضیح می دهد که به شما کمک می کند هر اطلاعاتی را که می خواهید به خاطر بسپارید و حفظ کنید. این پلک ها به شما نشان می دهد که چگونه اطلاعات را در ذهن خود سازماندهی و ذخیره کنید تا هرگز آن را فراموش نکنید.</p>', '2017-08-23 00:00:00', 4, 317, 'https://images.blinkist.io/images/books/59982502b238e10005eeaecb/1_1/470.jpg', '/en/books/unlimited-memory-en/purchase', 'حافظه-نامحدود', '2023-01-26 20:22:01.419686', '2023-01-26 20:22:01.419686', NULL, 'Unlimited Memory');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (839, 'قدرت فشار', 'چرا فشار مشکل نیست، راه حل است', 'چرا فشار مشکل نیست، راه حل است', 24, 8, 'book', 't', '<p><em>قدرت فشار </em> (2021) به دنیای فشار در همه اشکال آن و نحوه برخورد افراد با عملکرد بالا با آن نگاهی عمیق می‌اندازد. با توجه به الگوهای هر دو لحظه اوج فشار و فشار در مسافت طولانی، مجموعه ای کاربردی از ابزارها را در اختیار شما قرار می دهد تا شروع به استفاده از فشار به نفع خود کنید.</p>', '2021-11-01 00:00:00', 5, 247, 'https://images.blinkist.io/images/books/6176b73f6cee0700087ad61e/1_1/470.jpg', '/en/books/the-power-of-pressure-en/purchase', 'قدرت-فشار', '2023-01-26 20:22:08.241572', '2023-01-26 20:22:08.241572', NULL, 'The Power of Pressure');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (840, 'بیوگرافی قبل از خواب: مادام کوری', 'یک زندگینامه', 'یک زندگینامه', 26, 6, 'book', 't', '<p>دو جایزه نوبل، پیشرفت‌های علمی درخشان، زیان‌های غم‌انگیز، کار خستگی‌ناپذیر در بیمارستان‌های جنگ جهانی اول: ماری کوری زندگی پرحادثه‌ای داشت. در این بیوگرافی قبل از خواب، ما داستان ماری کوری را بیان می کنیم و شما را با زن پشت افسانه های متعدد آشنا می کنیم.</p>
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (841, 'فرال', 'بازگرداندن زمین، دریا و زندگی انسان', 'بازگرداندن زمین، دریا و زندگی انسان', 24, 9, 'book', 't', '<p><em>Feral </em>(2013) هم تحلیل و هم مانیفست است. نویسنده جورج مونبیوت به آنچه مردم در زندگی روزمره خود فاقد آن هستند می پردازد: طبیعت و بیابان واقعی. این کتاب استدلال می‌کند که مناطق خاصی باید به طبیعت واگذار شود و دوباره وحشی شود، و مزایای انجام این کار - هم برای سیاره و هم برای مردم - به زودی به دنبال خواهد داشت.</p>', '2018-05-03 00:00:00', 4, 17, 'https://images.blinkist.io/images/books/5ae6ea5cb238e10007f78971/1_1/470.jpg', '/en/books/feral-en/purchase', 'فرال', '2023-01-26 20:33:45.1235', '2023-01-26 20:33:45.1235', NULL, 'Feral');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (842, 'قلب معامله', 'چگونه مانند یک مغول املاک و مستغلات سرمایه گذاری و مذاکره کنیم', 'چگونه مانند یک مغول املاک و مستغلات سرمایه گذاری و مذاکره کنیم', 14, 6, 'book', 't', '<p><em>The Heart of the Deal </em>(2017) راهنمایی های بلندپروازانه ای را به نمایندگان املاک و مستغلات در مورد چگونگی ایجاد آن در صنعت ارائه می دهد. این مجموعه مملو از نمونه هایی از تجربیات نویسنده است تا شما نیز بتوانید نحوه جلب نظر مشتریان و دستیابی به سطوح مشابهی از موفقیت را بیاموزید.</p>
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (843, 'زندگی مخفی ضمایر', 'آنچه کلمات ما درباره ما می گویند', 'آنچه کلمات ما درباره ما می گویند', 19, 8, 'book', 't', '<p><em>زندگی مخفی ضمایر</em> (2011) نوری را بر زبان روزمره که ما بندرت به آن توجه می کنیم می تاباند و راه هایی را که در آن به عنوان پنجره ای به شخصیت و ارتباطات اجتماعی ما عمل می کند، آشکار می کند. </p>', '2016-03-07 00:00:00', 4, 22, 'https://images.blinkist.io/images/books/56dd866324b39b0007000001/1_1/470.jpg', '/en/books/the-secret-life-of-pronouns-en/purchase', 'زندگی-مخفی-ضمایر', '2023-01-26 20:33:59.283467', '2023-01-26 20:33:59.283467', NULL, 'The Secret Life of Pronouns');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (844, 'دختران و جنسیت', 'پیمایش در منظره جدید پیچیده', 'پیمایش در منظره جدید پیچیده', 15, 6, 'book', 't', '<p><em>دختران و سکس </em>(2016) منظره‌ای از سکس و تمایلات جنسی را که امروزه دختران و زنان جوان تلاش می‌کنند تا از آن عبور کنند، روشن می‌کند. بسیاری از زنان در حال توسعه تلاش می‌کنند تا تعادل مناسبی بین آن‌هایی که جامعه می‌خواهند و آن‌هایی که می‌خواهند خودشان باشند پیدا کنند. این کار آسانی نیست، اما ما می‌توانیم با تغییر شیوه صحبت درباره جنسیت و توانمندسازی دختران برای شکل دادن به آینده‌شان، آن را آسان‌تر کنیم.</p>', '2017-05-31 00:00:00', 4, 54, 'https://images.blinkist.io/images/books/59293c1fb238e10006000677/1_1/470.jpg', '/en/books/girls-and-sex-en/purchase', 'دختران-و-جنسیت', '2023-01-26 20:34:04.283166', '2023-01-26 20:34:04.283166', NULL, 'Girls &amp; Sex');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (845, 'شکم گندم', 'گندم را از دست بدهید، وزن خود را کم کنید و مسیر بازگشت به سلامتی را پیدا کنید', 'گندم را از دست بدهید، وزن خود را کم کنید و مسیر بازگشت به سلامتی را پیدا کنید', 18, 7, 'book', 't', '<p><em>شکم گندم</em> (2011) به بررسی ویرانی هایی می پردازد که محصولات مدرن گندم بر سلامت روحی و جسمی ما وارد می کنند. این نشان می دهد که چگونه استفاده از گندم در طول سال ها تغییر کرده است، و همچنین چگونه رژیم غذایی ما به طور چشمگیری تغییر کرده است. نویسنده، دکتر ویلیام دیویس، از آخرین تحقیقات علمی برای پیشبرد استدلال حذف گندم از رژیم غذایی شما برای همیشه استفاده می کند. </p>', '2019-12-16 00:00:00', 4, 106, 'https://images.blinkist.io/images/books/5df3847b6cee0700079265a3/1_1/470.jpg', '/en/books/wheat-belly-en/purchase', 'شکم-گندم', '2023-01-26 20:34:12.132714', '2023-01-26 20:34:12.132714', NULL, 'Wheat Belly');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (846, 'انگشت شست ویولونیست', 'و دیگر داستان های گمشده عشق، جنگ و نبوغ، که توسط کد ژنتیکی ما نوشته شده است', 'و دیگر داستان های گمشده عشق، جنگ و نبوغ، که توسط کد ژنتیکی ما نوشته شده است', 16, 10, 'book', 'f', '<p><em></em> <em>ویلونیست</em> <em>شست</em> یک کاوش در DNA، مارپیچ دوگانه خود زندگی است. چشمک‌های زیر اکتشافات علمی را نشان می‌دهند که ما را به درک DNA و نقش اصلی آن در پیدایش حیات بر روی زمین هدایت کردند.</p>', '2014-05-06 09:40:31', 5, 15, 'https://images.blinkist.io/images/books/5369fdc66631340007430000/1_1/470.jpg', '/en/books/the-violinists-thumb-en/purchase', 'انگشت-شست-ویولونیست', '2023-01-26 20:34:17.428252', '2023-01-26 20:34:17.428252', NULL, 'The Violinist’s Thumb');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (847, 'دختر، صورتت را بشور', 'از باور دروغ هایی که در مورد اینکه چه کسی هستید دست بردارید، تا بتوانید به آن چیزی تبدیل شوید که قرار بود باشید', 'از باور دروغ هایی که در مورد اینکه چه کسی هستید دست بردارید، تا بتوانید به آن چیزی تبدیل شوید که قرار بود باشید', 19, 7, 'book', 't', '<p><em>دختر، صورتت را بشور </em>(2018) درباره یک حقیقت مهم است - تو و به تنهایی مسئول زندگی و خوشبختی خودت هستی. این یک راهنمای توانمند و گاهی چالش برانگیز برای داشتن یک زندگی شاد، سازنده و جاه طلبانه است.</p>', '2018-09-19 00:00:00', 4, 101, 'https://images.blinkist.io/images/books/5b9bc78f862c43000758bba7/1_1/470.jpg', '/en/books/girl-wash-your-face-en/purchase', 'دختر،-صورتت-را-بشور', '2023-01-26 20:34:25.058727', '2023-01-26 20:34:25.058727', NULL, 'Girl, Wash Your Face');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (848, 'عادت موفقیت', 'از آرزو کردن دست بردارید، انجام دادن را شروع کنید و فرمان زندگی خود را به دست بگیرید', 'از آرزو کردن دست بردارید، انجام دادن را شروع کنید و فرمان زندگی خود را به دست بگیرید', 13, 6, 'book', 't', '<p>رویاهای بزرگی که هرگز محقق نمی شوند؟ لیست طولانی از کارهایی که باید انجام دهید، اما نیمی از صبح را در فیس بوک گذراندید؟ <em>عادت موفقیت</em> (2015) تمام چیزی است که برای روشن کردن یک موشک استعاری زیر صندلی میز خود نیاز دارید. با مکاشفه‌های زمینی و دستورالعمل‌های ساده‌اش، به راحتی می‌توان آن را در زندگی‌ای که در حال حاضر دارید به کار برد و شما را به زندگی که می‌خواهید نزدیک‌تر کرد.</p>', '2015-09-16 00:00:00', 4, 77, 'https://images.blinkist.io/images/books/55f6e27d29161a00090000a2/1_1/470.jpg', '/en/books/the-achievement-habit-en/purchase', 'عادت-موفقیت', '2023-01-26 20:34:32.399504', '2023-01-26 20:34:32.399504', NULL, 'The Achievement Habit');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (849, 'خرد کردن آن در آپارتمان ها و املاک تجاری', 'چگونه یک سرمایه گذار کوچک می تواند آن را بزرگ کند', 'چگونه یک سرمایه گذار کوچک می تواند آن را بزرگ کند', 15, 6, 'book', 't', '<p><em>در هم شکستن آن در آپارتمان‌ها و املاک تجاری</em> (2017) نگاهی به اسرار موفقیت خارق‌العاده نویسنده در بازار املاک و مستغلات دارد. این کتاب سرشار از توصیه‌های قابل اجرا برای سرمایه‌گذاران احتمالی است، همچنین به مالکان مستقر کمک می‌کند تا از املاک و مستغلات خود نهایت استفاده را ببرند. در طول مسیر، نویسنده نمونه‌هایی از سال‌ها کار در این صنعت را به اشتراک می‌گذارد.</p>', '2018-09-05 00:00:00', 4, 116, 'https://images.blinkist.io/images/books/5b8c256fb238e100073e7b4f/1_1/470.jpg', '/en/books/crushing-it-in-apartments-and-commercial-real-estate-en/purchase', 'خرد-کردن-آن-در-آپارتمان-ها-و-املاک-تجاری', '2023-01-26 20:34:39.79767', '2023-01-26 20:34:39.79767', NULL, 'Crushing It in Apartments and Commercial Real Estate');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (850, 'روش ویم هاف', 'پتانسیل کامل انسانی خود را فعال کنید', 'پتانسیل کامل انسانی خود را فعال کنید', 26, 8, 'book', 't', '<p><em>روش ویم هاف </em>(2020) معتقد است که ما می‌توانیم با استفاده از روش‌های ویم هوف بر هر چیزی، از بیماری و افسردگی گرفته تا شرایط آب و هوایی شدید، غلبه کنیم. بر اساس سه ستون - سرما، تنفس و طرز فکر - <em>روش ویم هوف </em>به دنبال کمک به شما برای فعال کردن پتانسیل کامل خود است.</p>', '2020-11-23 00:00:00', 5, 192, 'https://images.blinkist.io/images/books/5fb797796cee07000726735c/1_1/470.jpg', '/en/books/the-wim-hof-method-en/purchase', 'روش-ویم-هاف', '2023-01-26 20:34:47.026665', '2023-01-26 20:34:47.026665', NULL, 'The Wim Hof Method');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (851, 'پول هوشمند بچه های باهوش', 'پرورش نسل بعدی برای برنده شدن با پول', 'پرورش نسل بعدی برای برنده شدن با پول', 15, 4, 'book', 't', '<p><em>کودکان هوشمند با پول هوشمند</em> (2014) والدین - یا هر کسی که به تربیت فرزندان کمک می کند - در آموزش به آن بچه ها برای باهوش شدن مالی راهنمایی می کند. اصول اولیه مانند رابطه بین کار و پول را مرور کنید و توصیه های عملی برای آموزش به کودکان نوپا در دوران نوجوانی برای کسب اعتماد با پول پیدا کنید.</p>', '2023-01-16 00:00:00', NULL, 6, 'https://images.blinkist.io/images/books/63be960de8fd3c00080b410f/1_1/470.jpg', '/en/books/smart-money-smart-kids-en/purchase', 'پول-هوشمند-بچه-های-باهوش', '2023-01-26 20:34:54.142138', '2023-01-26 20:34:54.142138', NULL, 'Smart Money Smart Kids');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (852, 'انقلاب اپی ژنتیک', 'چگونه زیست شناسی مدرن درک ما از ژنتیک، بیماری و وراثت را بازنویسی می کند', 'چگونه زیست شناسی مدرن درک ما از ژنتیک، بیماری و وراثت را بازنویسی می کند', 24, 4, 'book', 't', '<p><em>انقلاب اپی ژنتیک </em>(2011) مروری بر حوزه پیشرفته اپی ژنتیک است - با نگاهی به عوامل مختلفی که با ژن‌های شما تعامل دارند و نحوه رفتار آنها را تغییر می‌دهند تا شما را بسازند. شما. از سلامت روان گرفته تا چاقی، روش‌های جذاب و اغلب غیرمنتظره‌ای را بررسی می‌کند که اپی ژنتیک می‌تواند بر زندگی و سلامت ما تأثیر بگذارد.</p>', '2021-10-03 00:00:00', 5, 293, 'https://images.blinkist.io/images/books/6155c1e16cee070008e6cb00/1_1/470.jpg', '/en/books/the-epigenetics-revolution-en/purchase', 'انقلاب-اپی-ژنتیک', '2023-01-26 20:35:01.0639', '2023-01-26 20:35:01.0639', NULL, 'The Epigenetics Revolution');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (853, 'شما را در اینترنت ببینم', 'با بازاریابی دیجیتال کسب و کار کوچک خود را بسازید', 'با بازاریابی دیجیتال کسب و کار کوچک خود را بسازید', 21, 7, 'book', 't', '<p><em>See You on the Internet</em>(2020) یک راهنمای ساده برای پیمایش در دنیای بازاریابی دیجیتال است. اگر تا به حال از فکر ساختن یک وب‌سایت یا اجرای کمپین بازاریابی ایمیلی احساس ترس کرده‌اید، <em>شما را در اینترنت می‌بینم</em> شما را در برنامه‌ریزی، اجرا، و اندازه‌گیری تلاش‌های بازاریابی دیجیتال شما راهنمایی می‌کند. p>', '2020-07-31 00:00:00', 4, 102, 'https://images.blinkist.io/images/books/5f2013fa6cee07000751e971/1_1/470.jpg', '/en/books/see-you-on-the-internet-en/purchase', 'شما-را-در-اینترنت-ببینم', '2023-01-26 20:35:08.504592', '2023-01-26 20:35:08.504592', NULL, 'See You on the Internet');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (854, 'شن به بزرگ', 'چگونه استقامت، اشتیاق، و شهامت شما را از حالت عادی به حالت خارق العاده می برد', 'چگونه استقامت، اشتیاق، و شهامت شما را از حالت عادی به حالت خارق العاده می برد', 13, 5, 'book', 't', '<p>بسیاری از مردم استعداد دارند، اما تعداد کمی در حرفه انتخابی خود ستاره می شوند. در <em>Grit to Great</em> (2015)، دو زن در صدر مشاغل تبلیغاتی راهنمای خود را برای توسعه انعطاف‌پذیری و پیوند سخت ارائه می‌دهند که به موفقیت شما کمک می‌کند.</p>', '2015-12-25 00:00:00', 4, 103, 'https://images.blinkist.io/images/books/56786a880bac9b0007000024/1_1/470.jpg', '/en/books/grit-to-great-en/purchase', 'شن-به-بزرگ', '2023-01-26 20:35:15.716446', '2023-01-26 20:35:15.716446', NULL, 'Grit to Great');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (855, 'هزینه ای که برای کالج می پردازید', 'نقشه راه کاملاً جدید برای بزرگترین تصمیم مالی که خانواده شما تا به حال می گیرد', 'نقشه راه کاملاً جدید برای بزرگترین تصمیم مالی که خانواده شما تا به حال می گیرد', 20, 6, 'book', 't', '<p><em>هزینه ای که برای کالج می پردازید </em>(2021) یک فروشگاه تک مرحله ای برای همه چیزهایی است که باید در مورد انتخاب کالج و تامین مالی تحصیل خود بدانید. با بررسی مربیگری، کمک‌های مالی و حقوق فارغ‌التحصیلان، دنیایی اغلب گیج‌کننده را روشن می‌کند، با هدف اطمینان از اینکه تصمیمات مهم دانش‌آموزان آگاهانه هستند.</p>', '2021-05-01 00:00:00', 4, 29, 'https://images.blinkist.io/images/books/60827f6b6cee0700076a0fe6/1_1/470.jpg', '/en/books/the-price-you-pay-for-college-en/purchase', 'هزینه-ای-که-برای-کالج-می-پردازید', '2023-01-26 20:35:21.21692', '2023-01-26 20:35:21.21692', NULL, 'The Price You Pay for College');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (856, 'کتاب شادی', 'شادی پایدار در دنیایی در حال تغییر', 'شادی پایدار در دنیایی در حال تغییر', 21, 9, 'book', 't', '<p><em>کتاب شادی</em> (2016) راهنمای روشنگری برای داشتن یک زندگی عاری از غم، استرس و رنج است. این پلک زدن ها مملو از روش های عملی برای ایجاد شادی برای خود و دیگران و در عین حال غلبه بر موانعی است که اغلب افراد را از یافتن خوشبختی روی زمین باز می دارد.</p>', '2017-10-12 00:00:00', 5, 213, 'https://images.blinkist.io/images/books/59db8b59b238e10005594b1c/1_1/470.jpg', '/en/books/the-book-of-joy-en/purchase', 'کتاب-شادی', '2023-01-26 20:35:28.418399', '2023-01-26 20:35:28.418399', NULL, 'The Book of Joy');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (857, 'سمت راست تاریخ', 'چگونه عقل و هدف اخلاقی غرب را بزرگ کرد؟', 'چگونه عقل و هدف اخلاقی غرب را بزرگ کرد؟', 20, 7, 'book', 't', '<p><em>سمت راست تاریخ </em>(2019) هم دفاع مهیجی از تمدن غرب است و هم راهنمای مفیدی برای تفکر مذهبی و فلسفی که زیربنای آن است. این کتاب قرن‌های فکری را بررسی می‌کند که به ساختن و حفظ غرب کمک کرده است، و به دنبال درک و از بین بردن تهدیدهای اخیر این طرز تفکر است.</p>', '2019-05-03 00:00:00', 4, 146, 'https://images.blinkist.io/images/books/5cc82bf76cee0700082212c4/1_1/470.jpg', '/en/books/the-right-side-of-history-en/purchase', 'سمت-راست-تاریخ', '2023-01-26 20:35:35.345329', '2023-01-26 20:35:35.345329', NULL, 'The Right Side of History');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (858, 'تیم های رویایی', 'با هم کار کنید بدون اینکه از هم بپاشید', 'با هم کار کنید بدون اینکه از هم بپاشید', 25, 8, 'book', 't', '<p><em>تیم‌های رویایی </em> (2018) آنچه را که برای یک تیم واقعاً عالی می‌سازد، برجسته می‌کند. مملو از مثال‌های عجیب و غریب و جالب از زمان‌ها و صنایع مختلف، Snow علم پشت تیم‌های رویایی را نشان می‌دهد، چه چیزی آنها را فوق‌العاده کرده است و چگونه می‌توان استراتژی‌های آن‌ها را امروز به کار برد.</p>', '2018-09-11 00:00:00', 4, 41, 'https://images.blinkist.io/images/books/5b9408b0862c430007fdf649/1_1/470.jpg', '/en/books/dream-teams-en/purchase', 'تیم-های-رویایی', '2023-01-26 20:35:42.529726', '2023-01-26 20:35:42.529726', NULL, 'Dream Teams');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (859, 'شکوفایی خود را تصور کنید', 'پول هوشمند حرکت می کند تا چشم انداز شما را به واقعیت تبدیل کند', 'پول هوشمند حرکت می کند تا چشم انداز شما را به واقعیت تبدیل کند', 14, 6, 'book', 't', '<p><em>شکوفایی خود را تصویر کنید</em> (2015) راهنمای تعریف و دستیابی به زندگی ایده آل شما است. این پلک ها تکنیک های ارزشمندی برای تجسم موفقیت، تعیین اهداف و کنار گذاشتن پول لازم برای دستیابی به هر چیزی که می خواهید به خواننده آموزش می دهد.</p>', '2015-09-10 00:00:00', 4, 46, 'https://images.blinkist.io/images/books/55ed56df11ad1a00090000dd/1_1/470.jpg', '/en/books/picture-your-prosperity-en/purchase', 'شکوفایی-خود-را-تصور-کنید', '2023-01-26 20:35:49.463579', '2023-01-26 20:35:49.463579', NULL, 'Picture Your Prosperity');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (867, 'عشق برنامه قاتل است', 'چگونه در کسب و کار برنده شویم و بر دوستان تأثیر بگذاریم', 'چگونه در کسب و کار برنده شویم و بر دوستان تأثیر بگذاریم', 19, 8, 'book', 't', '<p><em>Love Is the Killer App</em> (2003) راهنمای موفقیت شغلی در زمان‌های در حال تغییر است. راز؟ عشق و شفقت. این پلک‌ها توضیح می‌دهند که چگونه عشق – در مفهوم تجاری – می‌تواند به شما کمک کند در حین دستیابی به اهدافتان در زندگی و کار، باهوش، سخاوتمند و دلسوز باشید.</p>', '2015-10-21 00:00:00', 5, 21, 'https://images.blinkist.io/images/books/5623e13832646600073e0000/1_1/470.jpg', '/en/books/love-is-the-killer-app-en/purchase', 'عشق-برنامه-قاتل-است', '2023-01-26 20:36:42.761681', '2023-01-26 20:36:42.761681', NULL, 'Love is the Killer App');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (860, 'فیلمنامه را ورق بزنید', 'وادار کردن مردم به این فکر کنند که ایده شما ایده آنهاست', 'وادار کردن مردم به این فکر کنند که ایده شما ایده آنهاست', 18, 6, 'book', 't', '<p><em>Flip The Script </em>(2019) به شما کمک می کند تا بازی فروش و مذاکره خود را ارتقا دهید. فروش تماماً در مورد هنر متقاعد کردن است، اما همه ما می دانیم که هیچ کس دوست ندارد احساس کند که دستکاری شده است. برای اینکه ایده یا محصول خود را در دنیای امروز بفروشید، خریداران شما باید احساس کنند که این تصمیم را بر اساس شرایط خود می‌گیرند. Flip The Script تکنیک هایی را ارائه می دهد که به شما این امکان را می دهد که به طور نامحسوس هر کسی را متقاعد کنید که ایده شما درست است.</p>', '2020-03-16 00:00:00', 4, 85, 'https://images.blinkist.io/images/books/5e6b7a986cee070007dabd3c/1_1/470.jpg', '/en/books/flip-the-script-en/purchase', 'فیلمنامه-را-ورق-بزنید', '2023-01-26 20:35:54.630338', '2023-01-26 20:35:54.630338', NULL, 'Flip The Script');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (861, 'دیلی رواقی', '366 مراقبه در مورد خرد، استقامت و هنر زندگی', '366 مراقبه در مورد خرد، استقامت و هنر زندگی', 33, 12, 'book', 't', '<p><em>The Daily Stoic</em> (2016) مجموعه‌ای از مراقبه‌های روزانه است که از خرد فیلسوفان رواقی که در امپراتوری روم زندگی می‌کردند، استخراج شده است. نوشته‌های امپراطور مارکوس اورلیوس، سنکا نمایشنامه‌نویس و اپیکتتوس، فیلسوف برده‌شده، همگی مطالب قابل تأملی را برای نویسندگان فراهم می‌کنند تا آن‌ها را تازه‌سازی و تازه‌سازی کنند. این پلک زدن ها باعث تقویت تفکر خود می شود و در عین حال خواننده را تشویق می کند که برای آرامش و خود زندگی ارزش قائل شود.</p>', '2018-08-17 00:00:00', 5, 628, 'https://images.blinkist.io/images/books/5b73f3aab238e100073cda34/1_1/470.jpg', '/en/books/the-daily-stoic-en/purchase', 'دیلی-رواقی', '2023-01-26 20:36:01.345077', '2023-01-26 20:36:01.345077', NULL, 'The Daily Stoic');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (862, 'هنر ساده زیستی', '100 تمرین روزانه از یک راهب ذن ژاپنی برای یک عمر آرامش و شادی', '100 تمرین روزانه از یک راهب ذن ژاپنی برای یک عمر آرامش و شادی', 20, 7, 'book', 't', '<p><em>هنر ساده زیستن</em> (2019) عادات کوچکی را بررسی می‌کند که تغییر بزرگی در زندگی روزمره شما ایجاد می‌کنند. آموزه های ذن بودیسم را توضیح می دهد و چگونگی به کارگیری آنها را نشان می دهد. مملو از نکات مفید، این راهنمای شما برای یک زندگی آرام تر است. </p>', '2020-02-11 00:00:00', 5, 446, 'https://images.blinkist.io/images/books/5e3f7f616cee070006b5f8f3/1_1/470.jpg', '/en/books/the-art-of-simple-living-en/purchase', 'هنر-ساده-زیستی', '2023-01-26 20:36:09.203473', '2023-01-26 20:36:09.203473', NULL, 'The Art of Simple Living');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (863, 'کد جهانی', 'چگونه فرهنگ جدید ارزش های جهانی در حال تغییر شکل دادن به تجارت و بازاریابی است؟', 'چگونه فرهنگ جدید ارزش های جهانی در حال تغییر شکل دادن به تجارت و بازاریابی است؟', 15, 6, 'book', 't', '<p><em>رمز جهانی </em>(2015) درباره یک پدیده اخیر در سراسر جهان است: ناخودآگاهی جهانی یا کدی که حاوی سیستم جدیدی از ارزش ها، باورها و اصول است. این کد توسط Global Tribe، یک گروه بسیار متحرک و بین فرهنگی از افرادی که روندها را تنظیم می کنند، وضعیت موجود را متزلزل می کنند و به جمعیت هدف برندهای لوکس جهانی تبدیل می شوند، تشکیل و به اشتراک گذاشته شده است.</p>', '2016-10-27 00:00:00', 3, 12, 'https://images.blinkist.io/images/books/580b7073d4d2ce0003dd2493/1_1/470.jpg', '/en/books/the-global-code-en/purchase', 'کد-جهانی', '2023-01-26 20:36:16.172896', '2023-01-26 20:36:16.172896', NULL, 'The Global Code');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (864, 'تک تک وظایف', 'یک کار را در یک زمان انجام دهید', 'یک کار را در یک زمان انجام دهید', 15, 7, 'book', 't', '<p><em>Singletasking </em>(2015) به برخی از افسانه های رایج در مورد چندوظیفه و بهره وری می پردازد. پر از توصیه‌ها و ترفندهای عملی برای کمک به شما در استفاده بیشتر از روزتان، <em>تک تکلیف </em>به وضوح نشان می‌دهد که چگونه تمرکز همه جانبه بر روی یک کار منجر به یک زندگی کارآمدتر و در نهایت شادتر می‌شود.</p>', '2016-01-28 00:00:00', 4, 132, 'https://images.blinkist.io/images/books/56a6aef0fb7e870007000025/1_1/470.jpg', '/en/books/singletasking-en/purchase', 'تک-تک-وظایف', '2023-01-26 20:36:23.363235', '2023-01-26 20:36:23.363235', NULL, 'Singletasking');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (865, 'CRM متصل', 'اجرای یک استراتژی کسب و کار مبتنی بر داده و مشتری محور', 'اجرای یک استراتژی کسب و کار مبتنی بر داده و مشتری محور', 12, 5, 'book', 't', '<p><em>CRM متصل</em> (2014) کلمات کلیدی مانند «ابر»، «شخصی‌سازی» و «داده بزرگ» را کاهش می‌دهد تا به ما نشان دهد چگونه از اطلاعات برای ارائه خدمات به مشتریان در دنیای جدید و شجاع آنلاین استفاده کنیم. کسب و کار.</p>', '2016-06-23 00:00:00', 4, 32, 'https://images.blinkist.io/images/books/576182ee0beabd0003161b41/1_1/470.jpg', '/en/books/connected-crm-en/purchase', 'CRM-متصل', '2023-01-26 20:36:30.270727', '2023-01-26 20:36:30.270727', NULL, 'Connected CRM');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (866, 'در حال افزایش قوی', 'همه زمین می خورند، اما نکته کلیدی این است که بدانید چگونه دوباره بلند شوید', 'همه زمین می خورند، اما نکته کلیدی این است که بدانید چگونه دوباره بلند شوید', 20, 9, 'book', 't', '<p><em>Rising Strong </em>(2015) راهنمای شما برای بلند کردن خود و پاک کردن گرد و غبار پس از شکست - و قوی‌تر شدن، شجاع‌تر و مهربان‌تر شدن به دلیل آن است. چه رویای کارآفرین بودن یا حفظ یک رابطه عاشقانه را داشته باشید، این پلک ها سه مرحله حیاتی برای مقابله با هر مبارزه ای را در اختیار شما قرار می دهند.</p>', '2015-11-18 00:00:00', 4, 332, 'https://images.blinkist.io/images/books/5649fc176634310007390000/1_1/470.jpg', '/en/books/rising-strong-en/purchase', 'در-حال-افزایش-قوی', '2023-01-26 20:36:35.820754', '2023-01-26 20:36:35.820754', NULL, 'Rising Strong');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (868, 'مغناطیس استعداد', 'چگونه یک محل کار بسازیم که بهترین ها را جذب و حفظ کند', 'چگونه یک محل کار بسازیم که بهترین ها را جذب و حفظ کند', 10, 4, 'book', 't', '<p>در <em>مغناطیس استعدادها</em>، نویسنده روبرتا چینسکی ماتوسون به شما نشان می‌دهد که چگونه محل کار خود را به محیطی تبدیل کنید که استعدادهای برتر را مانند آهنربا جذب کند. این کتاب توصیه های عملی در مورد چگونگی ایجاد استراتژی برای جلوتر ماندن از رقبا با شناسایی اینکه چگونه فناوری در حال تحول و نسل جدیدی از کارگران کسب و کار را در قرن بیست و یکم تغییر داده اند، ارائه می دهد.</p>', '2015-03-19 00:00:00', 4, 17, 'https://images.blinkist.io/images/books/55062d3d666365000a870000/1_1/470.jpg', '/en/books/talent-magnetism-en/purchase', 'مغناطیس-استعداد', '2023-01-26 20:36:50.241327', '2023-01-26 20:36:50.241327', NULL, 'Talent Magnetism');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (869, 'گزینه B', 'مواجهه با ناملایمات، ایجاد انعطاف پذیری و یافتن شادی', 'مواجهه با ناملایمات، ایجاد انعطاف پذیری و یافتن شادی', 14, 6, 'book', 't', '<p><em>گزینه B</em> (2017) بر اساس تجربیات شخصی شریل سندبرگ است که پس از از دست دادن همسرش، در یک دوره ماتم عمیق فرو رفت. با این حال، داستان شریل داستان ناامیدی نیست. این یکی از پشتکار است، و بیرون آمدن از یک تجربه وحشتناک حتی قوی تر از قبل. کشف کنید که شریل در مورد روند سوگواری چه آموخته است و چگونه توانست شادی خود را بازیابد، معنای زندگی - و مرگ - را بیابد و ادامه دهد.</p>', '2017-05-18 00:00:00', 4, 72, 'https://images.blinkist.io/images/books/5919b4dfb238e1000736bc26/1_1/470.jpg', '/en/books/option-b-en/purchase', 'گزینه-B', '2023-01-26 20:36:57.515096', '2023-01-26 20:36:57.515096', NULL, 'Option B');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (870, 'بهتر شوید', '15 روش اثبات شده برای ایجاد روابط موثر در محل کار', '15 روش اثبات شده برای ایجاد روابط موثر در محل کار', 20, 10, 'book', 't', '<p><em>بهتر شوید </em>(2017) بینش ارزشمندی در مورد چگونگی ایجاد و حفظ روابط بهتر در محل کار ارائه می دهد. با انبوهی از توصیه‌های عملی که می‌توانید امروز عمل کنید، این راهنمای مفیدی است، هم برای تقویت روابط مهم و هم برای اجتناب از همه دام‌های معمولی که می‌توانند باعث ایجاد مشکل در محل کار شوند.</p>', '2021-04-29 09:09:26.731', 4, 42, 'https://images.blinkist.io/images/books/608a764b6cee070007228924/1_1/470.jpg', '/en/books/get-better-en/purchase', 'بهتر-شوید', '2023-01-26 20:37:04.374588', '2023-01-26 20:37:04.374588', NULL, 'Get Better');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (871, 'One Up در وال استریت', 'چگونه از آنچه قبلاً می دانید برای کسب درآمد در بازار استفاده کنید', 'چگونه از آنچه قبلاً می دانید برای کسب درآمد در بازار استفاده کنید', 23, 8, 'book', 't', '<p><em>One Up On Wall Street </em>(2000) راهنمای آماتوری برای سرمایه گذاری موفقیت آمیز در بازار سهام است. از اینکه چرا سرمایه‌گذاران حرفه‌ای هنگام انتخاب سهام کوتاه می‌آیند تا نحوه شناسایی چشم‌اندازهای سرمایه‌گذاری عالی، <em>One Up On Wall Street</em> توصیه‌های ساده و در عین حال مؤثری را برای دستیابی به موفقیت مالی به اشتراک می‌گذارد. </p>', '2021-07-22 00:00:00', 4, 212, 'https://images.blinkist.io/images/books/60f147506cee070007faab7b/1_1/470.jpg', '/en/books/one-up-on-wall-street-en/purchase', 'One-Up-در-وال-استریت', '2023-01-26 20:37:11.56105', '2023-01-26 20:37:11.56105', NULL, 'One Up On Wall Street');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (872, 'صحبت با بزها', 'لحظاتی که به یاد می آورید و داستان هایی که هرگز نشنیده اید', 'لحظاتی که به یاد می آورید و داستان هایی که هرگز نشنیده اید', 24, 8, 'book', 't', '<p><em>Talking to GOATs </em>(2020) داستان‌های درونی و لحظات به یاد ماندنی را از برخی از بزرگترین ورزشکاران و رویدادهای ورزشی که جهان تاکنون دیده است را بازگو می‌کند. این بینش ها از کارنامه چهار دهه ای مصاحبه کننده مشهور ورزشی، جیم گری، استخراج شده است.</p>', '2021-01-24 00:00:00', 4, 34, 'https://images.blinkist.io/images/books/6007fb1e6cee0700085e6593/1_1/470.jpg', '/en/books/talking-to-goats-en/purchase', 'صحبت-با-بزها', '2023-01-26 20:37:18.784446', '2023-01-26 20:37:18.784446', NULL, 'Talking to GOATs');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (873, 'هنر امکان', 'تغییر زندگی حرفه ای و شخصی', 'تغییر زندگی حرفه ای و شخصی', 25, 8, 'book', 't', '<p><em>هنر امکان </em>(2000) مجموعه ای از استراتژی ها را ارائه می دهد که امکان را به هر جنبه ای از زندگی شما دعوت می کند. با اجرای این استراتژی‌ها، می‌توانید خلاقیت خود را تقویت کنید، مهارت‌های حل مسئله خود را تقویت کنید و روابط خود را با دیگران عمیق‌تر کنید.</p>', '2021-10-23 00:00:00', 5, 112, 'https://images.blinkist.io/images/books/61702e3c6cee0700087aa4fc/1_1/470.jpg', '/en/books/the-art-of-possibility-en/purchase', 'هنر-امکان', '2023-01-26 20:37:25.994024', '2023-01-26 20:37:25.994024', NULL, 'The Art of Possibility');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (874, 'قوانین محتوا', 'چگونه بلاگ های قاتل، پادکست ها، ویدئوها، کتاب های الکترونیکی، وبینارها (و موارد دیگر) ایجاد کنیم که مشتریان را درگیر کند و کسب و کار شما را شعله ور کند', 'چگونه بلاگ های قاتل، پادکست ها، ویدئوها، کتاب های الکترونیکی، وبینارها (و موارد دیگر) ایجاد کنیم که مشتریان را درگیر کند و کسب و کار شما را شعله ور کند', 18, 7, 'book', 't', '<p><em>قوانین محتوا </em>(2012) راهنمای انتشار محتوا است که به شما در اجرای استراتژی‌های موثر و پایدار کمک می‌کند. صرف نظر از اینکه شما یک مبتدی در شبکه های اجتماعی هستید یا یک حرفه ای حرفه ای با وب، این پلک ها شما را از طریق ابزارهای محتوای مبتنی بر وب و سایت های رسانه های اجتماعی راهنمایی می کنند، در حالی که نکات مفیدی در زمینه محتوایی در این راه ارائه می دهند. </p>', '2015-07-31 00:00:00', 4, 63, 'https://images.blinkist.io/images/books/55b7ec3f3235390007c80000/1_1/470.jpg', '/en/books/content-rules-en/purchase', 'قوانین-محتوا', '2023-01-26 20:37:33.585502', '2023-01-26 20:37:33.585502', NULL, 'Content Rules');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (875, 'حرکت کوچک، تغییر بزرگ', 'استفاده از رزولوشن های کوچک برای تغییر دائمی زندگی شما', 'استفاده از رزولوشن های کوچک برای تغییر دائمی زندگی شما', 19, 8, 'book', 't', '<p>در <em>کوچک</em> <em>حرکت،</em> <em>بزرگ</em> <em>تغییر،</em> خواهید آموخت که چرا ما اغلب در انجام آن ناکام هستیم تغییراتی را در زندگی مان دنبال کنیم که به شدت می خواهیم ایجاد کنیم. نویسنده کارولین آرنولد توضیح می‌دهد که ما کوتاهی می‌کنیم زیرا تصمیمات خود را به گونه‌ای طراحی نمی‌کنیم که واقعاً قابل دستیابی باشد. درعوض، ما باید بر روی «ریز رزولوشن‌ها» تمرکز کنیم - تعهدات کوچک و آسان برای حفظ که منجر به تغییرات بزرگ می‌شود.</p>', '2014-09-02 00:00:00', 5, 24, 'https://images.blinkist.io/images/books/5406e9ec3933310008a40000/1_1/470.jpg', '/en/books/small-move-big-change-en/purchase', 'حرکت-کوچک،-تغییر-بزرگ', '2023-01-26 20:37:40.651425', '2023-01-26 20:37:40.651425', NULL, 'Small Move, Big Change');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (876, 'قانون عدم تماس', 'راهنمای زنده ماندن از جدایی با احترام به خود', 'راهنمای زنده ماندن از جدایی با احترام به خود', 23, 8, 'book', 't', '<p><em>قانون عدم تماس</em>راهنمای سختگیرانه ای است که اگر احساس می کنید از جدایی کتک خورده اید، به نظر نمی رسد که دوست قبلی خود را رها کنید یا در یک رابطه گیر کرده اید، به آن نیاز دارید. دوباره رابطه غیرعادی در اینجا نکات و ترفندهایی در مورد چگونگی پیدا کردن فاصله عاطفی، تمرکز مجدد بر روی خود و در نهایت رسیدن به بسته شدن پیدا خواهید کرد.</p>', '2020-10-31 00:00:00', 4, 66, 'https://images.blinkist.io/images/books/5f9a94ae6cee07000676b162/1_1/470.jpg', '/en/books/the-no-contact-rule-en/purchase', 'قانون-عدم-تماس', '2023-01-26 20:37:47.376104', '2023-01-26 20:37:47.376104', NULL, 'The No Contact Rule');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (877, 'نمای طولانی', 'استراتژی های شغلی برای شروع قوی، رسیدن به سطح بالا و دورتر رفتن', 'استراتژی های شغلی برای شروع قوی، رسیدن به سطح بالا و دورتر رفتن', 16, 7, 'book', 't', '<p><em>The Long View</em> (2016) راهنمای محکمی برای ایجاد یک شغل پایدار و معنادار است. با جمع آوری یک مجموعه مهارت مفید، توسعه یک شبکه شخصی دینامیت و مهمتر از همه، یافتن یک تعادل خوب بین کار و زندگی، خود را در مسیر درست قرار دهید. کار نباید بدبخت باشد و برای یافتن شغلی که هم از نظر عاطفی و هم از نظر مالی سودآور باشد، دیر نیست.</p>', '2017-09-13 00:00:00', 4, 90, 'https://images.blinkist.io/images/books/59b8474db238e10005c1fb21/1_1/470.jpg', '/en/books/the-long-view-en/purchase', 'نمای-طولانی', '2023-01-26 20:37:54.557268', '2023-01-26 20:37:54.557268', NULL, 'The Long View');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (878, 'یک مخاطب یک', 'بازپس گیری خلاقیت به خاطر خودش', 'بازپس گیری خلاقیت به خاطر خودش', 23, 8, 'book', 't', '<p><em>A Audience of One </em>(2018) خوانندگان را به سیری عمیق در زندگی روزمره ذهن خلاق می برد. نویسنده سرینیواس رائو از تجربه زندگی خود و همچنین خرد فراوانی از دیگر هنرمندان و خلاقان استفاده می کند تا توضیح دهد که چرا شادی یا رضایت کمی در زندگی ای که در تلاش برای راضی کردن دیگران است وجود دارد. رائو شواهد علمی و عملی ارائه می‌دهد که نشان می‌دهد چگونه یک زندگی خلاقانه با ارزش، به جای انتظارات دیگران، به پذیرش فرآیند و وفادار بودن به دیدگاه خود بستگی دارد.</p>', '2018-08-08 00:00:00', 4, 68, 'https://images.blinkist.io/images/books/5b672760b238e100078c2eef/1_1/470.jpg', '/en/books/an-audience-of-one-en/purchase', 'یک-مخاطب-یک', '2023-01-26 20:38:02.101951', '2023-01-26 20:38:02.101951', NULL, 'An Audience of One');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (879, 'ما', 'گذر از من و شما برای ایجاد یک رابطه عاشقانه تر', 'گذر از من و شما برای ایجاد یک رابطه عاشقانه تر', 20, 4, 'book', 't', '<p><em>ما </em>(2022) برای هر کسی است که رابطه عاشقانه‌اش به امتیازدهی و جنگ قدرت تبدیل شده است. مجموعه‌ای از مهارت‌های مبتنی بر علم را ارائه می‌دهد که با مثال‌های غنی و دقیق نشان داده شده است تا به شما و شریک زندگی‌تان کمک کند تا فردگرایی سمی <em>و</em> رابطه‌تان را درمان کنید. </p>', '2022-10-14 00:00:00', 5, 287, 'https://images.blinkist.io/images/books/63456f326cee0700087c48ae/1_1/470.jpg', '/en/books/us-en/purchase', 'ما', '2023-01-26 20:38:09.377363', '2023-01-26 20:38:09.377363', NULL, 'Us');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (880, 'SuperFreakonomics', 'خنک سازی جهانی، روسپی های وطن پرست و چرا بمب گذاران انتحاری باید بیمه عمر بخرند', 'خنک سازی جهانی، روسپی های وطن پرست و چرا بمب گذاران انتحاری باید بیمه عمر بخرند', 19, 8, 'book', 't', '<p><em>SuperFreakonomics</em> (2009) توضیح می دهد که چرا تفکر مانند یک اقتصاددان می تواند به ما در درک دنیای مدرن خود کمک کند. این چشمک‌ها اصول کلیدی اقتصادی و اهمیت جمع‌آوری داده‌ها با داستان‌های رنگارنگ تاریخ بشر را نشان می‌دهد و راه‌حل‌های شگفت‌انگیزی برای مشکلات جهانی که امروز با آن مواجه هستیم ارائه می‌دهد.</p>', '2015-08-20 00:00:00', 4, 67, 'https://images.blinkist.io/images/books/55d1d519688f6700090000ab/1_1/470.jpg', '/en/books/superfreakonomics-en/purchase', 'SuperFreakonomics', '2023-01-26 20:38:16.968959', '2023-01-26 20:38:16.968959', NULL, 'SuperFreakonomics');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (881, 'تلاش برای امتحان نکردن', 'چین باستان، علم مدرن و قدرت خودانگیختگی', 'چین باستان، علم مدرن و قدرت خودانگیختگی', 13, 6, 'book', 't', '<p><em>تلاش نکردن</em> (2014) راهنمای شما به فلسفه چین باستان است. این پلک‌ها توضیح می‌دهند که چرا باید اجازه دهید زندگی بدون اینکه مجبور به اتفاق افتادن اتفاق بیفتد، خود را به شما نشان دهد. آنها همچنین راه هایی را برای داشتن یک زندگی کم استرس معرفی می کنند.</p>', '2017-03-09 00:00:00', 4, 53, 'https://images.blinkist.io/images/books/58bea6168eba16000496c7f5/1_1/470.jpg', '/en/books/trying-not-to-try-en/purchase', 'تلاش-برای-امتحان-نکردن', '2023-01-26 20:38:24.383659', '2023-01-26 20:38:24.383659', NULL, 'Trying Not to Try');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (883, 'تغییر پول هزاره', 'از بدهی فرار کنید، برای آینده خود پس انداز کنید و اکنون زندگی غنی داشته باشید', 'از بدهی فرار کنید، برای آینده خود پس انداز کنید و اکنون زندگی غنی داشته باشید', 25, 8, 'book', 't', '<p><em>Mallennial Money Makeover</em> (2019) خواندنی ضروری برای هزاره‌هایی است که می‌خواهند بر امور مالی خود مسلط شوند. در این راهنمای قابل دسترس برای مدیریت پول، کانر ریچاردسون راه‌حل‌های مالی ساده‌ای را برای چالش‌های اقتصادی منحصربه‌فرد و عوامل استرس‌زا که بسیاری از هزاره‌ها تجربه می‌کنند، ارائه می‌دهد.</p>', '2019-11-08 00:00:00', 4, 109, 'https://images.blinkist.io/images/books/5dc197516cee0700075419ba/1_1/470.jpg', '/en/books/millennial-money-makeover-en/purchase', 'تغییر-پول-هزاره', '2023-01-26 20:38:39.193706', '2023-01-26 20:38:39.193706', NULL, 'Millennial Money Makeover');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (884, 'دیر شکوفه ها', 'قدرت صبر در جهانی که وسواس زودهنگامی دارد', 'قدرت صبر در جهانی که وسواس زودهنگامی دارد', 23, 8, 'book', 't', '<p><em>Late Bloomers</em>(2019) به بررسی این موضوع می پردازد که چرا جامعه مدرن وسواس زیادی به دستاوردهای اولیه دارد. اثرات مخربی را که یک آموزش پربار می‌تواند بر سلامت روان جوانان داشته باشد و همچنین چگونگی تأثیر خانواده، همسالان و رسانه‌ها بر مسیرهای زندگی ما را توضیح می‌دهد. ریچ کارلگارد، نویسنده، با تکیه بر تجربیات خود، پیشنهاد می‌کند که شکوفا شدن در مراحل بعدی زندگی چیزی نیست که باید از آن خجالت کشید، بلکه چیزی است که باید از آن تجلیل کرد.</p>', '2020-10-10 00:00:00', 5, 220, 'https://images.blinkist.io/images/books/5f7ec9086cee07000613ac6b/1_1/470.jpg', '/en/books/late-bloomers-en/purchase', 'دیر-شکوفه-ها', '2023-01-26 20:38:44.635625', '2023-01-26 20:38:44.635625', NULL, 'Late Bloomers');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (885, 'اخلاق', 'یک مقدمه بسیار کوتاه', 'یک مقدمه بسیار کوتاه', 25, 3, 'book', 't', '<p><em>اخلاق: یک مقدمه بسیار کوتاه </em>(2001) دقیقاً همان کاری را انجام می‌دهد که روی قلع می‌گوید: این یک مقدمه روشن و قابل دسترس برای شاخه‌ای از فلسفه است که به نحوه رفتار ما با یکدیگر مربوط می‌شود. سایمون بلکبرن با بررسی چالش‌ها و نظریه‌های کلیدی در اخلاق، اصطلاحات فلسفی را کوتاه می‌کند تا بتوانیم یاد بگیریم که به وضوح درباره اینکه چگونه باید رفتار کنیم فکر کنیم.</p>', '2022-02-13 00:00:00', 4, 268, 'https://images.blinkist.io/images/books/620691826cee070008e3db1e/1_1/470.jpg', '/en/books/ethics-en/purchase', 'اخلاق', '2023-01-26 20:38:51.784624', '2023-01-26 20:38:51.784624', NULL, 'Ethics');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (886, 'ایده تا اجرا', 'چگونه همه چیز را در کسب و کار خود بهینه سازی، خودکارسازی و برون سپاری کنید', 'چگونه همه چیز را در کسب و کار خود بهینه سازی، خودکارسازی و برون سپاری کنید', 20, 9, 'book', 't', '<p>بر اساس داستان واقعی دو دوست که یک شبه شرکتی را با سرمایه گذاری نقدی صفر تاسیس کردند و آن را در سال بعد ایجاد کردند، <em>Idea to Execution</em> (2016) درباره چالش های روزمره ای است که کارآفرینان با آن مواجه می شوند. راه اندازی یک استارت آپ این پلک‌ها مراحل موفقیت را به شما نشان می‌دهند، از طراحی یک طرح کسب‌وکار تا قرار دادن ابزارهایی که اعداد عملکرد شرکت شما را بهینه می‌کنند.</p>', '2016-11-11 00:00:00', 4, 63, 'https://images.blinkist.io/images/books/5822fa2adf93d80004cc8ac1/1_1/470.jpg', '/en/books/idea-to-execution-en/purchase', 'ایده-تا-اجرا', '2023-01-26 20:38:58.777121', '2023-01-26 20:38:58.777121', NULL, 'Idea to Execution');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (887, 'زندگی به روش 80/20', 'کمتر کار کنید، کمتر نگران باشید، بیشتر موفق شوید، بیشتر لذت ببرید', 'کمتر کار کنید، کمتر نگران باشید، بیشتر موفق شوید، بیشتر لذت ببرید', 13, 6, 'book', 't', '<p><em>زندگی به روش 80/20</em> به شما نشان می دهد که چگونه از اصل 80/20 استفاده کنید، یک مفهوم اقتصادی که بیان می کند که اکثریت قریب به اتفاق نتایج حاصل از نسبت کوچکی از تلاش، در زندگی شخصی شماست. . نویسنده با توصیه‌های عمل‌گرایانه و قابل اجرا در مورد چگونگی خلق بیشتر با کمتر، خواننده را تشویق می‌کند تا روی آنچه مهم است تمرکز کند و خارج از چارچوب فکر کند.</p>', '2015-02-19 00:00:00', 4, 125, 'https://images.blinkist.io/images/books/54e3d412303764000a820000/1_1/470.jpg', '/en/books/living-the-80-slash-20-way-en/purchase', 'زندگی-به-روش-80/20', '2023-01-26 20:39:07.991304', '2023-01-26 20:39:07.991304', NULL, 'Living the 80/20 Way');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (888, 'سرمایه گذار پابرهنه', 'تنها راهنمای پولی که همیشه به آن نیاز دارید', 'تنها راهنمای پولی که همیشه به آن نیاز دارید', 10, 5, 'book', 't', '<p><em>سرمایه گذار پابرهنه</em> (2017) به شما دستورالعمل های روشنی در مورد اینکه چگونه بهتر پول خود را مدیریت کنید، ارائه می دهد. قوانین ساده ای وجود دارد که باید از آنها پیروی کنید که امنیت مالی شما را تضمین می کند و به شما کمک می کند تا هرگونه وابستگی به اعتبار را قطع کنید.</p>', '2018-06-01 00:00:00', 4, 99, 'https://images.blinkist.io/images/books/5b0c1ad3b238e1000740dc80/1_1/470.jpg', '/en/books/the-barefoot-investor-en/purchase', 'سرمایه-گذار-پابرهنه', '2023-01-26 20:39:14.813901', '2023-01-26 20:39:14.813901', NULL, 'The Barefoot Investor');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (889, 'خاموش کردن ساعت', 'در حین انجام کارهای بیشتر، کمتر مشغول شوید', 'در حین انجام کارهای بیشتر، کمتر مشغول شوید', 20, 7, 'book', 't', '<p><em>Off the Clock</em> (2018) توصیه‌های عملی در مورد چگونگی استفاده بیشتر از زمانتان، از آزاد کردن برنامه‌های شلوغ تا دستیابی به کارهای بیشتر در فواصل زمانی کوتاه‌تر، ارائه می‌کند. واندرکام با استفاده از حکایات شخصی و همچنین بینش های علمی، به بررسی این موضوع می پردازد که چرا برخی از ما احساس می کنیم تمام وقت دنیا را داریم، در حالی که دیگران احساس می کنند که زمان از میان انگشتانشان می لغزد.</p>
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (890, 'Wired to Care', 'چگونه شرکت ها با ایجاد همدلی گسترده پیشرفت می کنند', 'چگونه شرکت ها با ایجاد همدلی گسترده پیشرفت می کنند', 10, 5, 'book', 'f', '<p>به‌نظر می‌رسد کسب‌وکارهای مدرن بیشتر به انبوهی از داده‌ها و گزارش‌های روند متکی هستند تا نیازها و خواسته‌های مشتریان واقعی. <em>Wired to Care </em> نشان می دهد که چگونه کسب و کارها می توانند از همدلی برای ایجاد ارتباط با مشتریان و کشف آنچه واقعاً می خواهند استفاده کنند. در سطح کل شرکت، این نوع همدلی منجر به رشد می‌شود و می‌تواند یک تغییر بازی برای تک تک کارکنان باشد.</p>', '2015-01-27 00:00:00', NULL, 9, 'https://images.blinkist.io/images/books/54c64e9a3732390009280000/1_1/470.jpg', '/en/books/wired-to-care-en/purchase', 'Wired-to-Care', '2023-01-26 20:39:27.411847', '2023-01-26 20:39:27.411847', NULL, 'Wired to Care');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (891, 'داستان زندگی من', 'داستان الهام بخش پیروزی هلن کلر بر نابینایی و ناشنوایی', 'داستان الهام بخش پیروزی هلن کلر بر نابینایی و ناشنوایی', 10, 4, 'book', 't', '<p><em>داستان زندگی من </em> (1903) وقایع سالهای اولیه هلن کلر، زن جوانی است که در سنین جوانی ناشنوا و نابینا شد. این کتاب به بررسی چالش‌هایی می‌پردازد که او در دوران کودکی دارای معلولیت با آن روبرو بود و افراد شگفت‌انگیزی را که در این راه به او کمک کردند، معرفی می‌کند.</p>', '2018-02-01 00:00:00', 5, 25, 'https://images.blinkist.io/images/books/5a6f0c58b238e10009732059/1_1/470.jpg', '/en/books/the-story-of-my-life-en/purchase', 'داستان-زندگی-من', '2023-01-26 20:39:34.691472', '2023-01-26 20:39:34.691472', NULL, 'The Story of My Life');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (892, 'کتاب', 'در مورد تابو علیه دانستن اینکه شما کی هستید', 'در مورد تابو علیه دانستن اینکه شما کی هستید', 17, 7, 'book', 't', '<p><em>کتاب</em> (1966) درباره سوالات بزرگ زندگی است. معنی همه اش چیست؟ ما واقعاً کجای جهان هستی هستیم؟ نویسنده آلن واتس خواننده را در سفری اکتشافی راهنمایی می‌کند که مفروضات رایج در مورد آنچه در زندگی مهم است، نحوه عملکرد جهان و ماهیت خدا زیر سوال می‌رود.</p>', '2018-03-16 00:00:00', 5, 187, 'https://images.blinkist.io/images/books/5aa7bb21b238e10007af44aa/1_1/470.jpg', '/en/books/the-book-en/purchase', 'کتاب', '2023-01-26 20:39:41.544041', '2023-01-26 20:39:41.544041', NULL, 'The Book');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (893, 'انسان خود را به کار بیاورید', '10 روش مطمئن برای طراحی یک محل کار که برای مردم خوب است، برای تجارت عالی است و فقط می تواند دنیا را تغییر دهد', '10 روش مطمئن برای طراحی یک محل کار که برای مردم خوب است، برای تجارت عالی است و فقط می تواند دنیا را تغییر دهد', 23, 7, 'book', 't', '<p><em>Bring Your Human to Work</em>(2018) به بررسی این موضوع می پردازد که چگونه سازمان ها می توانند ارتباط انسانی را در مرکز تجارت خود قرار دهند. این مزایا، هم مالی و هم اجتماعی، تشویق ارتباطات بهتر و روابط عمیق‌تر بین همکاران را تشریح می‌کند. </p>', '2021-05-11 00:00:00', 4, 74, 'https://images.blinkist.io/images/books/60953acc6cee0700077e6424/1_1/470.jpg', '/en/books/bring-your-human-to-work-en/purchase', 'انسان-خود-را-به-کار-بیاورید', '2023-01-26 20:39:48.532301', '2023-01-26 20:39:48.532301', NULL, 'Bring Your Human to Work');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (894, 'کتاب فیلد اسکرام', 'یک کلاس کارشناسی ارشد در تسریع عملکرد، به دست آوردن نتایج، و تعریف آینده', 'یک کلاس کارشناسی ارشد در تسریع عملکرد، به دست آوردن نتایج، و تعریف آینده', 27, 8, 'book', 't', '<p><em>کتاب فیلد اسکرام </em>(2019) یک راهنمای عملی و عملی برای چارچوب سازمانی اسکرام در ذهنیت چابک است. این کتابچه راهنمای مختصر نحوه عملکرد اسکرام برای افزایش سرعت کار و اطمینان از اینکه هر تیمی تأثیر مناسبی را برای کسب‌وکار ارائه می‌دهد، خلاصه می‌کند. همچنین نحوه پیاده‌سازی اسکرام را در هر سازمانی در تمامی صنایع از نرم‌افزار گرفته تا نوسازی خانه و حتی ارتش توضیح می‌دهد.</p>', '2021-01-19 00:00:00', 5, 107, 'https://images.blinkist.io/images/books/60016a586cee070006e8201e/1_1/470.jpg', '/en/books/the-scrum-fieldbook-en/purchase', 'کتاب-فیلد-اسکرام', '2023-01-26 20:39:55.767063', '2023-01-26 20:39:55.767063', NULL, 'The Scrum Fieldbook');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (895, 'زیلو تاک', 'قوانین جدید املاک و مستغلات', 'قوانین جدید املاک و مستغلات', 12, 5, 'book', 't', '<p><em>Zillow Talk: The New Rules of Real Estate</em> (2015) همه ابزارهایی را که خواننده برای خرید، فروش یا اجاره خانه نیاز دارد در اختیار خواننده قرار می دهد. از معمای اجاره یا خرید، زمان فروش و چگونگی افزایش ارزش ملک خود، این پلک ها معضلات همیشگی مهم املاک و مستغلات - بزرگترین سرمایه گذاری زندگی شما - را روشن می کند.</p>', '2015-05-20 00:00:00', 4, 63, 'https://images.blinkist.io/images/books/555b367661353300077c0000/1_1/470.jpg', '/en/books/zillow-talk-en/purchase', 'زیلو-تاک', '2023-01-26 20:40:05.883249', '2023-01-26 20:40:05.883249', NULL, 'Zillow Talk');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (896, 'مذاکره در مورد غیر قابل مذاکره', 'چگونه بیشترین درگیری های احساسی خود را حل کنید', 'چگونه بیشترین درگیری های احساسی خود را حل کنید', 20, 8, 'book', 't', '<p><em>مذاکره غیرقابل مذاکره</em> (2016) بینش هایی را در مورد چارچوب جدیدی ارائه می دهد که می تواند برای حل تعارضات سرسختانه در زندگی شخصی و حرفه ای ما اعمال شود. پلک‌ها بر اهمیت «ذهن قبیله‌ای» تأکید می‌کنند و همچنین نشان می‌دهند که چگونه به طور فعال به دردهای عاطفی رسیدگی می‌کنیم و نقش هویت در حل تعارض را بررسی می‌کنیم.</p>', '2017-06-23 00:00:00', 4, 131, 'https://images.blinkist.io/images/books/5948c80fb238e10005eecf6a/1_1/470.jpg', '/en/books/negotiating-the-nonnegotiable-en/purchase', 'مذاکره-در-مورد-غیر-قابل-مذاکره', '2023-01-26 20:40:12.995206', '2023-01-26 20:40:12.995206', NULL, 'Negotiating the Nonnegotiable');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1616, 'نظریه ریسمان', 'در مورد تنیس', 'در مورد تنیس', 13, 5, 'book', 't', '<p><em>تئوری ریسمان</em>(2016) مجموعه ای از مقالات درباره تنیس توسط دیوید فاستر والاس است. بهترین بازیکنان جهان جان خود را فدا می کنند تا بتوانند ما را سرگرم کنند، اما فداکاری آنها آنها را به سطحی از عظمت می رساند که بقیه انسان های فرومایه هرگز به آن نخواهیم رسید.</p>', '2017-05-16 00:00:00', 4, 50, 'https://images.blinkist.io/images/books/5918c2edb238e100066a4e4a/1_1/470.jpg', '/en/books/string-theory-en/purchase', 'نظریه-ریسمان', '2023-01-27 02:54:32.43071', '2023-01-27 02:54:32.43071', NULL, 'String Theory');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (897, 'با پایان در ذهن', 'مردن، مرگ و خرد در عصر انکار', 'مردن، مرگ و خرد در عصر انکار', 22, 8, 'book', 't', '<p><em>With the End Mind </em>(2017) پادزهر قدرتمندی برای ترس، جهل و سوءتفاهم که مرگ را در فرهنگ معاصر احاطه کرده است ارائه می دهد. از طریق مشاهدات و بازتاب‌های شخصی، داستان‌های تلخ برخی از بیماران لاعلاج را روایت می‌کند که نویسنده در طول سه دهه فعالیت خود به عنوان پزشک مراقبت‌های تسکینی با آنها کار کرده است. </p>', '2019-10-24 00:00:00', 4, 62, 'https://images.blinkist.io/images/books/5db08c0a6cee07000742365d/1_1/470.jpg', '/en/books/with-the-end-in-mind-en/purchase', 'با-پایان-در-ذهن', '2023-01-26 20:40:20.43898', '2023-01-26 20:40:20.43898', NULL, 'With the End in Mind');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (898, 'آنچه هر سرمایه گذار فرشته می خواهد شما بدانید', 'یک خودی نشان می دهد که چگونه برای ایده میلیارد دلاری خود بودجه هوشمند دریافت کنید', 'یک خودی نشان می دهد که چگونه برای ایده میلیارد دلاری خود بودجه هوشمند دریافت کنید', 15, 7, 'book', 't', '<p><em>آنچه که هر سرمایه‌گذار فرشته می‌خواهد شما بدانید </em>(2013) نکاتی را به کارآفرینان تازه‌کار ارائه می‌کند در مورد اینکه چه چیزی را در یک سرمایه‌گذار باید جستجو کنید - و چگونه می‌توانید یک "فرشته" را برای سرمایه‌گذاری جذب کنید. با آمادگی کامل و درک خوب از انگیزه های سرمایه گذار، هر کارآفرینی می تواند برای ایده بزرگ بعدی خود تأمین مالی کند.</p>', '2015-04-15 00:00:00', 4, 48, 'https://images.blinkist.io/images/books/552bdff06466340007930000/1_1/470.jpg', '/en/books/what-every-angel-investor-wants-you-to-know-en/purchase', 'آنچه-هر-سرمایه-گذار-فرشته-می-خواهد-شما-بدانید', '2023-01-26 20:40:27.71864', '2023-01-26 20:40:27.71864', NULL, 'What Every Angel Investor Wants You to Know');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (899, 'از دست دادن بکارت من', 'چگونه زنده ماندم، از آن لذت بردم و کسب و کار به روش خودم ثروتمند شدم', 'چگونه زنده ماندم، از آن لذت بردم و کسب و کار به روش خودم ثروتمند شدم', 30, 13, 'book', 't', '<p><em>از دست دادن</em> <em>باکرگی من</em> <em>باکرگی</em> پرفروش‌ترین زندگینامه بین‌المللی از تاجر خودساخته ریچارد برانسون است. او ماجراهای سودآور خود را شرح می دهد، که با ترک تحصیل، تأسیس یک شرکت ضبط و عبور از اقیانوس اطلس با یک قایق تندرو شروع می شود. در اصل، این کتاب در مورد این است که چگونه زیرکی، اراده و طرز فکر ماجراجویانه در ساختن یکی از ثروتمندترین مردان روی زمین نقش داشته است.</p>', '2014-09-09 00:00:00', 4, 152, 'https://images.blinkist.io/images/books/540dcca966613400081c0000/1_1/470.jpg', '/en/books/losing-my-virginity-en/purchase', 'از-دست-دادن-بکارت-من', '2023-01-26 20:40:33.051575', '2023-01-26 20:40:33.051575', NULL, 'Losing My Virginity');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (900, 'صمیمیت و میل', 'اشتیاق را در رابطه خود بیدار کنید', 'اشتیاق را در رابطه خود بیدار کنید', 25, 8, 'book', 't', '<p><em>صمیمیت و میل: شور و شوق را در رابطه خود بیدار کنید </em>(2009) توضیح می دهد که چرا همه افراد در روابط متعهدانه و طولانی مدت با مشکلات جنسی مواجه می شوند. این کتاب با مطالعه موردی زوج‌های واقعی در رابطه جنسی، نشان می‌دهد که چگونه افراد در روابط می‌توانند دیدگاه خود را تغییر دهند - و با خود و یکدیگر مقابله کنند تا اشتیاق جنسی را دوباره بیدار کنند.</p>', '2020-10-22 00:00:00', 4, 409, 'https://images.blinkist.io/images/books/5f8965126cee070007a86bde/1_1/470.jpg', '/en/books/intimacy-and-desire-en/purchase', 'صمیمیت-و-میل', '2023-01-26 20:40:40.497986', '2023-01-26 20:40:40.497986', NULL, 'Intimacy &amp; Desire');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (901, 'ژن ورزش', 'درون علم عملکرد ورزشی فوق العاده', 'درون علم عملکرد ورزشی فوق العاده', 16, 8, 'book', 't', '<p><em>ژن ورزشی</em> نگاهی به ویژگی‌های فیزیولوژیکی مفید در ورزش‌های مختلف و پیشینه ارثی آنها می‌اندازد. همچنین بررسی می‌کند که چرا مردم در بخش‌های خاصی از جهان به روش خاص خود تکامل یافته‌اند و چگونه این امر در حوزه ورزش‌های خاص مفید است.</p>', '2014-03-19 08:25:19', 4, 71, 'https://images.blinkist.io/images/books/532866723635380008e00000/1_1/470.jpg', '/en/books/the-sports-gene-en/purchase', 'ژن-ورزش', '2023-01-26 20:40:47.609096', '2023-01-26 20:40:47.609096', NULL, 'The Sports Gene');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (902, 'ترن هوایی کارآفرین', 'چرا اکنون زمان #JoinTheRide است؟', 'چرا اکنون زمان #JoinTheRide است؟', 20, 8, 'book', 't', '<p><em>ترن هوایی کارآفرین</em> (2015) راهنمای اساسی برای ایجاد یک کسب و کار موفق است. این پلک‌ها با نگاهی دقیق به چهار مهارت حیاتی برای موفقیت: فروش، استخدام، رهبری و بهره‌وری، شما را در مهم‌ترین جنبه‌های کارآفرینی راهنمایی می‌کنند.</p>', '2015-06-10 00:00:00', 5, 75, 'https://images.blinkist.io/images/books/5575979e3935610007420000/1_1/470.jpg', '/en/books/the-entrepreneur-roller-coaster-en/purchase', 'ترن-هوایی-کارآفرین', '2023-01-26 20:40:55.128157', '2023-01-26 20:40:55.128157', NULL, 'The Entrepreneur Roller Coaster');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (903, 'آخرین سرمایه گذاری مطمئن', 'اکنون خرج کنید تا ثروت واقعی خود را برای همیشه افزایش دهید', 'اکنون خرج کنید تا ثروت واقعی خود را برای همیشه افزایش دهید', 23, 8, 'book', 't', '<p><em>آخرین سرمایه گذاری مطمئن </em>(2016) برنامه ریزی مالی را با تمرکز بر روی تنها چیزی که کنترل کامل روی آن دارید، تغییر می دهد: خودتان. مدل آن سه رشته را به شما آموزش می دهد که از سه حوزه ثروت پشتیبانی می کنند تا پتانسیل درآمد شما را تقویت کرده و شادی روزانه شما را افزایش دهند.</p>', '2020-07-21 00:00:00', 4, 197, 'https://images.blinkist.io/images/books/5f10c8936cee0700066c458c/1_1/470.jpg', '/en/books/the-last-safe-investment-en/purchase', 'آخرین-سرمایه-گذاری-مطمئن', '2023-01-26 20:41:02.274026', '2023-01-26 20:41:02.274026', NULL, 'The Last Safe Investment');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (904, 'دویدن در', 'چگونه دویدن زندگی من را نجات داد', 'چگونه دویدن زندگی من را نجات داد', 18, 6, 'book', 't', '<p><em>دویدن در </em>(2019) اثرات مخرب اختلالات اضطرابی را بررسی می کند و نشان می دهد که چگونه ورزش می تواند به درمان آنها کمک کند. این پلک ها همچنین مبارزات سلامت روان نویسنده بلا مکی را بررسی می کند و سفر او به سمت بهبودی را ترسیم می کند. </p>', '2020-03-05 00:00:00', 4, 106, 'https://images.blinkist.io/images/books/5e5f901e6cee07000655e2a6/1_1/470.jpg', '/en/books/jog-on-en/purchase', 'دویدن-در', '2023-01-26 20:41:10.145917', '2023-01-26 20:41:10.145917', NULL, 'Jog On');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (905, 'چگونه مانند یک امپراتور روم فکر کنیم', 'فلسفه رواقی مارکوس اورلیوس', 'فلسفه رواقی مارکوس اورلیوس', 20, 9, 'book', 't', '<p><em>چگونه مانند یک امپراتور روم فکر کنیم</em> (2019) اصول راهنمای رواقی گری را از طریق زندگی و نوشته های مارکوس اورلیوس توصیف می کند. به عنوان یکی از ارجمندترین امپراتوران روم، تحسین برانگیزترین ویژگی های او به عنوان یک رهبر توسط فلسفه رواقیان مشخص شد. ما همچنین متوجه می‌شویم که چگونه امروز هر کسی می‌تواند این شیوه‌ها را دنبال کند.</p>', '2020-03-15 00:00:00', 5, 296, 'https://images.blinkist.io/images/books/5e68f3636cee0700068bda95/1_1/470.jpg', '/en/books/how-to-think-like-a-roman-emperor-en/purchase', 'چگونه-مانند-یک-امپراتور-روم-فکر-کنیم', '2023-01-26 20:41:16.965576', '2023-01-26 20:41:16.965576', NULL, 'How to Think Like a Roman Emperor');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (906, 'تجارت جدید برای زندگی', 'روانشناسی، نظم و انضباط، ابزارها و سیستم های معاملاتی، کنترل ریسک، مدیریت تجارت', 'روانشناسی، نظم و انضباط، ابزارها و سیستم های معاملاتی، کنترل ریسک، مدیریت تجارت', 16, 8, 'book', 't', '<p><em>The New Trading for a Living </em>(2014) راهنمای کامل شما برای شروع تجارت است. این پلک ها یک نمای کلی از طیف وسیعی از روش های معاملاتی ارائه می دهند که به شما امکان می دهد با حداقل ریسک به بازار نزدیک شوید.</p>', '2015-06-22 00:00:00', 4, 122, 'https://images.blinkist.io/images/books/5587e74b3966300007000000/1_1/470.jpg', '/en/books/the-new-trading-for-a-living-en/purchase', 'تجارت-جدید-برای-زندگی', '2023-01-26 20:41:23.923251', '2023-01-26 20:41:23.923251', NULL, 'The New Trading for a Living');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (907, 'نقاط کور رهبری', 'چگونه رهبران موفق نقاط ضعف مهم را شناسایی کرده و بر آنها غلبه می کنند', 'چگونه رهبران موفق نقاط ضعف مهم را شناسایی کرده و بر آنها غلبه می کنند', 15, 7, 'book', 't', '<p><em>نقاط کور رهبری </em>همه چیز درباره ناشناخته‌هایی است که ما را به عقب می‌اندازد - شکاف‌هایی در مهارت‌ها، دانش و درک ما که باعث می‌شود کارایی کسب‌وکار و مهارت‌های حل مشکل ما از بین برود. با پیروی از تکنیک های ذکر شده در این کتاب، می توانید به طور موثر نقاط کور خود را شناسایی و از بین ببرید.</p>', '2015-03-23 00:00:00', 4, 72, 'https://images.blinkist.io/images/books/550fed62666564000a020000/1_1/470.jpg', '/en/books/leadership-blindspots-en/purchase', 'نقاط-کور-رهبری', '2023-01-26 20:41:30.964403', '2023-01-26 20:41:30.964403', NULL, 'Leadership Blindspots');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (908, 'لذت کار', '30 راه برای اصلاح فرهنگ کاری و عاشق شدن دوباره به شغلتان', '30 راه برای اصلاح فرهنگ کاری و عاشق شدن دوباره به شغلتان', 23, 8, 'book', 't', '<p><em>لذت کار</em> (2019) نکات و تکنیک‌هایی را ارائه می‌کند تا کار را کم استرس‌تر و بسیار سرگرم‌کننده‌تر و سازنده‌تر کنید. بسیاری از مشکلات بهره وری را که در محیط کار امروزی می توان یافت، بررسی می کند و راه حل هایی برای افزایش کارایی و آرامش بیشتر ارائه می دهد. همچنین ایده هایی در مورد چگونگی بهبود جو در دفتر و با همکاران خود به منظور مشارکت در کار گروهی مؤثر و هماهنگ ارائه می دهد. </p>', '2019-09-09 00:00:00', 4, 140, 'https://images.blinkist.io/images/books/5d72602c6cee07000897c414/1_1/470.jpg', '/en/books/the-joy-of-work-en/purchase', 'لذت-کار', '2023-01-26 20:41:35.936819', '2023-01-26 20:41:35.936819', NULL, 'The Joy of Work');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (909, 'بله و', 'چگونه بداهه نوازی تفکر «نه، اما» را معکوس می کند و خلاقیت و همکاری را بهبود می بخشد', 'چگونه بداهه نوازی تفکر «نه، اما» را معکوس می کند و خلاقیت و همکاری را بهبود می بخشد', 18, 7, 'book', 't', '<p><em>بله</em>، <em>و </em>(2015) به شما نشان می‌دهد که چگونه با استفاده از تکنیک‌های کمدی بداهه در دنیای تجارت، می‌توانید ایده‌های بهتری تولید کنید و ارتباطات مؤثرتری را تقویت کنید. هدف نهایی ایجاد تیمی آماده برای رویارویی با هر چالشی است. نویسندگان از تجربه شخصی از کار با استعدادهای برجسته مانند تینا فی، استفن کولبرت و امی پولر استفاده می کنند.</p>', '2015-06-29 00:00:00', 4, 39, 'https://images.blinkist.io/images/books/55914c9030383300070a0000/1_1/470.jpg', '/en/books/yes-and-en/purchase', 'بله-و', '2023-01-26 20:41:43.173039', '2023-01-26 20:41:43.173039', NULL, 'Yes, And');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (910, 'نادر', 'مسابقه پرمخاطره برای ارضای نیاز ما به کمیاب ترین فلزات روی زمین', 'مسابقه پرمخاطره برای ارضای نیاز ما به کمیاب ترین فلزات روی زمین', 17, 8, 'book', 't', '<p><em>نادر</em> (2015) عناصر شیمیایی رایج اما گریزان در زیر سطح زمین را روشن می کند - عناصری که نقش مهمی را در توسعه فناوری مدرن ایفا می کنند. درک بهتری از آنچه واقعاً منجر به کشمکش‌های ژئوپلیتیکی بین ابرقدرت‌های جهان می‌شود و اینکه گروهی از فلزات کمیاب خاکی با آینده منابع انرژی، ابزارها و فناوری نظامی ما چه ارتباطی دارد، دریافت کنید.</p>', '2017-03-07 00:00:00', 4, 13, 'https://images.blinkist.io/images/books/58bd12f7c7c53e00041d65e9/1_1/470.jpg', '/en/books/rare-en/purchase', 'نادر', '2023-01-26 20:41:51.054751', '2023-01-26 20:41:51.054751', NULL, 'Rare');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (911, 'بازاریابی 3.0', 'از محصولات گرفته تا مشتریان و روح انسان', 'از محصولات گرفته تا مشتریان و روح انسان', 17, 7, 'book', 't', '<p><em>Marketing 3.0</em> راهنمای استراتژی های بازاریابی فردا است. این پلک‌ها توضیح می‌دهند که چگونه تاکتیک‌های قدیمی منسوخ شده‌اند، زیرا مردم به دنبال معنای زندگی خود و شرکت‌هایی هستند که می‌توانند آن را ارائه دهند. در ادامه بخوانید تا بدانید چگونه می‌توانید استراتژی بازاریابی خود را با تغییر ماهیت ترجیحات مصرف‌کننده تطبیق دهید.</p>', '2015-10-12 00:00:00', 4, 80, 'https://images.blinkist.io/images/books/561bd1c93635640007150000/1_1/470.jpg', '/en/books/marketing-3-dot-0-en/purchase', 'بازاریابی-3.0', '2023-01-26 20:41:58.356783', '2023-01-26 20:41:58.356783', NULL, 'Marketing 3.0');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (912, 'خودتان را بشناسید، پول خود را بشناسید', 'کشف کنید که چرا پول را به روشی که انجام می دهید مدیریت می کنید، و در مورد آن چه کاری باید انجام دهید!', 'کشف کنید که چرا پول را به روشی که انجام می دهید مدیریت می کنید، و در مورد آن چه کاری باید انجام دهید!', 24, 9, 'book', 't', '<p><em>خودت را بشناس، پولت را بشناس</em> (2021)<em> </em>به امور مالی شخصی از منظری بدیع می پردازد. به جای اینکه صرفاً به شما نشان دهد چگونه بودجه ایجاد کنید یا به شما بگوییم که هر ماه بیشتر پس انداز کنید، روانشناسی پشت تصمیم گیری را آشکار می کند. اگر می خواهید سلامت مالی خود را بهبود ببخشید، باید درک کنید که <em>چرا </em> اشتباهاتی را مرتکب می شوید. به آن رسیدگی کنید و می‌توانید طرز فکر پول خود را تغییر دهید و آینده بهتری بسازید.</p>', '2021-03-16 00:00:00', 4, 174, 'https://images.blinkist.io/images/books/604b2d436cee070007937971/1_1/470.jpg', '/en/books/know-yourself-know-your-money-en/purchase', 'خودتان-را-بشناسید،-پول-خود-را-بشناسید', '2023-01-26 20:42:05.904711', '2023-01-26 20:42:05.904711', NULL, 'Know Yourself, Know Your Money');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (913, 'انقلاب مدیریتی', 'آنچه در جهان اتفاق می افتد', 'آنچه در جهان اتفاق می افتد', 18, 6, 'book', 't', '<p>با تکیه بر استدلال‌های قوی و نشان دادن بینش‌های خارق‌العاده، در<em> انقلاب مدیریتی</em> (1941) جیمز برنهام ظهور یک طبقه حاکم جدید - مدیران - را بررسی می‌کند که قول داده بودند سرمایه‌داران ثروتمند را از موقعیت اصلی خود خلع کنند. در اقتصاد اواسط قرن بیستم اگرچه بیش از هفت دهه پیش نوشته شده است، مضامین و استدلال های این کتاب هنوز در جامعه امروزی طنین انداز است.</p>', '2018-10-01 00:00:00', 4, 21, 'https://images.blinkist.io/images/books/5bb1441a862c430007565f3d/1_1/470.jpg', '/en/books/the-managerial-revolution-en/purchase', 'انقلاب-مدیریتی', '2023-01-26 20:42:13.009409', '2023-01-26 20:42:13.009409', NULL, 'The Managerial Revolution');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (914, 'هنر توقف زمان', 'ذهن آگاهی عملی برای افراد پرمشغله', 'ذهن آگاهی عملی برای افراد پرمشغله', 25, 9, 'book', 't', '<p><em>هنر توقف زمان</em> (2017) به سؤالاتی که این روزها در ذهن بسیاری از ما وجود دارد پاسخ می دهد: تمام وقت ما کجا می رود؟ و چگونه می توانیم آن را پس بگیریم؟ پدرام شجاعی، نویسنده، با ترکیب اصول عملی مدیریت زمان با ایده‌های فلسفی ذهن آگاهی، به ما نشان می‌دهد که چگونه می‌توانیم از زمان محدود خود در زمین بهترین استفاده را ببریم.</p>', '2020-10-21 00:00:00', 5, 901, 'https://images.blinkist.io/images/books/5f8963416cee0700063afb30/1_1/470.jpg', '/en/books/the-art-of-stopping-time-en/purchase', 'هنر-توقف-زمان', '2023-01-26 20:42:20.874913', '2023-01-26 20:42:20.874913', NULL, 'The Art of Stopping Time');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (915, 'شجاع', '50 عمل روزمره شجاعت برای پیشرفت در کار، عشق و زندگی', '50 عمل روزمره شجاعت برای پیشرفت در کار، عشق و زندگی', 21, 8, 'book', 't', '<p><em>شجاع</em> (2015) به جزئیات اقداماتی می‌پردازد که هر کسی می‌تواند برای شجاع‌تر شدن در زندگی روزمره انجام دهد. با انجام این کار، تعاملات اجتماعی و هنجارهایی که افراد را از رفتار شجاعانه‌تر باز می‌دارد، از هم جدا می‌کند. این پلک ها نشان می دهد که چگونه ترس مردم را از زندگی با پتانسیل کامل خود باز می دارد و ابزارهایی را برای شجاع تر شدن و یادگیری چگونگی پیشرفت فراهم می کند. </p>', '2019-10-22 00:00:00', 4, 110, 'https://images.blinkist.io/images/books/5da9c3be6cee070008285fbd/1_1/470.jpg', '/en/books/brave-en/purchase', 'شجاع', '2023-01-26 20:42:27.803017', '2023-01-26 20:42:27.803017', NULL, 'Brave');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (916, 'قدرت شکست', 'چگونه جیب های خالی، بودجه فشرده و میل به موفقیت می توانند به بزرگترین مزیت رقابتی شما تبدیل شوند', 'چگونه جیب های خالی، بودجه فشرده و میل به موفقیت می توانند به بزرگترین مزیت رقابتی شما تبدیل شوند', 19, 8, 'book', 't', '<p><em>قدرت شکست</em> (2016) نشان می دهد که چگونه شروع یک کسب و کار با بودجه محدود نباید یک نقطه ضعف باشد. با دیدگاه درست، می توان از قدرت بروک برای تولید خلاقیت خیره کننده استفاده کرد. با این نگاه تازه به دنیای کسب و کار، دیگر پول - یا کمبود آن - را به عنوان مانعی برای کارآفرینی نمی بینید، زیرا حقیقت این است که هر کسی با ایده درست و نگرش می تواند یک کسب و کار را راه اندازی کند. پس منتظر چه چیزی هستید؟</p>', '2017-06-19 00:00:00', 4, 65, 'https://images.blinkist.io/images/books/5944e034b238e10005eece08/1_1/470.jpg', '/en/books/the-power-of-broke-en/purchase', 'قدرت-شکست', '2023-01-26 20:42:33.122458', '2023-01-26 20:42:33.122458', NULL, 'The Power of Broke');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (917, 'نقشه آن', 'راهنمای عملی طراحی آموزش استراتژیک', 'راهنمای عملی طراحی آموزش استراتژیک', 18, 5, 'book', 't', '<p><em>نقشه بردارید! کتاب نقشه برداری اقدام </em>(2017) یک راهنمای عملی و عملی برای کسانی است که در دنیای کسب و کار هستند که آموزش طراحی را برای همکاران حرفه ای خود طراحی می کنند. این راهنمای انقلابی بر حل مشکلات در کسب و کار و دستیابی به نتایج قابل اندازه گیری مجدد تمرکز دارد. بنابراین، اگر می‌خواهید آن وبینارهای بی‌اثر و پشته‌های اسلاید خسته‌کننده را دور بریزید، دیگر نگاه نکنید—<em>آن را نقشه‌برداری کنید! </em>به شما کمک می‌کند تا روی مشکلات تمرکز کنید، چگونه به این راه رسیده‌اند، و چه کاری می‌توانند برای نتایج قابل اثبات انجام دهند. </p>', '2022-10-21 00:00:00', 4, 20, 'https://images.blinkist.io/images/books/635107436cee07000860c52d/1_1/470.jpg', '/en/books/map-it-en/purchase', 'نقشه-آن', '2023-01-26 20:42:40.958322', '2023-01-26 20:42:40.958322', NULL, 'Map It');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (918, 'ترک کنید', 'بستن فاصله بین شغل روزانه و شغل رویایی شما', 'بستن فاصله بین شغل روزانه و شغل رویایی شما', 18, 9, 'book', 't', '<p>پیدا کردن اینکه واقعاً می‌خواهید در زندگی کجا باشید نیاز به صبر، کار سخت و برنامه‌ریزی دارد، اما هر کسی می‌تواند با فداکاری درست این کار را انجام دهد. <em>ترک کردن</em> که پر از حکایات شخصی بسیاری از یک دوره 12 ساله پرشور شغلی است، هوشمندانه ترین راه را برای ترک شغل روزانه به خاطر شغل رویایی خود به شما نشان می دهد.</p>', '2015-01-16 00:00:00', 4, 25, 'https://images.blinkist.io/images/books/54b3b5df6466330009750000/1_1/470.jpg', '/en/books/quitter-en/purchase', 'ترک-کنید', '2023-01-26 20:42:46.606238', '2023-01-26 20:42:46.606238', NULL, 'Quitter');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (919, 'اول کار های مهم', 'زندگی کردن، عشق ورزیدن، آموختن، به جای گذاشتن میراث', 'زندگی کردن، عشق ورزیدن، آموختن، به جای گذاشتن میراث', 14, 10, 'book', 't', '<p>این عنوان بینش‌ها و دستورالعمل‌های ارزشمندی را در اختیار شما قرار می‌دهد که به شما کمک می‌کند زندگی خود را روی چیزهایی متمرکز کنید که واقعاً پرمعنا هستند. شما یاد خواهید گرفت که چگونه اولویت های خود را تعیین کنید، بهترین تصمیم ها را بگیرید و چشم اندازی دقیق برای آینده ایجاد کنید. اگر به دنبال ایجاد تغییرات مثبت در زندگی خود هستید، این کتاب مکانی عالی برای شروع است!</p>', '2014-08-12 00:00:00', 5, 489, 'https://images.blinkist.io/images/books/53eb1fcb3634330007010000/1_1/470.jpg', '/en/books/first-things-first-en/purchase', 'اول-کار-های-مهم', '2023-01-26 20:46:49.92776', '2023-01-26 20:46:49.92776', NULL, 'First Things First');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (920, 'چگونه بدون سرمایه یک سرمایه دار باشیم', 'چهار قانونی که برای ثروتمند شدن باید زیر پا بگذارید', 'چهار قانونی که برای ثروتمند شدن باید زیر پا بگذارید', 21, 8, 'book', 't', '<p><em>چگونه بدون هیچ سرمایه ای سرمایه دار باشیم</em> (2019) اسرار سیستم سرمایه داری را باز می کند تا به کارآفرینان نوپا نشان دهد که چگونه بدون سوزاندن شمع از هر دو طرف، درآمدهای کلان به دست آورند. مولتی میلیونر خودساخته ناتان لاتکا، مملو از هک های خلاقانه و توصیه های عملی، این افسانه را از بین می برد که برای ثروتمند شدن به پول زیادی یا ایده ای خیره کننده اصیل نیاز دارید. بنابراین به چه چیزی <em>کار</em> نیاز دارید؟ ساده: تمایل به شکستن قوانین تعیین شده و ترسیم مسیر خود.</p>', '2019-09-20 00:00:00', 4, 149, 'https://images.blinkist.io/images/books/5d80cd0c6cee0700095f01ac/1_1/470.jpg', '/en/books/how-to-be-a-capitalist-without-any-capital-en/purchase', 'چگونه-بدون-سرمایه-یک-سرمایه-دار-باشیم', '2023-01-26 20:47:07.54774', '2023-01-26 20:47:07.54774', NULL, 'How to Be a Capitalist Without Any Capital');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (921, 'بر اساس شرایط خودش', 'زندگی نلسون راکفلر', 'زندگی نلسون راکفلر', 36, 15, 'book', 't', '<p><em>On His Own Terms</em>(2014) داستان زندگی قابل توجه نلسون راکفلر را روایت می کند که از بدنامی و ثروت خانواده اش برای تغییر جهان به سوی بهتر شدن استفاده کرد. این پلک ها شما را در طول زندگی نلسون، از مشارکت او در کسب و کار خانوادگی نفت گرفته تا حرفه طولانی او در سیاست، راهنمایی می کند.</p>', '2017-03-17 00:00:00', 4, 14, 'https://images.blinkist.io/images/books/58c6b8be8d9003000407262c/1_1/470.jpg', '/en/books/on-his-own-terms-en/purchase', 'بر-اساس-شرایط-خودش', '2023-01-26 20:47:22.642134', '2023-01-26 20:47:22.642134', NULL, 'On His Own Terms');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (922, 'چهار گام تا ظهور', 'استراتژی های موفق برای محصولاتی که برنده می شوند', 'استراتژی های موفق برای محصولاتی که برنده می شوند', 17, 8, 'book', 't', '<p>با مشاهده نمونه هایی از شرکت هایی که شکست خورده اند، <em></em> <em>چهار</em> <em>گام</em> <em>تا</em> <em> em> <em>Epiphany</em> بینش‌های کلیدی که استارت‌آپ‌ها برای دستیابی به موفقیت و تداوم آن، و دور شدن از مسیر شکست نیاز دارند، توضیح می‌دهد.</p>', '2014-07-29 00:00:00', 4, 103, 'https://images.blinkist.io/images/books/53d8cefa3930340007840100/1_1/470.jpg', '/en/books/the-four-steps-to-the-epiphany-en/purchase', 'چهار-گام-تا-ظهور', '2023-01-26 20:47:38.471748', '2023-01-26 20:47:38.471748', NULL, 'The Four Steps to the Epiphany');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (923, 'اقدامات حماسی', 'یک دکتر. هفت میلیارد بیمار', 'یک دکتر. هفت میلیارد بیمار', 19, 7, 'book', 't', '<p><em>Epic Measures</em> (2015) داستان باورنکردنی را روایت می‌کند که چگونه مردی به نام کریستوفر موری توانست جامع‌ترین مطالعه پزشکی را که تا کنون جمع‌آوری شده است بسازد. دریابید که چه چیزی موری و تیم متعهدش از همکارانش را برای ایجاد نقشه جهانی از هر بیماری و بیماری شناخته شده برای انسان ترغیب کرده است – و کشف کنید که چگونه کار برجسته او چهره سلامت جهان را متحول کرده است. </p>', '2017-08-31 00:00:00', 4, 15, 'https://images.blinkist.io/images/books/59a2bdd8b238e10006a12957/1_1/470.jpg', '/en/books/epic-measures-en/purchase', 'اقدامات-حماسی', '2023-01-26 20:47:54.100812', '2023-01-26 20:47:54.100812', NULL, 'Epic Measures');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (924, 'دانه قهوه', 'یک درس ساده برای ایجاد تغییر مثبت', 'یک درس ساده برای ایجاد تغییر مثبت', 20, 7, 'book', 't', '<p><em>دانه قهوه</em> (2019) یک افسانه امروزی است که داستان آبه، یک پسر معمولی آمریکایی را روایت می‌کند که زندگی او با درس قدرتمندی که از معلم علوم خود می‌گیرد، برای همیشه تغییر می‌کند. . جکسون. با انتقال این درس به بزرگسالی، آبه می تواند بر چالش های خود غلبه کند، مثبت بماند و دنیای اطراف خود را متحول کند. با دنبال کردن داستان زندگی او و یادگیری درسی که الهام‌بخش آن است، ما نیز می‌توانیم کنترل سرنوشت خود را در دست بگیریم.</p>', '2019-08-08 00:00:00', 4, 143, 'https://images.blinkist.io/images/books/5d47e5376cee07000859eaea/1_1/470.jpg', '/en/books/the-coffee-bean-en/purchase', 'دانه-قهوه', '2023-01-26 20:48:11.019', '2023-01-26 20:48:11.019', NULL, 'The Coffee Bean');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (925, 'در بهترین حالت شما', 'چگونه زمان، انرژی و اولویت ها را به نفع خود بدست آوریم', 'چگونه زمان، انرژی و اولویت ها را به نفع خود بدست آوریم', 21, 6, 'book', 't', '<p><em>در بهترین حالت </em>(2021) یک راهنمای عملی برای حرکت فراتر از مدیریت زمان است. با تکیه بر دهه‌ها رهبری کری نیوهوف، نشان می‌دهد که چگونه زمان، انرژی و اولویت‌های خود را همگام‌سازی کنید تا بتوانید به اهداف خود برسید، انرژی بیشتری برای آنچه دوست دارید داشته باشید و شروع به پیشرفت کنید هم در محل کار و هم در خانه.</p >', '2021-11-22 00:00:00', 5, 485, 'https://images.blinkist.io/images/books/618d36436cee070008fdeb68/1_1/470.jpg', '/en/books/at-your-best-en/purchase', 'در-بهترین-حالت-شما', '2023-01-26 20:48:26.266372', '2023-01-26 20:48:26.266372', NULL, 'At Your Best');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (926, 'آیا خودم را روشن کنم؟', 'چرا خوب نوشتن مهم است', 'چرا خوب نوشتن مهم است', 19, 8, 'book', 't', '<p><em>آیا خودم را روشن کنم؟ </em>(2017) نگاهی بسیار ضروری به این موضوع ارائه می دهد که چرا پیام های واضح و مختصر، اکنون بیش از هر زمان دیگری، بسیار مهم هستند. این روزها محتوای بسیار زیادی وجود دارد، اما یافتن حقیقت هرگز به این سختی نبوده است. سیاستمداران و مدیران بازاریابی عمدا از کلمات گمراه کننده استفاده می کنند که حقیقت را پنهان می کند و ما را سردرگم و بی اعتماد می کند. مواقع دیگر، نوشتن بد باعث می‌شود که سرمان را خارانیم. اگر امیدواریم حقایق را بهتر درک کنیم، به افراد بیشتری نیاز داریم که بتوانند نوشتار واضح و معناداری ارائه دهند.</p>', '2017-12-26 00:00:00', 4, 51, 'https://images.blinkist.io/images/books/5a3d2e2db238e10007128b73/1_1/470.jpg', '/en/books/do-i-make-myself-clear-en/purchase', 'آیا-خودم-را-روشن-کنم؟', '2023-01-26 20:48:42.123312', '2023-01-26 20:48:42.123312', NULL, 'Do I Make Myself Clear?');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (927, 'مردی که بازار را حل کرد', 'چگونه جیم سیمونز انقلاب کوانت را راه اندازی کرد', 'چگونه جیم سیمونز انقلاب کوانت را راه اندازی کرد', 23, 8, 'book', 't', '<p><em>مردی که بازار را حل کرد </em>(2019) زندگی مدیر صندوق سرمایه گذاری مرموز و ریاضیدان جیم سیمونز را نشان می دهد. این داستان اوایل زندگی او را به عنوان یک هندسه‌سنج درخشان که برای ریاضیاتش جوایزی را به دست آورد، برای کارهایش در شکستن کدهای شوروی، تا موفقیتش با شرکت مدیریت صندوق تامینی Renaissance Technologies را نشان می‌دهد. سایمونز بسیار بیشتر از یک سرمایه گذار دیگر، دنیا را با ریاضیات و روش های خود تغییر داد.</p>', '2019-12-05 00:00:00', 4, 162, 'https://images.blinkist.io/images/books/5de8307c6cee070008b723e5/1_1/470.jpg', '/en/books/the-man-who-solved-the-market-en/purchase', 'مردی-که-بازار-را-حل-کرد', '2023-01-26 20:48:56.95103', '2023-01-26 20:48:56.95103', NULL, 'The Man Who Solved the Market');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (928, 'تیتان', 'The Life of John D. Rockefeller, Sr.', 'The Life of John D. Rockefeller, Sr.', 30, 13, 'book', 't', '<p><em>Titan</em> (1998) بیوگرافی جامع جان دی راکفلر پدر، سرمایه دار اصلی نفت و بنیانگذار استاندارد اویل، بزرگترین نام صنعت در طول قرن نوزدهم و اوایل قرن بیستم است. این کتاب داستان راکفلر را از دوران کودکی فروتن تا تبدیل شدنش به ثروتمندترین مرد تاریخ آمریکا و بازنشستگی عجیبش روایت می کند. این بینشی از زندگی شخصی راکفلر، شیوه های تجاری و تلاش های بشردوستانه ارائه می دهد.</p>', '2018-04-19 00:00:00', 5, 62, 'https://images.blinkist.io/images/books/5ad59e99b238e100079b48e7/1_1/470.jpg', '/en/books/titan-en/purchase', 'تیتان', '2023-01-26 20:49:12.165814', '2023-01-26 20:49:12.165814', NULL, 'Titan');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (929, 'استارتاپلند', 'چگونه سه مرد همه چیز را به خطر انداختند تا یک ایده را به یک تجارت جهانی تبدیل کنند', 'چگونه سه مرد همه چیز را به خطر انداختند تا یک ایده را به یک تجارت جهانی تبدیل کنند', 15, 7, 'book', 't', '<p>در <em>Startupland </em>(2015)، میکل سوان داستان اصلی شرکت خود، <em>Zendesk</em> را تعریف می‌کند. او توضیح می‌دهد که چگونه از کار در یک وب‌سایت کوچک در دانمارک به مدیرعاملی یک شرکت تجاری میلیون دلاری در ایالات متحده تبدیل شده است، و بینش‌هایی را که در این راه به‌دست آورده به اشتراک می‌گذارد.</p>', '2015-11-24 00:00:00', 4, 24, 'https://images.blinkist.io/images/books/5653a09463626400071d0000/1_1/470.jpg', '/en/books/startupland-en/purchase', 'استارتاپلند', '2023-01-26 20:49:27.152849', '2023-01-26 20:49:27.152849', NULL, 'Startupland');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (930, 'جهت مختصاتی واقعی شمال', 'رهبری معتبر خود را کشف کنید', 'رهبری معتبر خود را کشف کنید', 20, 8, 'book', 't', '<p><em>True North </em>(2007) راهنمایی برای کشف قطب نمای درونی و وفادار ماندن به خود است، همه اینها در حالی که مهارت هایی را که برای یک رهبر معتبر به آن نیاز دارید، توسعه می دهید. با آشکار کردن ارزش‌ها و انگیزه‌های خود، ابزارهایی را که برای ساختن یک زندگی حرفه‌ای نیاز دارید به دست خواهید آورد.</p>', '2015-08-10 00:00:00', 4, 72, 'https://images.blinkist.io/images/books/55c7c45166643600072c0000/1_1/470.jpg', '/en/books/true-north-en/purchase', 'جهت-مختصاتی-واقعی-شمال', '2023-01-26 20:49:42.460215', '2023-01-26 20:49:42.460215', NULL, 'True North');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (931, 'امپراطور همه بیماری ها', 'بیوگرافی سرطان', 'بیوگرافی سرطان', 22, 9, 'book', 't', '<p><em>امپراطور همه بیماریها </em>نگاهی آموزنده به بیماری کشنده ای است که میلیون ها نفر را تحت تاثیر قرار داده است. سرطان یکی از بزرگ‌ترین چالش‌های پیش روی علم پزشکی امروز است و این کتاب به ما فرصتی نادر می‌دهد تا در مورد هر جنبه‌ای از آن – علل آن، فرآیندهای بیولوژیکی شگفت‌انگیز آن و مبارزه همیشه در حال تغییر ما با آن، از گذشته تا امروز، بیاموزیم. روز.</p>', '2014-11-04 00:00:00', 5, 81, 'https://images.blinkist.io/images/books/545798d43365660008850000/1_1/470.jpg', '/en/books/the-emperor-of-all-maladies-en/purchase', 'امپراطور-همه-بیماری-ها', '2023-01-26 20:49:53.243725', '2023-01-26 20:49:53.243725', NULL, 'The Emperor of All Maladies');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (932, 'Sh*t خود را با هم جمع کنید', 'بدون F * cks با توجه به راهنمای', 'بدون F * cks با توجه به راهنمای', 14, 6, 'book', 't', '<p><em>Get Your Sh*t Together</em> (2016) یک راهنمای صریح و کاربردی برای مرتب کردن زندگی شما است. از مقابله با اضطراب گرفته تا رژیم‌های ورزشی، از رابطه‌تان تا شغلتان، این پلک زدن‌ها به شما کمک می‌کند به اهدافتان برسید و از زندگی‌تان بیشتر بهره ببرید.</p>', '2018-09-04 00:00:00', 4, 402, 'https://images.blinkist.io/images/books/5b8c1ddfb238e100073e7b41/1_1/470.jpg', '/en/books/get-your-sh-star-t-together-en/purchase', 'Sh*t-خود-را-با-هم-جمع-کنید', '2023-01-26 20:50:05.810298', '2023-01-26 20:50:05.810298', NULL, 'Get Your Sh*t Together');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (933, 'چگونه تنها باشیم', 'مدرسه زندگی', 'مدرسه زندگی', 16, 8, 'book', 't', '<p>فرهنگ متمرکز بر اجتماع امروزی، زمان بسیار کمی را به ما می‌دهد و برای مواقعی که ممکن است واقعاً نیاز به تنها بودن داشته باشیم، آمادگی لازم را نداریم. <em>How to Be Alone</em> (2014) به ما نشان می دهد که نیازی به ترس از تنهایی نداریم و تنها بودن فواید و لذت های زیادی دارد. بنابراین نترسید، به تنهایی بروید!</p>', '2016-04-12 00:00:00', 4, 225, 'https://images.blinkist.io/images/books/57096d418b5d6e000300004b/1_1/470.jpg', '/en/books/how-to-be-alone-en/purchase', 'چگونه-تنها-باشیم', '2023-01-26 20:50:21.203438', '2023-01-26 20:50:21.203438', NULL, 'How to Be Alone');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (934, 'خارج از ذهن ما', 'یادگیری خلاق بودن', 'یادگیری خلاق بودن', 15, 6, 'book', 't', '<p><em>Out of Our Minds</em> (2001) نوری را بر دنیای تجاری پرشتاب و دائماً در حال تغییر می تاباند. به طور خاص، بررسی می‌کند که چگونه فناوری پیشرفت کرده و روش کسب و کار ما را تغییر داده است، در حالی که سیستم آموزش عمومی ما در روزهای انقلاب صنعتی گیر کرده است. این نگاهی می‌اندازد به اینکه چه تغییراتی باید انجام شود تا مدارس بتوانند نسل بعدی را برای چالش‌های خلاقانه‌ای که در راه است آماده کنند.</p>', '2017-08-11 00:00:00', 5, 47, 'https://images.blinkist.io/images/books/59888ea0b238e100054c1d81/1_1/470.jpg', '/en/books/out-of-our-minds-en/purchase', 'خارج-از-ذهن-ما', '2023-01-26 20:50:32.575197', '2023-01-26 20:50:32.575197', NULL, 'Out of Our Minds');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (935, 'رایگان', 'چگونه باهوش‌ترین کسب‌وکارهای امروزی با دادن چیزی در ازای هیچ سود می‌برند؟', 'چگونه باهوش‌ترین کسب‌وکارهای امروزی با دادن چیزی در ازای هیچ سود می‌برند؟', 15, 10, 'book', 'f', '<p><em>Free (2010) </em>توضیح می‌دهد که چگونه با ظهور بازار دیجیتال، درک ما از اقتصاد سنتی تغییر می‌کند. این نشان می دهد که چگونه تجارت قرن بیست و یکم به شیوه ای بی سابقه تغییر کرده است و چگونه برای موفقیت باید کاملاً در درک خود از جریان پول تجدید نظر کنیم. این توضیح می دهد که چرا باید باورهای قدیمی خود را رها کنیم و این مدل کسب و کار جدید را بپذیریم، جایی که رایگان باید نقطه شروع باشد. مهمتر از همه، نویسنده نشان می دهد که چگونه هنوز راه های زیادی برای کسب درآمد از «رایگان» وجود دارد.</p>
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (936, 'شیفت', '7 تغییر ذهنی قدرتمند برای کاهش وزن پایدار', '7 تغییر ذهنی قدرتمند برای کاهش وزن پایدار', 23, 8, 'book', 't', '<p><em>تغییر </em>(2021) چگونگی دستیابی به کاهش وزن را با تغییر طرز فکرتان شرح می دهد. با تغییر طرز فکری که در مورد خود و بدنتان دارید، می‌توانید تغییرات باورنکردنی را ایجاد کنید که می‌تواند نه تنها بدن شما، بلکه احساس خود، شادی و ارزش خود را نیز تغییر دهد.</p>', '2022-01-28 00:00:00', 4, 282, 'https://images.blinkist.io/images/books/61eade026cee0700086566c1/1_1/470.jpg', '/en/books/the-shift-en/purchase', 'شیفت', '2023-01-26 20:51:00.426637', '2023-01-26 20:51:00.426637', NULL, 'The Shift');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (937, '7 راز برای سرمایه گذاری مانند وارن بافت', 'تکنیک های بافت سرمایه گذاری ارزشی و استراتژی های اثبات شده او برای موفقیت بلندمدت', 'تکنیک های بافت سرمایه گذاری ارزشی و استراتژی های اثبات شده او برای موفقیت بلندمدت', 24, 7, 'book', 't', '<p><em>7 راز برای سرمایه‌گذاری مانند وارن بافت </em>(2019) خلاصه‌ای مفید از اساسی‌ترین رازهای سرمایه‌گذاری مانند یک حرفه‌ای را ارائه می‌دهد. بسیاری از نکاتی که ارائه می دهد به اصول اولیه سرمایه گذاری ارزشی می پردازد. این رویکرد مدتهاست که متدولوژی وارن بافت برای تعیین اینکه در کدام کسب و کارها سرمایه گذاری شود، بوده است.</p>', '2022-06-03 00:00:00', 5, 327, 'https://images.blinkist.io/images/books/62975fcc6cee0700093666ca/1_1/470.jpg', '/en/books/7-secrets-to-investing-like-warren-buffett-en/purchase', '7-راز-برای-سرمایه-گذاری-مانند-وارن-بافت', '2023-01-26 20:51:17.169057', '2023-01-26 20:51:17.169057', NULL, '7 Secrets to Investing Like Warren Buffett');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (938, 'گول زدن از شیطان', 'راز آزادی و موفقیت', 'راز آزادی و موفقیت', 10, 4, 'book', 't', '<p>در ابتدا در سال 1938 نوشته شد، <em>فرهنگ کردن شیطان </em> (2011) ناپلئون هیل به مدت بیش از هفتاد سال یک نسخه خطی منتشر نشده باقی ماند. کتاب هیل که توسط شارون لچتر ویرایش و حاشیه نویسی شده است، که محتوا را برای خوانندگان معاصر ارائه می کند، خلاصه ای از توصیه هایی در مورد چگونگی موفقیت در زندگی است. خوانندگان اکنون به باورهای شخصی هیل در مورد نیروهایی که ما را از داشتن یک زندگی موفق باز می دارند و اصولی که ما را قادر می سازد بر آن نیروها غلبه کنیم دسترسی کامل دارند.</p>', '2018-07-12 00:00:00', 4, 281, 'https://images.blinkist.io/images/books/5b46be8ab238e1000718d551/1_1/470.jpg', '/en/books/outwitting-the-devil-en/purchase', 'گول-زدن-از-شیطان', '2023-01-26 20:51:27.862048', '2023-01-26 20:51:27.862048', NULL, 'Outwitting the Devil');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (939, 'هنر منطق', 'چگونه در دنیایی که اینطور نیست معنا پیدا کنیم', 'چگونه در دنیایی که اینطور نیست معنا پیدا کنیم', 25, 8, 'book', 't', '<p><em>هنر منطق</em>(2018) به یک سوال مهم می پردازد: چگونه در دنیای پسا حقیقت حرکت کنیم، جایی که اخبار جعلی و رسانه های اجتماعی واقعیت را شکل می دهند؟ یوجنیا چنگ ریاضیدان نشان می دهد که چگونه می توانیم از منطق برای به چالش کشیدن فرضیات خود و جستجوی حقیقت استفاده کنیم. و با کمال تعجب، او به ما نشان می دهد که وقتی منطق را با احساسات ترکیب می کنیم، بهتر می توانیم در دنیای غیرمنطقی خود حرکت کنیم.</p>', '2020-01-30 00:00:00', 4, 168, 'https://images.blinkist.io/images/books/5e2de2a86cee0700062aae1c/1_1/470.jpg', '/en/books/the-art-of-logic-en/purchase', 'هنر-منطق', '2023-01-26 20:51:43.17947', '2023-01-26 20:51:43.17947', NULL, 'The Art of Logic');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (940, 'لحظه رهبری', 'نه داستان واقعی از پیروزی و فاجعه و درس های آنها برای همه ما', 'نه داستان واقعی از پیروزی و فاجعه و درس های آنها برای همه ما', 12, 5, 'book', 't', '<p>در <em>لحظه رهبری </em> (1999) ما رهبران طیف وسیعی از زمینه های مختلف را در سفرهای باورنکردنی آنها همراهی می کنیم و با مشاهده پاسخ آنها به چالش های حیاتی، برخی از اصول اصلی رهبری بزرگ را می آموزیم. . از جستجوی فرصت‌های جدید تا جلب اعتماد تیمتان، این پلک‌ها راهنمای شما برای رهبری خوب در سخت‌ترین زمان‌ها هستند.</p>', '2017-06-15 00:00:00', 4, 28, 'https://images.blinkist.io/images/books/593e64adb238e100051fdde4/1_1/470.jpg', '/en/books/the-leadership-moment-en/purchase', 'لحظه-رهبری', '2023-01-26 20:51:58.894138', '2023-01-26 20:51:58.894138', NULL, 'The Leadership Moment');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (941, 'ماجراجویی در آنتروپوسن', 'سفری به قلب سیاره ای که ما ساختیم', 'سفری به قلب سیاره ای که ما ساختیم', 30, 10, 'book', 't', '<p><em>Adventures in the Anthropocene</em> (2014) به بررسی این موضوع می‌پردازد که چگونه بشر در دهه‌های اخیر این سیاره را چنان تغییر داده است که گفته می‌شود عصر جدید زمین‌شناسی در حال شکل‌گیری است - ما در حال عبور از هولوسن هستیم. به آنتروپوسن یا عصر انسان. نویسنده گایا وینس بررسی می کند که تغییراتی که ما ایجاد کرده ایم واقعاً چه معنایی برای جهان دارند. از جزایر در حال ناپدید شدن گرفته تا زاغه های شهری، از ماهیگیران مکونگ تا قبایل عشایری باستانی در کنیا، این پلک ها داستان رابطه جدید ما با طبیعت و امیدهای ما به آینده را بیان می کنند.</p>', '2020-04-06 00:00:00', 4, 77, 'https://images.blinkist.io/images/books/5e872ddc6cee070007bf0488/1_1/470.jpg', '/en/books/adventures-in-the-anthropocene-en/purchase', 'ماجراجویی-در-آنتروپوسن', '2023-01-26 20:52:14.142264', '2023-01-26 20:52:14.142264', NULL, 'Adventures in the Anthropocene');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (942, 'بازی', 'نفوذ به انجمن مخفی هنرمندان پیکاپ', 'نفوذ به انجمن مخفی هنرمندان پیکاپ', 16, 7, 'book', 't', '<p><em>بازی</em> (2005) به خوانندگان نگاهی درونی به «جامعه پیکاپ» می‌دهد که مردانی که ناامیدند زنان را متقاعد کنند که با آنها بخوابند، در آن حضور می‌یابند. این پلک‌ها توصیه‌های یک استاد برجسته اغواگری و پیامدهای کمتر موفقیت‌های او را به اشتراک می‌گذارند.</p>', '2016-01-08 00:00:00', 3, 202, 'https://images.blinkist.io/images/books/568b8cc2de78c0000700004d/1_1/470.jpg', '/en/books/the-game-en/purchase', 'بازی', '2023-01-26 20:52:25.295164', '2023-01-26 20:52:25.295164', NULL, 'The Game');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (943, 'بازیکنان تاثیرگذار', 'چگونه پیش قدم شوید، بزرگتر بازی کنید و تاثیر خود را چند برابر کنید', 'چگونه پیش قدم شوید، بزرگتر بازی کنید و تاثیر خود را چند برابر کنید', 18, 6, 'book', 't', '<p><em>بازیکنان تأثیرگذار</em> (2021) ویژگی‌های ضروری‌ترین بازیکنان یک تیم یا سازمان را آشکار می‌کند و طرز فکری را که این افراد تأثیرگذار را از بقیه متمایز می‌کند، تجزیه می‌کند. با تکیه بر بینش رهبران برتر صنعت، نشان می دهد که چگونه از رویکردهای استفاده شده توسط متخصصان با نفوذ برای چند برابر کردن تأثیر خود در محل کار استفاده کنید.</p>', '2022-04-25 00:00:00', 4, 256, 'https://images.blinkist.io/images/books/626427e66cee070008778719/1_1/470.jpg', '/en/books/impact-players-en/purchase', 'بازیکنان-تاثیرگذار', '2023-01-26 20:52:41.018165', '2023-01-26 20:52:41.018165', NULL, 'Impact Players');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (944, 'ماشین فروش نهایی', 'کسب و کار خود را با تمرکز بی امان بر روی 12 استراتژی کلیدی شارژ کنید', 'کسب و کار خود را با تمرکز بی امان بر روی 12 استراتژی کلیدی شارژ کنید', 27, 13, 'book', 't', '<p><em></em> <em>نهایی</em> <em>فروش</em> <em>ماشین</em> دوازده استراتژی کلیدی برای بهبود نحوه انجام کسب و کار و همچنین سایر استراتژی‌ها ارائه می‌کند. روش‌ها و ابزارهایی که به شما کمک می‌کنند در همه جنبه‌های کسب‌وکارتان، از مدیریت گرفته تا بازاریابی و فروش، هوشمندانه‌تر و مؤثرتر کار کنید.</p>', '2014-05-20 08:59:15', 4, 72, 'https://images.blinkist.io/images/books/537c616b3465300007210000/1_1/470.jpg', '/en/books/the-ultimate-sales-machine-en/purchase', 'ماشین-فروش-نهایی', '2023-01-26 20:52:56.207989', '2023-01-26 20:52:56.207989', NULL, 'The Ultimate Sales Machine');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (945, 'فراتر از کلمات', 'حیوانات چه فکر می کنند و چه احساسی دارند', 'حیوانات چه فکر می کنند و چه احساسی دارند', 24, 10, 'book', 't', '<p><em>Beyond Words</em>(2015) توضیحی در مورد تمایل دنیای حیوانات به فکر و احساس است. این پلک ها شما را در جوامع پیچیده دنیای طبیعی راهنمایی می کنند و توضیح می دهند که حیوانات چگونه فکر می کنند، احساسات واقعی را تجربه می کنند و یاد می گیرند.</p>', '2016-03-15 00:00:00', 4, 18, 'https://images.blinkist.io/images/books/56e6d43b9854a500070000b0/1_1/470.jpg', '/en/books/beyond-words-en/purchase', 'فراتر-از-کلمات', '2023-01-26 20:53:11.262408', '2023-01-26 20:53:11.262408', NULL, 'Beyond Words');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (946, 'باهوش ترین پسرهای اتاق', 'ظهور شگفت انگیز و سقوط رسوایی انرون', 'ظهور شگفت انگیز و سقوط رسوایی انرون', 24, 10, 'book', 't', '<p><em>باهوش‌ترین پسران اتاق</em> (2003) داستان قابل توجهی از معامله‌گر انرژی انرون را روایت می‌کند – زمانی که پوستر نوآوری بازار در وال استریت بود – و سقوط چشمگیر آن از ارتفاعات استراتوسفر. این پلک‌ها داستان مهیج فریب مالی را به تفصیل شرح می‌دهند، در حالی که شخصیت‌هایی را که فرهنگ شرکتی انرون را ساختند و آن را برای فاجعه آماده کردند، روشن می‌کنند.</p>', '2015-09-23 00:00:00', 5, 55, 'https://images.blinkist.io/images/books/55fff3a3615cd10009000040/1_1/470.jpg', '/en/books/the-smartest-guys-in-the-room-en/purchase', 'باهوش-ترین-پسرهای-اتاق', '2023-01-26 20:53:26.416932', '2023-01-26 20:53:26.416932', NULL, 'The Smartest Guys in the Room');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (947, 'مجذوب کردن', 'هفت محرک شما برای متقاعد کردن و جذب شدن', 'هفت محرک شما برای متقاعد کردن و جذب شدن', 26, 11, 'book', 't', '<p>در <em>Fascinate</em>، نویسنده سالی هاگس‌هد به ما کمک می‌کند پتانسیل خود را برای شیفتگی درک کنیم. <em>Fascinate</em> با توضیح دقیق نحوه عملکرد جذابیت و چگونگی ایجاد آن در دیگران، به زبان واضح، ابزارهایی را در اختیار شما، شرکت و برندتان قرار می دهد که می توانید آن را مجذوب خود کنید. این "هفت محرک جذابیت" می تواند به شما کمک کند تا شانس موفقیت را هم در زندگی شخصی و هم در تجارت افزایش دهید.</p>', '2014-09-02 00:00:00', 4, 62, 'https://images.blinkist.io/images/books/5405d5666632650008240000/1_1/470.jpg', '/en/books/fascinate-en/purchase', 'مجذوب-کردن', '2023-01-26 20:53:42.218447', '2023-01-26 20:53:42.218447', NULL, 'Fascinate');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (948, 'اصل بولزی', 'تسلط بر ارتباطات مبتنی بر قصد برای همکاری، اجرا و موفقیت', 'تسلط بر ارتباطات مبتنی بر قصد برای همکاری، اجرا و موفقیت', 19, 6, 'book', 't', '<p><em>اصل Bullseye</em> (2018) یک راهنمای عملی برای ارتباط مطمئن و شفاف در محیط‌های تجاری معاصر است. این پلک‌ها که همه چیز را از برندسازی شخصی گرفته تا الهام بخشیدن به دیگران و اجرای مؤثر جلسات را پوشش می‌دهد، به شما نشان می‌دهد چگونه خطوط خود را با سبک ارائه دهید و مخاطبان خود را جلب کنید.</p>', '2020-01-27 00:00:00', 4, 95, 'https://images.blinkist.io/images/books/5e2dbeeb6cee0700062aadef/1_1/470.jpg', '/en/books/the-bullseye-principle-en/purchase', 'اصل-بولزی', '2023-01-26 20:53:57.701847', '2023-01-26 20:53:57.701847', NULL, 'The Bullseye Principle');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (949, 'SuperLife', '5 راه حل ساده که شما را سالم، تناسب اندام و برای همیشه عالی می کند', '5 راه حل ساده که شما را سالم، تناسب اندام و برای همیشه عالی می کند', 19, 7, 'book', 't', '<p><em>SuperLife</em> (2015) راهنمای گم شده برای بدن شما است. با تشریح پنج نیروی حیاتی اساسی برای رفاه انسان، توضیح می‌دهد که چگونه می‌توانید از این نیروها برای بهینه‌سازی سلامت خود، احساس شگفت‌انگیز و زندگی طولانی در آینده استفاده کنید.</p>', '2020-10-02 00:00:00', 4, 142, 'https://images.blinkist.io/images/books/5f6dcd536cee070006551da5/1_1/470.jpg', '/en/books/superlife-en/purchase', 'SuperLife', '2023-01-26 20:54:12.954145', '2023-01-26 20:54:12.954145', NULL, 'SuperLife');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (950, 'فروش استراتژیک جدید', 'سیستم فروش منحصربه‌فرد که توسط بهترین شرکت‌های جهان به اثبات رسیده است', 'سیستم فروش منحصربه‌فرد که توسط بهترین شرکت‌های جهان به اثبات رسیده است', 13, 6, 'book', 't', '<p><em>فروش استراتژیک جدید</em> (1995) به شما می آموزد که چگونه فروش را به مثبت ترین و سودمندترین راه برای خود و خریدار خود ببندید. موفقیت بلندمدت در فروش به ایجاد روابط، جلب رضایت مشتریان و شناسایی عوامل کلیدی موثر بر فروش بستگی دارد و این پلک زدن ها شما را در مسیرتان قرار می دهد.</p>', '2016-05-13 00:00:00', 4, 56, 'https://images.blinkist.io/images/books/572f0176a35db30003e6be15/1_1/470.jpg', '/en/books/the-new-strategic-selling-en/purchase', 'فروش-استراتژیک-جدید', '2023-01-26 20:54:28.349325', '2023-01-26 20:54:28.349325', NULL, 'The New Strategic Selling');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (951, 'کودک تمام مغز', '12 استراتژی انقلابی برای پرورش ذهن در حال رشد فرزندتان', '12 استراتژی انقلابی برای پرورش ذهن در حال رشد فرزندتان', 15, 6, 'book', 't', '<p><em>کودک تمام مغز</em> (2011) راهنمای والدین برای درک ذهن کودکان است. این پلک‌ها توضیح می‌دهند که چگونه به فرزندتان کمک کنید تا جنبه‌های مختلف مغزش را ادغام کند و به یک انسان ذهنی خوب تبدیل شود.</p>', '2016-12-28 00:00:00', 5, 321, 'https://images.blinkist.io/images/books/58506baa3e967900044cb0cc/1_1/470.jpg', '/en/books/the-whole-brain-child-en/purchase', 'کودک-تمام-مغز', '2023-01-26 20:54:44.079179', '2023-01-26 20:54:44.079179', NULL, 'The Whole-Brain Child');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (952, 'ارتباطات استراتژیک', 'چهره جدید شبکه سازی در دنیای مشارکتی', 'چهره جدید شبکه سازی در دنیای مشارکتی', 14, 6, 'book', 't', '<p><em>ارتباطات استراتژیک </em>(2015) نکات عملی را در مورد توسعه مهارت‌ها برای تبدیل شدن به یک شبکه‌گر مؤثر ارائه می‌دهد. در دنیایی که به طور فزاینده ای متصل می شود، شبکه هرگز مهمتر از این نبوده است. دریابید که برای موفقیت در محل کار جدید به چه مهارت ها و دانشی نیاز دارید.</p>', '2015-05-26 00:00:00', 4, 47, 'https://images.blinkist.io/images/books/5563a8c064616400071c0000/1_1/470.jpg', '/en/books/strategic-connections-en/purchase', 'ارتباطات-استراتژیک', '2023-01-26 20:55:00.100993', '2023-01-26 20:55:00.100993', NULL, 'Strategic Connections');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (953, 'پول زندگی واقعی', 'راهنمای صادقانه برای کنترل امور مالی', 'راهنمای صادقانه برای کنترل امور مالی', 23, 8, 'book', 't', '<p><em>پول واقعی زندگی </em>(2020) بخشی از خاطرات، بخشی راهنمای مالی است. نویسنده، کلر سیل، از طریق توصیف مبارزه دردناک خود با بدهی، مسیری را برای هر کسی که می‌خواهد به امور مالی خود رسیدگی کند، تعیین می‌کند. او روابط شخصی پیچیده ای را که بسیاری از ما با پول داریم، و همچنین عوامل اجتماعی و اقتصادی که شرایط ما را تعیین می کنند، بررسی می کند.</p>', '2020-08-24 00:00:00', 4, 80, 'https://images.blinkist.io/images/books/5f3f84ff6cee070006d1cb30/1_1/470.jpg', '/en/books/real-life-money-en/purchase', 'پول-زندگی-واقعی', '2023-01-26 20:55:16.199199', '2023-01-26 20:55:16.199199', NULL, 'Real Life Money');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (954, 'آزادی مالی', 'یک مسیر اثبات شده برای تمام پولی که همیشه به آن نیاز خواهید داشت', 'یک مسیر اثبات شده برای تمام پولی که همیشه به آن نیاز خواهید داشت', 20, 8, 'book', 't', '<p><em>آزادی مالی (2019)</em> یک استراتژی مالی ارائه می‌دهد که به شما کمک می‌کند تا ثروت کافی برای زندگی از منافع سرمایه‌گذاری‌های خود تولید کنید و شما را از نیاز به کار رها کند. صرف نظر از وضعیت مالی فعلی یا سطح درآمد خود، می توانید از این استراتژی برای رسیدن به استقلال مالی استفاده کنید تا بتوانید زودتر و شادتر بازنشسته شوید.</p>', '2020-07-02 00:00:00', 4, 369, 'https://images.blinkist.io/images/books/5ef5f7f06cee0700068b1fe8/1_1/470.jpg', '/en/books/financial-freedom-en/purchase', 'آزادی-مالی', '2023-01-26 20:55:31.249697', '2023-01-26 20:55:31.249697', NULL, 'Financial Freedom');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (955, 'مانند یک کارآفرین فکر کنید، مانند یک مدیر عامل رفتار کنید', '50 نکته ضروری که به شما کمک می کند سرپا بمانید، به عقب برگردید و در محل کار پیش بروید', '50 نکته ضروری که به شما کمک می کند سرپا بمانید، به عقب برگردید و در محل کار پیش بروید', 20, 7, 'book', 't', '<p> مردم مسیر مستقیمی را در حرفه خود از تحصیل تا اشتغال ثابت و تا بازنشستگی دنبال می کردند. اما جهان تغییر کرده است، و مهم‌تر از هر زمان دیگری است که بدانیم چگونه سازگار شویم. بورلی ای. جونز در <em>مثل یک کارآفرین فکر کنید، مانند یک مدیر عامل عمل کنید</em> (2015)، بورلی ای. جونز نکات خود را برای تبدیل شدن به یک حرفه ای چابک تر و انعطاف پذیرتر که مسئولیت حرفه خود را بر عهده دارد، بیان می کند.</p>', '2018-12-13 00:00:00', 4, 146, 'https://images.blinkist.io/images/books/5c10e19d6cee0700079356c0/1_1/470.jpg', '/en/books/think-like-an-entrepreneur-act-like-a-ceo-en/purchase', 'مانند-یک-کارآفرین-فکر-کنید،-مانند-یک-مدیر-عامل-رفتار-کنید', '2023-01-26 20:55:46.683598', '2023-01-26 20:55:46.683598', NULL, 'Think Like an Entrepreneur, Act Like a CEO');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (956, 'بي وقفه', 'زندگی من تا کنون', 'زندگی من تا کنون', 28, 13, 'book', 't', '<p><em>Unstoppable</em> (2017) داستان شخصی ماریا شاراپووا، ستاره تنیس مشهور و معتبر بین المللی را روایت می کند. این داستان زندگی او را روایت می‌کند، از زمانی که خانواده‌اش پس از فاجعه چرنوبیل از بلاروس فرار کردند، تا نقل مکان او به ایالات متحده و دستاوردهای شغلی باورنکردنی‌اش. زندگی‌نامه شاراپووا شاهدی بر قدرت اراده قوی و عزم تزلزل ناپذیر است.</p>', '2018-01-12 00:00:00', 5, 30, 'https://images.blinkist.io/images/books/5a535c22b238e100063370ef/1_1/470.jpg', '/en/books/unstoppable-en/purchase', 'بي-وقفه', '2023-01-26 20:56:01.931586', '2023-01-26 20:56:01.931586', NULL, 'Unstoppable');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (957, 'نفرین بزرگی', 'ضد انحصار در عصر طلاکاری جدید', 'ضد انحصار در عصر طلاکاری جدید', 33, 11, 'book', 't', '<p><em>نفرین بزرگی</em> (2018) به موضوعات و سؤالاتی می‌پردازد که در زمان‌های اخیر به‌ویژه مهم شده‌اند. چگونه و چرا بازارها تحت سلطه تعداد انگشت شماری از غول های شرکتی قرار گرفته اند؟ و چه کاری می توانیم در مورد آن انجام دهیم؟ نویسنده برای پاسخ به این سوالات، تاریخ سیاسی، اقتصادی و حقوقی تمرکز اقتصادی را بازگو می کند. در طول مسیر، او خطرات ناشی از آن و چگونگی کاهش آنها را بررسی می کند.</p>', '2019-02-05 00:00:00', 5, 23, 'https://images.blinkist.io/images/books/5c57048a6cee070008f61115/1_1/470.jpg', '/en/books/the-curse-of-bigness-en/purchase', 'نفرین-بزرگی', '2023-01-26 20:56:17.693085', '2023-01-26 20:56:17.693085', NULL, 'The Curse of Bigness');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (958, 'انسان ساختن کار', 'چگونه شرکت های انسان محور آینده کار و جهان را تغییر می دهند', 'چگونه شرکت های انسان محور آینده کار و جهان را تغییر می دهند', 22, 7, 'book', 't', '<p><em>Making Work Human </em>(2020) یک نقشه راه برای ساختن محل کار آینده بر اساس ارزش های مثبت انسانی مانند اجتماع، ارتباط و تعلق است. پیشگامان شرکت شناسایی اجتماعی Workhuman با تکیه بر حجم وسیعی از داده ها و با استفاده از تجزیه و تحلیل های عمیق، توضیح می دهند که چگونه فرهنگ کاری قدردانی، مردم را شادتر و سالم تر می کند و در عین حال بهره وری و عملکرد را افزایش می دهد.</p>', '2020-12-22 00:00:00', 4, 40, 'https://images.blinkist.io/images/books/5fda37d86cee07000670aeab/1_1/470.jpg', '/en/books/making-work-human-en/purchase', 'انسان-ساختن-کار', '2023-01-26 20:56:34.164565', '2023-01-26 20:56:34.164565', NULL, 'Making Work Human');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (959, 'بودا و بداس', 'هنر معنوی راز موفقیت در کار', 'هنر معنوی راز موفقیت در کار', 29, 9, 'book', 't', '<p><em>The Buddha and the Badass </em>(2020) چگونگی تسلط بر کار و زندگی را با استفاده از آگاهی عمیق از خود و یادگیری نحوه تأثیرگذاری می‌گوید. این پلک‌ها گام‌های عملی برای آوردن معنای واقعی به کار شما، انجام مأموریت‌های جسورانه در کنار دیگران، و طراحی و زندگی ایده‌آل شما ارائه می‌کنند.</p>', '2020-09-12 00:00:00', 4, 371, 'https://images.blinkist.io/images/books/5f5779556cee0700066abc4d/1_1/470.jpg', '/en/books/the-buddha-and-the-badass-en/purchase', 'بودا-و-بداس', '2023-01-26 20:56:45.134152', '2023-01-26 20:56:45.134152', NULL, 'The Buddha and the Badass');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (960, 'قدرت توجه', 'آنچه که بهترین رهبران می بینند', 'آنچه که بهترین رهبران می بینند', 21, 10, 'book', 't', '<p>هنگامی که روزانه درگیر می‌شویم، اغلب چیزهایی را نمی‌بینیم که دقیقاً در مقابل ما هستند. گاهی اوقات ما به اندازه کافی توجه نمی کنیم؛ گاهی اوقات ما به طور ناخودآگاه خود را نسبت به چیزها "کور" می کنیم. <em>قدرت توجه کردن</em> در مورد یادگیری <em>توجه</em> است، مهارتی که در تصمیم گیری های مهم و همچنین برای رهبر عالی بودن بسیار مهم است. </p>', '2021-05-11 15:48:48.675', 4, 76, 'https://images.blinkist.io/images/books/608a732d6cee070008a8ed80/1_1/470.jpg', '/en/books/the-power-of-noticing-en/purchase', 'قدرت-توجه', '2023-01-26 20:57:01.625092', '2023-01-26 20:57:01.625092', NULL, 'The Power of Noticing');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (961, 'چه چنگالی می خورید؟', 'یک برنامه اقدام برای شربت خانه و بشقاب شما', 'یک برنامه اقدام برای شربت خانه و بشقاب شما', 16, 7, 'book', 't', '<p><em>چه می خورید چنگال؟</em> (2014) ترکیبات پنهان موجود در غذایی که هر روز می خورید و تأثیرات مشکل آفرینی که می توانند روی بدن و ذهن شما داشته باشند را نشان می دهد. این پلک ها به شما برنامه ای می دهد که چگونه رابطه خود را با غذا تغییر دهید و با خوردن بهتر و آگاهانه تر، سالم تر شوید.</p>', '2016-04-01 00:00:00', 4, 16, 'https://images.blinkist.io/images/books/56faa6c6df814200070000a0/1_1/470.jpg', '/en/books/what-the-fork-are-you-eating-en/purchase', 'چه-چنگالی-می-خورید؟', '2023-01-26 20:57:16.945843', '2023-01-26 20:57:16.945843', NULL, 'What the Fork Are You Eating?');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (962, 'فراوانی', 'مسیر درونی به سوی ثروت', 'مسیر درونی به سوی ثروت', 28, 5, 'book', 't', '<p><em>فراوانی </em>(2022) راه جدیدی برای رهایی شما از زندگی کمبود و کمبود ارائه می دهد. با استفاده از تکنیک‌های مدیتیشن آن، می‌توانید زندگی خود را از زندگی‌ای که با محدودیت‌ها همراه است به زندگی‌ای تبدیل کنید که هیچ نمی‌خواهید.</p>', '2022-06-16 00:00:00', 5, 365, 'https://images.blinkist.io/images/books/62a9f5d76cee07000892aa99/1_1/470.jpg', '/en/books/abundance-en-deepak-chopra/purchase', 'فراوانی', '2023-01-26 20:57:27.840118', '2023-01-26 20:57:27.840118', NULL, 'Abundance');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (963, 'پرونده علیه شکر', 'عشق ما به شکر ما را می کشد', 'عشق ما به شکر ما را می کشد', 15, 6, 'book', 't', '<p><em>موضوع علیه شکر </em>(2016) نگاهی انتقادی به این دارد که چگونه صنعت شکر با وجود اینکه داده‌های پزشکی نشان می‌دهد که می‌تواند برای سلامتی ما مضر باشد، همیشه قوی‌تر شده است. دریابید که چگونه این اتفاق افتاد و چگونه منتقدان با وجود شواهد قاطع مبنی بر اینکه این یک عنصر می‌تواند با بسیاری از جدی‌ترین بیماری‌های دنیای غرب مرتبط باشد، سکوت و تمسخر شده‌اند.</p>', '2017-08-08 00:00:00', 5, 102, 'https://images.blinkist.io/images/books/5984edabb238e100054c1cf8/1_1/470.jpg', '/en/books/the-case-against-sugar-en/purchase', 'پرونده-علیه-شکر', '2023-01-26 20:57:39.075698', '2023-01-26 20:57:39.075698', NULL, 'The Case Against Sugar');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (964, 'مقیاس موفقیت', 'بینش تخصصی در مورد رشد کسب و کار شما', 'بینش تخصصی در مورد رشد کسب و کار شما', 17, 6, 'book', 't', '<p><em>مقیاس موفقیت </em>(2021) راهنمایی برای تبدیل کسب و کار کوچک شما به یک شرکت بسیار بزرگتر و موفق تر از امروز است. از تامین مالی جمعی گرفته تا شرح شغل، زیر و بم - و بالا و پایین - افزایش هر شرکتی را پوشش می دهد.</p>', '2021-09-10 00:00:00', 4, 152, 'https://images.blinkist.io/images/books/6138793a6cee07000840e923/1_1/470.jpg', '/en/books/scale-for-success-en/purchase', 'مقیاس-موفقیت', '2023-01-26 20:57:54.186138', '2023-01-26 20:57:54.186138', NULL, 'Scale for Success');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (965, 'نظم بیرونی، آرامش درونی', 'شلوغ و سازماندهی کنید تا فضای بیشتری برای شادی ایجاد کنید', 'شلوغ و سازماندهی کنید تا فضای بیشتری برای شادی ایجاد کنید', 16, 6, 'book', 't', '<p><em>نظم بیرونی، آرامش درونی</em> (2019) توضیح می‌دهد که چگونه می‌توانید خانه‌تان را شلوغ کنید و آن را مرتب و زیبا نگه دارید. این پلک‌ها با بررسی دلایلی که چرا محیط‌های منظم برای سلامتی ما بسیار مهم هستند، نکات و توصیه‌های عملی در مورد چگونگی غلبه بر آشفتگی برای همیشه ارائه می‌دهند.</p>', '2019-03-20 00:00:00', 4, 154, 'https://images.blinkist.io/images/books/5c90af4c6cee070007feb6f4/1_1/470.jpg', '/en/books/outer-order-inner-calm-en/purchase', 'نظم-بیرونی،-آرامش-درونی', '2023-01-26 20:58:05.326532', '2023-01-26 20:58:05.326532', NULL, 'Outer Order, Inner Calm');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (966, 'مینیمالیسم دیجیتال', 'انتخاب یک زندگی متمرکز در دنیای پر سر و صدا', 'انتخاب یک زندگی متمرکز در دنیای پر سر و صدا', 20, 8, 'book', 't', '<p><em>مینیمالیسم دیجیتال</em> (2018) یک راهنمای عملی برای پیمایش در چشم‌انداز رسانه‌های امروزی است، جایی که شرکت‌های میلیارد دلاری در تلاش هستند تا چشمان شما را تا حد امکان به پلتفرم‌های خود بچسبانند. خوشبختانه، شک و تردیدهای فزاینده ای در مورد فناوری جدید و رسانه های دیجیتال وجود دارد. مردم مشتاق هستند که استقلال خود را بازیابند و در حالی که در آن هستند، زندگی رضایت‌بخش‌تر و سالم‌تری داشته باشند. با استفاده از این ابزارها و روش‌ها، شما نیز می‌توانید تمرکز و بهره‌وری ناشی از عقب‌نشینی از فناوری جدید را دوباره به دست آورید.</p>', '2019-02-26 00:00:00', 5, 620, 'https://images.blinkist.io/images/books/5c724d9a6cee070008ba6580/1_1/470.jpg', '/en/books/digital-minimalism-en/purchase', 'مینیمالیسم-دیجیتال', '2023-01-26 20:58:20.761451', '2023-01-26 20:58:20.761451', NULL, 'Digital Minimalism');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (967, 'رژیم غذایی پگان', 'Paleo و Vegan را با هم ترکیب کنید تا همیشه تناسب اندام، شاد و سالم بمانید', 'Paleo و Vegan را با هم ترکیب کنید تا همیشه تناسب اندام، شاد و سالم بمانید', 23, 8, 'book', 't', '<p><em>رژیم غذایی پگان</em>(2021) یک رویکرد ساده و علم محور برای تغذیه است که بهترین دو رژیم غذایی محبوب - گیاهخواری و پالئو را با هم ترکیب می کند. نتیجه؟ روشی برای خوردن که سبزیجات را پیش‌زمینه می‌کند، از کربوهیدرات‌های تصفیه شده اجتناب می‌کند و از چربی‌ها و فرآورده‌های حیوانی اخلاقی استفاده می‌کند. مزایای این رژیم برای خود صحبت می کند: کلسترول پایین تر، سلامت روده بهتر، انرژی بیشتر و شادی بیشتر. </p>', '2021-04-21 00:00:00', 4, 154, 'https://images.blinkist.io/images/books/607d9d2c6cee070007991263/1_1/470.jpg', '/en/books/the-pegan-diet-en/purchase', 'رژیم-غذایی-پگان', '2023-01-26 20:58:36.52897', '2023-01-26 20:58:36.52897', NULL, 'The Pegan Diet');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1326, 'شادی آور', 'قدرت شگفت انگیز چیزهای معمولی برای ایجاد شادی خارق العاده', 'قدرت شگفت انگیز چیزهای معمولی برای ایجاد شادی خارق العاده', 23, 8, 'book', 't', '<p><em>Joyful</em> (2018) جنبه هایی از رنگ، شکل، بازیگوشی و هوس را در بر می گیرد که ما را در زندگی روزمره احاطه کرده اند. این پلک زدن ها یک مورد مثبت برای نقشی است که طراحی و معماری می توانند در شادتر و شادتر کردن زندگی ایفا کنند.</p>', '2019-06-27 00:00:00', 4, 62, 'https://images.blinkist.io/images/books/5d1382216cee070007d74ca9/1_1/470.jpg', '/en/books/joyful-en/purchase', 'شادی-آور', '2023-01-27 02:09:54.635152', '2023-01-27 02:09:54.635152', NULL, 'Joyful');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (968, 'صداقت رادیکال', 'چگونه با گفتن حقیقت زندگی خود را متحول کنید', 'چگونه با گفتن حقیقت زندگی خود را متحول کنید', 22, 6, 'book', 't', '<p><em>صداقت رادیکال </em> (برای اولین بار در سال 1993 منتشر شد، این نسخه 2004) راهنمایی برای کمک به شما برای گفتن حقیقت است. همه ما همیشه دروغ می گوییم، و تنها از طریق صداقت بسیار است که می توانیم از اخلاق گرایی که ما را احاطه کرده است فرار کنیم و واقعاً خودمان باشیم.</p>', '2021-08-09 00:00:00', 3, 293, 'https://images.blinkist.io/images/books/610d26bc6cee0700074275cb/1_1/470.jpg', '/en/books/radical-honesty-en/purchase', 'صداقت-رادیکال', '2023-01-26 20:58:51.559081', '2023-01-26 20:58:51.559081', NULL, 'Radical Honesty');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (969, 'سبک کار', 'انقلابی برای رفاه، بهره وری و جامعه', 'انقلابی برای رفاه، بهره وری و جامعه', 21, 4, 'book', 't', '<p><em>سبک کار: انقلابی برای رفاه، بهره‌وری و جامعه</em>(2022) مفهوم <em>سبک کاری</em> را معرفی می‌کند: آزادی انتخاب زمان و مکان کار. با بررسی تاریخ منسوخ شده استاندارد 9 تا 5 هفته کاری در پرتو عصر دیجیتال مدرن، نویسندگان پایه و اساس یک روش کار فردی و مستقل را ایجاد کردند. </p>', '2022-11-16 00:00:00', 4, 154, 'https://images.blinkist.io/images/books/63735d0f73bf6d000e2d58a6/1_1/470.jpg', '/en/books/workstyle-en/purchase', 'سبک-کار', '2023-01-26 20:59:08.665105', '2023-01-26 20:59:08.665105', NULL, 'Workstyle');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (970, 'رفاه بدون رشد', 'اقتصاد برای یک سیاره متناهی', 'اقتصاد برای یک سیاره متناهی', 16, 9, 'book', 'f', '<p><em>شکوفایی</em> <em>بدون</em> <em>رشد</em> استدلال می‌کند که مدل فعلی رشد اقتصادی ما پایدار نیست: منابع سیاره ما را تا حدی تحت فشار قرار می‌دهد. و باعث تغییرات آب و هوایی، آسیب های زیست محیطی و آسیب های روانی می شود. جکسون چشم‌اندازی برای یک مدل اقتصادی پایدار و زیست‌محیطی ارائه می‌کند که به جای رشد بر رفاه عمومی تمرکز دارد، و راه‌هایی را که از طریق آنها ممکن است این گذار محقق شود، بررسی می‌کند.</p>', '2014-06-24 00:00:00', 5, 30, 'https://images.blinkist.io/images/books/53a889c86665630007000000/1_1/470.jpg', '/en/books/prosperity-without-growth-en/purchase', 'رفاه-بدون-رشد', '2023-01-26 20:59:24.010828', '2023-01-26 20:59:24.010828', NULL, 'Prosperity without Growth');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (971, 'آن قورباغه را بخور!', '21 روش عالی برای توقف تعلل و انجام کارهای بیشتر در زمان کمتر', '21 روش عالی برای توقف تعلل و انجام کارهای بیشتر در زمان کمتر', 13, 6, 'book', 't', '<p><em>قورباغه را بخور!</em> همه چیز درباره غلبه بر تعلل و یادگیری مدیریت زمان است. طبیعی است که در کار احساس غرق شدن کنید، اما وقتی یاد بگیرید که «قورباغه هایتان را بخورید» - به این معنی که ابتدا مهم ترین وظایف خود را انجام دهید - کارآمدتر کار خواهید کرد و همچنین شادتر خواهید بود.</p>', '2015-05-15 00:00:00', 4, 544, 'https://images.blinkist.io/images/books/55512f536332630007fd0000/1_1/470.jpg', '/en/books/eat-that-frog-en/purchase', 'آن-قورباغه-را-بخور!', '2023-01-26 20:59:35.200472', '2023-01-26 20:59:35.200472', NULL, 'Eat That Frog!');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (972, 'در کافه اگزیستانسیالیست', 'کوکتل آزادی، بودن و زردآلو', 'کوکتل آزادی، بودن و زردآلو', 27, 9, 'book', 't', '<p><em>در کافه اگزیستانسیالیسم</em> (2016) تولد اگزیستانسیالیسم در اوایل قرن بیستم را بازگو می کند. این کتاب هم یک بیوگرافی و هم یک متن فلسفی است که داستان های تک تک فیلسوفان و همچنین ایده های آنها را بیان می کند. مهمتر از همه، بررسی می‌کند که چگونه پرسش‌های بزرگ فلسفی می‌توانند زندگی ما و نحوه زندگی ما را روشن کنند.</p>', '2019-03-08 00:00:00', 5, 155, 'https://images.blinkist.io/images/books/5c7fc3ce6cee07000722a7c3/1_1/470.jpg', '/en/books/at-the-existentialist-cafe-en/purchase', 'در-کافه-اگزیستانسیالیست', '2023-01-26 20:59:50.428838', '2023-01-26 20:59:50.428838', NULL, 'At The Existentialist Café');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (973, 'هم رقابتی', 'یک ذهنیت انقلابی که ترکیبی از رقابت و همکاری است. استراتژی نظریه بازی که بازی کسب و کار را تغییر می دهد', 'یک ذهنیت انقلابی که ترکیبی از رقابت و همکاری است. استراتژی نظریه بازی که بازی کسب و کار را تغییر می دهد', 16, 7, 'book', 't', '<p><em>Co-opetition</em> (1996) تئوری بازی را با استراتژی کسب و کار ترکیب می کند و یک نقشه راه برای چگونگی ایجاد یک سرمایه گذاری موفق ارائه می دهد. نویسندگان توضیح می‌دهند که چگونه اداره یک کسب‌وکار دقیقاً مانند انجام یک بازی است: شامل تسلط بر قوانین، شناخت بازیکنان و ارزشی که به ارمغان می‌آورند، درک رویکردهای تاکتیکی و توانایی دیدن تصویر بزرگ است. با وجود این عناصر، می توانید از آنها برای بهبود موقعیت خود در بازی کسب و کار استفاده کنید.</p>', '2015-09-28 00:00:00', 4, 19, 'https://images.blinkist.io/images/books/560864e38a14e60009000000/1_1/470.jpg', '/en/books/co-opetition-en/purchase', 'هم-رقابتی', '2023-01-26 21:00:05.780549', '2023-01-26 21:00:05.780549', NULL, 'Co-opetition ');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (974, 'اقتصاد شما', 'کارآفرین درونی خود را کشف کنید و زندگی خود را در رکود ثابت کنید', 'کارآفرین درونی خود را کشف کنید و زندگی خود را در رکود ثابت کنید', 11, 5, 'book', 't', '<p><em>The Economy Of You</em> (2014) راهنمای شما برای ایجاد و حفظ منابع درآمد اضافی است. از جستجوی فرصت‌ها و توسعه شبکه‌ها گرفته تا یافتن مخاطبان و مواجهه با چالش‌های جدید، این پلک‌ها ابزارهایی را در اختیار شما قرار می‌دهند که برای انجام کاری که دوست دارید بدون ترک شغل تمام وقت خود به آن نیاز دارید.</p>', '2016-03-10 00:00:00', 4, 12, 'https://images.blinkist.io/images/books/56e0315e26ea840007000054/1_1/470.jpg', '/en/books/the-economy-of-you-en/purchase', 'اقتصاد-شما', '2023-01-26 21:00:21.12628', '2023-01-26 21:00:21.12628', NULL, 'The Economy of You');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (975, 'سرنوشت غذا', 'آنچه در دنیای بزرگتر، داغتر و هوشمندتر خواهیم خورد', 'آنچه در دنیای بزرگتر، داغتر و هوشمندتر خواهیم خورد', 20, 6, 'book', 't', '<p><em>سرنوشت غذا</em> (2019) به دنیایی که به سرعت در حال تغییر است و این سوال که چگونه جمعیت رو به رشد خود را تغذیه کنیم می‌پردازد. آیا می توان یک منبع غذایی تمیز و مقاوم در برابر آب و هوا تولید کرد که برای رفع نیازهای ما کافی باشد؟ <em>سرنوشت غذا</em> به بررسی نیازهای تکنولوژیکی و جامعه شناختی تغذیه جهان می پردازد. </p>', '2020-04-02 00:00:00', 4, 55, 'https://images.blinkist.io/images/books/5e8337d36cee0700060257b4/1_1/470.jpg', '/en/books/the-fate-of-food-en/purchase', 'سرنوشت-غذا', '2023-01-26 21:00:36.430773', '2023-01-26 21:00:36.430773', NULL, 'The Fate of Food');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (976, 'وقتی بدن نه می گوید', 'هزینه استرس پنهان', 'هزینه استرس پنهان', 26, 8, 'book', 't', '<p><em>وقتی بدن نه می گوید </em>(2003) ارتباطات پنهان بین سلامت روان و بیماری جسمی را بررسی می کند. علم پزشکی مدرن اغلب سعی می کند به ما اطمینان دهد که ذهن و بدن ما کاملاً از هم جدا هستند - در حالی که در واقعیت، آنها عمیقاً به هم مرتبط هستند. استرس‌های ذهنی اغلب به‌عنوان بیماری‌های فیزیولوژیکی، اختلالات و شرایط مزمن در بدن ظاهر می‌شوند که سلامت و رفاه ما را به خطر می‌اندازند.</p>', '2020-10-09 00:00:00', 5, 342, 'https://images.blinkist.io/images/books/5f7c2e746cee070006f71a02/1_1/470.jpg', '/en/books/when-the-body-says-no-en/purchase', 'وقتی-بدن-نه-می-گوید', '2023-01-26 21:00:52.125241', '2023-01-26 21:00:52.125241', NULL, 'When the Body Says No');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (977, 'تجارت برای بوهمیایی ها', 'خوب زندگی کن، پول در بیاور', 'خوب زندگی کن، پول در بیاور', 21, 8, 'book', 't', '<p><em>Business for Bohemians</em> (2016) به افراد خلاق و آزاده راه دیگری برای امرار معاش می دهد. ترکیب توصیه‌های عملی، تأملات فلسفی و حکایات زندگی‌نامه‌ای، نشان می‌دهد که می‌توانید بدون قربانی کردن ارزش‌های غیرمعمول خود وارد دنیای تجارت شوید. </p>', '2020-04-26 00:00:00', 4, 71, 'https://images.blinkist.io/images/books/5e9e2bc96cee070006833323/1_1/470.jpg', '/en/books/business-for-bohemians-en/purchase', 'تجارت-برای-بوهمیایی-ها', '2023-01-26 21:01:08.490399', '2023-01-26 21:01:08.490399', NULL, 'Business for Bohemians');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (978, 'تغییر مدیریت پروژه', 'پارادایم ضروری برای تبدیل برنامه ریزی استراتژیک خود به عمل', 'پارادایم ضروری برای تبدیل برنامه ریزی استراتژیک خود به عمل', 22, 6, 'book', 't', '<p><em>تغییر مدیریت پروژه </em>(2021) تصمیم دارد به تعدادی از مشکلات در دنیای مدیریت پروژه رسیدگی کند. از برنامه‌ریزی استراتژیک گرفته تا زمان‌بندی و بودجه‌بندی، به سمت پروژه‌های هموارتر و موفق‌تر اشاره می‌کند.</p>', '2021-07-01 00:00:00', 4, 77, 'https://images.blinkist.io/images/books/60d9f03c6cee0700074d86bb/1_1/470.jpg', '/en/books/transforming-project-management-en/purchase', 'تغییر-مدیریت-پروژه', '2023-01-26 21:01:23.741151', '2023-01-26 21:01:23.741151', NULL, 'Transforming Project Management');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (979, 'یوگای نفس', 'راهنمای گام به گام پرانایاما', 'راهنمای گام به گام پرانایاما', 22, 7, 'book', 't', '<p><em>یوگای نفس</em>(2002) مزایای سلامتی تنفس کارآمد را تشریح می‌کند و به بررسی این موضوع می‌پردازد که چرا بسیاری از ما به بهترین شکل نفس نمی‌کشیم. این پلک‌ها همچنین تمرین‌های ساده یوگا را توصیف می‌کنند که به شما کمک می‌کند نفس خود را کنترل کنید و حالت ذهنی آرام‌تری را ایجاد کنید. </p>', '2020-08-06 00:00:00', 4, 92, 'https://images.blinkist.io/images/books/5f240b2e6cee070006bddc41/1_1/470.jpg', '/en/books/the-yoga-of-breath-en/purchase', 'یوگای-نفس', '2023-01-26 21:01:38.764271', '2023-01-26 21:01:38.764271', NULL, 'The Yoga of Breath');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (980, 'شادی در صورت تقاضا', 'هنر کشف شادی درون', 'هنر کشف شادی درون', 18, 7, 'book', 't', '<p><em>Joy on Demand</em> (2016) راهنمایی برای یافتن آرامش درونی، آرامش و شادی از طریق تمرین باستانی مدیتیشن است. این پلک ها شما را از طریق یک برنامه ساده و ابتدایی راهنمایی می کند که لحظات بدبختی را به دریچه های امید تبدیل می کند و در نهایت شما را به سمت شادی واقعی و پایدار راهنمایی می کند.</p>', '2017-11-17 00:00:00', 4, 69, 'https://images.blinkist.io/images/books/5a098a54b238e1000655ceef/1_1/470.jpg', '/en/books/joy-on-demand-en/purchase', 'شادی-در-صورت-تقاضا', '2023-01-26 21:01:54.500534', '2023-01-26 21:01:54.500534', NULL, 'Joy on Demand');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (981, 'تفکر جعبه سیاه', 'حقیقت شگفت انگیز درباره موفقیت (و چرا برخی از مردم هرگز از اشتباهات درس نمی گیرند)', 'حقیقت شگفت انگیز درباره موفقیت (و چرا برخی از مردم هرگز از اشتباهات درس نمی گیرند)', 13, 6, 'book', 't', '<p><em>تفکر جعبه سیاه</em> (2015) راه‌هایی را بررسی می‌کند که در آن شکست، علی‌رغم تمام شرم و درد ناشی از آن، در واقع یکی از بزرگترین دارایی‌های ما است. <em>تفکر جعبه سیاه</em> پر از نکات عملی در مورد چگونگی ایجاد یک رابطه سالم و سازنده با شکست، شما را در مسیر موفقیت قرار می دهد.</p>', '2016-01-04 00:00:00', 4, 106, 'https://images.blinkist.io/images/books/568a66f18944a6000700002d/1_1/470.jpg', '/en/books/black-box-thinking-en/purchase', 'تفکر-جعبه-سیاه', '2023-01-26 21:02:10.85772', '2023-01-26 21:02:10.85772', NULL, 'Black Box Thinking');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (982, 'آماده برای هر چیزی', '52 اصل بهره وری برای کار و زندگی', '52 اصل بهره وری برای کار و زندگی', 15, 9, 'book', 'f', '<p>در <em>آماده</em> <em>برای</em> <em>هر چیزی</em>، کارشناس بهره وری دیوید آلن تکنیک های مختلفی را ارائه می دهد که به شما کمک می کند ذهن و میز خود را پاک کنید. با چیزهایی که شما را عقب نگه می دارد، و برای تمام پروژه های خلاقانه، چالش برانگیز و با ارزشی که سر راهتان قرار می گیرد آماده شوید. علاوه بر این، این کتاب به عنوان مقدمه ای بر اصول کلی سیستم بهره وری پیشگام آلن عمل می کند.</p>', '2014-05-13 13:52:07', 4, 64, 'https://images.blinkist.io/images/books/537230ab6264390007150000/1_1/470.jpg', '/en/books/ready-for-anything-en/purchase', 'آماده-برای-هر-چیزی', '2023-01-26 21:02:21.731278', '2023-01-26 21:02:21.731278', NULL, 'Ready for Anything');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (983, 'هنر جنگ', 'استراتژی نظامی کلاسیک برای سیاست، تجارت و زندگی روزمره', 'استراتژی نظامی کلاسیک برای سیاست، تجارت و زندگی روزمره', 14, 7, 'book', 't', '<p>هزاران سال قدمت،<em> هنر جنگ</em> یک رساله نظامی چینی است که کار قطعی تاکتیک‌ها و استراتژی‌های نظامی در نظر گرفته می‌شود. این تاکتیک‌های نظامی و همچنین استراتژی تجاری و قانونی در شرق و غرب تأثیر زیادی گذاشته است. رهبرانی مانند ژنرال داگلاس مک آرتور و مائو زدونگ از آن الهام گرفته اند.</p>', '2013-06-12 00:00:00', 4, 611, 'https://images.blinkist.io/images/books/519b9614e4b034cd5017bab8/1_1/470.jpg', '/en/books/the-art-of-war-en/purchase', 'هنر-جنگ', '2023-01-26 21:02:32.437219', '2023-01-26 21:02:32.437219', NULL, 'The Art of War');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (984, 'به وحشی', 'گزارشی تزلزل ناپذیر از زندگی و مرگ خارق العاده کریستوفر مک کندلس', 'گزارشی تزلزل ناپذیر از زندگی و مرگ خارق العاده کریستوفر مک کندلس', 21, 7, 'book', 't', '<p><em>Into the Wild </em> (1996) روایتی است بی وقفه از زندگی و مرگ خارق العاده کریستوفر مک کندلس. مک کندلس زندگی ممتاز خود را رها کرد و در غرب آمریکا پرسه زد. او سخت زندگی کرد، دوستان پیدا کرد و ریسک کرد - و برای هیجان ماجراجویی، بهای نهایی را پرداخت.</p>', '2020-11-22 00:00:00', 4, 43, 'https://images.blinkist.io/images/books/5fae601a6cee070007d20e1e/1_1/470.jpg', '/en/books/into-the-wild-en/purchase', 'به-وحشی', '2023-01-26 21:02:47.98228', '2023-01-26 21:02:47.98228', NULL, 'Into the Wild');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (985, 'ساخت یک مدیر', 'وقتی همه به شما نگاه می کنند چه باید کرد', 'وقتی همه به شما نگاه می کنند چه باید کرد', 17, 6, 'book', 't', '<p><em>Making of a Manage</em>r (2019) به بررسی کارهایی می‌پردازد که مدیران جدید می‌توانند در سه ماه اول و بعد از آن انجام دهند تا مطمئن شوند تیمشان نتایج عالی دریافت می‌کند. از جلسات گرفته تا استخدام و مدیریت یک تیم در حال رشد، این پلک ها فرصت ها و مشکلاتی را که همه مدیران جدید با آن روبرو هستند بررسی می کند و نشان می دهد که مدیران بزرگ ساخته شده اند، نه متولد شده اند.</p>', '2019-04-17 00:00:00', 4, 162, 'https://images.blinkist.io/images/books/5cb4c9926cee07000700673d/1_1/470.jpg', '/en/books/the-making-of-a-manager-en/purchase', 'ساخت-یک-مدیر', '2023-01-26 21:03:03.390742', '2023-01-26 21:03:03.390742', NULL, 'The Making of a Manager');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (986, '10 قانون اختراع مجدد شغلی', 'مهارت های ضروری بقا برای هر اقتصادی', 'مهارت های ضروری بقا برای هر اقتصادی', 20, 10, 'book', 't', '<p><em>10 قانون اختراع مجدد شغلی </em>(2010) مهارت های بقای شغلی را که برای اقتصاد قرن بیست و یکم نیاز دارید به شما آموزش می دهد. مهم نیست که در چه صنعتی می خواهید وارد شوید، این کتاب به شما کمک می کند تا یک نقشه راه موفق برای رسیدن به هدف خود ایجاد کنید.</p>', '2015-11-18 00:00:00', 4, 32, 'https://images.blinkist.io/images/books/564a044466343100076e0000/1_1/470.jpg', '/en/books/the-10-laws-of-career-reinvention-en/purchase', '10-قانون-اختراع-مجدد-شغلی', '2023-01-26 21:03:19.434572', '2023-01-26 21:03:19.434572', NULL, 'The 10 Laws of Career Reinvention');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (987, 'میلیونر خودکار', 'یک برنامه قدرتمند یک مرحله ای برای زندگی و ثروتمند شدن', 'یک برنامه قدرتمند یک مرحله ای برای زندگی و ثروتمند شدن', 13, 7, 'book', 'f', '<p><em>میلیونر خودکار</em> (2003) یک راهنمای بسیار کاربردی و مفید است که نشان می‌دهد چگونه هر کسی می‌تواند در طول زمان درآمد متوسطی را به ثروت تبدیل کند. نویسنده دیوید باخ ثابت می کند که کسب یک میلیون دلار به هیچ جادوگری مالی پیچیده یا حتی بودجه ای منظم برای خرج کردن نیاز ندارد - تنها چیزی که لازم است یک برنامه ساده یک مرحله ای است!</p>', '2018-10-03 00:00:00', 4, 146, 'https://images.blinkist.io/images/books/5bb28db6862c4300075b36e1/1_1/470.jpg', '/en/books/the-automatic-millionaire-en/purchase', 'میلیونر-خودکار', '2023-01-26 21:03:35.052531', '2023-01-26 21:03:35.052531', NULL, 'The Automatic Millionaire');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (988, 'مانیفست قهرمان روزمره', 'مثبت بودن خود را فعال کنید، بهره وری خود را به حداکثر برسانید، به جهان خدمت کنید', 'مثبت بودن خود را فعال کنید، بهره وری خود را به حداکثر برسانید، به جهان خدمت کنید', 19, 5, 'book', 't', '<p><em>مانیفست هر روز قهرمان </em>(2021) آغازگر چگونگی تبدیل شدن به قهرمان زندگی خود است. این مملو از طرح‌های دقیق است که با مقالات کوتاه، حکایت‌ها و حتی شعر در هم آمیخته است تا به شما کمک کند شادتر، سازنده‌تر و موفق‌تر شوید.</p>', '2022-10-31 00:00:00', 4, 479, 'https://images.blinkist.io/images/books/635a8e9349472e0009c489d4/1_1/470.jpg', '/en/books/the-everyday-hero-manifesto-en/purchase', 'مانیفست-قهرمان-روزمره', '2023-01-26 21:03:46.701085', '2023-01-26 21:03:46.701085', NULL, 'The Everyday Hero Manifesto');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (989, 'خارج از پیچ و خم', 'داستانی درباره قدرت باور', 'داستانی درباره قدرت باور', 23, 8, 'book', 't', '<p><em>Out of the Maze</em> (2018) داستانی ساده اما قدرتمند را روایت می‌کند که درس‌های مهم زندگی را در مورد سازگاری با تغییر، چه در زندگی شخصی و چه در زندگی حرفه‌ای، نشان می‌دهد. این دنباله ای بر کتاب معروف نویسنده <em>Who Moved My Cheese</em> (1998) است که به ما اهمیت انطباق با واقعیت های جدید را می آموزد. در اینجا ما در مورد راه هایی که در واقع می توانیم به آن سازگاری دست یابیم، بیشتر می آموزیم.</p>', '2018-12-07 00:00:00', 5, 45, 'https://images.blinkist.io/images/books/5c06a9986cee070008ff3dad/1_1/470.jpg', '/en/books/out-of-the-maze-en/purchase', 'خارج-از-پیچ-و-خم', '2023-01-26 21:03:57.654457', '2023-01-26 21:03:57.654457', NULL, 'Out of the Maze');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (990, 'هیچ کاری نکن', 'چگونه از کار بیش از حد، زیاده روی و کم کاری دور شویم', 'چگونه از کار بیش از حد، زیاده روی و کم کاری دور شویم', 23, 7, 'book', 't', '<p><em>هیچ کاری نکن </em>(2020) استدلال می کند که وسواس ما نسبت به کارایی و بهره وری باعث شده است که قدرت اوقات فراغت را دست کم بگیریم. سلست هدلی، نویسنده، با ردیابی افزایش کارایی در قرن‌های گذشته، و همچنین عواقب امروزی لاغر شدن بیش از حد خود، ادعا می‌کند که باید شروع کنیم به خود اجازه دهیم لذت واقعی بیکاری را تجربه کنیم.</p>', '2020-09-05 00:00:00', 4, 195, 'https://images.blinkist.io/images/books/5f4e0b8f6cee070006fa09c0/1_1/470.jpg', '/en/books/do-nothing-en/purchase', 'هیچ-کاری-نکن', '2023-01-26 21:04:08.562388', '2023-01-26 21:04:08.562388', NULL, 'Do Nothing');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (991, 'ما همه بازاریاب هستیم', '20 اصل مهم که به شما کمک می کند مانند یک بازاریاب بازاریابی کنید', '20 اصل مهم که به شما کمک می کند مانند یک بازاریاب بازاریابی کنید', 21, 7, 'book', 't', '<p><em>ما همه بازاریاب هستیم</em>(2019) یک نمای کلی مفید از تاکتیک ها و اصولی که دنیای بازاریابی دیجیتال را هدایت می کنند ارائه می دهد. چه بخشی از یک کسب و کار کوچک یا یک شرکت بزرگ باشید، یا صرفاً کنجکاو باشید که ایده‌ها چگونه به صورت آنلاین فروخته می‌شوند، اینها نکاتی هستند که می‌توانند طرز فکر شما را در مورد بازاریابی تغییر دهند.</p>', '2019-08-05 00:00:00', 4, 103, 'https://images.blinkist.io/images/books/5d445f246cee07000859ea2b/1_1/470.jpg', '/en/books/were-all-marketers-en/purchase', 'ما-همه-بازاریاب-هستیم', '2023-01-26 21:04:25.208229', '2023-01-26 21:04:25.208229', NULL, 'We’re All Marketers');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (992, 'زبان های رهبری', 'چگونه از کلمات، اعمال و رفتارهای خود برای تأثیرگذاری بر تیم، همسالان و رئیس خود استفاده کنید', 'چگونه از کلمات، اعمال و رفتارهای خود برای تأثیرگذاری بر تیم، همسالان و رئیس خود استفاده کنید', 19, 6, 'book', 't', '<p><em>زبان‌های رهبری</em> (2019) نشان می‌دهد که چگونه مرز بین رهبری مؤثر و ناکارآمد می‌تواند نازک باشد. توضیح می‌دهد که با چند تکنیک ساده، می‌توانید سبک رهبری خود را در اختیار بگیرید و به یک رهبر الهام‌بخش و با اعتماد به نفس تبدیل شوید که در محیط کاری رقابتی امروزی برجسته می‌شود.</p>', '2020-03-23 00:00:00', 4, 265, 'https://images.blinkist.io/images/books/5e74c67a6cee0700069ea407/1_1/470.jpg', '/en/books/the-languages-of-leadership-en/purchase', 'زبان-های-رهبری', '2023-01-26 21:04:36.517866', '2023-01-26 21:04:36.517866', NULL, 'The Languages of Leadership');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (993, 'مردم خوب', 'تنها تصمیم رهبری که واقعاً مهم است', 'تنها تصمیم رهبری که واقعاً مهم است', 25, 8, 'book', 't', '<p><em>مردم خوب </em>(2017) موارد خوبی را در دنیای بی عیب و نقص تجارت بازگو می کند. آنتونی تجان با تعریف مجدد خوبی و افراد خوب به عنوان عناصر حیاتی یک شرکت موفق، این ایده را به چالش می‌کشد که ما فقط از طریق مهارت‌ها و شایستگی‌های خود می‌توانیم موفق شویم.</p>', '2018-11-09 00:00:00', 4, 21, 'https://images.blinkist.io/images/books/5be2f6d16cee070007d42878/1_1/470.jpg', '/en/books/good-people-en/purchase', 'مردم-خوب', '2023-01-26 21:04:52.74595', '2023-01-26 21:04:52.74595', NULL, 'Good People');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (994, 'عصر جاه طلبی', 'تعقیب ثروت، حقیقت و ایمان در چین جدید', 'تعقیب ثروت، حقیقت و ایمان در چین جدید', 19, 11, 'book', 'f', '<p><em>عصر جاه طلبی</em>نگاهی روشنگر به تغییرات زیادی که در 30 سال گذشته در چین رخ داده است ارائه می دهد و کشور را از یک کشور فقیر و در حال توسعه به قدرت اقتصادی امروزی تبدیل کرده است. ایوان اوسنوس زندگی روزمره شهروندان چینی را در حالی که واقعیت اجتماعی و اقتصادی جدیدی را دنبال می کنند، بررسی می کند.</p>', '2015-02-03 00:00:00', 4, 15, 'https://images.blinkist.io/images/books/54cf877c323335000a2f0000/1_1/470.jpg', '/en/books/age-of-ambition-en/purchase', 'عصر-جاه-طلبی', '2023-01-26 21:11:58.486804', '2023-01-26 21:11:58.486804', NULL, 'Age of Ambition');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (995, 'وگان الهام گرفته', 'ترکیبات فصلی، دستور العمل های خلاقانه، منوهای خوراکی', 'ترکیبات فصلی، دستور العمل های خلاقانه، منوهای خوراکی', 28, 7, 'book', 't', '<p><em>The Inspired Vegan</em> (2012) یک کتاب آشپزی مبتنی بر گیاه است که شامل دستور العمل های اصلی و همچنین تجسم مجدد غذاهای دلخواه سنتی، از کیک جانی تا جامبالایا است. اما این مجموعه ای از الهام نیز است - نویسنده برایانت تری دستور العمل ها را با توصیه هایی برای موسیقی، ادبیات و هنر شرح می دهد تا نه تنها اشتهای خوانندگان، بلکه خلاقیت و تجربیات آشپزی آنها را تقویت کند. </p>', '2020-09-12 00:00:00', 4, 16, 'https://images.blinkist.io/images/books/5f5775c66cee0700066abc43/1_1/470.jpg', '/en/books/the-inspired-vegan-en/purchase', 'وگان-الهام-گرفته', '2023-01-26 21:12:13.693853', '2023-01-26 21:12:13.693853', NULL, 'The Inspired Vegan');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (996, 'مغز خود را بیوهک کنید', 'چگونه سلامت شناختی، عملکرد و قدرت را تقویت کنیم', 'چگونه سلامت شناختی، عملکرد و قدرت را تقویت کنیم', 22, 7, 'book', 't', '<p><em>Biohack Your Brain </em>(2020) راهنمای مراقبت از ضروری ترین اندام شما – مغز است. با تکیه بر آخرین تحقیقات علوم اعصاب، حاوی توصیه های عملی در مورد همه چیز از بهینه سازی رژیم غذایی برای سلامت مغز گرفته تا تحریک سلول های خاکستری و غلبه بر استرس است. در طول مسیر، روشن می کند که چگونه می توانید از خود در برابر بیماری های شناختی مانند آلزایمر محافظت کنید.</p>', '2021-11-25 00:00:00', 5, 824, 'https://images.blinkist.io/images/books/619e25206cee07000894554f/1_1/470.jpg', '/en/books/biohack-your-brain-en/purchase', 'مغز-خود-را-بیوهک-کنید', '2023-01-26 21:12:29.055896', '2023-01-26 21:12:29.055896', NULL, 'Biohack Your Brain');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (997, 'چگونه یک بزرگسال در روابط باشیم', 'پنج کلید عشق آگاهانه', 'پنج کلید عشق آگاهانه', 26, 8, 'book', 't', '<p><em>چگونه در روابط بزرگسال باشیم </em>(2002) راهنمای قطعی روابط موثر است. این تمرکز بر این است که چگونه همه ما می‌توانیم عاشق‌تر شویم و به عشق بازتر باشیم، هم به نفع خودمان و هم به نفع جهان گسترده‌تر. نویسنده دیوید ریکو، با تکیه بر مفهوم بودایی ذهن آگاهی، پنج مفهوم عشق آگاهانه را بررسی می کند، و اینکه چگونه می توان آنها را در روابط در طول زندگی ما به کار برد.</p>', '2020-07-23 00:00:00', 5, 267, 'https://images.blinkist.io/images/books/5f1159966cee07000652e25c/1_1/470.jpg', '/en/books/how-to-be-an-adult-in-relationships-en/purchase', 'چگونه-یک-بزرگسال-در-روابط-باشیم', '2023-01-26 21:12:44.104977', '2023-01-26 21:12:44.104977', NULL, 'How to Be an Adult in Relationships');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (998, 'مثل اینکه مهم است به خدا هدایت کنید', 'رهبری ارزش‌محور در دنیای موفقیت‌محور', 'رهبری ارزش‌محور در دنیای موفقیت‌محور', 25, 8, 'book', 't', '<p><em>مثل اینکه مهم است به خدا هدایت کنید </em>(2021) یادآوری به مسیحیان است که کار فقط پول و موقعیت نیست. استرنز از تجربیات شغلی خود برای ارائه راهنمایی به مسیحیان در موقعیت های رهبری استفاده می کند. او ارزش های کلیدی را برای اولویت بندی ترسیم می کند و پیشنهادهای عملی برای بهبود سازمان ها و ایجاد محیط کاری مثبت تر ارائه می دهد.</p>', '2022-01-25 00:00:00', 4, 201, 'https://images.blinkist.io/images/books/61ead5d66cee070008ef9205/1_1/470.jpg', '/en/books/lead-like-it-matters-to-god-en/purchase', 'مثل-اینکه-مهم-است-به-خدا-هدایت-کنید', '2023-01-26 21:12:59.452525', '2023-01-26 21:12:59.452525', NULL, 'Lead Like It Matters to God');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (999, 'فرکانس Gen Z', 'چگونه برندها هماهنگ می شوند و اعتبار ایجاد می کنند', 'چگونه برندها هماهنگ می شوند و اعتبار ایجاد می کنند', 22, 8, 'book', 't', '<p><em>فرکانس Gen Z </em>(2018) طرحی را برای برندهایی ارائه می دهد که به دنبال برقراری ارتباط و ایجاد روابط معنادار با نسل Z هستند. نویسندگان علاوه بر ارائه بینشی به ذهن این جمعیت در حال رشد، عملی را ارائه می دهند. مشاوره در مورد استراتژی محتوا، بازاریابی، رسانه های اجتماعی و موارد دیگر. </p>', '2020-01-30 00:00:00', 4, 141, 'https://images.blinkist.io/images/books/5e2dde226cee0700062aae15/1_1/470.jpg', '/en/books/the-gen-z-frequency-en/purchase', 'فرکانس-Gen-Z', '2023-01-26 21:13:14.690446', '2023-01-26 21:13:14.690446', NULL, 'The Gen Z Frequency');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1000, 'حقیقت، دروغ و تبلیغات', 'هنر برنامه ریزی حسابداری', 'هنر برنامه ریزی حسابداری', 13, 5, 'book', 't', '<p>در <em>حقیقت، دروغ و تبلیغات</em> (1998)، برنامه‌ریز پیشرو حساب، جان استیل، بینش خود را نسبت به دنیای تبلیغات به اشتراک می‌گذارد. برای استیل، ایجاد تبلیغات عالی تماماً در مورد درک مصرف‌کننده است و حکایات قانع‌کننده پشت صحنه او نقشی را که برنامه‌ریزان حساب در ایجاد یک کمپین موفق بازی می‌کنند، نشان می‌دهد.</p>', '2015-04-28 00:00:00', 5, 11, 'https://images.blinkist.io/images/books/553f5d8e6136310007150000/1_1/470.jpg', '/en/books/truth-lies-and-advertising-en/purchase', 'حقیقت،-دروغ-و-تبلیغات', '2023-01-26 21:13:30.992528', '2023-01-26 21:13:30.992528', NULL, 'Truth, Lies and Advertising');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1001, 'RBG بدنام', 'زندگی و زمانه روت بادر گینزبورگ', 'زندگی و زمانه روت بادر گینزبورگ', 25, 9, 'book', 't', '<p><em>RBG بدنام </em>(2015) داستان زندگی روث بادر گینزبرگ قاضی دادگاه عالی ایالات متحده را شرح می دهد. از دوران کودکی اش در بروکلین - زمانی که او را با نام مستعارش کیکی می شناختند - تا تسخیر تصورات عمومی با مخالفت های تندش روی نیمکت، این پلک ها مبارزه بی امان یک زن را برای دادن حقوق برابر به زنان و مردان آمریکایی تحت قوانین کشور نشان می دهد. /p>
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1002, 'هشت درس استاد طبیعت', 'آنچه طبیعت درباره خوب زندگی کردن در جهان به ما می آموزد', 'آنچه طبیعت درباره خوب زندگی کردن در جهان به ما می آموزد', 24, 8, 'book', 't', '<p><em>هشت درس اصلی طبیعت </em>(2019) رساله ای تأمل برانگیز در مورد آنچه طبیعت می تواند در مورد خوب زیستن به ما بیاموزد است. با مشاهده دقیق بسیاری از اشکال زندگی، از قارچ های جنگلی گرفته تا فیل های قدرتمند، راهنما درس های ارزشمندی را نشان می دهد که ممکن است برای ما داشته باشند. با انجام این کار، ما را دعوت می کند تا با حسی تازه از هیبت و شگفتی دوباره به دنیای وحشی اطراف خود نگاه کنیم.</p>', '2021-02-06 00:00:00', 5, 132, 'https://images.blinkist.io/images/books/6013cad96cee070007f481b0/1_1/470.jpg', '/en/books/the-eight-master-lessons-of-nature-en/purchase', 'هشت-درس-استاد-طبیعت', '2023-01-26 21:13:59.605771', '2023-01-26 21:13:59.605771', NULL, 'The Eight Master Lessons of Nature');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1003, 'غول درون را بیدار کن', 'چگونه کنترل فوری سرنوشت ذهنی، عاطفی، فیزیکی و مالی خود را در دست بگیرید', 'چگونه کنترل فوری سرنوشت ذهنی، عاطفی، فیزیکی و مالی خود را در دست بگیرید', 19, 9, 'book', 't', '<p><em>Awaken The Giant Within</em> (1991) استدلال می کند که، در نهایت، همه ما کنترل زندگی خود را در دست داریم و با تغییر عادات، کنترل احساسات و اعتقاد به چیزهایی که می خواهیم باور کنیم، می توانیم زندگی ایده آل خود را به واقعیت تبدیل کنیم.</p>', '2014-10-21 00:00:00', 4, 401, 'https://images.blinkist.io/images/books/5445278861613300086b0000/1_1/470.jpg', '/en/books/awaken-the-giant-within-en/purchase', 'غول-درون-را-بیدار-کن', '2023-01-26 21:14:15.23738', '2023-01-26 21:14:15.23738', NULL, 'Awaken The Giant Within');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1004, 'علامت خود را بسازید', 'راهنمای خلاق برای ایجاد یک کسب و کار با تاثیر', 'راهنمای خلاق برای ایجاد یک کسب و کار با تاثیر', 18, 8, 'book', 't', '<p><em>Make Your Mark</em>درایت و نکات 21 تا از موفق ترین کارآفرینان و خلاقان چند سال اخیر را به نمایش می گذارد. این هنرمندان، برنامه‌نویسان، توسعه‌دهندگان و نویسندگان اسرار و ایده‌هایی را به اشتراک می‌گذارند که به آنها کمک کرده تا بازارهای مربوطه خود را با طوفان به دست آورند.</p>', '2015-03-13 00:00:00', 4, 37, 'https://images.blinkist.io/images/books/54fec71b626661000a110100/1_1/470.jpg', '/en/books/make-your-mark-en/purchase', 'علامت-خود-را-بسازید', '2023-01-26 21:14:30.899665', '2023-01-26 21:14:30.899665', NULL, 'Make Your Mark');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1485, 'درمان', 'سفری به علم ذهن بر روی بدن', 'سفری به علم ذهن بر روی بدن', 25, 10, 'book', 't', '<p><em>درمان</em> (2016) راهنمای شما برای قدرت شفابخشی ذهن است. این پلک‌ها عمق واقعی اثر دارونما را توضیح می‌دهند، که چگونه هیپنوتیزم می‌تواند بیماری‌ها را درمان کند و جایگزین‌های جالب و علمی پشتیبانی شده برای مسکن‌ها و جراحی‌های بسیار برجسته در پزشکی غربی را توضیح می‌دهد.</p>', '2017-05-15 00:00:00', 5, 84, 'https://images.blinkist.io/images/books/5918bb84b238e100066a4e10/1_1/470.jpg', '/en/books/cure-en/purchase', 'درمان', '2023-01-27 02:29:03.856794', '2023-01-27 02:29:03.856794', NULL, 'Cure');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1005, 'مشتریان اول', 'معجزه دو کلمه', 'معجزه دو کلمه', 11, 5, 'book', 't', '<p><em>مشتریان اول </em>(2013) نشان می دهد که چگونه صداقت، شایستگی و شفقت می توانند با ایجاد روابط قوی و قابل اعتماد با مشتریان به کلیدهای موفقیت بزرگ در شرکت شما تبدیل شوند. نویسندگان برخی از بینش‌های عالی را ارائه می‌دهند که از تجربیات خودشان گرفته شده‌اند، زیرا تنها در چند سال از کارگزاران املاک و مستغلات بسیار موفق شده‌اند.</p>', '2016-02-26 00:00:00', 4, 24, 'https://images.blinkist.io/images/books/56cdb5cf74766a000700009a/1_1/470.jpg', '/en/books/clients-first-en/purchase', 'مشتریان-اول', '2023-01-26 21:14:46.026546', '2023-01-26 21:14:46.026546', NULL, 'Clients First');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1006, 'قدرت کمتر', 'هنر زیبای محدود کردن خود به موارد ضروری ... در تجارت و زندگی', 'هنر زیبای محدود کردن خود به موارد ضروری ... در تجارت و زندگی', 14, 9, 'book', 't', '<p><em>قدرت کمتر</em> ایده‌آل <em>مینیمالیسم مولد</em> لئو بابوتا را معرفی می‌کند. رویکرد او عمدتاً بر توسعه عادات خوب به عنوان کلید تغییرات بلندمدت تمرکز دارد.</p>', '2014-04-08 08:35:51', 4, 166, 'https://images.blinkist.io/images/books/53444ab46432320007050000/1_1/470.jpg', '/en/books/the-power-of-less-en/purchase', 'قدرت-کمتر', '2023-01-26 21:15:01.204854', '2023-01-26 21:15:01.204854', NULL, 'The Power of Less');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1007, '4 رشته اجرا', 'دستیابی به اهداف بسیار مهم شما', 'دستیابی به اهداف بسیار مهم شما', 17, 8, 'book', 't', '<p><em>4 رشته اجرا</em> (2012) راهنمای مدیران عامل و مدیران است که به رهبران نشان می دهد چگونه اهداف استراتژیک خود را با واداشتن کارکنان خود به رفتار متفاوت اجرا کنند. با معرفی چهار رشته اجرایی، به تیم خود برای دستیابی به اهداف گسترده تر شرکت انگیزه می دهید.</p>', '2015-06-17 00:00:00', 5, 189, 'https://images.blinkist.io/images/books/558062f662323200072b0000/1_1/470.jpg', '/en/books/the-4-disciplines-of-execution-en/purchase', '4-رشته-اجرا', '2023-01-26 21:15:13.167725', '2023-01-26 21:15:13.167725', NULL, 'The 4 Disciplines of Execution');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1008, 'توجه شما را جلب کرد؟', 'چگونه فتنه ایجاد کنیم و با هر کسی ارتباط برقرار کنیم', 'چگونه فتنه ایجاد کنیم و با هر کسی ارتباط برقرار کنیم', 18, 8, 'book', 't', '<p><em>توجه شما را جلب کرد؟</em> (2015) راهنمای نهایی برای گرفتن و حفظ تمرکز افراد پریشان در دنیای پر سرعت امروز است. شما یاد خواهید گرفت که چگونه بر بی حوصلگی و حواس پرتی مزمن مخاطبان خود غلبه کنید تا خود را به یک سخنران جذاب و جذاب تبدیل کنید.</p>', '2015-10-02 00:00:00', 4, 55, 'https://images.blinkist.io/images/books/560949058a14e600090000d2/1_1/470.jpg', '/en/books/got-your-attention-en/purchase', 'توجه-شما-را-جلب-کرد؟', '2023-01-26 21:15:23.748875', '2023-01-26 21:15:23.748875', NULL, 'Got Your Attention?');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1009, 'همه پادکست دارند (به جز شما)', 'راهنمای چگونه از اولین خانواده پادکست', 'راهنمای چگونه از اولین خانواده پادکست', 25, 8, 'book', 't', '<p><em>همه یک پادکست دارند</em> (2021) یک راهنمای عملی و الهام‌بخش برای ساختن پادکست خودتان است. از انتخاب موضوع تا ایجاد مخاطب، پادکست نباید ترسناک باشد. حتی اگر پول نقد کم دارید و به فناوری نمی‌دانید، می‌توانید با کمی سرسختی و پشتکار چیزی عالی خلق کنید.</p>', '2021-04-19 00:00:00', 4, 86, 'https://images.blinkist.io/images/books/60795aaf6cee070007bf9440/1_1/470.jpg', '/en/books/everybody-has-a-podcast-except-you-en/purchase', 'همه-پادکست-دارند-(به-جز-شما)', '2023-01-26 21:15:34.284554', '2023-01-26 21:15:34.284554', NULL, 'Everybody Has a Podcast (Except You)');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1010, 'طراحی چیزهای روزمره', 'روانشناسی شناختی طراحی خوب', 'روانشناسی شناختی طراحی خوب', 17, 9, 'book', 't', '<p>این کتاب به بررسی روانشناسی شناختی طراحی خوب و آنچه محصولی را می‌سازد که به نیازهای کاربران پاسخ می‌دهد، می‌پردازد. نویسنده موانع مشترک طراحی خوب، نحوه کاهش و رفع خطاها، و نحوه نزدیک کردن کاربران و فناوری به یکدیگر را توسعه می‌دهد.</p>', '2014-05-13 12:59:49', 4, 230, 'https://images.blinkist.io/images/books/537231ee6264390007230000/1_1/470.jpg', '/en/books/the-design-of-everyday-things-en/purchase', 'طراحی-چیزهای-روزمره', '2023-01-26 21:15:44.369277', '2023-01-26 21:15:44.369277', NULL, 'The Design of Everyday Things');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1011, 'مینیمالیسم', 'زندگی معنادار داشته باشید', 'زندگی معنادار داشته باشید', 19, 7, 'book', 't', '<p><em>مینیمالیسم</em> (2011) راهی جایگزین به خوانندگان ارائه می دهد که از مشقت های 9 تا 5 اجتناب می کند و به آنها کمک می کند تا بر آنچه در زندگی مهم است تمرکز کنند. نویسندگان جاشوا فیلدز میلبورن و رایان نیکودیموس راهنمایی عملی در مورد اینکه چگونه هر کسی می‌تواند خود را از قید و بندهای مالی و عاطفی زندگی مدرن رها کند تا سبک زندگی جدید و ساده‌تری بسازد که هنوز معتبر و ارزشمند است، دارند.</p>', '2018-07-16 00:00:00', 4, 290, 'https://images.blinkist.io/images/books/5b4c8d79b238e10007b7ecb3/1_1/470.jpg', '/en/books/minimalism-en/purchase', 'مینیمالیسم', '2023-01-26 21:15:54.662988', '2023-01-26 21:15:54.662988', NULL, 'Minimalism');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1012, 'مالک آن بود. دوستش دارم. آن را کار کند.', 'چگونه هر شغلی را به شغل رویایی خود تبدیل کنیم', 'چگونه هر شغلی را به شغل رویایی خود تبدیل کنیم', 21, 6, 'book', 't', '<p><strong>درباره چیست؟</strong></p>
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1013, 'مقداری مونتاژ مورد نیاز است', 'رمزگشایی چهار میلیارد سال زندگی، از فسیل های باستانی تا DNA', 'رمزگشایی چهار میلیارد سال زندگی، از فسیل های باستانی تا DNA', 16, 6, 'book', 't', '<p><em>مجموعه لازم است </em>(2020) گزارشی قابل دسترس از تحولات بزرگ در تاریخ زندگی است. دیرینه شناس، نیل شوبین، کار خود را به دنبال یافتن فسیل ها برای پاسخ به بزرگترین سؤالات زندگی آغاز کرد - اما با پیشرفت های علمی اخیر، او استدلال می کند که مطالعه DNA اطلاعات بیشتری در مورد سفری که ما برای تبدیل شدن به انسان طی کردیم، نشان می دهد.</p>', '2020-11-23 00:00:00', 4, 39, 'https://images.blinkist.io/images/books/5fb796636cee07000726733d/1_1/470.jpg', '/en/books/some-assembly-required-en/purchase', 'مقداری-مونتاژ-مورد-نیاز-است', '2023-01-26 21:16:13.588231', '2023-01-26 21:16:13.588231', NULL, 'Some Assembly Required');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1014, 'لبه اعتماد', 'چگونه رهبران برتر نتایج سریع‌تر، روابط عمیق‌تر و خط پایانی قوی‌تر به دست می‌آورند', 'چگونه رهبران برتر نتایج سریع‌تر، روابط عمیق‌تر و خط پایانی قوی‌تر به دست می‌آورند', 21, 11, 'book', 't', '<p><em>The Trust Edge </em>(2012) توضیح می دهد که چرا اعتماد نه تنها برای یک زندگی شخصی شاد ضروری است، بلکه <em>عامل اساسی در کسب و کار و روابط تجاری موفق است. این هشت ستون به اصطلاح اعتماد را تشریح و مورد بحث قرار می‌دهد و استدلال می‌کند که این اصول باید اساس اعمال روزانه شما باشند تا آنچه را که نویسنده آن را «لبه اعتماد» می‌نامد به دست آورید. این کتاب همچنین نحوه بازسازی اعتماد را پس از آسیب دیدگی مورد بحث قرار می‌دهد.</p>', '2021-05-11 14:40:29.985', 5, 16, 'https://images.blinkist.io/images/books/60952af36cee0700077e63c1/1_1/470.jpg', '/en/books/the-trust-edge-en/purchase', 'لبه-اعتماد', '2023-01-26 21:16:23.696078', '2023-01-26 21:16:23.696078', NULL, 'The Trust Edge');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1015, 'پرنده به پرنده', 'چند دستورالعمل در مورد نوشتن و زندگی', 'چند دستورالعمل در مورد نوشتن و زندگی', 23, 11, 'book', 't', '<p>از دیدگاه شخصی نویسنده آن لاموت، <em>پرنده</em> <em>توسط</em> <em>پرنده</em> راهنمایی برای تبدیل شدن به یک نویسنده بهتر و بهبود زندگی شما است. راه رویکرد متمایز، صداقت و حکایات شخصی لاموت، این کتاب را برای نویسندگان یا هر کسی که می‌خواهد یکی شود، ضروری می‌سازد.</p>', '2014-09-16 00:00:00', 4, 94, 'https://images.blinkist.io/images/books/54195b7c6439610008000000/1_1/470.jpg', '/en/books/bird-by-bird-en/purchase', 'پرنده-به-پرنده', '2023-01-26 21:16:33.947142', '2023-01-26 21:16:33.947142', NULL, 'Bird by Bird');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1016, 'عیب', 'سفر به کامل بودن، یادگیری هولی بودن است', 'سفر به کامل بودن، یادگیری هولی بودن است', 15, 5, 'book', 't', '<p><em>Flawsome </em>(2020) راهنمای تبدیل شدن به بهترین نسخه از خود با پذیرش بخش‌های نه چندان عالی است. بسیاری از ما به دنبال راه‌هایی برای پنهان کردن عیوب خود هستیم، اما کلید رشد واقعی خودمان این است که این عیوب را بپذیریم، بفهمیم از کجا نشأت می‌گیرند و از آنها درس بگیریم.</p>', '2020-12-15 00:00:00', 5, 35, 'https://images.blinkist.io/images/books/5fd3464a6cee07000639bf53/1_1/470.jpg', '/en/books/flawsome-en/purchase', 'عیب', '2023-01-26 21:16:44.946946', '2023-01-26 21:16:44.946946', NULL, 'Flawsome');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1017, 'تنها بازی در شهر', 'بانک های مرکزی، بی ثباتی، و اجتناب از سقوط بعدی', 'بانک های مرکزی، بی ثباتی، و اجتناب از سقوط بعدی', 16, 7, 'book', 't', '<p>بحران مالی 2008 به طور چشمگیری چشم انداز اقتصاد جهانی را تغییر داد. بانک های مرکزی اکنون نقش بسیار متفاوتی نسبت به گذشته ایفا می کنند و ما اکنون با مجموعه ای از ریسک ها و مشکلات اقتصادی جدید مواجه هستیم. <em>The Only Game in Town</em> (2016) ریشه‌های این خطرات و مشکلات و آنچه را که می‌توانیم برای غلبه بر آنها انجام دهیم، بیان می‌کند.</p>', '2016-06-03 00:00:00', 4, 42, 'https://images.blinkist.io/images/books/57483f68c678450003db711e/1_1/470.jpg', '/en/books/the-only-game-in-town-en/purchase', 'تنها-بازی-در-شهر', '2023-01-26 21:16:56.381528', '2023-01-26 21:16:56.381528', NULL, 'The Only Game In Town');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1018, 'تئوری بازی های زیبا', 'چگونه فوتبال می تواند به اقتصاد کمک کند', 'چگونه فوتبال می تواند به اقتصاد کمک کند', 16, 7, 'book', 't', '<p><em>زیبا</em> <em>بازی</em> <em>نظریه</em> (2014) با نگاهی به دنیای شگفت‌انگیز فوتبال حرفه‌ای، به ما نشان می‌دهد که چقدر اقتصاد در زندگی روزمره ما قابل استفاده است. <em>Beautiful</em> <em>Game</em> <em>Theory</em> با بررسی آمار و مطالعات قانع‌کننده در مورد شوت‌آوت‌ها، تماس‌های داوران و فروش بلیت، بینش‌های جالبی را در مورد روانشناسی ارائه می‌دهد. اقتصاد رفتاری.</p>', '2014-09-16 00:00:00', 4, 54, 'https://images.blinkist.io/images/books/54195eca6439610008290000/1_1/470.jpg', '/en/books/beautiful-game-theory-en/purchase', 'تئوری-بازی-های-زیبا', '2023-01-26 21:17:08.805011', '2023-01-26 21:17:08.805011', NULL, 'Beautiful Game Theory');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1019, 'رهایش کن', 'کوچک کردن راه خود برای یک زندگی ثروتمندتر و شادتر', 'کوچک کردن راه خود برای یک زندگی ثروتمندتر و شادتر', 18, 6, 'book', 't', '<p><em>Let It Go</em> (2017) راهنمای شما برای شلوغ کردن و کوچک کردن خانه است. توصیه های عملی در مورد جدا کردن آنچه باید نگه داریم و دوست داشته باشیم از چیزی که ما را عقب نگه می دارد و باید تخلیه شود ارائه می دهد. همچنین بسیاری از برداشت‌های منفی مردم را در مورد کوچک‌سازی به چالش می‌کشد و ما را تشویق می‌کند که این فرآیند را به‌عنوان یک تجربه مثبت و تحسین‌برانگیز تغییر دهیم.</p>', '2020-03-13 00:00:00', 4, 139, 'https://images.blinkist.io/images/books/5e68e5356cee070006d37b37/1_1/470.jpg', '/en/books/let-it-go-en/purchase', 'رهایش-کن', '2023-01-26 21:17:19.571076', '2023-01-26 21:17:19.571076', NULL, 'Let It Go');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1020, 'امور مالی دختر باهوش', 'بدهی را کنار بگذارید، پول پس انداز کنید و ثروت واقعی بسازید', 'بدهی را کنار بگذارید، پول پس انداز کنید و ثروت واقعی بسازید', 20, 8, 'book', 't', 'هدف <p><em>Clever Girl Finance</em> (2019) کمک به زنان است که مسئولیت رفاه مالی خود را بدون احساس قضاوت یا تحت فشار قرار دهند. این بهترین راه‌ها را برای مدیریت امور مالی، رهایی از بدهی، پس‌انداز پول، و خلق ثروت و در عین حال وفادار ماندن به ارزش‌ها و شخصیت خود نشان می‌دهد.</p>', '2020-03-12 00:00:00', 4, 89, 'https://images.blinkist.io/images/books/5e68d9236cee070006d37ae6/1_1/470.jpg', '/en/books/clever-girl-finance-en/purchase', 'امور-مالی-دختر-باهوش', '2023-01-26 21:17:30.237844', '2023-01-26 21:17:30.237844', NULL, 'Clever Girl Finance');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1021, 'عمدی', 'آیا شما یک مدیر هستید یا یک شروع کننده جنبش؟', 'آیا شما یک مدیر هستید یا یک شروع کننده جنبش؟', 21, 7, 'book', 't', '<p><em>هدفمند </em>(2018) یک کتاب راهنمای هیجان انگیز برای به دست آوردن ایده های بزرگ شما برای تغییر است. جنیفر دولسکی، نویسنده، با تکیه بر تجربیات خود در Change.org، نشان می‌دهد که جنبش‌های مردمی چگونه شروع می‌شوند، چگونه طرفداران خود را ایجاد می‌کنند و در نهایت، چگونه تغییرات واقعی را در جهان اعمال می‌کنند. Dulski مثال‌های زیادی در دنیای واقعی ارائه می‌دهد، از اینکه چگونه رهبران وفاداری را القا می‌کنند تا بهترین تاکتیک‌ها برای گرفتن تصمیم‌گیرندگان قدرتمند در کنار شما.</p>', '2018-11-28 00:00:00', 4, 27, 'https://images.blinkist.io/images/books/5bf9e4b86cee070007cab48e/1_1/470.jpg', '/en/books/purposeful-en/purchase', 'عمدی', '2023-01-26 21:17:41.052119', '2023-01-26 21:17:41.052119', NULL, 'Purposeful');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1022, 'صحبت', 'علم گفتگو', 'علم گفتگو', 25, 8, 'book', 't', '<p>از صحبت‌های کوچک با باریستا گرفته تا چت‌های خنک‌کننده با همکاران، ما زمان زیادی را صرف صحبت کردن <em> می‌کنیم -- </em>اما تعداد کمی از ما علم را درک می‌کنیم که زیربنای <em>چگونه </em است. > صحبت می کنیم <em>Talk </em>(2018) بلوک‌های ساختمانی اساسی و الگوهای معمول برخوردهای مکالمه را تجزیه می‌کند تا ساختارها و استراتژی‌های پشت آنچه می‌گوییم را آشکار کند، و طرحی برای چگونگی یادگیری مؤثرتر صحبت کردن و گوش دادن ارائه می‌دهد. </p>', '2019-09-19 00:00:00', 4, 188, 'https://images.blinkist.io/images/books/5d80f6776cee0700095f0537/1_1/470.jpg', '/en/books/talk-en/purchase', 'صحبت', '2023-01-26 21:56:47.509391', '2023-01-26 21:56:47.509391', NULL, 'Talk');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1023, 'کاما سوترا کامل', 'اولین ترجمه مدرن خلاصه نشده متن کلاسیک هندی', 'اولین ترجمه مدرن خلاصه نشده متن کلاسیک هندی', 21, 7, 'book', 't', '<p><em>کاما سوترا کامل</em>(1994) ترجمه ای از متن کلاسیک هندی است که در قرن چهارم گردآوری شده است. این یک راهنمای پایدار برای لذت های عشق و رابطه جنسی است.</p>', '2021-05-15 00:00:00', 4, 85, 'https://images.blinkist.io/images/books/60950a5c6cee070007151f8f/1_1/470.jpg', '/en/books/the-complete-kama-sutra-en/purchase', 'کاما-سوترا-کامل', '2023-01-26 21:56:59.044045', '2023-01-26 21:56:59.044045', NULL, 'The Complete Kama Sutra');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1024, 'این 2016', 'بهینه سازی موتورهای جستجو را با استراتژی های بازاریابی اینترنتی هوشمند بیاموزید', 'بهینه سازی موتورهای جستجو را با استراتژی های بازاریابی اینترنتی هوشمند بیاموزید', 15, 6, 'book', 't', '<p><em>SEO 2016</em> (2015) راهنمای قطعی شما برای تسلط بر بهینه سازی موتور جستجو است. این پلک‌ها عملکرد اساسی الگوریتم رتبه‌بندی Google را توضیح می‌دهند و استراتژی‌های کلی برای افزایش دید وب‌سایت شما و به شما کمک می‌کنند در رتبه‌بندی موتورهای جستجو بالاتر بروید.</p>', '2016-12-12 00:00:00', 4, 29, 'https://images.blinkist.io/images/books/584c46e5af38d6000494d4d4/1_1/470.jpg', '/en/books/seo-2016-en/purchase', 'این-2016', '2023-01-26 21:57:09.739549', '2023-01-26 21:57:09.739549', NULL, 'SEO 2016');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1025, 'ممنون که دیر کردی', 'راهنمای خوش‌بین برای رشد در عصر شتاب‌ها', 'راهنمای خوش‌بین برای رشد در عصر شتاب‌ها', 14, 5, 'book', 't', '<p><em>از اینکه دیر کردید متشکرم</em> (2016) همه چیز درباره شتاب - اقتصاد، فناوری و محیط زیست ما است. این پلک‌ها توضیح می‌دهند که چرا جهان با سرعت فزاینده‌ای در حال حرکت است و خطراتی را که این روند می‌تواند به همراه داشته باشد و همچنین آنچه را که ما از آن به دست می‌آوریم نشان می‌دهد.</p>', '2017-11-16 00:00:00', 4, 36, 'https://images.blinkist.io/images/books/5a0981c5b238e1000655ceca/1_1/470.jpg', '/en/books/thank-you-for-being-late-en/purchase', 'ممنون-که-دیر-کردی', '2023-01-26 21:57:19.900596', '2023-01-26 21:57:19.900596', NULL, 'Thank You for Being Late');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1026, 'اعداد بر دنیای شما حکومت می کنند', 'تأثیر پنهان احتمالات و آمار بر هر کاری که انجام می دهید', 'تأثیر پنهان احتمالات و آمار بر هر کاری که انجام می دهید', 12, 5, 'book', 't', '<p><em>اعداد بر دنیای شما حکومت می کنند</em> (2010) راهنمای استدلال آماری است و اینکه چگونه می توانید از اطلاعات آماری مشخص به طور مؤثر برای درک و همچنین بهبود دنیای خود استفاده کنید. این پلک ها خواننده را از طریق پنج اصل کلیدی آمار و نحوه استفاده از آنها برای بهبود تصمیم گیری در زمینه های مختلف راهنمایی می کند.</p>', '2015-10-13 00:00:00', 4, 49, 'https://images.blinkist.io/images/books/561c16913635640007480000/1_1/470.jpg', '/en/books/numbers-rule-your-world-en/purchase', 'اعداد-بر-دنیای-شما-حکومت-می-کنند', '2023-01-26 21:57:30.263919', '2023-01-26 21:57:30.263919', NULL, 'Numbers Rule Your World');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1049, 'پایان کارها', 'پول، معنا و آزادی بدون 9 به 5', 'پول، معنا و آزادی بدون 9 به 5', 18, 7, 'book', 't', '<p>تیلور پیرسون با اقتباس از تاریخچه چند قرن اخیر و صدها مصاحبه با کارآفرینان، در <em>پایان مشاغل</em> (2015) نشان می‌دهد که چرا کارآفرین بودن امن‌تر و سودآورتر از همیشه است. او توضیح می دهد که چرا بسیاری از فارغ التحصیلان برای یافتن کار مشکل دارند، و چرا تبدیل شدن به یک کارآفرین در دنیای جهانی شده ما به ما معنا و آزادی بیشتری نسبت به کار کردن با روش های معمولی 9 به 5 می دهد.</p>', '2015-11-27 00:00:00', 4, 34, 'https://images.blinkist.io/images/books/5654301663626400078e0000/1_1/470.jpg', '/en/books/the-end-of-jobs-en/purchase', 'پایان-کارها', '2023-01-26 22:01:26.916308', '2023-01-26 22:01:26.916308', NULL, 'The End of Jobs');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1027, 'پرداخت منصفانه بازی منصفانه', 'همسو کردن عملکرد اجرایی و پرداخت', 'همسو کردن عملکرد اجرایی و پرداخت', 11, 5, 'book', 't', '<p><em>بازی منصفانه با پرداخت منصفانه</em> (2010) اصول اساسی جبران منصفانه مدیران را بیان می کند. این پلک‌ها توضیح می‌دهند که چه چیزی باعث معقول کردن پاداش می‌شود، چرا مدیران اجرایی اغلب حقوق‌های نامتناسب بیشتری نسبت به سایر کارمندان دریافت می‌کنند و از کدام استراتژی‌های مشخص می‌توانید برای تعیین یک مقیاس دستمزد منصفانه برای شرکت خود استفاده کنید.</p>', '2016-12-16 00:00:00', NULL, 9, 'https://images.blinkist.io/images/books/5850567c3e967900044cb0c6/1_1/470.jpg', '/en/books/fair-pay-fair-play-en/purchase', 'پرداخت-منصفانه-بازی-منصفانه', '2023-01-26 21:57:41.708913', '2023-01-26 21:57:41.708913', NULL, 'Fair Pay Fair Play');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1028, 'شیطان در شهر سفید', 'قتل، جادو و جنون در نمایشگاهی که آمریکا را تغییر داد', 'قتل، جادو و جنون در نمایشگاهی که آمریکا را تغییر داد', 11, 5, 'book', 't', '<p><em>شیطان در شهر سفید </em>(2003) شما را به شیکاگو در دهه 1890 می برد، زمانی که این شهر در حال رشد میزبان نمایشگاه جهانی در بحبوحه دوران تحولات اجتماعی و جنایات جدی بود. این پلک‌ها داستانی از نوآوری‌های هیجان‌انگیز آمریکایی را با اعمال غیرقابل توصیف یکی از اولین قاتلان زنجیره‌ای جهان ترکیب می‌کند.</p>', '2016-12-02 00:00:00', 4, 26, 'https://images.blinkist.io/images/books/583d6bfce536360004b64eef/1_1/470.jpg', '/en/books/the-devil-in-the-white-city-en/purchase', 'شیطان-در-شهر-سفید', '2023-01-26 21:57:51.957154', '2023-01-26 21:57:51.957154', NULL, 'The Devil in the White City');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1029, 'وکسرها', 'داستان درونی واکسن AstraZeneca آکسفورد و مسابقه با ویروس', 'داستان درونی واکسن AstraZeneca آکسفورد و مسابقه با ویروس', 24, 7, 'book', 't', '<p><em>Vaxxers </em>(2021) مسابقه توسعه واکسن کاربردی برای مهار گسترش ویروس COVID-19 را دنبال می کند. پروفسور سارا گیلبرت و دکتر کاترین گرین، از دانشگاه آکسفورد، بینش جالب و آموزنده ای را در مورد فرآیند طراحی، آزمایش و ساخت واکسن Oxford-AstraZeneca در زمان بی سابقه ارائه کردند. آن‌ها لحظات هیجان‌انگیز نوآوری و همچنین موانعی را که در طول مسیر با آن مواجه می‌شوند، بازگو می‌کنند.</p>', '2021-10-31 00:00:00', 4, 146, 'https://images.blinkist.io/images/books/6176b4516cee070008e1b731/1_1/470.jpg', '/en/books/vaxxers-en/purchase', 'وکسرها', '2023-01-26 21:58:03.305853', '2023-01-26 21:58:03.305853', NULL, 'Vaxxers');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1030, 'عادات بد', 'آگاهی، مرزها و ارتقاهای روزانه را که برای چسبیدن به آنها نیاز دارید، پرورش دهید', 'آگاهی، مرزها و ارتقاهای روزانه را که برای چسبیدن به آنها نیاز دارید، پرورش دهید', 15, 5, 'book', 't', '<p><em>عادات بد </em>(2020) یک راهنمای ساده برای ایجاد عادات مثبت است. این راهنما یک رویکرد گام به گام برای شکستن الگوهای قدیمی و ایجاد الگوهای جدید ارائه می دهد.</p>', '2021-02-25 00:00:00', 4, 265, 'https://images.blinkist.io/images/books/602f6c5d6cee070008a2d0e8/1_1/470.jpg', '/en/books/badass-habits-en/purchase', 'عادات-بد', '2023-01-26 21:58:13.7555', '2023-01-26 21:58:13.7555', NULL, 'Badass Habits');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1031, 'قدرت نونچی', 'راز کره ای برای شادی و موفقیت', 'راز کره ای برای شادی و موفقیت', 22, 8, 'book', 't', '<p><em>قدرت نونچی </em> (2019) مقدمه‌ای بر هنر ظریف کره‌ای سنجش خلق و خو و افکار دیگران به منظور ایجاد اعتماد، ارتباط و هماهنگی است. در حالی که nunchi ریشه در فرهنگ کره دارد، درس های آن در زمینه های بسیار فراتر از کره قابل استفاده است. این به این دلیل است که nunchi یک مهارت اجتماعی است که به شما قدرت می‌دهد تا اتاق را بخوانید و دیگران را درک کنید تا بتوانید روابط خود را بهبود ببخشید، در محل کارتان پیش بروید و بر افراد در هر زمینه و مکانی تأثیر بگذارید. </p>', '2019-12-12 00:00:00', 4, 126, 'https://images.blinkist.io/images/books/5df108366cee0700087fd27e/1_1/470.jpg', '/en/books/the-power-of-nunchi-en/purchase', 'قدرت-نونچی', '2023-01-26 21:58:25.916228', '2023-01-26 21:58:25.916228', NULL, 'The Power of Nunchi');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1032, 'کسب و کار تعلق', 'چگونه جوامعی بسازیم که در نهایت رشد کنند', 'چگونه جوامعی بسازیم که در نهایت رشد کنند', 27, 6, 'book', 't', '<p><em>کسب و کار متعلق </em>(2021) به بررسی این موضوع می پردازد که چگونه کسب و کارها می توانند از قدرت جوامع آنلاین به نفع خود و مشتریانشان استفاده کنند.</p>', '2022-04-19 00:00:00', 5, 73, 'https://images.blinkist.io/images/books/625e97c56cee07000837f5fa/1_1/470.jpg', '/en/books/the-business-of-belonging-en/purchase', 'تجارت-تعلق', '2023-01-26 21:58:37.610429', '2023-01-26 21:58:37.610429', NULL, 'The Business of Belonging');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1033, 'فراتر از کارآفرینی 2.0', 'تبدیل کسب و کار خود به یک شرکت بزرگ ماندگار', 'تبدیل کسب و کار خود به یک شرکت بزرگ ماندگار', 24, 8, 'book', 't', '<p><em>Beyond Entrepreneurship 2.0 </em>(2020) کتاب راهنمای تجاری ضروری جیم کالینز و بیل لازیر در سال 1992، <em>Beyond Entrepreneurship</em> را برای کارآفرینان، رویاپردازان و نوآوران امروزی به‌روزرسانی می‌کند. این نسخه جدید توصیه های تجاری و استراتژی جاودانه متن اصلی را که با بینش های پیشرفته و مطالعات موردی مرتبط با دنیای تجارت امروز تکمیل شده است، ترکیب می کند.</p>', '2021-05-06 00:00:00', 5, 118, 'https://images.blinkist.io/images/books/608bc8bb6cee070008a8f57e/1_1/470.jpg', '/en/books/beyond-entrepreneurship-2-dot-0-en/purchase', 'فراتر-از-کارآفرینی-2.0', '2023-01-26 21:58:48.406171', '2023-01-26 21:58:48.406171', NULL, 'Beyond Entrepreneurship 2.0');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1086, 'بر هسته خود مسلط شوید', 'راهنمای علمی برای دستیابی به اوج عملکرد و مقاومت در برابر آسیب', 'راهنمای علمی برای دستیابی به اوج عملکرد و مقاومت در برابر آسیب', 22, 6, 'book', 't', '<p><em>Master Your Core</em> (2021) یک نمای کلی از اینکه چگونه تقویت هسته شما می تواند به طور مستقیم عملکرد ورزشی و خلق و خوی شما را در عین کاهش صدمات افزایش دهد، ارائه می دهد. این یک توضیح علمی از "ثبات هسته" ارائه می دهد و شامل تنفس، کشش، و تمرینات پویا برای تمرین عضلات مرکزی و بهبود سلامت کلی شما است.</p>', '2021-12-30 00:00:00', 4, 398, 'https://images.blinkist.io/images/books/61c1aa5a6cee0700083346c4/1_1/470.jpg', '/en/books/master-your-core-en/purchase', 'بر-هسته-خود-مسلط-شوید', '2023-01-27 01:22:55.119185', '2023-01-27 01:22:55.119185', NULL, 'Master Your Core');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1034, 'نوآوری جوگاد', 'صرفه جویی فکر کنید، انعطاف پذیر باشید، رشدی موفقیت آمیز ایجاد کنید', 'صرفه جویی بیندیشید، انعطاف پذیر باشید، رشد چشمگیری ایجاد کنید', 12, 5, 'book', 't', '<p><em>Jugaad Innovation </em>(2012) برای رهبران تجاری که می خواهند نوآوری را در بازار جهانی غیرقابل پیش بینی امروزی پیش ببرند، راهنمایی های بسیار مورد نیاز را ارائه می دهد. این پلک‌ها به نوآوران در هند، چین و در سراسر آفریقا نگاه می‌کنند تا رویکردهای تازه، از پایین به بالا، تکنیک‌های صرفه‌جویانه و استراتژی‌های مدیریتی انعطاف‌پذیر را به خواننده ارائه دهند تا درک قوی از اصول جوگاد به خواننده بدهد.</p>', '2015-07-09 00:00:00', 3, 18, 'https://images.blinkist.io/images/books/559bcba03966610007d10000/1_1/470.jpg', '/en/books/jugaad-innovation-en/purchase', 'نوآوری-جوگاد', '2023-01-26 21:58:59.414318', '2023-01-26 21:58:59.414318', NULL, 'Jugaad Innovation');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1035, 'شما مربی شما', 'چگونه بر چالش ها در محل کار غلبه کنید و شغل خود را تحت کنترل بگیرید', 'چگونه بر چالش ها در محل کار غلبه کنید و کنترل شغل خود را در دست بگیرید', 21, 6, 'book', 't', '<p><em>You Coach You</em>(2022) راهنمایی است برای اینکه مربی خودتان باشید تا حداکثر موفقیت شغلی و شادی داشته باشید. با راهنماهای عملی، سوالاتی که به شما کمک می‌کند درباره شخصیت خود در محل کار فکر کنید و تمرین‌های سرگرم‌کننده، نویسندگان به شما نشان می‌دهند که چگونه می‌توانید بهترین تشویق کننده و راهنمای خود باشید. </p>', '2022-06-07 00:00:00', 5, 307, 'https://images.blinkist.io/images/books/62989c4b6cee070008da433f/1_1/470.jpg', '/en/books/you-coach-you-en/purchase', 'شما-مربی-شما', '2023-01-26 21:59:06.885911', '2023-01-26 21:59:06.885911', NULL, 'You Coach You');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1036, 'غذا و تغذیه', 'آنچه همه باید بدانند', 'آنچه همه باید بدانند', 24, 8, 'book', 't', '<p><em>غذا و تغذیه </em>(2018) به علم پشت آنچه می خوریم نگاه می کند. تنها بر اساس بهترین و دقیق‌ترین مطالعات، سروصداها و مدها را کاهش می‌دهد تا آنچه را که واقعاً در مورد تغذیه سالم می‌دانیم، آشکار کند.</p>', '2020-12-17 00:00:00', 4, 249, 'https://images.blinkist.io/images/books/5fd345d06cee0700066470c3/1_1/470.jpg', '/en/books/food-and-nutrition-en/purchase', 'غذا-و-تغذیه', '2023-01-26 21:59:17.131763', '2023-01-26 21:59:17.131763', NULL, 'Food and Nutrition');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1037, 'بزرگترین بازگشت رهبر', 'جذب، توسعه و تکثیر رهبران', 'جذب، توسعه و تکثیر رهبران', 24, 8, 'book', 't', '<p><em>The Leader''s Greatest Return</em> (2020) راهنمای توسعه رهبری است که از تجربه 25 ساله نویسنده در پرورش رهبران در سراسر جهان استفاده می کند. این پلک‌ها چگونگی شناسایی پتانسیل رهبری، پرورش آن و پرورش فرهنگی را توضیح می‌دهند که در آن رهبران سازمانی هرگز از توسعه آن دست نمی‌کشند. </p>', '2020-06-01 00:00:00', 4, 117, 'https://images.blinkist.io/images/books/5ed1396c6cee0700060c1ef5/1_1/470.jpg', '/en/books/the-leaders-greatest-return-en/purchase', 'بزرگترین-بازگشت-رهبر', '2023-01-26 21:59:25.235996', '2023-01-26 21:59:25.235996', NULL, 'The Leader’s Greatest Return');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1038, 'کمی تاریخ فلسفه', 'تفکری را که تاریخ فلسفه را شکل داد کشف کنید', 'تفکری را که تاریخ فلسفه را شکل داد کشف کنید', 21, 7, 'book', 't', '<p><em>تاریخ کمی از فلسفه </em>(2011) خوانندگان را به یک تور سوت از متفکرانی می برد که در طول دو هزار و نیم سال فلسفه را شکل دادند. از یونان باستان تا آلمان قرن بیستم، این کتاب باعث می‌شود که پرسش‌های دیرینه فلسفه امروز به اندازه زمانی که برای اولین بار مطرح شدند مرتبط باشند.</p>', '2020-11-11 00:00:00', 4, 235, 'https://images.blinkist.io/images/books/5fa5594e6cee070006bad8fc/1_1/470.jpg', '/en/books/a-little-history-of-philosophy-en/purchase', 'کمی-تاریخ-فلسفه', '2023-01-26 21:59:35.266768', '2023-01-26 21:59:35.266768', NULL, 'A Little History of Philosophy');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1039, 'کارمند به کارآفرین', 'چگونه آزادی خود را به دست آوریم و کارهایی را انجام دهیم که مهم هستند', 'چگونه آزادی خود را به دست آوریم و کارهایی را انجام دهیم که مهم هستند', 19, 6, 'book', 't', '<p><em>کارمند به کارآفرین </em>(2018) نشان می دهد که چگونه می توان از ذهنیت یک کارمند به ذهنیت یک کارآفرین عبور کرد. این نشان می دهد که چگونه می توانید هدف خود را در کار خود دنبال کنید و در عین حال از دام هایی که بیشتر کارآفرینان برای اولین بار با آن مواجه می شوند اجتناب کنید. با استراتژی‌های عملی برای راه‌اندازی و آزمایش ایده‌های شما، این کاوش در ذهنیت کارآفرینی ثابت می‌کند که هر کسی وقتی به ابزار و نگرش مناسب مجهز باشد، می‌تواند در کار و زندگی خود به موفقیت دست یابد.</p>', '2020-12-28 00:00:00', 5, 204, 'https://images.blinkist.io/images/books/5fda461d6cee07000670aef9/1_1/470.jpg', '/en/books/employee-to-entrepreneur-en/purchase', 'کارمند-به-کارآفرین', '2023-01-26 21:59:45.662458', '2023-01-26 21:59:45.662458', NULL, 'Employee to Entrepreneur');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1040, 'رژیم تنظیم مجدد متابولیسم', 'کبد خود را ترمیم کنید، ذخیره چربی را متوقف کنید و به طور طبیعی وزن کم کنید', 'کبد خود را ترمیم کنید، ذخیره چربی را متوقف کنید و به طور طبیعی وزن کم کنید', 17, 6, 'book', 't', '<p><em>رژیم غذایی تنظیم مجدد متابولیسم</em> (2019) رژیم غذایی پاکسازی جدید چهار هفته ای است که برای التیام آسیب به کبد، تحریک متابولیسم و ​​ترویج کاهش وزن سریع طراحی شده است. این پلک ها علم پشت برنامه را با شیرجه رفتن عمیق در زندگی مرموز کبد شما توضیح می دهند. آن‌ها نشان می‌دهند که چرا کبد شما برای سلامتی شما بسیار مهم است، چگونه می‌تواند مملو از چربی شود، و گام‌های ساده‌ای که می‌توانید برای تمیز کردن و بازگرداندن کبدتان به سلامت مطلوب بردارید.</p>', '2020-05-07 00:00:00', 5, 554, 'https://images.blinkist.io/images/books/5eac8a296cee0700060f4fd2/1_1/470.jpg', '/en/books/the-metabolism-reset-diet-en/purchase', 'رژیم-تنظیم-مجدد-متابولیسم', '2023-01-26 21:59:55.665534', '2023-01-26 21:59:55.665534', NULL, 'The Metabolism Reset Diet');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1041, 'زمین کامل', 'چگونه می توان آن را برای اولین بار، هر بار درست گفت', 'چگونه می توان آن را برای اولین بار، هر بار درست گفت', 26, 12, 'book', 't', '<p><em>Pitch</em> <em>Perfect</em> توصیه‌ها و اصولی را ارائه می‌کند که می‌تواند به هر کسی کمک کند تا ارتباط مؤثرتری برقرار کند. این به شما می آموزد که چگونه یک استدلال یا داستان را با اطمینان، به روشی به یاد ماندنی ارائه کنید و چگونه نکات خود را با دقت بیشتری بیان کنید. نویسنده هفت اصل را معرفی می‌کند که به شما کمک می‌کند تا از لحن درست در زندگی حرفه‌ای و خصوصی خود استفاده کنید.</p>', '2014-08-05 00:00:00', 4, 73, 'https://images.blinkist.io/images/books/53e20ab26339360007290000/1_1/470.jpg', '/en/books/pitch-perfect-en/purchase', 'زمین-کامل', '2023-01-26 22:00:06.447255', '2023-01-26 22:00:06.447255', NULL, 'Pitch Perfect');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1042, 'فروش مغز', 'وقتی علم با خرید روبرو می شود', 'وقتی علم با خرید روبرو می شود', 13, 6, 'book', 't', '<p><em>فروش مغز</em> (2013) تاکتیک‌های نوآورانه‌ای را نشان می‌دهد که به بازاریابان کمک می‌کند با استفاده از قدرت‌های علوم اعصاب مشتریان را جذب کنند. این پلک‌ها استراتژی‌های بازاریابی روان‌شناختی، زبان بدن و جذابیت حسی را بررسی می‌کنند که هر خرده‌فروش باید بداند و هر مشتری باید بداند چگونه از آن اجتناب کند!</p>', '2015-08-04 00:00:00', 4, 39, 'https://images.blinkist.io/images/books/55bf5a8d63646100073a0000/1_1/470.jpg', '/en/books/the-brain-sell-en/purchase', 'فروش-مغز', '2023-01-26 22:00:16.753386', '2023-01-26 22:00:16.753386', NULL, 'The Brain Sell');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1043, 'زباله نیست', 'با دور انداختن کمتر تفاوت بزرگی ایجاد کنید', 'با دور انداختن کمتر تفاوت بزرگی ایجاد کنید', 19, 6, 'book', 't', '<p><em>Waste Not </em>(2019) یک راهنمای عملی برای تغییر سبک زندگی مصرفی شما به منظور تأثیرگذاری بزرگ و سازگار با محیط زیست است. بیاموزید که چگونه از امکانات دنیای مدرن لذت ببرید بدون اینکه انبوهی از زباله های مدرن را پشت سر بگذارید.</p>', '2021-10-05 00:00:00', 4, 42, 'https://images.blinkist.io/images/books/6155bef56cee070008752820/1_1/470.jpg', '/en/books/waste-not-en/purchase', 'زباله-نیست', '2023-01-26 22:00:26.979637', '2023-01-26 22:00:26.979637', NULL, 'Waste Not');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1044, 'رسیدن به بله', 'مذاکره برای توافق بدون تسلیم شدن', 'مذاکره برای توافق بدون تسلیم شدن', 18, 11, 'book', 't', '<p><em>دستیابی به بله </em>(1981) به عنوان <em>مرجع </em>موفق مذاکرات در نظر گرفته می‌شود. این ابزارها و تکنیک‌های اثبات‌شده‌ای را ارائه می‌کند که می‌تواند به شما در حل هرگونه تعارض و یافتن راه‌حل‌های برد-برد کمک کند.</p>', '2013-12-11 09:03:59', 4, 419, 'https://images.blinkist.io/images/books/52a6e3e73839360008200000/1_1/470.jpg', '/en/books/getting-to-yes-en/purchase', 'رسیدن-به-بله', '2023-01-26 22:00:37.047931', '2023-01-26 22:00:37.047931', NULL, 'Getting to Yes');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1045, 'راه صداقت', 'یافتن راه رسیدن به خود واقعی', 'یافتن راه رسیدن به خود واقعی', 21, 5, 'book', 't', '<p><em>راه صداقت </em>(2021) یک فرآیند چهار مرحله ای برای یافتن یکپارچگی است - کیفیتی که می تواند رنج ناشی از اعمال و باورهای خلبان خودکار مضر را کاهش دهد. با برقراری ارتباط مجدد با چیزی که به شما احساس کامل بودن می دهد، به احساس هدفمندی، شفای عاطفی و رفاه ذهنی دست خواهید یافت.</p>', '2021-06-07 00:00:00', 4, 252, 'https://images.blinkist.io/images/books/60b8b5a16cee070007296f6a/1_1/470.jpg', '/en/books/the-way-of-integrity-en/purchase', 'راه-صداقت', '2023-01-26 22:00:47.413778', '2023-01-26 22:00:47.413778', NULL, 'The Way of Integrity');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1046, 'هنر شروع', 'راهنمای زمان تست شده و سخت شده برای هر کسی که هر کاری را شروع می کند', 'راهنمای زمان تست شده و سخت شده برای هر کسی که هر کاری را شروع می کند', 20, 11, 'book', 't', '<p><em></em> <em>هنر</em> <em></em> <em></em> <em>شروع</em> مروری کوتاه بر برخی از جنبه های کلیدی راه اندازی و راه اندازی یک کسب و کار این شامل موضوعاتی مانند پیشنهاد برای تامین مالی، استخدام افراد مناسب و ایجاد یک برند موفق است.</p>', '2014-08-05 00:00:00', 4, 64, 'https://images.blinkist.io/images/books/53e220056339360007600000/1_1/470.jpg', '/en/books/the-art-of-the-start-en/purchase', 'هنر-شروع', '2023-01-26 22:00:54.408193', '2023-01-26 22:00:54.408193', NULL, 'The Art of the Start');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1047, 'آموزشگاه آشپزی پیشخوان آشپزخانه', 'چگونه چند درس ساده 9 تازه کار آشپزی را به آشپزهای خانه نترس تبدیل کرد', 'چگونه چند درس ساده 9 تازه کار آشپزی را به آشپزهای خانه نترس تبدیل کرد', 30, 9, 'book', 't', '<p><em>مدرسه آشپزی پیشخوان آشپزخانه </em>(2011) راهنمای عملی برای تسلط بر هنر آشپزی خوب در خانه است. کاتلین فلین تصمیم گرفت تا نه آشپز خانه ناامن را به مهارت های حیاتی آشپزخانه مجهز کند. آنها یاد گرفتند که چگونه با اطمینان چاقو را در دست بگیرند، مرغ را کباب کنند و یک قرص نان متوسط ​​بپزند. اما مهمتر از آن، آنها یاد گرفتند که برای غذا ارزش قائل شوند و آگاهانه در مورد اینکه چه می خورند و چگونه غذا می خرند، انتخاب کنند. در این پلک‌ها، فلین درس‌های کلیدی کارگاه‌های خود را جمع‌آوری می‌کند تا الهام بخش هر آشپز خانه باشد.</p>', '2020-09-03 00:00:00', 4, 28, 'https://images.blinkist.io/images/books/5f4dfd096cee070006b7579d/1_1/470.jpg', '/en/books/the-kitchen-counter-cooking-school-en/purchase', 'آموزشگاه-آشپزی-پیشخوان-آشپزخانه', '2023-01-26 22:01:06.189173', '2023-01-26 22:01:06.189173', NULL, 'The Kitchen Counter Cooking School');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1048, 'کاهش مقیاس', 'زندگی بزرگ در یک مکان کوچکتر', 'زندگی بزرگ در یک مکان کوچکتر', 12, 6, 'book', 't', '<p><em>Scaling Down</em> (2005) به شما کمک می کند انگیزه جمع آوری چیزهای بیشتری از آنچه واقعاً نیاز دارید را درک کنید، و اینکه چرا وقتی آن چیزها را به دست آوردید، نمی خواهید آنها را رها کنید. . با یک راهنمای گام به گام مفید، استراتژی‌های موثری برای کاهش مقیاس و یادگیری زندگی با کمتر ارائه می‌دهد.</p>', '2016-08-22 00:00:00', 4, 42, 'https://images.blinkist.io/images/books/57b9e7b6ece3ed0003d5ac00/1_1/470.jpg', '/en/books/scaling-down-en/purchase', 'کاهش-مقیاس', '2023-01-26 22:01:16.795822', '2023-01-26 22:01:16.795822', NULL, 'Scaling Down');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1050, 'چگونه دوستان خود را به دست آوریم و بر مردم تأثیر بگذاریم', 'قوانین اساسی برای اینکه چگونه یک تاثیر اولیه خوب داشته باشیم', 'قوانین اساسی برای اینکه چگونه یک تاثیر اولیه خوب داشته باشیم', 18, 7, 'book', 't', '<p><em>چگونه دوستان به دست آوریم و بر افراد تأثیر بگذاریم</em> (1936) یک کلاس کارشناسی ارشد در مدیریت و برخورد با مردم ارائه می دهد. از ایجاد یک برداشت اولیه خوب تا مخالفت مؤثر، همه چیزهایی را که باید در مورد مهارت، خوشایند و مطمئن شدن در معاملات شخصی و تجاری خود بدانید، در بر دارد.</p>', '2021-05-12 06:50:33.042', 5, 1543, 'https://images.blinkist.io/images/books/609931d56cee0700077e67e1/1_1/470.jpg', '/en/books/how-to-win-friends-and-influence-people-en/purchase', 'چگونه-دوستان-خود-را-به-دست-آوریم-و-بر-مردم-تأثیر-بگذاریم', '2023-01-26 22:01:35.69123', '2023-01-26 22:01:35.69123', NULL, 'How to Win Friends &amp; Influence People');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1051, 'انجام کارهای درست به درستی', 'مدیر اجرایی موثر چگونه وقت خود را صرف می کند', 'مدیر اجرایی موثر چگونه وقت خود را صرف می کند', 12, 5, 'book', 't', '<p><em>انجام کارهای درست به درستی</em> (2015) هسته رهبری موفق را کاهش می دهد. این به شما می آموزد که چگونه یک تیم را مدیریت کنید و چگونه با دیگران کار کنید تا به نتایج سودآور و سازنده برسید. برای احساس اعتماد به نفس و هدایت تیم خود به موفقیت آماده شوید.</p>', '2017-01-19 00:00:00', 4, 63, 'https://images.blinkist.io/images/books/587df18e850310000464e85e/1_1/470.jpg', '/en/books/doing-the-right-things-right-en/purchase', 'انجام-کارهای-درست-به-درستی', '2023-01-26 22:01:45.959528', '2023-01-26 22:01:45.959528', NULL, 'Doing the Right Things Right');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1052, 'تمرین', 'ارسال کار خلاقانه', 'ارسال کار خلاقانه', 25, 8, 'book', 't', '<p><em>The Practice </em>(2020) یک کتاب راهنما برای متخصصان خلاق و خلاقانی است که به دنبال حرفه ای شدن هستند. نویسنده ست گودین این افسانه ها را که مبنی بر اینکه خلاقان نابغه های تنها هستند و خلاقیت را نمی توان آموزش داد، زیر پا می گذارد و نکات و بینش های عملی را برای تقویت اعتماد به نفس خلاق و تعمیق تمرین خلاق ارائه می دهد.</p>', '2021-01-02 00:00:00', 5, 126, 'https://images.blinkist.io/images/books/5fdb1b016cee0700073571a4/1_1/470.jpg', '/en/books/the-practice-en/purchase', 'تمرین', '2023-01-26 22:01:54.0657', '2023-01-26 22:01:54.0657', NULL, 'The Practice');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1053, 'زندگی، روی خط', 'داستان یک سرآشپز از تعقیب عظمت، رویارویی با مرگ، و باز تعریف شیوه غذا خوردن', 'داستان یک سرآشپز از تعقیب عظمت، رویارویی با مرگ، و باز تعریف شیوه غذا خوردن', 21, 9, 'book', 't', '<p><em>زندگی، روی خط</em> (2011) داستان قابل توجه گرانت آچاتز، سرآشپزی مصمم را روایت می کند که تلاش برای تبدیل شدن به بهترین، باعث شد تا قبل از 30 سالگی، غذاهای آمریکایی را دوباره تعریف کند. رویاهای او با افتتاح رستوران خود به نام Alinea در شیکاگو به حقیقت پیوست، اما درست زمانی که جوایز و جوایز و تقدیرنامه‌ها در حال سرازیر شدن بود، چالش بزرگ‌تری پیش روی او قرار گرفت: او به سرطان دهان پیشرفته مبتلا شد و با احتمال مرگ یا از دست دادن خود مواجه شد. زبان.</p>', '2016-12-26 00:00:00', NULL, 5, 'https://images.blinkist.io/images/books/5846eb0e714e5f00047cdce7/1_1/470.jpg', '/en/books/life-on-the-line-en/purchase', 'زندگی،-روی-خط', '2023-01-26 22:02:04.025139', '2023-01-26 22:02:04.025139', NULL, 'Life, on the Line');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1054, 'ماهیگیری فولا', 'اقتصاد دستکاری و فریب', 'اقتصاد دستکاری و فریب', 15, 6, 'book', 't', '<p><em>Phishing for Phools</em> (2015) روش‌هایی را نشان می‌دهد که در آن سیستم‌های مدرن بازار آزاد، که اغلب به عنوان مظهر مبادله منطقی ستایش می‌شوند، در عوض با فریب عمدی، با هدف هل دادن شما تقویت می‌شوند. بر خلاف منافع شخصی خود عمل کنید.</p>', '2016-01-20 00:00:00', 4, 73, 'https://images.blinkist.io/images/books/569e2df3f16f340007000055/1_1/470.jpg', '/en/books/phishing-for-phools-en/purchase', 'ماهیگیری-فولا', '2023-01-26 22:02:14.906004', '2023-01-26 22:02:14.906004', NULL, 'Phishing for Phools');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1055, 'رشد سریع، درست انجام شده است', 'رهبری، نفوذ و نوآوری برای موفقیت', 'رهبری، نفوذ و نوآوری برای موفقیت', 19, 6, 'book', 't', '<p><em>رشد سریع، درست انجام شده </em>(2020) طرحی را برای رهبری یک سازمان متمرکز بر رشد ارائه می کند. این توضیح می دهد که چگونه یک رابطه همزیستی بین ذهن خلاق، فنی و تجاری پیش نیاز موفقیت است. برای دستیابی به این موفقیت به عنوان یک رهبر، باید خود را با هر یک از این حوزه های مختلف آشنا کنید، روان ارتباط برقرار کنید و الهام بخش نوآوری باشید. </p>', '2021-08-12 00:00:00', 4, 51, 'https://images.blinkist.io/images/books/610d2ea66cee070007427619/1_1/470.jpg', '/en/books/rapid-growth-done-right-en/purchase', 'رشد-سریع،-درست-انجام-شده-است', '2023-01-26 22:02:26.416709', '2023-01-26 22:02:26.416709', NULL, 'Rapid Growth, Done Right');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1056, 'و خبر خوب این است که ...', 'درس ها و توصیه هایی از طرف روشن', 'درس ها و توصیه هایی از طرف روشن', 13, 6, 'book', 't', '<p><em>And the Good News Is…</em> (2015) شما را در زندگی و زمانه دانا پرینو راهنمایی می کند. این پلک‌ها زندگی دانا را دنبال می‌کنند - از اوایل کودکی او در روستایی وایومینگ تا حرفه‌اش در کاپیتول هیل - و توصیه‌های کاربردی برای موفقیت و پیشرفت شخصی در این راه ارائه می‌دهند.</p>', '2016-01-27 00:00:00', NULL, 9, 'https://images.blinkist.io/images/books/56a6ae35fb7e87000700001f/1_1/470.jpg', '/en/books/and-the-good-news-is-dot-dot-dot-en/purchase', 'و-خبر-خوب-این-است-که-...', '2023-01-26 22:02:36.77322', '2023-01-26 22:02:36.77322', NULL, 'And the Good News Is...');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1057, 'دختران رادیوم', 'داستان تاریک زنان درخشان آمریکا', 'داستان تاریک زنان درخشان آمریکا', 16, 6, 'book', 't', '<p><em>دختران رادیوم </em>(2016) داستان غم انگیز و در نهایت الهام بخش کارگران زن آمریکایی در اوایل قرن بیستم را روایت می کند که برخی از بدترین سهل انگاری های شرکتی قابل تصور را تحمل کردند. مبارزه باورنکردنی آنها برای عدالت و مسئولیت تا به امروز همچنان یک داستان مرتبط است.</p>', '2018-04-13 00:00:00', 5, 20, 'https://images.blinkist.io/images/books/5accb7f6b238e1000747deb6/1_1/470.jpg', '/en/books/the-radium-girls-en/purchase', 'دختران-رادیوم', '2023-01-26 22:02:46.946435', '2023-01-26 22:02:46.946435', NULL, 'The Radium Girls');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1058, 'یافتن معنا در دنیای ناقص', 'کاوش در راه های بسیاری که زندگی می تواند معنادار باشد', 'کاوش در راه های بسیاری که زندگی می تواند معنادار باشد', 22, 8, 'book', 't', '<p><em>یافتن معنا در یک جهان ناقص</em> (2017) به ما نشان می‌دهد که اگرچه سؤالات درباره معنای زندگی دشوار است، اما نیازی به مرموز بودن آنها نیست. Iddo Landau ابزارهایی را فراهم می کند که به ما کمک می کند تا در مورد معنای زندگی به روشی روشن و منطقی فکر کنیم. او نظریه‌هایی را توضیح می‌دهد که ما را قادر می‌سازد تا معنای زندگی را ببینیم، و توصیه‌های عملی در مورد چگونگی تقویت آن معنا ارائه می‌دهد.</p>', '2020-06-14 00:00:00', 5, 99, 'https://images.blinkist.io/images/books/5ee262726cee0700068376df/1_1/470.jpg', '/en/books/finding-meaning-in-an-imperfect-world-en/purchase', 'یافتن-معنا-در-دنیای-ناقص', '2023-01-26 22:02:58.804068', '2023-01-26 22:02:58.804068', NULL, 'Finding Meaning in an Imperfect World');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1059, 'چگونه باید زندگی کنیم؟', 'ایده های بزرگ از گذشته برای زندگی روزمره', 'ایده های بزرگ از گذشته برای زندگی روزمره', 32, 12, 'book', 't', '<p><em>چگونه باید زندگی کنیم؟ </em>(2013) دیدگاه گسترده ای از این که چرا ما غربی ها تمایل داریم آن گونه که فکر می کنیم، می کنیم، ارائه می دهد. از عشق تا کار تا مرگ، چگونگی تکامل دیدگاه‌های امروزی ما را توضیح می‌دهد و توصیه‌های قدیمی را در مورد اینکه چگونه می‌توانیم آنها را بهبود بخشیم ارائه می‌دهد.</p>', '2018-04-25 00:00:00', 5, 39, 'https://images.blinkist.io/images/books/5ade22f8b238e10007bda16f/1_1/470.jpg', '/en/books/how-should-we-live-en/purchase', 'چگونه-باید-زندگی-کنیم؟', '2023-01-26 22:03:08.878027', '2023-01-26 22:03:08.878027', NULL, 'How Should We Live?');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1060, 'پیاده روی مست', 'چگونه تصادفی بر زندگی ما حکومت می کند', 'چگونه تصادفی بر زندگی ما حکومت می کند', 15, 8, 'book', 'f', '<p>این کتاب درباره نقش تصادفی در زندگی ما است. این کتاب ریشه‌های تاریخی آمارهای مدرن را بررسی می‌کند و به اصول اساسی ریاضی می‌پردازد تا توضیح دهد که چگونه - مانند یک فرد مست که برای راه رفتن تلاش می‌کند - بسیاری از زندگی‌های ما توسط شانس محض دیکته شده است.</p>', '2014-09-09 00:00:00', 4, 37, 'https://images.blinkist.io/images/books/540f2e353934640008330000/1_1/470.jpg', '/en/books/the-drunkards-walk-en/purchase', 'پیاده-روی-مست', '2023-01-26 22:03:19.426606', '2023-01-26 22:03:19.426606', NULL, 'The Drunkard’s Walk');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1061, 'شغل U', 'چگونه با توسعه مهارت هایی که شرکت ها واقعاً به آن نیاز دارند، ثروت و موفقیت را به دست آوریم', 'چگونه با توسعه مهارت هایی که شرکت ها واقعاً به آن نیاز دارند، ثروت و موفقیت را به دست آوریم', 12, 5, 'book', 't', '<p><em>Job U</em> (2015) نشان می دهد که چگونه این ایده که کالج برای همه است، هم برای فرد و هم نیروی کار به عنوان یک کل - و حتی خود اقتصاد ضرر خواهد داشت. این پلک‌ها روش‌های جایگزین برای آموزش را بررسی می‌کنند که به ما کمک می‌کند شغل‌های <em>و </em>پردرآمد را پیدا کنیم، و ثابت می‌کند که کالج آن چیزی نیست که باید باشد.</p>', '2015-04-15 00:00:00', 4, 11, 'https://images.blinkist.io/images/books/552bde5d6466340007780000/1_1/470.jpg', '/en/books/job-u-en/purchase', 'شغل-U', '2023-01-26 22:03:29.77991', '2023-01-26 22:03:29.77991', NULL, 'Job U');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1062, 'ورزشکار متفکر', 'رازهای عملکرد خالص', 'رازهای عملکرد خالص', 14, 6, 'book', 't', '<p><em>ورزشکار آگاه</em> (2015) توضیح می‌دهد که چگونه با تمرین تمرکز حواس، «ابر قدرت‌های» پنهان خود را باز کنید. وقتی یاد بگیرید چگونه الوهیت درونی خود را هدایت کنید، به اوج عملکرد خود می رسید - در ورزش یا در هر زمینه دیگری.</p>', '2015-11-25 00:00:00', 4, 108, 'https://images.blinkist.io/images/books/56541a8a63626400072b0000/1_1/470.jpg', '/en/books/the-mindful-athlete-en/purchase', 'ورزشکار-متفکر', '2023-01-26 22:03:43.446954', '2023-01-26 22:03:43.446954', NULL, 'The Mindful Athlete');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1063, 'مدیریت پروژه برای مدیر پروژه غیر رسمی', 'عنوان فرانکلین کاوی', 'عنوان فرانکلین کاوی', 18, 6, 'book', 't', '<p><em>مدیریت پروژه برای مدیر پروژه غیررسمی </em>(2015) پدیده‌ای را بررسی می‌کند که بسیاری از افراد با آن مواجه هستند - آنها وظیفه مدیریت پروژه‌ها را دارند اما هیچ آموزش رسمی در مدیریت پروژه ندارند. اگر در این شرایط هستید، نگران نباشید. با یادگیری نحوه ترکیب رهبری الهام بخش با مدیریت پروژه موثر، تضمین می کنید که شانس موفقیت پروژه بعدی خود را افزایش می دهید.</p>', '2022-10-25 00:00:00', 5, 324, 'https://images.blinkist.io/images/books/635248256cee0700093823dd/1_1/470.jpg', '/en/books/project-management-for-the-unofficial-project-manager-en/purchase', 'مدیریت-پروژه-برای-مدیر-پروژه-غیر-رسمی', '2023-01-26 22:03:53.47023', '2023-01-26 22:03:53.47023', NULL, 'Project Management for the Unofficial Project Manager');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1064, 'مدیریت شهرت آنلاین', 'چگونه از شرکت خود در رسانه های اجتماعی محافظت کنیم', 'چگونه از شرکت خود در رسانه های اجتماعی محافظت کنیم', 17, 7, 'book', 't', '<p><em>مدیریت شهرت آنلاین </em>(2015) بینشی ارائه می دهد که چگونه شرکت ها و مدیران عاملی که نمی دانند چگونه رسانه های اجتماعی و اینترنت را مدیریت کنند، می توانند به شهرت خود آسیب برسانند. دریابید که چگونه یک حادثه کوچک با یک مشتری ناراضی می تواند به طوفانی از پست های منفی و توییت های عصبانی تبدیل شود. مهمتر از آن، دریابید که چگونه می توانید از این اتفاق برای شما جلوگیری کنید.</p>
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1065, 'بیوگرافی قبل از خواب: چهره های پنهان', 'رویای آمریکایی و داستان ناگفته ریاضیدانان زن سیاه پوست که به پیروزی در مسابقه فضایی کمک کردند', 'رویای آمریکایی و داستان ناگفته ریاضیدانان زن سیاه پوست که به پیروزی در مسابقه فضایی کمک کردند', 44, 6, 'book', 't', '<p><strong>روایت شده توسط Jeannette Robinson</strong></p>
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1066, 'رئیس آن', 'زمان، درآمد و زندگی خود را کنترل کنید', 'زمان، درآمد و زندگی خود را کنترل کنید', 22, 7, 'book', 't', '<p><em>Boss It </em>(2020) راهنمای شروع هر کارآفرین مشتاق است. این کتاب پر از راهنمایی های عملی و انگیزه های الهام بخش، تمام آنچه را که باید بدانید برای تبدیل رویای خود به یک تجارت کاملاً تثبیت شده، تشریح می کند. </p>', '2021-10-04 00:00:00', 4, 187, 'https://images.blinkist.io/images/books/6155c3ed6cee070008752e82/1_1/470.jpg', '/en/books/boss-it-en/purchase', 'رئیس-آن', '2023-01-26 22:04:25.942527', '2023-01-26 22:04:25.942527', NULL, 'Boss It');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1067, 'همیشه گرسنه؟', 'هوس ها را غلبه کنید، سلول های چربی خود را دوباره آموزش دهید و برای همیشه وزن کم کنید', 'هوس ها را غلبه کنید، سلول های چربی خود را دوباره آموزش دهید و برای همیشه وزن کم کنید', 17, 8, 'book', 't', '<p><em>همیشه گرسنه هستید؟ </em>(2016) باورهای غلط رایج در مورد سلامتی و کاهش وزن را توضیح می دهد. در آن خواهید دید که در تلاش برای کاهش وزن چه اشتباهی انجام داده اید، و مهمتر از همه، کشف کنید که چگونه می توانید بدن خود را برای پردازش چربی بدون دست کشیدن از غذای واقعی و خوشمزه آموزش دهید.</p>', '2016-04-29 00:00:00', 4, 100, 'https://images.blinkist.io/images/books/571f54f07289830003455857/1_1/470.jpg', '/en/books/always-hungry-en/purchase', 'همیشه-گرسنه؟', '2023-01-26 22:04:36.621744', '2023-01-26 22:04:36.621744', NULL, 'Always Hungry?');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1068, 'چگونه نگرانی را متوقف کنیم و زندگی را شروع کنیم', 'کلاسیک خودیاری که به شما کمک می کند دیگر نگران نباشید', 'کلاسیک خودیاری که به شما کمک می کند دیگر نگران نباشید', 21, 12, 'book', 't', '<p><em>چگونه نگرانی را متوقف کنیم و زندگی را شروع کنیم</em> (۱۹۴۸) یک کتاب کلاسیک خودیاری است که به وضوح توضیح می دهد که چرا نگرانی برای شما بد است و چه کاری می توانید در مورد آن انجام دهید. <em>چگونه از نگرانی دست بردارید و زندگی را شروع کنید</em> با ابزارها و تکنیک هایی برای عمل، و همچنین انبوهی از مثال ها و حکایات برای پشتیبانی از توصیه های آن، می تواند به شما کمک کند امروز کمتر نگران باشید.</p>', '2013-12-11 09:03:29', 5, 587, 'https://images.blinkist.io/images/books/52a6df4b383936000c1b0000/1_1/470.jpg', '/en/books/how-to-stop-worrying-and-start-living-en/purchase', 'چگونه-نگرانی-را-متوقف-کنیم-و-زندگی-را-شروع-کنیم', '2023-01-26 22:04:47.207023', '2023-01-26 22:04:47.207023', NULL, 'How to Stop Worrying and Start Living');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1069, 'ابزارها', '5 ابزاری که به شما کمک می کند شجاعت، خلاقیت و اراده را بیابید - و الهام بخش شما برای زندگی در حرکت رو به جلو است.', '5 ابزاری که به شما کمک می کند شجاعت، خلاقیت و اراده را بیابید - و الهام بخش شما برای زندگی در حرکت رو به جلو است.', 16, 6, 'book', 't', '<p><em>ابزارها: 5 ابزاری که به شما کمک می کند شجاعت، خلاقیت و اراده را بیابید - و به شما الهام می بخشد که زندگی را با حرکت رو به جلو زندگی کنید</em> (2012) پنج تمرین ذهنی را برای مقابله فوری با چالش های رایجی که ممکن است وجود داشته باشند، تشریح می کند. شما را در زندگی عقب نگه می دارد نویسندگان همکار درمانگر هستند و شامل موارد بیمار و طرح‌هایی برای توضیح بیشتر در مورد نحوه استفاده از هر ابزار می‌شوند. </p>', '2023-01-24 00:00:00', NULL, 4, 'https://images.blinkist.io/images/books/63cf8051c68d9c00098939cc/1_1/470.jpg', '/en/books/the-tools-en/purchase', 'ابزارها', '2023-01-26 22:04:57.401074', '2023-01-26 22:04:57.401074', NULL, 'The Tools');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1070, 'آجر به آجر', 'چگونه لگو قوانین نوآوری را بازنویسی کرد و صنعت جهانی اسباب بازی را تسخیر کرد', 'چگونه لگو قوانین نوآوری را بازنویسی کرد و صنعت جهانی اسباب بازی را تسخیر کرد', 18, 10, 'book', 'f', '<p><em>Brick by Brick</em> به شکست‌ها و موفقیت نهایی یکی از محبوب‌ترین برندهای جهان می‌پردازد: LEGO. با بررسی استراتژی‌های مدیریتی که لگو را از نزدیک به فاجعه بازگرداند، <em>Brick by Brick</em> نشان می‌دهد که چگونه می‌توان نوآوری را مسئولانه مدیریت کرد.</p>', '2014-11-18 00:00:00', 5, 10, 'https://images.blinkist.io/images/books/546a08c03034360009500000/1_1/470.jpg', '/en/books/brick-by-brick-en/purchase', 'آجر-به-آجر', '2023-01-26 22:05:08.428805', '2023-01-26 22:05:08.428805', NULL, 'Brick by Brick');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1078, 'قبایل', 'ما به شما نیاز داریم که ما را هدایت کنید', 'ما به شما نیاز داریم که ما را هدایت کنید', 15, 7, 'book', 't', '<p>در این کتاب، نویسنده ست گودین قوی‌ترین واحد سازمان اجتماعی را آشکار می‌کند: «قبیله» یا گروهی از افراد مرتبط با یک هدف، یک رهبر و یکدیگر، که با هم باعث تغییر در جامعه می‌شوند. این به ما نشان می دهد که چگونه می توانیم از قدرت اینترنت برای تشکیل و رهبری قبیله های خود استفاده کنیم. Tribes همچنین از نیاز جهانی به تغییر و رهبری حمایت می کند، بنابراین ما می توانیم به عنوان یک شرکت یا به عنوان یک جامعه رشد کنیم.</p>', '2014-07-15 00:00:00', 5, 141, 'https://images.blinkist.io/images/books/53c620d63839340007000000/1_1/470.jpg', '/en/books/tribes-en/purchase', 'قبایل', '2023-01-26 22:06:26.988802', '2023-01-26 22:06:26.988802', NULL, 'Tribes');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1071, 'دوازده و نیم', 'استفاده از عناصر احساسی لازم برای موفقیت در کسب و کار', 'استفاده از عناصر احساسی لازم برای موفقیت در کسب و کار', 27, 13, 'book', 't', '<p><em>Twelve and a Half </em>(2021) یک راهنمای صریح و صریح برای دوازده مهارت احساسی است که برای شما در تجارت و زندگی موفقیت به ارمغان می آورد. با ترکیب حکایت‌هایی از تجربه نویسنده و همچنین سناریوهای تجاری معمولی، نشان می‌دهد که چگونه، در طرح کلان چیزها، مهارت‌های «نرم» در واقع می‌توانند مهم‌تر از مهارت‌های «سخت» اغلب اولویت‌دار باشند. با داشتن پایه ای قوی در هوش هیجانی، مدیران اجرایی، بنیانگذاران و کارآفرینان می توانند حتی سخت ترین موقعیت ها را با متانت و اعتماد به نفس پشت سر بگذارند.</p>', '2022-02-28 00:00:00', 4, 283, 'https://images.blinkist.io/images/books/621c6a3f6cee070008cdebe7/1_1/470.jpg', '/en/books/twelve-and-a-half-en/purchase', 'دوازده-و-نیم', '2023-01-26 22:05:16.426902', '2023-01-26 22:05:16.426902', NULL, 'Twelve and a Half');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1072, 'خوب داخل', 'راهنمای تبدیل شدن به والدینی که می خواهید باشید', 'راهنمای تبدیل شدن به والدینی که می خواهید باشید', 16, 7, 'book', 't', '<p><em>Good Inside</em> (2022) به والدینی که هنگام مدیریت تعارض در خانه‌هایشان احساس درماندگی می‌کنند، امیدواری می‌دهد. بیشتر از والدین،<em> </em>معنی دوست داشتن خود و گسترش آن عشق به فرزندانتان است. دکتر بکی استراتژی‌های سنتی پاداش و تنبیه را رد می‌کند، در عوض والدین را تشویق می‌کند تا با فرزندانشان تفاهم کنند و در عین حال مرزهای سالم را حفظ کنند.</p>', '2022-11-09 00:00:00', 5, 300, 'https://images.blinkist.io/images/books/636a1b16958fe900087a387d/1_1/470.jpg', '/en/books/good-inside-en/purchase', 'خوب-داخل', '2023-01-26 22:05:27.34533', '2023-01-26 22:05:27.34533', NULL, 'Good Inside');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1073, 'هفت قانون معنوی موفقیت', 'راهنمای کتاب جیبی برای تحقق رویاهای خود', 'راهنمای کتاب جیبی برای تحقق رویاهای خود', 16, 7, 'book', 't', '<p><em>هفت قانون معنوی موفقیت</em> (2007) درباره نیروهایی در جهان است که می توانند شما را به سمت شغل عالی، افزایش ثروت و رفاه، روابط قوی و مهمتر از همه، هدایت کنند. توانایی لذت بردن از آنچه در این لحظه دارید هفت قانون جهانی موفقیت را کشف کنید و از انرژی و فراوانی بی پایان جهان بهره ببرید!</p>', '2016-06-30 00:00:00', 4, 246, 'https://images.blinkist.io/images/books/576bac11e0dd250003d615d0/1_1/470.jpg', '/en/books/the-seven-spiritual-laws-of-success-en/purchase', 'هفت-قانون-معنوی-موفقیت', '2023-01-26 22:05:38.006078', '2023-01-26 22:05:38.006078', NULL, 'The Seven Spiritual Laws of Success');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1074, 'بحران در منطقه سرخ', 'داستان مرگبارترین شیوع ابولا در تاریخ و شیوع های آینده', 'داستان مرگبارترین شیوع ابولا در تاریخ، و همه گیری های آینده', 24, 9, 'book', 't', '<p><em>بحران در منطقه سرخ</em> (2019) روایتی جذاب از خط مقدم شیوع ابولا در سال 2014 در غرب آفریقا را ارائه می دهد. این یک داستان غم انگیز و امیدبخش از اولین بیمار آلوده تا زندگی های بسیاری است که قبل از حل بحران از بین رفته است. </p>', '2019-09-27 00:00:00', 5, 30, 'https://images.blinkist.io/images/books/5d8a0c976cee0700095f1b7d/1_1/470.jpg', '/en/books/crisis-in-the-red-zone-en/purchase', 'بحران-در-منطقه-سرخ', '2023-01-26 22:05:48.546875', '2023-01-26 22:05:48.546875', NULL, 'Crisis in the Red Zone');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1075, 'چگونه در ورزش کسب و کار برنده شویم', 'اگر من می توانم آن را انجام دهم، شما می توانید آن را انجام دهید', 'اگر من می توانم آن را انجام دهم، شما می توانید آن را انجام دهید', 13, 6, 'book', 't', '<p>در <em>چگونه در ورزش کسب‌وکار برنده شوید </em> (2011)، مارک کوبان توصیه‌ها و حکمت‌های غیر متعارفی را در مورد چگونگی پیشرفت در دنیای تجارت ارائه می‌دهد. این کتاب که مجموعه‌ای از پست‌ها از وبلاگ مشهور کوبا را تشکیل می‌دهد، داستان موفقیت غیرمتعارف خود کوبا را بیان می‌کند – داستانی که مطمئناً هر کسی را که مایل به تفکر متفاوتی است الهام می‌دهد.</p>', '2015-10-22 00:00:00', 4, 46, 'https://images.blinkist.io/images/books/562497906361310007020000/1_1/470.jpg', '/en/books/how-to-win-at-the-sport-of-business-en/purchase', 'چگونه-در-ورزش-کسب-و-کار-برنده-شویم', '2023-01-26 22:05:59.255278', '2023-01-26 22:05:59.255278', NULL, 'How to Win at the Sport of Business');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1076, 'بهانه ای نیست!', 'قدرت انضباط شخصی', 'قدرت انضباط شخصی', 17, 7, 'book', 't', '<p><em>بدون بهانه! </em>(2010) انضباط شخصی را به عنوان کلید دستیابی به موفقیت تعریف می کند و توضیح می دهد که چگونه اعمال خود انضباطی در هر سه حوزه اصلی زندگی شما - موفقیت شخصی، شغلی و شادی کلی - می تواند تأثیر عمیقی بر سلامت شما داشته باشد. بودن.</p>', '2018-08-07 00:00:00', 4, 837, 'https://images.blinkist.io/images/books/5b6720ceb238e10007857556/1_1/470.jpg', '/en/books/no-excuses-en/purchase', 'بهانه-ای-نیست!', '2023-01-26 22:06:08.278546', '2023-01-26 22:06:08.278546', NULL, 'No Excuses!');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1077, 'چگونه پولم را سرمایه گذاری کنم', 'کارشناسان امور مالی نشان می دهند که چگونه پس انداز، خرج و سرمایه گذاری می کنند', 'کارشناسان امور مالی نشان می دهند که چگونه پس انداز، خرج و سرمایه گذاری می کنند', 20, 6, 'book', 't', '<p><em>چگونه پولم را سرمایه گذاری کنم</em> (2020) در مورد روش<em>درست</em> برنامه ریزی آینده مالی شما نیست. در عوض، بینشی نادر در مورد آنچه که خودی های صنعت مالی با پول خود انجام می دهند، ارائه می دهد. پس حرفه ای ها چگونه بازار را بازی می کنند؟ خوب، معلوم است که هیچ پاسخ واحدی برای این سوال وجود ندارد. نحوه سرمایه گذاری افراد بستگی به این دارد که چه کسانی هستند و چه نوع ارزش ها و اهدافی دارند.</p>', '2021-02-11 00:00:00', 4, 179, 'https://images.blinkist.io/images/books/601d30856cee070007e6c182/1_1/470.jpg', '/en/books/how-i-invest-my-money-en/purchase', 'چگونه-پولم-را-سرمایه-گذاری-کنم', '2023-01-26 22:06:19.063172', '2023-01-26 22:06:19.063172', NULL, 'How I Invest My Money');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1079, 'چگونه زیستن', 'آنچه قانون سنت بندیکت درباره شادی، معنا و اجتماع به ما می آموزد', 'آنچه قانون سنت بندیکت درباره شادی، معنا و اجتماع به ما می آموزد', 23, 8, 'book', 't', '<p><em>چگونه زندگی کنیم </em>(2018) نگاهی متفکرانه به آموزه‌های سنت بندیکت دارد و اینکه چگونه قوانینی که او برای زندگی رهبانی قرن ششم به کار می‌برد، می‌تواند به ما کمک کند امروز زندگی بهتری داشته باشیم. از مزایای پرورش سکوت گرفته تا بینش در مورد اینکه چگونه رهبر بهتری باشید، دریابید که چگونه <em>قانون سنت بندیکت</em> می‌تواند به شما کمک کند تا در دام‌های زندگی مدرن بهتر پیمایش کنید. </p>', '2021-03-21 00:00:00', 5, 195, 'https://images.blinkist.io/images/books/6050ad136cee070007a43e8c/1_1/470.jpg', '/en/books/how-to-live-en/purchase', 'چگونه-زیستن', '2023-01-26 22:06:37.578782', '2023-01-26 22:06:37.578782', NULL, 'How to Live');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1080, 'اقتصاد ناک آف', 'چگونه تقلید باعث نوآوری می شود', 'چگونه تقلید باعث نوآوری می شود', 13, 7, 'book', 'f', '<p><em>The Knockoff Economy</em>این ایده را که کپی برداری و تقلید موانع جدی برای صنایع ایجاد می کند به چالش می کشد. در عوض، از مثال‌های عینی استفاده می‌کند تا نشان دهد که چگونه، در عصری که کپی کردن آسان‌تر از همیشه است، نوآوری در اوج تاریخی خود قرار دارد.</p>', '2015-03-03 00:00:00', NULL, 3, 'https://images.blinkist.io/images/books/54f57bac623735000a120000/1_1/470.jpg', '/en/books/the-knockoff-economy-en/purchase', 'اقتصاد-ناک-آف', '2023-01-26 22:06:48.014258', '2023-01-26 22:06:48.014258', NULL, 'The Knockoff Economy');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1081, 'تصمیم گیری و حل مسئله', 'از موانع عبور کنید و عدم اطمینان در کار را از بین ببرید', 'از موانع عبور کنید و عدم اطمینان در کار را از بین ببرید', 17, 6, 'book', 't', '<p><em>تصمیم گیری و حل مسئله</em> (2019) تصمیم گیری، حل مسئله و تفکر خلاق را توضیح می دهد. دستورالعمل هایی را برای ایجاد و بهبود این مهارت ها ارائه می دهد و اهمیت این توانایی ها را بررسی می کند که شما را قادر می سازد ظرفیت تفکر عملی خود را گسترش دهید.</p>', '2023-01-02 00:00:00', 4, 30, 'https://images.blinkist.io/images/books/63ab0e5b73bf6d0009f220e5/1_1/470.jpg', '/en/books/decision-making-and-problem-solving-en/purchase', 'تصمیم-گیری-و-حل-مسئله', '2023-01-26 22:06:59.679551', '2023-01-26 22:06:59.679551', NULL, 'Decision Making and Problem Solving');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1082, 'عوضی های دمدمی مزاج', 'حقیقت در مورد داروهایی که مصرف می کنید، خوابی که از دست می دهید، رابطه جنسی که ندارید، و آنچه واقعا شما را دیوانه می کند', 'حقیقت در مورد داروهایی که مصرف می کنید، خوابی که از دست می دهید، رابطه جنسی که ندارید، و آنچه واقعا شما را دیوانه می کند', 19, 8, 'book', 't', '<p><em>Moody Bitches</em>(2015) راهنمای شما برای بدن و مغز زن است. این پلک زدن‌ها برخی از دلایل پشت احساسات و خلق و خوی نوسانی را که زنان می‌توانند تجربه کنند و اینکه چگونه می‌توانند بهتر با خودشان هماهنگ شوند، احساسات و بدنشان را در آغوش بگیرند، توضیح می‌دهد.</p>', '2017-05-04 00:00:00', 4, 44, 'https://images.blinkist.io/images/books/590630afb238e10008b85716/1_1/470.jpg', '/en/books/moody-bitches-en/purchase', 'عوضی-های-دمدمی-مزاج', '2023-01-27 00:51:34.861091', '2023-01-27 00:51:34.861091', NULL, 'Moody Bitches');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1083, 'تنوع عصبی در محل کار', 'با نیروی کار متنوع عصبی، نوآوری، عملکرد و بهره وری را هدایت کنید', 'با نیروی کار متنوع عصبی، نوآوری، عملکرد و بهره وری را هدایت کنید', 15, 4, 'book', 't', '<p><em>تنوع عصبی در محل کار </em>(2022) یک راهنمای عملی برای استخدام کارمندان با تنوع عصبی و ایجاد محیط های کاری است که به آنها امکان پیشرفت می دهد. به لطف انقلاب دیجیتال، دنیای کار به طور چشمگیری در دهه های گذشته تغییر کرده است. با این حال، فرهنگ شرکتی در دام شیوه‌های استخدام قدیمی باقی مانده است که برای تنوع عصبی کارساز نیست. با به‌روزرسانی این شیوه‌ها، محل کار فراگیرتری ایجاد می‌کنید که تیم‌های موفق و نوآورتری را به همراه خواهد داشت.</p>', '2022-09-30 00:00:00', 4, 238, 'https://images.blinkist.io/images/books/63316f0e6cee070008ecbbf2/1_1/470.jpg', '/en/books/neurodiversity-at-work-en/purchase', 'تنوع-عصبی-در-محل-کار', '2023-01-27 00:51:59.789879', '2023-01-27 00:51:59.789879', NULL, 'Neurodiversity at Work');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1084, 'زندگی لیموناد', 'چگونه به موفقیت، ایجاد شادی و تسخیر هر چیزی کمک کنیم', 'چگونه به موفقیت، ایجاد شادی و تسخیر هر چیزی کمک کنیم', 27, 5, 'book', 't', '<p><em>زندگی لیموناد</em> (2019) یک راهنمای عملی برای زندگی با طراحی است. این استدلال می کند که اکثر مردم به سختی کار خود رضایت می دهند و برای اینکه چرا همه چیز برنامه ریزی نمی شود بهانه می آورند. اما، در نهایت، تنها کسی که می تواند اوضاع را تغییر دهد، شما هستید. اگر مایلید در تعقیب اهدافتان اصیل و جسور باشید، می توانید زندگی پر از رضایت و ماجراجویی داشته باشید. The Lemonade Life نشان می دهد که چگونه گام های عملی برای تبدیل رویاهای خود به واقعیت بردارید.</p>', '2022-06-14 00:00:00', 5, 451, 'https://images.blinkist.io/images/books/62a842636cee070008170a64/1_1/470.jpg', '/en/books/the-lemonade-life-en/purchase', 'زندگی-لیموناد', '2023-01-27 00:52:22.370683', '2023-01-27 00:52:22.370683', NULL, 'The Lemonade Life');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1085, 'استارتاپ ناب', 'چگونه نوآوری مداوم کسب و کارهای کاملاً موفقی را ایجاد می کند', 'چگونه نوآوری مداوم کسب و کارهای کاملاً موفقی را ایجاد می کند', 18, 11, 'book', 't', '<p><em>استارت‌آپ ناب </em>(2011) به استارت‌آپ‌ها و شرکت‌های فناوری کمک می‌کند تا مدل‌های کسب‌وکار پایدار را توسعه دهند. از نمونه سازی سریع و مداوم و تمرکز بر داده های بازخورد مشتری حمایت می کند.</p>
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1087, 'سرعت اعتماد', 'تنها چیزی که همه چیز را تغییر می دهد', 'تنها چیزی که همه چیز را تغییر می دهد', 13, 5, 'book', 't', '<p><em>سرعت اعتماد</em> (2006) درباره اهمیت اعتماد است و اینکه چگونه می‌تواند همه جنبه‌های زندگی ما را بهبود بخشد، از روابط شخصی گرفته تا بهره‌وری در دفتر. اعتماد، ارتباطات را بهبود می بخشد و با انجام این کار، کارایی را سرعت می بخشد و در عین حال هزینه را کاهش می دهد. در سراسر این کتاب، نویسندگان به ما نکاتی را ارائه می دهند که دقیقاً چه کاری انجام دهیم تا اعتماد در زندگی خود را افزایش دهیم.</p>', '2015-02-04 00:00:00', 4, 143, 'https://images.blinkist.io/images/books/54cf8ec5323335000a550000/1_1/470.jpg', '/en/books/the-speed-of-trust-en/purchase', 'سرعت-اعتماد', '2023-01-27 01:23:16.078073', '2023-01-27 01:23:16.078073', NULL, 'The Speed of Trust');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1088, 'ذهن بدون نگرانی', 'مغز خود را تمرین دهید، چرخه چرخش استرس را آرام کنید و شادتر و سازنده‌تر خود را کشف کنید', 'مغز خود را تمرین دهید، چرخه چرخش استرس را آرام کنید و شادتر و سازنده‌تر خود را کشف کنید', 16, 7, 'book', 't', '<p><em>ذهن بدون نگرانی</em> (2017) نگاهی دقیق به این دارد که چرا ما زمان زیادی را صرف نگرانی می کنیم و برای کاهش این نگرانی ها چه کاری می توان انجام داد. داشتن ذهنی پرتنش ممکن است بخشی از انسان بودن باشد، اما این بدان معنا نیست که نمی توانید برای کنترل بهتر افکار و احساسات خود قدم بردارید. در اینجا چند نکته و تکنیک برای کنترل ذهن و داشتن زندگی شادتر وجود دارد.</p>', '2017-10-19 00:00:00', 4, 100, 'https://images.blinkist.io/images/books/59e4a3feb238e100062ad1e7/1_1/470.jpg', '/en/books/the-worry-free-mind-en/purchase', 'ذهن-بدون-نگرانی', '2023-01-27 01:23:40.728752', '2023-01-27 01:23:40.728752', NULL, 'The Worry-Free Mind');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1089, 'در حال', 'کاوش یک دانشمند درباره مسائل بزرگ هستی', 'کاوش یک دانشمند درباره مسائل بزرگ هستی', 14, 6, 'book', 't', '<p><em>روی</em> <em>هستی، برتری روش علمی بر دین و عرفان را در بررسی مسائل بزرگ هستی مطرح می کند. حتی در مواردی که علم هنوز قادر به جایگزینی تمام جنبه‌های باور دینی با حقایق عینی نیست، <em>روشن</em> <em>بودن</em> نشان می‌دهد که قبل از انجام آن فقط مسئله زمان است. /p>', '2014-07-01 00:00:00', 3, 49, 'https://images.blinkist.io/images/books/53b3c5c33135350007230000/1_1/470.jpg', '/en/books/on-being-en/purchase', 'در-حال', '2023-01-27 01:23:57.958992', '2023-01-27 01:23:57.958992', NULL, 'On Being');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1090, 'همه لایق یک مدیر عالی هستند', '6 تمرین حیاتی برای رهبری یک تیم', '6 تمرین حیاتی برای رهبری یک تیم', 22, 7, 'book', 't', '<p><em>همه لیاقت یک مدیر عالی را دارند </em>(2019) شش روش حیاتی را به رهبران کسب و کار ارائه می دهد که اعضای تیم را به افراد با عملکرد بالا تبدیل می کند. با ارائه راه‌حل‌های عملی، شکافی را که بسیاری از مدیران جدید بدون دریافت هیچ گونه آموزش رهبری ارتقا می‌یابند، پر می‌کند. </p>', '2022-02-07 00:00:00', 5, 234, 'https://images.blinkist.io/images/books/61f7d8ab6cee0700086389d3/1_1/470.jpg', '/en/books/everyone-deserves-a-great-manager-en/purchase', 'همه-لایق-یک-مدیر-عالی-هستند', '2023-01-27 01:24:20.926376', '2023-01-27 01:24:20.926376', NULL, 'Everyone Deserves a Great Manager');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1091, 'عادت هشتم', 'از اثربخشی تا عظمت', 'از اثربخشی تا عظمت', 17, 8, 'book', 't', '<p><em>عادت هشتم</em> (2004) به شما کمک می کند صدای درونی خود را پیدا کنید و در نتیجه زندگی کامل تری داشته باشید. کاوی توضیح می دهد که چرا ما برای احساس انگیزه و اشتیاق (به ویژه در زندگی کاری خود) تلاش می کنیم و چگونه می توانیم آن را تغییر دهیم.</p>', '2015-09-24 00:00:00', 4, 343, 'https://images.blinkist.io/images/books/55fffd1d615cd1000900009e/1_1/470.jpg', '/en/books/the-8th-habit-en/purchase', 'عادت-هشتم', '2023-01-27 01:24:34.664156', '2023-01-27 01:24:34.664156', NULL, 'The 8th Habit');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1092, 'وراثت', 'چگونه ژن های ما زندگی ما را تغییر می دهند و زندگی ما ژن های ما را تغییر می دهد', 'چگونه ژن های ما زندگی ما را تغییر می دهند و زندگی ما ژن های ما را تغییر می دهد', 16, 7, 'book', 't', '<p><em>ارث </em>(2014) دلیلی بر این است که برای درک اهمیت ژنتیک خود نیازی به دانشمند بودن ندارید. این پلک‌ها توضیح می‌دهند که DNA شما چگونه بر زندگی روزمره شما تأثیر می‌گذارد، از ظاهر شما و آنچه می‌خورید تا میزان حساسیت شما به مواردی مانند اضطراب و بیماری. پس خود را با دانش مسلح کنید و درباره ژن‌هایی که شما را همان چیزی که هستید می‌سازند، اطلاعات بیشتری کسب کنید.</p>', '2017-09-14 00:00:00', 4, 39, 'https://images.blinkist.io/images/books/59b7f676b238e10005c1fb09/1_1/470.jpg', '/en/books/inheritance-en/purchase', 'وراثت', '2023-01-27 01:24:56.160837', '2023-01-27 01:24:56.160837', NULL, 'Inheritance');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1093, 'نمیتونی به من صدمه بزنی', 'بر ذهن خود مسلط شوید و از شانس ها سرپیچی کنید', 'بر ذهن خود مسلط شوید و از شانس ها سرپیچی کنید', 18, 6, 'book', 't', '<p><em>Can’t Hurt Me</em>(2018) داستان زندگی واقعی الهام بخش دیوید گوگینز، یکی از خوش اندام ترین مردان جهان است. پلک‌ها رویدادهای کلیدی زندگی این ورزشکار و مرد نظامی الهام‌بخش را بررسی می‌کنند و بینش شگفت‌انگیزی از یک ذهن واقعا متمرکز و شکست ناپذیر ارائه می‌دهند.</p>', '2019-01-21 00:00:00', 4, 612, 'https://images.blinkist.io/images/books/5c43af116cee070007b96086/1_1/470.jpg', '/en/books/cant-hurt-me-en/purchase', 'نمیتونی-به-من-صدمه-بزنی', '2023-01-27 01:25:18.051543', '2023-01-27 01:25:18.051543', NULL, 'Can’t Hurt Me');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1094, 'هنر زنانه شیردهی', 'از بارداری تا از شیر گرفتن، کتابی که هر شیردهی به آن نیاز دارد', 'از بارداری تا از شیر گرفتن، کتابی که هر شیردهی به آن نیاز دارد', 15, 8, 'book', 't', '<p><em>هنر زنانه شیردهی</em> (2010) نسخه به روز شده راهنمای کلاسیک و قطعی در مورد شیردهی است. بر اساس این فرض که تغذیه با شیر مادر باید استاندارد اولیه تغذیه کودک باشد، این کتاب پاسخ ها و تکنیک هایی را برای چالش های رایج و مبهم شیردهی ارائه می دهد.</p>', '2023-01-18 00:00:00', NULL, 1, 'https://images.blinkist.io/images/books/63c65cebca3d9100087f3eec/1_1/470.jpg', '/en/books/the-womanly-art-of-breastfeeding-en/purchase', 'هنر-زنانه-شیردهی', '2023-01-27 01:25:39.606477', '2023-01-27 01:25:39.606477', NULL, 'The Womanly Art of Breastfeeding');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1095, 'اسطوره الکترونیکی مورد بازبینی قرار گرفت', 'چرا اکثر مشاغل کوچک کار نمی کنند و در مورد آن چه باید کرد؟', 'چرا اکثر مشاغل کوچک کار نمی کنند و در مورد آن چه باید کرد؟', 26, 12, 'book', 't', '<p>در نسخه اصلاح شده و به روز شده کتاب معروف خود <em>The</em> <em>E-Myth</em>، نویسنده مایکل گربر اسطوره های مختلفی را در مورد آنچه که در راه اندازی یک کسب و کار کوچک دخیل است و نحوه انجام کسب و کار را موفق کند <em></em> <em>اسطوره الکترونیکی</em> <em>بازبینی شده</em> که شما را در هر مرحله از نحوه ایجاد یک کسب و کار راهنمایی می کند، تفاوت مهم بین کار کردن در <em>در</em> را برجسته می کند. em> کسب و کار شما و کار <em>روی</em> کسب و کار شما.</p>', '2014-07-22 00:00:00', 5, 268, 'https://images.blinkist.io/images/books/53cf7bc43630650007ac0000/1_1/470.jpg', '/en/books/the-e-myth-revisited-en/purchase', 'اسطوره-الکترونیکی-مورد-بازبینی-قرار-گرفت', '2023-01-27 01:26:03.172627', '2023-01-27 01:26:03.172627', NULL, 'The E-Myth Revisited');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1096, 'کارهای خوب!', 'بازاریابی و ابتکارات شرکتی که دنیای بهتری را می سازند ... و خط آخر', 'بازاریابی و ابتکارات شرکتی که دنیای بهتری را می سازند ... و خط آخر', 17, 7, 'book', 't', '<p><em>کارهای خوب!</em> (2012) نگاهی روشنگر به روشی ارائه می دهد که انجام کارهای خوب می تواند در واقع به پیشرفت شرکت ها کمک کند. بر اساس مثال‌های امروزی و واقعی، ابزارها و استراتژی‌هایی را در اختیار افراد صاحب نظر تجاری قرار می‌دهد که برای ایجاد تغییر در جهان و در عین حال سودآوری نیاز دارند.</p>', '2015-04-14 00:00:00', NULL, 8, 'https://images.blinkist.io/images/books/552bdc526466340007590000/1_1/470.jpg', '/en/books/good-works-en/purchase', 'کارهای-خوب!', '2023-01-27 01:26:21.701703', '2023-01-27 01:26:21.701703', NULL, 'Good Works!');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1097, 'پیشرو از هر کجا', 'قفل قدرت و عملکرد تیم های راه دور را باز کنید', 'قفل قدرت و عملکرد تیم های راه دور را باز کنید', 21, 6, 'book', 't', '<p><em>Leading from Anywhere </em>(2021) راهنمای هدایت یک تیم راه دور است که همه چیز را از ایجاد فرهنگ شرکت، مدیریت عملکرد، و برگزاری جلسات مجازی گرفته تا ارائه بازخورد به اعضای تیم را پوشش می‌دهد. علاوه بر تعیین بهترین راه برای مدیریت یک تیم از راه دور، به طور کلی یک مورد قوی برای کار از راه دور ایجاد می کند. </p>', '2021-04-16 00:00:00', 4, 150, 'https://images.blinkist.io/images/books/607018046cee070007aad574/1_1/470.jpg', '/en/books/leading-from-anywhere-en/purchase', 'پیشرو-از-هر-کجا', '2023-01-27 01:26:36.281472', '2023-01-27 01:26:36.281472', NULL, 'Leading from Anywhere');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1098, 'علم زیستن', '۲۱۹ دلیل برای تجدید نظر در روال روزانه', '۲۱۹ دلیل برای تجدید نظر در روال روزانه', 20, 7, 'book', 't', '<p><em>The Science of Living </em>(2020) علم پشت کارهایی را که هر روز انجام می‌دهید بررسی می‌کند و برخی از افسانه‌های رایجی را که عادات شما را شکل می‌دهند، از بین می‌برد. با انجام این کار، به شما کمک می کند روزهای خود را بهتر برنامه ریزی کنید تا بتوانید زندگی سالم تر، شادتر و پربارتر داشته باشید.</p>', '2021-04-22 00:00:00', 4, 258, 'https://images.blinkist.io/images/books/60795b176cee070007bf944b/1_1/470.jpg', '/en/books/the-science-of-living-en/purchase', 'علم-زیستن', '2023-01-27 01:26:57.166476', '2023-01-27 01:26:57.166476', NULL, 'The Science of Living');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1099, 'ایمان دیوانه', 'این فقط دیوانه است تا زمانی که اتفاق بیفتد', 'این فقط دیوانه است تا زمانی که اتفاق بیفتد', 20, 7, 'book', 't', '<p><em>Crazy Faith</em>(2021) ماهیت چند وجهی ایمان مدرن را بررسی می کند. این توضیح می‌دهد که چگونه داستان‌های کلیدی از کتاب مقدس هنوز با چالش‌هایی که امروز با آن روبرو هستیم مرتبط هستند، و راه‌حل‌های مبتنی بر ایمان را برای استرس‌های زندگی روزمره ارائه می‌دهد.</p>', '2022-03-18 00:00:00', 4, 193, 'https://images.blinkist.io/images/books/62347dc16cee0700080753b8/1_1/470.jpg', '/en/books/crazy-faith-en/purchase', 'ایمان-دیوانه', '2023-01-27 01:27:15.687773', '2023-01-27 01:27:15.687773', NULL, 'Crazy Faith');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1100, 'از قدرت به قدرت', 'یافتن موفقیت، شادی و هدف عمیق در نیمه دوم زندگی', 'یافتن موفقیت، شادی و هدف عمیق در نیمه دوم زندگی', 19, 4, 'book', 't', '<p><em>از قدرت تا قدرت </em>(2022) نقشه راهی برای شکوفایی در نیمه دوم زندگی است. مملو از توصیه‌های عملی، به خوانندگان کمک می‌کند تا روی موفقیت‌های گذشته تمرکز نکنند و در زمان حال تحقق پیدا کنند.</p>', '2022-04-28 00:00:00', 5, 522, 'https://images.blinkist.io/images/books/62694bd46cee0700084609df/1_1/470.jpg', '/en/books/from-strength-to-strength-en/purchase', 'از-قدرت-به-قدرت', '2023-01-27 01:42:38.751315', '2023-01-27 01:42:38.751315', NULL, 'From Strength to Strength');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1101, 'ریمیکس', 'چگونه در محل کار چند نسلی رهبری و موفق شویم', 'چگونه در محل کار چند نسلی رهبری و موفق شویم', 12, 4, 'book', 't', '<p><em>ریمیکس</em> (2019) اهمیت ایجاد و حفظ یک فضای کاری چند نسلی را نشان می‌دهد که همه را شامل می‌شود. ترکیبی از داده‌های اخیر، تحقیقات مستقل و مطالعات موردی از شرکت‌های Fortune 500، به تیم‌ها نشان می‌دهد که چگونه سبک‌های کاری متنوع را بپذیرند و برخوردهای احتمالی را به فرصت تبدیل کنند.</p>', '2022-11-08 00:00:00', NULL, 6, 'https://images.blinkist.io/images/books/636a1386958fe900087a3807/1_1/470.jpg', '/en/books/the-remix-en/purchase', 'ریمیکس', '2023-01-27 01:42:43.951151', '2023-01-27 01:42:43.951151', NULL, 'The Remix');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1102, 'اولین مسلمان', 'داستان محمد', 'داستان محمد', 16, 8, 'book', 't', '<p><em>اولین مسلمان</em> (2013) داستان باورنکردنی پیامبر اسلام، اولین عضو ایمان اسلامی را شرح می دهد. این پلک ها شما را به قبل از تولد حضرت محمد (ص) بازمی گرداند و داستان کامل بعثت خداوند بر این پیامبر، نحوه گسترش اسلام و نظر معاصرانش در مورد عقاید او را بیان می کند.</p>', '2017-06-09 00:00:00', 4, 67, 'https://images.blinkist.io/images/books/593553aeb238e100051fda9f/1_1/470.jpg', '/en/books/the-first-muslim-en/purchase', 'اولین-مسلمان', '2023-01-27 01:42:51.37747', '2023-01-27 01:42:51.37747', NULL, 'The First Muslim');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1103, 'ثروتمندترین مرد بابل', 'اکنون برای قرن بیست و یکم بازبینی و به روز شده است', 'اکنون برای قرن بیست و یکم بازبینی و به روز شده است', 17, 9, 'book', 't', '<p><em>ثروتمندترین مرد بابل – اکنون برای قرن بیست و یکم بازبینی و به روز شده است</em> مجموعه ای از مثل ها در بابل باستان درباره خرد مالی است. در این پلک‌ها، این تمثیل‌ها را می‌بینید که به توصیه‌های امروزی تقطیر شده‌اند که می‌توانند به شما در جمع‌آوری ثروت کمک کنند.</p>', '2014-04-15 06:29:16', 4, 507, 'https://images.blinkist.io/images/books/534d4cb46633610007320000/1_1/470.jpg', '/en/books/the-richest-man-in-babylon-en/purchase', 'ثروتمندترین-مرد-بابل', '2023-01-27 01:42:58.678738', '2023-01-27 01:42:58.678738', NULL, 'The Richest Man in Babylon');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1104, 'ارزش بدهی در ساختن ثروت', 'ایجاد مسیر سرخوردن خود برای یک L.I.F.E مالی سالم', 'ایجاد مسیر سرخوردن خود برای یک L.I.F.E مالی سالم', 17, 5, 'book', 't', '<p><em>ارزش بدهی در ایجاد ثروت </em>(2017) یک راهنمای عملی برای مدیریت امور مالی شخصی شما است. این کتاب راهنما به جای محکوم کردن هزینه‌ها، راهبردهایی برای تبدیل بدهی به دارایی خود ارائه می‌کند.</p>', '2020-11-12 00:00:00', 4, 146, 'https://images.blinkist.io/images/books/5fa5564b6cee070006bad8e0/1_1/470.jpg', '/en/books/the-value-of-debt-in-building-wealth-en/purchase', 'ارزش-بدهی-در-ساختن-ثروت', '2023-01-27 01:43:05.544139', '2023-01-27 01:43:05.544139', NULL, 'The Value of Debt in Building Wealth');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1105, 'مقیاس پلت فرم', 'چگونه یک مدل کسب و کار نوظهور به استارت آپ ها کمک می کند تا با حداقل سرمایه گذاری امپراتوری های بزرگ بسازند', 'چگونه یک مدل کسب و کار نوظهور به استارت آپ ها کمک می کند تا با حداقل سرمایه گذاری امپراتوری های بزرگ بسازند', 18, 8, 'book', 't', '<p>نوع جدیدی از کسب و کار در دهه گذشته ظهور کرده است. فیس بوک، Airbnb، یوتیوب، توییتر محبوبیت زیادی پیدا کرده اند – اما این شرکت ها چه چیزی مشترک دارند؟ همه آنها پلتفرم هستند: میلیون ها کاربر را جمع آوری می کنند و به ارزش های میلیارد دلاری می رسند، اما به جای محصولات، چیزهای بسیار متفاوتی را ارائه می دهند. <em>مقیاس پلتفرم</em> (2015) تجزیه و تحلیل دقیقی از مکانیسم‌هایی ارائه می‌کند که این مدل کسب‌وکار پلتفرم جدید را هدایت می‌کند و اینکه چگونه به رشد سرسام‌آور دست می‌یابد.</p>', '2016-04-26 00:00:00', 5, 42, 'https://images.blinkist.io/images/books/5717a37b3f35690007554e19/1_1/470.jpg', '/en/books/platform-scale-en/purchase', 'مقیاس-پلت-فرم', '2023-01-27 01:43:12.970659', '2023-01-27 01:43:12.970659', NULL, 'Platform Scale');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1106, 'انتظار بهتر', 'چرا حکمت مرسوم بارداری اشتباه است و آنچه واقعاً باید بدانید؟', 'چرا حکمت مرسوم بارداری اشتباه است و آنچه واقعاً باید بدانید؟', 25, 8, 'book', 't', '<p><em>انتظار بهتر </em>(2013) با از بین بردن ابهامات افسانه های بارداری و افشای حقایق واقعی، به مادران آینده آرامش می دهد. نویسنده امیلی اوستر، اقتصاددان برجسته، خرد متعارف را به چالش می کشد و آن را دوباره ارزیابی می کند تا بتوانید تصمیمات خود را برای بارداری شاد و سالم بگیرید.</p>', '2020-04-21 00:00:00', 4, 55, 'https://images.blinkist.io/images/books/5e9980396cee070007b55daa/1_1/470.jpg', '/en/books/expecting-better-en/purchase', 'انتظار-بهتر', '2023-01-27 01:43:18.170436', '2023-01-27 01:43:18.170436', NULL, 'Expecting Better');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1107, 'غذاهای نابغه', 'باهوش‌تر، شادتر و سازنده‌تر شوید و از مغزتان برای زندگی محافظت کنید', 'باهوش‌تر، شادتر و سازنده‌تر شوید و از مغزتان برای زندگی محافظت کنید', 25, 9, 'book', 't', '<p><em>غذاهای نابغه </em> (2018) به یک نکته ساده اما قانع کننده اشاره می کند: آنچه امروز می خوریم باعث گرسنگی مغزمان می شود. با تکیه بر به روزترین تحقیقات علمی، نقاط را به هم متصل می کند و نشان می دهد که چگونه رژیم غذایی ما می تواند بر سلامت شناختی ما تأثیر بگذارد. اما این فقط یک رساله آکادمیک نیست - این یک برنامه عملی است که شما را در مسیر چابکی ذهنی بیشتر، تعادل و زندگی شادتر قرار می دهد و در عین حال از خود در برابر زوال عقل محافظت می کند.</p>', '2018-09-26 00:00:00', 5, 382, 'https://images.blinkist.io/images/books/5ba81194862c4300070469ce/1_1/470.jpg', '/en/books/genius-foods-en/purchase', 'غذاهای-نابغه', '2023-01-27 01:43:25.273656', '2023-01-27 01:43:25.273656', NULL, 'Genius Foods');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1108, 'بودای زنده، مسیح زنده', 'زمینه مشترک مسیحیت و بودیسم را بررسی کنید', 'زمینه مشترک مسیحیت و بودیسم را بررسی کنید', 25, 7, 'book', 't', '<p><em>بودای زنده، مسیح زنده </em>(1995) مراقبه ای است در مورد تقاطع های شگفت انگیز بین بودیسم و ​​مسیحیت. این متن متفکر، زمینه مشترک دو تن از تأثیرگذارترین رهبران معنوی جهان را نشان می‌دهد.</p>', '2021-08-08 00:00:00', 4, 224, 'https://images.blinkist.io/images/books/6103a1406cee070007903c03/1_1/470.jpg', '/en/books/living-buddha-living-christ-en/purchase', 'بودای-زنده،-مسیح-زنده', '2023-01-27 01:43:30.536194', '2023-01-27 01:43:30.536194', NULL, 'Living Buddha, Living Christ');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1109, 'راه اندازی شما', 'با آینده سازگار شوید، روی خود سرمایه گذاری کنید و شغل خود را متحول کنید', 'با آینده سازگار شوید، روی خود سرمایه گذاری کنید و شغل خود را متحول کنید', 14, 8, 'book', 't', '<p><em>The Start-Up of You</em> (2012) راهنمایی است برای اینکه چگونه می‌توانید از استراتژی‌های مورد استفاده استارت‌آپ‌ها در حرفه خود استفاده کنید: سازگار بودن، ایجاد روابط و دنبال کردن فرصت‌های شکست.</ p>
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1110, 'فروش جدید. ساده شده.', 'کتاب راهنمای ضروری برای جستجو و توسعه کسب و کار جدید', 'کتاب راهنمای ضروری برای جستجو و توسعه کسب و کار جدید', 20, 8, 'book', 't', '<p><em>فروش جدید. ساده شده. </em>(2012) راهنمایی برای کسانی است که مسئول یافتن کسب و کار جدید هستند. نگاهی به اصول اولیه می‌اندازد و توصیه‌ها و تکنیک‌های عملی را به فروشنده مشتاق کسب‌وکار جدید ارائه می‌دهد.</p>', '2022-03-22 00:00:00', 4, 98, 'https://images.blinkist.io/images/books/623886396cee070008e4ca3c/1_1/470.jpg', '/en/books/new-sales-simplified-en/purchase', 'فروش-جدید.-ساده-شده.', '2023-01-27 01:43:45.308263', '2023-01-27 01:43:45.308263', NULL, 'New Sales. Simplified.');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1111, 'ضریب هوشی رشد', 'در مورد انتخاب هایی که کسب و کار شما را می سازند یا از بین می برند هوشمندتر باشید', 'در مورد انتخاب هایی که کسب و کار شما را می سازند یا از بین می برند هوشمندتر باشید', 25, 10, 'book', 't', '<p><em>ضریب هوشی رشد</em> (2018) به این سوال میلیون دلاری پاسخ می دهد که چگونه کسب و کار خود را رشد دهید. مملو از توصیه‌های عملی، نکات و استراتژی‌هایی که از کارآفرینان برتر امروزی و شرکت‌های آنها جمع‌آوری شده‌اند، این راهنمای نهایی برای تصمیم‌گیری هوشمندانه است که به شرکت‌های در مراحل اولیه کمک می‌کند تا از زمین خارج شوند یا غول‌های راکد را جوان کنند.</p>', '2019-02-21 00:00:00', 4, 91, 'https://images.blinkist.io/images/books/5c6bdaf06cee070007fe6a0f/1_1/470.jpg', '/en/books/growth-iq-en/purchase', 'ضریب-هوشی-رشد', '2023-01-27 01:43:52.150098', '2023-01-27 01:43:52.150098', NULL, 'Growth IQ');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1112, 'کل پول Makeover', 'یک برنامه اثبات شده برای تناسب اندام مالی', 'یک برنامه اثبات شده برای تناسب اندام مالی', 16, 8, 'book', 't', '<p><em>Total Money Makeover</em> (2013) یک راهنمای گام به گام برای تغییر وضعیت مالی شما است، مهم نیست که چقدر بد به نظر می رسد. با دنبال کردن این هفت مرحله ساده، می توانید امنیت مالی را به زندگی خود بازگردانید و برنامه ریزی برای بازنشستگی راحت و رضایت بخش را آغاز کنید.</p>', '2015-03-31 00:00:00', 4, 200, 'https://images.blinkist.io/images/books/55189bb43961320007570000/1_1/470.jpg', '/en/books/the-total-money-makeover-en/purchase', 'کل-پول-Makeover', '2023-01-27 01:43:59.047346', '2023-01-27 01:43:59.047346', NULL, 'The Total Money Makeover');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1113, 'تسهیل پیشرفت', 'چگونه موانع را از بین ببریم، تفاوت ها را پل بزنیم و با هم به جلو حرکت کنیم', 'چگونه موانع را از بین ببریم، تفاوت ها را پل بزنیم و با هم به جلو حرکت کنیم', 15, 4, 'book', 't', '<p><em>تسهیل پیشرفت </em>(2021) به این موضوع می پردازد که چگونه مردم می توانند حل نشدنی ترین مشکلات خود را حل کنند. با استفاده از رویکردی که طی دهه‌ها بهبود یافته است، می‌توانید یاد بگیرید که چگونه موانع را از درگیری‌ها حذف کنید و به سمت حل و فصل پیشرفت کنید.</p>', '2022-12-13 00:00:00', 4, 19, 'https://images.blinkist.io/images/books/63984427ac44630009457065/1_1/470.jpg', '/en/books/facilitating-breakthrough-en/purchase', 'تسهیل-پیشرفت', '2023-01-27 01:44:06.456489', '2023-01-27 01:44:06.456489', NULL, 'Facilitating Breakthrough');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1114, 'فریب ایکاروس', 'چقدر بلند پرواز خواهید کرد؟', 'چقدر بلند پرواز خواهید کرد؟', 19, 8, 'book', 't', '<em>فریب ایکاروس </em> (2012) اسطوره‌ای به قدمت یونانیان باستان را هدف قرار می‌دهد – که هدف گرفتن از بالا قطعاً با اشک به پایان می‌رسد. ایکاروس ممکن است خیلی نزدیک به خورشید پرواز کرده باشد، اما معمولا فراموش می کنیم که به او هشدار داده شده بود که خیلی پایین پرواز نکند. چرا این مهم است؟ خوب، ما در اقتصاد جدیدی زندگی می کنیم که در آن حفظ ارتفاع با کروز کنترل باعث کاهش آن نمی شود. اقتصاد جدید، جهانی و متصل اینجاست که بماند و زمانی که مشاغل «ایمن» خودکار شوند. کسانی که می‌خواهند بهتر پیشرفت کنند، اهداف خود را بالا می‌برند. و این بیش از همه به معنای یک چیز است: زندگی و کار خلاقانه.</p>', '2018-10-31 00:00:00', 4, 72, 'https://images.blinkist.io/images/books/5bd6163f6cee070007206451/1_1/470.jpg', '/en/books/the-icarus-deception-en/purchase', 'فریب-ایکاروس', '2023-01-27 01:44:11.557809', '2023-01-27 01:44:11.557809', NULL, 'The Icarus Deception');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1115, 'رشد کارکنان بزرگ', 'تبدیل افراد معمولی به مجریان خارق العاده', 'تبدیل افراد معمولی به مجریان خارق العاده', 15, 7, 'book', 't', '<p><em>در حال رشد کارکنان عالی </em>(2006) در مورد مربیگری، مدیریت و رهبری است. اریکا اندرسن، مشاور و مدیر عامل، با استفاده از باغبانی به عنوان استعاره ای که در سراسر کتاب وجود دارد، به طرز هوشمندانه ای توضیح می دهد که چگونه می توان با موفقیت کارمندانی موفق و سازنده را توسعه داد.</p>', '2015-05-08 00:00:00', 4, 24, 'https://images.blinkist.io/images/books/554784b43666320007dc0000/1_1/470.jpg', '/en/books/growing-great-employees-en/purchase', 'رشد-کارکنان-بزرگ', '2023-01-27 01:44:18.746552', '2023-01-27 01:44:18.746552', NULL, 'Growing Great Employees');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1116, 'چقدر کافی است؟', 'پول و زندگی خوب', 'پول و زندگی خوب', 15, 8, 'book', 'f', '<p><em>چگونه</em> <em>چقدر</em> <em>بسیار است</em> <em>کافی است</em> برای آگاه کردن انتقادی خواننده در مورد زمینه‌های اخلاقی، تاریخی و اقتصادی سرمایه داری مدرن، وسواس آن برای انباشت بیشتر و بیشتر، و پیامدهای آن. همچنین به شدت یک جایگزین اخلاقی را برای این سبک زندگی ترسیم می کند، که در آن وسواس ما به "بیشتر" با "زندگی خوب" جایگزین می شود.</p>', '2014-08-12 00:00:00', 4, 23, 'https://images.blinkist.io/images/books/53e89b7533383300071d0000/1_1/470.jpg', '/en/books/how-much-is-enough-en/purchase', 'چقدر-کافی-است؟', '2023-01-27 01:44:26.719351', '2023-01-27 01:44:26.719351', NULL, 'How Much is Enough?');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1117, 'هنر انتظار', 'درباره باروری، پزشکی و مادری', 'درباره باروری، پزشکی و مادری', 12, 5, 'book', 't', '<p><em>هنر انتظار</em>(2016) روایت‌های اجتماعی پیرامون تولد، بارداری و فرزندپروری را شرح می‌دهد. این پلک‌ها حکایت‌های شخصی تکان‌دهنده‌ای را در کنار نمونه‌های تاریخی ارائه می‌دهند تا توجه را به داستان‌های اغلب ناشنیده‌ای از فرزندخواندگی، <em>لقاح آزمایشگاهی </em>و عقیم‌سازی اجباری معطوف کند.', '2017-04-06 00:00:00', 3, 15, 'https://images.blinkist.io/images/books/58e2004ffe685600046c9341/1_1/470.jpg', '/en/books/the-art-of-waiting-en/purchase', 'هنر-انتظار', '2023-01-27 01:44:33.702494', '2023-01-27 01:44:33.702494', NULL, 'The Art of Waiting');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1118, 'گفتگوهای دشوار', 'چگونه در مورد آنچه که بیشتر اهمیت دارد بحث کنیم', 'چگونه در مورد آنچه که بیشتر اهمیت دارد بحث کنیم', 14, 6, 'book', 't', '<p><em>مکالمات دشوار </em>(1999) به این موضوع می پردازد که چه چیزی یک مکالمه را دشوار می کند و چرا اغلب سعی می کنیم از آنها اجتناب کنیم. نحوه برخورد صحیح و مانور دادن در موضوعات سخت برای ایجاد روابط مثبت و معنادار را تشریح می کند.</p>', '2018-09-20 00:00:00', 4, 236, 'https://images.blinkist.io/images/books/5ba1ffa7862c43000776ae16/1_1/470.jpg', '/en/books/difficult-conversations-en/purchase', 'گفتگوهای-دشوار', '2023-01-27 01:44:41.114901', '2023-01-27 01:44:41.114901', NULL, 'Difficult Conversations');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1119, 'قوانین استراتژی', 'پنج درس بی انتها از بیل گیتس، اندی گروو و استیو جابز', 'پنج درس بی انتها از بیل گیتس، اندی گروو و استیو جابز', 19, 7, 'book', 't', '<p><em>قوانین استراتژی</em> (2015) استراتژی‌های تجاری و سبک‌های رهبری سه مدیر عامل فناوری فوق‌العاده موفق را بررسی می‌کند: بیل گیتس از مایکروسافت، اندی گروو از اینتل و استیو جابز از اپل. این پلک ها تخصص استراتژیک لازم برای ایجاد یک کسب و کار رقابتی و تضمین موفقیت بلندمدت را از بین می برند.</p>', '2015-06-09 00:00:00', 4, 75, 'https://images.blinkist.io/images/books/557594313935610007300000/1_1/470.jpg', '/en/books/strategy-rules-en/purchase', 'قوانین-استراتژی', '2023-01-27 01:44:48.227358', '2023-01-27 01:44:48.227358', NULL, 'Strategy Rules');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1120, 'فرضیه پرورش', 'چرا بچه ها آنطور که انجام می دهند رفتار می کنند؟', 'چرا بچه ها آنطور که انجام می دهند رفتار می کنند؟', 16, 8, 'book', 't', '<p><em>فرض پرورش</em> (1998) به بحث طولانی مدت در مورد نقش طبیعت و پرورش می پردازد. این پلک‌ها عوامل مختلفی را توضیح می‌دهند که بر رشد کودک تأثیر می‌گذارند و این موضع غالب را که کودکان محصول تربیت آنها هستند، از بین می‌برد.</p>', '2016-05-12 00:00:00', 4, 52, 'https://images.blinkist.io/images/books/572ef324a35db30003e6bded/1_1/470.jpg', '/en/books/the-nurture-assumption-en/purchase', 'فرضیه-پرورش', '2023-01-27 01:44:55.622588', '2023-01-27 01:44:55.622588', NULL, 'The Nurture Assumption');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1121, 'بی شرم', 'اصلاحات جنسی', 'اصلاحات جنسی', 18, 6, 'book', 't', '<p><em>بی شرم</em> (2019) به بررسی این موضوع می‌پردازد که چگونه دیدگاه کلیسا در مورد جنسیت و تمایلات جنسی به عنوان گناهکار باعث گناه و شرمساری هم‌نشینانش شده است. نویسنده از طریق داستان‌های شخصی و داستان‌هایی که اعضای کلیسایش با او به اشتراک گذاشته‌اند، اثرات مضر آموزه‌های کلیسا را ​​نشان می‌دهد. او روشی جدید و فراگیر برای نزدیک شدن به مسائل جنسی و تضمین زندگی جنسی رضایت بخش برای همه ارائه می دهد.</p>', '2020-04-28 00:00:00', 3, 97, 'https://images.blinkist.io/images/books/5ea31d026cee070006614d8a/1_1/470.jpg', '/en/books/shameless-en/purchase', 'بی-شرم', '2023-01-27 01:45:02.97314', '2023-01-27 01:45:02.97314', NULL, 'Shameless');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1122, 'متفکر نمونه', 'آنچه شما باید بدانید تا داده ها برای شما کار کنند', 'آنچه شما باید بدانید تا داده ها برای شما کار کنند', 20, 7, 'book', 't', '<p><em>The Model Thinker</em>(2018) راهنمای استفاده از مدل‌ها برای ایجاد گفتگو در مورد داده‌ها است. در جهانی پر از اطلاعات، نور بسیار مورد نیاز را بر الگوهای زیربنای سر و صدا می اندازد - و ما را به راه هایی راهنمایی می کند که می توانیم آن الگوها را برای خود آشکار کنیم.</p>', '2021-06-21 00:00:00', 4, 149, 'https://images.blinkist.io/images/books/60cc437d6cee07000810fdd5/1_1/470.jpg', '/en/books/the-model-thinker-en/purchase', 'متفکر-نمونه', '2023-01-27 01:45:10.335515', '2023-01-27 01:45:10.335515', NULL, 'The Model Thinker');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1123, 'کتاب راهنمای مستقیم به مصرف کننده', 'داستان ها و استراتژی های برندهایی که قوانین DTC را نوشته اند', 'داستان ها و استراتژی های برندهایی که قوانین DTC را نوشته اند', 17, 4, 'book', 't', '<p><em>کتاب راهنمای مستقیم به مصرف کننده </em>(2022) نگاهی می‌اندازد به اینکه چگونه برخی از برندهای برتر تجارت الکترونیک جهان به جایگاه امروزی خود رسیده‌اند. از طریق مجموعه‌ای از مصاحبه‌های الهام‌بخش با بنیان‌گذاران DTC، داستان‌هایی از شکست و موفقیت را کشف خواهید کرد – و موقعیت بهتری برای ایجاد شرکت DTC خود خواهید داشت.</p>', '2022-11-29 00:00:00', 4, 30, 'https://images.blinkist.io/images/books/63808d5dba31850008d6c389/1_1/470.jpg', '/en/books/the-direct-to-consumer-playbook-en/purchase', 'کتاب-راهنمای-مستقیم-به-مصرف-کننده', '2023-01-27 01:45:18.261363', '2023-01-27 01:45:18.261363', NULL, 'The Direct to Consumer Playbook');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1124, 'به طور کامل ارائه شود', 'علم، هنر و تمرین ذهن آگاهی', 'علم، هنر و تمرین ذهن آگاهی', 21, 8, 'book', 't', '<p><em>Fully Present</em> (2010) یک راهنمای عملی برای تمرکز حواس است که مملو از نکات کاربردی است که به شما کمک می کند تا از تمرین باستانی امروز استفاده کنید. بر اساس تخصص دو تن از محققان برجسته امروزی تمرکز حواس، این پلک ها شما را از طریق علم و هنر مدیتیشن راهنمایی می کنند و به شما نشان می دهند که چگونه آن را در زندگی روزمره خود ادغام کنید و شروع به تبدیل فعالیت های روزمره به تجربیات غنی کنید.</p>', '2019-01-25 00:00:00', 5, 152, 'https://images.blinkist.io/images/books/5c49dafd6cee070007b962a4/1_1/470.jpg', '/en/books/fully-present-en/purchase', 'به-طور-کامل-ارائه-شود', '2023-01-27 01:45:25.509792', '2023-01-27 01:45:25.509792', NULL, 'Fully Present');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1125, 'کانبان شخصی', 'نقشه برداری کار / مسیریابی زندگی', 'نقشه برداری کار / مسیریابی زندگی', 17, 8, 'book', 't', '<p><em>کانبان شخصی</em> (2011) یک ابزار سازگار برای افراد بصری گرا است. این به شما کمک می کند تا زندگی و کار خود را سازماندهی کنید و بین این دو تعادل ایجاد کنید. این پلک ها به شما می آموزند که چگونه کانبان خود را راه اندازی کنید و چگونه آن را عملی کنید و در نتیجه کارایی خود را به حداکثر برسانید. آنها همچنین بینش هایی را در مورد الگوهای زندگی ارائه می دهند و به شما امکان می دهند پیشرفت را اندازه گیری کرده و وظایف موجود در بشقاب خود را محدود کنید.</p>', '2015-09-16 00:00:00', 4, 106, 'https://images.blinkist.io/images/books/55f6e5f829161a00090000dc/1_1/470.jpg', '/en/books/personal-kanban-en/purchase', 'کانبان-شخصی', '2023-01-27 01:45:33.453452', '2023-01-27 01:45:33.453452', NULL, 'Personal Kanban');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1126, 'شبکه عنکبوتی', 'داستان وحشیانه یک نابغه ریاضی، گروهی از بانکداران پشت خنجر، و یکی از بزرگترین کلاهبرداری های تاریخ مالی', 'داستان وحشیانه یک نابغه ریاضی، گروهی از بانکداران پشت خنجر، و یکی از بزرگترین کلاهبرداری های تاریخ مالی', 18, 7, 'book', 't', '<p><em>شبکه عنکبوتی</em> (۲۰۱۷) داستان جذاب تام هیز را روایت می‌کند، مردی که عادت مخفیانه صنعت بانکداری در دستکاری نرخ‌های بهره را گرفت. این داستانی است از اتفاقی که وقتی معامله‌گران، کارگزاران و مدیران بانک اجازه دارند بدون نظارت فعالیت کنند.</p>', '2017-11-03 00:00:00', 4, 57, 'https://images.blinkist.io/images/books/59f6ed7fb238e10006f607b0/1_1/470.jpg', '/en/books/the-spider-network-en/purchase', 'شبکه-عنکبوتی', '2023-01-27 01:45:41.177713', '2023-01-27 01:45:41.177713', NULL, 'The Spider Network');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1127, 'دستور و کنترل', 'سلاح های هسته ای، حادثه دمشق، و توهم ایمنی', 'سلاح های هسته ای، حادثه دمشق، و توهم ایمنی', 27, 11, 'book', 't', '<p><em>فرماندهی و کنترل</em>(2013) حقیقت آزاردهنده‌ای را در پشت برنامه تسلیحات هسته‌ای ایالات متحده آشکار می‌کند. دریابید که واقعاً از زمان جنگ جهانی دوم، زمانی که اولین بمب هسته‌ای اختراع شد، چه اتفاقی افتاده است، و ما چقدر خوش شانس هستیم که با وجود تصادفات متعدد و تماس‌های نزدیک که می‌توانست آرماگدون را آغاز کند، هنوز اینجا هستیم. اگر فکر می‌کنید که انبار سلاح‌های هسته‌ای در ایالات متحده همیشه به طور ایمن در زیر قفل و کلید ذخیره شده است - دوباره فکر کنید!</p>', '2017-08-09 00:00:00', 5, 27, 'https://images.blinkist.io/images/books/5984f315b238e1000629009c/1_1/470.jpg', '/en/books/command-and-control-en/purchase', 'دستور-و-کنترل', '2023-01-27 01:45:48.145467', '2023-01-27 01:45:48.145467', NULL, 'Command and Control');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1128, 'تفکر در جعبه های جدید', 'پارادایم جدید برای خلاقیت تجاری', 'پارادایم جدید برای خلاقیت تجاری', 20, 8, 'book', 't', '<p><em>تفکر در جعبه‌های جدید </em>(2013) نگاهی عمیق به ذهن دارد تا درک روشنی از فرآیند خلاق ایجاد کند. این ابزار به خواننده می‌دهد تا «جعبه‌هایی» را که برای سازمان‌دهی اطلاعات، شکل دادن به درک ما از جهان و در نهایت امکان نوآوری استفاده می‌کنیم، کشف، دستکاری و حتی ایجاد کند.</p>', '2015-05-11 00:00:00', 4, 32, 'https://images.blinkist.io/images/books/5550ad1f6332630007070000/1_1/470.jpg', '/en/books/thinking-in-new-boxes-en/purchase', 'تفکر-در-جعبه-های-جدید', '2023-01-27 01:45:55.347928', '2023-01-27 01:45:55.347928', NULL, 'Thinking in New Boxes');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1129, 'واضح تر، نزدیک تر، بهتر', 'افراد موفق دنیا را چگونه می بینند', 'افراد موفق دنیا را چگونه می بینند', 26, 8, 'book', 't', '<p><em>واضح تر، نزدیکتر، بهتر</em> (2020) به ما می آموزد که جهان را از دریچه افراد موفق ببینیم. امیلی بالستیس، نویسنده، با تکیه بر علم بینایی، روانشناسی انگیزشی، و مطالعات موردی از انواع افراد موفق، به ما نشان می‌دهد که چگونه برای غلبه بر چالش‌ها و رسیدن به اهدافمان، ادراکات خود را اصلاح کنیم.</p>', '2020-10-12 00:00:00', 4, 111, 'https://images.blinkist.io/images/books/5f802ca76cee07000646ad60/1_1/470.jpg', '/en/books/clearer-closer-better-en/purchase', 'واضح-تر،-نزدیک-تر،-بهتر', '2023-01-27 01:46:02.324372', '2023-01-27 01:46:02.324372', NULL, 'Clearer, Closer, Better');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1130, 'آنالکت ها', 'قصار و حکایات از الگوی حکیمان چینی', 'قصار و حکایات از الگوی حکیمان چینی', 20, 4, 'book', 't', '<p><em>آنالکت ها</em> مجموعه ای از بیست "کتاب" است که حاوی نقل قول ها و گفته های ارزشمندی از کنفوسیوس فیلسوف چینی و همچنین شاگردانش است. قدمت این سخنان حکیمانه به هزاران سال پیش برمی‌گردد، اما در طول اعصار به طرز قابل ملاحظه‌ای مرتبط باقی مانده‌اند. </p>', '2022-06-20 20:00:00', 5, 360, 'https://images.blinkist.io/images/books/62b06f346cee07000872d68d/1_1/470.jpg', '/en/books/the-analects-en/purchase', 'آنالکت-ها', '2023-01-27 01:46:10.02409', '2023-01-27 01:46:10.02409', NULL, 'The Analects');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1131, 'ملکه مد', 'آنچه ماری آنتوانت در انقلاب پوشید', 'آنچه ماری آنتوانت در انقلاب پوشید', 14, 6, 'book', 't', '<p><em>ملکه مد</em> (2006) راه‌های ناگفته‌ای را نشان می‌دهد که ماری آنتوانت، با حس نمادین‌شکنانه‌اش از مد و رفتار شورشی‌اش، وضعیت موجود دربار فرانسه در قرن هجدهم را به چالش کشید. اصالت متهورانه او راهی برای او بود تا صدا و شخصیت خود را به اشتراک بگذارد، و داستان او چیزهای زیادی در مورد سیاست های انقلابی که در تاریخ مد و فرانسه یافت می شود به ما می گوید.</p>', '2016-09-23 00:00:00', 5, 19, 'https://images.blinkist.io/images/books/57dd860df9916500030ea79b/1_1/470.jpg', '/en/books/queen-of-fashion-en/purchase', 'ملکه-مد', '2023-01-27 01:46:16.888573', '2023-01-27 01:46:16.888573', NULL, 'Queen of Fashion');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1132, 'استارت آپ 100 دلاری', 'رئیس خود را اخراج کنید، کاری را که دوست دارید انجام دهید و بهتر کار کنید تا بیشتر زندگی کنید', 'رئیس خود را اخراج کنید، کاری را که دوست دارید انجام دهید و بهتر کار کنید تا بیشتر زندگی کنید', 20, 9, 'book', 't', '<p><em>استارت‌آپ 100 دلاری</em> راهنمای افرادی است که می‌خواهند شغل‌های 9 تا 5 خود را ترک کنند و کسب‌وکار خود را راه‌اندازی کنند. Guillebeau با استفاده از مطالعات موردی 50 کارآفرینی که کسب‌وکارهای خرد را با 100 دلار یا کمتر راه‌اندازی کرده‌اند، توصیه‌ها و ابزارهایی را در مورد چگونگی تعریف و فروش موفقیت‌آمیز یک محصول، و همچنین نحوه رشد کسب‌وکار خود از آنجا ارائه می‌دهد.</p>', '2013-09-19 00:00:00', 5, 188, 'https://images.blinkist.io/images/books/523069aae4b0678a5bde879a/1_1/470.jpg', '/en/books/the-100-dollars-startup-en/purchase', 'استارت-آپ-100-دلاری', '2023-01-27 01:46:21.769011', '2023-01-27 01:46:21.769011', NULL, 'The $100 Startup');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1133, 'کسب و کار خود را حق امتیاز دهید', 'راهنمای بکارگیری بزرگترین استراتژی رشد تا کنون', 'راهنمای بکارگیری بزرگترین استراتژی رشد تا کنون', 16, 7, 'book', 't', '<p><em>فرانچایز کسب و کار شما</em> (2016) نکات و نکات راه اندازی یک امتیاز کسب و کار را نشان می دهد. از برنده شدن بر فرنچایزها گرفته تا اطمینان از کیفیت برند شما در شاخه‌ها، این چشمک‌ها راهنمای عملی برای فرانشیز است و به شما کمک می‌کند تا کسب و کار خود را با یک استراتژی رشد قدرتمند افزایش دهید.</p>', '2016-10-07 00:00:00', 5, 21, 'https://images.blinkist.io/images/books/57f2957a90bf6100031a3faf/1_1/470.jpg', '/en/books/franchise-your-business-en/purchase', 'کسب-و-کار-خود-را-حق-امتیاز-دهید', '2023-01-27 01:46:28.493905', '2023-01-27 01:46:28.493905', NULL, 'Franchise Your Business');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1134, 'فراخوان وحشی ما', 'چگونه ارتباط با حیوانات می تواند زندگی ما را متحول کند و زندگی آنها را نجات دهد', 'چگونه ارتباط با حیوانات می تواند زندگی ما را متحول کند و زندگی آنها را نجات دهد', 19, 6, 'book', 't', '<p><em>Our Wild Calling</em> (2020) بررسی می‌کند که چگونه انسان‌ها و سایر حیوانات می‌توانند از روابط سودمند متقابل لذت ببرند. داستان‌ها و فلسفه‌های جنبش بوم‌شناختی را بررسی می‌کند و چگونگی حرکت به سوی آینده‌ای امیدوارکننده‌تر برای همه زمینیان را تشریح می‌کند. </p>', '2021-11-02 00:00:00', 5, 41, 'https://images.blinkist.io/images/books/617a8e8f6cee070008bd7aaf/1_1/470.jpg', '/en/books/our-wild-calling-en/purchase', 'فراخوان-وحشی-ما', '2023-01-27 01:46:35.238257', '2023-01-27 01:46:35.238257', NULL, 'Our Wild Calling');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1135, '60 ثانیه و شما استخدام شده اید!', 'چگونه مصاحبه را در یک دقیقه به پایان برسانیم', 'چگونه مصاحبه را در یک دقیقه به پایان برسانیم', 12, 5, 'book', 't', '<p><em>60 ثانیه و شما استخدام شده اید!</em> (1994) راهنمای شما برای انجام مصاحبه شغلی بعدی شماست. این پلک ها مملو از توصیه های عملی در مورد چگونگی جلب توجه یک کارفرمای بالقوه، فروش خود و رسیدن به شغل رویاهایتان است.</p>', '2017-04-19 00:00:00', 4, 154, 'https://images.blinkist.io/images/books/58f146a586c51e0004dd646b/1_1/470.jpg', '/en/books/60-seconds-and-youre-hired-en/purchase', '60-ثانیه-و-شما-استخدام-شده-اید!', '2023-01-27 01:46:42.205059', '2023-01-27 01:46:42.205059', NULL, '60 Seconds &amp; You’re Hired!');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1136, 'دره عجیب و غریب', 'یک خاطره', 'یک خاطره', 28, 10, 'book', 't', '<p>در اوج شکوفایی فناوری، آنا وینر زندگی حرفه‌ای بدی را در نیویورک به خاطر هجوم طلای کالیفرنیایی مدرن در سیلیکون ولی ترک کرد. او که به دنبال پول، ثبات، و تایید اجتماعی بود، صنعتی را یافت که بر اساس ارزش‌گذاری‌های متورم، منیت‌های غول‌پیکر، مردانگی سمی و بسیاری از اصطلاحات تخصصی کار می‌کرد. در <em>Uncanny Valley</em> (2020)، شما سفر او را از طریق سه شغل نوپا به سوی ارزش‌گذاری واقعی‌تر از خود دنبال خواهید کرد.</p>', '2020-02-14 00:00:00', 4, 46, 'https://images.blinkist.io/images/books/5e43678c6cee0700068c4e6a/1_1/470.jpg', '/en/books/uncanny-valley-en/purchase', 'دره-عجیب-و-غریب', '2023-01-27 01:46:48.838921', '2023-01-27 01:46:48.838921', NULL, 'Uncanny Valley');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1137, 'کیمیاگری', 'هنر تاریک و علم عجیب ایجاد جادو در برندها، تجارت و زندگی', 'هنر تاریک و علم عجیب ایجاد جادو در برندها، تجارت و زندگی', 20, 7, 'book', 't', '<p><em>کیمیاگری (2018)</em> یک مورد برای تفکر غیرمنطقی در جهانی شیفته منطق است. روری ساترلند با تکیه بر دانش دست اول خود از صنعت تبلیغات و بینش‌های روان‌شناسی رفتاری، استدلال می‌کند که جهان بسیار پیچیده‌تر از آن است که بتوان با یک دریچه به آن نگاه کرد. برای حل مشکلات روزمره، باید از تحلیل‌های سطحی عبور کنیم و حتی به ظاهر بی‌معنی‌ترین ایده‌ها - که اغلب بسیار قدرتمند هستند - بگشاییم. تنها در این صورت است که می توانیم کیمیاگر واقعی باشیم. </p>', '2019-12-24 00:00:00', 4, 139, 'https://images.blinkist.io/images/books/5dfcac286cee07000788a1eb/1_1/470.jpg', '/en/books/alchemy-en/purchase', 'کیمیاگری', '2023-01-27 01:46:56.713878', '2023-01-27 01:46:56.713878', NULL, 'Alchemy');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1138, '121 تاریخ اول', 'چگونه در قرار آنلاین موفق شویم، عاشق شویم و همیشه شاد زندگی کنیم (واقعا!)', 'چگونه در قرار آنلاین موفق شویم، عاشق شویم و همیشه شاد زندگی کنیم (واقعا!)', 16, 8, 'book', 't', '<p><em>121 First Dates</em> (2016) راهنمای زنان برای قرار آنلاین است. این چشمک‌ها به شما کمک می‌کند یک نمایه برنده ایجاد کنید، برای اولین قرار ملاقات خود آماده شوید و با مشکلاتی که هنگام جستجوی آقای راست پیش می‌آیند، مقابله کنید.</p>', '2017-04-14 00:00:00', 4, 54, 'https://images.blinkist.io/images/books/58ecb487511add00045ae2e2/1_1/470.jpg', '/en/books/121-first-dates-en/purchase', '121-تاریخ-اول', '2023-01-27 01:47:03.725688', '2023-01-27 01:47:03.725688', NULL, '121 First Dates');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1139, 'چارچوب بندی مجدد سازمان ها', 'هنر، انتخاب و رهبری', 'هنر، انتخاب و رهبری', 22, 8, 'book', 't', '<p><em>Reframing Organizations</em> (2017) به چگونگی ساختار سازمان ها به منظور ساده سازی وظایف و تصمیم گیری می پردازد. این نشان می‌دهد که در هنگام رویارویی با چالش‌های پیچیده، هیچ راه بی‌خطری برای رسیدن به پاسخ درست وجود ندارد. با این حال، ساختارهای خاصی وجود دارد که شانس موفقیت شرکت را افزایش می دهد.</p>', '2019-03-29 00:00:00', 4, 32, 'https://images.blinkist.io/images/books/5c9b9efa6cee070008e68780/1_1/470.jpg', '/en/books/reframing-organizations-en/purchase', 'چارچوب-بندی-مجدد-سازمان-ها', '2023-01-27 01:47:10.931337', '2023-01-27 01:47:10.931337', NULL, 'Reframing Organizations');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1140, 'علم دستاوردهای هوشمند', 'چگونه افراد باهوش راه خود را به سوی موفقیت متمرکز می کنند، ایجاد می کنند و رشد می دهند', 'چگونه افراد باهوش راه خود را به سوی موفقیت متمرکز می کنند، ایجاد می کنند و رشد می دهند', 23, 8, 'book', 't', '<p><em>علم موفقیت هوشمند </em>(2018) درباره چگونگی بهره وری و خلاقیت بیشتر است تا به اهدافی که برای خود تعیین کرده اید دست یابید. این کتاب به شما نشان می‌دهد که چگونه به افکار درست فکر کنید و اطراف خود را با افراد مناسب احاطه کنید تا انگیزه خود را حفظ کنید.</p>', '2019-06-24 00:00:00', 4, 370, 'https://images.blinkist.io/images/books/5d0d08de6cee070007d744c8/1_1/470.jpg', '/en/books/the-science-of-intelligent-achievement-en/purchase', 'علم-دستاوردهای-هوشمند', '2023-01-27 01:47:18.39326', '2023-01-27 01:47:18.39326', NULL, 'The Science of Intelligent Achievement');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1141, 'محور', 'تنها حرکتی که اهمیت دارد حرکت بعدی شماست', 'تنها حرکتی که اهمیت دارد حرکت بعدی شماست', 25, 8, 'book', 't', '<p><em>Pivot </em>(2016) رویکرد چهار مرحله ای را برای پیمایش تغییرات شغلی و رشد شخصی تعریف می کند. علاوه بر نشان دادن عناصر اساسی این روش، نویسنده جنی بلیک نشان می‌دهد که چگونه می‌توان آن را توسط مدیران در شیوه‌های کاری روزمره خود گنجاند.</p>', '2018-06-27 00:00:00', 4, 59, 'https://images.blinkist.io/images/books/5b2fe2ebb238e10006f8a86d/1_1/470.jpg', '/en/books/pivot-en/purchase', 'محور', '2023-01-27 01:47:25.665794', '2023-01-27 01:47:25.665794', NULL, 'Pivot');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1142, 'سرمایه داری بدون سرمایه', 'ظهور اقتصاد نامشهود', 'ظهور اقتصاد نامشهود', 26, 9, 'book', 't', '<p><em>سرمایه داری بدون سرمایه </em>(2017) گزارشی از اهمیت رو به رشد اقتصاد ناملموس است. امروزه برای اولین بار، اکثر اقتصادهای توسعه یافته کمتر بر روی دارایی های فیزیکی و فیزیکی مانند ماشین آلات و کارخانه ها سرمایه گذاری می کنند تا در دارایی های نامشهود مانند نرم افزار، قابلیت تحقیق و توسعه. این چیزهای ناملموس بسیار ارزشمند هستند اما به شکل فیزیکی وجود ندارند. چشمک های پیش رو به بررسی ماهیت این روند و همچنین اثرات آن بر تجارت، اقتصاد و سیاست عمومی می پردازد.</p>', '2018-10-11 00:00:00', 5, 62, 'https://images.blinkist.io/images/books/5bbcd6c56cee070007978a6e/1_1/470.jpg', '/en/books/capitalism-without-capital-en/purchase', 'سرمایه-داری-بدون-سرمایه', '2023-01-27 01:47:33.454897', '2023-01-27 01:47:33.454897', NULL, 'Capitalism Without Capital');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1143, 'تاریخچه مختصر اندیشه', 'راهنمای فلسفی برای زیستن', 'راهنمای فلسفی برای زیستن', 24, 7, 'book', 't', '<p><em>A Brief History of Thought</em> (1996) لحظات بزرگ تاریخ فلسفه غرب را به شیوه ای شفاف و قابل دسترس - از رواقی گری یونان کلاسیک تا پست مدرنیسم قرن بیستم را شرح می دهد. نه صرفاً توصیف ایده‌آل‌های انتزاعی، بلکه نشان می‌دهد که چگونه می‌توانیم از خرد بهترین متفکران جهان برای زندگی شادتر و معنادارتر استفاده کنیم.</p>', '2019-08-08 00:00:00', 4, 244, 'https://images.blinkist.io/images/books/5d47ecf66cee07000859eb3f/1_1/470.jpg', '/en/books/a-brief-history-of-thought-en/purchase', 'تاریخچه-مختصر-اندیشه', '2023-01-27 01:47:40.81424', '2023-01-27 01:47:40.81424', NULL, 'A Brief History of Thought');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1144, 'تطبیق پذیری', 'هنر برنده شدن در عصر عدم اطمینان', 'هنر برنده شدن در عصر عدم اطمینان', 21, 8, 'book', 't', '<p><em>انطباق پذیری</em> (2012) مهارتی را بررسی می کند که در محیط تجاری پرشتاب و بسیار بی ثبات امروزی اهمیت بیشتری پیدا می کند: توانایی سازگاری. این چیزی است که تفاوت بین مبتکران موفقی را ایجاد می کند که به پیشرفت ادامه می دهند و در گل و لای که برای زنده ماندن تلاش می کنند - یا به سادگی زیر بار می روند. این پلک‌ها با پرتره‌های روشن‌کننده هر دو، سازگاری را در عمل در همه جا از زمین گلف گرفته تا میدان نبرد و اتاق هیئت تجزیه و تحلیل می‌کنند.</p>', '2019-03-29 00:00:00', 5, 45, 'https://images.blinkist.io/images/books/5c9b94406cee070007cb64ec/1_1/470.jpg', '/en/books/adaptability-en/purchase', 'تطبیق-پذیری', '2023-01-27 01:47:48.729149', '2023-01-27 01:47:48.729149', NULL, 'Adaptability');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1145, 'لبه سیاه', 'اطلاعات داخلی، پول کثیف، و تلاش برای سرنگون کردن تحت تعقیب ترین مرد در وال استریت', 'اطلاعات داخلی، پول کثیف، و تلاش برای سرنگون کردن تحت تعقیب ترین مرد در وال استریت', 20, 8, 'book', 't', '<p><em>Black Edge</em> (2017) داستان واقعی طمع و جنایت مالی در وال استریت در دهه 2000 را روایت می کند. این تجارت در مقیاس بزرگ و غیرقانونی خودی در SAC Capital Advisors، یک صندوق تامینی که توسط سرمایه گذار ستاره، استیو کوهن تأسیس شده است، توضیح می دهد. SAC فرهنگ تجارت بر روی اطلاعات داخلی را حفظ کرده است، اما در حالی که برخی از معامله گران در SAC به دلیل تجارت داخلی محکوم شده بودند، مقامات ایالات متحده هرگز نتوانستند خود استیو کوهن را از درآمد میلیونی خود باز دارند - و او هرگز به هیچ جرمی محکوم نشد.</p>', '2017-10-03 00:00:00', 4, 15, 'https://images.blinkist.io/images/books/59d26759b238e10005435bbc/1_1/470.jpg', '/en/books/black-edge-en/purchase', 'لبه-سیاه', '2023-01-27 01:47:56.813248', '2023-01-27 01:47:56.813248', NULL, 'Black Edge');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1146, 'رهبر درونگرا', 'بر پایه قدرت آرام خود بسازید', 'بر پایه قدرت آرام خود بسازید', 19, 9, 'book', 't', '<p>کان‌ویلر چالش‌های خاصی را که درون‌گراها در دنیای کسب‌وکار برون‌گرا با آن روبرو هستند، بررسی می‌کند. سپس تصمیم می‌گیرد نشان دهد که چگونه مدیران درون‌گرا می‌توانند محدودیت‌های خود را پشت سر بگذارند، از نقاط قوت مشخصه خود استفاده کنند و همچنان رهبران بزرگی شوند.</p>', '2014-06-10 14:22:14', 4, 131, 'https://images.blinkist.io/images/books/5398646e64663700072e0000/1_1/470.jpg', '/en/books/the-introverted-leader-en/purchase', 'رهبر-درونگرا', '2023-01-27 01:48:04.897225', '2023-01-27 01:48:04.897225', NULL, 'The Introverted Leader');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1147, 'ریاضت', 'تاریخچه یک ایده خطرناک', 'تاریخچه یک ایده خطرناک', 16, 6, 'book', 't', '<p><em>ریاضت اقتصادی </em>(2013) سردرگمی پشت بحران‌های مالی اخیر ما را کاهش می‌دهد و نشان می‌دهد که وقتی اقتصاددانان خواستار اجرای سیاست ریاضت اقتصادی هستند واقعاً چه اتفاقی می‌افتد. این زمانی است که بودجه‌ها قطع می‌شود، بودجه عمومی کاهش می‌یابد و خانواده‌های طبقه کارگر آسیب می‌بینند تا بانک‌ها پس‌انداز شوند و به درآمدهای میلیاردی ادامه دهند. دریابید که واقعاً چه اتفاقی می‌افتد و وقتی کشور شما به سمت ریاضت کشیده می‌شود واقعاً از چه کسی محافظت می‌شود.</p>', '2017-07-04 00:00:00', 4, 34, 'https://images.blinkist.io/images/books/595a2344b238e10007cd5077/1_1/470.jpg', '/en/books/austerity-en/purchase', 'ریاضت', '2023-01-27 01:48:12.000754', '2023-01-27 01:48:12.000754', NULL, 'Austerity');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1148, 'اسپارتان بالا!', 'راهنمای بدون زندانی برای غلبه بر موانع و دستیابی به اوج عملکرد در زندگی', 'راهنمای بدون زندانی برای غلبه بر موانع و دستیابی به اوج عملکرد در زندگی', 12, 5, 'book', 't', '<p><em>Spartan Up! </em>(2014) یک راهنمای عمیق برای زندگی کامل از طریق به چالش کشیدن خود و بودن بهترین فردی است که می توانید باشید. شیوه زندگی «اسپارتی» از اسپارتی‌های یونان باستان الهام می‌گیرد. فلسفه های خود را در زمینه مدرن پیاده سازی کنند تا زندگی سالم تر و رضایت بخشی داشته باشند.</p>', '2015-10-26 00:00:00', 4, 91, 'https://images.blinkist.io/images/books/562e109f3864310007010000/1_1/470.jpg', '/en/books/spartan-up-en/purchase', 'اسپارتان-بالا!', '2023-01-27 01:48:19.221094', '2023-01-27 01:48:19.221094', NULL, 'Spartan Up!');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1149, 'بخیه', 'کتابی در مورد معنا، امید و ترمیم', 'کتابی در مورد معنا، امید و ترمیم', 10, 4, 'book', 't', '<p><em>Stitches</em> (2014) درباره پذیرفتن جنبه‌های منفی زندگی است که قادر به تغییر آنها نیستید، و ایجاد جامعه‌ای برای کمک به شما برای حل آنها. این پلک‌ها توضیح می‌دهند که چرا بسیاری از مردم از رنج و درد فرار می‌کنند، و چرا تصدیق چنین تجربیات دشواری تنها راه غلبه بر آن‌ها است.</p>', '2017-02-03 00:00:00', 4, 21, 'https://images.blinkist.io/images/books/5891e44c78a78e0004051aab/1_1/470.jpg', '/en/books/stitches-en/purchase', 'بخیه', '2023-01-27 01:48:24.481073', '2023-01-27 01:48:24.481073', NULL, 'Stitches');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1150, 'کش آمدن', 'قفل قدرت کمتر را باز کنید و بیشتر از آنچه تصور می کردید به دست آورید', 'قفل قدرت کمتر را باز کنید و بیشتر از آنچه تصور می کردید به دست آورید', 17, 7, 'book', 't', '<p><em>کشش </em>(2017) راهنمای شما برای کشف پتانسیل خلاق واقعی شماست. این پلک‌ها به شما یاد می‌دهند که چگونه منابع داخلی و خارجی را که برای باز کردن احتمالات جدید، رسیدن به ستاره‌ها و برتری در زندگی به آن‌ها نیاز دارید، شناسایی کنید. </p>', '2017-10-23 00:00:00', 4, 32, 'https://images.blinkist.io/images/books/59ed22fbb238e10006455471/1_1/470.jpg', '/en/books/stretch-en-scott-sonenshein/purchase', 'کش-آمدن', '2023-01-27 01:48:32.279039', '2023-01-27 01:48:32.279039', NULL, 'Stretch');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1151, 'نوبت شماست', 'چگونه یک بزرگسال باشیم', 'چگونه یک بزرگسال باشیم', 31, 8, 'book', 't', '<p><em>نوبت شماست </em>(2021) راهنمای قرن بیست و یکم برای بزرگسالی - و خودشناسی است. داستان‌ها و بینش‌هایی که همه چیز را از روابط گرفته تا سلامت روان و پول پوشش می‌دهند، تصویری از معنای بزرگ شدن را نشان می‌دهند. به جای ترسیم یک تعریف یا هدف سفت و سخت، ابزارهایی را ارائه می‌کند که به شما کمک می‌کند تا درمورد چشم‌انداز بزرگسالی و داشتن یک زندگی غنی و معنادار احساس قدرت و هیجان کنید.</p>', '2022-02-21 00:00:00', 5, 235, 'https://images.blinkist.io/images/books/6213481b6cee0700081e6da7/1_1/470.jpg', '/en/books/your-turn-en/purchase', 'نوبت-شماست', '2023-01-27 01:48:37.645769', '2023-01-27 01:48:37.645769', NULL, 'Your Turn');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1152, 'تبدیل شدن به استیو جابز', 'تکامل یک شروع بی پروا به یک رهبر بصیر', 'تکامل یک شروع بی پروا به یک رهبر بصیر', 25, 10, 'book', 't', '<p><em>Becoming Steve Jobs</em> (2015) داستان زندگی و کار این نابغه فناوری را روایت می کند. این پلک‌ها نگاهی درونی به تاریخ اپل می‌دهد، پیشرفت شخصی جابز را شرح می‌دهد، موفقیت‌های اولیه و همچنین شکست‌هایش را بررسی می‌کند، و نشان می‌دهد که چگونه انگیزه و نوآوری او باعث تولید محصولات انقلابی مانند آیفون شد.</p >', '2017-11-10 00:00:00', 4, 96, 'https://images.blinkist.io/images/books/5a00e6d6b238e100067eaf65/1_1/470.jpg', '/en/books/becoming-steve-jobs-en/purchase', 'تبدیل-شدن-به-استیو-جابز', '2023-01-27 01:48:44.916942', '2023-01-27 01:48:44.916942', NULL, 'Becoming Steve Jobs');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1153, 'پول هزاره', 'چگونه سرمایه گذاران جوان می توانند ثروت بسازند', 'چگونه سرمایه گذاران جوان می توانند ثروت بسازند', 15, 7, 'book', 't', '<p>اگرچه پیشرفت‌های تکنولوژیکی سرمایه‌گذاری در بازار سهام را آسان‌تر از همیشه کرده است، میلنیال‌های امروزی (جوانان متولد سال‌های 1980 تا 2000) تمایل به ریسک‌گریزی دارند. اما این نوع تفکر اشتباه است. با توجه به اینکه مزایایی مانند تامین اجتماعی و مستمری های بازنشستگی به خطر افتاده است، هرگز برای جوانان مهم نبوده است که در امنیت مالی آینده خود سرمایه گذاری کنند.</p>', '2015-01-08 00:00:00', 4, 131, 'https://images.blinkist.io/images/books/54a9903762333200097e0000/1_1/470.jpg', '/en/books/millennial-money-en/purchase', 'پول-هزاره', '2023-01-27 01:48:52.170007', '2023-01-27 01:48:52.170007', NULL, 'Millennial Money');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1154, 'افسانه انگیزه', 'چگونه افراد موفق واقعاً خود را برای برنده شدن آماده می کنند', 'چگونه افراد موفق واقعاً خود را برای برنده شدن آماده می کنند', 20, 7, 'book', 't', '<p><em>افسانه انگیزه </em>(2018) این ایده را که شما برای موفقیت به انگیزه نیاز دارید، رد می کند. با استفاده از تجربیات خود نویسنده و مثال‌هایی از افراد موفق در طیف وسیعی از زمینه‌ها، به شما نشان می‌دهد که چگونه فرآیندی را برای رسیدن به اهداف خود پرورش دهید و از تحقق در طول مسیر لذت ببرید.</p>', '2021-04-28 00:00:00', 5, 233, 'https://images.blinkist.io/images/books/6082d1516cee0700072c7da1/1_1/470.jpg', '/en/books/the-motivation-myth-en/purchase', 'افسانه-انگیزه', '2023-01-27 01:48:59.334541', '2023-01-27 01:48:59.334541', NULL, 'The Motivation Myth');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1155, 'افکار خود را تغییر دهید - زندگی خود را تغییر دهید', 'زندگی با حکمت تائو', 'زندگی با حکمت تائو', 17, 6, 'book', 't', '<p><em>افکار خود را تغییر دهید - زندگی خود را تغییر دهید</em> (2007) شما را در هر آیاتی از <em>تائو ته چینگ</em>، متن کلاسیک مربوط به سنت‌های فلسفی و معنوی تائوئیسم، راهنمایی می‌کند. . نویسنده با اقتباس از تفاسیر مختلف مدرن، آموزه‌های اساسی را بیرون می‌کشد و راه‌هایی را پیشنهاد می‌کند که تائوئیسم امروزه مرتبط و سودمند است.</p>', '2019-09-03 00:00:00', 5, 267, 'https://images.blinkist.io/images/books/5d6c2b486cee0700081a65cf/1_1/470.jpg', '/en/books/change-your-thoughts-change-your-life-en/purchase', 'افکار-خود-را-تغییر-دهید---زندگی-خود-را-تغییر-دهید', '2023-01-27 01:49:06.93937', '2023-01-27 01:49:06.93937', NULL, 'Change Your Thoughts – Change Your Life');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1156, 'کمی تاریخ اقتصاد', 'سفری بی‌سابقه به پرسش‌های اصلی مطرح شده توسط اقتصاددانان در طول قرن‌ها، از ارسطو تا توماس پیکتی', 'سفری بی‌سابقه به پرسش‌های اصلی مطرح شده توسط اقتصاددانان در طول قرن‌ها، از ارسطو تا توماس پیکتی', 26, 9, 'book', 't', '<p><em>تاریخ کمی از اقتصاد </em>(2017) یک تور سوتی است که در مورد سؤالات اصلی اقتصاددانان در طول قرن ها، از ارسطو تا توماس پیکتی، مطرح شده است. این کتاب به بررسی مسائل مربوط به نابرابری، خودخواهی و نقشی که دولت در اقتصادها باید ایفا کند، می پردازد. </p>', '2021-03-04 00:00:00', 5, 238, 'https://images.blinkist.io/images/books/6038cad36cee07000751a796/1_1/470.jpg', '/en/books/a-little-history-of-economics-en/purchase', 'کمی-تاریخ-اقتصاد', '2023-01-27 01:49:14.751623', '2023-01-27 01:49:14.751623', NULL, 'A Little History of Economics');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1157, 'پنج عنصر تفکر موثر', 'پنج راه برای تصمیم گیری بهتر', 'پنج راه برای تصمیم گیری بهتر', 22, 9, 'book', 't', '<p>با <em></em> <em>پنج</em> <em>عنصر</em> <em></em> <em>موثر</em> <em>تفکر،< /em> یاد خواهید گرفت که چگونه به طور مؤثر فکر کنید و پتانسیل کامل خود را به کار ببرید. با استفاده از چهار عنصر - خاک، آتش، هوا و آب - به عنوان یک اصل سازماندهی، نویسندگان تکنیک‌های زیادی را برای بهبود شیوه تفکر ما توضیح می‌دهند. با افزودن عنصر پنجم، تغییر، نشان می‌دهند که چگونه اتخاذ نگرش صحیح به ایجاد تغییرات پایدار و مثبت کمک می‌کند.</p>', '2014-09-02 00:00:00', 4, 86, 'https://images.blinkist.io/images/books/540477793663330008160000/1_1/470.jpg', '/en/books/the-five-elements-of-effective-thinking-en/purchase', 'پنج-عنصر-تفکر-موثر', '2023-01-27 01:49:22.471824', '2023-01-27 01:49:22.471824', NULL, 'The Five Elements of Effective Thinking');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1158, 'اجرای زندگی او', 'مردم در مقابل O. J. Simpson', 'مردم در مقابل O. J. Simpson', 15, 6, 'book', 't', '<p><em>The Run of His Life</em> (1997) به بررسی موارد ضروری پرونده قتل O. J. Simpson می پردازد: شخصیت های درگیر و نیروهای اجتماعی که منجر به تبرئه تکان دهنده این فوق ستاره فوتبال شد. این پلک‌ها فقط داستان یک مرد را شرح نمی‌دهند، بلکه نشان می‌دهند که چگونه جامعه آمریکایی داستان پیروزی سیمپسون را به یک تراژدی تبدیل کرد.</p>', '2016-09-14 00:00:00', NULL, 4, 'https://images.blinkist.io/images/books/57d79ec1fe3591000389f788/1_1/470.jpg', '/en/books/the-run-of-his-life-en/purchase', 'اجرای-زندگی-او', '2023-01-27 01:49:29.876164', '2023-01-27 01:49:29.876164', NULL, 'The Run of His Life');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1159, 'سرمایه گذار هوشمند', 'کتاب قطعی سرمایه گذاری ارزشی', 'کتاب قطعی سرمایه گذاری ارزشی', 21, 9, 'book', 't', '<p><em>سرمایه‌گذار هوشمند</em>توصیه‌های درستی در مورد سرمایه‌گذاری از یک منبع قابل اعتماد ارائه می‌کند - بنجامین گراهام، سرمایه‌گذاری که پس از سقوط مالی سال 1929 شکوفا شد. نویسنده با آموختن از اشتباهات خود، دقیقاً چه چیزی را بیان می‌کند. برای تبدیل شدن به یک سرمایه گذار موفق در هر محیطی لازم است.</p>', '2014-12-19 00:00:00', 4, 885, 'https://images.blinkist.io/images/books/54912c283633390009270000/1_1/470.jpg', '/en/books/the-intelligent-investor-en/purchase', 'سرمایه-گذار-هوشمند', '2023-01-27 01:49:37.820988', '2023-01-27 01:49:37.820988', NULL, 'The Intelligent Investor');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1160, 'کار انعطاف پذیر', 'نحوه پیاده سازی انعطاف پذیری در محیط کار برای بهبود عملکرد کارکنان و کسب و کار', 'نحوه پیاده سازی انعطاف پذیری در محیط کار برای بهبود عملکرد کارکنان و کسب و کار', 24, 8, 'book', 't', '<p><em>کار منعطف </em>(2021) یک راهنمای عملی برای سازماندهی کار خارج از استاندارد نه به پنج است. این کتاب راهنمای مفید، مجموعه متنوعی از ترتیبات کاری ممکن در دنیای معاصر را بررسی می‌کند.</p>', '2021-03-12 00:00:00', 4, 79, 'https://images.blinkist.io/images/books/6041e9ab6cee070007be7c58/1_1/470.jpg', '/en/books/flexible-working-en/purchase', 'کار-انعطاف-پذیر', '2023-01-27 01:49:46.124683', '2023-01-27 01:49:46.124683', NULL, 'Flexible Working');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1217, 'شروع کار در مشاوره', 'در کسب و کار مشاوره سودآور شروع کنید', 'در کسب و کار مشاوره سودآور شروع کنید', 18, 8, 'book', 't', '<p><em>شروع در مشاوره </em>(2009) کتاب راهنما برای مشاوران نوپا است. از پیدا کردن جایگاه خود و یادگیری در مورد مسائل حقوقی گرفته تا تسلط بر هنر دوگانه بازاریابی و برندسازی، این چشمک‌ها تمام مراحل سفر شما به ساختن یک شرکت مشاوره قوی - و همچنین حفظ آن را نشان می‌دهند.</p>', '2015-07-23 00:00:00', 4, 27, 'https://images.blinkist.io/images/books/55acfe2e6536380007f70000/1_1/470.jpg', '/en/books/getting-started-in-consulting-en/purchase', 'شروع-کار-در-مشاوره', '2023-01-27 01:56:39.381881', '2023-01-27 01:56:39.381881', NULL, 'Getting Started in Consulting');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1161, 'بازگشت به انسان', 'چگونه رهبران بزرگ در عصر انزوا ارتباط ایجاد می کنند', 'چگونه رهبران بزرگ در عصر انزوا ارتباط ایجاد می کنند', 21, 7, 'book', 't', '<p><em>بازگشت به انسان </em>(2018) بررسی می‌کند که چگونه مکان‌های کاری که رویکرد انسانی‌تری ارائه می‌دهند، نه تنها محیط بهتری را برای کارکنان، بلکه نتایج کسب‌وکار بهتری ارائه می‌دهند. در عصری که استفاده از فناوری بر آن حاکم است، <em>بازگشت به انسان</em> یک راهنمای عملی است که به رهبران محل کار نشان می‌دهد چگونه می‌توانند فرهنگ سازمانی بهتری بر اساس ارتباطات انسانی ایجاد کنند.</p>', '2018-12-20 00:00:00', 5, 34, 'https://images.blinkist.io/images/books/5c1a10cf6cee07000841f897/1_1/470.jpg', '/en/books/back-to-human-en/purchase', 'بازگشت-به-انسان', '2023-01-27 01:49:53.906549', '2023-01-27 01:49:53.906549', NULL, 'Back to Human');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1162, 'چتر نجات شما چه رنگی است؟ 2021', 'راهنمای شما برای یک عمر کار معنادار و موفقیت شغلی', 'راهنمای شما برای یک عمر کار معنادار و موفقیت شغلی', 26, 7, 'book', 't', '<p><em>چتر نجات شما چه رنگی است؟ 2021 </em>(2021) نسخه جدیدی از کتابی است که به طور گسترده به عنوان کتاب مقدس شکارچیان شغل شناخته می شود. مملو از تمرین‌های کلاسیک و استراتژی‌های آزمایش‌شده زمان است که به کارکنان آینده‌نگر قدرت می‌دهد تا نقشی را که می‌خواهند بیابند و ایمن کنند. این نسخه جدید حاوی به‌روزرسانی‌های ضروری است که با بازار کار معاصر صحبت می‌کند.</p>', '2021-04-05 00:00:00', 5, 72, 'https://images.blinkist.io/images/books/606459676cee07000701802f/1_1/470.jpg', '/en/books/what-color-is-your-parachute-2021-en/purchase', 'چتر-نجات-شما-چه-رنگی-است؟-2021', '2023-01-27 01:50:01.457274', '2023-01-27 01:50:01.457274', NULL, 'What Color Is Your Parachute? 2021');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1163, 'بازطراحی رهبری', 'سادگی: طراحی، فناوری، تجارت، زندگی', 'سادگی: طراحی، فناوری، تجارت، زندگی', 11, 5, 'book', 't', '<p><em>بازطراحی رهبری</em> (2011) اصطلاحات اصطلاحی را از مدیریت خارج می کند و آن را با لمس انسانی جایگزین می کند. رهبر عالی بودن به معنای حضور در فروشگاه (یا دفتر)، برقراری ارتباط با کارمندان و مهمتر از همه تمرکز و احترام آنهاست. نویسنده راه‌های ساده‌ای را ارائه می‌کند تا مدیری باشید که اصول و قلب خود را حفظ کند.</p>', '2015-08-07 00:00:00', 4, 46, 'https://images.blinkist.io/images/books/55c1280a3439630007390100/1_1/470.jpg', '/en/books/redesigning-leadership-en/purchase', 'بازطراحی-رهبری', '2023-01-27 01:50:07.281057', '2023-01-27 01:50:07.281057', NULL, 'Redesigning Leadership');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1164, 'مهتاب!', 'استراتژی های تغییر بازی برای ایجاد مشاغل میلیارد دلاری', 'استراتژی های تغییر بازی برای ایجاد مشاغل میلیارد دلاری', 12, 6, 'book', 'f', '<p><em>Moonshot!</em> توضیح می‌دهد که چگونه فناوری‌های جدید چشم‌انداز کسب‌وکار را برای همیشه تغییر داده‌اند، جایی که مشتری امروزی باهوش‌تر است و کنترل بیشتری دارد. این کتاب توصیه هایی را در مورد چگونگی رقابتی تر شدن از طریق ایجاد یک تجربه استثنایی مشتری به هدف اصلی شما ارائه می دهد.</p>', '2015-01-20 00:00:00', NULL, 9, 'https://images.blinkist.io/images/books/54bd207b633234000a410000/1_1/470.jpg', '/en/books/moonshot-en/purchase', 'مهتاب!', '2023-01-27 01:50:15.645353', '2023-01-27 01:50:15.645353', NULL, 'Moonshot!');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1165, 'نقشه راه آیین ها', 'راه انسانی برای تبدیل روتین های روزمره به جادوی محل کار', 'راه انسانی برای تبدیل روتین های روزمره به جادوی محل کار', 21, 7, 'book', 't', '<p><em>نقشه راه تشریفات </em>(2021) یک راهنمای مدرن در مورد چگونگی ایجاد تشریفات در محل کار است که مشارکت کارکنان را افزایش داده و تعهد تیم را تقویت می کند. این یک خرد اساسی برای محیط کار انسان است.</p>', '2021-04-15 00:00:00', 4, 35, 'https://images.blinkist.io/images/books/607020056cee070007aad5d7/1_1/470.jpg', '/en/books/rituals-roadmap-en/purchase', 'نقشه-راه-آیین-ها', '2023-01-27 01:50:21.250374', '2023-01-27 01:50:21.250374', NULL, 'Rituals Roadmap');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1166, 'هنر برقراری ارتباط', 'جذابیت ذهن آگاهی در زندگی روزمره ما', 'جذابیت ذهن آگاهی در زندگی روزمره ما', 15, 7, 'book', 't', '<p><em>هنر برقراری ارتباط</em> (2013) بینش ارزشمندی در مورد اینکه چگونه می‌توانید با تمرین <em>ذهن‌آگاهی</em> به یک ارتباط‌گر مؤثرتر تبدیل شوید، ارائه می‌دهد. با تکیه بر خرد بودایی، راه‌هایی را بیان می‌کند که می‌توانید شنونده محترمی شوید، خود را به خوبی ابراز کنید و در نهایت روابط خود را با عزیزانتان بهبود بخشید.</p>', '2015-01-12 00:00:00', 5, 271, 'https://images.blinkist.io/images/books/548fe6e365323500095e0100/1_1/470.jpg', '/en/books/the-art-of-communicating-en/purchase', 'هنر-برقراری-ارتباط', '2023-01-27 01:50:26.678153', '2023-01-27 01:50:26.678153', NULL, 'The Art of Communicating');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1167, 'خلاف واقع', 'چرا تقریباً هر آنچه در مورد زنان، شهوت و خیانت باور داریم اشتباه است و چگونه علم جدید می تواند ما را آزاد کند؟', 'چرا تقریباً هر آنچه در مورد زنان، شهوت و خیانت باور داریم اشتباه است و چگونه علم جدید می تواند ما را آزاد کند؟', 17, 6, 'book', 't', '<p><em>نادرست</em> (2018) با هدف به چالش کشیدن این فرض دیرینه مبنی بر اینکه زنان نسبت به مردان کمتر به رابطه جنسی علاقه دارند، می پردازد. غواصی در تاریخ و جزئیات بدن انسان، <em>نادرست</em> نشان می دهد که زنان نه تنها تمایلات جنسی قوی دارند، بلکه به دنبال رضایت از شرکای مختلف هستند.</p>', '2020-06-20 00:00:00', 4, 121, 'https://images.blinkist.io/images/books/5ee906066cee070007e60dd4/1_1/470.jpg', '/en/books/untrue-en/purchase', 'خلاف-واقع', '2023-01-27 01:50:33.826749', '2023-01-27 01:50:33.826749', NULL, 'Untrue');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1486, 'اگه می تونی منو بگیر', 'داستان واقعی یک جعلی واقعی', 'داستان واقعی یک جعلی واقعی', 14, 5, 'book', 't', '<p>داستان فرانک آبگنال از کلاهبرداری میلیون‌ها دلار از قربانیان ناخواسته در حالی که خود را به عنوان خلبان، وکیل و پروفسور نشان می‌دهد، داستان افسانه‌ای است. او در <em>اگر می توانی مرا بگیر</em> (1980)، داستان خود را تعریف می کند.</p>', '2016-10-05 00:00:00', 5, 51, 'https://images.blinkist.io/images/books/57f51c7122172d0003082d31/1_1/470.jpg', '/en/books/catch-me-if-you-can-en/purchase', 'اگه-می-تونی-منو-بگیر', '2023-01-27 02:29:10.780833', '2023-01-27 02:29:10.780833', NULL, 'Catch Me If You Can');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1168, 'کمپین هایی که دنیا را تکان دادند', 'سیر تحول روابط عمومی', 'سیر تحول روابط عمومی', 18, 8, 'book', 't', '<p><em>کمپین هایی که جهان را تکان دادند </em>(2015) تاریخ روابط عمومی را از طریق مجموعه ای از کمپین های پیشگامانه بیان می کند، کاری که الهام بخش یک تغییر انقلابی در ارتباطات بود. این پلک‌ها به شما نشان می‌دهند که چگونه کمپینی ایجاد کنید که تأثیر جدی داشته باشد و شرکت شما را به موفقیت برساند.</p>', '2016-05-17 00:00:00', 4, 23, 'https://images.blinkist.io/images/books/5734586de2369000032901e8/1_1/470.jpg', '/en/books/campaigns-that-shook-the-world-en/purchase', 'کمپین-هایی-که-دنیا-را-تکان-دادند', '2023-01-27 01:50:41.268788', '2023-01-27 01:50:41.268788', NULL, 'Campaigns that Shook the World');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1169, 'سبک', 'تاریخ تابشی از خلقت تا عصر کوانتومی', 'تاریخ تابشی از خلقت تا عصر کوانتومی', 11, 5, 'book', 't', '<p><em>نور</em> (2016) درباره روشنایی در تمام اشکال آن است. این پلک‌ها به نخستین روزهای بشریت بازمی‌گردد تا نشان دهد چگونه، برای هزاران سال، نور به عنوان الهام‌بخش الهی، هنری و علمی عمل کرده است.</p>', '2016-07-11 00:00:00', 4, 20, 'https://images.blinkist.io/images/books/577f7651b7b7eb000373a169/1_1/470.jpg', '/en/books/light-en/purchase', 'سبک', '2023-01-27 01:50:49.180293', '2023-01-27 01:50:49.180293', NULL, 'Light');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1170, 'مناطق آبی', '9 درس برای طولانی‌تر زندگی کردن از افرادی که طولانی‌ترین عمر را داشته‌اند', '9 درس برای طولانی‌تر زندگی کردن از افرادی که طولانی‌ترین عمر را داشته‌اند', 13, 5, 'book', 't', '<p><em>مناطق آبی </em>(2012، برای اولین بار در سال 2008 منتشر شد) شما را در مناطقی از جهان با بالاترین غلظت صدساله سالم به گردش در می آورد. با بررسی نحوه زندگی و تعامل مردم در این مناطق، بینشی در مورد چگونگی افزایش طول عمر خود به دست می آوریم.</p>
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1171, 'دوبل دوبل', 'چگونه درآمد و سود خود را در 3 سال یا کمتر دو برابر کنید', 'چگونه درآمد و سود خود را در 3 سال یا کمتر دو برابر کنید', 15, 8, 'book', 'f', '<p><em>Double Double </em>(2011) کلیدهایی برای باز کردن رشد قدرتمند در کسب و کارتان در اختیار شما قرار می دهد. این پلک‌ها شما را راهنمایی می‌کنند، از تعریف مؤثر چشم‌انداز شرکتتان گرفته تا افزایش عملکرد کارکنان تا اطمینان از انعطاف‌پذیری شما به عنوان یک رهبر.</p>
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1172, 'سال تفکر جادویی', 'درس از دست دادن', 'درس از دست دادن', 35, 12, 'book', 't', '<p><em>سال تفکر جادویی </em>(2005) خاطرات تلخی درباره از دست دادن و اندوه است. این داستان عمیقا شخصی تجربیات جوآن دیدیون با بیماری های تهدید کننده زندگی دخترش و مرگ همسرش را روایت می کند. اما بیشتر از آن، این یک کاوش فلسفی تفکربرانگیز در مورد معنای فناپذیری، شکنندگی زندگی و تغییرپذیری هر چیزی است که ما را احاطه کرده است.</p>', '2019-07-11 00:00:00', 4, 66, 'https://images.blinkist.io/images/books/5d25a4ac6cee0700075fceea/1_1/470.jpg', '/en/books/the-year-of-magical-thinking-en/purchase', 'سال-تفکر-جادویی', '2023-01-27 01:51:08.517415', '2023-01-27 01:51:08.517415', NULL, 'The Year of Magical Thinking');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1173, 'تو سعادت خواهی کرد', 'ده فرمان برای کسب درآمد', 'ده فرمان برای کسب درآمد', 23, 9, 'book', 't', '<p><em>تو سعادت خواهی کرد </em>(2009) نگاهی آشکار به آنچه اصول یهود می تواند در مورد ساختن ثروت و موفقیت به ما بیاموزد ارائه می دهد. با پایبندی به این اصول، می توان در اقتصاد پرنوسان امروزی زنده ماند و پیشرفت کرد.</p>', '2017-02-23 00:00:00', 4, 37, 'https://images.blinkist.io/images/books/58a994438e98580004e555ed/1_1/470.jpg', '/en/books/thou-shall-prosper-en/purchase', 'تو-سعادت-خواهی-کرد', '2023-01-27 01:51:15.425667', '2023-01-27 01:51:15.425667', NULL, 'Thou Shall Prosper');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1174, 'در تعقیب سیر', 'نگاهی صمیمانه به لامپ بدبوی الهی', 'نگاهی صمیمانه به لامپ بدبوی الهی', 18, 6, 'book', 't', '<p><em>در تعقیب سیر </em>(2012) پوست نازک و کاغذی را لایه برداری می کند تا حقایق درونی آلیوم معجزه آسایی را آشکار کند که طعم بدیع و خواص ترمیم کنندگی آن را تبدیل به یکی از لوازم اصلی آشپزخانه برای هزاران سال کرده است. غواصی عمیق در تاریخچه، کشت و کاربردهای آشپزی و پزشکی این گیاه، این اکتشاف غنی از "لامپ با بوی الهی" مملو از لقمه های خوشمزه برای آشپزها، باغبانان و علاقه مندان به تاریخ است.</p>', '2018-11-05 00:00:00', 4, 16, 'https://images.blinkist.io/images/books/5bdf6b616cee070007da46d2/1_1/470.jpg', '/en/books/in-pursuit-of-garlic-en/purchase', 'در-تعقیب-سیر', '2023-01-27 01:51:22.886693', '2023-01-27 01:51:22.886693', NULL, 'In Pursuit of Garlic');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1225, 'مجری موثر', 'راهنمای قطعی برای انجام کارهای درست', 'راهنمای قطعی برای انجام کارهای درست', 15, 7, 'book', 't', '<p>در <em>The Effective Executive، </em>نویسنده پیتر دراکر راهنمای گام به گام برای تبدیل شدن به یک مدیر مولدتر و موثرتر را ارائه می دهد. با تسلط بر چند روش و اصول، می توانید ظرفیت های خود را به عنوان یک رهبر توسعه دهید و همچنین از نقاط قوت کارمندان خود با هدف بهبود نتایج در سراسر سازمان خود حمایت کنید.</p>', '2014-11-03 00:00:00', 4, 158, 'https://images.blinkist.io/images/books/5457503133656600081f0000/1_1/470.jpg', '/en/books/the-effective-executive-en/purchase', 'مجری-موثر', '2023-01-27 01:57:31.398661', '2023-01-27 01:57:31.398661', NULL, 'The Effective Executive');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1175, 'قطب نما رژیم غذایی', 'راهنمای 12 مرحله‌ای برای تغذیه مبتنی بر علم برای زندگی سالم‌تر و طولانی‌تر', 'راهنمای 12 مرحله‌ای برای تغذیه مبتنی بر علم برای زندگی سالم‌تر و طولانی‌تر', 23, 7, 'book', 't', '<p><em>قطب‌نمای رژیم غذایی </em> (2018) آخرین تحقیقات در مورد سلامت، پیری و تغذیه را در یک برنامه با پشتوانه علمی خلاصه می‌کند که هر کسی می‌تواند آن را در رژیم غذایی خود اعمال کند. هنگامی که نویسنده، باس کاست، در سن 40 سالگی هنگام دویدن به زمین افتاد، تصمیم گرفت رژیم غذایی خود را به شدت تغییر دهد و سبک زندگی سالم تری داشته باشد. این کتاب نتیجه سال‌ها پیگیری این سوال است: واقعاً چه چیزی <em></em>سالم است؟</p>', '2021-04-06 00:00:00', 5, 130, 'https://images.blinkist.io/images/books/6064582e6cee070007018023/1_1/470.jpg', '/en/books/the-diet-compass-en/purchase', 'قطب-نما-رژیم-غذایی', '2023-01-27 01:51:31.020351', '2023-01-27 01:51:31.020351', NULL, 'The Diet Compass');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1176, 'هدایای نقص', 'آنچه را که فکر می کنید باید باشید رها کنید و آنچه هستید را در آغوش بگیرید', 'آنچه را که فکر می کنید باید باشید رها کنید و آنچه هستید را در آغوش بگیرید', 22, 10, 'book', 't', '<p><em>هدایای نقص</em>راه‌حلی در دسترس و جذاب را در ده اصل ارائه می‌دهد که می‌توانید برای داشتن یک زندگی رضایت‌بخش‌تر، که با شجاعت، ارتباط و شفقت نسبت به دیگران تعریف می‌شود، دنبال کنید. این کتاب که مملو از حکایات مرتبط و توصیه های عملی است، منبع مفیدی برای خوانندگان جوان و پیر است.</p>', '2015-02-05 00:00:00', 5, 523, 'https://images.blinkist.io/images/books/54cf907e323335000a5e0000/1_1/470.jpg', '/en/books/the-gifts-of-imperfection-en/purchase', 'هدایای-نقص', '2023-01-27 01:51:35.837425', '2023-01-27 01:51:35.837425', NULL, 'The Gifts of Imperfection');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1177, 'یادگیری رهبری', 'پنج اصل برای تبدیل شدن به یک رهبر نمونه', 'پنج اصل برای تبدیل شدن به یک رهبر نمونه', 12, 5, 'book', 't', '<p><em>Learning Leadership</em> (2016) ثابت می کند که رهبران لازم نیست با استعداد رهبری عالی متولد شوند. مانند هر مهارت دیگری، رهبری چیزی است که می توان آن را آموخت و بهبود بخشید. و تنها با کمک پنج استراتژی اساسی، شما نیز می توانید بیاموزید که برای یک رهبر موثر چه چیزی لازم است. اینها نکات عالی برای کسانی است که به تازگی وارد یک موقعیت رهبری می شوند یا برای افراد حرفه ای که به دنبال چشم اندازی تازه هستند.</p>', '2017-07-20 00:00:00', 4, 112, 'https://images.blinkist.io/images/books/596c9f05b238e10005430c4d/1_1/470.jpg', '/en/books/learning-leadership-en/purchase', 'یادگیری-رهبری', '2023-01-27 01:51:42.627958', '2023-01-27 01:51:42.627958', NULL, 'Learning Leadership');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1178, 'بیوگرافی قبل از خواب: زندگی نامه النور روزولت', 'بانوی اول، دولتمرد، پیشگام', 'بانوی اول، دولتمرد، پیشگام', 23, 6, 'book', 't', '<p><em><strong>روایت ژانت رابینسون، با موسیقی فدریکو کدرونی</strong><br><br>زندگی‌نامه النور روزولت (1961) داستان زندگی یکی از بیستم را روایت می‌کند. بزرگترین شخصیت های قرن آمریکا بانوی اول، دولتمرد، مبارز خستگی ناپذیر علیه بی عدالتی و نابرابری - النور روزولت چیزهای زیادی بود. در زندگی‌نامه‌اش، او ما را در طول زندگی‌اش می‌برد، از دوران کودکی ناخوشایند تا ازدواجش با FDR و کار کلیدی‌اش با سازمان ملل.</p>', '2021-07-04 00:00:00', 5, 138, 'https://images.blinkist.io/images/books/60defff76cee070007790e94/1_1/470.jpg', '/en/books/bedtime-biography-the-autobiography-of-eleanor-roosevelt-en/purchase', 'بیوگرافی-قبل-از-خواب:-زندگی-نامه-النور-روزولت', '2023-01-27 01:51:50.506862', '2023-01-27 01:51:50.506862', NULL, 'Bedtime Biography: The Autobiography of Eleanor Roosevelt');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1179, 'کلمات جادویی', 'علم و اسرار نهفته در 7 کلمه ای که انگیزه می دهد، درگیر می کند و تأثیر می گذارد', 'علم و اسرار نهفته در 7 کلمه ای که انگیزه می دهد، درگیر می کند و تأثیر می گذارد', 11, 5, 'book', 't', '<p><em>کلمات جادویی</em> (2014) هفت کلمه را مورد بحث قرار می دهد که افراد را به انجام عمل ترغیب می کند. شما بدون توجه به اهدافتان به افرادی نیاز دارید که با شما کار کنند، و این پلک زدن ها توصیه هایی را برای ایجاد ارتباطات معنی دار و وادار کردن دوستان و همکارانتان برای همکاری با شما در مورد آنچه می خواهید ارائه می دهد.</p>', '2016-02-18 00:00:00', 4, 82, 'https://images.blinkist.io/images/books/56c065264f33cc000700004c/1_1/470.jpg', '/en/books/magic-words-en/purchase', 'کلمات-جادویی', '2023-01-27 01:51:58.287511', '2023-01-27 01:51:58.287511', NULL, 'Magic Words');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1180, 'افسون', 'هنر تغییر قلب ها، ذهن ها و اعمال', 'هنر تغییر قلب ها، ذهن ها و اعمال', 25, 10, 'book', 't', '<em>افسون گای کاوازاکی</em> به شما می آموزد که چگونه قلب، ذهن و اعمال افراد اطراف خود را تغییر دهید و آنها را به حامیان با روحیه هدف خود تبدیل کنید. همچنین گام‌های کلیدی در مسیر ایجاد شیفتگی پایدار نسبت به محصول و شرکت شما و همچنین توصیه‌های مفیدی در مورد نحوه مقاومت در برابر افسون دیگران ارائه می‌دهد.</p>', '2014-07-15 00:00:00', 4, 20, 'https://images.blinkist.io/images/books/53c6724338393400073b0100/1_1/470.jpg', '/en/books/enchantment-en/purchase', 'افسون', '2023-01-27 01:52:03.273658', '2023-01-27 01:52:03.273658', NULL, 'Enchantment');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1181, 'از طریق شیشه زبان', 'چرا جهان در زبان های دیگر متفاوت به نظر می رسد؟', 'چرا جهان در زبان های دیگر متفاوت به نظر می رسد؟', 20, 9, 'book', 't', '<p><em>Through the Language Glass </em>(2010) راه های بسیاری را که زبان فرهنگ ما را منعکس می کند و بر آن تأثیر می گذارد را بررسی می کند. با کاوش در روش‌های مختلف برخورد زبان‌ها با فضا، جنسیت و رنگ، این کتاب نشان می‌دهد که زبانی که صحبت می‌کنید اساساً درک شما از جهان را تغییر می‌دهد.</p>', '2015-09-30 00:00:00', 4, 42, 'https://images.blinkist.io/images/books/560929988a14e60009000071/1_1/470.jpg', '/en/books/through-the-language-glass-en/purchase', 'از-طریق-شیشه-زبان', '2023-01-27 01:52:11.41702', '2023-01-27 01:52:11.41702', NULL, 'Through the Language Glass');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1182, 'دنیای مخفی آب و هوا', 'نحوه خواندن علائم در هر ابر، نسیم، تپه، خیابان، گیاه، حیوان و قطره شبنم', 'نحوه خواندن علائم در هر ابر، نسیم، تپه، خیابان، گیاه، حیوان و قطره شبنم', 20, 7, 'book', 't', '<p><em>The Secret World of Weather </em>(2021) به شما می آموزد که چگونه به زبان فراموش شده آب و هوای محلی صحبت کنید. ابرها، بادها، گیاهان و سایر ویژگی‌های محیطی ما، همگی سرنخ‌هایی در مورد آب و هوا به ما می‌دهند که در واقع آن را در مقابل آنچه در پیش‌بینی روزانه شنیده‌ایم، تجربه می‌کنیم. فقط با کمی تمرین، به راحتی می توانید پیام های مخفی آنها را تنظیم کنید و شروع به پیش بینی آب و هوای خود کنید.</p>', '2021-08-31 00:00:00', 4, 200, 'https://images.blinkist.io/images/books/612902cb6cee070007d2904a/1_1/470.jpg', '/en/books/the-secret-world-of-weather-en/purchase', 'دنیای-مخفی-آب-و-هوا', '2023-01-27 01:52:19.270132', '2023-01-27 01:52:19.270132', NULL, 'The Secret World of Weather');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1183, 'StrengthsFinder 2.0', 'خودت را بشناس، سپس برو بیرون و دنیا را فتح کن!', 'خودت را بشناس، سپس برو بیرون و دنیا را فتح کن!', 11, 6, 'book', 't', '<p>در <em>StrengthsFinder 2.0</em> (2007) خواهید آموخت که چگونه مهارت های خود را شناسایی کرده و آنها را به نفع خود توسعه دهید. تام راث چارچوبی قدرتمند برای پرورش پتانسیل شما و تطبیق نقاط قوت شما با حرفه خود ارائه می دهد.</p>', '2016-04-21 00:00:00', 4, 105, 'https://images.blinkist.io/images/books/5714b456344e1b0007a4c852/1_1/470.jpg', '/en/books/strengthsfinder-2-dot-0-en/purchase', 'StrengthsFinder-2.0', '2023-01-27 01:52:27.25071', '2023-01-27 01:52:27.25071', NULL, 'StrengthsFinder 2.0');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1184, 'کد پرفروش', 'آناتومی رمان پرفروش', 'آناتومی رمان پرفروش', 19, 8, 'book', 't', '<p><em>کد پرفروش </em> (2016) داستان قابل توجهی را در پشت یک الگوریتم کامپیوتری تازه توسعه یافته با قدرت باز کردن اسرار محبوب ترین کتاب های پرفروش نشان می دهد. با تجزیه و تحلیل بیش از هزار کتاب پرفروش، الگوهایی پدیدار شدند که به ما نشان می‌دهند کدام مضامین، طرح‌ها، سبک‌ها و شخصیت‌ها در کسب جایگاه کتاب در بالای نمودارها نقش دارند.</p>', '2017-05-18 00:00:00', 5, 28, 'https://images.blinkist.io/images/books/5919a51ab238e100066a4f06/1_1/470.jpg', '/en/books/the-bestseller-code-en/purchase', 'کد-پرفروش', '2023-01-27 01:52:35.546378', '2023-01-27 01:52:35.546378', NULL, 'The Bestseller Code');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1185, 'از شیر گرفتن در 15', 'مشاوره به روز و 100 دستور غذای سریع', 'مشاوره به روز و 100 دستور غذای سریع', 26, 10, 'book', 't', '<p><em>Wean in 15</em>(2020) یک راهنمای عملی برای کمک به کودک شما برای تبدیل شدن به یک غذاخور سالم و مشتاق است. بر اساس دستورالعمل‌ها و داده‌های به‌روز از سرویس بهداشت ملی بریتانیا، سازمان بهداشت جهانی، و محققان و متخصصان مختلف رژیم غذایی، برنامه‌ای گام به گام - از جمله دستور العمل‌ها - برای نحوه از شیر گرفتن نوزاد ارائه می‌دهد. در عین حال، تصدیق می‌کند که هیچ روشی برای همه وجود ندارد، و شما را تشویق می‌کند که این طرح را با سبک فرزندپروری فردی و نیازهای خاص کودکتان تطبیق دهید.</p>', '2020-10-17 00:00:00', 5, 12, 'https://images.blinkist.io/images/books/5f802ace6cee07000629e8df/1_1/470.jpg', '/en/books/wean-in-15-en/purchase', 'از-شیر-گرفتن-در-15', '2023-01-27 01:52:42.95284', '2023-01-27 01:52:42.95284', NULL, 'Wean in 15');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1186, 'شجاعت ناقص', 'با ترک آسایش و ترسیدن، زندگی هدفمندی داشته باشید', 'با ترک آسایش و ترسیدن، زندگی هدفمندی داشته باشید', 22, 8, 'book', 't', '<p>در <em>شجاعت ناقص</em> (2018)، جسیکا هونگر داستان‌های الهام‌بخشی از زندگی هدفمند خود به عنوان یک کارآفرین به اشتراک می‌گذارد. او توضیح می دهد که چگونه با ایجاد ارتباط بین صنعتگران در کشورهای در حال توسعه با زنان در سراسر ایالات متحده، یک تجارت بسیار موفق جواهرات و مد را ایجاد کرد. او همچنین به اشتراک می‌گذارد که چگونه با انجام این کار، از منطقه آسایش خود خارج شد، ذخایر جدیدی از شجاعت پیدا کرد و به دنبال یک زندگی هدفمند و رضایت بخش است.</p>', '2018-09-25 00:00:00', 3, 30, 'https://images.blinkist.io/images/books/5ba80321862c4300070469bf/1_1/470.jpg', '/en/books/imperfect-courage-en/purchase', 'شجاعت-ناقص', '2023-01-27 01:52:50.681415', '2023-01-27 01:52:50.681415', NULL, 'Imperfect Courage');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1187, 'داستان بدن انسان', 'تکامل، سلامت و بیماری', 'تکامل، سلامت و بیماری', 32, 11, 'book', 't', '<p><em>داستان بدن انسان </em>(2013) کاوشی جذاب از داستانی است که بیش از یک میلیون سال در حال ساخت است: تکامل بدن انسان. دانیل لیبرمن از لحظه‌ای که اجداد ما برای اولین بار خود را از برادران انسان‌دوستشان متمایز کردند، تاریخ بیولوژیکی انسان‌ها را دقیقاً تا زمان کنونی ما دنبال می‌کند.</p>', '2018-06-28 00:00:00', 5, 108, 'https://images.blinkist.io/images/books/5b2fea9eb238e10006f8a87d/1_1/470.jpg', '/en/books/the-story-of-the-human-body-en/purchase', 'داستان-بدن-انسان', '2023-01-27 01:52:58.017848', '2023-01-27 01:52:58.017848', NULL, 'The Story of the Human Body');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1188, 'مهندسی درون', 'راهنمای یوگی برای شادی', 'راهنمای یوگی برای شادی', 18, 8, 'book', 't', '<p><em>مهندسی درونی</em> (2016) توضیح می دهد که چگونه شادی را فقط می توان در درون خود یافت. این پلک‌ها حکمت معنوی را معرفی می‌کنند که شما را شادتر، کامل‌تر و در صلح با زندگی‌ای که دارید می‌گذراند.</p>', '2017-07-26 00:00:00', 4, 211, 'https://images.blinkist.io/images/books/59751e00b238e100057032bf/1_1/470.jpg', '/en/books/inner-engineering-en/purchase', 'مهندسی-درون', '2023-01-27 01:53:05.792721', '2023-01-27 01:53:05.792721', NULL, 'Inner Engineering');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1232, 'سال بدون شلوار', 'Wordpress.com و آینده کار', 'Wordpress.com و آینده کار', 13, 7, 'book', 'f', '<p><em>سال بدون شلوار</em>نگاهی صمیمی به زندگی در یکی از موفق‌ترین شرکت‌های فناوری ارائه می‌دهد: Automattic، مغزهای پشت سایت‌هایی مانند Wordpress.com و Polldaddy. با فکر کردن خارج از چارچوب، کنار گذاشتن سنت و کاهش چربی فرآیندهای خود، شما نیز می توانید از نمونه Automattic پیروی کنید و نوآوری را شروع کنید.</p>', '2015-02-13 00:00:00', 4, 16, 'https://images.blinkist.io/images/books/54d89f0f383963000aa40000/1_1/470.jpg', '/en/books/the-year-without-pants-en/purchase', 'سال-بدون-شلوار', '2023-01-27 01:58:25.943479', '2023-01-27 01:58:25.943479', NULL, 'The Year Without Pants');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1189, 'عادات موفقیت میلیونرها', 'دروازه ثروت و رفاه', 'دروازه ثروت و رفاه', 20, 6, 'book', 't', '<p><em>عادات موفقیت میلیونر</em> (2016) حکمت دوره‌های موفقیت مشهور دین گرازیوسی را فشرده می‌کند، که آموزش می‌دهد افراد موفق نگرش مثبت‌تری نسبت به زندگی دارند و عادات سازنده‌تری نسبت به افراد عادی به کار می‌گیرند. اما شما نیز می توانید با ترکیب عاداتی که دیگران را قبل از شما به سعادت رسانده اند، به موفقیت برسید! در این پلک‌ها، بینش‌ها و تمرین‌هایی را می‌بینید که می‌توانید همین الان به کار ببرید تا به شما کمک کند تا از پتانسیل کامل خود استفاده کنید و به سطوح بیشتری از ثروت، آزادی، و رضایت از آنچه که تا به حال تصور می‌کردید دست یابید.</p>', '2020-05-18 00:00:00', 5, 594, 'https://images.blinkist.io/images/books/5ebe72336cee070006fdcb99/1_1/470.jpg', '/en/books/millionaire-success-habits-en/purchase', 'عادات-موفقیت-میلیونرها', '2023-01-27 01:53:13.767657', '2023-01-27 01:53:13.767657', NULL, 'Millionaire Success Habits');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1190, 'گره گشایی شده', 'هدایت دختران نوجوان از طریق هفت گذر به بزرگسالی', 'هدایت دختران نوجوان از طریق هفت گذر به بزرگسالی', 19, 8, 'book', 't', '<p><em>Untangled</em> (2016) راهنمایی برای مادران و پدران، برای معلمان و مربیان است - هر کسی که ممکن است در تلاش برای درک بهتر زندگی و مبارزات دختران نوجوان باشد. این توصیه های ارزشمندی را در مورد چگونگی تشخیص آنچه که آنها از سر می گذرانند ارائه می دهد تا بتوانید از برخی از دام های رایج اجتناب کنید و وضعیت را بدتر نکنید.</p>', '2017-06-22 00:00:00', 4, 75, 'https://images.blinkist.io/images/books/5947d660b238e10005eecf01/1_1/470.jpg', '/en/books/untangled-en/purchase', 'گره-گشایی-شده', '2023-01-27 01:53:21.26032', '2023-01-27 01:53:21.26032', NULL, 'Untangled');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1191, 'عاشق مهربانی', 'هنر انقلابی شادی', 'هنر انقلابی شادی', 27, 8, 'book', 't', '<p><em>مهربانی </em>(1995) راهنمای ملایمی برای کشف معانی عمیق عشق و شادی است. با بینش‌های روان‌شناختی و مراقبه‌های عملی، به ما نشان می‌دهد که چگونه مسیر بودایی برای پیگیری یک قلب آزاد می‌تواند به هر یک از ما کمک کند تا از شادی درخشان درونی خود بهره ببریم - به ما اجازه می‌دهد با خود و دیگران مهربان‌تر باشیم. </p>', '2021-05-08 00:00:00', 5, 357, 'https://images.blinkist.io/images/books/608bf88d6cee07000722925c/1_1/470.jpg', '/en/books/lovingkindness-en/purchase', 'عاشق-مهربانی', '2023-01-27 01:53:26.638872', '2023-01-27 01:53:26.638872', NULL, 'Lovingkindness');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1192, 'پیامی به گارسیا', 'و دیگر نوشته های ضروری در مورد موفقیت', 'و دیگر نوشته های ضروری در مورد موفقیت', 9, 4, 'book', 't', '<p><em>پیامی به گارسیا</em> (1899) درس‌هایی را که باید از یک ستوان اسپانیایی-آمریکایی دوران جنگ آموخته شود، نشان می‌دهد که سطحی از فداکاری را به کار خود نشان می‌دهد که همه ما باید برای مطابقت با آن تلاش کنیم. در هسته خود، این کتاب توضیح می دهد که چگونه سخت کار کردن، کلید زندگی خوب، با فضیلت ماندن، یافتن شادی و بهبود جهان در کل است.</p>', '2016-07-21 00:00:00', 4, 31, 'https://images.blinkist.io/images/books/5787797dc6cd380003a5c5ba/1_1/470.jpg', '/en/books/a-message-to-garcia-en/purchase', 'پیامی-به-گارسیا', '2023-01-27 01:53:34.211475', '2023-01-27 01:53:34.211475', NULL, 'A Message to Garcia');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1193, 'بازاریابی محتوای حماسی', 'چگونه یک داستان متفاوت بگوییم، از شلوغی ها عبور کنیم و با بازاریابی کمتر مشتریان بیشتری به دست آوریم', 'چگونه یک داستان متفاوت بگوییم، از شلوغی ها عبور کنیم و با بازاریابی کمتر مشتریان بیشتری به دست آوریم', 16, 6, 'book', 't', '<p><em>بازاریابی محتوای حماسی </em>(2014) یک راهنمای گام به گام برای تسلط بر یکی از خلاقانه ترین رویکردهای امروزی در بازاریابی محصول به شما ارائه می دهد. شناخت مخاطبان خود و تشکیل تیم محتوای درجه یک تنها برخی از عناصر کلیدی برای دستیابی به یک استراتژی بازاریابی محتوای موفق و پیشروی در یک بازار بسیار رقابتی است.</p>', '2015-05-26 00:00:00', 4, 100, 'https://images.blinkist.io/images/books/5563ac2a6461640007540000/1_1/470.jpg', '/en/books/epic-content-marketing-en/purchase', 'بازاریابی-محتوای-حماسی', '2023-01-27 01:53:39.464713', '2023-01-27 01:53:39.464713', NULL, 'Epic Content Marketing');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1194, 'اقتصاد برای منافع عمومی', 'با یک برنده جایزه نوبل وارد اقتصاد شوید', 'با یک برنده جایزه نوبل وارد اقتصاد شوید', 28, 10, 'book', 't', '<p>کتاب <em>اقتصاد برای خیر عمومی</em> ژان تیرول (2017) نگاهی گسترده به اقتصاد معاصر است که مملو از بینش‌های فراوانی در مورد نظریه و عمل اقتصاد مدرن است. Tirole با ساختارشکنی تضاد فرضی دولت و بازار، ارتباطات متقابل متعدد آنها را در زمینه‌هایی از تغییرات آب و هوایی گرفته تا حقوق مالکیت و اقتصاد دیجیتال جدید بررسی می‌کند.</p>', '2018-05-21 00:00:00', 4, 46, 'https://images.blinkist.io/images/books/5b01a475b238e100075e00a8/1_1/470.jpg', '/en/books/economics-for-the-common-good-en/purchase', 'اقتصاد-برای-منافع-عمومی', '2023-01-27 01:53:47.314891', '2023-01-27 01:53:47.314891', NULL, 'Economics for the Common Good');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1195, 'بدن', 'راهنمای سرنشینان', 'راهنمای سرنشینان', 29, 11, 'book', 't', '<p><em>بدن: راهنمای سرنشینان</em> (2019) گزارشی سرگرم‌کننده و پر از واقعیت از نحوه کار همه ما است. بیل برایسون با شوخ طبعی خود، روش های شگفت انگیزی که بدن ما در کنار هم قرار می گیرد و آنچه در درون آنها می گذرد را توضیح می دهد.</p>', '2019-11-15 00:00:00', 4, 225, 'https://images.blinkist.io/images/books/5dcace826cee07000744ce11/1_1/470.jpg', '/en/books/the-body-en/purchase', 'بدن', '2023-01-27 01:53:52.635952', '2023-01-27 01:53:52.635952', NULL, 'The Body');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1494, 'Screamfree Parenting', 'رویکرد انقلابی برای تربیت فرزندان با حفظ خونسردی', 'رویکرد انقلابی برای تربیت فرزندان با حفظ خونسردی', 9, 4, 'book', 't', '<p><em>Screamfree Parenting</em> (2007) راهنمای شما برای ارتباط بهتر با فرزندانتان است. از فضا و مرزهایی که یک کودک به آن نیاز دارد، تا اعتماد و عشقی که به خودتان نیاز دارید، این پلک ها اصول والدین بدون جیغ را روشن می کند.</p>', '2016-03-24 00:00:00', 4, 106, 'https://images.blinkist.io/images/books/56f12748f77893000700001b/1_1/470.jpg', '/en/books/screamfree-parenting-en/purchase', 'Screamfree-Parenting', '2023-01-27 02:30:10.538943', '2023-01-27 02:30:10.538943', NULL, 'Screamfree Parenting');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1196, 'زمان گذاشتن', 'چگونه روی آنچه که هر روز مهم است تمرکز کنیم', 'چگونه روی آنچه که هر روز مهم است تمرکز کنیم', 35, 13, 'book', 't', '<p><em>زمان بسازید</em> (2018) به ظاهر غیرممکن را وعده می دهد، سپس در واقع کالا را تحویل می دهد. این پلک‌ها به شما کمک می‌کنند دقیقاً همان چیزی را که عنوان نشان می‌دهد انجام دهید: وقت بیشتری بگذارید. البته، ساعات زیادی در روز وجود دارد و شما نمی توانید تعداد بیشتری از آنها را تولید کنید. با این حال، آنچه که آنها ارائه می دهند، یک تشخیص روشنگر است از اینکه چگونه و چرا وقت خود را به خاطر مشغله ها و حواس پرتی ها از دست می دهید، همراه با یک استراتژی بسیار شخصی سازی شده و یک بوفه سخاوتمندانه از تاکتیک های عملی برای بازیابی آن، که به شما امکان می دهد کارهایی را که واقعاً می خواهید انجام دهید. در زندگی انجام دهید.</p>', '2018-11-01 00:00:00', 4, 218, 'https://images.blinkist.io/images/books/5bd969c16cee070007bc4c7a/1_1/470.jpg', '/en/books/make-time-en/purchase', 'زمان-گذاشتن', '2023-01-27 01:53:59.903949', '2023-01-27 01:53:59.903949', NULL, 'Make Time');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1197, 'خلاق تصادفی', 'چگونه در یک لحظه درخشان باشیم', 'چگونه در یک لحظه درخشان باشیم', 18, 7, 'book', 't', '<p><em>خلاقیت تصادفی</em> (2011) توضیح می دهد که چگونه می توانید خلاقیت فردی خود را آزاد کنید و مدیریت کنید. این کتاب بیان می‌کند که همه افراد پتانسیل خلاقیت را دارند، اگرچه بسیاری فاقد ابزار لازم برای عمل بر روی این خلاقیت هستند. این کتاب نحوه دستیابی به حداکثر خلاقیت را شرح می‌دهد و تکنیک‌هایی را در اختیار شما قرار می‌دهد که به شما کمک می‌کند تا به طور مداوم و بدون زحمت خلق کنید.</p>', '2018-02-01 00:00:00', 5, 89, 'https://images.blinkist.io/images/books/5a6f0753b238e10009732042/1_1/470.jpg', '/en/books/the-accidental-creative-en/purchase', 'خلاق-تصادفی', '2023-01-27 01:54:07.153986', '2023-01-27 01:54:07.153986', NULL, 'The Accidental Creative');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1198, '11 قانون دوست داشتنی', 'شبکه‌های ارتباطی … زیرا مردم با افرادی که دوست دارند تجارت می‌کنند', 'شبکه‌های ارتباطی … زیرا مردم با افرادی که دوست دارند تجارت می‌کنند', 15, 7, 'book', 't', '<p><em>11 قانون دوست‌داشتنی</em> (2011) راهنمای شبکه‌سازی است که بر اساس یک واقعیت ساده بنا شده است: <em>افراد با افرادی که دوست دارند تجارت می‌کنند.</em> این پلک‌ها نحوه انجام کار را توضیح می‌دهند. دوست داشتنی ترین ویژگی های خود را کشف کنید، گفتگوها را شروع کنید و آنها را ادامه دهید، و تأثیر مثبت پایداری بر مردم بگذارید.</p>', '2016-06-10 00:00:00', 4, 155, 'https://images.blinkist.io/images/books/57500d447bea3d0003c715b7/1_1/470.jpg', '/en/books/the-11-laws-of-likability-en/purchase', '11-قانون-دوست-داشتنی', '2023-01-27 01:54:14.68528', '2023-01-27 01:54:14.68528', NULL, 'The 11 Laws of Likability');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1199, 'پای را تقسیم کنید', 'یک راه رادیکال جدید برای مذاکره', 'یک راه رادیکال جدید برای مذاکره', 17, 3, 'book', 't', '<p><em>Split the Pie </em>(2022) رویکرد جدیدی را برای نحوه مذاکره همه افراد نشان می دهد. در حالی که مذاکرات اغلب بدترین چیزها را در افراد به ارمغان می آورد، لازم نیست اینگونه باشد. با استفاده از رویکرد "پای"، می‌توانید با این اطمینان وارد هر مذاکره‌ای شوید که در نهایت سهم منصفانه خود را خواهید داشت.</p>', '2022-09-27 00:00:00', 4, 260, 'https://images.blinkist.io/images/books/633165436cee070008ecbb6c/1_1/470.jpg', '/en/books/split-the-pie-en/purchase', 'پای-را-تقسیم-کنید', '2023-01-27 01:54:21.935331', '2023-01-27 01:54:21.935331', NULL, 'Split the Pie');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1200, 'تحصیل کرده', 'یک خاطره', 'یک خاطره', 32, 12, 'book', 't', '<p><em>تحصیل شده</em> (2018) خاطرات تارا وستور است که در یک خانواده مورمون در روستایی آیداهو بزرگ شد و علیرغم اینکه هرگز به مدرسه نرفته بود، توانست مدرک دکترای خود را از دانشگاه کمبریج دریافت کند. . با این حال، او برای رسیدن به رویاهای تحصیلی خود مجبور به پرداخت هزینه زیادی شد. در واقع، او خانواده خود را در این روند از دست داد.</p>', '2018-05-24 00:00:00', 4, 133, 'https://images.blinkist.io/images/books/5b01b50cb238e100075e00cf/1_1/470.jpg', '/en/books/educated-en/purchase', 'تحصیل-کرده', '2023-01-27 01:54:29.177035', '2023-01-27 01:54:29.177035', NULL, 'Educated');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1201, 'اسطوره سیزیف', 'یک مقاله اگزیستانسیالیستی تأثیرگذار در مورد زندگی با اشتیاق و آزادی بیشتر', 'یک مقاله اگزیستانسیالیستی تأثیرگذار در مورد زندگی با اشتیاق و آزادی بیشتر', 14, 6, 'book', 't', '<p><em>افسانه سیزیف</em> (1942) مقاله ای تأثیرگذار است که به طور قابل توجهی به جنبش های فلسفی اگزیستانسیالیسم و ​​پوچ گرایی کمک کرد. این مقاله می‌پرسد که آیا زندگی در دنیایی که از معنای دینی تهی شده است ارزش زیستن دارد یا خیر و به این موضوع می‌پردازد که آیا خودکشی تنها پاسخ مناسب به خلأ بی‌معنای است؟ در نهایت، این مقاله از خودکشی توصیه می‌کند و استدلال می‌کند که بی‌معنای هستی در واقع شرط یک زندگی کامل است که با آزادی، اشتیاق و شادی زندگی می‌کند.</p>', '2021-02-06 00:00:00', 5, 228, 'https://images.blinkist.io/images/books/6013d1046cee070008ada601/1_1/470.jpg', '/en/books/the-myth-of-sisyphus-en/purchase', 'اسطوره-سیزیف', '2023-01-27 01:54:36.009799', '2023-01-27 01:54:36.009799', NULL, 'The Myth of Sisyphus ');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1202, 'تاریخچه عجیب قرار ملاقات', 'از جین آستن تا Tinder', 'از جین آستن تا Tinder', 30, 11, 'book', 't', '<p><em>تاریخ عجیب قرار ملاقات</em> (2017) خوانندگان را از طریق تاریخچه قرار ملاقات و روابط در بریتانیا راهنمایی می کند. از رقص‌ها و قوانین رسمی دهه 1700 تا رشد دوستیابی آنلاین در سال‌های اخیر، این پلک‌ها نشان می‌دهد که قرار ملاقات و یافتن عشق واقعی همیشه یک امر دشوار بوده است. اما خوشبختانه، امروز آسان‌تر از همیشه است.</p>', '2019-01-24 00:00:00', 4, 29, 'https://images.blinkist.io/images/books/5c4886f66cee07000701c182/1_1/470.jpg', '/en/books/the-curious-history-of-dating-en/purchase', 'تاریخچه-عجیب-قرار-ملاقات', '2023-01-27 01:54:43.161668', '2023-01-27 01:54:43.161668', NULL, 'The Curious History of Dating');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1203, 'پرونده اخلاقی برای سوخت های فسیلی', 'اگر استفاده از سوخت های فسیلی سالم و اخلاقی باشد، چه؟', 'اگر استفاده از سوخت های فسیلی سالم و اخلاقی باشد، چه؟', 10, 4, 'book', 't', '<p>در <em>موضوع اخلاقی برای سوخت‌های فسیلی</em>، نویسنده الکس اپستاین به بررسی مزایای سوخت‌های فسیلی مانند زغال‌سنگ، گاز طبیعی و نفت می‌پردازد. این کتاب تأثیرات شگرف و مثبتی که استفاده از چنین سوخت‌هایی بر جامعه داشته است را بیان می‌کند و افسانه‌های متعدد مرتبط با سوخت‌های فسیلی را بررسی می‌کند. مهمتر از همه، استفاده از سوخت‌های فسیلی یک تصمیم اخلاقی است، زیرا مزایای آنها برای بشریت بیشتر از نگرانی‌های زیست‌محیطی امروزی است.</p>', '2015-03-18 00:00:00', 2, 73, 'https://images.blinkist.io/images/books/55062a72666365000a6c0000/1_1/470.jpg', '/en/books/the-moral-case-for-fossil-fuels-en/purchase', 'پرونده-اخلاقی-برای-سوخت-های-فسیلی', '2023-01-27 01:54:50.295305', '2023-01-27 01:54:50.295305', NULL, 'The Moral Case for Fossil Fuels');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1204, 'ماده تاریک و دایناسورها', 'به هم پیوستگی شگفت انگیز کیهان', 'به هم پیوستگی شگفت انگیز کیهان', 23, 11, 'book', 't', '<p><em>ماده تاریک و دایناسورها</em> (2015) نگاهی دقیق به ارتباطات متقابل قابل توجه بین زمین و جهان اطراف آن دارد. این پلک‌ها توضیح می‌دهند که چگونه ماده تاریک، ماده نامرئی که بیشتر کیهان را تشکیل می‌دهد، با انقراض‌های انبوه در گذشته و دنباله‌دارهایی که ممکن است روزی روزی دیگر را ایجاد کنند، ارتباط دارد.</p>', '2016-06-22 00:00:00', 4, 53, 'https://images.blinkist.io/images/books/576906d1ae95d80003cf773b/1_1/470.jpg', '/en/books/dark-matter-and-the-dinosaurs-en/purchase', 'ماده-تاریک-و-دایناسورها', '2023-01-27 01:54:57.738421', '2023-01-27 01:54:57.738421', NULL, 'Dark Matter and the Dinosaurs');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1205, 'گفتگوی منظم', 'ارائه های تجاری دوباره تعریف شد', 'ارائه های تجاری دوباره تعریف شد', 11, 5, 'book', 't', '<p><em>مکالمه منظم</em> (2014) راهنمای طراحی، آماده سازی و ارائه یک ارائه قاتل است. این پلک‌ها توضیح می‌دهند که چرا سخنرانی با ارائه در یک زمینه تجاری متفاوت است و چرا ارائه‌های قوی مانند یک مکالمه خوب هستند.</p>', '2017-02-20 00:00:00', 4, 20, 'https://images.blinkist.io/images/books/58aadac38e98580004e55686/1_1/470.jpg', '/en/books/the-orderly-conversation-en/purchase', 'گفتگوی-منظم', '2023-01-27 01:55:06.518426', '2023-01-27 01:55:06.518426', NULL, 'The Orderly Conversation');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1206, 'تجسم مجدد سرمایه داری در جهانی در آتش', 'چگونه تجارت می تواند جهان را نجات دهد', 'چگونه تجارت می تواند جهان را نجات دهد', 25, 8, 'book', 't', '<p><em>تصویر مجدد سرمایه داری در جهانی در آتش </em>(2020) از ما می خواهد که اگر می خواهیم از بحران های کنونی خود، مانند تغییرات آب و هوا، نابرابری، و پوپولیسم اقتدارگرا جان سالم به در ببریم، در نحوه عملکرد سیستم اقتصادی خود تجدید نظر کنیم. در این راهنمای آینده، ربکا هندرسون توضیح می‌دهد که چگونه باید هدفی را در سرمایه‌گذاری‌های تجاری خود القا کنیم، به طوری که آنها ارزش مشترک ایجاد کنند، نه صرفاً ارزش سهامداران.</p>', '2020-10-07 00:00:00', 4, 150, 'https://images.blinkist.io/images/books/5f76e2276cee070007d0480d/1_1/470.jpg', '/en/books/reimagining-capitalism-in-a-world-on-fire-en/purchase', 'تجسم-مجدد-سرمایه-داری-در-جهانی-در-آتش', '2023-01-27 01:55:14.436839', '2023-01-27 01:55:14.436839', NULL, 'Reimagining Capitalism in a World on Fire');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1207, 'الکساندر همیلتون', 'پرفروش ترین الهام بخش موزیکال موفق برادوی', 'پرفروش ترین الهام بخش موزیکال موفق برادوی', 38, 15, 'book', 't', '<p><em>الکساندر همیلتون </em>(2004) داستان باورنکردنی یک پسر یتیم فقیر را روایت می‌کند که جاه‌طلبی، هوش و سرسختی بی‌پایانش مسیر تاریخ آمریکا را شکل داده است. این زندگینامه الکساندر همیلتون، روشنفکر، سرباز و سیاستمداری است که کمک کرد ایالات متحده به کشور امروزی تبدیل شود. </p>', '2019-02-14 00:00:00', 5, 70, 'https://images.blinkist.io/images/books/5c62ee486cee0700078afee7/1_1/470.jpg', '/en/books/alexander-hamilton-en/purchase', 'الکساندر-همیلتون', '2023-01-27 01:55:20.219953', '2023-01-27 01:55:20.219953', NULL, 'Alexander Hamilton');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1208, 'انرژی', 'راهنمای یک مبتدی', 'راهنمای یک مبتدی', 17, 7, 'book', 't', '<p><em>انرژی </em>(2006) بینش هایی را در مورد یکی از گریزناپذیرترین مفاهیم در طیف تفکر بشر ارائه می دهد: انرژی. با درک اینکه انرژی چیست، چگونه به ما کمک کرده تا به جایی که امروز هستیم برسیم و اتکای ما به اشکال خاصی از انرژی چه خطراتی را به همراه دارد، برای مقابله با چالش های پیش روی تمدن مدرن مجهزتر خواهیم شد.</p>', '2015-08-03 00:00:00', 4, 94, 'https://images.blinkist.io/images/books/55bf57c063646100070f0000/1_1/470.jpg', '/en/books/energy-en/purchase', 'انرژی', '2023-01-27 01:55:28.531179', '2023-01-27 01:55:28.531179', NULL, 'Energy');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1209, 'انفجار صوتی', 'چگونه صدا طرز فکر، احساس و خرید ما را تغییر می دهد', 'چگونه صدا طرز فکر، احساس و خرید ما را تغییر می دهد', 11, 4, 'book', 't', '<p><em>Sonic Boom </em>(2014) راه‌های متعددی را که صداها نه تنها در محیط، بلکه در زندگی شخصی ما نفوذ می‌کنند، نشان می‌دهد. از برند شرکت شما گرفته تا فضای شخصی شما، صدا این قدرت را دارد که ما را به یاد بیاورد و حتی می تواند ما را تشویق به خرید کند. این پلک‌ها دقیقاً به شما نشان می‌دهند که چگونه از قدرت صدا در تجارت و زندگی خود استفاده کنید.</p>', '2015-04-23 00:00:00', 4, 10, 'https://images.blinkist.io/images/books/553501f76638630007d50000/1_1/470.jpg', '/en/books/sonic-boom-en/purchase', 'انفجار-صوتی', '2023-01-27 01:55:35.883996', '2023-01-27 01:55:35.883996', NULL, 'Sonic Boom');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1210, 'جفت گیری در اسارت', 'در جستجوی هوش اروتیک', 'در جستجوی هوش اروتیک', 24, 8, 'book', 't', '<p><em>جفت گیری در اسارت </em>(2006)<em> </em>سوالی را که همه در یک رابطه متعهدانه می پرسند را بررسی می کند: آیا می توان شور و اشتیاق را در مدت زمان طولانی حفظ کرد؟ استر پرل، نویسنده معتقد است که چنین است، اما او فکر می‌کند که ما فقط می‌توانیم با ارزیابی مجدد ایده‌آل‌های مدرن پیرامون تعهد و درک بهتر اینکه چگونه تاریخچه‌های شخصی ما بر رفتار ما در اتاق خواب تأثیر می‌گذارد، هیجان جنسی ایجاد کنیم. اگر بتوانیم این کار را انجام دهیم، روابطمان را با رمز و راز و هیجانی که شور و شوق را شعله ور می کند، تقویت می کنیم.</p>', '2020-03-22 00:00:00', 5, 274, 'https://images.blinkist.io/images/books/5e70e90c6cee0700062443e6/1_1/470.jpg', '/en/books/mating-in-captivity-en/purchase', 'جفت-گیری-در-اسارت', '2023-01-27 01:55:43.998973', '2023-01-27 01:55:43.998973', NULL, 'Mating in Captivity');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1211, 'سام والتون: ساخت آمریکا', 'داستان من', 'داستان من', 16, 7, 'book', 't', '<p><em>ساخت آمریکا</em> (1992) داستان الهام‌بخش سام والتون، بنیانگذار والمارت، یکی از بزرگترین شرکت‌های جهان را روایت می‌کند. دریابید که چگونه والتون از رویکرد مشتری اول برای تبدیل یک فروشگاه انواع کوچک به یک امپراتوری تجاری جهانی استفاده کرد و چگونه یک پسر فقیر از اوکلاهاما به یکی از ثروتمندترین افراد جهان تبدیل شد.</p>', '2016-05-17 00:00:00', 4, 69, 'https://images.blinkist.io/images/books/57344e4de2369000032901d3/1_1/470.jpg', '/en/books/sam-walton-made-in-america-en/purchase', 'سام-والتون:-ساخت-آمریکا', '2023-01-27 01:55:51.296208', '2023-01-27 01:55:51.296208', NULL, 'Sam Walton: Made in America');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1212, 'خماری استدلال', 'توانمندسازی زوج ها برای مبارزه هوشمندانه تر و غلبه بر مشکلات ارتباطی', 'توانمندسازی زوج ها برای مبارزه هوشمندانه تر و غلبه بر مشکلات ارتباطی', 17, 5, 'book', 't', '<p><em>خماری مشاجره</em> (2021) راهنمای شما برای دعوای سازنده با یک شریک عاشقانه است تا هم از درگیری درس بگیرید و هم قوی تر از آن بیرون بیایید. از طریق ارتباط واضح، از این که بفهمید چگونه اختلاف نظرها می توانند ناگهان به فرصت هایی برای رشد تبدیل شوند، شگفت زده خواهید شد.</p>', '2022-12-27 00:00:00', 5, 45, 'https://images.blinkist.io/images/books/63a1ab12ac4463000945cfc1/1_1/470.jpg', '/en/books/the-argument-hangover-en/purchase', 'خماری-استدلال', '2023-01-27 01:55:59.15492', '2023-01-27 01:55:59.15492', NULL, 'The Argument Hangover');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1213, 'تحقق ایده ها', 'غلبه بر موانع بین چشم انداز و واقعیت', 'غلبه بر موانع بین چشم انداز و واقعیت', 19, 8, 'book', 't', '<p><em>انجام ایده‌ها</em> با موانعی که بین ایده‌های شما و اجرای آنها وجود دارد، سروکار دارد. با ارائه مثال‌های واقعی از برخی از برندهای برجسته جهان و ذهن خلاق، بینشی را در مورد راه‌هایی که افراد موفق و بخش‌های خلاق بر این موانع غلبه می‌کنند، ارائه می‌دهد.</p>', '2015-01-01 00:00:00', 4, 72, 'https://images.blinkist.io/images/books/548f077d6532350009300100/1_1/470.jpg', '/en/books/making-ideas-happen-en/purchase', 'تحقق-ایده-ها', '2023-01-27 01:56:07.479588', '2023-01-27 01:56:07.479588', NULL, 'Making Ideas Happen');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1214, 'تحقیق کاربر', 'راهنمای عملی برای طراحی محصولات و خدمات بهتر', 'راهنمای عملی برای طراحی محصولات و خدمات بهتر', 19, 8, 'book', 't', '<p><em>تحقیق کاربر</em> (2018) یک راهنمای عملی چگونه برای کارآفرینان، محققان و مدیرانی است که علاقه مند به پاسخگویی به مهمترین سؤال در تجارت هستند - آیا محصول شما نیازهای مشتریان شما را برآورده می کند؟ این پلک ها با تکیه بر سال ها تجربه نویسنده استفانی مارش در تحقیقات کاربر، متداول ترین روش ها را ارائه می دهند که مزایا و معایب هر کدام را به وضوح توضیح می دهند. </p>', '2019-08-27 00:00:00', 4, 54, 'https://images.blinkist.io/images/books/5d5eebe26cee070007c14bf6/1_1/470.jpg', '/en/books/user-research-en/purchase', 'تحقیق-کاربر', '2023-01-27 01:56:15.456353', '2023-01-27 01:56:15.456353', NULL, 'User Research');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1215, 'چگونه تقریباً در همه چیز شکست بخوریم و همچنان برنده بزرگ شویم', 'نوعی داستان زندگی من', 'نوعی داستان زندگی من', 16, 6, 'book', 't', '<p><em>چگونه در تقریباً همه چیز شکست بخوریم و همچنان برنده شوید</em> (2013) یک کوله بار از زندگی و توصیه های شغلی از خالق <em>Dilbert</em>، کمیک استریپ محبوب است. اسکات آدامز توضیح می دهد که چگونه به عنوان یک کاریکاتوریست و تاجر موفق شد، نه با وجود شکست هایش، بلکه به خاطر آنها. او همچنین اسرار خود را برای حفظ سطح انرژی بالا و استفاده از آنها برای ایجاد یک زندگی پر از یادگیری و بهبود مستمر به اشتراک می گذارد.</p>', '2018-04-27 00:00:00', 4, 112, 'https://images.blinkist.io/images/books/5ade2f0ab238e10007596e8e/1_1/470.jpg', '/en/books/how-to-fail-at-almost-everything-and-still-win-big-en/purchase', 'چگونه-تقریباً-در-همه-چیز-شکست-بخوریم-و-همچنان-برنده-بزرگ-شویم', '2023-01-27 01:56:23.478753', '2023-01-27 01:56:23.478753', NULL, 'How to Fail at Almost Everything and Still Win Big');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1216, 'قدرت داستان سرایی بصری', 'چگونه از تصاویر، ویدئوها و رسانه های اجتماعی برای بازاریابی برند خود استفاده کنید', 'چگونه از تصاویر، ویدئوها و رسانه های اجتماعی برای بازاریابی برند خود استفاده کنید', 19, 8, 'book', 't', '<p><em>قدرت داستان سرایی بصری</em> (2014) راهنمای نهایی است که به شما نشان می دهد چگونه از طریق تصاویر بصری داستان بگویید و چگونه از این تکنیک به نفع شرکت خود استفاده کنید. با مثال‌های واضح، این پلک‌ها با جزئیات توضیح می‌دهند که چگونه می‌توانید از طریق تصاویر قدرتمند بر مهم‌ترین پلتفرم‌های رسانه‌های اجتماعی امروزی تسلط داشته باشید. </p>', '2015-11-03 00:00:00', 4, 45, 'https://images.blinkist.io/images/books/56376a8362346500071e0000/1_1/470.jpg', '/en/books/the-power-of-visual-storytelling-en/purchase', 'قدرت-داستان-سرایی-بصری', '2023-01-27 01:56:31.279139', '2023-01-27 01:56:31.279139', NULL, 'The Power of Visual Storytelling');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1218, 'چگونه در مورد سکس بیشتر فکر کنیم', 'توصیه های جنسی حکیم از یک معتاد فلسفی', 'توصیه های جنسی حکیم از یک معتاد فلسفی', 37, 13, 'book', 't', '<p>در <em>چگونه بیشتر درباره سکس فکر کنیم </em> (2012)، آلن دو باتن به دنیای عجیب و اغلب ناراحت کننده سکس فرو می رود. این چشمک‌ها که با انعکاس ظریفی از معنای واقعی جنسیت و جایگاه آن در زندگی ما همراه است، مملو از بینش روانشناسی میل و توصیه‌های عملی است، مانند چگونگی حفظ علاقه جنسی در روابط طولانی‌مدت. دی باتن در نهایت نتیجه می گیرد که سکس هرگز ساده نخواهد بود، اما می تواند لذت بخش باشد. تنها کاری که باید انجام دهیم این است که بیشتر در مورد آن فکر کنیم.</p>', '2018-06-04 00:00:00', 4, 175, 'https://images.blinkist.io/images/books/5b1471f2b238e10007fe756e/1_1/470.jpg', '/en/books/how-to-think-more-about-sex-en/purchase', 'چگونه-در-مورد-سکس-بیشتر-فکر-کنیم', '2023-01-27 01:56:45.200846', '2023-01-27 01:56:45.200846', NULL, 'How to Think More About Sex');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1219, 'به جادو اعتقاد داری؟', 'ویتامین ها، مکمل ها و همه چیزهای طبیعی: نگاهی به پشت پرده', 'ویتامین ها، مکمل ها و همه چیزهای طبیعی: نگاهی به پشت پرده', 10, 4, 'book', 't', '<p><em>آیا به جادو اعتقاد دارید؟</em> (2013) حقیقت پنهان پشت طب جایگزین را آشکار می کند. با یافته‌های پژوهشی روشن‌گر و مطالعات موردی آشکار، این پلک زدن‌ها باعث می‌شود باورهای خود در مورد درمان‌های ظاهراً کاملاً طبیعی و عوارض جانبی آن‌ها را بازنگری کنیم.</p>', '2015-08-03 00:00:00', 3, 39, 'https://images.blinkist.io/images/books/55bf56846364610007010000/1_1/470.jpg', '/en/books/do-you-believe-in-magic-en/purchase', 'به-جادو-اعتقاد-داری؟', '2023-01-27 01:56:52.861421', '2023-01-27 01:56:52.861421', NULL, 'Do You Believe in Magic?');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1220, 'هنر تخمیر', 'کاوشی عمیق در مفاهیم و فرآیندهای اساسی از سراسر جهان', 'کاوشی عمیق در مفاهیم و فرآیندهای اساسی از سراسر جهان', 27, 7, 'book', 't', '<p><em>هنر تخمیر</em> (2012) یک اکتشاف برنده جوایز تخمیر است - یک فرآیند بیولوژیکی که کلیدی برای درک تکامل و فرهنگ گونه ما ارائه می دهد. از پیدایش حیات روی زمین گرفته تا خفاش‌های دوستدار الکل و هنر ساخت کلم ترش، سندور کاتز در این گزارش گیرا از تاریخ طبیعی و انسانی تخمیر، سنگ تمام نمی‌گذارد. </p>', '2021-07-06 00:00:00', 4, 63, 'https://images.blinkist.io/images/books/60ddc8256cee070007f2ca66/1_1/470.jpg', '/en/books/the-art-of-fermentation-en/purchase', 'هنر-تخمیر', '2023-01-27 01:56:59.78695', '2023-01-27 01:56:59.78695', NULL, 'The Art of Fermentation');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1221, 'عظمت اولیه', '12 اهرم موفقیت', '12 اهرم موفقیت', 22, 9, 'book', 't', '<p><em>عظمت اولیه</em> (2015) توضیح می‌دهد که هر کسی می‌تواند زندگی کاملی داشته باشد. این به سادگی اولویت بندی چیزهایی است که واقعاً مهم هستند. به جای اینکه سعی کنید با کسب موقعیت، شهرت و پول موفق به نظر برسید، باید بر روی دستیابی به موفقیت واقعی با رشد شخصیت درونی خود تمرکز کنید - کاری که 12 اهرم موفقیت آن را ساده می کند.</p>', '2018-03-06 00:00:00', 5, 227, 'https://images.blinkist.io/images/books/5a9b350eb238e1000791093a/1_1/470.jpg', '/en/books/primary-greatness-en/purchase', 'عظمت-اولیه', '2023-01-27 01:57:06.777687', '2023-01-27 01:57:06.777687', NULL, 'Primary Greatness');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1222, 'هوشمندتر سریعتر بهتر', 'رازهای سازنده بودن در زندگی و تجارت', 'رازهای سازنده بودن در زندگی و تجارت', 14, 6, 'book', 't', '<p><em>هوشمندتر سریعتر بهتر </em>(2016) داستانهای شخصی و تحقیقات تجاری را با هم ترکیب می کند تا نشان دهد که سازنده بودن فقط مدیریت لیست کارهای شما نیست، بلکه انتخاب صحیح و حفظ طرز فکر صحیح است. . این پلک‌ها توصیه‌هایی در مورد چگونگی با انگیزه ماندن، حفظ خود در مسیر و کار در تیم‌ها برای به حداکثر رساندن خلاقیت، بهره‌وری و موفقیت شما ارائه می‌دهند.</p>', '2016-06-30 00:00:00', 4, 330, 'https://images.blinkist.io/images/books/576ba933e0dd250003d615ba/1_1/470.jpg', '/en/books/smarter-faster-better-en/purchase', 'هوشمندتر-سریعتر-بهتر', '2023-01-27 01:57:13.902992', '2023-01-27 01:57:13.902992', NULL, 'Smarter Faster Better');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1223, 'اوبونتو روزمره', 'زندگی بهتر با هم، به روش آفریقایی', 'زندگی بهتر با هم، به روش آفریقایی', 23, 8, 'book', 't', '<p><em> Everyday Ubuntu </em> (2019) 14 عمل <em>ubuntu </em> را توضیح می دهد - یک فلسفه آفریقای جنوبی که می آموزد همه انسان ها عمیقاً به هم مرتبط هستند. با ارائه مطالعات موردی الهام‌بخش و تمرین‌های عملی، نشان می‌دهد که چگونه می‌توانید از <em>ubuntu </em>برای عمیق‌تر کردن ارتباطات خود با دیگران و رسیدن به آرامش درونی بیشتر استفاده کنید.</p>', '2020-03-24 00:00:00', 5, 188, 'https://images.blinkist.io/images/books/5e74dbee6cee07000650d507/1_1/470.jpg', '/en/books/everyday-ubuntu-en/purchase', 'اوبونتو-روزمره', '2023-01-27 01:57:21.326959', '2023-01-27 01:57:21.326959', NULL, 'Everyday Ubuntu');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1224, 'نظم و انضباط سرنوشت است', 'قدرت خودکنترلی', 'قدرت خودکنترلی', 18, 4, 'book', 't', '<p><em>انضباط سرنوشت است</em> (2022) از فضایل رواقی استفاده می‌کند تا زندگی‌ای را که توسط خود انضباط هدایت می‌شود، مطرح کند. این نشان می‌دهد که چگونه کنترل بدن، افکار و احساسات، پیش‌نیاز تسلط بر هر چیز دیگری است - و از چهره‌های تاریخی برای نشان دادن اینکه چگونه چیزهایی مانند خواب، ناراحتی و مهربانی با عظمت پیوند می‌خورند، استفاده می‌کند. </p>', '2022-11-07 00:00:00', 5, 1089, 'https://images.blinkist.io/images/books/63625bd6958fe9000879ffdf/1_1/470.jpg', '/en/books/discipline-is-destiny-en/purchase', 'نظم-و-انضباط-سرنوشت-است', '2023-01-27 01:57:26.539016', '2023-01-27 01:57:26.539016', NULL, 'Discipline Is Destiny');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1233, 'هیچی نگو', 'داستان واقعی قتل و خاطره در ایرلند شمالی', 'داستان واقعی قتل و خاطره در ایرلند شمالی', 19, 6, 'book', 't', '<p><em>هیچ چیزی نگو</em> (2018) یک داستان واقعی تکان دهنده از قتل در جریان درگیری ایرلند شمالی را بررسی می کند. این پلک‌ها مراقبه‌ای قانع‌کننده در مورد یکی از تاریک‌ترین فصل‌های تاریخ ایرلند است و بر برخی از چهره‌های کلیدی درگیری و همچنین بدنام‌ترین جنایات آن دوره روشن می‌شود.</p>', '2019-04-09 00:00:00', 4, 36, 'https://images.blinkist.io/images/books/5ca9b8106cee07000759a4b5/1_1/470.jpg', '/en/books/say-nothing-en/purchase', 'هیچی-نگو', '2023-01-27 01:58:33.991179', '2023-01-27 01:58:33.991179', NULL, 'Say Nothing');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1226, 'بسیار گرانبها', 'افسانه ارزش منصفانه (و نحوه استفاده از آن)', 'افسانه ارزش منصفانه (و نحوه استفاده از آن)', 14, 7, 'book', 't', '<p><em>بی‌قیمت</em> (2010) دلایل روان‌شناختی پشت ارزش و قیمتی که ما به چیزها می‌دهیم را بررسی می‌کند. از طریق آزمایش‌های متعدد و مطالعات موردی در قیمت‌گذاری، نویسنده توضیح می‌دهد که چگونه قیمت‌ها بر تصمیم خرید ما تأثیر می‌گذارند و شرکت‌هایی را که از قیمت‌گذاری برای افزایش سود استفاده می‌کنند، نشان می‌دهد.</p>', '2015-06-24 00:00:00', 5, 20, 'https://images.blinkist.io/images/books/558922be3466610007400000/1_1/470.jpg', '/en/books/priceless-en/purchase', 'بسیار-گرانبها', '2023-01-27 01:57:38.769597', '2023-01-27 01:57:38.769597', NULL, 'Priceless');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1227, 'مزیت تجربه کارمند', 'چگونه با دادن فضای کاری به کارکنان، ابزارهای مورد نیاز و فرهنگی که می توانند جشن بگیرند، در جنگ برای استعداد پیروز شویم.', 'چگونه با دادن فضای کاری به کارکنان، ابزارهای مورد نیاز و فرهنگی که می توانند جشن بگیرند، در جنگ برای استعداد پیروز شویم.', 27, 9, 'book', 't', '<p><em>مزیت تجربه کارکنان</em> (2017) بررسی می‌کند که چگونه و چرا سازمان‌هایی که بر تجربه کارمندان تمرکز می‌کنند بسیار بهتر از سازمان‌هایی هستند که این کار را انجام نمی‌دهند. با استفاده از تحقیقات اخیر، ابعاد و ویژگی های کلیدی یک محل کار را شناسایی می کند که یک تجربه بهینه برای کارمندان ایجاد می کند. همچنین پیشنهادات عملی برای اینکه چگونه شما نیز می توانید چنین محیط کاری را ایجاد کنید، ارائه می دهد، که به کارمندان این امکان را می دهد تا احساس الهام، انگیزه و اشتیاق برای انجام کارهای خود داشته باشند. </p>', '2019-07-16 00:00:00', 4, 48, 'https://images.blinkist.io/images/books/5d2cd3f16cee0700079126fc/1_1/470.jpg', '/en/books/the-employee-experience-advantage-en/purchase', 'مزیت-تجربه-کارمند', '2023-01-27 01:57:46.847356', '2023-01-27 01:57:46.847356', NULL, 'The Employee Experience Advantage');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1228, 'برای کارآفرین آماده نیست', 'روشی برای جنون راه اندازی کسب و کار خودتان', 'روشی برای جنون راه اندازی کسب و کار خودتان', 18, 5, 'book', 't', '<p><em>Unprepared to Entrepreneur</em>(2021) یک راهنمای صریح و پر جنب و جوش برای راه اندازی یک کسب و کار برای کسانی است که می ترسند دانش لازم را ندارند، نگران شکست خوردنشان هستند یا مطمئن نیستند. چگونه شروع کنیم مملو از نکات کاربردی و حکایات شخصی، به شما نشان می دهد که برای موفقیت در دنیای تجارت، نیازی به یک برنامه کامل یا مدرک گران قیمت ندارید. شما فقط به یک چشم انداز، انگیزه – یا جنون – برای تحقق آن نیاز دارید، و انعطاف پذیری برای اینکه همیشه روی پای خود بایستید.</p>', '2022-03-25 00:00:00', 4, 171, 'https://images.blinkist.io/images/books/623da31a6cee070008873e45/1_1/470.jpg', '/en/books/unprepared-to-entrepreneur-en/purchase', 'برای-کارآفرین-آماده-نیست', '2023-01-27 01:57:54.747998', '2023-01-27 01:57:54.747998', NULL, 'Unprepared to Entrepreneur');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1229, 'شکستن با شکر', 'برنامه ای برای طلاق گرفتن از رژیم های غذایی، کاهش وزن و بهترین زندگی خود', 'برنامه ای برای طلاق گرفتن از رژیم های غذایی، کاهش وزن و بهترین زندگی خود', 21, 6, 'book', 't', '<p><strong>درباره چیست؟</strong></p>
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1230, 'لبه داستان سرایی', 'چگونه کسب و کار خود را متحول کنید، از فریاد زدن به خلأ دست بردارید، و مردم شما را دوست داشته باشند', 'چگونه کسب و کار خود را متحول کنید، از فریاد زدن به خلأ دست بردارید، و مردم شما را دوست داشته باشند', 20, 6, 'book', 't', '<p><em>The Storytelling Edge </em>(2018) مطالعه‌ای درباره ارتباطات دو استراتژیست محتوا است که یک ضرب‌المثل قدیمی بومیان آمریکا را در دل گرفته‌اند - "کسانی که داستان‌ها را می‌گویند دنیا را اداره می‌کنند." همانطور که شین اسنو و جو لازاوسکاس بیان می کنند، مهم نیست که شما یک فرد، یک کسب و کار یا یک دولت باشید: اگر می خواهید در دنیای امروز پیشرفت کنید، باید بتوانید داستان خود را قانع کننده و روان بیان کنید. تا حد امکان.</p>', '2019-12-26 00:00:00', 4, 262, 'https://images.blinkist.io/images/books/5dfcb4d16cee0700087f97a3/1_1/470.jpg', '/en/books/the-storytelling-edge-en/purchase', 'لبه-داستان-سرایی', '2023-01-27 01:58:11.945181', '2023-01-27 01:58:11.945181', NULL, 'The Storytelling Edge');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1231, 'تیم هایی که کار می کنند', 'هفت عامل موثر بودن تیم', 'هفت عامل موثر بودن تیم', 24, 7, 'book', 't', '<p><em>تیم‌هایی که کار می‌کنند </em>(2020) هفت محرک را ارائه می‌کند که هر تیمی را موثر می‌سازد. این راهنمای عملی که حاوی آخرین تحقیقات و نمونه‌های واقعی است، از تجربه چندین ساله نویسندگان همکار اسکات تاننبام و ادواردو سالاس در کمک به تیم‌ها برای موفقیت استفاده می‌کند.</p>', '2021-07-14 00:00:00', 5, 80, 'https://images.blinkist.io/images/books/60ddd3836cee07000754f899/1_1/470.jpg', '/en/books/teams-that-work-en/purchase', 'تیم-هایی-که-کار-می-کنند', '2023-01-27 01:58:20.100561', '2023-01-27 01:58:20.100561', NULL, 'Teams That Work');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1255, 'خودت را مختل کن', 'استفاده از قدرت نوآوری مخرب', 'استفاده از قدرت نوآوری مخرب', 15, 7, 'book', 't', '<p><em>Disrupt Yourself </em>(2015) درباره شروع سفر اکتشاف مداوم است که شغل شماست. با دنبال کردن علایق خود، کشف استعدادهای منحصر به فرد خود، ریسک کردن صحیح و آمادگی برای یادگیری، خود را دائماً از کار خود تحریک و راضی خواهید دید.</p>', '2016-11-02 00:00:00', 4, 94, 'https://images.blinkist.io/images/books/58130c78f70d8c00030942b6/1_1/470.jpg', '/en/books/disrupt-yourself-en/purchase', 'خودت-را-مختل-کن', '2023-01-27 02:01:13.230936', '2023-01-27 02:01:13.230936', NULL, 'Disrupt Yourself');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1234, 'توییتر یک استراتژی نیست', 'کشف مجدد هنر بازاریابی برند', 'کشف مجدد هنر بازاریابی برند', 12, 6, 'book', 'f', '<p><em>تویتر یک استراتژی نیست</em> با تشریح اصول اصلی که پایه و اساس یک برند شرکتی موفق را تشکیل می‌دهند، به‌هم ریختگی هشتگ‌ها و کنترل‌ها را برای رسیدن به هدف بازاریابی مؤثر کاهش می‌دهد. اگرچه رسانه‌های اجتماعی بسیار محبوب هستند، اما این کتاب نشان می‌دهد که بازاریابی سنتی هنوز اهمیت دارد و راز موفقیت - همانطور که همیشه بوده - داشتن یک ایده خوب برای برند است.</p>', '2014-12-12 00:00:00', NULL, 9, 'https://images.blinkist.io/images/books/548627a36331620009f50000/1_1/470.jpg', '/en/books/twitter-is-not-a-strategy-en/purchase', 'توییتر-یک-استراتژی-نیست', '2023-01-27 01:58:41.518957', '2023-01-27 01:58:41.518957', NULL, 'Twitter Is Not A Strategy');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1235, 'هویج و چوب', 'قدرت مشوق ها برای انجام کارها را باز کنید', 'قدرت مشوق ها برای انجام کارها را باز کنید', 16, 8, 'book', 't', '<p><em>هویج و چوب</em> (2010) کتاب مقدس رفتار، مشوق ها و خودکنترلی است. این پلک ها توضیح می دهند که چگونه می توانید عادت های بد را با پاداش ها، تنبیه ها و تعهدات رسمی نسبت به خود عوض کنید. مهارت های لازم برای مقابله با چالش هایی مانند کاهش وزن، ترک سیگار و پس انداز برای دوران بازنشستگی را به دست خواهید آورد.</p>', '2015-08-17 00:00:00', 4, 23, 'https://images.blinkist.io/images/books/55d0f510688f670009000016/1_1/470.jpg', '/en/books/carrots-and-sticks-en/purchase', 'هویج-و-چوب', '2023-01-27 01:58:46.732061', '2023-01-27 01:58:46.732061', NULL, 'Carrots and Sticks');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1236, 'گلوله برفی', 'وارن بافت و تجارت زندگی', 'وارن بافت و تجارت زندگی', 32, 14, 'book', 't', '<p><em>"در یازده سالگی او 120 دلار پس انداز کرده بود، که در سال 1941 پول زیادی بود. او از این پول برای انجام اولین سرمایه گذاری خود استفاده کرد. او شش سهم از شرکت Cities Service Preferred خرید - سه سهم برای او و سه نفر برای خواهرش دوریس."</em></p>
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1237, 'چالش رهبری', 'چگونه اتفاقات خارق العاده ای در سازمان ها رخ دهد؟', 'چگونه اتفاقات خارق العاده ای در سازمان ها رخ دهد؟', 24, 11, 'book', 't', '<p>در <em>رهبری</em> <em>چالش</em>، جیمز کوزز و بری پوزنر توضیح می‌دهند که چگونه هر کسی می‌تواند رهبر بهتری شود. نویسندگان با ذکر مثال‌های مختلف از تجربه 25 ساله و تحقیقات گسترده خود، نظریه‌های خود را در مورد آنچه یک رهبر موفق می‌سازد، ارائه می‌کنند و توصیه‌های عملی در مورد چگونگی یادگیری رفتار رهبری خوب ارائه می‌کنند.</p>', '2014-08-26 00:00:00', 4, 80, 'https://images.blinkist.io/images/books/53fd9dac37626200082a0000/1_1/470.jpg', '/en/books/the-leadership-challenge-en/purchase', 'چالش-رهبری', '2023-01-27 01:58:59.904996', '2023-01-27 01:58:59.904996', NULL, 'The Leadership Challenge');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1238, 'شکل دهنده ها', 'روش کار را دوباره ابداع کنید و آینده را تغییر دهید', 'روش کار را دوباره ابداع کنید و آینده را تغییر دهید', 17, 6, 'book', 't', '<p><em>Shapers </em>(2020) شرح می دهد که چگونه تغییرات تکنولوژیکی و سازمانی محل کار ما را متحول کرده است. مهم‌تر از همه، شایستگی‌های کلیدی را که سازمان‌ها و کارگران مدرن باید توسعه دهند تا در دنیای عدم اطمینان و اختلال رشد کنند، مشخص می‌کند.</p>', '2021-10-09 00:00:00', 5, 34, 'https://images.blinkist.io/images/books/615d9c486cee070007a2c63d/1_1/470.jpg', '/en/books/shapers-en/purchase', 'شکل-دهنده-ها', '2023-01-27 01:59:07.724591', '2023-01-27 01:59:07.724591', NULL, 'Shapers');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1239, '21 روز تا یک ایده بزرگ', 'ایجاد مفاهیم موفقیت آمیز کسب و کار', 'ایجاد مفاهیم موفقیت آمیز کسب و کار', 15, 7, 'book', 't', '<p><em>21 روز تا یک ایده بزرگ</em> (2015) راهنمای شما برای احیای مجدد خلاقیت بازیگوش و کشف ایده های درخشان بی شماری است که مغز شما قادر به تولید آن است. این پلک‌ها اسرار تکنیک‌های ساده و در عین حال مؤثر را به اشتراک می‌گذارند تا خلاقیت‌های شما را به جریان بیاندازند، و نکات مفیدی برای تبدیل ایده‌های وحشیانه شما به یک کسب‌وکار قابل اجرا ارائه می‌دهند.</p>', '2016-11-03 00:00:00', 4, 142, 'https://images.blinkist.io/images/books/581745419907fc0003a25fed/1_1/470.jpg', '/en/books/21-days-to-a-big-idea-en/purchase', '21-روز-تا-یک-ایده-بزرگ', '2023-01-27 01:59:15.4681', '2023-01-27 01:59:15.4681', NULL, '21 Days to a Big Idea');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1240, 'میکرواستری', 'کوچک بیاموزید، سریع بیاموزید و پتانسیل خود را برای دستیابی به هر چیزی باز کنید', 'کوچک بیاموزید، سریع بیاموزید و پتانسیل خود را برای دستیابی به هر چیزی باز کنید', 16, 6, 'book', 't', '<p><em>Micromastery</em> (2017) به شما می آموزد که چگونه به طور موثر یک مهارت جدید را با رویکردی متمرکز و تدریجی بیاموزید. با راهنمایی‌ها و توصیه‌های مفید و کاربردی، تمام مراحلی را که باید برای اطمینان از موفقیت شما در هر کاری که انجام می‌دهید، انجام دهید، تشریح می‌کند.</p>', '2018-08-16 00:00:00', 3, 88, 'https://images.blinkist.io/images/books/5b740e73b238e100065e1afd/1_1/470.jpg', '/en/books/micromastery-en/purchase', 'میکرواستری', '2023-01-27 01:59:23.518887', '2023-01-27 01:59:23.518887', NULL, 'Micromastery');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1241, 'اقتصاد وجدان', 'چگونه یک جنبش توده ای برای خیر برای تجارت عالی است', 'چگونه یک جنبش توده ای برای خیر برای تجارت عالی است', 13, 7, 'book', 'f', '<p><em>اقتصاد وجدان </em>(2014) پیامدهایی را که دنیای در حال تغییر و بیش از حد به هم پیوسته ما برای کسب‌وکارها و برندها دارد، آشکار می‌کند. این پلک‌ها شما را از طریق اصول و استراتژی‌هایی راهنمایی می‌کنند که برای هر شرکتی که امیدوار است مشتریان صریح و باهوش را در قلب فرهنگ وجدان امروزی به دست آورد، حیاتی است.</p>', '2016-02-02 00:00:00', NULL, 4, 'https://images.blinkist.io/images/books/56afb2f1377c1600070000e1/1_1/470.jpg', '/en/books/the-conscience-economy-en/purchase', 'اقتصاد-وجدان', '2023-01-27 01:59:31.298275', '2023-01-27 01:59:31.298275', NULL, 'The Conscience Economy');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1242, 'کلماتی که کار می کنند', 'این چیزی نیست که شما می گویید، چیزی است که مردم می شنوند', 'این چیزی نیست که شما می گویید، چیزی است که مردم می شنوند', 19, 7, 'book', 't', '<p><em>Words That Work</em> (2007) راهنمایی برای رساندن کارآمدتر و موثرتر نظرتان است. این پلک‌ها قدرت زبان را توضیح می‌دهند و این که چگونه می‌تواند به شما در موقعیت‌های مختلف، از تجارت گرفته تا بحث‌های سیاسی و خروج از بلیط ترافیک، کمک کند.</p>', '2016-04-27 00:00:00', 4, 113, 'https://images.blinkist.io/images/books/5717a6973f35690007554e42/1_1/470.jpg', '/en/books/words-that-work-en/purchase', 'کلماتی-که-کار-می-کنند', '2023-01-27 01:59:38.658694', '2023-01-27 01:59:38.658694', NULL, 'Words That Work');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1243, 'تست مادر', 'وقتی همه به شما دروغ می گویند چگونه با مشتریان صحبت کنید و بیاموزید که آیا کسب و کار شما ایده خوبی است؟', 'وقتی همه به شما دروغ می گویند چگونه با مشتریان صحبت کنید و بیاموزید که آیا کسب و کار شما ایده خوبی است؟', 8, 4, 'book', 't', '<p>دو نوع مکالمه مهمی که هنگام تأسیس یک کسب و کار خواهید داشت، گفتگوهایی با مشتریان بالقوه و گفتگوهایی با سرمایه گذاران بالقوه است. <em>آزمون مادر</em> (2013) توصیه هایی را در مورد شناسایی اطلاعاتی که <em>واقعاً</em> نیاز دارید از این جلسات ارائه می دهد و اطمینان حاصل می کند که کسب و کار شما بهترین پایه ممکن برای موفقیت را دارد.</p>', '2016-02-04 00:00:00', 4, 130, 'https://images.blinkist.io/images/books/56afa9ca377c160007000078/1_1/470.jpg', '/en/books/the-mom-test-en/purchase', 'تست-مادر', '2023-01-27 01:59:46.425372', '2023-01-27 01:59:46.425372', NULL, 'The Mom Test');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1244, 'فروشگاه همه چیز', 'جف بزوس و عصر آمازون', 'جف بزوس و عصر آمازون', 20, 9, 'book', 't', '<p> علیرغم اینکه آمازون امروزه یک شرکت میلیارد دلاری است، با شروعی ساده در گاراژ جف بزوس ساخته شد. از همان ابتدا، بزوس توسط چشم انداز بزرگ ایجاد یک <em>فروشگاه همه چیز</em> هدایت شد - که در این بین، عملاً محقق شد. این کتاب با تمرکز یکسان بر شرکت و موسس آن، نشان می دهد که او چگونه رویای خود را به واقعیت تبدیل کرد.</p>
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1245, '#کار خود را ارتقا دهید', 'راه هوشمند برای ایجاد تعادل بین زندگی خانوادگی و شغلی', 'راه هوشمند برای ایجاد تعادل بین زندگی خانوادگی و شغلی', 21, 7, 'book', 't', '<p><em>#Upcycle Your Job</em>(2019)<em> </em>رویکردی شش مرحله ای برای یافتن تعادل کامل بین کار و زندگی ارائه می دهد. اگرچه این روش برای مادران شاغل طراحی شده است، اما هر کسی که می‌خواهد بدون فداکاری شغلی در این فرآیند بیشتر از زندگی بهره ببرد، می‌تواند از این روش استفاده کند.</p>', '2020-12-14 00:00:00', 4, 39, 'https://images.blinkist.io/images/books/5fd345396cee07000639bf45/1_1/470.jpg', '/en/books/number-upcycle-your-job-en/purchase', '#کار-خود-را-ارتقا-دهید', '2023-01-27 02:00:01.349892', '2023-01-27 02:00:01.349892', NULL, '#Upcycle Your Job');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1246, 'چه کسی نه چگونه', 'فرمول دستیابی به اهداف بزرگتر از طریق تسریع در کار تیمی', 'فرمول دستیابی به اهداف بزرگتر از طریق تسریع در کار تیمی', 21, 7, 'book', 't', '<p><em>Who Not How </em>(2020) شیوه جدیدی از تفکر در مورد کارآفرینی، تعیین هدف و همکاری را معرفی می کند. ذهنیت <em>Who Not How</em> که توسط مربی کسب و کار دن سالیوان ایجاد شده است، اهمیت واگذاری وظایف به دیگران را نشان می دهد. با دعوت از آنها برای کمک به شما در دستیابی به اهدافتان، زمان آزاد بیشتری به دست می آورید، درآمد خود را افزایش می دهید و روابط حرفه ای ارزشمند و پایدار ایجاد می کنید.</p>', '2022-01-22 00:00:00', 5, 411, 'https://images.blinkist.io/images/books/61e55c1c6cee0700098c3537/1_1/470.jpg', '/en/books/who-not-how-en/purchase', 'چه-کسی-نه-چگونه', '2023-01-27 02:00:09.092809', '2023-01-27 02:00:09.092809', NULL, 'Who Not How');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1247, 'چگونه سقوط توانا', 'و چرا برخی از شرکت ها هرگز تسلیم نمی شوند', 'و چرا برخی از شرکت ها هرگز تسلیم نمی شوند', 19, 8, 'book', 't', '<p>در <em>چگونه</em> <em></em> <em>پاییز قدرتمند</em> <em></em>، کارشناس تجاری تأثیرگذار جیم کالینز به بررسی این موضوع می‌پردازد که چگونه حتی شرکت‌های موفق می‌توانند ناگهان سقوط کنند. به خصوص اگر تصمیمات اشتباه بگیرند. او همچنین توصیه هایی به رهبران ارائه می دهد تا از انجام اشتباهات مشابه جلوگیری کنند.</p>', '2014-06-24 00:00:00', 5, 81, 'https://images.blinkist.io/images/books/53aa82d36337660007070000/1_1/470.jpg', '/en/books/how-the-mighty-fall-en/purchase', 'چگونه-سقوط-توانا', '2023-01-27 02:00:15.019275', '2023-01-27 02:00:15.019275', NULL, 'How the Mighty Fall');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1248, 'زندگی درونی حیوانات', 'عشق، اندوه، و شفقت - مشاهدات شگفت انگیز از یک دنیای پنهان', 'عشق، اندوه، و شفقت - مشاهدات شگفت انگیز از یک دنیای پنهان', 24, 11, 'book', 't', '<p>در <em>زندگی درونی حیوانات</em> (2017) پیتر وولبن آخرین تحقیقات در مورد احساسات و عواطف حیوانات را مورد بحث قرار می دهد. او بینش هایی را از مطالعات متعدد و همچنین از تجربیات شخصی خود از جنگلی که دهه ها در آن زندگی و کار کرده است به دست می آورد. این کتاب استدلال می کند که زندگی درونی حیوانات واقعاً با زندگی ما تفاوت چندانی ندارد.</p>', '2018-01-04 00:00:00', 5, 44, 'https://images.blinkist.io/images/books/5a43af49b238e10006e1ad0d/1_1/470.jpg', '/en/books/the-inner-life-of-animals-en/purchase', 'زندگی-درونی-حیوانات', '2023-01-27 02:00:22.620242', '2023-01-27 02:00:22.620242', NULL, 'The Inner Life of Animals');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1249, 'کتاب کوچکی که هنوز بازار را شکست می دهد', 'کلاسیک ادبیات مالی', 'کلاسیک ادبیات مالی', 14, 6, 'book', 't', '<p>می‌خواهید پول نقدی که به سختی به دست آورده‌اید را در چیزی سرمایه‌گذاری کنید که سود واقعی را به شما بدهد؟ نمی‌دانید چگونه می‌توان با بدبختی‌های دنیای مالی مذاکره کرد؟ <em>کتاب کوچکی که هنوز بازار را شکست می‌دهد</em> یک کتاب پرفروش <em>نیویورک تایمز</em> است که فرمول ساده‌ای را معرفی و توضیح می‌دهد که هر کسی را قادر می‌سازد بازدهی بالاتر از میانگین در بازار سهام داشته باشد.< /p>', '2015-02-05 00:00:00', 4, 138, 'https://images.blinkist.io/images/books/54cf9276323335000a6c0000/1_1/470.jpg', '/en/books/the-little-book-that-still-beats-the-market-en/purchase', 'کتاب-کوچکی-که-هنوز-بازار-را-شکست-می-دهد', '2023-01-27 02:00:30.094022', '2023-01-27 02:00:30.094022', NULL, 'The Little Book That Still Beats the Market');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1250, 'جدید به بزرگ', 'چگونه شرکت ها می توانند مانند کارآفرینان ایجاد کنند، مانند VC ها سرمایه گذاری کنند و یک سیستم عامل دائمی برای رشد نصب کنند', 'چگونه شرکت ها می توانند مانند کارآفرینان ایجاد کنند، مانند VC ها سرمایه گذاری کنند و یک سیستم عامل دائمی برای رشد نصب کنند', 22, 8, 'book', 't', '<p><em>New to Big</em> (2019) نشان می‌دهد که چگونه شرکت‌های معتبر می‌توانند یک مدل رشد فوق‌العاده را در قلب شرکت خود نصب کنند. با اتخاذ ساختار استارت‌آپ‌های جدید یا کارآفرینانی که برای اولین بار کار می‌کنند، می‌توانند از رکود جلوگیری کنند، استعداد خلاق خود را دوباره شعله‌ور کنند و برای حل مشکلات آینده نوآوری کنند.</p>', '2019-07-02 00:00:00', 5, 63, 'https://images.blinkist.io/images/books/5d17d62e6cee070007ea1000/1_1/470.jpg', '/en/books/new-to-big-en/purchase', 'جدید-به-بزرگ', '2023-01-27 02:00:38.356489', '2023-01-27 02:00:38.356489', NULL, 'New to Big');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1251, 'همه چیز به هم ریخته است', 'کتابی درباره امید', 'کتابی درباره امید', 23, 8, 'book', 't', '<p><em>همه چیز شکست خورده است</em> (2019) نگاهی است بدون محدودیت به وضعیت انسان مدرن و اینکه چرا بسیاری احساس می کنند که وضعیت جهان بسیار بدتر از آن چیزی است که واقعاً وجود دارد. است. نویسنده مارک منسون به ستون‌های فلسفه بشری، از جمله امانوئل کانت و فردریش نیچه نگاه می‌کند تا نشان دهد که چگونه تله‌های جامعه مدرن و مفاهیمی مانند امید، مردم را بر روی چیزهای اشتباه در زندگی متمرکز کرده است.</p>', '2019-05-14 00:00:00', 4, 667, 'https://images.blinkist.io/images/books/5cd6a6126cee070008f573a9/1_1/470.jpg', '/en/books/everything-is-f-star-cked-en/purchase', 'همه-چیز-به-هم-ریخته-است', '2023-01-27 02:00:43.790235', '2023-01-27 02:00:43.790235', NULL, 'Everything is F*cked');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1252, 'کتاب انسانها', 'تاریخچه مختصری از فرهنگ، جنسیت، جنگ و تکامل ما', 'تاریخچه مختصری از فرهنگ، جنسیت، جنگ و تکامل ما', 21, 7, 'book', 't', '<p><em>کتاب انسانها </em>(2018) یک تور قابل دسترسی از تاریخ تکامل است. هم ویژگی‌های بسیاری را که با حیوانات به اشتراک می‌گذاریم و هم ویژگی‌های بسیاری را که ما را متمایز می‌کنند، روشن می‌کند. با ترکیب آخرین اکتشافات علمی از ژنتیک و باستان شناسی، خلاصه ای هیجان انگیز از تنوع غنی حیات روی زمین ارائه می دهد.</p>', '2020-12-23 00:00:00', 4, 174, 'https://images.blinkist.io/images/books/5fda3a5b6cee070007356fc8/1_1/470.jpg', '/en/books/the-book-of-humans-en/purchase', 'کتاب-انسانها', '2023-01-27 02:00:52.453188', '2023-01-27 02:00:52.453188', NULL, 'The Book of Humans');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1253, 'یادگیری اهرمی', 'چگونه اختلال در آموزش به یادگیرندگان مادام العمر و کارشناسان کمک می کند تا چیزی برای آموزش داشته باشند', 'چگونه اختلال در آموزش به یادگیرندگان مادام العمر و کارشناسان کمک می کند تا چیزی برای آموزش داشته باشند', 29, 8, 'book', 't', '<p><em>Leveraged Learning</em> (2018) یک فرآیند شش مرحله ای را برای طراحی و اجرای یک روش بهینه یادگیری یا آموزش هر موضوعی ارائه می دهد. با تکیه بر پیشرفت‌های اخیر در زمینه آموزش، درس‌های آن به همان اندازه برای کسانی که دوره‌های تحصیلی سنتی، جدید یا خودآموز را دنبال می‌کنند - صرف نظر از اینکه هدف پیشرفت شخصی، حرفه‌ای یا تحصیلی باشد، قابل استفاده است. </p>', '2021-05-31 00:00:00', 4, 78, 'https://images.blinkist.io/images/books/60ae77136cee0700084a2c50/1_1/470.jpg', '/en/books/leveraged-learning-en/purchase', 'یادگیری-اهرمی', '2023-01-27 02:01:00.096952', '2023-01-27 02:01:00.096952', NULL, 'Leveraged Learning');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1254, 'جبر خوشبختی', 'یادداشت هایی در مورد پیگیری موفقیت، عشق و معنا', 'یادداشت هایی در مورد پیگیری موفقیت، عشق و معنا', 23, 8, 'book', 't', '<p><em>جبر خوشبختی </em>(2019) برخی از مهم ترین متغیرهای دخیل در زندگی پر از معنا، عشق و موفقیت را بیان می کند. سپس طیف گسترده ای از نکات و اصول عملی را در مورد نحوه هدایت تنش ها و مبادلات موجود در ایجاد تعادل بین این متغیرها در برابر یکدیگر ارائه می دهد.</p>', '2019-06-14 00:00:00', 4, 233, 'https://images.blinkist.io/images/books/5d00f9da6cee070007f40d39/1_1/470.jpg', '/en/books/the-algebra-of-happiness-en/purchase', 'جبر-خوشبختی', '2023-01-27 02:01:05.263886', '2023-01-27 02:01:05.263886', NULL, 'The Algebra of Happiness');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1256, 'بهتر از آلفا', 'سه گام برای به دست آوردن سود اضافی در دنیایی در حال تغییر', 'سه گام برای به دست آوردن سود اضافی در دنیایی در حال تغییر', 24, 7, 'book', 't', '<p><em>بهتر از آلفا </em>(2021) سرمایه‌گذاران را تشویق می‌کند تا وسواس خود را نسبت به آلفا رها کنند - مقداری که یک سرمایه‌گذاری در مقایسه با شاخص بازار بازگشت داده است. این بررسی می‌کند که واقعاً چه چیزی باعث بازدهی می‌شود، بنابراین می‌توانید یک سبد موفق بسازید و به جای تعقیب رنگین کمان، به اهداف سرمایه‌گذاری خود برسید.</p>', '2021-10-21 00:00:00', 4, 56, 'https://images.blinkist.io/images/books/6168168a6cee0700089d6aa0/1_1/470.jpg', '/en/books/better-than-alpha-en/purchase', 'بهتر-از-آلفا', '2023-01-27 02:01:21.382496', '2023-01-27 02:01:21.382496', NULL, 'Better than Alpha');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1257, 'کسب و کار زیست محیطی', 'تصاحب پایداری با برند بزرگ', 'تصاحب پایداری با برند بزرگ', 12, 6, 'book', 'f', '<p><em>Eco-Business</em> (2013) ابتکارات پایداری شرکت را باز می کند تا یک مدل کسب و کار را آشکار کند که ارتباط بسیار بیشتری با سود و سهم بازار دارد تا محیط زیست گرایی جدی. ابزارها و تاکتیک های شرح داده شده در این چشمک ها به کسب و کارها این امکان را می دهد که هزینه ها را کاهش دهند و سود را به حداکثر برسانند، همه اینها به نام محیط زیست. با این حال، از طریق همکاری شرکت‌ها با دولت‌ها و سازمان‌های غیردولتی، برخی از ابتکارات زیست محیطی شرکت‌ها در واقع می‌توانند تأثیر مثبتی بر محیط‌زیست داشته باشند.</p>', '2015-06-01 00:00:00', 5, 15, 'https://images.blinkist.io/images/books/556c57be3236630007110000/1_1/470.jpg', '/en/books/eco-business-en/purchase', 'کسب-و-کار-زیست-محیطی', '2023-01-27 02:01:29.458233', '2023-01-27 02:01:29.458233', NULL, 'Eco-Business');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1258, 'بازاریابی فیس بوک', 'راهنمای گام به گام نتایج تضمین شده', 'راهنمای گام به گام نتایج تضمین شده', 14, 6, 'book', 't', '<p><em>بازاریابی فیس‌بوک</em> (2014) راهنمای جامعی درباره این موضوع است که هم اصول اولیه مانند ایجاد تبلیغات ساده و هم تکنیک‌های پیشرفته کاربر قدرتمند مانند ایجاد مخاطبین سفارشی را پوشش می‌دهد.</p>', '2015-04-06 00:00:00', 4, 52, 'https://images.blinkist.io/images/books/552239f23832370007000000/1_1/470.jpg', '/en/books/facebook-marketing-en/purchase', 'بازاریابی-فیس-بوک', '2023-01-27 02:01:37.806619', '2023-01-27 02:01:37.806619', NULL, 'Facebook Marketing');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1259, 'ارائه شادی', 'راهی به سوی سود، اشتیاق و هدف', 'راهی به سوی سود، اشتیاق و هدف', 11, 7, 'book', 't', '<p>موضوع اصلی کتاب، کسب و کار به معنای واقعی کلمه ارائه شادی و در عین حال داشتن یک زندگی پرشور و هدف است. <em>ارائه شادی</em> (2013) داستان تونی هسیه و شرکتش Zappos را روایت می‌کند و نشان می‌دهد که چگونه فکر کردن طولانی‌مدت و پیروی از علایق شما نه تنها می‌تواند منجر به سود شود، بلکه زندگی شادی را برای کارکنان و مشتریان شما به همراه دارد. ، و خودتان. این کتاب یک رویکرد جایگزین برای فرهنگ شرکتی را توصیف می‌کند که بر مفهوم ساده شاد کردن افراد اطرافتان و با انجام این کار افزایش شادی خود تمرکز دارد.</p>', '2013-01-01 00:00:00', 4, 93, 'https://images.blinkist.io/images/books/50f4086ae4b0627d64b97abf/1_1/470.jpg', '/en/books/delivering-happiness-en/purchase', 'ارائه-شادی', '2023-01-27 02:01:46.293371', '2023-01-27 02:01:46.293371', NULL, 'Delivering Happiness');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1260, 'برخیز، بیدار', 'داستان‌های الهام‌بخش کارآفرینان جوانی که از کالج فارغ‌التحصیل شده‌اند و به کسب‌وکار خودشان تبدیل شده‌اند.', 'داستان‌های الهام‌بخش کارآفرینان جوانی که از کالج فارغ‌التحصیل شده‌اند و به کسب‌وکار خودشان تبدیل شده‌اند.', 18, 6, 'book', 't', '<p><em>برخیز، بیدار</em> (2015) خوانندگان را با برخی از الهام بخش ترین کارآفرینان آینده و آینده هند آشنا می کند. این اسلحه‌های جوان که از طیف گسترده‌ای از زمینه‌های مختلف تحصیلی و جغرافیایی استخراج شده‌اند، خود را در صنایع مختلفی مانند بخش ساخت‌وساز، مسکن دانشجویی و فست‌فود تثبیت کرده‌اند. وجه اشتراک آنها؟ آنها به جای اینکه منتظر فرصت عالی برای افتادن در دامان خود باشند، اوضاع را به دست خود گرفتند.</p>', '2019-05-23 00:00:00', 4, 42, 'https://images.blinkist.io/images/books/5ce50ad66cee0700086aaf90/1_1/470.jpg', '/en/books/arise-awake-en/purchase', 'برخیز،-بیدار', '2023-01-27 02:01:53.996153', '2023-01-27 02:01:53.996153', NULL, 'Arise, Awake');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1261, 'چگونه یک قلب شکسته را تعمیر کنیم', 'کمک به دل شکستگان', 'کمک به دل شکستگان', 15, 5, 'book', 't', '<p><em>چگونه یک قلب شکسته را تعمیر کنیم </em>(۲۰۱۸) پیام امیدی است خطاب به دل شکسته ها و غم زده ها. گای وینچ به خوانندگانش یادآوری می کند که زمان ممکن است شفا دهنده عالی باشد، اما این بدان معنا نیست که نمی توانید روند بهبودی را تسریع کنید. از نظر روانشناسی نافذ و بر اساس آخرین تحقیقات علمی، این کتابچه راهنمای عاشقان شما را در کمترین زمان ممکن روی پاهای خود خواهد دید.</p>', '2018-09-06 00:00:00', 4, 96, 'https://images.blinkist.io/images/books/5b8f8b39b238e10007eeca22/1_1/470.jpg', '/en/books/how-to-fix-a-broken-heart-en/purchase', 'چگونه-یک-قلب-شکسته-را-تعمیر-کنیم', '2023-01-27 02:02:01.987665', '2023-01-27 02:02:01.987665', NULL, 'How to Fix a Broken Heart');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1262, 'راه اندازی مجدد', 'رهبری و هنر بزرگ شدن', 'رهبری و هنر بزرگ شدن', 22, 8, 'book', 't', '<p><em>راه‌اندازی مجدد </em> (۲۰۱۹) به ما نشان می‌دهد که برای تبدیل شدن به رهبران بهتر، ابتدا باید انسان‌های بهتری شویم. جری کولونا از طریق فرآیند خودکاوشی رادیکال از ما می‌خواهد تا عمیقاً در مورد همه چیزهایی که ما را شکل داده و بر رفتار حرفه‌ای ما تأثیر می‌گذارند تأمل کنیم. او با اقتباس از تجربیات شخصی خام، ما را به سمت شکلی ریشه‌دارتر و انسانی‌تر از رهبری هدایت می‌کند.</p>', '2019-08-02 00:00:00', 4, 64, 'https://images.blinkist.io/images/books/5d4150c76cee07000859d594/1_1/470.jpg', '/en/books/reboot-en/purchase', 'راه-اندازی-مجدد', '2023-01-27 02:02:09.495216', '2023-01-27 02:02:09.495216', NULL, 'Reboot');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1263, 'کد انگیزه', 'نیروهای پنهانی که بهترین کار شما را هدایت می کنند را کشف کنید', 'نیروهای پنهانی که بهترین کار شما را هدایت می کنند را کشف کنید', 20, 7, 'book', 't', '<p><em>کد انگیزه </em>(2020) انواع مختلف انگیزه های درونی را بررسی می کند و <em>چرا</em> ما به روشی که انجام می دهیم رفتار می کنیم. این پلک‌ها با بینش‌هایی درباره خواسته‌ها و نیازهای منحصربه‌فرد ما، بخش گمشده پازل شخصیت را نشان می‌دهند.</p>', '2021-01-06 00:00:00', 4, 131, 'https://images.blinkist.io/images/books/5fdb1d6f6cee07000670b015/1_1/470.jpg', '/en/books/the-motivation-code-en/purchase', 'کد-انگیزه', '2023-01-27 02:02:19.673006', '2023-01-27 02:02:19.673006', NULL, 'The Motivation Code');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1264, 'سرویس افسانه ای', 'کلید مراقبت است', 'کلید مراقبت است', 14, 6, 'book', 't', '<p><em>سرویس افسانه ای</em> (2014) اصول خدمات عالی را تشریح می کند و نحوه پیاده سازی آنها را در شرکت خود شرح می دهد. از آنجایی که تعامل با مشتریان یک عنصر کلیدی تقریباً در هر کسب و کاری است، پیروی از این مدل راهی مطمئن برای بهبود عملکرد کلی شرکت شما است.</p>', '2015-04-02 00:00:00', 4, 21, 'https://images.blinkist.io/images/books/5518a2ea3961320007ba0000/1_1/470.jpg', '/en/books/legendary-service-en/purchase', 'سرویس-افسانه-ای', '2023-01-27 02:02:26.763257', '2023-01-27 02:02:26.763257', NULL, 'Legendary Service');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1265, 'چرا رژیم ها ما را چاق می کنند', 'عواقب ناخواسته وسواس ما با کاهش وزن', 'عواقب ناخواسته وسواس ما با کاهش وزن', 18, 7, 'book', 't', '<p>چرا رژیم‌ها ما را چاق می‌کنند (2016) بسیاری از افسانه‌های رایج در مورد رژیم‌ها و رابطه بین وزن و سلامتی را از بین می‌برد. این پلک‌ها علم پشت این ادعاها را بررسی می‌کنند که رژیم غذایی کارساز نیست و برای افرادی که می‌خواهند چند پوند وزن کم کنند و سالم‌تر زندگی کنند، جایگزین‌هایی ارائه می‌دهد.</p>', '2017-01-04 00:00:00', 4, 100, 'https://images.blinkist.io/images/books/5852ce2458b1350004ed16fa/1_1/470.jpg', '/en/books/why-diets-make-us-fat-en/purchase', 'چرا-رژیم-ها-ما-را-چاق-می-کنند', '2023-01-27 02:02:34.81296', '2023-01-27 02:02:34.81296', NULL, 'Why Diets Make Us Fat');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1266, 'تاریخچه شخصی', 'داستان قابل توجه بانوی برجسته آمریکایی را کشف کنید', 'داستان قابل توجه بانوی برجسته آمریکایی را کشف کنید', 27, 10, 'book', 't', '<p>زندگی نامه کاترین گراهام <em>تاریخ شخصی</em> (1997) داستان درونی روشنگر یکی از قدرتمندترین غول های رسانه ای ایالات متحده است. این خاطرات برنده جایزه پولیتزر با شروع دوران کودکی دشوار او، که توسط مادر سخت‌کوش و باهوشش شکل گرفته بود، نوری را روشن می‌کند که گراهام را در ردیف‌های حرفه روزنامه‌نگاری، تا بالای <em>واشنگتن پست قرار می‌دهد. سلسله مراتب </em>.</p>', '2018-05-31 00:00:00', 5, 12, 'https://images.blinkist.io/images/books/5b0c0a5bb238e100069695bf/1_1/470.jpg', '/en/books/personal-history-en/purchase', 'تاریخچه-شخصی', '2023-01-27 02:02:42.504308', '2023-01-27 02:02:42.504308', NULL, 'Personal History');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1267, 'برهنه شدن', 'افسانه ای تجاری درباره از بین بردن سه ترسی که وفاداری مشتری را خراب می کند', 'افسانه ای تجاری درباره از بین بردن سه ترسی که وفاداری مشتری را خراب می کند', 9, 4, 'book', 't', '<p><em>برهنه شدن</em> (2010) درباره آسیب پذیری و قدرت باورنکردنی آن است. این پلک ها چگونگی ایجاد اعتماد با مشتریان و غلبه بر سه ترس رایجی که مانع از نشان دادن آسیب پذیری واقعی شما می شوند را توضیح می دهد.</p>', '2017-07-18 00:00:00', 4, 33, 'https://images.blinkist.io/images/books/596b2882b238e1000601886d/1_1/470.jpg', '/en/books/getting-naked-en/purchase', 'برهنه-شدن', '2023-01-27 02:02:47.808828', '2023-01-27 02:02:47.808828', NULL, 'Getting Naked');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1268, 'فرهنگ را تغییر دهید، بازی را تغییر دهید', 'استراتژی موفقیت آمیز برای انرژی بخشیدن به سازمان شما و ایجاد پاسخگویی برای نتایج', 'استراتژی موفقیت آمیز برای انرژی بخشیدن به سازمان شما و ایجاد پاسخگویی برای نتایج', 14, 6, 'book', 't', '<p><em>تغییر فرهنگ، تغییر بازی</em> (2012) نشان می دهد که چگونه فرهنگ مسئولیت پذیری را در سازمان خود پیاده سازی کنید. خواهید فهمید که چگونه می توانید به تشویق تغییر در تفکر برای به دست آوردن نتایج تغییردهنده بازی که می خواهید کمک کنید و مراحل لازم برای حفظ چنین تغییراتی را بررسی کنید.</p>', '2015-06-01 00:00:00', 4, 129, 'https://images.blinkist.io/images/books/55000313646439000a020000/1_1/470.jpg', '/en/books/change-the-culture-change-the-game-en/purchase', 'فرهنگ-را-تغییر-دهید،-بازی-را-تغییر-دهید', '2023-01-27 02:02:55.677188', '2023-01-27 02:02:55.677188', NULL, 'Change the Culture, Change the Game');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1269, 'زیر شکم', 'داستان وسواسی موریانه ها و فناوری', 'داستان وسواسی موریانه ها و فناوری', 23, 7, 'book', 't', '<p><em>Underbug </em>(2018) دنیای شگفت‌انگیز حشره‌ای را بررسی می‌کند که آن‌قدر دوست‌داشتنی نیست که ممکن است سوسک‌ها را در مسابقه‌ای با نامحبوبیت شکست دهد - موریانه. نتیجه سال‌ها تحقیق و مصاحبه با زیست‌شناسان، حشره‌شناسان و ژنتیک‌دانان، مطالعه لیزا مارگونلی برای نجات شهرت این موجود نادیده گرفته شده است. در طول مسیر، او به بررسی قدرت‌های معماری قابل توجه موریانه‌ها می‌پردازد، رابطه عجیب آن‌ها را با یک قارچ ۲۵۰ میلیون ساله باز می‌کند و نشان می‌دهد که چگونه میکروب‌های موجود در روده‌های آن‌ها ممکن است به ما در ایجاد آینده‌ای پایدارتر کمک کنند. </p>', '2020-01-23 00:00:00', 5, 19, 'https://images.blinkist.io/images/books/5e26fce16cee07000686ae10/1_1/470.jpg', '/en/books/underbug-en/purchase', 'زیر-شکم', '2023-01-27 02:03:03.703824', '2023-01-27 02:03:03.703824', NULL, 'Underbug');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1270, 'Radical Candor (نسخه جدید)', 'بدون از دست دادن انسانیت خود یک رئیس Kickass باشید', 'بدون از دست دادن انسانیت خود یک رئیس Kickass باشید', 29, 7, 'book', 't', '<p><em>رادیکال صراحت </em>(2017) یک نقشه راه برای رهبرانی است که به دنبال ایجاد بهترین رابطه ممکن با کارمندان خود هستند. رویکرد بینش‌گر آن به مدیریت نشان می‌دهد که چگونه می‌توان یک محیط کاری ایجاد کرد که در آن ایده‌های عالی ظهور کنند، افراد به پتانسیل کامل خود دست یابند و کارمندان به پیروی از رئیس خود افتخار کنند.</p>', '2022-07-06 00:00:00', 5, 229, 'https://images.blinkist.io/images/books/62bda6066cee0700092f20b4/1_1/470.jpg', '/en/books/radical-candor-new-version-en/purchase', 'Radical-Candor-(نسخه-جدید)', '2023-01-27 02:03:11.353594', '2023-01-27 02:03:11.353594', NULL, 'Radical Candor (New Version)');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1271, 'قدرت مثبت اندیشی', 'مثبت فکر کنید و به آنچه می خواهید برسید', 'مثبت فکر کنید و به آنچه می خواهید برسید', 19, 10, 'book', 't', '<p><em></em> <em>قدرت</em> <em></em> <em>مثبت</em> <em>تفکر</em> یک کتابچه راهنمای خود اعلام شده برای رسیدن به شادی و غلبه بر سخت ترین مشکلات. این کتاب با تمرکز بر نگرش ما نسبت به موقعیت های زندگی و همچنین ایمان ما، به عنوان راهنمای روشی عمل می کند که چگونه می توانیم زندگی خود را از طریق تمرکز ثابت بر نتایج مثبت تغییر دهیم - اگر مایل به انجام آن انتخاب باشیم.</p>', '2014-06-24 00:00:00', 4, 199, 'https://images.blinkist.io/images/books/53a9d57c66656300071c0000/1_1/470.jpg', '/en/books/the-power-of-positive-thinking-en/purchase', 'قدرت-مثبت-اندیشی', '2023-01-27 02:03:18.872295', '2023-01-27 02:03:18.872295', NULL, 'The Power of Positive Thinking');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1272, 'انجام کارها', 'هنر بهره وری بدون استرس', 'هنر بهره وری بدون استرس', 22, 13, 'book', 'f', '<p>در <em>Getting Things Done</em>(2001)، دیوید آلن سیستم معروف خود را برای بهره وری بدون استرس معرفی می کند. با استفاده از این سیستم، می‌توانید با تعداد زیادی از کارهایی که باید انجام دهید، روبرو شوید، اما همچنان سازنده، خلاق و آرام باشید.</p>
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1273, 'گذراندن زمستان', 'قدرت استراحت و عقب نشینی در زمان های سخت', 'قدرت استراحت و عقب نشینی در زمان های سخت', 20, 8, 'book', 't', '<p><em>زمستان </em>(2020) شرح قانع‌کننده‌ای است از این که چگونه کاترین می، نویسنده یاد گرفت که با روی آوردن به درس‌های زمستان، فصلی تلخ و خشن در زندگی خود را در آغوش بگیرد. از سونا گرفته تا شنا در زمستان سرد، گرگ‌ها تا انقلاب زمستانی، ماه می به این موضوع می‌پردازد که چگونه حیوانات، گیاهان و فرهنگ‌ها در طول تاریخ در تاریک‌ترین زمان سال زنده مانده‌اند و حتی شکوفا شده‌اند.</p>', '2021-03-01 00:00:00', 4, 68, 'https://images.blinkist.io/images/books/6038c9a46cee07000751a764/1_1/470.jpg', '/en/books/wintering-en/purchase', 'گذراندن-زمستان', '2023-01-27 02:03:32.967743', '2023-01-27 02:03:32.967743', NULL, 'Wintering');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1274, 'درخت درهم', 'تاریخچه رادیکال جدید زندگی', 'تاریخچه رادیکال جدید زندگی', 22, 8, 'book', 't', '<p><em>درخت درهم </em>(۲۰۱۸) به خوانندگان کنجکاو خلاصه‌ای حیاتی از پیچش‌ها و چرخش‌های علمی زیادی که از زمان چارلز داروین در درک ما از تکامل رخ داده است، ارائه می‌کند. توضیحات روشن نویسنده دیوید کوامن شما را با تمام آنچه که ما می دانیم و نمی دانیم در مورد چگونگی شکل گیری حیات در سیاره زمین سریع آشنا می کند.</p>', '2018-09-21 00:00:00', 5, 27, 'https://images.blinkist.io/images/books/5ba215ac862c430007e4945d/1_1/470.jpg', '/en/books/the-tangled-tree-en/purchase', 'درخت-درهم', '2023-01-27 02:03:40.890315', '2023-01-27 02:03:40.890315', NULL, 'The Tangled Tree');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1275, 'قدرت No', 'زیرا یک کلمه کوچک می تواند سلامتی، شادی و فراوانی به ارمغان بیاورد', 'زیرا یک کلمه کوچک می تواند سلامتی، شادی و فراوانی به ارمغان بیاورد', 11, 4, 'book', 't', '<p><em>قدرت نه </em>(2014) رویکردی جامع و شهودی نسبت به سلامتی، فراوانی و شادی ارائه می دهد: به چیزهایی که به شما آسیب می رسانند و سرعت شما را کاهش می دهند نه بگویید تا انرژی داشته باشید. برای گفتن بله به چیزهایی که به نظر شما نشاط بخش است.</p>', '2015-05-29 00:00:00', 4, 74, 'https://images.blinkist.io/images/books/5563c3a06461640007f90000/1_1/470.jpg', '/en/books/the-power-of-no-en/purchase', 'قدرت-No', '2023-01-27 02:03:49.123447', '2023-01-27 02:03:49.123447', NULL, 'The Power of No');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1276, 'فقط پارانوئید زنده می ماند', 'آخرالزمان را به فرصت تبدیل کنید', 'آخرالزمان را به فرصت تبدیل کنید', 21, 10, 'book', 't', '<p><em>Only</em> <em></em> <em>Paranoid</em> <em>Survive</em> (1999) تجربیات و توصیه‌های ارزشمند یکی از تحسین‌شده‌ترین افراد را ارائه می‌کند. و مدیران عامل موفق زمان های اخیر: اندرو اس. گروو. در این کتاب، گرو استراتژی‌های بسیاری را پیشنهاد می‌کند که شرکت‌ها می‌توانند برای بقا – و حتی بهره‌برداری – از آنچه که او «نقاط عطف استراتژیک» می‌نامد: آن لحظات غرق شدن یا شنا کردن در وجود یک شرکت، اتخاذ کنند. این کتاب درک عمیق‌تری از روش‌های اتخاذ تصمیم‌های استراتژیک و به‌ویژه از آنچه در هدایت یک شرکت فناوری پیشرو دخیل است، در اختیار خواننده قرار می‌دهد.</p>
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1277, 'آن را به جلو تصور کنید', 'شجاعت، خلاقیت و قدرت تغییر', 'شجاعت، خلاقیت و قدرت تغییر', 19, 6, 'book', 't', '<p><em>Imagine it Forward</em> (2018) موفقیت‌ها و شکست‌های یکی از پرکارترین تاجران آمریکایی، بث کامستاک را نشان می‌دهد. این پلک‌ها با ترکیب حکایت‌های دوران تصدی او در جنرال الکتریک با بینش‌های شگفت‌انگیز و توصیه‌های عملی ضروری، زندگی و زمان‌های این تغییر‌دهنده و مبتکر برجسته را بررسی می‌کنند.</p>', '2018-11-22 00:00:00', 4, 37, 'https://images.blinkist.io/images/books/5bf41cfe6cee07000758f168/1_1/470.jpg', '/en/books/imagine-it-forward-en/purchase', 'آن-را-به-جلو-تصور-کنید', '2023-01-27 02:04:05.028607', '2023-01-27 02:04:05.028607', NULL, 'Imagine It Forward');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1278, 'تعمیرکار', 'نجات استارتاپ ها از مرگ توسط سیاست', 'نجات استارتاپ ها از مرگ توسط سیاست', 28, 9, 'book', 't', '<p><em>The Fixer </em>(2018) داستان ماجراجویی های یک استراتژیست سیاسی در سیاست و تجارت است. بردلی تاسک پیش از راه‌اندازی مشاوره خود برای مشاوره به استارت‌آپ‌ها، در حین مشاوره با برخی از بزرگ‌ترین نام‌های سیاست آمریکا، یاد می‌گیرد که چگونه هنر نفوذ سیاسی را آموخت. از آن زمان، تاسک صنعت تاکسی را از خفه کردن اوبر با مقررات منع کرده است، تنظیم‌کننده‌های تنبل را از راه‌اندازی بیمه‌گر نوآورانه لیموناد ممانعت می‌کند، و با تلاش‌های کازینوها برای سرکوب صنعت ورزش‌های فانتزی آنلاین مبارزه می‌کند.</p>', '2018-10-10 00:00:00', 5, 13, 'https://images.blinkist.io/images/books/5bb949c4862c43000775ed2b/1_1/470.jpg', '/en/books/the-fixer-en/purchase', 'تعمیرکار', '2023-01-27 02:04:12.965302', '2023-01-27 02:04:12.965302', NULL, 'The Fixer');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1279, 'پارادوکس قدرت', 'چگونه نفوذ به دست می آوریم و از دست می دهیم', 'چگونه نفوذ به دست می آوریم و از دست می دهیم', 13, 5, 'book', 't', '<p><em>پارادوکس قدرت</em> (2016) از انبوهی از داده‌های حاصل از مطالعات متعدد علوم اجتماعی در 20 سال گذشته برای بررسی پویایی قدرت استفاده می‌کند. دکتر داچر کلتنر به معنای قدرت در زندگی روزمره به پایان می رسد، درباره اینکه چرا بسیاری از مردم قدرت خود را از دست می دهند و از آنها سوء استفاده می کنند بحث می کند و توضیح می دهد که چگونه می توان از آن برای تبدیل جهان به مکانی بهتر استفاده کرد.</p>', '2018-01-04 00:00:00', 4, 108, 'https://images.blinkist.io/images/books/5a43a08fb238e10007128c34/1_1/470.jpg', '/en/books/the-power-paradox-en/purchase', 'پارادوکس-قدرت', '2023-01-27 02:04:20.657864', '2023-01-27 02:04:20.657864', NULL, 'The Power Paradox');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1280, 'قدرت بیداری', 'تمرینات ذهن آگاهی و ابزارهای معنوی برای متحول کردن زندگی شما', 'تمرینات ذهن آگاهی و ابزارهای معنوی برای متحول کردن زندگی شما', 25, 8, 'book', 't', '<p><em>قدرت بیداری </em> (2020) مجموعه ای از نوشته های جاودانه توسط رهبر معنوی و انگیزشی فقید وین دایر است. آنها کاوشی در دسترس و در عین حال الهام بخش از این باور او ارائه می دهند که تفکر روشنگرانه می تواند تغییرات ملموس و مثبت را در جهان نشان دهد.</p>', '2021-05-29 00:00:00', 5, 315, 'https://images.blinkist.io/images/books/60acea256cee0700080cfaf4/1_1/470.jpg', '/en/books/the-power-of-awakening-en/purchase', 'قدرت-بیداری', '2023-01-27 02:04:26.041203', '2023-01-27 02:04:26.041203', NULL, 'The Power of Awakening');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1281, 'سلام اسم من عالیه', 'نحوه ایجاد نام های تجاری که چسبیده باشند', 'نحوه ایجاد نام های تجاری که چسبیده باشند', 11, 4, 'book', 't', '<p><em>سلام، نام من عالی است</em> (2014) درباره مهم ترین تصمیمی است که یک کسب و کار جدید با آن روبرو می شود: انتخاب نام تجاری که شرکت را وارد استراتوسفری می کند که به آن تعلق دارد. ممکن است فکر کنید انتخاب یک نام ساده است، اما چیزهای زیادی برای یادگیری دارید! این راهنمای شما برای مذاکره با مارها و نردبان‌های فرآیند نام‌گذاری برند است - و در صدر قرار گرفتن.</p>', '2015-10-28 00:00:00', 4, 19, 'https://images.blinkist.io/images/books/562e306538643100073b0000/1_1/470.jpg', '/en/books/hello-my-name-is-awesome-en/purchase', 'سلام-اسم-من-عالیه', '2023-01-27 02:04:33.793591', '2023-01-27 02:04:33.793591', NULL, 'Hello, My Name is Awesome');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1282, 'اگر شما را درک می کردم، آیا این قیافه را در صورتم داشتم؟', 'ماجراهای من در هنر و علم ارتباط و برقراری ارتباط', 'ماجراهای من در هنر و علم ارتباط و برقراری ارتباط', 12, 5, 'book', 't', '<p><em>اگر شما را درک می کردم، آیا این نگاه را به صورتم می دیدم؟</em> (2017) توضیح می دهد که چگونه از تکنیک های بداهه که توسط بازیگران و کمدین ها انجام می شود، می توان به عنوان روش های آموزشی برای برقراری ارتباط بهتر استفاده کرد. آلدا از نمونه‌های روشن‌کننده ارتباطات نادرست از زندگی خود استفاده می‌کند تا نشان دهد چگونه همه ما می‌توانیم در ارتباط و گفتگو با یکدیگر بهتر باشیم.</p>', '2017-11-07 00:00:00', 4, 41, 'https://images.blinkist.io/images/books/59fe4717b238e100073f4207/1_1/470.jpg', '/en/books/if-i-understood-you-would-i-have-this-look-on-my-face-en/purchase', 'اگر-شما-را-درک-می-کردم،-آیا-این-قیافه-را-در-صورتم-داشتم؟', '2023-01-27 02:04:41.584558', '2023-01-27 02:04:41.584558', NULL, 'If I Understood You, Would I Have This Look On My Face? ');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1283, 'آقای در دسترس و دختر عقبگرد', 'راهنمای قطعی برای درک مردان از نظر عاطفی در دسترس و زنانی که آنها را دوست دارند', 'راهنمای قطعی برای درک مردان از نظر عاطفی در دسترس و زنانی که آنها را دوست دارند', 24, 8, 'book', 't', '<p><em>Mr Unavailable & the Fallback Girl </em>(2008) برای هر کسی که دائماً توسط شرکای غیرقابل دسترس از نظر عاطفی درگیر می شود، راه نجاتی فراهم می کند. <em>آقای غیرقابل دسترس</em> با بینش‌های شخصی عمیق، عشق سخت، و مقدار زیادی شوخ طبعی، راهنمای ضروری برای شکستن الگوهای مخرب روابط و یافتن عشق است.</p>', '2020-11-19 00:00:00', 5, 110, 'https://images.blinkist.io/images/books/5fae5d1e6cee070006bb42c1/1_1/470.jpg', '/en/books/mr-unavailable-and-the-fallback-girl-en/purchase', 'آقای-در-دسترس-و-دختر-عقبگرد', '2023-01-27 02:04:47.468839', '2023-01-27 02:04:47.468839', NULL, 'Mr Unavailable &amp; the Fallback Girl');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1284, 'طراحی کنید', 'چرا زیبایی کلید همه چیز است', 'چرا زیبایی کلید همه چیز است', 24, 8, 'book', 't', '<p><em>Do Design</em> (2016) یک کتابچه راهنمای مفید برای طراحان، صنعتگران و خلاقان از هر رشته ای است که می خواهند بدانند چه چیزی طراحی را عالی می کند و چگونه می توانند در کار خود به آن دست یابند. با پوشش مفهوم گسترده ای از طراحی،<em>Do Design</em> فراتر از طراحی چیزها است تا به نحوه طراحی کسب و کار و حتی زندگی خود فکر کند. در نهایت، این پلک زدن ها فراخوانی برای ما است تا با ایجاد زیبایی بیشتر در جهان، زندگی انسان ها را به سمت بهتر تغییر دهیم.</p>', '2019-12-27 00:00:00', 4, 110, 'https://images.blinkist.io/images/books/5dfcb6d76cee07000788a237/1_1/470.jpg', '/en/books/do-design-en/purchase', 'طراحی-کنید', '2023-01-27 02:04:54.69627', '2023-01-27 02:04:54.69627', NULL, 'Do Design');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1285, 'شروع کنید', 'ترس را به صورت مشت کنید، از میانگین فرار کنید، کاری را انجام دهید که مهم است', 'ترس را به صورت مشت کنید، از میانگین فرار کنید، کاری را انجام دهید که مهم است', 17, 8, 'book', 't', '<p>آیا برای فرار از حد متوسط ​​و عالی شدن آماده هستید؟ آیا می خواهید بر ترس های خود غلبه کنید و رویاهای خود را دنبال کنید؟ زندگی هدفمند و انجام کارهای مهم به چه معناست؟ در نهایت، مهم ترین گام در دستیابی به هر هدف بزرگ <em>START</em> است.</p>', '2014-12-11 00:00:00', 4, 33, 'https://images.blinkist.io/images/books/548625c86331620009d60000/1_1/470.jpg', '/en/books/start-en/purchase', 'شروع-کنید', '2023-01-27 02:05:00.043462', '2023-01-27 02:05:00.043462', NULL, 'Start');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1286, 'تائو فیزیک', 'کاوشی در تشابهات بین فیزیک مدرن و عرفان شرقی', 'کاوشی در تشابهات بین فیزیک مدرن و عرفان شرقی', 22, 8, 'book', 't', '<p><em>تائو فیزیک</em> (1975) رابطه بین علم سخت فیزیک مدرن و روشنگری معنوی عرفان شرقی را بررسی می کند. این پلک ها شباهت های قابل توجهی را بین نظریه نسبیت و نظریه کوانتومی از یک سو و هندوئیسم، بودیسم و ​​تائوئیسم از سوی دیگر نشان می دهد.</p>', '2017-11-23 00:00:00', 4, 153, 'https://images.blinkist.io/images/books/5a140003b238e100065296f4/1_1/470.jpg', '/en/books/the-tao-of-physics-en/purchase', 'تائو-فیزیک', '2023-01-27 02:05:08.55827', '2023-01-27 02:05:08.55827', NULL, 'The Tao of Physics');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1287, 'چگونه یک روز خوب داشته باشیم', 'بزرگتر فکر کنید، احساس بهتری داشته باشید و زندگی کاری خود را متحول کنید', 'بزرگتر فکر کنید، احساس بهتری داشته باشید و زندگی کاری خود را متحول کنید', 15, 6, 'book', 't', '<p><em>چگونه روز خوبی داشته باشیم </em>(2016) با توصیه هایی بر اساس یافته های اخیر در زمینه های روانشناسی، اقتصاد و علوم اعصاب توضیح می دهد که چگونه می توانید از روز کاری خود بهترین استفاده را ببرید. این پلک‌ها به شما یاد می‌دهند که چگونه مانند یک حرفه‌ای در چالش‌های محل کار مدرن پیمایش کنید و سطح انرژی خود را در روزهای پر اعصاب یا خسته‌کننده افزایش دهید.</p>', '2016-12-01 00:00:00', 4, 159, 'https://images.blinkist.io/images/books/583d641ee536360004b64ed8/1_1/470.jpg', '/en/books/how-to-have-a-good-day-en/purchase', 'چگونه-یک-روز-خوب-داشته-باشیم', '2023-01-27 02:05:15.748443', '2023-01-27 02:05:15.748443', NULL, 'How To Have A Good Day');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1288, 'مالکیت افراطی', 'چگونه مهرهای دریایی ایالات متحده رهبری و پیروز می شوند', 'چگونه مهرهای دریایی ایالات متحده رهبری و پیروز می شوند', 15, 6, 'book', 't', '<p><em>Extreme Ownership</em> (2015) درباره نحوه رهبری فرماندهان تیم نیروی دریایی است. این پلک‌ها در مورد موقعیت‌های جنگی پیچیده و مرگ و زندگی صحبت می‌کنند که نیروی دریایی SEAL معمولاً باید با آن دست و پنجه نرم کنند و اینکه چگونه می‌توانید مهارت‌های آن‌ها را در دنیای تجارت به کار ببرید.</p>', '2017-12-08 00:00:00', 5, 437, 'https://images.blinkist.io/images/books/5a26855fb238e1000635072b/1_1/470.jpg', '/en/books/extreme-ownership-en/purchase', 'مالکیت-افراطی', '2023-01-27 02:05:22.996288', '2023-01-27 02:05:22.996288', NULL, 'Extreme Ownership');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1289, 'فوری!', 'استراتژی هایی برای کنترل فوریت، کاهش استرس و افزایش بهره وری', 'استراتژی هایی برای کنترل فوریت، کاهش استرس و افزایش بهره وری', 23, 7, 'book', 't', '<p><em>فوری! </em>(2021) راهنمای شما برای انجام کارهای درست در زمان مناسب است. در دنیای پر سرعت ما، افتادن در دام فوریت آسان است - و همگام شدن با خواسته های ثابت اغلب غیرممکن به نظر می رسد. اما با یادگیری جایگزینی آگاهانه رفتارهای واکنشی با رفتارهای پیشگیرانه، می توانید استرس را کاهش دهید و کارهای عمیق تر و موثرتری انجام دهید.</p>', '2022-02-24 00:00:00', 4, 213, 'https://images.blinkist.io/images/books/6213917d6cee070008f6ed26/1_1/470.jpg', '/en/books/urgent-en/purchase', 'فوری!', '2023-01-27 02:05:28.079012', '2023-01-27 02:05:28.079012', NULL, 'Urgent!');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1290, 'قدرت یک شماره مثبت', 'چگونه نه بگوییم و همچنان به بله برسیم', 'چگونه نه بگوییم و همچنان به بله برسیم', 22, 7, 'book', 't', '<p>در <em>قدرت یک نه مثبت </em> (2007)، ویلیام اوری عمیقاً در قدرت نه فرو می رود. از آنجایی که <em>نه</em> به راحتی یکی از قوی ترین کلمات در هر زبانی است، مردم تمایل دارند از آن سوء استفاده کنند یا از ترس استفاده از آن می ترسند که باعث ناراحتی کسی شوند. <em>قدرت یک نه مثبت </em> دقیقاً به شما می گوید که چگونه از خودتان دفاع کنید و در عین مقاومت در برابر پرخاشگری و حفظ روابط کلیدی، قاطعانه امتناع کنید.</p>', '2021-01-18 00:00:00', 4, 129, 'https://images.blinkist.io/images/books/600169766cee070006e82008/1_1/470.jpg', '/en/books/the-power-of-a-positive-no-en/purchase', 'قدرت-یک-شماره-مثبت', '2023-01-27 02:05:35.701824', '2023-01-27 02:05:35.701824', NULL, 'The Power of a Positive No');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1291, 'آنچه مهم است را اندازه گیری کنید', 'چگونه گوگل، بونو و بنیاد گیتس جهان را با OKR تکان می دهند', 'چگونه گوگل، بونو و بنیاد گیتس جهان را با OKR تکان می دهند', 20, 6, 'book', 't', '<p><em>Measure What Matters </em>(2018) سفر مادام العمر جان دوئر را در کمک به سازمانها در اجرای اهداف و نتایج کلیدی - که با نام OKR شناخته می شود - شرح می دهد. با کمک OKR، شرکت‌هایی مانند Google و سازمان‌های غیرانتفاعی مانند بنیاد گیتس توانسته‌اند نحوه تعیین اهداف خود را برای رسیدن به ارتفاعات جدید تغییر دهند.</p>', '2018-06-20 00:00:00', 4, 474, 'https://images.blinkist.io/images/books/5b25d19bb238e100074bcf8f/1_1/470.jpg', '/en/books/measure-what-matters-en/purchase', 'آنچه-مهم-است-را-اندازه-گیری-کنید', '2023-01-27 02:05:44.048583', '2023-01-27 02:05:44.048583', NULL, 'Measure What Matters');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1292, 'سفر باورنکردنی گیاهان', 'گزارشی جذاب از تاریخ طبیعی', 'گزارشی جذاب از تاریخ طبیعی', 20, 6, 'book', 't', '<p><em>سفر باورنکردنی گیاهان </em>(2020) داستان شگفت انگیزی را بیان می کند که چگونه گیاهان در هر گوشه ای از کره زمین ساکن شدند. این بیوگرافی زیست‌شناختی که تاریخ طبیعی را با آخرین بینش‌های علوم زیستی مرتبط می‌کند، نشان می‌دهد که چگونه گیاهان بسیار پویاتر از آنچه به نظر می‌رسند هستند.</p>', '2020-09-05 00:00:00', 5, 57, 'https://images.blinkist.io/images/books/5f4e0e0a6cee070006957868/1_1/470.jpg', '/en/books/the-incredible-journey-of-plants-en/purchase', 'سفر-باورنکردنی-گیاهان', '2023-01-27 02:05:51.788334', '2023-01-27 02:05:51.788334', NULL, 'The Incredible Journey of Plants');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1293, 'قلاب شده', 'غذا، اراده آزاد، و نحوه سوء استفاده غول های غذا از اعتیاد ما', 'غذا، اراده آزاد، و نحوه سوء استفاده غول های غذا از اعتیاد ما', 23, 6, 'book', 't', '<p><em>Hooked </em>(2021) رابطه پیچیده ما با مواد غذایی فرآوری شده را بررسی می کند. این توضیح می‌دهد که چرا برخی غذاها ما را بیشتر میل می‌کنند، و نشان می‌دهد که چگونه شیمی مغز و زیست‌شناسی تکاملی ما توسط صنعت فست فود مورد بهره‌برداری قرار می‌گیرد.</p>', '2021-08-05 00:00:00', 4, 273, 'https://images.blinkist.io/images/books/61039ff66cee070007d9f4e5/1_1/470.jpg', '/en/books/hooked-en-michael-moss/purchase', 'قلاب-شده', '2023-01-27 02:05:57.25351', '2023-01-27 02:05:57.25351', NULL, 'Hooked');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1294, 'چگونه یک دانشجوی مستقیم شویم', 'استراتژی های غیر متعارفی که دانش آموزان کالج واقعی برای کسب امتیاز بالا در حین مطالعه کمتر استفاده می کنند', 'استراتژی های غیر متعارفی که دانش آموزان کالج واقعی برای کسب امتیاز بالا در حین مطالعه کمتر استفاده می کنند', 24, 10, 'book', 't', '<p><em>چگونه</em> <em></em> <em>دانش آموز شوید</em> <em>آ</em> /em> استراتژی‌های موفقی را به شما پیشنهاد می‌کند که توسط دانش‌آموزان مستقیم A واقعی استفاده می‌شود تا به شما کمک کند در حین مطالعه کمتر نمرات بهتری کسب کنید. از مدیریت زمان گرفته تا توصیه های ملموس در مورد تدوین پایان نامه، این کتاب تمام ابزارهایی را که برای به دست آوردن 4.0 عالی بدون فرسودگی نیاز دارید در اختیار شما قرار می دهد.</p>', '2014-08-26 00:00:00', 4, 147, 'https://images.blinkist.io/images/books/53fb87473731620008000000/1_1/470.jpg', '/en/books/how-to-become-a-straight-a-student-en/purchase', 'چگونه-یک-دانشجوی-مستقیم-شویم', '2023-01-27 02:06:02.382849', '2023-01-27 02:06:02.382849', NULL, 'How to Become a Straight-A Student');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1295, 'هشت مهارت ضروری افراد برای مدیریت پروژه', 'حل رایج ترین مشکلات افراد برای رهبران تیم', 'حل رایج ترین مشکلات افراد برای رهبران تیم', 27, 9, 'book', 't', '<p><em>هشت مهارت ضروری افراد برای مدیریت پروژه </em>(2018) یک راهنمای عملی است که برای کمک به رهبران تیم در تشخیص و حل مشکلات افراد در محیط‌های کاری افقی امروزی طراحی شده است. ثمره سال‌ها تجربه دست اول، کتاب بازی زاخاری وانگ برای رهبری مؤثر مملو از توصیه‌های عملی در مورد چگونگی تقویت انگیزه، مقابله با عملکرد ضعیف و ترس از شکست است.</p>', '2019-02-11 00:00:00', 4, 116, 'https://images.blinkist.io/images/books/5c60ae426cee070007658844/1_1/470.jpg', '/en/books/the-eight-essential-people-skills-for-project-management-en/purchase', 'هشت-مهارت-ضروری-افراد-برای-مدیریت-پروژه', '2023-01-27 02:06:10.054047', '2023-01-27 02:06:10.054047', NULL, 'The Eight Essential People Skills for Project Management');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1296, 'هنر گمشده اتصال', 'روش جمع آوری، بپرسید، انجام دهید برای ایجاد روابط تجاری معنادار', 'روش جمع آوری، بپرسید، انجام دهید برای ایجاد روابط تجاری معنادار', 18, 6, 'book', 't', '<p><em>هنر گمشده ارتباط </em>(2021) درباره ایجاد روابط معتبرتر در محل کار و زندگی است. این نشان می‌دهد که چگونه شبکه‌سازی حرفه‌ای همیشه نباید تراکنشی باشد، و روش سه مرحله‌ای جمع‌آوری، بپرسید، انجام دهید را برای ایجاد روابط معنادار و از بین بردن موانع فناوری برای ارتباط عمیق‌تر انسانی ارائه می‌دهد.</p>', '2021-10-14 00:00:00', 4, 70, 'https://images.blinkist.io/images/books/615ff5706cee070007bf9ab4/1_1/470.jpg', '/en/books/the-lost-art-of-connecting-en/purchase', 'هنر-گمشده-اتصال', '2023-01-27 02:06:17.998521', '2023-01-27 02:06:17.998521', NULL, 'The Lost Art of Connecting');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1297, 'قلب خود را در آن بریزید', 'چگونه استارباکس یک فنجان در یک زمان یک شرکت ایجاد کرد', 'چگونه استارباکس یک فنجان در یک زمان یک شرکت ایجاد کرد', 18, 8, 'book', 't', '<p><em>قلب خود را درون آن بریزید</em>شما را به سفری جذاب می برد که چگونه استارباکس به یک داستان موفقیت آمیز تبدیل شد. این کتاب شروع آن را روشن می کند، نشان می دهد که چگونه نرخ رشد سریع ممکن بود و توضیح می دهد که چگونه کسب و کارها می توانند از استراتژی ها و اصول آن بیاموزند.</p>', '2015-02-27 00:00:00', 5, 32, 'https://images.blinkist.io/images/books/54eafb5e393366000acf0000/1_1/470.jpg', '/en/books/pour-your-heart-into-it-en/purchase', 'قلب-خود-را-در-آن-بریزید', '2023-01-27 02:06:25.631036', '2023-01-27 02:06:25.631036', NULL, 'Pour Your Heart Into It');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1298, 'پادزهر', 'شادی برای افرادی که نمی توانند مثبت اندیشی را تحمل کنند', 'شادی برای افرادی که نمی توانند مثبت اندیشی را تحمل کنند', 18, 9, 'book', 't', '<p><em></em> <em>پادزهر</em> راهنمای افراد باهوش برای درک ایده‌ای است که بسیار اشتباه درک شده است. نویسنده تأکید می کند که تفکر مثبت راه حل نیست، بلکه بخشی از مشکل است. او یک مسیر جایگزین و «منفی» برای خوشبختی و موفقیت را ترسیم می کند که شامل پذیرش شکست، بدبینی، ناامنی و عدم اطمینان است – چیزی که ما معمولاً زندگی خود را صرف تلاش برای اجتناب از آن می کنیم.</p>', '2014-02-12 09:14:00', 4, 249, 'https://images.blinkist.io/images/books/52fa431b66626100080d0000/1_1/470.jpg', '/en/books/the-antidote-en/purchase', 'پادزهر', '2023-01-27 02:06:33.298632', '2023-01-27 02:06:33.298632', NULL, 'The Antidote');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1299, 'فانی بودن', 'بیماری، دارو و آنچه در پایان مهم است', 'بیماری، دارو و آنچه در پایان مهم است', 19, 8, 'book', 't', '<p><em>فانی بودن </em>(2014) به خواننده کمک می‌کند یکی از ناگزیرترین اجتناب‌ناپذیر زندگی را پیمایش و درک کند: مرگ. در این کتاب با موفقیت ها و شکست های رویکرد جامعه مدرن به مرگ و مردن آشنا می شوید. همچنین یاد خواهید گرفت که چگونه با مرگ مقابله کنید و با انجام این کار، چگونه بهترین استفاده را از زندگی ببرید.</p>', '2015-04-02 00:00:00', 5, 111, 'https://images.blinkist.io/images/books/5519d8b76661620007000000/1_1/470.jpg', '/en/books/being-mortal-en/purchase', 'فانی-بودن', '2023-01-27 02:06:41.124457', '2023-01-27 02:06:41.124457', NULL, 'Being Mortal');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1300, 'راهنمای راه اندازی', 'اسرار سریعترین استارتاپ های در حال رشد از کارآفرینان بنیانگذار آنها', 'اسرار سریعترین استارتاپ های در حال رشد از کارآفرینان بنیانگذار آنها', 10, 5, 'book', 't', '<p><em>Startup-Playbook</em> (2012) مستقیماً از بنیانگذاران برخی از بزرگ‌ترین استارت‌آپ‌های جهان، نکاتی را برای کسب‌وکار به شما ارائه می‌دهد. نویسنده با انجام مصاحبه با بنیانگذاران شرکت هایی مانند LinkedIn و Spanx، آنچه را که باید انجام دهید تا آن را بزرگ کنید، کشف می کند.</p>', '2016-01-22 00:00:00', 4, 184, 'https://images.blinkist.io/images/books/569e7fe7eaed8a0007000028/1_1/470.jpg', '/en/books/the-startup-playbook-en/purchase', 'راهنمای-راه-اندازی', '2023-01-27 02:06:49.729903', '2023-01-27 02:06:49.729903', NULL, 'The Startup Playbook');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1301, 'مانیفست چک لیست', 'چگونه کارها را درست انجام دهیم', 'چگونه کارها را درست انجام دهیم', 16, 7, 'book', 't', '<p>برگرفته از تجربه او به عنوان جراح عمومی، <em>مانیفست فهرست چک</em> (2009) Atul Gawande شواهد شگفت انگیزی را نشان می دهد که چگونه استفاده از یک چک لیست ساده می تواند به طور قابل توجهی خطای انسانی را در حرفه های پیچیده مانند هوانوردی، مهندسی و ... کاهش دهد. دارو.</p>', '2013-12-24 09:27:01', 4, 224, 'https://images.blinkist.io/images/books/52023570e4b0d3bda98fefd9/1_1/470.jpg', '/en/books/the-checklist-manifesto-en/purchase', 'مانیفست-چک-لیست', '2023-01-27 02:06:55.320429', '2023-01-27 02:06:55.320429', NULL, 'The Checklist Manifesto');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1302, 'نه پینت', 'سفری در میان پول، دارو و اسرار خون', 'سفری در میان پول، دارو و اسرار خون', 24, 7, 'book', 't', '<p><em>Nine Pints ​​</em>(2018) داستان غنی اما نادیده گرفته شده خون را بررسی می کند. رز جورج با نگاهی پانوراما و نزدیک شدن به موضوع از زوایای مختلف، به علم خون نگاه می کند و برخی از نهادها، مشاغل و تابوهایی را که در اطراف این مایع حیاتی به وجود آمده اند، جزئیات می دهد.</p>', '2019-06-28 00:00:00', 5, 36, 'https://images.blinkist.io/images/books/5d13307f6cee070007d74c07/1_1/470.jpg', '/en/books/nine-pints-en/purchase', 'نه-پینت', '2023-01-27 02:07:03.080294', '2023-01-27 02:07:03.080294', NULL, 'Nine Pints');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1303, 'پول جوان', 'درون دنیای پنهان سربازان پس از سقوط وال استریت', 'درون دنیای پنهان سربازان پس از سقوط وال استریت', 15, 8, 'book', 't', '<p>کوین روز سه سال را به دنبال هشت جوان وال استریت گذراند تا دریابد که سقوط 2007 - و عواقب آن - چگونه بر صنعت مالی تأثیر گذاشته است. <em>Young Money </em>تصویر واضحی از تحلیلگران جوان ترسیم می کند که خود را در یک ترن هوایی بی وقفه از شب و استرس شدید می بینند، در حالی که درآمد شش رقمی به دست می آورند.</p>', '2014-12-03 00:00:00', 4, 21, 'https://images.blinkist.io/images/books/547c9b5563633000099c0400/1_1/470.jpg', '/en/books/young-money-en/purchase', 'پول-جوان', '2023-01-27 02:07:11.101754', '2023-01-27 02:07:11.101754', NULL, 'Young Money');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1304, 'رازهای موفقیت سوپراستارهای بازاریابی آنلاین', 'از موفق ترین بازاریابان آنلاین امروزی بیاموزید', 'از موفق ترین بازاریابان آنلاین امروزی بیاموزید', 11, 6, 'book', 't', '<p><em>رازهای موفقیت سوپراستارهای بازاریابی آنلاین</em> (2015) به شما کمک می‌کند کمپینی را برنامه‌ریزی کنید تا محصول خود را به یک مخاطب جدید بالقوه بی‌شمار ببرید. این پلک ها اصول و استراتژی های ساختن یک وبلاگ برنده، ایجاد محتوای آنلاین عالی یا وایرال شدن ویدیوهای شما را نشان می دهد.</p>', '2017-05-19 00:00:00', 4, 46, 'https://images.blinkist.io/images/books/5919b19db238e1000736bc0d/1_1/470.jpg', '/en/books/success-secrets-of-the-online-marketing-superstars-en/purchase', 'رازهای-موفقیت-سوپراستارهای-بازاریابی-آنلاین', '2023-01-27 02:07:18.338129', '2023-01-27 02:07:18.338129', NULL, 'Success Secrets of the Online Marketing Superstars');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1305, 'هر دو/و فکر کردن', 'از تنش های خلاقانه برای حل سخت ترین مشکلات خود بپذیرید', 'از تنش های خلاقانه برای حل سخت ترین مشکلات خود بپذیرید', 8, 2, 'book', 't', '<p><em>Both/And Thinking </em>(2022) چارچوب جدیدی برای تصمیم گیری ارائه می دهد. با طرز فکر یا/یا، دنیای شما پر از انتخاب های پیچیده و فداکاری های دشوار به نظر می رسد. با اتخاذ یک طرز فکر هر دو/و، می‌توانید انتخاب‌های سخت را به فرصت‌های پربار تبدیل کنید - هیچ فداکاری لازم نیست.</p>', '2022-12-08 00:00:00', 4, 32, 'https://images.blinkist.io/images/books/6391af7c7a8e390009365fbb/1_1/470.jpg', '/en/books/both-slash-and-thinking-en/purchase', 'هر-دو/و-فکر-کردن', '2023-01-27 02:07:25.378169', '2023-01-27 02:07:25.378169', NULL, 'Both/And Thinking');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1306, '15 قانون ارزشمند رشد', 'آنها را زندگی کنید و به پتانسیل خود برسید', 'آنها را زندگی کنید و به پتانسیل خود برسید', 26, 10, 'book', 't', '<p>در <em>15 قانون ارزشمند رشد </em> (2012)، استاد رهبری، جان سی. ماکسول، اسرار خود برای توسعه خود را به اشتراک می گذارد. او آشکار می کند که رشد شخصی باید به طور فعال پرورش داده شود. به خودی خود اتفاق نمی افتد با کشف ارزش های کلیدی خود، تدوین یک استراتژی، و انجام اقدامات کوچک هر روز، می توانید رشد شخصی خود را تسریع کنید - و زندگی پر از شادی، ماجراجویی و رضایت داشته باشید.</p>', '2020-04-20 00:00:00', 5, 292, 'https://images.blinkist.io/images/books/5e9979816cee070007b55d9a/1_1/470.jpg', '/en/books/the-15-invaluable-laws-of-growth-en/purchase', '15-قانون-ارزشمند-رشد', '2023-01-27 02:07:31.378561', '2023-01-27 02:07:31.378561', NULL, 'The 15 Invaluable Laws of Growth');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1307, '23 چیزی که درباره سرمایه داری به شما نمی گویند', 'چرا سرمایه داری آن چیزی نیست که شما فکر می کنید.', 'چرا سرمایه داری آن چیزی نیست که شما فکر می کنید.', 23, 10, 'book', 't', '<p>در <em>23</em> <em>چیزها</em> <em>آنها</em> <em>ن</em> <em>به شما می گویند</em> <em> </em> <em>درباره</em> <em>سرمایه داری</em> ها-جون چانگ بزرگترین افسانه های رویکرد اقتصادی کنونی ما را از بین می برد. او توضیح می‌دهد که چگونه، علی‌رغم آنچه اکثر اقتصاددانان معتقدند، مشکلات زیادی در سرمایه‌داری بازار آزاد وجود دارد. چانگ علاوه بر توضیح مشکلات، راه‌حل‌های ممکنی را نیز ارائه می‌کند که می‌تواند به ما در ساختن دنیایی بهتر و عادلانه‌تر کمک کند.</p>', '2014-06-24 00:00:00', 4, 131, 'https://images.blinkist.io/images/books/53aa85eb32633900070b0000/1_1/470.jpg', '/en/books/23-things-they-dont-tell-you-about-capitalism-en/purchase', '23-چیزی-که-درباره-سرمایه-داری-به-شما-نمی-گویند', '2023-01-27 02:07:38.761574', '2023-01-27 02:07:38.761574', NULL, '23 Things They Don’t Tell You About Capitalism');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1308, 'محرک های گفتگو', 'راهنمای کامل ایجاد مشتری با دهان به دهان', 'راهنمای کامل ایجاد مشتری با دهان به دهان', 16, 6, 'book', 't', '<p><em>محرک‌های گفتگو </em>(2018) حقیقتی را به ما یادآوری می‌کند که آنقدر بدیهی است که اغلب فراموش می‌شود: هیچ چیز به اندازه توصیه‌های شفاهی، مشتریان را از درهای شما عبور نمی‌دهد. ترفند این است که به طور استراتژیک مکالمه را با نکات صحبتی که به دقت طراحی شده اند هدایت کنید که شما را از رقبا متمایز می کند. در این پلک ها، نحوه انجام این کار را خواهید آموخت.</p>', '2019-02-04 00:00:00', 5, 43, 'https://images.blinkist.io/images/books/5c56fb116cee070008d6c85f/1_1/470.jpg', '/en/books/talk-triggers-en/purchase', 'محرک-های-گفتگو', '2023-01-27 02:07:45.767362', '2023-01-27 02:07:45.767362', NULL, 'Talk Triggers');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1309, 'ضرب کننده ها', 'چگونه بهترین رهبران همه را باهوش‌تر می‌کنند', 'چگونه بهترین رهبران همه را باهوش‌تر می‌کنند', 24, 9, 'book', 't', '<p><em>Multipliers</em> (2010) تفاوت بین رهبران خوب، معروف به Multipliers، که می توانند به هر تیمی بپیوندند و آن را شکوفا کنند، و رهبران بد، شناخته شده به عنوان کوچک کننده<em>،</em> بررسی می کند. که می تواند هر تیمی را از انرژی و راندن خود تخلیه کند. نویسنده لیز وایزمن توضیح می‌دهد که چگونه می‌توان انواع مختلف ضرب‌کننده‌ها و کاهش‌دهنده‌ها را تشخیص داد، در حالی که مهارت‌هایی را که باید برای توسعه آن تلاش کنید با مهارت‌هایی که به هر قیمتی باید از آن‌ها اجتناب کنید، مقایسه می‌کند.</p>', '2018-06-15 00:00:00', 5, 148, 'https://images.blinkist.io/images/books/5b203354b238e100070025c7/1_1/470.jpg', '/en/books/multipliers-en/purchase', 'ضرب-کننده-ها', '2023-01-27 02:07:51.211458', '2023-01-27 02:07:51.211458', NULL, 'Multipliers');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1310, 'مرگبارترین دشمن', 'جنگ ما علیه میکروب های قاتل', 'جنگ ما علیه میکروب های قاتل', 31, 10, 'book', 't', '<p><em>کشنده ترین دشمن </em>(2017) هشداری هشیارکننده در مورد تهدید جدی بیماری های عفونی برای زندگی مدرن است. با استفاده از نمونه هایی مانند ابولا، سارس، و زیکا، این آغازگر دستگیر کننده در اپیدمیولوژی چگونگی ظهور، گسترش و تبدیل شدن بیماری ها به بیماری های همه گیر را توضیح می دهد. </p>', '2020-04-25 00:00:00', 5, 47, 'https://images.blinkist.io/images/books/5e9e2aec6cee070006833321/1_1/470.jpg', '/en/books/deadliest-enemy-en/purchase', 'مرگبارترین-دشمن', '2023-01-27 02:07:58.445127', '2023-01-27 02:07:58.445127', NULL, 'Deadliest Enemy');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1311, 'آموزش یک سرمایه گذار ارزشی', 'جستجوی تحول آفرین من برای ثروت، خرد و روشنگری', 'جستجوی تحول آفرین من برای ثروت، خرد و روشنگری', 20, 9, 'book', 't', '<p>در <em>آموزش یک سرمایه گذار ارزشی </em>(2014)، گای اسپایر تحول خود را از مدیر حریص صندوق تامینی در وال استریت به یک <em>سرمایه گذار ارزشی موفق</em> بازگو می کند. اسپایر با به اشتراک گذاشتن داستان باورنکردنی حرفه خود و خردی که در این راه به دست آورده است، بینش های شگفت انگیزی در مورد آنچه که او به عنوان انتخابی نادرست بین داشتن یک زندگی اخلاقی و یک زندگی موفق مالی می بیند، دارد. با تحسین فراوان، اسپایر همچنین از افرادی که بیشترین تأثیر را در زندگی حرفه‌ای او داشتند نام می‌برد و تأثیر خاصی را که هر یک از آنها بر طرز فکر و حرفه او داشتند، توضیح می‌دهد.</p>', '2014-11-13 00:00:00', 4, 120, 'https://images.blinkist.io/images/books/546325c46634660008000000/1_1/470.jpg', '/en/books/the-education-of-a-value-investor-en/purchase', 'آموزش-یک-سرمایه-گذار-ارزشی', '2023-01-27 02:08:05.271489', '2023-01-27 02:08:05.271489', NULL, 'The Education of a Value Investor');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1312, 'بیوگرافی قبل از خواب: ملکه مد', 'آنچه ماری آنتوانت در انقلاب پوشید', 'آنچه ماری آنتوانت در انقلاب پوشید', 32, 5, 'book', 't', '<p><strong>به روایت مارستون یورک<br></strong><br><strong>موسیقی توسط فدریکو کدرونی</strong><em><br></em></p>
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1313, 'زمان سرقت از بانک', '... و 131 پیشنهاد تاب خورده دیگر و شعارهای خوش نیت.', '... و 131 پیشنهاد تاب خورده دیگر و شعارهای خوش نیت.', 19, 8, 'book', 't', '<p><em>When To Rob a Bank</em> (2015) مجموعه‌ای از مقالات منتشر شده در وبلاگ Freakonomics در freakonomics.com را ارائه می‌کند که اکنون ده سال است که قوی‌تر شده است. لویت و دوبنر با توجه به چیزهای غیرقابل پیش بینی و کاملاً عجیب، همه چیز را پوشش می دهند، از اینکه چرا باید از کسی که نام میانی او وین است دوری کنید تا اینکه چرا برخی از ما باید بیشتر از دیگران رابطه جنسی داشته باشیم.</p>', '2015-07-17 00:00:00', 4, 54, 'https://images.blinkist.io/images/books/55a39ec03738610007250100/1_1/470.jpg', '/en/books/when-to-rob-a-bank-en/purchase', 'زمان-سرقت-از-بانک', '2023-01-27 02:08:18.147135', '2023-01-27 02:08:18.147135', NULL, 'When to Rob a Bank');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1314, 'چیزهای کوچک را عرق نکنید. . . و این همه چیز کوچک است', 'راه های ساده برای جلوگیری از تسلط بر چیزهای کوچک', 'راه های ساده برای جلوگیری از تسلط بر چیزهای کوچک', 12, 6, 'book', 'f', '<p><em>از چیزهای کوچک عرق نکن</em>(1997) همه چیز در مورد یافتن شادی و آرامش خاطر است. این به شما می آموزد که چگونه مشکلات خود را به فرصت تبدیل کنید، در موقعیت های استرس زا آرام بمانید و به طور کامل در لحظه زندگی کنید تا بتوانید از آنچه دارید قدردانی کنید و بیشترین بهره را از زندگی ببرید.</p>', '2015-04-10 00:00:00', 4, 123, 'https://images.blinkist.io/images/books/552473e43066650007a20000/1_1/470.jpg', '/en/books/dont-sweat-the-small-stuff-and-its-all-small-stuff-en/purchase', 'چیزهای-کوچک-را-عرق-نکنید.-.-.-و-این-همه-چیز-کوچک-است', '2023-01-27 02:08:25.404707', '2023-01-27 02:08:25.404707', NULL, 'Don’t Sweat the Small Stuff . . . and It’s All Small Stuff');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1315, 'برو وحشی', 'چربی بخورید، آزاد بدوید، اجتماعی باشید و قوانین دیگر Evolution را برای سلامتی و رفاه کامل دنبال کنید.', 'چربی بخورید، آزاد بدوید، اجتماعی باشید و قوانین دیگر Evolution را برای سلامتی و رفاه کامل دنبال کنید.', 15, 6, 'book', 't', '<p><em>Go Wild</em>(2014) نگاهی به موقع به این موضوع می دهد که چرا انسان ها نباید تمام روز جلوی کامپیوتر بنشینند. تکامل بدن و ذهن ما را برای سبک زندگی و رژیم غذایی بی تحرک امروزی ساخته نیست. حرکت ما از بیابان به اتاقک احتمالاً مسئول افزایش حساسیت ما به تعدادی از بیماری‌های جدید است. </p>', '2017-06-15 00:00:00', 4, 25, 'https://images.blinkist.io/images/books/593e7517b238e10005ae415a/1_1/470.jpg', '/en/books/go-wild-en/purchase', 'برو-وحشی', '2023-01-27 02:08:32.947522', '2023-01-27 02:08:32.947522', NULL, 'Go Wild');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1316, 'یوگا سوتراهای پاتانجلی', 'آموزه های جاودانه برای ذهن، بدن و هارمونی عاطفی', 'آموزه های جاودانه برای ذهن، بدن و هارمونی عاطفی', 25, 8, 'book', 't', '<p><em>یوگا سوتراهای پاتانجلی</em> (1978) متنی کلاسیک در مورد فلسفه و تمرین یوگا است. این کتاب که به زبان سانسکریت باستان نوشته شده است، ایده های اصلی متافیزیکی، معنوی، روانی، اخلاقی و اخلاقی یوگا را توضیح می دهد. همچنین اصول نحوه تمرین یوگا را بیان می کند، بنابراین می توانید این ایده ها را عملی کنید و از آنها برای رسیدن به شادی پایدار و آرامش درونی استفاده کنید. </p>', '2021-11-07 00:00:00', 5, 264, 'https://images.blinkist.io/images/books/617be9b56cee07000723559e/1_1/470.jpg', '/en/books/the-yoga-sutras-of-patanjali-en/purchase', 'یوگا-سوتراهای-پاتانجلی', '2023-01-27 02:08:40.72882', '2023-01-27 02:08:40.72882', NULL, 'The Yoga Sutras of Patanjali');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1317, 'طرح محتوای یک ساعته', 'راهنمای Solopreneur برای ارزش یکسال ایده های پست وبلاگ در 60 دقیقه و ایجاد محتوایی که بفروشد و قلاب کند', 'راهنمای Solopreneur برای ارزش یکسال ایده های پست وبلاگ در 60 دقیقه و ایجاد محتوایی که بفروشد و قلاب کند', 12, 5, 'book', 't', '<p><em>برنامه محتوای یک ساعته</em> (2017) یک راهنمای استراتژیک برای ایجاد محتوای وبلاگ جذاب، جلب توجه و سودآور است. ثمره سال‌ها تجربه عملی در بازاریابی آنلاین، توصیه‌های عملی میرا کوتاند برای تولیدکنندگان بالقوه محتوا، دقیقاً بر <em>چگونه</em> متمرکز است. پر از نکات و استراتژی‌های مفید، این پلک زدن‌ها به شما کمک می‌کند تا ایده‌های درخشان خود را از روی زمین بسازید.</p>', '2018-10-04 00:00:00', 4, 123, 'https://images.blinkist.io/images/books/5bb39d1f862c4300075b3703/1_1/470.jpg', '/en/books/the-one-hour-content-plan-en/purchase', 'طرح-محتوای-یک-ساعته', '2023-01-27 02:08:48.182061', '2023-01-27 02:08:48.182061', NULL, 'The One Hour Content Plan');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1325, 'پول دیگران', 'تجارت واقعی امور مالی', 'تجارت واقعی امور مالی', 17, 7, 'book', 't', '<p><em>پول سایر افراد </em>(2015) تقسیم‌بندی دقیقی از بخش مالی ارائه می‌کند: نحوه عملکرد آن، تأثیری که بر اقتصادها می‌گذارد و هدف آن در حالت ایده‌آل چه خواهد بود – برخلاف هدف فعلی آن است. دریابید که چرا بخش مالی بین‌المللی به مکانیزمی بی‌رحمانه متشکل از قطعات فاسد تبدیل شده است و کشف کنید که چگونه می‌توان این قطعات را حذف کرد و در نهایت جایگزین کرد.</p>', '2017-07-13 00:00:00', 4, 59, 'https://images.blinkist.io/images/books/596105fcb238e100054fb0be/1_1/470.jpg', '/en/books/other-peoples-money-en/purchase', 'پول-دیگران', '2023-01-27 02:09:46.79447', '2023-01-27 02:09:46.79447', NULL, 'Other People’s Money');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1318, 'عادات کوچک', 'تغییرات کوچک که همه چیز را تغییر می دهد', 'تغییرات کوچک که همه چیز را تغییر می دهد', 22, 7, 'book', 't', '<p><em>عادت‌های کوچک </em> (2019) مراقبه‌ای است در مورد فضیلت‌های نخوردن بیش از حدی که می‌توانید بجوید. بی جی فاگ، تحلیلگر رفتاری استدلال می کند که اگر می خواهید تغییرات مثبتی ایجاد کنید، باید کوچک فکر کنید. میخوای خوش فرم بشی؟ با دو بار فشار در روز شروع کنید. آیا می خواهید هوشیارتر شوید؟ هر بار که در ماشین خود را می بندید یک نفس یوگا بکشید. این «عادات کوچک» سطح را پایین می‌آورد، به این معنی که گنجاندن آن‌ها در روال فعلی‌تان آسان‌تر است. با این حال، با گذشت زمان، مغز شما را دوباره سیم‌کشی می‌کنند و عادت‌های فضیلت‌آمیز را به‌طور خودکار مانند دم کردن یک فنجان قهوه در صبح ایجاد می‌کنند.</p>', '2020-02-18 00:00:00', 5, 1446, 'https://images.blinkist.io/images/books/5e48ae806cee07000726e170/1_1/470.jpg', '/en/books/tiny-habits-en/purchase', 'عادات-کوچک', '2023-01-27 02:08:55.936706', '2023-01-27 02:08:55.936706', NULL, 'Tiny Habits');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1319, 'سه ماهه پنجم', 'راهنمای مادر شاغل برای استایل، سلامت عقل و موفقیت بزرگ بعد از بچه', 'راهنمای مادر شاغل برای استایل، سلامت عقل و موفقیت بزرگ بعد از بچه', 14, 6, 'book', 't', '<p><em>سه ماهه پنجم</em> (2017) مملو از توصیه ها و نکاتی است که برای تازه مادران در مورد چگونگی بازگشت موفقیت آمیز به سر کار پس از مرخصی زایمانشان وجود دارد. این کتاب با پوشش جزئیات مهمی مانند لباس پوشیدن، نحوه انتخاب بهترین مهدکودک و نحوه تغذیه نوزاد حتی زمانی که همراه آن نیستید، از تجربیات خود نویسنده و همچنین مصاحبه با دیگر مادران جدید استفاده می کند. این یک راهنمای عملی و الهام‌بخش خودیاری برای تازه مادرانی است که ممکن است از احتمال بازگشت به شغل خود غافلگیر شوند.</p>', '2017-12-29 00:00:00', 3, 19, 'https://images.blinkist.io/images/books/5a3a398ab238e10007128aed/1_1/470.jpg', '/en/books/the-fifth-trimester-en/purchase', 'سه-ماهه-پنجم', '2023-01-27 02:09:03.28313', '2023-01-27 02:09:03.28313', NULL, 'The Fifth Trimester');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1320, 'معادله خدا', 'جست‌وجو برای تئوری همه چیز', 'جست‌وجو برای تئوری همه چیز', 23, 7, 'book', 't', '<p><em>معادله خدا </em>(2021) نگاهی قابل دسترس به تاریخ و حال فیزیک نظری است. این آغازگر، علم را در پس نسبیت، نظریه ریسمان، و جستجوی «نظریه همه چیز» گریزان باز می کند.</p>', '2021-05-22 00:00:00', 5, 278, 'https://images.blinkist.io/images/books/60a78c266cee070007790f0b/1_1/470.jpg', '/en/books/the-god-equation-en/purchase', 'معادله-خدا', '2023-01-27 02:09:11.023611', '2023-01-27 02:09:11.023611', NULL, 'The God Equation');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1321, 'تجارت خرد میلیون دلاری', 'چگونه تخصص خود را به یک دوره آنلاین دیجیتال تبدیل کنیم', 'چگونه تخصص خود را به یک دوره آنلاین دیجیتال تبدیل کنیم', 20, 6, 'book', 't', '<p><em>تجارت خرد میلیون دلاری </em>(2021) یک راهنمای عملی برای ایجاد اولین دوره آنلاین شما - و کسب درآمد زیاد در این فرآیند است. از ارائه ایده ای که اشتیاق شما را تغذیه می کند تا به کمال رساندن بازاریابی شما، راهنمایی هایی را در مورد چگونگی ادعای جایگاه خود در این صنعت نوآورانه و رو به رشد یادگیری آنلاین ارائه می دهد.</p>', '2022-10-12 00:00:00', 4, 41, 'https://images.blinkist.io/images/books/634536306cee07000854271d/1_1/470.jpg', '/en/books/million-dollar-micro-business-en/purchase', 'تجارت-خرد-میلیون-دلاری', '2023-01-27 02:09:18.523731', '2023-01-27 02:09:18.523731', NULL, 'Million Dollar Micro Business	');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1322, 'تانترا شهری', 'سکس مقدس برای قرن بیست و یکم', 'سکس مقدس برای قرن بیست و یکم', 22, 9, 'book', 't', '<p><em>Urban Tantra</em>(2007) یک راهنمای بی‌معنی و بدون تعصب برای تانترا است - تمرینی معنوی که به شما نگاهی تازه به زندگی جنسی شما می‌دهد. این نشان می دهد که تانترا می تواند برای هر کسی کار کند. برای یک تمرین‌کننده BDSM که می‌خواهد تشریفات خود را تشدید کند، به همان اندازه مفید است که برای والدینی عجول که به دنبال برقراری ارتباط مجدد با تمایلات جنسی خود هستند. برای تمرین تانترا، نیازی به تسلط بر پوزیشن های پیچیده یا یادگیری آواز خواندن به زبان سانسکریت ندارید. تنها چیزی که نیاز دارید چند ابزار ساده است که به شما کمک می‌کند تا هوشیارتر شوید و وارد بدن خود شوید.</p>', '2021-02-04 00:00:00', 4, 91, 'https://images.blinkist.io/images/books/601433316cee070008ada7fe/1_1/470.jpg', '/en/books/urban-tantra-en/purchase', 'تانترا-شهری', '2023-01-27 02:09:25.753041', '2023-01-27 02:09:25.753041', NULL, 'Urban Tantra');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1323, 'تغییر رهبری', '۱۱ تغییر اساسی که هر رهبر باید بپذیرد', '۱۱ تغییر اساسی که هر رهبر باید بپذیرد', 20, 7, 'book', 't', '<p><em>Leadershift</em> (2019) به رهبران و رهبران بالقوه کمک می کند تا توانایی و تمایل خود را برای ایجاد تغییراتی در رهبری خود ایجاد کنند که به طور مثبت نه تنها رشد آنها، بلکه رشد سازمان آنها را تقویت کند. این نشان می‌دهد که چگونه با طرز فکر صحیح و به‌روزترین تفکر، همه ما می‌توانیم به عنوان رهبر به موفقیت‌های بزرگی دست یابیم.</p>', '2019-04-02 00:00:00', 5, 195, 'https://images.blinkist.io/images/books/5ca27bc56cee0700079f2c3b/1_1/470.jpg', '/en/books/leadershift-en/purchase', 'تغییر-رهبری', '2023-01-27 02:09:31.091536', '2023-01-27 02:09:31.091536', NULL, 'Leadershift');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1324, 'عشق جنگجو', 'یک خاطره', 'یک خاطره', 27, 8, 'book', 't', '<p><em>جنگجوی عشق </em>(2017) اثر گلنون دویل، خاطراتی است که چگونگی مبارزه یک زن با اعتیاد، بی نظمی در غذا خوردن و خیانت را با رویارویی و در نهایت مالکیت آسیب پذیری های خود بازگو می کند. فراتر از آن، این یک مراقبه است در مورد آنچه که درد باید به ما بیاموزد، و چگونه، با پذیرش شکست های خود، می توانیم به عنوان اصیل ترین خود زندگی کنیم.</p>', '2021-03-27 00:00:00', 4, 79, 'https://images.blinkist.io/images/books/605475c16cee0700073c376d/1_1/470.jpg', '/en/books/love-warrior-en/purchase', 'عشق-جنگجو', '2023-01-27 02:09:39.033691', '2023-01-27 02:09:39.033691', NULL, 'Love Warrior');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1327, 'از سرت برو بیرون', 'توقف مارپیچ افکار سمی', 'توقف مارپیچ افکار سمی', 18, 7, 'book', 't', '<p><em>از سرت بیرون برو</em> (2020) کتاب راهنمای کسانی است که به دنبال رهایی از افکار منفی هستند. داروی جنی آلن؟ خود و ذهن خود را تسلیم آغوش مسیح و محبت خدا کنیم. نویسنده بر این باور است که با انجام این کار، همه ما می توانیم زندگی پر از افکاری داشته باشیم که ما را در مسیری مثبت هدایت می کنند - و از منفی بودن اطرافمان اجتناب کنیم.</p>', '2020-03-07 00:00:00', 4, 99, 'https://images.blinkist.io/images/books/5e5fabd46cee0700069aea8d/1_1/470.jpg', '/en/books/get-out-of-your-head-en/purchase', 'از-سرت-برو-بیرون', '2023-01-27 02:10:02.506359', '2023-01-27 02:10:02.506359', NULL, 'Get Out of Your Head');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1328, 'روان در 3 ماه', 'نکات و تکنیک هایی برای کمک به یادگیری هر زبانی', 'نکات و تکنیک هایی برای کمک به یادگیری هر زبانی', 13, 6, 'book', 't', '<p><em>Fluent In 3 Months</em> (2014) راهنمای تسلط بر هر زبانی در زمان بی سابقه است. این پلک ها مملو از روش های مفیدی است که به شما کمک می کند یک زبان جدید را به طور موثر و موثر یاد بگیرید. آنها اشکال سنتی یادگیری زبان را از بین می‌برند، استراتژی‌های عملی را ارائه می‌کنند تا امروز شما را به صحبت بفرستند و شما را در مسیر چند زبانه بودن قرار می‌دهند.</p>', '2016-12-21 00:00:00', 4, 164, 'https://images.blinkist.io/images/books/58559c5b1219060004019e0a/1_1/470.jpg', '/en/books/fluent-in-3-months-en/purchase', 'روان-در-3-ماه', '2023-01-27 02:10:10.414022', '2023-01-27 02:10:10.414022', NULL, 'Fluent In 3 Months');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1329, 'هی ویپل، این را فشار بده!', 'راهنمای کلاسیک برای ایجاد تبلیغات عالی', 'راهنمای کلاسیک برای ایجاد تبلیغات عالی', 13, 7, 'book', 'f', '<p><em>هی ویپل، این را فشار بده! </em>برای کسانی که دهه‌ها در این کسب‌وکار بوده‌اند، و برای تازه‌واردها، و برای هرکسی که شیفته آن چیزی است که وقتی خلاقیت با تجارت روبرو می‌شود چه اتفاقی می‌افتد، تبدیل شده است. عنوان اشاره ای بی احترامانه به یک کمپین غیر متعارف دهه 1970 برای دستمال توالت شارمین است که یک کارمند مزاحم مغازه به نام آقای ویپل را نشان می داد که نمی توانست از فشار دادن محصول خودداری کند. این روش بینش صادقانه و عملی سالیوان را در مورد فرآیند خلاقانه تبلیغاتی که گاهاً دیوانه کننده است، تنظیم می کند.</p>', '2014-12-04 00:00:00', 4, 15, 'https://images.blinkist.io/images/books/547dbb283166390009a30200/1_1/470.jpg', '/en/books/hey-whipple-squeeze-this-en/purchase', 'هی-ویپل،-این-را-فشار-بده!', '2023-01-27 02:10:18.178572', '2023-01-27 02:10:18.178572', NULL, 'Hey Whipple, Squeeze This!');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1330, 'اصل پیتر', 'چرا همه چیز همیشه اشتباه است', 'چرا همه چیز همیشه اشتباه است', 11, 5, 'book', 't', '<p><em>اصل پیتر</em> (1969) توضیح می‌دهد که چرا احساس می‌کنید در محل کار توسط بی‌کفایتی احاطه شده‌اید – شما هستید! این کتاب پرخاشگر تبلیغاتی را برای آنچه واقعاً هستند نشان می دهد: پیشرفت به سطح نهایی ناتوانی ما. این پلک‌ها به ما کمک می‌کنند تا بفهمیم سلسله‌مراتب شرکتی واقعاً چگونه عمل می‌کند، و همچنین توصیه‌هایی در مورد نحوه برخورد با ناتوانی خودمان ارائه می‌دهد.</p>', '2015-07-08 00:00:00', 4, 28, 'https://images.blinkist.io/images/books/559bc6f13966610007800000/1_1/470.jpg', '/en/books/the-peter-principle-en/purchase', 'اصل-پیتر', '2023-01-27 02:10:25.955314', '2023-01-27 02:10:25.955314', NULL, 'The Peter Principle');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1331, 'زمین غیر قابل سکونت', 'داستانی از آینده', 'داستانی از آینده', 32, 10, 'book', 't', '<p><em>زمین غیرقابل سکونت </em> (۲۰۱۹) خلاصه‌ای وحشتناک از وحشت‌هایی است که در انتظار جهانی همیشه گرم‌تر است. والاس ولز با درخشش شاعرانه از آخرین تحقیقات در علم آب و هوا استفاده می کند تا یک هشدار نهایی زیبا به ما بدهد. آتش‌سوزی‌های جنگلی فراری، شهرهای زیر آب، هوای آلوده و همه‌گیری‌های جهانی - این فجایع و سایر فجایع ناشی از آب و هوا نه تنها در آینده نزدیک در انتظار شماست، بلکه در برخی موارد قبلاً نیز رسیده است.</p>', '2019-03-22 00:00:00', 5, 122, 'https://images.blinkist.io/images/books/5c90fb776cee070007feb895/1_1/470.jpg', '/en/books/the-uninhabitable-earth-en/purchase', 'زمین-غیر-قابل-سکونت', '2023-01-27 02:10:33.968999', '2023-01-27 02:10:33.968999', NULL, 'The Uninhabitable Earth');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1332, 'تماس گرفتن', 'استراتژی ساده ای که برای گسترش شبکه و افزایش نفوذ خود به آن نیاز دارید', 'استراتژی ساده ای که برای گسترش شبکه و افزایش نفوذ خود به آن نیاز دارید', 16, 6, 'book', 't', '<p><em>Reach Out </em>(2017) توسط Molly Beck کتابچه راهنمای ساده ای است که به شما کمک می کند تا اهداف شغلی خود را از طریق ارتباط با مردم و گسترش شبکه خود پیش ببرید. در این کتاب، بک خواننده را از طریق بایدها و نبایدهای رسیدن به مخاطب راهنمایی می‌کند و نمونه‌های مفیدی از نحوه بهترین استفاده از این استراتژی ارائه می‌دهد.</p>', '2018-08-01 00:00:00', 4, 18, 'https://images.blinkist.io/images/books/5b611d59b238e10006c07c29/1_1/470.jpg', '/en/books/reach-out-en/purchase', 'تماس-گرفتن', '2023-01-27 02:10:41.222218', '2023-01-27 02:10:41.222218', NULL, 'Reach Out');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1333, 'بیوگرافی قبل از خواب: من', 'زندگینامه', 'زندگینامه', 32, 6, 'book', 't', '<p><strong>به روایت مارستون یورک</strong></p>
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1334, 'هوش هیجانی برای مدیران پروژه', 'مهارت های مردمی که برای دستیابی به نتایج برجسته نیاز دارید', 'مهارت های مردمی که برای دستیابی به نتایج برجسته نیاز دارید', 14, 6, 'book', 't', '<p><em>هوش عاطفی برای مدیران پروژه </em>(2007) بر اساس نوشته های دانیل گولمن است که اصول <em>هوش عاطفی</em> را توسعه داده است. هوش عاطفی در بسیاری از جنبه‌های زندگی بسیار مهم است و در این نگاه آنتونی مرسینو اصول گولمن را به‌طور خاص بر اساس نیازهای مدیران پروژه تنظیم می‌کند.</p>', '2016-09-15 00:00:00', 4, 116, 'https://images.blinkist.io/images/books/57d65c6b08c9270003b191be/1_1/470.jpg', '/en/books/emotional-intelligence-for-project-managers-en/purchase', 'هوش-هیجانی-برای-مدیران-پروژه', '2023-01-27 02:10:57.013537', '2023-01-27 02:10:57.013537', NULL, 'Emotional Intelligence for Project Managers');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1335, 'فردا را امروز سازماندهی کنید', 'هشت راه برای آموزش مجدد ذهن برای بهینه سازی عملکرد در محل کار و زندگی', 'هشت راه برای آموزش مجدد ذهن برای بهینه سازی عملکرد در محل کار و زندگی', 18, 8, 'book', 't', '<p><em>امروز سازماندهی کنید</em> (2015) راهنمای قطعی برای دستیابی به یک شغل موفق و زندگی کامل است. این پلک‌ها اطلاعات ارزشمندی را در اختیار شما قرار می‌دهند و ابزارهایی را در اختیار شما قرار می‌دهند تا قدرت ذهن خود را باز کنید، اعتماد به نفس خود را افزایش دهید و به سازنده‌ترین خود تبدیل شوید.</p>', '2016-04-18 00:00:00', 5, 189, 'https://images.blinkist.io/images/books/5713a5965236f20007c16f42/1_1/470.jpg', '/en/books/organize-tomorrow-today-en/purchase', 'فردا-را-امروز-سازماندهی-کنید', '2023-01-27 02:11:05.049476', '2023-01-27 02:11:05.049476', NULL, 'Organize Tomorrow Today');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1336, 'بزرگ شدن خدا', 'راهنمای یک مبتدی', 'راهنمای یک مبتدی', 24, 8, 'book', 't', '<p><em>Outgrowing God</em> (2019) به ما نشان می دهد که چرا همه ما باید بی خدا باشیم. ریچارد داوکینز با افشای اینکه چگونه کتاب‌های مقدسی مانند کتاب مقدس مملو از نادرستی و نادرستی تاریخی است، استدلال می‌کند که ما نمی‌توانیم این کتاب‌ها را جدی بگیریم، و همچنین نباید برای راهنمایی اخلاقی به آنها تکیه کنیم. برای توضیح این همه پیچیدگی و نامحتمل موجودات زنده، باید به علم و به طور خاص به روند تکامل نگاه کنیم. این تکامل از طریق انتخاب طبیعی است که ما و سایر موجودات زنده را از پایین به بالا به وجود آورده است. </p>', '2019-11-05 00:00:00', 4, 284, 'https://images.blinkist.io/images/books/5dbc49c06cee070007541467/1_1/470.jpg', '/en/books/outgrowing-god-en/purchase', 'بزرگ-شدن-خدا', '2023-01-27 02:11:10.807126', '2023-01-27 02:11:10.807126', NULL, 'Outgrowing God');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1337, 'طعم Ottolenghi', 'یک کتاب آشپزی', 'یک کتاب آشپزی', 25, 8, 'book', 't', '<p><em>Ottolenghi Flavor </em>(2020) به آشپزهای خانگی نشان می دهد که چگونه طعم های بزرگ ایجاد کنند. این دستورالعمل در مورد اینکه کدام روش های پخت و پز بهترین نتایج را در آشپزخانه های گیاهی می گیرند، ارائه می دهد. برای جفت کردن مواد مختلف و انتخاب بهترین محصول توصیه می کند. و الهام بخش برای ایجاد غذاهای هیجان انگیز و خوش طعم است.</p>', '2020-12-25 00:00:00', 4, 18, 'https://images.blinkist.io/images/books/5fe1af936cee070007f8656d/1_1/470.jpg', '/en/books/ottolenghi-flavor-en/purchase', 'طعم-Ottolenghi', '2023-01-27 02:11:18.473647', '2023-01-27 02:11:18.473647', NULL, 'Ottolenghi Flavor');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1338, 'راه ذن', 'تاریخچه و اصول اصلی فلسفه شرقی ذن', 'تاریخچه و اصول اصلی فلسفه شرقی ذن', 23, 8, 'book', 't', '<p><em>راه ذن </em>(1957) اثری کلاسیک است که ریشه های تاریخی و اصول اصلی ذن بودیسم را بیان می کند. دنیای ما با سرعتی سرسام آور در حال تغییر است و اغلب به نظر می رسد که قوانین قدیمی به محض اینکه به آنها عادت کنیم دیگر اعمال نمی شوند. فلسفه شرقی ذن می تواند به ما کمک کند سکون ذهنی و شادی را در عدم اطمینان پیدا کنیم که به شدت به آن نیاز داریم.</p>', '2020-04-23 00:00:00', 5, 541, 'https://images.blinkist.io/images/books/5e9e1baa6cee070006128b32/1_1/470.jpg', '/en/books/the-way-of-zen-en/purchase', 'راه-ذن', '2023-01-27 02:11:23.797704', '2023-01-27 02:11:23.797704', NULL, 'The Way of Zen');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1339, 'همیشه سبز', 'وفاداری پایدار مشتری را پرورش دهید که باعث رونق کسب و کار شما می شود', 'وفاداری پایدار مشتری را پرورش دهید که باعث رونق کسب و کار شما می شود', 21, 9, 'book', 't', '<p><em>Evergreen </em>(2015) درباره تازه نگه داشتن کسب و کار شما و جلوگیری از رکود است که بقای آن را تهدید می کند. فلمینگ فلسفه ای را ترسیم می کند که مشتریان را در مرکز استراتژی شرکت قرار می دهد، خرد تجاری متعارف را به چالش می کشد و توصیه های ملموسی برای ایجاد سودآوری بلندمدت ارائه می دهد.</p>', '2015-05-21 00:00:00', 4, 24, 'https://images.blinkist.io/images/books/555b3bd56135330007ae0000/1_1/470.jpg', '/en/books/evergreen-en/purchase', 'همیشه-سبز', '2023-01-27 02:11:30.972201', '2023-01-27 02:11:30.972201', NULL, 'Evergreen');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1340, 'تولید مدل کسب و کار', 'کتاب راهنما برای بینندگان، تغییر دهندگان بازی و چالش‌گران', 'کتاب راهنما برای بینندگان، تغییر دهندگان بازی و چالش‌گران', 17, 7, 'book', 't', '<p><em>تولید مدل کسب و کار </em>(2010) راهنمای جامعی برای ایجاد مدل های کسب و کار نوآورانه است. از همدلی و ارتباط با مشتریان گرفته تا الهام گرفتن برای محصولات و یادگیری از برخی از پلتفرم‌های تغییردهنده بازی امروزی، این پلک‌ها به شما کمک می‌کند تا تفکر تجاری خود را شروع کنید.</p>', '2017-01-13 00:00:00', 4, 76, 'https://images.blinkist.io/images/books/58761d1a9acc4a0004cf71a7/1_1/470.jpg', '/en/books/business-model-generation-en/purchase', 'تولید-مدل-کسب-و-کار', '2023-01-27 02:11:38.478471', '2023-01-27 02:11:38.478471', NULL, 'Business Model Generation');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1415, 'راه ویرجین', 'هر آنچه در مورد رهبری می دانم', 'هر آنچه در مورد رهبری می دانم', 19, 7, 'book', 't', '<p><em>راه ویرجین</em> (2015) اسرار رهبری ریچارد برانسون را بررسی می کند. این پلک ها با تکیه بر حکایات دنیای واقعی از چندین دهه تجربه نویسنده و شیوه های عجیب و غریب انجام تجارت، بینشی از یکی از خلاق ترین ذهن های جهان است.</p>', '2019-06-17 00:00:00', 4, 391, 'https://images.blinkist.io/images/books/5d05687d6cee0700091f7dd6/1_1/470.jpg', '/en/books/the-virgin-way-en/purchase', 'راه-ویرجین', '2023-01-27 02:20:55.88193', '2023-01-27 02:20:55.88193', NULL, 'The Virgin Way');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1341, 'شادی در کار', 'سازماندهی زندگی حرفه ای خود', 'سازماندهی زندگی حرفه ای خود', 21, 8, 'book', 't', '<p><em>Joy at Work</em> (2020) روش محبوب و متحول کننده زندگی KonMari را برای مرتب کردن خانه شما استفاده می کند و آن را در محل کار شما اعمال می کند. هدف این رویکرد جدید تمیز کردن و سازماندهی نه تنها میز و قفسه‌های کتاب، بلکه فضای ذخیره‌سازی رایانه و صندوق ورودی ایمیل شما است. مثل همیشه، استفاده از روش KonMari شما را به یافتن شادی و کشف مجدد آنچه واقعاً در زندگی شما مهم است نزدیک‌تر می‌کند.</p>', '2020-05-08 00:00:00', 4, 122, 'https://images.blinkist.io/images/books/5eb425e56cee070006697f4d/1_1/470.jpg', '/en/books/joy-at-work-en/purchase', 'شادی-در-کار', '2023-01-27 02:11:46.198558', '2023-01-27 02:11:46.198558', NULL, 'Joy at Work');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1342, 'معنی ازدواج', 'مواجهه با پیچیدگی های تعهد با حکمت خداوند', 'مواجهه با پیچیدگی های تعهد با حکمت خداوند', 22, 7, 'book', 't', '<p><em>معنای ازدواج </em>(2011) مدیتیشنی است در مورد ازدواج در عصری که نرخ طلاق سرسام آور است و شک و تردید فزاینده ای در مورد اینکه زندگی تک همسری می تواند خوشبختی واقعی را به ارمغان بیاورد. کشیش تیموتی کلر و الهی‌دان کتی کلر می‌پرسند چه مشکلی پیش آمده است - چرا بسیاری از زوج‌ها در انجام عهد خود مردد هستند و بسیاری دیگر آن را در ازدواج خود ترک می‌کنند؟ پاسخ نویسندگان: ما بیش از حد ایده آل گرا هستیم، معیارهای غیرممکن تعیین می کنیم و معنای واقعی ازدواج را فراموش کرده ایم - یاد می گیریم هر روز دوباره دوست بداریم، درسی در قلب آموزه های کتاب مقدس.</p>', '2021-01-16 00:00:00', 4, 80, 'https://images.blinkist.io/images/books/5ff831276cee070007f83665/1_1/470.jpg', '/en/books/the-meaning-of-marriage-en/purchase', 'معنی-ازدواج', '2023-01-27 02:11:53.833884', '2023-01-27 02:11:53.833884', NULL, 'The Meaning of Marriage');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1343, 'تغذیه عمیق', 'چرا ژن های شما به غذای سنتی نیاز دارند؟', 'چرا ژن های شما به غذای سنتی نیاز دارند؟', 16, 7, 'book', 't', '<p><em>تغذیه عمیق</em> (2008) در مورد رژیم های غذایی مدرن و چگونگی بیمار کردن آنها در افراد است. این پلک‌ها خطر مواد غذایی تولید شده در صنعت را توضیح می‌دهند، چه بلایی سر بدن ما می‌آورند و چگونه می‌توانیم به روش قبلی غذا خوردن برگردیم که سال‌های آینده ما را سالم‌تر نگه می‌دارد.</p>', '2017-07-21 00:00:00', 4, 107, 'https://images.blinkist.io/images/books/596caa5fb238e1000517dcd8/1_1/470.jpg', '/en/books/deep-nutrition-en/purchase', 'تغذیه-عمیق', '2023-01-27 02:12:00.996292', '2023-01-27 02:12:00.996292', NULL, 'Deep Nutrition');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1344, 'نتایج رادیکال', 'چگونه تیم های خارق العاده ای ایجاد کنیم که نتایج ملموسی به دست آورند', 'چگونه تیم های خارق العاده ای ایجاد کنیم که نتایج ملموسی به دست آورند', 20, 7, 'book', 't', '<p><em>نتایج رادیکال</em> (2019) راه‌هایی را برای تبدیل استراتژی‌های سطح بالا به نتایج عالی برای کسب و کار شما بررسی می‌کند. با آشکار کردن عدم ارتباط مشترک بین مدیران تصمیم‌گیر و کارکنان خط مقدم، به بررسی این موضوع می‌پردازد که چگونه همه سطوح یک سازمان می‌توانند با یکدیگر بهتر کار کنند تا نتایج را به‌طور اساسی بهبود بخشند. </p>', '2019-10-17 00:00:00', 4, 23, 'https://images.blinkist.io/images/books/5da5cd8a6cee0700074e3334/1_1/470.jpg', '/en/books/radical-outcomes-en/purchase', 'نتایج-رادیکال', '2023-01-27 02:12:08.183869', '2023-01-27 02:12:08.183869', NULL, 'Radical Outcomes');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1345, 'هفده تناقض و پایان سرمایه داری', 'خطرات سرمایه داری', 'خطرات سرمایه داری', 18, 10, 'book', 'f', '<p><em>هفده تناقض و پایان سرمایه داری</em> (2014) تضادهای ذاتی و گاه خطرناک سرمایه را آشکار می کند. این کتاب از طریق توضیح عملکرد درونی سرمایه، به بررسی این موضوع می‌پردازد که چرا موتور اقتصادی سرمایه‌داری ممکن است دچار لکنت شود، و چرا گاهی اوقات در آستانه فروپاشی به نظر می‌رسد.</p>', '2015-08-10 00:00:00', 4, 23, 'https://images.blinkist.io/images/books/55c7c0ff6664360007010000/1_1/470.jpg', '/en/books/seventeen-contradictions-and-the-end-of-capitalism-en/purchase', 'هفده-تناقض-و-پایان-سرمایه-داری', '2023-01-27 02:12:14.793015', '2023-01-27 02:12:14.793015', NULL, 'Seventeen Contradictions and the End of Capitalism');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1346, 'تا پایان وقت', 'ذهن، ماده و جستجوی ما برای معنا در جهان در حال تکامل', 'ذهن، ماده و جستجوی ما برای معنا در جهان در حال تکامل', 28, 9, 'book', 't', '<p><em>تا پایان زمان</em> (2020) یک نگاه غیررسمی و قابل دسترس به عالی ترین موضوعات تمام دوران است: زمان، جهان، و تلاش بی پایان بشریت برای یافتن معنا. فیزیکدان برایان گرین از همان ابتدا شروع می کند - انفجار بزرگی که تمام این منظره دیوانه کننده را به راه انداخت - سپس به بررسی تکامل فرهنگ بشری از مذهب، زبان و هنر می پردازد. در نهایت، او کوچک‌نمایی می‌کند تا بررسی کند که جهان چه اتفاقی می‌افتد، و اینکه آیا ممکن است زندگی دوباره ظهور کند یا خیر.</p>', '2020-05-23 00:00:00', 5, 89, 'https://images.blinkist.io/images/books/5ec453196cee070006b2fc83/1_1/470.jpg', '/en/books/until-the-end-of-time-en/purchase', 'تا-پایان-وقت', '2023-01-27 02:12:22.31932', '2023-01-27 02:12:22.31932', NULL, 'Until the End of Time');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1347, 'چگونه هلو بخوریم', 'منوها، داستان ها و مکان ها.', 'منوها، داستان ها و مکان ها.', 27, 12, 'book', 't', '<p><em>How to Eat a Peach</em> (2018) بخشی از کتاب آشپزی، بخشی زندگینامه و بخشی سفرنامه است. این پلک ها مملو از ایده هایی برای منوهای خوشمزه و درست کردن یک کوکتل بی ارزش، همه چیزهایی را که باید در مورد میزبانی یک مهمانی شام خاطره انگیز بدانید را به شما می گوید. آنها همچنین به شما نگاهی اجمالی به ذهن آشپزی می دهند که در هنر داستان گویی از طریق غذا تسلط یافته است و شما را به یک تور آشپزی در مکان هایی می برند که بیشترین الهام را برای او به همراه داشته است. </p>', '2020-05-23 00:00:00', 4, 26, 'https://images.blinkist.io/images/books/5ec44ee26cee070006b2fc80/1_1/470.jpg', '/en/books/how-to-eat-a-peach-en/purchase', 'چگونه-هلو-بخوریم', '2023-01-27 02:12:29.34539', '2023-01-27 02:12:29.34539', NULL, 'How to Eat a Peach');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1348, 'تصویر بزرگ', 'درباره سرچشمه های زندگی، معنا و خود جهان', 'درباره سرچشمه های زندگی، معنا و خود جهان', 18, 7, 'book', 't', '<p><em>تصویر بزرگ </em>(2016) نگاهی بلندپروازانه به دنیایی است که ما می شناسیم و اینکه چگونه می توان از تفکر علمی برای درک بیشتر آن استفاده کرد. این کتاب با بررسی دقیق منشأ حیات، آگاهی و خود جهان، راهی قیاسی برای بررسی چالش‌برانگیزترین پرسش‌های فلسفه، فیزیک و زیست‌شناسی به خوانندگان می‌دهد.</p>', '2017-09-29 00:00:00', 4, 293, 'https://images.blinkist.io/images/books/59c8ffeab238e100052dbeb1/1_1/470.jpg', '/en/books/the-big-picture-en/purchase', 'تصویر-بزرگ', '2023-01-27 02:12:37.098655', '2023-01-27 02:12:37.098655', NULL, 'The Big Picture');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1349, 'راهبی که فراری خود را فروخت', 'راهنمای استفاده از شیوه های باستانی برای بهبود کیفیت زندگی و دستیابی به اهدافتان', 'راهنمای استفاده از شیوه های باستانی برای بهبود کیفیت زندگی و دستیابی به اهدافتان', 15, 7, 'book', 't', '<p><em>راهبی که فراری خود را فروخت</em> (1997) راه حلی برای مشکلات زندگی مدرن ارائه می دهد. یک افسانه، داستان روشنگری وکیل سابق جولیان مانتل را بیان می کند و توصیه هایی در مورد چگونگی زندگی شادتر، پر ارزش تر و روشن تر می دهد.</p>', '2017-09-01 00:00:00', 5, 577, 'https://images.blinkist.io/images/books/59a2d8e4b238e10005eeb756/1_1/470.jpg', '/en/books/the-monk-who-sold-his-ferrari-en/purchase', 'راهبی-که-فراری-خود-را-فروخت', '2023-01-27 02:12:42.534607', '2023-01-27 02:12:42.534607', NULL, 'The Monk Who Sold His Ferrari');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1350, 'آماده آتش هدف!', 'راهنمای عملی برای تعیین و دستیابی به اهداف', 'راهنمای عملی برای تعیین و دستیابی به اهداف', 23, 8, 'book', 't', '<p><em>آتش هدف آماده! </em>(2014) یک راهنمای گام به گام برای تعیین و دستیابی به اهداف شخصی و حرفه ای است. اگر می خواهید کارهای بیشتری در زندگی انجام دهید اما مطمئن نیستید از کجا شروع کنید، این یک نقطه شروع قابل دسترسی برای یادگیری هنر تبدیل رویاها به واقعیت است.</p>', '2021-01-04 00:00:00', 5, 88, 'https://images.blinkist.io/images/books/5fdb1c586cee0700073571b7/1_1/470.jpg', '/en/books/ready-aim-fire-en/purchase', 'آماده-آتش-هدف!', '2023-01-27 02:12:49.632849', '2023-01-27 02:12:49.632849', NULL, 'Ready Aim Fire!');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1351, 'ذهن کنجکاو', 'راز زندگی بزرگتر', 'راز زندگی بزرگتر', 14, 7, 'book', 't', '<p><em>ذهن کنجکاو</em> (2015) یک ویژگی حیاتی را بررسی می کند که بسیاری از ما به اندازه کافی برای آن ارزش قائل نیستیم: کنجکاوی. این پلک‌ها اهمیت حیاتی کنجکاوی را توضیح می‌دهند و راه‌هایی را که می‌تواند روابط شما با کارمندان، مشتریان یا عزیزانتان را بهبود بخشد - و حتی به شما کمک می‌کند تا بر ترس‌هایتان غلبه کنید.</p>', '2015-06-19 00:00:00', 4, 31, 'https://images.blinkist.io/images/books/558072946232320007800000/1_1/470.jpg', '/en/books/a-curious-mind-en/purchase', 'ذهن-کنجکاو', '2023-01-27 02:12:57.017719', '2023-01-27 02:12:57.017719', NULL, 'A Curious Mind');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1352, 'انضباط برابر با آزادی است', 'راهنمای فیلد', 'راهنمای فیلد', 23, 7, 'book', 't', '<p><em>انضباط برابر با آزادی </em>(2020) راهنمای رشته شما برای هنر خود انضباطی است. این نشان می‌دهد که چه کاری باید انجام دهید تا پتانسیل کامل خود را برآورده کنید - و اینکه چرا منضبط بودن شما را آزاد می‌کند. </p>', '2021-06-28 00:00:00', 4, 459, 'https://images.blinkist.io/images/books/60d323756cee070007bee646/1_1/470.jpg', '/en/books/discipline-equals-freedom-en/purchase', 'انضباط-برابر-با-آزادی-است', '2023-01-27 02:13:04.593179', '2023-01-27 02:13:04.593179', NULL, 'Discipline Equals Freedom');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1353, 'پروژه مزرعه حیوانات', 'سفری تصادفی به دنیای مخفی کشاورزی و حقیقت در مورد غذای ما', 'سفری تصادفی به دنیای مخفی کشاورزی و حقیقت در مورد غذای ما', 23, 11, 'book', 't', '<p><em>Project Animal Farm</em> (2015) همه چیز درباره یکی از مضرترین صنایع زمان ما است: تولید انبوه مدرن گوشت، تخم مرغ و شیر. به بررسی شرایط وحشتناکی که حیوانات مزرعه در آن نگهداری می شوند و تأثیرات خطرناک کشاورزی کارخانه بر انسان، حیوانات و محیط زیست می پردازد.</p>', '2015-12-31 00:00:00', 3, 10, 'https://images.blinkist.io/images/books/5681b981704a880007000055/1_1/470.jpg', '/en/books/project-animal-farm-en/purchase', 'پروژه-مزرعه-حیوانات', '2023-01-27 02:13:12.762677', '2023-01-27 02:13:12.762677', NULL, 'Project Animal Farm');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1354, 'بازی با FIRE (بازنشستگی زودهنگام استقلال مالی)', 'چقدر برای آزادی مالی پیش می روید؟', 'چقدر برای آزادی مالی پیش می روید؟', 18, 5, 'book', 't', '<p><em>بازی با آتش </em>(2019) نگاهی به جنبش رو به رشد معروف به FIRE یا استقلال مالی، بازنشستگی زودهنگام دارد. با شرح مفصلی از سفر تغییر دهنده زندگی خود نویسنده و نمونه هایی از جانبازان مختلف FIRE، راه هایی را نشان می دهد که از طریق آنها می توانید عادت های خرج کردن و سرمایه گذاری خود را تغییر دهید تا به علایق خود ادامه دهید و زندگی معنادارتری داشته باشید.</p>', '2019-04-11 00:00:00', 4, 371, 'https://images.blinkist.io/images/books/5cac57436cee070008bd5436/1_1/470.jpg', '/en/books/playing-with-fire-financial-independence-retire-early-en/purchase', 'بازی-با-FIRE-(بازنشستگی-زودهنگام-استقلال-مالی)', '2023-01-27 02:13:20.088041', '2023-01-27 02:13:20.088041', NULL, 'Playing with FIRE (Financial Independence Retire Early)');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1355, 'کنار آمدن', 'نحوه کار با هر کسی (حتی افراد دشوار)', 'نحوه کار با هر کسی (حتی افراد دشوار)', 7, 3, 'book', 't', '<p><em>Getting Along </em>(2022) اهمیت تعاملات در محل کار و اثرات آن بر بهره وری و خلاقیت را توصیف می کند.</p>', '2022-11-02 00:00:00', 3, 180, 'https://images.blinkist.io/images/books/6360f7a0958fe9000879ec52/1_1/470.jpg', '/en/books/getting-along-en/purchase', 'کنار-آمدن', '2023-01-27 02:13:27.645602', '2023-01-27 02:13:27.645602', NULL, 'Getting Along');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1356, 'اقتصاد متشکرم', 'چگونه رسانه های اجتماعی کسب و کار را تغییر دادند و این برای شرکت شما چه معنایی دارد.', 'چگونه رسانه های اجتماعی کسب و کار را تغییر دادند و این برای شرکت شما چه معنایی دارد.', 18, 8, 'book', 't', '<p><em></em> <em>متشکرم</em> <em>شما</em> <em>اقتصاد</em> (2011) توضیح می‌دهد که چگونه ظهور رسانه‌های اجتماعی رابطه بین شرکت ها و مشتریان آنها این نشان می‌دهد که تعامل آنلاین برای شرکت‌هایی که می‌خواهند موفق شوند چقدر مهم است، و نکاتی را در مورد اینکه چگونه شرکت‌ها می‌توانند از رسانه‌های اجتماعی برای تأثیرگذاری بر تصویر عمومی خود در طول مسیر استفاده کنند، ارائه می‌دهد.</p>', '2014-08-12 00:00:00', 4, 34, 'https://images.blinkist.io/images/books/53ea0ffc31373700070e0000/1_1/470.jpg', '/en/books/the-thank-you-economy-en/purchase', 'اقتصاد-متشکرم', '2023-01-27 02:13:33.31276', '2023-01-27 02:13:33.31276', NULL, 'The Thank You Economy');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1357, 'کتاب مارماهی ها', 'شیفتگی همیشگی ما با مرموزترین موجود در دنیای طبیعی', 'شیفتگی همیشگی ما با مرموزترین موجود در دنیای طبیعی', 22, 7, 'book', 't', '<p><em>کتاب مارماهی ها</em> (2020) خواننده را به یک اودیسه جانورشناسی می برد که هزاران سال را در بر می گیرد. این داستان مارماهی است - موجودی که بشریت را با چرخه زندگی عجیب و پیچیده خود مجذوب خود کرده است. دانشمندان بی‌شماری کار خود را وقف معمای این ماهی کرده‌اند، ماهی که در طول زندگی خود دچار دگرگونی‌های متعددی شده و مهاجرت طاقت‌فرسا به آن سوی اقیانوس اطلس را برای تولید مثل متحمل شده است. اما ثابت شده است که مارماهی موجودی دست نیافتنی است و هنوز رازهای زیادی در مورد زندگی آن وجود دارد که به نظر می رسد قصد دارد آنها را حفظ کند.</p>', '2020-12-20 00:00:00', 5, 19, 'https://images.blinkist.io/images/books/5fd34b6c6cee07000639bf7c/1_1/470.jpg', '/en/books/the-book-of-eels-en/purchase', 'کتاب-مارماهی-ها', '2023-01-27 02:13:41.764691', '2023-01-27 02:13:41.764691', NULL, 'The Book of Eels');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1358, 'از جایی که هستید شروع کنید', 'راهنمای زندگی مشفقانه', 'راهنمای زندگی مشفقانه', 16, 7, 'book', 't', '<p><em>از جایی که هستید شروع کنید</em> (1994) یک راهنمای روشنگر برای باز کردن قلب و ذهن و یادگیری احساس شادی بیشتر در پوست است. شیوه هایی را کشف کنید که آرامش و آرامش را برای راهبان و راهبه های بودایی به ارمغان می آورد، و همچنین فلسفه ای که مردم را در مسیر نیروانا قرار می دهد. این توصیه ای نیست که چه بخور و شمع بخریم. این به شما نشان می دهد که چگونه به عمق خود نگاه کنید تا با شیاطین خود مقابله کنید و در نقاط ضعف خود قدرت پیدا کنید.</p>', '2017-11-30 00:00:00', 5, 100, 'https://images.blinkist.io/images/books/5a1e9e88b238e10007f56655/1_1/470.jpg', '/en/books/start-where-you-are-en/purchase', 'از-جایی-که-هستید-شروع-کنید', '2023-01-27 02:13:47.499149', '2023-01-27 02:13:47.499149', NULL, 'Start Where You Are');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1359, 'پایان بیماری', 'بدن چگونه کار می کند و «سلامتی واقعاً به چه معناست»', 'بدن چگونه کار می کند و «سلامتی واقعاً به چه معناست»', 13, 6, 'book', 't', '<p><em>پایان بیماری</em> (2012) همه چیز درباره سلامتی است، اینکه ما چگونه به آن نگاه می کنیم، تصورات نادرست پیرامون آن کجاست و چگونه می توانیم بهترین احساس را داشته باشیم. این پلک‌ها مدلی متفاوت برای سلامت واقعی به همراه توصیه‌های عملی در مورد اینکه چگونه سالم‌ترین خود باشید، ارائه می‌دهد.</p>', '2018-04-10 00:00:00', 4, 36, 'https://images.blinkist.io/images/books/5acbf8fcb238e1000747de61/1_1/470.jpg', '/en/books/the-end-of-illness-en/purchase', 'پایان-بیماری', '2023-01-27 02:13:54.909619', '2023-01-27 02:13:54.909619', NULL, 'The End of Illness');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1360, 'رهبری زبان است', 'قدرت پنهان آنچه می گویید - و آنچه نمی کنید', 'قدرت پنهان آنچه می گویید - و آنچه نمی کنید', 29, 10, 'book', 't', '<p><em>رهبری زبان است</em> (2020) کتاب بازی برای مدیریت موفق تیم است. این کتاب که توسط یک کاپیتان سابق نیروی دریایی ایالات متحده نوشته شده است، به رهبران می آموزد که چگونه می توانند زبان و طرز فکر خود را برای بهبود تصمیم گیری، توانمندسازی کارگران و دستیابی به نتایج بهتر تغییر دهند.</p>', '2020-10-29 00:00:00', 5, 142, 'https://images.blinkist.io/images/books/5f929fe26cee070007038df2/1_1/470.jpg', '/en/books/leadership-is-language-en/purchase', 'رهبری-زبان-است', '2023-01-27 02:14:02.135699', '2023-01-27 02:14:02.135699', NULL, 'Leadership Is Language');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1361, 'زندگی پنهان درختان', 'چه احساسی دارند، چگونه با هم ارتباط برقرار می کنند - اکتشافاتی از یک دنیای مخفی', 'چه احساسی دارند، چگونه با هم ارتباط برقرار می کنند - اکتشافاتی از یک دنیای مخفی', 21, 9, 'book', 't', '<p>درختان در چرخه های پیچیده بی شماری درگیر هستند و دائماً برای آب، نور و بقای خود مبارزه می کنند. این مبارزه منجر به توانایی‌های شگفت‌انگیزی شده است: درختان با یکدیگر ارتباط برقرار می‌کنند، به یکدیگر کمک می‌کنند، با قارچ‌ها و موجودات دیگر همکاری می‌کنند، خاطرات دارند و حتی نسخه‌ای از اینترنت را توسعه داده‌اند!</p>', '2016-09-13 00:00:00', 5, 337, 'https://images.blinkist.io/images/books/57d4615cb20bac00031a0d2d/1_1/470.jpg', '/en/books/the-hidden-life-of-trees-en/purchase', 'زندگی-پنهان-درختان', '2023-01-27 02:14:07.455228', '2023-01-27 02:14:07.455228', NULL, 'The Hidden Life of Trees');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1362, 'قدرت امروز', 'راهنمای روشنگری معنوی', 'راهنمای روشنگری معنوی', 19, 9, 'book', 't', '<p><em></em> <em>قدرت</em> <em></em> <em>اکنون</em> (1997) روش خاصی را برای پایان دادن به رنج و دستیابی ارائه می دهد. آرامش درونی، زندگی کامل در زمان حال و جدا کردن خود از ذهن. این کتاب همچنین به شما می آموزد که خود را از "من" خود جدا کنید - بخشی از ذهن که به دنبال کنترل بر تفکر و رفتار شماست. این استدلال می کند که با انجام این کار می توانید یاد بگیرید که حال را بپذیرید، میزان درد را کاهش دهید، روابط خود را بهبود بخشید و به طور کلی از زندگی بهتری لذت ببرید.</p>', '2014-02-25 08:00:00', 5, 1012, 'https://images.blinkist.io/images/books/530c61aa34623100082d0000/1_1/470.jpg', '/en/books/the-power-of-now-en/purchase', 'قدرت-امروز', '2023-01-27 02:14:13.087761', '2023-01-27 02:14:13.087761', NULL, 'The Power of Now');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1363, 'بیداری شفقت در کار', 'قدرت آرامی که مردم و سازمان ها را ارتقا می دهد', 'قدرت آرامی که مردم و سازمان ها را ارتقا می دهد', 23, 8, 'book', 't', '<p><em>بیداری شفقت در محل کار</em> (2017) نقش شفقت را در محل کار در نظر می گیرد. روش‌هایی را که افراد و سازمان‌ها می‌توانند برای توسعه فرهنگ همدلی و شفقت استفاده کنند، نشان می‌دهد و نشان می‌دهد که چگونه افراد و شرکت‌ها به طور یکسان می‌توانند از چنین رویکردی بهره ببرند.</p>', '2018-08-02 00:00:00', 4, 25, 'https://images.blinkist.io/images/books/5b616d04b238e1000734cca9/1_1/470.jpg', '/en/books/awakening-compassion-at-work-en/purchase', 'بیداری-شفقت-در-کار', '2023-01-27 02:14:20.862846', '2023-01-27 02:14:20.862846', NULL, 'Awakening Compassion at Work');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1364, 'فلسفه برای زندگی', 'و سایر شرایط خطرناک', 'و سایر شرایط خطرناک', 21, 9, 'book', 't', '<p>این چشمک‌ها حکمت باستانی را به شما می‌آموزد که الهام‌بخش علم مدرن رفاه است. معلمان شما بزرگترین فیلسوفان باستان هستند، و هر درس سوالات و تکنیک هایی را نشان می دهد که می تواند به شما در مسیر زندگی خوب کمک کند. <em>فلسفه برای زندگی</em> در 19 کشور منتشر شده است و به عنوان <em>تایمز</em>کتاب سال 2013 انتخاب شد.</p>', '2014-04-01 13:53:56', 5, 301, 'https://images.blinkist.io/images/books/533afa2e3961370007170000/1_1/470.jpg', '/en/books/philosophy-for-life-en/purchase', 'فلسفه-برای-زندگی', '2023-01-27 02:14:28.490627', '2023-01-27 02:14:28.490627', NULL, 'Philosophy for Life');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1365, 'قدرت بالا', 'چگونه زنان باهوش در اقتصاد جدید پیروز می شوند', 'چگونه زنان باهوش در اقتصاد جدید پیروز می شوند', 23, 8, 'book', 't', '<p><em>Power Up</em> (2017) با توصیه‌های عملی و حکایات صمیمانه از پیشگامان دره سیلیکون، قصد دارد زنان را در محل کار توانمند کند. اگرچه این کتاب عمدتاً بر صنعت فناوری متمرکز است، اما یک کتاب راهنما است که می تواند برای شکستن سقف های شیشه ای در همه صنایع اعمال شود. ماگدالنا یشیل از در اختیار گرفتن انتخاب های شغلی گرفته تا هدایت سیاست های اداری جنسیتی، دعوتی برای اقدام برای زنانی که خواهان اعتبار مناسب برای کار سخت خود و دستمزد مناسب هستند، ارائه می دهد.</p>', '2018-08-03 00:00:00', 4, 13, 'https://images.blinkist.io/images/books/5b6180e8b238e1000734ccb8/1_1/470.jpg', '/en/books/power-up-en/purchase', 'قدرت-بالا', '2023-01-27 02:14:37.560685', '2023-01-27 02:14:37.560685', NULL, 'Power Up');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1366, 'چگونه با اسب پرواز کنیم', 'تاریخچه مخفی خلقت، اختراع و اکتشاف', 'تاریخچه مخفی خلقت، اختراع و اکتشاف', 13, 5, 'book', 't', '<p><em>How to Fly a Horse </em>(2015) در فرآیند خلقت تحقیق می کند و در نهایت متوجه می شود که خود این عمل بسیار عادی تر از آن چیزی است که ما اغلب فکر می کنیم. در واقع، با تکیه بر خلاقیت نسل‌های متفکر، هر کسی می‌تواند خلق کند، به شرطی که اراده و اراده لازم برای این کار را داشته باشد.</p>', '2015-03-27 00:00:00', 4, 15, 'https://images.blinkist.io/images/books/55103d0c376430000a000000/1_1/470.jpg', '/en/books/how-to-fly-a-horse-en/purchase', 'چگونه-با-اسب-پرواز-کنیم', '2023-01-27 02:14:45.233553', '2023-01-27 02:14:45.233553', NULL, 'How to Fly a Horse');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1367, 'تعقیب خورشید', 'علم جدید نور خورشید و چگونگی شکل دادن آن به بدن و ذهن ما', 'علم جدید نور خورشید و چگونگی شکل دادن آن به بدن و ذهن ما', 17, 6, 'book', 't', '<p><em>تعقیب خورشید</em> (2019) گزارشی جذاب از تأثیر خورشید بر زندگی روزمره ما ارائه می دهد. در طول تاریخ، انسان ها خورشید را پرستش کرده اند و از خواص ترمیمی و شفابخش آن استفاده کرده اند. همانطور که نویسنده لیندا گدس توضیح می دهد، علم به وضوح نشان می دهد که خورشید یکی از مهم ترین عناصر سلامت و تندرستی ما است.</p>', '2020-01-16 00:00:00', 4, 81, 'https://images.blinkist.io/images/books/5e1da9e06cee070008c98858/1_1/470.jpg', '/en/books/chasing-the-sun-en/purchase', 'تعقیب-خورشید', '2023-01-27 02:14:53.069765', '2023-01-27 02:14:53.069765', NULL, 'Chasing the Sun');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1368, 'عاقل تر', 'ریشه های علمی خرد، شفقت، و آنچه ما را خوب می کند', 'ریشه های علمی خرد، شفقت، و آنچه ما را خوب می کند', 19, 6, 'book', 't', '<p><em>Wiser </em>(2020) رویکرد علمی به خرد را با نکات عملی در مورد چگونگی رشد عاقل‌تر امروز ترکیب می‌کند. با تکیه بر دهه‌ها تحقیق و مطالعات پیشرفته، توضیحات و توصیه‌هایی را در تحقیقات خود در مورد شفقت، پیری، تصمیم‌گیری و موارد دیگر به همراه دارد.</p>', '2021-04-29 00:00:00', 5, 83, 'https://images.blinkist.io/images/books/60827f886cee0700072c7be4/1_1/470.jpg', '/en/books/wiser-en/purchase', 'عاقل-تر', '2023-01-27 02:15:01.261152', '2023-01-27 02:15:01.261152', NULL, 'Wiser');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1369, 'علم داستان سرایی', 'زیربنای علمی یک داستان خوب', 'زیربنای علمی یک داستان خوب', 21, 7, 'book', 't', '<p><em>علم داستان سرایی </em>(2019) به شما نشان می دهد که چگونه با استفاده از درس های روانشناسی و علوم اعصاب، داستانی جذاب بسازید. این پلک‌ها شما را در مراحل ایجاد روایتی راهنمایی می‌کنند که مخاطب شما را با دستکاری زیرکانه مغزشان جذب می‌کند. ویل استور از نشان دادن نحوه خلق یک شخصیت کاملاً معیوب گرفته تا توضیح قدرت برانگیختن جزئیات، عناصر مهمی را که در ساختن یک داستان عالی نقش دارند را آشکار می کند. </p>', '2019-10-31 00:00:00', 4, 363, 'https://images.blinkist.io/images/books/5db812496cee0700087a33e8/1_1/470.jpg', '/en/books/the-science-of-storytelling-en/purchase', 'علم-داستان-سرایی', '2023-01-27 02:15:09.093694', '2023-01-27 02:15:09.093694', NULL, 'The Science of Storytelling');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1370, 'تسلط عشق', 'راهنمای عملی هنر رابطه', 'راهنمای عملی هنر رابطه', 24, 8, 'book', 't', '<p><em>تسلط عشق </em> (1999) از حکایات و مثال‌هایی استفاده می‌کند تا فرضیات و دروغ‌های نادرستی را که مشخصه روابط بیشتر افراد است، نشان دهد. این راهنمای غلبه بر زخم‌های عاطفی و تبدیل روابط از جنگ‌های کنترل به ارتباطات هماهنگ مبتنی بر عشق، شادی و آزادی است.</p>', '2021-06-27 00:00:00', 4, 528, 'https://images.blinkist.io/images/books/60d321966cee070007bee626/1_1/470.jpg', '/en/books/the-mastery-of-love-en/purchase', 'تسلط-عشق', '2023-01-27 02:15:16.683301', '2023-01-27 02:15:16.683301', NULL, 'The Mastery of Love');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1371, 'خدا بزرگ نیست', 'چگونه دین همه چیز را مسموم می کند', 'چگونه دین همه چیز را مسموم می کند', 16, 9, 'book', 't', '<p><em>خدا بزرگ نیست </em>توسعه باورهای دینی را از ابتدایی‌ترین، ابتدایی‌ترین دوران بشر تا امروز دنبال می‌کند. این کتاب تلاش می‌کند پیامدهای خطرناک تفکر دینی و دلایلی را توضیح دهد که چرا ایمان هنوز وجود دارد. همچنین به توضیح این که چرا نظریه علمی و باور دینی هرگز نمی‌توانند با هم سازگار شوند کمک می‌کند.</p>', '2013-02-13 00:00:00', 4, 193, 'https://images.blinkist.io/images/books/5101706fe4b0991857b92610/1_1/470.jpg', '/en/books/god-is-not-great-en/purchase', 'خدا-بزرگ-نیست', '2023-01-27 02:15:22.423059', '2023-01-27 02:15:22.423059', NULL, 'God Is Not Great');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1372, 'خود حاکم', 'با حکمت قدرتمند وداها، اوپانیشادها و بهاگاواد گیتا، شادی و آزادی درونی خود را به دست آورید.', 'با حکمت قدرتمند وداها، اوپانیشادها و بهاگاواد گیتا، شادی و آزادی درونی خود را به دست آورید.', 23, 7, 'book', 't', '<p><em>Sovereign Self </em>(2020) وداها را بررسی می کند. این متون که بیش از 5000 سال پیش آشکار شدند، سنگ بنای هندوئیسم، بودیسم و ​​سنت های مذهبی بی شمار دیگری در شبه قاره هند هستند. مملو از بینش های معنوی، وداها حول یک سوال اصلی می چرخند: چگونه مطابق با ماهیت واقعی واقعیت زندگی کنیم؟ همانطور که در این پلک ها کشف خواهید کرد، پاسخ با کشف خود واقعی خود شروع می شود. </p>', '2021-07-24 00:00:00', 5, 350, 'https://images.blinkist.io/images/books/60f925176cee070008946156/1_1/470.jpg', '/en/books/sovereign-self-en/purchase', 'خود-حاکم', '2023-01-27 02:15:30.744432', '2023-01-27 02:15:30.744432', NULL, 'Sovereign Self');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1373, 'کل', 'بازاندیشی در علم تغذیه', 'بازاندیشی در علم تغذیه', 16, 7, 'book', 't', '<p><em>Whole</em>(2013) سوالات جالبی را مطرح می کند: آیا تغییر در رژیم غذایی ما می تواند دنیا را تغییر دهد؟ آیا کاهش مصرف گوشت ما و کره زمین را بسیار سالم تر می کند؟ شواهد مطمئناً نشان می‌دهند که رژیم غذایی مبتنی بر غذاهای کامل، گیاهان و سایر غذاهای کم پروتئین ممکن است کلید زندگی سالم‌تر برای همه باشد. بنابراین دریابید که چرا قدرت‌ها ترجیح می‌دهند شما به خوردن فست فود ادامه دهید.</p>', '2017-03-06 00:00:00', 4, 66, 'https://images.blinkist.io/images/books/58bc915fc7c53e00041d65c9/1_1/470.jpg', '/en/books/whole-en/purchase', 'کل', '2023-01-27 02:15:38.569125', '2023-01-27 02:15:38.569125', NULL, 'Whole');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1374, 'کوری ارادی', 'چرا ما بدیهیات را در معرض خطر نادیده می گیریم؟', 'چرا ما بدیهیات را در معرض خطر نادیده می گیریم؟', 15, 6, 'book', 't', '<p><em>کوری عمدی</em> (2011) درباره یک پدیده رایج است که از طریق آن انسان ها از واقعیت های ناراحت کننده جهان جلوگیری می کنند. این پلک‌ها توضیح می‌دهند که چگونه و چرا مردم اغلب نمی‌توانند آنچه را که در جلوی بینی‌شان قرار دارد ببینند و مراحلی را که همه ما می‌توانیم برای باز کردن چشمانمان به روی حقیقت انجام دهیم، تشریح می‌کند.</p>', '2017-10-11 00:00:00', 5, 21, 'https://images.blinkist.io/images/books/59dce465b238e10007fea0a5/1_1/470.jpg', '/en/books/willful-blindness-en/purchase', 'کوری-ارادی', '2023-01-27 02:15:44.54268', '2023-01-27 02:15:44.54268', NULL, 'Willful Blindness');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1375, 'چیز درست بعدی', 'یک تمرین ساده و روحی برای تصمیم گیری در زندگی', 'یک تمرین ساده و روحی برای تصمیم گیری در زندگی', 19, 7, 'book', 't', '<p><em>کار درست بعدی</em> (2019) نگاهی تازه به خرد تصمیم گیری رایج دارد. این پلک‌ها با تکیه بر حکایات شخصی و همچنین داستان‌هایی از کتاب مقدس، توصیه‌های روح‌انگیزی را ارائه می‌کنند تا شما را از طریق خستگی تصمیم‌گیری یا تردید مزمن راهنمایی کند تا بتوانید کار بعدی خود را پیدا کنید.</p>', '2019-05-10 00:00:00', 4, 102, 'https://images.blinkist.io/images/books/5cd0c7816cee07000830d529/1_1/470.jpg', '/en/books/the-next-right-thing-en/purchase', 'چیز-درست-بعدی', '2023-01-27 02:15:52.702776', '2023-01-27 02:15:52.702776', NULL, 'The Next Right Thing');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1376, 'از مسیر خود خارج شوید', 'راهنمای شکاک برای رشد و تحقق', 'راهنمای شکاک برای رشد و تحقق', 23, 8, 'book', 't', '<p><em>از راه خود خارج شوید</em> (2020) به بررسی افکار محدود کننده ای می پردازد که می توانند ما را از رشد، احساس رضایت و حضور کامل برای عزیزانمان باز دارند. نویسنده با رد کردن دروغ های خود ساخته خود با صراحت و شوخ طبعی، بینشی در مورد اینکه چگونه می توانید بر موقعیت های طولانی مدت مشابه غلبه کنید، ارائه می دهد.</p>', '2020-05-17 00:00:00', 4, 488, 'https://images.blinkist.io/images/books/5ebd482f6cee070006c51575/1_1/470.jpg', '/en/books/get-out-of-your-own-way-en/purchase', 'از-مسیر-خود-خارج-شوید', '2023-01-27 02:16:00.513142', '2023-01-27 02:16:00.513142', NULL, 'Get Out of Your Own Way');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1377, 'پشته نوآوری', 'ساختن یک کسب و کار شکست ناپذیر یک ایده دیوانه در یک زمان', 'ساختن یک کسب و کار شکست ناپذیر یک ایده دیوانه در یک زمان', 28, 8, 'book', 't', '<p><em>The Innovation Stack </em>(2020)<em></em>بررسی می کند که برای یک کارآفرین واقعی چه چیزی لازم است – یعنی پیدا کردن مشکلی که هیچ کس دیگری آن را حل نکرده است و هر کاری را که می خواهید انجام دهید می تواند آن را حل کند. این نشان می دهد که چگونه دو دوست با شجاعت، نبوغ و طنز، یک شرکت خدمات مالی میلیارد دلاری را از پایه ایجاد کردند. </p>', '2021-07-12 00:00:00', 5, 109, 'https://images.blinkist.io/images/books/60ddd5f86cee070007f2caa1/1_1/470.jpg', '/en/books/the-innovation-stack-en/purchase', 'پشته-نوآوری', '2023-01-27 02:16:07.983695', '2023-01-27 02:16:07.983695', NULL, 'The Innovation Stack');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1457, 'کار عمیق', 'قوانینی برای موفقیت متمرکز در دنیای پریشان', 'قوانینی برای موفقیت متمرکز در دنیای پریشان', 9, 4, 'book', 't', '<p><em>Deep Work</em> (2016) همه چیز درباره این است که چگونه ظهور فناوری توانایی ما را برای تمرکز عمیق روی کارها از بین برده است - و چگونه بر این محاصره غلبه کنیم. این پلک‌ها استراتژی‌های مختلفی را نشان می‌دهند که می‌تواند به شما کمک کند خروجی کارتان را بهبود ببخشید و از زمان آزادتان حداکثر استفاده را ببرید.</p>', '2016-06-17 00:00:00', 4, 1471, 'https://images.blinkist.io/images/books/575a6dfe5b96b60003675a18/1_1/470.jpg', '/en/books/deep-work-en/purchase', 'کار-عمیق', '2023-01-27 02:25:55.801309', '2023-01-27 02:25:55.801309', NULL, 'Deep Work');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1378, 'والدین مینیمالیستی', 'با انجام کمتر از زندگی خانوادگی مدرن بیشتر لذت ببرید', 'با انجام کمتر از زندگی خانوادگی مدرن بیشتر لذت ببرید', 16, 7, 'book', 't', '<p><em>والدین مینیمالیستی</em> (2013) مفهوم جدیدی از فرزندپروری را ارائه می‌کند: قوانین کمتر و گوش دادن بیشتر به قلب شما. کریستین کوه و آشا دورنفست به جای پیروی از آخرین روندهای فرزندپروری گله، رویکردی را برای تربیت خانواده ارائه می دهند که ارزش های شخصی و خانوادگی شما را در قلب زندگی شما به عنوان والدین قرار می دهد.</p>', '2015-09-21 00:00:00', 4, 68, 'https://images.blinkist.io/images/books/55ffed69615cd1000900000e/1_1/470.jpg', '/en/books/minimalist-parenting-en/purchase', 'والدین-مینیمالیستی', '2023-01-27 02:16:15.057047', '2023-01-27 02:16:15.057047', NULL, 'Minimalist Parenting');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1379, 'سنجاق', 'آیا شما ضروری هستید؟', 'آیا شما ضروری هستید؟', 12, 7, 'book', 't', '<p><em>Linchpin</em> توضیح می‌دهد که چرا باید در محل کار یک پهپاد بی‌خبر نباشید و در عوض تبدیل به یک گیره‌دار شوید – کسی که انرژی خود را در کار می‌ریزد و برای شرکت ضروری است. این نه تنها برای حرفه شما بهتر است، بلکه کار را بسیار لذت بخش تر و با ارزش تر می کند.</p>', '2013-05-28 00:00:00', 4, 149, 'https://images.blinkist.io/images/books/51483e8fe4b0f71597bd1359/1_1/470.jpg', '/en/books/linchpin-en/purchase', 'سنجاق', '2023-01-27 02:16:19.884982', '2023-01-27 02:16:19.884982', NULL, 'Linchpin');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1380, 'که باید از سختی ها بیزاری کرد', 'آموزه های رواقیون رومی', 'آموزه های رواقیون رومی', 21, 7, 'book', 't', '<p><em>که باید از سختی‌ها بیزاری کرد</em>(2020) مجموعه‌ای از سخنرانی‌هایی است که در قرن اول پس از میلاد در روم امپراتوری توسط گایوس موسونیوس روفوس رواقی ایراد شد. فلسفه موسونیوس که به عنوان «سقراط رومی» معرفی می شود، چیزی جز آکادمیک است. سخنرانی‌های او که برای کمک به شنوندگان طراحی شده‌اند تا بهترین زندگی ممکن را داشته باشند، به سوالات عملی و روزمره می‌پردازند. نتیجه؟ دکترینی که واقعاً می توانید با آن زندگی کنید.</p>', '2021-04-14 00:00:00', 5, 85, 'https://images.blinkist.io/images/books/6074012c6cee070007aad72e/1_1/470.jpg', '/en/books/that-one-should-disdain-hardships-en/purchase', 'که-باید-از-سختی-ها-بیزاری-کرد', '2023-01-27 02:16:27.937438', '2023-01-27 02:16:27.937438', NULL, 'That One Should Disdain Hardships');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1381, 'دختران باهوش هم دست به کار می شوند', 'راهنمای بی معنی برای ایجاد زندگی که می خواهید', 'راهنمای بی معنی برای ایجاد زندگی که می خواهید', 26, 9, 'book', 't', '<p><em>Smart Girls Screw Up Too</em> (2019) یک راهنمای مفید و توانمند برای تغییر زندگی شما است. این انبوهی از توصیه ها، ابزارها و تمرین ها را ارائه می دهد که زندگی شما را از جنبه منفی، جایی که اعتماد به نفس پایین و مشاغل و روابط بد دارید، به سمت بالا می برد، جایی که شما به تمام استوانه ها شلیک خواهید کرد و بهترین استفاده را خواهید برد. از آنچه دارید.</p>', '2019-11-01 00:00:00', 4, 67, 'https://images.blinkist.io/images/books/5db85acd6cee070008a69287/1_1/470.jpg', '/en/books/smart-girls-screw-up-too-en/purchase', 'دختران-باهوش-هم-دست-به-کار-می-شوند', '2023-01-27 02:16:35.663212', '2023-01-27 02:16:35.663212', NULL, 'Smart Girls Screw Up Too');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1382, 'اثر سنجاقک', 'راه های سریع، موثر و قدرتمند برای استفاده از رسانه های اجتماعی برای ایجاد تغییرات اجتماعی', 'راه های سریع، موثر و قدرتمند برای استفاده از رسانه های اجتماعی برای ایجاد تغییرات اجتماعی', 14, 6, 'book', 't', '<p><em></em> <em>سنجاقک</em> <em>اثر</em> توضیح می‌دهد که چگونه هر کسی می‌تواند از قدرت رسانه‌های اجتماعی برای جذب افراد در پشت تغییرات اجتماعی معنادار استفاده کند.</p>', '2014-07-01 00:00:00', 4, 16, 'https://images.blinkist.io/images/books/53b4246b63373200073b0000/1_1/470.jpg', '/en/books/the-dragonfly-effect-en/purchase', 'اثر-سنجاقک', '2023-01-27 02:16:43.208144', '2023-01-27 02:16:43.208144', NULL, 'The Dragonfly Effect');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1383, 'استرس کمتر، بیشتر انجام دهید', 'مدیتیشن برای اجرای فوق العاده', 'مدیتیشن برای اجرای فوق العاده', 22, 7, 'book', 't', '<p><em>استرس کمتر، بیشتر به انجام برسانید </em>(۲۰۱۹) نشان می‌دهد که چگونه مدیتیشن می‌تواند به افراد پرمشغله کمک کند تا در زندگی پرشتاب خود کارهای بیشتری انجام دهند. در سال‌های اخیر، علم آنچه را که مراقبه‌گران برای هزاران سال می‌دانستند، آشکار کرده است: این ابزار ساده را می‌توان در هر زمان و هر مکان برای کاهش استرس، به دست آوردن وضوح ذهنی، و بهبود عملکرد در طول زندگی‌تان تمرین کرد.</p>', '2021-04-04 00:00:00', 5, 336, 'https://images.blinkist.io/images/books/606492916cee070007b3bcb6/1_1/470.jpg', '/en/books/stress-less-accomplish-more-en/purchase', 'استرس-کمتر،-بیشتر-انجام-دهید', '2023-01-27 02:16:50.97065', '2023-01-27 02:16:50.97065', NULL, 'Stress Less, Accomplish More');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1384, 'روده', 'داستان درونی دست کم گرفته شده ترین عضو بدن ما', 'داستان درونی دست کم گرفته شده ترین عضو بدن ما', 22, 10, 'book', 't', '<p><em>روده </em>(2015) نگاهی سرگرم کننده و در عین حال علمی به اندامی دارد که به اندازه مغز جالب و مهم است - روده. با ردیابی یک تکه کیک در حالی که در سیستم گوارشی کار می کند، از اکوسیستم پیچیده و چشمگیر آن قدردانی خواهید کرد.</p>', '2016-02-05 00:00:00', 4, 78, 'https://images.blinkist.io/images/books/56afadd9377c1600070000a5/1_1/470.jpg', '/en/books/gut-en/purchase', 'روده', '2023-01-27 02:16:59.304099', '2023-01-27 02:16:59.304099', NULL, 'Gut');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1385, 'رسیدن به آنجا', 'کتابی از مربیان', 'کتابی از مربیان', 14, 6, 'book', 't', '<p><em>Getting There</em>(2015) پرتره‌های الهام‌بخشی از کارآفرینان، هنرمندان، نویسندگان و مدیران عامل موفقی را ارائه می‌دهد که با سخت کوشی و پشتکار، علایق واقعی خود را در مقابل همه مشکلات دنبال کردند. هدف این مجموعه داستان های اول شخص نشان دادن این است که شما نیز چگونه می توانید «به آنجا بروید» و رویاهای خود را زندگی کنید.</p>', '2016-01-07 00:00:00', 3, 12, 'https://images.blinkist.io/images/books/568b0535de78c00007000038/1_1/470.jpg', '/en/books/getting-there-en/purchase', 'رسیدن-به-آنجا', '2023-01-27 02:17:06.73075', '2023-01-27 02:17:06.73075', NULL, 'Getting There');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1386, 'زندگی رو به جلو', 'یک برنامه اثبات شده برای توقف دریفت و به دست آوردن زندگی که می خواهید', 'یک برنامه اثبات شده برای توقف دریفت و به دست آوردن زندگی که می خواهید', 25, 8, 'book', 't', '<p><em>Living Forward </em>(2016) راه حلی برای این واقعیت ارائه می دهد که بسیاری از ما با آن روبرو هستیم: زندگی ما آنطور که انتظار داشتیم پیش نرفت. هنگامی که ما یک برنامه روشن و مرتبط نداریم، زندگی ما معمولاً بر روی مماس ها کشیده می شود و با برنامه های افراد دیگر پر می شود. این پلک ها دستورالعمل های گام به گام در مورد نحوه ایجاد یک برنامه زندگی را ارائه می دهند تا بتوانید کنترل را دوباره به دست آورید و به جایی که واقعاً می خواهید برسید برسید.</p>', '2020-08-10 00:00:00', 5, 174, 'https://images.blinkist.io/images/books/5f2d272f6cee07000669b5d8/1_1/470.jpg', '/en/books/living-forward-en/purchase', 'زندگی-رو-به-جلو', '2023-01-27 02:17:15.014336', '2023-01-27 02:17:15.014336', NULL, 'Living Forward');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1387, 'منظورت را بگو', 'رویکردی آگاهانه به ارتباطات بدون خشونت', 'رویکردی آگاهانه به ارتباطات بدون خشونت', 32, 11, 'book', 't', '<p><em> منظورتان را بگویید</em> (2018) راهنمای ارتباط معنادار و سازنده است. این نشان می‌دهد که چگونه می‌توانید عادت‌های قدیمی و غیر مفید را پشت سر بگذارید و مهارت‌هایی را برای بیان ذهن خود به روشی واضح و معتبر توسعه دهید. همچنین چند روش ساده را آموزش می دهد تا مکالمات شما را مؤثرتر و رضایت بخش تر کند.</p>', '2020-05-21 00:00:00', 5, 195, 'https://images.blinkist.io/images/books/5ec3c27e6cee0700065b9f9f/1_1/470.jpg', '/en/books/say-what-you-mean-en/purchase', 'منظورت-را-بگو', '2023-01-27 02:17:23.539316', '2023-01-27 02:17:23.539316', NULL, 'Say What You Mean');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1388, 'شما یک بدجنس هستید', 'چگونه از شک به عظمت خود دست برداریم و زندگی عالی را شروع کنیم', 'چگونه از شک به عظمت خود دست برداریم و زندگی عالی را شروع کنیم', 16, 7, 'book', 't', '<p><em>You Are a Badass</em>(2013) راهنمای شما برای زندگی کامل است. Sincero تجزیه و تحلیلی از دقیقاً آنچه شما را عقب نگه می دارد ارائه می دهد و استراتژی های قدرتمندی را برای ترک عادت های بد ارائه می دهد تا بتوانید واقعاً رویاهای خود را تحقق بخشید.</p>
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1389, '1000 نسخه اول شما', 'راهنمای گام به گام بازاریابی کتاب شما', 'راهنمای گام به گام بازاریابی کتاب شما', 15, 9, 'book', 'f', '<p>در <em>1000 نسخه اول شما</em>، تیم گرال راهنمای گام به گام استراتژی اتصال خود را برای نویسندگان شرح می دهد. او نشان می دهد که چگونه می توانید بستری برای پیدا کردن مخاطبان خود ایجاد کنید و آنها را در جریان نگه دارید تا کتاب بعدی شما را بخرند. مملو از اطلاعات حیاتی در مورد چگونگی علاقه مند کردن خوانندگان به کار خود با محتوای آنلاین خوب و نحوه فروش بدون شلختگی، <em>1000 نسخه اول شما </em>برای هر نویسنده مشتاق یا معتبری باید مطالعه شود.</p >', '2014-04-29 11:18:41', NULL, 6, 'https://images.blinkist.io/images/books/5360da0e6233360007170100/1_1/470.jpg', '/en/books/your-first-1000-copies-en/purchase', '1000-نسخه-اول-شما', '2023-01-27 02:17:36.5337', '2023-01-27 02:17:36.5337', NULL, 'Your First 1000 Copies');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1390, 'با صفر بمیر', 'گرفتن تمام آنچه می توانید از پول و زندگی خود', 'گرفتن تمام آنچه می توانید از پول و زندگی خود', 19, 7, 'book', 't', '<p><em>بمیر با صفر </em>(2020) مزایای خرج کردن بیشتر و پس انداز کمتر را بررسی می کند. این پلک‌ها افسانه‌هایی را که مفهوم تأخیر در رضایت و بازنشستگی راحت را احاطه کرده‌اند، از بین می‌برند. آنها همچنین توضیح می دهند که چگونه همه می توانند از پول خود لذت بیشتری ببرند.</p>', '2020-12-29 00:00:00', 5, 237, 'https://images.blinkist.io/images/books/5fdb162e6cee07000670afdf/1_1/470.jpg', '/en/books/die-with-zero-en/purchase', 'با-صفر-بمیر', '2023-01-27 02:17:44.511374', '2023-01-27 02:17:44.511374', NULL, 'Die with Zero');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1391, 'تربیت انسان', 'ایجاد یک مشارکت مشارکتی با فرزندتان', 'ایجاد یک مشارکت مشارکتی با فرزندتان', 23, 8, 'book', 't', '<p><em>پرورش انسان‌ها </em>(2016) بخشی از راهنمای عملی و بخشی مانیفست در مورد قدرت حل مشکلات مشارکتی است. استفاده از تهدید، رشوه و تنبیه رفتار کودکان را به طور پایدار تغییر نمی دهد. این به این دلیل است که شما فقط به جای رسیدگی به علت اصلی، علائم مشکل را سرکوب می کنید. به جای درگیر شدن در جنگ قدرت، سعی کنید از فرزندانتان بپرسید که واقعاً چه خبر است و راه حل هایی را با هم در میان بگذارید. نه تنها راه حل های بهتری پیدا خواهید کرد، بلکه رابطه شما به طور چشمگیری بهبود خواهد یافت.</p>', '2023-01-14 00:00:00', NULL, 6, 'https://images.blinkist.io/images/books/63bd0d9382ae2f00089040d6/1_1/470.jpg', '/en/books/raising-human-beings-en/purchase', 'تربیت-انسان', '2023-01-27 02:17:52.304255', '2023-01-27 02:17:52.304255', NULL, 'Raising Human Beings');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1392, 'نوشتن که کار می کند', 'چگونه در تجارت به طور موثر ارتباط برقرار کنیم', 'چگونه در تجارت به طور موثر ارتباط برقرار کنیم', 21, 8, 'book', 't', '<p><em>نوشتن که کار می کند</em> (1981) راهنمای قطعی برای نوشتن تجاری است. این پلک‌ها مملو از توصیه‌هایی در مورد نحوه نوشتن ارتباطات تجاری واضح، قانع‌کننده و مختصر است که همه چیز از گزارش‌های فصلی گرفته تا ارائه‌ها، ایمیل‌ها و حتی رزومه‌ها را پوشش می‌دهد.</p>', '2018-02-06 00:00:00', 4, 48, 'https://images.blinkist.io/images/books/5a74fe7eb238e100070eb3d5/1_1/470.jpg', '/en/books/writing-that-works-en/purchase', 'نوشتن-که-کار-می-کند', '2023-01-27 02:18:00.28363', '2023-01-27 02:18:00.28363', NULL, 'Writing That Works');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1393, 'قدرت تمرکز تزلزل ناپذیر', 'چگونه زندگی ای را که می خواهید زندگی کنید', 'چگونه زندگی ای را که می خواهید زندگی کنید', 20, 5, 'book', 't', '<p><em>قدرت تمرکز تزلزل ناپذیر </em>(2022) یک راهنمای عملی و شخصی است که گام‌های روشنی را برای پایان دادن به حواس‌پرتی‌ها، ترس‌ها و نگرانی‌هایی که ما را تحت فشار و مضطرب نگه می‌دارند، ارائه می‌دهد، در حالی که مسیری روشن را ترسیم می‌کند. به سمت وضوح ذهنی و تمرکز بیشتر. مملو از گام‌های مشخص و بازتاب‌های شخصی، نگاهی عمیق به قدرت فوق‌العاده ذهن و اینکه چگونه تمرکز می‌تواند به همه کمک کند تا زندگی هدفمندتر و شادتری داشته باشند، ارائه می‌کند.</p>', '2022-11-21 00:00:00', 5, 676, 'https://images.blinkist.io/images/books/63749e96b3fb5d000d92cffa/1_1/470.jpg', '/en/books/the-power-of-unwavering-focus-en/purchase', 'قدرت-تمرکز-تزلزل-ناپذیر', '2023-01-27 02:18:08.646695', '2023-01-27 02:18:08.646695', NULL, 'The Power of Unwavering Focus');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1394, 'سازمان های نمایی', 'چرا سازمان‌های جدید ده برابر بهتر، سریع‌تر و ارزان‌تر از سازمان شما هستند (و در مورد آن چه باید کرد)', 'چرا سازمان‌های جدید ده برابر بهتر، سریع‌تر و ارزان‌تر از سازمان شما هستند (و در مورد آن چه باید کرد)', 22, 9, 'book', 't', '<p><em>سازمان‌های نمایی</em> نگاهی تخصصی به این شکل جدید و حیاتی سازمان شرکت ارائه می‌دهد که نویسندگان ادعا می‌کنند به زودی به یک استاندارد صنعتی تبدیل خواهد شد. شما دقیقاً یاد خواهید گرفت که یک سازمان نمایی یا ExO چیست و چگونه می توانید سازمان خود را بسازید. شرکت‌هایی مانند Uber و AirBnB نمونه‌های برتر ExOs هستند. اگر شرکت شما می‌خواهد زنده بماند، باید خود را وفق دهید.</p>', '2015-02-16 00:00:00', 5, 82, 'https://images.blinkist.io/images/books/54e20703306266000a2a0000/1_1/470.jpg', '/en/books/exponential-organizations-en/purchase', 'سازمان-های-نمایی', '2023-01-27 02:18:16.411598', '2023-01-27 02:18:16.411598', NULL, 'Exponential Organizations');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1395, 'لمس صخره', 'تجربه نابینایی', 'تجربه نابینایی', 18, 7, 'book', 't', '<p><em>لمس صخره</em>(1990) شرحی از درک یک مرد از نابینایی است. جان ام. هال پس از از دست دادن بینایی خود به عنوان یک مرد بالغ، تجربه روانی و جسمی روزانه نابینایی، ابزارهایی که نابینایان برای هدایت فضا و روابط استفاده می کنند، و معنای نابینایی در دنیای بینا را بررسی می کند. p>', '2020-05-22 00:00:00', 5, 20, 'https://images.blinkist.io/images/books/5ec43de76cee0700065ba12f/1_1/470.jpg', '/en/books/touching-the-rock-en/purchase', 'لمس-صخره', '2023-01-27 02:18:23.821888', '2023-01-27 02:18:23.821888', NULL, 'Touching the Rock');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1396, 'ذهنیت خالق', '92 ابزار برای باز کردن رازهای نوآوری، رشد و پایداری', '92 ابزار برای باز کردن رازهای نوآوری، رشد و پایداری', 25, 7, 'book', 't', '<p><em>ذهنیت خالق</em> (2020) راهنمای جامعی برای گنجاندن خلاقیت در هر کاری است که انجام می‌دهید. خلاقیت به دور از اینکه چیزی باشد که فقط هنرمندان از آن برخوردارند، در واقع یک عنصر ضروری در هر حرفه یا تجارت موفقی است. متأسفانه، بسیاری از ما پتانسیل خلاقیت کامل خود را با ندانم کاری که در ابتدا داریم تلف می کنیم. آماده شوید تا استعدادهای خلاق نهفته را باز کنید که به شما و کسب و کارتان برتری نسبت به رقبا می دهد.</p>', '2021-02-10 00:00:00', 4, 108, 'https://images.blinkist.io/images/books/601d462b6cee0700078f64dd/1_1/470.jpg', '/en/books/the-creator-mindset-en/purchase', 'ذهنیت-خالق', '2023-01-27 02:18:31.350368', '2023-01-27 02:18:31.350368', NULL, 'The Creator Mindset');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1397, 'آنچه شما انجام می دهید همان چیزی است که شما هستید', 'چگونه فرهنگ کسب و کار خود را ایجاد کنیم', 'چگونه فرهنگ کسب و کار خود را ایجاد کنیم', 24, 8, 'book', 't', '<p>در <em>What You Do Is Who You are </em> (۲۰۱۹)، بن هوروویتز، سرمایه‌دار و کارشناس مدیریت، تعریف خود را از فرهنگ کسب‌وکار ارائه می‌کند. او از طریق نمونه‌های معاصر و برخی مسیرهای انحرافی تاریخی گذشته از افراد سرشناس مانند چنگیز خان و سامورایی، توصیه‌های جالبی در مورد نحوه ایجاد فرهنگی مناسب برای کسب و کار شما ارائه می‌دهد.</p>', '2019-11-27 00:00:00', 4, 108, 'https://images.blinkist.io/images/books/5dd7e4e46cee0700084a7774/1_1/470.jpg', '/en/books/what-you-do-is-who-you-are-en/purchase', 'آنچه-شما-انجام-می-دهید-همان-چیزی-است-که-شما-هستید', '2023-01-27 02:18:39.445759', '2023-01-27 02:18:39.445759', NULL, 'What You Do Is Who You Are');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1398, 'زندگی در 1% برتر شما', 'نه مراسم ضروری برای دستیابی به اهداف نهایی زندگی', 'نه مراسم ضروری برای دستیابی به اهداف نهایی زندگی', 20, 9, 'book', 't', 'نویسنده Alissa Finerman بیان می کند که <p>در <em>Living</em> <em>In</em> <em>شما</em> <em>برترین</em> <em>1٪</em> نه درس کلیدی برای رسیدن به پتانسیل کامل و تبدیل شدن به بهترین خود ممکن. از طریق مطالعات علمی و مثال‌های واقعی، خواهید فهمید که چگونه می‌توانید بر موانع غلبه کنید و به اهداف خود برسید.</p>', '2014-07-15 00:00:00', 4, 108, 'https://images.blinkist.io/images/books/53c637e23839340007bc0000/1_1/470.jpg', '/en/books/living-in-your-top-1-percent-en/purchase', 'زندگی-در-1%-برتر-شما', '2023-01-27 02:18:46.877506', '2023-01-27 02:18:46.877506', NULL, 'Living In Your Top 1%');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1399, 'غریزه زبان', 'ذهن چگونه زبان می آفریند', 'ذهن چگونه زبان می آفریند', 23, 10, 'book', 't', '<p><em>غریزه زبان</em> (1994) نگاهی عمیق به ریشه‌ها و پیچیدگی‌های زبان ارائه می‌دهد، و در طول مسیر، هم دوره‌ای کوتاه در زبان‌شناسی و هم در انسان‌شناسی زبانی ارائه می‌دهد. با بررسی استعداد ما در زبان، این کتاب نشان می‌دهد که تمایل به یادگیری زبان در واقع در مغز ما جابجا شده است.</p>', '2014-12-24 00:00:00', 4, 71, 'https://images.blinkist.io/images/books/548a1aa23363370009820000/1_1/470.jpg', '/en/books/the-language-instinct-en/purchase', 'غریزه-زبان', '2023-01-27 02:18:55.120258', '2023-01-27 02:18:55.120258', NULL, 'The Language Instinct');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1400, 'بدون سر', 'ذن و کشف مجدد امر آشکار', 'ذن و کشف مجدد امر آشکار', 31, 12, 'book', 't', '<p><em>بی سر</em> (1961) کلاسیک بی نظیری از فلسفه، معنویت و عرفان است. با ترکیب مشاهدات تجربی، تجربیات عرفانی، استدلال های منطقی، درون نگری شخصی، تمرین های عملی، ذن بودیسم، و دیگر سنت های معنوی شرقی، هدف آن در هم شکستن دوگانگی هایی است که در زیر بسیاری از اندیشه های غربی نهفته است: سوژه و ابژه، ذهن و بدن، خود. و جهان غیر خود، درونی و بیرونی. به جای آنها، نویسنده ادعا می کند که ما می توانیم خود و جهان اطرافمان را به شکلی کاملاً متفاوت ببینیم.</p>', '2020-04-07 00:00:00', 4, 100, 'https://images.blinkist.io/images/books/5e8752226cee0700065b508a/1_1/470.jpg', '/en/books/on-having-no-head-en/purchase', 'بدون-سر', '2023-01-27 02:19:03.265541', '2023-01-27 02:19:03.265541', NULL, 'On Having No Head');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1401, 'سگ جنگی', 'چگونه اپل و گوگل وارد جنگ شدند و انقلابی را آغاز کردند', 'چگونه اپل و گوگل وارد جنگ شدند و انقلابی را آغاز کردند', 20, 9, 'book', 't', '<p><em>Dogfight</em> (2013) داستانی را بازگو می کند که چگونه یک شراکت تجاری دوستانه بین غول های فناوری اپل و گوگل به رقابتی تلخ تبدیل شد، زیرا این شرکت ها برای کنترل بازار دستگاه های اینترنت تلفن همراه می جنگیدند.</em><em> p>', '2016-07-26 00:00:00', 5, 15, 'https://images.blinkist.io/images/books/57923e18b3b9b300032e80d2/1_1/470.jpg', '/en/books/dogfight-en/purchase', 'سگ-جنگی', '2023-01-27 02:19:11.491048', '2023-01-27 02:19:11.491048', NULL, 'Dogfight');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1402, 'پاندمی', 'ردیابی موارد مسری، از وبا گرفته تا ابولا و فراتر از آن', 'ردیابی موارد مسری، از وبا گرفته تا ابولا و فراتر از آن', 17, 7, 'book', 't', '<p><em>Pandemic </em>(2016) دنیای شگفت‌انگیز پاتوژن‌ها و بیماری‌ها و چگونگی انتشار آنها از یک خفاش در چین به پنج قاره دیگر را در یک روز بررسی می‌کند. این بیماری ها چگونه تکامل می یابند و جامعه مدرن چگونه به موفقیت آنها کمک می کند؟ و مهمتر از همه: چه کاری می توانیم انجام دهیم تا همه گیری بعدی را متوقف کنیم؟</p>', '2016-05-24 00:00:00', 4, 101, 'https://images.blinkist.io/images/books/5740a2c42edd1b00032e6b57/1_1/470.jpg', '/en/books/pandemic-en/purchase', 'پاندمی', '2023-01-27 02:19:19.480397', '2023-01-27 02:19:19.480397', NULL, 'Pandemic');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1403, 'مشاوره بی عیب و نقص', 'راهنمای استفاده از تخصص شما', 'راهنمای استفاده از تخصص شما', 15, 7, 'book', 't', '<p><em>مشاوره بی عیب و نقص</em> (ویرایش دوم، 2000) با راهنمای گام به گام تمام مراحل مشاوره حرفه ای، نگاهی درونی به هنر مشاوره به شما می دهد. چه مشاوری باشید که تازه کار خود را شروع کرده‌اید یا یک رهبر تجاری باشید که با مشاوران کار می‌کند، این کتاب به شما نشان می‌دهد که چگونه روابط مشاور و مشتری را با موفقیت مدیریت کنید.</p>', '2015-05-12 00:00:00', 4, 41, 'https://images.blinkist.io/images/books/5550afce6332630007280000/1_1/470.jpg', '/en/books/flawless-consulting-en/purchase', 'مشاوره-بی-عیب-و-نقص', '2023-01-27 02:19:27.305163', '2023-01-27 02:19:27.305163', NULL, 'Flawless Consulting');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1404, 'سوپر انسان', 'طرح ضد گلوله برای پیر شدن به عقب و شاید حتی برای همیشه زندگی کردن', 'طرح ضد گلوله برای پیر شدن به عقب و شاید حتی برای همیشه زندگی کردن', 24, 8, 'book', 't', '<p><em>"هیچ مکملی نمی تواند طیف کاملی از نور مورد نیاز انسان از خورشید را تکرار کند.</em><em>"</em></p>
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1405, 'چگونه یک استارت آپ راه اندازی کنیم', 'کتاب بازی سیلیکون ولی برای کارآفرینان', 'کتاب بازی سیلیکون ولی برای کارآفرینان', 12, 5, 'book', 't', '<p><em>چگونه یک استارت آپ راه اندازی کنیم </em>(2015) یک راهنمای عملی برای تأسیس شرکت خود است. از درخواست بودجه تا استخدام کارمندان، این پلک‌ها نکات، استراتژی‌ها و بینش‌هایی را در مورد اولین قدم‌هایی که یک استارت‌آپ باید برای ایجاد مسیری به سوی رشد پایدار و پایدار بردارد ارائه می‌دهد.</p>', '2016-09-05 00:00:00', 4, 73, 'https://images.blinkist.io/images/books/57c93eef08dc1b000317fe51/1_1/470.jpg', '/en/books/how-to-start-a-start-up-en/purchase', 'چگونه-یک-استارت-آپ-راه-اندازی-کنیم', '2023-01-27 02:19:40.249074', '2023-01-27 02:19:40.249074', NULL, 'How to Start a Start-up');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1406, 'دلیل گل', 'تاریخچه، فرهنگ، زیست شناسی و چگونگی تغییر زندگی ما', 'تاریخچه، فرهنگ، زیست شناسی و چگونگی تغییر زندگی ما', 21, 8, 'book', 't', '<p><em>The Reason for Flowers</em> (2015) درباره منشا، بازتولید و تأثیرات این قطعات شگفت انگیز از آثار هنری تکاملی است. این پلک‌ها توضیح می‌دهند که گل‌ها چگونه رابطه جنسی دارند، چرا آن‌قدر زیبا هستند و چرا انسان‌ها اینقدر شیفته آن‌ها شده‌اند.</p>', '2016-09-22 00:00:00', 4, 62, 'https://images.blinkist.io/images/books/57dd8123f9916500030ea780/1_1/470.jpg', '/en/books/the-reason-for-flowers-en/purchase', 'دلیل-گل', '2023-01-27 02:19:48.228141', '2023-01-27 02:19:48.228141', NULL, 'The Reason For Flowers');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1407, 'آموزش فروشندگان به قهرمانان فروش', 'کتاب بازی تاکتیکی برای مدیران و مدیران اجرایی', 'کتاب بازی تاکتیکی برای مدیران و مدیران اجرایی', 12, 6, 'book', 't', '<p><em>مربیگری فروشندگان به قهرمانان فروش</em> (2008) راهنمای مدیر فروش برای مربیگری فروشندگان و یادگیری نحوه ایجاد ارتباطات قدرتمند در بین نیروهای فروش است. شما یاد خواهید گرفت که چگونه تیم خود را قدرتمند کنید، ترس های خود را رها کنید و به یک مربی فروش بسیار موثر تبدیل شوید. </p>', '2016-02-03 00:00:00', 4, 63, 'https://images.blinkist.io/images/books/56afa397377c160007000035/1_1/470.jpg', '/en/books/coaching-salespeople-into-sales-champions-en/purchase', 'آموزش-فروشندگان-به-قهرمانان-فروش', '2023-01-27 02:19:56.145617', '2023-01-27 02:19:56.145617', NULL, 'Coaching Salespeople into Sales Champions');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1408, 'کاخ حافظه', 'هر چیزی و همه چیز را بیاموزید (از شکسپیر و دیکنز شروع کنید)', 'هر چیزی و همه چیز را بیاموزید (از شکسپیر و دیکنز شروع کنید)', 9, 5, 'book', 't', '<p><em>قصر حافظه</em> (2012) یک راهنمای گام به گام برای استفاده از حافظه فضایی است تا به شما کمک کند تا کاملاً هر چیزی را به خاطر بسپارید. این به شما می‌آموزد که چگونه قصری از خاطرات بسازید که به شما این قدرت را می‌دهد تا همه چیزهایی را که می‌خوانید به خاطر بیاورید، و حتی نام هر نمایشنامه شکسپیر را فقط در 15 دقیقه به خاطر بسپارید.</p>', '2015-12-15 00:00:00', 4, 158, 'https://images.blinkist.io/images/books/566fdbcacf6aa30007000004/1_1/470.jpg', '/en/books/the-memory-palace-en/purchase', 'کاخ-حافظه', '2023-01-27 02:20:03.892724', '2023-01-27 02:20:03.892724', NULL, 'The Memory Palace');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1409, 'هنر اغواگری', 'بررسی بازی غیراخلاقی و تکنیک های اغواگران', 'بررسی بازی غیراخلاقی و تکنیک های اغواگران', 19, 8, 'book', 't', '<p><em>هنر اغواگری</em> (2001) بازی غیراخلاقی اغواگری را بررسی می کند و توضیح می دهد که چگونه اغواگری همیشه در ذهن شروع می شود و موفق ترین اغواگران این را به خوبی می دانند. راهبردهایی را برای تحریک علاقه، از بین بردن هدف اغواگری، برانگیختن میل و برانگیختن احساسات توضیح می دهد. این تاکتیک ها منجر به اغوای نهایی هدف می شود.</p>', '2017-07-05 00:00:00', 4, 543, 'https://images.blinkist.io/images/books/595a51e9b238e10007cd5124/1_1/470.jpg', '/en/books/the-art-of-seduction-en/purchase', 'هنر-اغواگری', '2023-01-27 02:20:11.439289', '2023-01-27 02:20:11.439289', NULL, 'The Art of Seduction');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1410, 'ادامه بده', '10 راه برای خلاق ماندن در زمان خوب و بد', '10 راه برای خلاق ماندن در زمان خوب و بد', 24, 8, 'book', 't', '<p>پر از نکات، تکنیک‌ها و استراتژی‌های عملی برای پرورش خلاقیت، <em>ادامه دهید </em> (2019) راه‌های متنوعی را در اختیار خوانندگان قرار می‌دهد تا در مواجهه با مشکلات کار خلاقانه خود پایداری کنند. در حالی که متن عمدتاً با در نظر گرفتن هنرمندان حرفه ای و غیرحرفه ای نوشته شده است، ایده ها برای هر کسی که شغل یا سرگرمی آنها نیاز به خلاقیت دارد قابل استفاده است. </p>', '2019-09-11 00:00:00', 5, 158, 'https://images.blinkist.io/images/books/5d726c2c6cee07000897c449/1_1/470.jpg', '/en/books/keep-going-en/purchase', 'ادامه-بده', '2023-01-27 02:20:18.996182', '2023-01-27 02:20:18.996182', NULL, 'Keep Going');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1411, 'زندگی فاجعه کامل', 'استفاده از خرد بدن و ذهن برای مواجهه با استرس، درد و بیماری', 'استفاده از خرد بدن و ذهن برای مواجهه با استرس، درد و بیماری', 25, 8, 'book', 't', '<p><em>زندگی کامل با فاجعه</em> (1990) این کتاب را نمی‌پوشاند: این کتابی است که اذعان می‌کند زندگی گاهی ممکن است مانند یک فاجعه پس از دیگری باشد. اما در حالی که ممکن است نتوانیم از فجایع زندگی جلوگیری کنیم، نحوه واکنش ما به آنها کاملاً در کنترل ما است. یک کلاسیک شناخته شده در ژانر زندگی آگاهانه، <em>زندگی فاجعه کامل </em>توضیح می دهد که چگونه طوفان های زندگی را می توان از طریق ذهن آگاهی تحمل کرد.</p>', '2020-05-30 00:00:00', 5, 127, 'https://images.blinkist.io/images/books/5ecd6c986cee0700078a3fc7/1_1/470.jpg', '/en/books/full-catastrophe-living-en/purchase', 'زندگی-فاجعه-کامل', '2023-01-27 02:20:26.549299', '2023-01-27 02:20:26.549299', NULL, 'Full Catastrophe Living');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1412, 'قوانین شورشی', 'جسارت به خود بودن در تجارت', 'جسارت به خود بودن در تجارت', 21, 11, 'book', 't', '<p>در <em>The</em> <em>Rebel</em> <em>قوانین</em>، چیپ کانلی داستان‌های موفقیت‌آمیز شورشیان کارآفرین را به ما می‌دهد. کانلی به ظاهر تاجر شورشی که مظهر دو متضاد ظاهری است، درک می کند: هوش تجاری و امتناع از اجرای قوانین. او استدلال می کند که شورشیان تجاری، یعنی افرادی که با علایق درونی خود ارتباط برقرار می کنند و جرات استفاده از بینش و غریزه خود را دارند، نه تنها در تجارت موفق ترند، بلکه به طور کلی شادتر هستند.</p>', '2014-08-19 00:00:00', 4, 15, 'https://images.blinkist.io/images/books/53f477ed34333900086e0000/1_1/470.jpg', '/en/books/the-rebel-rules-en/purchase', 'قوانین-شورشی', '2023-01-27 02:20:34.85674', '2023-01-27 02:20:34.85674', NULL, 'The Rebel Rules');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1413, 'استعداد بیش از حد ارزیابی می شود', 'آنچه واقعاً مجریان کلاس جهانی را از بقیه جدا می کند', 'آنچه واقعاً مجریان کلاس جهانی را از بقیه جدا می کند', 21, 9, 'book', 't', '<p><em>استعداد بیش از حد ارزیابی می‌شود </em>با عملکرد برتر در تعدادی از زمینه‌ها به کاوش می‌پردازد تا در انتهای آنچه که آنها را عالی می‌کند، قرار بگیرد. برخلاف آنچه که بیشتر ما به طور شهودی در مورد مهارت فکر می کنیم، این کتاب شواهد فریبنده ای ارائه می دهد که نشان می دهد عملکرد برتر در هر زمینه ای توسط استعداد ذاتی آنها تعیین نمی شود، بلکه با تلاش های عمدی در طول سالیان متمادی تعیین می شود.</p>', '2014-04-23 09:09:38.871', 5, 76, 'https://images.blinkist.io/images/books/534e958e6531660007000000/1_1/470.jpg', '/en/books/talent-is-overrated-en/purchase', 'استعداد-بیش-از-حد-ارزیابی-می-شود', '2023-01-27 02:20:42.084685', '2023-01-27 02:20:42.084685', NULL, 'Talent is Overrated');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1414, 'چهره را بخوانید', 'چهره خوانی برای موفقیت در شغل، روابط و سلامتی', 'چهره خوانی برای موفقیت در شغل، روابط و سلامتی', 26, 8, 'book', 't', '<p><em>Read the Face</em> (2021) یک راهنمای مبتدی برای هنر و علم هزاره‌ای فیزیوگنومی یا چهره‌خوانی است. تاریخچه مختصری از این عمل ارائه می‌کند، تکنیک‌ها و روش‌ها را تشریح می‌کند، و شامل مطالعات موردی روشن‌گری می‌شود.</p>', '2021-09-15 00:00:00', 3, 180, 'https://images.blinkist.io/images/books/613dc2dd6cee070007045016/1_1/470.jpg', '/en/books/read-the-face-en/purchase', 'چهره-را-بخوانید', '2023-01-27 02:20:50.040301', '2023-01-27 02:20:50.040301', NULL, 'Read the Face');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1416, 'یک کلمه آرام', 'لابی گری، سرمایه داری همراه و سیاست شکسته در بریتانیا', 'لابی گری، سرمایه داری همراه و سیاست شکسته در بریتانیا', 15, 9, 'book', 'f', '<p><em>A</em> <em>آرام</em> <em>Word</em> توضیح می‌دهد که لابییسم چیست، چگونه کار می‌کند و چرا می‌تواند برای دموکراسی خطرناک باشد. نویسندگان گستره لابی‌گری امروز را آشکار می‌کنند، استراتژی‌های مختلفی را که توسط لابی‌گران برای تأثیرگذاری بر دولت‌ها استفاده می‌شود، شرح می‌دهند و راه‌حلی برای کمک به دفاع از دموکراسی ارائه می‌دهند.</p>', '2014-06-03 14:35:13', NULL, 3, 'https://images.blinkist.io/images/books/538f2c443761300007020100/1_1/470.jpg', '/en/books/a-quiet-word-en/purchase', 'یک-کلمه-آرام', '2023-01-27 02:21:03.832803', '2023-01-27 02:21:03.832803', NULL, 'A Quiet Word');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1417, 'اقتصاد: راهنمای کاربر', 'هر آنچه باید در مورد اقتصاد بدانید', 'هر آنچه باید در مورد اقتصاد بدانید', 31, 13, 'book', 't', '<p><em>Economics: The User''s Guide</em>مفاهیم بنیادی اقتصاد را به روشی آسان و قانع‌کننده بیان می‌کند. این کتاب با بررسی تاریخچه اقتصاد و همچنین برخی تغییرات حیاتی در نهادهای اقتصادی جهانی، هر آنچه را که باید در مورد نحوه عملکرد اقتصاد امروز بدانید را به شما آموزش می‌دهد.</p>', '2014-10-22 00:00:00', 4, 125, 'https://images.blinkist.io/images/books/5447426930336100081f0000/1_1/470.jpg', '/en/books/economics-the-users-guide-en/purchase', 'اقتصاد:-راهنمای-کاربر', '2023-01-27 02:21:09.395293', '2023-01-27 02:21:09.395293', NULL, 'Economics: The User’s Guide');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1418, 'ترک کنید', 'قدرت دانستن زمان دور شدن', 'قدرت دانستن زمان دور شدن', 16, 6, 'book', 't', '<p><em>ترک </em>(2022) یک مهارت کم ارزش و مهم را که می تواند منجر به موفقیت شود، مورد استفاده قرار می دهد: دانستن زمان تعظیم. این توصیه‌های قدیمی را که شجاعت و پشتکار برای دستیابی به اهداف ضروری است - و راهنمای نحوه ترک سیگار، حتی زمانی که دشوار است، ارائه می‌دهد. </p>', '2022-11-09 00:00:00', 5, 209, 'https://images.blinkist.io/images/books/636a1726958fe900087a3842/1_1/470.jpg', '/en/books/quit-en/purchase', 'ترک-کنید', '2023-01-27 02:21:16.968758', '2023-01-27 02:21:16.968758', NULL, 'Quit');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1419, 'یک سال با پیتر دراکر', '52 هفته مربیگری برای اثربخشی رهبری', '52 هفته مربیگری برای اثربخشی رهبری', 17, 7, 'book', 't', '<p><em>یک سال با پیتر دراکر </em>(2014) گنجینه‌ای از ضروری‌ترین بینش‌های استاد مدیریت را ارائه می‌دهد که به نام «دراکریسم» شناخته می‌شود. طی دهه‌ها، پیتر دراکر (که در سال 2005 درگذشت) یک فلسفه پیشگامانه از رهبری و موفقیت را توسعه داد، آموزه‌هایی که به طور سعادتمندانه‌ای عاری از اصطلاحاتی است که امروزه بر مطالعات مدیریتی حاکم است.</p>', '2014-12-11 00:00:00', 4, 56, 'https://images.blinkist.io/images/books/54883ed93835630009050000/1_1/470.jpg', '/en/books/a-year-with-peter-drucker-en/purchase', 'یک-سال-با-پیتر-دراکر', '2023-01-27 02:21:25.194211', '2023-01-27 02:21:25.194211', NULL, 'A Year with Peter Drucker');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1420, 'صفات تغییر یافته', 'علم نشان می دهد که چگونه مدیتیشن ذهن، مغز و بدن شما را تغییر می دهد', 'علم نشان می دهد که چگونه مدیتیشن ذهن، مغز و بدن شما را تغییر می دهد', 21, 8, 'book', 't', '<p><em>Altered Traits</em>(2017) نگاهی تجربی به هنر مدیتیشن دارد و مزایایی را که بر سلامت ذهنی ما دارد به تفصیل شرح می دهد. همچنین به انواع مختلف مدیتیشن و همچنین اثرات تمرین‌های مراقبه بر گروه‌های مختلف، از جمله مراقبه‌گران با تجربه، دانش‌آموزان و حتی یک یوگی نگاه می‌کند.</p>', '2018-10-05 00:00:00', 5, 180, 'https://images.blinkist.io/images/books/5bb5c7f5862c430007d26da9/1_1/470.jpg', '/en/books/altered-traits-en/purchase', 'صفات-تغییر-یافته', '2023-01-27 02:21:33.454071', '2023-01-27 02:21:33.454071', NULL, 'Altered Traits');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1421, 'خوردن حیوانات', '(الف) اخلاق عادات و سنت های غذایی ما', '(الف) اخلاق عادات و سنت های غذایی ما', 21, 11, 'book', 't', '<p><em>Eating Animals</em> (2009) نمایی جامع از صنعت مدرن گوشت ارائه می‌دهد و نشان می‌دهد که چگونه کل فرآیند تولید آنقدر کاملاً منحرف شده است که دیگر به عنوان کشاورزی قابل تشخیص نیست.</p>
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1422, 'دزدی مثل یک هنرمند', '10 چیزی که هیچ کس در مورد خلاق بودن به شما نگفته است', '10 چیزی که هیچ کس در مورد خلاق بودن به شما نگفته است', 12, 6, 'book', 't', '<p><em>دزدی مانند یک هنرمند </em>(2012) به شما کمک می‌کند راز خلق هنر عالی را کشف کنید: سرقت. هیچ هنرمندی آثار خود را در خلاء خلق نمی کند: همه هنرها تحت تأثیر هنری هستند که قبل از آن بوده اند. <em>دزدی مانند یک هنرمند</em> به شما می آموزد که چگونه از کار قهرمانان خود "دزدی" کنید و از آن برای ایجاد چیزی جدید و منحصر به فرد استفاده کنید. همچنین توصیه های مهمی در مورد استفاده از اینترنت برای راه اندازی حرفه خود ارائه می دهد تا دیگران از خلاقیت شما لذت ببرند!</p>', '2015-02-25 00:00:00', 5, 226, 'https://images.blinkist.io/images/books/54eaf1c7393366000a590000/1_1/470.jpg', '/en/books/steal-like-an-artist-en/purchase', 'دزدی-مثل-یک-هنرمند', '2023-01-27 02:21:46.569467', '2023-01-27 02:21:46.569467', NULL, 'Steal Like an Artist');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1475, 'سود از مثبت', 'استراتژی های رهبری اثبات شده برای افزایش بهره وری و تغییر کسب و کار شما', 'استراتژی های رهبری اثبات شده برای افزایش بهره وری و تغییر کسب و کار شما', 16, 9, 'book', 'f', '<p><em>سود از مثبت</em> توضیح می دهد که چگونه رهبران می توانند بهره وری، همکاری و سودآوری را با استفاده از ابزارهای روانشناسی مثبت برای افزایش عملکرد کارکنان خود افزایش دهند. مثال‌های واضحی از اینکه چگونه تغییرات کوچک می‌توانند تفاوت‌های بزرگ ایجاد کنند، ارائه می‌کند.</p>', '2014-10-08 08:30:00', 4, 13, 'https://images.blinkist.io/images/books/543392a234373600081a0000/1_1/470.jpg', '/en/books/profit-from-the-positive-en/purchase', 'سود-از-مثبت', '2023-01-27 02:27:57.364837', '2023-01-27 02:27:57.364837', NULL, 'Profit from the Positive');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1423, 'چگونه شنیده شویم', 'رازهایی برای صحبت کردن و گوش دادن قدرتمند', 'رازهایی برای صحبت کردن و گوش دادن قدرتمند', 15, 6, 'book', 't', '<p><em>چگونه شنیده شویم </em>(2017) راه‌های اثبات شده برای تبدیل شدن به یک سخنران قدرتمند را شناسایی می‌کند، نوعی که توجه افراد را جلب می‌کند و آنها را در تک تک کلمات شما نگه می‌دارد. نویسنده جولیان تریزور همچنین گام‌هایی را که افراد می‌توانند برای بهبود مهارت‌های شنیداری خود بردارند را بررسی می‌کند و به آنها اجازه می‌دهد تا آنچه را که گفته می‌شود بهتر درک کنند و شنونده احساس کند که شنیده می‌شود. این نکات می تواند به بهبود مهارت های ارتباطی و مهم ترین روابط ما کمک کند.</p>', '2018-02-26 00:00:00', 4, 118, 'https://images.blinkist.io/images/books/5a927133b238e10006d081f2/1_1/470.jpg', '/en/books/how-to-be-heard-en/purchase', 'چگونه-شنیده-شویم', '2023-01-27 02:21:53.952257', '2023-01-27 02:21:53.952257', NULL, 'How to be Heard');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1424, 'توسعه رهبر درون شما', 'مبانی کتاب مقدس برای رهبری را کشف کنید', 'مبانی کتاب مقدس برای رهبری را کشف کنید', 16, 6, 'book', 't', '<p><em>توسعه رهبر درون شما</em> (1993) راهنمای تبدیل شدن به یک رهبر در هر زمینه ای است که انتخاب می کنید. این پلک‌ها سطوح رهبری، ویژگی‌های لازم برای دستیابی به آن‌ها و گام‌های مشخصی را که می‌توانید برای بالا رفتن از نردبان رهبری بردارید، نشان می‌دهد.</p>', '2018-01-11 00:00:00', 4, 159, 'https://images.blinkist.io/images/books/5a53443ab238e100063370d7/1_1/470.jpg', '/en/books/developing-the-leader-within-you-en/purchase', 'توسعه-رهبر-درون-شما', '2023-01-27 02:21:59.699926', '2023-01-27 02:21:59.699926', NULL, 'Developing the Leader Within You');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1425, 'همانطور که یک مرد فکر می کند', 'متن کلاسیکی که قدرت مثبت اندیشی را اثبات می کند', 'متن کلاسیکی که قدرت مثبت اندیشی را اثبات می کند', 8, 4, 'book', 't', '<p><em>As a Man Thinketh</em> (1903) فلسفه جیمز آلن را به تصویر می کشد. این پلک زدن ها قدرتی را که افکار بر شخصیت، شرایط و رفاه ما دارند، آشکار می کند. ما به مزایای یادگیری تسلط بر ذهن خود و هدایت افکار خود به سمت اهدافی که می خواهیم به آنها دست یابیم، پی می بریم.</p>', '2016-02-03 00:00:00', 4, 182, 'https://images.blinkist.io/images/books/56afa7f7377c160007000064/1_1/470.jpg', '/en/books/as-a-man-thinketh-en/purchase', 'همانطور-که-یک-مرد-فکر-می-کند', '2023-01-27 02:22:08.314116', '2023-01-27 02:22:08.314116', NULL, 'As A Man Thinketh');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1426, 'پیشی گرفتن از جمعیت', 'راهنمای سرمایه گذاران ارزشی برای شروع، ساختن و حفظ ثروت خانوادگی', 'راهنمای سرمایه گذاران ارزشی برای شروع، ساختن و حفظ ثروت خانوادگی', 17, 8, 'book', 't', '<p><em>پیشرفت از جمعیت</em> (2015) یک راهنمای مبتدی مبتدی برای سرمایه گذاری است. این پلک ها تمام دانش لازم برای شروع سرمایه گذاری را در اختیار شما قرار می دهد. فقط انتظار نداشته باشید که یک شبه ثروتمند شوید: سرمایه گذاری خوب به صبر، انضباط و عقلانیت بستگی دارد.</p>', '2016-05-23 00:00:00', 4, 66, 'https://images.blinkist.io/images/books/574087eed37f7e00034566ef/1_1/470.jpg', '/en/books/outsmarting-the-crowd-en/purchase', 'پیشی-گرفتن-از-جمعیت', '2023-01-27 02:22:15.63707', '2023-01-27 02:22:15.63707', NULL, 'Outsmarting the Crowd');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1427, 'مزیت', 'چرا سلامت سازمانی هر چیز دیگری را در کسب و کار رد می کند؟', 'چرا سلامت سازمانی هر چیز دیگری را در کسب و کار رد می کند؟', 25, 11, 'book', 't', '<p>این پلک‌ها اصول کلیدی برای ساختن یک سازمان سالم را نشان می‌دهند که در آن همه کارکنان در یک جهت و به دنبال اهداف یکسانی گرد هم می‌آیند. این سازمان ها را قادر می سازد تا به پتانسیل کامل خود دست یابند، در حالی که رقبای ناسالم منابع را در کشمکش های داخلی هدر می دهند.</p>', '2014-04-01 11:16:37', 5, 121, 'https://images.blinkist.io/images/books/533af8903961370007000000/1_1/470.jpg', '/en/books/the-advantage-en/purchase', 'مزیت', '2023-01-27 02:22:21.805122', '2023-01-27 02:22:21.805122', NULL, 'The Advantage');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1428, 'جادوی ریاضیات', 'حل x و پی بردن به چرایی', 'حل x و پی بردن به چرایی', 15, 8, 'book', 'f', '<p><em>جادوی ریاضیات</em> (2015) جادوی پنهان در دنیای شگفت انگیز ریاضیات را نشان می دهد. این پلک‌ها الگوهای زیبا و اغلب شگفت‌انگیز مشاهدات ریاضی را به شما نشان می‌دهند، دانش شما را در مورد هندسه و جبر گسترش می‌دهند، ترفندهای مهمانی عددی را به شما آموزش می‌دهند و ویژگی‌های اسرارآمیز اعدادی مانند π (pi) را روشن می‌کنند.</p>', '2016-03-01 00:00:00', 4, 31, 'https://images.blinkist.io/images/books/56d44a35bb82ae000700005f/1_1/470.jpg', '/en/books/the-magic-of-maths-en/purchase', 'جادوی-ریاضیات', '2023-01-27 02:22:29.786415', '2023-01-27 02:22:29.786415', NULL, 'The Magic of Maths');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1429, 'صاحب هر روز خود شوید', 'بر فشار برای اثبات و نشان دادن کاری که مجبور به انجام آن شده اید غلبه کنید', 'بر فشار برای اثبات و نشان دادن کاری که مجبور به انجام آن شده اید غلبه کنید', 17, 6, 'book', 't', '<p><em>مالک هر روز خود باشید</em> راهنمایی برای یافتن خود و هدف واقعی خود در زندگی است. این پلک ها هم روایتی عمیقاً شخصی از زندگی نویسنده است و هم طرحی عملی برای تغییر زندگی شما. آنها به شما نشان خواهند داد که چگونه فشارهای مداوم زندگی مدرن را به نفع چیزی رضایت بخش تر از خود دور کنید.</p>', '2020-06-18 00:00:00', 4, 397, 'https://images.blinkist.io/images/books/5ee394126cee070006eca45f/1_1/470.jpg', '/en/books/own-your-everyday-en/purchase', 'صاحب-هر-روز-خود-شوید', '2023-01-27 02:22:37.277872', '2023-01-27 02:22:37.277872', NULL, 'Own Your Everyday');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1483, 'چگونه یک کودک وحشی تربیت کنیم', 'هنر و علم عاشق شدن با طبیعت', 'هنر و علم عاشق شدن با طبیعت', 14, 7, 'book', 't', '<p><em>چگونه یک کودک وحشی تربیت کنیم</em> (2015) به خانواده شما کمک می کند تا دوباره با طبیعت ارتباط برقرار کنند. با نکات مفید و استراتژی های هوشمندانه، این پلک زدن ها اطمینان حاصل می کند که فرزندان شما می توانند از مزایای علمی اثبات شده بزرگ شدن در فضای باز لذت ببرند.</p>', '2016-04-11 00:00:00', 4, 24, 'https://images.blinkist.io/images/books/57096a898b5d6e0003000032/1_1/470.jpg', '/en/books/how-to-raise-a-wild-child-en/purchase', 'چگونه-یک-کودک-وحشی-تربیت-کنیم', '2023-01-27 02:28:49.343819', '2023-01-27 02:28:49.343819', NULL, 'How to Raise a Wild Child');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1430, 'وعده مداد', 'چگونه یک فرد معمولی می تواند تغییری خارق العاده ایجاد کند', 'چگونه یک فرد معمولی می تواند تغییری خارق العاده ایجاد کند', 18, 11, 'book', 'f', '<p>این کتاب داستان الهام بخش Adam Braun و Pencils of Promise را روایت می کند، خیریه ای که او با تنها 25 دلار تأسیس کرد و بیش از 500 مدرسه در کشورهای در حال توسعه در سراسر جهان ساخته است. این کتاب به درس‌های ساده‌ای تقسیم می‌شود که نشان می‌دهد چگونه همه می‌توانند اشتیاق خود را پیدا کنند، از پتانسیل خود بهترین استفاده را ببرند و زندگی پر از معنا، شادی و الهام داشته باشند.</p>', '2014-06-17 00:00:00', 4, 13, 'https://images.blinkist.io/images/books/53a121dd6230370007040000/1_1/470.jpg', '/en/books/the-promise-of-a-pencil-en/purchase', 'وعده-مداد', '2023-01-27 02:22:44.719985', '2023-01-27 02:22:44.719985', NULL, 'The Promise of a Pencil');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1431, 'استاندارد بیت کوین', 'جایگزین غیرمتمرکز بانک مرکزی', 'جایگزین غیرمتمرکز بانک مرکزی', 27, 9, 'book', 't', '<p><em>استاندارد بیت‌کوین </em>(2018) داستان پول را از اولین ارزهای سنگی گرفته تا رابطه عاشقانه ویکتوریایی‌ها با طلا و بچه جدید امروز در بلوک - ارز دیجیتال دیجیتال، ردیابی می‌کند. Saifedean Ammous، یک اقتصاددان که متقاعد شده است که ما باید از فضایل فراموش شده پول سالم استقبال کنیم، معتقد است که بیت کوین ممکن است آینده باشد. مانند ذخایر طلای گذشته، این طلا دارای ویژگی‌های منحصربه‌فردی است که به این معناست که در موقعیت ایده‌آلی قرار دارد تا به‌عنوان وسیله مبادله‌ای عمل کند که نمی‌توان آن را توسط دولت‌های متزلزل دستکاری کرد. و اگر بخواهیم اقتصاد خود را به ثبات و رشد بازگردانیم و چرخه رونق و رکود را پشت سر بگذاریم، این خبر خوبی است.</p>', '2019-01-11 00:00:00', 5, 445, 'https://images.blinkist.io/images/books/5c35c7706cee0700078a9bba/1_1/470.jpg', '/en/books/the-bitcoin-standard-en/purchase', 'استاندارد-بیت-کوین', '2023-01-27 02:22:51.666759', '2023-01-27 02:22:51.666759', NULL, 'The Bitcoin Standard');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1432, 'جهش بزرگ', 'بر ترس پنهان خود غلبه کنید و زندگی را به سطح بعدی ببرید', 'بر ترس پنهان خود غلبه کنید و زندگی را به سطح بعدی ببرید', 15, 7, 'book', 't', '<p><em>جهش بزرگ </em>(2009) گنجینه ای از بینش های ارزشمند در مورد چگونگی غلبه بر ترس ها و تمایلاتی است که در مسیر موفقیت پایدار قرار دارند. هندریکس راه‌های زیادی را به ما نشان می‌دهد که می‌توانیم رویاهای خود را خراب کنیم و راه‌های عملی برای اجتناب از این دام‌های بسیار رایج ارائه می‌دهد.</p>', '2018-02-08 00:00:00', 4, 102, 'https://images.blinkist.io/images/books/5a7824b5b238e100065411e0/1_1/470.jpg', '/en/books/the-big-leap-en/purchase', 'جهش-بزرگ', '2023-01-27 02:22:59.515938', '2023-01-27 02:22:59.515938', NULL, 'The Big Leap');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1433, 'دنیایی بدون ایمیل', 'تجسم مجدد کار در عصر پربار ارتباطات', 'تجسم مجدد کار در عصر پربار ارتباطات', 28, 8, 'book', 't', '<p><em>جهانی بدون ایمیل </em>(2021) تجسم مجدد جسورانه ای از محل کار ارائه می دهد، جایی که در آن روزهای ایمیل و پیام های فوری متعلق به گذشته است. این استدلال می کند که اگرچه ایمیل ممکن است بخشی جدایی ناپذیر از کار دانش مدرن به نظر برسد، اما در واقع باعث می شود همه افراد بهره وری و تمرکز کمتری داشته باشند، نه به ذکر است که بدبخت شوند. راه حل به یک تغییر پارادایم عمده نیاز دارد - اما ارزش تلاش را دارد.</p>', '2021-03-22 00:00:00', 4, 245, 'https://images.blinkist.io/images/books/605476216cee0700076902af/1_1/470.jpg', '/en/books/a-world-without-email-en/purchase', 'دنیایی-بدون-ایمیل', '2023-01-27 02:23:04.894472', '2023-01-27 02:23:04.894472', NULL, 'A World Without Email');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1434, 'تمدن', 'شش برنامه قاتل قدرت غربی', 'شش برنامه قاتل قدرت غربی', 20, 10, 'book', 't', '<p>به نظر می رسد بحران اعتماد در غرب وجود دارد. در مواجهه با قدرت رو به رشد چین، و با عدم علاقه ظاهری به تاریخ و تمدن خود، بسیاری از این بیم دارند که غرب به نوعی راه خود را گم کرده باشد.</p>
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1435, 'سرمایه گذاری با تاثیر', 'چرا امور مالی یک نیروی خوب است؟', 'چرا امور مالی یک نیروی خوب است؟', 13, 5, 'book', 't', '<p><em>Investing With Impact </em>(2015) به بررسی این موضوع می پردازد که چگونه مردم از قدرت سرمایه داری برای انجام کارهای خوب و بهبود جامعه در کل استفاده کرده اند. همانطور که تعدادی از سرمایه گذاران اخلاقی و بشردوستانه نشان داده اند، امور مالی نباید یک سیستم طمع خالص باشد. دریابید که چرا سیستم سرمایه داری که اغلب شیطانی می شود ممکن است راز نجات جهان باشد.</p>', '2017-08-17 00:00:00', 4, 49, 'https://images.blinkist.io/images/books/599304fcb238e100058f78b6/1_1/470.jpg', '/en/books/investing-with-impact-en/purchase', 'سرمایه-گذاری-با-تاثیر', '2023-01-27 02:23:18.611067', '2023-01-27 02:23:18.611067', NULL, 'Investing With Impact');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1466, 'بخور تا زندگی کنی', 'برنامه شگفت انگیز غنی از مواد مغذی برای کاهش وزن سریع و پایدار', 'برنامه شگفت انگیز غنی از مواد مغذی برای کاهش وزن سریع و پایدار', 22, 10, 'book', 't', '<p><em>Eat</em> <em>to</em> <em>Live</em> به خوانندگان یک دید کلی از تغذیه انسان، ارزیابی مجدد خرد متعارف تغذیه ای، مطالعات موردی شخصی و برنامه غذایی عملی با بسیاری از توصیه ها. خواننده می تواند انتظار داشته باشد که در مورد تعدادی از مطالعات مختلف تغذیه ای و همچنین فواید و عواقب سلامتی غذاهای اساسی مانند گوشت، شیر، ماهی، سبزیجات و میوه ها بیاموزد.</p>', '2014-04-15 06:21:13', 4, 124, 'https://images.blinkist.io/images/books/534d583066336100078f0000/1_1/470.jpg', '/en/books/eat-to-live-en/purchase', 'بخور-تا-زندگی-کنی', '2023-01-27 02:26:56.731159', '2023-01-27 02:26:56.731159', NULL, 'Eat to Live');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1436, 'انتشار ویروس ایده', 'بازاریابی در افراد را متوقف کنید! با کمک به مشتریان خود در انجام بازاریابی برای شما، ایده های خود را به اپیدمی تبدیل کنید', 'بازاریابی در افراد را متوقف کنید! با کمک به مشتریان خود در انجام بازاریابی برای شما، ایده های خود را به اپیدمی تبدیل کنید', 23, 8, 'book', 't', '<p><em>Unleashing the Ideavirus</em> (2000) نقشه ای را برای ترسیم یک کمپین بازاریابی موفق در چشم انداز رسانه های مدرن ارائه می دهد. این استدلال می‌کند که ظهور اینترنت و کاهش تبلیغات به‌عنوان روشی مؤثر برای دسترسی به مردم، حکم می‌کند که ما باید در نحوه رویکرد بازاریابی تجدیدنظر اساسی کنیم. و این رویکرد جدید باید پتانسیل انتشار ایده‌ها از طریق ارتباط همتا به همتا را در بر بگیرد.</p>', '2019-12-19 00:00:00', 4, 72, 'https://images.blinkist.io/images/books/5df8d8806cee070008c0014f/1_1/470.jpg', '/en/books/unleashing-the-ideavirus-en/purchase', 'انتشار-ویروس-ایده', '2023-01-27 02:23:24.282822', '2023-01-27 02:23:24.282822', NULL, 'Unleashing the Ideavirus');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1437, 'چرا دانش آموزان مدرسه را دوست ندارند؟', 'پاسخ یک دانشمند شناختی به سوالاتی درباره نحوه عملکرد ذهن و معنای آن برای کلاس درس', 'پاسخ یک دانشمند شناختی به سوالاتی درباره نحوه عملکرد ذهن و معنای آن برای کلاس درس', 21, 7, 'book', 't', '<p><em>چرا دانش آموزان مدرسه را دوست ندارند؟ </em>(2009) به دنبال توضیح مهم ترین فرآیندهای مغز در رابطه با حافظه، یادگیری و هوش است. درک قوی‌تر از این مکانیسم‌ها، همه مربیان را قادر می‌سازد تا خود را در روش‌های تدریس بهتر آموزش دهند و منجر به برنامه‌های آموزشی جذاب‌تر و مؤثرتر شوند.</p>', '2019-04-25 00:00:00', 4, 102, 'https://images.blinkist.io/images/books/5cbcf0156cee070008bad28a/1_1/470.jpg', '/en/books/why-dont-students-like-school-en/purchase', 'چرا-دانش-آموزان-مدرسه-را-دوست-ندارند؟', '2023-01-27 02:23:32.233383', '2023-01-27 02:23:32.233383', NULL, 'Why Don’t Students Like School?');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1438, 'کنسول جنگ', 'سگا، نینتندو و نبردی که یک نسل را تعریف کرد', 'سگا، نینتندو و نبردی که یک نسل را تعریف کرد', 15, 8, 'book', 'f', '<p><em>Console Wars</em> داستان حماسی و رقابتی صنعت شکل بین توسعه دهندگان بازی های ویدیویی <em>Sega</em> و <em>Nintendo</em> در اوایل دهه 1990 را شرح می دهد. در طی پنج سال کوتاه، سگا از یک مرد ضعیف مورد تمسخر به رهبر بازار ایالات متحده در بازی‌های کنسولی تبدیل شد، سلطه‌ای که اساساً مسیر آینده بازی را دیکته می‌کرد.</p>', '2014-11-28 00:00:00', 4, 10, 'https://images.blinkist.io/images/books/5475165530386200091d0000/1_1/470.jpg', '/en/books/console-wars-en/purchase', 'کنسول-جنگ', '2023-01-27 02:23:40.443273', '2023-01-27 02:23:40.443273', NULL, 'Console Wars');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1439, 'با یک داستان رهبری کنید', 'راهنمای ساخت روایت‌های تجاری که مجذوب، متقاعد و الهام‌بخش است', 'راهنمای ساخت روایت‌های تجاری که مجذوب، متقاعد و الهام‌بخش است', 19, 9, 'book', 't', '<p><em>Lead with a Story</em> (2012) به شما می آموزد که چگونه مهارت های خود را به عنوان یک رهبر بزرگ با استفاده از قدرت داستان سرایی افزایش دهید. با مثال‌هایی از یکی از موفق‌ترین شرکت‌های جهان، یاد می‌گیرید که چگونه یک داستان عالی بسازید که به مردم انگیزه می‌دهد و رفتار آنها را اصلاح می‌کند.</p>', '2014-11-14 00:00:00', 4, 75, 'https://images.blinkist.io/images/books/5463378966346600083e0000/1_1/470.jpg', '/en/books/lead-with-a-story-en/purchase', 'با-یک-داستان-رهبری-کنید', '2023-01-27 02:23:48.042192', '2023-01-27 02:23:48.042192', NULL, 'Lead with a Story');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1440, 'ظهور و سقوط دایناسورها', 'تاریخ جدیدی از دنیای گمشده', 'تاریخ جدیدی از دنیای گمشده', 28, 9, 'book', 't', '<p>در <em>ظهور و سقوط دایناسورها</em> (2018)، دیرینه‌شناس برجسته جوان، استیو بروسات، ما را به سفری در زمان و مکان می‌برد و تاریخچه دایناسورهای مختلف و جهان‌هایی را که در آن‌ها وجود دارند، شرح می‌دهد. زندگی می کرد. او با دانش عمیق خود از فسیل ها و شواهد زمین شناسی هدایت می شود و بنابراین می تواند داستان های جذاب دایناسورها را در کانون توجه قرار دهد.</p>', '2018-11-30 00:00:00', 5, 67, 'https://images.blinkist.io/images/books/5bfd77066cee070007f92783/1_1/470.jpg', '/en/books/the-rise-and-fall-of-the-dinosaurs-en/purchase', 'ظهور-و-سقوط-دایناسورها', '2023-01-27 02:23:55.936056', '2023-01-27 02:23:55.936056', NULL, 'The Rise and Fall of the Dinosaurs');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1441, 'بیشتر از کمتر', 'پیدا کردن زندگی که می خواهید زیر هر چیزی که دارید', 'پیدا کردن زندگی که می خواهید زیر هر چیزی که دارید', 20, 8, 'book', 't', '<p><em>بیشتر از کمتر</em>(2016) راهنمای نهایی برای به دست آوردن بیشتر از زندگی با داشتن مالکیت کمتر است. این کتابی عملی است که توسط یک چراغ پیشرو در جنبش رو به رشد آمریکا علیه مصرف گرایی بیش از حد و زندگی درهم ریخته نوشته شده است، این کتابی کاربردی است که به شما کمک می کند فضا، منابع و زمان را آزاد کنید تا بتوانید چیزهایی را که واقعاً مهم هستند دنبال کنید.</p>', '2018-12-26 00:00:00', 5, 388, 'https://images.blinkist.io/images/books/5c1ec4cb6cee070008e79f5d/1_1/470.jpg', '/en/books/the-more-of-less-en/purchase', 'بیشتر-از-کمتر', '2023-01-27 02:24:03.618462', '2023-01-27 02:24:03.618462', NULL, 'The More of Less');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1442, 'راه پرنده', 'نگاهی جدید به نحوه صحبت، کار، بازی، والدین و فکر پرندگان', 'نگاهی جدید به نحوه صحبت، کار، بازی، والدین و فکر پرندگان', 22, 7, 'book', 't', '<p><em>راه پرنده </em>(2020) مطالعه ای بر روی پرندگان است که هم از تخصص دانشمند و هم از لذت تماشاگر پرنده استفاده می کند. جشنی از تنوع حیرت‌انگیز پرندگان و رفتار آن‌ها، جهان را در تعقیب عملکرد درونی ذهن پرندگان کاوش می‌کند. از جنگل‌های بارانی پرآب کاستاریکا گرفته تا حومه‌های شهرهای استرالیا که در معرض خطر زاغی‌ها قرار گرفته‌اند، نحوه بازی، والدین و شکار پرندگان متفاوت از پیروان مورچه‌ها، طوطی‌ها، شکارچیان و زاغ‌ها را بررسی می‌کند.</p>', '2020-10-24 00:00:00', 4, 30, 'https://images.blinkist.io/images/books/5f9053856cee070007038947/1_1/470.jpg', '/en/books/the-bird-way-en/purchase', 'راه-پرنده', '2023-01-27 02:24:09.167299', '2023-01-27 02:24:09.167299', NULL, 'The Bird Way');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1443, 'قدرت دوره', 'هورمون های خود را مهار کنید و چرخه خود را برای خود به کار بگیرید', 'هورمون های خود را مهار کنید و چرخه خود را برای خود به کار بگیرید', 23, 8, 'book', 't', '<p><em>توان پریود</em>(2019) راهنمای نهایی شما برای پریود، هورمون ها و سلامت باروری است. Maisie Hill، متخصص سلامت قاعدگی توضیح می دهد که چگونه چرخه قاعدگی شما بر خلق و خو، خواب و انرژی شما تأثیر می گذارد و نشان می دهد که چگونه می توانید از قدرت هورمون های خود استفاده کنید تا از هر مرحله از چرخه خود بیشترین بهره را ببرید. هیل با تکیه بر علم و تجربه شخصی، شما را به ابزار و دانشی مجهز می کند تا «مشکلات زنانه» خود را به قدرت دوره تبدیل کنید.</p>', '2020-01-07 00:00:00', 5, 63, 'https://images.blinkist.io/images/books/5e11f5fd6cee070008dc6f28/1_1/470.jpg', '/en/books/period-power-en/purchase', 'قدرت-دوره', '2023-01-27 02:24:16.865647', '2023-01-27 02:24:16.865647', NULL, 'Period Power');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1444, 'ماوریکس', 'چگونه رهبری جسور جهان را تغییر می دهد', 'چگونه رهبری جسور جهان را تغییر می دهد', 28, 8, 'book', 't', '<p><em>Mavericks </em>(2022) یک مورد برای رهبری ماوریک ایجاد می کند. این نشان می‌دهد که متفکران مستقل با انگیزه اهداف معنادار می‌توانند مشاغل و جوامع خود را متحول کنند - و هر کسی می‌تواند با تمرکز بر پنج ویژگی کلیدی، مغرور درونی خود را توسعه دهد.</p>', '2022-06-24 00:00:00', 4, 228, 'https://images.blinkist.io/images/books/62a1a8376cee0700084f3d30/1_1/470.jpg', '/en/books/mavericks-en/purchase', 'ماوریکس', '2023-01-27 02:24:24.506684', '2023-01-27 02:24:24.506684', NULL, 'Mavericks');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1445, 'خودت بشنو', 'چگونه در دنیای پر سر و صدا آرامش پیدا کنیم', 'چگونه در دنیای پر سر و صدا آرامش پیدا کنیم', 23, 8, 'book', 't', '<p><em>Hear Yourself</em>(2021) راهنمای حذف حواس‌پرتی‌ها، خاموش کردن ذهن و اتصال به آرامش درونی است. مملو از حکمت باستانی و حکایات قانع کننده، به شما می آموزد که برای مقابله با سر و صدا و مشغله های دنیای بیرون، آرامش و آرامش را در درون خود پرورش دهید.</p>', '2021-11-22 00:00:00', 5, 361, 'https://images.blinkist.io/images/books/618d37ad6cee070008d52c9a/1_1/470.jpg', '/en/books/hear-yourself-en/purchase', 'خودت-بشنو', '2023-01-27 02:24:31.864838', '2023-01-27 02:24:31.864838', NULL, 'Hear Yourself');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1446, 'توهم خدا', 'علم پشت بیخدایی', 'علم پشت بیخدایی', 26, 11, 'book', 't', '<p><em>هذیان خدا</em> (2006) محبوب‌ترین استدلال‌ها و استدلال‌ها برای وجود خدا را تجزیه می‌کند تا نامحتمل بودن آماری و منطقی وجود واقعی یک موجود برتر را نشان دهد. این پلک‌ها توضیح می‌دهند که چرا دین <em>نباید</em>پایه‌ای برای اخلاقیات جامعه باشد و چگونه می‌تواند واقعاً برای استانداردهای اخلاقی ما مضر باشد.</p>', '2015-10-28 00:00:00', 4, 249, 'https://images.blinkist.io/images/books/519de7b5e4b0a17389a8ac0f/1_1/470.jpg', '/en/books/the-god-delusion-en/purchase', 'توهم-خدا', '2023-01-27 02:24:37.323563', '2023-01-27 02:24:37.323563', NULL, 'The God Delusion');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1447, 'چه می شود اگر؟ 2', 'پاسخ های علمی جدی اضافی به سؤالات فرضی پوچ', 'پاسخ های علمی جدی اضافی به سؤالات فرضی پوچ', 17, 7, 'book', 't', '<p><em>اگر؟ 2</em>(2022) دنباله رندال مونرو بر پرفروش‌ترین <em>نیویورک تایمز</em> <em>چه می‌شد اگر؟ </em>همانند نسخه قبلی خود، شامل پاسخ های علمی جدی مونرو به سؤالات پوچ، خنده دار و عجیبی است که خوانندگان برای او ارسال کرده اند، از جمله «اگر یک گلوله برفی از بالای کوه اورست به پایین غلت بخورد چقدر بزرگ می شود. ؟" به "آیا یک نفر می تواند یک ابر را بخورد؟"</p>', '2023-01-03 00:00:00', 4, 19, 'https://images.blinkist.io/images/books/63ab14c873bf6d0009f22107/1_1/470.jpg', '/en/books/what-if-2-en/purchase', 'چه-می-شود-اگر؟-2', '2023-01-27 02:24:42.26618', '2023-01-27 02:24:42.26618', NULL, 'What If? 2');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1448, 'برای برنده شدن متولد شد', 'موفقیت خود را بیابید', 'موفقیت خود را بیابید', 15, 6, 'book', 't', '<p><em>Born to Win </em>(2012) یک فلسفه ساده اما موثر برای موفقیت را آموزش می دهد: ابتدا باید برنامه ریزی کنید و برای برنده شدن آماده شوید، تنها در این صورت می توانید انتظار برنده شدن را داشته باشید. این کتاب نحوه اجرای این فلسفه را از ایجاد چشم انداز و اهداف گرفته تا تجهیز خود برای موفقیت نشان می دهد. همچنین اهمیت مثبت اندیشی و پرورش کل وجود شما را برجسته می کند.</p>', '2021-06-07 00:00:00', 5, 187, 'https://images.blinkist.io/images/books/60b8b3316cee070007296f5a/1_1/470.jpg', '/en/books/born-to-win-en/purchase', 'برای-برنده-شدن-متولد-شد', '2023-01-27 02:24:49.635454', '2023-01-27 02:24:49.635454', NULL, 'Born to Win');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1449, 'رژیم مالی', 'راهنمای کامل مبتدیان برای خوب شدن با پول', 'راهنمای کامل مبتدیان برای خوب شدن با پول', 19, 7, 'book', 't', '<p><em>رژیم غذایی مالی </em>(2018) یک راهنمای مبتدی برای بهتر شدن با پول است. چه بخواهید عادات خرج کردن خود را تحت کنترل درآورید، چه بخواهید بدهی های دانشجویی خود را بپردازید یا فقط بفهمید که چگونه برای آینده پول پس انداز کنید، این پلک زدن ها ابزارهای لازم برای انجام این کار را در اختیار شما قرار می دهد.</p>', '2018-08-31 00:00:00', 4, 104, 'https://images.blinkist.io/images/books/5b86673db238e1000726cca4/1_1/470.jpg', '/en/books/the-financial-diet-en/purchase', 'رژیم-مالی', '2023-01-27 02:24:56.945552', '2023-01-27 02:24:56.945552', NULL, 'The Financial Diet');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1458, 'مسیر نمک', 'داستان زن و شوهری است که همه چیز خود را از دست دادند و به سواحل انگلیس رفتند', 'داستان زن و شوهری است که همه چیز خود را از دست دادند و به سواحل انگلیس رفتند', 21, 8, 'book', 't', '<p><em>مسیر نمک</em> (2018) داستانی از تراژدی است - و نحوه واکنش یک زوج به آن. در عرض یک هفته، به نویسنده، رینور وین، اخطار تخلیه داده شد و همسرش، موت، به بیماری لاعلاج تشخیص داده شد. اما، رینور و موث به جای تسلیم شدن در برابر ناامیدی، بی خانمانی را پذیرفتند و تصمیم گرفتند در مسیر ساحلی جنوب غربی در جنوب انگلستان پیاده روی کنند. <em>مسیر نمک</em>داستان پیاده روی 630 مایلی آنها به سوی آینده ای نامطمئن است.</p>', '2020-04-19 00:00:00', 4, 23, 'https://images.blinkist.io/images/books/5e95bf3f6cee0700060a0e01/1_1/470.jpg', '/en/books/the-salt-path-en/purchase', 'مسیر-نمک', '2023-01-27 02:26:02.764662', '2023-01-27 02:26:02.764662', NULL, 'The Salt Path');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1450, 'تورم مهم است', 'تئوری موج تورمی، تاثیر آن بر تورم گذشته و حال ... و تورم در آینده', 'تئوری موج تورمی، تاثیر آن بر تورم گذشته و حال ... و تورم در آینده', 19, 5, 'book', 't', '<p><em>Inflation Matters </em>(2015) آنچه را که اغلب به عنوان یک موضوع فشرده و پیچیده ارائه می شود - و نه خسته کننده - در نظر می گیرد و آن را به چیزی تبدیل می کند که همه می توانند بفهمند. با استفاده از توضیحات ساده و واضح، دلایل وجود تورم، چه چیزی و چه کسی آن را تداوم می بخشد و چگونه بر اقتصاد و جامعه به عنوان یک کل تأثیر می گذارد، ارائه می دهد. با تجزیه و تحلیل روندهای تاریخی، همچنین نظریه ای را ارائه می دهد که تورم در طول زمان از یک الگوی موجی پیروی می کند -⁠ اما لزوماً نیازی به باقی ماندن آن وجود ندارد.</p>', '2022-10-06 00:00:00', 4, 246, 'https://images.blinkist.io/images/books/633c1d4f6cee0700081b479f/1_1/470.jpg', '/en/books/inflation-matters-en/purchase', 'تورم-مهم-است', '2023-01-27 02:25:04.218685', '2023-01-27 02:25:04.218685', NULL, 'Inflation Matters');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1451, 'استراتژیست جدید', 'سازمان خود را شکل دهید و جلوتر از تغییر باشید', 'سازمان خود را شکل دهید و جلوتر از تغییر باشید', 24, 7, 'book', 't', '<p><em>استراتژیست جدید</em> (2020) یک راهنمای عملی در مورد نحوه انجام استراتژی برای رهبران کسب و کار است. توضیح می‌دهد که کار استراتژی در زندگی روزمره یک شرکت چگونه به نظر می‌رسد، شایستگی‌هایی را که رهبران استراتژیک به آن نیاز دارند نشان می‌دهد، و ابزارهایی را ارائه می‌کند که به استراتژیست‌ها در کارشان کمک می‌کند. همچنین راه‌هایی را که استراتژیست‌ها برای انطباق با دنیای در حال تغییر نیاز دارند، بررسی می‌کند و اصولی را ارائه می‌کند که می‌توانند از آنها برای رهبران موفق استفاده کنند.</p>', '2020-05-21 00:00:00', 4, 105, 'https://images.blinkist.io/images/books/5eb72e0c6cee070006697f78/1_1/470.jpg', '/en/books/the-new-strategist-en/purchase', 'استراتژیست-جدید', '2023-01-27 02:25:11.344828', '2023-01-27 02:25:11.344828', NULL, 'The New Strategist');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1452, 'معنی دار', 'داستان ایده هایی که پرواز می کنند', 'داستان ایده هایی که پرواز می کنند', 11, 5, 'book', 't', '<p><em>معنی‌دار</em> (2015) راهنمای اصلی قرار دادن مشتریان در کسب‌وکار شما است. این پلک ها، با آموزش نحوه تولید محصولی که واقعاً برای مشتریان شما اهمیت دارد و به آنها قدرت می بخشد، برند شما را کاملاً با خواسته های قرن بیست و یکم هماهنگ می کند.</p>', '2016-02-10 00:00:00', 4, 18, 'https://images.blinkist.io/images/books/56b8ab65d119f9000700002a/1_1/470.jpg', '/en/books/meaningful-en/purchase', 'معنی-دار', '2023-01-27 02:25:16.870754', '2023-01-27 02:25:16.870754', NULL, 'Meaningful');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1453, 'تمرکز راه حل بی امان', 'ذهن خود را برای غلبه بر استرس، فشار و عملکرد ضعیف آموزش دهید', 'ذهن خود را برای غلبه بر استرس، فشار و عملکرد ضعیف آموزش دهید', 24, 8, 'book', 't', '<p><em> تمرکز راه حل بی امان </em>(2021) نشان می دهد که چگونه داشتن یک طرز فکر خوش بینانه تر می تواند زندگی ما را متحول کند. نویسندگان با استفاده از یک فرآیند سه مرحله‌ای، بینش‌ها، ابزارها و چارچوب‌هایی را برای توسعه سرسختی ذهنی مورد نیاز برای از بین بردن تمایلات ما به سمت منفی‌گرایی به اشتراک می‌گذارند.</p>', '2021-03-17 00:00:00', 5, 159, 'https://images.blinkist.io/images/books/604b46626cee0700071de23d/1_1/470.jpg', '/en/books/relentless-solution-focus-en/purchase', 'تمرکز-راه-حل-بی-امان', '2023-01-27 02:25:24.283921', '2023-01-27 02:25:24.283921', NULL, 'Relentless Solution Focus');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1454, 'خدمت بالا، مربی پایین', 'تسلط بر میانه و هر دو طرف رهبری', 'تسلط بر میانه و هر دو طرف رهبری', 25, 8, 'book', 't', '<p><em>Serve Up, Coach Down </em>(2018) یک راهنمای رهبری شرکتی برای مدیران میانی است. با به اشتراک گذاشتن استراتژی‌هایی که برای مدیریت مؤثر تیم <em>و </em>رئیس خود به آنها نیاز دارند، کارگران را قادر می‌سازد تا «مسلط بر وسط» شوند.', '2020-09-18 00:00:00', 4, 110, 'https://images.blinkist.io/images/books/5f60b6ed6cee070006e450c9/1_1/470.jpg', '/en/books/serve-up-coach-down-en/purchase', 'خدمت-بالا،-مربی-پایین', '2023-01-27 02:25:32.207402', '2023-01-27 02:25:32.207402', NULL, 'Serve Up, Coach Down');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1455, 'دنیایت را عوض کن', 'چگونه هر کسی، هر کجا می تواند تفاوت ایجاد کند', 'چگونه هر کسی، هر کجا می تواند تفاوت ایجاد کند', 25, 7, 'book', 't', '<p><em>دنیای خود را تغییر دهید </em>(2021) یک راهنمای عملی برای کسانی است که مشتاق تغییر خود و جوامع خود هستند. به جای ترساندن از همه مشکلات دنیا، می‌توانیم مسائلی را که برایمان مهم‌تر هستند شناسایی کنیم و برای یافتن راه‌حل اقدامات مشخصی انجام دهیم. حتی اقدامات کوچک نیز می توانند اثری موج دار داشته باشند و دیگران را ترغیب کنند تا در تلاش برای تغییر به ما بپیوندند. </p>', '2021-03-15 00:00:00', 4, 121, 'https://images.blinkist.io/images/books/604b2b436cee07000793795f/1_1/470.jpg', '/en/books/change-your-world-en/purchase', 'دنیایت-را-عوض-کن', '2023-01-27 02:25:42.861897', '2023-01-27 02:25:42.861897', NULL, 'Change Your World');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1456, 'انسان سازی کنید', 'چگونه سازمان های مردم محور در یک دنیای اجتماعی موفق می شوند', 'چگونه سازمان های مردم محور در یک دنیای اجتماعی موفق می شوند', 16, 9, 'book', 'f', '<p>در این راهنمای عملی هم برای صاحبان مشاغل و هم برای کارمندان، مشاوران پیشرو سازمان، جیمی ناتر و مدی گرانت، نکات مهمی را برای چگونگی «انسانی کردن» شرکت‌ها در سطح فرهنگی و سازمانی ارائه می‌دهند - همه اینها به منظور موقعیت‌یابی شرکت رشد موثر در عصر رسانه های اجتماعی.</p>', '2014-12-22 00:00:00', NULL, 3, 'https://images.blinkist.io/images/books/548a13d93363370009580000/1_1/470.jpg', '/en/books/humanize-en/purchase', 'انسان-سازی-کنید', '2023-01-27 02:25:50.968999', '2023-01-27 02:25:50.968999', NULL, 'Humanize');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1459, 'قدرت تغییر دهنده زندگی سوفرولوژی', 'نفس بکش و با افراد آرام و شاد ارتباط برقرار کن', 'نفس بکش و با افراد آرام و شاد ارتباط برقرار کن', 20, 7, 'book', 't', '<p><em>قدرت تغییر دهنده زندگی سوفرولوژی</em> (2018) به عمق "ابر قدرت ملایم" سوفرولوژی می پردازد، یک تمرین درمانی منحصر به فرد که از تکنیک های تنفس، مدیتیشن و تجسم خلاق برای کاهش استرس استفاده می کند و شما را قادر می سازد. برای مدیریت چالش های زندگی روزمره ابزار ساده اما قدرتمند Sophrology با همه سبک های زندگی و برنامه ها سازگار است - فقط چند دقیقه تمرین در روز شما را به بهبود سلامت، شادی و رفاه راهنمایی می کند. </p>', '2019-09-17 00:00:00', 4, 85, 'https://images.blinkist.io/images/books/5d7b5cf06cee070007d54fd9/1_1/470.jpg', '/en/books/the-life-changing-power-of-sophrology-en/purchase', 'قدرت-تغییر-دهنده-زندگی-سوفرولوژی', '2023-01-27 02:26:09.845274', '2023-01-27 02:26:09.845274', NULL, 'The Life-Changing Power of Sophrology');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1460, 'قوانین سرایت', 'چرا چیزها گسترش می یابند - و چرا متوقف می شوند', 'چرا چیزها گسترش می یابند - و چرا متوقف می شوند', 24, 7, 'book', 't', '<p><em>قوانین سرایت</em> (2020) نگاهی علمی و ریاضی به نحوه انتشار ویروس‌ها و اینکه چگونه ایده‌ها، رفتار و محتوای آنلاین محبوب همه از الگوهای مشابهی پیروی می‌کنند، دارد. با پیروی از قوانین سرایت، می‌توانیم در مورد گسترش ایده‌ها، عواملی که باعث بلایای مالی می‌شوند، و اینکه چگونه اعمال مضری مانند خشونت با اسلحه می‌توانند جامعه را آلوده کنند، بینشی به دست آوریم.</p>', '2020-04-13 00:00:00', 4, 84, 'https://images.blinkist.io/images/books/5e903f4b6cee0700069967c5/1_1/470.jpg', '/en/books/the-rules-of-contagion-en/purchase', 'قوانین-سرایت', '2023-01-27 02:26:17.299726', '2023-01-27 02:26:17.299726', NULL, 'The Rules of Contagion');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1461, 'شجاعانه دوست داشتن', 'بیست درس از خودیابی برای کمک به شما برای رسیدن به عشقی که می خواهید', 'بیست درس از خودیابی برای کمک به شما برای رسیدن به عشقی که می خواهید', 30, 8, 'book', 't', '<p><em>Loving Bravely </em>(2017) آغازگر یافتن عشق از طریق درون نگری و خودشناسی است. این راهنمای عشق درس‌های ارزشمندی در مورد چگونگی ایجاد روابطی که واقعاً دوام می‌آورند به شما می‌آموزد.</p>', '2021-07-17 00:00:00', 4, 211, 'https://images.blinkist.io/images/books/60ec2dd66cee070007752b5d/1_1/470.jpg', '/en/books/loving-bravely-en/purchase', 'شجاعانه-دوست-داشتن', '2023-01-27 02:26:24.276459', '2023-01-27 02:26:24.276459', NULL, 'Loving Bravely');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1462, 'MBA شخصی', 'در هنر تجارت مسلط شوید', 'در هنر تجارت مسلط شوید', 19, 9, 'book', 't', '<p><em>MBA شخصی </em>شامل همه چیزهایی است که در تجارت باید بدانید. امروزه، رهبران واقعی کسب و کار از طریق تجربه و تحقیقات شخصی خود ساخته می شوند، نه در دانشگاه ها. از توسعه ایده‌تان تا بستن یک معامله، این پلک‌ها شما را در کل فرآیند تبدیل شدن به یک داستان موفقیت کسب‌وکار خودساخته راهنمایی می‌کنند.</p>', '2015-02-10 00:00:00', 4, 117, 'https://images.blinkist.io/images/books/54d8953c383963000a3f0000/1_1/470.jpg', '/en/books/the-personal-mba-en/purchase', 'MBA-شخصی', '2023-01-27 02:26:29.850394', '2023-01-27 02:26:29.850394', NULL, 'The Personal MBA');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1463, 'بازگشت به عشق', 'تأملاتی در اصول یک دوره در معجزات', 'تأملاتی در اصول یک دوره در معجزات', 17, 7, 'book', 't', '<p><em>بازگشت به عشق </em>(1992) فراخوانی قدرتمند برای تسلیم شدن خود به قدرتی بالاتر در جهان با طرد نفس و در آغوش کشیدن عشق است. پیام تأمل برانگیز ماریان ویلیامسون به ما نشان می‌دهد که چگونه ترس‌ها و رنجش‌هایی را که باعث سرکوب عشقی که همه ما در درون خود داریم، رها کنیم. گام های عملی او به شما کمک می کند تا روابط، شغل و خوشبختی کلی خود را بهبود بخشید.</p>', '2018-03-28 00:00:00', 4, 103, 'https://images.blinkist.io/images/books/5ab6f0dcb238e10005bf5917/1_1/470.jpg', '/en/books/a-return-to-love-en/purchase', 'بازگشت-به-عشق', '2023-01-27 02:26:37.191747', '2023-01-27 02:26:37.191747', NULL, 'A Return to Love');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1464, 'هندسه ثروت', 'چگونه یک زندگی با پول و معنا شکل دهیم', 'چگونه یک زندگی با پول و معنا شکل دهیم', 21, 8, 'book', 't', '<p><em>هندسه ثروت </em>(2018) یک راهنمای عملی برای مدیریت امور مالی شما است. مملو از خرد مالی و نکات عملی مدیریت پول، این پلک ها همچنین به سؤالات بزرگتر و فلسفی در مورد فراوانی نگاه می کنند. نویسنده برایان پورتنوی استدلال می کند که برنامه ریزی مادی و معنوی دست به دست هم می دهند. مراقب هر دو باشید تا به ثروت واقعی دست یابید.</p>', '2020-01-29 00:00:00', 4, 185, 'https://images.blinkist.io/images/books/5e2dd3016cee0700062aae06/1_1/470.jpg', '/en/books/the-geometry-of-wealth-en/purchase', 'هندسه-ثروت', '2023-01-27 02:26:44.63354', '2023-01-27 02:26:44.63354', NULL, 'The Geometry of Wealth');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1465, 'دیوانه کننده ساده', 'وسواسی که باعث موفقیت اپل می شود', 'وسواسی که باعث موفقیت اپل می شود', 15, 8, 'book', 't', '<p><em>Insanely</em> <em>Simple</em> در مورد استراتژی تجاری ساده نگه داشتن چیزها صحبت می کند. نویسنده فرآیندهای درونی اپل را بررسی می‌کند تا به ما نشان دهد چگونه می‌توانیم سادگی را در کار خود اعمال کنیم و چرا پیچیدگی می‌تواند مانع توسعه یک شرکت شود. خواننده با نحوه اجرای استیو جابز این ساختار در اپل و حفظ آن حتی در مواجهه با منتقدان آشنا خواهد شد.</p>', '2014-06-24 00:00:00', 4, 116, 'https://images.blinkist.io/images/books/53aad60a37303200072a0000/1_1/470.jpg', '/en/books/insanely-simple-en/purchase', 'دیوانه-کننده-ساده', '2023-01-27 02:26:52.024565', '2023-01-27 02:26:52.024565', NULL, 'Insanely Simple');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1467, 'برکشایر فراتر از بافت', 'ارزش پایدار ارزش ها', 'ارزش پایدار ارزش ها', 17, 7, 'book', 't', '<p><em>Berkshire Beyond Buffett</em> (2014) ارزش‌های اصلی را نشان می‌دهد که فرهنگ شرکتی برکشایر هاتاوی را که توسط بنیانگذار آن، وارن بافت ایجاد شده است، تعریف می‌کند. این کتاب در ادامه ثابت می‌کند که دیدگاه منحصربه‌فرد شرکت سرمایه‌گذاری از سرمایه‌گذاری و عملیات، موفقیت آن را حتی پس از درگذشت بافت تضمین می‌کند.</p>', '2015-06-18 00:00:00', 4, 58, 'https://images.blinkist.io/images/books/5580661f62323200074a0000/1_1/470.jpg', '/en/books/berkshire-beyond-buffett-en/purchase', 'برکشایر-فراتر-از-بافت', '2023-01-27 02:27:03.469184', '2023-01-27 02:27:03.469184', NULL, 'Berkshire Beyond Buffett');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1468, '21 قانون انکارناپذیر رهبری', 'آنها را دنبال کنید تا مردم شما را دنبال کنند', 'آنها را دنبال کنید تا مردم شما را دنبال کنند', 15, 7, 'book', 't', '<p><em>21 قانون انکار ناپذیر رهبری </em>(1998) توضیح می دهد که برای تبدیل شدن به یک رهبر بزرگ چه چیزی لازم است. این پلک‌ها بسیاری از ویژگی‌ها، مهارت‌ها و ویژگی‌هایی را برجسته می‌کنند که به رهبران سراسر جهان قدرت جذب پیروان وفادار و هدایت آنها به سمت موفقیت را داده است. دریابید که ری کروک، وینستون چرچیل و مادر ترزا چه مشترکاتی دارند – و چه کاری می توانید انجام دهید تا خودتان رهبر بهتری شوید.</p>', '2016-11-29 00:00:00', 4, 236, 'https://images.blinkist.io/images/books/583af051d4507000044fa59e/1_1/470.jpg', '/en/books/the-21-irrefutable-laws-of-leadership-en/purchase', '21-قانون-انکارناپذیر-رهبری', '2023-01-27 02:27:08.588053', '2023-01-27 02:27:08.588053', NULL, 'The 21 Irrefutable Laws of Leadership');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1469, 'سوپر جاذبه', 'روش هایی برای تجلی زندگی فراتر از وحشیانه ترین رویاهای شما', 'روش هایی برای تجلی زندگی فراتر از وحشیانه ترین رویاهای شما', 34, 11, 'book', 't', '<p><em>Super Attractor</em> (2019) یک راهنمای عملی برای تبدیل شدن به موجودی همسو با معنویت است، کسی که می‌تواند از نیروی متعالی که همه ما را احاطه کرده است بهره ببرد. چه یک روح پیر هستید یا به تازگی سفر خود را شروع کرده اید، پیروی از درس های نویسنده گابریل برنشتاین به شما این امکان را می دهد تا هدف درونی را پیدا کنید، بر ترس ها غلبه کنید و زندگی را شروع کنید که شایسته آن هستید.<em></em></p>', '2019-11-11 00:00:00', 5, 405, 'https://images.blinkist.io/images/books/5dc577eb6cee070007e48085/1_1/470.jpg', '/en/books/super-attractor-en/purchase', 'سوپر-جاذبه', '2023-01-27 02:27:16.542112', '2023-01-27 02:27:16.542112', NULL, 'Super Attractor');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1470, 'چراغ سبز', 'سفری به زندگی و ذهن بازیگر برنده جایزه متیو مک کانهی', 'سفری به زندگی و ذهن بازیگر برنده جایزه متیو مک کانهی', 40, 12, 'book', 't', '<p><em>Greenlights </em>(2020) یک تور راهنما به زندگی و ذهن بازیگر برنده جایزه متیو مک کانهی است. این پلک‌ها داستان او را همانطور که فقط او می‌توانست بیان کند، مملو از «منطق غیرقانونی» است که به یک فلسفه شخصی بدیع و اصیل برای چگونگی زندگی در نهایت آن کمک کرده است.</p>', '2021-01-14 00:00:00', 4, 184, 'https://images.blinkist.io/images/books/5ff82ebb6cee070007f83639/1_1/470.jpg', '/en/books/greenlights-en/purchase', 'چراغ-سبز', '2023-01-27 02:27:23.44294', '2023-01-27 02:27:23.44294', NULL, 'Greenlights');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1471, 'سکس برای یک', 'لذت خودخواهی', 'لذت خودخواهی', 24, 7, 'book', 't', '<p><em>سکس برای یک </em> (1987) بخشی از خاطرات، کتاب راهنمای بخشی از بتی دادسون، یک فمینیست پیشگام طرفدار جنسیت و مدافع خودارضایی است. دادسون سفر شهوانی خود را بازگو می کند و رویکردی گام به گام برای پذیرش عشق به خود ارائه می دهد.</p>', '2021-02-16 00:00:00', 4, 129, 'https://images.blinkist.io/images/books/602654766cee07000752cf7d/1_1/470.jpg', '/en/books/sex-for-one-en/purchase', 'سکس-برای-یک', '2023-01-27 02:27:30.81291', '2023-01-27 02:27:30.81291', NULL, 'Sex for One');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1472, 'مادران یعنی کسب و کار', 'راهنمای ایجاد یک شرکت موفق و زندگی شاد به عنوان یک مادر کارآفرین', 'راهنمای ایجاد یک شرکت موفق و زندگی شاد به عنوان یک مادر کارآفرین', 14, 6, 'book', 't', '<p><em>Moms Mean Business</em>راهنمای مدیریت زمان برای مادران کارآفرین است. این پلک‌ها به شما کمک می‌کنند اولویت‌های واقعی‌تان را کشف کنید، و تکنیک‌های برنامه‌ریزی را در اختیار شما قرار می‌دهند که به شما امکان می‌دهد زمان بیشتری را به جاه‌طلبی‌ها و خودتان اختصاص دهید.</p>', '2015-12-02 00:00:00', 5, 19, 'https://images.blinkist.io/images/books/565c7f9b990675000700005b/1_1/470.jpg', '/en/books/moms-mean-business-en/purchase', 'مادران-یعنی-کسب-و-کار', '2023-01-27 02:27:38.036014', '2023-01-27 02:27:38.036014', NULL, 'Moms Mean Business');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1473, 'چیزهایی که هیچ کس دیگری نمی تواند به ما بیاموزد', 'تبدیل ضررها به درس', 'تبدیل ضررها به درس', 14, 5, 'book', 't', '<p><em>چیزهایی که هیچ کس دیگری نمی تواند به ما بیاموزد</em> (2019) یک کتاب خودیاری بخشی از خاطرات و قسمتی غیر متعارف است. مملو از داستان‌های شخصی آشکار و تفکرات فلسفی، به شما انگیزه می‌دهد که باورهای خود را در مورد شکست، موفقیت و آنچه واقعاً زندگی را معنادار می‌کند، زیر سوال ببرید.</p>', '2022-10-04 00:00:00', 5, 554, 'https://images.blinkist.io/images/books/633591476cee070008031e6a/1_1/470.jpg', '/en/books/things-no-one-else-can-teach-us-en/purchase', 'چیزهایی-که-هیچ-کس-دیگری-نمی-تواند-به-ما-بیاموزد', '2023-01-27 02:27:45.309242', '2023-01-27 02:27:45.309242', NULL, 'Things No One Else Can Teach Us');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1474, '7 عادت خانواده های بسیار موثر', 'ایجاد روابط قدرتمند و مثبت در خانواده', 'ایجاد روابط قدرتمند و مثبت در خانواده', 21, 7, 'book', 't', '<p><em>7 عادت خانواده‌های بسیار مؤثر </em> (1997) توسط استفن آر. کاوی نوشته شده است، همانطور که او می‌گوید: «چنین شور و اشتیاق . . . زیرا خانواده چیزی است که من بیشتر به آن اهمیت می دهم.» این یک کتاب بسیار شخصی است که در مورد نحوه به کارگیری هر یک از عادات نویسنده، همسر و نه فرزندش در زندگی خانوادگی خود صحبت می کند. همچنین می‌تواند راهنمای شما برای حل مشکلاتی باشد که در خانواده‌تان با آن مواجه هستید، در حالی که تلاش می‌کنید، فردی و با هم برای مؤثرتر شدن.</p>', '2022-11-02 00:00:00', 5, 304, 'https://images.blinkist.io/images/books/6360f33b958fe9000879ec39/1_1/470.jpg', '/en/books/the-7-habits-of-highly-effective-families-en/purchase', '7-عادت-خانواده-های-بسیار-موثر', '2023-01-27 02:27:50.432912', '2023-01-27 02:27:50.432912', NULL, 'The 7 Habits of Highly Effective Families');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1484, 'پشت و رو', 'یک خاطره', 'یک خاطره', 21, 8, 'book', 't', '<p><em>Inside Out </em>(2019) خاطرات دمی مور بازیگر هالیوودی است. در اینجا، او به درون خود می چرخد ​​و از حافظه گزارش می دهد - از دوران کودکی پریشان و شهرت فزاینده اش به عنوان عضوی از "برات پک" در دهه 1980، تا ازدواجش با بروس ویلیس و اشتون کوچر. </p>', '2019-11-14 00:00:00', 4, 47, 'https://images.blinkist.io/images/books/5dcac9476cee07000744cdf9/1_1/470.jpg', '/en/books/inside-out-en/purchase', 'پشت-و-رو', '2023-01-27 02:28:56.587899', '2023-01-27 02:28:56.587899', NULL, 'Inside Out');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1476, 'سر قوی', 'طرح ضد گلوله برای تقویت قدرت مغز، افزایش تمرکز و به حداکثر رساندن عملکرد - فقط در دو هفته', 'طرح ضد گلوله برای تقویت قدرت مغز، افزایش تمرکز و به حداکثر رساندن عملکرد - فقط در دو هفته', 18, 6, 'book', 't', '<p><strong>درباره چیست؟</strong></p>
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1477, 'آن را میخ کنید سپس آن را مقیاس کنید', 'راهنمای کارآفرین برای ایجاد و مدیریت نوآوری پیشرفت', 'راهنمای کارآفرین برای ایجاد و مدیریت نوآوری پیشرفت', 16, 6, 'book', 't', '<p><em>Nail It and Scale It</em> (2011) راهنمای شما برای تکمیل طرح کسب و کار و گسترش شرکت شما است. این چشمک‌ها روند ایجاد محصولات نوآورانه را که مشکلات را حل می‌کنند، هدف‌گذاری و برقراری ارتباط با بازارهای مناسب و اصلاح استراتژی‌تان قبل از توسعه کسب‌وکارتان نشان می‌دهد.</p>', '2017-03-28 00:00:00', 4, 52, 'https://images.blinkist.io/images/books/58d8fd4154572a0004c5177f/1_1/470.jpg', '/en/books/nail-it-then-scale-it-en/purchase', 'آن-را-میخ-کنید-سپس-آن-را-مقیاس-کنید', '2023-01-27 02:28:10.096216', '2023-01-27 02:28:10.096216', NULL, 'Nail It then Scale It');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1478, 'اجازه دهید مردم من به گشت و گذار بروند', 'آموزش یک تاجر بی میل', 'آموزش یک تاجر بی میل', 17, 7, 'book', 't', '<p><em>اجازه دهید مردم من به گشت و گذار بروند</em> (2005) نگاهی الهام بخش به شرکت محبوب تجهیزات فضای باز پاتاگونیا است، سازمانی که به دنیا نشان داده است که بیش از یک راه برای راه اندازی یک کسب و کار موفق وجود دارد. در این پلک‌ها، نه تنها با تاریخچه شرکت و فلسفه منحصر به فرد آن آشنا می‌شوید، بلکه متوجه می‌شوید که چرا پاتاگونیا برخی از شادترین کارمندان را در اطراف دارد و چرا مردم از خرید محصولات آن احساس خوبی دارند.</p >', '2017-02-17 00:00:00', 4, 34, 'https://images.blinkist.io/images/books/58a2f8ecb2613e0004fe67f1/1_1/470.jpg', '/en/books/let-my-people-go-surfing-en/purchase', 'اجازه-دهید-مردم-من-به-گشت-و-گذار-بروند', '2023-01-27 02:28:17.697922', '2023-01-27 02:28:17.697922', NULL, 'Let My People Go Surfing');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1479, 'من حاوی تعداد زیادی هستم', 'میکروب های درون ما و نمایی بزرگتر از زندگی', 'میکروب های درون ما و نمایی بزرگتر از زندگی', 14, 6, 'book', 't', '<p><em>I Contain Multitudes</em> (2016) به دنیای میکروسکوپی میکروب ها نگاه می کند و بینش شگفت انگیزی را در مورد روش های بی شماری که زندگی ما تحت تأثیر آنها قرار می دهد ارائه می دهد. خواهید فهمید که چگونه میکروب های باستانی کمک کردند تا جهان برای بشر قابل زندگی باشد و چگونه از طریق مشارکت های چشمگیر و ضروری به همه موجودات زنده زمین کمک می کنند.</p>', '2017-03-01 00:00:00', 4, 55, 'https://images.blinkist.io/images/books/58b40ad28566cb0004c1f3ec/1_1/470.jpg', '/en/books/i-contain-multitudes-en/purchase', 'من-حاوی-تعداد-زیادی-هستم', '2023-01-27 02:28:24.578854', '2023-01-27 02:28:24.578854', NULL, 'I Contain Multitudes');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1480, 'ما همه عجیب و غریب هستیم', 'ظهور قبایل و پایان عادی', 'ظهور قبایل و پایان عادی', 14, 4, 'book', 't', '<p><em>ما همه عجیب هستیم </em>(2011) ذهنیت یکسانی را هدف قرار می دهد که در بسیاری از فرهنگ ما وجود دارد. برای مدت طولانی، بازاریابان، تولیدکنندگان و رسانه‌ها به گونه‌ای به دنیا نزدیک شده‌اند که گویی همه مردم یکسان هستند. ست گودین با این مانیفست ادراکی، اسطوره بازار انبوه را آشکار می کند و استدلال می کند که بشریت بسیار متنوع تر، عجیب و غریب تر و عجیب تر از آن چیزی است که به نظر می رسد. </p>', '2019-12-10 00:00:00', 4, 169, 'https://images.blinkist.io/images/books/5dec224d6cee07000892110c/1_1/470.jpg', '/en/books/we-are-all-weird-en/purchase', 'ما-همه-عجیب-و-غریب-هستیم', '2023-01-27 02:28:29.537332', '2023-01-27 02:28:29.537332', NULL, 'We Are All Weird');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1481, 'غیر منطقی', 'بله گفتن به زندگی بدون محدودیت', 'بله گفتن به زندگی بدون محدودیت', 23, 6, 'book', 't', '<p><em>غیر منطقی </em> (2022) داستان این است که چگونه امانوئل آچو، بازیکن حرفه‌ای سابق فوتبال که به ستاره رسانه تبدیل شد، تصمیم گرفت مسیر غیرمنطقی را برای تحقق پتانسیل و رویاهای خود طی کند. او به جای پیروی از قوانین، انتظارات و محدودیت های جامعه، تصمیم گرفت همه آنها را بشکند – و با انجام این کار، تبدیل به چیزی شد که امروز هست. و حدس بزنید چه؟ شما می توانید همین کار را انجام دهید.</p>', '2022-05-30 00:00:00', 4, 218, 'https://images.blinkist.io/images/books/628e34dd6cee070008d48e6f/1_1/470.jpg', '/en/books/illogical-en/purchase', 'غیر-منطقی', '2023-01-27 02:28:37.275471', '2023-01-27 02:28:37.275471', NULL, 'Illogical');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1482, 'تسلط بر چرخه بازار', 'گرفتن شانس در سمت شما', 'گرفتن شانس در سمت شما', 19, 6, 'book', 't', '<p><em>تسلط بر چرخه بازار </em>(2018) به موضوعی می پردازد که اغلب اشتباه گرفته می شود، نادیده گرفته می شود یا هر دو: چرخه های مالی. این نه تنها توضیح می‌دهد که چرخه‌ها چگونه هستند، چگونه عمل می‌کنند و چه چیزی بر آن‌ها تأثیر می‌گذارند، بلکه بهترین نحوه قرار گرفتن در درون آنها برای مقابله با ریسک و محیط فعلی بازار را توضیح می‌دهد. در طول مسیر، چندین چرخه مالی اخیر را مورد بحث قرار می‌دهد و درس‌هایی را که می‌توان از هرکدام آموخت.</p>', '2018-12-03 00:00:00', 4, 111, 'https://images.blinkist.io/images/books/5c0386946cee070007b8ed7b/1_1/470.jpg', '/en/books/mastering-the-market-cycle-en/purchase', 'تسلط-بر-چرخه-بازار', '2023-01-27 02:28:42.586751', '2023-01-27 02:28:42.586751', NULL, 'Mastering the Market Cycle');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1487, 'آموزش صدا برای والدین', 'چه بگوییم، چگونه بگوییم و چه زمانی گوش دهیم', 'چه بگوییم، چگونه بگوییم و چه زمانی گوش دهیم', 19, 7, 'book', 't', '<p><em>درس های صوتی برای والدین </em>(2018) به والدین نه تنها <em>چه</em> به کودکان بگویند - بلکه <em>چگونه</em> را می آموزد. هنگامی که با کودکان ارتباط برقرار می کنید، لحن، صدا و انتخاب کلمات شما به اندازه پیامی که می خواهید منتقل کنید مهم است. وندی موگل، کارشناس والدین، نشان می‌دهد که چگونه می‌توانید از ارتباط با فرزندتان بیشترین بهره را ببرید، چه با یک کودک نوپا ناشنوا یا یک نوجوان سرپیچی سر و کار داشته باشید. </p>', '2022-10-26 00:00:00', 4, 13, 'https://images.blinkist.io/images/books/63526dc26cee070009382478/1_1/470.jpg', '/en/books/voice-lessons-for-parents-en/purchase', 'آموزش-صدا-برای-والدین', '2023-01-27 02:29:18.238195', '2023-01-27 02:29:18.238195', NULL, 'Voice Lessons for Parents');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1488, 'چگونه زندگی خود را از بین ببرید', 'هک های زندگی برای یادگیرندگان مادام العمر مدرن', 'هک های زندگی برای یادگیرندگان مادام العمر مدرن', 28, 10, 'book', 't', '<p><em>How to Skimm Your Life</em> (2019) یک دوره آموزشی مفید در زمینه های مختلف از جمله سفر، جستجوی شغل و امور جهانی ارائه می دهد تا بتوانید در مورد چیزهای مهم آگاهی بیشتری داشته باشید. در زندگی. اگر تا به حال احساس کرده‌اید که برای تصمیم‌گیری‌های آگاهانه‌تر و روزانه به کمک نیاز دارید، بیشتر از این نگاه نکنید.</p>', '2019-07-31 00:00:00', 4, 94, 'https://images.blinkist.io/images/books/5d3ce1526cee070008098153/1_1/470.jpg', '/en/books/how-to-skimm-your-life-en/purchase', 'چگونه-زندگی-خود-را-از-بین-ببرید', '2023-01-27 02:29:25.871687', '2023-01-27 02:29:25.871687', NULL, 'How to Skimm Your Life');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1489, 'پرسیدن', 'فرمول آنلاین متضاد برای کشف دقیقاً آنچه مشتریان شما می خواهند بخرند... انبوهی از طرفداران راوینگ ایجاد کنید و هر کسب و کاری را به سطح بعدی ببرید.', 'فرمول آنلاین متضاد برای کشف دقیقاً آنچه مشتریان شما می خواهند بخرند... انبوهی از طرفداران راوینگ ایجاد کنید و هر کسب و کاری را به سطح بعدی ببرید.', 17, 7, 'book', 't', '<p><em>Ask </em> (2015) بر اساس یک ایده ساده است - اینکه یادگیری آنچه مشتری شما می خواهد به سادگی پرسیدن است. ترفند پرسیدن به روش درست است. <em>Ask</em>پر از بینش‌های عملی فوری درباره رفتار مشتری، <em>Ask </em>همه ابزارهایی را در اختیار شما می‌گذارد که برای کشف خواسته‌های مشتریانتان و ارائه آن به آنها نیاز دارید.</p>', '2015-09-25 00:00:00', 4, 38, 'https://images.blinkist.io/images/books/56000472615cd100090000ee/1_1/470.jpg', '/en/books/ask-en/purchase', 'پرسیدن', '2023-01-27 02:29:33.18407', '2023-01-27 02:29:33.18407', NULL, 'Ask ');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1490, 'اسرار قدرت مذاکره', 'رازهای درونی از یک مذاکره کننده استاد', 'رازهای درونی از یک مذاکره کننده استاد', 31, 12, 'book', 't', '<p><em>Secrets of Power Negotiating</em> (1987) ترفندهای تجارت مذاکره کننده اصلی را آشکار می کند. بر اساس اصول آزمایش شده با زمان که هدف آن یافتن راه حل های برد-برد برای هر دو طرف در هر مذاکره ای است، تاکتیک ها و استراتژی هایی را برای مذاکره مؤثر در معاملات در طیف گسترده ای از صنایع و موقعیت ها آموزش می دهد. چه در حال خرید یک محصول، فروش خدمات یا صرفاً تلاش برای رسیدن به توافق با شریک خود باشید، می توانید از اسرار مذاکره کننده قدرت راجر داوسون برای مذاکره با اطمینان و موفقیت استفاده کنید. </p>', '2019-11-22 00:00:00', 4, 211, 'https://images.blinkist.io/images/books/5dd40e6c6cee070007fe371f/1_1/470.jpg', '/en/books/secrets-of-power-negotiating-en/purchase', 'اسرار-قدرت-مذاکره', '2023-01-27 02:29:40.57474', '2023-01-27 02:29:40.57474', NULL, 'Secrets of Power Negotiating ');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1491, 'شفا از درون', 'کتاب راهنمای سلامتی شهودی', 'کتاب راهنمای سلامتی شهودی', 16, 6, 'book', 't', '<p><em>شفا از درون </em>(2022) کتاب راهنمای خوددرمانی است. در حالی که طب سنتی تمایل دارد بر علائم تمرکز کند، بیچر استدلال می کند که ما باید به <em>علت</em> یک بیماری توجه کنیم. استراتژی های درمانی او بر اساس تجربه شخصی و همچنین حرفه حرفه ای او به عنوان یک مشاور و شهود پزشکی است.</p>', '2022-05-05 00:00:00', 4, 242, 'https://images.blinkist.io/images/books/62665f006cee0700085a414a/1_1/470.jpg', '/en/books/heal-from-within-en/purchase', 'شفا-از-درون', '2023-01-27 02:29:48.041854', '2023-01-27 02:29:48.041854', NULL, 'Heal From Within');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1492, 'UX برای استارت‌آپ‌های ناب', 'تحقیق و طراحی سریعتر و هوشمندانه تجربه کاربر', 'تحقیق و طراحی سریعتر و هوشمندانه تجربه کاربر', 24, 8, 'book', 't', '<p><em>UX برای استارت‌آپ‌های ناب </em>(2013) رویکردی نوآورانه و مقرون‌به‌صرفه برای تحقیق و طراحی محصولات و خدمات ارائه می‌دهد. با توجه به استارت‌آپ‌ها و شرکت‌هایی که می‌خواهند مانند آن‌ها عمل کنند، نشان می‌دهد که می‌توانید تجربه کاربری عالی را برای مشتریان خود فراهم کنید و در عین حال هزینه‌های زمان و پول خود را تا حد امکان ناچیز نگه دارید.</p>', '2020-11-25 00:00:00', 5, 117, 'https://images.blinkist.io/images/books/5fb796636cee070006e48e7c/1_1/470.jpg', '/en/books/ux-for-lean-startups-en/purchase', 'UX-برای-استارت‌آپ‌های-ناب', '2023-01-27 02:29:55.602809', '2023-01-27 02:29:55.602809', NULL, 'UX for Lean Startups');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1493, 'برنده شدن', 'چگونه می توان با موفقیت یک شرکت را اداره کرد، افراد را مدیریت کرد و شغلی ایجاد کرد', 'چگونه می توان با موفقیت یک شرکت را اداره کرد، افراد را مدیریت کرد و شغلی ایجاد کرد', 24, 12, 'book', 't', '<p><em>برنده شدن</em> (2005) مجموعه‌ای از توصیه‌های بیهوده و تفکر اصیل در مورد اداره موفق شرکت، مدیریت افراد و ایجاد شغل است. این به سخت ترین سوالاتی که افراد در زندگی حرفه ای و خارج از آن با آن مواجه هستند پاسخ می دهد.</p>', '2013-12-24 09:24:39', 5, 58, 'https://images.blinkist.io/images/books/52b87e133737660012000000/1_1/470.jpg', '/en/books/winning-en/purchase', 'برنده-شدن', '2023-01-27 02:30:03.440569', '2023-01-27 02:30:03.440569', NULL, 'Winning');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1495, 'تحت فشار', 'مقابله با اپیدمی استرس و اضطراب در دختران', 'مقابله با اپیدمی استرس و اضطراب در دختران', 17, 6, 'book', 't', '<p><em>تحت فشار</em> (2019) چالش‌های خاصی را که دختران مدرسه‌ای در طول تحصیل، در خانه و به طور کلی در جامعه با آن‌ها مواجه هستند، بررسی می‌کند. لیزا دامور با تکیه بر تجربیات فراوان خود به عنوان یک روانشناس بالینی توضیح می دهد که چگونه والدین، معلمان و مربیان می توانند به دختران کمک کنند تا بر استرس و اضطرابی که به طور نامتناسبی بر زنان جوان تأثیر می گذارد غلبه کنند.</p>', '2019-04-05 00:00:00', 4, 41, 'https://images.blinkist.io/images/books/5ca337916cee070007a59384/1_1/470.jpg', '/en/books/under-pressure-en/purchase', 'تحت-فشار', '2023-01-27 02:30:15.364034', '2023-01-27 02:30:15.364034', NULL, 'Under Pressure');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1496, 'سواد کمی', 'بهره وری در عصر اطلاعات و اضافه بار ایمیل', 'بهره وری در عصر اطلاعات و اضافه بار ایمیل', 20, 8, 'book', 't', '<p><em>سواد بیتی</em>(2007) راهنما برای افرادی است که می‌خواهند در دنیایی که اطلاعات غیرضروری آن را فراگرفته است، بهتر از زمان خود استفاده کنند. با استفاده از ترفندهای سازمانی و صرفه جویی در زمان کتاب، به خوبی در راه رسیدن به سواد کمی خواهید بود.</p>', '2015-08-27 00:00:00', 4, 21, 'https://images.blinkist.io/images/books/55db35542647b1000900008c/1_1/470.jpg', '/en/books/bit-literacy-en/purchase', 'سواد-کمی', '2023-01-27 02:40:12.436206', '2023-01-27 02:40:12.436206', NULL, 'Bit Literacy');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1497, 'علم بد', 'نگاهی از پشت صحنه به علم ساختگی که هر روز ما را گمراه می کند.', 'نگاهی از پشت صحنه به علم ساختگی که هر روز ما را گمراه می کند.', 22, 9, 'book', 't', '<p>ما اغلب بدون هیچ فکری، زبان علمی که در تبلیغات یا اخبار استفاده می شود را می بلعیم. اما اگر کمی آن را تحلیل کنیم، اغلب متوجه می‌شویم که صرفاً یک شبه علم است. <em>بد</em> <em>علم</em> به ما نشان می‌دهد که این علم ساختگی می‌تواند منجر به سوء تفاهم‌های جدی، بی‌عدالتی و حتی مرگ شود.</p>', '2014-05-27 14:50:48', 4, 35, 'https://images.blinkist.io/images/books/5385f4f461623800073a0100/1_1/470.jpg', '/en/books/bad-science-en/purchase', 'علم-بد', '2023-01-27 02:40:19.766085', '2023-01-27 02:40:19.766085', NULL, 'Bad Science');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1498, 'افسانه تعادل کار و زندگی', 'بازنگری در تعادل بهینه خود برای موفقیت', 'بازنگری در تعادل بهینه خود برای موفقیت', 12, 6, 'book', 't', '<p><em>افسانه تعادل بین کار و زندگی </em>(2021) راهنمای مدیریت استرس و ایجاد هماهنگی در بخش‌های کلیدی زندگی شما با استفاده از روش هفت تکه است. روش Seven-Slice به جای تقسیم ساعات بیداری خود بین کار و زندگی، زندگی را در هفت بخش کلیدی مجدداً متن می کند و نشان می دهد که چگونه گذراندن وقت در هر یک از آنها در هر روز می تواند به شما کمک کند بر فشار غلبه کنید و آرامش پیدا کنید.</p>', '2021-06-09 00:00:00', 5, 434, 'https://images.blinkist.io/images/books/60ba26b86cee07000896dbdf/1_1/470.jpg', '/en/books/the-work-life-balance-myth-en/purchase', 'افسانه-تعادل-کار-و-زندگی', '2023-01-27 02:40:26.82091', '2023-01-27 02:40:26.82091', NULL, 'The Work-Life Balance Myth');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1499, 'شانس دوم', 'برای پول شما، زندگی شما و دنیای ما', 'برای پول شما، زندگی شما و دنیای ما', 15, 7, 'book', 't', '<p><em>فرصت دوم</em> (2015) دلایل شکاف ثروت فزاینده در ایالات متحده را تشریح می‌کند و توصیه‌هایی برای بالا رفتن از نردبان اقتصادی ارائه می‌دهد. این توضیح می‌دهد که چگونه می‌توانید از دارایی‌ها و بدهی‌ها استفاده کنید تا در آینده از موفقیت مالی بیشتری برخوردار شوید، در حالی که از مشکلات روزانه بیرون می‌روید.</p>', '2015-07-02 00:00:00', 4, 176, 'https://images.blinkist.io/images/books/55925e156561380007710000/1_1/470.jpg', '/en/books/second-chance-en/purchase', 'شانس-دوم', '2023-01-27 02:40:32.287917', '2023-01-27 02:40:32.287917', NULL, 'Second Chance');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1500, 'اقتصاد خوب برای روزهای سخت', 'پاسخ های بهتر به بزرگترین مشکلات ما', 'پاسخ های بهتر به بزرگترین مشکلات ما', 30, 11, 'book', 't', '<p><em>Good Economics for Hard Times</em> (2019) به طور سرسختانه برخی از به ظاهر حل نشدنی ترین مشکلاتی را که امروزه با آن روبرو هستیم بررسی می کند. Abhijit V. Banerjee و Esther Duflo استدلال می کنند که اقتصاد می تواند دیدگاه های جدیدی در مورد چگونگی حل تغییرات آب و هوا بدون آسیب رساندن به فقرا ارائه دهد و همچنین با مشکلات اجتماعی ناشی از افزایش نابرابری، تجارت جهانی و ترس از مهاجرت مقابله کند. </p>', '2020-03-19 00:00:00', 4, 165, 'https://images.blinkist.io/images/books/5e70d4306cee070006c42c32/1_1/470.jpg', '/en/books/good-economics-for-hard-times-en/purchase', 'اقتصاد-خوب-برای-روزهای-سخت', '2023-01-27 02:40:40.540466', '2023-01-27 02:40:40.540466', NULL, 'Good Economics for Hard Times');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1501, 'تکان دادن', 'بهبود تصمیم گیری در مورد سلامت، ثروت و شادی', 'بهبود تصمیم گیری در مورد سلامت، ثروت و شادی', 14, 10, 'book', 't', '<p>پیام <em>Nudge</em> این است که به ما نشان می‌دهد چگونه می‌توانیم، تنها با یک یا دو تکان کوچک، برای تصمیم‌گیری بهتر تشویق شویم. کتاب با توضیح دلایل تصمیمات اشتباهی که در زندگی روزمره می گیریم شروع می شود.</p>', '2012-12-23 15:59:44', 4, 312, 'https://images.blinkist.io/images/books/52822f17333464000c1f0000/1_1/470.jpg', '/en/books/nudge-en/purchase', 'تکان-دادن', '2023-01-27 02:40:48.127621', '2023-01-27 02:40:48.127621', NULL, 'Nudge');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1502, 'پخش شادی', 'علم احتراق و حفظ تغییرات مثبت', 'علم احتراق و حفظ تغییرات مثبت', 12, 5, 'book', 't', '<p><em>خوشبختی رادیو و تلویزیون</em> (2015) تأثیر بسیار مثبتی را بر بهره وری، کار گروهی و رفاه نشان می دهد. این پلک‌ها توضیح می‌دهند که چگونه می‌توانید با افکار مثبت ارتباط برقرار کنید تا امواج شادی را در جامعه، محل کار و روابط خود ارسال کنید.</p>', '2015-12-29 00:00:00', 4, 25, 'https://images.blinkist.io/images/books/5681b2f5704a88000700003c/1_1/470.jpg', '/en/books/broadcasting-happiness-en/purchase', 'پخش-شادی', '2023-01-27 02:40:56.090879', '2023-01-27 02:40:56.090879', NULL, 'Broadcasting Happiness');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1503, 'Codependent نه بیشتر', 'چگونه کنترل دیگران را متوقف کنیم و شروع به مراقبت از خود کنیم', 'چگونه کنترل دیگران را متوقف کنیم و شروع به مراقبت از خود کنیم', 20, 6, 'book', 't', '<p><em>Codependent No More </em>(1986) یک کلاسیک مدرن است که روابط همبسته را روشن می کند. پر از بینش های مفید در مورد همبستگی است و برخی از ابزارهای اساسی را که افراد می توانند برای بازیابی از آنها استفاده کنند، تشریح می کند.</p>', '2022-10-24 00:00:00', 4, 291, 'https://images.blinkist.io/images/books/635149196cee07000860c5d2/1_1/470.jpg', '/en/books/codependent-no-more-en/purchase', 'Codependent-نه-بیشتر', '2023-01-27 02:41:03.856717', '2023-01-27 02:41:03.856717', NULL, 'Codependent No More');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1504, 'تزلزل', 'آیا بازی انسانی شروع به اجرای خود کرده است؟', 'آیا بازی انسانی شروع به اجرای خود کرده است؟', 27, 9, 'book', 't', '<p><em>Falter</em> (2019) یک استدلال متقابل نسبتاً هشیارکننده برای انبوه کتاب‌های خوش‌بینانه در مورد حال و آینده است که اخیراً در بازار ظاهر شده‌اند. به جای اینکه همه چیز خیلی خوب باشد و حتی بهتر شود، نویسنده بیل مک کیبن استدلال می کند که به دلیل تهدیداتی که تغییرات آب و هوایی، مهندسی ژنتیک و هوش مصنوعی برای بشریت ایجاد می کند، همه چیز در حال حاضر بسیار بد است و در مسیر بدتری قرار دارد. او سپس به ارائه چند پیشنهاد برای چگونگی مقابله با این تهدیدات قبل از اینکه خیلی دیر شود، ادامه می دهد. </p>', '2019-05-29 00:00:00', 4, 55, 'https://images.blinkist.io/images/books/5ced4f436cee0700075a7477/1_1/470.jpg', '/en/books/falter-en/purchase', 'تزلزل', '2023-01-27 02:41:11.338437', '2023-01-27 02:41:11.338437', NULL, 'Falter');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1505, 'آزادی مجازی', 'چگونه با کارکنان مجازی کار کنید تا زمان بیشتری بخرید، بازدهی بیشتری داشته باشید و کسب و کار رویایی خود را بسازید', 'چگونه با کارکنان مجازی کار کنید تا زمان بیشتری بخرید، بازدهی بیشتری داشته باشید و کسب و کار رویایی خود را بسازید', 13, 7, 'book', 'f', '<p><em>آزادی مجازی </em>راهنمای کاملی در مورد هنر برون سپاری مجازی است. همه چیزهایی را که باید در هنگام جمع آوری تیم مجازی خود در نظر بگیرید، به تفصیل پوشش می دهد، در حالی که توصیه های محکمی در مورد نحوه دور زدن مشکلات رایج ارائه می دهد.</p>', '2015-01-06 00:00:00', NULL, 5, 'https://images.blinkist.io/images/books/54a989016233320009260000/1_1/470.jpg', '/en/books/virtual-freedom-en/purchase', 'آزادی-مجازی', '2023-01-27 02:41:19.328163', '2023-01-27 02:41:19.328163', NULL, 'Virtual Freedom');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1506, 'رهبر در شما', 'چگونه دوستان به دست آوریم، بر مردم تأثیر بگذاریم و در دنیایی در حال تغییر موفق شویم', 'چگونه دوستان به دست آوریم، بر مردم تأثیر بگذاریم و در دنیایی در حال تغییر موفق شویم', 25, 13, 'book', 't', '<p><em>رهبر در شما </em>(1993) نشان می‌دهد که چگونه بهره‌گیری از اشتیاق و خلاقیت شما می‌تواند به شما کمک کند تا ارتباط مؤثرتری داشته باشید و کارآمدتر کار کنید<em>. </em>این راهنمای عملی با تکیه بر بینش‌های رهبران در طیف گسترده‌ای از زمینه‌ها، شامل استراتژی‌هایی برای تقویت نقاط قوت رهبری، افزایش اعتماد به نفس و دستیابی به اهداف شخصی و حرفه‌ای شما است.</p>', '2021-08-30 00:00:00', 5, 330, 'https://images.blinkist.io/images/books/6128ffa16cee070007b5926b/1_1/470.jpg', '/en/books/the-leader-in-you-en/purchase', 'رهبر-در-شما', '2023-01-27 02:41:25.038385', '2023-01-27 02:41:25.038385', NULL, 'The Leader In You');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1507, 'زمین مانند هالیوود', 'آنچه می توانید از صنعت فیلم های پرمخاطب بیاموزید', 'آنچه می توانید از صنعت فیلم های پرمخاطب بیاموزید', 20, 4, 'book', 't', '<p><em>پیچ مانند هالیوود </em>(2022)<em> </em>مواد مخفی پشت تکنیک های موفق مورد استفاده برای ارائه فیلم ها و برنامه های تلویزیونی در هالیوود را آشکار می کند. خوشبختانه، مهم نیست در چه صنعتی کار می کنید - اصول پشت زمین هالیوود را می توان به طور جهانی اعمال کرد. با استفاده از قدرت داستان سرایی و روانشناسی متقاعدسازی، می توانید به معنای واقعی کلمه هر چیزی را برای هر کسی مطرح کنید.</p>', '2022-04-11 00:00:00', 4, 163, 'https://images.blinkist.io/images/books/6253de346cee070008dbe68b/1_1/470.jpg', '/en/books/pitch-like-hollywood-en/purchase', 'زمین-مانند-هالیوود', '2023-01-27 02:41:33.278961', '2023-01-27 02:41:33.278961', NULL, 'Pitch Like Hollywood');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1508, 'طراحی برای نحوه یادگیری مردم', 'از اصول کلیدی یادگیری برای فعال کردن حفظ دانش استفاده کنید', 'از اصول کلیدی یادگیری برای فعال کردن حفظ دانش استفاده کنید', 22, 5, 'book', 't', '<p><em>طراحی برای چگونگی یادگیری افراد </em>(2015) یک راهنمای عملی برای معلمان، رهبران کارگاه‌ها و مدیرانی است که می‌خواهند درس‌هایی ایجاد کنند که درگیر و الهام‌بخش باشد. این علم نحوه یادگیری ما را پوشش می‌دهد و سپس اصول طراحی را که زیربنای درس‌های موفق هستند به اشتراک می‌گذارد - مهم نیست چه چیزی تدریس می‌شود.</p>', '2022-10-11 00:00:00', 5, 82, 'https://images.blinkist.io/images/books/6343cef96cee070009e09c44/1_1/470.jpg', '/en/books/design-for-how-people-learn-en/purchase', 'طراحی-برای-نحوه-یادگیری-مردم', '2023-01-27 02:41:40.57835', '2023-01-27 02:41:40.57835', NULL, 'Design for How People Learn');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1509, 'باز کردن قفل خلاقیت', 'چگونه با تغییر ذهنیت های خلاقانه، هر مشکلی را حل کنیم و بهترین تصمیم ها را بگیریم', 'چگونه با تغییر ذهنیت های خلاقانه، هر مشکلی را حل کنیم و بهترین تصمیم ها را بگیریم', 20, 6, 'book', 't', '<p><em>باز کردن قفل خلاقیت </em>(2019) راهنمای آزادسازی خلاقیت در محل کار است. با شروع با این فرض که همه افراد ذاتاً خلاق هستند، استدلال می‌کند که بهترین راه برای باز کردن خلاقیت کارکنان استخدام خلاقان ستاره‌دار یا تجدید ساختار کسب‌وکارتان نیست. در عوض، نکته کلیدی این است که ذهنیت های محل کار را که خلاقیت افرادی را که از قبل در میان شما هستند خفه می کنند، از بین ببرید. </p>', '2020-01-01 00:00:00', 4, 223, 'https://images.blinkist.io/images/books/5dfcbfb76cee07000788a274/1_1/470.jpg', '/en/books/unlocking-creativity-en/purchase', 'باز-کردن-قفل-خلاقیت', '2023-01-27 02:41:48.449956', '2023-01-27 02:41:48.449956', NULL, 'Unlocking Creativity');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1510, 'شرکت خانواده', 'راهنمای داده محور برای تصمیم گیری بهتر در سال های ابتدایی مدرسه', 'راهنمای داده محور برای تصمیم گیری بهتر در سال های ابتدایی مدرسه', 22, 7, 'book', 't', '<p><em>شرکت خانواده </em>(2021) آخرین تحقیقات در مورد رشد کودک پیش از نوجوانی را بررسی می کند. توضیح می‌دهد که چگونه والدین می‌توانند در مورد تصمیمات مهم والدین مانند مدرسه، زمان خواب، رژیم غذایی و برنامه فوق برنامه تصمیمات مبتنی بر داده اتخاذ کنند.</p>', '2021-10-19 00:00:00', 4, 46, 'https://images.blinkist.io/images/books/6168339f6cee0700087a5613/1_1/470.jpg', '/en/books/the-family-firm-en/purchase', 'شرکت-خانواده', '2023-01-27 02:41:53.955007', '2023-01-27 02:41:53.955007', NULL, 'The Family Firm');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1511, 'غول های کوچک', 'شرکت هایی که به جای بزرگ بودن، بزرگ بودن را انتخاب می کنند', 'شرکت هایی که به جای بزرگ بودن، بزرگ بودن را انتخاب می کنند', 12, 6, 'book', 'f', '<p>پدیده جدیدی در دنیای تجارت آمریکا در حال ظهور است: <em>غول های کوچک</em>. اینها شرکت های خصوصی هستند که از تعصب معمول شرکتی مبنی بر افزایش درآمد به هر قیمتی پیروی نمی کنند. درعوض، آنها به دلیل اشتیاق قلبی خود به محصول خود هدایت می شوند و بر عواملی مانند کیفیت و مراقبت از نیروی کار خود تمرکز می کنند. نویسنده 14 غول کوچک را بررسی کرده است تا توضیح دهد که چگونه این استراتژی باعث موفقیت آنها شده است.</p>', '2014-10-17 00:00:00', 4, 31, 'https://images.blinkist.io/images/books/543e78833065650008660000/1_1/470.jpg', '/en/books/small-giants-en/purchase', 'غول-های-کوچک', '2023-01-27 02:42:01.302168', '2023-01-27 02:42:01.302168', NULL, 'Small Giants');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1512, 'بتهوون', 'یک زندگی در نه تکه', 'یک زندگی در نه تکه', 38, 10, 'book', 't', '<p><em>بتهوون </em>(2020) با کاوش در 9 آهنگ خاص که بینش تازه ای را در مورد لحظات کلیدی زندگی او ارائه می دهد، نگاهی بی نظیر به آهنگساز افسانه ای دارد. نویسنده تصورات غلط رایج در مورد بتهوون را به عنوان نابغه منزوی، شکنجه‌شده و انسان‌دوست به چالش می‌کشد - در عوض هنرمندی را به تصویر می‌کشد که برای دوستی‌ها ارزش قائل است، مشتاق عشق است و از چانه‌زنی بر سر قراردادهای انتشاراتی بالاتر نیست.</p>', '2021-02-28 00:00:00', 5, 71, 'https://images.blinkist.io/images/books/602f9d836cee070007759b1a/1_1/470.jpg', '/en/books/beethoven-en/purchase', 'بتهوون', '2023-01-27 02:42:08.984582', '2023-01-27 02:42:08.984582', NULL, 'Beethoven');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1513, 'سکس آهسته', 'مسیری برای تحقق و جنسیت پایدار', 'مسیری برای تحقق و جنسیت پایدار', 21, 7, 'book', 't', '<p><em>سکس آهسته </em>(2011) یک مورد قوی برای کاهش زندگی عشقی ما به منظور داشتن رابطه جنسی رضایت بخش تر و روابط عمیق تر و شادتر ایجاد می کند. در جامعه پرمشغله و مصرف‌گرای ما، رابطه جنسی اغلب به عنوان یک راه حل سریع برای رضایت جسمانی استفاده می‌شود – اما این می‌تواند باعث شود احساس پوچی کنیم. رابطه جنسی آهسته به ما کمک می کند تا با یادگیری نحوه عشق ورزی به شیوه ای آگاهانه و آگاهانه که در نهایت به همان اندازه که محرک است، شفابخش باشد، پتانسیل تمایلات جنسی خود را آشکار کنیم.</p>', '2020-12-17 00:00:00', 4, 284, 'https://images.blinkist.io/images/books/5fd34f366cee07000639bf88/1_1/470.jpg', '/en/books/slow-sex-en/purchase', 'سکس-آهسته', '2023-01-27 02:42:17.041957', '2023-01-27 02:42:17.041957', NULL, 'Slow Sex');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1514, 'مرا محکم نگه دار', 'راهنمای شما برای موفقیت آمیزترین رویکرد برای ایجاد روابط عاشقانه', 'راهنمای شما برای موفقیت آمیزترین رویکرد برای ایجاد روابط عاشقانه', 15, 7, 'book', 't', '<p><em>مرا محکم نگه دار</em> (2008) بر یکی از بزرگترین چالش های زندگی تمرکز دارد: ایجاد و حفظ یک رابطه صمیمی. با تکیه بر فرم زوج درمانی بسیار موفق نویسنده EFT (<em>زوج درمانی متمرکز بر عاطفی</em>) - بر اساس این ایده که کیفیت روابط با لحظات عاطفی کلیدی، مثبت و منفی تعریف می شود - این پلک ها به شما نشان می دهند. چگونه یک پیوند عمیق تر و پایدارتر با شریک زندگی خود ایجاد کنید.</p>', '2017-05-03 00:00:00', 4, 183, 'https://images.blinkist.io/images/books/590351cdb238e10008b85698/1_1/470.jpg', '/en/books/hold-me-tight-en/purchase', 'مرا-محکم-نگه-دار', '2023-01-27 02:42:22.785434', '2023-01-27 02:42:22.785434', NULL, 'Hold Me Tight');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1515, 'معامله خام', 'چگونه «اقتصاد اوبر» و سرمایه داری فراری کارگران آمریکایی را به هم می زند', 'چگونه «اقتصاد اوبر» و سرمایه داری فراری کارگران آمریکایی را به هم می زند', 17, 7, 'book', 't', '<p><em>Raw Deal </em>(2015) حقیقت زشتی را که در پس اقتصاد اشتراک‌گذاری جدید و آسیبی که شرکت‌هایی مانند Uber یا Airbnb بر جوامع سراسر جهان وارد می‌کنند، آشکار می‌کند. یک بحران بزرگ در افق وجود دارد و نه تنها بر کارکنان استثمار شده این شرکت ها تأثیر خواهد گذاشت. همه ما در معرض خطر هستیم و باید گام های بعدی خود را عاقلانه انتخاب کنیم تا از فروپاشی اقتصادی جلوگیری کنیم.</p>', '2017-04-21 00:00:00', 3, 20, 'https://images.blinkist.io/images/books/58f4abd01507cf00046b9987/1_1/470.jpg', '/en/books/raw-deal-en/purchase', 'معامله-خام', '2023-01-27 02:42:30.906765', '2023-01-27 02:42:30.906765', NULL, 'Raw Deal');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1516, 'مثل یک میلیونر دست بردارید', 'هیچ حقه، شانس یا صندوق اعتماد مورد نیاز نیست', 'هیچ حقه، شانس یا صندوق اعتماد مورد نیاز نیست', 28, 9, 'book', 't', '<p><em>ترک مانند یک میلیونر </em>(2019) یک راهنمای جسورانه و بیهوده برای مدیریت پول و افزایش ثروت است. با تکیه بر رویکرد ریاضی اثبات شده کریستی شن در پس‌انداز، سرمایه‌گذاری و خرج کردن، این پلک زدن‌ها نه تنها شما را از شر بدهی رهایی نمی‌بخشند، بلکه شما را در مسیر استقلال مالی قرار می‌دهند. بهترین خبر؟ برای رسیدن به آن نیازی نیست که یک کارآفرین یا یک بارون املاک و مستغلات شوید. تنها چیزی که لازم است یک صفحه گسترده و برنامه ریزی دقیق است. </p>', '2019-08-19 00:00:00', 4, 253, 'https://images.blinkist.io/images/books/5d59665c6cee0700075bcef7/1_1/470.jpg', '/en/books/quit-like-a-millionaire-en/purchase', 'مثل-یک-میلیونر-دست-بردارید', '2023-01-27 02:42:38.793193', '2023-01-27 02:42:38.793193', NULL, 'Quit Like a Millionaire');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1517, 'بهتر بخورید، احساس بهتری داشته باشید', 'دستور العمل های من برای سلامتی و شفا، درون و بیرون', 'دستور العمل های من برای سلامتی و شفا، درون و بیرون', 20, 7, 'book', 't', '<p><em>بهتر بخورید، احساس بهتری داشته باشید </em>(2021) راهنمای ایجاد یک رژیم غذایی متعادل است. بر اساس سفر شخصی Giada De Laurentis برای تغییر وضعیت سلامتی او، نشان می دهد که چگونه می توانید رژیم غذایی خود را برای کنترل التهاب و بهبود رفاه خود تغییر دهید.</p>', '2021-05-19 00:00:00', 4, 36, 'https://images.blinkist.io/images/books/60a376046cee07000794b534/1_1/470.jpg', '/en/books/eat-better-feel-better-en/purchase', 'بهتر-بخورید،-احساس-بهتری-داشته-باشید', '2023-01-27 02:42:46.159801', '2023-01-27 02:42:46.159801', NULL, 'Eat Better, Feel Better');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1518, 'سال زندگی دانمارکی', 'کشف رازهای شادترین کشور جهان', 'کشف رازهای شادترین کشور جهان', 15, 6, 'book', 't', '<p><em>The Year of Living Danishly</em> (2015) همه چیز درباره دانمارک است و اینکه چرا این کشور مکانی عالی برای زندگی در نظر گرفته می شود. این پلک ها نگاهی درونی به فرهنگ و جامعه دانمارک دارند تا توضیح دهند که چرا این کشور کوچک اسکاندیناویایی همواره در صدر گزارش شادی جهانی سازمان ملل و همچنین شاخص رفاه و شادی کمیسیون اتحادیه اروپا قرار دارد.</p>', '2018-01-19 00:00:00', 4, 49, 'https://images.blinkist.io/images/books/5a5cab08b238e10007f154cd/1_1/470.jpg', '/en/books/the-year-of-living-danishly-en/purchase', 'سال-زندگی-دانمارکی', '2023-01-27 02:42:54.010017', '2023-01-27 02:42:54.010017', NULL, 'The Year of Living Danishly');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1519, 'روده خود را دنبال کنید', 'تاثیر عظیم میکروب های کوچک', 'تاثیر عظیم میکروب های کوچک', 14, 5, 'book', 't', '<p><em>Follow Your Gut</em> (2015) دنیای میکروب ها را زیر میکروسکوپ قرار می دهد و نشان می دهد که چیزهای کوچک - در این مورد، باکتری ها - چقدر بر زندگی ما تأثیر می گذارند. واقعیت این است که ما در حال خزیدن با باکتری‌ها، چه در داخل و چه در خارج هستیم، و اگر اینطور نبودیم، زندگی چندان عالی نبود. باکتری ها عملکردهای مهم بسیاری مانند شادی و سلامتی ما را انجام می دهند. وقت آن است که یاد بگیرید چگونه با آنها خوب رفتار کنید!</p>', '2016-12-30 00:00:00', 4, 73, 'https://images.blinkist.io/images/books/584e99b93a41200004701651/1_1/470.jpg', '/en/books/follow-your-gut-en/purchase', 'روده-خود-را-دنبال-کنید', '2023-01-27 02:43:02.080464', '2023-01-27 02:43:02.080464', NULL, 'Follow Your Gut');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1520, 'فکر کردم فقط من هستم (اما اینطور نیست)', 'ساختن سفر از «مردم چه فکر خواهند کرد؟» به "من کافی هستم"', 'ساختن سفر از «مردم چه فکر خواهند کرد؟» به "من کافی هستم"', 15, 7, 'book', 't', '<p><em>فکر می‌کردم فقط من بودم (اما اینطور نیست)</em> (2008) راهنمای احساس درونی و کاملاً انسانی شرم است. این پلک‌ها این احساس پیچیده را توضیح می‌دهند، درباره چگونگی پیدایش آن بحث می‌کنند و راه‌هایی را توصیف می‌کنند که در آن همدلی و ارتباط با یکدیگر می‌تواند به بهبودی انسان‌ها کمک کند.</p>', '2017-08-10 00:00:00', 4, 335, 'https://images.blinkist.io/images/books/59887690b238e100054c1d56/1_1/470.jpg', '/en/books/i-thought-it-was-just-me-but-it-isnt-en/purchase', 'فکر-کردم-فقط-من-هستم-(اما-اینطور-نیست)', '2023-01-27 02:43:07.160265', '2023-01-27 02:43:07.160265', NULL, 'I Thought It Was Just Me (but it isn’t)');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1521, 'کلوپ صبحانه برای 40 نفر', 'رویکردی بدیع برای حذف پول و اختراع مجدد زندگی', 'رویکردی بدیع برای حذف پول و اختراع مجدد زندگی', 16, 5, 'book', 't', '<p><em>باشگاه صبحانه برای 40-somethings</em> (2018) بر باورها، فرضیات و نگرش های اشتباه در مورد پول که بین شما و آزادی مالی ایستاده است، روشن می شود. این پلک‌ها با استفاده از گروه رنگارنگ شخصیت‌های داستانی، درس‌های بسیار ارزشمندی از زندگی مالی را با پیچش روایی ارائه می‌کنند.</p>', '2019-12-17 00:00:00', 4, 68, 'https://images.blinkist.io/images/books/5df38b026cee0700079265b9/1_1/470.jpg', '/en/books/the-breakfast-club-for-40-somethings-en/purchase', 'کلوپ-صبحانه-برای-40-نفر', '2023-01-27 02:43:14.513243', '2023-01-27 02:43:14.513243', NULL, 'The Breakfast Club for 40-Somethings');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1522, 'نظریه عمومی عشق', 'علم پشت عاشق شدن', 'علم پشت عاشق شدن', 19, 8, 'book', 't', '<p>در <em>نظریه عمومی عشق</em>، سه روانپزشک نگاهی علمی به پدیده عشق دارند. نویسندگان با این استدلال که تجربه عاطفی ما در بزرگسالی عمیقاً تحت تأثیر روابط دوران کودکی ما است، راه‌هایی را برای خنثی کردن این «برنامه‌ریزی» عاطفی و ایجاد روابط سالم‌تر با دوستان و شرکای عاشقانه پیشنهاد می‌کنند.</p>', '2014-09-25 00:15:00', 4, 120, 'https://images.blinkist.io/images/books/5421426a37303300081a0000/1_1/470.jpg', '/en/books/a-general-theory-of-love-en/purchase', 'نظریه-عمومی-عشق', '2023-01-27 02:43:22.298569', '2023-01-27 02:43:22.298569', NULL, 'A General Theory of Love');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1523, 'اکتیویسم لذت', 'سیاست احساس خوب', 'سیاست احساس خوب', 20, 6, 'book', 't', '<p><em>فعالیت لذت </em>(2019) مقدمه ای بر سیاست لذت ارائه می دهد. این کتاب راه‌هایی را بررسی می‌کند که از طریق آنها می‌توانیم از سرکوب و به حاشیه راندن رهایی پیدا کنیم - و در عوض احساسات آزادی را در آغوش بگیریم. این روش‌هایی را ارائه می‌کند که از طریق آنها می‌توانیم درک بهتری از آسیب‌های گذشته به دست آوریم و با ارتباط عمیق‌تر با بدن و جوامع خود به جلو برویم.</p>', '2020-11-12 00:00:00', 3, 132, 'https://images.blinkist.io/images/books/5fa57dcf6cee070006d9fad6/1_1/470.jpg', '/en/books/pleasure-activism-en/purchase', 'اکتیویسم-لذت', '2023-01-27 02:43:30.178196', '2023-01-27 02:43:30.178196', NULL, 'Pleasure Activism');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1562, 'موتور فرهنگ', 'چارچوبی برای نتایج رانندگی، الهام بخشیدن به کارمندان و متحول کردن محل کار شما', 'چارچوبی برای نتایج رانندگی، الهام بخشیدن به کارمندان و متحول کردن محل کار شما', 13, 5, 'book', 't', '<p><em>موتور فرهنگ</em>(2014) راهنمای ایجاد یک محل کار الهام بخش با ایجاد انقلاب در فرهنگ سازمان شما است. این پلک ها شما را در فرآیند طراحی، اجرا و مدیریت یک اساسنامه سازمانی برای هدایت و تغییر هر گروه راهنمایی می کند.</p>', '2015-08-06 00:00:00', 4, 33, 'https://images.blinkist.io/images/books/55c0f27e34396300078b0000/1_1/470.jpg', '/en/books/the-culture-engine-en/purchase', 'موتور-فرهنگ', '2023-01-27 02:48:07.893848', '2023-01-27 02:48:07.893848', NULL, 'The Culture Engine');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1524, 'پروژه بهره وری', 'راه های اثبات شده برای عالی تر شدن', 'راه های اثبات شده برای عالی تر شدن', 13, 6, 'book', 't', '<p><em>پروژه بهره وری</em> (2016) یک راهنمای عملی برای چگونگی داشتن یک زندگی سازنده و معنادار است. با استفاده از تکنیک‌های قابل درک و توصیه‌های قابل اعتماد، خواهید فهمید که چگونه هوشمندانه‌تر کار کنید و کاری را که واقعاً مهم است انجام دهید. از اتلاف وقت و به تعویق انداختن خودداری کنید و ابزارهای جدیدی را برای کنترل زندگی خود انتخاب کنید!</p>', '2017-09-08 00:00:00', 4, 192, 'https://images.blinkist.io/images/books/59aea92fb238e10005ef0077/1_1/470.jpg', '/en/books/the-productivity-project-en/purchase', 'پروژه-بهره-وری', '2023-01-27 02:43:35.336809', '2023-01-27 02:43:35.336809', NULL, 'The Productivity Project');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1525, 'زندگی من به طور کامل', 'کار، خانواده و آینده ما', 'کار، خانواده و آینده ما', 26, 8, 'book', 't', '<p><em>زندگی کامل من</em> (2021)<em> </em>خاطرات ایندرا نویی مدیرعامل سابق پپسی است. او در تلاش برای وقت گذاشتن برای خانواده‌اش، به موفقیت‌اش و رفتار شعبده‌بازی‌ای که نیاز داشت فکر می‌کند.</p>', '2022-05-15 00:00:00', 4, 107, 'https://images.blinkist.io/images/books/627e53fa6cee070008ab2996/1_1/470.jpg', '/en/books/my-life-in-full-en/purchase', 'زندگی-من-به-طور-کامل', '2023-01-27 02:43:42.769387', '2023-01-27 02:43:42.769387', NULL, 'My Life in Full');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1526, 'دوراهی های بنیانگذار', 'پیش بینی و اجتناب از دام هایی که می تواند یک استارت آپ را غرق کند', 'پیش بینی و اجتناب از دام هایی که می تواند یک استارت آپ را غرق کند', 18, 9, 'book', 't', '<p><em>معضلات بنیانگذار</em> (2013) دقیقاً نشان می دهد که برای تبدیل شدن به یک شرکت نوپا چه چیزی لازم است. این راهنمای گام به گام برگرفته از تحقیقات و مطالعات موردی نویسنده، به شما کمک می‌کند تا در آب‌های خشن مراحل اولیه شرکت خود حرکت کنید.</p>', '2015-05-05 00:00:00', 4, 54, 'https://images.blinkist.io/images/books/5547721c3666320007290000/1_1/470.jpg', '/en/books/the-founders-dilemmas-en/purchase', 'دوراهی-های-بنیانگذار', '2023-01-27 02:43:50.186022', '2023-01-27 02:43:50.186022', NULL, 'The Founder’s Dilemmas');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1527, 'چگونه یادداشت هوشمند برداریم', 'یک تکنیک ساده برای تقویت نوشتن، یادگیری و تفکر - برای دانشجویان، دانشگاهیان و نویسندگان کتاب غیرداستانی', 'یک تکنیک ساده برای تقویت نوشتن، یادگیری و تفکر - برای دانشجویان، دانشگاهیان و نویسندگان کتاب غیرداستانی', 18, 6, 'book', 't', '<p><em>چگونه یادداشت های هوشمند برداریم</em> (2017) دقیقاً همین است – توضیحی در مورد چگونگی و چرایی یادداشت برداری هوشمند. توضیح می دهد که چگونه این تکنیک ساده، کمتر شناخته شده و اغلب اشتباه درک شده می تواند به تفکر، نوشتن و یادگیری شما کمک کند. با کمک یادداشت های هوشمند، ممکن است دیگر هرگز با وحشت یک صفحه خالی روبرو نشوید.</p>', '2021-07-27 00:00:00', 4, 591, 'https://images.blinkist.io/images/books/60fe5b446cee0700070a51c1/1_1/470.jpg', '/en/books/how-to-take-smart-notes-en/purchase', 'چگونه-یادداشت-هوشمند-برداریم', '2023-01-27 02:43:57.405295', '2023-01-27 02:43:57.405295', NULL, 'How to Take Smart Notes');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1528, 'طراحی یادگیری مبتنی بر شواهد', 'ایجاد آموزش برای بهبود عملکرد', 'ایجاد آموزش برای بهبود عملکرد', 19, 5, 'book', 't', '<p><em>طراحی یادگیری مبتنی بر شواهد </em>(2020) وضعیت یادگیری و توسعه در محل کار امروز را بررسی می کند. در حالی که بسیاری از اسطوره های یادگیری هنوز در یادگیری در محل کار معاصر با آن مواجه می شوند، راه های موثری برای یادگیری حرفه ای ها وجود دارد تا آنها را شناسایی کرده و آنها را حذف کنند. پس از انجام این کار، تعدادی تکنیک فوق العاده وجود دارد که متخصصان یادگیری می توانند از آنها برای کمک به یادگیری کارکنان استفاده کنند.</p>', '2022-10-25 00:00:00', 4, 63, 'https://images.blinkist.io/images/books/63524d4b6cee07000860cb49/1_1/470.jpg', '/en/books/evidence-informed-learning-design-en/purchase', 'طراحی-یادگیری-مبتنی-بر-شواهد', '2023-01-27 02:44:04.803014', '2023-01-27 02:44:04.803014', NULL, 'Evidence-Informed Learning Design');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1529, 'جی-زی', 'ساخت امریکا', 'ساخت امریکا', 19, 7, 'book', 't', '<p><em>JAY-Z: Made in America </em>(2019) مشارکت های سیاسی و هنری عظیم یکی از تأثیرگذارترین هنرمندان هیپ هاپ زمان ما را بررسی می کند. JAY-Z تنها خواننده رپ است که میلیاردر شده است. زندگی حرفه ای او سه دهه و 17 آلبوم پلاتینیوم را در بر می گیرد. با این حال، او بسیار بیشتر از یک درآمد بزرگ است. این پلک زدن ها نشان می دهد که او همچنین یک هنرمند ماجراجو، تجربی و یک فعال اصولگرا است که از نفوذ قابل توجه خود برای مبارزه با نابرابری اجتماعی استفاده می کند. </p>', '2020-02-07 00:00:00', 4, 43, 'https://images.blinkist.io/images/books/5e3bf4e66cee07000682b9cf/1_1/470.jpg', '/en/books/jay-z-en/purchase', 'جی-زی', '2023-01-27 02:44:12.843509', '2023-01-27 02:44:12.843509', NULL, 'JAY-Z');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1530, 'خوشحال', 'چرا کم و بیش همه چیز کاملاً خوب است', 'چرا کم و بیش همه چیز کاملاً خوب است', 22, 8, 'book', 't', '<p><em>Happy</em> (2016) نگاهی به ذن ترین فیلسوفان جهان باستان - رواقیون - می اندازد و می پرسد متفکرانی مانند اپیکور، سنکا و مارکوس اورلیوس چه چیزی می توانند درباره شادی به ما بیاموزند. پاسخ به گفته درن براون؟ یک معامله بزرگ. این پلک‌ها که مملو از بینش‌هایی درباره دیدگاه‌های قوی و منطقی این حکیمان یونانی و رومی است، فصلی حیاتی در تاریخ فلسفه غرب را روشن می‌کند و در عین حال به ما نشان می‌دهد که چگونه می‌توانیم امروز زندگی بهتر و رضایت‌بخش‌تری داشته باشیم. </p>', '2019-09-10 00:00:00', 4, 166, 'https://images.blinkist.io/images/books/5d7265596cee0700082d109b/1_1/470.jpg', '/en/books/happy-en/purchase', 'خوشحال', '2023-01-27 02:44:20.011422', '2023-01-27 02:44:20.011422', NULL, 'Happy');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1531, 'هوشمندهای تازه کار', 'چرا یادگیری بر دانستن در بازی جدید کار؟', 'چرا یادگیری بر دانستن در بازی جدید کار؟', 15, 8, 'book', 'f', '<p>جهان سریعتر از همیشه در حال تغییر است. کارمندان تازه کار و بی تجربه زمانی که مایل به یادگیری و سازگاری هستند در محل کار مزیت دارند. <em>Rookie Smarts</em> نشان می‌دهد که چگونه، هنگامی که پروژه‌ها با نگاهی تازه برخورد می‌شوند، سازمان‌ها موفق می‌شوند. این همچنین شامل نکات مفیدی در مورد اینکه چگونه حتی کارگران باتجربه می‌توانند با ایجاد یک طرز فکر تازه‌کار تیزبین بمانند.</p>', '2015-01-23 00:00:00', 4, 13, 'https://images.blinkist.io/images/books/54bd2d323465370009780000/1_1/470.jpg', '/en/books/rookie-smarts-en/purchase', 'هوشمندهای-تازه-کار', '2023-01-27 02:44:25.75918', '2023-01-27 02:44:25.75918', NULL, 'Rookie Smarts');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1532, 'اختلال انفجار بزرگ', 'بقای کسب و کار در عصر نوآوری مداوم', 'بقای کسب و کار در عصر نوآوری مداوم', 20, 7, 'book', 't', '<p><em>اختلال بیگ بنگ</em> (2014) توضیح می‌دهد که چگونه نوآوری‌های مخرب بسیاری از کسب‌وکارهای امروزی را به خطر می‌اندازند، و چگونه می‌توان با وجود این اختلالات، کسب‌وکار خود را زنده نگه داشت. این چهار مرحله اختلال در بازار را توصیف می کند و 12 قانون را ارائه می دهد که به شما کمک می کند از آنها عبور کنید.</p>', '2018-06-14 00:00:00', 4, 28, 'https://images.blinkist.io/images/books/5b20248cb238e100070025b8/1_1/470.jpg', '/en/books/big-bang-disruption-en/purchase', 'اختلال-انفجار-بزرگ', '2023-01-27 02:44:33.846798', '2023-01-27 02:44:33.846798', NULL, 'Big Bang Disruption');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1533, 'مدیر یک دقیقه ای', 'بهره وری، سود و رفاه خود را افزایش دهید', 'بهره وری، سود و رفاه خود را افزایش دهید', 10, 4, 'book', 't', '<p>با فروش جهانی بیش از 13 میلیون، <em>مدیر یک دقیقه ای</em> کلاسیکی است که هنوز در حال تغییر محل کار است. توضیح می‌دهد که چگونه مدیران می‌توانند نتایج برجسته‌ای را از کارمندان خود دریافت کنند در حالی که کمترین زمان ممکن را صرف مدیریت فعالانه آنها می‌کنند. یک <em>یک دقیقه مدیریت</em> فقط به سه ابزار ساده نیاز دارد تا بهره وری را افزایش دهد - و شرکت خود را متحول کند.</p>', '2014-10-13 00:00:00', 4, 160, 'https://images.blinkist.io/images/books/543a3c683539360008000000/1_1/470.jpg', '/en/books/the-one-minute-manager-en/purchase', 'مدیر-یک-دقیقه-ای', '2023-01-27 02:44:44.642835', '2023-01-27 02:44:44.642835', NULL, 'The One Minute Manager');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1534, 'اوج', 'رازهایی از علم جدید تخصص', 'رازهایی از علم جدید تخصص', 14, 6, 'book', 't', '<p><em>پیک</em> (2016) راهنمای شما برای دستیابی به تخصص از طریق تمرین منظم است. برخلاف تصور عمومی که توانایی طبیعی نقش مهمی در تعیین عملکرد دارد، این پلک‌ها به شما نشان می‌دهند که تقریباً هر کسی می‌تواند مهارت‌های تخصصی را در صورت تمرین سخت و صحیح کسب کند.</p>', '2017-01-20 00:00:00', 4, 141, 'https://images.blinkist.io/images/books/587f919ff7a77800049a9cbe/1_1/470.jpg', '/en/books/peak-en-anders-ericsson-and-robert-pool/purchase', 'اوج', '2023-01-27 02:44:52.135578', '2023-01-27 02:44:52.135578', NULL, 'Peak');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1535, 'نگرش منعکس کننده رهبری است', 'تفاوت بین مدیریت و رهبری و بیشتر', 'تفاوت بین مدیریت و رهبری و بیشتر', 11, 5, 'book', 't', '<p><em>نگرش منعکس کننده رهبری</em> (2015) نشان می دهد که چرا دنیای مدرن کار مملو از رئیسان بد است. این پلک‌ها عناصر رهبری را که عملکرد عالی را هدایت می‌کنند، از دانستن تفاوت بین مدیریت و هدایت تا پرورش نگرش صحیح در تیم شما روشن می‌کند. خواهید آموخت که اگرچه رهبری استثنایی نادر است، اما چیزی است که می توانید یاد بگیرید.</p>', '2016-05-27 00:00:00', 4, 40, 'https://images.blinkist.io/images/books/5740bccd2edd1b00032e6bfb/1_1/470.jpg', '/en/books/attitude-reflects-leadership-en/purchase', 'نگرش-منعکس-کننده-رهبری-است', '2023-01-27 02:45:00.196819', '2023-01-27 02:45:00.196819', NULL, 'Attitude Reflects Leadership ');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1536, 'حالات خوب، زندگی خوب', 'چگونه عشق به خود کلید باز کردن عظمت شماست', 'چگونه عشق به خود کلید باز کردن عظمت شماست', 22, 7, 'book', 't', '<p><em>حالات خوب، زندگی خوب </em>(2020) قدرت تفکر مثبت را بررسی می کند. با تشریح تکنیک‌های ساده برای تغییر طرز فکرتان، نشان می‌دهد که چگونه هر یک از ما می‌توانیم شادی و آینده خود را کنترل کنیم.</p>', '2021-01-15 00:00:00', 4, 201, 'https://images.blinkist.io/images/books/5ff82f736cee070007f83650/1_1/470.jpg', '/en/books/good-vibes-good-life-en/purchase', 'حالات-خوب،-زندگی-خوب', '2023-01-27 02:45:07.667173', '2023-01-27 02:45:07.667173', NULL, 'Good Vibes, Good Life');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1537, 'آنچه در مدرسه بازرگانی هاروارد به شما یاد نمی دهند', 'یادداشت های یک مدیر هوشمند خیابانی', 'یادداشت های یک مدیر هوشمند خیابانی', 14, 6, 'book', 't', '<p><em>آنچه در مدرسه بازرگانی هاروارد به شما یاد نمی دهند</em> (1984) مقدمه ای است برای همه چیزهایی که اساتید شما در مدرسه بازرگانی به شما یاد نمی دهند و نمی توانند به شما یاد دهند. نکات و ترفندهایی را بیاموزید که فقط افرادی با تجربه واقعی در بازار کار در زرادخانه خود دارند، مانند نحوه ایجاد تأثیر خوب و نحوه استفاده از مفهوم ترس در هنگام فروش.</p>', '2017-09-28 00:00:00', 4, 124, 'https://images.blinkist.io/images/books/59c8fcbab238e10005c201d7/1_1/470.jpg', '/en/books/what-they-dont-teach-you-at-harvard-business-school-en/purchase', 'آنچه-در-مدرسه-بازرگانی-هاروارد-به-شما-یاد-نمی-دهند', '2023-01-27 02:45:15.652735', '2023-01-27 02:45:15.652735', NULL, 'What They Don’t Teach You at Harvard Business School');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1545, 'هنر آمار', 'یادگیری از داده ها', 'یادگیری از داده ها', 25, 8, 'book', 't', '<p><em>هنر آمار </em>(2019) مقدمه ای غیرفنی بر مفاهیم اساسی علم آمار است. در کنار تجزیه و تحلیل های انتزاعی ریاضی به نفع رویکردی انسان محورتر، توضیح می دهد که چگونه علم آمار به ما کمک می کند به سؤالات پاسخ دهیم و داستان های آموزنده تر را بیان کنیم. فراتر از اعداد، نقش رسانه ها و سوگیری روانی را در تحریف ادعاهای آماری نیز در نظر می گیرد. در این پلک ها ابزار و دانش لازم برای درک و ارزیابی این ادعاها را خواهید یافت.</p>', '2020-02-04 00:00:00', 4, 209, 'https://images.blinkist.io/images/books/5e3818766cee070006ee6937/1_1/470.jpg', '/en/books/the-art-of-statistics-en/purchase', 'هنر-آمار', '2023-01-27 02:46:13.97682', '2023-01-27 02:46:13.97682', NULL, 'The Art of Statistics');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1538, 'شام متفکر', 'ایجاد روابط مادام العمر با اتصال کارشناسان، اینفلوئنسرها و Linchpins', 'ایجاد روابط مادام العمر با اتصال کارشناسان، اینفلوئنسرها و Linchpins', 11, 5, 'book', 't', '<p>در <em>Mastermind Dinners</em> (2015)، نویسنده Jayson Gaignard با دعوت از تأثیرگذاران و مدیران سطح بالا به شام، روشی نوآورانه را برای ایجاد شبکه‌هایی با دوام معرفی می‌کند. به عنوان یک میزبان شام مغز متفکر، با جمع کردن افراد جالب در اطراف یک میز برای به اشتراک گذاشتن یک وعده غذایی و ارتباط معنادار با یکدیگر، دنیای کاملا جدیدی از امکانات شبکه را باز می کنید.</p>', '2015-06-16 00:00:00', 4, 22, 'https://images.blinkist.io/images/books/557d9fd36533380007360000/1_1/470.jpg', '/en/books/mastermind-dinners-en/purchase', 'شام-متفکر', '2023-01-27 02:45:23.499054', '2023-01-27 02:45:23.499054', NULL, 'Mastermind Dinners');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1539, 'کوچک بزرگ', 'تغییرات کوچکی که جرقه نفوذ بزرگی می‌زند', 'تغییرات کوچکی که جرقه نفوذ بزرگی می‌زند', 16, 8, 'book', 't', '<p><em>Small BIG</em> ۵۲ مثال ارائه می‌دهد که چگونه تغییرات جزئی در رفتار شما می‌تواند شما را در مذاکره با دیگران و متقاعد کردن آنها مطمئن‌تر و موفق‌تر کند. کسانی که این کتاب را می‌خوانند می‌توانند از مثال‌ها ارزش بگیرند و در سبک متقاعدسازی خود پیشرفت‌های چشمگیری ایجاد کنند.</p>', '2014-10-15 00:00:00', 4, 51, 'https://images.blinkist.io/images/books/543d4e0463633200081b0000/1_1/470.jpg', '/en/books/the-small-big-en/purchase', 'کوچک-بزرگ', '2023-01-27 02:45:30.746798', '2023-01-27 02:45:30.746798', NULL, 'The Small BIG');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1540, 'از دست دادن سیگنال', 'داستان ناگفته پشت ظهور خارق العاده و سقوط تماشایی بلک بری', 'داستان ناگفته پشت ظهور خارق العاده و سقوط تماشایی بلک بری', 18, 8, 'book', 't', '<p><em>از دست دادن سیگنال </em>(2015) داستان Research in Motion را روایت می کند، شرکتی که BlackBerry را ایجاد کرده است. با شروع دوران RIM به عنوان یک رقیب کوچک در ارتباطات بی سیم در اواسط دهه 1990، ما را به عنوان تأثیرگذارترین بازیگر در بازار دستگاه های ارتباطی بی سیم در اواسط دهه 2000 به پیروزی رساند و نشان داد که چرا RIM به همان سرعتی که رشد می کرد غرق شد. .</p>', '2016-03-14 00:00:00', NULL, 8, 'https://images.blinkist.io/images/books/56e6a62c9854a5000700002d/1_1/470.jpg', '/en/books/losing-the-signal-en/purchase', 'از-دست-دادن-سیگنال', '2023-01-27 02:45:37.682588', '2023-01-27 02:45:37.682588', NULL, 'Losing The Signal');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1541, 'Crypto Wars', 'مرگ های جعلی، میلیاردها گمشده، و اختلال در صنعت', 'مرگ های جعلی، میلیاردها گمشده، و اختلال در صنعت', 27, 6, 'book', 't', '<p><em>جنگ‌های رمزنگاری: مرگ‌های جعلی، میلیاردها گمشده، و اختلال در صنعت </em>(2021) سرپوش برخی از جسورانه‌ترین کلاهبرداری‌ها و رسوایی‌های بدنام کریپتوسپهر را برمی‌دارد. از کریپتوکوئین گمشده، دکتر روجا ایگناتوا، تا بچه غوغاگر فناوری که - حداقل به گفته طلبکارانش - مرگ خود را جعل کرده است، <em>جنگ های رمزنگاری</em> قانع کننده ترین داستان های این صنعت مخفیانه را به اشتراک می گذارد.</p >', '2022-04-08 00:00:00', 4, 185, 'https://images.blinkist.io/images/books/624af1be6cee070008b661a1/1_1/470.jpg', '/en/books/crypto-wars-en/purchase', 'Crypto-Wars', '2023-01-27 02:45:44.97177', '2023-01-27 02:45:44.97177', NULL, 'Crypto Wars');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1542, 'مدیر عامل همسایه', 'چهار رفتاری که افراد عادی را به رهبرانی در کلاس جهانی تبدیل می کند', 'چهار رفتاری که افراد عادی را به رهبرانی در کلاس جهانی تبدیل می کند', 17, 7, 'book', 't', '<p><em>مدیر عامل مجاور</em> (2017) نگاهی می‌اندازد به آنچه که یک مدیر عامل خوب را از یک مدیر عالی جدا می‌کند. با پشتیبانی از تحقیقات گسترده به سرپرستی نویسندگان، پیشنهاد می‌کند که افراد عادی می‌توانند رهبران شرکت‌های بزرگ و موفق شوند، و جزئیات مربوط به مراحل بالا رفتن از آن نردبان شرکتی را شرح می‌دهد.</p>', '2018-08-20 00:00:00', 4, 140, 'https://images.blinkist.io/images/books/5b79bd06b238e100077000da/1_1/470.jpg', '/en/books/the-ceo-next-door-en/purchase', 'مدیر-عامل-همسایه', '2023-01-27 02:45:52.236935', '2023-01-27 02:45:52.236935', NULL, 'The CEO Next Door');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1543, 'مصونیت', 'اهمیت سیستم ایمنی بدن ما', 'اهمیت سیستم ایمنی بدن ما', 14, 6, 'book', 't', '<p><em>ایمنی</em> (2015) راهنمایی برای آن مدافع بزرگ بدن انسان است که در غیر این صورت به عنوان سیستم ایمنی شناخته می شود. توضیح مفصلی در مورد اینکه چگونه پاسخ‌های ایمنی از ما در برابر انواع بیماری‌ها، حتی سرطان‌ها دفاع می‌کنند، و اینکه چگونه یک سیستم ایمنی ناکارآمد می‌تواند دردسر بزرگی ایجاد کند، ارائه می‌دهد.</p>', '2016-04-13 00:00:00', 4, 33, 'https://images.blinkist.io/images/books/57097a4d8b5d6e00030000b7/1_1/470.jpg', '/en/books/immunity-en/purchase', 'مصونیت', '2023-01-27 02:45:59.567461', '2023-01-27 02:45:59.567461', NULL, 'Immunity ');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1544, 'تصادف ناگهانی', 'یک دانشمند تجارت، یک شکار جهانی و مرموزترین سقوط بازار در تاریخ', 'یک دانشمند تجارت، یک شکار جهانی و مرموزترین سقوط بازار در تاریخ', 18, 6, 'book', 't', '<p><em>Flash Crash </em>(2020) داستان "Hound of Hounslow" را روایت می کند، ناویندر سینگ سارائو، مردی بریتانیایی که متهم به ایجاد سقوط ناگهانی و چشمگیر بازار سهام در سال 2010 است. این یک شرح مفصل است. و داستان سریع تقلب جهانی و رویاهای کیشوت.</p>', '2021-01-23 00:00:00', 5, 59, 'https://images.blinkist.io/images/books/600187c36cee0700069e4cef/1_1/470.jpg', '/en/books/flash-crash-en/purchase', 'تصادف-ناگهانی', '2023-01-27 02:46:07.066245', '2023-01-27 02:46:07.066245', NULL, 'Flash Crash');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1561, 'نامرئی', 'قدرت کار گمنام در عصر خودسازی بی امان', 'قدرت کار گمنام در عصر خودسازی بی امان', 13, 7, 'book', 'f', '<p>این پلک‌ها درباره افراد <em>نامرئی</em> جامعه ما هستند: کسانی که به‌دلیل انگیزه‌های درونی خود سخت کار می‌کنند تا چشم‌انداز پاداش. اگرچه ما نمی توانیم آنها را ببینیم، آنها ستون فقرات جامعه هستند. با این حال، نگرش‌های فرهنگی کنونی در حال کاهش نقش خود هستند و اگر می‌خواهیم دنیای خود را بهبود بخشیم، باید قدردانی خود را نسبت به <em>نامرئی‌ها</em> تجدید کنیم.</p>', '2014-09-30 00:15:00', NULL, 7, 'https://images.blinkist.io/images/books/542927266665620008460000/1_1/470.jpg', '/en/books/invisibles-en/purchase', 'نامرئی', '2023-01-27 02:48:00.445373', '2023-01-27 02:48:00.445373', NULL, 'Invisibles');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1546, 'بیوگرافی قبل از خواب: فلورانس نایتینگل', '1820-1910', '1820-1910', 33, 6, 'book', 't', '<p><strong>به روایت مارستون یورک</strong></p>
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1547, 'سکس باشکوه', 'درس هایی از عاشقان فوق العاده', 'درس هایی از عاشقان فوق العاده', 17, 6, 'book', 't', '<p><em>جنس با شکوه </em>(2020) راهنمایی برای داشتن رابطه جنسی برجسته، هر چند وقت یکبار است. به جای تمرکز بر تکنیک‌های جنسی خاص، از مصاحبه با عاشقان خارق‌العاده استفاده می‌کند تا به ویژگی‌ها و ویژگی‌هایی بپردازد که رابطه جنسی باشکوه را ممکن می‌سازد. </p>', '2021-07-31 00:00:00', 4, 489, 'https://images.blinkist.io/images/books/60fe66626cee0700070a51e6/1_1/470.jpg', '/en/books/magnificent-sex-en/purchase', 'سکس-باشکوه', '2023-01-27 02:46:27.608063', '2023-01-27 02:46:27.608063', NULL, 'Magnificent Sex');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1548, 'همه در', 'یک اتوبیوگرافی', 'یک اتوبیوگرافی', 35, 11, 'book', 't', '<p><em>All In </em>(2021) داستان زندگی بی‌نظیر بیلی جین کینگ را روایت می‌کند، زنی که دعوت به برابری در ورزش زنان را رهبری کرد که به زودی در سراسر جهان طنین انداز شد. فعالیت و امتناع کینگ از عقب نشینی منجر به تغییرات واقعی در مجلس قانونگذاری ایالات متحده شد، با نتایجی که بسیار فراتر از حوزه ورزش گسترش یافت. در تمام مدت، کینگ با مسائل شخصی دست و پنجه نرم می کرد که فقط بعداً در زندگی حل می شد.</p>', '2021-10-25 00:00:00', 5, 23, 'https://images.blinkist.io/images/books/617160c56cee0700087ac25c/1_1/470.jpg', '/en/books/all-in-en/purchase', 'همه-در', '2023-01-27 02:46:34.22899', '2023-01-27 02:46:34.22899', NULL, 'All In');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1549, 'سود', 'منطق پنهانی که انگیزه های ما را شکل می دهد', 'منطق پنهانی که انگیزه های ما را شکل می دهد', 11, 4, 'book', 't', '<p><em>پرداخت</em> (2016) همه چیز در مورد منطق انگیزه و چگونگی ایجاد آن برای شما است. این پلک‌ها عوامل مختلفی را توضیح می‌دهند که افراد را به سمت دستیابی سوق می‌دهند و نشان می‌دهند که چرا مهم‌ترین عامل همه چیز معناست.</p>', '2017-01-12 00:00:00', 4, 64, 'https://images.blinkist.io/images/books/58739c68dc846a0004a77f06/1_1/470.jpg', '/en/books/payoff-en/purchase', 'سود', '2023-01-27 02:46:41.15882', '2023-01-27 02:46:41.15882', NULL, 'Payoff');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1550, 'یک سوال زیباتر', 'قدرت تحقیق برای برانگیختن ایده های موفقیت آمیز', 'قدرت تحقیق برای برانگیختن ایده های موفقیت آمیز', 14, 6, 'book', 't', '<p><em>یک سوال زیباتر </em>بر اهمیت یافتن سوالات مناسب در جستجوی موفقیت تاکید می کند. با کمک تحقیقات پیشرفته و مثال‌هایی از دنیای تجارت، این کتاب سؤال «زیبا» را تعریف می‌کند و به شما نشان می‌دهد که چگونه خودتان شروع به پرسیدن چنین سؤالاتی کنید.</p>', '2014-12-09 00:00:00', 4, 68, 'https://images.blinkist.io/images/books/5485c7a76331620009410000/1_1/470.jpg', '/en/books/a-more-beautiful-question-en/purchase', 'یک-سوال-زیباتر', '2023-01-27 02:46:48.003048', '2023-01-27 02:46:48.003048', NULL, 'A More Beautiful Question');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1551, 'دارایی ملت ها', 'تاثیرگذارترین کتاب اقتصادی تمام دوران', 'تاثیرگذارترین کتاب اقتصادی تمام دوران', 11, 4, 'book', 't', '<p><em>ثروت ملل</em>یک اثر عمیقاً تأثیرگذار در مطالعه اقتصاد است و دقیقاً چگونگی ثروتمند شدن کشورها را بررسی می‌کند. آدام اسمیت مدافع این است که با اجازه دادن به افراد برای پیگیری آزادانه منافع شخصی خود در یک بازار آزاد، بدون مقررات دولتی، کشورها پیشرفت خواهند کرد.</p>', '2015-03-04 00:00:00', 4, 679, 'https://images.blinkist.io/images/books/54f57f4c623735000a330000/1_1/470.jpg', '/en/books/the-wealth-of-nations-en/purchase', 'دارایی-ملت-ها', '2023-01-27 02:46:55.20101', '2023-01-27 02:46:55.20101', NULL, 'The Wealth of Nations');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1552, 'یک قدم کوچک می تواند زندگی شما را تغییر دهد', 'راه کایزن', 'راه کایزن', 18, 8, 'book', 't', '<p><em>یک قدم کوچک می تواند زندگی شما را تغییر دهد </em>(2004) یک راهنمای عملی خودیاری است که از مفهوم کایزن الهام گرفته شده است - تغییر از طریق گام های کوچک. این روش تکنیک‌های ساده‌ای را پیشنهاد می‌کند که می‌تواند به هر کسی کمک کند زندگی خود را بهبود بخشد و تغییراتی پایدار ایجاد کند، هر بار یک قدم کوچک.</p>', '2022-10-17 00:00:00', 5, 596, 'https://images.blinkist.io/images/books/63492efd6cee070008ea04e8/1_1/470.jpg', '/en/books/one-small-step-can-change-your-life-en/purchase', 'یک-قدم-کوچک-می-تواند-زندگی-شما-را-تغییر-دهد', '2023-01-27 02:47:03.468979', '2023-01-27 02:47:03.468979', NULL, 'One Small Step Can Change Your Life');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1553, 'حسابداری ساده ساخته شده است', 'حسابداری در 100 صفحه یا کمتر توضیح داده شده است', 'حسابداری در 100 صفحه یا کمتر توضیح داده شده است', 14, 6, 'book', 't', '<p><em>حسابداری ساده شده</em> (2013) مقدمه ای کوتاه بر مبانی حسابداری ارائه می دهد و نحوه خواندن مهم ترین صورت های مالی و نتیجه گیری در مورد اعداد را نشان می دهد. همچنین سیستم دفتر کل دوبار ورود را مشخص می‌کند، که نشانه‌ای از بهترین شیوه‌های حسابداری است.</p>', '2015-05-26 00:00:00', 5, 95, 'https://images.blinkist.io/images/books/5563a6006461640007010000/1_1/470.jpg', '/en/books/accounting-made-simple-en/purchase', 'حسابداری-ساده-ساخته-شده-است', '2023-01-27 02:47:10.476809', '2023-01-27 02:47:10.476809', NULL, 'Accounting Made Simple');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1554, 'راهنمای کامل شغلی درونگرا', 'از پیدا کردن یک شغل، تا زنده ماندن، شکوفا شدن و حرکت به سمت بالا', 'از پیدا کردن یک شغل، تا زنده ماندن، شکوفا شدن و حرکت به سمت بالا', 24, 8, 'book', 't', '<p><em>راهنمای کامل شغلی Introvert''s Complete Career Guide </em>(2019) ابزاری برای افراد محتاط و کمتر قاطعانه است که می خواهند اعتماد به نفس به دست آورند و در حرفه خود پیشرفت کنند. توصیه‌های عملی و حمایتی آن به درون‌گراها کمک می‌کند تا از نقاط قوت خود بهره ببرند تا نه تنها خود را حفظ کنند، بلکه در محل کار نیز شکوفا شوند.</p>', '2019-12-03 00:00:00', 4, 111, 'https://images.blinkist.io/images/books/5de133806cee0700072947bc/1_1/470.jpg', '/en/books/the-introverts-complete-career-guide-en/purchase', 'راهنمای-کامل-شغلی-درونگرا', '2023-01-27 02:47:17.943825', '2023-01-27 02:47:17.943825', NULL, 'The Introvert’s Complete Career Guide');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1555, 'عادات با عملکرد بالا', 'چگونه افراد خارق العاده اینگونه می شوند', 'چگونه افراد خارق العاده اینگونه می شوند', 18, 7, 'book', 't', '<p><em>عادات با عملکرد بالا</em> (2017) شش عادتی را بررسی می کند که می تواند یک فرد معمولی را به یک عادت فوق العاده سازنده تبدیل کند. مربی عملکرد، برندون بورچارد، از داده‌ها و آمارهای یکی از بزرگ‌ترین مطالعاتی که بر روی پربازده‌ترین افراد جهان انجام شده است، استفاده می‌کند تا عادات آن‌ها را بررسی کند و بفهمد که چه چیزی باعث می‌شود که آن‌ها را تغییر دهند.</p>
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1556, 'در درون خود جستجو کنید', 'مسیر غیرمنتظره برای رسیدن به موفقیت، شادی (و صلح جهانی)', 'مسیر غیرمنتظره برای رسیدن به موفقیت، شادی (و صلح جهانی)', 19, 7, 'book', 't', '<p><em>جستجوی درون خود</em> (2012) به شما می آموزد که چگونه می توان از قدرت هوش هیجانی و ذهن آگاهی برای پیشرفت شخصی و حرفه ای استفاده کرد. آموزه های تان بر اساس سال ها تحقیق است و این فرصت را به شما می دهد تا شادی، خلاقیت و بهره وری خود را بهبود بخشید.</p>', '2018-01-26 00:00:00', 4, 139, 'https://images.blinkist.io/images/books/5a65b8adb238e10007b0ca10/1_1/470.jpg', '/en/books/search-inside-yourself-en/purchase', 'در-درون-خود-جستجو-کنید', '2023-01-27 02:47:31.023106', '2023-01-27 02:47:31.023106', NULL, 'Search Inside Yourself');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1557, 'آیا شارژ کامل دارید؟', '3 کلید برای انرژی بخشیدن به کار و زندگی شما', '3 کلید برای انرژی بخشیدن به کار و زندگی شما', 15, 7, 'book', 't', '<p><em>آیا شما کاملا شارژ شده اید </em>(2015) راهنمای شما برای حذف روزهای تعطیل، یک تعامل مثبت در هر زمان است. از معاشرت بیشتر گرفته تا نشستن کمتر، این پلک زدن ها نکات و ترفندهای ساده ای را برای تولید انرژی ذهنی و جسمی مورد نیاز خود نشان می دهد، همه اینها با یافتن معنایی بیشتر در زندگی شما.</p>', '2015-06-23 00:00:00', 4, 95, 'https://images.blinkist.io/images/books/55891da13466610007020000/1_1/470.jpg', '/en/books/are-you-fully-charged-en/purchase', 'آیا-شارژ-کامل-دارید؟', '2023-01-27 02:47:36.177484', '2023-01-27 02:47:36.177484', NULL, 'Are You Fully Charged?');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1558, 'قهرمان در یک ماموریت', 'راهی به سوی زندگی معنادار', 'راهی به سوی زندگی معنادار', 23, 6, 'book', 't', '<p><em>قهرمان در یک ماموریت </em>(2022) نقش داستان و معنا را در زندگی روزمره ما بررسی می کند. این نشان می‌دهد که چگونه می‌توانیم به شیوه‌ای از زندگی قهرمانانه‌تر روی آوریم، و زیربنای یک طرز فکر قهرمانانه را آشکار می‌کند. </p>', '2022-03-04 00:00:00', 4, 193, 'https://images.blinkist.io/images/books/62221ab06cee0700083d2f2a/1_1/470.jpg', '/en/books/hero-on-a-mission-en/purchase', 'قهرمان-در-یک-ماموریت', '2023-01-27 02:47:41.532545', '2023-01-27 02:47:41.532545', NULL, 'Hero on a Mission');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1559, 'اهداف رابطه', 'چگونه در دوستیابی، ازدواج و سکس برنده شویم', 'چگونه در دوستیابی، ازدواج و سکس برنده شویم', 23, 8, 'book', 't', '<p><em>اهداف رابطه</em>(2020) طرحی برای توسعه روابط طولانی مدت با دوستان، همسرتان و خدا ارائه می دهد. مایکل تاد، نویسنده، با روایت تجربیات خود از درد دل و شفا، موانع رایج در روابط مدرن را بررسی کرده و نکاتی را برای غلبه بر آنها ارائه می‌کند. او همچنین نشان می‌دهد که چگونه می‌توانید اهداف دقیقی را تعیین کنید تا به شما کمک کند تا روابط مناسب را هدف قرار دهید.</p>', '2020-09-26 00:00:00', 3, 186, 'https://images.blinkist.io/images/books/5f69c26a6cee070006a73185/1_1/470.jpg', '/en/books/relationship-goals-en/purchase', 'اهداف-رابطه', '2023-01-27 02:47:46.909945', '2023-01-27 02:47:46.909945', NULL, 'Relationship Goals');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1560, 'حس سبک', 'راهنمای انسان متفکر برای نوشتن در قرن بیست و یکم', 'راهنمای انسان متفکر برای نوشتن در قرن بیست و یکم', 18, 8, 'book', 't', '<p><em>حس سبک </em>(2014) یک راهنمای تازه و مرتبط برای نوشتن متون قدرتمند و خوانا از همه نوع ارائه می دهد. <em>حس سبک</em>به جای تمجید از همان قوانین گیج کننده و گاه ضد شهودی که در راهنماهای سبک سنتی یافت می شود، ترفندهای ساده و اکتشافی را ارائه می دهد که تضمین شده برای بهبود نوشتار شماست.</p>', '2016-01-28 00:00:00', 4, 63, 'https://images.blinkist.io/images/books/56a6af98fb7e87000700002b/1_1/470.jpg', '/en/books/the-sense-of-style-en/purchase', 'حس-سبک', '2023-01-27 02:47:52.287057', '2023-01-27 02:47:52.287057', NULL, 'The Sense of Style');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1564, 'جعبه', 'چگونه کانتینر حمل و نقل جهان را کوچکتر و اقتصاد جهانی را بزرگتر کرد؟', 'چگونه کانتینر حمل و نقل جهان را کوچکتر و اقتصاد جهانی را بزرگتر کرد؟', 24, 10, 'book', 't', '<p><em>جعبه</em> (2006) داستان کودک پوستر حمل و نقل مدرن، کانتینر، و اینکه چگونه صنعت حمل و نقل را متحول کرد و جهانی شدن را فعال کرد، می گوید. این پلک‌ها شما را به سفری مفصل در این تغییر به ظاهر ساده اما انقلابی در سیستم‌های تجارت جهانی می‌برد.</p>', '2015-12-17 00:00:00', 4, 34, 'https://images.blinkist.io/images/books/566fee90cf6aa3000700003e/1_1/470.jpg', '/en/books/the-box-en/purchase', 'جعبه', '2023-01-27 02:48:19.785907', '2023-01-27 02:48:19.785907', NULL, 'The Box');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1565, 'به مدرسه برنگرد', 'کتابی برای یادگیری هر چیزی', 'کتابی برای یادگیری هر چیزی', 17, 8, 'book', 't', '<p><em>به مدرسه برنگرد</em>نشان می دهد که چگونه نداشتن مدرک شما را به یک زندگی ناموفق محکوم نمی کند. در واقع، کاملا برعکس: این کتاب که مملو از مثال‌های واقعی است، یک مورد قوی برای یادگیری مستقل و همچنین اصولی را ارائه می‌کند که می‌توانید فوراً آن را اعمال کنید تا یادگیری مستقل بخشی از زندگی شما باشد.</p>', '2014-10-02 00:00:00', 4, 56, 'https://images.blinkist.io/images/books/54299a1462666100081c0000/1_1/470.jpg', '/en/books/dont-go-back-to-school-en/purchase', 'به-مدرسه-برنگرد', '2023-01-27 02:48:26.658474', '2023-01-27 02:48:26.658474', NULL, 'Don’t Go Back to School');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1566, 'بودیسم - ساده و ساده', 'تمرین آگاه بودن، همین حالا، هر روز', 'تمرین آگاه بودن، همین حالا، هر روز', 11, 5, 'book', 't', '<p><em>Budism Plain and Simple</em> (2013) راهنمای بی معنی شما برای اعمال ضروری بودایی است. از ایجاد آگاهی تا زندگی در لحظه حال، مهمترین آموزه های بودیسم به روشی واضح و قابل دسترس توضیح داده شده و با جنبه هایی از زندگی روزمره که در آن ما بیشترین نیاز را داریم، مرتبط هستند.</p>', '2015-09-03 00:00:00', 4, 271, 'https://images.blinkist.io/images/books/55e618957a20120009000049/1_1/470.jpg', '/en/books/buddhism-plain-and-simple-en/purchase', 'بودیسم---ساده-و-ساده', '2023-01-27 02:48:33.483751', '2023-01-27 02:48:33.483751', NULL, 'Buddhism – Plain and Simple');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1567, 'سازماندهی از درون به بیرون', 'سیستم بدون خطا برای سازماندهی خانه، دفتر و زندگی شما', 'سیستم بدون خطا برای سازماندهی خانه، دفتر و زندگی شما', 12, 6, 'book', 'f', '<p><em>سازماندهی از درون بیرون</em> (1998) کتاب راهنمای ضروری در مورد چگونگی سازماندهی زندگی خود به روشی شخصی و پایدار است. از دفتر کار گرفته تا خانه و چمدان، این پلک‌ها راهبردهای گام به گام واضحی را برای سازماندهی کل دنیای شما ترسیم می‌کنند.</p>', '2015-06-02 00:00:00', 4, 42, 'https://images.blinkist.io/images/books/556c5d443236630007220000/1_1/470.jpg', '/en/books/organizing-from-the-inside-out-en/purchase', 'سازماندهی-از-درون-به-بیرون', '2023-01-27 02:48:41.069169', '2023-01-27 02:48:41.069169', NULL, 'Organizing From The Inside Out');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1568, 'تائو ته چینگ', 'فلسفه تائوئیست برای صلح، رضایت و تعادل در زندگی', 'فلسفه تائوئیست برای صلح، رضایت و تعادل در زندگی', 16, 4, 'book', 't', '<p><em>تائو ته چینگ</em> (حدود 400 سال قبل از میلاد) یکی از متون بنیادی تائوئیسم، جنبش فلسفی و مذهبی پایدار است که می توان آن را به حدود قرن چهارم قبل از میلاد ردیابی کرد. در طول اعصار، حکمت شاعرانه آن همچنان مرتبط، الهام‌بخش و جاودانه است.</p>', '2022-12-14 00:00:00', 4, 38, 'https://images.blinkist.io/images/books/6398475bac44630009457086/1_1/470.jpg', '/en/books/tao-te-ching-en/purchase', 'تائو-ته-چینگ', '2023-01-27 02:48:48.400322', '2023-01-27 02:48:48.400322', NULL, 'Tao Te Ching');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1569, 'بزرگترین نمایش روی زمین', 'شواهدی برای تکامل', 'شواهدی برای تکامل', 19, 10, 'book', 't', '<p><em>The Greatest Show on Earth</em>(2009)<em></em>به استدلال‌های آفرینش‌گرایان که منکر این هستند که تکامل یک واقعیت علمی است، می‌پردازد و انتقادات آنها را نادرست نشان می‌دهد.< /p>
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1570, 'میلیونر همسایه', 'رازهای شگفت انگیز ثروتمندان آمریکا', 'رازهای شگفت انگیز ثروتمندان آمریکا', 13, 5, 'book', 't', '<p>برگرفته از مصاحبه های شخصی، <em>میلیونر همسایه</em> (1996) نشان می دهد که زندگی روزمره بسیاری از میلیونرها با کلیشه ماشین های لوکس، عمارت ها و جت های شخصی فاصله دارد. با این حال، این کتاب همچنین این باور را که میلیونر شدن دشوار است، رد می کند - هر کسی می تواند نه تنها یاد بگیرد که چگونه ثروتمند شود، بلکه ثروتمند بماند.</p>', '2015-06-11 00:00:00', 4, 295, 'https://images.blinkist.io/images/books/5575a37639356100076e0000/1_1/470.jpg', '/en/books/the-millionaire-next-door-en/purchase', 'میلیونر-همسایه', '2023-01-27 02:49:01.063457', '2023-01-27 02:49:01.063457', NULL, 'The Millionaire Next Door');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1571, 'هنر حکمت دنیوی', 'اوراکل جیبی', 'اوراکل جیبی', 21, 4, 'book', 't', '<p><em>هنر خرد دنیوی</em> (1647) یک کلاسیک کلاسیک خودیاری جاودانه است. شامل 300 اصل کوتاه اما درخشان، چگونگی زندگی کردن، دستیابی به موفقیت و جلب احترام را روشن می کند. این کتاب در طول تاریخ تقریباً 400 ساله انتشار خود به طور مداوم مرتبط باقی مانده است و الهام بخش افرادی مانند آرتور شوپنهاور و فردریش نیچه بوده است.</p>', '2022-06-26 00:00:00', 4, 409, 'https://images.blinkist.io/images/books/62b451476cee0700083ae7ef/1_1/470.jpg', '/en/books/the-art-of-worldly-wisdom-en/purchase', 'هنر-حکمت-دنیوی', '2023-01-27 02:49:09.034269', '2023-01-27 02:49:09.034269', NULL, 'The Art of Worldly Wisdom');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1573, 'کد دیابت', 'پیشگیری و معکوس کردن دیابت نوع 2 به طور طبیعی', 'پیشگیری و معکوس کردن دیابت نوع 2 به طور طبیعی', 22, 8, 'book', 't', '<p><em>کد دیابت </em>(2018) به یکی از هشداردهنده ترین اپیدمی های بهداشتی در جهان غربی می پردازد: افزایش دیابت نوع 2 - اختلالی که ارتباط نزدیکی با رژیم غذایی نامناسب و چاقی دارد. اما همانطور که جیسون فانگ نشان می دهد، می توان آن را معکوس کرد. نکته مهم این است که بفهمیم چه چیزی کار می کند و چه چیزی نیست. فانگ با تکیه بر تجربه حرفه ای خود و همچنین آخرین داده های علمی، یک مورد قدرتمند برای یک استراتژی رژیم غذایی برای پیشگیری و معکوس کردن دیابت نوع 2 ایجاد می کند که می توانید از امروز شروع به اجرای آن کنید.</p>', '2018-08-16 00:00:00', 5, 124, 'https://images.blinkist.io/images/books/5b73d82db238e100073cda1d/1_1/470.jpg', '/en/books/the-diabetes-code-en/purchase', 'کد-دیابت', '2023-01-27 02:49:23.08374', '2023-01-27 02:49:23.08374', NULL, 'The Diabetes Code');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1574, 'میانه کثیف', 'راه خود را از طریق سخت ترین و حیاتی ترین بخش هر سرمایه گذاری جسورانه پیدا کنید', 'راه خود را از طریق سخت ترین و حیاتی ترین بخش هر سرمایه گذاری جسورانه پیدا کنید', 19, 6, 'book', 't', '<p><em>میانه کثیف</em> (2018) واقعیت دشوار پیشبرد سرمایه‌گذاری کارآفرینی شما را از ایده‌پردازی تا تکمیل شدن، افزایش می‌دهد. اسکات بلسکی با اجتناب از افسانه مرسوم افزایش تدریجی به شکوه، توضیح می‌دهد که چگونه و کجا موفقیت استارت‌آپ شکل می‌گیرد: در مرحله میانی چالش‌برانگیز اما حیاتی این سرمایه‌گذاری.</p>', '2018-11-21 00:00:00', 4, 35, 'https://images.blinkist.io/images/books/5bf1f6f16cee070007ce4d01/1_1/470.jpg', '/en/books/the-messy-middle-en/purchase', 'میانه-کثیف', '2023-01-27 02:49:29.174596', '2023-01-27 02:49:29.174596', NULL, 'The Messy Middle');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1575, 'فروشنده چند ساله', 'هنر ساخت و بازاریابی کار ماندگار', 'هنر ساخت و بازاریابی کار ماندگار', 18, 8, 'book', 't', '<p><em>فروشنده چندساله</em> (2017) توضیح می دهد که چگونه می توان اطمینان حاصل کرد که کار خلاقانه عالی نیز در بازار موفق است. این پلک‌ها نه تنها نحوه موفقیت برای یک پروژه خاص را نشان می‌دهند، بلکه چگونگی تضمین موفقیت طولانی‌مدت مداوم برای خود به عنوان یک فرد خلاق را نیز نشان می‌دهند.</p>', '2017-12-07 00:00:00', 4, 31, 'https://images.blinkist.io/images/books/5a256f59b238e10008f0f445/1_1/470.jpg', '/en/books/perennial-seller-en/purchase', 'فروشنده-چند-ساله', '2023-01-27 02:49:34.948397', '2023-01-27 02:49:34.948397', NULL, 'Perennial Seller');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1576, 'قبیله مربیان', 'مشاوره زندگی کوتاه از بهترین های جهان', 'مشاوره زندگی کوتاه از بهترین های جهان', 18, 8, 'book', 't', '<p><em>قبیله مربیان</em> (2017) مجموعه‌ای روشنگر از مصاحبه‌ها با مربیان - متخصصان بسیار معتبری است که به طور گسترده‌ای به عنوان رهبران حوزه‌های مربوطه خود در نظر گرفته می‌شوند. تیم فریس برای درک رازهای موفقیت آنها از این مربیان سؤالات مختلفی می پرسد، از جمله "کتاب های مورد علاقه شما چیست؟" به "عادات روزانه شما چیست؟" پاسخ ها مجموعه ای از نکات مفید برای رسیدن به اوج را تشکیل می دهند.</p>', '2018-02-12 00:00:00', 4, 350, 'https://images.blinkist.io/images/books/5a808ba5b238e100085ef1e8/1_1/470.jpg', '/en/books/tribe-of-mentors-en/purchase', 'قبیله-مربیان', '2023-01-27 02:49:40.40113', '2023-01-27 02:49:40.40113', NULL, 'Tribe of Mentors');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1577, 'انقلاب پول خوب', 'چگونه پول بیشتری به دست آوریم تا کارهای خوبی انجام دهیم', 'چگونه پول بیشتری به دست آوریم تا کارهای خوبی انجام دهیم', 19, 5, 'book', 't', '<p><em>Good Money Revolution </em>(2022) راهنمای شما برای کسب درآمد بیشتر است – تا بتوانید پول بیشتری ببخشید. کسب درآمد با هدف به نفع همه است، از جمله شما.</p>', '2022-11-29 00:00:00', 4, 298, 'https://images.blinkist.io/images/books/638089ffba31850008d6c36b/1_1/470.jpg', '/en/books/good-money-revolution-en/purchase', 'انقلاب-پول-خوب', '2023-01-27 02:49:48.882152', '2023-01-27 02:49:48.882152', NULL, 'Good Money Revolution');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1578, 'علم بوسیدن', 'آنچه لب های ما به ما می گویند', 'آنچه لب های ما به ما می گویند', 11, 6, 'book', 't', '<p>بوسیدن: بخشی عادی از زندگی است. اما تعداد کمی از مردم اهمیت واقعی آن را درک می کنند. <em>علم بوسیدن</em> (2011) توضیح می دهد که چرا بوسیدن ریشه در زیست شناسی انسان و حیوان دارد، وقتی آن را انجام می دهیم از نظر فیزیولوژیکی چه اتفاقی می افتد و چرا بسیار مهمتر از آن چیزی است که شما ممکن است تصور کنید.</p>', '2016-03-17 00:00:00', 4, 190, 'https://images.blinkist.io/images/books/56e6e5349854a50007000113/1_1/470.jpg', '/en/books/the-science-of-kissing-en/purchase', 'علم-بوسیدن', '2023-01-27 02:49:56.609889', '2023-01-27 02:49:56.609889', NULL, 'The Science of Kissing');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1579, 'کوکلند', 'تاریخچه مخفی صنایع کخ و قدرت شرکتی در آمریکا', 'تاریخچه مخفی صنایع کخ و قدرت شرکتی در آمریکا', 23, 8, 'book', 't', '<p><em>Kochland </em>(2019) بیوگرافی صنایع Koch است. زمانی که یک مجموعه نسبتاً کوچک و نامنظم از هلدینگ‌های خصوصی بود، صنایع کوخ اکنون دومین شرکت خصوصی بزرگ در ایالات متحده است، با شبکه گسترده‌ای از دارایی‌ها که شامل همه چیز از پالایشگاه‌های نفت گرفته تا کارخانه‌های شیمیایی و خطوط لوله نفت تا کارخانه‌های کاغذ است. این پلک ها داستان رشد عظیم کخ را بیان می کند و نورهای جانبی را بر زندگی چارلز کخ، مدیرعامل بیش از 50 سال کوخ و مردی که همه چیز را ممکن کرد، می تاباند. </p>', '2021-07-09 00:00:00', 4, 39, 'https://images.blinkist.io/images/books/60dad99c6cee07000769b99d/1_1/470.jpg', '/en/books/kochland-en/purchase', 'کوکلند', '2023-01-27 02:50:04.573311', '2023-01-27 02:50:04.573311', NULL, 'Kochland');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1580, 'زندگی چیست؟', 'با ذهن و ماده و طرح های زندگی نامه ای', 'با ذهن و ماده و طرح های زندگی نامه ای', 25, 7, 'book', 't', '<p><em>زندگی چیست؟ </em>(1944) یک متن علمی کلاسیک است که بر اساس مجموعه ای از سخنرانی ها در کالج ترینیتی دوبلین توسط فیزیکدان مشهور اروین شرودینگر ارائه شده است. اگرچه شرودینگر یک فیزیکدان بود، اما این سخنرانی‌ها به مسائل زیست‌شناسی و ژنتیک می‌پرداختند - در درجه اول این سؤال اساسی که چگونه فیزیک و شیمی می‌توانند فرآیندهایی را که در موجودات زنده رخ می‌دهند توضیح دهند. مفاهیمی که او کاوش کرد، انقلابی را در ژنتیک به وجود آورد و از جمله زیست شناسان جیمز دی واتسون و فرانسیس کریک، که با هم ساختار مارپیچ دوگانه DNA را پیشنهاد کردند، الهام بخش شد.</p>', '2021-11-29 00:00:00', 4, 275, 'https://images.blinkist.io/images/books/61a0c17e6cee07000851b1b2/1_1/470.jpg', '/en/books/what-is-life-en/purchase', 'زندگی-چیست؟', '2023-01-27 02:50:12.427857', '2023-01-27 02:50:12.427857', NULL, 'What is Life?');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1581, 'قدرت سرگرمی', 'چگونه دوباره احساس زنده بودن کنیم', 'چگونه دوباره احساس زنده بودن کنیم', 26, 6, 'book', 't', '<p><em>قدرت سرگرمی </em>(2021) توضیح می دهد که چرا سرگرمی برای داشتن یک زندگی شاد و سالم اساسی است و چگونه می توان بیشتر از آن لذت برد. نه هر <em>سرگرمی</em> قدیمی، بلکه <em>تفریح ​​واقعی</em> - نوعی سرگرمی که باعث می‌شود بخندید، لبخند بزنید و احساس زنده بودن کنید!</p>', '2022-03-28 00:00:00', 4, 303, 'https://images.blinkist.io/images/books/62419db06cee070008a0cb06/1_1/470.jpg', '/en/books/the-power-of-fun-en/purchase', 'قدرت-سرگرمی', '2023-01-27 02:50:17.905825', '2023-01-27 02:50:17.905825', NULL, 'The Power of Fun');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1582, 'ذهن تمرین کننده', 'توسعه تمرکز و انضباط در زندگی شما', 'توسعه تمرکز و انضباط در زندگی شما', 10, 4, 'book', 't', '<p><em>ذهن تمرین کننده </em>(2005) راه حلی هوشمندانه و ساده برای کنترل اضطراب هنگام کار در جهت اهدافمان ارائه می دهد. این پلک‌ها تأثیر انتظارات ما بر بهره‌وری ما را نشان می‌دهد و گام‌هایی را نشان می‌دهد که می‌توانید برای زندگی در زمان حال، لذت بردن از پیشرفت خود و انجام واقعاً کارها بردارید.</p>', '2016-02-11 00:00:00', 4, 106, 'https://images.blinkist.io/images/books/56b8e3bed119f9000700008f/1_1/470.jpg', '/en/books/the-practicing-mind-en/purchase', 'ذهن-تمرین-کننده', '2023-01-27 02:50:25.055465', '2023-01-27 02:50:25.055465', NULL, 'The Practicing Mind');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1583, 'زبان خاموش رهبران', 'چگونه زبان بدن می تواند کمک کند - یا آسیب برساند - چگونه شما رهبری می کنید', 'چگونه زبان بدن می تواند کمک کند - یا آسیب برساند - چگونه شما رهبری می کنید', 16, 7, 'book', 't', '<p> رهبران قوی باید زبان بدن مناسب را به نمایش بگذارند و بتوانند آن را به خوبی در اعضای تیم خود بخوانند، اگر می خواهند آنها را به سمت موفقیت هدایت کنند. <em>زبان خاموش رهبران</em> (2011) نکاتی را برای خواندن و کنترل زبان بدن ارائه می دهد، حتی در فرهنگ هایی که نشانه های اجتماعی متفاوت است.</p>', '2016-01-05 00:00:00', 4, 60, 'https://images.blinkist.io/images/books/568aea8ede78c00007000009/1_1/470.jpg', '/en/books/the-silent-language-of-leaders-en/purchase', 'زبان-خاموش-رهبران', '2023-01-27 02:50:32.063365', '2023-01-27 02:50:32.063365', NULL, 'The Silent Language of Leaders');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1584, 'خدای اسراف', 'بازیابی قلب ایمان مسیحی', 'بازیابی قلب ایمان مسیحی', 15, 5, 'book', 't', '<p><em>خدای ولخرج</em>(2008) تفسیر جدیدی از تمثیل کلاسیک پسر ولگرد است. به جای تمرکز بر سرکشی بی پروا پسر کوچکتر در داستان، بر برادر بزرگتر وظیفه شناس تمرکز می کند که از طریق اطاعت از قوانین به دلایل اشتباه گناه می کند. این به ما نشان می‌دهد که همه ما این تمایلات مشکل‌ساز به درست‌کاری و برتر بودن را داریم، اما این چیزی است که ایمان مسیحی واقعاً درباره آن نیست. </p>', '2021-11-14 00:00:00', 4, 239, 'https://images.blinkist.io/images/books/6183e11d6cee070007adb076/1_1/470.jpg', '/en/books/the-prodigal-god-en/purchase', 'خدای-اسراف', '2023-01-27 02:50:39.205316', '2023-01-27 02:50:39.205316', NULL, 'The Prodigal God');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1585, 'طرح انرژی', 'هوشمندانه بخورید، احساس قوی کنید، در اوج خود عمل کنید', 'هوشمندانه بخورید، احساس قوی کنید، در اوج خود عمل کنید', 20, 7, 'book', 't', '<p><em>طرح انرژی </em>(2019) یک رویکرد مبتنی بر علم برای تغذیه سالم را بررسی می کند. این آخرین تحقیقات در زمینه تغذیه را بررسی می‌کند و نحوه استفاده از این اطلاعات را برای انتخاب بهتر در مورد غذایی که می‌خورید بیان می‌کند. </p>', '2021-03-04 00:00:00', 4, 171, 'https://images.blinkist.io/images/books/6038ca0d6cee070007bd5622/1_1/470.jpg', '/en/books/the-energy-plan-en/purchase', 'طرح-انرژی', '2023-01-27 02:50:45.883678', '2023-01-27 02:50:45.883678', NULL, 'The Energy Plan');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1586, 'مرزها را تعیین کنید، آرامش را پیدا کنید', 'راهنمای بازیابی خود', 'راهنمای بازیابی خود', 28, 9, 'book', 't', '<p>Set Boundaries, Find Peace (2021) هر آنچه را که باید در مورد مرزها بدانید را بیان می کند: اینکه آنها چیستند، چرا به آنها نیاز دارید و چگونه آنها را در زندگی خود در حال حاضر پیاده کنید. این پلک زدن‌ها با شکستن زیر و بم تعیین مرزهای سالم، به شما اعتماد به نفس و قدرت می‌دهد تا در نهایت با آن مکالمات سختی که مدت‌هاست از آن‌ها اجتناب می‌کردید، مقابله کنید.</p>', '2021-05-03 00:00:00', 5, 460, 'https://images.blinkist.io/images/books/608bc8806cee070008a8f573/1_1/470.jpg', '/en/books/set-boundaries-find-peace-en/purchase', 'مرزها-را-تعیین-کنید،-آرامش-را-پیدا-کنید', '2023-01-27 02:50:52.81561', '2023-01-27 02:50:52.81561', NULL, 'Set Boundaries, Find Peace');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1587, 'همکاری با یکدیگر', 'چرا مشارکت های بزرگ موفق می شوند؟', 'چرا مشارکت های بزرگ موفق می شوند؟', 13, 6, 'book', 't', '<p><em>کار با هم</em> (2010) همه چیز درباره مزایای مشارکت های تجاری قوی است. برخی از افراد زمانی که با شخص دیگری جفت می‌شوند بیشترین بهره‌وری را دارند و این پلک‌ها از چندین مثال برجسته برای تشریح نحوه عملکرد انواع مختلف مشارکت استفاده می‌کنند.</p>', '2015-08-12 00:00:00', 4, 18, 'https://images.blinkist.io/images/books/55c7c8006664360007580000/1_1/470.jpg', '/en/books/working-together-en/purchase', 'همکاری-با-یکدیگر', '2023-01-27 02:50:59.987622', '2023-01-27 02:50:59.987622', NULL, 'Working Together');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1588, 'باشگاه ذهن', 'چه کسی فکر می کند، چه احساسی دارد و چرا مهم است', 'چه کسی فکر می کند، چه احساسی دارد و چرا مهم است', 12, 5, 'book', 't', '<p><em>باشگاه ذهن</em> (2016) درباره این است که چگونه ما موجودات را دارای ذهن می‌دانیم یا نه، و این تصمیم چگونه بر قضاوت‌های اخلاقی ما تأثیر می‌گذارد. این پلک‌ها توضیح می‌دهند که چه چیزی یک ذهن را تشکیل می‌دهد و همچنین چگونگی و چرایی درک ما از ذهن‌ها به روشی که انجام می‌دهیم را توضیح می‌دهد.</p>', '2016-08-10 00:00:00', 4, 115, 'https://images.blinkist.io/images/books/57a8c1141c2e11000357faba/1_1/470.jpg', '/en/books/the-mind-club-en/purchase', 'باشگاه-ذهن', '2023-01-27 02:51:07.466876', '2023-01-27 02:51:07.466876', NULL, 'The Mind Club');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1589, 'بربرها در دروازه', 'سقوط RJR Nabisco', 'سقوط RJR Nabisco', 19, 8, 'book', 't', '<p><em>Barbarians at the Gate</em> (1989) داستان یکی از بزرگترین معاملات شرکتی در تاریخ ایالات متحده، خرید اهرمی RJR Nabisco را روایت می کند. این پلک‌ها تصویری جذاب از رفتار افراطی و زیاده‌روی در آمریکای شرکت‌های بزرگ در طول دهه 1980 ارائه می‌دهند.</p>', '2017-08-29 00:00:00', 4, 35, 'https://images.blinkist.io/images/books/59a2d684b238e10006a12972/1_1/470.jpg', '/en/books/barbarians-at-the-gate-en/purchase', 'بربرها-در-دروازه', '2023-01-27 02:51:14.641233', '2023-01-27 02:51:14.641233', NULL, 'Barbarians at the Gate');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1590, 'نقطه جانوس', 'نظریه جدید زمان', 'نظریه جدید زمان', 17, 6, 'book', 't', '<p><em>نقطه جانوس </em>(2020) برداشتی تحریک‌آمیز و جدید از منشأ زمان و سرنوشت جهان است. امروزه اکثر فیزیکدانان معتقدند که جهان به شکلی که ما می شناسیم با انفجار بزرگ آغاز شده است. اما ممکن است احتمال متفاوتی وجود داشته باشد - که انفجار بزرگ آغاز زمان نبود، بلکه صرفاً یک نقطه بسیار ویژه در تاریخ کیهان ما بود.</p>', '2021-03-05 00:00:00', 4, 113, 'https://images.blinkist.io/images/books/6038c86f6cee070007bd5604/1_1/470.jpg', '/en/books/the-janus-point-en/purchase', 'نقطه-جانوس', '2023-01-27 02:51:22.259105', '2023-01-27 02:51:22.259105', NULL, 'The Janus Point');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1591, 'کار آگاهانه', 'چگونه مدیتیشن تجارت را از درون به بیرون تغییر می دهد', 'چگونه مدیتیشن تجارت را از درون به بیرون تغییر می دهد', 17, 8, 'book', 't', '<p><em>Mindful Work</em> (2015) مقدمه ای بر چرایی و چگونگی استفاده از ذهن آگاهی در غرب در سطح فردی و همچنین حرفه ای ارائه می دهد. با استفاده از مثال‌هایی از شرکت‌های معروف، مزایایی را که ذهن آگاهی می‌تواند به شما، افراد اطرافتان و محیط ارائه دهد، توضیح می‌دهد.</p>', '2015-12-10 00:00:00', 4, 74, 'https://images.blinkist.io/images/books/566610d5cb2fee0007000023/1_1/470.jpg', '/en/books/mindful-work-en/purchase', 'کار-آگاهانه', '2023-01-27 02:51:29.400833', '2023-01-27 02:51:29.400833', NULL, 'Mindful Work');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1592, 'توجه کرد', 'تبلیغات نوآورانه برای دنیای دیجیتال', 'تبلیغات نوآورانه برای دنیای دیجیتال', 15, 6, 'book', 't', '<p>چگونه می‌توانید در عصر مسدودکننده‌های تبلیغات، کاهش توجه و انتخاب عظیم مصرف‌کننده، مردم را به برند خود علاقه مند کنید؟ <em>توجه ویژه</em> (2015) تغییرات سریع چشم‌انداز رسانه را مورد بحث قرار می‌دهد و استراتژی‌هایی را برای موفقیت ترسیم می‌کند که فراتر از قرار دادن بنر و پنجره‌های بازشو است.</p>', '2015-07-09 00:00:00', 4, 25, 'https://images.blinkist.io/images/books/559bc89d3966610007990000/1_1/470.jpg', '/en/books/paid-attention-en/purchase', 'توجه-کرد', '2023-01-27 02:51:36.958911', '2023-01-27 02:51:36.958911', NULL, 'Paid Attention');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1593, 'U Thrive', 'چگونه در دانشگاه (و زندگی) موفق شویم', 'چگونه در دانشگاه (و زندگی) موفق شویم', 15, 6, 'book', 't', '<p><em>U Thrive </em>(2017) ابزارهای لازم برای پیشرفت در محوطه دانشگاه و فراتر از آن را فراهم می کند. این پلک‌ها در بخش‌های مساوی آموزنده و کاربردی هستند، بینش‌های بسیار خوبی را ارائه می‌دهند و توصیه‌های مفیدی را در مورد همه چیز از کاهش استرس در طول امتحانات نهایی گرفته تا زنده‌ماندن هم‌سرایان کابوس‌وار در خوابگاه ارائه می‌دهند.</p>', '2017-10-20 00:00:00', 4, 23, 'https://images.blinkist.io/images/books/59e4ac3ab238e1000617b407/1_1/470.jpg', '/en/books/u-thrive-en/purchase', 'U-Thrive', '2023-01-27 02:51:44.775553', '2023-01-27 02:51:44.775553', NULL, 'U Thrive');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1594, 'روال صبحگاهی من', 'چگونه افراد موفق هر روز را با الهام شروع می کنند', 'چگونه افراد موفق هر روز را با الهام شروع می کنند', 27, 10, 'book', 't', '<p>بر اساس مصاحبه‌های نویسندگان با 64 نفر از موفق‌ترین افراد امروزی، <em>روتین صبحگاهی من </em>(2018) راهنمای عملی برای پرندگان بالقوه است. بله، زندگی در ترس از ساعت زنگ دار و عبادت در محراب عملکرد خواب تلفنتان آسان است، اما لازم نیست اینطور باشد. صبح ها اصلاً نیازی به آسیب زا بودن ندارند. علاوه بر این، پیدا کردن روال مناسب برای ساعات اولیه کل روز شما را به سمت بهتر شدن تغییر می‌دهد.</p>', '2018-05-15 00:00:00', 4, 1005, 'https://images.blinkist.io/images/books/5af866e5b238e100073a2237/1_1/470.jpg', '/en/books/my-morning-routine-en/purchase', 'روال-صبحگاهی-من', '2023-01-27 02:51:52.577939', '2023-01-27 02:51:52.577939', NULL, 'My Morning Routine');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1595, 'شکافی در خلقت', 'ویرایش ژن و قدرت غیرقابل تصور برای کنترل تکامل', 'ویرایش ژن و قدرت غیرقابل تصور برای کنترل تکامل', 22, 8, 'book', 't', '<p><em>یک شکاف در خلقت</em> (2017) هر آنچه را که باید در مورد CRISPR بدانید، توضیح می‌دهد، روشی جدید برای تغییر ژن‌های موجودات زنده. این پلک ها جزئیات علمی ویرایش ژن را توضیح می دهند و در عین حال پیامدهای پزشکی و اخلاقی آن را نیز مورد بحث قرار می دهند.</p>', '2017-12-12 00:00:00', 5, 51, 'https://images.blinkist.io/images/books/5a2dd1afb238e1000a9f2cd1/1_1/470.jpg', '/en/books/a-crack-in-creation-en/purchase', 'شکافی-در-خلقت', '2023-01-27 02:52:00.325641', '2023-01-27 02:52:00.325641', NULL, 'A Crack in Creation');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1596, 'فراتر از اراده', 'از استرس تا موفقیت در 40 روز', 'از استرس تا موفقیت در 40 روز', 16, 7, 'book', 't', '<p><em>Beyond Willpower</em> (2015) راهنمای دستیابی به عمیق ترین و آرزومندترین اهداف شماست. این پلک‌ها نحوه تحقق رویاهایی را که برای شما شادی، شادی و عشق واقعی به ارمغان می‌آورند، توضیح می‌دهند، در حالی که به شما در مورد موانعی که معمولاً هنگام انجام این کار با آن‌ها مواجه می‌شوند هشدار می‌دهند، و همچنین به چند میانبر اشاره می‌کنند.</p>', '2017-01-12 00:00:00', 4, 56, 'https://images.blinkist.io/images/books/58760bc49acc4a0004cf717e/1_1/470.jpg', '/en/books/beyond-willpower-en/purchase', 'فراتر-از-اراده', '2023-01-27 02:52:08.281448', '2023-01-27 02:52:08.281448', NULL, 'Beyond Willpower');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1597, 'این بعد را برطرف کنید', 'تغییر حیاتی را ایجاد کنید که کسب و کار شما را ارتقا می دهد', 'تغییر حیاتی را ایجاد کنید که کسب و کار شما را ارتقا می دهد', 24, 8, 'book', 't', '<p><em>Fix This Next </em>(2020) به صاحبان کسب و کار سیستم ساده ای برای رسیدگی به مسائل کلیدی که مانع از شکوفایی شرکتشان می شود، ارائه می دهد. به جای تلاش برای رفع هر مشکل به یکباره، نشان می دهد که چگونه اجزای مختلف یک تجارت بر یکدیگر تأثیر می گذارند. همچنین ابزاری به نام سلسله مراتب نیازهای کسب و کار را ارائه می‌کند که می‌تواند به مالکان کمک کند تا ابتدا با کدام مشکل برخورد کنند تا از رشد و سودآوری مستمر اطمینان حاصل کنند.</p>', '2020-09-11 00:00:00', 5, 91, 'https://images.blinkist.io/images/books/5f527e546cee070006424328/1_1/470.jpg', '/en/books/fix-this-next-en/purchase', 'این-بعد-را-برطرف-کنید', '2023-01-27 02:52:16.619029', '2023-01-27 02:52:16.619029', NULL, 'Fix This Next');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1598, 'در مورد کوتاهی عمر', 'زندگی طولانی است اگر بدانید چگونه از آن استفاده کنید', 'زندگی طولانی است اگر بدانید چگونه از آن استفاده کنید', 12, 5, 'book', 't', '<p><em>درباره کوتاهی زندگی </em>(49 پس از میلاد) مقاله ای در مورد چگونگی قدردانی از زندگی - و نحوه استفاده از آن است. این پلک‌ها به شما نشان می‌دهند که در این دنیا چه چیزی واقعاً ارزشمند است و چگونه می‌توانید با مسائل بی‌اهمیت پریشان نشوید. آن‌ها به شما نشان می‌دهند که شادی واقعی از کجا می‌آید و چرا سخت‌کوشی منجر به ذهنی آرام و راضی نمی‌شود.</p>', '2017-04-14 00:00:00', 5, 301, 'https://images.blinkist.io/images/books/58ecb00a511add00045ae2c8/1_1/470.jpg', '/en/books/on-the-shortness-of-life-en/purchase', 'در-مورد-کوتاهی-عمر', '2023-01-27 02:52:23.964931', '2023-01-27 02:52:23.964931', NULL, 'On the Shortness of Life');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1599, 'هیپنوتولد', 'رویکرد موفقیت آمیز برای زایمان ایمن تر، آسان تر و راحت تر', 'رویکرد موفقیت آمیز برای زایمان ایمن تر، آسان تر و راحت تر', 21, 7, 'book', 't', '<p><em>HypnoBirthing</em> (1992) به بررسی این موضوع می‌پردازد که چگونه مادران باردار می‌توانند از زایمان راحت‌تر و شادتر لذت ببرند. این پلک‌ها تکنیک‌های هیپنوتیزم درمانی ساده‌ای را ارائه می‌کنند که زنان باردار می‌توانند آن‌ها را در خانه انجام دهند. آنها همچنین فلسفه راهنمای HypnoBirthing را آشکار می کنند و نشان می دهند که چگونه می تواند به زنان کمک کند تا زایمان طبیعی و کمتر دردناکی داشته باشند.</p>', '2020-06-06 00:00:00', 4, 86, 'https://images.blinkist.io/images/books/5ed6bc726cee0700060d2141/1_1/470.jpg', '/en/books/hypnobirthing-en/purchase', 'هیپنوتولد', '2023-01-27 02:52:31.376042', '2023-01-27 02:52:31.376042', NULL, 'HypnoBirthing');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1600, 'رسانه های اجتماعی دوست داشتنی', 'چگونه مشتریان خود را خوشحال کنیم، یک نام تجاری غیرقابل مقاومت ایجاد کنیم و به طور کلی در همه شبکه های اجتماعی که مهم هستند شگفت انگیز باشیم', 'چگونه مشتریان خود را خوشحال کنیم، یک نام تجاری غیرقابل مقاومت ایجاد کنیم و به طور کلی در همه شبکه های اجتماعی که مهم هستند شگفت انگیز باشیم', 24, 7, 'book', 't', '<p><em>رسانه های اجتماعی دوست داشتنی </em>(2011) راهنمای مفیدی برای تبلیغ کسب و کار شما در رسانه های اجتماعی است. این راهنما بهترین استراتژی‌ها را برای جلب توجه مثبت در پلتفرم‌هایی مانند Facebook، Twitter، Instagram و موارد دیگر نشان می‌دهد.</p>', '2021-06-29 00:00:00', 4, 142, 'https://images.blinkist.io/images/books/60d58fa26cee07000752ad86/1_1/470.jpg', '/en/books/likeable-social-media-en/purchase', 'رسانه-های-اجتماعی-دوست-داشتنی', '2023-01-27 02:52:39.779982', '2023-01-27 02:52:39.779982', NULL, 'Likeable Social Media');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1601, 'ظهور دختران موشک', 'زنانی که ما را از موشک به ماه تا مریخ پیش بردند', 'زنانی که ما را از موشک به ماه تا مریخ پیش بردند', 19, 8, 'book', 't', '<p><em>Rise of the Rocket Girls</em> (2016) داستان های جذاب و روشنگرانه زنانی را که در آزمایشگاه پیشرانه جت کار می کردند، نشان می دهد. این آزمایشگاه آزمایشگاه را از روزهای اولیه تا دوران مدرن، از آغاز عجیب تا نقش آن به عنوان یکی از مهم‌ترین اجزای ناسا، ردیابی می‌کند. این زنان مسئول اعداد و محاسبات مهمی بودند که ایالات متحده را در مسابقه فضایی نگه داشت و به پرتاب موشک، ماهواره و کاوشگر به دورترین نقاط منظومه شمسی کمک کرد. نفوذ آنها را نمی توان انکار کرد. و بیشتر از آن، باید تصدیق شود.</p>', '2017-10-27 00:00:00', 5, 18, 'https://images.blinkist.io/images/books/59ec8effb238e1000645543f/1_1/470.jpg', '/en/books/rise-of-the-rocket-girls-en/purchase', 'ظهور-دختران-موشک', '2023-01-27 02:52:47.504211', '2023-01-27 02:52:47.504211', NULL, 'Rise of the Rocket Girls');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1617, 'رئیس خودساخته', 'مشاوره، هک، و درس از صاحبان مشاغل کوچک', 'مشاوره، هک، و درس از صاحبان مشاغل کوچک', 19, 6, 'book', 't', '<p><em>Self-Made Boss </em>(2022) یک کیت شروع عملی برای هر کسی است که به دنبال راه اندازی یک تجارت کوچک است. این مجموعه مملو از توصیه ها و مطالعات موردی است که به کسب و کارهای کوچک در سراسر ایالات متحده می پردازد، با دستورالعمل های گام به گام برای تبدیل ایده عالی شما به یک تجارت موفق. </p>', '2022-06-14 12:00:00', 4, 148, 'https://images.blinkist.io/images/books/62a733bf6cee0700084f4614/1_1/470.jpg', '/en/books/self-made-boss-en/purchase', 'رئیس-خودساخته', '2023-01-27 02:54:40.322169', '2023-01-27 02:54:40.322169', NULL, 'Self-Made Boss');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1602, 'اول سود', 'کسب و کار خود را از یک هیولای پول خوار به یک ماشین پولساز تبدیل کنید', 'کسب و کار خود را از یک هیولای پول خوار به یک ماشین پولساز تبدیل کنید', 20, 7, 'book', 't', '<p><em>Profit First </em>(2014) گام‌های عملی را که کارآفرینان می‌توانند برای مشاهده فوری تفاوت مثبت در حساب‌های بانکی خود انجام دهند، بیان می‌کند. این چشمک‌ها توضیح می‌دهند که چگونه حسابداری سنتی بین کسب‌وکارها و سودهایی که صاحبان آن‌ها رویایش دارند قرار می‌گیرد و رویکرد جدیدی را پیشنهاد می‌کند که سودآوری ثابت را تضمین می‌کند. </p>', '2020-06-15 00:00:00', 5, 360, 'https://images.blinkist.io/images/books/5ee3629e6cee070006837780/1_1/470.jpg', '/en/books/profit-first-en/purchase', 'اول-سود', '2023-01-27 02:52:53.09867', '2023-01-27 02:52:53.09867', NULL, 'Profit First');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1603, 'جاه طلب بدون عذرخواهی', 'ریسک کنید، موانع را بشکنید و با شرایط خودتان موفقیت ایجاد کنید', 'ریسک کنید، موانع را بشکنید و با شرایط خودتان موفقیت ایجاد کنید', 19, 6, 'book', 't', '<p><em>Unapologetically Ambitious</em>(2020) سفر Shellye Archambeau برای تبدیل شدن به یکی از معدود مدیران عامل زن آفریقایی آمریکایی در سیلیکون ولی را دنبال می کند. این پلک‌ها برخی از درس‌ها، نگرش‌ها و استراتژی‌های ارزشمندی را نشان می‌دهند که به او در رسیدن به اهدافش کمک کردند.</p>', '2020-12-10 00:00:00', 4, 69, 'https://images.blinkist.io/images/books/5fca0a7b6cee070006b73a05/1_1/470.jpg', '/en/books/unapologetically-ambitious-en/purchase', 'جاه-طلب-بدون-عذرخواهی', '2023-01-27 02:53:00.612677', '2023-01-27 02:53:00.612677', NULL, 'Unapologetically Ambitious');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1604, 'ظهور استارتاپ', 'انقلاب کارآفرینی در حال بازسازی خاورمیانه', 'انقلاب کارآفرینی در حال بازسازی خاورمیانه', 12, 6, 'book', 'f', '<p>قیام های بهار عربی بسیاری از خاورمیانه را از نظر سیاسی بدون تغییر باقی گذاشت، اما سر و صدای زیادی به پا کرد. و با این حال، انقلاب دوم و آرام‌تری در همان منطقه در حال وقوع است - و همه چیز در مورد ظهور فناوری و کارآفرینی است. از طریق داستان‌های کارآفرینان خاورمیانه‌ای که در بیروت، امان، دبی، استانبول و جاهای دیگر زندگی می‌کنند، <em>Startup Rising</em> یک منطقه را نشان می‌دهد که دوباره خود را به عنوان مرکز فرصت‌های اقتصادی اختراع می‌کند.</p>', '2014-12-09 00:00:00', NULL, 7, 'https://images.blinkist.io/images/books/5485cce76331620009780000/1_1/470.jpg', '/en/books/startup-rising-en/purchase', 'ظهور-استارتاپ', '2023-01-27 02:53:08.70526', '2023-01-27 02:53:08.70526', NULL, 'Startup Rising');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1605, 'طرح مالی یک صفحه ای', 'یک راه ساده برای باهوش بودن در مورد پول خود', 'یک راه ساده برای باهوش بودن در مورد پول خود', 12, 6, 'book', 't', '<p><em>برنامه مالی یک صفحه ای </em>(2015) بودجه بندی را آسان می کند: هنگامی که می دانید چرا پول برای شما مهم است، فقط باید مطمئن شوید که به اندازه کافی برای انجام آنچه می خواهید چه ایجاد درآمد پایدار یا پس انداز برای آینده. این راه حل برنامه ریزی ساده همه ابزارها، نکات و ترفندهایی را که برای تحقق رویاهای مالی خود نیاز دارید در اختیار شما قرار می دهد.</p>', '2015-12-14 00:00:00', 4, 142, 'https://images.blinkist.io/images/books/566ebbd4ddd17a0007000003/1_1/470.jpg', '/en/books/the-one-page-financial-plan-en/purchase', 'طرح-مالی-یک-صفحه-ای', '2023-01-27 02:53:13.77869', '2023-01-27 02:53:13.77869', NULL, 'The One-Page Financial Plan');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1606, 'کیهان', 'یک قدم کوچک به سوی درک عظمت جهان هستی', 'یک قدم کوچک به سوی درک عظمت جهان هستی', 21, 7, 'book', 't', '<p><em>کیهان</em> (1980) نقطه عطفی در علم رایج است. این به ما مفاهیم اساسی درک ما از جهان را نشان می دهد، سیارات و ستارگان چگونه هستند و درک ما از آنها چگونه تغییر کرده و تکامل یافته است.</p>', '2018-09-03 00:00:00', 4, 173, 'https://images.blinkist.io/images/books/5b8c0d94b238e100073e7b2f/1_1/470.jpg', '/en/books/cosmos-en/purchase', 'کیهان', '2023-01-27 02:53:21.620639', '2023-01-27 02:53:21.620639', NULL, 'Cosmos');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1607, 'راهب شهری', 'حکمت شرقی و هک های مدرن برای توقف زمان و یافتن موفقیت، شادی و آرامش', 'حکمت شرقی و هک های مدرن برای توقف زمان و یافتن موفقیت، شادی و آرامش', 30, 10, 'book', 't', '<p><em>راهب شهری </em>(2016) راهنمای میدانی برای نحوه گذر از زندگی مدرن با ذهنیت راهب‌گونه‌تر است. با تکیه بر سنت های معنوی شرقی، علوم معاصر، و زندگی اجدادمان، مملو از نکات عملی در مورد اینکه چگونه می توانیم خرد باستانی را در سبک زندگی مدرن خود ادغام کنیم. این به طیف گسترده ای از مشکلات شخصی، از جمله استرس، رژیم های غذایی ناسالم، و کمبود وقت، انرژی و احساس هدف می پردازد.</p>', '2021-01-18 00:00:00', 5, 90, 'https://images.blinkist.io/images/books/60016b1e6cee070006e82041/1_1/470.jpg', '/en/books/the-urban-monk-en/purchase', 'راهب-شهری', '2023-01-27 02:53:27.23721', '2023-01-27 02:53:27.23721', NULL, 'The Urban Monk');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1608, 'وفاداران زامبی', 'استفاده از خدمات مشتری عالی برای ایجاد طرفداران Rabid', 'استفاده از خدمات مشتری عالی برای ایجاد طرفداران Rabid', 11, 5, 'book', 't', '<p><em>وفاداران زامبی </em>(2015) به شما اطلاعاتی در مورد مشتریانی می دهد که هر شرکتی آرزوی جذب آنها را دارد. این پلک ها که با داستان های روشنگری از طیف گسترده ای از مشاغل نشان داده شده اند، گام های ساده ای را در اختیار شما قرار می دهند که برند شما می تواند برای ایجاد، رشد و حفظ یک پایگاه مشتری وفادار و مشتاق بردارد.</p>', '2016-02-19 00:00:00', 5, 17, 'https://images.blinkist.io/images/books/56c06a5a4f33cc0007000079/1_1/470.jpg', '/en/books/zombie-loyalists-en/purchase', 'وفاداران-زامبی', '2023-01-27 02:53:35.071557', '2023-01-27 02:53:35.071557', NULL, 'Zombie Loyalists');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1609, 'به خوبی با دیگران کار می کند', 'راهنمای یک فرد خارجی برای دست دادن، ساکت کردن، برخورد با حرکات تند و دیگر مهارت‌های حیاتی در تجارت که هیچ‌کس هرگز به شما یاد نمی‌دهد', 'راهنمای یک فرد خارجی برای دست دادن، ساکت کردن، برخورد با حرکات تند و دیگر مهارت‌های حیاتی در تجارت که هیچ‌کس هرگز به شما یاد نمی‌دهد', 10, 5, 'book', 't', '<p><em>به‌خوبی با دیگران کار می‌کند</em> (2015) راهنمای حرفه‌ای‌ها – چه جدید و چه قدیمی – است که به دنبال نکات و ترفندهایی برای مدیریت خود در محیط کار مدرن هستند. از تسلط بر فرآیند مصاحبه گرفته تا تطبیق در روز اول، این پلک ها قوانین اجتماعی حیاتی را به شما می آموزند که هیچ کس هرگز درباره آنها صحبت نمی کند.</p>', '2015-12-21 00:00:00', 3, 34, 'https://images.blinkist.io/images/books/5677bac2fba8510007000000/1_1/470.jpg', '/en/books/works-well-with-others-en/purchase', 'به-خوبی-با-دیگران-کار-می-کند', '2023-01-27 02:53:42.684345', '2023-01-27 02:53:42.684345', NULL, 'Works Well With Others');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1610, 'موفقیت و شانس', 'خوشبختی و اسطوره شایسته سالاری', 'خوشبختی و اسطوره شایسته سالاری', 21, 7, 'book', 't', '<p><em>موفقیت و شانس</em>(2016) نگاهی غیرمتعارف به نقش شانس در اقتصاد ما ارائه می دهد. این مانیفست استدلال می‌کند که کمی شانس خیلی بیشتر از آنچه فکر می‌کنیم مهم است و نادیده گرفتن این واقعیت چیزی است که ما را از پیشرفت باز می‌دارد.</p>', '2017-03-13 00:00:00', 4, 125, 'https://images.blinkist.io/images/books/58c688518d90030004072587/1_1/470.jpg', '/en/books/success-and-luck-en/purchase', 'موفقیت-و-شانس', '2023-01-27 02:53:49.89312', '2023-01-27 02:53:49.89312', NULL, 'Success and Luck');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1611, 'خوش بینی آموخته است', 'چگونه ذهن و زندگی خود را تغییر دهید', 'چگونه ذهن و زندگی خود را تغییر دهید', 18, 11, 'book', 'f', '<p><em>خوش‌بینی آموخته شده </em>توضیح می‌دهد که چرا بسیاری از افراد بدبین می‌شوند و پیامدهای منفی این عادت چیست. علاوه بر این، نشان می دهد که چگونه خوش بینی یا بدبینی همیشگی ما در همه زمینه های زندگی ما را برای بهتر یا بدتر تحت تاثیر قرار می دهد. در نهایت، نشان می‌دهد که چگونه بدبین‌ها می‌توانند یاد بگیرند که چگونه خوش‌بین شوند، در نتیجه سلامت و شادی خود را تا حد زیادی بهبود می‌بخشند، و چندین تکنیک برای یادگیری این شیوه جدید تفکر ارائه می‌کند.</p>', '2014-04-29 11:00:00', 5, 210, 'https://images.blinkist.io/images/books/534ec41a6531660007650000/1_1/470.jpg', '/en/books/learned-optimism-en/purchase', 'خوش-بینی-آموخته-است', '2023-01-27 02:53:56.914981', '2023-01-27 02:53:56.914981', NULL, 'Learned Optimism');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1612, 'از بیرون هدایت کنید', 'چگونه آینده خود را بسازیم و تغییر واقعی ایجاد کنیم', 'چگونه آینده خود را بسازیم و تغییر واقعی ایجاد کنیم', 25, 8, 'book', 't', '<p><em>Lead from the Outside </em>(2018) یک کتاب راهنما برای افراد خارجی است که به دنبال یک صندلی پشت میز هستند. استیسی آبرامز بیان می‌کند که چگونه افراد کم‌نماینده و محروم می‌توانند از جاه‌طلبی و نبوغ خود برای به دست آوردن قدرت استفاده کنند، در مورد مسائل مالی، غلبه بر ترس و هک کردن سیستم مشاوره ارائه می‌دهند.</p>', '2021-01-08 00:00:00', 4, 39, 'https://images.blinkist.io/images/books/5ff2d8966cee070006eae23e/1_1/470.jpg', '/en/books/lead-from-the-outside-en/purchase', 'از-بیرون-هدایت-کنید', '2023-01-27 02:54:04.020024', '2023-01-27 02:54:04.020024', NULL, 'Lead from the Outside');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1613, 'ساعت برق', 'چگونه روی اهداف خود تمرکز کنید و زندگی مورد علاقه خود را ایجاد کنید', 'چگونه روی اهداف خود تمرکز کنید و زندگی مورد علاقه خود را ایجاد کنید', 21, 7, 'book', 't', '<p><em>ساعت قدرت</em>(2020) راهی را معرفی می‌کند که می‌توانید با اختصاص اولین ساعت هر روز به یک هدف یا اشتیاق، مسئولیت زندگی خود را به دست بگیرید. در دنیای شلوغ امروز، به تعویق انداختن کار آسان است. به جای اینکه منتظر زمان عالی برای دنبال کردن یک هدف باشید، باید برای انجام آن زمان <em>تخصیص</em> داشته باشید. یک ساعت در روز می تواند نگرش، عادات، سلامت و ارتباطات اجتماعی شما را تغییر دهد – و این تغییرات می تواند منجر به یک زندگی رضایت بخش تر و سازنده تر شود. </p>', '2021-02-23 00:00:00', 4, 237, 'https://images.blinkist.io/images/books/60335be06cee070007cf1781/1_1/470.jpg', '/en/books/power-hour-en/purchase', 'ساعت-برق', '2023-01-27 02:54:11.430737', '2023-01-27 02:54:11.430737', NULL, 'Power Hour');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1614, 'حقیقت در مورد مشارکت کارکنان', 'افسانه ای در مورد پرداختن به سه علت ریشه ای بدبختی شغلی', 'افسانه ای در مورد پرداختن به سه علت ریشه ای بدبختی شغلی', 18, 7, 'book', 't', '<p><em>حقیقت درباره مشارکت کارکنان</em> (2007) به شما می گوید که چگونه هر نوع شغلی را از بدبختی به معنی دار تبدیل کنید. با استفاده از سه نکته کلیدی، از کار خود لذت و رضایت خواهید داشت. پلک‌ها راهنمایی برای کارفرمایان برای ایجاد محیطی است که کارکنان می‌توانند در آن پیشرفت کنند، و به جویندگان کار توصیه می‌کند که چگونه شغلی را پیدا کنند که مناسب آنها باشد.</p>', '2019-04-10 00:00:00', 4, 132, 'https://images.blinkist.io/images/books/5ca9c1ce6cee07000759a4c7/1_1/470.jpg', '/en/books/the-truth-about-employee-engagement-en/purchase', 'حقیقت-در-مورد-مشارکت-کارکنان', '2023-01-27 02:54:17.529145', '2023-01-27 02:54:17.529145', NULL, 'The Truth about Employee Engagement');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1615, 'از راه دور', 'دفتر مورد نیاز نیست', 'دفتر مورد نیاز نیست', 16, 8, 'book', 't', '<p>در <em>Remote، </em>نگاهی درونی به نوع جدیدی از رابطه کاری می‌بینید که با فناوری مدرن امکان‌پذیر شده است، به نام "کار از راه دور". این کتاب ترس‌های رایج شرکت‌ها در مورد اجازه دادن به کارمندان برای کار از راه دور را توضیح می‌دهد و در مقابل، مزایای بسیاری از کار از راه دور را بیان می‌کند. نکته مهم این است که توصیه های عملی به مدیرانی ارائه می دهد که کارگران از راه دور را استخدام می کنند یا در نظر دارند گزینه های کار از راه دور را برای شرکت خود معرفی کنند.</p>', '2014-09-26 00:15:00', 4, 61, 'https://images.blinkist.io/images/books/54215d3337303300087d0000/1_1/470.jpg', '/en/books/remote-en/purchase', 'از-راه-دور', '2023-01-27 02:54:22.981425', '2023-01-27 02:54:22.981425', NULL, 'Remote');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1618, 'ثروت پنهان ملل', 'بلای بهشت ​​های مالیاتی', 'بلای بهشت ​​های مالیاتی', 15, 7, 'book', 't', '<p><em>ثروت پنهان ملل</em> (2015) حقیقتی را در مورد دهه‌ها شیوه‌های تجاری فریبکارانه که بر آشفتگی اقتصادی امروز افزوده‌اند، آشکار می‌کند. تریلیون‌ها دلار در سرتاسر جهان بدون مالیات می‌روند و کشورها بار را بر دوش شهروندان بی‌گناه می‌گذارند که تنها تنش‌های اقتصادی را افزایش می‌دهد. بنابراین چه کاری می توان برای جلوگیری از فرار مالیاتی انجام داد و شرکت ها شروع به پرداخت بدهی های خود کردند؟</p>', '2016-04-25 00:00:00', 4, 24, 'https://images.blinkist.io/images/books/57179eb93f35690007554dde/1_1/470.jpg', '/en/books/the-hidden-wealth-of-nations-en/purchase', 'ثروت-پنهان-ملل', '2023-01-27 02:54:48.073001', '2023-01-27 02:54:48.073001', NULL, 'The Hidden Wealth of Nations');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1619, 'فارمگدون', 'هزینه واقعی گوشت ارزان', 'هزینه واقعی گوشت ارزان', 31, 13, 'book', 't', '<p><em>Farmageddon</em> (2014) راهنمای عمیقی برای واقعیت تاریک گوشت ارزان است. این پلک ها توضیح می دهند که چگونه کشاورزی صنعتی جایگزین روش های سنتی شده است و چگونه منابع ما را تخلیه می کند، محیط زیست را مسموم می کند و ما را ناسالم می کند.</p>', '2016-07-01 00:00:00', 5, 13, 'https://images.blinkist.io/images/books/576d60a565d3da0003a7def1/1_1/470.jpg', '/en/books/farmageddon-en/purchase', 'فارمگدون', '2023-01-27 02:54:55.401579', '2023-01-27 02:54:55.401579', NULL, 'Farmageddon');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1620, 'پیدا کردن من', 'یک خاطره', 'یک خاطره', 23, 3, 'book', 't', '<p><em>Finding Me</em>(2022) خاطرات مورد انتظار ویولا دیویس بازیگر برنده جایزه اسکار، تونی و امی است. دیویس از به اشتراک گذاشتن دقیق‌ترین و صمیمی‌ترین جزئیات داستان زندگی‌اش، از سختی‌های وحشیانه دوران کودکی‌اش در رود آیلند، از سال‌های سرسختش به عنوان بازیگر صحنه برادوی، تا ورودش به رده‌های بالای سلبریتی هالیوود، هراسی ندارد. </p>', '2022-07-10 00:00:00', 5, 232, 'https://images.blinkist.io/images/books/62c5a4776cee070008104e4b/1_1/470.jpg', '/en/books/finding-me-en/purchase', 'پیدا-کردن-من', '2023-01-27 02:55:02.386466', '2023-01-27 02:55:02.386466', NULL, 'Finding Me');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1621, 'رویکرد حلقه', 'چگونه سازمان خود را از درون به بیرون متحول کنید', 'چگونه سازمان خود را از درون به بیرون متحول کنید', 25, 8, 'book', 't', '<p><em>رویکرد حلقه</em>(2019) رویکردی سیستماتیک برای تحول سازمان‌ها ارائه می‌کند. مجموعه ابزار ایده‌ها و روش‌های آن به گونه‌ای طراحی شده است که حتی به بزرگ‌ترین سازمان کمک کند عادت‌های بد خود را تغییر دهد، در نتیجه آن را قادر می‌سازد تا با چالش‌های آینده سازگار شود. </p>', '2019-09-24 00:00:00', 4, 59, 'https://images.blinkist.io/images/books/5d87dd2b6cee0700095f143f/1_1/470.jpg', '/en/books/the-loop-approach-en/purchase', 'رویکرد-حلقه', '2023-01-27 02:55:09.119218', '2023-01-27 02:55:09.119218', NULL, 'The Loop Approach');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1622, 'آنچه اکنون مهم است', 'چگونه در دنیای تغییرات بی امان، رقابت وحشیانه و نوآوری غیرقابل توقف برنده شویم', 'چگونه در دنیای تغییرات بی امان، رقابت وحشیانه و نوآوری غیرقابل توقف برنده شویم', 14, 6, 'book', 't', '<p><em>چه اهمیتی دارد اکنون </em>(2012) چالش های بسیاری را برای شرکت هایی که به دنبال حرکت در دنیایی که به طور فزاینده ای جهانی شده و مبتنی بر فناوری هستند را نشان می دهد. با توصیه‌های عملی، این پلک‌ها نشان می‌دهند که چگونه  شرکت نه تنها می‌تواند در چنین محیطی زنده بماند، بلکه می‌تواند سازگار، نوآوری و پیشرفت کند.</p>', '2015-04-29 00:00:00', 4, 30, 'https://images.blinkist.io/images/books/553fbdb561363100075f0000/1_1/470.jpg', '/en/books/what-matters-now-en/purchase', 'آنچه-اکنون-مهم-است', '2023-01-27 02:55:16.484809', '2023-01-27 02:55:16.484809', NULL, 'What Matters Now');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1623, 'متنفران خود را در آغوش بگیرید', 'چگونه شکایات را بپذیریم و مشتریان خود را حفظ کنیم', 'چگونه شکایات را بپذیریم و مشتریان خود را حفظ کنیم', 13, 6, 'book', 't', '<p><em>متنفران را در آغوش بگیرید</em> (2016) راهنمای استفاده از مشتریان ناراضی برای بهبود کسب و کارتان است. این پلک‌ها توضیح می‌دهند که چرا گوش دادن و پاسخ دادن به نظرات منفی مفید است و چگونه می‌توانید خشن‌ترین مشتریان خود را به بزرگترین طرفداران خود تبدیل کنید.</p>', '2016-06-01 00:00:00', 4, 22, 'https://images.blinkist.io/images/books/5746d08bb49ff200039c4d8e/1_1/470.jpg', '/en/books/hug-your-haters-en/purchase', 'متنفران-خود-را-در-آغوش-بگیرید', '2023-01-27 02:55:24.459728', '2023-01-27 02:55:24.459728', NULL, 'Hug Your Haters');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1624, 'کد استعداد', 'بزرگی متولد نمی شود رشد کرده است. در اینجا چگونه است.', 'بزرگی متولد نمی شود رشد کرده است. در اینجا چگونه است.', 20, 9, 'book', 't', '<p><em>کد</em><em>استعداد</em><em></em> از یافته‌های عصبی اخیر استفاده می‌کند تا توضیح دهد که چگونه می‌توان استعدادها را از طریق تمرین عمیق تربیت کرد. این نشان می‌دهد که چگونه پرورش عایق سلولی ما - به نام <em>میلین </em>- بر رشد مهارت‌های ما تأثیر می‌گذارد و توضیح می‌دهد که چرا روش‌های خاصی از تمرین و مربیگری در "مناطق استعدادها" در سراسر جهان به موفقیت بزرگی استفاده شده‌اند.< /p>', '2014-04-08 12:39:59', 5, 176, 'https://images.blinkist.io/images/books/5344481e6432320007010000/1_1/470.jpg', '/en/books/the-talent-code-en/purchase', 'کد-استعداد', '2023-01-27 02:55:32.739136', '2023-01-27 02:55:32.739136', NULL, 'The Talent Code');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1625, 'تاریخچه مختصر زمان', 'از انفجار بزرگ تا سیاه چاله ها', 'از انفجار بزرگ تا سیاه چاله ها', 27, 13, 'book', 't', '<p><em>A Brief History of Time </em>(1988) نگاهی به تاریخچه نظریه علمی و ایده هایی می اندازد که درک ما از جهان امروزی را شکل می دهند. از انفجارهای بزرگ و سیاه‌چاله‌ها گرفته تا کوچک‌ترین ذرات جهان، هاوکینگ یک نمای کلی از تاریخ جهان و علم پیچیده پشت آن ارائه می‌کند، همه به گونه‌ای ارائه شده است که حتی خوانندگانی که با این ایده‌ها آشنا می‌شوند. اولین بار خواهد فهمید.</p>', '2014-02-19 09:00:00', 5, 382, 'https://images.blinkist.io/images/books/53048af534393700084e0000/1_1/470.jpg', '/en/books/a-brief-history-of-time-en/purchase', 'تاریخچه-مختصر-زمان', '2023-01-27 02:55:41.213667', '2023-01-27 02:55:41.213667', NULL, 'A Brief History of Time');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1626, 'استراتژی و تاکتیک های قیمت گذاری', 'راهنمای رشد سودآورتر', 'راهنمای رشد سودآورتر', 15, 8, 'book', 'f', '<p><em>استراتژی و تاکتیک های قیمت گذاری </em>(2010) اهمیت اساسی نحوه قیمت گذاری محصولات خود را نشان می دهد. با افشای باورهای غلط رایج، توضیح سه بعد قیمت گذاری موثر و پنج قدمی که می توانید برای دستیابی به آن بردارید، این پلک ها راهنمای ضروری برای به حداکثر رساندن سود شما از طریق قیمت گذاری هوشمندانه هستند.</p>', '2017-01-13 00:00:00', 4, 34, 'https://images.blinkist.io/images/books/58540cdee663d400041cec5d/1_1/470.jpg', '/en/books/the-strategy-and-tactics-of-pricing-en/purchase', 'استراتژی-و-تاکتیک-های-قیمت-گذاری', '2023-01-27 02:55:49.113856', '2023-01-27 02:55:49.113856', NULL, 'The Strategy and Tactics of Pricing');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1627, 'در استراتژی بزرگ', 'یک کلاس کارشناسی ارشد در تفکر استراتژیک', 'یک کلاس کارشناسی ارشد در تفکر استراتژیک', 16, 5, 'book', 't', '<p><em>در استراتژی بزرگ </em>(2018) از مطالعات موردی در طول تاریخ، از جمله روم باستان و جنگ سرد استفاده می‌کند تا ویژگی‌های مشترک بهترین رهبران جهان را بررسی کند. جان لوئیس گادیس، نویسنده برنده جایزه پولیتزر، همچنین به اشتباهات رایجی که در طول سال‌ها مرتکب شده‌اند، می‌پردازد که حتی قدرتمندترین رهبران را به زانو درآورده است.</p>', '2018-11-13 00:00:00', 4, 162, 'https://images.blinkist.io/images/books/5be8c6de6cee070007d428e6/1_1/470.jpg', '/en/books/on-grand-strategy-en/purchase', 'در-استراتژی-بزرگ', '2023-01-27 02:55:56.8317', '2023-01-27 02:55:56.8317', NULL, 'On Grand Strategy');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1628, 'اعداد ساده، صحبت مستقیم، سودهای بزرگ!', 'چهار کلید برای باز کردن پتانسیل کسب و کار شما', 'چهار کلید برای باز کردن پتانسیل کسب و کار شما', 18, 8, 'book', 't', '<p><em>اعداد ساده، صحبت مستقیم، سودهای کلان!</em> (2011) عناصر ضروری و به هم پیوسته ای را که باید بدانید و بر طول عمر و رشد شرکت شما تأثیر می گذارد، تشریح می کند. از طریق یک سری مراحل ساده، می‌توانید محل کار پربارتری ایجاد کنید تا در نهایت عملکرد را افزایش دهید و ثروت بیشتری بسازید.</p>', '2015-05-01 00:00:00', 4, 19, 'https://images.blinkist.io/images/books/553fff966233390007300000/1_1/470.jpg', '/en/books/simple-numbers-straight-talk-big-profits-en/purchase', 'اعداد-ساده،-صحبت-مستقیم،-سودهای-بزرگ!', '2023-01-27 02:56:04.648062', '2023-01-27 02:56:04.648062', NULL, 'Simple Numbers, Straight Talk, Big Profits!');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1629, 'بووار شدن', 'یک زندگی', 'یک زندگی', 24, 8, 'book', 't', '<p><em>Becoming Beauvoir</em>(2019) داستان فیلسوف، نویسنده و نماد فمینیست فرانسوی سیمون دوبوار را برای مخاطبان معاصر بازگو می کند. <em>Becoming Beauvoir</em>با استفاده از نامه‌ها و خاطرات منتشر نشده قبلی، چگونگی تبدیل شدن این روشنفکر مشهور به خود را شرح می‌دهد.</p>', '2020-09-18 00:00:00', 4, 69, 'https://images.blinkist.io/images/books/5f5fde966cee0700064ebcf4/1_1/470.jpg', '/en/books/becoming-beauvoir-en/purchase', 'بووار-شدن', '2023-01-27 02:56:12.972235', '2023-01-27 02:56:12.972235', NULL, 'Becoming Beauvoir');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1630, 'بزرگترین ایده ها در جهان', 'فضا، زمان و حرکت', 'فضا، زمان و حرکت', 17, 4, 'book', 't', '<p><em>فضا، زمان و حرکت</em> (2022) اولین مجموعه از یک مجموعه سه قسمتی با عنوان بزرگترین ایده ها در جهان است. در طول همه‌گیری کووید-19، شان کارول شروع به تولید ویدیوهایی کرد که برخی از بزرگترین ایده‌ها و مفاهیم فیزیک مدرن و معادلاتی را که از آنها پشتیبانی می‌کنند، توضیح می‌داد. او در مجموع 24 ویدیو تولید کرد و سپس مجموعه کتاب را از آن مطالب توسعه داد.</p>', '2022-12-28 00:00:00', 4, 42, 'https://images.blinkist.io/images/books/63a1cc74ac4463000945d8d6/1_1/470.jpg', '/en/books/the-biggest-ideas-in-the-universe-en/purchase', 'بزرگترین-ایده-ها-در-جهان', '2023-01-27 02:56:20.870435', '2023-01-27 02:56:20.870435', NULL, 'The Biggest Ideas in the Universe');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1631, 'اکنون، نقاط قوت خود را کشف کنید', 'چگونه استعدادهای خود و افرادی را که مدیریت می کنید پرورش دهید', 'چگونه استعدادهای خود و افرادی را که مدیریت می کنید پرورش دهید', 12, 5, 'book', 't', '<p><em>اکنون، نقاط قوت خود را کشف کنید </em>(2004) بینشی در مورد اینکه نقاط قوت چیست، از کجا می آیند و چرا باید روی آنها تمرکز کنیم، ارائه می دهد. این پلک‌ها نکات و تکنیک‌هایی را برای کشف استعدادهای طبیعی و استفاده از آنها برای قرار دادن خود یا کارمندانتان در مسیر تعالی بیان می‌کنند.</p>', '2016-01-29 00:00:00', 4, 82, 'https://images.blinkist.io/images/books/56a6b130fb7e870007000039/1_1/470.jpg', '/en/books/now-discover-your-strengths-en/purchase', 'اکنون،-نقاط-قوت-خود-را-کشف-کنید', '2023-01-27 02:56:28.428544', '2023-01-27 02:56:28.428544', NULL, 'Now, Discover Your Strengths');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1632, 'پنج اختلال در یک تیم', 'افسانه رهبری', 'افسانه رهبری', 17, 9, 'book', 't', '<p><em>پنج ناکارآمدی یک تیم</em> (2002) این مفهوم را ارائه می‌کند که تیم‌ها ذاتاً ناکارآمد هستند، بنابراین باید اقدامات عمدی برای تسهیل کار تیمی عالی انجام شود. یک رهبر تیم آگاه می تواند کارهای زیادی برای مؤثرتر کردن تیم خود انجام دهد، و کتاب ابزارهای عملی برای دستیابی به این هدف را تشریح می کند.</p>', '2014-02-04 09:00:00', 5, 534, 'https://images.blinkist.io/images/books/52f1195c35653600110b0000/1_1/470.jpg', '/en/books/the-five-dysfunctions-of-a-team-en/purchase', 'پنج-اختلال-در-یک-تیم', '2023-01-27 02:56:34.211803', '2023-01-27 02:56:34.211803', NULL, 'The Five Dysfunctions of a Team');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1633, 'سوپر باس ها', 'چگونه رهبران استثنایی بر جریان استعداد تسلط دارند', 'چگونه رهبران استثنایی بر جریان استعداد تسلط دارند', 16, 7, 'book', 't', '<p><em>Superbosses</em> (2016) راهنمای خودی برای درک اینکه چگونه رهبران کاریزماتیک، اغلب بحث برانگیز اما فراموش نشدنی تیک می زنند. این پلک‌ها الگوها و استراتژی‌های رئیس‌های با عملکرد برتر را نشان می‌دهند و توضیح می‌دهند که چگونه می‌توانید با تبدیل شدن به یک سوپر رئیس به کارمندان خود کمک کنید تا موفق شوند!</p>', '2016-06-28 00:00:00', 4, 21, 'https://images.blinkist.io/images/books/576b9b1be0dd250003d6158b/1_1/470.jpg', '/en/books/superbosses-en/purchase', 'سوپر-باس-ها', '2023-01-27 02:56:42.107351', '2023-01-27 02:56:42.107351', NULL, 'Superbosses');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1634, 'میمون های آشوب', 'فورچون زشت و شکست تصادفی در سیلیکون ولی', 'فورچون زشت و شکست تصادفی در سیلیکون ولی', 17, 7, 'book', 't', '<p><em>Chaos Monkeys</em> (2016) نگاهی آشکار به طرح‌های فریبکارانه و رویاهای میلیارد دلاری دارد که استارت‌آپ‌ها را در سیلیکون ولی هدایت می‌کنند. از شرکت‌هایی مانند گوگل و فیس‌بوک بازدید کنید و ببینید چه چیزی برای موفقیت لازم است و همچنین در پشت صحنه برخی از غالب‌ترین استارت‌آپ‌های جهان چه اتفاقی می‌افتد.</p>', '2016-12-01 00:00:00', 4, 35, 'https://images.blinkist.io/images/books/583d59f1e536360004b64ebd/1_1/470.jpg', '/en/books/chaos-monkeys-en/purchase', 'میمون-های-آشوب', '2023-01-27 02:56:50.157911', '2023-01-27 02:56:50.157911', NULL, 'Chaos Monkeys');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1635, 'مدرسه شبانه', 'علم تغییر زندگی در مورد خواب', 'علم تغییر زندگی در مورد خواب', 19, 8, 'book', 't', '<p><em>مدرسه شبانه </em>(2014) در مورد یک عنصر است که اغلب نادیده گرفته می شود و در عین حال ضروری برای شادی و موفقیت در زندگی است: یک خواب خوب شبانه. مردم قرن‌هاست که با خواب دست و پنجه نرم می‌کنند، و در حالی که ما به روش‌هایی برای کاهش بی‌خوابی دست و پنجه نرم می‌کنیم، همچنین بینش زیادی در مورد اینکه چرا خواب بسیار حیاتی است، به دست آورده‌ایم.</p>', '2017-04-27 00:00:00', 4, 48, 'https://images.blinkist.io/images/books/58ff6a3fb238e100061eedef/1_1/470.jpg', '/en/books/night-school-en/purchase', 'مدرسه-شبانه', '2023-01-27 02:56:58.760621', '2023-01-27 02:56:58.760621', NULL, 'Night School');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1636, 'وقتی نفس هوا می شود', 'یافتن امید در مواجهه با مشکلات غیرقابل حل', 'یافتن امید در مواجهه با مشکلات غیرقابل حل', 19, 9, 'book', 't', '<p><em>When Breath Becomes Air</em> (2016) داستان باورنکردنی Paul Kalanithi، جراح مغز و اعصاب و متخصص مغز و اعصاب را روایت می کند که در اواسط دهه سی سالگی به سرطان مبتلا شد و در اثر آن درگذشت. این پلک ها جزئیات سفر خارق العاده او در جستجوی معنای زندگی در مواجهه با مرگ را نشان می دهد.</p>', '2017-06-28 00:00:00', 4, 114, 'https://images.blinkist.io/images/books/594f008ab238e10005bb48e4/1_1/470.jpg', '/en/books/when-breath-becomes-air-en/purchase', 'وقتی-نفس-هوا-می-شود', '2023-01-27 02:57:06.610955', '2023-01-27 02:57:06.610955', NULL, 'When Breath Becomes Air');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1637, 'وقتی همه چیز از هم می پاشد', 'توصیه های قلبی برای زمان های سخت', 'توصیه های قلبی برای زمان های سخت', 15, 6, 'book', 't', '<p><em>When Things Fall Apart</em> (1997) راهنمای مقابله با بزرگترین چالش‌هایی است که زندگی بر سر شما ایجاد می‌کند. این پلک‌ها طیف وسیعی از مفاهیم و استراتژی‌ها را بررسی می‌کنند، از مدیتیشن گرفته تا شفقت به خود و تکنیک‌های تنفس، که به شما کمک می‌کند در مواجهه با سختی‌ها انعطاف‌پذیری داشته باشید و قدردانی عمیق‌تری از زندگی در لحظه داشته باشید.</p>', '2017-03-01 00:00:00', 4, 150, 'https://images.blinkist.io/images/books/58b410eb8566cb0004c1f405/1_1/470.jpg', '/en/books/when-things-fall-apart-en/purchase', 'وقتی-همه-چیز-از-هم-می-پاشد', '2023-01-27 02:57:12.458897', '2023-01-27 02:57:12.458897', NULL, 'When Things Fall Apart');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1638, 'ایده های خوب از کجا می آیند', 'تاریخ طبیعی نوآوری', 'تاریخ طبیعی نوآوری', 18, 9, 'book', 't', '<p><em>از کجا ایده های خوب می آیند</em> (2011) تکامل حیات روی زمین و تاریخ علم را بررسی می کند. این پرفروش‌ترین کتاب <em>نیویورک تایمز</em> شباهت‌های بسیاری را بین این دو برجسته می‌کند، از اتم‌های کربن که اولین بلوک‌های سازنده زندگی را تشکیل می‌دهند تا شهرها و شبکه جهانی وب که نوآوری‌ها و اکتشافات بزرگ را پرورش می‌دهد.</p>
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1639, 'سازمان ایده محور', 'باز کردن قدرت ایده های پایین به بالا', 'باز کردن قدرت ایده های پایین به بالا', 12, 6, 'book', 'f', '<p><em>سازمان ایده محور</em>n توضیح می دهد که چگونه سازمان ها می توانند با تشویق نوآوری در هر سطحی از کسب و کار، خود را برای موفقیت بلندمدت قرار دهند. اگرچه اکثر شرکت‌ها فکر می‌کنند که خلاقیت باید از بالا، یعنی از مدیران و کارشناسان ناشی شود، سازمان‌های ایده‌محور از نوآوری از پایین به بالا قدرت می‌گیرند.</p>', '2015-02-24 00:00:00', 4, 10, 'https://images.blinkist.io/images/books/54eaeeb4393366000a370000/1_1/470.jpg', '/en/books/the-idea-driven-organization-en/purchase', 'سازمان-ایده-محور', '2023-01-27 02:57:26.364489', '2023-01-27 02:57:26.364489', NULL, 'The Idea-Driven Organization');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1640, 'در نوشتن خوب', 'راهنمای کلاسیک برای نوشتن آثار غیرداستانی', 'راهنمای کلاسیک برای نوشتن آثار غیرداستانی', 25, 8, 'book', 't', '<p><em>درباره خوب نوشتن </em>(1976) اثر ویلیام زینسر راهنمای ضروری برای هنر و هنر نویسندگی غیرداستانی است. این کتاب راهنما که از دوره نویسندگی زینسر در دانشگاه ییل اقتباس شده است، اصول نوشتن خوب را به شیوه ای گرم و در دسترس معرفی می کند. علاوه بر این، مملو از نکات، ترفندها و ابزارهایی برای صیقل دادن نثر به کمال است.</p>', '2020-08-15 00:00:00', 4, 260, 'https://images.blinkist.io/images/books/5f3190076cee070006606550/1_1/470.jpg', '/en/books/on-writing-well-en/purchase', 'در-نوشتن-خوب', '2023-01-27 02:57:34.125533', '2023-01-27 02:57:34.125533', NULL, 'On Writing Well');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1677, 'وعده های غول ها', 'چگونه می توانید خلاء رهبری را پر کنید', 'چگونه می توانید خلاء رهبری را پر کنید', 25, 8, 'book', 't', '<p><em>The Promises of Giants </em>(2021) مجموعه ای از استراتژی ها را ارائه می دهد که شما را به یک رهبر خارق العاده تبدیل می کند. صرف نظر از اینکه چه کاری انجام می دهید یا در کجا در مسیر شغلی خود هستید، این سری از نکات عملی موفقیت شما را تسریع می کند و در عین حال به اطرافیانتان قدرت می بخشد. </p>', '2021-09-17 00:00:00', 4, 27, 'https://images.blinkist.io/images/books/613f694e6cee070007f35fbb/1_1/470.jpg', '/en/books/the-promises-of-giants-en/purchase', 'وعده-های-غول-ها', '2023-01-27 03:02:04.442253', '2023-01-27 03:02:04.442253', NULL, 'The Promises of Giants');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1641, 'تاب آوری', 'حکمت سخت به دست آمده برای زندگی بهتر', 'حکمت سخت به دست آمده برای زندگی بهتر', 14, 6, 'book', 't', '<p><em>تاب آوری</em> (2015) ما را تشویق می کند تا با درد و سختی مقابله کنیم و از آنها برای ایجاد معنا و یافتن شادی استفاده کنیم. نویسنده قول معجزه نمی دهد، زیرا هیچ درمان آسانی برای از دست دادن یک عزیز یا مواجهه با تراژدی های دیگر وجود ندارد. او فقط نوید اثربخشی کار سخت را می دهد و توضیح می دهد که چگونه بر ترس از شکست غلبه کنید و مسئولیت زندگی خود را به عهده بگیرید. اگر بتوانید این کار را انجام دهید، چالش‌هایی که با آن روبرو هستید تنها شما را قوی‌تر، عاقل‌تر و شجاع‌تر می‌کند.</p>', '2015-09-10 00:00:00', 4, 59, 'https://images.blinkist.io/images/books/55ed2e8611ad1a0009000077/1_1/470.jpg', '/en/books/resilience-en/purchase', 'تاب-آوری', '2023-01-27 02:57:41.681985', '2023-01-27 02:57:41.681985', NULL, 'Resilience');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1642, 'راه اندازی مجدد', 'آخرین فرصت برای اقتصاد هند', 'آخرین فرصت برای اقتصاد هند', 17, 8, 'book', 't', '<p>چند دهه پیش، به نظر می رسید هند آماده تبدیل شدن به یک بازیگر اصلی در اقتصاد جهانی است. امروز یکسری مشکلات جدی کشور را عقب نگه داشته است. <em>راه‌اندازی مجدد </em>(2015) توضیح می‌دهد که چه چیزی باعث افول هند شده است و بینش‌هایی در مورد آنچه می‌توان برای رفع آن انجام داد ارائه می‌دهد.</p>', '2016-03-04 00:00:00', NULL, 6, 'https://images.blinkist.io/images/books/56d81aa002c15c0007000008/1_1/470.jpg', '/en/books/restart-en/purchase', 'راه-اندازی-مجدد', '2023-01-27 02:57:49.584008', '2023-01-27 02:57:49.584008', NULL, 'Restart');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1643, 'به کیهان خوش آمدید', 'یک تور اخترفیزیکی', 'یک تور اخترفیزیکی', 37, 10, 'book', 't', '<p><em>Welcome to the Universe</em>(2016) مقدمه ای خیره کننده و نفس گیر برای اخترفیزیک است که بر اساس دوره محبوبی است که سه نویسنده در دانشگاه پرینستون ارائه کردند. همه - حتی افراد غیرعلم - را به سفری در جهان شناخته شده می کشاند، برای بررسی ستارگان، کهکشان ها، سیاهچاله ها و موارد دیگر توقف می کنند و همه اینها در حالی است که تئوری های جذابی در مورد سفر در زمان، مهبانگ و چشم انداز آن ارائه می کنند. زندگی در کهکشان های دیگر.</p>', '2022-11-13 00:00:00', 5, 278, 'https://images.blinkist.io/images/books/636a34cb11a60c0008278708/1_1/470.jpg', '/en/books/welcome-to-the-universe-en/purchase', 'به-کیهان-خوش-آمدید', '2023-01-27 02:57:57.482527', '2023-01-27 02:57:57.482527', NULL, 'Welcome to the Universe');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1644, 'پارادوکس طول عمر', 'چگونه در سنین پیری جوان بمیریم', 'چگونه در سنین پیری جوان بمیریم', 25, 8, 'book', 't', '<p><em>پارادوکس طول عمر </em>(2019) به سه مورد از مهم‌ترین عوامل پیری می‌پردازد: باکتری‌های روده، دیواره‌های روده و میتوکندری ما. نویسنده با کمک به درک نقش این عوامل در سلامتی ما و با نشان دادن چند استراتژی قدرتمند که می توانیم برای حمایت از آنها اتخاذ کنیم، ما را به زندگی طولانی و سالم راهنمایی می کند.</p>', '2019-04-16 00:00:00', 5, 224, 'https://images.blinkist.io/images/books/5cb4c56e6cee07000700672e/1_1/470.jpg', '/en/books/the-longevity-paradox-en/purchase', 'پارادوکس-طول-عمر', '2023-01-27 02:58:05.855651', '2023-01-27 02:58:05.855651', NULL, 'The Longevity Paradox');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1645, 'ملت جوانان', 'ایجاد برندهای قابل توجه در فرهنگ جوان محور', 'ایجاد برندهای قابل توجه در فرهنگ جوان محور', 16, 7, 'book', 't', '<p><em>YouthNation</em> (2015) بینش های اساسی را در مورد جوانان امروزی ارائه می دهد - نسل، سبک زندگی و پدیده رو به رشدی که برای موفقیت هر کسب و کاری در آینده ضروری است. این پلک ها نکات و نکات YouthNation را به شما می آموزد و به شما کمک می کند یک استراتژی به روز برای شرکت خود بسازید.</p>', '2015-12-18 00:00:00', NULL, 7, 'https://images.blinkist.io/images/books/566ffd98cf6aa30007000052/1_1/470.jpg', '/en/books/youthnation-en/purchase', 'ملت-جوانان', '2023-01-27 02:58:14.499067', '2023-01-27 02:58:14.499067', NULL, 'YouthNation');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1646, 'نظریه U', 'رهبری از آینده همانطور که ظهور می کند', 'رهبری از آینده همانطور که ظهور می کند', 13, 8, 'book', 'f', '<p>امروز، تغییرات اجتماعی بزرگی در حال انجام است، که هر کدام چالش‌های بزرگی را برای رهبران امروز و فردا ایجاد می‌کنند. <em>Theory U </em>(2016) توضیح می‌دهد که چگونه فرآیند به اصطلاح U می‌تواند برای مقابله با این چالش‌ها به طور جمعی و اجرای سریع راه‌حل‌ها استفاده شود. این با ضربه زدن به نقطه کور، منبع عمیق ترین غرایز خلاق ما به دست می آید.</p>', '2014-03-11 10:31:47', 4, 35, 'https://images.blinkist.io/images/books/531f6a576166310008000000/1_1/470.jpg', '/en/books/theory-u-en/purchase', 'نظریه-U', '2023-01-27 02:58:22.109481', '2023-01-27 02:58:22.109481', NULL, 'Theory U');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1647, 'این تو نیستی', '27 دلیل (اشتباه) که شما مجرد هستید', '27 دلیل (اشتباه) که شما مجرد هستید', 16, 8, 'book', 't', '<p><em>It’s Not You</em> (2014) پادزهری برای راهنماهای قراریابی کلیشه ای است که توصیه هایی را ارائه می دهند که با سبک زندگی مدرن امروزی مرتبط نیستند. در اینجا خواهید فهمید که چرا بعد از 30 سالگی دیگر نیازی به ترس از مجرد بودن ندارید و چرا ازدواج نباید به عنوان کلید خوشبختی شما در نظر گرفته شود. این راهنمایی برای کمک به زنان مجرد امروزی است که در دنیای دوستیابی کاملاً متفاوت از یک نسل قبل حرکت کنند.</p>', '2017-05-25 00:00:00', 4, 59, 'https://images.blinkist.io/images/books/59256927b238e10007b6afd4/1_1/470.jpg', '/en/books/its-not-you-en/purchase', 'این-تو-نیستی', '2023-01-27 02:58:30.260596', '2023-01-27 02:58:30.260596', NULL, 'It’s Not You');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1678, 'مشکلات وحشی', 'راهنمای تصمیماتی که ما را تعریف می کنند', 'راهنمای تصمیماتی که ما را تعریف می کنند', 16, 5, 'book', 't', '<p><em>مشکلات وحشی </em>(2022) کاوشی در تصمیم گیری است، به ویژه هنگامی که به مسائل مهم زندگی می رسد که می توانند عمیق ترین تأثیر را داشته باشند. اگرچه دنیای مدرن الگوریتم ها و رویکردهای عملی برای انجام این کار ارائه می دهد، محاسبات همیشه بهترین راه برای داشتن یک زندگی خوب نیست.</p>', '2022-11-02 00:00:00', 5, 288, 'https://images.blinkist.io/images/books/6360fd1c958fe9000879ec92/1_1/470.jpg', '/en/books/wild-problems-en/purchase', 'مشکلات-وحشی', '2023-01-27 03:02:12.419264', '2023-01-27 03:02:12.419264', NULL, 'Wild Problems');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1648, 'چگونه با هر کسی صحبت کنیم', '92 ترفند کوچک برای موفقیت بزرگ در روابط', '92 ترفند کوچک برای موفقیت بزرگ در روابط', 25, 11, 'book', 't', '<p><em>چگونه با هر کسی صحبت کنیم (1998) یک راهنمای ضروری برای بهبود مکالمات و زیباتر و مؤثرتر شدن در تعاملات اجتماعی شما است - بدون توجه به موقعیت. لیل لوندز گنجینه ای از تکنیک ها و نکاتی را به خوانندگان ارائه می دهد که به هر فردی که از نظر اجتماعی بی دست و پا هستند کمک می کند تا در محیط های محل کار، جلسات، زندگی خصوصی خود و در مهمانی ها اعتماد بیشتری کسب کند.</p>', '2018-06-01 00:00:00', 4, 1159, 'https://images.blinkist.io/images/books/5b0c24e0b238e10007ba983a/1_1/470.jpg', '/en/books/how-to-talk-to-anyone-en/purchase', 'چگونه-با-هر-کسی-صحبت-کنیم', '2023-01-27 02:58:37.777674', '2023-01-27 02:58:37.777674', NULL, 'How to Talk to Anyone');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1649, 'نخواب، مارها هستند', 'زندگی و زبان در جنگل آمازون', 'زندگی و زبان در جنگل آمازون', 13, 5, 'book', 't', '<p><em>نخواب، آنجا مارها هستند </em>(2008) در مورد فرهنگ و زبان منحصر به فرد پیراها به ما می گوید، مردم بومی جنگل آمازون که از اعداد استفاده نمی کنند و برای رنگ ها نام دارند. یا با صحبت های کوچک زحمت بکشید. آنها همچنین بیشتر از سایر فرهنگ ها می خندند و لبخند می زنند. این پلک‌ها توضیح می‌دهند که زبان‌ها چه چیزی می‌توانند درباره تجربه انسان به ما بگویند و علاوه بر این، چرا نباید فراموش کنیم که چه تعداد از فرهنگ‌ها و زبان‌های دیگر به غیر از فرهنگ ما در سراسر جهان وجود دارد.</p>', '2017-04-07 00:00:00', 5, 28, 'https://images.blinkist.io/images/books/58e20ad3fe685600046c9386/1_1/470.jpg', '/en/books/dont-sleep-there-are-snakes-en/purchase', 'نخواب،-مارها-هستند', '2023-01-27 02:58:44.546224', '2023-01-27 02:58:44.546224', NULL, 'Don’t Sleep, There Are Snakes');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1650, 'پتانسیل خود را به حداکثر برسانید', 'تخصص خود را افزایش دهید، ریسک های جسورانه را بپذیرید و شغلی باورنکردنی بسازید', 'تخصص خود را افزایش دهید، ریسک های جسورانه را بپذیرید و شغلی باورنکردنی بسازید', 13, 6, 'book', 't', '<p><em>پتانسیل خود را به حداکثر برسانید</em> (2013) در مورد استفاده حداکثری از مهارت‌ها، استعدادها و جاه‌طلبی‌ها است. این نکات و ابزارهای عمل محور را ارائه می دهد که به شما در اجرای ایده های خود و ایجاد یک حرفه شگفت انگیز کمک می کند. ویژگی ها و طرز فکر مولدترین افراد را کشف کنید و چگونه حداکثر پتانسیل خود را باز کنید.</p>', '2017-08-11 00:00:00', 4, 69, 'https://images.blinkist.io/images/books/59887e58b238e10006290102/1_1/470.jpg', '/en/books/maximize-your-potential-en/purchase', 'پتانسیل-خود-را-به-حداکثر-برسانید', '2023-01-27 02:58:49.396551', '2023-01-27 02:58:49.396551', NULL, 'Maximize Your Potential');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1651, 'تجزیه و تحلیل پیش بینی کننده', 'قدرت پیش بینی اینکه چه کسی کلیک کند، بخرد، دروغ بگوید یا بمیرد', 'قدرت پیش بینی اینکه چه کسی کلیک کند، بخرد، دروغ بگوید یا بمیرد', 17, 7, 'book', 't', '<p><em>Predictive Analytics</em>(2016) مقدمه ای مفید برای یک زمینه پیچیده و جذاب ارائه می دهد. بیاموزید که چگونه داده‌ها خرد می‌شوند تا مردم بتوانند تصمیمات آگاهانه‌تری بگیرند، رویه‌ای که به‌شدت روش انجام تحقیقات جهان و اداره کسب‌وکارش را تغییر داده است. Siegel نگاهی روشنگرانه به حوزه‌های گسترده‌ای ارائه می‌دهد که برای همیشه تغییر کرده‌اند، از بازاریابی گرفته تا مراقبت‌های بهداشتی، بانکداری تا هوش مصنوعی.</p>', '2017-11-27 00:00:00', 4, 57, 'https://images.blinkist.io/images/books/5a193e52b238e10006ebb457/1_1/470.jpg', '/en/books/predictive-analytics-en/purchase', 'تجزیه-و-تحلیل-پیش-بینی-کننده', '2023-01-27 02:58:56.353592', '2023-01-27 02:58:56.353592', NULL, 'Predictive Analytics');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1652, 'قدرت مشارکت کامل', 'مدیریت انرژی، نه زمان، کلید عملکرد بالا و تجدید شخصی است', 'مدیریت انرژی، نه زمان، کلید عملکرد بالا و تجدید شخصی است', 22, 10, 'book', 't', '<p><em>قدرت تعامل کامل</em> با بررسی علل و کیفیت بسیاری از منابع انرژی انرژی ما، فرمول اوج عملکرد را بررسی می کند. نویسندگان ترفندها و روش هایی را در مورد چگونگی پرورش آن منابع انرژی به روشی ارائه می دهند که به ما کمک می کند زندگی کاملی داشته باشیم که به عمیق ترین ارزش های ما پایبند باشد.</p>', '2021-04-29 08:46:46.791', 4, 68, 'https://images.blinkist.io/images/books/608a70ce6cee0700072288ff/1_1/470.jpg', '/en/books/the-power-of-full-engagement-en/purchase', 'قدرت-مشارکت-کامل', '2023-01-27 02:59:03.912727', '2023-01-27 02:59:03.912727', NULL, 'The Power of Full Engagement');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1653, 'استاد نادان', 'چگونه رهبران بزرگ درخشش غیر قابل پیش بینی را القا می کنند', 'چگونه رهبران بزرگ درخشش غیر قابل پیش بینی را القا می کنند', 14, 6, 'book', 't', '<p><em>استاد نادان </em>(2015) به دنیای موسیقی ارکسترال، سمفونی ها و اپرا می پردازد تا بینش هایی را در مورد رهبری آشکار کند - با پیچ و تاب بیشتری. با نگاهی دقیق‌تر به برخی از نام‌های بزرگ موسیقی کلاسیک، این پلک‌ها به ما کمک می‌کنند تا دیدگاه‌های جدیدی در مورد اینکه چگونه می‌توانیم با پذیرش اشتباهات وحدت و نوآوری را پیش ببریم، کشف کنیم.</p>', '2015-09-29 00:00:00', NULL, 8, 'https://images.blinkist.io/images/books/560926e68a14e60009000047/1_1/470.jpg', '/en/books/the-ignorant-maestro-en/purchase', 'استاد-نادان', '2023-01-27 02:59:10.832888', '2023-01-27 02:59:10.832888', NULL, 'The Ignorant Maestro');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1661, 'دارما در DNA', 'بینش در تقاطع زیست شناسی و بودیسم', 'بینش در تقاطع زیست شناسی و بودیسم', 18, 3, 'book', 't', '<p><em>دارما در DNA </em>(2022) تقاطعات بین فلسفه بودایی و زیست شناسی را بررسی می کند. در نگاه اول، این دو سنت نمی توانند بیشتر از این متفاوت باشند. یکی روحانی است. تجربی دیگر اما همپوشانی هایی وجود دارد. برای یکی، هر دو سنت تلاش‌هایی برای کشف معنا هستند. اما چیزی بیشتر از این وجود دارد: به نظر می‌رسد که هم آموزه‌های بودا و هم یافته‌های زیست‌شناسان در درک مشابهی از معنای انسان بودن همگرایی دارند.</p>', '2022-12-02 00:00:00', 4, 247, 'https://images.blinkist.io/images/books/6380aa4c4b900400085fc152/1_1/470.jpg', '/en/books/the-dharma-in-dna-en/purchase', 'دارما-در-DNA', '2023-01-27 03:00:08.498152', '2023-01-27 03:00:08.498152', NULL, 'The Dharma in DNA');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1654, 'کوچکتر سریعتر سبکتر متراکمتر ارزانتر', 'چگونه نوآوری به اثبات اشتباه فاجعه گران ادامه می دهد؟', 'چگونه نوآوری به اثبات اشتباه فاجعه گران ادامه می دهد؟', 14, 6, 'book', 't', '<p><em>کوچکتر سریعتر سبکتر چگالتر ارزانتر</em> (2014) روانشناسی پشت اضطراب و بدبینی ما در مورد تغییرات آب و هوا را توضیح می دهد. این پلک‌ها به جای تسلیم شدن و بازگشت به سبک زندگی قرون وسطایی، توضیح می‌دهند که چگونه نوآوری و فناوری‌های جدید به بشریت کمک می‌کند تا بقای خود را ادامه دهد و به حرکت رو به جلو ادامه دهد.</p>', '2016-09-30 00:00:00', 2, 39, 'https://images.blinkist.io/images/books/57e8e6fa4af49600036fe3f2/1_1/470.jpg', '/en/books/smaller-faster-lighter-denser-cheaper-en/purchase', 'کوچکتر-سریعتر-سبکتر-متراکمتر-ارزانتر', '2023-01-27 02:59:17.758109', '2023-01-27 02:59:17.758109', NULL, 'Smaller Faster Lighter Denser Cheaper');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1655, 'ذهن شاد', 'راهنمای ساده برای داشتن زندگی شادتر از امروز', 'راهنمای ساده برای داشتن زندگی شادتر از امروز', 24, 9, 'book', 't', '<p><em>ذهن شاد</em> (2017) تصورات و واقعیت‌های نادرست پیرامون آن چیز دست نیافتنی را بررسی می‌کند: خوشبختی. نویسندگان کوین هورسلی و لوئیس فوری توضیح می‌دهند که چرا انسان‌ها علیرغم قرن‌ها تمرین، هنوز در مکان‌های نامناسب به دنبال خوشبختی می‌گردند و تنها ناراحتی را در جستجوی ثروت‌های مادی می‌یابند. آنها همچنین یک برنامه عملی ارائه می دهند که می تواند به هر کسی کمک کند تا در مسیر درست برای زندگی شادتر و رضایت بخش تر قرار گیرد.</p>', '2019-08-12 00:00:00', 5, 232, 'https://images.blinkist.io/images/books/5d504ffe6cee0700071a3a5c/1_1/470.jpg', '/en/books/the-happy-mind-en/purchase', 'ذهن-شاد', '2023-01-27 02:59:25.51415', '2023-01-27 02:59:25.51415', NULL, 'The Happy Mind');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1656, 'شکست رو به جلو', 'تبدیل اشتباهات به پله هایی برای موفقیت', 'تبدیل اشتباهات به پله هایی برای موفقیت', 14, 6, 'book', 't', '<p><em>شکست پیش رو</em> (2000) دیدگاه مثبتی در مورد شکست ارائه می دهد. این پلک ها از داستان های موفقیت افسانه ای و حکایات ادبی استفاده می کنند تا اهمیت شکست، مزایای پذیرش آن و قدرت استفاده از اشتباهات خود را برای تحریک رشد شخصی توضیح دهند.</p>', '2017-04-20 00:00:00', 5, 157, 'https://images.blinkist.io/images/books/58f4a0821507cf00046b9952/1_1/470.jpg', '/en/books/failing-forward-en/purchase', 'شکست-رو-به-جلو', '2023-01-27 02:59:31.218784', '2023-01-27 02:59:31.218784', NULL, 'Failing Forward');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1657, 'بسازش', 'کتاب بازی شورشی برای تعامل با کارکنان در کلاس جهانی', 'کتاب بازی شورشی برای تعامل با کارکنان در کلاس جهانی', 35, 13, 'book', 't', '<p><em>Build It</em>(2018) نگاهی به یکی از مهم‌ترین رازهای موفقیت کسب‌وکار دارد که در عین حال نادیده گرفته شده است: مشارکت کارکنان. گلن الیوت و دبرا کوری با تکیه بر یک دهه تحقیق روی 2000 شرکت، تاکتیک‌های برخی از شناخته‌شده‌ترین شرکت‌های امروزی را بررسی می‌کنند تا روشن کنند که چگونه کارگران خود را فعال و سازنده نگه می‌دارند. یک موضوع مشترک؟ همه آنها کتاب قوانین منابع انسانی را پاره کردند و این کتاب راهگشا برای کمک به شما در انجام این کار طراحی شده است.</p>
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1658, 'قانون موفقیت', '15 اصل قدرتمند برای ثروت، سلامتی و خوشبختی', '15 اصل قدرتمند برای ثروت، سلامتی و خوشبختی', 26, 9, 'book', 't', '<p><em>قانون موفقیت </em>(1928) شامل 15 درس ارزشمند است که می توانید از آنها برای ایجاد انگیزه در مورد تبدیل برنامه ها و رویاهای خود به واقعیت استفاده کنید. شما می توانید این درس های عملی را امروز عملی کنید. آنها برای کمک به شما در تبدیل کلمات به عمل، به دست آوردن اعتماد به نفس و پیشرفت در هر محیطی طراحی شده اند.</p>', '2021-06-24 00:00:00', 5, 633, 'https://images.blinkist.io/images/books/60d307fc6cee070007e95dc6/1_1/470.jpg', '/en/books/the-law-of-success-en/purchase', 'قانون-موفقیت', '2023-01-27 02:59:44.467334', '2023-01-27 02:59:44.467334', NULL, 'The Law of Success');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1659, 'ابرقدرت های خلاق', 'خود را برای عصر خلاقیت تجهیز کنید', 'خود را برای عصر خلاقیت تجهیز کنید', 20, 8, 'book', 't', '<p><em>Creative Superpowers</em> (2018) یک راهنمای یک مرحله‌ای برای هک کردن خلاقیت شما است که توسط تیمی متشکل از افراد برجسته ساخته شده است که توصیه‌های خود را عملی کرده‌اند. مملو از نکات مفید و بینش‌های به موقع، این جعبه کبریتی است که شما به دنبال آن بودید تا آن آتش‌های خلاقانه خفته را برانگیزد.</p>', '2018-09-14 00:00:00', 5, 68, 'https://images.blinkist.io/images/books/5b990335862c430008dbba95/1_1/470.jpg', '/en/books/creative-superpowers-en/purchase', 'ابرقدرت-های-خلاق', '2023-01-27 02:59:52.401546', '2023-01-27 02:59:52.401546', NULL, 'Creative Superpowers');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1660, 'بازاریابی مرتکب', '12 گام برای ایجاد برندهای بی رقیب B2B', '12 گام برای ایجاد برندهای بی رقیب B2B', 18, 4, 'book', 't', '<p><em>بازاریابی Renegade </em>(2021) راهنمای دقیقی برای تبدیل شدن به یک بازاریاب B2B پیشرو در فضای شرکتی دیوانه کننده امروزی است. این چهار ویژگی کلیدی مدیران بازاریابی بسیار موفق را متمایز می کند و به شما نشان می دهد که چگونه می توانید آنها را در شرکت خود اعمال کنید. مهمتر از همه، نشان می دهد که چگونه می توان مارک های معنی دار ایجاد کرد که در هر سطح از سازمان شما تجسم یافته است<em>.</em></p>', '2022-09-13 00:00:00', 4, 131, 'https://images.blinkist.io/images/books/63199d396cee0700085f7f65/1_1/470.jpg', '/en/books/renegade-marketing-en/purchase', 'بازاریابی-مرتکب', '2023-01-27 03:00:00.152827', '2023-01-27 03:00:00.152827', NULL, 'Renegade Marketing');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1662, 'تشریفات روزانه', 'هنرمندان چگونه کار می کنند', 'هنرمندان چگونه کار می کنند', 17, 8, 'book', 't', '<p><em>آیین‌های روزانه</em> (2013) مجموعه‌ای سرگرم‌کننده و روشن‌کننده از کارهای روزمره ذهن‌ها و هنرمندان بزرگ است. شامل عادات کاری افرادی مانند جین آستن، لودویگ ون بتهوون و پابلو پیکاسو، بینش هایی را در مورد بهترین راه ها برای به حداکثر رساندن کارایی و جلوگیری از انسداد نویسنده، و همچنین نکاتی در مورد چگونگی گذراندن در دنیای خلاق ارائه می دهد.</p >', '2015-11-13 00:00:00', 4, 74, 'https://images.blinkist.io/images/books/56407ebe38663300076c0000/1_1/470.jpg', '/en/books/daily-rituals-en/purchase', 'تشریفات-روزانه', '2023-01-27 03:00:16.7306', '2023-01-27 03:00:16.7306', NULL, 'Daily Rituals');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1663, 'تیم قرمز', 'چگونه با تفکر مانند دشمن موفق شویم', 'چگونه با تفکر مانند دشمن موفق شویم', 13, 6, 'book', 't', '<p><em>تیم قرمز</em> (2015) بینشی در مورد استراتژی‌های نظامی و امنیتی ارائه می‌دهد که سعی می‌کنند حرکت بعدی دشمن را پیش‌بینی کنند. این کتاب با پوشش رویدادهایی از دستگیری اسامه بن لادن تا سرقت های مرموز که از طریق پنجره های سقفی انبار انجام می شود، یادآور آسیب پذیری های روزمره و اقداماتی است که باید در مورد آن انجام داد.</p>', '2016-07-29 00:00:00', 4, 39, 'https://images.blinkist.io/images/books/5794a7cf115d370003373e46/1_1/470.jpg', '/en/books/red-team-en/purchase', 'تیم-قرمز', '2023-01-27 03:00:25.060873', '2023-01-27 03:00:25.060873', NULL, 'Red Team');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1664, 'چگونه شروع کنیم', 'یک برنامه اثبات شده برای شروع کاری که مهم است', 'یک برنامه اثبات شده برای شروع کاری که مهم است', 23, 6, 'book', 't', '<p><em>How to Begin </em>(2022) استدلال می کند که با کار کردن روی چیزهای سخت قفل عظمت خود را باز می کنید. چیزهایی که اهمیت دارند. نه به شریک زندگی، دوستان یا خانواده شما - بلکه به <em>شما</em>. با این حال، سخت ترین بخش، خود کار نیست. شناسایی انواع پروژه هایی است که ارزش سرمایه گذاری در آنها را دارند. پروژه هایی که به زندگی شما معنا می بخشد. و این چیزی است که این کتاب واقعاً درباره آن است: کمک به شما برای کشف اهداف ارزشمند.</p>', '2022-04-07 00:00:00', 4, 589, 'https://images.blinkist.io/images/books/624ae6e96cee070008b6613e/1_1/470.jpg', '/en/books/how-to-begin-en/purchase', 'چگونه-شروع-کنیم', '2023-01-27 03:00:30.845178', '2023-01-27 03:00:30.845178', NULL, 'How to Begin');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1665, 'ثروت بدون مالیات', 'چگونه با کاهش دائمی مالیات خود ثروت هنگفتی بسازید؟', 'چگونه با کاهش دائمی مالیات خود ثروت هنگفتی بسازید؟', 15, 5, 'book', 't', '<p><em>ثروت بدون مالیات </em>(2012) رمز و راز مالیات را از بین می برد. این بینش گرانبها در مورد مالیات ها و برنامه ریزی مالیاتی ارائه می دهد که می توانید از آنها برای ساختن ثروت خود استفاده کنید. با اقتباس از تجربه حرفه ای و درک عمیق قوانین مالیاتی، اصول و قواعد زیربنای بهترین برنامه ریزی مالی را تجزیه می کند و به شما نشان می دهد که چگونه قوانین برای کمک به صرفه جویی در پول شما وجود دارد.</p>', '2023-01-03 00:00:00', 4, 45, 'https://images.blinkist.io/images/books/63aeb42af9d4a60007023051/1_1/470.jpg', '/en/books/tax-free-wealth-en/purchase', 'ثروت-بدون-مالیات', '2023-01-27 03:00:38.833944', '2023-01-27 03:00:38.833944', NULL, 'Tax-Free Wealth');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1666, 'سقوط به سمت بالا', 'معنویتی برای دو نیمه زندگی', 'معنویتی برای دو نیمه زندگی', 20, 5, 'book', 't', '<p><em>Falling Upward</em>(2011) "وظایف" دو نیمه زندگی را بررسی می کند. توضیح می دهد که نیمه دوم زندگی پیر شدن نیست. این در مورد پر کردن "ظرف" است که در نیمه اول ایجاد می کنیم و هدف خود را پیدا می کنیم. </p>', '2022-11-30 00:00:00', 5, 33, 'https://images.blinkist.io/images/books/6380a5544b900400085fc120/1_1/470.jpg', '/en/books/falling-upward-en/purchase', 'سقوط-به-سمت-بالا', '2023-01-27 03:00:46.304045', '2023-01-27 03:00:46.304045', NULL, 'Falling Upward');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1667, 'مشتری خودکار', 'ایجاد یک کسب و کار اشتراکی در هر صنعتی', 'ایجاد یک کسب و کار اشتراکی در هر صنعتی', 18, 9, 'book', 't', '<p>از خواربارفروشی‌ها گرفته تا دسترسی در پیست اسکی به MP3 - امروزه همه انواع کسب‌وکارها با اشتراک کار می‌کنند، و همه از غول‌هایی مانند آمازون گرفته تا شرکت‌های کوچک محلی سود می‌برند. <em>مشتری خودکار</em> مدل‌های متعددی را که می‌توانید برای بهره‌گیری از قدرت اشتراک‌ها استفاده کنید، تجزیه و تحلیل می‌کند، نحوه اندازه‌گیری موفقیت جدیدتان را توضیح می‌دهد، و نکاتی درباره ادامه کار خوب به شما ارائه می‌دهد.</p>', '2015-04-09 00:00:00', 4, 27, 'https://images.blinkist.io/images/books/552467343066650007630000/1_1/470.jpg', '/en/books/the-automatic-customer-en/purchase', 'مشتری-خودکار', '2023-01-27 03:00:52.037053', '2023-01-27 03:00:52.037053', NULL, 'The Automatic Customer');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1668, 'در کار پیروز شوید و در زندگی موفق شوید', '5 اصل برای رهایی از کیش کار زیاد', '5 اصل برای رهایی از کیش کار زیاد', 17, 7, 'book', 't', '<p><em>برنده شدن در کار و موفقیت در زندگی </em>(2021) به بررسی مشکلات فرهنگ کاری ساعات طولانی ما می پردازد. این نشان می‌دهد که چگونه حرفه‌ای‌ها می‌توانند زندگی شخصی خود را احیا کنند و به تعادل بهتری بین کار و زندگی دست یابند.</p>', '2021-06-11 00:00:00', 4, 145, 'https://images.blinkist.io/images/books/60bf736d6cee07000896ec51/1_1/470.jpg', '/en/books/win-at-work-and-succeed-at-life-en/purchase', 'در-کار-پیروز-شوید-و-در-زندگی-موفق-شوید', '2023-01-27 03:00:59.917339', '2023-01-27 03:00:59.917339', NULL, 'Win at Work and Succeed at Life');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1676, 'مردم را دوست داشته باشید، از چیزها استفاده کنید', 'زیرا مخالف هرگز کار نمی کند', 'زیرا مخالف هرگز کار نمی کند', 24, 7, 'book', 't', '<p><em>مردم را دوست بدارید، از چیزها استفاده کنید </em>(2021) مانیفستی است که از لذت های مینیمالیسم ستایش می کند. این آغازگر توضیح می دهد که چرا زندگی با چیزهای کمتر می تواند منجر به درهم ریختگی کمتر و روابط رضایت بخش تر شود.</p>', '2021-09-18 00:00:00', 4, 342, 'https://images.blinkist.io/images/books/61443dc86cee070007e04cf6/1_1/470.jpg', '/en/books/love-people-use-things-en/purchase', 'مردم-را-دوست-داشته-باشید،-از-چیزها-استفاده-کنید', '2023-01-27 03:01:56.345805', '2023-01-27 03:01:56.345805', NULL, 'Love People, Use Things');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1669, 'بی حد و حصر', 'مغز خود را ارتقا دهید، هر چیزی را سریعتر بیاموزید و زندگی استثنایی خود را باز کنید', 'مغز خود را ارتقا دهید، هر چیزی را سریعتر بیاموزید و زندگی استثنایی خود را باز کنید', 31, 10, 'book', 't', '<p><em>Limitless </em>(2020) یک راهنمای قدرتمند برای استفاده کامل از قابلیت‌های باورنکردنی مغز شما است. این برای هر کسی که تا به حال احساس کرده است برای موفقیت بیش از حد گنگ، بسیار کند یا بیش از حد بی مهارت بوده است، به چشم می خورد. بیاموزید که چگونه مغز خود را محدود کنید - و قدرت رسیدن به هر چیزی را به دست آورید.</p>', '2020-09-19 00:00:00', 5, 2022, 'https://images.blinkist.io/images/books/5f5fda5d6cee070006c639ec/1_1/470.jpg', '/en/books/limitless-en/purchase', 'بی-حد-و-حصر', '2023-01-27 03:01:08.321655', '2023-01-27 03:01:08.321655', NULL, 'Limitless');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1670, 'باقی مانده', 'چرا وقتی کمتر کار می کنید بیشتر کار می کنید؟', 'چرا وقتی کمتر کار می کنید بیشتر کار می کنید؟', 18, 8, 'book', 't', '<p><em>استراحت </em>(2016) این تصور غلط رایج را هدف قرار می‌دهد که هر چه بیشتر کار کنیم، بیشتر می‌توانیم کار را انجام دهیم. این مطالعه مبتنی بر تجربی که توسط یک استراتژیست دره سیلیکون نوشته شده است که رژیم تنبیهی او در ساعات طولانی اداری او را به طرز خطرناکی به فرسودگی شغلی نزدیک کرده است، این مطالعه مبتنی بر تجربی این ایده را برعکس می کند. رسیدن به اهداف و دستیابی به موفقیت به این معنا نیست که ساعت‌های بی‌پایان پشت میز کار خود را بگذرانید، بلکه در مورد یافتن بهترین زمان برای کار، استراحت کافی و پرورش خلاقیت شماست.</p>', '2018-11-08 00:00:00', 5, 263, 'https://images.blinkist.io/images/books/5be2c4fb6cee070008719cc9/1_1/470.jpg', '/en/books/rest-en/purchase', 'باقی-مانده', '2023-01-27 03:01:16.25797', '2023-01-27 03:01:16.25797', NULL, 'Rest');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1671, 'ساخته شده به چوب', 'چرا برخی از ایده ها زنده می مانند و برخی دیگر می میرند؟', 'چرا برخی از ایده ها زنده می مانند و برخی دیگر می میرند؟', 17, 9, 'book', 't', '<p><em>Made to Stick</em>توضیح می‌دهد که چرا برخی از ایده‌ها محبوب می‌شوند، در حالی که برخی دیگر پژمرده می‌شوند و می‌میرند.</p>
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1672, 'به هر حال هاللویا', 'کشف دوباره رحمت', 'کشف دوباره رحمت', 17, 8, 'book', 't', '<p><em>Hallelujah Anyway</em> (2017) معرفی مجدد مفاهیم رحمت و مهربانی است. اگر تا به حال به این فکر کرده اید که آیا این ارزش ها کاملاً ناپدید شده اند، این بینش بسیار مورد نیاز را در مورد اینکه چرا کمبود آنها وجود دارد و ما برای بازگرداندن آنها به زندگی خود چه کاری می توانیم انجام دهیم ارائه می دهد. یک روز دیگر را با غمگینی برای خود تلف نکن؛ در مسیر کشف مجدد لذت زندگی قرار بگیرید.</p>', '2017-11-02 00:00:00', 5, 25, 'https://images.blinkist.io/images/books/59f5e0f8b238e10006bf7646/1_1/470.jpg', '/en/books/hallelujah-anyway-en/purchase', 'به-هر-حال-هاللویا', '2023-01-27 03:01:29.626326', '2023-01-27 03:01:29.626326', NULL, 'Hallelujah Anyway');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1673, 'فقط کار', 'چگونه تعصب، تعصب و قلدری را ریشه کن کنیم تا فرهنگ فراگیری ایجاد کنیم', 'چگونه تعصب، تعصب و قلدری را ریشه کن کنیم تا فرهنگ فراگیری ایجاد کنیم', 28, 10, 'book', 't', '<p><em>Just Work</em>(2021) نشان می‌دهد که تعصب و تبعیض کنترل نشده چقدر در محل کار مضر است. هرکسی تعصبات و تعصبات ناخودآگاهی دارد که با خود به کار می آورد. اما اگر با اینها رودررو مواجه نشوند، می توانند یک محیط کاری مسموم با کارمندان ناراضی ایجاد کنند که نمی توانند بهترین کار را انجام دهند. مقابله با تعصب یک پیروزی برای همه است.</p>', '2021-05-18 00:00:00', 3, 119, 'https://images.blinkist.io/images/books/609bec1a6cee07000784b983/1_1/470.jpg', '/en/books/just-work-en/purchase', 'فقط-کار', '2023-01-27 03:01:35.06631', '2023-01-27 03:01:35.06631', NULL, 'Just Work');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1674, 'سیمی برای ایجاد', 'کشف رازهای ذهن خلاق', 'کشف رازهای ذهن خلاق', 26, 10, 'book', 't', '<p><em>Wired to Create </em>(2015) تلاش می کند تا آن ویژگی گریزان انسانی یعنی خلاقیت را معنا کند. این اکتشافات اخیر در علوم اعصاب و روانشناسی را با کاوش در عادات و شیوه های افراد بسیار خلاق دنبال می کند. «ذهن آشفته» و ویژگی‌های متناقض افراد خلاق، اهمیت عاداتی مانند بازی تخیلی و خیال‌پردازی، اشتیاق و شهود یا صراحت و حساسیت را آشکار می‌کند، که همگی در طول تاریخ بشر در هنر و نوآوری بزرگ نقش محوری داشته‌اند.</p>', '2019-01-09 00:00:00', 5, 129, 'https://images.blinkist.io/images/books/5c31ec936cee070007b479b5/1_1/470.jpg', '/en/books/wired-to-create-en/purchase', 'سیمی-برای-ایجاد', '2023-01-27 03:01:42.804425', '2023-01-27 03:01:42.804425', NULL, 'Wired To Create');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1675, 'اجرایی تکامل یافته', 'آینده کار عشق در عمل است', 'آینده کار عشق در عمل است', 27, 9, 'book', 't', '<p><em>The Evolved Executive </em>(2018) به رهبران کسب و کار امروزی راهنمای گام به گام در مورد اینکه چگونه رهبری و نیروی کار خود را برای دوران مدرن متحول کنند ارائه می دهد. هدر هنسون ویکمن، نویسنده، توصیه هایی در مورد چگونگی دور شدن از باورها و ساختارهای تجاری گذشته که باعث ترس در دل کارمندان می شود، ارائه می دهد و رویکردی معقول تر، مؤثرتر و دوست داشتنی تر را اتخاذ می کند. با استفاده از این نکات می توانید یک محل کار مولدتر و انعطاف پذیرتر پر از کارکنان توانمند و با انگیزه ایجاد کنید. </p>', '2019-07-01 00:00:00', 5, 23, 'https://images.blinkist.io/images/books/5d17d0206cee070007ea0ff3/1_1/470.jpg', '/en/books/the-evolved-executive-en/purchase', 'اجرایی-تکامل-یافته', '2023-01-27 03:01:50.75068', '2023-01-27 03:01:50.75068', NULL, 'The Evolved Executive');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1679, 'رازهای ارتباط پویا', 'با تمرکز آماده شوید، با وضوح ارائه دهید، با قدرت صحبت کنید', 'با تمرکز آماده شوید، با وضوح ارائه دهید، با قدرت صحبت کنید', 18, 8, 'book', 't', '<p><em>اسرار ارتباطات پویا</em> نحوه آماده سازی و ارائه موثر یک سخنرانی را توضیح می دهد. از طریق روش SCORRE خود نویسنده، ما از طریق شش مؤلفه کلیدی یک سخنرانی موفق راهنمایی می شویم: موضوع، موضوع اصلی، هدف، منطق، منابع و ارزیابی.</p>', '2014-09-14 00:00:00', 4, 52, 'https://images.blinkist.io/images/books/5416bf593861300008410000/1_1/470.jpg', '/en/books/secrets-of-dynamic-communication-en/purchase', 'رازهای-ارتباط-پویا', '2023-01-27 03:02:20.045211', '2023-01-27 03:02:20.045211', NULL, 'Secrets of Dynamic Communication');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1680, 'Rich Dad''s Retire Young Retire Rich', 'چگونه به سرعت ثروتمند شویم و برای همیشه ثروتمند بمانیم!', 'چگونه به سرعت ثروتمند شویم و برای همیشه ثروتمند بمانیم!', 22, 7, 'book', 't', '<p><em>Rich Dad''s Retire Young Retire Rich </em>(2012) رویکرد منحصر به فرد کارآفرین رابرت کیوساکی به امور مالی شخصی را آشکار می کند. او استدلال می کند که اگر می خواهید ثروتمند شوید، باید بدانید که چگونه از ذهن، برنامه و اقدامات خود استفاده کنید. کیوساکی نشان می‌دهد که پول درآوردن آسان‌تر از آن چیزی است که فکرش را می‌کنید.</p>', '2021-03-04 00:00:00', 5, 307, 'https://images.blinkist.io/images/books/6038c80e6cee070007bd55fa/1_1/470.jpg', '/en/books/rich-dads-retire-young-retire-rich-en/purchase', 'Rich-Dad''s-Retire-Young-Retire-Rich', '2023-01-27 03:02:24.771765', '2023-01-27 03:02:24.771765', NULL, 'Rich Dad’s Retire Young Retire Rich');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1681, 'اعتراضات', 'راهنمای نهایی برای تسلط بر هنر و علم گذراندن گذشته شماره', 'راهنمای نهایی برای تسلط بر هنر و علم گذراندن گذشته شماره', 21, 7, 'book', 't', '<p><em>Objections</em> (2019) رازهای پشت سرگردانی مخالفت‌های رایج فروش را بررسی می‌کند. با استفاده از بینش‌هایی از دنیای تجارت و روانشناسی، نشان می‌دهد که چگونه می‌توانید حتی بی‌میل‌ترین فرد را به یک خریدار مشتاق تبدیل کنید. </p>', '2019-11-14 00:00:00', 5, 104, 'https://images.blinkist.io/images/books/5dcac5806cee070007e48571/1_1/470.jpg', '/en/books/objections-en/purchase', 'اعتراضات', '2023-01-27 03:02:29.818885', '2023-01-27 03:02:29.818885', NULL, 'Objections');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1682, 'ذهنیت مامبا', 'چگونه بازی می کنم', 'چگونه بازی می کنم', 13, 5, 'book', 't', '<p><em>ذهنیت مامبا </em> (2018) برداشت شخصی کوبی برایانت از بسکتبال، زندگی و حرفه‌اش است. جزئیاتی در مورد چگونگی آمادگی جسمانی و ذهنی او برای بازی، عمق تجزیه و تحلیل حریفان و نحوه هدایت و رشد بسکتبال به او ارائه می دهد.</p>', '2022-12-29 00:00:00', 4, 111, 'https://images.blinkist.io/images/books/63ab0958ac44630009461241/1_1/470.jpg', '/en/books/the-mamba-mentality-en/purchase', 'ذهنیت-مامبا', '2023-01-27 03:02:36.750254', '2023-01-27 03:02:36.750254', NULL, 'The Mamba Mentality');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1683, 'از تازه کار تا بزرگ شده', 'رهبری خود را رشد دهید تا کسب و کار خود را توسعه دهید', 'رهبری خود را رشد دهید تا کسب و کار خود را توسعه دهید', 24, 8, 'book', 't', '<p><em>From Start-Up to Grown-Up </em>(2021)<em> </em>راهنمای بنیانگذاران و مدیران عامل استارت‌آپ‌هایی است که در راه گسترش هستند. ترکیب شیوه‌های مربیگری نویسنده برنده جایزه با بینش‌های جمع‌آوری‌شده از بنیان‌گذاران و مدیران اجرایی برجسته، مهارت‌های رهبری را که برای رشد در کنار کسب‌وکارتان نیاز دارید، مشخص می‌کند.</p>', '2022-03-29 00:00:00', 4, 105, 'https://images.blinkist.io/images/books/6241c1e66cee070008e3e87d/1_1/470.jpg', '/en/books/from-start-up-to-grown-up-en/purchase', 'از-تازه-کار-تا-بزرگ-شده', '2023-01-27 03:02:44.002901', '2023-01-27 03:02:44.002901', NULL, 'From Start-Up to Grown-Up');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1684, 'بازاریابی چریکی', 'استراتژی های آسان و ارزان برای کسب سودهای کلان از کسب و کار کوچک', 'استراتژی های آسان و ارزان برای کسب سودهای کلان از کسب و کار کوچک', 19, 8, 'book', 't', '<p> <em>بازاریابی چریکی</em> که در ابتدا در سال 1984 منتشر شد، یک کتاب کلاسیک است که برای بازاریابان ضروری است. این توضیح می دهد که چگونه شرکت های کوچک با بودجه بازاریابی محدود می توانند با خلاقیت با رقبای بزرگتر رقابت کنند.</p>', '2014-10-09 00:15:00', 4, 48, 'https://images.blinkist.io/images/books/543473c666636200081b0000/1_1/470.jpg', '/en/books/guerrilla-marketing-en/purchase', 'بازاریابی-چریکی', '2023-01-27 03:02:50.959812', '2023-01-27 03:02:50.959812', NULL, 'Guerrilla Marketing');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1685, 'رهبری آگاهانه', 'ارتقای انسانیت از طریق تجارت', 'ارتقای انسانیت از طریق تجارت', 23, 8, 'book', 't', '<p><em>رهبری آگاهانه</em> (2020) نشان می‌دهد که برای رهبری یک کسب‌وکار هدفمند که فراتر از نتیجه را می‌بیند، چه چیزی لازم است. جان مکی با تکیه بر تجربه خود به عنوان مدیر عامل یکی از بزرگترین سوپرمارکت‌های زنجیره‌ای در ایالات متحده، نشان می‌دهد که چگونه رهبران می‌توانند کسب‌وکار خود را به گونه‌ای شکل دهند که نوآورتر، رقابتی‌تر و از نظر اجتماعی مسئولیت‌پذیرتر شوند.</p>', '2020-11-16 00:00:00', 4, 103, 'https://images.blinkist.io/images/books/5fae5cf06cee070007d20e00/1_1/470.jpg', '/en/books/conscious-leadership-en/purchase', 'رهبری-آگاهانه', '2023-01-27 03:02:57.909207', '2023-01-27 03:02:57.909207', NULL, 'Conscious Leadership');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1686, 'حیوان قصه گو', 'چگونه داستان ها از ما انسان می سازند', 'چگونه داستان ها از ما انسان می سازند', 16, 7, 'book', 't', '<p><em>حیوان قصه گو </em>(2012) اعتیاد بشریت به داستان ها را بررسی می کند. این ارزش تکاملی شگفت‌انگیز آن‌ها را آشکار می‌کند و به وضوح اهمیت - و همچنین عوارض - را که داستان‌ها به زندگی ما می‌آورند، توضیح می‌دهد.</p>', '2016-02-29 00:00:00', 4, 67, 'https://images.blinkist.io/images/books/56d412f3bb82ae0007000002/1_1/470.jpg', '/en/books/the-storytelling-animal-en/purchase', 'حیوان-قصه-گو', '2023-01-27 03:03:04.434305', '2023-01-27 03:03:04.434305', NULL, 'The Storytelling Animal');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1687, 'مثل TED صحبت کن', 'نه راز سخنور عمومی ذهن برتر جهان', 'نه راز سخنور عمومی ذهن برتر جهان', 21, 9, 'book', 't', '<p>در <em>Talk</em> <em>مانند</em> <em>TED </em> (2014)، با استراتژی‌های ارائه که توسط تأثیرگذارترین سخنرانان عمومی جهان استفاده می‌شوند، آشنا خواهید شد. نویسنده Carmine Gallo بیش از 500 سخنرانی TED را تجزیه و تحلیل کرد تا ویژگی های مشترکی را که این سخنرانی ها را بسیار تأثیرگذار و جذاب می کند شناسایی کند.</p>', '2014-09-09 00:00:00', 5, 259, 'https://images.blinkist.io/images/books/54100f7b3635620008010000/1_1/470.jpg', '/en/books/talk-like-ted-en/purchase', 'مثل-TED-صحبت-کن', '2023-01-27 03:03:09.496443', '2023-01-27 03:03:09.496443', NULL, 'Talk Like TED');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1688, 'جانوران کوچکتر', 'تاریخچه پوزه به دم خوک فروتن', 'تاریخچه پوزه به دم خوک فروتن', 15, 7, 'book', 't', '<p><em>جانوران کوچکتر</em> (2015) به تاریخچه طولانی و جذاب خوک می پردازد. خوک که اغلب موجودی پست در نظر گرفته می شود، در واقع تنها حیوانی است که از ابتدای وجود ما با ما در ارتباط بوده است. شهرت خوک در طول سال‌ها ضربه‌های زیادی خورده است - و امروزه، به دلیل شیوه‌های کشاورزی مدرن، ممکن است رفاه آن بیش از هر زمان دیگری آسیب ببیند.</p>', '2016-07-14 00:00:00', NULL, 6, 'https://images.blinkist.io/images/books/577fbc83c088090003fe9f03/1_1/470.jpg', '/en/books/lesser-beasts-en/purchase', 'جانوران-کوچکتر', '2023-01-27 03:03:16.612135', '2023-01-27 03:03:16.612135', NULL, 'Lesser Beasts');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1689, 'مانند یک جادوگر بورس معامله کنید', 'نحوه دستیابی به عملکرد فوق العاده در سهام در هر بازار', 'نحوه دستیابی به عملکرد فوق العاده در سهام در هر بازار', 15, 5, 'book', 't', '<p><em>تجارت مانند یک جادوگر بازار سهام</em> (2013) راهنمای روش سرمایه گذاری SEPA (تحلیل نقطه ورودی خاص) است. شما را از طریق مدیریت ریسک، به حداکثر رساندن سود، و مهمتر از همه، ایمان به توانایی خود هدایت می کند. برای شروع کار در بازار سهام، لازم نیست حرفه ای باشید – در واقع، موقعیت شما به عنوان یک سرمایه گذار غیرعادی ممکن است در واقع بزرگترین نقطه قوت شما باشد. </p>', '2023-01-23 00:00:00', NULL, 2, 'https://images.blinkist.io/images/books/63c6cfbf3784800008d66c28/1_1/470.jpg', '/en/books/trade-like-a-stock-market-wizard-en/purchase', 'مانند-یک-جادوگر-بورس-معامله-کنید', '2023-01-27 03:03:23.546505', '2023-01-27 03:03:23.546505', NULL, 'Trade Like a Stock Market Wizard');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1690, 'بازارهای تطبیقی', 'تکامل مالی با سرعت فکر', 'تکامل مالی با سرعت فکر', 20, 8, 'book', 't', '<p><em>بازارهای تطبیقی ​​</em>(2017) درباره یک نظریه اقتصادی جدید است که به ما کمک می کند عنصر انسانی پشت بازارهای مالی را بهتر درک کنیم. اندرو دبلیو لو به طرز ماهرانه‌ای کاستی‌های تئوری‌های اقتصادی رایج را نشان می‌دهد و به ما نشان می‌دهد که چگونه امور مالی کمتر شبیه فیزیک یا ریاضی است و بیشتر شبیه یک موجود زنده پاسخگو و در حال تکامل است – نه بی شباهت به خودمان.</p>', '2018-02-23 00:00:00', 4, 55, 'https://images.blinkist.io/images/books/5a8c256bb238e100074317bb/1_1/470.jpg', '/en/books/adaptive-markets-en/purchase', 'بازارهای-تطبیقی', '2023-01-27 12:50:00.846204', '2023-01-27 12:50:00.846204', NULL, 'Adaptive Markets');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1691, 'قدرت بخشش قدرت', 'چگونه بهترین رهبران یاد می گیرند که رها کنند', 'چگونه بهترین رهبران یاد می گیرند که رها کنند', 19, 6, 'book', 't', '<p><em>قدرت بخشش قدرت </em>(2021) توضیح می‌دهد که چگونه رهبران، سازمان‌ها و کسب‌وکارها می‌توانند قدرت را با دادن قدرت مهار کنند. با جایگزین کردن ایده‌های سنتی سلسله مراتب با ذهنیتی که حول صورت‌های فلکی متمرکز است، می‌توانیم شبکه‌های انعطاف‌پذیری ایجاد کنیم که به ما امکان می‌دهد کارهای بزرگ را بهتر انجام دهیم. </p>', '2021-07-28 00:00:00', 4, 236, 'https://images.blinkist.io/images/books/60ffb6176cee070007f2f766/1_1/470.jpg', '/en/books/the-power-of-giving-away-power-en/purchase', 'قدرت-بخشش-قدرت', '2023-01-27 12:50:22.413164', '2023-01-27 12:50:22.413164', NULL, 'The Power of Giving Away Power');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1692, 'یک تیم از رهبران', 'توانمندسازی هر عضو برای تصاحب مالکیت، نشان دادن ابتکار عمل و ارائه نتایج', 'توانمندسازی هر عضو برای تصاحب مالکیت، نشان دادن ابتکار عمل و ارائه نتایج', 10, 5, 'book', 'f', '<p><em>تیم رهبران </em>(2014) راه حلی قدرتمند برای شرکت هایی که با مشکلات داخلی مانند از دست دادن بهره وری، جابجایی بالا و تعهد کم کارکنان مواجه هستند، ارائه می دهد. این چشمک‌ها روش‌ها و ابزارهای عملی، از جمله مدل توسعه تیم پنج مرحله‌ای را نشان می‌دهند تا شما را به سمت یک محیط کاری پرمشغله و با عملکرد بالا راهنمایی کنند.</p>', '2015-04-21 00:00:00', 4, 29, 'https://images.blinkist.io/images/books/5534f88c6638630007420000/1_1/470.jpg', '/en/books/a-team-of-leaders-en/purchase', 'یک-تیم-از-رهبران', '2023-01-27 12:50:46.746326', '2023-01-27 12:50:46.746326', NULL, 'A Team of Leaders');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1693, 'قانون 10X', 'تنها تفاوت بین موفقیت و شکست', 'تنها تفاوت بین موفقیت و شکست', 14, 6, 'book', 't', '<p><em>قانون 10X </em>(2011) نشانه های روشنی برای نحوه بهترین برنامه ریزی برای مسیر موفقیت ارائه می دهد. این پلک ها به شما می آموزند که چرا این استراتژی کمتر شناخته شده کار می کند و چگونه آن را به مرحله اجرا درآورید، در حالی که ابزارهایی را نیز در اختیار شما قرار می دهد که برای موفقیت بیشتر از آنچه فکر می کردید، نیاز دارید.</p>', '2017-05-22 00:00:00', 4, 393, 'https://images.blinkist.io/images/books/5921f5c0b238e100077ef9b5/1_1/470.jpg', '/en/books/the-10x-rule-en/purchase', 'قانون-10X', '2023-01-27 12:51:03.185147', '2023-01-27 12:51:03.185147', NULL, 'The 10X Rule');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1694, 'خرید کلاس به عنوان Soulcraft', 'تحقیق در مورد ارزش کار', 'تحقیق در مورد ارزش کار', 21, 9, 'book', 't', '<p><em>Shop Class as Soulcraft</em> (2009) دیدگاهی است که چگونه کار با دستان شما می تواند زندگی شما را متحول کند. این پلک‌ها نگاهی به ماهیت در حال تغییر کار، ارزش کار یدی و اینکه چگونه انتخاب یک حرفه، در مقابل یک حرفه، ممکن است بلیط شما برای خوشبختی باشد، می‌اندازد.</p>', '2015-11-30 00:00:00', 5, 16, 'https://images.blinkist.io/images/books/565c347d9906750007000012/1_1/470.jpg', '/en/books/shop-class-as-soulcraft-en/purchase', 'خرید-کلاس-به-عنوان-Soulcraft', '2023-01-27 12:51:28.784605', '2023-01-27 12:51:28.784605', NULL, 'Shop Class as Soulcraft ');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1695, 'راه اختراع مجدد', 'چگونه اختلال ایجاد کنیم و تحول را تسریع کنیم', 'چگونه اختلال ایجاد کنیم و تحول را تسریع کنیم', 17, 7, 'book', 't', '<p>در <em>جاده اختراع مجدد، </em>نویسنده جاش لینکنر اهمیت کنجکاوی و تمایل به تغییر را در دنیای کسب و کار پویای امروزی نشان می دهد. شرکت‌هایی که خواهان موفقیت پایدار هستند باید دائماً خود، فرهنگ، محصولات و حتی مشتریان خود را دوباره اختراع کنند.</p>', '2015-03-13 00:00:00', 5, 24, 'https://images.blinkist.io/images/books/54fec3e5626661000af10000/1_1/470.jpg', '/en/books/the-road-to-reinvention-en/purchase', 'راه-اختراع-مجدد', '2023-01-27 12:51:54.483203', '2023-01-27 12:51:54.483203', NULL, 'The Road to Reinvention');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1696, 'ذات گرایی', 'زندگی خود را تنها با تمرکز بر موارد ضروری بهبود بخشید', 'زندگی خود را تنها با تمرکز بر موارد ضروری بهبود بخشید', 20, 10, 'book', 't', '<p><em>Essentialism </em>(2014)<em> </em>به شما می آموزد که چگونه با انجام کارهای کمتر، بهتر عمل کنید. <em>Essentialism</em> با ارائه راه‌حل‌های عملی برای اینکه چگونه اولویت‌هایتان را مشخص کنید، به شما کمک می‌کند تا همه چیزهای ناخواسته‌ای را در برنامه‌تان حذف کنید که باعث می‌شود شما واقعاً سازنده و کامل نباشید.</p>', '2014-09-23 00:00:00', 5, 664, 'https://images.blinkist.io/images/books/542041bb63656400082d0000/1_1/470.jpg', '/en/books/essentialism-en/purchase', 'ذات-گرایی', '2023-01-27 12:52:10.220334', '2023-01-27 12:52:10.220334', NULL, 'Essentialism');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1697, 'جاده دره پنهان', 'درون ذهن یک خانواده آمریکایی', 'درون ذهن یک خانواده آمریکایی', 31, 11, 'book', 't', '<p><em>Hidden Valley Road </em>(2020) داستان قابل توجه خانواده گالوین متشکل از 12 فرزند را روایت می کند که نیمی از آنها مبتلا به اسکیزوفرنی هستند. به طور قابل توجهی، گالوین ها به یکی از بهترین امیدهای ما برای درک ماهیت بیولوژیکی این بیماری روانی که اغلب اشتباه درک می شود تبدیل شدند.</p>', '2020-05-24 00:00:00', 4, 30, 'https://images.blinkist.io/images/books/5ec460806cee070006b2fc8c/1_1/470.jpg', '/en/books/hidden-valley-road-en/purchase', 'جاده-دره-پنهان', '2023-01-27 12:52:35.518953', '2023-01-27 12:52:35.518953', NULL, 'Hidden Valley Road');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1698, 'ساعت کاری', 'کسب و کار خود را طوری طراحی کنید که خودش اداره شود', 'کسب و کار خود را طوری طراحی کنید که خودش اداره شود', 23, 8, 'book', 't', '<p><em>ساعت کاری</em>(2018) توضیح می‌دهد که چگونه کارآفرینان می‌توانند شرکت‌های خود را بدون قربانی کردن عقلشان رشد دهند. این ترفند، پیاده‌سازی سیستم‌های هوشمند و رویه‌های عملیاتی استاندارد است که به کسب‌وکار شما اجازه می‌دهد مانند ساعتی بدون ورودی ثابت شما کار کند، و شما را آزاد می‌کند تا با چالش‌ها مقابله کنید یا فرصت‌هایی را که برایتان پیش می‌آیند در آغوش بگیرید.</p>', '2021-03-01 00:00:00', 5, 93, 'https://images.blinkist.io/images/books/6038ca5c6cee07000751a788/1_1/470.jpg', '/en/books/clockwork-en/purchase', 'ساعت-کاری', '2023-01-27 12:52:53.664713', '2023-01-27 12:52:53.664713', NULL, 'Clockwork');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1699, 'می توانم زمزمه تو را بشنوم', 'سفری صمیمی از طریق علم صدا و زبان', 'سفری صمیمی از طریق علم صدا و زبان', 15, 7, 'book', 't', '<p><em>I Can Hear You Whisper</em> (2014) درباره ارتباطات انسانی و پدیده و فرهنگ ناشنوایی است. شنوایی فرآیند پیچیده ای است که برای همه یکسان عمل نمی کند و افرادی که ناشنوا یا کم شنوا هستند روش های جایگزینی برای ارتباط ایجاد کرده اند که فرهنگ خاصی پیرامون آن رشد کرده است. این پلک‌ها نمای کلی از آن فرهنگ را نشان می‌دهد و نشان می‌دهد که به اندازه هر فرهنگ دیگری غنی است.</p>', '2016-04-29 00:00:00', NULL, 8, 'https://images.blinkist.io/images/books/571fbe0589578600031588ad/1_1/470.jpg', '/en/books/i-can-hear-you-whisper-en/purchase', 'می-توانم-زمزمه-تو-را-بشنوم', '2023-01-27 12:53:19.930693', '2023-01-27 12:53:19.930693', NULL, 'I Can Hear You Whisper');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1700, 'شکاف برند', 'چگونه می توان فاصله بین استراتژی و طراحی کسب و کار را پر کرد', 'چگونه می توان فاصله بین استراتژی و طراحی کسب و کار را پر کرد', 15, 6, 'book', 't', '<p>در <em>شکاف برند، </em>می توانید اطلاعاتی در مورد اینکه چگونه یک نام تجاری قوی می تواند به شرکت شما مزیت رقابتی بدهد، به دست خواهید آورد. وقتی یاد می گیرید که چگونه پنج رشته نام تجاری را که در این کتاب به آنها اشاره شده است اجرا کنید، متوجه می شوید که با از بین بردن شکاف بین استراتژی و خلاقیت، می توانید یک نام تجاری مقاومت ناپذیر بسازید که مشتریان را مورد توجه قرار دهد.</p>', '2014-11-25 00:00:00', 4, 72, 'https://images.blinkist.io/images/books/54733c223635610009200000/1_1/470.jpg', '/en/books/the-brand-gap-en/purchase', 'شکاف-برند', '2023-01-27 12:53:46.908723', '2023-01-27 12:53:46.908723', NULL, 'The Brand Gap');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1701, 'سعادت بیشتر', 'چگونه بدون تلاش واقعی در مدیتیشن موفق شویم', 'چگونه بدون تلاش واقعی در مدیتیشن موفق شویم', 22, 7, 'book', 't', '<p><em>Bliss More </em>(2018) یک رویکرد رادیکال و بی دردسر برای مدیتیشن را ترسیم می کند. چه زمانی که روی بالش نشسته‌اید بی‌قرار شده‌اید یا بیشتر به درد کمرتان فکر کرده‌اید تا یکپارچگی با کیهان، این کتاب مراحل ساده‌ای را بیان می‌کند که به شما کمک می‌کند شیار مراقبه خود را پیدا کنید. </p>', '2021-09-23 00:00:00', 4, 203, 'https://images.blinkist.io/images/books/61446e1c6cee070007c18c9a/1_1/470.jpg', '/en/books/bliss-more-en/purchase', 'سعادت-بیشتر', '2023-01-27 12:54:09.966585', '2023-01-27 12:54:09.966585', NULL, 'Bliss More');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (9, 'نفس دشمن است', 'مبارزه برای تسلط بر بزرگترین حریف ما', 'مبارزه برای تسلط بر بزرگترین حریف ما', 22, 6, 'book', 't', '<p><em>نفس دشمن است </em>(۲۰۱۶) با استفاده از نمونه‌های تاریخی و فرهنگی، خطرات خودپرستی و استراتژی‌هایی را که می‌توانیم برای مهار غرور خود استفاده کنیم، ترسیم می‌کند. از پیدا کردن یک مربی تا یادگیری نحوه واگذاری وظایف، این پلک‌ها به ما نشان می‌دهند که چرا ثابت قدم ماندن می‌تواند موفقیت آینده را تضمین کند.</p>', '2017-01-10 00:00:00', 4, 532, 'https://images.blinkist.io/images/books/587243cc6267350004ccad12/1_1/470.jpg', '/en/books/ego-is-the-enemy-en/purchase', 'نفس-دشمن-است', '2023-01-26 18:47:36', '2023-01-26 18:47:36', NULL, 'Ego is the Enemy');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1702, 'گرفتن هر چیزی که می توانید از همه چیزهایی که دارید', '21 روشی که می‌توانید در رقابت بهتر فکر کنید، عملکرد بهتری داشته باشید و کسب درآمد کنید', '21 روشی که می‌توانید در رقابت بهتر فکر کنید، عملکرد بهتری داشته باشید و کسب درآمد کنید', 12, 5, 'book', 't', '<p><em>به دست آوردن هر چیزی که می توانید از همه چیزهایی که دارید</em> (2000) راهنمایی برای شناسایی فرصت های جدید، تضمین مشتریان جدید و موفقیت است، صرف نظر از اینکه در چه حوزه ای از کسب و کار شما هستید. این پلک‌ها توضیح می‌دهند که چگونه می‌توانید از چیزهایی که در حال حاضر دارید بیشتر استفاده کنید و چگونه می‌توانید از آن به نفع کسب‌وکارتان استفاده کنید.</p>', '2016-11-22 00:00:00', 4, 36, 'https://images.blinkist.io/images/books/582b18354fe8520004998ba5/1_1/470.jpg', '/en/books/getting-everything-you-can-out-of-all-youve-got-en/purchase', 'گرفتن-هر-چیزی-که-می-توانید-از-همه-چیزهایی-که-دارید', '2023-01-27 12:54:30.431935', '2023-01-27 12:54:30.431935', NULL, 'Getting Everything You Can Out of All You’ve Got');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1703, 'کلمات در حال حرکت', 'چرا انگلیسی نمی‌خواهد – و نمی‌تواند – بی‌حرکت بنشیند (مثل، به معنای واقعی کلمه)', 'چرا انگلیسی نمی‌خواهد – و نمی‌تواند – بی‌حرکت بنشیند (مثل، به معنای واقعی کلمه)', 21, 8, 'book', 't', '<p><em>Words on the Move</em> (2016) یک تور بی‌سابقه در طول تاریخ زبان انگلیسی، از ریشه‌های آنگلوساکسون تا زبان جهانی است. مملو از بینش‌های روشن‌کننده در مورد تکامل کلمات و معنا، نگاه سرگرم‌کننده جان مک‌ورتر به زبان، بسیاری از اسطوره‌ها را در این مسیر از بین می‌برد. او استدلال می‌کند که شکلک‌ها و استفاده جدید از "مانند" تهدیدی برای زبان ما نیستند، بلکه کاملاً برعکس - آنها آخرین فصل‌های داستانی از تکامل بی‌پایان هستند.</p>', '2018-07-27 00:00:00', 5, 27, 'https://images.blinkist.io/images/books/5b588d66b238e10007a4bb55/1_1/470.jpg', '/en/books/words-on-the-move-en/purchase', 'کلمات-در-حال-حرکت', '2023-01-27 12:54:54.288034', '2023-01-27 12:54:54.288034', NULL, 'Words on the Move');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (1, 'مختل شده', 'ماجراجویی من در حباب استارت‌آپ', 'ماجراجویی من در حباب استارت‌آپ', 20, 9, 'book', 't', '<p><em>Disrupted</em> (2016) با نگاهی آشکار و پشت صحنه به شرکت نرم‌افزار HubSpot بوستون، فرهنگ و شیوه‌های استارت‌آپ‌های فناوری را ابهام می‌کند. پس از 25 سال به عنوان روزنامه نگار فناوری، دن لیون از <em>Newsweek</em> اخراج شد و شغل جدیدی در یک استارت آپ پذیرفت. این پلک ها به دنبال سفر پر دست انداز و طنز لیون است که او سعی می کند در دنیای عجیب و غریب جدید پر از دیوارهای آب نبات و دیگر نمونه های عجیب و غریب HubSpottiness حرکت کند.</p>', '2016-10-07 00:00:00', 4, 26, 'https://images.blinkist.io/images/books/57f2911b90bf6100031a3f9c/1_1/470.jpg', '/en/books/disrupted-en/purchase', 'مختل-شده-است', '2023-01-26 18:46:15', '2023-01-26 18:46:15', NULL, 'Disrupted');
INSERT INTO "public"."books" ("id", "title", "tagline", "tagline_html", "read_time", "ideas", "type", "has_audio", "description", "published_at", "rating", "total_rating", "cover_image", "purchase_url", "slug", "created_at", "updated_at", "deleted_at", "original_title") VALUES (42, 'شدن', 'خاطرات صمیمی، قدرتمند و الهام بخش بانوی اول سابق ایالات متحده', 'خاطرات صمیمی، قدرتمند و الهام بخش بانوی اول سابق ایالات متحده', 36, 12, 'book', 't', '<p><em>شدن</em> (2018) داستان میشل اوباما، خواهرزاده رابینسون را روایت می کند. او که از پدر و مادری دوست داشتنی در یک محله طبقه کارگر شیکاگو متولد شد، به زنی قوی و مستقل تبدیل شد که به طور اتفاقی مردی به نام باراک اوباما را ملاقات کرد و عاشق او شد. این داستان زندگی زنی است که انتظار نداشت اولین بانوی اول آفریقایی-آمریکایی شود، اما راهی برای ادامه دادن صدای منحصر به فرد خود در غیرمعمول ترین و سخت ترین شرایط پیدا کرد.</p>', '2018-11-23 00:00:00', 5, 483, 'https://images.blinkist.io/images/books/5bf79abb6cee070007caaf8b/1_1/470.jpg', '/en/books/becoming-en/purchase', 'شدن', '2023-01-26 18:51:22', '2023-01-26 18:51:22', NULL, 'Becoming');
