INSERT INTO "public"."categories" ("id", "name", "slug", "description", "created_at", "updated_at", "deleted_at", "original_name", "icon", "titles") VALUES (17, 'طبیعت و محیط زیست', 'طبیعت-و-محیط-زیست', 'حیوانات عجیب و غریب، شیفتگی ما به طبیعت و اهمیت محیط زیست.', '2023-01-26 18:57:06.615374', '2023-01-26 18:57:06.615374', NULL, 'Nature & the Environment', '<path d="M23.04 1.67V.96h-.672C21.84.96 10.262.672 5.251 5.683c-4.57 4.57-3.12 12.864-2.717 14.765L0 22.983 1.018 24l2.534-2.534c1.7.352 3.43.533 5.165.537 3.168 0 6.998-.652 9.6-3.254C23.328 13.738 23.04 2.16 23.04 1.67zm-5.76 16.061c-3.456 3.485-9.773 2.928-12.48 2.496l4.08-4.08h5.76v-1.44h-4.33l3.581-3.58h4.685v-1.44H15.36l2.746-2.746-1.047-1.018-2.745 2.717V5.424h-1.44v4.685l-3.581 3.58V9.323h-1.44v5.76L3.773 19.2c-.432-2.707-.96-9.024 2.505-12.48 3.908-3.907 12.768-4.272 15.36-4.3-.067 2.534-.432 11.404-4.358 15.311z" fill="currentColor"></path>', 31);
INSERT INTO "public"."categories" ("id", "name", "slug", "description", "created_at", "updated_at", "deleted_at", "original_name", "icon", "titles") VALUES (21, 'خلاقیت', 'خلاقیت', 'آیا می خواهید انرژی خلاق خود را تقویت کنید؟ برای تفکر خارج از چارچوب الهام بگیرید.', '2023-01-26 19:19:26.082637', '2023-01-26 19:19:26.082637', NULL, 'Creativity', '<clipPath id="a">
INSERT INTO "public"."categories" ("id", "name", "slug", "description", "created_at", "updated_at", "deleted_at", "original_name", "icon", "titles") VALUES (7, 'مدیریت و رهبری', 'مدیریت-و-رهبری', 'هر رهبر بزرگی رازهای منحصر به فردی برای موفقیت دارد، اما رازهایی که همه آنها بر سر آن توافق دارند چیست؟ کتاب ها! بخوانید، قدم بردارید و بدرخشید.', '2023-01-26 18:47:31.860848', '2023-01-26 18:47:31.860848', NULL, 'Management & Leadership', '<clipPath id="a">
INSERT INTO "public"."categories" ("id", "name", "slug", "description", "created_at", "updated_at", "deleted_at", "original_name", "icon", "titles") VALUES (3, 'بازاریابی و فروش', 'بازاریابی-و-فروش', 'این همه پیام های سابلیمینال و روغن مار نیست. در اینجا کارشناسان در مورد استراتژی های بازاریابی محتوا و فروش برای قرن بیست و یکم صحبت می کنند.', '2023-01-26 18:46:32.798204', '2023-01-26 18:46:32.798204', NULL, 'Marketing & Sales', '<g fill="currentColor">
INSERT INTO "public"."categories" ("id", "name", "slug", "description", "created_at", "updated_at", "deleted_at", "original_name", "icon", "titles") VALUES (8, 'بهره‌وری', 'بهره-وری-و-مدیریت-زمان', 'آماده اید که از هر دقیقه بیشتر بسازید؟ استراتژی خود را اینجا پیدا کنید و شروع کنید.', '2023-01-26 18:47:49.984581', '2023-01-26 18:47:49.984581', NULL, 'Productivity', '<clipPath id="a">
INSERT INTO "public"."categories" ("id", "name", "slug", "description", "created_at", "updated_at", "deleted_at", "original_name", "icon", "titles") VALUES (15, 'انگیزه و الهام', 'انگیزه-و-الهام', 'یک کتاب بنویسید، یک فروشگاه راه اندازی کنید یا بالاخره آن استارت آپ را پیدا کردید. این خواندن ها شما را به رویاهای بزرگ می اندازد.', '2023-01-26 18:52:24.939801', '2023-01-26 18:52:24.939801', NULL, 'Motivation & Inspiration', '<clipPath id="a">
INSERT INTO "public"."categories" ("id", "name", "slug", "description", "created_at", "updated_at", "deleted_at", "original_name", "icon", "titles") VALUES (9, 'توسعه فردی', 'رشد-فردی-و-بهبود-خود', 'آیا می خواهید عادت های بد خود را برای همیشه کنار بگذارید و در بازی زندگی برنده شوید؟ شما در جای مناسب هستید', '2023-01-26 18:48:25.340945', '2023-01-26 18:48:25.340945', NULL, 'Personal Development', '<path d="M24 24H0v-7.3h5.72l-.1-5.57h5.64V5.57h5.62V0H24zM1.5 22.51h21V1.5h-4.12v5.57h-5.62v5.57H7.15l.09 5.57H1.5z" fill="currentColor"></path>', 68);
INSERT INTO "public"."categories" ("id", "name", "slug", "description", "created_at", "updated_at", "deleted_at", "original_name", "icon", "titles") VALUES (10, 'بیوگرافی و خاطرات', 'بیوگرافی-و-خاطرات', 'ماندلا به ماری کوری، استیو جابز به توسن لوورتور - درس های زندگی غول ها را بیاموزید.', '2023-01-26 18:48:37.951349', '2023-01-26 18:48:37.951349', NULL, 'Biography & Memoir', '<clipPath id="a">
INSERT INTO "public"."categories" ("id", "name", "slug", "description", "created_at", "updated_at", "deleted_at", "original_name", "icon", "titles") VALUES (18, 'سکس و روابط', 'روابط-و-فرزندپروری', 'بیاموزید که چگونه کسانی را که دوست دارید بهتر دوست داشته باشید - در روابط خود و در رختخواب.', '2023-01-26 19:02:58.807826', '2023-01-26 19:02:58.807826', NULL, 'Sex & Relationships', '<g fill="currentColor" fill-rule="evenodd">
INSERT INTO "public"."categories" ("id", "name", "slug", "description", "created_at", "updated_at", "deleted_at", "original_name", "icon", "titles") VALUES (19, 'فرهنگ شرکتی', 'فرهنگ-شرکتی', 'از شروع کار با هولاکراسی گرفته تا مدیریت تغییر مانند یک قهرمان، یاد بگیرید که چگونه با حیوان سازمان پیچیده مبارزه کنید.', '2023-01-26 19:04:44.459679', '2023-01-26 19:04:44.459679', NULL, 'Corporate Culture', '<clipPath id="a">
