INSERT INTO "public"."categories" ("id", "name", "slug", "description", "created_at", "updated_at", "deleted_at", "original_name", "icon", "titles") VALUES (14, 'سلامت و تغذیه', 'سلامتی-و-تندرستی', 'کره در قهوه، فضیلت های گیاهخواری، و هوشمندانه دویدن: این عناوین مراقبت از بدن و ذهن شما را ساده تر از همیشه می کنند.', '2023-01-26 18:49:48.705716', '2023-01-26 18:49:48.705716', NULL, 'Health & Nutrition', '<path d="M23.66 9.26a6.56 6.56 0 00-3.48-3.73 5.521 5.521 0 00-.83-.33 11.91 11.91 0 00.08-4.55L19.3 0l-.66.05c-.18 0-4.27.35-6.34 3.05-.215.28-.4.581-.55.9a6.34 6.34 0 00-2.3-2.21L8.72 3.1a4.85 4.85 0 012.2 2.61 8.08 8.08 0 00-7.1-.18A6.56 6.56 0 00.34 9.26a8.68 8.68 0 00.83 6.61l.22.44.008.015C3.494 20.608 5.154 24 8.8 24a7.32 7.32 0 003.2-.94 7.32 7.32 0 003.2.94c3.643 0 5.303-3.376 7.407-7.654l.013-.026.21-.44a8.679 8.679 0 00.83-6.62zm-5.61-7.61a9.77 9.77 0 01-.17 3.23 7.6 7.6 0 00-5.16 1A3.81 3.81 0 0113.49 4a7.6 7.6 0 014.56-2.35zm-15.32 14l-.21-.44a7.2 7.2 0 01-.76-5.46 5 5 0 012.72-2.88C6.3 6 9.79 5.9 11.37 8.06v13.62a5.89 5.89 0 01-2.57.81c-2.71 0-4.05-2.72-6.07-6.84zm18.76-.44l-.22.44c-2 4.12-3.36 6.84-6.07 6.84a6 6 0 01-2.58-.81V8.06C14.21 5.9 17.7 6 19.52 6.87a5 5 0 012.73 2.88 7.29 7.29 0 01-.76 5.46zM8.2 16.43c1.8.87 1.8-4.27 1.8-4.27s-3.55 3.4-1.8 4.27zm5.68-4.27s0 5.14 1.75 4.27-1.75-4.27-1.75-4.27z" fill="currentColor" fill-rule="evenodd"></path>', 108);
INSERT INTO "public"."categories" ("id", "name", "slug", "description", "created_at", "updated_at", "deleted_at", "original_name", "icon", "titles") VALUES (4, 'علوم پایه', 'علوم-پایه', 'موضوع ژن ها، جهان و کامپیوترها - کشف کنید که چه چیزی گذشته را شکل داده و آینده را مشخص خواهد کرد.', '2023-01-26 18:46:43.922823', '2023-01-26 18:46:43.922823', NULL, 'Science', '<clipPath id="a">
