INSERT INTO "public"."categories" ("id", "name", "slug", "description", "created_at", "updated_at", "deleted_at", "original_name", "icon", "titles") VALUES (22, 'دین و معنویت', 'دین-و-معنویت', 'هر آنچه باید در مورد سه دین جهانی توحیدی، بودیسم، معنویت و خیلی چیزهای دیگر بدانید.', '2023-01-26 19:31:33.992521', '2023-01-26 19:31:33.992521', NULL, 'Religion & Spirituality', '<clipPath id="a">
INSERT INTO "public"."categories" ("id", "name", "slug", "description", "created_at", "updated_at", "deleted_at", "original_name", "icon", "titles") VALUES (11, 'مهارت‌های ارتباطی', 'مهارت-های-ارتباطی-و-اجتماعی', 'چیزهایی که هرگز در مورد صحبت کردن در جمع، زبان بدن و IQ اجتماعی نمی دانستید - از اینجا شروع کنید تا بهتر شوید.', '2023-01-26 18:48:49.581874', '2023-01-26 18:48:49.581874', NULL, 'Communication Skills', '<path d="M3.7 7.69C3.7 3.45 8.25 0 13.84 0S24 3.45 24 7.69a6.41 6.41 0 01-1.69 4.19L22 16.32 18.14 15c.088.367.139.743.15 1.12 0 3.87-4.15 7-9.15 7a11.79 11.79 0 01-3.46-.52l-3.94 1.34-.28-4A5.79 5.79 0 010 16.16c0-2.43 1.64-4.63 4.3-5.89a6.06 6.06 0 01-.6-2.58zM5.91 21.1a10.31 10.31 0 003.23.52c4.22 0 7.65-2.45 7.65-5.51a3.931 3.931 0 00-.17-1.08c-.913.201-1.845.302-2.78.3a11 11 0 01-8.76-3.83c-2.21 1-3.58 2.74-3.58 4.61a4.41 4.41 0 001.24 3l.18.19.18 2.6 2.57-.9zm14.98-9.84l.17-.19a5 5 0 001.41-3.38c0-3.41-3.87-6.19-8.63-6.19S5.16 4.32 5.16 7.73s3.88 6.19 8.64 6.19c1.237.007 2.467-.19 3.64-.58l.24-.08 3 1zm-1.48-3.59a1 1 0 11-2 0 1 1 0 012 0zm-5.5 1a1 1 0 100-2 1 1 0 000 2zM8.864 6.839a1 1 0 111.111 1.663 1 1 0 01-1.11-1.663z" fill="currentColor" fill-rule="evenodd"></path>', 117);
INSERT INTO "public"."categories" ("id", "name", "slug", "description", "created_at", "updated_at", "deleted_at", "original_name", "icon", "titles") VALUES (5, 'ذهن-آگاهی و شادی', 'ذهن-آگاهی-و-شادی', 'علم این را ثابت می کند: بهترین راه برای رسیدن به خوشبختی، شناخت خود است. این پلک زدن ها به شما کمک می کند هماهنگ شوید، زمین گیر شوید و اکنون اینجا باشید.', '2023-01-26 18:47:07.902915', '2023-01-26 18:47:07.902915', NULL, 'Mindfulness & Happiness', '<clipPath id="a">
INSERT INTO "public"."categories" ("id", "name", "slug", "description", "created_at", "updated_at", "deleted_at", "original_name", "icon", "titles") VALUES (1, 'کارآفرینی', 'کارآفرینی-و-کسب-و-کار-کوچک', 'همه چیزهایی که باید در مورد رونق گرفتن با بودجه کم، کسب اولین میلیون و استخدام از همان ابتدا بدانید.', '2023-01-26 18:46:09.97953', '2023-01-26 18:46:09.97953', NULL, 'Entrepreneurship', '<clipPath id="a">
INSERT INTO "public"."categories" ("id", "name", "slug", "description", "created_at", "updated_at", "deleted_at", "original_name", "icon", "titles") VALUES (6, 'پول و سرمایه‌گذاری', 'پول-و-سرمایه-گذاری', 'شما برای پول خود سخت کار می کنید، درست است؟ اجازه دهید کارشناسان به شما نشان دهند که چگونه این کار را برای خود سخت کنید.', '2023-01-26 18:47:19.778585', '2023-01-26 18:47:19.778585', NULL, 'Money & Investments', '<clipPath id="a">
INSERT INTO "public"."categories" ("id", "name", "slug", "description", "created_at", "updated_at", "deleted_at", "original_name", "icon", "titles") VALUES (12, 'فرزندپروری', 'فرزندپروری', 'از بارداری تا بزرگ کردن نوجوانان - در اینجا همه چیزهایی است که باید در مورد والدین بدانید.', '2023-01-26 18:49:07.738051', '2023-01-26 18:49:07.738051', NULL, 'Parenting', '<g fill="currentColor" fill-rule="evenodd">
INSERT INTO "public"."categories" ("id", "name", "slug", "description", "created_at", "updated_at", "deleted_at", "original_name", "icon", "titles") VALUES (16, 'فلسفه', 'فلسفه', 'آیا می خواهید در مورد زندگی، مرگ و همه چیز در بین آنها از خردمندترین افرادی که تا کنون زندگی کرده اند یاد بگیرید؟ برای پاسخ به تمام سوالات داغ خود به این فیلسوفان حکیم مراجعه کنید.', '2023-01-26 18:53:44.984743', '2023-01-26 18:53:44.984743', NULL, 'Philosophy', '<path d="M16.65 13.84h-.11c-.406-.12-.82-.21-1.24-.27a4.8 4.8 0 00.87-.93 5.47 5.47 0 003.7-1.46 5.53 5.53 0 001.14-3.84L21 6.63h-.68a5.452 5.452 0 00-.68 0 5.58 5.58 0 00-.46-3.95l-.32-.6-.63.26a6.49 6.49 0 00-1.16.68A5.5 5.5 0 0015.24.41L14.69 0l-.46.5A5.22 5.22 0 0012.91 4c.017.183.05.363.1.54a5.49 5.49 0 00-1-.1 5.56 5.56 0 00-1 .1c.046-.177.076-.358.09-.54A5.22 5.22 0 009.78.5L9.32 0l-.54.41a5.48 5.48 0 00-1.85 2.66 6.23 6.23 0 00-1.15-.68l-.63-.26-.32.6a5.63 5.63 0 00-.46 4 3.9 3.9 0 00-.68 0H3v.58a5.53 5.53 0 001.14 3.84 5.47 5.47 0 003.7 1.46c.258.372.564.708.91 1A8.931 8.931 0 007 14l-.2.07C2.54 15.6 0 19 0 23.25V24h24v-.75c0-4.44-2.74-7.95-7.35-9.41zm2.16-3.71A3.33 3.33 0 0117 11a3.34 3.34 0 01.73-1.93 3.3 3.3 0 011.84-.89 3.35 3.35 0 01-.76 1.95zm-.67-6a3.35 3.35 0 01.07 2.09 3.37 3.37 0 01-1.36 1.57 3.35 3.35 0 01-.07-2.09 3.32 3.32 0 011.36-1.55zm-3.25-2a3 3 0 01.8 1.63 2.73 2.73 0 01-.29 1.37 3 3 0 01-.19.36 3 3 0 01-.8-1.62 3.06 3.06 0 01.48-1.73zm.74 7.49A3.63 3.63 0 1112 6a3.65 3.65 0 013.63 3.63zM9.12 2.14a3.06 3.06 0 01.49 1.76 3 3 0 01-.8 1.62 4.13 4.13 0 01-.2-.37 2.79 2.79 0 01-.29-1.38 3 3 0 01.8-1.63zm-3.25 2a3.32 3.32 0 011.36 1.58 3.5 3.5 0 01-.07 2.09A3.37 3.37 0 015.8 6.24a3.35 3.35 0 01.07-2.09zm-.67 6a3.28 3.28 0 01-.74-1.92 3.25 3.25 0 011.83.89A3.29 3.29 0 017 11a3.33 3.33 0 01-1.8-.87zm2.06 5.33h.12A7.811 7.811 0 0110 15h4c.378.002.755.028 1.13.08-.59 2.15-2.69 6.84-9.95 7.46H1.53c.27-3.28 2.33-5.82 5.73-7.08zm3.53 7a11.42 11.42 0 005.8-7.08c3.5 1.24 5.61 3.77 5.89 7.08z" fill="currentColor"></path