INSERT INTO "public"."collections" ("id", "curator_id", "name", "tagline", "description", "created_at", "updated_at", "deleted_at", "original_name", "cover_image", "slug") VALUES (2, 2, 'عناوین برگزیده ۲۰۲۲', 'در سال ۲۰۲۲ چه عناوینی برگزیده بودند؟', 'همانطور که به تمام آموخته‌های سال ۲۰۲۲ نگاه می‌کنیم، کتابداران ما مجموعه‌ای از عناوین برگزیده‌ی امسال را که ما - و شما - بیشتر دوست داشتیم را با شما به اشتراک می‌گذارند!', '2023-02-03 17:55:58.470161', '2023-02-03 17:55:58.470161', NULL, 'Our Top Picks from 2022', 'https://images.blinkist.io/images/curated_lists/2092/1_1/640.jpg', 'عناوین-برگزیده-۲۰۲۲');
INSERT INTO "public"."collections" ("id", "curator_id", "name", "tagline", "description", "created_at", "updated_at", "deleted_at", "original_name", "cover_image", "slug") VALUES (1, 1, 'گل‌های رنگارنگ', 'این کتب بهترین کتب منتشر شده در دهه‌ی هفتاد خورشیدی هستند', 'کتابداران کتابچ پس از سال‌ها تلاش و با زحمت فراوان خبر مرگ‌شان این کتب را آماده کردند', '2023-02-03 18:33:28.892728', '2023-02-03 18:33:28.892728', NULL, 'Colourful Flowers', 'https://images.blinkist.io/images/curated_lists/1178/1_1/640.jpg', 'گل‌های-رنگارنگ');
